--
-- Name: claim_anonymous_analysis_v2_preflight(uuid, character varying, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.claim_anonymous_analysis_v2_preflight(p_preflight_id uuid, p_claim_token_hash character varying, p_user_id uuid) RETURNS TABLE(claimed boolean, preflight_status text, owner_preflight_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_anonymous public.analysis_preflights%ROWTYPE;
    v_owner public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_claim_token_hash IS NULL
       OR p_claim_token_hash !~ '^[0-9a-f]{64}$'
       OR p_user_id IS NULL
       OR (SELECT auth.uid()) IS DISTINCT FROM p_user_id THEN
        RETURN QUERY SELECT FALSE, 'invalid'::TEXT, NULL::UUID;
        RETURN;
    END IF;

    -- Match the checkout create RPC's lock order: take the owner advisory lock
    -- before the users row lock and any preflight row lock. Claim/create
    -- transactions therefore cannot acquire the users and advisory locks in
    -- opposite orders.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'analysis-anonymous-preflight:' || p_user_id::TEXT,
            0
        )
    );

    PERFORM 1
    FROM public.users AS owner_user
    WHERE owner_user.id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'invalid'::TEXT, NULL::UUID;
        RETURN;
    END IF;

    -- Both advisory and users-row locks may wait behind checkout work. Do not
    -- make an expiry decision using a timestamp sampled before those waits.
    v_now := pg_catalog.clock_timestamp();

    SELECT preflight.* INTO v_anonymous
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id IS NULL
      AND preflight.provider_selector = 'anonymous_apify'
      AND preflight.claim_token_hash = p_claim_token_hash
      AND preflight.claim_expires_at > v_now
      AND preflight.status IN ('ready', 'blocked')
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'rejected'::TEXT, NULL::UUID;
        RETURN;
    END IF;

    -- Lock the current owner row in the same transaction. A stale row must be
    -- terminalized before the anonymous row is attached, otherwise the active
    -- owner uniqueness fence can reject a valid OAuth continuation.
    SELECT preflight.* INTO v_owner
    FROM public.analysis_preflights AS preflight
    WHERE preflight.user_id = p_user_id
      AND preflight.status IN ('pending', 'processing', 'ready')
    ORDER BY preflight.updated_at DESC, preflight.created_at DESC
    LIMIT 1
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF FOUND THEN
        IF v_owner.expires_at <= v_now THEN
            -- Internal bounded disposition: ANONYMOUS_PREFLIGHT_OWNER_STALE.
            UPDATE public.analysis_preflights
            SET status = 'expired',
                claim_token_hash = NULL,
                claim_expires_at = NULL,
                lease_token = NULL,
                lease_expires_at = NULL,
                error_code = NULL,
                blocked_at = NULL,
                updated_at = v_now
            WHERE id = v_owner.id
              AND user_id = p_user_id
              AND status IN ('pending', 'processing', 'ready');
        ELSE
            UPDATE public.analysis_preflights
            SET status = 'expired',
                claim_token_hash = NULL,
                claim_expires_at = NULL,
                lease_token = NULL,
                lease_expires_at = NULL,
                error_code = NULL,
                blocked_at = NULL,
                updated_at = v_now
            WHERE id = v_anonymous.id;

            IF v_owner.target_instagram_id IS NOT DISTINCT FROM v_anonymous.target_instagram_id THEN
                RETURN QUERY SELECT FALSE, 'owner_active'::TEXT, v_owner.id;
            ELSE
                -- Internal bounded disposition: ANONYMOUS_PREFLIGHT_OWNER_TARGET_CONFLICT.
                RETURN QUERY SELECT FALSE, 'owner_active_other_target'::TEXT, NULL::UUID;
            END IF;
            RETURN;
        END IF;
    END IF;

    v_now := pg_catalog.clock_timestamp();
    UPDATE public.analysis_preflights
    SET user_id = p_user_id,
        claim_token_hash = NULL,
        claim_expires_at = NULL,
        claimed_at = COALESCE(claimed_at, v_now),
        updated_at = v_now
    WHERE id = p_preflight_id
      AND user_id IS NULL
      AND claim_token_hash = p_claim_token_hash
      AND claim_expires_at > v_now
      AND status IN ('ready', 'blocked');
    IF FOUND THEN
        RETURN QUERY SELECT TRUE, 'claimed'::TEXT, NULL::UUID;
    ELSE
        RETURN QUERY SELECT FALSE, 'rejected'::TEXT, NULL::UUID;
    END IF;
END;
$_$;


--
-- Name: account_ledger_legacy_e2e_candidate_ids_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_ledger_legacy_e2e_candidate_ids_v1() RETURNS TABLE(account_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
    WITH exact_marker_lineage AS (
        SELECT paid_order.user_id AS account_id,
            paid_order.id AS order_id
        FROM public.earlybird_orders AS paid_order
        JOIN public.earlybird_webhook_events AS webhook_event
          ON webhook_event.order_id = paid_order.id
        WHERE paid_order.payment_id IS NOT NULL
          AND paid_order.payment_id ~ '^e2e-[a-z0-9][a-z0-9_-]{0,63}$'
          AND paid_order.paid_at IS NOT NULL
          AND paid_order.actual_groble_product_id IS NOT NULL
          AND paid_order.actual_amount_krw > 0
          AND webhook_event.event_type = 'payment.completed'
          AND webhook_event.disposition = 'accepted'
          AND webhook_event.payment_id = paid_order.payment_id
          AND webhook_event.product_id = paid_order.actual_groble_product_id
          AND webhook_event.amount_krw = paid_order.actual_amount_krw
          AND webhook_event.event_id ~ '^e2e-[a-z0-9][a-z0-9_-]{0,63}$'
          AND webhook_event.idempotency_key ~ '^e2e-[a-z0-9][a-z0-9_-]{0,63}$'
          AND webhook_event.payment_id ~ '^e2e-[a-z0-9][a-z0-9_-]{0,63}$'
    ),
    accounts_with_invalid_accepted_lineage AS (
        SELECT paid_order.user_id AS account_id,
            paid_order.id AS order_id
        FROM public.earlybird_orders AS paid_order
        JOIN public.earlybird_webhook_events AS webhook_event
          ON webhook_event.order_id = paid_order.id
        WHERE webhook_event.event_type = 'payment.completed'
          AND webhook_event.disposition = 'accepted'
          AND (
                paid_order.payment_id IS NULL
                OR paid_order.payment_id !~ '^e2e-[a-z0-9][a-z0-9_-]{0,63}$'
                OR paid_order.paid_at IS NULL
                OR paid_order.actual_groble_product_id IS NULL
                OR paid_order.actual_amount_krw IS NULL
                OR paid_order.actual_amount_krw <= 0
                OR webhook_event.event_id IS NULL
                OR webhook_event.event_id !~ '^e2e-[a-z0-9][a-z0-9_-]{0,63}$'
                OR webhook_event.idempotency_key IS NULL
                OR webhook_event.idempotency_key
                    !~ '^e2e-[a-z0-9][a-z0-9_-]{0,63}$'
                OR webhook_event.payment_id IS NULL
                OR webhook_event.payment_id
                    !~ '^e2e-[a-z0-9][a-z0-9_-]{0,63}$'
                OR webhook_event.payment_id
                    IS DISTINCT FROM paid_order.payment_id
                OR webhook_event.product_id
                    IS DISTINCT FROM paid_order.actual_groble_product_id
                OR webhook_event.amount_krw
                    IS DISTINCT FROM paid_order.actual_amount_krw
          )
    )
    SELECT account.id
    FROM public.users AS account
    WHERE account.classification_version IS NULL
      AND NOT EXISTS (
          SELECT 1
          FROM auth.users AS auth_user
          WHERE auth_user.id = account.id
      )
      AND EXISTS (
          SELECT 1
          FROM public.analysis_requests AS analysis_request
          WHERE analysis_request.user_id = account.id
      )
      AND EXISTS (
          SELECT 1
          FROM exact_marker_lineage AS marker_lineage
          WHERE marker_lineage.account_id = account.id
      )
      AND NOT EXISTS (
          SELECT 1
          FROM accounts_with_invalid_accepted_lineage AS invalid_lineage
          WHERE invalid_lineage.account_id = account.id
      )
    ORDER BY account.id
$_$;


--
-- Name: account_profile_patch_valid(jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_profile_patch_valid(p_patch jsonb, p_allow_phone boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT p_patch IS NOT NULL
       AND pg_catalog.jsonb_typeof(p_patch) = 'object'
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_each(p_patch) AS patch_item(key, value)
            WHERE patch_item.key NOT IN (
                    'name', 'nickname', 'profile_image', 'gender', 'birthyear'
                )
                AND NOT (
                    p_allow_phone
                    AND patch_item.key IN (
                        'phone_number',
                        'phone_number_normalized',
                        'phone_number_verification_source',
                        'phone_number_verified_at'
                    )
                )
               OR pg_catalog.jsonb_typeof(patch_item.value)
                    NOT IN ('string', 'null')
       )
$$;


--
-- Name: acquire_analysis_provider_admission(text, text, text, text, text, uuid, text, text, uuid, uuid, bigint, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquire_analysis_provider_admission(p_admission_id text, p_workload_role text, p_logical_provider text, p_credential_slot text, p_budget_key text, p_request_id uuid, p_job_key text, p_operation_key text, p_job_claim_token uuid, p_claim_token uuid, p_provider_fence bigint, p_lease_token uuid, p_lease_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_expected_id TEXT;
    v_existing public.analysis_provider_admission_leases%ROWTYPE;
    v_budget public.analysis_provider_admission_budgets%ROWTYPE;
    v_budget_found BOOLEAN := FALSE;
    v_global_key TEXT := p_workload_role || ':' || p_logical_provider || ':global';
    v_slot_key TEXT := p_workload_role || ':' || p_logical_provider || ':' || p_credential_slot;
    v_relationship_key TEXT := p_workload_role || ':' || p_logical_provider || ':' || p_credential_slot || ':relationship';
    v_active_count INTEGER;
    v_max_active INTEGER := 0;
    v_rate_limited BOOLEAN := FALSE;
    v_budget_count INTEGER := 0;
    v_required_budget_count INTEGER := 2;
    v_relationship_operation BOOLEAN := p_operation_key LIKE 'relationship-%';
    v_ledger_state TEXT;
    v_reacquire BOOLEAN := FALSE;
    v_identity_lock_key TEXT := p_workload_role || ':' || p_logical_provider || ':'
        || pg_catalog.lower(p_request_id::TEXT) || ':' || p_job_key || ':' || p_operation_key;
BEGIN
    IF p_admission_id IS NULL
       OR p_admission_id !~ '^[0-9a-f]{64}$'
       OR p_workload_role NOT IN ('preflight', 'paid')
       OR p_logical_provider NOT IN ('apify', 'gemini')
       OR p_credential_slot IS NULL
       OR p_credential_slot !~ '^[a-z][a-z0-9_-]{1,31}$'
       OR p_budget_key IS NULL
       OR p_budget_key !~ '^(preflight|paid):(apify|gemini):[a-z0-9:_-]{1,96}$'
       OR p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_operation_key IS NULL
       OR pg_catalog.char_length(p_operation_key) NOT BETWEEN 1 AND 256
       OR p_operation_key !~ '^[a-z0-9][a-z0-9:._-]{0,255}$'
       OR p_job_claim_token IS NULL
       OR p_claim_token IS NULL
       OR (p_logical_provider = 'gemini' AND (p_provider_fence IS NULL OR p_provider_fence < 1))
       OR (p_logical_provider <> 'gemini' AND p_provider_fence IS NOT NULL)
       OR p_lease_token IS NULL
       OR p_lease_seconds NOT BETWEEN 10 AND 900 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;

    v_expected_id := public.analysis_provider_admission_expected_id(
        p_workload_role, p_logical_provider, p_credential_slot,
        p_request_id, p_job_key, p_operation_key
    );
    IF p_admission_id IS DISTINCT FROM v_expected_id THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF p_workload_role = 'preflight'
       AND (p_logical_provider <> 'apify'
            OR p_credential_slot NOT IN ('primary', 'tertiary', 'quaternary', 'quinary', 'senary', 'septenary', 'octonary', 'nonary', 'tenth')) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CREDENTIAL_FORBIDDEN', ERRCODE = 'P0001';
    END IF;
    IF p_logical_provider = 'gemini'
       AND p_credential_slot !~ '^gemini-[1-8]$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CREDENTIAL_FORBIDDEN', ERRCODE = 'P0001';
    END IF;
    IF p_budget_key NOT IN (v_global_key, v_slot_key, v_relationship_key) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF (v_relationship_operation AND p_budget_key <> v_relationship_key)
       OR (NOT v_relationship_operation AND p_budget_key = v_relationship_key) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_relationship_operation THEN
        v_required_budget_count := 3;
    END IF;

    PERFORM public.assert_analysis_provider_admission_claim(
        p_workload_role,
        p_logical_provider,
        p_credential_slot,
        p_request_id,
        p_job_key,
        p_operation_key,
        p_job_claim_token,
        p_claim_token,
        p_provider_fence,
        v_now
    );

    -- Serialize the durable operation identity before the first existence
    -- check. The admission id deliberately includes credential slot, so a
    -- retry that drifts slot/budget must take the same lock and be classified
    -- before it reaches the alternate-id unique identity constraint.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(v_identity_lock_key, 0)
    );

    SELECT lease.* INTO v_existing
    FROM public.analysis_provider_admission_leases AS lease
    WHERE lease.workload_role = p_workload_role
      AND lease.logical_provider = p_logical_provider
      AND lease.request_id = p_request_id
      AND lease.job_key = p_job_key
      AND lease.operation_key = p_operation_key
      AND lease.admission_id IS DISTINCT FROM p_admission_id
    FOR UPDATE;
    IF FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;

    -- Keep a second id lock for unrelated operation identities that happen to
    -- hash to the same durable-operation lock and for exact-id replay.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_admission_id, 0)
    );

    SELECT lease.* INTO v_existing
    FROM public.analysis_provider_admission_leases AS lease
    WHERE lease.admission_id = p_admission_id
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.workload_role IS DISTINCT FROM p_workload_role
           OR v_existing.logical_provider IS DISTINCT FROM p_logical_provider
           OR v_existing.credential_slot IS DISTINCT FROM p_credential_slot
           OR v_existing.budget_key IS DISTINCT FROM p_budget_key
           OR v_existing.request_id IS DISTINCT FROM p_request_id
           OR v_existing.job_key IS DISTINCT FROM p_job_key
           OR v_existing.operation_key IS DISTINCT FROM p_operation_key THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        IF v_existing.state = 'leased' AND v_existing.expires_at > v_now THEN
            -- A durable operation can keep the same provider fence while the
            -- queue worker claim rotates. Both claims are ownership, so any
            -- change is a takeover and must be backed by an already-running
            -- provider ledger before rotating this admission's secret/fence.
            IF v_existing.claim_token IS DISTINCT FROM p_claim_token
               OR v_existing.job_claim_token IS DISTINCT FROM p_job_claim_token THEN
                -- A takeover may only adopt an already-running provider row. A
                -- fresh/start-ambiguous row remains owned by its original claim.
                v_ledger_state := public.analysis_provider_admission_ledger_state(v_existing);
                IF v_ledger_state <> 'running' THEN
                    RAISE EXCEPTION USING
                        MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
                END IF;
                UPDATE public.analysis_provider_admission_leases AS lease
                SET claim_token = p_claim_token,
                    job_claim_token = p_job_claim_token,
                    provider_fence = p_provider_fence,
                    lease_token = p_lease_token,
                    fence = lease.fence + 1,
                    updated_at = v_now
                WHERE lease.admission_id = p_admission_id
                  AND lease.state = 'leased'
                  AND lease.expires_at > v_now
                RETURNING lease.* INTO v_existing;
                IF NOT FOUND THEN
                    RAISE EXCEPTION USING
                        MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_FENCE_MISMATCH', ERRCODE = 'P0001';
                END IF;
                SELECT pg_catalog.count(*)::INTEGER INTO v_active_count
                FROM public.analysis_provider_admission_leases AS lease
                WHERE lease.state IN ('leased', 'recovery_required')
                  AND lease.workload_role = p_workload_role
                  AND lease.logical_provider = p_logical_provider;
                SELECT budget.max_active INTO v_max_active
                FROM public.analysis_provider_admission_budgets AS budget
                WHERE budget.budget_key = p_budget_key;
                RETURN public.analysis_provider_admission_json(
                    v_existing, 'adopted', v_active_count, COALESCE(v_max_active, 1),
                    p_job_claim_token, p_claim_token
                );
            END IF;
            SELECT pg_catalog.count(*)::INTEGER INTO v_active_count
            FROM public.analysis_provider_admission_leases AS lease
            WHERE lease.state IN ('leased', 'recovery_required')
              AND lease.workload_role = p_workload_role
              AND lease.logical_provider = p_logical_provider;
            SELECT budget.max_active INTO v_max_active
            FROM public.analysis_provider_admission_budgets AS budget
            WHERE budget.budget_key = p_budget_key;
            RETURN public.analysis_provider_admission_json(
                v_existing, 'already_acquired', v_active_count, COALESCE(v_max_active, 1),
                p_job_claim_token, p_claim_token
            );
        END IF;
        IF v_existing.state = 'leased' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CAPACITY_PENDING', ERRCODE = 'P0001';
        END IF;
        IF v_existing.state = 'recovery_required' THEN
            -- Expiry does not prove that the provider stopped. A recovery pass
            -- may hand the same operation to a live durable task only after the
            -- provider ledger proves that the external run is still running.
            v_ledger_state := public.analysis_provider_admission_ledger_state(v_existing);
            IF v_ledger_state = 'running' THEN
                UPDATE public.analysis_provider_admission_leases AS lease
                SET state = 'leased',
                    claim_token = p_claim_token,
                    job_claim_token = p_job_claim_token,
                    provider_fence = p_provider_fence,
                    lease_token = p_lease_token,
                    fence = lease.fence + 1,
                    acquired_at = v_now,
                    expires_at = v_now + (p_lease_seconds || ' seconds')::INTERVAL,
                    recovered_at = NULL,
                    release_reason = NULL,
                    resolution_source = NULL,
                    resolution_token_hash = NULL,
                    updated_at = v_now
                WHERE lease.admission_id = p_admission_id
                  AND lease.state = 'recovery_required'
                RETURNING lease.* INTO v_existing;
                IF NOT FOUND THEN
                    RAISE EXCEPTION USING
                        MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_FENCE_MISMATCH', ERRCODE = 'P0001';
                END IF;
                SELECT pg_catalog.count(*)::INTEGER INTO v_active_count
                FROM public.analysis_provider_admission_leases AS lease
                WHERE lease.state IN ('leased', 'recovery_required')
                  AND lease.workload_role = p_workload_role
                  AND lease.logical_provider = p_logical_provider;
                SELECT budget.max_active INTO v_max_active
                FROM public.analysis_provider_admission_budgets AS budget
                WHERE budget.budget_key = p_budget_key;
                RETURN public.analysis_provider_admission_json(
                    v_existing, 'adopted', v_active_count, COALESCE(v_max_active, 1),
                    p_job_claim_token, p_claim_token
                );
            END IF;
            -- Terminal/available/quarantined states are released by the
            -- resolver, never by an acquire retry. Pending and identity
            -- conflicts retain the row and therefore retain capacity.
            IF v_ledger_state = 'identity_conflict' THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
            END IF;
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CAPACITY_PENDING', ERRCODE = 'P0001';
        END IF;
        IF v_existing.state = 'released' AND v_existing.release_reason = 'prestart_rejected' THEN
            v_ledger_state := public.analysis_provider_admission_ledger_state(v_existing);
            IF v_ledger_state NOT IN ('terminal', 'missing') THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
            END IF;
            v_reacquire := TRUE;
        ELSE
            -- Terminal release rows are intentionally not reusable: their
            -- provider ledger may already contain a charged run.
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
    END IF;

    -- Lock all budgets used by the role/provider in lexical order. Every caller uses
    -- this order, so concurrent slot/global claims cannot deadlock each other.
    FOR v_budget IN
        SELECT budget.*
        FROM public.analysis_provider_admission_budgets AS budget
        WHERE budget.budget_key IN (p_budget_key, v_global_key, v_slot_key)
           OR (v_relationship_operation AND budget.budget_key = v_relationship_key)
        ORDER BY budget.budget_key
        FOR UPDATE
    LOOP
        v_budget_count := v_budget_count + 1;
        IF v_budget.workload_role IS DISTINCT FROM p_workload_role
           OR v_budget.logical_provider IS DISTINCT FROM p_logical_provider
           OR (
               v_budget.budget_key = p_budget_key
               AND v_budget.credential_slot IS DISTINCT FROM
                   CASE WHEN v_budget.budget_key = v_global_key THEN NULL ELSE p_credential_slot END
           ) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        v_budget_found := v_budget_found OR v_budget.budget_key = p_budget_key;
        v_max_active := CASE
            WHEN v_budget.budget_key = p_budget_key THEN v_budget.max_active
            ELSE v_max_active
        END;
        SELECT pg_catalog.count(*)::INTEGER INTO v_active_count
        FROM public.analysis_provider_admission_leases AS lease
        WHERE lease.state IN ('leased', 'recovery_required')
          AND lease.workload_role = v_budget.workload_role
          AND lease.logical_provider = v_budget.logical_provider
          AND (
              v_budget.credential_slot IS NULL
              OR lease.credential_slot = v_budget.credential_slot
          )
          AND (
              v_budget.budget_key NOT LIKE '%:relationship'
              OR lease.operation_key LIKE 'relationship-%'
          );
        IF v_active_count >= v_budget.max_active THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CAPACITY_PENDING', ERRCODE = 'P0001';
        END IF;
        IF v_budget.window_started_at + INTERVAL '1 minute' <= v_now THEN
            UPDATE public.analysis_provider_admission_budgets AS budget
            SET window_started_at = v_now, window_count = 0, updated_at = v_now
            WHERE budget.budget_key = v_budget.budget_key;
            v_budget.window_count := 0;
        END IF;
        IF v_budget.window_count >= v_budget.rate_limit_per_minute THEN
            v_rate_limited := TRUE;
        END IF;
    END LOOP;
    IF v_budget_count < v_required_budget_count OR NOT v_budget_found OR v_rate_limited THEN
        IF v_budget_count < v_required_budget_count OR NOT v_budget_found THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_BUDGET_NOT_FOUND', ERRCODE = 'P0001';
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CAPACITY_PENDING', ERRCODE = 'P0001';
    END IF;

    FOR v_budget IN
        SELECT budget.*
        FROM public.analysis_provider_admission_budgets AS budget
        WHERE budget.budget_key IN (p_budget_key, v_global_key, v_slot_key)
           OR (v_relationship_operation AND budget.budget_key = v_relationship_key)
        ORDER BY budget.budget_key
        FOR UPDATE
    LOOP
        UPDATE public.analysis_provider_admission_budgets AS budget
        SET window_count = budget.window_count + 1, updated_at = v_now
        WHERE budget.budget_key = v_budget.budget_key;
    END LOOP;

    IF v_reacquire THEN
        UPDATE public.analysis_provider_admission_leases AS lease
        SET state = 'leased',
                    claim_token = p_claim_token,
                    job_claim_token = p_job_claim_token,
                    provider_fence = p_provider_fence,
            lease_token = p_lease_token,
            fence = lease.fence + 1,
            acquired_at = v_now,
            expires_at = v_now + (p_lease_seconds || ' seconds')::INTERVAL,
            released_at = NULL,
            recovered_at = NULL,
            release_reason = NULL,
            resolution_source = NULL,
            resolution_token_hash = NULL,
            updated_at = v_now
        WHERE lease.admission_id = p_admission_id
          AND lease.state = 'released'
          AND lease.release_reason = 'prestart_rejected'
        RETURNING lease.* INTO v_existing;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_FENCE_MISMATCH', ERRCODE = 'P0001';
        END IF;
    ELSE
        INSERT INTO public.analysis_provider_admission_leases (
        admission_id, workload_role, logical_provider, credential_slot, budget_key,
            request_id, job_key, operation_key, claim_token, job_claim_token,
            provider_fence,
            lease_token, fence,
        acquired_at, expires_at, created_at, updated_at
        ) VALUES (
        p_admission_id, p_workload_role, p_logical_provider, p_credential_slot, p_budget_key,
        p_request_id, p_job_key, p_operation_key, p_claim_token, p_job_claim_token,
        p_provider_fence,
        p_lease_token, 1,
        v_now, v_now + (p_lease_seconds || ' seconds')::INTERVAL, v_now, v_now
        )
        RETURNING * INTO v_existing;
    END IF;

    SELECT pg_catalog.count(*)::INTEGER INTO v_active_count
    FROM public.analysis_provider_admission_leases AS lease
    WHERE lease.state IN ('leased', 'recovery_required')
      AND lease.workload_role = p_workload_role
      AND lease.logical_provider = p_logical_provider;
    RETURN public.analysis_provider_admission_json(
        v_existing, 'acquired', v_active_count, COALESCE(v_max_active, 1),
        p_job_claim_token, p_claim_token
    );
END;
$_$;


--
-- Name: acquire_analysis_request_lease(uuid, uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquire_analysis_request_lease(p_request_id uuid, p_user_id uuid, p_expected_step text, p_lease_token uuid, p_lease_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    affected_rows INTEGER;
BEGIN
    IF p_lease_seconds < 30 OR p_lease_seconds > 7200 THEN
        RAISE EXCEPTION 'lease duration out of range';
    END IF;

    UPDATE public.analysis_requests AS analysis_request
    SET processing_lease_token = p_lease_token,
        processing_lease_expires_at = pg_catalog.clock_timestamp()
            + pg_catalog.make_interval(secs => p_lease_seconds)
    WHERE analysis_request.id = p_request_id
      AND analysis_request.user_id = p_user_id
      AND analysis_request.pipeline_version IS DISTINCT FROM 'v2'
      AND analysis_request.status IN ('pending', 'processing')
      AND COALESCE(analysis_request.current_step, 'pending') = p_expected_step
      AND (
          analysis_request.processing_lease_token IS NULL
          OR analysis_request.processing_lease_expires_at IS NULL
          OR analysis_request.processing_lease_expires_at <= pg_catalog.clock_timestamp()
      );

    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    RETURN affected_rows = 1;
END;
$$;


--
-- Name: acquire_analysis_v2_apify_secret_ref_prune_fence(text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquire_analysis_v2_apify_secret_ref_prune_fence(p_drop_slots text[], p_owner_source_commit_sha text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_drop_slots TEXT[];
    v_guard public.analysis_v2_apify_secret_ref_prune_guard%ROWTYPE;
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    IF NOT public.analysis_v2_valid_apify_secret_ref_prune_slots(p_drop_slots)
       OR p_owner_source_commit_sha IS NULL
       OR p_owner_source_commit_sha !~ '^[0-9a-f]{40}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_FENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    v_drop_slots :=
        public.analysis_v2_normalize_apify_secret_ref_prune_slots(p_drop_slots);

    SELECT guard.*
    INTO v_guard
    FROM public.analysis_v2_apify_secret_ref_prune_guard AS guard
    WHERE guard.singleton IS TRUE
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_GUARD_CORRUPT',
            ERRCODE = 'P0001';
    END IF;

    IF v_guard.drop_slots IS NOT NULL THEN
        IF v_guard.drop_slots IS DISTINCT FROM v_drop_slots
           OR v_guard.owner_source_commit_sha
                IS DISTINCT FROM p_owner_source_commit_sha THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_FENCE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'active', TRUE,
            'acquired', FALSE,
            'dropSlots', pg_catalog.to_jsonb(v_drop_slots)
        );
    END IF;

    UPDATE public.analysis_v2_apify_secret_ref_prune_guard AS guard
    SET drop_slots = v_drop_slots,
        owner_source_commit_sha = p_owner_source_commit_sha,
        fenced_at = v_now,
        updated_at = v_now
    WHERE guard.singleton IS TRUE;

    RETURN pg_catalog.jsonb_build_object(
        'active', TRUE,
        'acquired', TRUE,
        'dropSlots', pg_catalog.to_jsonb(v_drop_slots)
    );
END;
$_$;


--
-- Name: acquire_analysis_v2_gemini_lease(uuid, text, integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquire_analysis_v2_gemini_lease(p_request_id uuid, p_job_key text, p_attempt integer, p_claim_token uuid, p_lease_seconds integer DEFAULT 240) RETURNS TABLE(outcome text, slot smallint, lease_claim_token uuid, fence bigint, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_lease public.analysis_v2_gemini_leases%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_claim_token IS NULL
       OR p_attempt IS NULL OR p_attempt NOT BETWEEN 1 AND 4
       OR p_lease_seconds IS NULL OR p_lease_seconds NOT BETWEEN 225 AND 300
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GEMINI_LEASE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('analysis-v2-gemini-leases', 0)
    );

    UPDATE public.analysis_v2_gemini_leases AS lease
    SET state = 'quarantined',
        quarantined_at = v_now,
        updated_at = v_now
    WHERE lease.state = 'leased'
      AND lease.expires_at <= v_now;

    SELECT lease.* INTO v_lease
    FROM public.analysis_v2_gemini_leases AS lease
    WHERE lease.request_id = p_request_id
      AND lease.job_key = p_job_key
      AND lease.attempt = p_attempt
    ORDER BY lease.slot
    LIMIT 1
    FOR UPDATE;
    IF FOUND THEN
        IF v_lease.state = 'leased'
           AND v_lease.lease_claim_token = p_claim_token
           AND v_lease.expires_at > v_now THEN
            RETURN QUERY SELECT
                'acquired'::TEXT,
                v_lease.slot,
                v_lease.lease_claim_token,
                v_lease.fence,
                v_lease.expires_at;
            RETURN;
        END IF;
        IF v_lease.state = 'leased' THEN
            UPDATE public.analysis_v2_gemini_leases AS lease
            SET state = 'quarantined',
                quarantined_at = v_now,
                updated_at = v_now
            WHERE lease.slot = v_lease.slot
            RETURNING lease.* INTO v_lease;
        END IF;
        RETURN QUERY SELECT
            'quarantine_active'::TEXT,
            v_lease.slot,
            NULL::UUID,
            v_lease.fence,
            v_lease.expires_at;
        RETURN;
    END IF;

    SELECT lease.* INTO v_lease
    FROM public.analysis_v2_gemini_leases AS lease
    WHERE lease.state = 'available'
    ORDER BY lease.slot
    LIMIT 1
    FOR UPDATE;
    IF NOT FOUND THEN
        IF EXISTS (
            SELECT 1
            FROM public.analysis_v2_gemini_leases AS lease
            WHERE lease.state = 'quarantined'
        ) THEN
            RETURN QUERY SELECT
                'quarantine_active'::TEXT,
                NULL::SMALLINT,
                NULL::UUID,
                NULL::BIGINT,
                NULL::TIMESTAMP WITH TIME ZONE;
        ELSE
            RETURN QUERY SELECT
                'capacity_pending'::TEXT,
                NULL::SMALLINT,
                NULL::UUID,
                NULL::BIGINT,
                NULL::TIMESTAMP WITH TIME ZONE;
        END IF;
        RETURN;
    END IF;

    UPDATE public.analysis_v2_gemini_leases AS lease
    SET state = 'leased',
        fence = lease.fence + 1,
        request_id = p_request_id,
        job_key = p_job_key,
        attempt = p_attempt,
        lease_claim_token = p_claim_token,
        acquired_at = v_now,
        expires_at = v_now + p_lease_seconds * INTERVAL '1 second',
        quarantined_at = NULL,
        updated_at = v_now
    WHERE lease.slot = v_lease.slot
      AND lease.state = 'available'
    RETURNING lease.* INTO v_lease;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GEMINI_LEASE_AMBIGUOUS',
            ERRCODE = 'P0001';
    END IF;

    RETURN QUERY SELECT
        'acquired'::TEXT,
        v_lease.slot,
        v_lease.lease_claim_token,
        v_lease.fence,
        v_lease.expires_at;
END;
$_$;


--
-- Name: acquire_analysis_v2_gemini_lease_v2(uuid, text, text, text, integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquire_analysis_v2_gemini_lease_v2(p_request_id uuid, p_job_key text, p_operation_key text, p_stage text, p_attempt integer, p_claim_token uuid, p_lease_seconds integer DEFAULT 240) RETURNS TABLE(outcome text, slot smallint, lease_claim_token uuid, fence bigint, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_lease public.analysis_v2_gemini_leases%ROWTYPE;
    v_resolver_count INTEGER;
BEGIN
    IF p_request_id IS NULL
       OR p_claim_token IS NULL
       OR p_attempt IS NULL OR p_attempt NOT BETWEEN 1 AND 4
       OR p_lease_seconds IS NULL OR p_lease_seconds NOT BETWEEN 225 AND 300
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_operation_key IS NULL
       OR NOT public.analysis_v2_valid_ai_operation_key(p_operation_key)
       OR p_stage NOT IN (
            'genderTriage', 'genderResolution', 'featureAnalysis',
            'highRiskNarrative', 'privateAccountName', 'partnerSafety'
       )
       OR NOT public.analysis_v2_ai_operation_matches_stage(p_operation_key, p_stage) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GEMINI_LEASE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('analysis-v2-gemini-leases', 0)
    );

    UPDATE public.analysis_v2_gemini_leases AS lease
    SET state = 'quarantined',
        quarantined_at = v_now,
        updated_at = v_now
    WHERE lease.state = 'leased'
      AND lease.expires_at <= v_now;

    UPDATE public.analysis_v2_gemini_leases AS lease
    SET state = 'available',
        request_id = NULL,
        job_key = NULL,
        operation_key = NULL,
        stage = NULL,
        attempt = NULL,
        lease_claim_token = NULL,
        acquired_at = NULL,
        expires_at = NULL,
        quarantined_at = NULL,
        updated_at = v_now
    WHERE lease.state = 'quarantined'
      AND lease.stage = 'genderResolution'
      AND lease.expires_at <= v_now
      AND NOT EXISTS (
            SELECT 1
            FROM public.analysis_v2_ai_attempts AS ai_attempt
            WHERE ai_attempt.request_id = lease.request_id
              AND ai_attempt.job_key = lease.job_key
              AND ai_attempt.operation_key = lease.operation_key
              AND ai_attempt.attempt = lease.attempt
              AND ai_attempt.stage = 'genderResolution'
              AND ai_attempt.status = 'reserved'
      );

    SELECT lease.* INTO v_lease
    FROM public.analysis_v2_gemini_leases AS lease
    WHERE lease.request_id = p_request_id
      AND lease.job_key = p_job_key
      AND lease.operation_key = p_operation_key
      AND lease.attempt = p_attempt
    ORDER BY lease.slot
    LIMIT 1
    FOR UPDATE;
    IF FOUND THEN
        IF v_lease.state = 'leased'
           AND v_lease.lease_claim_token = p_claim_token
           AND v_lease.expires_at > v_now THEN
            RETURN QUERY SELECT
                'acquired'::TEXT,
                v_lease.slot,
                v_lease.lease_claim_token,
                v_lease.fence,
                v_lease.expires_at;
            RETURN;
        END IF;
        IF v_lease.state = 'leased' THEN
            UPDATE public.analysis_v2_gemini_leases AS lease
            SET state = 'quarantined',
                quarantined_at = v_now,
                updated_at = v_now
            WHERE lease.slot = v_lease.slot
            RETURNING lease.* INTO v_lease;
        END IF;
        RETURN QUERY SELECT
            'quarantine_active'::TEXT,
            v_lease.slot,
            NULL::UUID,
            v_lease.fence,
            v_lease.expires_at;
        RETURN;
    END IF;

    SELECT pg_catalog.count(*)::INTEGER INTO v_resolver_count
    FROM public.analysis_v2_gemini_leases AS lease
    WHERE lease.state IN ('leased', 'quarantined')
      AND lease.stage = 'genderResolution';
    IF p_stage = 'genderResolution' AND v_resolver_count >= 2 THEN
        RETURN QUERY SELECT
            'resolver_capacity_pending'::TEXT,
            NULL::SMALLINT,
            NULL::UUID,
            NULL::BIGINT,
            NULL::TIMESTAMP WITH TIME ZONE;
        RETURN;
    END IF;

    SELECT lease.* INTO v_lease
    FROM public.analysis_v2_gemini_leases AS lease
    WHERE lease.state = 'available'
    ORDER BY lease.slot
    LIMIT 1
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT
            'capacity_pending'::TEXT,
            NULL::SMALLINT,
            NULL::UUID,
            NULL::BIGINT,
            NULL::TIMESTAMP WITH TIME ZONE;
        RETURN;
    END IF;

    UPDATE public.analysis_v2_gemini_leases AS lease
    SET state = 'leased',
        fence = lease.fence + 1,
        request_id = p_request_id,
        job_key = p_job_key,
        operation_key = p_operation_key,
        stage = p_stage,
        attempt = p_attempt,
        lease_claim_token = p_claim_token,
        acquired_at = v_now,
        expires_at = v_now + p_lease_seconds * INTERVAL '1 second',
        quarantined_at = NULL,
        updated_at = v_now
    WHERE lease.slot = v_lease.slot
      AND lease.state = 'available'
    RETURNING lease.* INTO v_lease;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GEMINI_LEASE_AMBIGUOUS',
            ERRCODE = 'P0001';
    END IF;

    RETURN QUERY SELECT
        'acquired'::TEXT,
        v_lease.slot,
        v_lease.lease_claim_token,
        v_lease.fence,
        v_lease.expires_at;
END;
$_$;


--
-- Name: acquire_analysis_v2_scheduler_gemini_lease_v1(uuid, text, text, text, integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquire_analysis_v2_scheduler_gemini_lease_v1(p_request_id uuid, p_job_key text, p_operation_key text, p_stage text, p_attempt integer, p_claim_token uuid, p_lease_seconds integer DEFAULT 240) RETURNS TABLE(outcome text, slot smallint, lease_claim_token uuid, fence bigint, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_existing public.analysis_v2_gemini_leases%ROWTYPE;
    v_stage_count INTEGER;
    v_stage_limit INTEGER;
BEGIN
    IF p_request_id IS NULL
       OR p_claim_token IS NULL
       OR p_attempt IS NULL OR p_attempt NOT BETWEEN 1 AND 4
       OR p_lease_seconds IS NULL OR p_lease_seconds NOT BETWEEN 225 AND 300
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_operation_key IS NULL
       OR NOT public.analysis_v2_valid_ai_operation_key(p_operation_key)
       OR NOT (
            (
                p_stage = 'genderTriage'
                AND p_operation_key ~ '^gender-triage:[0-9a-f]{64}$'
            )
            OR (
                p_stage = 'featureAnalysis'
                AND p_operation_key ~ '^feature-analysis:[0-9a-f]{64}$'
            )
            OR (
                p_stage = 'privateAccountName'
                AND p_operation_key ~ '^private-account-name:[0-9a-f]{64}$'
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SCHEDULER_GEMINI_LEASE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id
      AND request.pipeline_version = 'v2'
    FOR SHARE;
    IF NOT FOUND
       OR v_request.status NOT IN ('pending', 'processing')
       OR NOT (
            v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.4', 'aiStage', 'ai-stage-policy-v2.8', 'scheduler', 'ai-scheduler-v1')
            OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.4', 'aiStage', 'ai-stage-policy-v2.9', 'scheduler', 'ai-scheduler-v1')
            OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.4', 'aiStage', 'ai-stage-policy-v2.10', 'scheduler', 'ai-scheduler-v1')
            OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.5', 'aiStage', 'ai-stage-policy-v2.8', 'scheduler', 'ai-scheduler-v1')
            OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.5', 'aiStage', 'ai-stage-policy-v2.9', 'scheduler', 'ai-scheduler-v1')
            OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.5', 'aiStage', 'ai-stage-policy-v2.10', 'scheduler', 'ai-scheduler-v1')
            OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.4', 'aiStage', 'ai-stage-policy-v2.11', 'scheduler', 'ai-scheduler-v1')
            OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.5', 'aiStage', 'ai-stage-policy-v2.11', 'scheduler', 'ai-scheduler-v1')
            OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.4', 'aiStage', 'ai-stage-policy-v2.12', 'scheduler', 'ai-scheduler-v1')
            OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.5', 'aiStage', 'ai-stage-policy-v2.12', 'scheduler', 'ai-scheduler-v1')
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SCHEDULER_OPERATION_POLICY_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('analysis-v2-gemini-leases', 0)
    );

    UPDATE public.analysis_v2_gemini_leases AS lease
    SET state = 'quarantined',
        quarantined_at = v_now,
        updated_at = v_now
    WHERE lease.state = 'leased'
      AND lease.expires_at <= v_now;

    SELECT lease.* INTO v_existing
    FROM public.analysis_v2_gemini_leases AS lease
    WHERE lease.request_id = p_request_id
      AND lease.job_key = p_job_key
      AND lease.operation_key = p_operation_key
      AND lease.attempt = p_attempt
    ORDER BY lease.slot
    LIMIT 1
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.state = 'leased'
           AND v_existing.lease_claim_token = p_claim_token
           AND v_existing.expires_at > v_now THEN
            RETURN QUERY SELECT
                'acquired'::TEXT,
                v_existing.slot::SMALLINT,
                v_existing.lease_claim_token,
                v_existing.fence,
                v_existing.expires_at;
            RETURN;
        END IF;
        RETURN QUERY
        SELECT *
        FROM public.acquire_analysis_v2_gemini_lease_v2(
            p_request_id,
            p_job_key,
            p_operation_key,
            p_stage,
            p_attempt,
            p_claim_token,
            p_lease_seconds
        );
        RETURN;
    END IF;

    v_stage_limit := CASE p_stage
        WHEN 'genderTriage' THEN 6
        WHEN 'featureAnalysis' THEN 3
        WHEN 'privateAccountName' THEN 2
        ELSE NULL
    END;
    SELECT pg_catalog.count(*)::INTEGER INTO v_stage_count
    FROM public.analysis_v2_gemini_leases AS lease
    WHERE lease.state IN ('leased', 'quarantined')
      AND lease.stage = p_stage;
    IF v_stage_count >= v_stage_limit THEN
        RETURN QUERY SELECT
            'capacity_pending'::TEXT,
            NULL::SMALLINT,
            NULL::UUID,
            NULL::BIGINT,
            NULL::TIMESTAMP WITH TIME ZONE;
        RETURN;
    END IF;

    RETURN QUERY
    SELECT *
    FROM public.acquire_analysis_v2_gemini_lease_v2(
        p_request_id,
        p_job_key,
        p_operation_key,
        p_stage,
        p_attempt,
        p_claim_token,
        p_lease_seconds
    );
END;
$_$;


--
-- Name: activate_analysis_beta_apify_request_credit(uuid, uuid, uuid, text, jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_analysis_beta_apify_request_credit(p_preflight_id uuid, p_request_id uuid, p_user_id uuid, p_selected_plan_id text, p_operation_slot_map jsonb, p_operation_budget_map jsonb, p_max_snapshot_age_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_preflight public.analysis_preflights%ROWTYPE;
DECLARE v_before public.analysis_beta_pool_allocations%ROWTYPE;
DECLARE v_active public.analysis_beta_pool_allocations%ROWTYPE;
DECLARE v_request public.analysis_requests%ROWTYPE;
DECLARE v_existing public.analysis_v2_provider_execution_policies%ROWTYPE;
DECLARE v_policy_hash TEXT; DECLARE v_result JSONB;
BEGIN
    PERFORM users.id FROM public.users AS users WHERE users.id = p_user_id FOR KEY SHARE;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight
      WHERE preflight.id = p_preflight_id FOR UPDATE;
    SELECT allocation.* INTO v_before FROM public.analysis_beta_pool_allocations AS allocation
      WHERE allocation.preflight_id = p_preflight_id FOR UPDATE;
    v_result := public.activate_analysis_beta_apify_request_credit_unbound(
      p_preflight_id,p_request_id,p_user_id,p_selected_plan_id,p_operation_slot_map,p_operation_budget_map,p_max_snapshot_age_seconds);
    SELECT allocation.* INTO v_active FROM public.analysis_beta_pool_allocations AS allocation
      WHERE allocation.preflight_id = p_preflight_id FOR UPDATE;
    SELECT analysis_request.* INTO v_request FROM public.analysis_requests AS analysis_request
      WHERE analysis_request.id = p_request_id FOR UPDATE;
    v_policy_hash := public.analysis_beta_provider_policy_hash(pg_catalog.lower(v_request.target_instagram_id),p_operation_slot_map);
    SELECT policy.* INTO v_existing FROM public.analysis_v2_provider_execution_policies AS policy
      WHERE policy.request_id = p_request_id FOR UPDATE;
    IF v_before.lifecycle_state = 'active' THEN
      IF NOT FOUND OR v_existing.mode IS DISTINCT FROM 'betatest_free_pool'
        OR v_existing.policy_version IS DISTINCT FROM 'betatest-free-pool-v1'
        OR v_existing.entitlement_jti_hash IS NOT NULL
        OR v_existing.target_instagram_id IS DISTINCT FROM pg_catalog.lower(v_request.target_instagram_id)
        OR v_existing.operation_slot_map IS DISTINCT FROM p_operation_slot_map
        OR v_existing.policy_hash IS DISTINCT FROM v_policy_hash THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_PROVIDER_POLICY_CONFLICT', ERRCODE = 'P0001';
      END IF;
      RETURN v_result;
    END IF;
    IF FOUND THEN RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_PROVIDER_POLICY_CONFLICT', ERRCODE = 'P0001'; END IF;
    IF v_active.lifecycle_state IS DISTINCT FROM 'active' OR v_active.request_id IS DISTINCT FROM p_request_id
      OR v_active.operation_slot_map IS DISTINCT FROM p_operation_slot_map
      OR v_request.analysis_entry_channel IS DISTINCT FROM 'betatest' THEN
      RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_PROVIDER_POLICY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    INSERT INTO public.analysis_v2_provider_execution_policies(
      request_id,mode,policy_version,entitlement_jti_hash,target_instagram_id,operation_slot_map,policy_hash
    ) VALUES (p_request_id,'betatest_free_pool','betatest-free-pool-v1',NULL,
      pg_catalog.lower(v_request.target_instagram_id),p_operation_slot_map,v_policy_hash);
    RETURN v_result;
END; $$;


--
-- Name: activate_analysis_beta_apify_request_credit_unbound(uuid, uuid, uuid, text, jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_analysis_beta_apify_request_credit_unbound(p_preflight_id uuid, p_request_id uuid, p_user_id uuid, p_selected_plan_id text, p_operation_slot_map jsonb, p_operation_budget_map jsonb, p_max_snapshot_age_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    -- The delegated implementation locks all exact nine snapshots under the
    -- shared analysis-apify-free-pool advisory lock before validating capacity.
    RETURN public.activate_analysis_beta_apify_request_credit_unbound_pre_capacity_hardening(
        p_preflight_id, p_request_id, p_user_id, p_selected_plan_id,
        p_operation_slot_map, p_operation_budget_map, p_max_snapshot_age_seconds
    );
END;
$$;


--
-- Name: activate_analysis_beta_apify_request_credit_unbound_pre_capacit(uuid, uuid, uuid, text, jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_analysis_beta_apify_request_credit_unbound_pre_capacit(p_preflight_id uuid, p_request_id uuid, p_user_id uuid, p_selected_plan_id text, p_operation_slot_map jsonb, p_operation_budget_map jsonb, p_max_snapshot_age_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_existing public.analysis_beta_pool_allocations%ROWTYPE;
    v_active public.analysis_beta_pool_allocations%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_target_reservation public.analysis_beta_pool_reservations%ROWTYPE;
    v_grant public.analysis_beta_access_grants%ROWTYPE;
    v_locked_snapshot public.analysis_apify_credit_snapshots%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_proposed RECORD;
    v_lock_count INTEGER := 0;
    v_job_count INTEGER := 0;
    v_job_ineligible BOOLEAN := FALSE;
    v_capacity NUMERIC;
BEGIN
    IF p_preflight_id IS NULL
       OR p_request_id IS NULL
       OR p_user_id IS NULL
       OR p_selected_plan_id NOT IN ('basic', 'standard', 'plus')
       OR p_operation_slot_map IS NULL
       OR NOT public.analysis_beta_valid_operation_slot_map(p_operation_slot_map)
       OR p_operation_budget_map IS NULL
       OR NOT public.analysis_beta_valid_operation_budget_map(p_operation_budget_map)
       OR p_max_snapshot_age_seconds IS NULL
       OR p_max_snapshot_age_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ALLOCATION_INVALID', ERRCODE = 'P0001';
    END IF;

    PERFORM users.id FROM public.users AS users WHERE users.id = p_user_id FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;
    SELECT allocation.* INTO v_existing
    FROM public.analysis_beta_pool_allocations AS allocation
    WHERE allocation.preflight_id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    IF v_existing.lifecycle_state = 'active' THEN
        IF v_existing.user_id IS DISTINCT FROM p_user_id
           OR v_existing.request_id IS DISTINCT FROM p_request_id
           OR v_existing.selected_plan_id IS DISTINCT FROM p_selected_plan_id
           OR v_existing.operation_slot_map IS DISTINCT FROM p_operation_slot_map
           OR v_existing.operation_budget_map IS DISTINCT FROM p_operation_budget_map THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_beta_pool_allocation_json(v_existing);
    END IF;

    SELECT reservation.* INTO v_target_reservation
    FROM public.analysis_beta_pool_reservations AS reservation
    WHERE reservation.allocation_id = v_existing.id
      AND reservation.operation_family = 'target-profile'
    FOR UPDATE;
    IF NOT FOUND
       OR v_existing.user_id IS DISTINCT FROM p_user_id
       OR v_existing.lifecycle_state IS DISTINCT FROM 'preflight_held'
       OR v_existing.policy_version IS DISTINCT FROM 'betatest-free-pool-v1'
       OR v_target_reservation.credential_slot IS DISTINCT FROM p_operation_slot_map->>'target-profile'
       OR v_target_reservation.reserved_usd IS DISTINCT FROM (p_operation_budget_map->>'target-profile')::NUMERIC THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
    END IF;

    IF v_preflight.user_id IS DISTINCT FROM p_user_id
       OR v_preflight.access_mode IS DISTINCT FROM 'production'
       OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'betatest'
       OR v_preflight.status IS DISTINCT FROM 'consumed'
       OR v_preflight.consumed_request_id IS DISTINCT FROM p_request_id
       OR v_existing.expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    SELECT grant_row.* INTO v_grant
    FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ACCESS_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_request.user_id IS DISTINCT FROM p_user_id
       OR v_request.preflight_id IS DISTINCT FROM p_preflight_id
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'production'
       OR v_request.test_entitlement_jti_hash IS NOT NULL
       OR v_request.selected_plan_id_snapshot IS DISTINCT FROM p_selected_plan_id
       OR v_request.status IS DISTINCT FROM 'pending'
       OR v_request.background_processing IS DISTINCT FROM FALSE
       OR v_request.analysis_entry_channel IS DISTINCT FROM 'standard' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    FOR v_job IN
        SELECT job.* FROM public.analysis_pipeline_jobs AS job
        WHERE job.request_id = p_request_id
        ORDER BY job.job_key
        FOR UPDATE
    LOOP
        v_job_count := v_job_count + 1;
        IF v_job.status IS DISTINCT FROM 'pending'
           OR v_job.dispatch_state IS DISTINCT FROM 'pending'
           OR v_job.dispatch_generation <> 0
           OR v_job.dispatch_reservation_token IS NOT NULL
           OR v_job.dispatch_reserved_at IS NOT NULL
           OR v_job.dispatched_at IS NOT NULL
           OR v_job.dispatch_task_name IS NOT NULL
           OR v_job.delivered_at IS NOT NULL
           OR v_job.first_started_at IS NOT NULL THEN
            v_job_ineligible := TRUE;
        END IF;
    END LOOP;
    IF v_job_count = 0 OR v_job_ineligible
       OR EXISTS (
            SELECT 1 FROM public.analysis_v2_provider_runs AS provider_run
            WHERE provider_run.request_id = p_request_id
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    PERFORM public.analysis_beta_pool_lock();
    FOR v_locked_snapshot IN
        SELECT snapshot.* FROM public.analysis_apify_credit_snapshots AS snapshot
        WHERE public.analysis_beta_valid_apify_credential_slot(snapshot.credential_slot)
        ORDER BY CASE snapshot.credential_slot
            WHEN 'primary' THEN 1 WHEN 'tertiary' THEN 2
            WHEN 'quaternary' THEN 3 WHEN 'quinary' THEN 4
            WHEN 'senary' THEN 5 WHEN 'septenary' THEN 6
            WHEN 'octonary' THEN 7 WHEN 'nonary' THEN 8 WHEN 'tenth' THEN 9
        END
        FOR UPDATE
    LOOP
        v_lock_count := v_lock_count + 1;
    END LOOP;

    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.expires_at <= v_now OR v_existing.expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;
    IF v_grant.enabled IS DISTINCT FROM TRUE
       OR (v_grant.expires_at IS NOT NULL AND (
            NOT pg_catalog.isfinite(v_grant.expires_at) OR v_grant.expires_at <= v_now
       )) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ACCESS_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;
    IF v_lock_count <> 9 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INCOMPLETE', ERRCODE = 'P0001';
    END IF;

    -- The target reservation is immutable, but its account must still be
    -- healthy and within the current snapshot fence at activation time.
    SELECT capacity.effective_capacity_usd INTO v_capacity
    FROM public.analysis_beta_pool_effective_capacity_snapshot() AS capacity
    JOIN public.analysis_apify_credit_snapshots AS snapshot
      ON snapshot.credential_slot = capacity.credential_slot
    WHERE capacity.credential_slot = v_target_reservation.credential_slot
      AND snapshot.health_state = 'healthy'
      AND snapshot.monthly_limit_usd IS NOT NULL
      AND snapshot.monthly_usage_usd IS NOT NULL
      AND snapshot.observed_at IS NOT NULL
      AND snapshot.billing_cycle_start_at <= v_now
      AND snapshot.billing_cycle_end_at > v_now
      AND snapshot.observed_at >= v_now - pg_catalog.make_interval(secs => p_max_snapshot_age_seconds)
      AND snapshot.observed_at <= v_now + INTERVAL '1 minute'
      AND snapshot.manually_excluded IS NOT TRUE
      AND capacity.effective_capacity_usd >= v_target_reservation.reserved_usd;
    IF v_capacity IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_CAPACITY_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;

    FOR v_proposed IN
        SELECT slot_entry.slot_value AS credential_slot,
               pg_catalog.sum((p_operation_budget_map->>slot_entry.operation_family)::NUMERIC) AS proposed_usd
        FROM pg_catalog.jsonb_each_text(p_operation_slot_map) AS slot_entry(operation_family, slot_value)
        WHERE slot_entry.operation_family <> 'target-profile'
        GROUP BY slot_entry.slot_value
        ORDER BY slot_entry.slot_value
    LOOP
        SELECT capacity.effective_capacity_usd INTO v_capacity
        FROM public.analysis_beta_pool_effective_capacity_snapshot() AS capacity
        JOIN public.analysis_apify_credit_snapshots AS snapshot
          ON snapshot.credential_slot = capacity.credential_slot
        WHERE capacity.credential_slot = v_proposed.credential_slot
          AND snapshot.health_state = 'healthy'
          AND snapshot.monthly_limit_usd IS NOT NULL
          AND snapshot.monthly_usage_usd IS NOT NULL
          AND snapshot.observed_at IS NOT NULL
          AND snapshot.billing_cycle_start_at <= v_now
          AND snapshot.billing_cycle_end_at > v_now
          AND snapshot.observed_at >= v_now - pg_catalog.make_interval(secs => p_max_snapshot_age_seconds)
          AND snapshot.observed_at <= v_now + INTERVAL '1 minute'
          AND snapshot.manually_excluded IS NOT TRUE;
        IF v_capacity IS NULL OR v_capacity < v_proposed.proposed_usd THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_CAPACITY_UNAVAILABLE', ERRCODE = 'P0001';
        END IF;
    END LOOP;

    INSERT INTO public.analysis_beta_pool_reservations(
        allocation_id, operation_family, credential_slot, reserved_usd,
        lifecycle_state, created_at, updated_at
    )
    SELECT v_existing.id, slot_entry.operation_family, slot_entry.slot_value,
           (p_operation_budget_map->>slot_entry.operation_family)::NUMERIC,
           'preflight_held', v_now, v_now
    FROM pg_catalog.jsonb_each_text(p_operation_slot_map) AS slot_entry(operation_family, slot_value)
    WHERE slot_entry.operation_family <> 'target-profile'
    ORDER BY slot_entry.operation_family;

    UPDATE public.analysis_beta_pool_allocations AS allocation
    SET request_id = p_request_id,
        lifecycle_state = 'active',
        selected_plan_id = p_selected_plan_id,
        operation_slot_map = p_operation_slot_map,
        operation_budget_map = p_operation_budget_map,
        expires_at = v_now + INTERVAL '24 hours',
        updated_at = v_now,
        activated_at = v_now
    WHERE allocation.id = v_existing.id
    RETURNING * INTO v_active;
    UPDATE public.analysis_requests AS analysis_request
    SET analysis_entry_channel = 'betatest'
    WHERE analysis_request.id = p_request_id;
    RETURN public.analysis_beta_pool_allocation_json(v_active);
END;
$$;


--
-- Name: activate_analysis_beta_pool_reservations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_analysis_beta_pool_reservations() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_reservation_count INTEGER;
DECLARE v_reservation_drift BOOLEAN;
BEGIN
    IF OLD.lifecycle_state IS DISTINCT FROM 'active'
       AND NEW.lifecycle_state = 'active' THEN
        UPDATE public.analysis_beta_pool_reservations AS reservation
        SET lifecycle_state = 'active',
            updated_at = pg_catalog.clock_timestamp()
        WHERE reservation.allocation_id = NEW.id
          AND reservation.lifecycle_state = 'preflight_held';

        SELECT pg_catalog.count(*)::INTEGER,
               COALESCE(pg_catalog.bool_or(
                   reservation.lifecycle_state IS DISTINCT FROM 'active'
                   OR reservation.credential_slot IS DISTINCT FROM NEW.operation_slot_map->>reservation.operation_family
                   OR reservation.reserved_usd IS DISTINCT FROM (NEW.operation_budget_map->>reservation.operation_family)::NUMERIC
               ), FALSE)
        INTO v_reservation_count, v_reservation_drift
        FROM public.analysis_beta_pool_reservations AS reservation
        WHERE reservation.allocation_id = NEW.id;

        IF v_reservation_count <> 8 OR v_reservation_drift THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: activate_analysis_revenue_dispatch_guard_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_analysis_revenue_dispatch_guard_v1(p_request_id uuid, p_job_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_guard public.analysis_revenue_dispatch_guards%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REVENUE_DISPATCH_FENCE', ERRCODE = 'P0001';
    END IF;

    -- Canonical lock order: preflight → request → job → provider/source policy
    -- → revenue parent → guard.
    SELECT * INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    SELECT * INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    SELECT * INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    SELECT * INTO v_policy
    FROM public.analysis_v2_provider_execution_policies AS policy
    WHERE policy.request_id = p_request_id
    FOR UPDATE;
    SELECT * INTO v_parent
    FROM public.analysis_revenue_run_ledgers AS ledger
    WHERE ledger.request_id = p_request_id
    FOR UPDATE;
    SELECT * INTO v_guard
    FROM public.analysis_revenue_dispatch_guards AS dispatch_guard
    WHERE dispatch_guard.request_id = p_request_id
    FOR UPDATE;

    IF v_preflight.id IS NULL
       OR v_request.id IS NULL
       OR v_job.request_id IS NULL
       OR v_policy.request_id IS NULL
       OR v_parent.request_id IS NULL
       OR v_preflight.status IS DISTINCT FROM 'consumed'
       OR v_preflight.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot NOT IN ('basic', 'standard')
       OR v_policy.mode IS DISTINCT FROM 'test_operation_split'
       OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR v_parent.status IS DISTINCT FROM 'running'
       OR v_parent.preflight_id IS DISTINCT FROM v_request.preflight_id
       OR v_parent.user_id IS DISTINCT FROM v_request.user_id
       OR v_parent.plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_parent.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_parent.target_username_hmac IS DISTINCT FROM v_preflight.target_input_hash
       OR v_parent.preflight_refreshed_at IS DISTINCT FROM v_preflight.admission_refreshed_at
       OR v_parent.request_started_at IS DISTINCT FROM v_request.created_at THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REVENUE_DISPATCH_FENCE', ERRCODE = 'P0001';
    END IF;

    IF v_guard.request_id IS NULL THEN
        INSERT INTO public.analysis_revenue_dispatch_guards (
            request_id, state, reason_code
        ) VALUES (
            p_request_id, 'active', NULL
        );
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'active', 'created', TRUE, 'replayed', FALSE
        );
    END IF;
    IF v_guard.state = 'active' AND v_guard.reason_code IS NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'active', 'created', FALSE, 'replayed', TRUE
        );
    END IF;
    RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REVENUE_DISPATCH_FENCE', ERRCODE = 'P0001';
END;
$_$;


--
-- Name: activate_precheckout_blite_cohort_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_precheckout_blite_cohort_v1(p_preflight_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_deadline_at TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_preflight_id IS NULL OR p_claim_token IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_PREFLIGHT_FENCE_LOST', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.status <> 'processing'
       OR v_preflight.lease_token IS DISTINCT FROM p_claim_token
       OR v_preflight.lease_expires_at IS NULL
       OR v_preflight.lease_expires_at <= v_now
       OR v_preflight.expires_at <= v_now
       OR v_preflight.pii_scrubbed_at IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_PREFLIGHT_FENCE_LOST', ERRCODE = 'P0001';
    END IF;

    v_deadline_at := COALESCE(
        v_preflight.deadline_at,
        v_preflight.created_at + CASE
            WHEN v_preflight.precheckout_blite_deadline_seconds = 90
                THEN INTERVAL '90 seconds'
            ELSE INTERVAL '60 seconds'
        END
    );
    IF v_deadline_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_PREFLIGHT_FENCE_LOST', ERRCODE = 'P0001';
    END IF;

    IF NOT v_preflight.precheckout_blite_cohort THEN
        UPDATE public.analysis_preflights
        SET precheckout_blite_cohort = TRUE,
            updated_at = v_now
        WHERE id = v_preflight.id
        RETURNING * INTO v_preflight;
    END IF;

    IF v_preflight.submitted_at IS NULL
       OR v_preflight.deadline_at IS NULL
       OR v_preflight.deadline_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_PREFLIGHT_FENCE_LOST', ERRCODE = 'P0001';
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'submittedAt', v_preflight.submitted_at,
        'deadlineAt', v_preflight.deadline_at,
        'expiresAt', v_preflight.expires_at
    );
END;
$$;


--
-- Name: admit_analysis_v2_betatest_plan(uuid, uuid, uuid, integer, text, jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admit_analysis_v2_betatest_plan(p_preflight_id uuid, p_user_id uuid, p_admission_token uuid, p_admission_generation integer, p_selected_plan_id text, p_operation_slot_map jsonb, p_operation_budget_map jsonb, p_max_snapshot_age_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE;
    v_status_hint TEXT;
    v_consumed_request_hint UUID;
    v_gate_enabled BOOLEAN;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
    v_target_reservation public.analysis_beta_pool_reservations%ROWTYPE;
    v_grant public.analysis_beta_access_grants%ROWTYPE;
    v_replay JSONB;
    v_result JSONB;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_admission_token IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_selected_plan_id IS NULL
       OR p_selected_plan_id NOT IN ('basic', 'standard', 'plus')
       OR p_max_snapshot_age_seconds IS NULL
       OR p_max_snapshot_age_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION USING
            MESSAGE='ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE='P0001';
    END IF;

    -- Unlocked routing hint only. A consumed candidate is fully revalidated by
    -- the canonical user -> preflight -> allocation -> request/job/policy
    -- replay validator; a fresh candidate takes the gate before any row lock.
    SELECT preflight.status, preflight.consumed_request_id
    INTO v_status_hint, v_consumed_request_hint
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id=p_preflight_id AND preflight.user_id=p_user_id;
    IF FOUND AND (
        v_status_hint='consumed' OR v_consumed_request_hint IS NOT NULL
    ) THEN
        v_replay:=public.analysis_v2_betatest_plan_replay_internal(
            p_preflight_id,p_user_id,p_admission_token,
            p_admission_generation,p_selected_plan_id
        );
        IF v_replay IS NULL THEN
            RAISE EXCEPTION USING
                MESSAGE='ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE='P0001';
        END IF;
        RETURN v_replay;
    END IF;

    SELECT gate_row.enabled INTO v_gate_enabled
    FROM public.analysis_beta_runtime_gate AS gate_row
    WHERE gate_row.singleton=TRUE
    FOR SHARE;
    PERFORM 1 FROM public.users AS owner_user
    WHERE owner_user.id=p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE='ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE='P0001';
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id=p_preflight_id
    FOR UPDATE;
    IF v_preflight.id IS NULL OR v_preflight.user_id IS DISTINCT FROM p_user_id THEN
        RAISE EXCEPTION USING
            MESSAGE='ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE='P0001';
    END IF;

    -- A competing winner may have committed while the unlocked hint was
    -- stale. Re-enter immutable replay without applying current access.
    IF v_preflight.status='consumed'
       OR v_preflight.consumed_request_id IS NOT NULL THEN
        v_replay:=public.analysis_v2_betatest_plan_replay_internal(
            p_preflight_id,p_user_id,p_admission_token,
            p_admission_generation,p_selected_plan_id
        );
        IF v_replay IS NULL THEN
            RAISE EXCEPTION USING
                MESSAGE='ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE='P0001';
        END IF;
        RETURN v_replay;
    END IF;

    SELECT allocation.* INTO v_allocation
    FROM public.analysis_beta_pool_allocations AS allocation
    WHERE allocation.preflight_id=p_preflight_id
    FOR UPDATE;
    SELECT reservation.* INTO v_target_reservation
    FROM public.analysis_beta_pool_reservations AS reservation
    WHERE reservation.allocation_id=v_allocation.id
      AND reservation.operation_family='target-profile'
    FOR UPDATE;
    SELECT grant_row.* INTO v_grant
    FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id=p_user_id
    FOR UPDATE;
    v_now:=pg_catalog.clock_timestamp();

    IF v_gate_enabled IS DISTINCT FROM TRUE
       OR v_grant.user_id IS NULL
       OR v_grant.enabled IS DISTINCT FROM TRUE
       OR (v_grant.expires_at IS NOT NULL AND (
            NOT pg_catalog.isfinite(v_grant.expires_at)
            OR v_grant.expires_at<=v_now
       )) THEN
        RAISE EXCEPTION USING
            MESSAGE='ANALYSIS_BETA_ACCESS_UNAVAILABLE', ERRCODE='P0001';
    END IF;
    IF v_preflight.analysis_entry_channel IS DISTINCT FROM 'betatest'
       OR v_preflight.access_mode IS DISTINCT FROM 'production'
       OR v_preflight.beta_entry_provenance IS NULL
       OR v_preflight.beta_entry_provenance NOT IN (
            'betatest_service_v1','legacy_betatest_v1'
       )
       OR v_preflight.beta_prepare_generation NOT BETWEEN 1 AND 100
       OR v_preflight.beta_prepare_token IS NULL
       OR v_preflight.beta_prepare_state IS DISTINCT FROM 'prepared'
       OR v_preflight.beta_prepare_dispatch_state IS DISTINCT FROM 'completed'
       OR v_preflight.beta_prepare_completed_at IS NULL
       OR v_allocation.id IS NULL
       OR v_allocation.user_id IS DISTINCT FROM p_user_id
       OR v_allocation.lifecycle_state IS DISTINCT FROM 'preflight_held'
       OR v_allocation.policy_version IS DISTINCT FROM 'betatest-free-pool-v1'
       OR v_target_reservation.allocation_id IS NULL
       OR v_target_reservation.lifecycle_state IS DISTINCT FROM 'preflight_held'
       OR v_target_reservation.credential_slot IS DISTINCT FROM
            p_operation_slot_map->>'target-profile' THEN
        RAISE EXCEPTION USING
            MESSAGE='ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE='P0001';
    END IF;

    v_result:=public.analysis_v2_admit_betatest_plan_ungated_20260802(
        p_preflight_id,p_user_id,p_admission_token,p_admission_generation,
        p_selected_plan_id,p_operation_slot_map,p_operation_budget_map,
        p_max_snapshot_age_seconds
    );
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id=p_preflight_id
    FOR UPDATE;
    v_now:=pg_catalog.clock_timestamp();
    IF v_gate_enabled IS DISTINCT FROM TRUE
       OR v_grant.enabled IS DISTINCT FROM TRUE
       OR (v_grant.expires_at IS NOT NULL AND (
            NOT pg_catalog.isfinite(v_grant.expires_at)
            OR v_grant.expires_at<=v_now
       )) THEN
        RAISE EXCEPTION USING
            MESSAGE='ANALYSIS_BETA_ACCESS_UNAVAILABLE', ERRCODE='P0001';
    END IF;
    IF v_result IS NULL
       OR v_preflight.status IS DISTINCT FROM 'consumed'
       OR v_preflight.consumed_request_id IS NULL
       OR v_preflight.expires_at<=v_now
       OR v_preflight.admission_token IS DISTINCT FROM p_admission_token
       OR v_preflight.admission_generation IS DISTINCT FROM p_admission_generation
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM p_selected_plan_id
       OR v_preflight.admission_refreshed_at IS NULL
       OR v_preflight.admission_refreshed_at<v_now-INTERVAL '2 minutes'
       OR v_preflight.admission_refreshed_at>v_now+INTERVAL '30 seconds'
       OR v_preflight.beta_entry_provenance IS NULL
       OR v_preflight.beta_prepare_state IS DISTINCT FROM 'prepared' THEN
        RAISE EXCEPTION USING
            MESSAGE='ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE='P0001';
    END IF;
    RETURN v_result;
END;
$$;


--
-- Name: admit_earlybird_fulfillment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admit_earlybird_fulfillment(p_order_id uuid) RETURNS TABLE(order_id uuid, fulfillment_status text, preflight_id uuid, user_id uuid, plan_id text, request_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    PERFORM public.rebind_expired_paid_earlybird_preflight(p_order_id);
    RETURN QUERY SELECT * FROM public.admit_earlybird_fulfillment_core_20260730140000(p_order_id);
END;
$$;


--
-- Name: admit_earlybird_fulfillment_core_20260730140000(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admit_earlybird_fulfillment_core_20260730140000(p_order_id uuid) RETURNS TABLE(order_id uuid, fulfillment_status text, preflight_id uuid, user_id uuid, plan_id text, request_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_payment_valid BOOLEAN;
    v_capacity_required_plan_id TEXT;
    v_required_plan_id TEXT;
    v_plan_cards_snapshot JSONB;
    v_selected_card JSONB;
    v_capacity_rank INTEGER;
    v_required_rank INTEGER;
    v_selected_rank INTEGER;
    v_card_followers TEXT;
    v_card_following TEXT;
    v_plan_id TEXT;
    v_plan_rank INTEGER;
    v_catalog_plan JSONB;
    v_launch_status TEXT;
    v_selection_state TEXT;
    v_unavailable_reason TEXT;
BEGIN
    IF p_order_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    v_payment_valid := (
            v_order.status = 'paid'
            OR v_order.status IN ('analysis_in_progress', 'completed')
        )
        AND v_order.seller_reference_confirmed_at IS NOT NULL
        AND v_order.payment_id IS NOT NULL
        AND v_order.actual_amount_krw IS NOT NULL
        AND v_order.actual_amount_krw BETWEEN 0 AND v_order.expected_amount_krw
        AND v_order.actual_groble_product_id
            IS NOT DISTINCT FROM v_order.expected_groble_product_id;
    IF NOT v_payment_valid THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_PAYMENT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    IF v_fulfillment.status IN ('analysis_in_progress', 'completed') THEN
        RETURN QUERY SELECT
            v_order.id,
            v_fulfillment.status,
            v_order.preflight_id,
            v_order.user_id,
            v_order.plan_id,
            v_fulfillment.request_id;
        RETURN;
    END IF;
    IF v_fulfillment.status = 'manual_review' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_MANUAL_REVIEW',
            ERRCODE = 'P0001';
    END IF;
    IF v_fulfillment.status = 'awaiting_operator' THEN
        v_fulfillment.operator_admitted_at := v_now;
    END IF;
    IF v_fulfillment.status NOT IN (
        'awaiting_operator',
        'admission_pending',
        'retryable_failure'
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_STATE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.user_id IS DISTINCT FROM v_order.user_id
       OR v_preflight.access_mode <> 'production'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.plan_catalog_snapshot IS NULL
       OR NOT public.analysis_v2_valid_launch_snapshot(
            v_preflight.launch_status_snapshot
       )
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(
            v_preflight.plan_catalog_snapshot
       )
       OR NOT public.analysis_v2_valid_pricing_snapshot(
            v_preflight.pricing_snapshot
       )
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(
            v_preflight.policy_versions_snapshot
       )
       OR v_order.plan_id NOT IN ('basic', 'standard')
       OR v_preflight.plan_catalog_snapshot
            ->v_order.plan_id->>'launchStatus' <> 'production' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    -- The purge path clears the status-payload columns as one set. Never mix
    -- a partial current payload with a later admission payload.
    IF v_preflight.plan_cards_snapshot IS NOT NULL
       AND v_preflight.capacity_required_plan_id IS NOT NULL
       AND v_preflight.required_plan_id IS NOT NULL THEN
        v_capacity_required_plan_id := v_preflight.capacity_required_plan_id;
        v_required_plan_id := v_preflight.required_plan_id;
        v_plan_cards_snapshot := v_preflight.plan_cards_snapshot;
    ELSIF v_preflight.plan_cards_snapshot IS NULL
       AND v_preflight.capacity_required_plan_id IS NULL
       AND v_preflight.required_plan_id IS NULL
       AND v_preflight.admission_plan_cards_snapshot IS NOT NULL
       AND v_preflight.admission_capacity_required_plan_id IS NOT NULL
       AND v_preflight.admission_required_plan_id IS NOT NULL THEN
        v_capacity_required_plan_id :=
            v_preflight.admission_capacity_required_plan_id;
        v_required_plan_id := v_preflight.admission_required_plan_id;
        v_plan_cards_snapshot := v_preflight.admission_plan_cards_snapshot;
    ELSIF v_preflight.plan_cards_snapshot IS NULL
       AND v_preflight.capacity_required_plan_id IS NULL
       AND v_preflight.required_plan_id IS NULL
       AND v_preflight.admission_plan_cards_snapshot IS NULL
       AND v_preflight.admission_capacity_required_plan_id IS NULL
       AND v_preflight.admission_required_plan_id IS NULL THEN
        -- A paid order can outlive a scrubbed preflight before a fresh-admission
        -- attempt is recorded. Its immutable order counts plus pinned catalog
        -- are sufficient to rebuild the same plan-card contract; the normal
        -- fresh-admission worker still rechecks current profile availability.
        v_capacity_rank := NULL;
        v_required_rank := NULL;
        v_plan_cards_snapshot := '{}'::JSONB;
        FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
            v_plan_rank := CASE v_plan_id
                WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
            v_catalog_plan := v_preflight.plan_catalog_snapshot->v_plan_id;
            v_launch_status := v_preflight.launch_status_snapshot->>v_plan_id;
            IF v_catalog_plan->>'launchStatus' IS DISTINCT FROM v_launch_status THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT',
                    ERRCODE = 'P0001';
            END IF;
            IF v_capacity_rank IS NULL
               AND v_order.target_followers_count
                    <= (v_catalog_plan->'relationshipCapacity'->>'followers')::INTEGER
               AND v_order.target_following_count
                    <= (v_catalog_plan->'relationshipCapacity'->>'following')::INTEGER THEN
                v_capacity_rank := v_plan_rank;
                v_capacity_required_plan_id := v_plan_id;
            END IF;
        END LOOP;

        IF v_capacity_rank IS NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT',
                ERRCODE = 'P0001';
        END IF;

        FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
            v_plan_rank := CASE v_plan_id
                WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
            IF v_required_rank IS NULL
               AND v_plan_rank >= v_capacity_rank
               AND v_preflight.launch_status_snapshot->>v_plan_id = 'production' THEN
                v_required_rank := v_plan_rank;
                v_required_plan_id := v_plan_id;
            END IF;
        END LOOP;

        IF v_required_rank IS NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT',
                ERRCODE = 'P0001';
        END IF;

        FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
            v_plan_rank := CASE v_plan_id
                WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
            v_catalog_plan := v_preflight.plan_catalog_snapshot->v_plan_id;
            v_launch_status := v_preflight.launch_status_snapshot->>v_plan_id;
            IF v_plan_rank < v_capacity_rank THEN
                v_selection_state := 'unavailable';
                v_unavailable_reason := 'below_required_plan';
            ELSIF v_launch_status <> 'production' THEN
                v_selection_state := 'unavailable';
                v_unavailable_reason := 'launch_gate';
            ELSIF v_plan_id = v_required_plan_id THEN
                v_selection_state := 'required';
                v_unavailable_reason := NULL;
            ELSE
                v_selection_state := 'available_upgrade';
                v_unavailable_reason := NULL;
            END IF;
            v_plan_cards_snapshot := v_plan_cards_snapshot || pg_catalog.jsonb_build_object(
                v_plan_id,
                pg_catalog.jsonb_build_object(
                    'launchStatus', v_launch_status,
                    'relationshipCapacity', v_catalog_plan->'relationshipCapacity',
                    'detailedMutualLimit', v_catalog_plan->'detailedMutualLimit',
                    'selectionState', v_selection_state,
                    'unavailableReason', v_unavailable_reason
                )
            );
        END LOOP;
    ELSE
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    v_capacity_rank := CASE v_capacity_required_plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 WHEN 'plus' THEN 3
        ELSE NULL
    END;
    v_required_rank := CASE v_required_plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 WHEN 'plus' THEN 3
        ELSE NULL
    END;
    v_selected_rank := CASE v_order.plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE NULL
    END;
    v_selected_card := v_plan_cards_snapshot -> v_order.plan_id;
    v_card_followers := v_selected_card #>> '{relationshipCapacity,followers}';
    v_card_following := v_selected_card #>> '{relationshipCapacity,following}';

    IF v_capacity_rank IS NULL
       OR v_required_rank IS NULL
       OR v_selected_rank IS NULL
       OR v_capacity_rank > v_required_rank
       OR v_selected_rank < v_required_rank
       OR NOT public.analysis_v2_valid_plan_cards_snapshot(
            v_plan_cards_snapshot
       )
       OR v_selected_card IS NULL
       OR v_selected_card->>'launchStatus' <> 'production'
       OR v_selected_card->>'selectionState'
            NOT IN ('required', 'available_upgrade')
       OR v_card_followers IS NULL
       OR v_card_following IS NULL
       OR v_card_followers !~ '^[0-9]+$'
       OR v_card_following !~ '^[0-9]+$'
       OR v_card_followers::BIGINT < v_order.target_followers_count::BIGINT
       OR v_card_following::BIGINT < v_order.target_following_count::BIGINT THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET target_instagram_id = v_order.target_instagram_id,
        target_followers_count = v_order.target_followers_count,
        target_following_count = v_order.target_following_count,
        target_is_private = FALSE,
        exclusion_decision = v_order.exclusion_decision,
        excluded_instagram_id = v_order.excluded_instagram_id,
        capacity_required_plan_id = v_capacity_required_plan_id,
        required_plan_id = v_required_plan_id,
        plan_cards_snapshot = v_plan_cards_snapshot,
        status = 'ready',
        error_code = NULL,
        blocked_at = NULL,
        ready_at = COALESCE(preflight.ready_at, v_now),
        expires_at = v_now + INTERVAL '1 hour',
        pii_scrubbed_at = NULL,
        updated_at = v_now
    WHERE preflight.id = v_preflight.id;

    UPDATE public.earlybird_fulfillments AS fulfillment
    SET status = 'admission_pending',
        operator_admitted_at = COALESCE(
            fulfillment.operator_admitted_at,
            v_now
        ),
        lease_token = NULL,
        lease_expires_at = NULL,
        next_attempt_at = v_now,
        last_error_code = NULL,
        last_error_at = NULL,
        manual_review_at = NULL,
        updated_at = v_now
    WHERE fulfillment.order_id = p_order_id
    RETURNING fulfillment.* INTO v_fulfillment;

    RETURN QUERY SELECT
        v_order.id,
        v_fulfillment.status,
        v_order.preflight_id,
        v_order.user_id,
        v_order.plan_id,
        v_fulfillment.request_id;
END;
$_$;


--
-- Name: adopt_legacy_fresh_admission_provider_run(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.adopt_legacy_fresh_admission_provider_run(p_preflight_id uuid, p_operation_key text, p_admission_requested_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
BEGIN
    IF p_preflight_id IS NULL
       OR p_operation_key !~ '^target-profile-fresh-admission:g([1-9]|[1-9][0-9]|100)$'
       OR p_admission_requested_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- During a migration-first rollout, an older fresh-admission worker can reserve the
    -- legacy operation after this generation was requested. Move only that new row; an
    -- initial-preflight snapshot predates the request and must never be adopted.
    UPDATE public.analysis_preflight_provider_runs AS provider_run
    SET operation_key = p_operation_key,
        updated_at = pg_catalog.clock_timestamp()
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = 'target-profile-fallback'
      AND provider_run.reserved_at >= p_admission_requested_at
      AND NOT EXISTS (
          SELECT 1
          FROM public.analysis_preflight_provider_runs AS current_generation
          WHERE current_generation.preflight_id = p_preflight_id
            AND current_generation.operation_key = p_operation_key
      );
END;
$_$;


--
-- Name: aggregate_analysis_preflight_acquisition_costs(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aggregate_analysis_preflight_acquisition_costs(p_start_date date, p_end_date_exclusive date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_rows JSONB;
    v_unsettled_rows JSONB;
    v_unsettled_count INTEGER;
    v_unsettled_maximum_charge_usd NUMERIC(20, 12);
BEGIN
    IF p_start_date IS NULL
       OR p_end_date_exclusive IS NULL
       OR p_end_date_exclusive <= p_start_date
       OR p_end_date_exclusive > p_start_date + 3660 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_ACQUISITION_COST_PERIOD_INVALID',
            ERRCODE = 'P0001';
    END IF;

    WITH grouped AS (
        SELECT
            event.event_date,
            event.event_kind,
            event.logical_provider,
            event.actor_id,
            event.credential_slot,
            event.terminal_status,
            pg_catalog.count(*)::INTEGER AS event_count,
            pg_catalog.sum(event.max_charge_usd) AS maximum_charge_usd,
            pg_catalog.sum(event.actual_usage_usd) AS actual_usage_usd
        FROM public.analysis_preflight_acquisition_cost_events AS event
        WHERE event.event_date >= p_start_date
          AND event.event_date < p_end_date_exclusive
        GROUP BY
            event.event_date,
            event.event_kind,
            event.logical_provider,
            event.actor_id,
            event.credential_slot,
            event.terminal_status
    )
    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'eventDate', grouped.event_date,
                'eventKind', grouped.event_kind,
                'logicalProvider', grouped.logical_provider,
                'actorId', grouped.actor_id,
                'credentialSlot', grouped.credential_slot,
                'terminalStatus', grouped.terminal_status,
                'eventCount', grouped.event_count,
                'maximumChargeUsd', grouped.maximum_charge_usd,
                'actualUsageUsd', grouped.actual_usage_usd
            ) ORDER BY
                grouped.event_date,
                grouped.event_kind,
                grouped.logical_provider NULLS FIRST,
                grouped.credential_slot NULLS FIRST,
                grouped.terminal_status
        ),
        '[]'::JSONB
    ) INTO v_rows
    FROM grouped;

    WITH unsettled_grouped AS (
        SELECT
            provider_run.logical_provider,
            provider_run.actor_id,
            provider_run.credential_slot,
            provider_run.status,
            pg_catalog.count(*)::INTEGER AS run_count,
            pg_catalog.sum(provider_run.max_charge_usd) AS maximum_charge_usd,
            pg_catalog.min(provider_run.reserved_at) AS earliest_reserved_at,
            pg_catalog.max(provider_run.reserved_at) AS latest_reserved_at
        FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.actual_usage_usd IS NULL
          AND provider_run.status IN (
              'starting', 'running', 'succeeded', 'failed', 'aborted', 'timed_out'
          )
          AND (provider_run.reserved_at AT TIME ZONE 'UTC')::DATE >= p_start_date
          AND (provider_run.reserved_at AT TIME ZONE 'UTC')::DATE < p_end_date_exclusive
        GROUP BY
            provider_run.logical_provider,
            provider_run.actor_id,
            provider_run.credential_slot,
            provider_run.status
        ORDER BY
            provider_run.logical_provider,
            provider_run.credential_slot,
            provider_run.status
        LIMIT 30
    )
    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'logicalProvider', unsettled.logical_provider,
                'actorId', unsettled.actor_id,
                'credentialSlot', unsettled.credential_slot,
                'status', unsettled.status,
                'runCount', unsettled.run_count,
                'maximumChargeUsd', unsettled.maximum_charge_usd,
                'earliestReservedAt', unsettled.earliest_reserved_at,
                'latestReservedAt', unsettled.latest_reserved_at
            ) ORDER BY
                unsettled.logical_provider,
                unsettled.credential_slot,
                unsettled.status
        ),
        '[]'::JSONB
    ) INTO v_unsettled_rows
    FROM unsettled_grouped AS unsettled;

    SELECT
        pg_catalog.count(*)::INTEGER,
        COALESCE(pg_catalog.sum(provider_run.max_charge_usd), 0)
    INTO v_unsettled_count, v_unsettled_maximum_charge_usd
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.actual_usage_usd IS NULL
      AND provider_run.status IN (
          'starting', 'running', 'succeeded', 'failed', 'aborted', 'timed_out'
      )
      AND (provider_run.reserved_at AT TIME ZONE 'UTC')::DATE >= p_start_date
      AND (provider_run.reserved_at AT TIME ZONE 'UTC')::DATE < p_end_date_exclusive;

    RETURN pg_catalog.jsonb_build_object(
        'startDate', p_start_date,
        'endDateExclusive', p_end_date_exclusive,
        'rows', v_rows,
        'unsettledRows', v_unsettled_rows,
        'unsettledCount', v_unsettled_count,
        'unsettledMaximumChargeUsd', v_unsettled_maximum_charge_usd,
        'hasUnsettled', v_unsettled_count > 0,
        'isComplete', v_unsettled_count = 0
    );
END;
$$;


--
-- Name: analysis_apify_account_is_excluded(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_apify_account_is_excluded(p_credential_slot text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT COALESCE((
        SELECT snapshot.manually_excluded
        FROM public.analysis_apify_credit_snapshots AS snapshot
        WHERE snapshot.credential_slot = p_credential_slot
    ), FALSE);
$$;


--
-- Name: analysis_beta_has_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_beta_has_access() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    IF v_user_id IS NULL THEN RETURN FALSE; END IF;
    RETURN EXISTS (
        SELECT 1
        FROM public.analysis_beta_runtime_gate AS gate_row
        JOIN public.analysis_beta_access_grants AS grant_row
          ON grant_row.user_id = v_user_id
        WHERE gate_row.singleton = TRUE
          AND gate_row.enabled = TRUE
          AND grant_row.enabled = TRUE
          AND (grant_row.expires_at IS NULL OR grant_row.expires_at > v_now)
    );
END;
$$;


--
-- Name: analysis_beta_plan_operation_budget_map(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_beta_plan_operation_budget_map(p_plan_id text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT CASE p_plan_id
      WHEN 'basic' THEN '{"target-profile":0.0052,"relationship-followers":0.68,"relationship-following":0.68,"profile-fallback":0.782600000001,"profile-repair":0.81,"target-likers":0.93,"target-comments":0.234,"candidate-likers":1.55}'::JSONB
      WHEN 'standard' THEN '{"target-profile":0.0052,"relationship-followers":1.36,"relationship-following":1.36,"profile-fallback":1.5626,"profile-repair":1.62,"target-likers":0.93,"target-comments":0.234,"candidate-likers":1.55}'::JSONB
      WHEN 'plus' THEN '{"target-profile":0.0052,"relationship-followers":2.04,"relationship-following":2.04,"profile-fallback":2.3426,"profile-repair":2.43,"target-likers":0.93,"target-comments":0.234,"candidate-likers":1.55}'::JSONB
      ELSE NULL::JSONB
    END;
$$;


--
-- Name: analysis_beta_valid_operation_budget_map(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_beta_valid_operation_budget_map(p_map jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    entry RECORD;
    v_budget NUMERIC;
BEGIN
    IF pg_catalog.jsonb_typeof(p_map) IS DISTINCT FROM 'object'
       OR NOT p_map ?& ARRAY[
            'target-profile',
            'relationship-followers',
            'relationship-following',
            'profile-fallback',
            'profile-repair',
            'target-likers',
            'target-comments',
            'candidate-likers'
       ]
       OR p_map - ARRAY[
            'target-profile',
            'relationship-followers',
            'relationship-following',
            'profile-fallback',
            'profile-repair',
            'target-likers',
            'target-comments',
            'candidate-likers'
       ] <> '{}'::JSONB THEN
        RETURN FALSE;
    END IF;

    FOR entry IN
        SELECT operation_key, budget_value
        FROM pg_catalog.jsonb_each(p_map)
            AS budget_entry(operation_key, budget_value)
    LOOP
        IF pg_catalog.jsonb_typeof(entry.budget_value) <> 'number' THEN
            RETURN FALSE;
        END IF;
        BEGIN
            v_budget := (entry.budget_value #>> '{}')::NUMERIC;
        EXCEPTION
            WHEN invalid_text_representation OR numeric_value_out_of_range THEN
                RETURN FALSE;
        END;
        IF v_budget NOT BETWEEN 0.000000000001 AND 1000
           OR v_budget <> pg_catalog.round(v_budget, 12) THEN
            RETURN FALSE;
        END IF;
    END LOOP;
    RETURN TRUE;
END;
$$;


--
-- Name: analysis_beta_valid_operation_slot_map(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_beta_valid_operation_slot_map(p_map jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT COALESCE(
        pg_catalog.jsonb_typeof(p_map) = 'object'
        AND p_map ?& ARRAY[
            'target-profile',
            'relationship-followers',
            'relationship-following',
            'profile-fallback',
            'profile-repair',
            'target-likers',
            'target-comments',
            'candidate-likers'
        ]
        AND p_map - ARRAY[
            'target-profile',
            'relationship-followers',
            'relationship-following',
            'profile-fallback',
            'profile-repair',
            'target-likers',
            'target-comments',
            'candidate-likers'
        ] = '{}'::JSONB
        AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_each(p_map)
                AS entry(operation_key, slot_value)
            WHERE pg_catalog.jsonb_typeof(entry.slot_value) <> 'string'
               OR NOT public.analysis_beta_valid_apify_credential_slot(
                    entry.slot_value #>> '{}'
               )
        ),
        FALSE
    );
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: analysis_beta_pool_allocations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_beta_pool_allocations (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    preflight_id uuid NOT NULL,
    request_id uuid,
    user_id uuid NOT NULL,
    lifecycle_state text DEFAULT 'preflight_held'::text NOT NULL,
    selected_plan_id text,
    policy_version text DEFAULT 'betatest-free-pool-v1'::text NOT NULL,
    operation_slot_map jsonb,
    operation_budget_map jsonb,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    activated_at timestamp with time zone,
    settled_at timestamp with time zone,
    settlement_reason text,
    CONSTRAINT analysis_beta_pool_allocations_lifecycle_check CHECK ((lifecycle_state = ANY (ARRAY['preflight_held'::text, 'active'::text, 'settled'::text]))),
    CONSTRAINT analysis_beta_pool_allocations_policy_check CHECK ((policy_version = 'betatest-free-pool-v1'::text)),
    CONSTRAINT analysis_beta_pool_allocations_state_check CHECK ((((lifecycle_state = 'preflight_held'::text) AND (preflight_id IS NOT NULL) AND (user_id IS NOT NULL) AND (request_id IS NULL) AND (selected_plan_id IS NULL) AND (operation_slot_map IS NULL) AND (operation_budget_map IS NULL) AND (activated_at IS NULL)) OR ((lifecycle_state = 'active'::text) AND (preflight_id IS NOT NULL) AND (request_id IS NOT NULL) AND (user_id IS NOT NULL) AND (selected_plan_id = ANY (ARRAY['basic'::text, 'standard'::text, 'plus'::text])) AND public.analysis_beta_valid_operation_slot_map(operation_slot_map) AND public.analysis_beta_valid_operation_budget_map(operation_budget_map) AND (activated_at IS NOT NULL)) OR ((lifecycle_state = 'settled'::text) AND (settled_at IS NOT NULL) AND (settlement_reason = ANY (ARRAY['request_terminal'::text, 'preflight_expired'::text, 'recovery'::text]))))),
    CONSTRAINT analysis_beta_pool_allocations_time_check CHECK ((isfinite(expires_at) AND (expires_at > created_at) AND (updated_at >= created_at) AND ((activated_at IS NULL) OR (activated_at >= created_at)) AND ((activated_at IS NULL) OR (updated_at >= activated_at))))
);

ALTER TABLE ONLY public.analysis_beta_pool_allocations FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_beta_pool_allocation_json(public.analysis_beta_pool_allocations); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_beta_pool_allocation_json(p_allocation public.analysis_beta_pool_allocations) RETURNS jsonb
    LANGUAGE sql STABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'allocationId', p_allocation.id,
        'preflightId', p_allocation.preflight_id,
        'requestId', p_allocation.request_id,
        'lifecycleState', p_allocation.lifecycle_state,
        'policyVersion', p_allocation.policy_version,
        'selectedPlanId', p_allocation.selected_plan_id,
        'operationSlotMap', p_allocation.operation_slot_map,
        'operationBudgetMap', p_allocation.operation_budget_map,
        'expiresAt', p_allocation.expires_at
    );
$$;


--
-- Name: analysis_beta_pool_effective_capacity_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_beta_pool_effective_capacity_snapshot() RETURNS TABLE(credential_slot text, observed_at timestamp with time zone, effective_capacity_usd numeric)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT snapshot.credential_slot, snapshot.observed_at,
           snapshot.monthly_limit_usd - snapshot.monthly_usage_usd
             - COALESCE(held.usd, 0::NUMERIC)
             - COALESCE(debit.usd, 0::NUMERIC) AS effective_capacity_usd
    FROM public.analysis_apify_credit_snapshots AS snapshot
    LEFT JOIN LATERAL (
        SELECT COALESCE(pg_catalog.sum(reservation.reserved_usd), 0::NUMERIC) AS usd
        FROM public.analysis_beta_pool_reservations AS reservation
        WHERE reservation.credential_slot = snapshot.credential_slot
          AND reservation.lifecycle_state IN ('preflight_held', 'active')
    ) AS held ON TRUE
    LEFT JOIN LATERAL (
        SELECT COALESCE(pg_catalog.sum(item.usd), 0::NUMERIC) AS usd
        FROM (
            SELECT reservation.actual_usd AS usd
            FROM public.analysis_beta_pool_reservations AS reservation
            WHERE reservation.credential_slot = snapshot.credential_slot
              AND reservation.lifecycle_state = 'settled'
              AND reservation.actual_usd > 0
              AND reservation.reconciliation_watermark >= snapshot.observed_at
            UNION ALL
            SELECT local_debit.actual_usd
            FROM public.analysis_beta_pool_local_debits AS local_debit
            WHERE local_debit.credential_slot = snapshot.credential_slot
              AND local_debit.reconciliation_watermark >= snapshot.observed_at
            UNION ALL
            SELECT archive.unabsorbed_debit_usd
            FROM public.analysis_beta_pool_reservation_archive AS archive
            WHERE archive.credential_slot = snapshot.credential_slot
              AND (archive.archive_state = 'ambiguous_held'
                   OR archive.reconciliation_watermark >= snapshot.observed_at)
        ) AS item
    ) AS debit ON TRUE
    WHERE public.analysis_beta_valid_apify_credential_slot(snapshot.credential_slot);
$$;


--
-- Name: analysis_beta_pool_effective_local_debit_usd(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_beta_pool_effective_local_debit_usd(p_credential_slot text, p_observed_at timestamp with time zone) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT COALESCE(pg_catalog.sum(debit.usd), 0::NUMERIC)
    FROM (
      SELECT reservation.credential_slot, reservation.actual_usd AS usd,
             reservation.reconciliation_watermark, 'settled'::TEXT AS state
      FROM public.analysis_beta_pool_reservations AS reservation
      WHERE reservation.lifecycle_state = 'settled' AND reservation.actual_usd > 0
      UNION ALL
      SELECT archive.credential_slot, archive.unabsorbed_debit_usd,
             archive.reconciliation_watermark, archive.archive_state
      FROM public.analysis_beta_pool_reservation_archive AS archive
    ) AS debit
    WHERE debit.credential_slot = p_credential_slot
      -- There is deliberately no synthetic post-retention watermark for an
      -- ambiguous start. A provider snapshot, even a much newer one, cannot
      -- prove the unknown charge was included, so only settled debit has the
      -- strict-newer retirement path.
      AND (debit.state = 'ambiguous_held'
        OR debit.reconciliation_watermark >= p_observed_at);
$$;


--
-- Name: analysis_beta_pool_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_beta_pool_lock() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('analysis-apify-free-pool', 0)
    );
$$;


--
-- Name: analysis_beta_provider_policy_hash(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_beta_provider_policy_hash(p_target_instagram_id text, p_operation_slot_map jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'betatest-free-pool-v1' || E'\n' || p_target_instagram_id
                || E'\n' || p_operation_slot_map::TEXT,
                'UTF8'
            ), 'sha256'
        ), 'hex'
    )
$$;


--
-- Name: analysis_beta_valid_apify_credential_slot(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_beta_valid_apify_credential_slot(p_slot text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT COALESCE(
        p_slot IN (
            'primary', 'tertiary', 'quaternary', 'quinary', 'senary',
            'septenary', 'octonary', 'nonary', 'tenth'
        ),
        FALSE
    );
$$;


--
-- Name: analysis_capacity_activation_readiness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_capacity_activation_readiness() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_legacy_active_provider_runs BIGINT;
    v_legacy_active_preflight_runs BIGINT;
    v_legacy_active_profile_repair_runs BIGINT;
    v_legacy_active_v1_provider_runs BIGINT;
    v_legacy_active_processing_claims BIGINT;
    v_legacy_active_v2_job_claims BIGINT;
    v_legacy_active_profile_provider_canary_runs BIGINT;
    v_legacy_active_old_target_invocations BIGINT;
    v_legacy_active_queued_preflight_tasks BIGINT;
    v_legacy_active_queued_v2_tasks BIGINT;
    v_legacy_active_fresh_admissions BIGINT;
    v_legacy_active_beta_prepare BIGINT;
    v_unreconciled_provider_runs BIGINT;
    v_unreconciled_preflight_runs BIGINT;
    v_unreconciled_profile_repair_runs BIGINT;
    v_unreconciled_v1_provider_runs BIGINT;
    v_unreconciled_profile_provider_canary_runs BIGINT;
BEGIN
    -- A provider ledger is safe only when its exact durable admission is still
    -- active.  Healthy role-aware traffic therefore does not block promotion;
    -- an unadmitted, expired, or identity-drifted run does.
    SELECT pg_catalog.count(*)
    INTO v_legacy_active_provider_runs
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.status IN ('starting', 'running')
      AND NOT EXISTS (
          SELECT 1
          FROM public.analysis_provider_admission_leases AS admission
          WHERE admission.workload_role = 'paid'
            AND admission.logical_provider = provider_run.logical_provider
            AND admission.request_id = provider_run.request_id
            AND admission.job_key = provider_run.job_key
            AND admission.operation_key = provider_run.operation_key
            AND admission.credential_slot = provider_run.credential_slot
            AND admission.job_claim_token = provider_run.job_claim_token
            AND admission.state IN ('leased', 'recovery_required')
            AND admission.expires_at > v_now
      );

    -- Ordinary preflight, the narrowly validated beta paid branch, and fresh
    -- paid admission all use this ledger.  A live row with a matching active
    -- admission is safe; a starting/running row without one is a legacy start.
    SELECT pg_catalog.count(*)
    INTO v_legacy_active_preflight_runs
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.status IN ('starting', 'running')
      AND NOT EXISTS (
          SELECT 1
          FROM public.analysis_provider_admission_leases AS admission
          WHERE admission.logical_provider = 'apify'
            AND admission.request_id = provider_run.preflight_id
            AND admission.credential_slot = provider_run.credential_slot
            AND admission.state IN ('leased', 'recovery_required')
            AND admission.expires_at > v_now
            AND (
                (
                    admission.workload_role = 'preflight'
                    AND admission.job_key = 'preflight:provider'
                    AND admission.operation_key = 'target-profile-fallback'
                    AND provider_run.operation_key = 'target-profile-fallback'
                )
                OR (
                    admission.workload_role = 'paid'
                    AND admission.job_key = 'preflight:provider'
                    AND admission.operation_key = 'target-profile-fallback'
                    AND provider_run.operation_key = 'target-profile-fallback'
                )
                OR (
                    admission.workload_role = 'paid'
                    AND admission.job_key = 'paid:target-profile'
                    AND admission.operation_key ~ '^target-profile-fresh-admission:g([1-9]|[1-9][0-9]|100)$'
                    AND provider_run.operation_key = admission.operation_key
                )
            )
      );

    SELECT pg_catalog.count(*)
    INTO v_legacy_active_profile_repair_runs
    FROM public.analysis_v2_profile_repair_canary_runs AS canary_run
    WHERE canary_run.state IN ('starting', 'running', 'ambiguous');

    SELECT pg_catalog.count(*)
    INTO v_legacy_active_profile_provider_canary_runs
    FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
    WHERE canary_run.state IN ('starting', 'running', 'ambiguous');

    -- The V1 table intentionally has no terminal state; all rows are live
    -- provider intents and must be drained before an active gate-on revision.
    SELECT pg_catalog.count(*)
    INTO v_legacy_active_v1_provider_runs
    FROM public.analysis_provider_runs AS provider_run
    WHERE provider_run.status IN ('starting', 'running');

    -- Live V1 claims and unsafe preflight claims are separate from healthy
    -- role-aware ordinary traffic. Expired claims cannot create a provider and
    -- are left for normal maintenance recovery.
    SELECT pg_catalog.count(*)
    INTO v_legacy_active_processing_claims
    FROM (
        SELECT request.id
        FROM public.analysis_requests AS request
        WHERE request.pipeline_version IS DISTINCT FROM 'v2'
          AND request.status IN ('pending', 'processing')
          AND request.processing_lease_token IS NOT NULL
          AND request.processing_lease_expires_at > v_now
        UNION ALL
        SELECT preflight.id
        FROM public.analysis_preflights AS preflight
        WHERE preflight.status = 'processing'
          AND preflight.lease_token IS NOT NULL
          AND preflight.lease_expires_at > v_now
          AND (
              preflight.claim_workload_role IS NULL
              OR preflight.claim_contract_version IS NULL
              OR preflight.claim_workload_role IS DISTINCT FROM 'preflight'
              OR preflight.claim_contract_version IS DISTINCT FROM 2
              OR preflight.dispatch_workload_role IS NULL
              OR preflight.dispatch_contract_version IS NULL
              OR preflight.dispatch_workload_role IS DISTINCT FROM 'preflight'
              OR preflight.dispatch_contract_version IS DISTINCT FROM 2
          )
    ) AS live_claim;

    -- An exact paid job claim is safe for normal V2 work. Missing, half, or
    -- mismatched claim/dispatch markers are legacy ownership and block.
    SELECT pg_catalog.count(*)
    INTO v_legacy_active_v2_job_claims
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.status = 'processing'
      AND job.lease_token IS NOT NULL
      AND job.lease_expires_at > v_now
      AND (
          job.claim_workload_role IS NULL
          OR job.claim_contract_version IS NULL
          OR job.claim_workload_role IS DISTINCT FROM 'paid'
          OR job.claim_contract_version IS DISTINCT FROM 2
          OR job.dispatch_workload_role IS NULL
          OR job.dispatch_contract_version IS NULL
          OR job.dispatch_workload_role IS DISTINCT FROM 'paid'
          OR job.dispatch_contract_version IS DISTINCT FROM 2
      );

    SELECT pg_catalog.count(*)
    INTO v_legacy_active_old_target_invocations
    FROM public.analysis_requests AS request
    WHERE request.pipeline_version IS DISTINCT FROM 'v2'
      AND request.status IN ('pending', 'processing');

    -- Only unsafe active dispatches block. A completed ready ordinary
    -- preflight is intentionally excluded; exact role-aware pending and
    -- processing rows remain service-owned and recoverable.
    SELECT pg_catalog.count(*)
    INTO v_legacy_active_queued_preflight_tasks
    FROM public.analysis_preflights AS preflight
    WHERE preflight.status IN ('pending', 'processing')
      AND preflight.expires_at > v_now
      AND preflight.dispatch_state IN ('reserved', 'enqueued')
      AND (
          preflight.analysis_entry_channel = 'betatest'
          OR preflight.dispatch_workload_role IS NULL
          OR preflight.dispatch_contract_version IS NULL
          OR preflight.dispatch_workload_role IS DISTINCT FROM 'preflight'
          OR preflight.dispatch_contract_version IS DISTINCT FROM 2
          OR (
              preflight.dispatch_state = 'reserved'
              AND (
                  preflight.dispatch_token IS NULL
                  OR preflight.dispatch_reserved_at IS NULL
              )
          )
          OR (
              preflight.dispatch_state = 'enqueued'
              AND (
                  preflight.last_dispatch_token IS NULL
                  OR preflight.dispatch_reserved_at IS NULL
                  OR preflight.dispatched_at IS NULL
              )
          )
      );

    SELECT pg_catalog.count(*)
    INTO v_legacy_active_queued_v2_tasks
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.status IN ('pending', 'processing')
      AND job.dispatch_state IN ('reserved', 'enqueued', 'delivered')
      AND (
          job.dispatch_workload_role IS NULL
          OR job.dispatch_contract_version IS NULL
          OR job.dispatch_workload_role IS DISTINCT FROM 'paid'
          OR job.dispatch_contract_version IS DISTINCT FROM 2
          OR job.dispatch_reserved_at IS NULL
          OR job.dispatched_at IS NULL
          OR job.dispatch_task_name IS NULL
      );

    -- Fresh admission safety is the inverse of the old broad counter: a live
    -- exact admission is safe, while a live admission claim without its exact
    -- active ledger is unsafe and must block promotion.
    SELECT pg_catalog.count(*)
    INTO v_legacy_active_fresh_admissions
    FROM public.analysis_preflights AS preflight
    WHERE preflight.status IN ('pending', 'processing', 'ready')
      AND preflight.expires_at > v_now
      AND (
          (
              preflight.admission_status = 'processing'
              AND preflight.admission_claim_token IS NOT NULL
              AND preflight.admission_lease_expires_at > v_now
              AND NOT (
                  -- A trusted paid claim is sufficient for a fresh worker to
                  -- perform its admission transition. Otherwise an exact,
                  -- still-active admission lease is the durable proof. A live
                  -- claim with neither proof is the unsafe case.
                  (
                      preflight.admission_claim_workload_role IS NOT NULL
                      AND preflight.admission_claim_contract_version IS NOT NULL
                      AND preflight.admission_claim_workload_role IS NOT DISTINCT FROM 'paid'
                      AND preflight.admission_claim_contract_version IS NOT DISTINCT FROM 2
                  )
                  OR EXISTS (
                      SELECT 1
                      FROM public.analysis_provider_admission_leases AS admission
                      WHERE admission.workload_role = 'paid'
                        AND admission.logical_provider = 'apify'
                        AND admission.request_id = preflight.id
                        AND admission.job_key = 'paid:target-profile'
                        AND admission.operation_key =
                            'target-profile-fresh-admission:g' || preflight.admission_generation::TEXT
                        AND admission.job_claim_token = preflight.admission_claim_token
                        AND admission.claim_token = preflight.admission_claim_token
                        AND admission.state IN ('leased', 'recovery_required')
                        AND admission.expires_at > v_now
                  )
              )
          )
          OR (
              -- Roleless/unknown fresh predecessors are part of the drain cohort. They can
              -- remain status=ready while their durable admission task is queued, so count the
              -- exact admission dispatch states rather than relying on the profile status alone.
              preflight.admission_dispatch_state IN ('reserved', 'enqueued')
              AND preflight.admission_generation BETWEEN 1 AND 100
              AND (
                  preflight.admission_dispatch_workload_role IS NULL
                  OR preflight.admission_dispatch_contract_version IS NULL
                  OR preflight.admission_dispatch_workload_role IS DISTINCT FROM 'paid'
                  OR preflight.admission_dispatch_contract_version IS DISTINCT FROM 2
                  OR preflight.admission_dispatch_token IS NULL
                  OR preflight.admission_dispatch_reserved_at IS NULL
              )
          )
      );

    -- Beta preparation is an explicitly retired producer in the active
    -- exact-three preflight service. Include queued/claimed/active rows, but
    -- not a completed prepared/expired historical row.
    SELECT pg_catalog.count(*)
    INTO v_legacy_active_beta_prepare
    FROM public.analysis_preflights AS preflight
    WHERE preflight.analysis_entry_channel = 'betatest'
      AND preflight.expires_at > v_now
      AND (
          preflight.status IN ('pending', 'processing')
          OR preflight.beta_prepare_state IN ('reserved', 'preparing')
          OR preflight.beta_prepare_dispatch_state IN ('reserved', 'enqueued')
          OR (
              preflight.beta_prepare_lease_token IS NOT NULL
              AND preflight.beta_prepare_lease_expires_at > v_now
          )
      );

    SELECT pg_catalog.count(*)
    INTO v_unreconciled_provider_runs
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.status IN ('succeeded', 'failed', 'aborted', 'timed_out')
      AND provider_run.usage_reconciled_at IS NULL;

    SELECT pg_catalog.count(*)
    INTO v_unreconciled_preflight_runs
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.status IN ('succeeded', 'failed', 'aborted', 'timed_out')
      AND provider_run.usage_reconciled_at IS NULL;

    SELECT pg_catalog.count(*)
    INTO v_unreconciled_profile_repair_runs
    FROM public.analysis_v2_profile_repair_canary_runs AS canary_run
    WHERE canary_run.state IN ('succeeded', 'failed')
      AND canary_run.usage_reconciled_at IS NULL;

    SELECT pg_catalog.count(*)
    INTO v_unreconciled_v1_provider_runs
    FROM public.analysis_provider_runs AS provider_run;

    SELECT pg_catalog.count(*)
    INTO v_unreconciled_profile_provider_canary_runs
    FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
    WHERE canary_run.state IN ('succeeded', 'failed', 'verified_no_run')
      AND canary_run.usage_reconciled_at IS NULL;

    RETURN pg_catalog.jsonb_build_object(
        'ready',
            v_legacy_active_provider_runs = 0
            AND v_legacy_active_preflight_runs = 0
            AND v_legacy_active_profile_repair_runs = 0
            AND v_legacy_active_v1_provider_runs = 0
            AND v_legacy_active_processing_claims = 0
            AND v_legacy_active_v2_job_claims = 0
            AND v_legacy_active_profile_provider_canary_runs = 0
            AND v_legacy_active_old_target_invocations = 0
            AND v_legacy_active_queued_preflight_tasks = 0
            AND v_legacy_active_queued_v2_tasks = 0
            AND v_legacy_active_fresh_admissions = 0
            AND v_legacy_active_beta_prepare = 0
            AND v_unreconciled_provider_runs = 0
            AND v_unreconciled_preflight_runs = 0
            AND v_unreconciled_profile_repair_runs = 0
            AND v_unreconciled_v1_provider_runs = 0
            AND v_unreconciled_profile_provider_canary_runs = 0,
        'legacyActiveProviderRuns', v_legacy_active_provider_runs,
        'legacyActivePreflightRuns', v_legacy_active_preflight_runs,
        'legacyActiveProfileRepairRuns', v_legacy_active_profile_repair_runs,
        'legacyActiveV1ProviderRuns', v_legacy_active_v1_provider_runs,
        'legacyActiveProcessingClaims', v_legacy_active_processing_claims,
        'legacyActiveV2JobClaims', v_legacy_active_v2_job_claims,
        'legacyActiveProfileProviderCanaryRuns', v_legacy_active_profile_provider_canary_runs,
        'legacyActiveOldTargetInvocations', v_legacy_active_old_target_invocations,
        'legacyActiveQueuedPreflightTasks', v_legacy_active_queued_preflight_tasks,
        'legacyActiveQueuedV2Tasks', v_legacy_active_queued_v2_tasks,
        'legacyActiveFreshAdmissions', v_legacy_active_fresh_admissions,
        'legacyActiveBetaPrepare', v_legacy_active_beta_prepare,
        'unreconciledProviderRuns', v_unreconciled_provider_runs,
        'unreconciledPreflightRuns', v_unreconciled_preflight_runs,
        'unreconciledProfileRepairRuns', v_unreconciled_profile_repair_runs,
        'unreconciledV1ProviderRuns', v_unreconciled_v1_provider_runs,
        'unreconciledProfileProviderCanaryRuns', v_unreconciled_profile_provider_canary_runs,
        'legacyActiveTotal',
            v_legacy_active_provider_runs
            + v_legacy_active_preflight_runs
            + v_legacy_active_profile_repair_runs
            + v_legacy_active_v1_provider_runs
            + v_legacy_active_processing_claims
            + v_legacy_active_v2_job_claims
            + v_legacy_active_profile_provider_canary_runs
            + v_legacy_active_old_target_invocations
            + v_legacy_active_queued_preflight_tasks
            + v_legacy_active_queued_v2_tasks
            + v_legacy_active_fresh_admissions
            + v_legacy_active_beta_prepare,
        'unreconciledTotal',
            v_unreconciled_provider_runs
            + v_unreconciled_preflight_runs
            + v_unreconciled_profile_repair_runs
            + v_unreconciled_v1_provider_runs
            + v_unreconciled_profile_provider_canary_runs
    );
END;
$_$;


--
-- Name: analysis_order_audit_bundles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_order_audit_bundles (
    request_id uuid NOT NULL,
    version integer NOT NULL,
    bundle_hash character varying(64) NOT NULL,
    previous_version_hash character varying(64),
    source_set_hash character varying(64) NOT NULL,
    pipeline_version character varying(32) NOT NULL,
    pipeline_policy jsonb DEFAULT '{}'::jsonb NOT NULL,
    risk_policy_version character varying(64),
    ai_policy_version character varying(64),
    scheduler_policy_version character varying(64),
    plan_id character varying(16) NOT NULL,
    access_mode character varying(32) NOT NULL,
    order_id uuid,
    preflight_id uuid,
    target_instagram_id character varying(30),
    target_profile_available boolean NOT NULL,
    target_posts_available boolean NOT NULL,
    target_post_count integer,
    followers_declared integer,
    followers_collected integer,
    following_declared integer,
    following_collected integer,
    mutual_total integer NOT NULL,
    mutual_list_hash character varying(64) NOT NULL,
    public_total integer NOT NULL,
    private_total integer NOT NULL,
    screened_total integer NOT NULL,
    candidate_declared integer NOT NULL,
    candidate_collected integer NOT NULL,
    interaction_declared integer NOT NULL,
    interaction_collected integer NOT NULL,
    target_likes_declared integer,
    target_likes_collected integer,
    target_comments_declared integer,
    target_comments_collected integer,
    candidate_likes_declared integer,
    candidate_likes_collected integer,
    candidate_likes_evidence_collected integer,
    tags_declared integer,
    tags_collected integer,
    mentions_declared integer,
    mentions_collected integer,
    candidate_key_coverage jsonb DEFAULT '{}'::jsonb NOT NULL,
    provider_runs jsonb DEFAULT '[]'::jsonb NOT NULL,
    stage_status jsonb DEFAULT '{}'::jsonb NOT NULL,
    completeness_status character varying(16) NOT NULL,
    gap_codes text[] DEFAULT '{}'::text[] NOT NULL,
    cost_currency character varying(3) DEFAULT 'USD'::character varying NOT NULL,
    cost_status character varying(16) NOT NULL,
    cost_known_usd numeric(18,12),
    cost_conservative_usd numeric(18,12),
    total_known_cost_usd numeric(18,12),
    total_conservative_cost_usd numeric(18,12),
    cost_usage_unknown boolean NOT NULL,
    usage_unknown boolean NOT NULL,
    cost_missing_source_codes text[] DEFAULT '{}'::text[] NOT NULL,
    cost_provenance jsonb DEFAULT '{}'::jsonb NOT NULL,
    assembled_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_order_audit_bundle_access_check CHECK (((access_mode)::text = ANY ((ARRAY['production'::character varying, 'test_entitlement'::character varying])::text[]))),
    CONSTRAINT analysis_order_audit_bundle_completeness_check CHECK (((completeness_status)::text = ANY ((ARRAY['complete'::character varying, 'partial'::character varying, 'inconsistent'::character varying, 'failed'::character varying])::text[]))),
    CONSTRAINT analysis_order_audit_bundle_cost_check CHECK ((((cost_known_usd IS NULL) OR (cost_known_usd >= (0)::numeric)) AND ((cost_conservative_usd IS NULL) OR (cost_conservative_usd >= (0)::numeric)) AND ((total_known_cost_usd IS NULL) OR (total_known_cost_usd >= (0)::numeric)) AND ((total_conservative_cost_usd IS NULL) OR (total_conservative_cost_usd >= (0)::numeric)))),
    CONSTRAINT analysis_order_audit_bundle_cost_status_check CHECK (((cost_status)::text = ANY ((ARRAY['complete'::character varying, 'partial'::character varying, 'unknown'::character varying, 'not_available'::character varying])::text[]))),
    CONSTRAINT analysis_order_audit_bundle_count_check CHECK (((mutual_total >= 0) AND (public_total >= 0) AND (private_total >= 0) AND ((public_total + private_total) = mutual_total) AND (screened_total >= 0) AND (candidate_declared >= 0) AND (candidate_collected >= 0) AND (interaction_declared >= 0) AND (interaction_collected >= 0) AND ((target_likes_declared IS NULL) OR (target_likes_declared >= 0)) AND ((target_likes_collected IS NULL) OR (target_likes_collected >= 0)) AND ((target_comments_declared IS NULL) OR (target_comments_declared >= 0)) AND ((target_comments_collected IS NULL) OR (target_comments_collected >= 0)) AND ((candidate_likes_declared IS NULL) OR (candidate_likes_declared >= 0)) AND ((candidate_likes_collected IS NULL) OR (candidate_likes_collected >= 0)) AND ((candidate_likes_evidence_collected IS NULL) OR (candidate_likes_evidence_collected >= 0)) AND ((tags_declared IS NULL) OR (tags_declared >= 0)) AND ((tags_collected IS NULL) OR (tags_collected >= 0)) AND ((mentions_declared IS NULL) OR (mentions_declared >= 0)) AND ((mentions_collected IS NULL) OR (mentions_collected >= 0)))),
    CONSTRAINT analysis_order_audit_bundle_hash_check CHECK ((((bundle_hash)::text ~ '^[a-f0-9]{64}$'::text) AND ((source_set_hash)::text ~ '^[a-f0-9]{64}$'::text) AND ((previous_version_hash IS NULL) OR ((previous_version_hash)::text ~ '^[a-f0-9]{64}$'::text)))),
    CONSTRAINT analysis_order_audit_bundle_json_check CHECK (((jsonb_typeof(pipeline_policy) = 'object'::text) AND (jsonb_typeof(provider_runs) = 'array'::text) AND (jsonb_typeof(stage_status) = 'object'::text) AND (jsonb_typeof(candidate_key_coverage) = 'object'::text) AND (jsonb_typeof(cost_provenance) = ANY (ARRAY['object'::text, 'array'::text])))),
    CONSTRAINT analysis_order_audit_bundle_pipeline_check CHECK (((pipeline_version)::text = 'v2'::text)),
    CONSTRAINT analysis_order_audit_bundle_plan_check CHECK (((plan_id)::text = ANY ((ARRAY['basic'::character varying, 'standard'::character varying, 'plus'::character varying])::text[]))),
    CONSTRAINT analysis_order_audit_bundle_version_check CHECK (((version >= 1) AND (version <= 100000)))
);

ALTER TABLE ONLY public.analysis_order_audit_bundles FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_order_audit_bundle_payload(public.analysis_order_audit_bundles); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_order_audit_bundle_payload(p_bundle public.analysis_order_audit_bundles) RETURNS jsonb
    LANGUAGE sql STABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'requestId', p_bundle.request_id::TEXT,
        'version', p_bundle.version,
        'bundleHash', p_bundle.bundle_hash,
        'previousVersionHash', p_bundle.previous_version_hash,
        'sourceSetHash', p_bundle.source_set_hash,
        'status', p_bundle.completeness_status,
        'completeness', p_bundle.completeness_status,
        'gapCodes', pg_catalog.to_jsonb(p_bundle.gap_codes),
        'pipelineVersion', p_bundle.pipeline_version,
        'pipelinePolicy', public.analysis_order_audit_redact_json(p_bundle.pipeline_policy),
        'riskPolicyVersion', p_bundle.risk_policy_version,
        'aiPolicyVersion', p_bundle.ai_policy_version,
        'schedulerPolicyVersion', p_bundle.scheduler_policy_version,
        'planId', p_bundle.plan_id,
        'accessMode', p_bundle.access_mode,
        'orderId', p_bundle.order_id,
        'targetInstagramId', p_bundle.target_instagram_id,
        'targetProfileAvailable', p_bundle.target_profile_available,
        'targetPostsAvailable', p_bundle.target_posts_available,
        'targetPostCount', p_bundle.target_post_count,
        'followers', pg_catalog.jsonb_build_object(
            'declared', p_bundle.followers_declared,
            'collected', p_bundle.followers_collected
        ),
        'following', pg_catalog.jsonb_build_object(
            'declared', p_bundle.following_declared,
            'collected', p_bundle.following_collected
        ),
        'mutuals', pg_catalog.jsonb_build_object(
            'total', p_bundle.mutual_total,
            'public', p_bundle.public_total,
            'private', p_bundle.private_total,
            'screened', p_bundle.screened_total,
            'declared', p_bundle.candidate_declared,
            'collected', p_bundle.candidate_collected,
            'listHash', p_bundle.mutual_list_hash,
            'keyCoverage', p_bundle.candidate_key_coverage
        ),
        'gender', public.analysis_order_audit_summary_counts(
            p_bundle.request_id, p_bundle.version
        )->'gender',
        'risk', public.analysis_order_audit_summary_counts(
            p_bundle.request_id, p_bundle.version
        )->'risk',
        'interactions', pg_catalog.jsonb_build_object(
            'declared', p_bundle.interaction_declared,
            'collected', p_bundle.interaction_collected,
            'targetLikes', pg_catalog.jsonb_build_object(
                'declared', p_bundle.target_likes_declared,
                'collected', p_bundle.target_likes_collected
            ),
            'targetComments', pg_catalog.jsonb_build_object(
                'declared', p_bundle.target_comments_declared,
                'collected', p_bundle.target_comments_collected
            ),
            'candidateLikes', pg_catalog.jsonb_build_object(
                'declared', p_bundle.candidate_likes_declared,
                'collected', p_bundle.candidate_likes_collected,
                'evidenceCollected', p_bundle.candidate_likes_evidence_collected
            ),
            'tags', pg_catalog.jsonb_build_object(
                'declared', p_bundle.tags_declared,
                'collected', p_bundle.tags_collected
            ),
            'mentions', pg_catalog.jsonb_build_object(
                'declared', p_bundle.mentions_declared,
                'collected', p_bundle.mentions_collected
            )
        ),
        'providerRuns', p_bundle.provider_runs,
        'stageStatus', p_bundle.stage_status,
        'retention', public.analysis_order_audit_retention_payload(
            p_bundle.request_id, p_bundle.version, p_bundle.assembled_at
        ),
        'assembledAt', p_bundle.assembled_at,
        'cost', pg_catalog.jsonb_build_object(
            'currency', p_bundle.cost_currency,
            'status', p_bundle.cost_status,
            'knownUsd', p_bundle.cost_known_usd,
            'conservativeUsd', p_bundle.cost_conservative_usd,
            'totalKnownCostUsd', p_bundle.total_known_cost_usd,
            'totalConservativeCostUsd', p_bundle.total_conservative_cost_usd,
            'usageUnknown', p_bundle.cost_usage_unknown,
            'missingSourceCodes', pg_catalog.to_jsonb(p_bundle.cost_missing_source_codes),
            'provenance', public.analysis_order_audit_redact_json(p_bundle.cost_provenance)
        ),
        'usageUnknown', p_bundle.usage_unknown
    );
$$;


--
-- Name: analysis_order_audit_candidate_key_coverage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_order_audit_candidate_key_coverage(p_request_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    WITH selected_relationship AS (
        SELECT manifest.job_key
        FROM public.analysis_v2_relationship_manifests AS manifest
        WHERE manifest.request_id = p_request_id
        ORDER BY manifest.updated_at DESC NULLS LAST, manifest.job_key DESC
        LIMIT 1
    ),
    expected AS (
        SELECT DISTINCT mutual.username
        FROM public.analysis_v2_mutual_rows AS mutual
        WHERE mutual.request_id = p_request_id
          AND (
              NOT EXISTS (SELECT 1 FROM selected_relationship)
              OR mutual.job_key = (SELECT job_key FROM selected_relationship)
          )
    ),
    observed AS (
        SELECT DISTINCT feature.instagram_id AS username
        FROM public.analysis_v2_candidate_feature_rows AS feature
        WHERE feature.request_id = p_request_id
        UNION
        SELECT DISTINCT private_name.instagram_id AS username
        FROM public.analysis_v2_private_name_rows AS private_name
        WHERE private_name.request_id = p_request_id
    ),
    missing AS (
        SELECT expected.username FROM expected
        EXCEPT SELECT observed.username FROM observed
    ),
    extra AS (
        SELECT observed.username FROM observed
        EXCEPT SELECT expected.username FROM expected
    )
    SELECT pg_catalog.jsonb_build_object(
        'expected', COALESCE((
            SELECT pg_catalog.jsonb_agg(username ORDER BY username) FROM expected
        ), '[]'::JSONB),
        'observed', COALESCE((
            SELECT pg_catalog.jsonb_agg(username ORDER BY username) FROM observed
        ), '[]'::JSONB),
        'missing', COALESCE((
            SELECT pg_catalog.jsonb_agg(username ORDER BY username) FROM missing
        ), '[]'::JSONB),
        'extra', COALESCE((
            SELECT pg_catalog.jsonb_agg(username ORDER BY username) FROM extra
        ), '[]'::JSONB),
        'complete', NOT EXISTS (SELECT 1 FROM missing)
            AND NOT EXISTS (SELECT 1 FROM extra)
    );
$$;


--
-- Name: analysis_order_audit_cost_source_hash(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_order_audit_cost_source_hash(p_request_id uuid) RETURNS character varying
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT public.analysis_order_audit_digest(COALESCE((
        SELECT public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(rollup))::TEXT
        FROM public.analysis_v2_cost_rollups AS rollup
        WHERE rollup.request_id = p_request_id
        LIMIT 1
    ), 'missing-cost-source'));
$$;


--
-- Name: analysis_order_audit_digest(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_order_audit_digest(p_value text) RETURNS character varying
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.encode(
        extensions.digest(pg_catalog.convert_to(p_value, 'UTF8'), 'sha256'),
        'hex'
    );
$$;


--
-- Name: analysis_order_audit_enqueue_from_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_order_audit_enqueue_from_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.pipeline_version = 'v2'
       AND NEW.status IN ('completed', 'failed') THEN
        BEGIN
            PERFORM public.enqueue_analysis_order_audit_bundle(NEW.id);
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING USING MESSAGE = 'ANALYSIS_ORDER_AUDIT_ENQUEUE_FAILED';
        END;
        BEGIN
            PERFORM public.assemble_analysis_order_audit_bundle(NEW.id);
            PERFORM public.analysis_v2_purge_result_working_set(NEW.id, TRUE);
        EXCEPTION WHEN OTHERS THEN
            BEGIN
                PERFORM public.analysis_order_audit_purge_fence(
                    NEW.id, 'ANALYSIS_ORDER_AUDIT_ASSEMBLY_FAILED'
                );
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
            RAISE WARNING USING MESSAGE = 'ANALYSIS_ORDER_AUDIT_ASSEMBLY_FAILED';
        END;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: analysis_order_audit_enqueue_from_request_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_order_audit_enqueue_from_request_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    -- enqueue_analysis_order_audit_bundle compares costSourceHash with the latest immutable
    -- parent. INSERT and UPDATE both reach that comparison; unchanged cost keeps queue status = 'completed'
    -- while an IS DISTINCT FROM cost source reopens exactly one queue.
    IF TG_OP = 'INSERT'
       OR (TG_OP = 'UPDATE' AND NEW.request_id IS DISTINCT FROM NULL) THEN
        BEGIN
            PERFORM public.enqueue_analysis_order_audit_bundle(NEW.request_id);
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING USING MESSAGE = 'ANALYSIS_ORDER_AUDIT_ENQUEUE_FAILED';
        END;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: analysis_order_audit_parity_attestation_is_safe(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_order_audit_parity_attestation_is_safe(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
DECLARE
    v_entry RECORD;
    v_key TEXT;
    v_scalar TEXT;
BEGIN
    IF pg_catalog.jsonb_typeof(p_value) = 'object' THEN
        FOR v_entry IN
            SELECT entry.key, entry.value
            FROM pg_catalog.jsonb_each(p_value) AS entry
        LOOP
            v_key := pg_catalog.regexp_replace(
                pg_catalog.lower(v_entry.key), '[_-]', '', 'g'
            );
            IF v_key IN (
                'userid', 'useruuid', 'ownerid', 'owneruuid', 'actorid', 'actoruuid',
                'requestid', 'orderid', 'preflightid', 'accountid', 'provideraccount',
                'username', 'handle', 'comment', 'commenttext', 'raw', 'rawdata',
                'rawpayload', 'providerpayload', 'providerresponse', 'url', 'uri',
                'credential', 'credentials', 'password', 'cookie', 'authorization',
                'secret', 'session', 'sessionid'
            ) OR v_key LIKE '%token%'
              OR v_key LIKE '%payload%'
              OR v_key LIKE '%credential%'
              OR v_key LIKE '%secret%'
              OR v_key LIKE '%password%'
              OR v_key LIKE '%comment%'
              OR v_key LIKE '%username%'
              OR v_key LIKE '%handle%' THEN
                RETURN FALSE;
            END IF;
            IF NOT public.analysis_order_audit_parity_attestation_is_safe(v_entry.value) THEN
                RETURN FALSE;
            END IF;
        END LOOP;
    ELSIF pg_catalog.jsonb_typeof(p_value) = 'array' THEN
        FOR v_entry IN
            SELECT entry.value
            FROM pg_catalog.jsonb_array_elements(p_value) AS entry
        LOOP
            IF NOT public.analysis_order_audit_parity_attestation_is_safe(v_entry.value) THEN
                RETURN FALSE;
            END IF;
        END LOOP;
    ELSIF pg_catalog.jsonb_typeof(p_value) = 'string' THEN
        v_scalar := p_value #>> '{}';
        IF v_scalar ~* '^[A-Za-z][A-Za-z0-9+.-]*://'
           OR v_scalar ~* '^www\.'
           OR v_scalar ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
            RETURN FALSE;
        END IF;
    END IF;
    RETURN TRUE;
END;
$_$;


--
-- Name: analysis_order_audit_purge_fence(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_order_audit_purge_fence(p_request_id uuid, p_reason text DEFAULT 'ANALYSIS_ORDER_AUDIT_ASSEMBLY_FAILED'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
BEGIN
    -- ANALYSIS_ORDER_AUDIT_PURGE_FENCED is the durable safety outcome; the successful path emits
    -- ANALYSIS_ORDER_AUDIT_PURGE_COMPLETED after all allowlisted source rows are deleted.
    IF p_request_id IS NULL
       OR p_reason IS NULL
       OR p_reason !~ '^[A-Z][A-Z0-9_:-]{1,95}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_ORDER_AUDIT_INVALID_PURGE_FENCE', ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_order_audit_assembly_queue
       SET status = 'failed',
           next_attempt_at = pg_catalog.clock_timestamp(),
           lease_token = NULL,
           lease_expires_at = NULL,
           purge_fenced_at = pg_catalog.clock_timestamp(),
           purge_fence_reason = p_reason,
           purged_at = NULL,
           updated_at = pg_catalog.clock_timestamp()
     WHERE request_id = p_request_id;
END;
$_$;


--
-- Name: analysis_order_audit_redact_json(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_order_audit_redact_json(p_value jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
DECLARE
    v_type TEXT := pg_catalog.jsonb_typeof(p_value);
    v_result JSONB;
BEGIN
    IF v_type = 'object' THEN
        SELECT COALESCE(pg_catalog.jsonb_object_agg(entry.key,
            public.analysis_order_audit_redact_json(entry.value)), '{}'::JSONB)
          INTO v_result
          FROM pg_catalog.jsonb_each(p_value) AS entry(key, value)
         WHERE pg_catalog.lower(entry.key) NOT IN (
             'userid', 'user_id', 'providertoken', 'provider_token',
             'accesstoken', 'access_token', 'cookie', 'authorization',
             'requestid', 'request_id', 'orderid', 'order_id',
             'preflightid', 'preflight_id', 'actor', 'secret', 'token',
             'useruuid', 'user_uuid',
             'ownerid', 'owner_id', 'actorid', 'actor_id',
             'provideraccountid', 'provider_account_id', 'provideraccount',
             'provider_account', 'accountid', 'account_id', 'account', 'owner',
             'raw_payload', 'rawpayload', 'raw', 'raw_data', 'rawdata', 'provider_payload',
             'providerpayload', 'provider_response', 'providerresponse', 'job_claim_token',
             'jobclaimtoken', 'claim_token', 'claimtoken', 'reservation_token',
             'reservationtoken', 'session', 'session_id', 'sessionid',
             'producer_claim_token', 'producerclaimtoken'
         );
        RETURN v_result;
    END IF;
    IF v_type = 'array' THEN
        SELECT COALESCE(pg_catalog.jsonb_agg(
            public.analysis_order_audit_redact_json(entry.value)
            ORDER BY entry.ordinality
        ), '[]'::JSONB)
          INTO v_result
          FROM pg_catalog.jsonb_array_elements(p_value)
            WITH ORDINALITY AS entry(value, ordinality);
        RETURN v_result;
    END IF;
    RETURN p_value;
END;
$$;


--
-- Name: analysis_order_audit_retention_payload(uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_order_audit_retention_payload(p_request_id uuid, p_version integer, p_assembled_at timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT COALESCE((
        SELECT pg_catalog.jsonb_build_object(
            'state', CASE
                WHEN queue.purge_fenced_at IS NOT NULL THEN 'fenced'
                WHEN queue.status = 'completed' THEN 'retained'
                ELSE 'pending'
            END,
            'queueStatus', queue.status,
            'version', p_version,
            'assembledAt', p_assembled_at,
            'purgeFencedAt', queue.purge_fenced_at,
            'purgeFenceReason', queue.purge_fence_reason,
            'purgedAt', queue.purged_at,
            'queueUpdatedAt', queue.updated_at
        )
        FROM public.analysis_order_audit_assembly_queue AS queue
        WHERE queue.request_id = p_request_id
    ), pg_catalog.jsonb_build_object(
        'state', 'unknown',
        'queueStatus', NULL,
        'version', p_version,
        'assembledAt', p_assembled_at,
        'purgeFencedAt', NULL,
        'purgeFenceReason', NULL,
        'purgedAt', NULL,
        'queueUpdatedAt', NULL
    ));
$$;


--
-- Name: analysis_order_audit_source_table_hash(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_order_audit_source_table_hash(p_table_name text, p_request_id uuid) RETURNS character varying
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_hash VARCHAR(64);
BEGIN
    IF p_table_name IS NULL
       OR p_table_name !~ '^analysis_v2_[a-z0-9_]+$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_ORDER_AUDIT_INVALID_SOURCE_TABLE', ERRCODE = 'P0001';
    END IF;
    IF pg_catalog.to_regclass('public.' || p_table_name) IS NULL THEN
        RETURN public.analysis_order_audit_digest('missing-table:' || p_table_name);
    END IF;
    EXECUTE pg_catalog.format(
        'SELECT public.analysis_order_audit_digest(COALESCE((
             SELECT pg_catalog.jsonb_agg(
                 public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(source))
                 ORDER BY pg_catalog.to_jsonb(source)::TEXT
             )::TEXT
             FROM public.%I AS source
             WHERE source.request_id = $1
         ), ''[]''))', p_table_name
    ) INTO v_hash USING p_request_id;
    RETURN v_hash;
END;
$_$;


--
-- Name: analysis_order_audit_summary_counts(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_order_audit_summary_counts(p_request_id uuid, p_version integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'gender', pg_catalog.jsonb_build_object(
            'initialResolved', COUNT(*) FILTER (
                WHERE candidate.initial_gender_output IN ('female', 'male')
            )::INTEGER,
            'finalResolved', COUNT(*) FILTER (
                WHERE candidate.final_gender_output IN ('female', 'male')
            )::INTEGER
        ),
        'risk', pg_catalog.jsonb_build_object(
            'declared', COUNT(*) FILTER (
                WHERE NOT candidate.is_private
                  AND candidate.final_gender_output = 'female'
            )::INTEGER,
            'collected', COUNT(*) FILTER (
                WHERE NOT candidate.is_private
                  AND candidate.final_gender_output = 'female'
                  AND candidate.final_score IS NOT NULL
            )::INTEGER
        )
    )
    FROM public.analysis_order_audit_candidates AS candidate
    WHERE candidate.request_id = p_request_id
      AND candidate.version = p_version;
$$;


--
-- Name: analysis_v2_valid_apify_credential_slot(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_apify_credential_slot(p_slot text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT COALESCE(
        p_slot IN (
            'primary', 'secondary', 'tertiary', 'quaternary', 'quinary',
            'senary', 'septenary', 'octonary', 'nonary', 'tenth'
        ),
        FALSE
    );
$$;


--
-- Name: analysis_preflight_provider_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_preflight_provider_runs (
    preflight_id uuid NOT NULL,
    operation_key text DEFAULT 'target-profile-fallback'::text NOT NULL,
    input_hash character varying(64) NOT NULL,
    logical_provider text DEFAULT 'apify'::text NOT NULL,
    actor_id text DEFAULT 'apify/instagram-profile-scraper'::text NOT NULL,
    credential_slot text NOT NULL,
    max_charge_usd numeric(18,12) NOT NULL,
    status text DEFAULT 'starting'::text NOT NULL,
    run_id character varying(64),
    actual_usage_usd numeric(18,12),
    reserved_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    run_started_at timestamp with time zone,
    terminalized_at timestamp with time zone,
    usage_reconciled_at timestamp with time zone,
    usage_reconciliation_attempt_count integer DEFAULT 0 NOT NULL,
    usage_reconciliation_attempted_at timestamp with time zone,
    manual_resolution_evidence_hash character varying(64),
    manual_resolved_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    reusable_profile_schema_version smallint,
    CONSTRAINT analysis_preflight_provider_run_actor_check CHECK ((actor_id = 'apify/instagram-profile-scraper'::text)),
    CONSTRAINT analysis_preflight_provider_run_cost_check CHECK (((max_charge_usd = 0.002600000000) AND ((actual_usage_usd IS NULL) OR (((actual_usage_usd >= (0)::numeric) AND (actual_usage_usd <= (100000)::numeric)) AND (actual_usage_usd <= (max_charge_usd + 0.000000001)))))),
    CONSTRAINT analysis_preflight_provider_run_credential_check CHECK (public.analysis_v2_valid_apify_credential_slot(credential_slot)),
    CONSTRAINT analysis_preflight_provider_run_input_hash_check CHECK (((input_hash)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT analysis_preflight_provider_run_operation_check CHECK (((operation_key = 'target-profile-fallback'::text) OR (operation_key ~ '^target-profile-fresh-admission:g([1-9]|[1-9][0-9]|100)$'::text))),
    CONSTRAINT analysis_preflight_provider_run_provider_check CHECK ((logical_provider = 'apify'::text)),
    CONSTRAINT analysis_preflight_provider_run_reusable_profile_schema_check CHECK (((reusable_profile_schema_version IS NULL) OR (reusable_profile_schema_version = 1))),
    CONSTRAINT analysis_preflight_provider_run_run_id_check CHECK (((run_id IS NULL) OR ((run_id)::text ~ '^[A-Za-z0-9]{8,64}$'::text))),
    CONSTRAINT analysis_preflight_provider_run_state_check CHECK ((((status = 'starting'::text) AND (run_id IS NULL) AND (run_started_at IS NULL) AND (terminalized_at IS NULL) AND (actual_usage_usd IS NULL) AND (usage_reconciled_at IS NULL) AND (usage_reconciliation_attempt_count = 0) AND (usage_reconciliation_attempted_at IS NULL) AND (manual_resolution_evidence_hash IS NULL) AND (manual_resolved_at IS NULL)) OR ((status = 'running'::text) AND (run_id IS NOT NULL) AND (run_started_at IS NOT NULL) AND (terminalized_at IS NULL) AND (actual_usage_usd IS NULL) AND (usage_reconciled_at IS NULL) AND (manual_resolution_evidence_hash IS NULL) AND (manual_resolved_at IS NULL)) OR ((status = 'rejected'::text) AND (run_id IS NULL) AND (run_started_at IS NULL) AND (terminalized_at IS NOT NULL) AND (actual_usage_usd = (0)::numeric) AND (usage_reconciled_at IS NOT NULL) AND (usage_reconciliation_attempt_count = 0) AND (usage_reconciliation_attempted_at IS NULL) AND (manual_resolution_evidence_hash IS NULL) AND (manual_resolved_at IS NULL)) OR ((status = ANY (ARRAY['succeeded'::text, 'failed'::text, 'aborted'::text, 'timed_out'::text])) AND (run_id IS NOT NULL) AND (run_started_at IS NOT NULL) AND (terminalized_at IS NOT NULL) AND (((actual_usage_usd IS NULL) AND (usage_reconciled_at IS NULL)) OR ((actual_usage_usd IS NOT NULL) AND (usage_reconciled_at IS NOT NULL))) AND (manual_resolution_evidence_hash IS NULL) AND (manual_resolved_at IS NULL)) OR ((status = 'resolved_no_run'::text) AND (run_id IS NULL) AND (run_started_at IS NULL) AND (terminalized_at IS NOT NULL) AND (actual_usage_usd = (0)::numeric) AND (usage_reconciled_at IS NOT NULL) AND (usage_reconciliation_attempt_count = 0) AND (usage_reconciliation_attempted_at IS NULL) AND ((manual_resolution_evidence_hash)::text ~ '^[0-9a-f]{64}$'::text) AND (manual_resolved_at IS NOT NULL)) OR ((status = 'resolved_identity_drift'::text) AND (run_id IS NULL) AND (run_started_at IS NULL) AND (terminalized_at IS NOT NULL) AND (actual_usage_usd = max_charge_usd) AND (usage_reconciled_at IS NOT NULL) AND (usage_reconciliation_attempt_count = 0) AND (usage_reconciliation_attempted_at IS NULL) AND ((manual_resolution_evidence_hash)::text ~ '^[0-9a-f]{64}$'::text) AND (manual_resolved_at IS NOT NULL)))),
    CONSTRAINT analysis_preflight_provider_run_status_check CHECK ((status = ANY (ARRAY['starting'::text, 'running'::text, 'rejected'::text, 'succeeded'::text, 'failed'::text, 'aborted'::text, 'timed_out'::text, 'resolved_no_run'::text, 'resolved_identity_drift'::text]))),
    CONSTRAINT analysis_preflight_provider_run_time_check CHECK (((updated_at >= reserved_at) AND ((run_started_at IS NULL) OR (run_started_at >= reserved_at)) AND ((terminalized_at IS NULL) OR (terminalized_at >= run_started_at)) AND ((usage_reconciled_at IS NULL) OR (usage_reconciled_at >= terminalized_at)) AND ((manual_resolved_at IS NULL) OR (manual_resolved_at >= reserved_at)) AND ((manual_resolved_at IS NULL) OR (terminalized_at = manual_resolved_at)) AND ((manual_resolved_at IS NULL) OR (usage_reconciled_at = manual_resolved_at)) AND ((usage_reconciliation_attempted_at IS NULL) OR (usage_reconciliation_attempted_at >= run_started_at)))),
    CONSTRAINT analysis_preflight_provider_run_usage_attempt_count_check CHECK (((usage_reconciliation_attempt_count >= 0) AND (usage_reconciliation_attempt_count <= 100000)))
);

ALTER TABLE ONLY public.analysis_preflight_provider_runs FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_preflight_provider_run_json(public.analysis_preflight_provider_runs); Type: FUNCTION; Schema: public; Owner: -
