        'usageReconciliationAttemptedAt', p_run.usage_reconciliation_attempted_at,
        'evidenceReferenceHash', p_run.manual_resolution_evidence_hash,
        'manualResolvedAt', p_run.manual_resolved_at
    );
$$;


--
-- Name: analysis_provider_admission_expected_id(text, text, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_provider_admission_expected_id(p_workload_role text, p_logical_provider text, p_credential_slot text, p_request_id uuid, p_job_key text, p_operation_key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'analysis-provider-admission-v1' || E'\n'
                || p_workload_role || E'\n'
                || p_logical_provider || E'\n'
                || p_credential_slot || E'\n'
                || pg_catalog.lower(p_request_id::TEXT) || E'\n'
                || p_job_key || E'\n'
                || p_operation_key,
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    )
$$;


--
-- Name: analysis_provider_admission_leases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_provider_admission_leases (
    admission_id text NOT NULL,
    workload_role text NOT NULL,
    logical_provider text NOT NULL,
    credential_slot text NOT NULL,
    budget_key text NOT NULL,
    request_id uuid NOT NULL,
    job_key text NOT NULL,
    operation_key text NOT NULL,
    claim_token uuid NOT NULL,
    job_claim_token uuid NOT NULL,
    provider_fence bigint,
    lease_token uuid NOT NULL,
    fence bigint DEFAULT 1 NOT NULL,
    state text DEFAULT 'leased'::text NOT NULL,
    acquired_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    released_at timestamp with time zone,
    recovered_at timestamp with time zone,
    release_reason text,
    resolution_source text,
    resolution_token_hash text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_provider_admission_lease_id_check CHECK ((admission_id ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT analysis_provider_admission_lease_terminal_check CHECK ((((state = 'leased'::text) AND (released_at IS NULL) AND (release_reason IS NULL) AND (resolution_source IS NULL) AND (resolution_token_hash IS NULL)) OR ((state = 'released'::text) AND (released_at IS NOT NULL) AND (release_reason = ANY (ARRAY['terminal'::text, 'prestart_rejected'::text, 'ledger_resolved'::text])) AND ((release_reason <> 'ledger_resolved'::text) OR ((resolution_source = ANY (ARRAY['provider_ledger_terminal'::text, 'provider_ledger_absent'::text, 'gemini_lease_fenced'::text])) AND (resolution_token_hash ~ '^[a-f0-9]{64}$'::text)))) OR ((state = 'recovery_required'::text) AND (recovered_at IS NOT NULL) AND (released_at IS NULL) AND (release_reason IS NULL) AND (resolution_source IS NULL) AND (resolution_token_hash IS NULL)))),
    CONSTRAINT analysis_provider_admission_lease_time_check CHECK ((updated_at >= created_at)),
    CONSTRAINT analysis_provider_admission_leases_credential_slot_check CHECK ((credential_slot ~ '^[a-z][a-z0-9_-]{1,31}$'::text)),
    CONSTRAINT analysis_provider_admission_leases_fence_check CHECK ((fence >= 1)),
    CONSTRAINT analysis_provider_admission_leases_job_key_check CHECK ((job_key ~ '^[a-z0-9][a-z0-9:._-]{0,159}$'::text)),
    CONSTRAINT analysis_provider_admission_leases_logical_provider_check CHECK ((logical_provider = ANY (ARRAY['apify'::text, 'gemini'::text]))),
    CONSTRAINT analysis_provider_admission_leases_operation_key_check CHECK ((operation_key ~ '^[a-z0-9][a-z0-9:._-]{0,255}$'::text)),
    CONSTRAINT analysis_provider_admission_leases_state_check CHECK ((state = ANY (ARRAY['leased'::text, 'released'::text, 'recovery_required'::text]))),
    CONSTRAINT analysis_provider_admission_leases_workload_role_check CHECK ((workload_role = ANY (ARRAY['preflight'::text, 'paid'::text]))),
    CONSTRAINT analysis_provider_admission_provider_fence_check CHECK (((provider_fence IS NULL) OR (provider_fence >= 1)))
);

ALTER TABLE ONLY public.analysis_provider_admission_leases FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_provider_admission_json(public.analysis_provider_admission_leases, text, integer, integer, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_provider_admission_json(p_lease public.analysis_provider_admission_leases, p_outcome text, p_active_count integer, p_max_active integer, p_job_claim_token uuid, p_provider_claim_token uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'outcome', p_outcome,
        'admissionId', p_lease.admission_id,
        'workloadRole', p_lease.workload_role,
        'logicalProvider', p_lease.logical_provider,
        'credentialSlot', p_lease.credential_slot,
        'budgetKey', p_lease.budget_key,
        'operationKey', p_lease.operation_key,
        'requestId', pg_catalog.lower(p_lease.request_id::TEXT),
        'jobKey', p_lease.job_key,
        -- The lease secret is returned only to the exact current durable claim.
        -- This is a defense-in-depth check in addition to the claim validation in
        -- acquire; a stale/mis-bound replay must never receive a live secret.
        'leaseToken', CASE WHEN p_lease.state = 'leased'
                                AND p_lease.job_claim_token IS NOT DISTINCT FROM p_job_claim_token
                                AND p_lease.claim_token IS NOT DISTINCT FROM p_provider_claim_token
                           THEN p_lease.lease_token ELSE NULL END,
        'fence', CASE WHEN p_lease.state = 'leased'
                           AND p_lease.job_claim_token IS NOT DISTINCT FROM p_job_claim_token
                           AND p_lease.claim_token IS NOT DISTINCT FROM p_provider_claim_token
                      THEN p_lease.fence ELSE NULL END,
        'expiresAt', CASE WHEN p_lease.state = 'leased'
                               AND p_lease.job_claim_token IS NOT DISTINCT FROM p_job_claim_token
                               AND p_lease.claim_token IS NOT DISTINCT FROM p_provider_claim_token
                          THEN p_lease.expires_at ELSE NULL END,
        'activeCount', p_active_count,
        'maxActive', p_max_active
    )
$$;


--
-- Name: analysis_provider_admission_ledger_state(public.analysis_provider_admission_leases); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_provider_admission_ledger_state(p_lease public.analysis_provider_admission_leases) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_status TEXT;
    v_logical_provider TEXT;
    v_credential_slot TEXT;
    v_run_id TEXT;
    v_terminalized_at TIMESTAMPTZ;
    v_gemini_state TEXT;
    v_gemini_request_id UUID;
    v_gemini_job_key TEXT;
    v_gemini_attempt INTEGER;
    v_gemini_claim_token UUID;
    v_gemini_fence BIGINT;
    v_attempt INTEGER;
    v_claim_live BOOLEAN := FALSE;
    v_claim_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    IF p_lease.logical_provider = 'apify'
       AND p_lease.workload_role = 'preflight' THEN
        SELECT provider_run.status, provider_run.logical_provider,
               provider_run.credential_slot, provider_run.run_id,
               provider_run.terminalized_at
        INTO v_status, v_logical_provider, v_credential_slot, v_run_id, v_terminalized_at
        FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.preflight_id = p_lease.request_id
          AND provider_run.operation_key = p_lease.operation_key;
    ELSIF p_lease.logical_provider = 'apify'
          AND p_lease.workload_role = 'paid'
          AND p_lease.job_key = 'preflight:provider'
          AND p_lease.operation_key = 'target-profile-fallback' THEN
        -- Betatest preflight-held target profiles execute on the preflight
        -- route while consuming paid capacity. Their authoritative provider
        -- ledger remains the preflight-run table; treating this narrow
        -- identity as a normal V2 run would misclassify a live/ambiguous run
        -- as missing and release paid capacity unsafely.
        SELECT provider_run.status, provider_run.logical_provider,
               provider_run.credential_slot, provider_run.run_id,
               provider_run.terminalized_at
        INTO v_status, v_logical_provider, v_credential_slot, v_run_id, v_terminalized_at
        FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.preflight_id = p_lease.request_id
          AND provider_run.operation_key = p_lease.operation_key;
    ELSIF p_lease.logical_provider = 'apify'
          AND p_lease.workload_role = 'paid'
          AND p_lease.job_key = 'paid:target-profile'
          AND p_lease.operation_key ~ '^target-profile-fresh-admission:g([1-9]|[1-9][0-9]|100)$' THEN
        SELECT provider_run.status, provider_run.logical_provider,
               provider_run.credential_slot, provider_run.run_id,
               provider_run.terminalized_at
        INTO v_status, v_logical_provider, v_credential_slot, v_run_id, v_terminalized_at
        FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.preflight_id = p_lease.request_id
          AND provider_run.operation_key = p_lease.operation_key;
    ELSIF p_lease.logical_provider = 'apify' AND p_lease.workload_role = 'paid' THEN
        SELECT provider_run.status, provider_run.logical_provider,
               provider_run.credential_slot, provider_run.run_id,
               provider_run.terminalized_at
        INTO v_status, v_logical_provider, v_credential_slot, v_run_id, v_terminalized_at
        FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = p_lease.request_id
          AND provider_run.job_key = p_lease.job_key
          AND provider_run.operation_key = p_lease.operation_key;
    ELSIF p_lease.logical_provider = 'gemini' AND p_lease.workload_role = 'paid' THEN
        v_attempt := substring(p_lease.operation_key FROM ':attempt:([0-9]+)$')::INTEGER;
        IF v_attempt IS NULL THEN RETURN 'identity_conflict'; END IF;
        v_gemini_state := NULL;
        SELECT lease.state, lease.request_id, lease.job_key, lease.attempt,
               lease.lease_claim_token, lease.fence
        INTO v_gemini_state, v_gemini_request_id, v_gemini_job_key,
             v_gemini_attempt, v_gemini_claim_token, v_gemini_fence
        FROM public.analysis_v2_gemini_leases AS lease
        WHERE lease.slot = substring(p_lease.credential_slot FROM '^gemini-([1-8])$')::INTEGER;
        IF NOT FOUND THEN RETURN 'missing'; END IF;
        -- A cutoff/reap clears the slot identity but retains its monotonic
        -- fence. Once the slot fence advances, the old admission is safely
        -- fenced out even when the slot is currently available.
        IF v_gemini_state = 'available' THEN
            IF p_lease.provider_fence IS NOT NULL
               AND v_gemini_fence > p_lease.provider_fence THEN
                RETURN 'fenced_out';
            END IF;
            RETURN 'available';
        END IF;
        IF p_lease.provider_fence IS NOT NULL
           AND v_gemini_fence > p_lease.provider_fence
           AND (
               v_gemini_request_id IS DISTINCT FROM p_lease.request_id
               OR v_gemini_job_key IS DISTINCT FROM p_lease.job_key
               OR v_gemini_attempt IS DISTINCT FROM v_attempt
               OR v_gemini_claim_token IS DISTINCT FROM p_lease.claim_token
           ) THEN
            RETURN 'fenced_out';
        END IF;
        IF v_gemini_request_id IS DISTINCT FROM p_lease.request_id
           OR v_gemini_job_key IS DISTINCT FROM p_lease.job_key
           OR v_gemini_attempt IS DISTINCT FROM v_attempt THEN
            RETURN 'identity_conflict';
        END IF;
        IF v_gemini_claim_token IS DISTINCT FROM p_lease.claim_token THEN
            RETURN 'identity_conflict';
        END IF;
        IF p_lease.provider_fence IS NOT NULL
           AND v_gemini_fence IS DISTINCT FROM p_lease.provider_fence THEN
            RETURN 'identity_conflict';
        END IF;
        IF v_gemini_state = 'quarantined' THEN RETURN 'quarantined'; END IF;
        IF v_gemini_state = 'leased' THEN RETURN 'running'; END IF;
        RETURN 'pending';
    ELSE
        RETURN 'identity_conflict';
    END IF;

    IF v_status IS NULL THEN
        -- Admission is acquired before the provider-run reservation. A missing
        -- provider row is only safe to retire when the durable owner that was
        -- authorized to create that row is no longer live. The admission TTL
        -- is intentionally shorter than the job/preflight leases, so checking
        -- only the provider ledger would create a TOCTOU window after a pause:
        -- recovery could release capacity and the still-current worker could
        -- reserve/start the provider afterward.
        IF p_lease.workload_role = 'preflight'
           AND p_lease.logical_provider = 'apify'
           AND p_lease.job_key = 'preflight:provider'
           AND p_lease.operation_key = 'target-profile-fallback' THEN
            SELECT EXISTS (
                SELECT 1
                FROM public.analysis_preflights AS preflight
                WHERE preflight.id = p_lease.request_id
                  AND preflight.status = 'processing'
                  AND preflight.lease_token = p_lease.job_claim_token
                  AND preflight.lease_expires_at IS NOT NULL
                  AND preflight.lease_expires_at > v_claim_now
                  AND preflight.expires_at > v_claim_now
            ) INTO v_claim_live;
        ELSIF p_lease.workload_role = 'paid'
              AND p_lease.logical_provider = 'apify'
              AND p_lease.job_key = 'preflight:provider'
              AND p_lease.operation_key = 'target-profile-fallback' THEN
            -- Betatest preflight-held target profiles keep the preflight
            -- processing lease even though their admission consumes paid
            -- capacity.
            SELECT EXISTS (
                SELECT 1
                FROM public.analysis_preflights AS preflight
                WHERE preflight.id = p_lease.request_id
                  AND preflight.status = 'processing'
                  AND preflight.analysis_entry_channel = 'betatest'
                  AND preflight.lease_token = p_lease.job_claim_token
                  AND preflight.lease_expires_at IS NOT NULL
                  AND preflight.lease_expires_at > v_claim_now
                  AND preflight.expires_at > v_claim_now
            ) INTO v_claim_live;
        ELSIF p_lease.workload_role = 'paid'
              AND p_lease.logical_provider = 'apify'
              AND p_lease.job_key = 'paid:target-profile'
              AND p_lease.operation_key ~ '^target-profile-fresh-admission:g([1-9]|[1-9][0-9]|100)$' THEN
            SELECT EXISTS (
                SELECT 1
                FROM public.analysis_preflights AS preflight
                WHERE preflight.id = p_lease.request_id
                  AND preflight.status = 'ready'
                  AND preflight.admission_status = 'processing'
                  AND preflight.admission_claim_token = p_lease.job_claim_token
                  AND preflight.admission_lease_expires_at IS NOT NULL
                  AND preflight.admission_lease_expires_at > v_claim_now
                  AND preflight.expires_at > v_claim_now
            ) INTO v_claim_live;
        ELSIF p_lease.workload_role = 'paid' THEN
            SELECT EXISTS (
                SELECT 1
                FROM public.analysis_pipeline_jobs AS job
                WHERE job.request_id = p_lease.request_id
                  AND job.job_key = p_lease.job_key
                  AND job.status = 'processing'
                  AND job.lease_token = p_lease.job_claim_token
                  AND job.lease_expires_at IS NOT NULL
                  AND job.lease_expires_at > v_claim_now
            ) INTO v_claim_live;
        END IF;
        IF v_claim_live THEN RETURN 'pending'; END IF;
        RETURN 'missing';
    END IF;
    IF v_logical_provider IS DISTINCT FROM p_lease.logical_provider
       OR v_credential_slot IS DISTINCT FROM p_lease.credential_slot THEN
        RETURN 'identity_conflict';
    END IF;
    IF v_status = 'running' THEN RETURN 'running'; END IF;
    IF v_status IN ('succeeded', 'failed', 'aborted', 'timed_out', 'resolved_no_run', 'rejected')
       AND v_terminalized_at IS NOT NULL THEN
        RETURN 'terminal';
    END IF;
    RETURN 'pending';
END;
$_$;


--
-- Name: analysis_result_publication_authorized(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_result_publication_authorized(p_request_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = p_request_id
          AND analysis_request.status = 'completed'
          AND NOT (
              COALESCE(analysis_request.step_data, '{}'::JSONB)
                  ? 'conciergeBatchSource'
              OR COALESCE(analysis_request.idempotency_key, '')
                  LIKE 'concierge-batch-source:%'
          )
          AND (
              -- Free/legacy requests have no paid order projection.
              NOT EXISTS (
                  SELECT 1
                  FROM public.earlybird_orders AS earlybird_order
                  WHERE earlybird_order.result_request_id = analysis_request.id
                    AND earlybird_order.payment_id IS NOT NULL
              )
              -- The separate first-order publisher is authoritative even
              -- though that historic path has no completed outbox row.
              OR (
                  analysis_request.pipeline_version = 'v1'
                  AND COALESCE(analysis_request.step_data, '{}'::JSONB)
                      ? 'conciergeBootstrap'
                  AND EXISTS (
                      SELECT 1
                      FROM public.earlybird_orders AS earlybird_order
                      WHERE earlybird_order.result_request_id = analysis_request.id
                        AND earlybird_order.payment_id IS NOT NULL
                        AND earlybird_order.status = 'completed'
                  )
                  AND NOT EXISTS (
                      SELECT 1
                      FROM public.earlybird_orders AS earlybird_order
                      WHERE earlybird_order.result_request_id = analysis_request.id
                        AND earlybird_order.payment_id IS NOT NULL
                        AND earlybird_order.status IS DISTINCT FROM 'completed'
                  )
              )
              -- A commercial refund transition is compatible with a result
              -- that the request-bound fulfillment already completed. Other
              -- payment and cancellation states remain fail-closed.
              OR NOT EXISTS (
                  SELECT 1
                  FROM public.earlybird_orders AS earlybird_order
                  WHERE earlybird_order.result_request_id = analysis_request.id
                    AND earlybird_order.payment_id IS NOT NULL
                    AND (
                        earlybird_order.status NOT IN (
                            'completed',
                            'refund_pending',
                            'refunded'
                        )
                        OR NOT EXISTS (
                            SELECT 1
                            FROM public.earlybird_fulfillments AS fulfillment
                            WHERE fulfillment.order_id = earlybird_order.id
                              AND fulfillment.request_id = analysis_request.id
                              AND fulfillment.status = 'completed'
                              AND fulfillment.completed_at IS NOT NULL
                        )
                    )
              )
          )
    );
$$;


--
-- Name: analysis_revenue_ai_cost_assert_aggregates_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_revenue_ai_cost_assert_aggregates_v1(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_active_reserved INTEGER;
    v_settled_economic INTEGER;
    v_settled_billed INTEGER;
BEGIN
    SELECT * INTO v_parent FROM public.analysis_revenue_run_ledgers
      WHERE request_id = p_request_id FOR UPDATE;
    SELECT
        COALESCE(pg_catalog.sum(CASE WHEN status IN ('reserved', 'started') THEN reserved_krw ELSE 0 END), 0)::INTEGER,
        COALESCE(pg_catalog.sum(CASE WHEN status = 'settled' THEN economic_actual_krw ELSE 0 END), 0)::INTEGER,
        COALESCE(pg_catalog.sum(CASE WHEN status = 'settled' THEN billed_actual_krw ELSE 0 END), 0)::INTEGER
      INTO v_active_reserved, v_settled_economic, v_settled_billed
      FROM public.analysis_revenue_cost_operations WHERE request_id = p_request_id;
    IF v_parent.request_id IS NULL
       OR v_parent.reserved_cost_krw IS DISTINCT FROM v_active_reserved
       OR v_parent.economic_actual_krw IS DISTINCT FROM v_settled_economic
       OR v_parent.actual_cost_krw IS DISTINCT FROM v_settled_economic
       OR v_parent.billed_actual_krw IS DISTINCT FROM v_settled_billed THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
END;
$$;


--
-- Name: analysis_revenue_ai_cost_assert_lineage_v1(uuid, text, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_revenue_ai_cost_assert_lineage_v1(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_require_live_claim boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_entitlement public.analysis_v2_test_entitlement_consumptions%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_runner_plan TEXT;
    v_now TIMESTAMPTZ;
BEGIN
    IF p_request_id IS NULL OR p_job_key IS NULL
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_require_live_claim IS NULL
       OR (p_require_live_claim AND (
            p_job_claim_token IS NULL OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       )) THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    SELECT * INTO v_preflight FROM public.analysis_preflights
      WHERE consumed_request_id = p_request_id FOR UPDATE;
    SELECT * INTO v_request FROM public.analysis_requests
      WHERE id = p_request_id FOR UPDATE;
    SELECT * INTO v_entitlement FROM public.analysis_v2_test_entitlement_consumptions
      WHERE request_id = p_request_id FOR UPDATE;
    SELECT * INTO v_policy FROM public.analysis_v2_provider_execution_policies
      WHERE request_id = p_request_id FOR UPDATE;
    SELECT runner_plan INTO v_runner_plan FROM public.load_e2e_test_runner_v1(v_request.user_id);
    IF v_preflight.id IS NULL OR v_request.id IS NULL
       OR v_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_entitlement.request_id IS NULL OR v_policy.request_id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot NOT IN ('basic', 'standard')
       OR v_preflight.status IS DISTINCT FROM 'consumed'
       OR v_preflight.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_preflight.admission_generation IS DISTINCT FROM 1
       OR v_preflight.admission_status IS DISTINCT FROM 'ready'
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_preflight.admission_entitlement_jti_hash IS DISTINCT FROM v_request.test_entitlement_jti_hash
       OR v_preflight.admission_refreshed_at IS NULL
       OR v_preflight.user_id IS DISTINCT FROM v_request.user_id
       OR v_entitlement.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_entitlement.user_id IS DISTINCT FROM v_request.user_id
       OR v_entitlement.selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_entitlement.entitlement_jti_hash IS DISTINCT FROM v_request.test_entitlement_jti_hash
       OR v_policy.mode IS DISTINCT FROM 'test_operation_split'
       OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR v_policy.entitlement_jti_hash IS DISTINCT FROM v_entitlement.entitlement_jti_hash
       OR v_runner_plan IS DISTINCT FROM v_request.selected_plan_id_snapshot THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    SELECT * INTO v_job FROM public.analysis_pipeline_jobs
      WHERE request_id = p_request_id AND job_key = p_job_key FOR UPDATE;
    IF v_job.request_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF p_require_live_claim THEN
        v_now := pg_catalog.clock_timestamp();
        IF v_request.status NOT IN ('pending', 'processing')
           OR pg_catalog.lower(v_preflight.target_instagram_id)
                IS DISTINCT FROM pg_catalog.lower(v_request.target_instagram_id)
           OR pg_catalog.lower(v_policy.target_instagram_id)
                IS DISTINCT FROM pg_catalog.lower(v_preflight.target_instagram_id)
           OR v_job.status IS DISTINCT FROM 'processing'
           OR v_job.lease_token IS DISTINCT FROM p_job_claim_token
           OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
           OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at <= v_now THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
        END IF;
    END IF;
END;
$_$;


--
-- Name: analysis_revenue_ai_cost_assert_parent_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_revenue_ai_cost_assert_parent_v1(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
BEGIN
    SELECT * INTO v_preflight FROM public.analysis_preflights
      WHERE consumed_request_id = p_request_id;
    SELECT * INTO v_request FROM public.analysis_requests
      WHERE id = p_request_id;
    SELECT * INTO v_parent FROM public.analysis_revenue_run_ledgers
      WHERE request_id = p_request_id FOR UPDATE;
    IF v_preflight.id IS NULL OR v_request.id IS NULL OR v_parent.request_id IS NULL
       OR v_parent.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_parent.user_id IS DISTINCT FROM v_request.user_id
       OR v_parent.plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_parent.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_parent.target_username_hmac IS DISTINCT FROM v_preflight.target_input_hash
       OR v_parent.preflight_refreshed_at IS DISTINCT FROM v_preflight.admission_refreshed_at
       OR v_parent.request_started_at IS DISTINCT FROM v_request.created_at
       OR v_parent.pricing_snapshot_version IS DISTINCT FROM 'revenue-e2e-cost-2026-08-10-v1'
       OR v_parent.buffered_fx_krw_per_usd IS DISTINCT FROM 1450
       OR v_parent.cost_cap_krw IS DISTINCT FROM (
            CASE WHEN v_request.selected_plan_id_snapshot = 'basic' THEN 1808 ELSE 3634 END
       )
       OR v_parent.margin_target_krw IS DISTINCT FROM (
            CASE WHEN v_request.selected_plan_id_snapshot = 'basic' THEN 904 ELSE 1817 END
       )
       OR v_parent.status NOT IN ('running', 'manual_review') THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
END;
$$;


--
-- Name: analysis_revenue_ai_cost_max_usd_v1(text, text, text, text, smallint, text, text, smallint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_revenue_ai_cost_max_usd_v1(p_model_name text, p_location text, p_stage text, p_thinking_level text, p_media_count smallint, p_media_resolution text, p_prompt_version text, p_schema_version smallint, p_max_output_tokens integer) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    v_input_ceiling INTEGER;
BEGIN
    IF p_model_name IS NULL OR p_location IS NULL OR p_stage IS NULL
       OR p_thinking_level IS NULL OR p_media_count IS NULL
       OR p_media_resolution IS NULL OR p_prompt_version IS NULL
       OR p_schema_version IS NULL OR p_max_output_tokens IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF p_stage = 'genderTriage'
       AND p_model_name = 'gemini-3.1-flash-lite'
       AND p_thinking_level = 'MINIMAL' AND p_media_resolution = 'LOW'
       AND p_media_count BETWEEN 0 AND 10
       AND ((p_prompt_version IN ('gender-triage-v2', 'gender-triage-v3')
             AND p_schema_version = 2 AND p_max_output_tokens = 512)
            OR (p_prompt_version IN ('gender-triage-microbatch-v1', 'gender-triage-microbatch-v2')
                AND p_schema_version = 3 AND p_max_output_tokens = 1024)) THEN
        v_input_ceiling := 4096 + p_media_count * 2048;
    ELSIF p_stage = 'genderResolution'
       AND p_model_name = 'gemini-3-flash-preview'
       AND p_thinking_level = 'LOW' AND p_media_resolution = 'MEDIUM'
       AND p_media_count BETWEEN 0 AND 5
       AND p_prompt_version = 'gender-resolution-v1' AND p_schema_version = 1
       AND p_max_output_tokens = 512 THEN
        v_input_ceiling := 8192 + p_media_count * 2048;
    ELSIF p_stage = 'featureAnalysis'
       AND p_model_name = 'gemini-3.1-flash-lite'
       AND p_thinking_level = 'MEDIUM' AND p_media_resolution = 'MEDIUM'
       AND p_media_count BETWEEN 0 AND 11
       AND p_prompt_version IN ('feature-analysis-v3', 'feature-analysis-v4', 'feature-analysis-v5')
       AND p_schema_version = 3 AND p_max_output_tokens = 2048 THEN
        v_input_ceiling := 8192 + p_media_count * 2048;
    ELSIF p_stage = 'privateAccountName'
       AND p_model_name = 'gemini-3.1-flash-lite'
       AND p_thinking_level = 'MINIMAL' AND p_media_resolution = 'LOW'
       AND p_media_count = 0 AND p_prompt_version = 'private-account-name-v1'
       AND p_schema_version = 1 AND p_max_output_tokens = 8192 THEN
        v_input_ceiling := 8192;
    ELSIF p_stage = 'partnerSafety'
       AND p_model_name = 'gemini-3.1-flash-lite'
       AND p_thinking_level = 'MEDIUM' AND p_media_resolution = 'LOW'
       AND p_media_count BETWEEN 0 AND 1 AND p_prompt_version = 'partner-safety-v2'
       AND p_schema_version = 2 AND p_max_output_tokens = 768 THEN
        v_input_ceiling := 4096 + p_media_count * 2048;
    ELSIF p_stage = 'highRiskNarrative'
       AND p_model_name = 'gemini-3-flash-preview'
       AND p_thinking_level = 'HIGH' AND p_media_resolution = 'MEDIUM'
       AND p_media_count BETWEEN 0 AND 11
       AND p_prompt_version IN ('high-risk-narrative-v2', 'high-risk-narrative-v3')
       AND p_schema_version = 2 AND p_max_output_tokens = 4096 THEN
        v_input_ceiling := 8192 + p_media_count * 2048;
    ELSE
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    RETURN public.analysis_revenue_ai_cost_usd_v1(
        p_model_name, p_location, v_input_ceiling, p_max_output_tokens, 0
    );
END;
$$;


--
-- Name: analysis_revenue_ai_cost_operation_mapping_legacy_v1(uuid, text, text, text, text, smallint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_revenue_ai_cost_operation_mapping_legacy_v1(p_request_id uuid, p_job_key text, p_job_input_hash text, p_plan_id text, p_operation_key text, p_source_attempt smallint, p_stage text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_manifest public.analysis_v2_gender_routing_manifests%ROWTYPE;
    v_manifest_count INTEGER := 0;
BEGIN
    IF p_plan_id NOT IN ('basic', 'standard') OR p_source_attempt NOT BETWEEN 1 AND 4
       OR p_operation_key IS NULL OR p_stage IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF p_stage = 'genderTriage'
       AND p_operation_key ~ '^gender-triage:[a-f0-9]{64}$'
       AND p_job_key = 'track:relationships:collect' THEN
        FOR v_manifest IN
            SELECT * FROM public.analysis_v2_gender_routing_manifests
             WHERE request_id = p_request_id
               AND relationship_job_key = p_job_key
               AND relationship_job_input_hash = p_job_input_hash
               AND policy_version = 'gender-routing-v1'
               AND plan_id = p_plan_id
               AND status IN ('building', 'complete')
             FOR UPDATE
        LOOP
            v_manifest_count := v_manifest_count + 1;
            IF v_manifest_count > 1 THEN
                RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
            END IF;
        END LOOP;
        IF v_manifest_count <> 1 OR v_manifest.request_id IS NULL THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'operation_kind', CASE WHEN p_source_attempt = 1
                THEN 'stage_one_routing' ELSE 'stage_one_routing_retry' END,
            'selected_manifest_scope_hash', v_manifest.canonical_input_hmac
        );
    ELSIF p_stage = 'genderTriage'
       AND p_operation_key ~ '^gender-triage:[a-f0-9]{64}$'
       AND p_job_key ~ '^track:profile-ai:batch:[0-9]+$' THEN
        RETURN pg_catalog.jsonb_build_object('operation_kind', 'detail_profile');
    ELSIF p_stage = 'genderResolution'
       AND p_operation_key ~ '^gender-resolution:[a-f0-9]{64}$'
       AND p_job_key ~ '^track:profile-ai:batch:[0-9]+$' THEN
        RETURN pg_catalog.jsonb_build_object('operation_kind', 'resolver');
    ELSIF p_stage = 'featureAnalysis'
       AND p_operation_key ~ '^feature-analysis:[a-f0-9]{64}$'
       AND p_job_key ~ '^track:profile-ai:batch:[0-9]+$' THEN
        RETURN pg_catalog.jsonb_build_object('operation_kind', 'detail_media');
    ELSIF p_stage = 'privateAccountName'
       AND p_operation_key ~ '^private-account-name:[a-f0-9]{64}$'
       AND p_job_key ~ '^track:private-names:batch:[0-9]+$' THEN
        RETURN pg_catalog.jsonb_build_object('operation_kind', 'detail_profile');
    ELSIF p_stage = 'partnerSafety'
       AND p_operation_key ~ '^partner-safety:[a-f0-9]{64}$'
       AND p_job_key = 'track:partner-safety:batch:0' THEN
        RETURN pg_catalog.jsonb_build_object('operation_kind', 'detail_interaction');
    ELSIF p_stage = 'highRiskNarrative'
       AND p_operation_key ~ '^high-risk-narrative:[a-f0-9]{64}$'
       AND p_job_key = 'track:narratives:batch:0' THEN
        RETURN pg_catalog.jsonb_build_object('operation_kind', 'detail_interaction');
    END IF;
    RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
END;
$_$;


--
-- Name: analysis_revenue_ai_cost_operation_mapping_v1(uuid, text, text, text, text, smallint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_revenue_ai_cost_operation_mapping_v1(p_request_id uuid, p_job_key text, p_job_input_hash text, p_plan_id text, p_operation_key text, p_source_attempt smallint, p_stage text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_lineage public.analysis_revenue_ai_routing_attempt_lineages%ROWTYPE;
    v_manifest public.analysis_v2_gender_routing_manifests%ROWTYPE;
    v_manifest_count INTEGER := 0;
    v_source_hash TEXT;
BEGIN
    -- The strict opportunistic resolver is intentionally owned by
    -- primary_join. It is admitted by the durable request-scoped pass before
    -- this normal AI audit/cost lifecycle can reserve a Gemini attempt.
    IF p_stage = 'genderResolution'
       AND p_job_key = 'coordinator:join:primary-evidence'
       AND p_operation_key ~ '^gender-resolution:[a-f0-9]{64}$' THEN
        IF p_plan_id NOT IN ('basic', 'standard')
           OR p_source_attempt NOT BETWEEN 1 AND 4 THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
        END IF;
        v_source_hash := pg_catalog.encode(
            extensions.digest(pg_catalog.convert_to(p_operation_key, 'UTF8'), 'sha256'),
            'hex'
        );
        IF NOT EXISTS (
            SELECT 1
            FROM public.analysis_revenue_resolver_passes AS pass
            JOIN public.analysis_revenue_resolver_capacity_reservations AS reservation
              ON reservation.request_id = pass.request_id
             AND reservation.job_key = pass.job_key
             AND reservation.job_input_hash = pass.job_input_hash
             AND reservation.operation_key_hash = v_source_hash
             AND reservation.disposition = 'accepted'
            WHERE pass.request_id = p_request_id
              AND pass.job_key = p_job_key
              AND pass.job_input_hash = p_job_input_hash
              AND pass.plan_id = p_plan_id
        ) THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
        END IF;
        RETURN pg_catalog.jsonb_build_object('operation_kind', 'resolver');
    END IF;
    IF p_stage = 'genderTriage'
       AND p_job_key = 'track:relationships:collect'
       AND p_operation_key ~ '^gender-triage:[a-f0-9]{64}$' THEN
        v_source_hash := pg_catalog.encode(
            extensions.digest(pg_catalog.convert_to(p_operation_key, 'UTF8'), 'sha256'),
            'hex'
        );
        SELECT * INTO v_lineage
          FROM public.analysis_revenue_ai_routing_attempt_lineages
         WHERE request_id = p_request_id
           AND job_key = p_job_key
           AND source_operation_key_hash = v_source_hash
         FOR UPDATE;
        IF v_lineage.request_id IS NOT NULL THEN
            IF v_lineage.job_input_hash IS DISTINCT FROM p_job_input_hash
               OR v_lineage.routing_attempt NOT IN (1, 2)
               OR p_source_attempt NOT BETWEEN 1 AND 4
               OR p_plan_id NOT IN ('basic', 'standard') THEN
                RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
            END IF;
            FOR v_manifest IN
                SELECT * FROM public.analysis_v2_gender_routing_manifests
                 WHERE request_id = p_request_id
                   AND relationship_job_key = p_job_key
                   AND relationship_job_input_hash = p_job_input_hash
                   AND policy_version = 'gender-routing-v1'
                   AND plan_id = p_plan_id
                   AND status IN ('building', 'complete')
                 FOR UPDATE
            LOOP
                v_manifest_count := v_manifest_count + 1;
                IF v_manifest_count > 1 THEN
                    RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
                END IF;
            END LOOP;
            IF v_manifest_count <> 1 OR v_manifest.request_id IS NULL THEN
                RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
            END IF;
            RETURN pg_catalog.jsonb_build_object(
                'operation_kind', CASE WHEN v_lineage.routing_attempt = 1
                    THEN 'stage_one_routing' ELSE 'stage_one_routing_retry' END,
                'selected_manifest_scope_hash', v_manifest.canonical_input_hmac
            );
        END IF;
    END IF;
    RETURN public.analysis_revenue_ai_cost_operation_mapping_legacy_v1(
        p_request_id, p_job_key, p_job_input_hash, p_plan_id,
        p_operation_key, p_source_attempt, p_stage
    );
END;
$_$;


--
-- Name: analysis_revenue_ai_cost_owner_hash_v1(uuid, text, text, smallint, uuid, text, text, text, text, smallint, text, text, smallint, integer, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_revenue_ai_cost_owner_hash_v1(p_request_id uuid, p_job_key text, p_operation_key text, p_attempt smallint, p_reservation_token uuid, p_model_name text, p_location text, p_stage text, p_thinking_level text, p_media_count smallint, p_media_resolution text, p_prompt_version text, p_schema_version smallint, p_max_output_tokens integer, p_retry_count smallint) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
        'revenue-cost/live-ai-owner/v1:' || p_request_id::TEXT || ':' || p_job_key || ':'
        || p_operation_key || ':' || p_attempt::TEXT || ':' || p_reservation_token::TEXT || ':'
        || p_model_name || ':' || p_location || ':' || p_stage || ':'
        || COALESCE(p_thinking_level, '') || ':' || p_media_count::TEXT || ':'
        || COALESCE(p_media_resolution, '') || ':' || p_prompt_version || ':'
        || p_schema_version::TEXT || ':' || p_max_output_tokens::TEXT || ':' || p_retry_count::TEXT,
        'UTF8'
    ), 'sha256'), 'hex')
$$;


--
-- Name: analysis_revenue_ai_cost_refresh_review_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_revenue_ai_cost_refresh_review_v1(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_unsettled INTEGER;
    v_denied INTEGER;
    v_ambiguous INTEGER;
    v_skipped_start INTEGER;
BEGIN
    SELECT * INTO v_parent FROM public.analysis_revenue_run_ledgers
      WHERE request_id = p_request_id FOR UPDATE;
    SELECT
        pg_catalog.count(*) FILTER (WHERE status NOT IN ('settled', 'released'))::INTEGER,
        pg_catalog.count(*) FILTER (WHERE status = 'denied')::INTEGER,
        pg_catalog.count(*) FILTER (WHERE status = 'ambiguous')::INTEGER,
        pg_catalog.count(*) FILTER (WHERE lifecycle_anomaly = 'skipped_start')::INTEGER
      INTO v_unsettled, v_denied, v_ambiguous, v_skipped_start
      FROM public.analysis_revenue_cost_operations WHERE request_id = p_request_id;
    IF v_parent.manual_review_reason IN ('cost_overrun','cost_denied') THEN
        RETURN;
    ELSIF v_denied > 0 THEN
        UPDATE public.analysis_revenue_run_ledgers
           SET status = 'manual_review', manual_review_reason = 'cost_denied'
         WHERE request_id = p_request_id;
    ELSIF v_ambiguous > 0 THEN
        UPDATE public.analysis_revenue_run_ledgers
           SET status = 'manual_review', manual_review_reason = 'ambiguous_external_call'
         WHERE request_id = p_request_id;
    ELSIF v_skipped_start > 0 THEN
        UPDATE public.analysis_revenue_run_ledgers
           SET status = 'manual_review', manual_review_reason = 'routing_failure'
         WHERE request_id = p_request_id;
    ELSIF v_unsettled = 0
       AND v_parent.status = 'manual_review'
       AND v_parent.manual_review_reason IN ('ambiguous_external_call', 'routing_failure') THEN
        UPDATE public.analysis_revenue_run_ledgers
           SET status = 'running', manual_review_reason = NULL
         WHERE request_id = p_request_id;
    END IF;
END;
$$;


--
-- Name: analysis_revenue_ai_cost_usd_v1(text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_revenue_ai_cost_usd_v1(p_model_name text, p_location text, p_prompt_tokens integer, p_completion_tokens integer, p_thinking_tokens integer) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
DECLARE
    v_input_rate NUMERIC;
    v_output_rate NUMERIC;
BEGIN
    IF p_prompt_tokens < 0 OR p_completion_tokens < 0 OR p_thinking_tokens < 0
       OR p_prompt_tokens > 100000000 OR p_completion_tokens > 100000000
       OR p_thinking_tokens > 100000000 THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF p_model_name IN ('gemini-3.1-flash-lite', 'gemini-3.1-flash-lite-preview')
       OR p_model_name ~ '^gemini-3\\.1-flash-lite-[0-9]{3}$' THEN
        IF pg_catalog.lower(p_location) = 'global' THEN
            v_input_rate := 0.25::NUMERIC;
            v_output_rate := 1.5::NUMERIC;
        ELSE
            v_input_rate := 0.275::NUMERIC;
            v_output_rate := 1.65::NUMERIC;
        END IF;
    ELSIF p_model_name = 'gemini-3-flash-preview' THEN
        v_input_rate := 0.5::NUMERIC;
        v_output_rate := 3::NUMERIC;
    ELSE
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    RETURN pg_catalog.round(
        (p_prompt_tokens::NUMERIC * v_input_rate
         + (p_completion_tokens::NUMERIC + p_thinking_tokens::NUMERIC) * v_output_rate)
        / 1000000::NUMERIC,
        12
    );
END;
$_$;


--
-- Name: analysis_revenue_ai_set_routing_attempt_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_revenue_ai_set_routing_attempt_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_routing_attempt SMALLINT;
BEGIN
    IF NEW.owner_kind <> 'ai_attempt' THEN
        IF NEW.routing_attempt IS NOT NULL THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
        END IF;
        RETURN NEW;
    END IF;

    SELECT routing_attempt INTO v_routing_attempt
      FROM public.analysis_revenue_ai_routing_attempt_lineages
     WHERE request_id = NEW.request_id
       AND job_key = NEW.source_job_key
       AND source_operation_key_hash = NEW.source_operation_key_hash;
    IF FOUND THEN
        IF NEW.routing_attempt IS NOT NULL AND NEW.routing_attempt <> v_routing_attempt THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
        END IF;
        NEW.routing_attempt := v_routing_attempt;
    ELSIF NEW.routing_attempt IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: analysis_revenue_cost_ceil_krw(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_revenue_cost_ceil_krw(p_usd numeric) RETURNS integer
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.ceil(p_usd * 1450)::INTEGER
$$;


--
-- Name: analysis_revenue_valid_fresh_provider_operation_key_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_revenue_valid_fresh_provider_operation_key_v1(p_operation_key text) RETURNS boolean
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
    SELECT p_operation_key ~ '^(target-profile|profile-fallback|relationship-followers|relationship-following|target-likers|target-comments|candidate-likers):[a-f0-9]{64}$'
