--
-- Name: analysis_v2_admit_betatest_plan_ungated_20260802(uuid, uuid, uuid, integer, text, jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_admit_betatest_plan_ungated_20260802(p_preflight_id uuid, p_user_id uuid, p_admission_token uuid, p_admission_generation integer, p_selected_plan_id text, p_operation_slot_map jsonb, p_operation_budget_map jsonb, p_max_snapshot_age_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE;
    v_initial_job_key CONSTANT TEXT := 'coordinator:bootstrap';
    v_preflight public.analysis_preflights%ROWTYPE;
    v_grant public.analysis_beta_access_grants%ROWTYPE;
    v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
    v_target_reservation public.analysis_beta_pool_reservations%ROWTYPE;
    v_request_id UUID;
    v_scope_snapshot JSONB;
    v_selected_card JSONB;
    v_input_hash TEXT;
    v_active_request_id UUID;
    v_activation JSONB;
    v_replay JSONB;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_admission_token IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_selected_plan_id IS NULL
       OR p_selected_plan_id NOT IN ('basic', 'standard', 'plus')
       OR p_max_snapshot_age_seconds IS NULL
       OR p_max_snapshot_age_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    -- FOR UPDATE is the explicit one-user start serializer. Recovery takes a
    -- KEY SHARE lock first and therefore cannot invert later row-lock order.
    PERFORM users.id
    FROM public.users AS users
    WHERE users.id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.user_id IS DISTINCT FROM p_user_id
       OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'betatest'
       OR v_preflight.access_mode IS DISTINCT FROM 'production'
       OR v_preflight.admission_token IS DISTINCT FROM p_admission_token
       OR v_preflight.admission_generation IS DISTINCT FROM p_admission_generation
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM p_selected_plan_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    SELECT allocation.* INTO v_allocation
    FROM public.analysis_beta_pool_allocations AS allocation
    WHERE allocation.preflight_id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_allocation.user_id IS DISTINCT FROM p_user_id
       OR v_allocation.policy_version IS DISTINCT FROM 'betatest-free-pool-v1' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    -- A concurrent winner is replayed from stored identity. Caller-proposed
    -- slot/budget maps are advisory only once the allocation is immutable.
    IF v_allocation.lifecycle_state IN ('active', 'settled') THEN
        RETURN public.analysis_v2_betatest_plan_replay_internal(
            p_preflight_id,
            p_user_id,
            p_admission_token,
            p_admission_generation,
            p_selected_plan_id
        );
    END IF;

    IF v_allocation.lifecycle_state IS DISTINCT FROM 'preflight_held'
       OR NOT public.analysis_beta_valid_operation_slot_map(p_operation_slot_map)
       OR NOT public.analysis_beta_valid_operation_budget_map(p_operation_budget_map)
       OR p_operation_budget_map IS DISTINCT FROM
            public.analysis_beta_plan_operation_budget_map(p_selected_plan_id) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_ALLOCATION_INVALID', ERRCODE = 'P0001';
    END IF;

    -- Preserve the established activation order: target hold before grant.
    SELECT reservation.* INTO v_target_reservation
    FROM public.analysis_beta_pool_reservations AS reservation
    WHERE reservation.allocation_id = v_allocation.id
      AND reservation.operation_family = 'target-profile'
    FOR UPDATE;
    IF NOT FOUND
       OR v_target_reservation.credential_slot
            IS DISTINCT FROM p_operation_slot_map->>'target-profile'
       OR v_target_reservation.reserved_usd IS DISTINCT FROM 0.005200000000
       OR v_target_reservation.lifecycle_state IS DISTINCT FROM 'preflight_held' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
    END IF;

    SELECT grant_row.* INTO v_grant
    FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id = p_user_id
    FOR UPDATE;

    -- Load-bearing TOCTOU fence: database time is sampled only after every
    -- authoritative first-admission identity/grant/hold row has been locked.
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND
       OR v_grant.enabled IS DISTINCT FROM TRUE
       OR (
            v_grant.expires_at IS NOT NULL
            AND (
                NOT pg_catalog.isfinite(v_grant.expires_at)
                OR v_grant.expires_at <= v_now
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_ACCESS_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;

    IF v_preflight.status IS DISTINCT FROM 'ready'
       OR v_preflight.expires_at <= v_now
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.admission_status IS DISTINCT FROM 'ready'
       OR v_preflight.admission_refreshed_at IS NULL
       OR v_preflight.admission_refreshed_at < v_now - INTERVAL '2 minutes'
       OR v_preflight.admission_refreshed_at > v_now + INTERVAL '30 seconds'
       OR v_preflight.target_followers_count IS NULL
       OR v_preflight.target_following_count IS NULL
       OR v_preflight.capacity_required_plan_id IS NULL
       OR v_preflight.required_plan_id IS NULL
       OR v_preflight.plan_cards_snapshot IS NULL
       OR NOT public.analysis_v2_valid_plan_cards_snapshot(
            v_preflight.plan_cards_snapshot
       )
       OR NOT public.analysis_v2_valid_launch_snapshot(
            v_preflight.launch_status_snapshot
       )
       OR NOT public.analysis_v2_valid_pricing_snapshot(
            v_preflight.pricing_snapshot
       )
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(
            v_preflight.policy_versions_snapshot
       )
       OR v_allocation.expires_at <= v_now
       OR v_allocation.request_id IS NOT NULL
       OR v_allocation.operation_slot_map IS NOT NULL
       OR v_allocation.operation_budget_map IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    v_selected_card := v_preflight.plan_cards_snapshot->p_selected_plan_id;
    IF v_selected_card IS NULL
       OR v_selected_card->>'launchStatus' IS DISTINCT FROM 'production'
       OR v_selected_card->>'selectionState'
            NOT IN ('required', 'available_upgrade')
       OR v_preflight.target_followers_count >
            (v_selected_card->'relationshipCapacity'->>'followers')::INTEGER
       OR v_preflight.target_following_count >
            (v_selected_card->'relationshipCapacity'->>'following')::INTEGER THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    SELECT request.id INTO v_active_request_id
    FROM public.analysis_requests AS request
    WHERE request.user_id = p_user_id
      AND request.status IN ('pending', 'processing')
    ORDER BY request.id
    LIMIT 1
    FOR UPDATE;
    IF FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    v_scope_snapshot := pg_catalog.jsonb_build_object(
        'relationshipCapacity', v_selected_card->'relationshipCapacity',
        'detailedMutualLimit', v_selected_card->'detailedMutualLimit'
    );
    IF NOT public.analysis_v2_valid_scope_snapshot(v_scope_snapshot) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    v_request_id := extensions.gen_random_uuid();
    INSERT INTO public.analysis_requests (
        id,
        user_id,
        target_instagram_id,
        target_gender,
        status,
        progress,
        progress_step,
        current_step,
        step_data,
        gender_stats,
        plan_type,
        background_processing,
        idempotency_key,
        pipeline_version,
        preflight_id,
        excluded_instagram_id,
        exclusion_decision_snapshot,
        plan_access_mode_snapshot,
        capacity_required_plan_id_snapshot,
        required_plan_id_snapshot,
        selected_plan_id_snapshot,
        plan_launch_status_snapshot,
        plan_cards_snapshot,
        pricing_version_snapshot,
        pricing_snapshot,
        analysis_scope_snapshot,
        policy_versions_snapshot,
        analysis_entry_channel
    ) VALUES (
        v_request_id,
        p_user_id,
        v_preflight.target_instagram_id,
        'male',
        'pending',
        0,
        '분석 대기 중...',
        'pending',
        '{}'::JSONB,
        '{}'::JSONB,
        p_selected_plan_id,
        FALSE,
        'betatest:' || pg_catalog.lower(v_preflight.id::TEXT),
        'v2',
        v_preflight.id,
        v_preflight.excluded_instagram_id,
        v_preflight.exclusion_decision,
        'production',
        v_preflight.capacity_required_plan_id,
        v_preflight.required_plan_id,
        p_selected_plan_id,
        v_preflight.launch_status_snapshot,
        v_preflight.plan_cards_snapshot,
        v_preflight.pricing_version,
        v_preflight.pricing_snapshot,
        v_scope_snapshot,
        v_preflight.policy_versions_snapshot,
        'standard'
    );

    UPDATE public.analysis_preflights AS preflight
    SET status = 'consumed',
        consumed_at = v_now,
        consumed_request_id = v_request_id,
        updated_at = v_now
    WHERE preflight.id = v_preflight.id;

    v_input_hash := pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'analysis-v2-job-input-v1' || pg_catalog.chr(10)
                || pg_catalog.lower(v_request_id::TEXT)
                || pg_catalog.chr(10) || v_initial_job_key,
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );
    INSERT INTO public.analysis_pipeline_jobs (
        request_id,
        job_key,
        track,
        kind,
        batch,
        input_hash,
        required_job_keys
    ) VALUES (
        v_request_id,
        v_initial_job_key,
        'coordinator',
        'bootstrap',
        NULL,
        v_input_hash,
        '{}'::TEXT[]
    );

    -- The hardened primitive locks all six snapshots, repeats freshness and
    -- headroom, activates exactly eight reservations, and binds policy.
    v_activation := public.activate_analysis_beta_apify_request_credit(
        p_preflight_id,
        v_request_id,
        p_user_id,
        p_selected_plan_id,
        p_operation_slot_map,
        p_operation_budget_map,
        p_max_snapshot_age_seconds
    );
    IF v_activation->>'lifecycleState' IS DISTINCT FROM 'active'
       OR (v_activation->>'requestId')::UUID IS DISTINCT FROM v_request_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
    END IF;

    -- Activation may wait behind any of the six authoritative snapshot rows.
    -- Re-sample database time after that barrier so staged request/job/policy
    -- work rolls back when admission freshness expires while waiting.
    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.admission_refreshed_at IS NULL
       OR v_preflight.admission_refreshed_at < v_now - INTERVAL '2 minutes'
       OR v_preflight.admission_refreshed_at > v_now + INTERVAL '30 seconds' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    v_replay := public.analysis_v2_betatest_plan_replay_internal(
        p_preflight_id,
        p_user_id,
        p_admission_token,
        p_admission_generation,
        p_selected_plan_id
    );
    IF v_replay IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
    END IF;
    RETURN pg_catalog.jsonb_set(v_replay, '{replayed}', 'false'::JSONB, FALSE);
END;
$$;


--
-- Name: analysis_v2_ai_attempt_cost_provenance_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_ai_attempt_cost_provenance_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF OLD.pricing_version IS NOT NULL
           AND NEW.pricing_version IS DISTINCT FROM OLD.pricing_version THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_PRICING_VERSION_IMMUTABLE',
                ERRCODE = 'P0001';
        END IF;
        IF OLD.canonical_model_name IS NOT NULL
           AND (
               NEW.model_name IS DISTINCT FROM OLD.model_name
               OR NEW.location IS DISTINCT FROM OLD.location
               OR NEW.canonical_model_name IS DISTINCT FROM OLD.canonical_model_name
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_MODEL_PROVENANCE_IMMUTABLE',
                ERRCODE = 'P0001';
        END IF;
        IF OLD.cache_read_tokens IS NOT NULL
           AND (
               NEW.cache_read_tokens IS DISTINCT FROM OLD.cache_read_tokens
               OR NEW.usage_metadata_status IS DISTINCT FROM OLD.usage_metadata_status
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_CACHE_PROVENANCE_IMMUTABLE',
                ERRCODE = 'P0001';
        END IF;
        IF OLD.metered_estimated_cost_usd IS NOT NULL
           AND (
               NEW.metered_estimated_cost_usd IS DISTINCT FROM OLD.metered_estimated_cost_usd
               OR NEW.estimated_cost_usd IS DISTINCT FROM OLD.estimated_cost_usd
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_METERED_COST_IMMUTABLE',
                ERRCODE = 'P0001';
        END IF;
        NEW.pricing_version := COALESCE(OLD.pricing_version, NEW.pricing_version,
            'vertex-ai-cost-v1');
    ELSE
        NEW.pricing_version := COALESCE(NEW.pricing_version, 'vertex-ai-cost-v1');
    END IF;

    -- Only the current catalog is accepted. A future catalog requires a forward migration so
    -- every estimate remains tied to the exact immutable catalog used at write time.
    IF NEW.pricing_version <> 'vertex-ai-cost-v1' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_PRICING_VERSION_UNSUPPORTED',
            ERRCODE = 'P0001';
    END IF;
    NEW.canonical_model_name := public.analysis_v2_canonical_gemini_model(NEW.model_name);

    -- The V2 transport assembles only inline `contents` and never sends a cachedContent
    -- reference. For a complete response that proves cached-content input was zero; provider
    -- omission is not treated as proof on any transport that can send cached content.
    IF NEW.usage_metadata_status = 'complete' THEN
        NEW.cache_read_tokens := COALESCE(NEW.cache_read_tokens, 0);
    ELSE
        NEW.cache_read_tokens := NULL;
    END IF;
    NEW.metered_estimated_cost_usd := NEW.estimated_cost_usd;
    RETURN NEW;
END;
$$;


--
-- Name: analysis_v2_valid_ai_operation_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_ai_operation_key(p_operation_key text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
    SELECT pg_catalog.char_length(p_operation_key) BETWEEN 78 AND 86
       AND p_operation_key ~ '^(gender-triage|gender-resolution|feature-analysis|high-risk-narrative|private-account-name|partner-safety):[0-9a-f]{64}$';
$_$;


--
-- Name: analysis_v2_ai_attempts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_ai_attempts (
    request_id uuid NOT NULL,
    job_key character varying(160) NOT NULL,
    job_claim_token uuid NOT NULL,
    operation_key character varying(86) NOT NULL,
    attempt smallint NOT NULL,
    reservation_token uuid NOT NULL,
    status text DEFAULT 'reserved'::text NOT NULL,
    model_name character varying(100) NOT NULL,
    location character varying(63) NOT NULL,
    stage text NOT NULL,
    thinking_level text,
    media_count smallint NOT NULL,
    media_resolution text,
    prompt_version character varying(64) NOT NULL,
    schema_version smallint NOT NULL,
    max_output_tokens integer NOT NULL,
    retry_count smallint NOT NULL,
    usage_metadata_status text,
    usage_complete boolean,
    prompt_tokens integer,
    completion_tokens integer,
    total_tokens integer,
    thinking_tokens integer,
    latency_ms integer,
    estimated_cost_usd numeric(15,12),
    finish_reason character varying(64),
    terminal_payload_hash character varying(64),
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    terminalized_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    pricing_version character varying(64),
    canonical_model_name character varying(100),
    cache_read_tokens integer,
    metered_estimated_cost_usd numeric(15,12),
    CONSTRAINT analysis_v2_ai_attempt_cache_read_tokens_check CHECK (((cache_read_tokens IS NULL) OR ((cache_read_tokens >= 0) AND (cache_read_tokens <= 100000000)))),
    CONSTRAINT analysis_v2_ai_attempt_canonical_model_check CHECK (((canonical_model_name IS NULL) OR ((canonical_model_name)::text ~ '^[a-z0-9][a-z0-9._-]{0,99}$'::text))),
    CONSTRAINT analysis_v2_ai_attempt_cost_check CHECK (((estimated_cost_usd IS NULL) OR ((estimated_cost_usd >= (0)::numeric) AND (estimated_cost_usd <= 999.999999999999)))),
    CONSTRAINT analysis_v2_ai_attempt_generation_failure_check CHECK (((status <> ALL (ARRAY['rate_limited'::text, 'ambiguous'::text])) OR ((usage_metadata_status = 'missing'::text) AND (NOT usage_complete) AND (prompt_tokens IS NULL) AND (completion_tokens IS NULL) AND (total_tokens IS NULL) AND (thinking_tokens IS NULL) AND (estimated_cost_usd IS NULL) AND (finish_reason IS NULL)))),
    CONSTRAINT analysis_v2_ai_attempt_job_key_check CHECK ((((char_length((job_key)::text) >= 1) AND (char_length((job_key)::text) <= 160)) AND ((job_key)::text ~ '^[a-z0-9][a-z0-9:._-]{0,159}$'::text))),
    CONSTRAINT analysis_v2_ai_attempt_location_check CHECK (((location)::text ~ '^[a-z][a-z0-9-]{0,62}$'::text)),
    CONSTRAINT analysis_v2_ai_attempt_media_check CHECK ((((media_count >= 0) AND (media_count <= 11)) AND ((media_resolution IS NULL) OR (media_resolution = ANY (ARRAY['LOW'::text, 'MEDIUM'::text, 'HIGH'::text]))))),
    CONSTRAINT analysis_v2_ai_attempt_metered_estimated_cost_check CHECK (((metered_estimated_cost_usd IS NULL) OR ((metered_estimated_cost_usd >= (0)::numeric) AND (metered_estimated_cost_usd <= 999.999999999999)))),
    CONSTRAINT analysis_v2_ai_attempt_model_check CHECK (((model_name)::text ~ '^[a-z0-9][a-z0-9._-]{0,99}$'::text)),
    CONSTRAINT analysis_v2_ai_attempt_number_check CHECK (((attempt >= 1) AND (attempt <= 4))),
    CONSTRAINT analysis_v2_ai_attempt_operation_key_check CHECK (public.analysis_v2_valid_ai_operation_key((operation_key)::text)),
    CONSTRAINT analysis_v2_ai_attempt_pricing_version_check CHECK (((pricing_version IS NULL) OR ((pricing_version)::text ~ '^[A-Za-z0-9._:-]{1,64}$'::text))),
    CONSTRAINT analysis_v2_ai_attempt_prompt_check CHECK ((((char_length((prompt_version)::text) >= 1) AND (char_length((prompt_version)::text) <= 64)) AND ((prompt_version)::text ~ '^[A-Za-z0-9._:-]+$'::text) AND ((schema_version >= 1) AND (schema_version <= 9999)) AND ((max_output_tokens >= 1) AND (max_output_tokens <= 65536)) AND (retry_count = (attempt - 1)))),
    CONSTRAINT analysis_v2_ai_attempt_stage_check CHECK ((stage = ANY (ARRAY['genderTriage'::text, 'genderResolution'::text, 'featureAnalysis'::text, 'highRiskNarrative'::text, 'privateAccountName'::text, 'partnerSafety'::text]))),
    CONSTRAINT analysis_v2_ai_attempt_status_check CHECK ((status = ANY (ARRAY['reserved'::text, 'success'::text, 'rate_limited'::text, 'ambiguous'::text, 'rejected'::text, 'response_rejected'::text, 'cutoff'::text]))),
    CONSTRAINT analysis_v2_ai_attempt_terminal_shape_check CHECK ((((status = 'reserved'::text) AND (latency_ms IS NULL) AND (finish_reason IS NULL) AND (terminal_payload_hash IS NULL) AND (terminalized_at IS NULL)) OR ((status <> 'reserved'::text) AND (usage_metadata_status IS NOT NULL) AND (usage_complete IS NOT NULL) AND ((latency_ms >= 0) AND (latency_ms <= 3600000)) AND ((terminal_payload_hash)::text ~ '^[0-9a-f]{64}$'::text) AND (terminalized_at IS NOT NULL)))),
    CONSTRAINT analysis_v2_ai_attempt_thinking_check CHECK (((thinking_level IS NULL) OR (thinking_level = ANY (ARRAY['MINIMAL'::text, 'LOW'::text, 'MEDIUM'::text, 'HIGH'::text])))),
    CONSTRAINT analysis_v2_ai_attempt_time_check CHECK (((updated_at >= created_at) AND ((terminalized_at IS NULL) OR (terminalized_at >= created_at)))),
    CONSTRAINT analysis_v2_ai_attempt_usage_check CHECK ((((usage_metadata_status = 'complete'::text) AND usage_complete AND ((prompt_tokens >= 0) AND (prompt_tokens <= 100000000)) AND ((completion_tokens >= 0) AND (completion_tokens <= 100000000)) AND ((total_tokens >= 0) AND (total_tokens <= 100000000)) AND ((thinking_tokens >= 0) AND (thinking_tokens <= 100000000)) AND (total_tokens = ((prompt_tokens + completion_tokens) + thinking_tokens))) OR ((usage_metadata_status = ANY (ARRAY['missing'::text, 'malformed'::text])) AND (NOT usage_complete) AND (prompt_tokens IS NULL) AND (completion_tokens IS NULL) AND (total_tokens IS NULL) AND (thinking_tokens IS NULL) AND (estimated_cost_usd IS NULL)) OR ((usage_metadata_status IS NULL) AND (usage_complete IS NULL) AND (prompt_tokens IS NULL) AND (completion_tokens IS NULL) AND (total_tokens IS NULL) AND (thinking_tokens IS NULL) AND (estimated_cost_usd IS NULL))))
);

ALTER TABLE ONLY public.analysis_v2_ai_attempts FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_ai_attempt_json(public.analysis_v2_ai_attempts); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_ai_attempt_json(p_attempt public.analysis_v2_ai_attempts) RETURNS jsonb
    LANGUAGE sql STABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'requestId', p_attempt.request_id,
        'jobKey', p_attempt.job_key,
        'operationKey', p_attempt.operation_key,
        'attempt', p_attempt.attempt,
        'reservationToken', p_attempt.reservation_token,
        'status', p_attempt.status,
        'modelName', p_attempt.model_name,
        'location', p_attempt.location,
        'stage', p_attempt.stage,
        'thinkingLevel', p_attempt.thinking_level,
        'mediaCount', p_attempt.media_count,
        'mediaResolution', p_attempt.media_resolution,
        'promptVersion', p_attempt.prompt_version,
        'schemaVersion', p_attempt.schema_version,
        'maxOutputTokens', p_attempt.max_output_tokens,
        'retryCount', p_attempt.retry_count,
        'usageMetadataStatus', p_attempt.usage_metadata_status,
        'usageComplete', p_attempt.usage_complete,
        'tokenUsage', CASE
            WHEN p_attempt.usage_metadata_status = 'complete' THEN
                pg_catalog.jsonb_build_object(
                    'promptTokens', p_attempt.prompt_tokens,
                    'completionTokens', p_attempt.completion_tokens,
                    'totalTokens', p_attempt.total_tokens,
                    'thinkingTokens', p_attempt.thinking_tokens
                )
            ELSE NULL
        END,
        'latencyMs', p_attempt.latency_ms,
        'estimatedCostUsd', p_attempt.estimated_cost_usd,
        'finishReason', p_attempt.finish_reason,
        'createdAt', p_attempt.created_at,
        'terminalizedAt', p_attempt.terminalized_at
    );
$$;


--
-- Name: analysis_v2_ai_canonical_json_text(jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_ai_canonical_json_text(p_value jsonb, p_depth integer DEFAULT 0) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
DECLARE
    v_result TEXT;
BEGIN
    IF p_depth NOT BETWEEN 0 AND 32
       OR pg_catalog.octet_length(p_value::TEXT) > 262144 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_CANONICAL_JSON_INVALID',
            ERRCODE = 'P0001';
    END IF;

    CASE pg_catalog.jsonb_typeof(p_value)
        WHEN 'object' THEN
            SELECT '{' || COALESCE(pg_catalog.string_agg(
                pg_catalog.to_jsonb(entry.key)::TEXT || ':'
                    || public.analysis_v2_ai_canonical_json_text(
                        entry.value,
                        p_depth + 1
                    ),
                ',' ORDER BY entry.key
            ), '') || '}'
            INTO v_result
            FROM pg_catalog.jsonb_each(p_value) AS entry(key, value);
        WHEN 'array' THEN
            SELECT '[' || COALESCE(pg_catalog.string_agg(
                public.analysis_v2_ai_canonical_json_text(
                    entry.value,
                    p_depth + 1
                ),
                ',' ORDER BY entry.ordinality
            ), '') || ']'
            INTO v_result
            FROM pg_catalog.jsonb_array_elements(p_value)
                WITH ORDINALITY AS entry(value, ordinality);
        ELSE
            v_result := p_value::TEXT;
    END CASE;
    RETURN v_result;
END;
$$;


--
-- Name: analysis_v2_ai_fallback_evidence_matches(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_ai_fallback_evidence_matches(p_request_id uuid, p_job_key text, p_operation_key text, p_stage text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.analysis_v2_ai_attempts AS rejected_attempt
        WHERE rejected_attempt.request_id = p_request_id
          AND rejected_attempt.job_key = p_job_key
          AND rejected_attempt.operation_key = p_operation_key
          AND rejected_attempt.stage = p_stage
          AND rejected_attempt.status = 'response_rejected'
    ) OR COALESCE((
        SELECT pg_catalog.count(*) = 4
           AND pg_catalog.count(DISTINCT exhausted_attempt.attempt) = 4
           AND pg_catalog.min(exhausted_attempt.attempt) = 1
           AND pg_catalog.max(exhausted_attempt.attempt) = 4
           AND pg_catalog.bool_and(
                exhausted_attempt.status = 'rate_limited'
                AND exhausted_attempt.terminalized_at IS NOT NULL
                AND exhausted_attempt.retry_count = exhausted_attempt.attempt - 1
           )
           AND pg_catalog.count(DISTINCT ROW(
                exhausted_attempt.model_name,
                exhausted_attempt.location,
                exhausted_attempt.thinking_level,
                exhausted_attempt.media_count,
                exhausted_attempt.media_resolution,
                exhausted_attempt.prompt_version,
                exhausted_attempt.schema_version,
                exhausted_attempt.max_output_tokens
           )) = 1
        FROM public.analysis_v2_ai_attempts AS exhausted_attempt
        WHERE exhausted_attempt.request_id = p_request_id
          AND exhausted_attempt.job_key = p_job_key
          AND exhausted_attempt.operation_key = p_operation_key
          AND exhausted_attempt.stage = p_stage
    ), FALSE);
$$;


--
-- Name: analysis_v2_ai_operation_matches_stage(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_ai_operation_matches_stage(p_operation_key text, p_stage text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT CASE p_stage
        WHEN 'genderTriage' THEN p_operation_key LIKE 'gender-triage:%'
        WHEN 'genderResolution' THEN p_operation_key LIKE 'gender-resolution:%'
        WHEN 'featureAnalysis' THEN p_operation_key LIKE 'feature-analysis:%'
        WHEN 'highRiskNarrative' THEN p_operation_key LIKE 'high-risk-narrative:%'
        WHEN 'privateAccountName' THEN p_operation_key LIKE 'private-account-name:%'
        WHEN 'partnerSafety' THEN p_operation_key LIKE 'partner-safety:%'
        ELSE FALSE
    END;
$$;


--
-- Name: analysis_v2_ai_result_cache_key(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_ai_result_cache_key(p_identity jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.encode(
        extensions.digest(
            pg_catalog.concat_ws(
                E'\n',
                'analysis-v2-ai-result-cache:v1',
                p_identity->>'stage',
                p_identity->>'model_name',
                COALESCE(p_identity->>'thinking_level', '-'),
                COALESCE(p_identity->>'media_resolution', '-'),
                p_identity->>'prompt_version',
                p_identity->>'schema_version',
                p_identity->>'max_output_tokens',
                p_identity->>'input_hash',
                p_identity->>'media_snapshot_hash'
            ),
            'sha256'
        ),
        'hex'
    );
$$;


--
-- Name: analysis_v2_valid_ai_result_envelope(jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_ai_result_envelope(p_result jsonb, p_canonical text, p_result_hash text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
BEGIN
    RETURN public.analysis_v2_valid_ai_result_json(p_result)
       AND pg_catalog.octet_length(pg_catalog.convert_to(p_canonical, 'UTF8'))
            BETWEEN 2 AND 262144
       AND p_canonical::JSONB = p_result
       AND p_result_hash ~ '^[0-9a-f]{64}$'
       AND p_result_hash = pg_catalog.encode(
            extensions.digest(
                pg_catalog.convert_to('analysis-v2-ai-result-content:v1', 'UTF8')
                    || pg_catalog.decode('00', 'hex')
                    || pg_catalog.convert_to(p_canonical, 'UTF8'),
                'sha256'
            ),
            'hex'
       );
EXCEPTION
    WHEN invalid_text_representation THEN
        RETURN FALSE;
END;
$_$;


--
-- Name: analysis_v2_ai_result_checkpoints; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_ai_result_checkpoints (
    request_id uuid NOT NULL,
    job_key character varying(160) NOT NULL,
    operation_key character varying(86) NOT NULL,
    cache_key character varying(64) NOT NULL,
    stage text NOT NULL,
    model_name character varying(100) NOT NULL,
    thinking_level text,
    media_resolution text,
    prompt_version character varying(64) NOT NULL,
    schema_version smallint NOT NULL,
    max_output_tokens integer NOT NULL,
    input_hash character varying(64) NOT NULL,
    media_snapshot_hash character varying(64) NOT NULL,
    cache_scope text NOT NULL,
    source text NOT NULL,
    attempt smallint,
    reservation_token uuid,
    result_json jsonb NOT NULL,
    result_canonical_json text NOT NULL,
    result_hash character varying(64) NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_v2_ai_result_checkpoint_hash_check CHECK ((((cache_key)::text ~ '^[0-9a-f]{64}$'::text) AND ((input_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((media_snapshot_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((result_hash)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT analysis_v2_ai_result_checkpoint_job_key_check CHECK ((((char_length((job_key)::text) >= 1) AND (char_length((job_key)::text) <= 160)) AND ((job_key)::text ~ '^[a-z0-9][a-z0-9:._-]{0,159}$'::text))),
    CONSTRAINT analysis_v2_ai_result_checkpoint_model_check CHECK (((model_name)::text ~ '^[a-z0-9][a-z0-9._-]{0,99}$'::text)),
    CONSTRAINT analysis_v2_ai_result_checkpoint_operation_key_check CHECK (public.analysis_v2_valid_ai_operation_key((operation_key)::text)),
    CONSTRAINT analysis_v2_ai_result_checkpoint_policy_check CHECK ((((thinking_level IS NULL) OR (thinking_level = ANY (ARRAY['MINIMAL'::text, 'LOW'::text, 'MEDIUM'::text, 'HIGH'::text]))) AND ((media_resolution IS NULL) OR (media_resolution = ANY (ARRAY['LOW'::text, 'MEDIUM'::text, 'HIGH'::text]))) AND ((char_length((prompt_version)::text) >= 1) AND (char_length((prompt_version)::text) <= 64)) AND ((prompt_version)::text ~ '^[A-Za-z0-9._:-]+$'::text) AND ((schema_version >= 1) AND (schema_version <= 9999)) AND ((max_output_tokens >= 1) AND (max_output_tokens <= 65536)) AND (cache_scope = ANY (ARRAY['request'::text, 'global_ttl'::text])) AND ((cache_scope = 'request'::text) OR (stage = ANY (ARRAY['genderTriage'::text, 'featureAnalysis'::text]))))),
    CONSTRAINT analysis_v2_ai_result_checkpoint_result_check CHECK (public.analysis_v2_valid_ai_result_envelope(result_json, result_canonical_json, (result_hash)::text)),
    CONSTRAINT analysis_v2_ai_result_checkpoint_source_check CHECK ((((source = 'generated'::text) AND ((attempt >= 1) AND (attempt <= 4)) AND (reservation_token IS NOT NULL)) OR ((source = 'global_cache'::text) AND (cache_scope = 'global_ttl'::text) AND (stage = ANY (ARRAY['genderTriage'::text, 'featureAnalysis'::text])) AND (attempt IS NULL) AND (reservation_token IS NULL)))),
    CONSTRAINT analysis_v2_ai_result_checkpoint_stage_check CHECK ((stage = ANY (ARRAY['genderTriage'::text, 'genderResolution'::text, 'featureAnalysis'::text, 'highRiskNarrative'::text, 'privateAccountName'::text, 'partnerSafety'::text])))
);

ALTER TABLE ONLY public.analysis_v2_ai_result_checkpoints FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_ai_result_checkpoint_json(public.analysis_v2_ai_result_checkpoints); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_ai_result_checkpoint_json(p_checkpoint public.analysis_v2_ai_result_checkpoints) RETURNS jsonb
    LANGUAGE sql STABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'requestId', p_checkpoint.request_id,
        'jobKey', p_checkpoint.job_key,
        'operationKey', p_checkpoint.operation_key,
        'cacheKey', p_checkpoint.cache_key,
        'stage', p_checkpoint.stage,
        'modelName', p_checkpoint.model_name,
        'thinkingLevel', p_checkpoint.thinking_level,
        'mediaResolution', p_checkpoint.media_resolution,
        'promptVersion', p_checkpoint.prompt_version,
        'schemaVersion', p_checkpoint.schema_version,
        'maxOutputTokens', p_checkpoint.max_output_tokens,
        'inputHash', p_checkpoint.input_hash,
        'mediaSnapshotHash', p_checkpoint.media_snapshot_hash,
        'cacheScope', p_checkpoint.cache_scope,
        'source', p_checkpoint.source,
        'attempt', p_checkpoint.attempt,
        'reservationToken', p_checkpoint.reservation_token,
        'result', p_checkpoint.result_json,
        'resultHash', p_checkpoint.result_hash,
        'chargeStatus', CASE
            WHEN p_checkpoint.source = 'global_cache' THEN 'cache_hit'
            WHEN ai_attempt.usage_metadata_status = 'complete' THEN 'generated_complete'
            ELSE 'generated_unknown'
        END,
        'usageMetadataStatus', ai_attempt.usage_metadata_status,
        'usageComplete', ai_attempt.usage_complete,
        'tokenUsage', CASE
            WHEN ai_attempt.usage_metadata_status = 'complete' THEN
                pg_catalog.jsonb_build_object(
                    'promptTokens', ai_attempt.prompt_tokens,
                    'completionTokens', ai_attempt.completion_tokens,
                    'totalTokens', ai_attempt.total_tokens,
                    'thinkingTokens', ai_attempt.thinking_tokens
                )
            ELSE NULL
        END,
        'latencyMs', ai_attempt.latency_ms,
        'estimatedCostUsd', ai_attempt.estimated_cost_usd,
        'finishReason', ai_attempt.finish_reason,
        'createdAt', p_checkpoint.created_at
    )
    FROM (SELECT 1) AS one_row
    LEFT JOIN public.analysis_v2_ai_attempts AS ai_attempt
      ON p_checkpoint.source = 'generated'
     AND ai_attempt.request_id = p_checkpoint.request_id
     AND ai_attempt.operation_key = p_checkpoint.operation_key
     AND ai_attempt.attempt = p_checkpoint.attempt
     AND ai_attempt.reservation_token = p_checkpoint.reservation_token;
$$;


--
-- Name: analysis_v2_ai_result_operation_key(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_ai_result_operation_key(p_identity jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT CASE p_identity->>'stage'
        WHEN 'genderTriage' THEN 'gender-triage:'
        WHEN 'genderResolution' THEN 'gender-resolution:'
        WHEN 'featureAnalysis' THEN 'feature-analysis:'
        WHEN 'highRiskNarrative' THEN 'high-risk-narrative:'
        WHEN 'privateAccountName' THEN 'private-account-name:'
        WHEN 'partnerSafety' THEN 'partner-safety:'
    END || public.analysis_v2_ai_result_cache_key(p_identity);
$$;


--
-- Name: analysis_v2_ai_scoring_stage_checkpoints; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_ai_scoring_stage_checkpoints (
    request_id uuid NOT NULL,
    stage_kind character varying(32) NOT NULL,
    batch_key integer NOT NULL,
    producer_job_key character varying(160) NOT NULL,
    producer_input_hash character varying(64) NOT NULL,
    producer_claim_token uuid NOT NULL,
    revision smallint DEFAULT 1 NOT NULL,
    item_count integer NOT NULL,
    result_hash character varying(64) NOT NULL,
    payload jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_v2_ai_scoring_stage_batch_check CHECK (((((stage_kind)::text = 'profile_ai_batch'::text) AND (batch_key >= 0)) OR (((stage_kind)::text <> 'profile_ai_batch'::text) AND (batch_key = '-1'::integer)))),
    CONSTRAINT analysis_v2_ai_scoring_stage_checkpoi_producer_input_hash_check CHECK (((producer_input_hash)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT analysis_v2_ai_scoring_stage_checkpoints_batch_key_check CHECK (((batch_key >= '-1'::integer) AND (batch_key <= 100000))),
    CONSTRAINT analysis_v2_ai_scoring_stage_checkpoints_item_count_check CHECK (((item_count >= 0) AND (item_count <= 1200))),
    CONSTRAINT analysis_v2_ai_scoring_stage_checkpoints_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT analysis_v2_ai_scoring_stage_checkpoints_result_hash_check CHECK (((result_hash)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT analysis_v2_ai_scoring_stage_checkpoints_revision_check CHECK ((revision = 1)),
    CONSTRAINT analysis_v2_ai_scoring_stage_checkpoints_stage_kind_check CHECK (((stage_kind)::text = ANY ((ARRAY['profile_ai_batch'::character varying, 'primary_join'::character varying, 'screening'::character varying, 'reverse_likes'::character varying, 'partner_safety'::character varying, 'final_score'::character varying, 'narrative'::character varying])::text[])))
);

ALTER TABLE ONLY public.analysis_v2_ai_scoring_stage_checkpoints FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_ai_scoring_stage_envelope(public.analysis_v2_ai_scoring_stage_checkpoints); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_ai_scoring_stage_envelope(p_row public.analysis_v2_ai_scoring_stage_checkpoints) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'stageKind', p_row.stage_kind,
        'batch', CASE WHEN p_row.batch_key = -1 THEN NULL ELSE p_row.batch_key END,
        'revision', p_row.revision,
        'resultHash', p_row.result_hash,
        'itemCount', p_row.item_count,
        'payload', p_row.payload
    );
$$;


--
-- Name: analysis_v2_apify_secret_ref_prune_readiness(text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_apify_secret_ref_prune_readiness(p_drop_slots text[], p_owner_source_commit_sha text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_drop_slots TEXT[];
    v_guard public.analysis_v2_apify_secret_ref_prune_guard%ROWTYPE;
    v_active_request_runs BIGINT;
    v_unreconciled_request_runs BIGINT;
    v_active_preflight_runs BIGINT;
    v_unreconciled_preflight_runs BIGINT;
    v_active_profile_repair_canary_runs BIGINT;
    v_unreconciled_profile_repair_canary_runs BIGINT;
    v_active_requests BIGINT;
    v_active_preflights BIGINT;
    v_active_drop_slot_policies BIGINT;
    v_incomplete_profile_provider_canary_cleanups BIGINT;
BEGIN
    IF NOT public.analysis_v2_valid_apify_secret_ref_prune_slots(p_drop_slots)
       OR p_owner_source_commit_sha IS NULL
       OR p_owner_source_commit_sha !~ '^[0-9a-f]{40}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_FENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    v_drop_slots :=
        public.analysis_v2_normalize_apify_secret_ref_prune_slots(p_drop_slots);

    SELECT guard.*
    INTO v_guard
    FROM public.analysis_v2_apify_secret_ref_prune_guard AS guard
    WHERE guard.singleton IS TRUE
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_GUARD_CORRUPT',
            ERRCODE = 'P0001';
    END IF;
    IF v_guard.drop_slots IS DISTINCT FROM v_drop_slots
       OR v_guard.owner_source_commit_sha
            IS DISTINCT FROM p_owner_source_commit_sha THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_FENCE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.count(*)
    INTO v_active_request_runs
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.credential_slot = ANY(v_drop_slots)
      AND provider_run.status IN ('starting', 'running');

    SELECT pg_catalog.count(*)
    INTO v_unreconciled_request_runs
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.credential_slot = ANY(v_drop_slots)
      AND provider_run.status IN ('succeeded', 'failed', 'aborted', 'timed_out')
      AND provider_run.usage_reconciled_at IS NULL;

    SELECT pg_catalog.count(*)
    INTO v_active_preflight_runs
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.credential_slot = ANY(v_drop_slots)
      AND provider_run.status IN ('starting', 'running');

    SELECT pg_catalog.count(*)
    INTO v_unreconciled_preflight_runs
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.credential_slot = ANY(v_drop_slots)
      AND provider_run.status IN ('succeeded', 'failed', 'aborted', 'timed_out')
      AND provider_run.usage_reconciled_at IS NULL;

    SELECT pg_catalog.count(*)
    INTO v_active_profile_repair_canary_runs
    FROM public.analysis_v2_profile_repair_canary_runs AS canary_run
    WHERE canary_run.credential_slot = ANY(v_drop_slots)
      AND canary_run.state IN ('starting', 'running', 'ambiguous');

    SELECT pg_catalog.count(*)
    INTO v_unreconciled_profile_repair_canary_runs
    FROM public.analysis_v2_profile_repair_canary_runs AS canary_run
    WHERE canary_run.credential_slot = ANY(v_drop_slots)
      AND canary_run.state IN ('succeeded', 'failed')
      AND canary_run.usage_reconciled_at IS NULL;

    -- A provider reservation can still be created before any provider ledger
    -- row exists. Reserve is fenced by an active request, while target-profile
    -- acquisition is fenced by either the main preflight state or the
    -- independent fresh-admission state. Requiring global quiet state prevents
    -- an old drained worker invocation from materializing a drop-slot run after
    -- this point-in-time audit.
    SELECT pg_catalog.count(*)
    INTO v_active_requests
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.status IN ('pending', 'processing');

    SELECT pg_catalog.count(*)
    INTO v_active_preflights
    FROM public.analysis_preflights AS preflight
    WHERE preflight.status IN ('pending', 'processing')
       OR (
            preflight.status = 'ready'
            AND preflight.admission_status IN ('pending', 'processing')
       );

    -- Keep the policy-specific count as diagnostic evidence. Terminal requests
    -- retain immutable policies but can no longer reserve provider runs.
    SELECT pg_catalog.count(*)
    INTO v_active_drop_slot_policies
    FROM public.analysis_v2_provider_execution_policies AS policy
    JOIN public.analysis_requests AS analysis_request
      ON analysis_request.id = policy.request_id
    WHERE analysis_request.status IN ('pending', 'processing')
      AND EXISTS (
          SELECT 1
          FROM pg_catalog.jsonb_each_text(
              policy.operation_slot_map
          ) AS operation_slot(operation_kind, credential_slot)
          WHERE operation_slot.credential_slot = ANY(v_drop_slots)
      );

    SELECT pg_catalog.count(*)
    INTO v_incomplete_profile_provider_canary_cleanups
    FROM public.analysis_v2_profile_provider_canary_experiments AS experiment
    WHERE (
        experiment.source_kvs_cleanup_state IS DISTINCT FROM 'verified_absent'
        OR experiment.source_dataset_cleanup_state IS DISTINCT FROM 'verified_absent'
        OR experiment.source_request_queue_cleanup_state
            IS DISTINCT FROM 'verified_absent'
    )
      AND EXISTS (
          SELECT 1
          FROM public.analysis_v2_provider_runs AS source_run
          JOIN public.analysis_v2_provider_execution_policies AS execution_policy
            ON execution_policy.request_id = source_run.request_id
          WHERE source_run.request_id = experiment.source_request_id
            AND source_run.status = 'succeeded'
            AND source_run.run_id ~ '^[A-Za-z0-9]{8,64}$'
            AND source_run.actor_id = 'apify/instagram-profile-scraper'
            AND source_run.job_key ~ '^track:profiles:batch:(?:0|[1-7])$'
            AND source_run.operation_key ~ '^profile-fallback:[0-9a-f]{64}$'
            AND execution_policy.mode = 'test_operation_split'
            AND execution_policy.policy_version = 'authorized-free-e2e-v1'
            AND execution_policy.operation_slot_map->>'profile-fallback'
                = source_run.credential_slot
            AND source_run.credential_slot = ANY(v_drop_slots)
      );

    RETURN pg_catalog.jsonb_build_object(
        'ready',
            v_active_request_runs = 0
            AND v_unreconciled_request_runs = 0
            AND v_active_preflight_runs = 0
            AND v_unreconciled_preflight_runs = 0
            AND v_active_profile_repair_canary_runs = 0
            AND v_unreconciled_profile_repair_canary_runs = 0
            AND v_active_requests = 0
            AND v_active_preflights = 0
            AND v_active_drop_slot_policies = 0
            AND v_incomplete_profile_provider_canary_cleanups = 0,
        'dropSlots', pg_catalog.to_jsonb(v_drop_slots),
        'activeRequestRuns', v_active_request_runs,
        'unreconciledRequestRuns', v_unreconciled_request_runs,
        'activePreflightRuns', v_active_preflight_runs,
        'unreconciledPreflightRuns', v_unreconciled_preflight_runs,
        'activeProfileRepairCanaryRuns', v_active_profile_repair_canary_runs,
        'unreconciledProfileRepairCanaryRuns',
            v_unreconciled_profile_repair_canary_runs,
        'activeRequests', v_active_requests,
        'activePreflights', v_active_preflights,
        'activeDropSlotPolicies', v_active_drop_slot_policies,
        'incompleteProfileProviderCanaryCleanups',
            v_incomplete_profile_provider_canary_cleanups
    );
END;
$_$;


--
-- Name: analysis_v2_apply_v211_summary_tone(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_apply_v211_summary_tone(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF p_request_id IS NULL OR NOT EXISTS (
        SELECT 1
        FROM public.analysis_requests AS request
        WHERE request.id = p_request_id
          AND request.policy_versions_snapshot->>'aiStage' IN ('ai-stage-policy-v2.11', 'ai-stage-policy-v2.12')
    ) THEN
        RETURN;
    END IF;

    UPDATE public.analysis_v2_female_results AS female
    SET one_line_overview = public.analysis_v2_v211_safe_overview_fallback(female.sort_ordinal)
    WHERE female.request_id = p_request_id
      AND female.one_line_overview ~* (
          '맥락[[:space:]]*(이|은)?[[:space:]]*(부족|없)|'
          || '(공개[[:space:]]*)?(단서|자료|정보)[[:space:]]*(가|는|이)?[[:space:]]*(부족|없)|'
          || '(단정|확정|판단)[[:space:]]*(하기[[:space:]]*)?(어렵|힘들)|'
          || '(분석|수집)[[:space:]]*(제약|한계)|제약(이|은)?[[:space:]]*있|참고[[:space:]]*(결과|용)'
      );
END;
$$;


--
-- Name: analysis_v2_apply_v28_summary_tone(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_apply_v28_summary_tone(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_total INTEGER; v_budget INTEGER; v_kept INTEGER := 0;
    v_previous_kept_ordinal SMALLINT := NULL; v_normalized TEXT;
    v_first_laugh_position INTEGER; v_row RECORD;
BEGIN
    IF p_request_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.analysis_requests AS request WHERE request.id = p_request_id
          AND request.policy_versions_snapshot->>'aiStage' IN ('ai-stage-policy-v2.8', 'ai-stage-policy-v2.10')
    ) THEN RETURN; END IF;
    WITH analyzed AS (
        SELECT female.candidate_id, female.sort_ordinal, female.one_line_overview,
            pg_catalog.count(*) OVER (PARTITION BY female.one_line_overview) AS duplicate_count
        FROM public.analysis_v2_female_results AS female WHERE female.request_id = p_request_id
    ), repair AS (
        SELECT analyzed.candidate_id, analyzed.sort_ordinal FROM analyzed
        WHERE analyzed.duplicate_count > 1 OR analyzed.one_line_overview ~ '[[:digit:]@]'
           OR analyzed.one_line_overview ~* ('risk[-_ ]?(?:policy|band)|score|스코어|점수|위험도|(?:일반|주의|고위험)[[:space:]]*단계|정책[[:space:]]*버전|계정[[:space:]]*(?:ID|아이디)')
           OR analyzed.one_line_overview ~ ('판독관|내[[:space:]]*눈(?:엔|에는)|제가[[:space:]]*보기(?:엔|에는)|저라면')
           OR analyzed.one_line_overview ~ ('^(피드가 말을 아끼는 편이네요|사진 배치가 지나치게 단정하네요|전체 분위기가 묘하게 계산돼 있네요|첫인상은 얌전한데 여운이 길게 남네요|취향을 슬쩍만 보여 주는 구성이네요|일상 기록이 의외로 빈틈없이 이어지네요|꾸민 듯 안 꾸민 듯한 장면이 많네요|프로필이 정답을 쉽게 주지 않네요|피드의 온도가 은근히 사람을 붙잡네요|설명보다 분위기가 먼저 말을 거네요)')
           OR analyzed.one_line_overview ~ ('^(확인된 공개 단서가 제한적이고|공개된 소개와 피드만으로는 맥락이 부족하고|수집된 공개 범위에서는 정보가 많지 않고|현재 보이는 공개 자료에는 빈칸이 남고|소개와 피드에서 확인되는 내용이 제한적이고|공개 화면에 드러난 단서만으로는 정보가 부족하고|확인 가능한 공개 기록의 범위가 좁고|지금 확보된 공개 자료에는 설명이 적고|공개 프로필과 피드만 보면 단서가 많지 않고|확인된 공개 정보 사이에 빈칸이 남고)')
    ) UPDATE public.analysis_v2_female_results AS female
      SET one_line_overview = public.analysis_v2_v28_safe_overview_fallback(repair.sort_ordinal)
      FROM repair WHERE female.request_id = p_request_id AND female.candidate_id = repair.candidate_id;
    SELECT pg_catalog.count(*)::INTEGER INTO v_total FROM public.analysis_v2_female_results AS female WHERE female.request_id = p_request_id;
    v_budget := pg_catalog.floor(v_total / 20.0)::INTEGER;
    FOR v_row IN SELECT female.candidate_id, female.sort_ordinal, female.one_line_overview
        FROM public.analysis_v2_female_results AS female WHERE female.request_id = p_request_id ORDER BY female.sort_ordinal, female.candidate_id LOOP
        IF v_row.one_line_overview ~ '판독관' THEN
            v_normalized := '소개와 피드 구성이 같은 방향을 가리킵니다. 무엇을 보여주려는지는 꽤 분명하네요.';
        ELSE
            v_normalized := pg_catalog.regexp_replace(pg_catalog.regexp_replace(v_row.one_line_overview, 'ㅋ+', 'ㅋㅋ', 'g'), '[[:space:]]{2,}', ' ', 'g');
        END IF;
        IF pg_catalog.strpos(v_normalized, 'ㅋㅋ') > 0 AND v_kept < v_budget
           AND (v_previous_kept_ordinal IS NULL OR v_row.sort_ordinal <> v_previous_kept_ordinal + 1) THEN
            v_first_laugh_position := pg_catalog.strpos(v_normalized, 'ㅋㅋ');
            v_normalized := pg_catalog.left(v_normalized, v_first_laugh_position + 1) || pg_catalog.regexp_replace(pg_catalog.substr(v_normalized, v_first_laugh_position + 2), 'ㅋ+', '', 'g');
            v_kept := v_kept + 1; v_previous_kept_ordinal := v_row.sort_ordinal;
        ELSE
            v_normalized := pg_catalog.regexp_replace(v_normalized, 'ㅋ+', '', 'g');
        END IF;
        UPDATE public.analysis_v2_female_results AS female SET one_line_overview = pg_catalog.btrim(pg_catalog.regexp_replace(v_normalized, '[[:space:]]{2,}', ' ', 'g'))
        WHERE female.request_id = p_request_id AND female.candidate_id = v_row.candidate_id;
    END LOOP;
    UPDATE public.analysis_v2_female_results AS female SET
        narrative_line_one = CASE WHEN female.narrative_line_one IS NULL THEN NULL ELSE pg_catalog.btrim(pg_catalog.regexp_replace(female.narrative_line_one, 'ㅋ+', '', 'g')) END,
        narrative_line_two = CASE WHEN female.narrative_line_two IS NULL THEN NULL ELSE pg_catalog.btrim(pg_catalog.regexp_replace(female.narrative_line_two, 'ㅋ+', '', 'g')) END
    WHERE female.request_id = p_request_id;
END;
$$;


--
-- Name: analysis_v2_valid_job_keys(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_job_keys(p_keys text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
    SELECT pg_catalog.cardinality(p_keys) <= 64
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.unnest(p_keys) AS job_key(value)
            WHERE job_key.value IS NULL
               OR pg_catalog.char_length(job_key.value) NOT BETWEEN 1 AND 160
               OR job_key.value !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       )
       AND pg_catalog.cardinality(p_keys) = (
            SELECT pg_catalog.count(DISTINCT job_key.value)::INTEGER
            FROM pg_catalog.unnest(p_keys) AS job_key(value)
       );
$_$;


--
-- Name: analysis_pipeline_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_pipeline_jobs (
    request_id uuid NOT NULL,
    job_key character varying(160) NOT NULL,
    track character varying(50) NOT NULL,
    kind character varying(50) NOT NULL,
    batch integer,
    input_hash character varying(64) NOT NULL,
    required_job_keys text[] DEFAULT '{}'::text[] NOT NULL,
    status character varying(16) DEFAULT 'pending'::character varying NOT NULL,
    dispatch_state character varying(16) DEFAULT 'pending'::character varying NOT NULL,
    dispatch_generation integer DEFAULT 0 NOT NULL,
    dispatch_reservation_token uuid,
    dispatch_reserved_at timestamp with time zone,
    dispatched_at timestamp with time zone,
    dispatch_task_name character varying(512),
    delivered_at timestamp with time zone,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    first_started_at timestamp with time zone,
    completion_token uuid,
    completion_fanout_hash character varying(32),
    last_error_code character varying(64),
    last_error_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    recovery_checked_at timestamp with time zone,
    recovery_not_before timestamp with time zone,
    ai_capacity_deferral_count integer DEFAULT 0 NOT NULL,
    scheduler_not_before_at timestamp with time zone,
    dispatch_workload_role text,
    dispatch_contract_version smallint,
    claim_workload_role text,
    claim_contract_version smallint,
    CONSTRAINT analysis_pipeline_jobs_ai_capacity_deferral_count_check CHECK (((ai_capacity_deferral_count >= 0) AND (ai_capacity_deferral_count <= 100000))),
    CONSTRAINT analysis_pipeline_jobs_attempt_check CHECK ((((attempt_count >= 0) AND (attempt_count <= 100)) AND (((attempt_count = 0) AND (first_started_at IS NULL)) OR ((attempt_count > 0) AND (first_started_at IS NOT NULL))))),
    CONSTRAINT analysis_pipeline_jobs_batch_check CHECK (((batch IS NULL) OR ((batch >= 0) AND (batch <= 100000)))),
    CONSTRAINT analysis_pipeline_jobs_completion_check CHECK (((((status)::text = 'completed'::text) AND (completed_at IS NOT NULL) AND (completion_token IS NOT NULL) AND (completion_fanout_hash IS NOT NULL) AND ((completion_fanout_hash)::text ~ '^[a-f0-9]{32}$'::text)) OR (((status)::text <> 'completed'::text) AND (completion_token IS NULL) AND (completion_fanout_hash IS NULL) AND ((((status)::text = ANY ((ARRAY['failed'::character varying, 'cancelled'::character varying])::text[])) AND (completed_at IS NOT NULL)) OR (((status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying])::text[])) AND (completed_at IS NULL)))))),
    CONSTRAINT analysis_pipeline_jobs_dispatch_generation_check CHECK (((dispatch_generation >= 0) AND (dispatch_generation <= 1000))),
    CONSTRAINT analysis_pipeline_jobs_dispatch_pair_check CHECK (((((dispatch_state)::text = 'pending'::text) AND (dispatch_generation = 0) AND (dispatch_reservation_token IS NULL) AND (dispatch_reserved_at IS NULL) AND (dispatched_at IS NULL) AND (dispatch_task_name IS NULL) AND (delivered_at IS NULL)) OR (((dispatch_state)::text = 'reserved'::text) AND (dispatch_generation > 0) AND (dispatch_reservation_token IS NOT NULL) AND (dispatch_reserved_at IS NOT NULL) AND (dispatched_at IS NULL) AND (dispatch_task_name IS NULL) AND (delivered_at IS NULL)) OR (((dispatch_state)::text = 'enqueued'::text) AND (dispatch_generation > 0) AND (dispatch_reservation_token IS NOT NULL) AND (dispatch_reserved_at IS NOT NULL) AND (dispatched_at IS NOT NULL) AND (dispatch_task_name IS NOT NULL) AND (delivered_at IS NULL)) OR (((dispatch_state)::text = 'delivered'::text) AND (dispatch_generation > 0) AND (dispatch_reservation_token IS NOT NULL) AND (dispatch_reserved_at IS NOT NULL) AND (dispatched_at IS NOT NULL) AND (dispatch_task_name IS NOT NULL) AND (delivered_at IS NOT NULL)))),
    CONSTRAINT analysis_pipeline_jobs_dispatch_state_check CHECK (((dispatch_state)::text = ANY ((ARRAY['pending'::character varying, 'reserved'::character varying, 'enqueued'::character varying, 'delivered'::character varying])::text[]))),
    CONSTRAINT analysis_pipeline_jobs_error_check CHECK ((((last_error_code IS NULL) AND (last_error_at IS NULL)) OR ((last_error_code IS NOT NULL) AND ((last_error_code)::text ~ '^[A-Z][A-Z0-9_]{0,63}$'::text) AND (last_error_at IS NOT NULL)))),
    CONSTRAINT analysis_pipeline_jobs_failed_error_check CHECK ((((status)::text <> 'failed'::text) OR (last_error_code IS NOT NULL))),
    CONSTRAINT analysis_pipeline_jobs_input_hash_check CHECK (((input_hash)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT analysis_pipeline_jobs_job_key_check CHECK ((((char_length((job_key)::text) >= 1) AND (char_length((job_key)::text) <= 160)) AND ((job_key)::text ~ '^[a-z0-9][a-z0-9:._-]{0,159}$'::text))),
    CONSTRAINT analysis_pipeline_jobs_kind_check CHECK ((((char_length((kind)::text) >= 1) AND (char_length((kind)::text) <= 50)) AND ((kind)::text ~ '^[a-z][a-z0-9_]{0,49}$'::text))),
    CONSTRAINT analysis_pipeline_jobs_lease_check CHECK (((((status)::text = 'processing'::text) AND (lease_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND ((dispatch_state)::text = 'delivered'::text)) OR (((status)::text <> 'processing'::text) AND (lease_token IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT analysis_pipeline_jobs_recovery_defer_check CHECK (((recovery_checked_at IS NULL) OR (recovery_not_before > recovery_checked_at))),
    CONSTRAINT analysis_pipeline_jobs_recovery_schedule_check CHECK (((((status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying])::text[])) AND (recovery_not_before IS NOT NULL)) OR (((status)::text = ANY ((ARRAY['completed'::character varying, 'failed'::character varying, 'cancelled'::character varying])::text[])) AND (recovery_checked_at IS NULL) AND (recovery_not_before IS NULL)))),
    CONSTRAINT analysis_pipeline_jobs_required_keys_check CHECK ((public.analysis_v2_valid_job_keys(required_job_keys) AND (NOT ((job_key)::text = ANY (required_job_keys))))),
    CONSTRAINT analysis_pipeline_jobs_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying, 'completed'::character varying, 'failed'::character varying, 'cancelled'::character varying])::text[]))),
    CONSTRAINT analysis_pipeline_jobs_task_name_check CHECK (((dispatch_task_name IS NULL) OR (((char_length((dispatch_task_name)::text) >= 1) AND (char_length((dispatch_task_name)::text) <= 512)) AND ((dispatch_task_name)::text ~ '^[A-Za-z0-9][A-Za-z0-9._:/=-]*$'::text)))),
    CONSTRAINT analysis_pipeline_jobs_timestamp_check CHECK (((updated_at >= created_at) AND ((dispatch_reserved_at IS NULL) OR (dispatch_reserved_at >= created_at)) AND ((dispatched_at IS NULL) OR (dispatched_at >= dispatch_reserved_at)) AND ((delivered_at IS NULL) OR (delivered_at >= dispatched_at)) AND ((first_started_at IS NULL) OR (first_started_at >= created_at)) AND ((last_error_at IS NULL) OR (last_error_at >= created_at)) AND ((completed_at IS NULL) OR (completed_at >= created_at)) AND ((lease_expires_at IS NULL) OR (lease_expires_at > updated_at)))),
    CONSTRAINT analysis_pipeline_jobs_track_check CHECK ((((char_length((track)::text) >= 1) AND (char_length((track)::text) <= 50)) AND ((track)::text ~ '^[a-z][a-z0-9_]{0,49}$'::text)))
);

ALTER TABLE ONLY public.analysis_pipeline_jobs FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_assert_ai_scoring_stage_consumer(public.analysis_pipeline_jobs, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_assert_ai_scoring_stage_consumer(p_job public.analysis_pipeline_jobs, p_stage_kind text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
BEGIN
    IF NOT (CASE p_stage_kind
        WHEN 'profile_ai_batch' THEN p_job.job_key IN (
            'coordinator:join:primary-evidence', 'coordinator:candidate-screening',
            'track:reverse-likes:collect', 'track:partner-safety:batch:0',
            'coordinator:join:final-score', 'track:narratives:batch:0'
        )
        WHEN 'primary_join' THEN p_job.job_key = 'coordinator:candidate-screening'
        WHEN 'screening' THEN p_job.job_key IN (
            'track:reverse-likes:collect', 'track:partner-safety:batch:0',
            'coordinator:join:final-score'
        )
        WHEN 'reverse_likes' THEN p_job.job_key IN (
            'coordinator:join:final-score', 'track:narratives:batch:0'
        )
        WHEN 'partner_safety' THEN p_job.job_key = 'coordinator:join:final-score'
        WHEN 'final_score' THEN p_job.job_key = 'track:narratives:batch:0'
        ELSE FALSE
    END) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_SCORING_STAGE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
END;
$$;


--
-- Name: analysis_v2_assert_ai_scoring_stage_producer(public.analysis_pipeline_jobs, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_assert_ai_scoring_stage_producer(p_job public.analysis_pipeline_jobs, p_stage_kind text, p_batch integer) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
BEGIN
    IF NOT (
        (p_stage_kind = 'profile_ai_batch'
            AND p_batch IS NOT NULL
            AND p_job.job_key = 'track:profile-ai:batch:' || p_batch::TEXT
            AND p_job.track = 'profile_ai'
            AND p_job.kind = 'ai'
            AND p_job.batch = p_batch)
        OR (p_stage_kind = 'primary_join' AND p_batch IS NULL
            AND p_job.job_key = 'coordinator:join:primary-evidence')
        OR (p_stage_kind = 'screening' AND p_batch IS NULL
            AND p_job.job_key = 'coordinator:candidate-screening')
        OR (p_stage_kind = 'reverse_likes' AND p_batch IS NULL
            AND p_job.job_key = 'track:reverse-likes:collect')
        OR (p_stage_kind = 'partner_safety' AND p_batch IS NULL
            AND p_job.job_key = 'track:partner-safety:batch:0')
        OR (p_stage_kind = 'final_score' AND p_batch IS NULL
            AND p_job.job_key = 'coordinator:join:final-score')
        OR (p_stage_kind = 'narrative' AND p_batch IS NULL
            AND p_job.job_key = 'track:narratives:batch:0')
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_SCORING_STAGE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
END;
$$;


--
-- Name: analysis_v2_assert_result_image_job_fence(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_assert_result_image_job_fence(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS DISTINCT FROM 'coordinator:finalize'
       OR p_claim_token IS NULL
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR NOT EXISTS (
            SELECT 1
            FROM public.analysis_requests AS analysis_request
            JOIN public.analysis_pipeline_jobs AS job
              ON job.request_id = analysis_request.id
             AND job.job_key = p_job_key
            WHERE analysis_request.id = p_request_id
              AND analysis_request.pipeline_version = 'v2'
              AND analysis_request.status IN ('pending', 'processing')
              AND job.track = 'coordinator'
              AND job.kind = 'finalizer'
              AND job.status = 'processing'
              AND job.input_hash = p_job_input_hash
              AND job.lease_token = p_claim_token
              AND job.lease_expires_at > pg_catalog.clock_timestamp()
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
END;
$_$;


--
-- Name: analysis_v2_assert_result_job_fence(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_assert_result_job_fence(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text) RETURNS public.analysis_pipeline_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
      AND analysis_request.status IN ('pending', 'processing')
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND
       OR v_job.status <> 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_v2_candidate_feature_manifests
    SET producer_claim_token = p_claim_token
    WHERE request_id = p_request_id
      AND producer_job_key = p_job_key
      AND producer_input_hash = p_job_input_hash
      AND producer_claim_token IS DISTINCT FROM p_claim_token;
    UPDATE public.analysis_v2_preliminary_score_manifests
    SET producer_claim_token = p_claim_token
    WHERE request_id = p_request_id
      AND producer_job_key = p_job_key
      AND producer_input_hash = p_job_input_hash
      AND producer_claim_token IS DISTINCT FROM p_claim_token;
    UPDATE public.analysis_v2_reverse_like_manifests
    SET producer_claim_token = p_claim_token
    WHERE request_id = p_request_id
      AND producer_job_key = p_job_key
      AND producer_input_hash = p_job_input_hash
      AND producer_claim_token IS DISTINCT FROM p_claim_token;
    UPDATE public.analysis_v2_partner_safety_manifests
    SET producer_claim_token = p_claim_token
    WHERE request_id = p_request_id
      AND producer_job_key = p_job_key
      AND producer_input_hash = p_job_input_hash
      AND producer_claim_token IS DISTINCT FROM p_claim_token;
    UPDATE public.analysis_v2_candidate_score_manifests
    SET producer_claim_token = p_claim_token
    WHERE request_id = p_request_id
      AND producer_job_key = p_job_key
      AND producer_input_hash = p_job_input_hash
      AND producer_claim_token IS DISTINCT FROM p_claim_token;
    UPDATE public.analysis_v2_private_name_manifests
    SET producer_claim_token = p_claim_token
    WHERE request_id = p_request_id
      AND producer_job_key = p_job_key
      AND producer_input_hash = p_job_input_hash
      AND producer_claim_token IS DISTINCT FROM p_claim_token;
    UPDATE public.analysis_v2_narrative_manifests
    SET producer_claim_token = p_claim_token
    WHERE request_id = p_request_id
      AND producer_job_key = p_job_key
      AND producer_input_hash = p_job_input_hash
      AND producer_claim_token IS DISTINCT FROM p_claim_token;

    RETURN v_job;
END;
$_$;


--
-- Name: analysis_v2_betatest_plan_replay_internal(uuid, uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_betatest_plan_replay_internal(p_preflight_id uuid, p_user_id uuid, p_admission_token uuid, p_admission_generation integer, p_selected_plan_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_initial_job_key CONSTANT TEXT := 'coordinator:bootstrap';
    v_preflight public.analysis_preflights%ROWTYPE;
    v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_activation JSONB;
    v_expected_input_hash TEXT;
    v_expected_scope JSONB;
    v_reservation_count INTEGER;
    v_active_reservation_count INTEGER;
    v_reservation_drift BOOLEAN;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_admission_token IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_selected_plan_id IS NULL
       OR p_selected_plan_id NOT IN ('basic', 'standard', 'plus') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    PERFORM users.id
    FROM public.users AS users
    WHERE users.id = p_user_id
    FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.user_id IS DISTINCT FROM p_user_id
       OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'betatest'
       OR v_preflight.access_mode IS DISTINCT FROM 'production'
       OR v_preflight.admission_token IS DISTINCT FROM p_admission_token
       OR v_preflight.admission_generation IS DISTINCT FROM p_admission_generation
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM p_selected_plan_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    SELECT allocation.* INTO v_allocation
    FROM public.analysis_beta_pool_allocations AS allocation
    WHERE allocation.preflight_id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        IF v_preflight.status = 'consumed'
           OR v_preflight.consumed_request_id IS NOT NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN NULL;
    END IF;

    IF v_allocation.lifecycle_state = 'preflight_held' THEN
        IF v_preflight.status = 'consumed'
           OR v_preflight.consumed_request_id IS NOT NULL
           OR v_allocation.request_id IS NOT NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN NULL;
    END IF;

    IF v_allocation.lifecycle_state NOT IN ('active', 'settled')
       OR v_allocation.user_id IS DISTINCT FROM p_user_id
       OR v_allocation.request_id IS NULL
       OR v_allocation.selected_plan_id IS DISTINCT FROM p_selected_plan_id
       OR v_allocation.policy_version IS DISTINCT FROM 'betatest-free-pool-v1'
       OR NOT public.analysis_beta_valid_operation_slot_map(v_allocation.operation_slot_map)
       OR v_allocation.operation_budget_map IS DISTINCT FROM
            public.analysis_beta_plan_operation_budget_map(p_selected_plan_id) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
    END IF;

    -- The already-reviewed active validator checks the immutable allocation and
    -- provider-policy bind with stored maps. No caller-side replan is consulted.
    IF v_allocation.lifecycle_state = 'active' THEN
        v_activation := public.activate_analysis_beta_apify_request_credit(
            p_preflight_id,
            v_allocation.request_id,
            p_user_id,
            p_selected_plan_id,
            v_allocation.operation_slot_map,
            v_allocation.operation_budget_map,
            300
        );
        IF v_activation->>'lifecycleState' IS DISTINCT FROM 'active'
           OR (v_activation->>'requestId')::UUID
                IS DISTINCT FROM v_allocation.request_id THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
        END IF;
    END IF;

    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    WHERE request.id = v_allocation.request_id
    FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = v_allocation.request_id
      AND job.job_key = v_initial_job_key
    FOR UPDATE;
    SELECT policy.* INTO v_policy
    FROM public.analysis_v2_provider_execution_policies AS policy
    WHERE policy.request_id = v_allocation.request_id
    FOR UPDATE;

    v_expected_input_hash := pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'analysis-v2-job-input-v1' || pg_catalog.chr(10)
                || pg_catalog.lower(v_allocation.request_id::TEXT)
                || pg_catalog.chr(10) || v_initial_job_key,
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );
    v_expected_scope := pg_catalog.jsonb_build_object(
        'relationshipCapacity',
            v_preflight.plan_cards_snapshot->p_selected_plan_id
                ->'relationshipCapacity',
        'detailedMutualLimit',
            v_preflight.plan_cards_snapshot->p_selected_plan_id
                ->'detailedMutualLimit'
    );

    SELECT pg_catalog.count(*)::INTEGER,
           pg_catalog.count(*) FILTER (
               WHERE reservation.lifecycle_state = 'active'
           )::INTEGER,
           COALESCE(pg_catalog.bool_or(
               v_allocation.operation_slot_map->>reservation.operation_family
                    IS DISTINCT FROM reservation.credential_slot
               OR (v_allocation.operation_budget_map
                    ->>reservation.operation_family)::NUMERIC
                    IS DISTINCT FROM reservation.reserved_usd
               OR (
                    v_allocation.lifecycle_state = 'active'
                    AND reservation.lifecycle_state NOT IN ('active', 'settled')
               )
               OR (
                    v_allocation.lifecycle_state = 'settled'
                    AND reservation.lifecycle_state <> 'settled'
               )
           ), FALSE)
    INTO v_reservation_count, v_active_reservation_count, v_reservation_drift
    FROM public.analysis_beta_pool_reservations AS reservation
    WHERE reservation.allocation_id = v_allocation.id;

    IF v_preflight.status IS DISTINCT FROM 'consumed'
       OR v_preflight.consumed_request_id IS DISTINCT FROM v_request.id
       OR v_request.id IS NULL
       OR v_request.user_id IS DISTINCT FROM p_user_id
       OR v_request.preflight_id IS DISTINCT FROM p_preflight_id
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'production'
       OR v_request.test_entitlement_jti_hash IS NOT NULL
       OR v_request.analysis_entry_channel IS DISTINCT FROM 'betatest'
       OR v_request.selected_plan_id_snapshot IS DISTINCT FROM p_selected_plan_id
       OR v_request.target_instagram_id
            IS DISTINCT FROM v_preflight.target_instagram_id
       OR v_request.excluded_instagram_id
            IS DISTINCT FROM v_preflight.excluded_instagram_id
       OR v_request.exclusion_decision_snapshot
            IS DISTINCT FROM v_preflight.exclusion_decision
       OR v_request.capacity_required_plan_id_snapshot
            IS DISTINCT FROM v_preflight.capacity_required_plan_id
       OR v_request.required_plan_id_snapshot
            IS DISTINCT FROM v_preflight.required_plan_id
       OR v_request.plan_launch_status_snapshot
            IS DISTINCT FROM v_preflight.launch_status_snapshot
       OR v_request.plan_cards_snapshot
            IS DISTINCT FROM v_preflight.plan_cards_snapshot
       OR v_request.pricing_version_snapshot
            IS DISTINCT FROM v_preflight.pricing_version
       OR v_request.pricing_snapshot IS DISTINCT FROM v_preflight.pricing_snapshot
       OR v_request.policy_versions_snapshot
            IS DISTINCT FROM v_preflight.policy_versions_snapshot
       OR v_request.analysis_scope_snapshot IS DISTINCT FROM v_expected_scope
       OR v_request.idempotency_key IS DISTINCT FROM
            'betatest:' || pg_catalog.lower(p_preflight_id::TEXT)
       OR v_request.status NOT IN ('pending', 'processing', 'completed', 'failed')
       OR v_job.request_id IS NULL
       OR v_job.track IS DISTINCT FROM 'coordinator'
       OR v_job.kind IS DISTINCT FROM 'bootstrap'
       OR v_job.batch IS NOT NULL
       OR v_job.required_job_keys IS DISTINCT FROM '{}'::TEXT[]
       OR v_job.input_hash IS DISTINCT FROM v_expected_input_hash
       OR v_policy.request_id IS NULL
       OR v_policy.mode IS DISTINCT FROM 'betatest_free_pool'
       OR v_policy.policy_version IS DISTINCT FROM 'betatest-free-pool-v1'
       OR v_policy.entitlement_jti_hash IS NOT NULL
       OR v_policy.target_instagram_id
            IS DISTINCT FROM pg_catalog.lower(v_request.target_instagram_id)
       OR v_policy.operation_slot_map
            IS DISTINCT FROM v_allocation.operation_slot_map
       OR v_policy.policy_hash IS DISTINCT FROM
            public.analysis_beta_provider_policy_hash(
                pg_catalog.lower(v_request.target_instagram_id),
                v_allocation.operation_slot_map
            )
       OR v_reservation_count <> 8
       OR (
            v_request.status IN ('pending', 'processing')
            AND (
                v_allocation.lifecycle_state <> 'active'
                OR v_active_reservation_count <> 8
            )
       )
       OR (
            v_request.status IN ('completed', 'failed')
            AND NOT (
                (
                    v_allocation.lifecycle_state = 'active'
                    AND v_active_reservation_count BETWEEN 1 AND 8
                )
                OR (
                    v_allocation.lifecycle_state = 'settled'
                    AND v_active_reservation_count = 0
                )
            )
       )
       OR v_reservation_drift THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', v_request.id,
        'initialJobKey', v_initial_job_key,
        'allocationId', v_allocation.id,
        'replayed', TRUE
    );
END;
$$;


--
-- Name: analysis_v2_calculate_progress_bp(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_calculate_progress_bp(p_tracks jsonb, p_status text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT CASE
        WHEN p_status = 'completed' THEN 10000
        ELSE LEAST(
            9999,
            pg_catalog.floor(
                7200::DOUBLE PRECISION * CASE
                    WHEN (p_tracks->'relationshipAi'->>'total')::INTEGER = 0 THEN 0
                    ELSE (p_tracks->'relationshipAi'->>'done')::DOUBLE PRECISION
                        / (p_tracks->'relationshipAi'->>'total')::DOUBLE PRECISION
                END
                + 1700::DOUBLE PRECISION * CASE
                    WHEN (p_tracks->'interactions'->>'total')::INTEGER = 0 THEN 0
                    ELSE (p_tracks->'interactions'->>'done')::DOUBLE PRECISION
                        / (p_tracks->'interactions'->>'total')::DOUBLE PRECISION
                END
                + 1100::DOUBLE PRECISION * CASE
                    WHEN (p_tracks->'finalization'->>'total')::INTEGER = 0 THEN 0
                    ELSE (p_tracks->'finalization'->>'done')::DOUBLE PRECISION
                        / (p_tracks->'finalization'->>'total')::DOUBLE PRECISION
                END
            )::INTEGER
        )
    END;
$$;


--
-- Name: analysis_v2_canonical_gemini_model(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_canonical_gemini_model(p_model_name text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
    WITH model AS (
        SELECT pg_catalog.regexp_replace(pg_catalog.btrim(p_model_name), '^.*/', '')
            AS model_name
    )
    SELECT CASE
        WHEN model.model_name ~ '^gemini-3[.]1-flash-lite(?:-preview(?:-[0-9]{3})?|-[0-9]{3})?$'
            THEN 'gemini-3.1-flash-lite'
        WHEN model.model_name ~ '^gemini-3[.]7-flash(?:-[0-9]{3})?$'
            THEN 'gemini-3.7-flash'
        WHEN model.model_name = 'gemini-3-flash-preview'
            THEN 'gemini-3-flash-preview'
        ELSE model.model_name
    END
    FROM model;
$_$;


--
-- Name: analysis_v2_capture_cost_rollup_before_preflight_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_capture_cost_rollup_before_preflight_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    -- Account/preflight cleanup can be the outer delete that cascades into a request. Capture
    -- while the consumed request and preflight/provider source rows are still addressable.
    PERFORM public.analysis_v2_refresh_cost_rollup_snapshot(OLD.consumed_request_id);
    RETURN OLD;
END;
$$;


--
-- Name: analysis_v2_capture_cost_rollup_before_request_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_capture_cost_rollup_before_request_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    PERFORM public.analysis_v2_refresh_cost_rollup_snapshot(OLD.id);
    RETURN OLD;
END;
$$;


--
-- Name: analysis_v2_checkpoint_candidate_features_complete(uuid, text, uuid, text, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_checkpoint_candidate_features_complete(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_batch integer, p_analyzed_count integer, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
    v_rows JSONB;
    v_checkpoint JSONB;
    v_request_policy_version TEXT;
BEGIN
    IF p_rows IS NULL OR pg_catalog.jsonb_typeof(p_rows) <> 'array' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT request.policy_versions_snapshot->>'aiStage'
    INTO v_request_policy_version
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id;

    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
        WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
           OR (item.value ? 'preFeaturePolicyVersion')
                <> (item.value ? 'preFeatureAdmission')
           OR (
                item.value ? 'preFeaturePolicyVersion'
                AND (
                    pg_catalog.jsonb_typeof(item.value->'preFeaturePolicyVersion')
                        <> pg_catalog.jsonb_typeof(item.value->'preFeatureAdmission')
                    OR (
                        pg_catalog.jsonb_typeof(item.value->'preFeaturePolicyVersion') = 'string'
                        AND (
                            item.value->>'preFeaturePolicyVersion' NOT IN (
                                'ai-stage-policy-v2.9',
                                'ai-stage-policy-v2.10',
                                'ai-stage-policy-v2.11',
                                'ai-stage-policy-v2.12'
                            )
                            OR item.value->>'preFeatureAdmission' NOT IN (
                                'nonpersonal_or_official',
                                'unsupported_unknown'
                            )
                            OR item.value->>'preFeaturePolicyVersion'
                                IS DISTINCT FROM v_request_policy_version
                            OR item.value->>'classification' <> 'unresolved'
                            OR item.value->'featureOperationKey' <> 'null'::JSONB
                            OR item.value->'featureResultHash' <> 'null'::JSONB
                            OR item.value->'feature' <> 'null'::JSONB
                            OR NOT public.analysis_v2_result_valid_media_context(
                                item.value->'mediaContext'
                            )
                            OR (
                                CASE
                                    WHEN pg_catalog.jsonb_typeof(
                                        item.value->'mediaContext'
                                            ->'featureAnalyzedSelectionIds'
                                    ) = 'array'
                                        THEN pg_catalog.jsonb_array_length(
                                            item.value->'mediaContext'
                                                ->'featureAnalyzedSelectionIds'
                                        )
                                    ELSE -1
                                END
                            ) <> 0
                            OR item.value->>'genderOperationKey'
                                !~ '^gender-triage:[a-f0-9]{64}$'
                            OR item.value->>'genderResultHash' !~ '^[a-f0-9]{64}$'
                            OR item.value->>'baselineClassification' <> 'unresolved'
                            OR item.value->>'classificationSource' <> 'unknown'
                            OR item.value->>'genderResolutionStatus' <> 'not_eligible'
                            OR item.value->'genderResolutionOperationKey'
                                <> 'null'::JSONB
                            OR item.value->'genderResolutionResultHash'
                                <> 'null'::JSONB
                        )
                    )
                    OR pg_catalog.jsonb_typeof(item.value->'preFeaturePolicyVersion')
                        NOT IN ('string', 'null')
                )
            )
           OR (
                pg_catalog.jsonb_typeof(item.value->'preFeaturePolicyVersion')
                    IS DISTINCT FROM 'string'
                AND item.value->>'classification' IN (
                    'verified_female', 'unresolved', 'unresolved_stage_conflict'
                )
                AND (
                    (item.value->>'featureOperationKey'
                        ~ '^feature-analysis:[a-f0-9]{64}$') IS DISTINCT FROM TRUE
                    OR (item.value->>'featureResultHash' ~ '^[a-f0-9]{64}$')
                        IS DISTINCT FROM TRUE
                )
            )
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    PERFORM public.analysis_v2_assert_result_job_fence(
        p_request_id,
        p_job_key,
        p_claim_token,
        p_job_input_hash
    );

    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
        WHERE pg_catalog.jsonb_typeof(item.value->'preFeaturePolicyVersion') = 'string'
          AND (NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_ai_result_checkpoints AS result
                WHERE result.request_id = p_request_id
                  AND result.job_key = p_job_key
                  AND result.operation_key = item.value->>'genderOperationKey'
                  AND result.stage = 'genderTriage'
                  AND result.result_hash = item.value->>'genderResultHash'
          )
                    AND NOT EXISTS (
                        SELECT 1
                        FROM public.analysis_v2_scheduler_operations AS scheduler
                        WHERE scheduler.request_id = p_request_id
                          AND scheduler.job_key = p_job_key
                          AND scheduler.operation_key
                              = item.value->>'genderOperationKey'
                          AND scheduler.stage = 'genderTriage'
                          AND scheduler.status = 'ready'
                          AND public.analysis_v2_gender_scheduler_contains_hash(
                              scheduler.result_json,
                              item.value->>'genderOperationKey',
                              item.value->>'genderResultHash'
                          )
                    ))
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_v2_candidate_feature_manifests AS manifest
    WHERE manifest.request_id = p_request_id
      AND manifest.batch = p_batch
    FOR UPDATE;

    IF FOUND THEN
        PERFORM 1
        FROM public.analysis_v2_candidate_feature_rows AS feature
        WHERE feature.request_id = p_request_id
          AND feature.batch = p_batch
        FOR UPDATE;

        IF EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
            LEFT JOIN public.analysis_v2_candidate_feature_rows AS feature
              ON feature.request_id = p_request_id
             AND feature.batch = p_batch
             AND feature.candidate_id = item.value->>'candidateId'
            WHERE pg_catalog.jsonb_typeof(item.value->'preFeaturePolicyVersion') = 'string'
              AND (
                    feature.candidate_id IS NULL
                    OR feature.terminal_classification IS DISTINCT FROM 'unresolved'
                    OR feature.media_context IS DISTINCT FROM item.value->'mediaContext'
                    OR feature.gender_operation_key
                        IS DISTINCT FROM item.value->>'genderOperationKey'
                    OR feature.gender_result_hash
                        IS DISTINCT FROM item.value->>'genderResultHash'
                    OR feature.baseline_classification IS DISTINCT FROM 'unresolved'
                    OR feature.classification_source IS DISTINCT FROM 'unknown'
                    OR feature.gender_resolution_status IS DISTINCT FROM 'not_eligible'
                    OR feature.gender_resolution_operation_key IS NOT NULL
                    OR feature.gender_resolution_result_hash IS NOT NULL
                    OR feature.pre_feature_policy_version
                        IS DISTINCT FROM item.value->>'preFeaturePolicyVersion'
                    OR feature.pre_feature_admission
                        IS DISTINCT FROM item.value->>'preFeatureAdmission'
              )
        ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_RESULT_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
    END IF;

    SELECT pg_catalog.jsonb_agg(
        CASE
            WHEN pg_catalog.jsonb_typeof(item.value->'preFeaturePolicyVersion') = 'string'
                THEN (
                    item.value - ARRAY[
                        'baselineClassification',
                        'classificationSource',
                        'genderResolutionStatus',
                        'genderResolutionOperationKey',
                        'genderResolutionResultHash',
                        'preFeaturePolicyVersion',
                        'preFeatureAdmission'
                    ]::TEXT[]
                ) || pg_catalog.jsonb_build_object(
                    'classification', 'media_unavailable',
                    'mediaContext', NULL,
                    'genderOperationKey', NULL,
                    'genderResultHash', NULL,
                    'featureOperationKey', NULL,
                    'featureResultHash', NULL,
                    'feature', NULL
                )
            ELSE item.value - ARRAY[
                'baselineClassification',
                'classificationSource',
                'genderResolutionStatus',
                'genderResolutionOperationKey',
                'genderResolutionResultHash',
                'preFeaturePolicyVersion',
                'preFeatureAdmission'
            ]::TEXT[]
        END
        ORDER BY item.value->>'candidateId'
    )
    INTO v_rows
    FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value);

    v_checkpoint := public.analysis_v2_checkpoint_candidate_features_complete_v26(
        p_request_id,
        p_job_key,
        p_claim_token,
        p_job_input_hash,
        p_batch,
        p_analyzed_count,
        v_rows
    );

    UPDATE public.analysis_v2_candidate_feature_rows AS feature
    SET terminal_classification = CASE
            WHEN pg_catalog.jsonb_typeof(item.value->'preFeaturePolicyVersion') = 'string'
                THEN 'unresolved'
            ELSE feature.terminal_classification
        END,
        media_context = CASE
            WHEN pg_catalog.jsonb_typeof(item.value->'preFeaturePolicyVersion') = 'string'
                THEN item.value->'mediaContext'
            ELSE feature.media_context
        END,
        gender_operation_key = CASE
            WHEN pg_catalog.jsonb_typeof(item.value->'preFeaturePolicyVersion') = 'string'
                THEN item.value->>'genderOperationKey'
            ELSE feature.gender_operation_key
        END,
        gender_result_hash = CASE
            WHEN pg_catalog.jsonb_typeof(item.value->'preFeaturePolicyVersion') = 'string'
                THEN item.value->>'genderResultHash'
            ELSE feature.gender_result_hash
        END,
        baseline_classification = COALESCE(
            item.value->>'baselineClassification',
            item.value->>'classification'
        ),
        classification_source = COALESCE(
            item.value->>'classificationSource',
            CASE
                WHEN item.value->>'classification' = 'verified_non_female'
                     AND item.value->'featureOperationKey' = 'null'::JSONB THEN 'triage'
                WHEN item.value->>'classification' IN (
                    'verified_female', 'verified_non_female'
                ) THEN 'feature'
                WHEN item.value->>'classification' IN (
                    'unresolved', 'unresolved_stage_conflict'
                ) THEN 'unknown'
                ELSE 'unavailable'
            END
        ),
        gender_resolution_status = COALESCE(
            item.value->>'genderResolutionStatus',
            'disabled'
        ),
        gender_resolution_operation_key = NULLIF(
            item.value->>'genderResolutionOperationKey',
            ''
        ),
        gender_resolution_result_hash = NULLIF(
            item.value->>'genderResolutionResultHash',
            ''
        ),
        pre_feature_policy_version = CASE
            WHEN pg_catalog.jsonb_typeof(item.value->'preFeaturePolicyVersion') = 'string'
                THEN item.value->>'preFeaturePolicyVersion'
            ELSE NULL
        END,
        pre_feature_admission = CASE
            WHEN pg_catalog.jsonb_typeof(item.value->'preFeatureAdmission') = 'string'
                THEN item.value->>'preFeatureAdmission'
            ELSE NULL
        END
    FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
    WHERE feature.request_id = p_request_id
      AND feature.batch = p_batch
      AND feature.candidate_id = item.value->>'candidateId';

    RETURN v_checkpoint;
END;
$_$;


--
-- Name: analysis_v2_checkpoint_candidate_features_complete_v26(uuid, text, uuid, text, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_checkpoint_candidate_features_complete_v26(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_batch integer, p_analyzed_count integer, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_rows JSONB;
    v_result_hash TEXT;
    v_existing RECORD;
BEGIN
    IF p_batch IS NULL OR p_batch NOT BETWEEN 0 AND 100000
       OR p_analyzed_count IS NULL OR p_analyzed_count NOT BETWEEN 1 AND 30
       OR p_rows IS NULL OR pg_catalog.jsonb_typeof(p_rows) <> 'array'
       OR pg_catalog.jsonb_array_length(p_rows) <> p_analyzed_count
       OR pg_catalog.octet_length(p_rows::TEXT) > 4194304
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR NOT (item.value ?& ARRAY[
                    'candidateId', 'instagramId', 'fullName', 'profileImageUrl', 'bio',
                    'classification', 'mediaContext', 'genderOperationKey',
                    'genderResultHash', 'featureOperationKey', 'featureResultHash', 'feature'
               ])
               OR item.value - ARRAY[
                    'candidateId', 'instagramId', 'fullName', 'profileImageUrl', 'bio',
                    'classification', 'mediaContext', 'genderOperationKey',
                    'genderResultHash', 'featureOperationKey', 'featureResultHash', 'feature'
               ]::TEXT[] <> '{}'::JSONB
               OR item.value->>'candidateId' !~ '^[A-Za-z0-9._:-]{1,128}$'
               OR item.value->>'instagramId' !~ '^[a-z0-9._]{1,30}$'
               OR item.value->>'classification' NOT IN (
                    'verified_female', 'verified_non_female', 'unresolved',
                    'unresolved_stage_conflict', 'media_unavailable', 'unavailable'
               )
               OR pg_catalog.jsonb_typeof(item.value->'fullName') NOT IN ('string', 'null')
               OR pg_catalog.jsonb_typeof(item.value->'profileImageUrl') NOT IN ('string', 'null')
               OR pg_catalog.jsonb_typeof(item.value->'bio') NOT IN ('string', 'null')
               OR (
                    pg_catalog.jsonb_typeof(item.value->'fullName') = 'string'
                    AND item.value->>'fullName' <> ''
                    AND (
                        pg_catalog.char_length(item.value->>'fullName') NOT BETWEEN 1 AND 200
                        OR item.value->>'fullName' ~ '[[:cntrl:]]'
                    )
               )
               OR (
                    pg_catalog.jsonb_typeof(item.value->'bio') = 'string'
                    AND (
                        pg_catalog.char_length(item.value->>'bio') > 2200
                        OR pg_catalog.translate(
                            item.value->>'bio',
                            pg_catalog.chr(10) || pg_catalog.chr(13),
                            ''
                        ) ~ '[[:cntrl:]]'
                    )
               )
               OR (
                    item.value->'profileImageUrl' <> 'null'::JSONB
                    AND NOT public.analysis_v2_result_valid_image_path(
                        item.value->>'profileImageUrl'
                    )
               )
               OR (
                    item.value->>'classification' IN ('unavailable', 'media_unavailable')
                    AND (
                        item.value->'mediaContext' <> 'null'::JSONB
                        OR item.value->'genderOperationKey' <> 'null'::JSONB
                        OR item.value->'genderResultHash' <> 'null'::JSONB
                        OR item.value->'featureOperationKey' <> 'null'::JSONB
                        OR item.value->'featureResultHash' <> 'null'::JSONB
                        OR item.value->'feature' <> 'null'::JSONB
                    )
               )
               OR (
                    item.value->>'classification' NOT IN ('unavailable', 'media_unavailable')
                    AND (
                        NOT public.analysis_v2_result_valid_media_context(item.value->'mediaContext')
                        OR item.value->>'genderOperationKey'
                            !~ '^gender-triage:[a-f0-9]{64}$'
                        OR item.value->>'genderResultHash' !~ '^[a-f0-9]{64}$'
                    )
               )
               OR (
                    item.value->>'classification' IN (
                        'verified_female', 'unresolved', 'unresolved_stage_conflict'
                    )
                    AND (
                        item.value->>'featureOperationKey'
                            !~ '^feature-analysis:[a-f0-9]{64}$'
                        OR item.value->>'featureResultHash' !~ '^[a-f0-9]{64}$'
                    )
               )
               OR (
                    item.value->>'classification' = 'verified_female'
                    AND (
                        pg_catalog.jsonb_typeof(item.value->'feature') <> 'object'
                        OR NOT (item.value->'feature' ?& ARRAY[
                            'appearanceGrade', 'exposureScore', 'isBusinessAccount',
                            'featurePartnerEvidenceStrong', 'oneLineOverview'
                        ])
                        OR (item.value->'feature') - ARRAY[
                            'appearanceGrade', 'exposureScore', 'isBusinessAccount',
                            'featurePartnerEvidenceStrong', 'oneLineOverview'
                        ]::TEXT[] <> '{}'::JSONB
                        OR item.value->'feature'->>'appearanceGrade' !~ '^[1-5]$'
                        OR item.value->'feature'->>'exposureScore' !~ '^[0-5]$'
                        OR pg_catalog.jsonb_typeof(
                            item.value->'feature'->'isBusinessAccount'
                        ) <> 'boolean'
                        OR pg_catalog.jsonb_typeof(
                            item.value->'feature'->'featurePartnerEvidenceStrong'
                        ) <> 'boolean'
                        OR NOT public.analysis_v2_result_valid_public_copy(
                            item.value->'feature'->>'oneLineOverview', 180
                        )
                    )
               )
               OR (
                    item.value->>'classification' <> 'verified_female'
                    AND item.value->'feature' <> 'null'::JSONB
               )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;

    v_job := public.analysis_v2_assert_result_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    IF v_job.job_key <> 'track:profile-ai:batch:' || p_batch::TEXT
       OR v_job.track <> 'profile_ai' OR v_job.kind <> 'ai'
       OR v_job.batch IS DISTINCT FROM p_batch THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT analysis_request.* INTO STRICT v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id;

    IF NOT EXISTS (
        SELECT 1 FROM public.analysis_v2_dag_batch_topology AS topology
        WHERE topology.request_id = p_request_id
          AND topology.topology_kind = 'profile'
          AND topology.batch = p_batch
          AND topology.item_count = p_analyzed_count
    ) OR NOT EXISTS (
        SELECT 1 FROM public.analysis_v2_dag_batch_results AS batch_result
        WHERE batch_result.request_id = p_request_id
          AND batch_result.result_kind = 'profile_fetch'
          AND batch_result.batch = p_batch
          AND batch_result.item_count = p_analyzed_count
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.jsonb_agg(item.value ORDER BY item.value->>'candidateId')
    INTO v_rows
    FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value);
    IF (
        SELECT pg_catalog.count(DISTINCT item.value->>'candidateId') <> p_analyzed_count
            OR pg_catalog.count(DISTINCT item.value->>'instagramId') <> p_analyzed_count
        FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
    ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
        WHERE item.value->>'instagramId' = pg_catalog.lower(v_request.target_instagram_id)
           OR item.value->>'instagramId' = v_request.excluded_instagram_id
           OR NOT EXISTS (
                SELECT 1 FROM public.analysis_v2_mutual_rows AS mutual
                WHERE mutual.request_id = p_request_id
                  AND mutual.job_key = 'track:relationships:collect'
                  AND mutual.username = item.value->>'instagramId'
                  AND NOT mutual.is_private
                  AND mutual.detailed_ordinal IS NOT NULL
           )
           OR (
                item.value->>'classification' NOT IN ('unavailable', 'media_unavailable')
                AND (
                    (NOT EXISTS (
                        SELECT 1 FROM public.analysis_v2_ai_result_checkpoints AS ai_result
                        WHERE ai_result.request_id = p_request_id
                          AND ai_result.job_key = p_job_key
                          AND ai_result.operation_key = item.value->>'genderOperationKey'
                          AND ai_result.stage = 'genderTriage'
                          AND ai_result.result_hash = item.value->>'genderResultHash'
                    )
                    AND NOT EXISTS (
                        SELECT 1
                        FROM public.analysis_v2_scheduler_operations AS scheduler
                        WHERE scheduler.request_id = p_request_id
                          AND scheduler.job_key = p_job_key
                          AND scheduler.operation_key
                              = item.value->>'genderOperationKey'
                          AND scheduler.stage = 'genderTriage'
                          AND scheduler.status = 'ready'
                          AND public.analysis_v2_gender_scheduler_contains_hash(
                              scheduler.result_json,
                              item.value->>'genderOperationKey',
                              item.value->>'genderResultHash'
                          )
                    ))
                    OR (
                        item.value->'featureOperationKey' <> 'null'::JSONB
                        AND NOT EXISTS (
                            SELECT 1 FROM public.analysis_v2_ai_result_checkpoints AS ai_result
                            WHERE ai_result.request_id = p_request_id
                              AND ai_result.job_key = p_job_key
                              AND ai_result.operation_key = item.value->>'featureOperationKey'
                              AND ai_result.stage = 'featureAnalysis'
                              AND ai_result.result_hash = item.value->>'featureResultHash'
                        )
                    )
                    OR (
                        item.value->>'classification' = 'verified_female'
                        AND NOT EXISTS (
                            SELECT 1
                            FROM public.analysis_v2_media_artifacts AS artifact
                            WHERE artifact.request_id = p_request_id
                              AND artifact.artifact_kind = 'media_bundle'
                              AND artifact.artifact_key = pg_catalog.encode(
                                  extensions.digest(
                                      pg_catalog.convert_to(
                                          'analysis-v2-media-bundle-key:v1'
                                              || pg_catalog.chr(10)
                                              || (item.value->'mediaContext'->>'bundleId'),
                                          'UTF8'
                                      ),
                                      'sha256'
                                  ),
                                  'hex'
                              )
                        )
                    )
                )
           )
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    v_result_hash := public.analysis_v2_result_staging_hash(
        'profile_classifications', p_batch, v_rows
    );
    SELECT manifest.* INTO v_existing
    FROM public.analysis_v2_candidate_feature_manifests AS manifest
    WHERE manifest.request_id = p_request_id AND manifest.batch = p_batch
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.producer_job_key <> p_job_key
           OR v_existing.producer_input_hash <> p_job_input_hash
           OR v_existing.producer_claim_token <> p_claim_token
           OR v_existing.item_count <> p_analyzed_count
           OR v_existing.row_count <> p_analyzed_count
           OR v_existing.result_hash <> v_result_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_result_checkpoint_json(
            p_request_id, p_job_key, p_batch, p_analyzed_count,
            p_analyzed_count, v_result_hash
        );
    END IF;

    INSERT INTO public.analysis_v2_candidate_feature_manifests (
        request_id, batch, producer_job_key, producer_input_hash,
        producer_claim_token, item_count, row_count, result_hash
    ) VALUES (
        p_request_id, p_batch, p_job_key, p_job_input_hash,
        p_claim_token, p_analyzed_count, p_analyzed_count, v_result_hash
    );
    INSERT INTO public.analysis_v2_candidate_feature_rows (
        request_id, batch, candidate_id, instagram_id, full_name, profile_image_url, bio,
        terminal_classification, media_context, appearance_grade, exposure_score,
        is_business_account, feature_partner_evidence_strong, one_line_overview,
        gender_operation_key, gender_result_hash, feature_operation_key, feature_result_hash
    )
    SELECT
        p_request_id,
        p_batch,
        item.value->>'candidateId',
        item.value->>'instagramId',
        NULLIF(item.value->>'fullName', ''),
        NULLIF(item.value->>'profileImageUrl', ''),
        NULLIF(item.value->>'bio', ''),
        item.value->>'classification',
        CASE WHEN item.value->'mediaContext' = 'null'::JSONB
            THEN NULL ELSE item.value->'mediaContext' END,
        CASE WHEN item.value->'feature' = 'null'::JSONB
            THEN NULL ELSE (item.value->'feature'->>'appearanceGrade')::SMALLINT END,
        CASE WHEN item.value->'feature' = 'null'::JSONB
            THEN NULL ELSE (item.value->'feature'->>'exposureScore')::SMALLINT END,
        CASE WHEN item.value->'feature' = 'null'::JSONB
            THEN NULL ELSE (item.value->'feature'->>'isBusinessAccount')::BOOLEAN END,
        CASE WHEN item.value->'feature' = 'null'::JSONB
            THEN NULL ELSE (item.value->'feature'->>'featurePartnerEvidenceStrong')::BOOLEAN END,
        CASE WHEN item.value->'feature' = 'null'::JSONB
            THEN NULL ELSE item.value->'feature'->>'oneLineOverview' END,
        NULLIF(item.value->>'genderOperationKey', ''),
        NULLIF(item.value->>'genderResultHash', ''),
        NULLIF(item.value->>'featureOperationKey', ''),
        NULLIF(item.value->>'featureResultHash', '')
    FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value);

    RETURN public.analysis_v2_result_checkpoint_json(
        p_request_id, p_job_key, p_batch, p_analyzed_count,
        p_analyzed_count, v_result_hash
    );
END;
$_$;


--
-- Name: analysis_v2_complete_result_and_purge_before_v28_tone(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_complete_result_and_purge_before_v28_tone(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_target_profile_image_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_analysis_unavailable_count INTEGER := 0;
    v_result JSONB;
    v_summary public.analysis_v2_result_summaries%ROWTYPE;
BEGIN
    IF pg_catalog.to_regclass(
        'public.analysis_v2_ai_scoring_stage_checkpoints'
    ) IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    PERFORM 1 FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id FOR UPDATE;
    PERFORM 1 FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id FOR UPDATE;
    PERFORM 1 FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    IF EXISTS (
        SELECT 1 FROM public.analysis_v2_provider_cleanup_intents AS intent
        WHERE intent.request_id = p_request_id AND intent.completed_at IS NULL
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_REQUIRED', ERRCODE = 'P0001';
    END IF;
    IF EXISTS (
        SELECT 1 FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = p_request_id
          AND provider_run.status IN ('starting', 'running')
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_REQUIRED', ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.analysis_v2_candidate_feature_rows AS feature
        WHERE feature.request_id = p_request_id
          AND feature.terminal_classification = 'unavailable'
          AND NOT (
            (
                feature.unavailable_reason = 'profile_fetch'
                AND EXISTS (
                    SELECT 1
                    FROM public.analysis_v2_profile_fetch_batches AS profile_batch
                    JOIN public.analysis_v2_profile_fetch_outcomes AS outcome
                      ON outcome.request_id = profile_batch.request_id
                     AND outcome.job_key = profile_batch.job_key
                     AND outcome.username = feature.instagram_id
                     AND outcome.attempt =
                        public.analysis_v2_profile_terminal_attempt(
                            profile_batch.request_id,
                            profile_batch.job_key,
                            feature.instagram_id,
                            profile_batch.frozen_unresolved_usernames
                        )
                    WHERE profile_batch.request_id = p_request_id
                      AND profile_batch.job_key = 'track:profiles:batch:'
                            || feature.batch::TEXT
                      AND outcome.status <> 'success'
                )
            )
            OR (
                feature.unavailable_reason = 'ai_response'
                AND EXISTS (
                    SELECT 1
                    FROM public.analysis_v2_profile_fetch_batches AS profile_batch
                    JOIN public.analysis_v2_profile_fetch_outcomes AS outcome
                      ON outcome.request_id = profile_batch.request_id
                     AND outcome.job_key = profile_batch.job_key
                     AND outcome.username = feature.instagram_id
                     AND outcome.attempt =
                        public.analysis_v2_profile_terminal_attempt(
                            profile_batch.request_id,
                            profile_batch.job_key,
                            feature.instagram_id,
                            profile_batch.frozen_unresolved_usernames
                        )
                    WHERE profile_batch.request_id = p_request_id
                      AND profile_batch.job_key = 'track:profiles:batch:'
                            || feature.batch::TEXT
                      AND outcome.status = 'success'
                )
                AND EXISTS (
                    SELECT 1
                    FROM public.analysis_v2_ai_scoring_stage_checkpoints AS rich_stage
                    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
                        rich_stage.payload->'outcomes'
                    ) AS rich_outcome(value)
                    WHERE rich_stage.request_id = p_request_id
                      AND rich_stage.stage_kind = 'profile_ai_batch'
                      AND rich_stage.batch_key = feature.batch
                      AND rich_outcome.value->>'candidateId' = feature.candidate_id
                      AND rich_outcome.value->>'instagramId' = feature.instagram_id
                      AND rich_outcome.value->>'status' = 'analysis_unavailable'
                )
            )
          )
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.count(*)::INTEGER INTO v_analysis_unavailable_count
    FROM public.analysis_v2_candidate_feature_rows AS feature
    WHERE feature.request_id = p_request_id
      AND feature.terminal_classification = 'unavailable'
      AND feature.unavailable_reason = 'ai_response';

    UPDATE public.analysis_v2_candidate_feature_rows AS feature
    SET terminal_classification = 'media_unavailable',
        unavailable_reason = NULL
    WHERE feature.request_id = p_request_id
      AND feature.terminal_classification = 'unavailable'
      AND feature.unavailable_reason = 'ai_response';

    v_result := public.analysis_v2_complete_result_and_purge_internal(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash,
        p_target_profile_image_url
    );

    IF v_analysis_unavailable_count > 0 THEN
        UPDATE public.analysis_v2_result_summaries AS summary
        SET media_unavailable_count = summary.media_unavailable_count
                - v_analysis_unavailable_count,
            analysis_unavailable_count = v_analysis_unavailable_count
        WHERE summary.request_id = p_request_id
        RETURNING summary.* INTO v_summary;
        IF v_summary.request_id IS NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
        END IF;
        v_result := pg_catalog.jsonb_set(
            v_result,
            ARRAY['summary'],
            public.analysis_v2_result_summary_json(v_summary),
            TRUE
        );
    END IF;
    RETURN v_result;
END;
$$;


--
-- Name: analysis_v2_complete_result_and_purge_internal(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_complete_result_and_purge_internal(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_target_profile_image_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_summary public.analysis_v2_result_summaries%ROWTYPE;
    v_relationship public.analysis_v2_relationship_manifests%ROWTYPE;
    v_followers public.analysis_v2_relationship_sides%ROWTYPE;
    v_following public.analysis_v2_relationship_sides%ROWTYPE;
    v_progress public.analysis_progress_state%ROWTYPE;
    v_tracks JSONB;
    v_revision BIGINT;
    v_sequence BIGINT;
    v_fingerprint TEXT;
    v_event_key TEXT;
    v_profile_count INTEGER;
    v_private_count INTEGER;
    v_verified_count INTEGER;
BEGIN
    IF p_request_id IS NULL OR p_job_key IS DISTINCT FROM 'coordinator:finalize'
       OR p_claim_token IS NULL OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR NOT public.analysis_v2_result_valid_image_path(p_target_profile_image_url) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;
    IF pg_catalog.to_regclass(
        'public.analysis_v2_ai_scoring_stage_checkpoints'
    ) IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id FOR UPDATE;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    IF v_preflight.id IS NULL OR v_request.id IS NULL OR v_job.request_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    IF v_request.status = 'completed' THEN
        SELECT summary.* INTO v_summary
        FROM public.analysis_v2_result_summaries AS summary
        WHERE summary.request_id = p_request_id;
        IF v_job.status <> 'completed'
           OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
           OR v_job.completion_token IS DISTINCT FROM p_claim_token
           OR v_summary.request_id IS NULL
           OR v_summary.finalizer_input_hash IS DISTINCT FROM p_job_input_hash
           OR v_summary.target_profile_image_url IS DISTINCT FROM p_target_profile_image_url THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'finalized', FALSE,
            'requestStatus', 'completed',
            'summary', public.analysis_v2_result_summary_json(v_summary)
        );
    END IF;
    IF v_request.status NOT IN ('pending', 'processing')
       OR v_job.track <> 'coordinator' OR v_job.kind <> 'finalizer'
       OR v_job.batch IS NOT NULL OR v_job.status <> 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF pg_catalog.cardinality(v_job.required_job_keys) < 1
       OR EXISTS (
            SELECT 1 FROM public.analysis_pipeline_jobs AS sibling
            WHERE sibling.request_id = p_request_id
              AND sibling.job_key <> p_job_key AND sibling.status <> 'completed'
       ) OR EXISTS (
            SELECT 1
            FROM pg_catalog.unnest(v_job.required_job_keys) AS required_key(value)
            LEFT JOIN public.analysis_pipeline_jobs AS required_job
              ON required_job.request_id = p_request_id
             AND required_job.job_key = required_key.value
            WHERE required_job.request_id IS NULL OR required_job.status <> 'completed'
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT relationship_manifest.* INTO v_relationship
    FROM public.analysis_v2_relationship_manifests AS relationship_manifest
    WHERE relationship_manifest.request_id = p_request_id
      AND relationship_manifest.job_key = 'track:relationships:collect';
    SELECT side.* INTO v_followers
    FROM public.analysis_v2_relationship_sides AS side
    WHERE side.request_id = p_request_id
      AND side.job_key = 'track:relationships:collect' AND side.side = 'followers';
    SELECT side.* INTO v_following
    FROM public.analysis_v2_relationship_sides AS side
    WHERE side.request_id = p_request_id
      AND side.job_key = 'track:relationships:collect' AND side.side = 'following';

    IF v_relationship.request_id IS NULL OR v_followers.request_id IS NULL
       OR v_following.request_id IS NULL
       OR v_preflight.target_followers_count IS DISTINCT FROM v_followers.declared_count
       OR v_preflight.target_following_count IS DISTINCT FROM v_following.declared_count
       OR v_followers.collected_count * 100 < v_followers.declared_count * 99
       OR v_following.collected_count * 100 < v_following.declared_count * 99
       OR v_relationship.followers_result_hash <> v_followers.result_hash
       OR v_relationship.following_result_hash <> v_following.result_hash
       OR v_relationship.excluded_username IS DISTINCT FROM v_request.excluded_instagram_id
       OR v_relationship.detailed_mutual_limit IS DISTINCT FROM
            (v_request.analysis_scope_snapshot->>'detailedMutualLimit')::INTEGER
       OR v_relationship.detailed_public_count <> LEAST(
            v_relationship.public_count, v_relationship.detailed_mutual_limit
       ) OR v_request.selected_plan_id_snapshot NOT IN ('basic', 'standard', 'plus')
       OR (v_request.policy_versions_snapshot->>'risk' IS NULL OR v_request.policy_versions_snapshot->>'risk' NOT IN ('risk-policy-v2.3', 'risk-policy-v2.4', 'risk-policy-v2.5'))
       OR NOT EXISTS (
            SELECT 1 FROM public.analysis_v2_dag_scopes AS scope
            WHERE scope.request_id = p_request_id
              AND scope.plan_id = v_request.selected_plan_id_snapshot
              AND scope.excluded_count = CASE
                    WHEN v_request.exclusion_decision_snapshot = 'exclude' THEN 1 ELSE 0 END
              AND 
scope.exclusion_decision_hash = public.analysis_v2_dag_hash_json(
                    pg_catalog.jsonb_build_object(
                        'domain', 'analysis-v2-exclusion-decision-v1',
                        'requestId', p_request_id,
                        'decision', v_request.exclusion_decision_snapshot,
                        'excludedInstagramId', v_request.excluded_instagram_id
                    )
              )
       ) OR (
            SELECT pg_catalog.count(*)
            FROM public.analysis_v2_dag_stage_manifests AS stage
            WHERE stage.request_id = p_request_id
       ) <> 8
       OR NOT EXISTS (
            SELECT 1 FROM public.analysis_v2_dag_stage_manifests AS stage
            WHERE stage.request_id = p_request_id AND stage.stage_kind = 'relationships'
              AND stage.result_hash = v_relationship.result_hash
              AND stage.detected_mutual_count = v_relationship.mutual_count
              AND stage.public_count = v_relationship.public_count
              AND stage.private_count = v_relationship.private_count
              AND stage.detailed_selected_public_count = v_relationship.detailed_public_count
       ) OR NOT EXISTS (
            SELECT 1
            FROM public.analysis_v2_target_evidence_manifests AS evidence
            JOIN public.analysis_v2_dag_stage_manifests AS stage
              ON stage.request_id = evidence.request_id
             AND stage.stage_kind = 'target_evidence'
             AND stage.result_hash = evidence.result_hash
             AND stage.interactor_count = evidence.interactor_count
            WHERE evidence.request_id = p_request_id
              AND evidence.job_key = 'track:target-evidence:collect'
              AND evidence.target_username = pg_catalog.lower(v_request.target_instagram_id)
              AND evidence.excluded_username IS NOT DISTINCT FROM v_request.excluded_instagram_id
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(pg_catalog.sum(topology.item_count), 0)::INTEGER INTO v_profile_count
    FROM public.analysis_v2_dag_batch_topology AS topology
    WHERE topology.request_id = p_request_id AND topology.topology_kind = 'profile';
    SELECT COALESCE(pg_catalog.sum(topology.item_count), 0)::INTEGER INTO v_private_count
    FROM public.analysis_v2_dag_batch_topology AS topology
    WHERE topology.request_id = p_request_id AND topology.topology_kind = 'private_name';
    SELECT pg_catalog.count(*)::INTEGER INTO v_verified_count
    FROM public.analysis_v2_candidate_feature_rows AS feature
    WHERE feature.request_id = p_request_id
      AND feature.terminal_classification = 'verified_female';

    IF v_profile_count <> v_relationship.detailed_public_count
       OR v_private_count <> v_relationship.private_count
       OR v_profile_count <> (
            SELECT pg_catalog.count(*) FROM public.analysis_v2_candidate_feature_rows AS feature
            WHERE feature.request_id = p_request_id
       ) OR v_private_count <> (
            SELECT pg_catalog.count(*) FROM public.analysis_v2_private_name_rows AS private_name
            WHERE private_name.request_id = p_request_id
       ) OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_dag_batch_topology AS topology
            LEFT JOIN public.analysis_v2_dag_batch_results AS fetch_result
              ON fetch_result.request_id = topology.request_id
             AND fetch_result.result_kind = 'profile_fetch'
             AND fetch_result.batch = topology.batch
             AND fetch_result.item_count = topology.item_count
            LEFT JOIN public.analysis_v2_dag_batch_results AS ai_result
              ON ai_result.request_id = topology.request_id
             AND ai_result.result_kind = 'profile_ai'
             AND ai_result.batch = topology.batch
             AND ai_result.item_count = topology.item_count
            LEFT JOIN public.analysis_v2_candidate_feature_manifests AS feature_manifest
              ON feature_manifest.request_id = topology.request_id
             AND feature_manifest.batch = topology.batch
             AND feature_manifest.item_count = topology.item_count
             AND feature_manifest.row_count = topology.item_count
             AND feature_manifest.producer_input_hash = ai_result.producer_input_hash
            LEFT JOIN public.analysis_v2_ai_scoring_stage_checkpoints AS rich_stage
              ON rich_stage.request_id = topology.request_id
             AND rich_stage.stage_kind = 'profile_ai_batch'
             AND rich_stage.batch_key = topology.batch
             AND rich_stage.producer_input_hash = ai_result.producer_input_hash
             AND rich_stage.result_hash = ai_result.result_hash
             AND rich_stage.item_count = topology.item_count
            WHERE topology.request_id = p_request_id
              AND topology.topology_kind = 'profile'
              AND (fetch_result.request_id IS NULL OR ai_result.request_id IS NULL
                OR feature_manifest.request_id IS NULL OR rich_stage.request_id IS NULL)
       ) OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_dag_batch_topology AS topology
            LEFT JOIN public.analysis_v2_dag_batch_results AS private_result
              ON private_result.request_id = topology.request_id
             AND private_result.result_kind = 'private_name'
             AND private_result.batch = topology.batch
             AND private_result.item_count = topology.item_count
            LEFT JOIN public.analysis_v2_private_name_manifests AS private_manifest
              ON private_manifest.request_id = topology.request_id
             AND private_manifest.batch = topology.batch
             AND private_manifest.item_count = topology.item_count
             AND private_manifest.producer_input_hash = private_result.producer_input_hash
             AND private_manifest.result_hash = private_result.result_hash
            WHERE topology.request_id = p_request_id
              AND topology.topology_kind = 'private_name'
              AND (private_result.request_id IS NULL OR private_manifest.request_id IS NULL)
       ) OR EXISTS (
            SELECT 1 FROM public.analysis_v2_candidate_feature_rows AS feature
            WHERE feature.request_id = p_request_id
              AND (
                feature.candidate_id <> public.analysis_v2_result_candidate_id(feature.instagram_id)
                OR feature.instagram_id = pg_catalog.lower(v_request.target_instagram_id)
                OR feature.instagram_id = v_request.excluded_instagram_id
                OR NOT EXISTS (
                    SELECT 1 FROM public.analysis_v2_mutual_rows AS mutual
                    WHERE mutual.request_id = p_request_id
                      AND mutual.job_key = 'track:relationships:collect'
                      AND mutual.username = feature.instagram_id
                      AND NOT mutual.is_private AND mutual.detailed_ordinal IS NOT NULL
                )
                OR NOT EXISTS (
                    SELECT 1
                    FROM public.analysis_v2_profile_fetch_batches AS profile_batch
                    JOIN public.analysis_v2_profile_fetch_outcomes AS outcome
                      ON outcome.request_id = profile_batch.request_id
                     AND outcome.job_key = profile_batch.job_key
                     AND outcome.username = feature.instagram_id
                     AND outcome.attempt =
                        public.analysis_v2_profile_terminal_attempt(
                            profile_batch.request_id,
                            profile_batch.job_key,
                            feature.instagram_id,
                            profile_batch.frozen_unresolved_usernames
                        )
                    WHERE profile_batch.request_id = p_request_id
                      AND profile_batch.job_key = 'track:profiles:batch:'
                            || feature.batch::TEXT
                      AND (
                        (
                            feature.terminal_classification = 'unavailable'
                            AND outcome.status <> 'success'
                        )
                        OR (
                            feature.terminal_classification = 'media_unavailable'
                            AND outcome.status = 'success'
                        )
                        OR (
                            feature.terminal_classification NOT IN (
                                'unavailable', 'media_unavailable'
                            )
                            AND outcome.status = 'success'
                        )
                      )
                )
              )
       ) OR EXISTS (
            SELECT 1 FROM public.analysis_v2_private_name_rows AS private_name
            WHERE private_name.request_id = p_request_id
              AND (
                private_name.candidate_id <>
                    public.analysis_v2_result_candidate_id(private_name.instagram_id)
                OR private_name.instagram_id = pg_catalog.lower(v_request.target_instagram_id)
                OR private_name.instagram_id = v_request.excluded_instagram_id
                OR NOT EXISTS (
                    SELECT 1 FROM public.analysis_v2_mutual_rows AS mutual
                    WHERE mutual.request_id = p_request_id
                      AND mutual.job_key = 'track:relationships:collect'
                      AND mutual.username = private_name.instagram_id AND mutual.is_private
                )
              )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.analysis_v2_dag_stage_manifests AS primary_join
        JOIN public.analysis_v2_ai_scoring_stage_checkpoints AS primary_rich
          ON primary_rich.request_id = primary_join.request_id
         AND primary_rich.stage_kind = 'primary_join' AND primary_rich.batch_key = -1
         AND primary_rich.producer_input_hash = primary_join.producer_input_hash
         AND primary_rich.result_hash = primary_join.result_hash
        JOIN public.analysis_v2_dag_stage_manifests AS screening
          ON screening.request_id = primary_join.request_id
         AND screening.stage_kind = 'screening'
        JOIN public.analysis_v2_ai_scoring_stage_checkpoints AS screening_rich
          ON screening_rich.request_id = screening.request_id
         AND screening_rich.stage_kind = 'screening' AND screening_rich.batch_key = -1
         AND screening_rich.producer_input_hash = screening.producer_input_hash
         AND screening_rich.result_hash = screening.result_hash
        JOIN public.analysis_v2_preliminary_score_manifests AS preliminary
          ON preliminary.request_id = primary_join.request_id
         AND preliminary.producer_input_hash = screening.producer_input_hash
         AND preliminary.item_count = screening.verified_female_count
        WHERE primary_join.request_id = p_request_id
          AND primary_join.stage_kind = 'primary_join'
          AND primary_join.verified_female_count = v_verified_count
          AND screening.verified_female_count = v_verified_count
          AND screening.shortlist_count = (
                SELECT pg_catalog.count(*)
                FROM public.analysis_v2_preliminary_score_rows AS score
                WHERE score.request_id = p_request_id
                  AND score.verification_shortlist_rank IS NOT NULL
          )
    ) OR NOT EXISTS (
        SELECT 1 FROM public.analysis_v2_dag_stage_manifests AS stage
        JOIN public.analysis_v2_ai_scoring_stage_checkpoints AS rich_stage
          ON rich_stage.request_id = stage.request_id
         AND rich_stage.stage_kind = 'reverse_likes' AND rich_stage.batch_key = -1
         AND rich_stage.producer_input_hash = stage.producer_input_hash
         AND rich_stage.result_hash = stage.result_hash
        JOIN public.analysis_v2_reverse_like_manifests AS manifest
          ON manifest.request_id = stage.request_id
         AND manifest.producer_input_hash = stage.producer_input_hash
        WHERE stage.request_id = p_request_id AND stage.stage_kind = 'reverse_likes'
          AND stage.shortlist_count = (
                SELECT pg_catalog.count(*)
                FROM public.analysis_v2_preliminary_score_rows AS preliminary
                WHERE preliminary.request_id = p_request_id
                  AND preliminary.verification_shortlist_rank IS NOT NULL
          )
    ) OR NOT EXISTS (
        SELECT 1 FROM public.analysis_v2_dag_stage_manifests AS stage
        JOIN public.analysis_v2_ai_scoring_stage_checkpoints AS rich_stage
          ON rich_stage.request_id = stage.request_id
         AND rich_stage.stage_kind = 'partner_safety' AND rich_stage.batch_key = -1
         AND rich_stage.producer_input_hash = stage.producer_input_hash
         AND rich_stage.result_hash = stage.result_hash
        JOIN public.analysis_v2_partner_safety_manifests AS manifest
          ON manifest.request_id = stage.request_id
         AND manifest.producer_input_hash = stage.producer_input_hash
        WHERE stage.request_id = p_request_id AND stage.stage_kind = 'partner_safety'
          AND stage.shortlist_count = (
                SELECT pg_catalog.count(*)
                FROM public.analysis_v2_preliminary_score_rows AS preliminary
                WHERE preliminary.request_id = p_request_id
                  AND preliminary.verification_shortlist_rank IS NOT NULL
          )
    ) OR NOT EXISTS (
        SELECT 1 FROM public.analysis_v2_dag_stage_manifests AS final_stage
        JOIN public.analysis_v2_ai_scoring_stage_checkpoints AS final_rich
          ON final_rich.request_id = final_stage.request_id
         AND final_rich.stage_kind = 'final_score' AND final_rich.batch_key = -1
         AND final_rich.producer_input_hash = final_stage.producer_input_hash
         AND final_rich.result_hash = final_stage.result_hash
        JOIN public.analysis_v2_candidate_score_manifests AS score_manifest
          ON score_manifest.request_id = final_stage.request_id
         AND score_manifest.producer_input_hash = final_stage.producer_input_hash
        JOIN public.analysis_v2_dag_stage_manifests AS narrative_stage
          ON narrative_stage.request_id = final_stage.request_id
         AND narrative_stage.stage_kind = 'narrative'
        JOIN public.analysis_v2_ai_scoring_stage_checkpoints AS narrative_rich
          ON narrative_rich.request_id = narrative_stage.request_id
         AND narrative_rich.stage_kind = 'narrative' AND narrative_rich.batch_key = -1
         AND narrative_rich.producer_input_hash = narrative_stage.producer_input_hash
         AND narrative_rich.result_hash = narrative_stage.result_hash
        JOIN public.analysis_v2_narrative_manifests AS narrative_manifest
          ON narrative_manifest.request_id = final_stage.request_id
         AND narrative_manifest.producer_input_hash = narrative_stage.producer_input_hash
        WHERE final_stage.request_id = p_request_id
          AND final_stage.stage_kind = 'final_score'
          AND score_manifest.item_count = v_verified_count
          AND final_stage.featured_high_risk_count = narrative_manifest.item_count
          AND final_stage.narrative_count = narrative_manifest.item_count
          AND narrative_stage.narrative_count = narrative_manifest.item_count
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT progress_state.* INTO v_progress
    FROM public.analysis_progress_state AS progress_state
    WHERE progress_state.request_id = p_request_id FOR UPDATE;
    IF v_progress.request_id IS NULL
       OR v_progress.status NOT IN ('queued', 'processing')
       OR EXISTS (
            SELECT 1 FROM public.analysis_progress_events AS progress_event
            WHERE progress_event.request_id = p_request_id
              AND progress_event.event_code = 'ANALYSIS_COMPLETED'
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.analysis_v2_result_summaries (
        request_id, target_instagram_id, target_profile_image_url, plan_id,
        followers_declared, followers_collected, following_declared, following_collected,
        detected_mutuals, public_mutuals, private_mutuals, screened_mutuals,
        not_screened_mutuals, fetch_unavailable_count, media_unavailable_count,
        exclusion_applied, score_policy_version,
        finalizer_input_hash
    ) VALUES (
        p_request_id, pg_catalog.lower(v_request.target_instagram_id),
        p_target_profile_image_url, v_request.selected_plan_id_snapshot,
        v_followers.declared_count, v_followers.collected_count,
        v_following.declared_count, v_following.collected_count,
        v_relationship.mutual_count, v_relationship.public_count,
        v_relationship.private_count, v_relationship.detailed_public_count,
        v_relationship.public_count - v_relationship.detailed_public_count,
        (SELECT pg_catalog.count(*) FROM public.analysis_v2_candidate_feature_rows AS feature
            WHERE feature.request_id = p_request_id
              AND feature.terminal_classification = 'unavailable'),
        (SELECT pg_catalog.count(*) FROM public.analysis_v2_candidate_feature_rows AS feature
            WHERE feature.request_id = p_request_id
              AND feature.terminal_classification = 'media_unavailable'),
        v_request.exclusion_decision_snapshot = 'exclude',
        v_request.policy_versions_snapshot->>'risk',
        p_job_input_hash
    ) RETURNING * INTO v_summary;

    INSERT INTO public.analysis_v2_female_results (
        request_id, candidate_id, sort_ordinal, instagram_id, full_name,
        profile_image_url, bio, display_score, risk_band, featured_rank,
        recent_mutual_rank, analysis_depth, one_line_overview,
        narrative_line_one, narrative_line_two
    )
    SELECT p_request_id, ordered.candidate_id, ordered.sort_ordinal,
        ordered.instagram_id, ordered.full_name, ordered.profile_image_url, ordered.bio,
        ordered.display_score, ordered.risk_band, ordered.featured_rank,
        ordered.recent_mutual_rank,
        CASE WHEN ordered.line_one IS NULL THEN 'features' ELSE 'narrative' END,
        ordered.one_line_overview, ordered.line_one, ordered.line_two
    FROM (
        SELECT feature.candidate_id, feature.instagram_id, feature.full_name,
            feature.profile_image_url, feature.bio, score.display_score, score.risk_band,
            
score.featured_rank, score.recent_mutual_rank,
            CASE
                WHEN pg_catalog.count(*) OVER (
                    PARTITION BY feature.one_line_overview
                ) > 1 THEN
                    public.analysis_v2_relative_overview_fallback(
                        pg_catalog.row_number() OVER (
                            PARTITION BY feature.one_line_overview
                            ORDER BY feature.candidate_id
                        )::INTEGER
                    )
                ELSE feature.one_line_overview
            END AS one_line_overview,
            narrative.line_one, narrative.line_two,
            pg_catalog.row_number() OVER (
                ORDER BY score.display_score DESC, feature.candidate_id
            )::SMALLINT AS sort_ordinal
        FROM public.analysis_v2_candidate_feature_rows AS feature
        JOIN public.analysis_v2_candidate_score_rows AS score
          ON score.request_id = feature.request_id
         AND score.candidate_id = feature.candidate_id
        LEFT JOIN public.analysis_v2_narrative_rows AS narrative
          ON narrative.request_id = feature.request_id
         AND narrative.candidate_id = feature.candidate_id
        WHERE feature.request_id = p_request_id
          AND feature.terminal_classification = 'verified_female'
    ) AS ordered;

    INSERT INTO public.analysis_v2_private_results (
        request_id, candidate_id, sort_ordinal, instagram_id, full_name, profile_image_url
    )
    SELECT p_request_id, private_name.candidate_id,
        pg_catalog.row_number() OVER (
            ORDER BY private_name.name_female_score DESC,
                private_name.name_confidence DESC, private_name.instagram_id
        )::SMALLINT,
        private_name.instagram_id, private_name.full_name, private_name.profile_image_url
    FROM public.analysis_v2_private_name_rows AS private_name
    WHERE private_name.request_id = p_request_id;

    IF (SELECT pg_catalog.count(*) FROM public.analysis_v2_female_results AS female
        WHERE female.request_id = p_request_id) <> v_verified_count
       OR (SELECT pg_catalog.count(*) FROM public.analysis_v2_private_results AS private_result
        WHERE private_result.request_id = p_request_id) <> v_relationship.private_count THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    v_tracks := pg_catalog.jsonb_build_object(
        'relationshipAi', pg_catalog.jsonb_build_object(
            'state', 'completed',
            'stageCode', v_progress.tracks->'relationshipAi'->>'stageCode',
            'done', (v_progress.tracks->'relationshipAi'->>'total')::INTEGER,
            'total', (v_progress.tracks->'relationshipAi'->>'total')::INTEGER,
            'progressBp', CASE WHEN (v_progress.tracks->'relationshipAi'->>'total')::INTEGER = 0
                THEN 0 ELSE 10000 END
        ),
        'interactions', pg_catalog.jsonb_build_object(
            'state', 'completed',
            'stageCode', v_progress.tracks->'interactions'->>'stageCode',
            'done', (v_progress.tracks->'interactions'->>'total')::INTEGER,
            'total', (v_progress.tracks->'interactions'->>'total')::INTEGER,
            'progressBp', CASE WHEN (v_progress.tracks->'interactions'->>'total')::INTEGER = 0
                THEN 0 ELSE 10000 END
        ),
        'finalization', pg_catalog.jsonb_build_object(
            'state', 'completed',
            'stageCode', v_progress.tracks->'finalization'->>'stageCode',
            'done', (v_progress.tracks->'finalization'->>'total')::INTEGER,
            'total', (v_progress.tracks->'finalization'->>'total')::INTEGER,
            'progressBp', CASE WHEN (v_progress.tracks->'finalization'->>'total')::INTEGER = 0
                THEN 0 ELSE 10000 END
        )
    );
    v_revision := v_progress.revision + 1;
    v_sequence := v_progress.last_event_seq + 1;
    v_fingerprint := public.analysis_v2_dag_hash_json(pg_catalog.jsonb_build_object(
        'domain', 'analysis-v2-progress-snapshot-v1',
        'requestId', p_request_id, 'status', 'completed', 'progressBp', 10000,
        'backgroundProcessing', FALSE, 'tracks', v_tracks,
        'activeProfile', NULL, 'etaRange', NULL
    ));
    v_event_key := public.analysis_v2_dag_hash_json(pg_catalog.jsonb_build_object(
        'domain', 'analysis-v2-progress-event-v1',
        'requestId', p_request_id, 'eventCode', 'ANALYSIS_COMPLETED'
    ));
    UPDATE public.analysis_progress_state AS progress_state
    SET revision = v_revision, status = 'completed', progress_bp = 10000,
        background_processing = FALSE, tracks = v_tracks, active_profile = NULL,
        eta_range = NULL, last_event_seq = v_sequence,
        snapshot_fingerprint = v_fingerprint, updated_at = v_now
    WHERE progress_state.request_id = p_request_id;
    INSERT INTO public.analysis_progress_events (
        request_id, seq, event_key, revision, snapshot_fingerprint, occurred_at,
        event_state, event_code, copy_code, aggregate_count
    ) VALUES (
        p_request_id, v_sequence, v_event_key, v_revision, v_fingerprint, v_now,
        'confirmed', 'ANALYSIS_COMPLETED', 'ANALYSIS_COMPLETED', NULL
    );

    UPDATE public.analysis_pipeline_jobs AS job
    SET status = 'completed', lease_token = NULL, lease_expires_at = NULL,
        completion_token = p_claim_token, completion_fanout_hash = pg_catalog.md5('[]'),
        completed_at = v_now, updated_at = v_now
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key;
    UPDATE public.analysis_requests AS analysis_request
    SET status = 'completed', progress = 100, background_processing = FALSE,
        progress_step = 'V2 analysis completed', current_step = 'completed',
        error_message = NULL, completed_at = v_now
    WHERE analysis_request.id = p_request_id;

    PERFORM public.analysis_v2_scrub_terminal_request_pii(p_request_id, v_now);
    PERFORM public.analysis_v2_purge_result_working_set(p_request_id, TRUE);
    RETURN pg_catalog.jsonb_build_object(
        'finalized', TRUE,
        'requestStatus', 'completed',
        'summary', public.analysis_v2_result_summary_json(v_summary)
    );
END;
$_$;


--
-- Name: analysis_v2_consume_entitlement_after_admission_internal(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_consume_entitlement_after_admission_internal(p_preflight_id uuid, p_user_id uuid, p_selected_plan_id text, p_entitlement_jti_hash text) RETURNS TABLE(request_id uuid, created boolean, initial_job_key text, request_status text, background_processing boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_request_id UUID;
    v_created BOOLEAN;
    v_initial_job_key CONSTANT TEXT := 'coordinator:bootstrap';
    v_input_hash TEXT;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
BEGIN
    SELECT consumed.request_id, consumed.created
    INTO v_request_id, v_created
    FROM public.consume_analysis_v2_test_entitlement_pre_job(
        p_preflight_id,
        p_user_id,
        p_selected_plan_id,
        p_entitlement_jti_hash
    ) AS consumed;

    IF v_request_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_ENTITLEMENT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = v_request_id
      AND analysis_request.user_id = p_user_id
      AND analysis_request.preflight_id = p_preflight_id
    FOR UPDATE;

    IF NOT FOUND
       OR v_request.pipeline_version <> 'v2'
       OR v_request.plan_access_mode_snapshot <> 'test_entitlement'
       OR v_request.selected_plan_id_snapshot <> p_selected_plan_id
       OR v_request.test_entitlement_jti_hash <> p_entitlement_jti_hash THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_ENTITLEMENT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    v_input_hash := pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'analysis-v2-job-input-v1'
                    || pg_catalog.chr(10)
                    || pg_catalog.lower(v_request_id::TEXT)
                    || pg_catalog.chr(10)
                    || v_initial_job_key,
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );

    INSERT INTO public.analysis_pipeline_jobs (
        request_id,
        job_key,
        track,
        kind,
        batch,
        input_hash,
        required_job_keys
    ) VALUES (
        v_request_id,
        v_initial_job_key,
        'coordinator',
        'bootstrap',
        NULL,
        v_input_hash,
        '{}'::TEXT[]
    )
    ON CONFLICT ON CONSTRAINT analysis_pipeline_jobs_pkey DO NOTHING;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = v_request_id
      AND job.job_key = v_initial_job_key
    FOR UPDATE;

    IF NOT FOUND
       OR v_job.track <> 'coordinator'
       OR v_job.kind <> 'bootstrap'
       OR v_job.batch IS NOT NULL
       OR v_job.input_hash <> v_input_hash
       OR v_job.required_job_keys <> '{}'::TEXT[] THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_ENTITLEMENT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    RETURN QUERY SELECT
        v_request_id,
        v_created,
        v_initial_job_key,
        v_request.status::TEXT,
        v_request.background_processing;
END;
$$;


--
-- Name: analysis_v2_cost_attribution_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_cost_attribution_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF TG_TABLE_NAME = 'analysis_preflights' THEN
        PERFORM public.analysis_v2_sync_cost_attributions(NEW.id);
    ELSIF TG_TABLE_NAME = 'analysis_preflight_provider_runs' THEN
        PERFORM public.analysis_v2_sync_cost_attributions(NEW.preflight_id);
    ELSE
        PERFORM public.analysis_v2_sync_cost_attributions(NEW.preflight_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: analysis_v2_cost_rollup_snapshot_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_cost_rollup_snapshot_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_request_id UUID;
BEGIN
    IF TG_TABLE_NAME = 'analysis_requests' THEN
        v_request_id := NEW.id;
    ELSIF TG_TABLE_NAME IN (
        'analysis_v2_provider_runs',
        'analysis_v2_ai_attempts',
        'analysis_v2_ai_result_checkpoints',
        'analysis_v2_selfhosted_auth_runs'
    ) THEN
        v_request_id := NEW.request_id;
    ELSIF TG_TABLE_NAME = 'earlybird_orders' THEN
        v_request_id := NEW.result_request_id;
    ELSIF TG_TABLE_NAME = 'analysis_preflights' THEN
        v_request_id := NEW.consumed_request_id;
    ELSIF TG_TABLE_NAME = 'analysis_preflight_provider_runs' THEN
        SELECT preflight.consumed_request_id
          INTO v_request_id
          FROM public.analysis_preflights AS preflight
         WHERE preflight.id = NEW.preflight_id;
    ELSIF TG_TABLE_NAME = 'vertex_ai_budget_reservations' THEN
        SELECT request.id
          INTO v_request_id
          FROM public.analysis_requests AS request
         WHERE request.id::TEXT = NEW.run_id;
    END IF;

    PERFORM public.analysis_v2_refresh_cost_rollup_snapshot(v_request_id);
    RETURN NEW;
END;
$$;


--
-- Name: analysis_v2_create_or_replay_preflight_unfenced_20260802(uuid, text, text, text, text, text, jsonb, jsonb, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_create_or_replay_preflight_unfenced_20260802(p_user_id uuid, p_email text, p_auth_provider text, p_target_instagram_id text, p_idempotency_key text, p_access_mode text, p_launch_status_snapshot jsonb, p_plan_catalog_snapshot jsonb, p_pricing_version text, p_pricing_snapshot jsonb, p_policy_versions_snapshot jsonb) RETURNS TABLE(preflight_id uuid, created boolean, preflight_status text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_target_instagram_id TEXT;
    v_existing public.analysis_preflights%ROWTYPE;
    v_preflight_id UUID;
    v_plan_id TEXT;
    v_recent_preflight_count INTEGER;
    v_global_preflight_count INTEGER;
BEGIN
    IF p_user_id IS NULL
       OR p_email IS NULL
       OR pg_catalog.char_length(pg_catalog.btrim(p_email)) < 3
       OR pg_catalog.char_length(pg_catalog.btrim(p_email)) > 255
       OR pg_catalog.strpos(p_email, '@') < 2
       OR p_auth_provider IS NULL
       OR p_auth_provider !~ '^[a-z0-9._:-]{1,50}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_AUTH_INPUT', ERRCODE = 'P0001';
    END IF;

    v_target_instagram_id := pg_catalog.lower(pg_catalog.btrim(p_target_instagram_id));
    IF v_target_instagram_id IS NULL
       OR v_target_instagram_id !~ '^[a-z0-9._]{1,30}$'
       OR p_idempotency_key IS NULL
       OR pg_catalog.char_length(p_idempotency_key) < 16
       OR pg_catalog.char_length(p_idempotency_key) > 128
       OR p_idempotency_key !~ '^[A-Za-z0-9._:-]+$'
       OR p_access_mode IS NULL
       OR p_access_mode NOT IN ('production', 'test_entitlement')
       OR NOT public.analysis_v2_valid_launch_snapshot(p_launch_status_snapshot)
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(p_plan_catalog_snapshot)
       OR p_pricing_version IS NULL
       OR pg_catalog.char_length(p_pricing_version) < 1
       OR pg_catalog.char_length(p_pricing_version) > 64
       OR p_pricing_version !~ '^[A-Za-z0-9._:-]+$'
       OR NOT public.analysis_v2_valid_pricing_snapshot(p_pricing_snapshot)
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(p_policy_versions_snapshot) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_PREFLIGHT_INPUT', ERRCODE = 'P0001';
    END IF;

    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        IF p_plan_catalog_snapshot->v_plan_id->>'launchStatus'
            IS DISTINCT FROM p_launch_status_snapshot->>v_plan_id THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_PREFLIGHT_INPUT', ERRCODE = 'P0001';
        END IF;
    END LOOP;

    INSERT INTO public.users (id, email, provider, analysis_count, is_paid_user)
    VALUES (p_user_id, pg_catalog.btrim(p_email), p_auth_provider, 0, FALSE)
    ON CONFLICT (id) DO NOTHING;

    PERFORM 1 FROM public.users WHERE id = p_user_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_AUTH_INPUT', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET status = 'expired',
        lease_token = NULL,
        lease_expires_at = NULL,
        updated_at = v_now
    WHERE preflight.user_id = p_user_id
      AND preflight.status IN ('pending', 'processing', 'ready')
      AND preflight.expires_at <= v_now
      AND EXISTS (
          SELECT 1
          FROM public.earlybird_orders AS earlybird_order
          WHERE earlybird_order.preflight_id = preflight.id
            AND earlybird_order.status IN (
                'payment_pending', 'cancelled', 'paid',
                'analysis_in_progress', 'completed'
            )
      );

    UPDATE public.analysis_preflights AS preflight
    SET status = 'expired',
        target_instagram_id = 'retained.'
            || pg_catalog.substr(pg_catalog.replace(preflight.id::TEXT, '-', ''), 1, 20),
        target_full_name = NULL,
        target_bio = NULL,
        target_profile_image_url = NULL,
        target_followers_count = NULL,
        target_following_count = NULL,
        target_is_private = NULL,
        capacity_required_plan_id = NULL,
        required_plan_id = NULL,
        plan_cards_snapshot = NULL,
        error_code = NULL,
        blocked_at = NULL,
        ready_at = NULL,
        exclusion_decision = 'skip',
        excluded_instagram_id = NULL,
        lease_token = NULL,
        lease_expires_at = NULL,
        pii_scrubbed_at = v_now,
        updated_at = v_now
    WHERE preflight.user_id = p_user_id
      AND preflight.status IN ('pending', 'processing', 'ready')
      AND preflight.expires_at <= v_now
      AND NOT EXISTS (
          SELECT 1
          FROM public.earlybird_orders AS earlybird_order
          WHERE earlybird_order.preflight_id = preflight.id
            AND earlybird_order.status IN (
                'payment_pending', 'cancelled', 'paid',
                'analysis_in_progress', 'completed'
            )
      );

    SELECT preflight.* INTO v_existing
    FROM public.analysis_preflights AS preflight
    WHERE preflight.user_id = p_user_id
      AND preflight.idempotency_key = p_idempotency_key
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.status = 'expired' THEN
            RETURN QUERY SELECT v_existing.id, FALSE, 'expired'::TEXT, v_existing.expires_at;
            RETURN;
        END IF;
        IF v_existing.target_instagram_id IS DISTINCT FROM v_target_instagram_id
           OR v_existing.access_mode IS DISTINCT FROM p_access_mode THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_IDEMPOTENCY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN QUERY SELECT v_existing.id, FALSE, v_existing.status, v_existing.expires_at;
        RETURN;
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('analysis-v2-preflight-global-hourly-budget', 0)
    );
    SELECT pg_catalog.count(*)::INTEGER INTO v_global_preflight_count
    FROM public.analysis_preflights AS recent_preflight
    WHERE recent_preflight.created_at > v_now - INTERVAL '1 hour';
    SELECT pg_catalog.count(*)::INTEGER INTO v_recent_preflight_count
    FROM public.analysis_preflights AS recent_preflight
    WHERE recent_preflight.user_id = p_user_id
      AND recent_preflight.created_at > v_now - INTERVAL '1 hour';
    IF v_recent_preflight_count >= 5
       OR EXISTS (
           SELECT 1 FROM public.analysis_preflights AS recent_preflight
           WHERE recent_preflight.user_id = p_user_id
             AND recent_preflight.created_at > v_now - INTERVAL '10 seconds'
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_RATE_LIMITED', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET status = 'expired', lease_token = NULL, lease_expires_at = NULL, updated_at = v_now
    WHERE preflight.user_id = p_user_id
      AND preflight.status IN ('pending', 'processing', 'ready');

    v_preflight_id := extensions.gen_random_uuid();
    INSERT INTO public.analysis_preflights (
        id, user_id, idempotency_key, target_instagram_id, status,
        exclusion_decision, access_mode, launch_status_snapshot,
        plan_catalog_snapshot, pricing_version, pricing_snapshot,
        policy_versions_snapshot, created_at, updated_at, expires_at
    ) VALUES (
        v_preflight_id, p_user_id, p_idempotency_key, v_target_instagram_id,
        'pending', 'pending', p_access_mode, p_launch_status_snapshot,
        p_plan_catalog_snapshot, p_pricing_version, p_pricing_snapshot,
        p_policy_versions_snapshot, v_now, v_now, v_now + INTERVAL '30 minutes'
    );
    RETURN QUERY SELECT v_preflight_id, TRUE, 'pending'::TEXT,
        v_now + INTERVAL '30 minutes';
END;
$_$;


--
-- Name: analysis_v2_dag_bounded_integer(jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_dag_bounded_integer(p_value jsonb, p_minimum integer, p_maximum integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT CASE
        WHEN pg_catalog.jsonb_typeof(p_value) = 'number'
         AND p_value::TEXT ~ '^(0|[1-9][0-9]{0,6})$'
        THEN (p_value::TEXT)::NUMERIC BETWEEN p_minimum AND p_maximum
        ELSE FALSE
    END;
$_$;


--
-- Name: analysis_v2_dag_hash_json(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_dag_hash_json(p_value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.encode(
        extensions.digest(pg_catalog.convert_to(p_value::TEXT, 'UTF8'), 'sha256'),
        'hex'
    );
$$;


--
-- Name: analysis_v2_dag_state_json(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_dag_state_json(p_request_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
        'schemaVersion', scope.schema_version,
        'requestSnapshotHash', scope.request_snapshot_hash,
        'planId', scope.plan_id,
        'planSnapshotHash', scope.plan_snapshot_hash,
        'girlfriendExclusion', pg_catalog.jsonb_build_object(
            'decisionHash', scope.exclusion_decision_hash,
            'excludedCount', scope.excluded_count
        ),
        'relationships', (
            SELECT pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
                'revision', stage.revision,
                'resultHash', stage.result_hash,
                'detectedMutualCount', stage.detected_mutual_count,
                'publicCount', stage.public_count,
                'privateCount', stage.private_count,
                'detailedSelectedPublicCount', stage.detailed_selected_public_count,
                'notScreenedPublicCount', stage.not_screened_public_count,
                'profileBatches', COALESCE((
                    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                        'batch', topology.batch,
                        'itemCount', topology.item_count,
                        'inputHash', topology.input_hash
                    ) ORDER BY topology.batch)
                    FROM public.analysis_v2_dag_batch_topology AS topology
                    WHERE topology.request_id = scope.request_id
                      AND topology.topology_kind = 'profile'
                ), '[]'::JSONB),
                'privateNameBatches', COALESCE((
                    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                        'batch', topology.batch,
                        'itemCount', topology.item_count,
                        'inputHash', topology.input_hash
                    ) ORDER BY topology.batch)
                    FROM public.analysis_v2_dag_batch_topology AS topology
                    WHERE topology.request_id = scope.request_id
                      AND topology.topology_kind = 'private_name'
                ), '[]'::JSONB),
                'relationshipSelectionPolicy', CASE
                    WHEN stage.relationship_selection_policy_version IS NULL THEN NULL
                    ELSE pg_catalog.jsonb_build_object(
                        'policyVersion', stage.relationship_selection_policy_version,
                        'relationshipCheckpointId', stage.relationship_selection_checkpoint_id,
                        'relationshipJobInputHash', stage.relationship_selection_job_input_hash,
                        'planId', stage.relationship_selection_plan_id,
                        'publicPopulationCount', stage.relationship_selection_public_population_count,
                        'selectedCount', stage.relationship_selection_selected_count
                    )
                END
            ))
            FROM public.analysis_v2_dag_stage_manifests AS stage
            WHERE stage.request_id = scope.request_id
              AND stage.stage_kind = 'relationships'
        ),
        'targetEvidence', (
            SELECT pg_catalog.jsonb_build_object(
                'revision', stage.revision,
                'resultHash', stage.result_hash,
                'interactorCount', stage.interactor_count
            )
            FROM public.analysis_v2_dag_stage_manifests AS stage
            WHERE stage.request_id = scope.request_id AND stage.stage_kind = 'target_evidence'
        ),
        'profileFetchBatches', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'batch', result.batch, 'itemCount', result.item_count,
                'producerInputHash', result.producer_input_hash,
                'revision', result.revision, 'resultHash', result.result_hash
            ) ORDER BY result.batch)
            FROM public.analysis_v2_dag_batch_results AS result
            WHERE result.request_id = scope.request_id AND result.result_kind = 'profile_fetch'
        ), '[]'::JSONB),
        'profileAiBatches', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'batch', result.batch, 'itemCount', result.item_count,
                'producerInputHash', result.producer_input_hash,
                'revision', result.revision, 'resultHash', result.result_hash
            ) ORDER BY result.batch)
            FROM public.analysis_v2_dag_batch_results AS result
            WHERE result.request_id = scope.request_id AND result.result_kind = 'profile_ai'
        ), '[]'::JSONB),
        'privateNameBatches', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'batch', result.batch, 'itemCount', result.item_count,
                'producerInputHash', result.producer_input_hash,
                'revision', result.revision, 'resultHash', result.result_hash
            ) ORDER BY result.batch)
            FROM public.analysis_v2_dag_batch_results AS result
            WHERE result.request_id = scope.request_id AND result.result_kind = 'private_name'
        ), '[]'::JSONB),
        'primaryJoin', (
            SELECT pg_catalog.jsonb_build_object(
                'revision', stage.revision, 'resultHash', stage.result_hash,
                'verifiedFemaleCount', stage.verified_female_count
            ) FROM public.analysis_v2_dag_stage_manifests AS stage
            WHERE stage.request_id = scope.request_id AND stage.stage_kind = 'primary_join'
        ),
        'screening', (
            SELECT pg_catalog.jsonb_build_object(
                'revision', stage.revision, 'resultHash', stage.result_hash,
                'verifiedFemaleCount', stage.verified_female_count,
                'shortlistCount', stage.shortlist_count, 'shortlistHash', stage.shortlist_hash
            ) FROM public.analysis_v2_dag_stage_manifests AS stage
            WHERE stage.request_id = scope.request_id AND stage.stage_kind = 'screening'
        ),
        'reverseLikes', (
            SELECT pg_catalog.jsonb_build_object(
                'revision', stage.revision, 'resultHash', stage.result_hash,
                'shortlistCount', stage.shortlist_count
            ) FROM public.analysis_v2_dag_stage_manifests AS stage
            WHERE stage.request_id = scope.request_id AND stage.stage_kind = 'reverse_likes'
        ),
        'partnerSafety', (
            SELECT pg_catalog.jsonb_build_object(
                'revision', stage.revision, 'resultHash', stage.result_hash,
                'shortlistCount', stage.shortlist_count
            ) FROM public.analysis_v2_dag_stage_manifests AS stage
            WHERE stage.request_id = scope.request_id AND stage.stage_kind = 'partner_safety'
        ),
        'finalScore', (
            SELECT pg_catalog.jsonb_build_object(
                'revision', stage.revision, 'resultHash', stage.result_hash,
                'featuredHighRiskCount', stage.featured_high_risk_count,
                'narrativeCount', stage.narrative_count,
                'narrativeBatchHash', stage.narrative_batch_hash
            ) FROM public.analysis_v2_dag_stage_manifests AS stage
            WHERE stage.request_id = scope.request_id AND stage.stage_kind = 'final_score'
        ),
        'narrative', (
            SELECT pg_catalog.jsonb_build_object(
                'revision', stage.revision, 'resultHash', stage.result_hash,
                'narrativeCount', stage.narrative_count
            ) FROM public.analysis_v2_dag_stage_manifests AS stage
            WHERE stage.request_id = scope.request_id AND stage.stage_kind = 'narrative'
        )
    ))
    FROM public.analysis_v2_dag_scopes AS scope
    WHERE scope.request_id = p_request_id;
$$;


--
-- Name: analysis_v2_effective_female_results(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_effective_female_results(p_request_id uuid) RETURNS TABLE(request_id uuid, candidate_id character varying, sort_ordinal smallint, instagram_id character varying, full_name character varying, profile_image_url text, bio character varying, display_score numeric, risk_band character varying, featured_rank smallint, recent_mutual_rank smallint, analysis_depth character varying, one_line_overview character varying, narrative_line_one character varying, narrative_line_two character varying)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_revision_id UUID;
BEGIN
    SELECT revision.revision_id INTO v_revision_id
    FROM public.analysis_v2_result_revisions AS revision
    WHERE revision.request_id = p_request_id AND revision.state = 'published';
    IF v_revision_id IS NULL THEN
        RETURN QUERY SELECT p_request_id, female.candidate_id, female.sort_ordinal, female.instagram_id,
            female.full_name, female.profile_image_url, female.bio, female.display_score,
            female.risk_band, female.featured_rank, female.recent_mutual_rank,
            female.analysis_depth, female.one_line_overview, female.narrative_line_one,
            female.narrative_line_two
        FROM public.analysis_v2_female_results AS female WHERE female.request_id = p_request_id;
    ELSE
        RETURN QUERY SELECT p_request_id, female.candidate_id, female.sort_ordinal, female.instagram_id,
            female.full_name, female.profile_image_url, female.bio, female.display_score,
            female.risk_band, female.featured_rank, female.recent_mutual_rank,
            female.analysis_depth, female.one_line_overview, female.narrative_line_one,
            female.narrative_line_two
        FROM public.analysis_v2_result_revision_female_rows AS female WHERE female.revision_id = v_revision_id;
    END IF;
END;
$$;


--
-- Name: analysis_v2_result_valid_image_path(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_result_valid_image_path(p_value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT p_value IS NULL OR (
        pg_catalog.char_length(p_value) BETWEEN 9 AND 8192
        AND p_value ~ '^https://([^/@]+\.)?(instagram\.com|cdninstagram\.com|fbcdn\.net|fbsbx\.com)(:443)?/'
        AND p_value !~ '[[:cntrl:]]'
    );
$$;


--
-- Name: analysis_v2_result_summaries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_result_summaries (
    request_id uuid NOT NULL,
    target_instagram_id character varying(30) NOT NULL,
    target_profile_image_url text,
    plan_id character varying(16) NOT NULL,
    followers_declared smallint NOT NULL,
    followers_collected smallint NOT NULL,
    following_declared smallint NOT NULL,
    following_collected smallint NOT NULL,
    detected_mutuals smallint NOT NULL,
    public_mutuals smallint NOT NULL,
    private_mutuals smallint NOT NULL,
    screened_mutuals smallint NOT NULL,
    not_screened_mutuals smallint NOT NULL,
    fetch_unavailable_count smallint NOT NULL,
    media_unavailable_count smallint NOT NULL,
    exclusion_applied boolean NOT NULL,
    score_policy_version character varying(64) NOT NULL,
    finalizer_input_hash character varying(64) NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    analysis_unavailable_count smallint DEFAULT 0 NOT NULL,
    male_count smallint NOT NULL,
    female_count smallint NOT NULL,
    unknown_count smallint NOT NULL,
    target_full_name character varying(200),
    CONSTRAINT analysis_v2_result_summaries_finalizer_input_hash_check CHECK (((finalizer_input_hash)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT analysis_v2_result_summaries_gender_counts_check CHECK (((male_count >= 0) AND (female_count >= 0) AND (unknown_count >= 0) AND (((male_count + female_count) + unknown_count) = screened_mutuals))),
    CONSTRAINT analysis_v2_result_summaries_plan_id_check CHECK (((plan_id)::text = ANY ((ARRAY['basic'::character varying, 'standard'::character varying, 'plus'::character varying])::text[]))),
    CONSTRAINT analysis_v2_result_summaries_score_policy_version_check CHECK (((score_policy_version)::text = ANY ((ARRAY['risk-policy-v2.2'::character varying, 'risk-policy-v2.3'::character varying, 'risk-policy-v2.4'::character varying, 'risk-policy-v2.5'::character varying])::text[]))),
    CONSTRAINT analysis_v2_result_summary_count_check CHECK ((((detected_mutuals >= 0) AND (detected_mutuals <= 1200)) AND ((public_mutuals >= 0) AND (public_mutuals <= detected_mutuals)) AND ((private_mutuals >= 0) AND (private_mutuals <= detected_mutuals)) AND ((public_mutuals + private_mutuals) = detected_mutuals) AND ((screened_mutuals >= 0) AND (screened_mutuals <= public_mutuals)) AND (not_screened_mutuals = (public_mutuals - screened_mutuals)) AND ((fetch_unavailable_count >= 0) AND (fetch_unavailable_count <= screened_mutuals)) AND ((media_unavailable_count >= 0) AND (media_unavailable_count <= screened_mutuals)) AND ((analysis_unavailable_count >= 0) AND (analysis_unavailable_count <= screened_mutuals)) AND (((fetch_unavailable_count + media_unavailable_count) + analysis_unavailable_count) <= screened_mutuals) AND (detected_mutuals <= followers_collected) AND (detected_mutuals <= following_collected))),
    CONSTRAINT analysis_v2_result_summary_coverage_check CHECK ((((followers_declared >= 0) AND (followers_declared <= 1200)) AND ((followers_collected >= 0) AND (followers_collected <= followers_declared)) AND ((following_declared >= 0) AND (following_declared <= 1200)) AND ((following_collected >= 0) AND (following_collected <= following_declared)) AND (((followers_declared = 0) AND (followers_collected = 0)) OR ((followers_collected * 100) >= (followers_declared * 99))) AND (((following_declared = 0) AND (following_collected = 0)) OR ((following_collected * 100) >= (following_declared * 99))))),
    CONSTRAINT analysis_v2_result_summary_image_check CHECK (public.analysis_v2_result_valid_image_path(target_profile_image_url)),
    CONSTRAINT analysis_v2_result_summary_username_check CHECK (((target_instagram_id)::text ~ '^[a-z0-9._]{1,30}$'::text))
);

ALTER TABLE ONLY public.analysis_v2_result_summaries FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_effective_result_summary_json(uuid, public.analysis_v2_result_summaries); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_effective_result_summary_json(p_request_id uuid, p_summary public.analysis_v2_result_summaries) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_revision public.analysis_v2_result_revisions%ROWTYPE;
DECLARE v_summary JSONB;
BEGIN
    v_summary := public.analysis_v2_result_summary_json(p_summary);
    SELECT revision.* INTO v_revision
    FROM public.analysis_v2_result_revisions AS revision
    WHERE revision.request_id = p_request_id AND revision.state = 'published';
    IF v_revision.revision_id IS NULL THEN RETURN v_summary; END IF;
    RETURN pg_catalog.jsonb_set(v_summary, '{genderStats}', pg_catalog.jsonb_build_object(
        'male', v_revision.male_count,
        'female', v_revision.female_count,
        'unknown', v_revision.unknown_count
    ));
END;
$$;


--
-- Name: analysis_v2_expected_relative_risk_rows(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_expected_relative_risk_rows(p_rows jsonb, p_strong_partner_candidate_ids text[]) RETURNS TABLE(candidate_id text, display_score numeric, risk_band text, relative_tier_applied boolean)
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
WITH source_rows AS (
    SELECT
        item.value->>'candidateId' AS candidate_id,
        (item.value->>'publicScore')::NUMERIC AS public_score,
        COALESCE(item.value->>'accountContext', 'personal') = 'official_group_or_brand'
            AS official_group_or_brand,
        COALESCE((item.value->'components'->>'candidateToTargetLikes')::NUMERIC, 0) > 0
            OR COALESCE((item.value->'components'->>'candidateToTargetComments')::NUMERIC, 0) > 0
            OR COALESCE(
                (item.value->'components'->>'candidateToTargetTagOrCaptionMention')::NUMERIC,
                0
            ) > 0 AS inbound,
        (item.value->>'candidateId') = ANY(
            COALESCE(p_strong_partner_candidate_ids, ARRAY[]::TEXT[])
        ) AS strong_partner
    FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
),
natural_rows AS (
    SELECT
        source.*,
        pg_catalog.round(source.public_score, 1) AS natural_display_score,
        CASE
            WHEN source.public_score < 4.2 THEN 'normal'
            WHEN source.public_score < 6.8 THEN 'caution'
            ELSE 'high_risk'
        END AS natural_risk_band
    FROM source_rows AS source
),
eligible_rows AS (
    SELECT
        natural_row.*,
        pg_catalog.row_number() OVER (
            ORDER BY natural_row.public_score DESC, natural_row.candidate_id
        )::INTEGER AS eligible_rank,
        pg_catalog.count(*) OVER ()::INTEGER AS eligible_count,
        pg_catalog.count(*) FILTER (WHERE natural_row.inbound) OVER ()::INTEGER AS inbound_count,
        pg_catalog.count(*) FILTER (
            WHERE natural_row.natural_risk_band = 'high_risk'
        ) OVER ()::INTEGER AS natural_high_count,
        pg_catalog.count(*) FILTER (
            WHERE natural_row.natural_risk_band <> 'normal'
        ) OVER ()::INTEGER AS natural_non_normal_count
    FROM natural_rows AS natural_row
    WHERE NOT natural_row.strong_partner
      AND NOT natural_row.official_group_or_brand
),
high_counts AS (
    SELECT eligible.*,
        CASE WHEN eligible.eligible_count < 3 THEN 0 ELSE GREATEST(
            1, LEAST(3, eligible.eligible_count - 2, eligible.natural_high_count)
        ) END AS requested_high_count
    FROM eligible_rows AS eligible
),
high_pool AS (
    SELECT counted.*,
        pg_catalog.row_number() OVER (
            ORDER BY counted.public_score DESC, counted.candidate_id
        )::INTEGER AS high_pool_rank
    FROM high_counts AS counted
    WHERE counted.inbound_count = 0 OR counted.inbound
),
high_selected AS (
    SELECT counted.*, COALESCE(
        pool.high_pool_rank <= counted.requested_high_count, FALSE
    ) AS selected_high
    FROM high_counts AS counted
    LEFT JOIN high_pool AS pool ON pool.candidate_id = counted.candidate_id
),
selected_counts AS (
    SELECT selected.*,
        pg_catalog.count(*) FILTER (WHERE selected.selected_high) OVER ()::INTEGER
            AS actual_high_count
    FROM high_selected AS selected
),
remaining_rows AS (
    SELECT selected.*,
        pg_catalog.row_number() OVER (
            ORDER BY selected.public_score DESC, selected.candidate_id
        )::INTEGER AS remaining_rank,
        pg_catalog.count(*) OVER ()::INTEGER AS remaining_count
    FROM selected_counts AS selected
    WHERE NOT selected.selected_high
),
eligible_tiers AS (
    SELECT selected.*,
        CASE
            WHEN selected.eligible_count < 3 THEN selected.natural_risk_band
            WHEN selected.selected_high THEN 'high_risk'
            WHEN remaining.remaining_rank <= LEAST(
                10, remaining.remaining_count,
                GREATEST(2, selected.natural_non_normal_count - selected.actual_high_count)
            ) THEN 'caution'
            ELSE 'normal'
        END AS expected_risk_band
    FROM selected_counts AS selected
    LEFT JOIN remaining_rows AS remaining ON remaining.candidate_id = selected.candidate_id
),
expected_eligible AS (
    SELECT tiered.candidate_id,
        CASE tiered.expected_risk_band
            WHEN 'high_risk' THEN LEAST(10.0, GREATEST(6.8, tiered.natural_display_score))
            WHEN 'caution' THEN LEAST(6.7, GREATEST(4.2, tiered.natural_display_score))
            ELSE LEAST(4.1, GREATEST(1.0, tiered.natural_display_score))
        END::NUMERIC AS display_score,
        tiered.expected_risk_band AS risk_band,
        tiered.eligible_count >= 3 AS relative_tier_applied
    FROM eligible_tiers AS tiered
),
expected_excluded AS (
    SELECT natural_row.candidate_id,
        CASE WHEN natural_row.official_group_or_brand
            THEN LEAST(4.1, GREATEST(1.0, natural_row.natural_display_score))
            ELSE natural_row.natural_display_score
        END::NUMERIC AS display_score,
        CASE WHEN natural_row.official_group_or_brand THEN 'normal'
            ELSE natural_row.natural_risk_band END AS risk_band,
        FALSE AS relative_tier_applied
    FROM natural_rows AS natural_row
    WHERE natural_row.strong_partner OR natural_row.official_group_or_brand
)
SELECT * FROM expected_eligible
UNION ALL
SELECT * FROM expected_excluded
ORDER BY candidate_id;
$$;


--
-- Name: analysis_v2_expected_relative_risk_rows(jsonb, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_expected_relative_risk_rows(p_rows jsonb, p_strong_partner_candidate_ids text[], p_risk_policy_version text) RETURNS TABLE(candidate_id text, display_score numeric, risk_band text, relative_tier_applied boolean)
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT * FROM public.analysis_v2_expected_relative_risk_rows_v23(
        p_rows, p_strong_partner_candidate_ids
    ) WHERE p_risk_policy_version = 'risk-policy-v2.3'
    UNION ALL
    SELECT * FROM public.analysis_v2_expected_relative_risk_rows(
        p_rows, p_strong_partner_candidate_ids
    ) WHERE p_risk_policy_version = 'risk-policy-v2.4'
    UNION ALL
    SELECT * FROM public.analysis_v2_expected_relative_risk_rows_v25(
        p_rows, p_strong_partner_candidate_ids
    ) WHERE p_risk_policy_version = 'risk-policy-v2.5'
    ORDER BY candidate_id;
$$;


--
-- Name: analysis_v2_expected_relative_risk_rows_v23(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_expected_relative_risk_rows_v23(p_rows jsonb, p_strong_partner_candidate_ids text[]) RETURNS TABLE(candidate_id text, display_score numeric, risk_band text, relative_tier_applied boolean)
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
WITH source_rows AS (
    SELECT
        item.value->>'candidateId' AS candidate_id,
        (item.value->>'publicScore')::NUMERIC AS public_score,
        (item.value->>'candidateId') = ANY(
            COALESCE(p_strong_partner_candidate_ids, ARRAY[]::TEXT[])
        ) AS strong_partner
    FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
),
natural_rows AS (
    SELECT
        source.candidate_id,
        source.public_score,
        pg_catalog.round(source.public_score, 1) AS natural_display_score,
        CASE
            WHEN source.public_score < 4.2 THEN 'normal'
            WHEN source.public_score < 6.8 THEN 'caution'
            ELSE 'high_risk'
        END AS natural_risk_band,
        source.strong_partner
    FROM source_rows AS source
),
eligible_rows AS (
    SELECT
        natural_row.*,
        pg_catalog.row_number() OVER (
            ORDER BY natural_row.public_score DESC, natural_row.candidate_id
        )::INTEGER AS eligible_rank,
        pg_catalog.count(*) OVER ()::INTEGER AS eligible_count,
        pg_catalog.count(*) FILTER (
            WHERE natural_row.natural_risk_band = 'high_risk'
        ) OVER ()::INTEGER AS natural_high_count,
        pg_catalog.count(*) FILTER (
            WHERE natural_row.natural_risk_band <> 'normal'
        ) OVER ()::INTEGER AS natural_non_normal_count
    FROM natural_rows AS natural_row
    WHERE NOT natural_row.strong_partner
),
eligible_counts AS (
    SELECT
        eligible.*,
        CASE
            WHEN eligible.eligible_count < 3 THEN 0
            ELSE GREATEST(
                1,
                LEAST(
                    eligible.eligible_count - 2,
                    eligible.natural_high_count
                )
            )
        END AS high_count
    FROM eligible_rows AS eligible
),
eligible_tiers AS (
    SELECT
        counted.*,
        CASE
            WHEN counted.eligible_count < 3 THEN counted.natural_risk_band
            WHEN counted.eligible_rank <= counted.high_count THEN 'high_risk'
            WHEN counted.eligible_rank <= counted.high_count + LEAST(
                counted.eligible_count - counted.high_count,
                GREATEST(
                    2,
                    counted.natural_non_normal_count - counted.high_count
                )
            ) THEN 'caution'
            ELSE 'normal'
        END AS expected_risk_band
    FROM eligible_counts AS counted
),
expected_eligible AS (
    SELECT
        tiered.candidate_id,
        CASE tiered.expected_risk_band
            WHEN 'high_risk' THEN
                LEAST(10.0, GREATEST(6.8, tiered.natural_display_score))
            WHEN 'caution' THEN
                LEAST(6.7, GREATEST(4.2, tiered.natural_display_score))
            ELSE LEAST(4.1, GREATEST(1.0, tiered.natural_display_score))
        END::NUMERIC AS display_score,
        tiered.expected_risk_band AS risk_band,
        tiered.eligible_count >= 3 AS relative_tier_applied
    FROM eligible_tiers AS tiered
),
expected_strong_partner AS (
    SELECT
        natural_row.candidate_id,
        natural_row.natural_display_score AS display_score,
        natural_row.natural_risk_band AS risk_band,
        FALSE AS relative_tier_applied
    FROM natural_rows AS natural_row
    WHERE natural_row.strong_partner
)
SELECT * FROM expected_eligible
UNION ALL
SELECT * FROM expected_strong_partner
ORDER BY candidate_id;
$$;


--
-- Name: analysis_v2_expected_relative_risk_rows_v25(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_expected_relative_risk_rows_v25(p_rows jsonb, p_strong_partner_candidate_ids text[]) RETURNS TABLE(candidate_id text, display_score numeric, risk_band text, relative_tier_applied boolean)
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
WITH source_rows AS (
    SELECT
        item.value->>'candidateId' AS candidate_id,
        (item.value->>'publicScore')::NUMERIC AS public_score,
        COALESCE(item.value->>'accountContext', 'personal') = 'official_group_or_brand'
            AS official_group_or_brand,
        COALESCE((item.value->'components'->>'candidateToTargetLikes')::NUMERIC, 0) > 0
            OR COALESCE(
                (item.value->'components'->>'candidateToTargetComments')::NUMERIC, 0
            ) > 0
            OR COALESCE(
                (item.value->'components'->>'candidateToTargetTagOrCaptionMention')::NUMERIC,
                0
            ) > 0 AS inbound,
        (item.value->>'candidateId') = ANY(
            COALESCE(p_strong_partner_candidate_ids, ARRAY[]::TEXT[])
        ) AS strong_partner
    FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
),
natural_rows AS (
    SELECT source.*,
        pg_catalog.round(source.public_score, 1) AS natural_display_score,
        CASE
            WHEN source.public_score < 4.2 THEN 'normal'
            WHEN source.public_score < 6.8 THEN 'caution'
            ELSE 'high_risk'
        END AS natural_risk_band
    FROM source_rows AS source
),
eligible_rows AS (
    SELECT natural_row.*,
        pg_catalog.count(*) OVER ()::INTEGER AS eligible_count,
        pg_catalog.count(*) FILTER (WHERE natural_row.inbound) OVER ()::INTEGER
            AS inbound_count,
        pg_catalog.count(*) FILTER (
            WHERE natural_row.natural_risk_band = 'high_risk'
        ) OVER ()::INTEGER AS natural_high_count,
        pg_catalog.count(*) FILTER (
            WHERE natural_row.natural_risk_band <> 'normal'
        ) OVER ()::INTEGER AS natural_non_normal_count
    FROM natural_rows AS natural_row
    WHERE NOT natural_row.strong_partner
      AND NOT natural_row.official_group_or_brand
),
high_pool AS (
    SELECT eligible.*,
        pg_catalog.row_number() OVER (
            ORDER BY eligible.public_score DESC, eligible.candidate_id
        )::INTEGER AS high_pool_rank
    FROM eligible_rows AS eligible
    WHERE eligible.inbound_count = 0 OR eligible.inbound
),
high_pool_facts AS (
    SELECT pool.*,
        pg_catalog.count(*) OVER ()::INTEGER AS high_pool_count,
        pg_catalog.max(pool.public_score) FILTER (
            WHERE pool.high_pool_rank = 3
        ) OVER () AS third_high_pool_score
    FROM high_pool AS pool
),
eligible_counts AS (
    SELECT eligible.*,
        COALESCE(pg_catalog.max(pool.high_pool_count), 0)::INTEGER AS high_pool_count,
        pg_catalog.max(pool.third_high_pool_score) AS third_high_pool_score
    FROM eligible_rows AS eligible
    LEFT JOIN high_pool_facts AS pool ON TRUE
    GROUP BY eligible.candidate_id, eligible.public_score,
        eligible.official_group_or_brand, eligible.inbound, eligible.strong_partner,
        eligible.eligible_count, eligible.inbound_count,
        eligible.natural_high_count, eligible.natural_non_normal_count,
        eligible.natural_display_score, eligible.natural_risk_band
),
requested_counts AS (
    SELECT counted.*,
        CASE WHEN counted.eligible_count < 3 THEN 0 ELSE LEAST(
            3,
            counted.eligible_count - 2,
            counted.high_pool_count,
            GREATEST(
                1,
                LEAST(3, counted.eligible_count - 2, counted.natural_high_count),
                CASE
                    WHEN counted.eligible_count >= 5
                     AND counted.high_pool_count >= 3
                     AND counted.third_high_pool_score >= 4.2 THEN 3
                    WHEN counted.eligible_count >= 4 THEN 2
                    ELSE 1
                END
            )
        ) END::INTEGER AS requested_high_count
    FROM eligible_counts AS counted
),
high_selected AS (
    SELECT counted.*,
        COALESCE(pool.high_pool_rank <= counted.requested_high_count, FALSE)
            AS selected_high
    FROM requested_counts AS counted
    LEFT JOIN high_pool_facts AS pool
      ON pool.candidate_id = counted.candidate_id
),
selected_counts AS (
    SELECT selected.*,
        pg_catalog.count(*) FILTER (WHERE selected.selected_high) OVER ()::INTEGER
            AS actual_high_count
    FROM high_selected AS selected
),
remaining_rows AS (
    SELECT selected.*,
        pg_catalog.row_number() OVER (
            ORDER BY selected.public_score DESC, selected.candidate_id
        )::INTEGER AS remaining_rank,
        pg_catalog.count(*) OVER ()::INTEGER AS remaining_count
    FROM selected_counts AS selected
    WHERE NOT selected.selected_high
),
eligible_tiers AS (
    SELECT selected.*,
        CASE
            WHEN selected.eligible_count < 3 THEN selected.natural_risk_band
            WHEN selected.selected_high THEN 'high_risk'
            WHEN remaining.remaining_rank <= LEAST(
                10, remaining.remaining_count,
                GREATEST(2, selected.natural_non_normal_count - selected.actual_high_count)
            ) THEN 'caution'
            ELSE 'normal'
        END AS expected_risk_band
    FROM selected_counts AS selected
    LEFT JOIN remaining_rows AS remaining
      ON remaining.candidate_id = selected.candidate_id
),
expected_eligible AS (
    SELECT tiered.candidate_id,
        CASE tiered.expected_risk_band
            WHEN 'high_risk' THEN
                LEAST(10.0, GREATEST(6.8, tiered.natural_display_score))
            WHEN 'caution' THEN
                LEAST(6.7, GREATEST(4.2, tiered.natural_display_score))
            ELSE LEAST(4.1, GREATEST(1.0, tiered.natural_display_score))
        END::NUMERIC AS display_score,
        tiered.expected_risk_band AS risk_band,
        tiered.eligible_count >= 3 AS relative_tier_applied
    FROM eligible_tiers AS tiered
),
expected_excluded AS (
    SELECT natural_row.candidate_id,
        CASE WHEN natural_row.official_group_or_brand
            THEN LEAST(4.1, GREATEST(1.0, natural_row.natural_display_score))
            ELSE natural_row.natural_display_score
        END::NUMERIC AS display_score,
        CASE WHEN natural_row.official_group_or_brand THEN 'normal'
            ELSE natural_row.natural_risk_band END AS risk_band,
        FALSE AS relative_tier_applied
    FROM natural_rows AS natural_row
    WHERE natural_row.strong_partner OR natural_row.official_group_or_brand
)
SELECT * FROM expected_eligible
UNION ALL
SELECT * FROM expected_excluded
ORDER BY candidate_id;
$$;


--
-- Name: analysis_v2_fail_result_and_purge_internal(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_fail_result_and_purge_internal(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_receipt public.analysis_v2_failure_receipts%ROWTYPE;
BEGIN
    IF p_request_id IS NULL OR p_job_key IS NULL
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_error_code IS NULL OR p_error_code !~ '^[A-Z][A-Z0-9_]{0,63}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;
    PERFORM 1 FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id FOR UPDATE;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    SELECT receipt.* INTO v_receipt
    FROM public.analysis_v2_failure_receipts AS receipt
    WHERE receipt.request_id = p_request_id FOR UPDATE;

    IF v_request.id IS NULL OR v_job.request_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    IF v_request.status = 'failed' THEN
        IF v_receipt.request_id IS NULL
           OR v_receipt.failed_job_key IS DISTINCT FROM p_job_key
           OR v_receipt.failed_job_input_hash IS DISTINCT FROM p_job_input_hash
           OR v_receipt.failed_claim_token IS DISTINCT FROM p_claim_token
           OR v_receipt.error_code IS DISTINCT FROM p_error_code THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'finalized', FALSE, 'requestStatus', 'failed'
        );
    END IF;
    IF v_request.status NOT IN ('pending', 'processing')
       OR v_job.status <> 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    INSERT INTO public.analysis_v2_failure_receipts (
        request_id, failed_job_key, failed_job_input_hash, failed_claim_token, error_code
    ) VALUES (
        p_request_id, p_job_key, p_job_input_hash, p_claim_token, p_error_code
    );
    PERFORM public.fail_analysis_v2_request_from_job(
        p_request_id, p_job_key, p_error_code
    );
    RETURN pg_catalog.jsonb_build_object(
        'finalized', TRUE, 'requestStatus', 'failed'
    );
END;
$_$;


--
-- Name: analysis_v2_fill_exact_adoption_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_fill_exact_adoption_identity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_source_input_hash TEXT;
BEGIN
    IF NEW.source_operation_key IS NULL THEN
        NEW.source_operation_key := NEW.operation_key;
    END IF;
    IF NEW.destination_input_hash IS NULL THEN
        SELECT source_run.input_hash INTO v_source_input_hash
        FROM public.analysis_v2_provider_runs AS source_run
        WHERE source_run.request_id = NEW.source_request_id
          AND source_run.job_key = NEW.source_job_key
          AND source_run.operation_key = NEW.source_operation_key
          AND source_run.run_id = NEW.source_run_id;
        NEW.destination_input_hash := v_source_input_hash;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: analysis_v2_gender_routing_manifests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_gender_routing_manifests (
    request_id uuid NOT NULL,
    relationship_job_key character varying(160) NOT NULL,
    relationship_job_input_hash character varying(64) NOT NULL,
    relationship_checkpoint_id character varying(64) NOT NULL,
    policy_version character varying(64) NOT NULL,
    manifest_schema_version smallint DEFAULT 1 NOT NULL,
    plan_id text NOT NULL,
    detailed_cap smallint NOT NULL,
    population_count smallint NOT NULL,
    canonical_input_hmac character varying(64) NOT NULL,
    status text DEFAULT 'building'::text NOT NULL,
    attempt_count smallint DEFAULT 1 NOT NULL,
    selected_count smallint,
    model_attempted_count smallint,
    model_valid_count smallint,
    model_failed_count smallint,
    model_retried_count smallint,
    quota_female_shortfall smallint,
    quota_uncertainty_shortfall smallint,
    female_priority_count smallint,
    uncertainty_count smallint,
    male_deprioritized_count smallint,
    selected_female_priority_count smallint,
    selected_uncertainty_count smallint,
    selected_male_deprioritized_count smallint,
    candidate_rows_hash character varying(32),
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    invalidated_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_v2_gender_routing_ma_relationship_job_input_hash_check CHECK (((relationship_job_input_hash)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT analysis_v2_gender_routing_man_relationship_checkpoint_id_check CHECK (((relationship_checkpoint_id)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT analysis_v2_gender_routing_manife_manifest_schema_version_check CHECK ((manifest_schema_version = 1)),
    CONSTRAINT analysis_v2_gender_routing_manifest_complete_check CHECK ((((status = 'building'::text) AND (selected_count IS NULL) AND (model_attempted_count IS NULL) AND (model_valid_count IS NULL) AND (model_failed_count IS NULL) AND (model_retried_count IS NULL) AND (quota_female_shortfall IS NULL) AND (quota_uncertainty_shortfall IS NULL) AND (female_priority_count IS NULL) AND (uncertainty_count IS NULL) AND (male_deprioritized_count IS NULL) AND (selected_female_priority_count IS NULL) AND (selected_uncertainty_count IS NULL) AND (selected_male_deprioritized_count IS NULL) AND (candidate_rows_hash IS NULL) AND (completed_at IS NULL) AND (invalidated_at IS NULL)) OR ((status = 'complete'::text) AND (selected_count = LEAST(population_count, detailed_cap)) AND ((model_attempted_count >= 0) AND (model_attempted_count <= population_count)) AND ((model_valid_count >= 0) AND (model_valid_count <= model_attempted_count)) AND ((model_failed_count >= 0) AND (model_failed_count <= model_attempted_count)) AND ((model_retried_count >= 0) AND (model_retried_count <= population_count)) AND ((quota_female_shortfall >= 0) AND (quota_female_shortfall <= 160)) AND ((quota_uncertainty_shortfall >= 0) AND (quota_uncertainty_shortfall <= 40)) AND ((female_priority_count >= 0) AND (female_priority_count <= population_count)) AND ((uncertainty_count >= 0) AND (uncertainty_count <= population_count)) AND ((male_deprioritized_count >= 0) AND (male_deprioritized_count <= population_count)) AND ((selected_female_priority_count >= 0) AND (selected_female_priority_count <= selected_count)) AND ((selected_uncertainty_count >= 0) AND (selected_uncertainty_count <= selected_count)) AND ((selected_male_deprioritized_count >= 0) AND (selected_male_deprioritized_count <= selected_count)) AND ((candidate_rows_hash)::text ~ '^[a-f0-9]{32}$'::text) AND (completed_at IS NOT NULL) AND (invalidated_at IS NULL)) OR ((status = 'invalidated'::text) AND (invalidated_at IS NOT NULL)))),
    CONSTRAINT analysis_v2_gender_routing_manifest_plan_cap_check CHECK ((((plan_id = 'basic'::text) AND (detailed_cap = 100) AND (population_count <= 400)) OR ((plan_id = 'standard'::text) AND (detailed_cap = 200) AND (population_count <= 800)))),
    CONSTRAINT analysis_v2_gender_routing_manifests_attempt_count_check CHECK (((attempt_count >= 1) AND (attempt_count <= 32767))),
    CONSTRAINT analysis_v2_gender_routing_manifests_canonical_input_hmac_check CHECK (((canonical_input_hmac)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT analysis_v2_gender_routing_manifests_detailed_cap_check CHECK ((detailed_cap = ANY (ARRAY[100, 200]))),
    CONSTRAINT analysis_v2_gender_routing_manifests_plan_id_check CHECK ((plan_id = ANY (ARRAY['basic'::text, 'standard'::text]))),
    CONSTRAINT analysis_v2_gender_routing_manifests_policy_version_check CHECK (((policy_version)::text = 'gender-routing-v1'::text)),
    CONSTRAINT analysis_v2_gender_routing_manifests_population_count_check CHECK (((population_count >= 0) AND (population_count <= 800))),
    CONSTRAINT analysis_v2_gender_routing_manifests_relationship_job_key_check CHECK (((relationship_job_key)::text = 'track:relationships:collect'::text)),
    CONSTRAINT analysis_v2_gender_routing_manifests_status_check CHECK ((status = ANY (ARRAY['building'::text, 'complete'::text, 'invalidated'::text])))
);

ALTER TABLE ONLY public.analysis_v2_gender_routing_manifests FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_gender_routing_manifest_json(public.analysis_v2_gender_routing_manifests); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_gender_routing_manifest_json(p_manifest public.analysis_v2_gender_routing_manifests) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
        'status', p_manifest.status,
        'attemptCount', p_manifest.attempt_count,
        'requestId', p_manifest.request_id,
        'relationshipCheckpointId', p_manifest.relationship_checkpoint_id,
        'relationshipJobInputHash', p_manifest.relationship_job_input_hash,
        'policyVersion', p_manifest.policy_version,
        'planId', p_manifest.plan_id,
        'canonicalInputHmac', p_manifest.canonical_input_hmac,
        'populationCount', p_manifest.population_count,
        'detailedCap', p_manifest.detailed_cap,
        'selectedCount', p_manifest.selected_count,
        'modelAttemptedCount', p_manifest.model_attempted_count,
        'modelValidCount', p_manifest.model_valid_count,
        'modelFailedCount', p_manifest.model_failed_count,
        'modelRetriedCount', p_manifest.model_retried_count,
        'quotaFemaleShortfall', p_manifest.quota_female_shortfall,
        'quotaUncertaintyShortfall', p_manifest.quota_uncertainty_shortfall,
        'femalePriorityCount', p_manifest.female_priority_count,
        'uncertaintyCount', p_manifest.uncertainty_count,
        'maleDeprioritizedCount', p_manifest.male_deprioritized_count,
        'selectedFemalePriorityCount', p_manifest.selected_female_priority_count,
        'selectedUncertaintyCount', p_manifest.selected_uncertainty_count,
        'selectedMaleDeprioritizedCount', p_manifest.selected_male_deprioritized_count
    ));
$$;


--
-- Name: analysis_v2_gender_scheduler_contains_hash(jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_gender_scheduler_contains_hash(p_result jsonb, p_expected_operation_key text, p_result_hash text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
BEGIN
    IF p_expected_operation_key !~ '^gender-triage:[a-f0-9]{64}$'
       OR p_result_hash !~ '^[a-f0-9]{64}$'
       OR pg_catalog.jsonb_typeof(p_result) <> 'object'
       OR NOT p_result ?& ARRAY['operationKey', 'results']
       OR (
            SELECT pg_catalog.count(*)
            FROM pg_catalog.jsonb_object_keys(p_result)
       ) <> 2
       OR pg_catalog.jsonb_typeof(p_result->'operationKey') <> 'string'
       OR p_result->>'operationKey' IS DISTINCT FROM p_expected_operation_key
       OR pg_catalog.jsonb_typeof(p_result->'results') <> 'array'
       OR pg_catalog.jsonb_array_length(p_result->'results') NOT BETWEEN 1 AND 64
       OR pg_catalog.octet_length(p_result::TEXT) > 524288 THEN
        RETURN FALSE;
    END IF;

    RETURN EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_result->'results') AS item(value)
        WHERE item.value->>'source' IN ('checkpoint', 'safe_fallback')
          AND pg_catalog.jsonb_typeof(item.value->'result'->'assessment') = 'object'
          AND pg_catalog.encode(
                extensions.digest(
                    pg_catalog.convert_to(
                        'analysis-v2-ai-result-content:v1',
                        'UTF8'
                    )
                        || pg_catalog.decode('00', 'hex')
                        || pg_catalog.convert_to(
                            public.analysis_v2_ai_canonical_json_text(
                                item.value->'result'->'assessment'
                            ),
                            'UTF8'
                        ),
                    'sha256'
                ),
                'hex'
          ) = p_result_hash
    );
EXCEPTION WHEN OTHERS THEN
    RETURN FALSE;
END;
$_$;


--
-- Name: analysis_v2_is_first_payment_concierge_publication(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_is_first_payment_concierge_publication(p_request_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.earlybird_v211_concierge_publications AS publication
        WHERE publication.request_id = p_request_id
          AND publication.status = 'publishing'
    );
$$;


--
-- Name: analysis_v2_load_operational_observability_internal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_load_operational_observability_internal(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
BEGIN
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_OBSERVABILITY_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id;
    IF NOT FOUND OR v_request.pipeline_version IS DISTINCT FROM 'v2' THEN
        RETURN NULL;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.analysis_pipeline_jobs AS job
        WHERE job.request_id = p_request_id
          AND job.job_key !~ '^(coordinator:(bootstrap|candidate-screening|finalize|join:(primary-evidence|final-score))|track:(relationships:collect|target-evidence:collect|profiles:batch:[0-9]+|profile-ai:batch:[0-9]+|private-names:batch:[0-9]+|reverse-likes:collect|partner-safety:batch:0|narratives:batch:0))$'
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_OBSERVABILITY_UNSAFE_JOB', ERRCODE = 'P0001';
    END IF;

    RETURN (
        WITH provider AS (
            SELECT
                pg_catalog.count(*)::INTEGER AS run_count,
                pg_catalog.count(*) FILTER (
                    WHERE provider_run.status IN ('starting', 'running')
                )::INTEGER AS active_count,
                pg_catalog.count(*) FILTER (
                    WHERE provider_run.status IN (
                        'succeeded', 'failed', 'aborted', 'timed_out'
                    ) AND provider_run.actual_usage_usd IS NULL
                )::INTEGER AS unreconciled_count,
                pg_catalog.count(provider_run.actual_usage_usd)::INTEGER
                    AS actual_cost_count,
                COALESCE(pg_catalog.sum(provider_run.actual_usage_usd), 0::NUMERIC)
                    AS actual_usd,
                COALESCE(pg_catalog.sum(COALESCE(
                    provider_run.actual_usage_usd,
                    provider_run.max_charge_usd
                )), 0::NUMERIC) AS conservative_usd,
                COALESCE(pg_catalog.sum(CASE
                    WHEN provider_run.run_started_at IS NULL THEN 0
                    ELSE pg_catalog.floor(pg_catalog.date_part('epoch', (
                        COALESCE(
                            provider_run.terminalized_at,
                            pg_catalog.statement_timestamp()
                        ) - provider_run.run_started_at
                    )) * 1000)::BIGINT
                END), 0::NUMERIC)::BIGINT AS runtime_ms_total
            FROM public.analysis_v2_provider_runs AS provider_run
            WHERE provider_run.request_id = p_request_id
        ),
        ai AS (
            SELECT
                pg_catalog.count(*)::INTEGER AS attempt_count,
                pg_catalog.count(*) FILTER (
                    WHERE ai_attempt.status = 'reserved'
                )::INTEGER AS reserved_count,
                pg_catalog.count(*) FILTER (
                    WHERE ai_attempt.status <> 'reserved'
                      AND (
                          ai_attempt.usage_complete IS DISTINCT FROM TRUE
                          OR ai_attempt.estimated_cost_usd IS NULL
                      )
                )::INTEGER AS missing_usage_count,
                pg_catalog.count(ai_attempt.estimated_cost_usd)::INTEGER
                    AS estimated_cost_count,
                COALESCE(pg_catalog.sum(ai_attempt.estimated_cost_usd), 0::NUMERIC)
                    AS estimated_usd,
                COALESCE(pg_catalog.sum(ai_attempt.latency_ms), 0::BIGINT)::BIGINT
                    AS latency_ms_total,
                COALESCE(pg_catalog.sum(ai_attempt.prompt_tokens), 0::BIGINT)::BIGINT
                    AS prompt_tokens,
                COALESCE(pg_catalog.sum(ai_attempt.completion_tokens), 0::BIGINT)::BIGINT
                    AS completion_tokens,
                COALESCE(pg_catalog.sum(ai_attempt.thinking_tokens), 0::BIGINT)::BIGINT
                    AS thinking_tokens
            FROM public.analysis_v2_ai_attempts AS ai_attempt
            WHERE ai_attempt.request_id = p_request_id
        ),
        job_rollup AS (
            SELECT
                pg_catalog.count(*)::INTEGER AS job_count,
                pg_catalog.count(*) FILTER (
                    WHERE job.status = 'pending'
                )::INTEGER AS pending_count,
                pg_catalog.count(*) FILTER (
                    WHERE job.status = 'processing'
                )::INTEGER AS processing_count,
                pg_catalog.count(*) FILTER (
                    WHERE job.status = 'completed'
                )::INTEGER AS completed_count,
                pg_catalog.count(*) FILTER (
                    WHERE job.status = 'failed'
                )::INTEGER AS failed_count,
                pg_catalog.count(*) FILTER (
                    WHERE job.status = 'cancelled'
                )::INTEGER AS cancelled_count,
                pg_catalog.min(job.first_started_at) AS first_started_at,
                pg_catalog.max(job.completed_at) AS last_completed_at,
                COALESCE(pg_catalog.sum(job.attempt_count), 0::BIGINT)::BIGINT
                    AS attempt_count_total
            FROM public.analysis_pipeline_jobs AS job
            WHERE job.request_id = p_request_id
        ),
        profile_rows AS (
            SELECT COALESCE(pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'jobKey', telemetry.job_key,
                    'source', telemetry.source,
                    'status', telemetry.status,
                    'failureCategory', telemetry.failure_category,
                    'httpStatus', telemetry.http_status,
                    'outcomeCount', telemetry.outcome_count,
                    'requestCount', telemetry.request_count_total,
                    'latencyMsTotal', telemetry.latency_ms_total,
                    'latencyMsMax', telemetry.latency_ms_max
                ) ORDER BY
                    telemetry.job_key,
                    telemetry.source,
                    telemetry.status,
                    telemetry.failure_category NULLS FIRST,
                    telemetry.http_status NULLS FIRST
            ), '[]'::JSONB) AS payload
            FROM public.analysis_v2_profile_fetch_telemetry AS telemetry
            WHERE telemetry.request_id = p_request_id
        ),
        coverage AS (
            SELECT pg_catalog.jsonb_build_object(
                'planId', telemetry.plan_id,
                'followersDeclared', telemetry.followers_declared,
                'followersCollected', telemetry.followers_collected,
                'followingDeclared', telemetry.following_declared,
                'followingCollected', telemetry.following_collected,
                'detectedMutuals', telemetry.detected_mutuals,
                'publicMutuals', telemetry.public_mutuals,
                'privateMutuals', telemetry.private_mutuals,
                'screenedMutuals', telemetry.screened_mutuals,
                'notScreenedMutuals', telemetry.not_screened_mutuals,
                'fetchUnavailableCount', telemetry.fetch_unavailable_count,
                'mediaUnavailableCount', telemetry.media_unavailable_count
            ) AS payload
            FROM public.analysis_v2_result_coverage_telemetry AS telemetry
            WHERE telemetry.request_id = p_request_id
        ),
        jobs AS (
            SELECT COALESCE(pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'jobKey', job.job_key,
                    'track', job.track,
                    'kind', job.kind,
                    'batch', job.batch,
                    'status', job.status,
                    'dispatchState', job.dispatch_state,
                    'attemptCount', job.attempt_count,
                    'firstStartedAt', job.first_started_at,
                    'completedAt', job.completed_at,
                    'durationMs', CASE
                        WHEN job.first_started_at IS NULL THEN NULL
                        ELSE GREATEST(0, pg_catalog.floor(pg_catalog.date_part('epoch', (
                            COALESCE(
                                job.completed_at,
                                pg_catalog.statement_timestamp()
                            ) - job.first_started_at
                        )) * 1000)::BIGINT)
                    END,
                    'lastErrorCode', job.last_error_code
                ) ORDER BY job.job_key
            ), '[]'::JSONB) AS payload
            FROM public.analysis_pipeline_jobs AS job
            WHERE job.request_id = p_request_id
        )
        SELECT pg_catalog.jsonb_build_object(
            'pipelineVersion', 'v2',
            'summary', pg_catalog.jsonb_build_object(
                'schemaVersion', 1,
                'requestId', p_request_id,
                'requestStatus', v_request.status,
                'planId', v_request.selected_plan_id_snapshot,
                'timing', pg_catalog.jsonb_build_object(
                    'createdAt', v_request.created_at,
                    'firstStartedAt', job_rollup.first_started_at,
                    'completedAt', v_request.completed_at,
                    'wallTimeMs', GREATEST(0, pg_catalog.floor(
                        pg_catalog.date_part('epoch', (
                            COALESCE(
                                v_request.completed_at,
                                pg_catalog.statement_timestamp()
                            ) - v_request.created_at
                        )) * 1000
                    )::BIGINT),
                    'queueDelayMs', CASE
                        WHEN job_rollup.first_started_at IS NULL THEN NULL
                        ELSE GREATEST(0, pg_catalog.floor(pg_catalog.date_part('epoch', (
                            job_rollup.first_started_at - v_request.created_at
                        )) * 1000)::BIGINT)
                    END,
                    'processingTimeMs', CASE
                        WHEN job_rollup.first_started_at IS NULL THEN NULL
                        ELSE GREATEST(0, pg_catalog.floor(pg_catalog.date_part('epoch', (
                            COALESCE(
                                v_request.completed_at,
                                pg_catalog.statement_timestamp()
                            ) - job_rollup.first_started_at
                        )) * 1000)::BIGINT)
                    END,
                    'providerRuntimeMsTotal', provider.runtime_ms_total,
                    'geminiLatencyMsTotal', ai.latency_ms_total
                ),
                'cost', pg_catalog.jsonb_build_object(
                    'currency', 'USD',
                    'providerActualUsd', provider.actual_usd,
                    'providerConservativeUsd', provider.conservative_usd,
                    'geminiEstimatedUsd', ai.estimated_usd,
                    'actualPlusGeminiEstimatedUsd',
                        provider.actual_usd + ai.estimated_usd,
                    'conservativePlusGeminiEstimatedUsd',
                        provider.conservative_usd + ai.estimated_usd,
                    'gcpInfrastructureIncluded', FALSE
                ),
                'completeness', pg_catalog.jsonb_build_object(
                    'costComplete',
                        v_request.status IN ('completed', 'failed')
                        AND provider.active_count = 0
                        AND provider.unreconciled_count = 0
                        AND ai.reserved_count = 0
                        AND ai.missing_usage_count = 0,
                    'pipelineComplete',
                        v_request.status = 'completed'
                        AND job_rollup.job_count > 0
                        AND job_rollup.pending_count = 0
                        AND job_rollup.processing_count = 0
                        AND job_rollup.failed_count = 0
                        AND job_rollup.cancelled_count = 0
                        AND EXISTS (SELECT 1 FROM coverage),
                    'resultCoverageAvailable', EXISTS (SELECT 1 FROM coverage),
                    'providerRunCount', provider.run_count,
                    'providerActiveCount', provider.active_count,
                    'providerUnreconciledCount', provider.unreconciled_count,
                    'providerActualCostCount', provider.actual_cost_count,
                    'aiAttemptCount', ai.attempt_count,
                    'aiReservedCount', ai.reserved_count,
                    'aiMissingUsageCount', ai.missing_usage_count,
                    'aiEstimatedCostCount', ai.estimated_cost_count,
                    'jobCount', job_rollup.job_count,
                    'jobPendingCount', job_rollup.pending_count,
                    'jobProcessingCount', job_rollup.processing_count,
                    'jobCompletedCount', job_rollup.completed_count,
                    'jobFailedCount', job_rollup.failed_count,
                    'jobCancelledCount', job_rollup.cancelled_count,
                    'jobAttemptCountTotal', job_rollup.attempt_count_total
                ),
                'geminiUsage', pg_catalog.jsonb_build_object(
                    'promptTokens', ai.prompt_tokens,
                    'completionTokens', ai.completion_tokens,
                    'thinkingTokens', ai.thinking_tokens
                ),
                'profileOutcomes', profile_rows.payload,
                'resultCoverage', (SELECT coverage.payload FROM coverage)
            ),
            'jobs', jobs.payload
        )
        FROM provider, ai, job_rollup, profile_rows, jobs
    );
END;
$_$;


--
-- Name: analysis_v2_load_progress_internal(uuid, uuid, bigint, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_load_progress_internal(p_request_id uuid, p_user_id uuid, p_after_sequence bigint, p_event_limit integer, p_include_candidate_media boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_state public.analysis_progress_state%ROWTYPE;
    v_events JSONB;
    v_active_profile JSONB;
    v_candidate_media JSONB := '[]'::JSONB;
    v_snapshot JSONB;
BEGIN
    IF p_request_id IS NULL
       OR p_user_id IS NULL
       OR p_after_sequence IS NULL
       OR p_after_sequence < 0
       OR p_after_sequence > 9007199254740991
       OR p_event_limit IS NULL
       OR p_event_limit < 1
       OR p_event_limit > 200
       OR p_include_candidate_media IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_INVALID', ERRCODE = 'P0001';
    END IF;

    -- The owner check is deliberately before any profile outcome is read.
    IF NOT EXISTS (
        SELECT 1
        FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = p_request_id
          AND analysis_request.user_id = p_user_id
          AND analysis_request.pipeline_version = 'v2'
    ) THEN
        RETURN NULL;
    END IF;

    SELECT progress_state.* INTO v_state
    FROM public.analysis_progress_state AS progress_state
    WHERE progress_state.request_id = p_request_id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    IF v_state.status = 'processing' THEN
        SELECT
            pg_catalog.jsonb_build_object(
                'maskedUsername', heartbeat.masked_username,
                'imageUrl', heartbeat.image_url,
                'feedImageUrls', heartbeat.feed_image_urls,
                'currentOrdinal', heartbeat.completed_count,
                'totalCount', heartbeat.total_count,
                'callPhase', heartbeat.call_phase
            ) || CASE
                WHEN heartbeat.candidate_key IS NULL THEN '{}'::JSONB
                ELSE pg_catalog.jsonb_build_object(
                    'candidateKey', heartbeat.candidate_key
                )
            END
        INTO v_active_profile
        FROM public.analysis_v2_active_profile_heartbeats AS heartbeat
        JOIN public.analysis_pipeline_jobs AS job
          ON job.request_id = heartbeat.request_id
         AND job.job_key = heartbeat.job_key
        WHERE heartbeat.request_id = p_request_id
          AND job.status = 'processing'
          AND job.input_hash = heartbeat.job_input_hash
          AND job.lease_token = heartbeat.claim_token
          AND job.lease_expires_at > pg_catalog.clock_timestamp()
        ORDER BY heartbeat.started_at DESC, heartbeat.updated_at DESC, heartbeat.job_key DESC
        LIMIT 1;

        IF p_include_candidate_media THEN
            -- Emit only the image-bearing projection needed by the owner rail;
            -- never aggregate the full private profile snapshot.
            SELECT COALESCE(pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'username', candidate.username,
                    'profile', pg_catalog.jsonb_strip_nulls(
                        pg_catalog.jsonb_build_object(
                            'profilePicUrl', candidate.profile_snapshot->'profilePicUrl',
                            'latestPosts', (
                                SELECT COALESCE(pg_catalog.jsonb_agg(
                                    pg_catalog.jsonb_strip_nulls(
                                        pg_catalog.jsonb_build_object(
                                            'type', post.value->'type',
                                            'imageUrl', post.value->'imageUrl',
                                            'thumbnailUrl', post.value->'thumbnailUrl',
                                            'videoUrl', post.value->'videoUrl',
                                            'mediaItems', CASE
                                                WHEN post.value->>'type' = 'carousel' THEN (
                                                    SELECT COALESCE(pg_catalog.jsonb_agg(
                                                        pg_catalog.jsonb_strip_nulls(
                                                            pg_catalog.jsonb_build_object(
                                                                'type', child.value->'type',
                                                                'imageUrl', child.value->'imageUrl',
                                                                'thumbnailUrl', child.value->'thumbnailUrl',
                                                                'videoUrl', child.value->'videoUrl'
                                                            )
                                                        ) ORDER BY child.ordinality
                                                    ), '[]'::JSONB)
                                                    FROM pg_catalog.jsonb_array_elements(
                                                        CASE
                                                            WHEN pg_catalog.jsonb_typeof(post.value->'mediaItems') = 'array'
                                                                THEN post.value->'mediaItems'
                                                            ELSE '[]'::JSONB
                                                        END
                                                    ) WITH ORDINALITY AS child(value, ordinality)
                                                    WHERE child.ordinality <= 20
                                                )
                                                ELSE NULL
                                            END
                                        )
                                    ) ORDER BY post.ordinality
                                ), '[]'::JSONB)
                                FROM pg_catalog.jsonb_array_elements(
                                    CASE
                                        WHEN pg_catalog.jsonb_typeof(candidate.profile_snapshot->'latestPosts') = 'array'
                                            THEN candidate.profile_snapshot->'latestPosts'
                                        ELSE '[]'::JSONB
                                    END
                                ) WITH ORDINALITY AS post(value, ordinality)
                                WHERE post.ordinality <= 8
                            )
                        )
                    )
                )
                ORDER BY candidate.captured_at ASC, candidate.ordinal, candidate.username
            ), '[]'::JSONB)
            INTO v_candidate_media
            FROM (
                SELECT candidate.username, candidate.profile_snapshot, candidate.captured_at, candidate.ordinal
                FROM (
                    SELECT DISTINCT ON (outcome.username)
                        outcome.username,
                        outcome.profile_snapshot,
                        outcome.captured_at,
                        outcome.ordinal
                    FROM public.analysis_v2_profile_fetch_outcomes AS outcome
                    WHERE outcome.request_id = p_request_id
                      AND outcome.job_key LIKE 'track:profiles:batch:%'
                      AND outcome.status = 'success'
                      AND outcome.profile_snapshot IS NOT NULL
                      AND outcome.profile_snapshot->>'isPrivate' = 'false'
                    ORDER BY outcome.username,
                        outcome.captured_at DESC,
                        outcome.ordinal DESC,
                        CASE outcome.attempt
                            WHEN 'repair' THEN 0
                            WHEN 'fallback' THEN 1
                            ELSE 2
                        END
                ) AS candidate
                -- Select newest unique candidates, then emit oldest-first for
                -- deterministic client reconciliation and rail motion.
                ORDER BY candidate.captured_at DESC, candidate.ordinal DESC, candidate.username DESC
                LIMIT 20
            ) AS candidate;
        END IF;
    END IF;

    SELECT COALESCE(pg_catalog.jsonb_agg(page.event_json ORDER BY page.seq), '[]'::JSONB)
    INTO v_events
    FROM (
        SELECT
            progress_event.seq,
            public.analysis_v2_progress_event_json(progress_event) AS event_json
        FROM public.analysis_progress_events AS progress_event
        WHERE progress_event.request_id = p_request_id
          AND progress_event.seq > p_after_sequence
        ORDER BY progress_event.seq
        LIMIT p_event_limit
    ) AS page;

    v_snapshot := pg_catalog.jsonb_set(
        public.analysis_v2_progress_snapshot_json(v_state),
        '{activeProfile}',
        COALESCE(v_active_profile, 'null'::JSONB),
        TRUE
    );
    IF p_include_candidate_media THEN
        v_snapshot := pg_catalog.jsonb_set(
            v_snapshot,
            '{candidateMediaRaw}',
            v_candidate_media,
            TRUE
        );
    END IF;
    RETURN pg_catalog.jsonb_build_object('snapshot', v_snapshot, 'events', v_events);
END;
$$;


--
-- Name: analysis_v2_valid_provider_operation_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_provider_operation_key(p_operation_key text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
    SELECT pg_catalog.char_length(p_operation_key) BETWEEN 78 AND 87
       AND p_operation_key ~ '^(target-profile|profile-fallback|profile-repair|relationship-followers|relationship-following|target-likers|target-comments|candidate-likers):[0-9a-f]{64}$';
$_$;


--
-- Name: analysis_v2_provider_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_provider_runs (
    request_id uuid NOT NULL,
    job_key character varying(160) NOT NULL,
    operation_key character varying(87) NOT NULL,
    input_hash character varying(64) NOT NULL,
    job_claim_token uuid NOT NULL,
    reservation_token uuid NOT NULL,
    logical_provider character varying(16) NOT NULL,
    actor_id character varying(200) NOT NULL,
    credential_slot character varying(16) NOT NULL,
    max_charge_usd numeric(18,12) NOT NULL,
    status character varying(16) DEFAULT 'starting'::character varying NOT NULL,
    run_id character varying(64),
    actual_usage_usd numeric(18,12),
    reserved_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    run_started_at timestamp with time zone,
    terminalized_at timestamp with time zone,
    usage_reconciled_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    usage_reconciliation_attempt_count integer DEFAULT 0 NOT NULL,
    usage_reconciliation_attempted_at timestamp with time zone,
    manual_resolution_kind text,
    manual_resolution_evidence_hash text,
    manual_resolved_at timestamp with time zone,
    CONSTRAINT analysis_v2_provider_run_actor_check CHECK ((((char_length((actor_id)::text) >= 3) AND (char_length((actor_id)::text) <= 200)) AND ((actor_id)::text ~ '^[A-Za-z0-9][A-Za-z0-9._~/-]{2,199}$'::text))),
    CONSTRAINT analysis_v2_provider_run_cost_check CHECK ((((max_charge_usd >= (0)::numeric) AND (max_charge_usd <= (100000)::numeric)) AND ((actual_usage_usd IS NULL) OR ((actual_usage_usd >= (0)::numeric) AND (actual_usage_usd <= (100000)::numeric))))),
    CONSTRAINT analysis_v2_provider_run_credential_check CHECK (public.analysis_v2_valid_apify_credential_slot((credential_slot)::text)),
    CONSTRAINT analysis_v2_provider_run_input_hash_check CHECK (((input_hash)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT analysis_v2_provider_run_job_key_check CHECK ((((char_length((job_key)::text) >= 1) AND (char_length((job_key)::text) <= 160)) AND ((job_key)::text ~ '^[a-z0-9][a-z0-9:._-]{0,159}$'::text))),
    CONSTRAINT analysis_v2_provider_run_operation_key_check CHECK (public.analysis_v2_valid_provider_operation_key((operation_key)::text)),
    CONSTRAINT analysis_v2_provider_run_provider_check CHECK (((logical_provider)::text = ANY ((ARRAY['apify'::character varying, 'coderx'::character varying])::text[]))),
    CONSTRAINT analysis_v2_provider_run_run_id_check CHECK (((run_id IS NULL) OR ((run_id)::text ~ '^[A-Za-z0-9]{8,64}$'::text))),
    CONSTRAINT analysis_v2_provider_run_state_check CHECK (((((status)::text = 'starting'::text) AND (run_id IS NULL) AND (run_started_at IS NULL) AND (terminalized_at IS NULL) AND (actual_usage_usd IS NULL) AND (usage_reconciled_at IS NULL)) OR (((status)::text = 'running'::text) AND (run_id IS NOT NULL) AND (run_started_at IS NOT NULL) AND (terminalized_at IS NULL) AND (actual_usage_usd IS NULL) AND (usage_reconciled_at IS NULL)) OR (((status)::text = 'rejected'::text) AND (run_id IS NULL) AND (run_started_at IS NULL) AND (terminalized_at IS NOT NULL) AND (actual_usage_usd = (0)::numeric) AND (usage_reconciled_at IS NOT NULL)) OR (((status)::text = ANY ((ARRAY['succeeded'::character varying, 'failed'::character varying, 'aborted'::character varying, 'timed_out'::character varying])::text[])) AND (run_id IS NOT NULL) AND (run_started_at IS NOT NULL) AND (terminalized_at IS NOT NULL) AND (((actual_usage_usd IS NULL) AND (usage_reconciled_at IS NULL)) OR ((actual_usage_usd IS NOT NULL) AND (usage_reconciled_at IS NOT NULL)))))),
    CONSTRAINT analysis_v2_provider_run_status_check CHECK (((status)::text = ANY ((ARRAY['starting'::character varying, 'running'::character varying, 'rejected'::character varying, 'succeeded'::character varying, 'failed'::character varying, 'aborted'::character varying, 'timed_out'::character varying])::text[]))),
    CONSTRAINT analysis_v2_provider_run_time_check CHECK (((updated_at >= reserved_at) AND ((run_started_at IS NULL) OR (run_started_at >= reserved_at)) AND ((terminalized_at IS NULL) OR (terminalized_at >= run_started_at)) AND ((usage_reconciled_at IS NULL) OR (usage_reconciled_at >= terminalized_at)))),
    CONSTRAINT analysis_v2_provider_runs_manual_resolution_contract CHECK ((((manual_resolution_kind IS NULL) AND (manual_resolution_evidence_hash IS NULL) AND (manual_resolved_at IS NULL)) OR ((manual_resolution_kind = 'conservative_max_charge'::text) AND (manual_resolution_evidence_hash ~ '^[0-9a-f]{64}$'::text) AND (manual_resolved_at IS NOT NULL) AND (terminalized_at IS NOT NULL) AND (manual_resolved_at >= terminalized_at) AND (actual_usage_usd = max_charge_usd) AND (usage_reconciled_at IS NOT NULL) AND (manual_resolved_at = usage_reconciled_at) AND ((status)::text = 'succeeded'::text) AND (run_id IS NOT NULL) AND (run_started_at IS NOT NULL) AND ((logical_provider)::text = 'apify'::text) AND ((credential_slot)::text = 'tertiary'::text)))),
    CONSTRAINT analysis_v2_provider_usage_attempt_count_check CHECK (((usage_reconciliation_attempt_count >= 0) AND (usage_reconciliation_attempt_count <= 100000))),
    CONSTRAINT analysis_v2_provider_usage_attempt_time_check CHECK (((usage_reconciliation_attempted_at IS NULL) OR (usage_reconciliation_attempted_at >= terminalized_at)))
);

ALTER TABLE ONLY public.analysis_v2_provider_runs FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_load_provider_evidence_source(uuid, text, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_load_provider_evidence_source(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_provider text, p_run_id text, p_credential_slot text DEFAULT NULL::text) RETURNS public.analysis_v2_provider_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_source public.analysis_v2_provider_runs%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
BEGIN
    SELECT job.* INTO STRICT v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_EVIDENCE_SOURCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.* INTO v_source
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
      AND provider_run.job_claim_token = p_claim_token
      AND provider_run.input_hash = p_input_hash
      AND provider_run.logical_provider = p_provider
      AND provider_run.run_id = p_run_id
      AND provider_run.status = 'succeeded'
      AND (
          p_credential_slot IS NULL
          OR provider_run.credential_slot = p_credential_slot
      )
    FOR UPDATE OF provider_run;
    IF FOUND THEN
        IF EXISTS (
            SELECT 1
            FROM public.analysis_v2_recovery_provider_run_adoptions AS adoption
            WHERE adoption.request_id = p_request_id
              AND adoption.job_key = p_job_key
              AND adoption.operation_key = p_operation_key
              AND adoption.destination_input_hash = p_input_hash
        ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROVIDER_EVIDENCE_SOURCE_INVALID',
                ERRCODE = 'P0001';
        END IF;
        RETURN v_source;
    END IF;

    SELECT provider_run.* INTO STRICT v_source
    FROM public.analysis_v2_recovery_provider_run_adoptions AS adoption
    JOIN public.analysis_v2_provider_runs AS provider_run
      ON provider_run.request_id = adoption.source_request_id
     AND provider_run.job_key = adoption.source_job_key
     AND provider_run.operation_key = adoption.source_operation_key
     AND provider_run.run_id = adoption.source_run_id
    WHERE adoption.request_id = p_request_id
      AND adoption.job_key = p_job_key
      AND adoption.operation_key = p_operation_key
      AND adoption.destination_input_hash = p_input_hash
      AND provider_run.logical_provider = p_provider
      AND provider_run.run_id = p_run_id
      AND provider_run.status = 'succeeded'
      AND provider_run.actual_usage_usd IS NOT NULL
      AND provider_run.usage_reconciled_at IS NOT NULL
      AND (
          p_credential_slot IS NULL
          OR provider_run.credential_slot = p_credential_slot
      )
    FOR UPDATE OF provider_run;
    IF EXISTS (
        SELECT 1
        FROM public.analysis_v2_provider_runs AS direct_run
        WHERE direct_run.request_id = p_request_id
          AND direct_run.job_key = p_job_key
          AND direct_run.operation_key = p_operation_key
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_EVIDENCE_SOURCE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    RETURN v_source;
EXCEPTION
    WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_EVIDENCE_SOURCE_INVALID',
            ERRCODE = 'P0001';
END;
$$;


--
-- Name: analysis_v2_selfhosted_auth_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_selfhosted_auth_runs (
    request_id uuid NOT NULL,
    job_key character varying(160) NOT NULL,
    operation_key character varying(87) NOT NULL,
    input_hash character varying(64) NOT NULL,
    job_claim_token uuid NOT NULL,
    run_id character varying(32) NOT NULL,
    account_slot character varying(16) NOT NULL,
    items jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_v2_selfhosted_auth_runs_account_slot_check CHECK (((account_slot)::text = 'primary'::text)),
    CONSTRAINT analysis_v2_selfhosted_auth_runs_input_hash_check CHECK (((input_hash)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT analysis_v2_selfhosted_auth_runs_items_check CHECK (((jsonb_typeof(items) = 'array'::text) AND (jsonb_array_length(items) <= 1500) AND (octet_length((items)::text) <= 4194304))),
    CONSTRAINT analysis_v2_selfhosted_auth_runs_job_key_check CHECK (((job_key)::text = ANY ((ARRAY['track:relationships:collect'::character varying, 'track:target-evidence:collect'::character varying, 'track:reverse-likes:collect'::character varying])::text[]))),
    CONSTRAINT analysis_v2_selfhosted_auth_runs_operation_key_check CHECK (((operation_key)::text ~ '^(relationship-(followers|following)|target-(likers|comments)|candidate-likers):[0-9a-f]{64}$'::text)),
    CONSTRAINT analysis_v2_selfhosted_auth_runs_run_id_check CHECK (((run_id)::text ~ '^[0-9a-f]{32}$'::text))
);

ALTER TABLE ONLY public.analysis_v2_selfhosted_auth_runs FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_load_selfhosted_auth_evidence_source(uuid, text, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_load_selfhosted_auth_evidence_source(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_provider text, p_run_id text, p_account_slot text) RETURNS public.analysis_v2_selfhosted_auth_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_receipt public.analysis_v2_selfhosted_auth_runs%ROWTYPE;
BEGIN
    IF NOT public.analysis_v2_valid_selfhosted_auth_evidence_source(
        p_request_id, p_job_key, p_claim_token, p_operation_key,
        p_input_hash, p_provider, p_run_id, p_account_slot
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SELFHOSTED_AUTH_EVIDENCE_SOURCE_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT receipt.* INTO STRICT v_receipt
    FROM public.analysis_v2_selfhosted_auth_runs AS receipt
    WHERE receipt.request_id = p_request_id
      AND receipt.job_key = p_job_key
      AND receipt.operation_key = p_operation_key
      AND receipt.job_claim_token = p_claim_token
      AND receipt.input_hash = p_input_hash
      AND receipt.run_id = p_run_id
      AND receipt.account_slot = p_account_slot
    FOR UPDATE;
    RETURN v_receipt;
EXCEPTION
    WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SELFHOSTED_AUTH_EVIDENCE_SOURCE_INVALID', ERRCODE = 'P0001';
END;
$$;


--
-- Name: analysis_v2_maintain_ai_global_result_cache(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_maintain_ai_global_result_cache(p_delete_limit integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
    v_acquired BOOLEAN;
    v_now TIMESTAMP WITH TIME ZONE;
    v_deleted_expired INTEGER := 0;
    v_deleted_overflow INTEGER := 0;
BEGIN
    IF p_delete_limit IS NULL OR p_delete_limit NOT BETWEEN 1 AND 10000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_CACHE_MAINTENANCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_acquired := pg_catalog.pg_try_advisory_xact_lock(
        pg_catalog.hashtextextended('analysis-v2-ai-global-cache-maintenance:v1', 0)
    );
    IF NOT v_acquired THEN
        RETURN pg_catalog.jsonb_build_object(
            'acquired', FALSE,
            'deletedExpired', 0,
            'deletedOverflow', 0
        );
    END IF;

    v_now := pg_catalog.clock_timestamp();
    WITH expired AS (
        SELECT cache.ctid
        FROM public.analysis_v2_ai_global_result_cache AS cache
        WHERE cache.expires_at <= v_now
        ORDER BY cache.expires_at, cache.cache_key
        LIMIT p_delete_limit
        FOR UPDATE SKIP LOCKED
    )
    DELETE FROM public.analysis_v2_ai_global_result_cache AS cache
    USING expired
    WHERE cache.ctid = expired.ctid;
    GET DIAGNOSTICS v_deleted_expired = ROW_COUNT;

    WITH overflow AS (
        SELECT cache.ctid
        FROM public.analysis_v2_ai_global_result_cache AS cache
        ORDER BY
            cache.last_accessed_at DESC,
            cache.created_at DESC,
            cache.cache_key
        OFFSET 10000
        LIMIT p_delete_limit
        FOR UPDATE SKIP LOCKED
    )
    DELETE FROM public.analysis_v2_ai_global_result_cache AS cache
    USING overflow
    WHERE cache.ctid = overflow.ctid;
    GET DIAGNOSTICS v_deleted_overflow = ROW_COUNT;

    RETURN pg_catalog.jsonb_build_object(
        'acquired', TRUE,
        'deletedExpired', v_deleted_expired,
        'deletedOverflow', v_deleted_overflow
    );
END;
$$;


--
-- Name: analysis_v2_normalize_apify_secret_ref_prune_slots(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_normalize_apify_secret_ref_prune_slots(p_slots text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.array_agg(requested.slot ORDER BY requested.slot)
    FROM pg_catalog.unnest(p_slots) AS requested(slot);
$$;


--
-- Name: analysis_v2_populate_result_gender_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_populate_result_gender_stats() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_male_count INTEGER;
    v_female_count INTEGER;
    v_unknown_count INTEGER;
BEGIN
    SELECT
        pg_catalog.count(*) FILTER (
            WHERE feature.terminal_classification = 'verified_non_female'
        )::INTEGER,
        pg_catalog.count(*) FILTER (
            WHERE feature.terminal_classification = 'verified_female'
        )::INTEGER,
        pg_catalog.count(*) FILTER (
            WHERE feature.terminal_classification NOT IN (
                'verified_female',
                'verified_non_female'
            )
        )::INTEGER
    INTO v_male_count, v_female_count, v_unknown_count
    FROM public.analysis_v2_candidate_feature_rows AS feature
    WHERE feature.request_id = NEW.request_id;

    IF v_male_count + v_female_count + v_unknown_count <> NEW.screened_mutuals THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    NEW.male_count := v_male_count::SMALLINT;
    NEW.female_count := v_female_count::SMALLINT;
    NEW.unknown_count := v_unknown_count::SMALLINT;
    RETURN NEW;
END;
$$;


--
-- Name: analysis_v2_populate_result_target_full_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_populate_result_target_full_name() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_target_full_name TEXT;
BEGIN
    SELECT NULLIF(pg_catalog.btrim(preflight.target_full_name), '')
    INTO v_target_full_name
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = NEW.request_id;

    NEW.target_full_name := v_target_full_name;
    RETURN NEW;
END;
$$;


--
-- Name: analysis_v2_profile_checkpoint_snapshot(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_profile_checkpoint_snapshot(p_request_id uuid, p_job_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'requestId', batch.request_id,
        'jobKey', batch.job_key,
        'requestedUsernames', pg_catalog.to_jsonb(batch.requested_usernames),
        'frozenUnresolvedUsernames',
            pg_catalog.to_jsonb(batch.frozen_unresolved_usernames),
        'primaryResults', COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'outcome', pg_catalog.jsonb_build_object(
                        'requestedUsername', outcome.username,
                        'source', outcome.source,
                        'status', outcome.status,
                        'failureCategory', outcome.failure_category,
                        'httpStatus', outcome.http_status,
                        'requestCount', outcome.request_count,
                        'latencyMs', outcome.latency_ms,
                        'capturedAt', outcome.captured_at
                    )
                ) || CASE
                    WHEN outcome.status = 'success' THEN
                        pg_catalog.jsonb_build_object('profile', outcome.profile_snapshot)
                    ELSE '{}'::JSONB
                END
                ORDER BY outcome.ordinal
            )
            FROM public.analysis_v2_profile_fetch_outcomes AS outcome
            WHERE outcome.request_id = batch.request_id
              AND outcome.job_key = batch.job_key
              AND outcome.attempt = CASE WHEN EXISTS (
                    SELECT 1
                    FROM public.analysis_v2_profile_fetch_outcomes AS fresh_outcome
                    WHERE fresh_outcome.request_id = batch.request_id
                      AND fresh_outcome.job_key = batch.job_key
                      AND fresh_outcome.attempt = 'fresh_apify'
                ) THEN 'fresh_apify' ELSE 'primary' END
        ), '[]'::JSONB),
        'fallbackResults', COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'outcome', pg_catalog.jsonb_build_object(
                        'requestedUsername', outcome.username,
                        'source', outcome.source,
                        'status', outcome.status,
                        'failureCategory', outcome.failure_category,
                        'httpStatus', outcome.http_status,
                        'requestCount', outcome.request_count,
                        'latencyMs', outcome.latency_ms,
                        'capturedAt', outcome.captured_at
                    )
                ) || CASE
                    WHEN outcome.status = 'success' THEN
                        pg_catalog.jsonb_build_object('profile', outcome.profile_snapshot)
                    ELSE '{}'::JSONB
                END
                ORDER BY outcome.ordinal
            )
            FROM public.analysis_v2_profile_fetch_outcomes AS outcome
            WHERE outcome.request_id = batch.request_id
              AND outcome.job_key = batch.job_key
              AND outcome.attempt = 'fallback'
        ), '[]'::JSONB),
        'repairResults', COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'outcome', pg_catalog.jsonb_build_object(
                        'requestedUsername', outcome.username,
                        'source', outcome.source,
                        'status', outcome.status,
                        'failureCategory', outcome.failure_category,
                        'httpStatus', outcome.http_status,
                        'requestCount', outcome.request_count,
                        'latencyMs', outcome.latency_ms,
                        'capturedAt', outcome.captured_at
                    )
                ) || CASE
                    WHEN outcome.status = 'success' THEN
                        pg_catalog.jsonb_build_object('profile', outcome.profile_snapshot)
                    ELSE '{}'::JSONB
                END
                ORDER BY outcome.ordinal
            )
            FROM public.analysis_v2_profile_fetch_outcomes AS outcome
            WHERE outcome.request_id = batch.request_id
              AND outcome.job_key = batch.job_key
              AND outcome.attempt = 'repair'
        ), '[]'::JSONB),
        'primaryCapturedAt', batch.primary_completed_at,
        'fallbackCapturedAt', batch.fallback_completed_at,
        'repairUsernames', pg_catalog.to_jsonb(batch.repair_usernames),
        'repairCapturedAt', batch.repair_completed_at
    )
    FROM public.analysis_v2_profile_fetch_batches AS batch
    WHERE batch.request_id = p_request_id
      AND batch.job_key = p_job_key;
$$;


--
-- Name: analysis_v2_profile_fetch_bounded_direct_fresh_apify_ready(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_profile_fetch_bounded_direct_fresh_apify_ready(p_request_id uuid, p_job_key text, p_expected_item_count integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT batch.request_id IS NOT NULL
       AND batch.fallback_completed_at IS NULL
       AND batch.fallback_payload_hash IS NULL
       AND batch.repair_completed_at IS NULL
       AND batch.repair_payload_hash IS NULL
       AND batch.repair_usernames IS NULL
       AND pg_catalog.cardinality(batch.requested_usernames) = p_expected_item_count
       AND batch.frozen_unresolved_usernames = COALESCE((
            SELECT pg_catalog.array_agg(outcome.username::TEXT ORDER BY outcome.ordinal)
            FROM public.analysis_v2_profile_fetch_outcomes AS outcome
            WHERE outcome.request_id = batch.request_id
              AND outcome.job_key = batch.job_key
              AND outcome.status <> 'success'
       ), '{}'::TEXT[])
       AND (
            SELECT pg_catalog.count(*)
            FROM public.analysis_v2_profile_fetch_outcomes AS outcome
            WHERE outcome.request_id = batch.request_id
              AND outcome.job_key = batch.job_key
       ) = p_expected_item_count
       -- Only 'failed' rows are bounded; 'unavailable' rows never count
       -- against this ceiling, matching evaluateProfileBatchCompleteness's
       -- `failed = final.filter(status === 'failed')` exactly.
       AND (
            SELECT pg_catalog.count(*)
            FROM public.analysis_v2_profile_fetch_outcomes AS outcome
            WHERE outcome.request_id = batch.request_id
              AND outcome.job_key = batch.job_key
              AND outcome.status = 'failed'
       ) <= (
            p_expected_item_count
            - pg_catalog.ceil(p_expected_item_count * 0.9)::INTEGER
       )
       AND NOT EXISTS (
            SELECT 1
            FROM public.analysis_v2_profile_fetch_outcomes AS outcome
            WHERE outcome.request_id = batch.request_id
              AND outcome.job_key = batch.job_key
              AND (
                   outcome.attempt <> 'fresh_apify'
                   OR outcome.source <> 'apify'
                   OR outcome.ordinal < 1
                   OR outcome.ordinal > p_expected_item_count
                   OR outcome.username IS DISTINCT FROM
                        batch.requested_usernames[outcome.ordinal::INTEGER]
                   OR outcome.status NOT IN ('success', 'unavailable', 'failed')
                   OR (
                        outcome.status = 'failed'
                        AND outcome.failure_category NOT IN ('incomplete', 'schema')
                   )
              )
       )
    FROM public.analysis_v2_profile_fetch_batches AS batch
    WHERE batch.request_id = p_request_id
      AND batch.job_key = p_job_key;
$$;


--
-- Name: analysis_v2_profile_provider_canary_experiments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_profile_provider_canary_experiments (
    source_request_id uuid NOT NULL,
    canary_version text DEFAULT 'profile-fallback-replacement-canary-v1'::text NOT NULL,
    ordered_set_hmac character varying(64),
    source_run_count integer DEFAULT 8 NOT NULL,
    candidate_count integer DEFAULT 15 NOT NULL,
    unique_candidate_count integer DEFAULT 15 NOT NULL,
    public_candidate_count integer DEFAULT 15 NOT NULL,
    incomplete_candidate_count integer DEFAULT 15 NOT NULL,
    unavailable_candidate_count integer DEFAULT 0 NOT NULL,
    primary_success_candidate_count integer DEFAULT 0 NOT NULL,
    critical_candidate_count integer DEFAULT 3 NOT NULL,
    state text DEFAULT 'active'::text NOT NULL,
    terminal_reason text,
    rep2_approval_deadline_at timestamp with time zone,
    source_kvs_cleanup_state text DEFAULT 'pending'::text NOT NULL,
    source_dataset_cleanup_state text DEFAULT 'pending'::text NOT NULL,
    source_request_queue_cleanup_state text DEFAULT 'pending'::text NOT NULL,
    source_kvs_cleaned_at timestamp with time zone,
    source_dataset_cleaned_at timestamp with time zone,
    source_request_queue_cleaned_at timestamp with time zone,
    cleanup_claim_token uuid,
    cleanup_claimed_at timestamp with time zone,
    cleanup_lease_expires_at timestamp with time zone,
    hmac_cleared_at timestamp with time zone,
    experiment_terminal_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_v2_profile_provider_canary_experiment_cleanup_time_che CHECK ((((source_kvs_cleanup_state = 'pending'::text) = (source_kvs_cleaned_at IS NULL)) AND ((source_dataset_cleanup_state = 'pending'::text) = (source_dataset_cleaned_at IS NULL)) AND ((source_request_queue_cleanup_state = 'pending'::text) = (source_request_queue_cleaned_at IS NULL)))),
    CONSTRAINT analysis_v2_profile_provider_canary_experiment_cleanup_value_ch CHECK (((source_kvs_cleanup_state = ANY (ARRAY['pending'::text, 'verified_absent'::text])) AND (source_dataset_cleanup_state = ANY (ARRAY['pending'::text, 'verified_absent'::text])) AND (source_request_queue_cleanup_state = ANY (ARRAY['pending'::text, 'verified_absent'::text])))),
    CONSTRAINT analysis_v2_profile_provider_canary_experiment_counts_check CHECK (((source_run_count = 8) AND (candidate_count = 15) AND (unique_candidate_count = 15) AND (public_candidate_count = 15) AND (incomplete_candidate_count = 15) AND (unavailable_candidate_count = 0) AND (primary_success_candidate_count = 0) AND (critical_candidate_count = 3))),
    CONSTRAINT analysis_v2_profile_provider_canary_experiment_hmac_check CHECK (((ordered_set_hmac IS NULL) OR ((ordered_set_hmac)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT analysis_v2_profile_provider_canary_experiment_lifecycle_check CHECK ((((state = 'active'::text) AND (ordered_set_hmac IS NOT NULL) AND (terminal_reason IS NULL) AND (rep2_approval_deadline_at IS NULL) AND (cleanup_claim_token IS NULL) AND (cleanup_claimed_at IS NULL) AND (cleanup_lease_expires_at IS NULL) AND (hmac_cleared_at IS NULL) AND (experiment_terminal_at IS NULL)) OR ((state = 'awaiting_repetition_2'::text) AND (ordered_set_hmac IS NOT NULL) AND (terminal_reason IS NULL) AND (rep2_approval_deadline_at IS NOT NULL) AND (cleanup_claim_token IS NULL) AND (cleanup_claimed_at IS NULL) AND (cleanup_lease_expires_at IS NULL) AND (hmac_cleared_at IS NULL) AND (experiment_terminal_at IS NULL)) OR ((state = 'terminalizing'::text) AND (ordered_set_hmac IS NOT NULL) AND (terminal_reason IS NOT NULL) AND (cleanup_claim_token IS NOT NULL) AND (cleanup_claimed_at IS NOT NULL) AND (cleanup_lease_expires_at IS NOT NULL) AND (hmac_cleared_at IS NULL) AND (experiment_terminal_at IS NULL)) OR ((state = 'experiment_terminal'::text) AND (ordered_set_hmac IS NULL) AND (terminal_reason IS NOT NULL) AND (source_kvs_cleanup_state = 'verified_absent'::text) AND (source_dataset_cleanup_state = 'verified_absent'::text) AND (source_request_queue_cleanup_state = 'verified_absent'::text) AND (hmac_cleared_at IS NOT NULL) AND (experiment_terminal_at IS NOT NULL)))),
    CONSTRAINT analysis_v2_profile_provider_canary_experiment_reason_check CHECK (((terminal_reason IS NULL) OR (terminal_reason = ANY (ARRAY['strict_failure'::text, 'verified_no_run'::text, 'completed'::text, 'aborted_by_operator'::text, 'expired_waiting_for_repetition'::text])))),
    CONSTRAINT analysis_v2_profile_provider_canary_experiment_state_value_chec CHECK ((state = ANY (ARRAY['active'::text, 'awaiting_repetition_2'::text, 'terminalizing'::text, 'experiment_terminal'::text]))),
    CONSTRAINT analysis_v2_profile_provider_canary_experiment_time_check CHECK (((updated_at >= created_at) AND ((rep2_approval_deadline_at IS NULL) OR (rep2_approval_deadline_at >= created_at)) AND ((cleanup_claimed_at IS NULL) OR (cleanup_claimed_at >= created_at)) AND ((cleanup_lease_expires_at IS NULL) OR (cleanup_lease_expires_at >= cleanup_claimed_at)) AND ((hmac_cleared_at IS NULL) OR (hmac_cleared_at >= created_at)) AND ((experiment_terminal_at IS NULL) OR (experiment_terminal_at >= hmac_cleared_at)))),
    CONSTRAINT analysis_v2_profile_provider_canary_experiment_version_check CHECK ((canary_version = 'profile-fallback-replacement-canary-v1'::text))
);

ALTER TABLE ONLY public.analysis_v2_profile_provider_canary_experiments FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_profile_provider_canary_experiment_json(public.analysis_v2_profile_provider_canary_experiments); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_profile_provider_canary_experiment_json(p_experiment public.analysis_v2_profile_provider_canary_experiments) RETURNS jsonb
    LANGUAGE sql STABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'sourceRequestId', p_experiment.source_request_id,
        'canaryVersion', p_experiment.canary_version,
        'orderedSetHmac', p_experiment.ordered_set_hmac,
        'sourceRunCount', p_experiment.source_run_count,
        'candidateCount', p_experiment.candidate_count,
        'uniqueCandidateCount', p_experiment.unique_candidate_count,
        'publicCandidateCount', p_experiment.public_candidate_count,
        'incompleteCandidateCount', p_experiment.incomplete_candidate_count,
        'unavailableCandidateCount', p_experiment.unavailable_candidate_count,
        'primarySuccessCandidateCount', p_experiment.primary_success_candidate_count,
        'criticalCandidateCount', p_experiment.critical_candidate_count,
        'state', p_experiment.state,
        'terminalReason', p_experiment.terminal_reason,
        'rep2ApprovalDeadlineAt', p_experiment.rep2_approval_deadline_at,
        'sourceKvsCleanupState', p_experiment.source_kvs_cleanup_state,
        'sourceDatasetCleanupState', p_experiment.source_dataset_cleanup_state,
        'sourceRequestQueueCleanupState', p_experiment.source_request_queue_cleanup_state,
        'sourceKvsCleanedAt', p_experiment.source_kvs_cleaned_at,
        'sourceDatasetCleanedAt', p_experiment.source_dataset_cleaned_at,
        'sourceRequestQueueCleanedAt', p_experiment.source_request_queue_cleaned_at,
        'cleanupClaimToken', p_experiment.cleanup_claim_token,
        'cleanupClaimedAt', p_experiment.cleanup_claimed_at,
        'cleanupLeaseExpiresAt', p_experiment.cleanup_lease_expires_at,
        'hmacClearedAt', p_experiment.hmac_cleared_at,
        'experimentTerminalAt', p_experiment.experiment_terminal_at,
        'createdAt', p_experiment.created_at,
        'updatedAt', p_experiment.updated_at
    );
$$;


--
-- Name: analysis_v2_profile_provider_canary_reserve_unfenced(uuid, integer, integer, integer, integer, integer, integer, integer, integer, integer, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_profile_provider_canary_reserve_unfenced(p_source_request_id uuid, p_repetition integer, p_source_run_count integer, p_candidate_count integer, p_unique_candidate_count integer, p_public_candidate_count integer, p_incomplete_candidate_count integer, p_unavailable_candidate_count integer, p_primary_success_candidate_count integer, p_critical_candidate_count integer, p_ordered_set_hmac text, p_restricted_access_verified boolean, p_reservation_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_source_count INTEGER;
    v_source_job_count INTEGER;
    v_source_run_id_count INTEGER;
    v_experiment public.analysis_v2_profile_provider_canary_experiments%ROWTYPE;
    v_previous public.analysis_v2_profile_provider_canary_runs%ROWTYPE;
    v_run public.analysis_v2_profile_provider_canary_runs%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL OR p_repetition NOT IN (1, 2)
       OR p_source_run_count IS DISTINCT FROM 8
       OR p_candidate_count IS DISTINCT FROM 15
       OR p_unique_candidate_count IS DISTINCT FROM 15
       OR p_public_candidate_count IS DISTINCT FROM 15
       OR p_incomplete_candidate_count IS DISTINCT FROM 15
       OR p_unavailable_candidate_count IS DISTINCT FROM 0
       OR p_primary_success_candidate_count IS DISTINCT FROM 0
       OR p_critical_candidate_count IS DISTINCT FROM 3
       OR p_ordered_set_hmac IS NULL OR p_ordered_set_hmac !~ '^[0-9a-f]{64}$'
       OR p_restricted_access_verified IS DISTINCT FROM TRUE
       OR p_reservation_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_INVALID', ERRCODE = 'P0001';
    END IF;

    -- APP_BOUND_SOURCE_REPLAY_PROOF: source storage is not readable from SQL. The caller
    -- derives this bounded aggregate proof from the zero-start replay; SQL stores no raw rows.

    SELECT pg_catalog.count(*)::INTEGER,
        pg_catalog.count(DISTINCT provider_run.job_key)::INTEGER,
        pg_catalog.count(DISTINCT provider_run.run_id)::INTEGER
    INTO v_source_count, v_source_job_count, v_source_run_id_count
    FROM public.analysis_requests AS analysis_request
    JOIN public.analysis_v2_provider_execution_policies AS execution_policy
      ON execution_policy.request_id = analysis_request.id
    JOIN public.analysis_v2_test_entitlement_consumptions AS entitlement_consumption
      ON entitlement_consumption.request_id = analysis_request.id
    JOIN public.analysis_preflights AS preflight
      ON preflight.id = entitlement_consumption.preflight_id
    JOIN public.analysis_v2_provider_runs AS provider_run
      ON provider_run.request_id = analysis_request.id
    WHERE analysis_request.id = p_source_request_id
      AND analysis_request.pipeline_version = 'v2'
      AND analysis_request.status = 'failed'
      AND analysis_request.plan_access_mode_snapshot = 'test_entitlement'
      AND analysis_request.selected_plan_id_snapshot = entitlement_consumption.selected_plan_id
      AND analysis_request.preflight_id = preflight.id
      AND analysis_request.test_entitlement_jti_hash = execution_policy.entitlement_jti_hash
      AND analysis_request.test_entitlement_jti_hash = entitlement_consumption.entitlement_jti_hash
      AND analysis_request.target_instagram_id = 'retained.' || pg_catalog.substr(
            pg_catalog.replace(analysis_request.id::TEXT, '-', ''), 1, 20
      )
      AND execution_policy.mode = 'test_operation_split'
      AND execution_policy.policy_version = 'authorized-free-e2e-v1'
      AND execution_policy.target_instagram_id = '0_min._.00'
      AND entitlement_consumption.user_id = analysis_request.user_id
      AND entitlement_consumption.selected_plan_id = 'standard'
      AND preflight.user_id = analysis_request.user_id
      AND preflight.consumed_request_id = analysis_request.id
      AND preflight.status = 'consumed'
      AND preflight.access_mode = 'test_entitlement'
      AND preflight.pii_scrubbed_at IS NOT NULL
      AND preflight.target_instagram_id = 'retained.' || pg_catalog.substr(
            pg_catalog.replace(preflight.id::TEXT, '-', ''), 1, 20
      )
      AND provider_run.status = 'succeeded'
      AND provider_run.run_id ~ '^[A-Za-z0-9]{8,64}$'
      AND provider_run.actor_id = 'apify/instagram-profile-scraper'
      AND provider_run.job_key ~ '^track:profiles:batch:(?:0|[1-7])$'
      AND provider_run.operation_key ~ '^profile-fallback:[0-9a-f]{64}$'
      AND execution_policy.operation_slot_map->>'profile-fallback' = provider_run.credential_slot;
    IF v_source_count IS DISTINCT FROM 8
       OR v_source_job_count IS DISTINCT FROM 8
       OR v_source_run_id_count IS DISTINCT FROM 8 THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT experiment.* INTO v_experiment
    FROM public.analysis_v2_profile_provider_canary_experiments AS experiment
    WHERE experiment.source_request_id = p_source_request_id
      AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
    FOR UPDATE;

    IF NOT FOUND THEN
        IF p_repetition <> 1 THEN
            RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_STATE_CONFLICT', ERRCODE = 'P0001';
        END IF;
        INSERT INTO public.analysis_v2_profile_provider_canary_experiments (
            source_request_id, ordered_set_hmac, source_run_count, candidate_count,
            unique_candidate_count, public_candidate_count, incomplete_candidate_count,
            unavailable_candidate_count, primary_success_candidate_count,
            critical_candidate_count
        ) VALUES (
            p_source_request_id, p_ordered_set_hmac, p_source_run_count, p_candidate_count,
            p_unique_candidate_count, p_public_candidate_count, p_incomplete_candidate_count,
            p_unavailable_candidate_count, p_primary_success_candidate_count,
            p_critical_candidate_count
        )
        RETURNING * INTO v_experiment;
    ELSIF v_experiment.ordered_set_hmac IS DISTINCT FROM p_ordered_set_hmac THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_HMAC_CONFLICT', ERRCODE = 'P0001';
    ELSIF v_experiment.source_run_count IS DISTINCT FROM p_source_run_count
       OR v_experiment.candidate_count IS DISTINCT FROM p_candidate_count
       OR v_experiment.unique_candidate_count IS DISTINCT FROM p_unique_candidate_count
       OR v_experiment.public_candidate_count IS DISTINCT FROM p_public_candidate_count
       OR v_experiment.incomplete_candidate_count IS DISTINCT FROM p_incomplete_candidate_count
       OR v_experiment.unavailable_candidate_count IS DISTINCT FROM p_unavailable_candidate_count
       OR v_experiment.primary_success_candidate_count IS DISTINCT FROM p_primary_success_candidate_count
       OR v_experiment.critical_candidate_count IS DISTINCT FROM p_critical_candidate_count THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;

    SELECT canary_run.* INTO v_run
    FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.repetition = p_repetition
    FOR UPDATE;
    IF FOUND THEN
        IF v_run.actor_id IS DISTINCT FROM 'apify/instagram-scraper'
           OR v_run.actor_build IS DISTINCT FROM '0.0.692'
           OR v_run.credential_slot IS DISTINCT FROM 'primary'
           OR v_run.requested_count IS DISTINCT FROM 15
           OR v_run.max_charge_usd IS DISTINCT FROM 0.050000000000
           OR (v_run.state IN ('starting', 'ambiguous', 'running')
               AND v_run.restricted_access_verified IS DISTINCT FROM TRUE) THEN
            RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'created', FALSE,
            'experiment', public.analysis_v2_profile_provider_canary_experiment_json(v_experiment),
            'run', public.analysis_v2_profile_provider_canary_run_json(v_run)
        );
    END IF;

    IF p_repetition = 2 THEN
        SELECT canary_run.* INTO v_previous
        FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
        WHERE canary_run.source_request_id = p_source_request_id
          AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
          AND canary_run.repetition = 1
        FOR UPDATE;
        IF NOT FOUND
           OR v_experiment.state IS DISTINCT FROM 'awaiting_repetition_2'
           OR v_experiment.rep2_approval_deadline_at IS NULL
           OR v_experiment.rep2_approval_deadline_at <= v_now
           OR v_previous.state IS DISTINCT FROM 'succeeded'
           OR v_previous.gate_passed IS DISTINCT FROM TRUE
           OR v_previous.cost_status IS DISTINCT FROM 'actual'
           OR v_previous.cleanup_completed_at IS NULL THEN
            RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_STATE_CONFLICT', ERRCODE = 'P0001';
        END IF;
        UPDATE public.analysis_v2_profile_provider_canary_experiments AS experiment
        SET state = 'active', rep2_approval_deadline_at = NULL, updated_at = v_now
        WHERE experiment.source_request_id = p_source_request_id
          AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
        RETURNING * INTO v_experiment;
    ELSIF v_experiment.state IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.analysis_v2_profile_provider_canary_runs (
        source_request_id, repetition, reservation_token, restricted_access_verified
    ) VALUES (p_source_request_id, p_repetition, p_reservation_token, TRUE)
    RETURNING * INTO v_run;
    RETURN pg_catalog.jsonb_build_object(
        'created', TRUE,
        'experiment', public.analysis_v2_profile_provider_canary_experiment_json(v_experiment),
        'run', public.analysis_v2_profile_provider_canary_run_json(v_run)
    );
END;
$_$;


--
-- Name: analysis_v2_profile_provider_canary_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_profile_provider_canary_runs (
    source_request_id uuid NOT NULL,
    canary_version text DEFAULT 'profile-fallback-replacement-canary-v1'::text NOT NULL,
    repetition integer NOT NULL,
    actor_id text DEFAULT 'apify/instagram-scraper'::text NOT NULL,
    actor_build text DEFAULT '0.0.692'::text NOT NULL,
    input_contract_version integer DEFAULT 1 NOT NULL,
    output_contract_version integer DEFAULT 1 NOT NULL,
    credential_slot text DEFAULT 'primary'::text NOT NULL,
    requested_count integer DEFAULT 15 NOT NULL,
    max_charge_usd numeric(18,12) DEFAULT 0.050000000000 NOT NULL,
    reservation_token uuid NOT NULL,
    state text DEFAULT 'starting'::text NOT NULL,
    run_id character varying(64),
    terminal_count integer,
    success_count integer,
    unavailable_count integer,
    incomplete_count integer,
    other_failure_count integer,
    critical_success_count integer,
    latency_ms integer,
    build_verified boolean,
    restricted_access_verified boolean NOT NULL,
    gate_passed boolean,
    actual_usage_usd numeric(18,12),
    cost_status text DEFAULT 'conservative'::text NOT NULL,
    kvs_cleanup_state text DEFAULT 'pending'::text NOT NULL,
    dataset_cleanup_state text DEFAULT 'pending'::text NOT NULL,
    request_queue_cleanup_state text DEFAULT 'pending'::text NOT NULL,
    kvs_cleaned_at timestamp with time zone,
    dataset_cleaned_at timestamp with time zone,
    request_queue_cleaned_at timestamp with time zone,
    resolution_kind text DEFAULT 'none'::text NOT NULL,
    resolution_evidence_hash character varying(64),
    reserved_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    run_started_at timestamp with time zone,
    ambiguous_at timestamp with time zone,
    resolved_at timestamp with time zone,
    terminalized_at timestamp with time zone,
    usage_reconciled_at timestamp with time zone,
    cleanup_completed_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_v2_profile_provider_canary_run_cleanup_value_check CHECK (((kvs_cleanup_state = ANY (ARRAY['pending'::text, 'verified_absent'::text, 'not_applicable'::text])) AND (dataset_cleanup_state = ANY (ARRAY['pending'::text, 'verified_absent'::text, 'not_applicable'::text])) AND (request_queue_cleanup_state = ANY (ARRAY['pending'::text, 'verified_absent'::text, 'not_applicable'::text])) AND ((kvs_cleanup_state = 'pending'::text) = (kvs_cleaned_at IS NULL)) AND ((dataset_cleanup_state = 'pending'::text) = (dataset_cleaned_at IS NULL)) AND ((request_queue_cleanup_state = 'pending'::text) = (request_queue_cleaned_at IS NULL)))),
    CONSTRAINT analysis_v2_profile_provider_canary_run_cost_check CHECK (((cost_status = ANY (ARRAY['actual'::text, 'conservative'::text, 'unknown'::text])) AND ((actual_usage_usd IS NULL) OR ((actual_usage_usd >= (0)::numeric) AND (actual_usage_usd <= 1.000000000000))))),
    CONSTRAINT analysis_v2_profile_provider_canary_run_counts_check CHECK ((((terminal_count IS NULL) OR (terminal_count = 15)) AND ((success_count IS NULL) OR ((success_count >= 0) AND (success_count <= 15))) AND ((unavailable_count IS NULL) OR ((unavailable_count >= 0) AND (unavailable_count <= 15))) AND ((incomplete_count IS NULL) OR ((incomplete_count >= 0) AND (incomplete_count <= 15))) AND ((other_failure_count IS NULL) OR ((other_failure_count >= 0) AND (other_failure_count <= 15))) AND ((critical_success_count IS NULL) OR ((critical_success_count >= 0) AND (critical_success_count <= 3))) AND ((latency_ms IS NULL) OR ((latency_ms >= 0) AND (latency_ms <= 300000))))),
    CONSTRAINT analysis_v2_profile_provider_canary_run_id_check CHECK (((run_id IS NULL) OR ((run_id)::text ~ '^[A-Za-z0-9]{8,64}$'::text))),
    CONSTRAINT analysis_v2_profile_provider_canary_run_identity_check CHECK (((canary_version = 'profile-fallback-replacement-canary-v1'::text) AND (repetition = ANY (ARRAY[1, 2])) AND (actor_id = 'apify/instagram-scraper'::text) AND (actor_build = '0.0.692'::text) AND (input_contract_version = 1) AND (output_contract_version = 1) AND (credential_slot = 'primary'::text) AND (requested_count = 15) AND (max_charge_usd = 0.050000000000))),
    CONSTRAINT analysis_v2_profile_provider_canary_run_lifecycle_check CHECK ((((state = 'starting'::text) AND (run_id IS NULL) AND (run_started_at IS NULL) AND (ambiguous_at IS NULL) AND (terminalized_at IS NULL) AND (terminal_count IS NULL) AND (actual_usage_usd IS NULL) AND (cost_status = 'conservative'::text) AND (gate_passed IS NULL)) OR ((state = 'ambiguous'::text) AND (run_id IS NULL) AND (run_started_at IS NULL) AND (ambiguous_at IS NOT NULL) AND (terminalized_at IS NULL) AND (terminal_count IS NULL) AND (actual_usage_usd IS NULL) AND (cost_status = 'unknown'::text) AND (gate_passed IS NULL)) OR ((state = 'running'::text) AND (run_id IS NOT NULL) AND (run_started_at IS NOT NULL) AND (terminalized_at IS NULL) AND (terminal_count IS NULL) AND (actual_usage_usd IS NULL) AND (cost_status = 'conservative'::text) AND (gate_passed IS NULL)) OR ((state = ANY (ARRAY['succeeded'::text, 'failed'::text])) AND (run_id IS NOT NULL) AND (run_started_at IS NOT NULL) AND (terminalized_at IS NOT NULL) AND (terminal_count = 15) AND (success_count IS NOT NULL) AND (unavailable_count IS NOT NULL) AND (incomplete_count IS NOT NULL) AND (other_failure_count IS NOT NULL) AND (critical_success_count IS NOT NULL) AND ((((success_count + unavailable_count) + incomplete_count) + other_failure_count) = 15) AND (latency_ms IS NOT NULL) AND (build_verified IS NOT NULL) AND (((actual_usage_usd IS NULL) AND (usage_reconciled_at IS NULL) AND (cost_status = 'conservative'::text) AND (cleanup_completed_at IS NULL)) OR ((actual_usage_usd IS NOT NULL) AND (usage_reconciled_at IS NOT NULL) AND (cost_status = 'actual'::text)))) OR ((state = 'verified_no_run'::text) AND (run_id IS NULL) AND (run_started_at IS NULL) AND (ambiguous_at IS NOT NULL) AND (terminalized_at IS NOT NULL) AND (terminal_count IS NULL) AND (success_count IS NULL) AND (actual_usage_usd = (0)::numeric) AND (usage_reconciled_at IS NOT NULL) AND (cost_status = 'actual'::text) AND (gate_passed = false) AND (kvs_cleanup_state = 'not_applicable'::text) AND (dataset_cleanup_state = 'not_applicable'::text) AND (request_queue_cleanup_state = 'not_applicable'::text) AND (cleanup_completed_at IS NOT NULL) AND (resolution_kind = 'verified_no_run'::text)))),
    CONSTRAINT analysis_v2_profile_provider_canary_run_resolution_check CHECK (((resolution_kind = ANY (ARRAY['none'::text, 'adopted_run'::text, 'verified_no_run'::text])) AND ((resolution_evidence_hash IS NULL) OR ((resolution_evidence_hash)::text ~ '^[0-9a-f]{64}$'::text)) AND (((resolution_kind = 'none'::text) AND (resolution_evidence_hash IS NULL) AND (resolved_at IS NULL)) OR ((resolution_kind <> 'none'::text) AND (resolution_evidence_hash IS NOT NULL) AND (resolved_at IS NOT NULL))))),
    CONSTRAINT analysis_v2_profile_provider_canary_run_state_value_check CHECK ((state = ANY (ARRAY['starting'::text, 'ambiguous'::text, 'running'::text, 'succeeded'::text, 'failed'::text, 'verified_no_run'::text]))),
    CONSTRAINT analysis_v2_profile_provider_canary_run_time_check CHECK (((updated_at >= reserved_at) AND ((run_started_at IS NULL) OR (run_started_at >= (reserved_at - '00:01:00'::interval))) AND ((ambiguous_at IS NULL) OR (ambiguous_at >= reserved_at)) AND ((resolved_at IS NULL) OR (resolved_at >= reserved_at)) AND ((terminalized_at IS NULL) OR (terminalized_at >= reserved_at)) AND ((usage_reconciled_at IS NULL) OR (usage_reconciled_at >= terminalized_at)) AND ((cleanup_completed_at IS NULL) OR (cleanup_completed_at >= usage_reconciled_at))))
);

ALTER TABLE ONLY public.analysis_v2_profile_provider_canary_runs FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_profile_provider_canary_run_json(public.analysis_v2_profile_provider_canary_runs); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_profile_provider_canary_run_json(p_run public.analysis_v2_profile_provider_canary_runs) RETURNS jsonb
    LANGUAGE sql STABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'sourceRequestId', p_run.source_request_id,
        'canaryVersion', p_run.canary_version,
        'repetition', p_run.repetition,
        'actorId', p_run.actor_id,
        'actorBuild', p_run.actor_build,
        'inputContractVersion', p_run.input_contract_version,
        'outputContractVersion', p_run.output_contract_version,
        'credentialSlot', p_run.credential_slot,
        'requestedCount', p_run.requested_count,
        'maxChargeUsd', p_run.max_charge_usd,
        'reservationToken', p_run.reservation_token,
        'state', p_run.state,
        'runId', p_run.run_id,
        'terminalCount', p_run.terminal_count,
        'successCount', p_run.success_count,
        'unavailableCount', p_run.unavailable_count,
        'incompleteCount', p_run.incomplete_count,
        'otherFailureCount', p_run.other_failure_count,
        'criticalSuccessCount', p_run.critical_success_count,
        'latencyMs', p_run.latency_ms,
        'buildVerified', p_run.build_verified,
        'restrictedAccessVerified', p_run.restricted_access_verified,
        'gatePassed', p_run.gate_passed,
        'actualUsageUsd', p_run.actual_usage_usd,
        'costStatus', p_run.cost_status,
        'kvsCleanupState', p_run.kvs_cleanup_state,
        'datasetCleanupState', p_run.dataset_cleanup_state,
        'requestQueueCleanupState', p_run.request_queue_cleanup_state,
        'kvsCleanedAt', p_run.kvs_cleaned_at,
        'datasetCleanedAt', p_run.dataset_cleaned_at,
        'requestQueueCleanedAt', p_run.request_queue_cleaned_at,
        'resolutionKind', p_run.resolution_kind,
        'resolutionEvidenceHash', p_run.resolution_evidence_hash,
        'reservedAt', p_run.reserved_at,
        'runStartedAt', p_run.run_started_at,
        'ambiguousAt', p_run.ambiguous_at,
        'resolvedAt', p_run.resolved_at,
        'terminalizedAt', p_run.terminalized_at,
        'usageReconciledAt', p_run.usage_reconciled_at,
        'cleanupCompletedAt', p_run.cleanup_completed_at,
        'updatedAt', p_run.updated_at
    );
$$;


--
-- Name: analysis_v2_profile_repair_canary_reserve_unfenced(uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_profile_repair_canary_reserve_unfenced(p_source_request_id uuid, p_repetition integer, p_credential_slot text, p_reservation_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_source public.analysis_requests%ROWTYPE;
    v_previous public.analysis_v2_profile_repair_canary_runs%ROWTYPE;
    v_run public.analysis_v2_profile_repair_canary_runs%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL
       OR p_repetition NOT IN (1, 2)
       OR p_credential_slot NOT IN (
            'primary', 'secondary', 'tertiary', 'quaternary', 'quinary'
       )
       OR p_reservation_token IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_source
    FROM public.analysis_requests AS analysis_request
    JOIN public.analysis_v2_provider_execution_policies AS execution_policy
      ON execution_policy.request_id = analysis_request.id
    JOIN public.analysis_v2_test_entitlement_consumptions AS entitlement_consumption
      ON entitlement_consumption.request_id = analysis_request.id
    JOIN public.analysis_preflights AS preflight
      ON preflight.id = entitlement_consumption.preflight_id
    WHERE analysis_request.id = p_source_request_id
      AND analysis_request.pipeline_version = 'v2'
      AND analysis_request.status = 'failed'
      AND analysis_request.plan_access_mode_snapshot = 'test_entitlement'
      AND analysis_request.selected_plan_id_snapshot =
            entitlement_consumption.selected_plan_id
      AND analysis_request.preflight_id = preflight.id
      AND analysis_request.test_entitlement_jti_hash =
            execution_policy.entitlement_jti_hash
      AND analysis_request.test_entitlement_jti_hash =
            entitlement_consumption.entitlement_jti_hash
      AND analysis_request.target_instagram_id =
            'retained.' || pg_catalog.substr(
                pg_catalog.replace(analysis_request.id::TEXT, '-', ''), 1, 20
            )
      AND execution_policy.mode = 'test_operation_split'
      AND execution_policy.policy_version = 'authorized-free-e2e-v1'
      AND execution_policy.target_instagram_id = '0_min._.00'
      AND execution_policy.operation_slot_map->>'profile-fallback' = p_credential_slot
      AND entitlement_consumption.user_id = analysis_request.user_id
      AND entitlement_consumption.selected_plan_id = 'standard'
      AND preflight.user_id = analysis_request.user_id
      AND preflight.consumed_request_id = analysis_request.id
      AND preflight.status = 'consumed'
      AND preflight.access_mode = 'test_entitlement'
      AND preflight.pii_scrubbed_at IS NOT NULL
      AND preflight.target_instagram_id =
            'retained.' || pg_catalog.substr(
                pg_catalog.replace(preflight.id::TEXT, '-', ''), 1, 20
            )
      AND NOT EXISTS (
            SELECT 1
            FROM public.analysis_v2_provider_runs AS provider_run
            WHERE provider_run.request_id = analysis_request.id
              AND provider_run.job_key ~ '^track:profiles:batch:(?:0|[1-9][0-9]{0,2})$'
              AND provider_run.operation_key ~ '^profile-fallback:[0-9a-f]{64}$'
              AND provider_run.credential_slot IS DISTINCT FROM p_credential_slot
      )
    FOR UPDATE OF analysis_request;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    IF p_repetition = 2 THEN
        SELECT canary_run.*
        INTO v_previous
        FROM public.analysis_v2_profile_repair_canary_runs AS canary_run
        WHERE canary_run.source_request_id = p_source_request_id
          AND canary_run.canary_version = 'profile-repair-canary-v1'
          AND canary_run.repetition = 1
        FOR UPDATE;
        IF NOT FOUND
           OR v_previous.state IS DISTINCT FROM 'succeeded'
           OR v_previous.gate_passed IS DISTINCT FROM TRUE
           OR v_previous.cost_status IS DISTINCT FROM 'actual'
           OR v_previous.actual_usage_usd IS NULL
           OR v_previous.actual_usage_usd > 0.050000000000 THEN
            RAISE EXCEPTION USING
                MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_STATE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
    END IF;

    SELECT canary_run.*
    INTO v_run
    FROM public.analysis_v2_profile_repair_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-repair-canary-v1'
      AND canary_run.repetition = p_repetition
    FOR UPDATE;
    IF FOUND THEN
        IF v_run.actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper'
           OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
           OR v_run.requested_count IS DISTINCT FROM 15
           OR v_run.max_charge_usd IS DISTINCT FROM 0.050000000000 THEN
            RAISE EXCEPTION USING
                MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_IDENTITY_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'created', FALSE,
            'run', public.analysis_v2_profile_repair_canary_run_json(v_run)
        );
    END IF;

    INSERT INTO public.analysis_v2_profile_repair_canary_runs (
        source_request_id,
        repetition,
        credential_slot,
        reservation_token
    ) VALUES (
        p_source_request_id,
        p_repetition,
        p_credential_slot,
        p_reservation_token
    )
    RETURNING * INTO v_run;

    RETURN pg_catalog.jsonb_build_object(
        'created', TRUE,
        'run', public.analysis_v2_profile_repair_canary_run_json(v_run)
    );
END;
$_$;


--
-- Name: analysis_v2_profile_repair_canary_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_profile_repair_canary_runs (
    source_request_id uuid NOT NULL,
    canary_version text DEFAULT 'profile-repair-canary-v1'::text NOT NULL,
    repetition integer NOT NULL,
    actor_id text DEFAULT 'apify/instagram-profile-scraper'::text NOT NULL,
    credential_slot text NOT NULL,
    requested_count integer DEFAULT 15 NOT NULL,
    max_charge_usd numeric(18,12) DEFAULT 0.050000000000 NOT NULL,
    reservation_token uuid NOT NULL,
    state text DEFAULT 'starting'::text NOT NULL,
    run_id character varying(64),
    terminal_count integer,
    success_count integer,
    unavailable_count integer,
    incomplete_count integer,
    other_failure_count integer,
    critical_recovered_count integer,
    latency_ms integer,
    gate_passed boolean,
    actual_usage_usd numeric(18,12),
    cost_status text DEFAULT 'conservative'::text NOT NULL,
    reserved_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    run_started_at timestamp with time zone,
    ambiguous_at timestamp with time zone,
    terminalized_at timestamp with time zone,
    usage_reconciled_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_v2_profile_repair_canary_actor_check CHECK ((actor_id = 'apify/instagram-profile-scraper'::text)),
    CONSTRAINT analysis_v2_profile_repair_canary_charge_check CHECK (((max_charge_usd = 0.050000000000) AND ((actual_usage_usd IS NULL) OR ((actual_usage_usd >= (0)::numeric) AND (actual_usage_usd <= 0.050000000000))))),
    CONSTRAINT analysis_v2_profile_repair_canary_cost_status_check CHECK ((cost_status = ANY (ARRAY['actual'::text, 'conservative'::text, 'unknown'::text]))),
    CONSTRAINT analysis_v2_profile_repair_canary_counts_check CHECK ((((terminal_count IS NULL) OR (terminal_count = 15)) AND ((success_count IS NULL) OR ((success_count >= 0) AND (success_count <= 15))) AND ((unavailable_count IS NULL) OR ((unavailable_count >= 0) AND (unavailable_count <= 15))) AND ((incomplete_count IS NULL) OR ((incomplete_count >= 0) AND (incomplete_count <= 15))) AND ((other_failure_count IS NULL) OR ((other_failure_count >= 0) AND (other_failure_count <= 15))) AND ((critical_recovered_count IS NULL) OR ((critical_recovered_count >= 0) AND (critical_recovered_count <= 15))) AND ((latency_ms IS NULL) OR ((latency_ms >= 0) AND (latency_ms <= 300000))))),
    CONSTRAINT analysis_v2_profile_repair_canary_credential_check CHECK ((credential_slot = ANY (ARRAY['primary'::text, 'secondary'::text, 'tertiary'::text, 'quaternary'::text, 'quinary'::text]))),
    CONSTRAINT analysis_v2_profile_repair_canary_repetition_check CHECK ((repetition = ANY (ARRAY[1, 2]))),
    CONSTRAINT analysis_v2_profile_repair_canary_requested_check CHECK ((requested_count = 15)),
    CONSTRAINT analysis_v2_profile_repair_canary_run_id_check CHECK (((run_id IS NULL) OR ((run_id)::text ~ '^[A-Za-z0-9]{8,64}$'::text))),
    CONSTRAINT analysis_v2_profile_repair_canary_state_check CHECK ((((state = 'starting'::text) AND (run_id IS NULL) AND (run_started_at IS NULL) AND (ambiguous_at IS NULL) AND (terminalized_at IS NULL) AND (terminal_count IS NULL) AND (success_count IS NULL) AND (unavailable_count IS NULL) AND (incomplete_count IS NULL) AND (other_failure_count IS NULL) AND (critical_recovered_count IS NULL) AND (latency_ms IS NULL) AND (gate_passed IS NULL) AND (actual_usage_usd IS NULL) AND (usage_reconciled_at IS NULL) AND (cost_status = 'conservative'::text)) OR ((state = 'running'::text) AND (run_id IS NOT NULL) AND (run_started_at IS NOT NULL) AND (ambiguous_at IS NULL) AND (terminalized_at IS NULL) AND (terminal_count IS NULL) AND (success_count IS NULL) AND (unavailable_count IS NULL) AND (incomplete_count IS NULL) AND (other_failure_count IS NULL) AND (critical_recovered_count IS NULL) AND (latency_ms IS NULL) AND (gate_passed IS NULL) AND (actual_usage_usd IS NULL) AND (usage_reconciled_at IS NULL) AND (cost_status = 'conservative'::text)) OR ((state = 'ambiguous'::text) AND (run_id IS NULL) AND (run_started_at IS NULL) AND (ambiguous_at IS NOT NULL) AND (terminalized_at IS NOT NULL) AND (terminal_count IS NULL) AND (success_count IS NULL) AND (unavailable_count IS NULL) AND (incomplete_count IS NULL) AND (other_failure_count IS NULL) AND (critical_recovered_count IS NULL) AND (latency_ms IS NULL) AND (gate_passed IS NULL) AND (actual_usage_usd IS NULL) AND (usage_reconciled_at IS NULL) AND (cost_status = 'unknown'::text)) OR ((state = ANY (ARRAY['succeeded'::text, 'failed'::text])) AND (run_id IS NOT NULL) AND (run_started_at IS NOT NULL) AND (ambiguous_at IS NULL) AND (terminalized_at IS NOT NULL) AND (terminal_count = 15) AND (success_count IS NOT NULL) AND (unavailable_count IS NOT NULL) AND (incomplete_count IS NOT NULL) AND (other_failure_count IS NOT NULL) AND ((((success_count + unavailable_count) + incomplete_count) + other_failure_count) = terminal_count) AND (critical_recovered_count IS NOT NULL) AND ((critical_recovered_count >= 0) AND (critical_recovered_count <= success_count)) AND (latency_ms IS NOT NULL) AND (gate_passed IS NOT NULL) AND (gate_passed = ((success_count >= 14) AND (unavailable_count <= 1) AND (other_failure_count = 0) AND (critical_recovered_count >= 1))) AND (gate_passed = (state = 'succeeded'::text)) AND (((actual_usage_usd IS NULL) AND (usage_reconciled_at IS NULL) AND (cost_status = 'conservative'::text)) OR ((actual_usage_usd IS NOT NULL) AND (usage_reconciled_at IS NOT NULL) AND (cost_status = 'actual'::text)))))),
    CONSTRAINT analysis_v2_profile_repair_canary_state_value_check CHECK ((state = ANY (ARRAY['starting'::text, 'running'::text, 'succeeded'::text, 'failed'::text, 'ambiguous'::text]))),
    CONSTRAINT analysis_v2_profile_repair_canary_time_check CHECK (((updated_at >= reserved_at) AND ((run_started_at IS NULL) OR (run_started_at >= reserved_at)) AND ((ambiguous_at IS NULL) OR (ambiguous_at >= reserved_at)) AND ((terminalized_at IS NULL) OR (terminalized_at >= reserved_at)) AND ((usage_reconciled_at IS NULL) OR (usage_reconciled_at >= terminalized_at)))),
    CONSTRAINT analysis_v2_profile_repair_canary_version_check CHECK ((canary_version = 'profile-repair-canary-v1'::text))
);

ALTER TABLE ONLY public.analysis_v2_profile_repair_canary_runs FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_profile_repair_canary_run_json(public.analysis_v2_profile_repair_canary_runs); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_profile_repair_canary_run_json(p_run public.analysis_v2_profile_repair_canary_runs) RETURNS jsonb
    LANGUAGE sql STABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'sourceRequestId', p_run.source_request_id,
        'canaryVersion', p_run.canary_version,
        'repetition', p_run.repetition,
        'actorId', p_run.actor_id,
        'credentialSlot', p_run.credential_slot,
        'requestedCount', p_run.requested_count,
        'maxChargeUsd', p_run.max_charge_usd,
        'reservationToken', p_run.reservation_token,
        'state', p_run.state,
        'runId', p_run.run_id,
        'terminalCount', p_run.terminal_count,
        'successCount', p_run.success_count,
        'unavailableCount', p_run.unavailable_count,
        'incompleteCount', p_run.incomplete_count,
        'otherFailureCount', p_run.other_failure_count,
        'criticalRecoveredCount', p_run.critical_recovered_count,
        'latencyMs', p_run.latency_ms,
        'gatePassed', p_run.gate_passed,
        'actualUsageUsd', p_run.actual_usage_usd,
        'costStatus', p_run.cost_status,
        'reservedAt', p_run.reserved_at,
        'runStartedAt', p_run.run_started_at,
        'ambiguousAt', p_run.ambiguous_at,
        'terminalizedAt', p_run.terminalized_at,
        'usageReconciledAt', p_run.usage_reconciled_at,
        'updatedAt', p_run.updated_at
    );
$$;


--
-- Name: analysis_v2_profile_repair_username_set(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_profile_repair_username_set(p_request_id uuid, p_job_key text) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT COALESCE(pg_catalog.array_agg(merged.username ORDER BY merged.ordinal), '{}')
    FROM (
        SELECT primary_outcome.ordinal,
               primary_outcome.username,
               COALESCE(fallback_outcome.status, primary_outcome.status) AS status
        FROM public.analysis_v2_profile_fetch_outcomes AS primary_outcome
        LEFT JOIN public.analysis_v2_profile_fetch_outcomes AS fallback_outcome
          ON fallback_outcome.request_id = primary_outcome.request_id
         AND fallback_outcome.job_key    = primary_outcome.job_key
         AND fallback_outcome.attempt    = 'fallback'
         AND fallback_outcome.username   = primary_outcome.username
        WHERE primary_outcome.request_id = p_request_id
          AND primary_outcome.job_key    = p_job_key
          AND primary_outcome.attempt    = 'primary'
          AND primary_outcome.status <> 'success'
    ) AS merged
    WHERE merged.status = 'failed';   -- 'unavailable' is deliberately never repaired
$$;


--
-- Name: analysis_v2_profile_terminal_attempt(uuid, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_profile_terminal_attempt(p_request_id uuid, p_job_key text, p_username text, p_frozen text[]) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT CASE
        WHEN EXISTS (
            SELECT 1
            FROM public.analysis_v2_profile_fetch_outcomes AS outcome
            WHERE outcome.request_id = p_request_id
              AND outcome.job_key = p_job_key
              AND outcome.username = p_username
              AND outcome.attempt = 'repair'
        ) THEN 'repair'
        WHEN EXISTS (
            SELECT 1
            FROM public.analysis_v2_profile_fetch_outcomes AS outcome
            WHERE outcome.request_id = p_request_id
              AND outcome.job_key = p_job_key
              AND outcome.username = p_username
              AND outcome.attempt = 'fresh_apify'
        ) THEN 'fresh_apify'
        WHEN p_username = ANY(p_frozen) THEN 'fallback'
        ELSE 'primary'
    END;
$$;


--
-- Name: analysis_v2_progress_canonical_tracks(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_progress_canonical_tracks(p_previous jsonb, p_next jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'relationshipAi', public.analysis_v2_progress_merge_track_stage(
            'relationshipAi', p_previous->'relationshipAi', p_next->'relationshipAi'
        ),
        'interactions', public.analysis_v2_progress_merge_track_stage(
            'interactions', p_previous->'interactions', p_next->'interactions'
        ),
        'finalization', public.analysis_v2_progress_merge_track_stage(
            'finalization', p_previous->'finalization', p_next->'finalization'
        )
    );
$$;


--
-- Name: analysis_progress_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_progress_events (
    request_id uuid NOT NULL,
    seq bigint NOT NULL,
    event_key character varying(64) NOT NULL,
    revision bigint NOT NULL,
    snapshot_fingerprint character varying(64) NOT NULL,
    occurred_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    event_state text NOT NULL,
    event_code text NOT NULL,
    copy_code text NOT NULL,
    aggregate_count integer,
    CONSTRAINT analysis_progress_events_aggregate_check CHECK (((aggregate_count IS NULL) OR ((aggregate_count >= 0) AND (aggregate_count <= 10000)))),
    CONSTRAINT analysis_progress_events_code_check CHECK ((event_code = ANY (ARRAY['TARGET_PROFILE_READY'::text, 'RELATIONSHIP_PROGRESS'::text, 'PROFILE_SCREENED'::text, 'SHORTLIST_READY'::text, 'POTENTIAL_HIGH_RISK_FOUND'::text, 'FINDING_CORRECTED'::text, 'FINDING_CONFIRMED'::text, 'ANALYSIS_COMPLETED'::text]))),
    CONSTRAINT analysis_progress_events_copy_check CHECK ((copy_code ~ '^[A-Z][A-Z0-9_]{0,63}$'::text)),
    CONSTRAINT analysis_progress_events_fingerprint_check CHECK (((snapshot_fingerprint)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT analysis_progress_events_key_check CHECK (((event_key)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT analysis_progress_events_revision_check CHECK (((revision >= 1) AND (revision <= '9007199254740991'::bigint))),
    CONSTRAINT analysis_progress_events_seq_check CHECK (((seq >= 1) AND (seq <= '9007199254740991'::bigint))),
    CONSTRAINT analysis_progress_events_state_check CHECK ((event_state = ANY (ARRAY['provisional'::text, 'confirmed'::text, 'corrected'::text])))
);

ALTER TABLE ONLY public.analysis_progress_events FORCE ROW LEVEL SECURITY;


