--
-- Name: analysis_v2_progress_merge_track_stage(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_progress_merge_track_stage(p_track_id text, p_previous jsonb, p_next jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT CASE
        -- Unknown stage codes are deliberately fail-closed. Returning the
        -- previous complete track preserves attribution and avoids allowing
        -- an unrecognized caller payload to erase durable progress.
        WHEN public.analysis_v2_progress_stage_rank(
                p_track_id, p_previous->>'stageCode'
             ) < 0
          OR public.analysis_v2_progress_stage_rank(
                p_track_id, p_next->>'stageCode'
             ) < 0
        THEN p_previous
        -- Once a track is terminal, the old transition contract permits only
        -- an exact replay. Do not synthesize a second terminal outcome.
        WHEN p_previous->>'state' IN ('completed', 'failed')
             AND p_next IS DISTINCT FROM p_previous
        THEN p_previous
        ELSE pg_catalog.jsonb_build_object(
            'state', CASE
                WHEN CASE p_next->>'state'
                    WHEN 'pending' THEN 0
                    WHEN 'running' THEN 1
                    WHEN 'completed' THEN 2
                    WHEN 'failed' THEN 2
                    ELSE -1
                END < CASE p_previous->>'state'
                    WHEN 'pending' THEN 0
                    WHEN 'running' THEN 1
                    WHEN 'completed' THEN 2
                    WHEN 'failed' THEN 2
                    ELSE -1
                END THEN p_previous->>'state'
                ELSE p_next->>'state'
            END,
            'stageCode', CASE
                WHEN public.analysis_v2_progress_stage_rank(
                        p_track_id, p_next->>'stageCode'
                     ) < public.analysis_v2_progress_stage_rank(
                        p_track_id, p_previous->>'stageCode'
                     ) THEN p_previous->>'stageCode'
                ELSE p_next->>'stageCode'
            END,
            'done', GREATEST(
                (p_previous->>'done')::INTEGER,
                (p_next->>'done')::INTEGER
            ),
            'total', GREATEST(
                (p_previous->>'total')::INTEGER,
                (p_next->>'total')::INTEGER
            ),
            'progressBp', GREATEST(
                (p_previous->>'progressBp')::INTEGER,
                (p_next->>'progressBp')::INTEGER
            )
        )
    END;
$$;


--
-- Name: analysis_v2_progress_snapshot_fingerprint(text, boolean, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_progress_snapshot_fingerprint(p_status text, p_background_processing boolean, p_tracks jsonb, p_active_profile jsonb, p_eta_range jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
    v_payload BYTEA := pg_catalog.convert_to(
        pg_catalog.jsonb_build_object(
            'domain', 'analysis-v2-progress-canonical-fingerprint-v1',
            'status', p_status,
            'backgroundProcessing', p_background_processing,
            'tracks', p_tracks,
            'activeProfile', p_active_profile,
            'etaRange', p_eta_range
        )::TEXT,
        'UTF8'
    );
    v_fingerprint TEXT;
BEGIN
    BEGIN
        EXECUTE 'SELECT pg_catalog.encode(pg_catalog.sha256($1::BYTEA), ''hex'')'
            INTO v_fingerprint
            USING v_payload;
    EXCEPTION
        WHEN undefined_function THEN
            EXECUTE 'SELECT pg_catalog.encode(extensions.digest($1::BYTEA, ''sha256''), ''hex'')'
                INTO v_fingerprint
                USING v_payload;
    END;
    RETURN v_fingerprint;
END;
$_$;


--
-- Name: analysis_v2_valid_progress_active_profile(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_progress_active_profile(p_profile jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT p_profile IS NULL OR (
        pg_catalog.jsonb_typeof(p_profile) = 'object'
        AND p_profile ?& ARRAY['maskedUsername', 'imageUrl']
        AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_object_keys(p_profile) AS profile_key(value)
            WHERE profile_key.value <> ALL (ARRAY['maskedUsername', 'imageUrl'])
        )
        AND pg_catalog.jsonb_typeof(p_profile->'maskedUsername') = 'string'
        AND p_profile->>'maskedUsername' ~ '^[A-Za-z0-9._]*\*[A-Za-z0-9._*]*$'
        AND pg_catalog.char_length(p_profile->>'maskedUsername') BETWEEN 1 AND 30
        AND (
            pg_catalog.jsonb_typeof(p_profile->'imageUrl') = 'null'
            OR (
                pg_catalog.jsonb_typeof(p_profile->'imageUrl') = 'string'
                AND pg_catalog.char_length(p_profile->>'imageUrl') BETWEEN 1 AND 2048
                AND p_profile->>'imageUrl' LIKE '/api/image-proxy?%'
            )
        )
    );
$_$;


--
-- Name: analysis_v2_valid_progress_eta(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_progress_eta(p_eta jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT p_eta IS NULL OR (
        pg_catalog.jsonb_typeof(p_eta) = 'object'
        AND p_eta ?& ARRAY['lowSeconds', 'highSeconds']
        AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_object_keys(p_eta) AS eta_key(value)
            WHERE eta_key.value <> ALL (ARRAY['lowSeconds', 'highSeconds'])
        )
        AND pg_catalog.jsonb_typeof(p_eta->'lowSeconds') = 'number'
        AND p_eta->>'lowSeconds' ~ '^(0|[1-9][0-9]{0,3})$'
        AND (p_eta->>'lowSeconds')::INTEGER BETWEEN 0 AND 3600
        AND pg_catalog.jsonb_typeof(p_eta->'highSeconds') = 'number'
        AND p_eta->>'highSeconds' ~ '^(0|[1-9][0-9]{0,3})$'
        AND (p_eta->>'highSeconds')::INTEGER BETWEEN 0 AND 3600
        AND (p_eta->>'lowSeconds')::INTEGER <= (p_eta->>'highSeconds')::INTEGER
    );
$_$;


--
-- Name: analysis_v2_valid_progress_tracks(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_progress_tracks(p_tracks jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT p_tracks IS NOT NULL
       AND pg_catalog.jsonb_typeof(p_tracks) = 'object'
       AND p_tracks ?& ARRAY['relationshipAi', 'interactions', 'finalization']
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_object_keys(p_tracks) AS track_key(value)
            WHERE track_key.value <> ALL (
                ARRAY['relationshipAi', 'interactions', 'finalization']
            )
       )
       AND public.analysis_v2_valid_progress_track(p_tracks->'relationshipAi')
       AND public.analysis_v2_valid_progress_track(p_tracks->'interactions')
       AND public.analysis_v2_valid_progress_track(p_tracks->'finalization');
$$;


--
-- Name: analysis_progress_state; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_progress_state (
    request_id uuid NOT NULL,
    revision bigint NOT NULL,
    status text NOT NULL,
    progress_bp integer NOT NULL,
    background_processing boolean NOT NULL,
    tracks jsonb NOT NULL,
    active_profile jsonb,
    eta_range jsonb,
    last_event_seq bigint NOT NULL,
    snapshot_fingerprint character varying(64) NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_progress_state_active_profile_check CHECK (public.analysis_v2_valid_progress_active_profile(active_profile)),
    CONSTRAINT analysis_progress_state_background_check CHECK ((((status = ANY (ARRAY['queued'::text, 'processing'::text])) AND background_processing) OR ((status = ANY (ARRAY['completed'::text, 'failed'::text, 'upgrade_required'::text])) AND (NOT background_processing)))),
    CONSTRAINT analysis_progress_state_bp_check CHECK (((progress_bp >= public.analysis_v2_calculate_progress_bp(tracks, status)) AND (progress_bp <=
CASE
    WHEN (status = 'completed'::text) THEN 10000
    ELSE 9999
END))),
    CONSTRAINT analysis_progress_state_completed_check CHECK (((status <> 'completed'::text) OR ((progress_bp = 10000) AND (((tracks -> 'relationshipAi'::text) ->> 'state'::text) = 'completed'::text) AND (((tracks -> 'interactions'::text) ->> 'state'::text) = 'completed'::text) AND (((tracks -> 'finalization'::text) ->> 'state'::text) = 'completed'::text)))),
    CONSTRAINT analysis_progress_state_eta_check CHECK (public.analysis_v2_valid_progress_eta(eta_range)),
    CONSTRAINT analysis_progress_state_fingerprint_check CHECK (((snapshot_fingerprint)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT analysis_progress_state_revision_check CHECK (((revision >= 1) AND (revision <= '9007199254740991'::bigint))),
    CONSTRAINT analysis_progress_state_sequence_check CHECK (((last_event_seq >= 0) AND (last_event_seq <= '9007199254740991'::bigint))),
    CONSTRAINT analysis_progress_state_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'processing'::text, 'completed'::text, 'failed'::text, 'upgrade_required'::text]))),
    CONSTRAINT analysis_progress_state_terminal_transient_check CHECK (((status <> ALL (ARRAY['completed'::text, 'failed'::text, 'upgrade_required'::text])) OR ((active_profile IS NULL) AND (eta_range IS NULL)))),
    CONSTRAINT analysis_progress_state_time_check CHECK ((updated_at >= created_at)),
    CONSTRAINT analysis_progress_state_tracks_check CHECK (public.analysis_v2_valid_progress_tracks(tracks))
);

ALTER TABLE ONLY public.analysis_progress_state FORCE ROW LEVEL SECURITY;


