--
-- Name: analysis_v2_progress_stage_rank(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_progress_stage_rank(p_track_id text, p_stage_code text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT CASE p_track_id
        WHEN 'relationshipAi' THEN CASE p_stage_code
            WHEN 'RELATIONSHIP_AI_QUEUED' THEN 0
            WHEN 'RELATIONSHIPS_COLLECTING' THEN 1
            WHEN 'RELATIONSHIP_AI_RUNNING' THEN 2
            WHEN 'PUBLIC_PROFILES_COLLECTING' THEN 3
            WHEN 'PROFILE_SCREENING' THEN 4
            WHEN 'EVIDENCE_JOINING' THEN 5
            WHEN 'CANDIDATES_RANKING' THEN 6
            WHEN 'PARTNER_CONTEXT_CHECKING' THEN 7
            WHEN 'RELATIONSHIP_AI_COMPLETE' THEN 8
            ELSE -1
        END
        WHEN 'interactions' THEN CASE p_stage_code
            WHEN 'INTERACTIONS_QUEUED' THEN 0
            WHEN 'TARGET_INTERACTIONS_COLLECTING' THEN 1
            WHEN 'INTERACTIONS_RUNNING' THEN 2
            WHEN 'SHORTLIST_INTERACTIONS_COLLECTING' THEN 3
            WHEN 'INTERACTIONS_COMPLETE' THEN 4
            ELSE -1
        END
        WHEN 'finalization' THEN CASE p_stage_code
            WHEN 'FINALIZATION_QUEUED' THEN 0
            WHEN 'FINALIZATION_RUNNING' THEN 1
            WHEN 'PRIVATE_NAMES_SCREENING' THEN 2
            WHEN 'FINAL_SCORE_CALCULATING' THEN 3
            WHEN 'HIGH_RISK_NARRATIVES_WRITING' THEN 4
            WHEN 'RESULT_FINALIZING' THEN 5
            WHEN 'FINALIZATION_COMPLETE' THEN 6
            ELSE -1
        END
        ELSE -1
    END;
$$;


--
-- Name: analysis_v2_progress_track_transition_valid(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_progress_track_transition_valid(p_previous jsonb, p_next jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT (p_next->>'done')::INTEGER >= (p_previous->>'done')::INTEGER
       AND (p_next->>'total')::INTEGER >= (p_previous->>'total')::INTEGER
       AND (p_next->>'progressBp')::INTEGER >= (p_previous->>'progressBp')::INTEGER
       AND (
            (p_previous->>'state' = 'pending'
                AND p_next->>'state' IN ('pending', 'running', 'completed', 'failed'))
            OR (p_previous->>'state' = 'running'
                AND p_next->>'state' IN ('running', 'completed', 'failed'))
            OR p_previous->>'state' IN ('completed', 'failed')
       )
       AND (
            p_previous->>'state' NOT IN ('completed', 'failed')
            OR p_next = p_previous
       );
$$;


