--
-- Name: analysis_v2_refresh_gender_resolution_metrics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_refresh_gender_resolution_metrics() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_metrics RECORD;
    v_policy_version TEXT;
    v_attempt_count INTEGER;
    v_usage_complete_count INTEGER;
    v_usage_missing_count INTEGER;
    v_applied_with_fence_count INTEGER;
    v_verified_baseline_mutation_count INTEGER;
    v_prompt_tokens BIGINT;
    v_completion_tokens BIGINT;
    v_total_tokens BIGINT;
    v_thinking_tokens BIGINT;
    v_estimated_cost_usd NUMERIC(18, 12);
    v_cost_known_count INTEGER;
    v_nonterminal_attempt_count INTEGER;
BEGIN
    IF NEW.stage_kind <> 'profile_ai_batch' THEN
        RETURN NEW;
    END IF;
    v_policy_version := public.load_analysis_v2_ai_stage_policy_version(NEW.request_id);
    WITH outcomes AS (
        SELECT outcome.value
        FROM public.analysis_v2_ai_scoring_stage_checkpoints AS checkpoint
        CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
            checkpoint.payload->'outcomes'
        ) AS outcome(value)
        WHERE checkpoint.request_id = NEW.request_id
          AND checkpoint.stage_kind = 'profile_ai_batch'
    )
    SELECT
        pg_catalog.count(*)::INTEGER AS screened_count,
        pg_catalog.count(*) FILTER (
            WHERE outcome.value->>'genderResolutionStatus'
                NOT IN ('disabled', 'not_eligible')
        )::INTEGER AS resolver_eligible_count,
        pg_catalog.count(*) FILTER (
            WHERE outcome.value->>'baselineClassification'
                NOT IN ('verified_female', 'verified_non_female')
        )::INTEGER AS baseline_unknown_count,
        pg_catalog.count(*) FILTER (
            WHERE outcome.value->>'status'
                NOT IN ('verified_female', 'verified_non_female')
        )::INTEGER AS final_unknown_count,
        pg_catalog.count(*) FILTER (
            WHERE outcome.value->>'genderResolutionStatus' IN (
                'ready_applied', 'ready_not_needed', 'ready_inconclusive'
            )
        )::INTEGER AS ready_count,
        pg_catalog.count(*) FILTER (
            WHERE outcome.value->>'genderResolutionStatus' = 'ready_applied'
        )::INTEGER AS applied_count,
        pg_catalog.count(*) FILTER (
            WHERE outcome.value->>'genderResolutionStatus' = 'ready_inconclusive'
        )::INTEGER AS inconclusive_count,
        pg_catalog.count(*) FILTER (
            WHERE outcome.value->>'genderResolutionStatus' = 'cutoff'
        )::INTEGER AS cutoff_count,
        pg_catalog.count(*) FILTER (
            WHERE outcome.value->>'genderResolutionStatus' = 'capacity_skipped'
        )::INTEGER AS capacity_skipped_count,
        pg_catalog.count(*) FILTER (
            WHERE outcome.value->>'genderResolutionStatus' = 'terminal_unavailable'
        )::INTEGER AS terminal_unavailable_count,
        pg_catalog.count(*) FILTER (
            WHERE pg_catalog.jsonb_array_length(
                    outcome.value->'mediaCoverage'->'failures'
                ) > 0
              AND pg_catalog.jsonb_array_length(
                    outcome.value->'mediaCoverage'->'failures'
                ) * 5
                    <= (outcome.value->'mediaCoverage'->>'selectedCount')::INTEGER
        )::INTEGER AS partial_media_accepted_candidate_count,
        COALESCE(pg_catalog.sum(
            (outcome.value->'mediaCoverage'->>'selectedCount')::INTEGER
        ), 0)::INTEGER AS selected_media_total,
        COALESCE(pg_catalog.sum(
            (outcome.value->'mediaCoverage'->>'normalizedCount')::INTEGER
        ), 0)::INTEGER AS normalized_media_total
    INTO v_metrics
    FROM outcomes AS outcome;

    SELECT
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status = 'ready_applied'
              AND feature.classification_source = 'gender_resolution'
              AND feature.gender_resolution_operation_key
                    ~ '^gender-resolution:[a-f0-9]{64}$'
              AND feature.gender_resolution_result_hash ~ '^[a-f0-9]{64}$'
        )::INTEGER,
        pg_catalog.count(*) FILTER (
            WHERE feature.baseline_classification IN (
                    'verified_female', 'verified_non_female'
                )
              AND feature.terminal_classification
                    IS DISTINCT FROM feature.baseline_classification
        )::INTEGER
    INTO v_applied_with_fence_count, v_verified_baseline_mutation_count
    FROM public.analysis_v2_candidate_feature_rows AS feature
    WHERE feature.request_id = NEW.request_id;

    SELECT
        pg_catalog.count(*)::INTEGER,
        pg_catalog.count(*) FILTER (
            WHERE attempt.usage_metadata_status = 'complete'
        )::INTEGER,
        pg_catalog.count(*) FILTER (
            WHERE attempt.usage_metadata_status IS DISTINCT FROM 'complete'
        )::INTEGER,
        COALESCE(pg_catalog.sum(attempt.prompt_tokens), 0)::BIGINT,
        COALESCE(pg_catalog.sum(attempt.completion_tokens), 0)::BIGINT,
        COALESCE(pg_catalog.sum(attempt.total_tokens), 0)::BIGINT,
        COALESCE(pg_catalog.sum(attempt.thinking_tokens), 0)::BIGINT,
        pg_catalog.sum(attempt.estimated_cost_usd)::NUMERIC(18, 12),
        pg_catalog.count(attempt.estimated_cost_usd)::INTEGER,
        pg_catalog.count(*) FILTER (
            WHERE attempt.status = 'reserved'
        )::INTEGER
    INTO
        v_attempt_count,
        v_usage_complete_count,
        v_usage_missing_count,
        v_prompt_tokens,
        v_completion_tokens,
        v_total_tokens,
        v_thinking_tokens,
        v_estimated_cost_usd,
        v_cost_known_count,
        v_nonterminal_attempt_count
    FROM public.analysis_v2_ai_attempts AS attempt
    WHERE attempt.request_id = NEW.request_id
      AND attempt.stage = 'genderResolution';

    INSERT INTO public.analysis_v2_gender_resolution_metrics (
        request_id,
        policy_version,
        screened_count,
        resolver_eligible_count,
        baseline_unknown_count,
        final_unknown_count,
        ready_count,
        applied_count,
        applied_with_fenced_result_count,
        verified_baseline_mutation_count,
        inconclusive_count,
        cutoff_count,
        capacity_skipped_count,
        terminal_unavailable_count,
        partial_media_accepted_candidate_count,
        selected_media_total,
        normalized_media_total,
        failed_media_total,
        resolver_attempt_count,
        resolver_usage_complete_count,
        resolver_usage_missing_count,
        resolver_prompt_tokens,
        resolver_completion_tokens,
        resolver_total_tokens,
        resolver_thinking_tokens,
        resolver_estimated_cost_usd,
        resolver_cost_known_count,
        resolver_nonterminal_attempt_count,
        metrics_finalized_at
    ) VALUES (
        NEW.request_id,
        v_policy_version,
        v_metrics.screened_count,
        v_metrics.resolver_eligible_count,
        v_metrics.baseline_unknown_count,
        v_metrics.final_unknown_count,
        v_metrics.ready_count,
        v_metrics.applied_count,
        v_applied_with_fence_count,
        v_verified_baseline_mutation_count,
        v_metrics.inconclusive_count,
        v_metrics.cutoff_count,
        v_metrics.capacity_skipped_count,
        v_metrics.terminal_unavailable_count,
        v_metrics.partial_media_accepted_candidate_count,
        v_metrics.selected_media_total,
        v_metrics.normalized_media_total,
        v_metrics.selected_media_total - v_metrics.normalized_media_total,
        v_attempt_count,
        v_usage_complete_count,
        v_usage_missing_count,
        v_prompt_tokens,
        v_completion_tokens,
        v_total_tokens,
        v_thinking_tokens,
        v_estimated_cost_usd,
        v_cost_known_count,
        v_nonterminal_attempt_count,
        NULL
    )
    ON CONFLICT (request_id) DO UPDATE
    SET policy_version = EXCLUDED.policy_version,
        screened_count = EXCLUDED.screened_count,
        resolver_eligible_count = EXCLUDED.resolver_eligible_count,
        baseline_unknown_count = EXCLUDED.baseline_unknown_count,
        final_unknown_count = EXCLUDED.final_unknown_count,
        ready_count = EXCLUDED.ready_count,
        applied_count = EXCLUDED.applied_count,
        applied_with_fenced_result_count =
            EXCLUDED.applied_with_fenced_result_count,
        verified_baseline_mutation_count =
            EXCLUDED.verified_baseline_mutation_count,
        inconclusive_count = EXCLUDED.inconclusive_count,
        cutoff_count = EXCLUDED.cutoff_count,
        capacity_skipped_count = EXCLUDED.capacity_skipped_count,
        terminal_unavailable_count = EXCLUDED.terminal_unavailable_count,
        partial_media_accepted_candidate_count =
            EXCLUDED.partial_media_accepted_candidate_count,
        selected_media_total = EXCLUDED.selected_media_total,
        normalized_media_total = EXCLUDED.normalized_media_total,
        failed_media_total = EXCLUDED.failed_media_total,
        resolver_attempt_count = EXCLUDED.resolver_attempt_count,
        resolver_usage_complete_count = EXCLUDED.resolver_usage_complete_count,
        resolver_usage_missing_count = EXCLUDED.resolver_usage_missing_count,
        resolver_prompt_tokens = EXCLUDED.resolver_prompt_tokens,
        resolver_completion_tokens = EXCLUDED.resolver_completion_tokens,
        resolver_total_tokens = EXCLUDED.resolver_total_tokens,
        resolver_thinking_tokens = EXCLUDED.resolver_thinking_tokens,
        resolver_estimated_cost_usd = EXCLUDED.resolver_estimated_cost_usd,
        resolver_cost_known_count = EXCLUDED.resolver_cost_known_count,
        resolver_nonterminal_attempt_count =
            EXCLUDED.resolver_nonterminal_attempt_count,
        metrics_finalized_at = NULL,
        updated_at = pg_catalog.clock_timestamp();
    RETURN NEW;
END;
$_$;


--
-- Name: analysis_v2_reject_global_ai_result_cache_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_reject_global_ai_result_cache_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    RAISE EXCEPTION USING
        MESSAGE = 'ANALYSIS_V2_GLOBAL_AI_RESULT_CACHE_DISABLED',
        ERRCODE = 'P0001';
END;
$$;


--
-- Name: analysis_v2_relationship_freeze_hash(text, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_relationship_freeze_hash(p_followers_hash text, p_following_hash text, p_exclusion_hash text, p_detailed_limit integer, p_mutual_rows jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'analysis-v2-relationship-freeze-v2'
                    || pg_catalog.chr(10) || p_followers_hash
                    || pg_catalog.chr(10) || p_following_hash
                    || pg_catalog.chr(10) || p_exclusion_hash
                    || pg_catalog.chr(10) || p_detailed_limit::TEXT
                    || pg_catalog.chr(10)
                    || COALESCE((
                        SELECT pg_catalog.string_agg(
                            mutual.value->>'mutual_ordinal'
                                || '|'
                                || (mutual.value->>'following_ordinal')
                                || '|'
                                || pg_catalog.octet_length(
                                    mutual.value->>'username'
                                )::TEXT
                                || ':' || (mutual.value->>'username')
                                || '|'
                                || CASE
                                    WHEN (mutual.value->>'is_private')::BOOLEAN
                                    THEN '1' ELSE '0'
                                END
                                || '|'
                                || CASE
                                    WHEN (mutual.value->>'is_verified')::BOOLEAN
                                    THEN '1' ELSE '0'
                                END
                                || '|'
                                || pg_catalog.octet_length(
                                    COALESCE(mutual.value->>'full_name', '')
                                )::TEXT
                                || ':' || COALESCE(mutual.value->>'full_name', '')
                                || '|'
                                || pg_catalog.octet_length(
                                    COALESCE(mutual.value->>'profile_pic_url', '')
                                )::TEXT
                                || ':' || COALESCE(mutual.value->>'profile_pic_url', '')
                                || '|'
                                || COALESCE(mutual.value->>'detailed_ordinal', ''),
                            pg_catalog.chr(10)
                            ORDER BY (mutual.value->>'mutual_ordinal')::INTEGER
                        )
                        FROM pg_catalog.jsonb_array_elements(p_mutual_rows) AS mutual(value)
                    ), ''),
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );
$$;


--
-- Name: analysis_v2_relationship_manifests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_relationship_manifests (
    request_id uuid NOT NULL,
    job_key character varying(160) NOT NULL,
    job_claim_token uuid NOT NULL,
    excluded_username character varying(30),
    exclusion_decision_hash character varying(64) NOT NULL,
    detailed_mutual_limit smallint NOT NULL,
    followers_result_hash character varying(64) NOT NULL,
    following_result_hash character varying(64) NOT NULL,
    result_hash character varying(64) NOT NULL,
    mutual_count smallint NOT NULL,
    public_count smallint NOT NULL,
    private_count smallint NOT NULL,
    detailed_public_count smallint NOT NULL,
    revision smallint DEFAULT 1 NOT NULL,
    frozen_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_v2_relationship_manifests_count_check CHECK ((((mutual_count >= 0) AND (mutual_count <= 1200)) AND ((public_count >= 0) AND (public_count <= mutual_count)) AND ((private_count >= 0) AND (private_count <= mutual_count)) AND ((public_count + private_count) = mutual_count) AND ((detailed_public_count >= 0) AND (detailed_public_count <= public_count)) AND (detailed_public_count <= detailed_mutual_limit))),
    CONSTRAINT analysis_v2_relationship_manifests_exclusion_check CHECK (((excluded_username IS NULL) OR ((excluded_username)::text ~ '^[a-z0-9._]{1,30}$'::text))),
    CONSTRAINT analysis_v2_relationship_manifests_hash_check CHECK ((((exclusion_decision_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((followers_result_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((following_result_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((result_hash)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT analysis_v2_relationship_manifests_limit_check CHECK ((detailed_mutual_limit = ANY (ARRAY[300, 600, 900]))),
    CONSTRAINT analysis_v2_relationship_manifests_revision_check CHECK ((revision = 1)),
    CONSTRAINT analysis_v2_relationship_manifests_timestamp_check CHECK (((frozen_at >= created_at) AND (updated_at >= created_at)))
);

ALTER TABLE ONLY public.analysis_v2_relationship_manifests FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_relationship_manifest_json(public.analysis_v2_relationship_manifests); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_relationship_manifest_json(p_manifest public.analysis_v2_relationship_manifests) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'revision', p_manifest.revision,
        'resultHash', p_manifest.result_hash,
        'exclusionDecisionHash', p_manifest.exclusion_decision_hash,
        'followersResultHash', p_manifest.followers_result_hash,
        'followingResultHash', p_manifest.following_result_hash,
        'mutualCount', p_manifest.mutual_count,
        'publicCount', p_manifest.public_count,
        'privateCount', p_manifest.private_count,
        'detailedPublicCount', p_manifest.detailed_public_count,
        'unscreenedPublicCount',
            p_manifest.public_count - p_manifest.detailed_public_count
    );
$$;


--
-- Name: analysis_v2_relationship_not_applicable_input_hash(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_relationship_not_applicable_input_hash(p_side text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT CASE
        WHEN p_side IN ('followers', 'following') THEN pg_catalog.encode(
            extensions.digest(
                pg_catalog.convert_to(
                    'analysis-v2-relationship-not-applicable-v1'
                        || pg_catalog.chr(10)
                        || p_side
                        || pg_catalog.chr(10)
                        || '0',
                    'UTF8'
                ),
                'sha256'
            ),
            'hex'
        )
        ELSE NULL
    END;
$$;


--
-- Name: analysis_v2_relationship_provider_identity(text, text, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_relationship_provider_identity(p_side text, p_target_username text, p_declared_count integer, p_plan_id text, p_replacement boolean DEFAULT false) RETURNS TABLE(operation_key text, input_hash text)
    LANGUAGE plpgsql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_kind TEXT;
    v_canonical TEXT;
BEGIN
    IF p_side NOT IN ('followers', 'following')
       OR p_target_username !~ '^[a-z0-9._]{1,30}$'
       OR p_declared_count NOT BETWEEN 1 AND 1200
       OR p_plan_id NOT IN ('basic', 'standard', 'plus') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RELATIONSHIP_PROVIDER_IDENTITY_INVALID',
            ERRCODE = 'P0001';
    END IF;
    v_kind := 'relationship-' || p_side;
    v_canonical :=
        pg_catalog.octet_length('relationship-v2')::TEXT || ':relationship-v2'
        || pg_catalog.chr(10)
        || pg_catalog.octet_length(p_side)::TEXT || ':' || p_side
        || pg_catalog.chr(10)
        || pg_catalog.octet_length(p_target_username)::TEXT || ':' || p_target_username
        || pg_catalog.chr(10)
        || pg_catalog.octet_length(p_declared_count::TEXT)::TEXT || ':' || p_declared_count::TEXT
        || pg_catalog.chr(10)
        || pg_catalog.octet_length(p_plan_id)::TEXT || ':' || p_plan_id
        || pg_catalog.chr(10)
        || pg_catalog.octet_length('apify-no-cookie')::TEXT || ':apify-no-cookie';
    IF p_replacement THEN
        v_canonical :=
            pg_catalog.octet_length('relationship-incomplete-replacement-v1')::TEXT
            || ':relationship-incomplete-replacement-v1'
            || pg_catalog.chr(10)
            || pg_catalog.octet_length(v_canonical)::TEXT || ':' || v_canonical;
    END IF;
    RETURN QUERY SELECT
        v_kind || ':' || pg_catalog.encode(extensions.digest(
            pg_catalog.convert_to(
                'analysis-v2-provider-operation-v1' || pg_catalog.chr(10)
                || v_kind || pg_catalog.chr(10) || v_canonical,
                'UTF8'
            ), 'sha256'
        ), 'hex'),
        pg_catalog.encode(extensions.digest(
            pg_catalog.convert_to(
                'analysis-v2-provider-input-v1' || pg_catalog.chr(10)
                || v_canonical,
                'UTF8'
            ), 'sha256'
        ), 'hex');
END;
$_$;


--
-- Name: analysis_v2_relationship_rows_hash(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_relationship_rows_hash(p_side text, p_rows jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'analysis-v2-relationship-result-v2'
                    || pg_catalog.chr(10)
                    || p_side
                    || pg_catalog.chr(10)
                    || COALESCE((
                        SELECT pg_catalog.string_agg(
                            relationship_row.ordinal::TEXT
                                || '|'
                                || pg_catalog.octet_length(
                                    relationship_row.value->>'username'
                                )::TEXT
                                || ':' || (relationship_row.value->>'username')
                                || '|'
                                || CASE
                                    WHEN (relationship_row.value->>'is_private')::BOOLEAN
                                    THEN '1' ELSE '0'
                                END
                                || '|'
                                || CASE
                                    WHEN (relationship_row.value->>'is_verified')::BOOLEAN
                                    THEN '1' ELSE '0'
                                END
                                || '|'
                                || pg_catalog.octet_length(
                                    COALESCE(relationship_row.value->>'full_name', '')
                                )::TEXT
                                || ':' || COALESCE(relationship_row.value->>'full_name', '')
                                || '|'
                                || pg_catalog.octet_length(
                                    COALESCE(relationship_row.value->>'profile_pic_url', '')
                                )::TEXT
                                || ':' || COALESCE(
                                    relationship_row.value->>'profile_pic_url', ''
                                ),
                            pg_catalog.chr(10)
                            ORDER BY relationship_row.ordinal
                        )
                        FROM pg_catalog.jsonb_array_elements(p_rows)
                            WITH ORDINALITY AS relationship_row(value, ordinal)
                    ), ''),
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );
$$;


--
-- Name: analysis_v2_relationship_sides; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_relationship_sides (
    request_id uuid NOT NULL,
    job_key character varying(160) NOT NULL,
    side character varying(16) NOT NULL,
    job_claim_token uuid NOT NULL,
    provider character varying(16),
    provider_run_id character varying(128),
    provider_operation_key character varying(128),
    provider_credential_slot character varying(16),
    declared_count smallint NOT NULL,
    collected_count smallint NOT NULL,
    coverage_bps smallint NOT NULL,
    input_hash character varying(64) NOT NULL,
    result_hash character varying(64) NOT NULL,
    revision smallint DEFAULT 1 NOT NULL,
    completed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    source_status character varying(24) DEFAULT 'collected'::character varying NOT NULL,
    CONSTRAINT analysis_v2_relationship_sides_count_check CHECK ((((declared_count >= 0) AND (declared_count <= 1200)) AND ((collected_count >= 0) AND (collected_count <= declared_count)) AND (((declared_count = 0) AND (collected_count = 0) AND (coverage_bps = 10000)) OR ((declared_count > 0) AND ((collected_count * 100) >= (declared_count * 99)) AND (coverage_bps = (((collected_count)::integer * 10000) / declared_count)))))),
    CONSTRAINT analysis_v2_relationship_sides_credential_check CHECK (((provider_credential_slot IS NULL) OR public.analysis_v2_valid_apify_credential_slot((provider_credential_slot)::text))),
    CONSTRAINT analysis_v2_relationship_sides_hash_check CHECK ((((input_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((result_hash)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT analysis_v2_relationship_sides_operation_check CHECK (((provider_operation_key)::text ~ (('^relationship-'::text || (side)::text) || ':[0-9a-f]{64}$'::text))),
    CONSTRAINT analysis_v2_relationship_sides_provider_check CHECK (((provider)::text = ANY ((ARRAY['apify'::character varying, 'coderx'::character varying, 'selfhosted_auth'::character varying])::text[]))),
    CONSTRAINT analysis_v2_relationship_sides_revision_check CHECK ((revision = 1)),
    CONSTRAINT analysis_v2_relationship_sides_run_id_check CHECK (((provider_run_id)::text ~ '^[A-Za-z0-9]{8,64}$'::text)),
    CONSTRAINT analysis_v2_relationship_sides_side_check CHECK (((side)::text = ANY ((ARRAY['followers'::character varying, 'following'::character varying])::text[]))),
    CONSTRAINT analysis_v2_relationship_sides_source_status_check CHECK (((((source_status)::text = 'not_applicable'::text) AND (declared_count = 0) AND (collected_count = 0) AND (coverage_bps = 10000) AND ((input_hash)::text = public.analysis_v2_relationship_not_applicable_input_hash((side)::text)) AND (provider IS NULL) AND (provider_run_id IS NULL) AND (provider_operation_key IS NULL) AND (provider_credential_slot IS NULL)) OR (((source_status)::text = 'collected'::text) AND (declared_count > 0) AND ((provider)::text = ANY ((ARRAY['apify'::character varying, 'selfhosted_auth'::character varying])::text[])) AND (provider_run_id IS NOT NULL) AND (provider_operation_key IS NOT NULL) AND (provider_credential_slot IS NOT NULL)))),
    CONSTRAINT analysis_v2_relationship_sides_timestamp_check CHECK (((completed_at >= created_at) AND (updated_at >= created_at)))
);

ALTER TABLE ONLY public.analysis_v2_relationship_sides FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_relationship_side_json(public.analysis_v2_relationship_sides); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_relationship_side_json(p_side public.analysis_v2_relationship_sides) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'side', p_side.side,
        'sourceStatus', p_side.source_status,
        'revision', p_side.revision,
        'declaredCount', p_side.declared_count,
        'collectedCount', p_side.collected_count,
        'coverageBps', p_side.coverage_bps,
        'inputHash', p_side.input_hash,
        'resultHash', p_side.result_hash
    );
$$;


--
-- Name: analysis_v2_relative_overview_fallback(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_relative_overview_fallback(p_duplicate_ordinal integer) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    v_prefixes CONSTANT TEXT[] := ARRAY[
        '피드가 말을 아끼는 편이네요, ',
        '사진 배치가 지나치게 단정하네요, ',
        '전체 분위기가 묘하게 계산돼 있네요, ',
        '첫인상은 얌전한데 여운이 길게 남네요, ',
        '취향을 슬쩍만 보여 주는 구성이네요, ',
        '일상 기록이 의외로 빈틈없이 이어지네요, ',
        '꾸민 듯 안 꾸민 듯한 장면이 많네요, ',
        '프로필이 정답을 쉽게 주지 않네요, ',
        '피드의 온도가 은근히 사람을 붙잡네요, ',
        '설명보다 분위기가 먼저 말을 거네요, '
    ];
    v_middles CONSTANT TEXT[] := ARRAY[
        '판독관은 괜히 숨은 취향부터 살피게 되고 ',
        '이 정도 여백이면 사소한 단서도 크게 보이고 ',
        '무심한 척한 연출까지 한 번 더 보게 되고 ',
        '평범한 장면 뒤의 선택이 자꾸 궁금해지고 ',
        '사진 사이의 온도 차를 괜히 재보게 되고 ',
        '말하지 않은 부분에 눈길이 더 오래 머물고 ',
        '취향의 방향을 혼자 추리해 보게 되고 ',
        '캡션보다 표정과 구도를 먼저 의심하게 되고 ',
        '단정한 화면 속 작은 변화를 찾게 되고 ',
        '별일 없어 보여도 촉이 한 번 더 움직이고 '
    ];
    v_suffixes CONSTANT TEXT[] := ARRAY[
        '마지막까지 묘한 여운이 남습니다.',
        '쉽게 지나치기에는 제법 신경이 쓰입니다.',
        '괜한 상상력이 조용히 발동합니다.',
        '한 번 본 뒤에도 은근히 기억에 남습니다.',
        '판독관의 참견 본능이 슬쩍 깨어납니다.',
        '차분한 화면보다 뒷이야기가 더 궁금합니다.',
        '평범하다고 넘기기엔 분위기가 선명합니다.',
        '조용한 피드치고는 존재감이 꽤 큽니다.',
        '결국 한 장씩 다시 들여다보게 됩니다.'
    ];
    v_zero_based INTEGER;
BEGIN
    IF p_duplicate_ordinal IS NULL OR p_duplicate_ordinal NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RELATIVE_OVERVIEW_INVALID',
            ERRCODE = 'P0001';
    END IF;
    v_zero_based := p_duplicate_ordinal - 1;
    RETURN
        v_prefixes[1 + (v_zero_based % 10)]
        || v_middles[1 + ((v_zero_based / 10) % 10)]
        || v_suffixes[1 + ((v_zero_based / 100) % 9)];
END;
$$;


--
-- Name: analysis_v2_replay_capture_policy_is_exact(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_replay_capture_policy_is_exact(p_snapshot jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT p_snapshot IS NOT NULL
       AND pg_catalog.jsonb_typeof(p_snapshot) = 'object'
       AND p_snapshot ?& ARRAY['pipeline', 'risk', 'aiStage', 'scheduler']
       AND p_snapshot - ARRAY['pipeline', 'risk', 'aiStage', 'scheduler']
            = '{}'::JSONB
       AND p_snapshot->>'pipeline' = 'v2'
       AND p_snapshot->>'risk' = 'risk-policy-v2.4'
       AND p_snapshot->>'aiStage' = 'ai-stage-policy-v2.9'
       AND p_snapshot->>'scheduler' = 'ai-scheduler-v1'
$$;


--
-- Name: analysis_v2_reserve_preflight_admission_after_settlement_intern(uuid, uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_reserve_preflight_admission_after_settlement_intern(p_preflight_id uuid, p_user_id uuid, p_selected_plan_id text, p_entitlement_jti_hash text, p_admission_token uuid, p_dispatch_token uuid) RETURNS TABLE(admission_status text, should_enqueue boolean, admission_generation integer, dispatch_generation integer, dispatch_token uuid, selected_plan_id text, selected_plan_allowed boolean, admission_token uuid, admission_refreshed_at timestamp with time zone, target_followers_count integer, target_following_count integer, capacity_required_plan_id text, required_plan_id text, plan_cards_snapshot jsonb, pricing_version text, pricing_snapshot jsonb, admission_error_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_fresh BOOLEAN;
    v_allowed BOOLEAN;
    v_same_attempt BOOLEAN;
    v_effective_token UUID;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_selected_plan_id IS NULL
       OR p_selected_plan_id NOT IN ('basic', 'standard', 'plus')
       OR p_entitlement_jti_hash IS NULL
       OR p_entitlement_jti_hash !~ '^[a-f0-9]{64}$'
       OR p_admission_token IS NULL
       OR p_dispatch_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_FRESH_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.expires_at <= v_now OR v_preflight.status = 'expired' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_EXPIRED', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status <> 'ready'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.exclusion_decision NOT IN ('exclude', 'skip') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.access_mode NOT IN ('production', 'test_entitlement')
       OR NOT public.analysis_v2_valid_launch_snapshot(v_preflight.launch_status_snapshot)
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(v_preflight.plan_catalog_snapshot)
       OR NOT public.analysis_v2_valid_pricing_snapshot(v_preflight.pricing_snapshot)
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(
           v_preflight.policy_versions_snapshot
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
    END IF;

    v_same_attempt := v_preflight.admission_selected_plan_id IS NOT DISTINCT FROM p_selected_plan_id
        AND v_preflight.admission_entitlement_jti_hash
            IS NOT DISTINCT FROM p_entitlement_jti_hash;
    v_effective_token := CASE
        WHEN v_same_attempt AND v_preflight.admission_token IS NOT NULL
            THEN v_preflight.admission_token
        ELSE p_admission_token
    END;

    v_fresh := v_preflight.admission_status IN ('ready', 'blocked')
        AND v_preflight.admission_refreshed_at >= v_now - INTERVAL '2 minutes'
        AND v_preflight.admission_refreshed_at <= v_now + INTERVAL '30 seconds';

    IF v_fresh THEN
        UPDATE public.analysis_preflights AS preflight
        SET admission_selected_plan_id = p_selected_plan_id,
            admission_entitlement_jti_hash = p_entitlement_jti_hash,
            admission_token = v_effective_token,
            updated_at = v_now
        WHERE preflight.id = v_preflight.id;

        v_allowed := v_preflight.admission_status = 'ready'
            AND v_preflight.admission_plan_cards_snapshot
                ->p_selected_plan_id->>'selectionState'
                IN ('required', 'available_upgrade');

        RETURN QUERY SELECT
            v_preflight.admission_status,
            FALSE,
            v_preflight.admission_generation,
            v_preflight.admission_dispatch_generation,
            NULL::UUID,
            p_selected_plan_id,
            CASE WHEN v_preflight.admission_status = 'ready' THEN v_allowed ELSE NULL END,
            CASE WHEN v_preflight.admission_status = 'ready'
                THEN v_effective_token ELSE NULL END,
            v_preflight.admission_refreshed_at,
            v_preflight.admission_target_followers_count,
            v_preflight.admission_target_following_count,
            v_preflight.admission_capacity_required_plan_id,
            v_preflight.admission_required_plan_id,
            v_preflight.admission_plan_cards_snapshot,
            v_preflight.pricing_version::TEXT,
            v_preflight.pricing_snapshot,
            v_preflight.admission_error_code;
        RETURN;
    END IF;

    IF v_preflight.admission_status = 'processing'
       AND v_preflight.admission_lease_expires_at <= v_now THEN
        UPDATE public.analysis_preflights AS preflight
        SET admission_status = 'pending',
            admission_selected_plan_id = p_selected_plan_id,
            admission_entitlement_jti_hash = p_entitlement_jti_hash,
            admission_token = v_effective_token,
            admission_claim_token = NULL,
            admission_lease_expires_at = NULL,
            updated_at = v_now
        WHERE preflight.id = v_preflight.id;
        v_preflight.admission_status := 'pending';
    END IF;

    IF v_preflight.admission_status = 'processing'
       AND v_preflight.admission_lease_expires_at > v_now THEN
        UPDATE public.analysis_preflights AS preflight
        SET admission_selected_plan_id = p_selected_plan_id,
            admission_entitlement_jti_hash = p_entitlement_jti_hash,
            admission_token = v_effective_token,
            updated_at = v_now
        WHERE preflight.id = v_preflight.id;

        RETURN QUERY SELECT
            'processing'::TEXT,
            FALSE,
            v_preflight.admission_generation,
            v_preflight.admission_dispatch_generation,
            NULL::UUID,
            p_selected_plan_id,
            NULL::BOOLEAN,
            NULL::UUID,
            NULL::TIMESTAMP WITH TIME ZONE,
            NULL::INTEGER,
            NULL::INTEGER,
            NULL::TEXT,
            NULL::TEXT,
            NULL::JSONB,
            v_preflight.pricing_version::TEXT,
            v_preflight.pricing_snapshot,
            NULL::TEXT;
        RETURN;
    END IF;

    IF v_preflight.admission_status = 'pending' THEN
        IF v_preflight.admission_dispatch_state = 'enqueued'
           OR (
               v_preflight.admission_dispatch_state = 'reserved'
               AND v_preflight.admission_dispatch_reserved_at
                    > v_now - INTERVAL '2 minutes'
           ) THEN
            UPDATE public.analysis_preflights AS preflight
            SET admission_selected_plan_id = p_selected_plan_id,
                admission_entitlement_jti_hash = p_entitlement_jti_hash,
                admission_token = v_effective_token,
                updated_at = v_now
            WHERE preflight.id = v_preflight.id;

            RETURN QUERY SELECT
                'pending'::TEXT,
                FALSE,
                v_preflight.admission_generation,
                v_preflight.admission_dispatch_generation,
                NULL::UUID,
                p_selected_plan_id,
                NULL::BOOLEAN,
                NULL::UUID,
                NULL::TIMESTAMP WITH TIME ZONE,
                NULL::INTEGER,
                NULL::INTEGER,
                NULL::TEXT,
                NULL::TEXT,
                NULL::JSONB,
                v_preflight.pricing_version::TEXT,
                v_preflight.pricing_snapshot,
                NULL::TEXT;
            RETURN;
        END IF;

        IF v_preflight.admission_dispatch_generation >= 100 THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
        END IF;

        UPDATE public.analysis_preflights AS preflight
        SET admission_selected_plan_id = p_selected_plan_id,
            admission_entitlement_jti_hash = p_entitlement_jti_hash,
            admission_token = v_effective_token,
            admission_dispatch_state = 'reserved',
            admission_dispatch_generation = v_preflight.admission_dispatch_generation + 1,
            admission_dispatch_token = p_dispatch_token,
            admission_dispatch_reserved_at = v_now,
            admission_dispatched_at = NULL,
            updated_at = v_now
        WHERE preflight.id = v_preflight.id;

        RETURN QUERY SELECT
            'pending'::TEXT,
            TRUE,
            v_preflight.admission_generation,
            v_preflight.admission_dispatch_generation + 1,
            p_dispatch_token,
            p_selected_plan_id,
            NULL::BOOLEAN,
            NULL::UUID,
            NULL::TIMESTAMP WITH TIME ZONE,
            NULL::INTEGER,
            NULL::INTEGER,
            NULL::TEXT,
            NULL::TEXT,
            NULL::JSONB,
            v_preflight.pricing_version::TEXT,
            v_preflight.pricing_snapshot,
            NULL::TEXT;
        RETURN;
    END IF;

    IF v_preflight.admission_generation >= 100 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET admission_status = 'pending',
        admission_generation = v_preflight.admission_generation + 1,
        admission_selected_plan_id = p_selected_plan_id,
        admission_entitlement_jti_hash = p_entitlement_jti_hash,
        admission_token = p_admission_token,
        admission_requested_at = v_now,
        admission_refreshed_at = NULL,
        admission_claim_token = NULL,
        admission_lease_expires_at = NULL,
        admission_dispatch_state = 'reserved',
        admission_dispatch_generation = 1,
        admission_dispatch_token = p_dispatch_token,
        admission_dispatch_reserved_at = v_now,
        admission_dispatched_at = NULL,
        admission_error_code = NULL,
        admission_target_followers_count = NULL,
        admission_target_following_count = NULL,
        admission_capacity_required_plan_id = NULL,
        admission_required_plan_id = NULL,
        admission_plan_cards_snapshot = NULL,
        admission_failure_count = 0,
        admission_last_error_code = NULL,
        updated_at = v_now
    WHERE preflight.id = v_preflight.id;

    RETURN QUERY SELECT
        'pending'::TEXT,
        TRUE,
        v_preflight.admission_generation + 1,
        1,
        p_dispatch_token,
        p_selected_plan_id,
        NULL::BOOLEAN,
        NULL::UUID,
        NULL::TIMESTAMP WITH TIME ZONE,
        NULL::INTEGER,
        NULL::INTEGER,
        NULL::TEXT,
        NULL::TEXT,
        NULL::JSONB,
        v_preflight.pricing_version::TEXT,
        v_preflight.pricing_snapshot,
        NULL::TEXT;
END;
$_$;


--
-- Name: analysis_v2_reserve_provider_run_internal(uuid, text, uuid, text, text, text, text, text, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_reserve_provider_run_internal(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric, p_reservation_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight_id UUID;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_existing public.analysis_v2_provider_runs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_operation_key IS NULL
       OR NOT public.analysis_v2_valid_provider_operation_key(p_operation_key)
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_logical_provider IS NULL
       OR p_logical_provider NOT IN ('apify', 'coderx')
       OR p_actor_id IS NULL
       OR pg_catalog.char_length(p_actor_id) NOT BETWEEN 3 AND 200
       OR p_actor_id !~ '^[A-Za-z0-9][A-Za-z0-9._~/-]{2,199}$'
       OR NOT public.analysis_v2_valid_apify_credential_slot(
            p_credential_slot
       )
       OR p_max_charge_usd IS NULL
       OR p_max_charge_usd NOT BETWEEN 0 AND 100000
       OR p_max_charge_usd <> pg_catalog.round(p_max_charge_usd, 12)
       OR p_reservation_token IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.id
    INTO v_preflight_id
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND OR v_request.status NOT IN ('pending', 'processing') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_ACTIVE',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_existing
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    FOR UPDATE;

    IF FOUND THEN
        IF v_existing.input_hash IS DISTINCT FROM p_input_hash
           OR v_existing.logical_provider IS DISTINCT FROM p_logical_provider
           OR v_existing.actor_id IS DISTINCT FROM p_actor_id
           OR v_existing.credential_slot IS DISTINCT FROM p_credential_slot
           OR v_existing.max_charge_usd IS DISTINCT FROM p_max_charge_usd THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_IDENTITY_CONFLICT',
                ERRCODE = 'P0001';
        END IF;

        IF v_existing.job_claim_token IS DISTINCT FROM p_claim_token THEN
            UPDATE public.analysis_v2_provider_runs AS provider_run
            SET job_claim_token = p_claim_token,
                updated_at = v_now
            WHERE provider_run.request_id = p_request_id
              AND provider_run.job_key = p_job_key
              AND provider_run.operation_key = p_operation_key
            RETURNING provider_run.* INTO v_existing;
        END IF;

        RETURN pg_catalog.jsonb_build_object(
            'created', FALSE,
            'run', public.analysis_v2_provider_run_json(v_existing)
        );
    END IF;

    INSERT INTO public.analysis_v2_provider_runs (
        request_id,
        job_key,
        operation_key,
        input_hash,
        job_claim_token,
        reservation_token,
        logical_provider,
        actor_id,
        credential_slot,
        max_charge_usd
    ) VALUES (
        p_request_id,
        p_job_key,
        p_operation_key,
        p_input_hash,
        p_claim_token,
        p_reservation_token,
        p_logical_provider,
        p_actor_id,
        p_credential_slot,
        p_max_charge_usd
    )
    RETURNING * INTO v_existing;

    RETURN pg_catalog.jsonb_build_object(
        'created', TRUE,
        'run', public.analysis_v2_provider_run_json(v_existing)
    );
END;
$_$;


--
-- Name: analysis_v2_result_candidate_id(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_result_candidate_id(p_username text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT 'candidate:' || pg_catalog.substr(
        pg_catalog.encode(
            extensions.digest(
                pg_catalog.convert_to(
                    'analysis-v2-candidate-id-v1' || pg_catalog.chr(10)
                        || pg_catalog.lower(p_username),
                    'UTF8'
                ),
                'sha256'
            ),
            'hex'
        ),
        1,
        40
    );
$$;


--
-- Name: analysis_v2_result_checkpoint_json(uuid, text, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_result_checkpoint_json(p_request_id uuid, p_job_key text, p_batch integer, p_item_count integer, p_row_count integer, p_result_hash text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT CASE
        WHEN p_request_id IS NULL OR p_job_key IS NULL
          OR p_item_count IS NULL OR p_row_count IS NULL OR p_result_hash IS NULL
        THEN NULL
        ELSE pg_catalog.jsonb_build_object(
            'requestId', p_request_id,
            'jobKey', p_job_key,
            'batch', p_batch,
            'itemCount', p_item_count,
            'rowCount', p_row_count,
            'resultHash', p_result_hash
        )
    END;
$$;


--
-- Name: analysis_v2_result_image_coverage_ok(integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_result_image_coverage_ok(p_expected_rows integer, p_durable_rows integer, p_sourced_images integer, p_ready_images integer, p_capture_failed_images integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT
        p_expected_rows BETWEEN 0 AND 50001
        AND p_durable_rows BETWEEN 0 AND p_expected_rows
        AND p_sourced_images BETWEEN 0 AND p_durable_rows
        AND p_ready_images BETWEEN 0 AND p_sourced_images
        AND p_capture_failed_images BETWEEN 0
            AND p_sourced_images - p_ready_images
        AND (
            p_expected_rows = 0
            OR (
                p_durable_rows::NUMERIC / p_expected_rows >= 0.98
                AND p_expected_rows - p_durable_rows <= 5
            )
        )
        AND (
            p_sourced_images = 0
            OR (
                p_ready_images::NUMERIC / p_sourced_images >= 0.95
                AND p_capture_failed_images <= 10
            )
        );
$$;


--
-- Name: analysis_v2_result_partner_safety_row_matches(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_result_partner_safety_row_matches(p_request_id uuid, p_partner_job_key text, p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
DECLARE
    v_feature public.analysis_v2_candidate_feature_rows%ROWTYPE;
    v_feature_ai public.analysis_v2_ai_result_checkpoints%ROWTYPE;
    v_partner_ai public.analysis_v2_ai_result_checkpoints%ROWTYPE;
    v_features JSONB;
    v_assessment JSONB;
    v_feature_evidence TEXT[] := '{}'::TEXT[];
    v_contact_evidence TEXT[] := '{}'::TEXT[];
    v_expected_evidence TEXT[] := '{}'::TEXT[];
    v_row_evidence TEXT[] := '{}'::TEXT[];
    v_feature_strong BOOLEAN;
    v_feature_weak BOOLEAN;
    v_contact_strong BOOLEAN := FALSE;
    v_contact_weak BOOLEAN := FALSE;
    v_expected_strong BOOLEAN;
    v_expected_weak_raw BOOLEAN;
    v_expected_weak BOOLEAN;
    v_expected_basis TEXT;
    v_source TEXT;
    v_expected_partner_bundle_id TEXT;
BEGIN
    IF p_request_id IS NULL
       OR p_partner_job_key IS NULL
       OR p_value IS NULL
       OR pg_catalog.jsonb_typeof(p_value) <> 'object'
       OR p_value->>'candidateId' !~ '^[A-Za-z0-9._:-]{1,128}$'
       OR p_value->>'source' NOT IN (
            'not_collected', 'feature_only', 'gemini', 'safe_fallback'
       )
       OR pg_catalog.jsonb_typeof(p_value->'hasStrongPartnerEvidence') <> 'boolean'
       OR pg_catalog.jsonb_typeof(p_value->'hasWeakPartnerEvidence') <> 'boolean'
       OR p_value->>'strongEvidenceBasis' NOT IN (
            'none', 'feature', 'contact_sheet', 'both'
       )
       OR pg_catalog.jsonb_typeof(p_value->'evidenceSelectionIds') <> 'array'
       OR pg_catalog.jsonb_array_length(p_value->'evidenceSelectionIds') > 8 THEN
        RETURN FALSE;
    END IF;

    SELECT feature.*
    INTO v_feature
    FROM public.analysis_v2_candidate_feature_rows AS feature
    WHERE feature.request_id = p_request_id
      AND feature.candidate_id = p_value->>'candidateId'
      AND feature.terminal_classification = 'verified_female';
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    SELECT ai_result.*
    INTO v_feature_ai
    FROM public.analysis_v2_ai_result_checkpoints AS ai_result
    JOIN public.analysis_v2_candidate_feature_manifests AS manifest
      ON manifest.request_id = v_feature.request_id
     AND manifest.batch = v_feature.batch
     AND manifest.producer_job_key = ai_result.job_key
    WHERE ai_result.request_id = p_request_id
      AND ai_result.operation_key = v_feature.feature_operation_key
      AND ai_result.stage = 'featureAnalysis'
      AND ai_result.result_hash = v_feature.feature_result_hash;
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    -- featureAnalysis checkpoints contain the raw validated model response.
    v_features := v_feature_ai.result_json;
    IF pg_catalog.jsonb_typeof(v_features) <> 'object'
       OR v_features->>'partnerExclusionContext' NOT IN (
            'none', 'celebrity_or_public_figure', 'older_relative', 'group_or_unclear'
       )
       OR v_features->>'marriageEvidence' NOT IN (
            'none', 'possible', 'strong', 'uncertain'
       )
       OR v_features->>'partnerEvidence' NOT IN (
            'none', 'weak', 'strong', 'uncertain'
       )
       OR pg_catalog.jsonb_typeof(v_features->'evidenceSelectionIds') <> 'object'
       OR pg_catalog.jsonb_typeof(
            v_features->'evidenceSelectionIds'->'marriagePartner'
          ) <> 'array'
       OR pg_catalog.jsonb_array_length(
            v_features->'evidenceSelectionIds'->'marriagePartner'
          ) > 10
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(
                v_features->'evidenceSelectionIds'->'marriagePartner'
            ) AS evidence(value)
            WHERE pg_catalog.jsonb_typeof(evidence.value) <> 'string'
               OR evidence.value #>> '{}' !~ '^[^[:cntrl:]]{1,240}$'
               OR NOT EXISTS (
                    SELECT 1
                    FROM pg_catalog.jsonb_array_elements_text(
                        v_feature.media_context->'selectionIds'
                    ) AS selected(value)
                    WHERE selected.value = evidence.value #>> '{}'
               )
       ) THEN
        RETURN FALSE;
    END IF;

    v_feature_strong := v_features->>'partnerExclusionContext' = 'none'
        AND (
            v_features->>'marriageEvidence' = 'strong'
            OR v_features->>'partnerEvidence' = 'strong'
        );
    v_feature_weak := v_features->>'partnerExclusionContext' = 'none'
        AND (
            v_features->>'marriageEvidence' = 'possible'
            OR v_features->>'partnerEvidence' = 'weak'
        );
    IF v_feature_strong OR v_feature_weak THEN
        SELECT COALESCE(
            pg_catalog.array_agg(evidence.value ORDER BY evidence.ordinality),
            '{}'::TEXT[]
        )
        INTO v_feature_evidence
        FROM pg_catalog.jsonb_array_elements_text(
            v_features->'evidenceSelectionIds'->'marriagePartner'
        ) WITH ORDINALITY AS evidence(value, ordinality);
    END IF;

    v_source := p_value->>'source';
    IF v_source = 'gemini' THEN
        SELECT ai_result.*
        INTO v_partner_ai
        FROM public.analysis_v2_ai_result_checkpoints AS ai_result
        WHERE ai_result.request_id = p_request_id
          AND ai_result.job_key = p_partner_job_key
          AND ai_result.operation_key = p_value->>'operationKey'
          AND ai_result.stage = 'partnerSafety'
          AND ai_result.result_hash = p_value->>'aiResultHash';
        IF NOT FOUND THEN
            RETURN FALSE;
        END IF;

        -- partnerSafety checkpoints likewise contain the raw assessment object.
        v_assessment := v_partner_ai.result_json;
        IF pg_catalog.jsonb_typeof(v_assessment) <> 'object'
           OR NOT (v_assessment ?& ARRAY[
                'companionPattern', 'partnerEvidence', 'exclusionContext',
                'confidence', 'evidenceSourceSelectionIds'
           ])
           OR v_assessment - ARRAY[
                'companionPattern', 'partnerEvidence', 'exclusionContext',
                'confidence', 'evidenceSourceSelectionIds'
           ] <> '{}'::JSONB
           OR v_assessment->>'companionPattern' NOT IN (
                'none', 'single_two_person', 'repeated_same_person',
                'explicit_couple_context', 'uncertain'
           )
           OR v_assessment->>'partnerEvidence' NOT IN (
                'none', 'weak', 'strong', 'uncertain'
           )
           OR v_assessment->>'exclusionContext' NOT IN (
                'none', 'celebrity_or_public_figure', 'older_relative', 'group_or_unclear'
           )
           OR v_assessment->>'confidence' NOT IN ('low', 'medium', 'high')
           OR pg_catalog.jsonb_typeof(
                v_assessment->'evidenceSourceSelectionIds'
              ) <> 'array'
           OR pg_catalog.jsonb_array_length(
                v_assessment->'evidenceSourceSelectionIds'
              ) > 8
           OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_array_elements(
                    v_assessment->'evidenceSourceSelectionIds'
                ) AS evidence(value)
                WHERE pg_catalog.jsonb_typeof(evidence.value) <> 'string'
                   OR evidence.value #>> '{}' !~ '^[^[:cntrl:]]{1,240}$'
           )
           OR (
                (
                    v_assessment->>'companionPattern' <> 'none'
                    OR v_assessment->>'partnerEvidence' <> 'none'
                    OR v_assessment->>'exclusionContext' <> 'none'
                )
                <> (
                    pg_catalog.jsonb_array_length(
                        v_assessment->'evidenceSourceSelectionIds'
                    ) > 0
                )
           )
           OR (
                v_assessment->>'exclusionContext' <> 'none'
                AND v_assessment->>'partnerEvidence' <> 'none'
           )
           OR (
                v_assessment->>'partnerEvidence' = 'strong'
                AND (
                    v_assessment->>'confidence' <> 'high'
                    OR v_assessment->>'companionPattern' NOT IN (
                        'repeated_same_person', 'explicit_couple_context'
                    )
                )
           )
           OR (
                v_assessment->>'partnerEvidence' = 'weak'
                AND v_assessment->>'companionPattern' NOT IN (
                    'single_two_person', 'repeated_same_person', 'explicit_couple_context'
                )
           ) THEN
            RETURN FALSE;
        END IF;

        v_expected_partner_bundle_id := 'bundle:' || pg_catalog.encode(
            extensions.digest(
                pg_catalog.convert_to(
                    'analysis-v2-partner-safety-bundle:v1' || pg_catalog.chr(10)
                        || (p_value->>'candidateId'),
                    'UTF8'
                ),
                'sha256'
            ),
            'hex'
        );
        IF p_value->>'bundleId' IS DISTINCT FROM v_expected_partner_bundle_id
           OR NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_media_artifacts AS artifact
                WHERE artifact.request_id = p_request_id
                  AND artifact.registration_job_key = p_partner_job_key
                  AND artifact.artifact_kind = 'media_bundle'
                  AND artifact.deleted_at IS NULL
                  AND artifact.artifact_key = pg_catalog.encode(
                      extensions.digest(
                          pg_catalog.convert_to(
                              'analysis-v2-media-bundle-key:v1' || pg_catalog.chr(10)
                                  || v_expected_partner_bundle_id,
                              'UTF8'
                          ),
                          'sha256'
                      ),
                      'hex'
                  )
           ) THEN
            RETURN FALSE;
        END IF;

        v_contact_strong := v_assessment->>'exclusionContext' = 'none'
            AND v_assessment->>'partnerEvidence' = 'strong';
        v_contact_weak := v_assessment->>'exclusionContext' = 'none'
            AND v_assessment->>'partnerEvidence' = 'weak';
        IF v_contact_strong OR v_contact_weak THEN
            SELECT COALESCE(
                pg_catalog.array_agg(evidence.value ORDER BY evidence.ordinality),
                '{}'::TEXT[]
            )
            INTO v_contact_evidence
            FROM pg_catalog.jsonb_array_elements_text(
                v_assessment->'evidenceSourceSelectionIds'
            ) WITH ORDINALITY AS evidence(value, ordinality);
        END IF;
    ELSIF v_source = 'safe_fallback' THEN
        v_expected_partner_bundle_id := 'bundle:' || pg_catalog.encode(
            extensions.digest(
                pg_catalog.convert_to(
                    'analysis-v2-partner-safety-bundle:v1' || pg_catalog.chr(10)
                        || (p_value->>'candidateId'),
                    'UTF8'
                ),
                'sha256'
            ),
            'hex'
        );
        IF p_value->>'bundleId' IS DISTINCT FROM v_expected_partner_bundle_id
           OR p_value->>'operationKey' !~ '^partner-safety:[a-f0-9]{64}$'
           OR p_value->'aiResultHash' <> 'null'::JSONB
           OR NOT public.analysis_v2_ai_fallback_evidence_matches(
                p_request_id,
                p_partner_job_key,
                p_value->>'operationKey',
                'partnerSafety'
           )
           OR NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_media_artifacts AS artifact
                WHERE artifact.request_id = p_request_id
                  AND artifact.registration_job_key = p_partner_job_key
                  AND artifact.artifact_kind = 'media_bundle'
                  AND artifact.deleted_at IS NULL
                  AND artifact.artifact_key = pg_catalog.encode(
                      extensions.digest(
                          pg_catalog.convert_to(
                              'analysis-v2-media-bundle-key:v1' || pg_catalog.chr(10)
                                  || v_expected_partner_bundle_id,
                              'UTF8'
                          ),
                          'sha256'
                      ),
                      'hex'
                  )
           ) THEN
            RETURN FALSE;
        END IF;
    ELSIF p_value->'bundleId' <> 'null'::JSONB
       OR p_value->'operationKey' <> 'null'::JSONB
       OR p_value->'aiResultHash' <> 'null'::JSONB THEN
        RETURN FALSE;
    END IF;

    v_expected_strong := v_feature_strong OR v_contact_strong;
    v_expected_weak_raw := v_feature_weak OR v_contact_weak;
    v_expected_weak := v_expected_weak_raw AND NOT v_expected_strong;
    v_expected_basis := CASE
        WHEN v_feature_strong AND v_contact_strong THEN 'both'
        WHEN v_feature_strong THEN 'feature'
        WHEN v_contact_strong THEN 'contact_sheet'
        ELSE 'none'
    END;

    SELECT COALESCE(
        pg_catalog.array_agg(canonical.value ORDER BY canonical.first_ordinal),
        '{}'::TEXT[]
    )
    INTO v_expected_evidence
    FROM (
        SELECT combined.value, MIN(combined.ordinality) AS first_ordinal
        FROM (
            SELECT evidence.value, evidence.ordinality::BIGINT AS ordinality
            FROM pg_catalog.unnest(v_feature_evidence)
                WITH ORDINALITY AS evidence(value, ordinality)
            UNION ALL
            SELECT evidence.value, 1000 + evidence.ordinality::BIGINT AS ordinality
            FROM pg_catalog.unnest(v_contact_evidence)
                WITH ORDINALITY AS evidence(value, ordinality)
        ) AS combined
        GROUP BY combined.value
        ORDER BY MIN(combined.ordinality)
        LIMIT 8
    ) AS canonical;
    SELECT COALESCE(
        pg_catalog.array_agg(evidence.value ORDER BY evidence.ordinality),
        '{}'::TEXT[]
    )
    INTO v_row_evidence
    FROM pg_catalog.jsonb_array_elements_text(p_value->'evidenceSelectionIds')
        WITH ORDINALITY AS evidence(value, ordinality);

    RETURN (p_value->>'hasStrongPartnerEvidence')::BOOLEAN
            IS NOT DISTINCT FROM v_expected_strong
       AND (p_value->>'hasWeakPartnerEvidence')::BOOLEAN
            IS NOT DISTINCT FROM v_expected_weak
       AND p_value->>'strongEvidenceBasis' IS NOT DISTINCT FROM v_expected_basis
       AND v_row_evidence IS NOT DISTINCT FROM v_expected_evidence
       AND public.analysis_v2_result_valid_ref_list(v_row_evidence, 8);
EXCEPTION
    WHEN data_exception THEN
        RETURN FALSE;
END;
$_$;


--
-- Name: analysis_v2_result_staging_hash(text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_result_staging_hash(p_kind text, p_batch integer, p_rows jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT CASE
        WHEN p_kind IS NULL OR p_rows IS NULL THEN NULL
        ELSE pg_catalog.encode(
            extensions.digest(
                pg_catalog.convert_to(
                    pg_catalog.concat_ws(
                        E'\n',
                        'analysis-v2-result-staging:v1',
                        p_kind,
                        COALESCE(p_batch::TEXT, '-'),
                        p_rows::TEXT
                    ),
                    'UTF8'
                ),
                'sha256'
            ),
            'hex'
        )
    END;
$$;


--
-- Name: analysis_v2_result_summary_json(public.analysis_v2_result_summaries); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_result_summary_json(p_summary public.analysis_v2_result_summaries) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'targetInstagramId', p_summary.target_instagram_id,
        'targetFullName', p_summary.target_full_name,
        'targetProfileImageUrl', p_summary.target_profile_image_url,
        'planId', p_summary.plan_id,
        'followers', pg_catalog.jsonb_build_object(
            'declared', p_summary.followers_declared,
            'collected', p_summary.followers_collected,
            'coverageRatio', CASE WHEN p_summary.followers_declared = 0 THEN 1
                ELSE p_summary.followers_collected::DOUBLE PRECISION
                    / p_summary.followers_declared::DOUBLE PRECISION END,
            'meetsCoverageGate', p_summary.followers_declared = 0
                OR p_summary.followers_collected * 100 >= p_summary.followers_declared * 99,
            'exactCountMatch', p_summary.followers_collected = p_summary.followers_declared
        ),
        'following', pg_catalog.jsonb_build_object(
            'declared', p_summary.following_declared,
            'collected', p_summary.following_collected,
            'coverageRatio', CASE WHEN p_summary.following_declared = 0 THEN 1
                ELSE p_summary.following_collected::DOUBLE PRECISION
                    / p_summary.following_declared::DOUBLE PRECISION END,
            'meetsCoverageGate', p_summary.following_declared = 0
                OR p_summary.following_collected * 100 >= p_summary.following_declared * 99,
            'exactCountMatch', p_summary.following_collected = p_summary.following_declared
        ),
        'detectedMutuals', p_summary.detected_mutuals,
        'publicMutuals', p_summary.public_mutuals,
        'privateMutuals', p_summary.private_mutuals,
        'screenedMutuals', p_summary.screened_mutuals,
        'genderStats', pg_catalog.jsonb_build_object(
            'male', p_summary.male_count,
            'female', p_summary.female_count,
            'unknown', p_summary.unknown_count
        ),
        'successfullyScreenedMutuals', p_summary.screened_mutuals
            - p_summary.fetch_unavailable_count - p_summary.media_unavailable_count
            - p_summary.analysis_unavailable_count,
        'fetchUnavailableMutuals', p_summary.fetch_unavailable_count,
        'mediaUnavailableMutuals', p_summary.media_unavailable_count,
        'analysisUnavailableMutuals', p_summary.analysis_unavailable_count,
        'notScreenedMutuals', p_summary.not_screened_mutuals,
        'exclusionApplied', p_summary.exclusion_applied,
        'scorePolicyVersion', p_summary.score_policy_version
    );
$$;


--
-- Name: analysis_v2_result_valid_media_context(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_result_valid_media_context(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
    v_selection_ids TEXT[];
    v_triage_ids TEXT[];
    v_feature_ids TEXT[];
BEGIN
    IF p_value IS NULL
       OR pg_catalog.jsonb_typeof(p_value) <> 'object'
       OR NOT (p_value ?& ARRAY[
            'bundleId', 'selectionIds', 'triageAnalyzedSelectionIds',
            'featureAnalyzedSelectionIds', 'captions', 'posts'
       ])
       OR p_value - ARRAY[
            'bundleId', 'selectionIds', 'triageAnalyzedSelectionIds',
            'featureAnalyzedSelectionIds', 'captions', 'posts'
       ] <> '{}'::JSONB
       OR p_value->>'bundleId' !~ '^bundle:[a-f0-9]{64}$'
       OR pg_catalog.octet_length(p_value::TEXT) > 131072
       OR pg_catalog.jsonb_typeof(p_value->'selectionIds') <> 'array'
       OR pg_catalog.jsonb_array_length(p_value->'selectionIds') NOT BETWEEN 1 AND 11
       OR pg_catalog.jsonb_typeof(p_value->'triageAnalyzedSelectionIds') <> 'array'
       OR pg_catalog.jsonb_array_length(p_value->'triageAnalyzedSelectionIds') NOT BETWEEN 1 AND 5
       OR pg_catalog.jsonb_typeof(p_value->'featureAnalyzedSelectionIds') <> 'array'
       OR pg_catalog.jsonb_array_length(p_value->'featureAnalyzedSelectionIds') > 11
       OR pg_catalog.jsonb_typeof(p_value->'captions') <> 'array'
       OR pg_catalog.jsonb_array_length(p_value->'captions') > 10
       OR pg_catalog.jsonb_typeof(p_value->'posts') <> 'array'
       OR pg_catalog.jsonb_array_length(p_value->'posts') > 8 THEN
        RETURN FALSE;
    END IF;

    SELECT pg_catalog.array_agg(selection_id.value ORDER BY selection_id.ordinality)
    INTO v_selection_ids
    FROM pg_catalog.jsonb_array_elements_text(p_value->'selectionIds')
        WITH ORDINALITY AS selection_id(value, ordinality);
    SELECT pg_catalog.array_agg(selection_id.value ORDER BY selection_id.ordinality)
    INTO v_triage_ids
    FROM pg_catalog.jsonb_array_elements_text(p_value->'triageAnalyzedSelectionIds')
        WITH ORDINALITY AS selection_id(value, ordinality);
    SELECT COALESCE(
        pg_catalog.array_agg(selection_id.value ORDER BY selection_id.ordinality),
        '{}'::TEXT[]
    )
    INTO v_feature_ids
    FROM pg_catalog.jsonb_array_elements_text(p_value->'featureAnalyzedSelectionIds')
        WITH ORDINALITY AS selection_id(value, ordinality);

    IF EXISTS (
        SELECT 1 FROM pg_catalog.unnest(v_selection_ids) AS item(value)
        WHERE item.value !~ '^[^[:cntrl:]]{1,240}$'
    ) OR pg_catalog.cardinality(v_selection_ids) <> (
        SELECT pg_catalog.count(DISTINCT item.value)
        FROM pg_catalog.unnest(v_selection_ids) AS item(value)
    ) OR NOT v_triage_ids <@ v_selection_ids
      OR NOT v_feature_ids <@ v_selection_ids
      OR pg_catalog.cardinality(v_triage_ids) <> (
        SELECT pg_catalog.count(DISTINCT item.value)
        FROM pg_catalog.unnest(v_triage_ids) AS item(value)
      ) OR pg_catalog.cardinality(v_feature_ids) <> (
        SELECT pg_catalog.count(DISTINCT item.value)
        FROM pg_catalog.unnest(v_feature_ids) AS item(value)
      ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_value->'captions') AS caption(value)
        WHERE pg_catalog.jsonb_typeof(caption.value) <> 'object'
           OR NOT (caption.value ?& ARRAY['evidenceRefId', 'selectionId', 'text'])
           OR caption.value - ARRAY['evidenceRefId', 'selectionId', 'text'] <> '{}'::JSONB
           OR caption.value->>'evidenceRefId' !~ '^[^[:cntrl:]]{1,240}$'
           OR caption.value->>'selectionId' !~ '^[^[:cntrl:]]{1,240}$'
           OR NOT (caption.value->>'selectionId' = ANY(v_selection_ids))
           OR pg_catalog.jsonb_typeof(caption.value->'text') <> 'string'
           OR pg_catalog.char_length(caption.value->>'text') > 2200
    ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_value->'posts') AS post(value)
        WHERE pg_catalog.jsonb_typeof(post.value) <> 'object'
           OR NOT (post.value ?& ARRAY['postId', 'taggedUsers', 'mentionedUsers'])
           OR post.value - ARRAY['postId', 'taggedUsers', 'mentionedUsers'] <> '{}'::JSONB
           OR post.value->>'postId' !~ '^[^[:cntrl:]]{1,255}$'
           OR pg_catalog.jsonb_typeof(post.value->'taggedUsers') <> 'array'
           OR pg_catalog.jsonb_array_length(post.value->'taggedUsers') > 50
           OR pg_catalog.jsonb_typeof(post.value->'mentionedUsers') <> 'array'
           OR pg_catalog.jsonb_array_length(post.value->'mentionedUsers') > 50
           OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_array_elements_text(
                    post.value->'taggedUsers' || post.value->'mentionedUsers'
                ) AS username(value)
                WHERE username.value !~ '^[a-z0-9._]{1,30}$'
           )
    ) THEN
        RETURN FALSE;
    END IF;
    RETURN TRUE;
EXCEPTION
    WHEN data_exception THEN
        RETURN FALSE;
END;
$_$;


--
-- Name: analysis_v2_result_valid_public_copy(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_result_valid_public_copy(p_value text, p_maximum integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT p_value IS NOT NULL
       AND p_maximum BETWEEN 1 AND 1000
       AND pg_catalog.char_length(p_value) BETWEEN 1 AND p_maximum
       AND pg_catalog.octet_length(p_value) <= p_maximum * 4
       AND p_value ~ '[가-힣]'
       AND p_value !~ '[[:cntrl:]]'
       AND p_value !~* 'https?://|www\.'
       AND p_value !~ '@';
$$;


--
-- Name: analysis_v2_result_valid_ref_list(text[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_result_valid_ref_list(p_values text[], p_maximum integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT p_values IS NOT NULL
       AND p_maximum BETWEEN 0 AND 100
       AND pg_catalog.cardinality(p_values) <= p_maximum
       AND pg_catalog.cardinality(p_values) = (
            SELECT pg_catalog.count(DISTINCT item.value)
            FROM pg_catalog.unnest(p_values) AS item(value)
       )
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.unnest(p_values) AS item(value)
            WHERE item.value !~ '^[^[:cntrl:]]{1,240}$'
       );
$_$;


--
-- Name: analysis_v2_result_valid_score_components(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_result_valid_score_components(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT p_value IS NOT NULL
       AND pg_catalog.jsonb_typeof(p_value) = 'object'
       AND (
            -- The candidate checkpoint fences requests by risk-policy snapshot. Keep this
            -- legacy shape valid only long enough for a v2.3 finalizer to drain.
            (
                p_value ?& ARRAY[
                    'candidateToTargetLikes', 'candidateToTargetComments',
                    'targetToCandidateLike', 'tagOrCaptionMention',
                    'recentMutual', 'appearanceExposure'
                ]
                AND p_value - ARRAY[
                    'candidateToTargetLikes', 'candidateToTargetComments',
                    'targetToCandidateLike', 'tagOrCaptionMention',
                    'recentMutual', 'appearanceExposure'
                ] = '{}'::JSONB
                AND pg_catalog.jsonb_typeof(p_value->'candidateToTargetLikes') = 'number'
                AND (p_value->>'candidateToTargetLikes')::NUMERIC BETWEEN 0 AND 20
                AND pg_catalog.jsonb_typeof(p_value->'candidateToTargetComments') = 'number'
                AND (p_value->>'candidateToTargetComments')::NUMERIC BETWEEN 0 AND 26
                AND pg_catalog.jsonb_typeof(p_value->'targetToCandidateLike') = 'number'
                AND (p_value->>'targetToCandidateLike')::NUMERIC BETWEEN 0 AND 3
                AND pg_catalog.jsonb_typeof(p_value->'tagOrCaptionMention') = 'number'
                AND (p_value->>'tagOrCaptionMention')::NUMERIC BETWEEN 0 AND 14
                AND pg_catalog.jsonb_typeof(p_value->'recentMutual') = 'number'
                AND (p_value->>'recentMutual')::NUMERIC BETWEEN 0 AND 17
                AND pg_catalog.jsonb_typeof(p_value->'appearanceExposure') = 'number'
                AND (p_value->>'appearanceExposure')::NUMERIC BETWEEN 0 AND 20
            )
            OR (
                p_value ?& ARRAY[
                    'candidateToTargetLikes', 'candidateToTargetComments',
                    'candidateToTargetTagOrCaptionMention',
                    'targetToCandidateTagOrCaptionMention',
                    'targetToCandidateLike', 'recentMutual', 'appearanceExposure'
                ]
                AND p_value - ARRAY[
                    'candidateToTargetLikes', 'candidateToTargetComments',
                    'candidateToTargetTagOrCaptionMention',
                    'targetToCandidateTagOrCaptionMention',
                    'targetToCandidateLike', 'recentMutual', 'appearanceExposure'
                ] = '{}'::JSONB
                AND pg_catalog.jsonb_typeof(p_value->'candidateToTargetLikes') = 'number'
                AND (p_value->>'candidateToTargetLikes')::NUMERIC BETWEEN 0 AND 24
                AND pg_catalog.jsonb_typeof(p_value->'candidateToTargetComments') = 'number'
                AND (p_value->>'candidateToTargetComments')::NUMERIC BETWEEN 0 AND 30
                AND pg_catalog.jsonb_typeof(p_value->'candidateToTargetTagOrCaptionMention') = 'number'
                AND (p_value->>'candidateToTargetTagOrCaptionMention')::NUMERIC BETWEEN 0 AND 12
                AND pg_catalog.jsonb_typeof(p_value->'targetToCandidateTagOrCaptionMention') = 'number'
                AND (p_value->>'targetToCandidateTagOrCaptionMention')::NUMERIC BETWEEN 0 AND 8
                AND pg_catalog.jsonb_typeof(p_value->'targetToCandidateLike') = 'number'
                AND (p_value->>'targetToCandidateLike')::NUMERIC BETWEEN 0 AND 5
                AND pg_catalog.jsonb_typeof(p_value->'recentMutual') = 'number'
                AND (p_value->>'recentMutual')::NUMERIC BETWEEN 0 AND 5
                AND pg_catalog.jsonb_typeof(p_value->'appearanceExposure') = 'number'
                AND (p_value->>'appearanceExposure')::NUMERIC BETWEEN 0 AND 16
            )
        );
$$;


--
-- Name: analysis_v2_scheduler_reader_valid_policy_snapshot_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_scheduler_reader_valid_policy_snapshot_v1(p_snapshot jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
    item RECORD;
    item_count INTEGER := 0;
BEGIN
    IF p_snapshot IS NULL
       OR pg_catalog.jsonb_typeof(p_snapshot) <> 'object'
       OR p_snapshot = '{}'::JSONB
       OR pg_catalog.octet_length(p_snapshot::TEXT) > 8192 THEN
        RETURN FALSE;
    END IF;

    IF p_snapshot ? 'scheduler'
       AND p_snapshot->>'scheduler' IS DISTINCT FROM 'ai-scheduler-v1' THEN
        RETURN FALSE;
    END IF;

    FOR item IN SELECT key, value FROM pg_catalog.jsonb_each(p_snapshot) LOOP
        item_count := item_count + 1;
        IF item_count > 16
           OR item.key !~ '^[A-Za-z][A-Za-z0-9._:-]{0,63}$'
           OR pg_catalog.jsonb_typeof(item.value) <> 'string'
           OR pg_catalog.char_length(item.value #>> '{}') < 1
           OR pg_catalog.char_length(item.value #>> '{}') > 128
           OR (item.value #>> '{}') !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$' THEN
            RETURN FALSE;
        END IF;
    END LOOP;
    RETURN TRUE;
END;
$_$;


--
-- Name: analysis_v2_score_audit_expected_v24_components(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_score_audit_expected_v24_components(p_signals jsonb, p_account_context text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'candidateToTargetLikes',
            LEAST((p_signals->>'candidateLikes')::NUMERIC * 6, 24),
        'candidateToTargetComments',
            LEAST((p_signals->>'candidateComments')::NUMERIC * 2.5, 30),
        'candidateToTargetTagOrCaptionMention',
            CASE WHEN (p_signals->>'candidateTagsTarget')::BOOLEAN THEN 12 ELSE 0 END,
        'targetToCandidateTagOrCaptionMention',
            CASE WHEN (p_signals->>'targetTagsCandidate')::BOOLEAN THEN 8 ELSE 0 END,
        'targetToCandidateLike',
            CASE WHEN p_signals->>'targetLikedCandidate' = 'observed' THEN 5 ELSE 0 END,
        'recentMutual',
            (CASE (p_signals->>'recentMutualRank')::INTEGER
                WHEN 1 THEN 5 WHEN 2 THEN 4.5 WHEN 3 THEN 4 WHEN 4 THEN 3.5
                WHEN 5 THEN 3 WHEN 6 THEN 2.5 WHEN 7 THEN 2 WHEN 8 THEN 1.5
                WHEN 9 THEN 1 WHEN 10 THEN 0.5 ELSE 0
            END) * (CASE p_account_context
                WHEN 'individual_creator' THEN 0.5
                WHEN 'official_group_or_brand' THEN 0
                ELSE 1
            END),
        'appearanceExposure',
            LEAST((
                CASE (p_signals->>'appearanceGrade')::INTEGER
                    WHEN 1 THEN 0 WHEN 2 THEN 3 WHEN 3 THEN 7
                    WHEN 4 THEN 10 WHEN 5 THEN 13
                END + (p_signals->>'exposureScore')::NUMERIC
            ) * 16 / 18, 16) * (CASE p_account_context
                WHEN 'individual_creator' THEN 0.5
                WHEN 'official_group_or_brand' THEN 0
                ELSE 1
            END)
    )
$$;


--
-- Name: analysis_v2_score_audit_expected_v25_components(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_score_audit_expected_v25_components(p_signals jsonb, p_account_context text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT public.analysis_v2_score_audit_expected_v24_components(
        p_signals, p_account_context
    );
$$;


--
-- Name: analysis_v2_score_audit_valid_candidate(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_score_audit_valid_candidate(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
BEGIN
    RETURN pg_catalog.jsonb_typeof(p_value) = 'object'
       AND p_value->>'candidateId' ~ '^[A-Za-z0-9._:-]{1,128}$'
       AND p_value->>'username' ~ '^[a-z0-9._]{1,30}$'
       AND p_value->>'accountContext' IN (
            'personal','individual_creator','official_group_or_brand','uncertain'
       )
       AND p_value->>'reverseLikeStatus' IN ('observed','not_observed','not_collected')
       AND pg_catalog.jsonb_typeof(p_value->'uniqueTargetPostsLikedByCandidate') = 'number'
       AND (p_value->>'uniqueTargetPostsLikedByCandidate')::NUMERIC BETWEEN 0 AND 4
       AND pg_catalog.jsonb_typeof(p_value->'boundedCandidateCommentsOnTarget') = 'number'
       AND (p_value->>'boundedCandidateCommentsOnTarget')::NUMERIC BETWEEN 0 AND 12
       AND (p_value->>'boundedCandidateCommentsOnTarget')::NUMERIC
            = pg_catalog.trunc((p_value->>'boundedCandidateCommentsOnTarget')::NUMERIC)
       AND pg_catalog.jsonb_typeof(p_value->'hasCandidateToTargetTagOrCaptionMention') = 'boolean'
       AND pg_catalog.jsonb_typeof(p_value->'hasTargetToCandidateTagOrCaptionMention') = 'boolean'
       AND (p_value->>'uniqueTargetPostsLikedByCandidate')::NUMERIC
            = pg_catalog.trunc((p_value->>'uniqueTargetPostsLikedByCandidate')::NUMERIC)
       AND (p_value->'recentFemaleMutualRank' = 'null'::JSONB
            OR (p_value->>'recentFemaleMutualRank') ~ '^(?:[1-9]|10)$')
       AND pg_catalog.jsonb_typeof(p_value->'appearanceGrade') = 'number'
       AND (p_value->>'appearanceGrade') ~ '^[1-5]$'
       AND pg_catalog.jsonb_typeof(p_value->'exposureScore') = 'number'
       AND (p_value->>'exposureScore')::NUMERIC BETWEEN 0 AND 5
       AND pg_catalog.jsonb_typeof(p_value->'hasWeakPartnerEvidence') = 'boolean'
       AND pg_catalog.jsonb_typeof(p_value->'hasStrongPartnerEvidence') = 'boolean'
       AND NOT (
            (p_value->>'hasWeakPartnerEvidence')::BOOLEAN
            AND (p_value->>'hasStrongPartnerEvidence')::BOOLEAN
       )
       AND pg_catalog.jsonb_typeof(p_value->'relativeTierApplied') = 'boolean'
       AND p_value->>'riskBand' IN ('normal','caution','high_risk')
       AND pg_catalog.jsonb_typeof(p_value->'displayScore') = 'number'
       AND (p_value->>'displayScore')::NUMERIC BETWEEN 1 AND 10
       AND public.analysis_v2_score_audit_valid_components(p_value->'risk'->'components')
       AND p_value->'risk'->>'policyVersion' IN ('risk-policy-v2.4', 'risk-policy-v2.5')
       AND pg_catalog.jsonb_typeof(p_value->'risk'->'preScore') = 'number'
       AND pg_catalog.jsonb_typeof(p_value->'risk'->'rawScore') = 'number'
       AND pg_catalog.jsonb_typeof(p_value->'risk'->'publicScore') = 'number'
       AND pg_catalog.jsonb_typeof(p_value->'risk'->'displayScore') = 'number'
       AND p_value->'risk'->>'riskBand' IN ('normal','caution','high_risk')
       AND (p_value->'risk'->>'weakPartnerAdjustment') ~ '^(?:-5|0)$'
       AND pg_catalog.jsonb_typeof(p_value->'risk'->'partnerCapApplied') = 'boolean'
       AND pg_catalog.jsonb_typeof(p_value->'hasStrongPartnerEvidence') = 'boolean';
EXCEPTION WHEN OTHERS THEN
    RETURN FALSE;
END;
$_$;


--
-- Name: analysis_v2_score_audit_valid_components(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_score_audit_valid_components(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
BEGIN
    RETURN pg_catalog.jsonb_typeof(p_value) = 'object'
       AND p_value ?& ARRAY[
            'candidateToTargetLikes','candidateToTargetComments',
            'candidateToTargetTagOrCaptionMention','targetToCandidateTagOrCaptionMention',
            'targetToCandidateLike','recentMutual','appearanceExposure'
       ]
       AND p_value - ARRAY[
            'candidateToTargetLikes','candidateToTargetComments',
            'candidateToTargetTagOrCaptionMention','targetToCandidateTagOrCaptionMention',
            'targetToCandidateLike','recentMutual','appearanceExposure'
       ] = '{}'::JSONB
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_each(p_value) AS component(key, value)
            WHERE pg_catalog.jsonb_typeof(component.value) <> 'number'
       );
EXCEPTION WHEN OTHERS THEN
    RETURN FALSE;
END;
$$;


--
-- Name: analysis_v2_scrub_terminal_request_pii(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_scrub_terminal_request_pii(p_request_id uuid, p_now timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    UPDATE public.analysis_preflights AS preflight
    SET target_instagram_id = 'retained.'
            || pg_catalog.substr(pg_catalog.replace(preflight.id::TEXT, '-', ''), 1, 20),
        target_full_name = NULL,
        target_bio = NULL,
        target_profile_image_url = NULL,
        exclusion_decision = 'skip',
        excluded_instagram_id = NULL,
        pii_scrubbed_at = COALESCE(preflight.pii_scrubbed_at, p_now),
        updated_at = p_now
    WHERE preflight.consumed_request_id = p_request_id
      AND preflight.status = 'consumed';

    UPDATE public.analysis_requests AS analysis_request
    SET target_instagram_id = 'retained.'
            || pg_catalog.substr(pg_catalog.replace(analysis_request.id::TEXT, '-', ''), 1, 20),
        exclusion_decision_snapshot = 'skip',
        excluded_instagram_id = NULL
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2';
END;
$$;


--
-- Name: analysis_v2_seal_gender_resolution_metrics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_seal_gender_resolution_metrics() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_policy_version TEXT;
    v_outcomes RECORD;
    v_features RECORD;
    v_attempts RECORD;
BEGIN
    PERFORM 1
    FROM public.analysis_v2_ai_attempts AS attempt
    WHERE attempt.request_id = NEW.request_id
      AND attempt.stage = 'genderResolution'
    FOR UPDATE;

    SELECT
        pg_catalog.count(*)::INTEGER AS attempt_count,
        pg_catalog.count(*) FILTER (
            WHERE attempt.status = 'reserved'
        )::INTEGER AS nonterminal_count,
        pg_catalog.count(*) FILTER (
            WHERE attempt.usage_metadata_status = 'complete'
        )::INTEGER AS usage_complete_count,
        pg_catalog.count(*) FILTER (
            WHERE attempt.usage_metadata_status IS DISTINCT FROM 'complete'
        )::INTEGER AS usage_missing_count,
        COALESCE(pg_catalog.sum(attempt.prompt_tokens), 0)::BIGINT
            AS prompt_tokens,
        COALESCE(pg_catalog.sum(attempt.completion_tokens), 0)::BIGINT
            AS completion_tokens,
        COALESCE(pg_catalog.sum(attempt.total_tokens), 0)::BIGINT
            AS total_tokens,
        COALESCE(pg_catalog.sum(attempt.thinking_tokens), 0)::BIGINT
            AS thinking_tokens,
        pg_catalog.sum(attempt.estimated_cost_usd)::NUMERIC(18, 12)
            AS estimated_cost_usd,
        pg_catalog.count(attempt.estimated_cost_usd)::INTEGER
            AS cost_known_count
    INTO v_attempts
    FROM public.analysis_v2_ai_attempts AS attempt
    WHERE attempt.request_id = NEW.request_id
      AND attempt.stage = 'genderResolution';

    IF v_attempts.nonterminal_count <> 0 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    WITH outcomes AS (
        SELECT outcome.value
        FROM public.analysis_v2_ai_scoring_stage_checkpoints AS checkpoint
        CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
            checkpoint.payload->'outcomes'
        ) AS outcome(value)
        WHERE checkpoint.request_id = NEW.request_id
          AND checkpoint.stage_kind = 'profile_ai_batch'
    )
    SELECT
        pg_catalog.count(*)::INTEGER AS outcome_count,
        pg_catalog.count(*) FILTER (
            WHERE pg_catalog.jsonb_array_length(
                    outcome.value->'mediaCoverage'->'failures'
                ) > 0
              AND pg_catalog.jsonb_array_length(
                    outcome.value->'mediaCoverage'->'failures'
                ) * 5
                    <= (outcome.value->'mediaCoverage'->>'selectedCount')::INTEGER
        )::INTEGER AS partial_media_accepted_candidate_count,
        COALESCE(pg_catalog.sum(
            (outcome.value->'mediaCoverage'->>'selectedCount')::INTEGER
        ), 0)::INTEGER AS selected_media_total,
        COALESCE(pg_catalog.sum(
            (outcome.value->'mediaCoverage'->>'normalizedCount')::INTEGER
        ), 0)::INTEGER AS normalized_media_total
    INTO v_outcomes
    FROM outcomes AS outcome;

    SELECT
        pg_catalog.count(*)::INTEGER AS screened_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status
                NOT IN ('disabled', 'not_eligible')
        )::INTEGER AS resolver_eligible_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.baseline_classification
                NOT IN ('verified_female', 'verified_non_female')
        )::INTEGER AS baseline_unknown_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.terminal_classification
                NOT IN ('verified_female', 'verified_non_female')
        )::INTEGER AS final_unknown_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status IN (
                'ready_applied', 'ready_not_needed', 'ready_inconclusive'
            )
        )::INTEGER AS ready_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status = 'ready_applied'
        )::INTEGER AS applied_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status = 'ready_applied'
              AND feature.classification_source = 'gender_resolution'
              AND feature.gender_resolution_operation_key
                    ~ '^gender-resolution:[a-f0-9]{64}$'
              AND feature.gender_resolution_result_hash ~ '^[a-f0-9]{64}$'
        )::INTEGER AS applied_with_fenced_result_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.baseline_classification IN (
                    'verified_female', 'verified_non_female'
                )
              AND feature.terminal_classification
                    IS DISTINCT FROM feature.baseline_classification
        )::INTEGER AS verified_baseline_mutation_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status = 'ready_inconclusive'
        )::INTEGER AS inconclusive_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status = 'cutoff'
        )::INTEGER AS cutoff_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status = 'capacity_skipped'
        )::INTEGER AS capacity_skipped_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status = 'terminal_unavailable'
        )::INTEGER AS terminal_unavailable_count
    INTO v_features
    FROM public.analysis_v2_candidate_feature_rows AS feature
    WHERE feature.request_id = NEW.request_id;

    IF v_features.screened_count <> v_outcomes.outcome_count THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    v_policy_version :=
        public.load_analysis_v2_ai_stage_policy_version(NEW.request_id);

    INSERT INTO public.analysis_v2_gender_resolution_metrics (
        request_id,
        policy_version,
        screened_count,
        resolver_eligible_count,
        baseline_unknown_count,
        final_unknown_count,
        ready_count,
        applied_count,
        applied_with_fenced_result_count,
        verified_baseline_mutation_count,
        inconclusive_count,
        cutoff_count,
        capacity_skipped_count,
        terminal_unavailable_count,
        partial_media_accepted_candidate_count,
        selected_media_total,
        normalized_media_total,
        failed_media_total,
        resolver_attempt_count,
        resolver_usage_complete_count,
        resolver_usage_missing_count,
        resolver_prompt_tokens,
        resolver_completion_tokens,
        resolver_total_tokens,
        resolver_thinking_tokens,
        resolver_estimated_cost_usd,
        resolver_cost_known_count,
        resolver_nonterminal_attempt_count,
        metrics_finalized_at
    ) VALUES (
        NEW.request_id,
        v_policy_version,
        v_features.screened_count,
        v_features.resolver_eligible_count,
        v_features.baseline_unknown_count,
        v_features.final_unknown_count,
        v_features.ready_count,
        v_features.applied_count,
        v_features.applied_with_fenced_result_count,
        v_features.verified_baseline_mutation_count,
        v_features.inconclusive_count,
        v_features.cutoff_count,
        v_features.capacity_skipped_count,
        v_features.terminal_unavailable_count,
        v_outcomes.partial_media_accepted_candidate_count,
        v_outcomes.selected_media_total,
        v_outcomes.normalized_media_total,
        v_outcomes.selected_media_total - v_outcomes.normalized_media_total,
        v_attempts.attempt_count,
        v_attempts.usage_complete_count,
        v_attempts.usage_missing_count,
        v_attempts.prompt_tokens,
        v_attempts.completion_tokens,
        v_attempts.total_tokens,
        v_attempts.thinking_tokens,
        v_attempts.estimated_cost_usd,
        v_attempts.cost_known_count,
        0,
        pg_catalog.clock_timestamp()
    )
    ON CONFLICT (request_id) DO UPDATE
    SET policy_version = EXCLUDED.policy_version,
        screened_count = EXCLUDED.screened_count,
        resolver_eligible_count = EXCLUDED.resolver_eligible_count,
        baseline_unknown_count = EXCLUDED.baseline_unknown_count,
        final_unknown_count = EXCLUDED.final_unknown_count,
        ready_count = EXCLUDED.ready_count,
        applied_count = EXCLUDED.applied_count,
        applied_with_fenced_result_count =
            EXCLUDED.applied_with_fenced_result_count,
        verified_baseline_mutation_count =
            EXCLUDED.verified_baseline_mutation_count,
        inconclusive_count = EXCLUDED.inconclusive_count,
        cutoff_count = EXCLUDED.cutoff_count,
        capacity_skipped_count = EXCLUDED.capacity_skipped_count,
        terminal_unavailable_count = EXCLUDED.terminal_unavailable_count,
        partial_media_accepted_candidate_count =
            EXCLUDED.partial_media_accepted_candidate_count,
        selected_media_total = EXCLUDED.selected_media_total,
        normalized_media_total = EXCLUDED.normalized_media_total,
        failed_media_total = EXCLUDED.failed_media_total,
        resolver_attempt_count = EXCLUDED.resolver_attempt_count,
        resolver_usage_complete_count = EXCLUDED.resolver_usage_complete_count,
        resolver_usage_missing_count = EXCLUDED.resolver_usage_missing_count,
        resolver_prompt_tokens = EXCLUDED.resolver_prompt_tokens,
        resolver_completion_tokens = EXCLUDED.resolver_completion_tokens,
        resolver_total_tokens = EXCLUDED.resolver_total_tokens,
        resolver_thinking_tokens = EXCLUDED.resolver_thinking_tokens,
        resolver_estimated_cost_usd = EXCLUDED.resolver_estimated_cost_usd,
        resolver_cost_known_count = EXCLUDED.resolver_cost_known_count,
        resolver_nonterminal_attempt_count = 0,
        metrics_finalized_at = EXCLUDED.metrics_finalized_at,
        updated_at = pg_catalog.clock_timestamp();

    RETURN NEW;
END;
$_$;


--
-- Name: analysis_v2_selfhosted_auth_run_json(public.analysis_v2_selfhosted_auth_runs); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_selfhosted_auth_run_json(p_receipt public.analysis_v2_selfhosted_auth_runs) RETURNS jsonb
    LANGUAGE sql STABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'schemaVersion', 1,
        'provider', 'selfhosted_auth',
        'operationKey', p_receipt.operation_key,
        'inputHash', p_receipt.input_hash,
        'runId', p_receipt.run_id,
        'accountSlot', p_receipt.account_slot,
        'items', p_receipt.items
    );
$$;


--
-- Name: analysis_v2_set_feature_unavailable_reason(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_set_feature_unavailable_reason() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
    v_fetch_status TEXT;
BEGIN
    IF NEW.terminal_classification <> 'unavailable' THEN
        NEW.unavailable_reason := NULL;
        RETURN NEW;
    END IF;

    SELECT outcome.status INTO v_fetch_status
    FROM public.analysis_v2_profile_fetch_batches AS profile_batch
    JOIN public.analysis_v2_profile_fetch_outcomes AS outcome
      ON outcome.request_id = profile_batch.request_id
     AND outcome.job_key = profile_batch.job_key
     AND outcome.username = NEW.instagram_id
     AND outcome.attempt = public.analysis_v2_profile_terminal_attempt(
            profile_batch.request_id,
            profile_batch.job_key,
            NEW.instagram_id,
            profile_batch.frozen_unresolved_usernames
     )
    WHERE profile_batch.request_id = NEW.request_id
      AND profile_batch.job_key = 'track:profiles:batch:' || NEW.batch::TEXT;

    IF v_fetch_status IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    NEW.unavailable_reason := CASE
        WHEN v_fetch_status = 'success' THEN 'ai_response'
        ELSE 'profile_fetch'
    END;
    RETURN NEW;
END;
$$;


--
-- Name: analysis_v2_set_job_recovery_schedule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_set_job_recovery_schedule() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    IF TG_OP = 'UPDATE'
       AND NEW.status IS NOT DISTINCT FROM OLD.status
       AND NEW.dispatch_state IS NOT DISTINCT FROM OLD.dispatch_state
       AND NEW.dispatch_generation IS NOT DISTINCT FROM OLD.dispatch_generation
       AND NEW.dispatch_reservation_token
            IS NOT DISTINCT FROM OLD.dispatch_reservation_token
       AND NEW.dispatch_reserved_at IS NOT DISTINCT FROM OLD.dispatch_reserved_at
       AND NEW.lease_expires_at IS NOT DISTINCT FROM OLD.lease_expires_at
       AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at
       AND NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at THEN
        RETURN NEW;
    END IF;

    NEW.recovery_checked_at := NULL;
    NEW.recovery_not_before := CASE
        WHEN NEW.status = 'pending' AND NEW.dispatch_state = 'pending'
            THEN NEW.created_at
        WHEN NEW.status = 'pending' AND NEW.dispatch_state = 'reserved'
            THEN NEW.dispatch_reserved_at
        WHEN NEW.status = 'pending'
             AND NEW.dispatch_state IN ('enqueued', 'delivered')
            THEN NEW.updated_at + INTERVAL '2 minutes'
        WHEN NEW.status = 'processing'
            THEN NEW.lease_expires_at
        ELSE NULL
    END;
    RETURN NEW;
END;
$$;


--
-- Name: analysis_v2_sync_cost_attributions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_sync_cost_attributions(p_preflight_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_request_id UUID;
    v_order_id UUID;
    v_inserted INTEGER := 0;
BEGIN
    IF p_preflight_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_COST_ATTRIBUTION_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.consumed_request_id
      INTO v_request_id
      FROM public.analysis_preflights AS preflight
     WHERE preflight.id = p_preflight_id
       AND preflight.status = 'consumed'
       AND preflight.consumed_request_id IS NOT NULL;
    IF v_request_id IS NULL THEN
        RETURN 0;
    END IF;

    SELECT earlybird_order.id
      INTO v_order_id
      FROM public.earlybird_orders AS earlybird_order
     WHERE earlybird_order.preflight_id = p_preflight_id
       AND (
            earlybird_order.result_request_id IS NULL
            OR earlybird_order.result_request_id = v_request_id
       )
     ORDER BY earlybird_order.id
     LIMIT 1;

    INSERT INTO public.analysis_v2_cost_attributions (
        request_id,
        preflight_id,
        order_id,
        source_kind,
        source_operation_key,
        source_identity_hash
    )
    SELECT
        v_request_id,
        provider_run.preflight_id,
        v_order_id,
        'preflight_provider_run',
        provider_run.operation_key,
        pg_catalog.encode(
            extensions.digest(
                pg_catalog.convert_to(
                    'analysis-v2-cost-source:v1' || pg_catalog.chr(10)
                    || provider_run.preflight_id::TEXT || pg_catalog.chr(10)
                    || provider_run.operation_key,
                    'UTF8'
                ),
                'sha256'
            ),
            'hex'
        )
      FROM public.analysis_preflight_provider_runs AS provider_run
     WHERE provider_run.preflight_id = p_preflight_id
    ON CONFLICT (request_id, source_kind, source_operation_key) DO UPDATE
       SET order_id = COALESCE(
            public.analysis_v2_cost_attributions.order_id,
            EXCLUDED.order_id
       ),
           updated_at = CASE
               WHEN public.analysis_v2_cost_attributions.order_id IS NULL
                    AND EXCLUDED.order_id IS NOT NULL
                   THEN pg_catalog.clock_timestamp()
               ELSE public.analysis_v2_cost_attributions.updated_at
           END
     WHERE public.analysis_v2_cost_attributions.order_id IS NULL
       AND EXCLUDED.order_id IS NOT NULL;

    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    RETURN v_inserted;
END;
$$;


--
-- Name: analysis_v2_valid_target_evidence_source(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_target_evidence_source(p_signal text, p_source jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT public.analysis_v2_valid_paid_target_evidence_source(p_signal, p_source)
       OR (
            p_source->>'provider' = 'selfhosted_auth'
            AND p_source->>'provider_credential_slot' = 'primary'
            AND public.analysis_v2_valid_paid_target_evidence_source(
                p_signal,
                pg_catalog.jsonb_set(p_source, '{provider}', '"apify"'::JSONB)
            )
       );
$$;


--
-- Name: analysis_v2_target_evidence_manifests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_target_evidence_manifests (
    request_id uuid NOT NULL,
    job_key character varying(160) NOT NULL,
    job_claim_token uuid NOT NULL,
    target_username character varying(30) NOT NULL,
    excluded_username character varying(30),
    input_hash character varying(64) NOT NULL,
    liker_source jsonb NOT NULL,
    comment_source jsonb NOT NULL,
    liker_source_hash character varying(64) NOT NULL,
    comment_source_hash character varying(64) NOT NULL,
    result_hash character varying(64) NOT NULL,
    interactor_count smallint NOT NULL,
    liker_count smallint NOT NULL,
    comment_count smallint NOT NULL,
    revision smallint DEFAULT 1 NOT NULL,
    frozen_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_v2_target_evidence_manifest_count_check CHECK ((((interactor_count >= 0) AND (interactor_count <= 690)) AND ((liker_count >= 0) AND (liker_count <= 600)) AND ((comment_count >= 0) AND (comment_count <= 90)) AND ((liker_count + comment_count) = interactor_count))),
    CONSTRAINT analysis_v2_target_evidence_manifest_hash_check CHECK ((((input_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((liker_source_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((comment_source_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((result_hash)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT analysis_v2_target_evidence_manifest_revision_check CHECK ((revision = 1)),
    CONSTRAINT analysis_v2_target_evidence_manifest_source_check CHECK ((public.analysis_v2_valid_target_evidence_source('target_post_like'::text, liker_source) AND public.analysis_v2_valid_target_evidence_source('target_post_comment'::text, comment_source))),
    CONSTRAINT analysis_v2_target_evidence_manifest_timestamp_check CHECK (((frozen_at >= created_at) AND (updated_at >= created_at))),
    CONSTRAINT analysis_v2_target_evidence_manifest_username_check CHECK ((((target_username)::text ~ '^[a-z0-9._]{1,30}$'::text) AND ((excluded_username IS NULL) OR (((excluded_username)::text ~ '^[a-z0-9._]{1,30}$'::text) AND ((excluded_username)::text <> (target_username)::text)))))
);

ALTER TABLE ONLY public.analysis_v2_target_evidence_manifests FORCE ROW LEVEL SECURITY;


--
-- Name: analysis_v2_target_evidence_manifest_json(public.analysis_v2_target_evidence_manifests); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_target_evidence_manifest_json(p_manifest public.analysis_v2_target_evidence_manifests) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'revision', p_manifest.revision,
        'resultHash', p_manifest.result_hash,
        'inputHash', p_manifest.input_hash,
        'interactorCount', p_manifest.interactor_count,
        'likerCount', p_manifest.liker_count,
        'commentCount', p_manifest.comment_count
    );
$$;


--
-- Name: analysis_v2_target_evidence_result_hash(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_target_evidence_result_hash(p_rows jsonb, p_liker_source jsonb, p_comment_source jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'analysis-v2-target-evidence-result-v2'
                    || pg_catalog.chr(10)
                    || public.analysis_v2_target_evidence_rows_hash(p_rows)
                    || pg_catalog.chr(10)
                    || public.analysis_v2_target_evidence_source_hash(
                        'target_post_like', p_liker_source
                    )
                    || pg_catalog.chr(10)
                    || public.analysis_v2_target_evidence_source_hash(
                        'target_post_comment', p_comment_source
                    ),
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );
$$;


--
-- Name: analysis_v2_target_evidence_rows_hash(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_target_evidence_rows_hash(p_rows jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'analysis-v2-target-evidence-rows-v2'
                    || pg_catalog.chr(10)
                    || COALESCE((
                        SELECT pg_catalog.string_agg(
                            evidence.ordinal::TEXT
                                || '|'
                                || (evidence.value->>'signal')
                                || '|'
                                || pg_catalog.octet_length(evidence.value->>'post_id')::TEXT
                                || ':' || (evidence.value->>'post_id')
                                || '|'
                                || pg_catalog.octet_length(
                                    evidence.value->>'source_interaction_id'
                                )::TEXT
                                || ':' || (evidence.value->>'source_interaction_id')
                                || '|'
                                || pg_catalog.octet_length(
                                    evidence.value->>'actor_username'
                                )::TEXT
                                || ':' || (evidence.value->>'actor_username')
                                || '|'
                                || pg_catalog.octet_length(
                                    COALESCE(evidence.value->>'occurred_at', '')
                                )::TEXT
                                || ':' || COALESCE(evidence.value->>'occurred_at', '')
                                || '|'
                                || pg_catalog.octet_length(
                                    COALESCE(evidence.value->>'content', '')
                                )::TEXT
                                || ':' || COALESCE(evidence.value->>'content', ''),
                            pg_catalog.chr(10)
                            ORDER BY evidence.ordinal
                        )
                        FROM pg_catalog.jsonb_array_elements(p_rows)
                            WITH ORDINALITY AS evidence(value, ordinal)
                    ), ''),
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );
$$;


--
-- Name: analysis_v2_target_evidence_source_hash(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_target_evidence_source_hash(p_signal text, p_source jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'analysis-v2-target-evidence-source-v1'
                    || pg_catalog.chr(10) || p_signal
                    || pg_catalog.chr(10) || (p_source->>'status')
                    || pg_catalog.chr(10) || (p_source->>'input_hash')
                    || pg_catalog.chr(10)
                    || pg_catalog.octet_length(COALESCE(p_source->>'provider', ''))::TEXT
                    || ':' || COALESCE(p_source->>'provider', '')
                    || pg_catalog.chr(10)
                    || pg_catalog.octet_length(
                        COALESCE(p_source->>'provider_run_id', '')
                    )::TEXT
                    || ':' || COALESCE(p_source->>'provider_run_id', '')
                    || pg_catalog.chr(10)
                    || pg_catalog.octet_length(
                        COALESCE(p_source->>'provider_operation_key', '')
                    )::TEXT
                    || ':' || COALESCE(p_source->>'provider_operation_key', '')
                    || pg_catalog.chr(10)
                    || pg_catalog.octet_length(
                        COALESCE(p_source->>'provider_credential_slot', '')
                    )::TEXT
                    || ':' || COALESCE(p_source->>'provider_credential_slot', '')
                    || CASE
                        WHEN pg_catalog.jsonb_array_length(p_source->'coverage') = 0 THEN ''
                        ELSE pg_catalog.chr(10) || (
                            SELECT pg_catalog.string_agg(
                                coverage.ordinal::TEXT
                                    || '|'
                                    || pg_catalog.octet_length(
                                        coverage.value->>'post_id'
                                    )::TEXT
                                    || ':' || (coverage.value->>'post_id')
                                    || '|' || (coverage.value->>'declared_count')
                                    || '|' || (coverage.value->>'returned_count')
                                    || '|' || (coverage.value->>'requested_limit'),
                                pg_catalog.chr(10)
                                ORDER BY coverage.ordinal
                            )
                            FROM pg_catalog.jsonb_array_elements(p_source->'coverage')
                                WITH ORDINALITY AS coverage(value, ordinal)
                        )
                    END,
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );
$$;


--
-- Name: analysis_v2_target_evidence_source_json(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_target_evidence_source_json(p_source jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'status', p_source->>'status',
        'inputHash', p_source->>'input_hash',
        'provider', p_source->'provider',
        'providerRunId', p_source->'provider_run_id',
        'providerOperationKey', p_source->'provider_operation_key',
        'providerCredentialSlot', p_source->'provider_credential_slot',
        'coverage', COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'postId', coverage.value->>'post_id',
                    'declaredCount', (coverage.value->>'declared_count')::INTEGER,
                    'returnedCount', (coverage.value->>'returned_count')::INTEGER,
                    'requestedLimit', (coverage.value->>'requested_limit')::INTEGER
                ) ORDER BY coverage.ordinal
            )
            FROM pg_catalog.jsonb_array_elements(p_source->'coverage')
                WITH ORDINALITY AS coverage(value, ordinal)
        ), '[]'::JSONB)
    );
$$;


--
-- Name: analysis_v2_terminalize_ai_attempt_internal(uuid, text, uuid, text, smallint, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_terminalize_ai_attempt_internal(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_attempt smallint, p_reservation_token uuid, p_status text, p_telemetry jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_existing public.analysis_v2_ai_attempts%ROWTYPE;
    v_payload_hash TEXT;
    v_terminalized_at TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_reservation_token IS NULL
       OR p_operation_key IS NULL
       OR p_attempt IS NULL
       OR p_telemetry IS NULL
       OR p_status IS NULL
       OR p_status NOT IN ('success', 'rate_limited', 'ambiguous', 'rejected', 'response_rejected', 'cutoff')
       OR NOT public.analysis_v2_valid_ai_operation_key(p_operation_key)
       OR NOT public.analysis_v2_valid_ai_terminal_telemetry(p_telemetry, p_attempt)
       OR NOT public.analysis_v2_ai_operation_matches_stage(
            p_operation_key,
            p_telemetry->>'stage'
       )
       OR (
            p_status IN ('rate_limited', 'ambiguous')
            AND (
                p_telemetry->>'usage_metadata_status' <> 'missing'
                OR (p_telemetry->>'usage_complete')::BOOLEAN
                OR p_telemetry->'finish_reason' <> 'null'::JSONB
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND OR v_request.pipeline_version IS DISTINCT FROM 'v2' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT ai_attempt.*
    INTO v_existing
    FROM public.analysis_v2_ai_attempts AS ai_attempt
    WHERE ai_attempt.request_id = p_request_id
      AND ai_attempt.operation_key = p_operation_key
      AND ai_attempt.attempt = p_attempt
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_NOT_READY',
            ERRCODE = 'P0001';
    END IF;
    IF v_existing.job_key IS DISTINCT FROM p_job_key
       OR v_existing.job_claim_token IS DISTINCT FROM p_claim_token
       OR v_existing.reservation_token <> p_reservation_token THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    IF v_existing.model_name IS DISTINCT FROM p_telemetry->>'model_name'
       OR v_existing.location IS DISTINCT FROM p_telemetry->>'location'
       OR v_existing.stage IS DISTINCT FROM p_telemetry->>'stage'
       OR v_existing.thinking_level IS DISTINCT FROM NULLIF(p_telemetry->>'thinking_level', '')
       OR v_existing.media_count IS DISTINCT FROM (p_telemetry->>'media_count')::SMALLINT
       OR v_existing.media_resolution IS DISTINCT FROM NULLIF(p_telemetry->>'media_resolution', '')
       OR v_existing.prompt_version IS DISTINCT FROM p_telemetry->>'prompt_version'
       OR v_existing.schema_version IS DISTINCT FROM (p_telemetry->>'schema_version')::SMALLINT
       OR v_existing.max_output_tokens IS DISTINCT FROM
            (p_telemetry->>'max_output_tokens')::INTEGER
       OR v_existing.retry_count IS DISTINCT FROM (p_telemetry->>'retry_count')::SMALLINT THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    v_payload_hash := pg_catalog.encode(
        extensions.digest(
            pg_catalog.jsonb_build_object(
                'status', p_status,
                'telemetry', p_telemetry
            )::TEXT,
            'sha256'
        ),
        'hex'
    );
    IF v_existing.status <> 'reserved' THEN
        IF v_existing.status <> p_status
           OR v_existing.terminal_payload_hash <> v_payload_hash THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_ai_attempt_json(v_existing);
    END IF;

    v_terminalized_at := pg_catalog.clock_timestamp();
    UPDATE public.analysis_v2_ai_attempts AS ai_attempt
    SET status = p_status,
        usage_metadata_status = p_telemetry->>'usage_metadata_status',
        usage_complete = (p_telemetry->>'usage_complete')::BOOLEAN,
        prompt_tokens = CASE
            WHEN p_telemetry->'prompt_tokens' = 'null'::JSONB THEN NULL
            ELSE (p_telemetry->>'prompt_tokens')::INTEGER
        END,
        completion_tokens = CASE
            WHEN p_telemetry->'completion_tokens' = 'null'::JSONB THEN NULL
            ELSE (p_telemetry->>'completion_tokens')::INTEGER
        END,
        total_tokens = CASE
            WHEN p_telemetry->'total_tokens' = 'null'::JSONB THEN NULL
            ELSE (p_telemetry->>'total_tokens')::INTEGER
        END,
        thinking_tokens = CASE
            WHEN p_telemetry->'thinking_tokens' = 'null'::JSONB THEN NULL
            ELSE (p_telemetry->>'thinking_tokens')::INTEGER
        END,
        latency_ms = (p_telemetry->>'latency_ms')::INTEGER,
        estimated_cost_usd = CASE
            WHEN p_telemetry->'estimated_cost_usd' = 'null'::JSONB THEN NULL
            ELSE (p_telemetry->>'estimated_cost_usd')::NUMERIC
        END,
        finish_reason = NULLIF(p_telemetry->>'finish_reason', ''),
        terminal_payload_hash = v_payload_hash,
        terminalized_at = v_terminalized_at,
        updated_at = v_terminalized_at
    WHERE ai_attempt.request_id = p_request_id
      AND ai_attempt.operation_key = p_operation_key
      AND ai_attempt.attempt = p_attempt
      AND ai_attempt.reservation_token = p_reservation_token
      AND ai_attempt.status = 'reserved'
    RETURNING * INTO v_existing;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    RETURN public.analysis_v2_ai_attempt_json(v_existing);
END;
$_$;


--
-- Name: analysis_v2_v211_maintenance_source_fingerprint(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_v211_maintenance_source_fingerprint(p_request_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                pg_catalog.concat_ws(
                    E'\n',
                    'analysis-v2-v211-maintenance-source:v1',
                    request.id::TEXT,
                    result_summary.finalizer_input_hash,
                    request.policy_versions_snapshot::TEXT,
                    COALESCE((
                        SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                            'actorId', provider_run.actor_id,
                            'credentialSlot', provider_run.credential_slot,
                            'runId', provider_run.run_id,
                            'operationKey', provider_run.operation_key,
                            'status', provider_run.status,
                            'usageReconciledAt', provider_run.usage_reconciled_at
                        ) ORDER BY provider_run.job_key, provider_run.operation_key)::TEXT
                        FROM public.analysis_v2_provider_runs AS provider_run
                        WHERE provider_run.request_id = request.id
                    ), '[]'),
                    COALESCE((
                        SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                            'actorId', provider_run.actor_id,
                            'credentialSlot', provider_run.credential_slot,
                            'runId', provider_run.run_id,
                            'operationKey', provider_run.operation_key,
                            'status', provider_run.status,
                            'usageReconciledAt', provider_run.usage_reconciled_at
                        ) ORDER BY provider_run.operation_key)::TEXT
                        FROM public.analysis_preflight_provider_runs AS provider_run
                        WHERE provider_run.preflight_id = request.preflight_id
                    ), '[]')
                ),
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    )
    FROM public.analysis_requests AS request
    JOIN public.analysis_v2_result_summaries AS result_summary
      ON result_summary.request_id = request.id
    WHERE request.id = p_request_id;
$$;


--
-- Name: analysis_v2_v211_safe_overview_fallback(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_v211_safe_overview_fallback(p_sort_ordinal integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT CASE pg_catalog.mod(COALESCE(p_sort_ordinal, 0), 6)
        WHEN 0 THEN '소개와 피드의 장면이 자연스럽게 이어집니다. 계정이 보여주는 일상의 결이 또렷하네요.'
        WHEN 1 THEN '사진마다 취향의 방향이 꾸준히 드러납니다. 가볍게 훑어도 계정의 분위기가 선명합니다.'
        WHEN 2 THEN '일상 기록과 관심사가 자연스럽게 섞여 있습니다. 피드의 흐름이 한 사람의 리듬으로 읽힙니다.'
        WHEN 3 THEN '소개 문구와 사진의 톤이 같은 쪽을 향합니다. 보여주고 싶은 모습이 분명한 계정입니다.'
        WHEN 4 THEN '피드 전반에 취향과 활동의 흔적이 고르게 남아 있습니다. 장면마다 계정의 색이 살아 있습니다.'
        ELSE '사진의 선택과 소개가 자연스럽게 맞물립니다. 일상을 기록하는 방식이 인상적으로 남습니다.'
    END;
$$;


--
-- Name: analysis_v2_v28_safe_overview_fallback(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_v28_safe_overview_fallback(p_sort_ordinal integer) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    v_prefixes CONSTANT TEXT[] := ARRAY[
        '확인된 공개 단서가 제한적이고, ',
        '공개된 소개와 피드만으로는 맥락이 부족하고, ',
        '수집된 공개 범위에서는 정보가 많지 않고, ',
        '현재 보이는 공개 자료에는 빈칸이 남고, ',
        '소개와 피드에서 확인되는 내용이 제한적이고, ',
        '공개 화면에 드러난 단서만으로는 정보가 부족하고, ',
        '확인 가능한 공개 기록의 범위가 좁고, ',
        '지금 확보된 공개 자료에는 설명이 적고, ',
        '공개 프로필과 피드만 보면 단서가 많지 않고, ',
        '확인된 공개 정보 사이에 빈칸이 남고, '
    ];
    v_middles CONSTANT TEXT[] := ARRAY[
        '계정 성격을 더 단정하기 어렵습니다. ',
        '세부 맥락까지 확정하기는 어렵습니다. ',
        '구체적인 배경을 읽어 내기 어렵습니다. ',
        '보이지 않는 사정까지 알 수는 없습니다. ',
        '확실한 특징을 더 붙이기 어렵습니다. ',
        '하나의 성격으로 묶기에는 근거가 부족합니다. ',
        '공개되지 않은 맥락은 판단할 수 없습니다. ',
        '뚜렷한 결론까지 가기에는 근거가 모자랍니다. ',
        '세부적인 해석을 더하기에는 자료가 부족합니다. ',
        '확인되지 않은 이야기를 보탤 수는 없습니다. '
    ];
    v_suffixes CONSTANT TEXT[] := ARRAY[
        '보이는 범위까지만 확인하는 편이 낫겠네요.',
        '빈칸을 추측으로 채울 이유는 없겠네요.',
        '없는 디테일까지 만들어 낼 필요는 없습니다.',
        '확인된 내용만 두고 보는 것이 안전합니다.',
        '공개 자료가 더 생기기 전에는 여기까지입니다.',
        '지금은 확인 가능한 내용만 남기는 편이 낫습니다.',
        '근거가 없는 해석은 붙이지 않는 게 맞겠네요.',
        '현재 자료만으로는 이 정도가 가장 정확합니다.',
        '보이지 않는 부분은 그대로 남겨 두는 게 낫습니다.'
    ];
    v_zero_based INTEGER;
BEGIN
    IF p_sort_ordinal IS NULL OR p_sort_ordinal NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_V28_SAFE_OVERVIEW_INVALID',
            ERRCODE = 'P0001';
    END IF;
    v_zero_based := p_sort_ordinal - 1;
    RETURN
        v_prefixes[1 + (v_zero_based % 10)]
        || v_middles[1 + ((v_zero_based / 10) % 10)]
        || v_suffixes[1 + ((v_zero_based / 100) % 9)];
END;
$$;


--
-- Name: analysis_v2_valid_active_profile_feed_image_urls(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_active_profile_feed_image_urls(p_feed_image_urls text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
    SELECT CASE
        WHEN p_feed_image_urls IS NULL THEN FALSE
        WHEN pg_catalog.cardinality(p_feed_image_urls) = 0 THEN TRUE
        WHEN pg_catalog.array_ndims(p_feed_image_urls) <> 1
          OR pg_catalog.array_lower(p_feed_image_urls, 1) <> 1
          OR pg_catalog.cardinality(p_feed_image_urls) NOT BETWEEN 1 AND 3 THEN FALSE
        WHEN EXISTS (
            SELECT 1
            FROM pg_catalog.unnest(p_feed_image_urls) AS feed(url)
            WHERE url IS NULL
               OR pg_catalog.char_length(url) NOT BETWEEN 1 AND 2048
               OR url NOT LIKE '/api/image-proxy?%'
        ) THEN FALSE
        ELSE (
            SELECT pg_catalog.count(DISTINCT url)
            FROM pg_catalog.unnest(p_feed_image_urls) AS feed(url)
        ) = pg_catalog.cardinality(p_feed_image_urls)
    END;
$$;


--
-- Name: analysis_v2_valid_ai_reservation_metadata(jsonb, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_ai_reservation_metadata(p_metadata jsonb, p_attempt smallint) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
    SELECT pg_catalog.jsonb_typeof(p_metadata) = 'object'
       AND p_attempt BETWEEN 1 AND 4
       AND p_metadata ?& ARRAY[
            'model_name', 'location', 'stage', 'thinking_level', 'media_count',
            'media_resolution', 'prompt_version', 'schema_version', 'max_output_tokens',
            'retry_count'
       ]
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_object_keys(p_metadata) AS metadata_key(value)
            WHERE metadata_key.value <> ALL(ARRAY[
                'model_name', 'location', 'stage', 'thinking_level', 'media_count',
                'media_resolution', 'prompt_version', 'schema_version', 'max_output_tokens',
                'retry_count'
            ])
       )
       AND pg_catalog.jsonb_typeof(p_metadata->'model_name') = 'string'
       AND p_metadata->>'model_name' ~ '^[a-z0-9][a-z0-9._-]{0,99}$'
       AND pg_catalog.jsonb_typeof(p_metadata->'location') = 'string'
       AND p_metadata->>'location' ~ '^[a-z][a-z0-9-]{0,62}$'
       AND pg_catalog.jsonb_typeof(p_metadata->'stage') = 'string'
       AND p_metadata->>'stage' IN (
            'genderTriage', 'genderResolution', 'featureAnalysis',
            'highRiskNarrative', 'privateAccountName', 'partnerSafety'
       )
       AND (
            p_metadata->'thinking_level' = 'null'::JSONB
            OR (
                pg_catalog.jsonb_typeof(p_metadata->'thinking_level') = 'string'
                AND p_metadata->>'thinking_level' IN ('MINIMAL', 'LOW', 'MEDIUM', 'HIGH')
            )
       )
       AND pg_catalog.jsonb_typeof(p_metadata->'media_count') = 'number'
       AND p_metadata->>'media_count' ~ '^(0|[1-9]|10|11)$'
       AND (
            p_metadata->'media_resolution' = 'null'::JSONB
            OR (
                pg_catalog.jsonb_typeof(p_metadata->'media_resolution') = 'string'
                AND p_metadata->>'media_resolution' IN ('LOW', 'MEDIUM', 'HIGH')
            )
       )
       AND pg_catalog.jsonb_typeof(p_metadata->'prompt_version') = 'string'
       AND pg_catalog.char_length(p_metadata->>'prompt_version') BETWEEN 1 AND 64
       AND p_metadata->>'prompt_version' ~ '^[A-Za-z0-9._:-]+$'
       AND pg_catalog.jsonb_typeof(p_metadata->'schema_version') = 'number'
       AND p_metadata->>'schema_version' ~ '^[1-9][0-9]{0,3}$'
       AND (p_metadata->>'schema_version')::INTEGER BETWEEN 1 AND 9999
       AND pg_catalog.jsonb_typeof(p_metadata->'max_output_tokens') = 'number'
       AND p_metadata->>'max_output_tokens' ~ '^[1-9][0-9]{0,4}$'
       AND (p_metadata->>'max_output_tokens')::INTEGER BETWEEN 1 AND 65536
       AND pg_catalog.jsonb_typeof(p_metadata->'retry_count') = 'number'
       AND p_metadata->>'retry_count' ~ '^[0-3]$'
       AND (p_metadata->>'retry_count')::SMALLINT = p_attempt - 1;
$_$;


--
-- Name: analysis_v2_valid_ai_result_identity(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_ai_result_identity(p_identity jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
    SELECT pg_catalog.jsonb_typeof(p_identity) = 'object'
       AND p_identity ?& ARRAY[
            'stage', 'model_name', 'thinking_level', 'media_resolution',
            'prompt_version', 'schema_version', 'input_hash',
            'max_output_tokens', 'media_snapshot_hash', 'cache_scope'
       ]
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_object_keys(p_identity) AS identity_key(value)
            WHERE identity_key.value <> ALL(ARRAY[
                'stage', 'model_name', 'thinking_level', 'media_resolution',
                'prompt_version', 'schema_version', 'input_hash',
                'max_output_tokens', 'media_snapshot_hash', 'cache_scope'
            ])
       )
       AND pg_catalog.jsonb_typeof(p_identity->'stage') = 'string'
       AND p_identity->>'stage' IN (
            'genderTriage', 'genderResolution', 'featureAnalysis',
            'highRiskNarrative', 'privateAccountName', 'partnerSafety'
       )
       AND pg_catalog.jsonb_typeof(p_identity->'model_name') = 'string'
       AND p_identity->>'model_name' ~ '^[a-z0-9][a-z0-9._-]{0,99}$'
       AND (
            p_identity->'thinking_level' = 'null'::JSONB
            OR (
                pg_catalog.jsonb_typeof(p_identity->'thinking_level') = 'string'
                AND p_identity->>'thinking_level' IN ('MINIMAL', 'LOW', 'MEDIUM', 'HIGH')
            )
       )
       AND (
            p_identity->'media_resolution' = 'null'::JSONB
            OR (
                pg_catalog.jsonb_typeof(p_identity->'media_resolution') = 'string'
                AND p_identity->>'media_resolution' IN ('LOW', 'MEDIUM', 'HIGH')
            )
       )
       AND pg_catalog.jsonb_typeof(p_identity->'prompt_version') = 'string'
       AND pg_catalog.char_length(p_identity->>'prompt_version') BETWEEN 1 AND 64
       AND p_identity->>'prompt_version' ~ '^[A-Za-z0-9._:-]+$'
       AND pg_catalog.jsonb_typeof(p_identity->'schema_version') = 'number'
       AND p_identity->>'schema_version' ~ '^[1-9][0-9]{0,3}$'
       AND (p_identity->>'schema_version')::INTEGER BETWEEN 1 AND 9999
       AND pg_catalog.jsonb_typeof(p_identity->'max_output_tokens') = 'number'
       AND p_identity->>'max_output_tokens' ~ '^[1-9][0-9]{0,4}$'
       AND (p_identity->>'max_output_tokens')::INTEGER BETWEEN 1 AND 65536
       AND pg_catalog.jsonb_typeof(p_identity->'input_hash') = 'string'
       AND p_identity->>'input_hash' ~ '^[0-9a-f]{64}$'
       AND pg_catalog.jsonb_typeof(p_identity->'media_snapshot_hash') = 'string'
       AND p_identity->>'media_snapshot_hash' ~ '^[0-9a-f]{64}$'
       AND pg_catalog.jsonb_typeof(p_identity->'cache_scope') = 'string'
       AND p_identity->>'cache_scope' = 'request';
$_$;


--
-- Name: analysis_v2_valid_ai_result_json(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_ai_result_json(p_result jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_typeof(p_result) = 'object'
       AND pg_catalog.octet_length(pg_catalog.convert_to(p_result::TEXT, 'UTF8'))
            BETWEEN 2 AND 262144
       AND (
            SELECT pg_catalog.count(*)
            FROM pg_catalog.jsonb_object_keys(p_result)
       ) <= 256;
$$;


--
-- Name: analysis_v2_valid_ai_terminal_telemetry(jsonb, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_ai_terminal_telemetry(p_telemetry jsonb, p_attempt smallint) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
    SELECT public.analysis_v2_valid_ai_reservation_metadata(
            pg_catalog.jsonb_build_object(
                'model_name', p_telemetry->'model_name',
                'location', p_telemetry->'location',
                'stage', p_telemetry->'stage',
                'thinking_level', p_telemetry->'thinking_level',
                'media_count', p_telemetry->'media_count',
                'media_resolution', p_telemetry->'media_resolution',
                'prompt_version', p_telemetry->'prompt_version',
                'schema_version', p_telemetry->'schema_version',
                'max_output_tokens', p_telemetry->'max_output_tokens',
                'retry_count', p_telemetry->'retry_count'
            ),
            p_attempt
       )
       AND p_telemetry ?& ARRAY[
            'usage_metadata_status', 'usage_complete', 'prompt_tokens',
            'completion_tokens', 'total_tokens', 'thinking_tokens', 'latency_ms',
            'estimated_cost_usd', 'finish_reason'
       ]
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_object_keys(p_telemetry) AS telemetry_key(value)
            WHERE telemetry_key.value <> ALL(ARRAY[
                'model_name', 'location', 'stage', 'thinking_level', 'media_count',
                'media_resolution', 'prompt_version', 'schema_version', 'retry_count',
                'max_output_tokens',
                'usage_metadata_status', 'usage_complete', 'prompt_tokens',
                'completion_tokens', 'total_tokens', 'thinking_tokens', 'latency_ms',
                'estimated_cost_usd', 'finish_reason'
            ])
       )
       AND pg_catalog.jsonb_typeof(p_telemetry->'usage_metadata_status') = 'string'
       AND p_telemetry->>'usage_metadata_status' IN ('complete', 'missing', 'malformed')
       AND pg_catalog.jsonb_typeof(p_telemetry->'usage_complete') = 'boolean'
       AND pg_catalog.jsonb_typeof(p_telemetry->'latency_ms') = 'number'
       AND p_telemetry->>'latency_ms' ~ '^(0|[1-9][0-9]{0,6})$'
       AND (p_telemetry->>'latency_ms')::INTEGER BETWEEN 0 AND 3600000
       AND (
            p_telemetry->'estimated_cost_usd' = 'null'::JSONB
            OR (
                pg_catalog.jsonb_typeof(p_telemetry->'estimated_cost_usd') = 'number'
                AND p_telemetry->>'estimated_cost_usd'
                    ~ '^(0|[1-9][0-9]{0,2})(\.[0-9]{1,12})?$'
                AND (p_telemetry->>'estimated_cost_usd')::NUMERIC
                    BETWEEN 0 AND 999.999999999999
            )
       )
       AND (
            p_telemetry->'finish_reason' = 'null'::JSONB
            OR (
                pg_catalog.jsonb_typeof(p_telemetry->'finish_reason') = 'string'
                AND pg_catalog.char_length(p_telemetry->>'finish_reason') BETWEEN 1 AND 64
                AND p_telemetry->>'finish_reason' ~ '^[A-Za-z0-9_.:-]+$'
            )
       )
       AND (
            (
                p_telemetry->>'usage_metadata_status' = 'complete'
                AND (p_telemetry->>'usage_complete')::BOOLEAN
                AND NOT EXISTS (
                    SELECT 1
                    FROM pg_catalog.unnest(ARRAY[
                        'prompt_tokens', 'completion_tokens', 'total_tokens', 'thinking_tokens'
                    ]) AS token_key(value)
                    WHERE p_telemetry->token_key.value = 'null'::JSONB
                       OR pg_catalog.jsonb_typeof(p_telemetry->token_key.value) <> 'number'
                       OR p_telemetry->>token_key.value !~ '^(0|[1-9][0-9]{0,8})$'
                       OR (p_telemetry->>token_key.value)::NUMERIC > 100000000
                )
                AND (p_telemetry->>'total_tokens')::NUMERIC
                    = (p_telemetry->>'prompt_tokens')::NUMERIC
                    + (p_telemetry->>'completion_tokens')::NUMERIC
                    + (p_telemetry->>'thinking_tokens')::NUMERIC
            )
            OR (
                p_telemetry->>'usage_metadata_status' IN ('missing', 'malformed')
                AND NOT (p_telemetry->>'usage_complete')::BOOLEAN
                AND p_telemetry->'prompt_tokens' = 'null'::JSONB
                AND p_telemetry->'completion_tokens' = 'null'::JSONB
                AND p_telemetry->'total_tokens' = 'null'::JSONB
                AND p_telemetry->'thinking_tokens' = 'null'::JSONB
                AND p_telemetry->'estimated_cost_usd' = 'null'::JSONB
            )
       );
$_$;


--
-- Name: analysis_v2_valid_apify_secret_ref_prune_slots(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_apify_secret_ref_prune_slots(p_slots text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT COALESCE(
        pg_catalog.cardinality(p_slots) BETWEEN 1 AND 5
        AND pg_catalog.cardinality(p_slots) = (
            SELECT pg_catalog.count(DISTINCT requested.slot)
            FROM pg_catalog.unnest(p_slots) AS requested(slot)
        )
        AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.unnest(p_slots) AS requested(slot)
            WHERE requested.slot IS NULL
               OR requested.slot = 'primary'
               OR NOT public.analysis_v2_valid_apify_credential_slot(
                    requested.slot
               )
        ),
        FALSE
    );
$$;


--
-- Name: analysis_v2_valid_iso_timestamp(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_iso_timestamp(p_value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
    v_timestamp TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_value IS NULL
       OR pg_catalog.char_length(p_value) > 64
       OR p_value !~
            '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' THEN
        RETURN FALSE;
    END IF;
    v_timestamp := p_value::TIMESTAMP WITH TIME ZONE;
    RETURN v_timestamp IS NOT NULL;
EXCEPTION
    WHEN datetime_field_overflow OR invalid_datetime_format THEN
        RETURN FALSE;
END;
$_$;


--
-- Name: analysis_v2_valid_launch_snapshot(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_launch_snapshot(p_snapshot jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    plan_id TEXT;
BEGIN
    IF p_snapshot IS NULL
       OR pg_catalog.jsonb_typeof(p_snapshot) <> 'object'
       OR pg_catalog.octet_length(p_snapshot::TEXT) > 2048
       OR NOT (p_snapshot ?& ARRAY['basic', 'standard', 'plus'])
       OR p_snapshot - ARRAY['basic', 'standard', 'plus'] <> '{}'::JSONB THEN
        RETURN FALSE;
    END IF;

    FOREACH plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        IF p_snapshot->>plan_id IS NULL
           OR p_snapshot->>plan_id NOT IN ('production', 'test_only', 'disabled') THEN
            RETURN FALSE;
        END IF;
    END LOOP;
    RETURN TRUE;
END;
$$;


--
-- Name: analysis_v2_valid_paid_target_evidence_source(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_paid_target_evidence_source(p_signal text, p_source jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT p_signal IN ('target_post_like', 'target_post_comment')
       AND p_source IS NOT NULL
       AND pg_catalog.jsonb_typeof(p_source) = 'object'
       AND p_source ?& ARRAY[
            'status', 'input_hash', 'provider', 'provider_run_id',
            'provider_operation_key', 'provider_credential_slot', 'coverage'
       ]
       AND p_source - ARRAY[
            'status', 'input_hash', 'provider', 'provider_run_id',
            'provider_operation_key', 'provider_credential_slot', 'coverage'
       ] = '{}'::JSONB
       AND pg_catalog.jsonb_typeof(p_source->'status') = 'string'
       AND p_source->>'status' IN ('collected', 'not_applicable')
       AND pg_catalog.jsonb_typeof(p_source->'input_hash') = 'string'
       AND p_source->>'input_hash' ~ '^[0-9a-f]{64}$'
       AND pg_catalog.jsonb_typeof(p_source->'coverage') = 'array'
       AND pg_catalog.jsonb_array_length(p_source->'coverage') <= CASE p_signal
            WHEN 'target_post_like' THEN 4 ELSE 6
       END
       AND (
            (
                p_source->>'status' = 'not_applicable'
                AND p_source->'provider' = 'null'::JSONB
                AND p_source->'provider_run_id' = 'null'::JSONB
                AND p_source->'provider_operation_key' = 'null'::JSONB
                AND p_source->'provider_credential_slot' = 'null'::JSONB
                AND pg_catalog.jsonb_array_length(p_source->'coverage') = 0
            )
            OR (
                p_source->>'status' = 'collected'
                AND pg_catalog.jsonb_typeof(p_source->'provider') = 'string'
                AND p_source->>'provider' IN ('apify', 'coderx')
                AND pg_catalog.jsonb_typeof(p_source->'provider_run_id') = 'string'
                AND p_source->>'provider_run_id' ~ '^[A-Za-z0-9]{8,64}$'
                AND pg_catalog.jsonb_typeof(p_source->'provider_operation_key') = 'string'
                AND p_source->>'provider_operation_key' ~ CASE p_signal
                    WHEN 'target_post_like' THEN '^target-likers:[0-9a-f]{64}$'
                    ELSE '^target-comments:[0-9a-f]{64}$'
                END
                AND pg_catalog.jsonb_typeof(p_source->'provider_credential_slot') = 'string'
                AND public.analysis_v2_valid_apify_credential_slot(
                    p_source->>'provider_credential_slot'
                )
                AND pg_catalog.jsonb_array_length(p_source->'coverage') >= 1
            )
       )
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_source->'coverage') AS coverage(value)
            WHERE pg_catalog.jsonb_typeof(coverage.value) <> 'object'
               OR NOT coverage.value ?& ARRAY[
                    'post_id', 'declared_count', 'returned_count', 'requested_limit'
               ]
               OR coverage.value - ARRAY[
                    'post_id', 'declared_count', 'returned_count', 'requested_limit'
               ] <> '{}'::JSONB
               OR pg_catalog.jsonb_typeof(coverage.value->'post_id') <> 'string'
               OR pg_catalog.char_length(coverage.value->>'post_id') NOT BETWEEN 1 AND 255
               OR coverage.value->>'post_id' ~ '[[:cntrl:]]'
               OR pg_catalog.jsonb_typeof(coverage.value->'declared_count') <> 'number'
               OR coverage.value->>'declared_count' !~ '^(0|[1-9][0-9]{0,7})$'
               OR (coverage.value->>'declared_count')::INTEGER > 10000000
               OR pg_catalog.jsonb_typeof(coverage.value->'returned_count') <> 'number'
               OR coverage.value->>'returned_count' !~ '^(0|[1-9][0-9]{0,2})$'
               OR (coverage.value->>'returned_count')::INTEGER > CASE p_signal
                    WHEN 'target_post_like' THEN 150 ELSE 15
               END
               OR pg_catalog.jsonb_typeof(coverage.value->'requested_limit') <> 'number'
               OR coverage.value->>'requested_limit' !~ '^(15|150)$'
               OR (coverage.value->>'requested_limit')::INTEGER <> CASE p_signal
                    WHEN 'target_post_like' THEN 150 ELSE 15
               END
               OR (coverage.value->>'returned_count')::INTEGER
                    > (coverage.value->>'requested_limit')::INTEGER
       )
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_source->'coverage') AS coverage(value)
            GROUP BY coverage.value->>'post_id'
            HAVING pg_catalog.count(*) > 1
       );
$_$;


--
-- Name: analysis_v2_valid_plan_cards_snapshot(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_plan_cards_snapshot(p_snapshot jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
    plan_id TEXT;
    card JSONB;
    capacity JSONB;
    required_count INTEGER := 0;
    selection_state TEXT;
    unavailable_reason TEXT;
BEGIN
    IF p_snapshot IS NULL
       OR pg_catalog.jsonb_typeof(p_snapshot) <> 'object'
       OR pg_catalog.octet_length(p_snapshot::TEXT) > 8192
       OR NOT (p_snapshot ?& ARRAY['basic', 'standard', 'plus'])
       OR p_snapshot - ARRAY['basic', 'standard', 'plus'] <> '{}'::JSONB THEN
        RETURN FALSE;
    END IF;

    FOREACH plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        card := p_snapshot->plan_id;
        IF pg_catalog.jsonb_typeof(card) <> 'object'
           OR NOT (card ?& ARRAY[
               'launchStatus',
               'selectionState',
               'unavailableReason',
               'relationshipCapacity',
               'detailedMutualLimit'
           ])
           OR card - ARRAY[
               'launchStatus',
               'selectionState',
               'unavailableReason',
               'relationshipCapacity',
               'detailedMutualLimit'
           ] <> '{}'::JSONB
           OR card->>'launchStatus' IS NULL
           OR card->>'launchStatus' NOT IN ('production', 'test_only', 'disabled')
           OR card->>'selectionState' IS NULL
           OR card->>'selectionState' NOT IN ('required', 'available_upgrade', 'unavailable')
           OR pg_catalog.jsonb_typeof(card->'detailedMutualLimit') <> 'number'
           OR card->>'detailedMutualLimit' !~ '^[0-9]+$'
           OR (card->>'detailedMutualLimit')::NUMERIC < 1
           OR (card->>'detailedMutualLimit')::NUMERIC > 100000 THEN
            RETURN FALSE;
        END IF;

        capacity := card->'relationshipCapacity';
        IF pg_catalog.jsonb_typeof(capacity) <> 'object'
           OR NOT (capacity ?& ARRAY['followers', 'following'])
           OR capacity - ARRAY['followers', 'following'] <> '{}'::JSONB
           OR pg_catalog.jsonb_typeof(capacity->'followers') <> 'number'
           OR pg_catalog.jsonb_typeof(capacity->'following') <> 'number'
           OR capacity->>'followers' !~ '^[0-9]+$'
           OR capacity->>'following' !~ '^[0-9]+$'
           OR (capacity->>'followers')::NUMERIC > 10000000
           OR (capacity->>'following')::NUMERIC > 10000000 THEN
            RETURN FALSE;
        END IF;

        selection_state := card->>'selectionState';
        unavailable_reason := card->>'unavailableReason';
        IF selection_state = 'unavailable' THEN
            IF unavailable_reason IS NULL
               OR unavailable_reason NOT IN ('below_required_plan', 'launch_gate') THEN
                RETURN FALSE;
            END IF;
        ELSIF card->'unavailableReason' <> 'null'::JSONB THEN
            RETURN FALSE;
        END IF;

        IF selection_state = 'required' THEN
            required_count := required_count + 1;
        END IF;
    END LOOP;

    RETURN required_count = 1;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN FALSE;
END;
$_$;


--
-- Name: analysis_v2_valid_plan_catalog_snapshot(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_plan_catalog_snapshot(p_snapshot jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
    plan_id TEXT;
    plan_definition JSONB;
    capacity JSONB;
    previous_followers INTEGER := 0;
    previous_following INTEGER := 0;
    previous_detailed_limit INTEGER := 0;
BEGIN
    IF p_snapshot IS NULL
       OR pg_catalog.jsonb_typeof(p_snapshot) <> 'object'
       OR pg_catalog.octet_length(p_snapshot::TEXT) > 4096
       OR NOT (p_snapshot ?& ARRAY['basic', 'standard', 'plus'])
       OR p_snapshot - ARRAY['basic', 'standard', 'plus'] <> '{}'::JSONB THEN
        RETURN FALSE;
    END IF;

    FOREACH plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        plan_definition := p_snapshot->plan_id;
        IF pg_catalog.jsonb_typeof(plan_definition) <> 'object'
           OR NOT (plan_definition ?& ARRAY[
               'launchStatus', 'relationshipCapacity', 'detailedMutualLimit'
           ])
           OR plan_definition - ARRAY[
               'launchStatus', 'relationshipCapacity', 'detailedMutualLimit'
           ] <> '{}'::JSONB
           OR plan_definition->>'launchStatus' NOT IN (
               'production', 'test_only', 'disabled'
           )
           OR pg_catalog.jsonb_typeof(plan_definition->'detailedMutualLimit') <> 'number'
           OR plan_definition->>'detailedMutualLimit' !~ '^[0-9]+$'
           OR (plan_definition->>'detailedMutualLimit')::NUMERIC < 1
           OR (plan_definition->>'detailedMutualLimit')::NUMERIC > 100000 THEN
            RETURN FALSE;
        END IF;

        capacity := plan_definition->'relationshipCapacity';
        IF pg_catalog.jsonb_typeof(capacity) <> 'object'
           OR NOT (capacity ?& ARRAY['followers', 'following'])
           OR capacity - ARRAY['followers', 'following'] <> '{}'::JSONB
           OR pg_catalog.jsonb_typeof(capacity->'followers') <> 'number'
           OR pg_catalog.jsonb_typeof(capacity->'following') <> 'number'
           OR capacity->>'followers' !~ '^[0-9]+$'
           OR capacity->>'following' !~ '^[0-9]+$'
           OR (capacity->>'followers')::NUMERIC < 1
           OR (capacity->>'following')::NUMERIC < 1
           OR (capacity->>'followers')::NUMERIC > 10000000
           OR (capacity->>'following')::NUMERIC > 10000000
           OR (capacity->>'followers')::INTEGER <= previous_followers
           OR (capacity->>'following')::INTEGER <= previous_following
           OR (plan_definition->>'detailedMutualLimit')::INTEGER <= previous_detailed_limit THEN
            RETURN FALSE;
        END IF;

        previous_followers := (capacity->>'followers')::INTEGER;
        previous_following := (capacity->>'following')::INTEGER;
        previous_detailed_limit := (plan_definition->>'detailedMutualLimit')::INTEGER;
    END LOOP;
    RETURN TRUE;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN FALSE;
END;
$_$;


--
-- Name: analysis_v2_valid_policy_versions_snapshot(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_policy_versions_snapshot(p_snapshot jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
    item RECORD;
    item_count INTEGER := 0;
BEGIN
    IF p_snapshot IS NULL
       OR pg_catalog.jsonb_typeof(p_snapshot) <> 'object'
       OR p_snapshot = '{}'::JSONB
       OR pg_catalog.octet_length(p_snapshot::TEXT) > 8192 THEN
        RETURN FALSE;
    END IF;

    IF p_snapshot ? 'scheduler'
       AND p_snapshot->>'scheduler' IS DISTINCT FROM 'ai-scheduler-v1' THEN
        RETURN FALSE;
    END IF;

    FOR item IN SELECT key, value FROM pg_catalog.jsonb_each(p_snapshot) LOOP
        item_count := item_count + 1;
        IF item_count > 16
           OR item.key !~ '^[A-Za-z][A-Za-z0-9._:-]{0,63}$'
           OR pg_catalog.jsonb_typeof(item.value) <> 'string'
           OR pg_catalog.char_length(item.value #>> '{}') < 1
           OR pg_catalog.char_length(item.value #>> '{}') > 128 THEN
            RETURN FALSE;
        END IF;
    END LOOP;
    RETURN TRUE;
END;
$_$;


--
-- Name: analysis_v2_valid_pricing_snapshot(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_pricing_snapshot(p_snapshot jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
    plan_id TEXT;
    price JSONB;
BEGIN
    IF p_snapshot IS NULL
       OR pg_catalog.jsonb_typeof(p_snapshot) <> 'object'
       OR pg_catalog.octet_length(p_snapshot::TEXT) > 8192
       OR NOT (p_snapshot ?& ARRAY['basic', 'standard', 'plus'])
       OR p_snapshot - ARRAY['basic', 'standard', 'plus'] <> '{}'::JSONB THEN
        RETURN FALSE;
    END IF;

    FOREACH plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        price := p_snapshot->plan_id;
        IF pg_catalog.jsonb_typeof(price) <> 'object'
           OR NOT (price ?& ARRAY['status', 'currency', 'amountKrw'])
           OR price - ARRAY['status', 'currency', 'amountKrw'] <> '{}'::JSONB
           OR price->>'currency' IS DISTINCT FROM 'KRW'
           OR price->>'status' IS NULL
           OR price->>'status' NOT IN ('deferred', 'quoted') THEN
            RETURN FALSE;
        END IF;

        IF price->>'status' = 'deferred' THEN
            IF price->'amountKrw' <> 'null'::JSONB THEN
                RETURN FALSE;
            END IF;
        ELSIF pg_catalog.jsonb_typeof(price->'amountKrw') <> 'number'
              OR price->>'amountKrw' !~ '^[0-9]+$'
              OR (price->>'amountKrw')::NUMERIC < 1
              OR (price->>'amountKrw')::NUMERIC > 1000000000 THEN
            RETURN FALSE;
        END IF;
    END LOOP;
    RETURN TRUE;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN FALSE;
END;
$_$;


--
-- Name: analysis_preflights; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_preflights (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    user_id uuid,
    idempotency_key character varying(128) NOT NULL,
    target_instagram_id character varying(30) NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    exclusion_decision text DEFAULT 'pending'::text NOT NULL,
    excluded_instagram_id character varying(30),
    access_mode text NOT NULL,
    launch_status_snapshot jsonb NOT NULL,
    plan_catalog_snapshot jsonb NOT NULL,
    plan_cards_snapshot jsonb,
    pricing_version character varying(64) NOT NULL,
    pricing_snapshot jsonb NOT NULL,
    policy_versions_snapshot jsonb NOT NULL,
    target_full_name character varying(200),
    target_bio character varying(2200),
    target_profile_image_url text,
    target_followers_count integer,
    target_following_count integer,
    target_is_private boolean,
    capacity_required_plan_id text,
    required_plan_id text,
    error_code text,
    worker_attempt_count integer DEFAULT 0 NOT NULL,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    dispatch_generation integer DEFAULT 0 NOT NULL,
    dispatch_state text DEFAULT 'unreserved'::text NOT NULL,
    dispatch_token uuid,
