    plan_id text NOT NULL,
    pricing_version character varying(64) NOT NULL,
    expected_amount_krw integer NOT NULL,
    expected_groble_product_id character varying(128) NOT NULL,
    disclosure_version character varying(64) NOT NULL,
    disclosure_text text NOT NULL,
    disclosure_accepted_at timestamp with time zone NOT NULL,
    status text DEFAULT 'payment_pending'::text NOT NULL,
    payment_id character varying(256),
    actual_groble_product_id character varying(128),
    actual_amount_krw integer,
    paid_at timestamp with time zone,
    due_at timestamp with time zone,
    plan_sequence smallint,
    result_request_id uuid,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expected_buyer_phone_number_normalized text,
    buyer_match_policy text,
    expected_buyer_phone_verification_source text,
    expected_buyer_phone_verified_at timestamp with time zone,
    groble_buyer_email text,
    groble_buyer_phone_number text,
    groble_buyer_display_name text,
    groble_seller_reference text,
    seller_reference_confirmed_at timestamp with time zone,
    concierge_apify_credential_slot text,
    checkout_blocked_at timestamp with time zone,
    checkout_blocked_reason text,
    CONSTRAINT earlybird_orders_buyer_match_snapshot_check CHECK (((buyer_match_policy IS NOT NULL) AND (((buyer_match_policy = 'legacy_email'::text) AND (expected_buyer_phone_number_normalized IS NULL) AND (expected_buyer_phone_verification_source IS NULL) AND (expected_buyer_phone_verified_at IS NULL)) OR ((buyer_match_policy = 'verified_kakao_phone'::text) AND (expected_buyer_phone_number_normalized IS NOT NULL) AND (NOT (expected_buyer_phone_verification_source IS DISTINCT FROM 'kakao_rest_api'::text)) AND (expected_buyer_phone_verified_at IS NOT NULL))))),
    CONSTRAINT earlybird_orders_checkout_block_check CHECK ((((checkout_blocked_at IS NULL) AND (checkout_blocked_reason IS NULL)) OR ((checkout_blocked_at IS NOT NULL) AND (checkout_blocked_reason = 'SUPERSEDED_LINEAGE'::text)))),
    CONSTRAINT earlybird_orders_concierge_apify_slot_check CHECK (((concierge_apify_credential_slot IS NULL) OR public.analysis_v2_valid_apify_credential_slot(concierge_apify_credential_slot))),
    CONSTRAINT earlybird_orders_counts_check CHECK ((((target_followers_count >= 0) AND (target_followers_count <= 10000000)) AND ((target_following_count >= 0) AND (target_following_count <= 10000000)))),
    CONSTRAINT earlybird_orders_due_check CHECK (((due_at IS NULL) OR ((paid_at IS NOT NULL) AND (due_at = (paid_at + '24:00:00'::interval))))),
    CONSTRAINT earlybird_orders_exclusion_check CHECK ((((exclusion_decision = 'skip'::text) AND (excluded_instagram_id IS NULL)) OR ((exclusion_decision = 'exclude'::text) AND ((excluded_instagram_id)::text ~ '^[a-z0-9._]{1,30}$'::text) AND ((excluded_instagram_id)::text <> (target_instagram_id)::text)))),
    CONSTRAINT earlybird_orders_expected_amount_check CHECK ((expected_amount_krw > 0)),
    CONSTRAINT earlybird_orders_expected_buyer_phone_check CHECK (((expected_buyer_phone_number_normalized IS NULL) OR (expected_buyer_phone_number_normalized ~ '^\+8210[0-9]{8}$'::text))),
    CONSTRAINT earlybird_orders_groble_buyer_display_name_check CHECK (((groble_buyer_display_name IS NULL) OR (char_length(groble_buyer_display_name) <= 100))),
    CONSTRAINT earlybird_orders_groble_buyer_email_check CHECK (((groble_buyer_email IS NULL) OR (char_length(groble_buyer_email) <= 320))),
    CONSTRAINT earlybird_orders_groble_buyer_phone_check CHECK (((groble_buyer_phone_number IS NULL) OR (char_length(groble_buyer_phone_number) <= 64))),
    CONSTRAINT earlybird_orders_payment_shape_check CHECK ((((status = 'payment_pending'::text) AND (payment_id IS NULL) AND (paid_at IS NULL)) OR (status <> 'payment_pending'::text))),
    CONSTRAINT earlybird_orders_plan_check CHECK ((plan_id = ANY (ARRAY['basic'::text, 'standard'::text]))),
    CONSTRAINT earlybird_orders_sequence_check CHECK (((plan_sequence IS NULL) OR ((plan_sequence >= 1) AND (plan_sequence <= 10)))),
    CONSTRAINT earlybird_orders_status_check CHECK ((status = ANY (ARRAY['payment_pending'::text, 'payment_failed'::text, 'paid'::text, 'analysis_in_progress'::text, 'completed'::text, 'overflow_refund_required'::text, 'cancelled'::text, 'refund_pending'::text, 'refunded'::text]))),
    CONSTRAINT earlybird_orders_target_check CHECK (((target_instagram_id)::text ~ '^[a-z0-9._]{1,30}$'::text))
);


--
-- Name: analysis_v2_valid_pre_hybrid_recovery_adoption_preflights(public.earlybird_orders, public.analysis_preflights, public.analysis_preflights); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_pre_hybrid_recovery_adoption_preflights(p_order public.earlybird_orders, p_recovery public.analysis_preflights, p_current public.analysis_preflights) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_plan_id TEXT;
    v_plan_rank INTEGER;
    v_catalog JSONB;
    v_launch TEXT;
    v_capacity TEXT;
    v_required TEXT;
    v_capacity_rank INTEGER;
    v_required_rank INTEGER;
    v_cards JSONB := '{}'::JSONB;
    v_state TEXT;
    v_reason TEXT;
    v_selected JSONB;
BEGIN
    -- The first-generation recovery shape still has its immutable admission
    -- witness. Keep the already-reviewed dual-recomputation policy for it.
    IF p_recovery.admission_target_followers_count IS NOT NULL
       OR p_recovery.admission_target_following_count IS NOT NULL
       OR p_recovery.admission_plan_cards_snapshot IS NOT NULL THEN
        IF p_recovery.admission_status <> 'ready'
           OR p_recovery.admission_selected_plan_id IS DISTINCT FROM p_order.plan_id
           OR p_recovery.admission_entitlement_jti_hash IS DISTINCT FROM
                pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
                    'earlybird-fulfillment-admission-v1'
                    || pg_catalog.chr(10)
                    || pg_catalog.lower(p_order.id::TEXT),
                    'UTF8'
                ), 'sha256'), 'hex') THEN
            RETURN FALSE;
        END IF;
        RETURN public.analysis_v2_valid_retained_admission_adoption_preflights(
            p_order, p_recovery, p_current
        );
    END IF;

    IF p_order.plan_id NOT IN ('basic', 'standard')
       OR p_order.target_followers_count IS NULL
       OR p_order.target_following_count IS NULL
       OR p_recovery.status <> 'expired'
       OR p_recovery.pii_scrubbed_at IS NULL
       OR p_recovery.pii_scrubbed_at < p_recovery.expires_at
       OR p_recovery.target_instagram_id IS DISTINCT FROM (
            'retained.' || pg_catalog.substr(
                pg_catalog.replace(p_recovery.id::TEXT, '-', ''), 1, 20
            )
       )
       OR p_recovery.target_full_name IS NOT NULL
       OR p_recovery.target_bio IS NOT NULL
       OR p_recovery.target_profile_image_url IS NOT NULL
       OR p_recovery.target_followers_count IS NOT NULL
       OR p_recovery.target_following_count IS NOT NULL
       OR p_recovery.target_is_private IS NOT NULL
       OR p_recovery.capacity_required_plan_id IS NOT NULL
       OR p_recovery.required_plan_id IS NOT NULL
       OR p_recovery.plan_cards_snapshot IS NOT NULL
       OR p_recovery.exclusion_decision <> 'skip'
       OR p_recovery.excluded_instagram_id IS NOT NULL
       OR p_recovery.lease_token IS NOT NULL
       OR p_recovery.lease_expires_at IS NOT NULL
       OR p_recovery.error_code IS NOT NULL
       OR p_recovery.blocked_at IS NOT NULL
       OR p_recovery.ready_at IS NOT NULL
       OR p_recovery.admission_status <> 'idle'
       OR p_recovery.admission_selected_plan_id IS NOT NULL
       OR p_recovery.admission_entitlement_jti_hash IS NOT NULL
       OR p_recovery.admission_token IS NOT NULL
       OR p_recovery.admission_requested_at IS NOT NULL
       OR p_recovery.admission_refreshed_at IS NOT NULL
       OR p_recovery.admission_claim_token IS NOT NULL
       OR p_recovery.admission_lease_expires_at IS NOT NULL
       OR p_recovery.admission_dispatch_state <> 'idle'
       OR p_recovery.admission_dispatch_token IS NOT NULL
       OR p_recovery.admission_dispatch_reserved_at IS NOT NULL
       OR p_recovery.admission_dispatched_at IS NOT NULL
       OR p_recovery.admission_error_code IS NOT NULL
       OR p_recovery.admission_capacity_required_plan_id IS NOT NULL
       OR p_recovery.admission_required_plan_id IS NOT NULL
       OR p_recovery.admission_last_error_code IS NOT NULL
       OR p_current.user_id IS DISTINCT FROM p_order.user_id
       OR p_current.access_mode <> 'production'
       OR p_current.target_instagram_id IS DISTINCT FROM p_order.target_instagram_id
       OR p_current.target_followers_count IS NULL
       OR p_current.target_following_count IS NULL
       OR p_current.exclusion_decision IS DISTINCT FROM p_order.exclusion_decision
       OR p_current.excluded_instagram_id IS DISTINCT FROM p_order.excluded_instagram_id
       OR p_current.launch_status_snapshot IS DISTINCT FROM p_recovery.launch_status_snapshot
       OR p_current.plan_catalog_snapshot IS DISTINCT FROM p_recovery.plan_catalog_snapshot
       OR p_current.pricing_version IS DISTINCT FROM p_recovery.pricing_version
       OR p_current.pricing_snapshot IS DISTINCT FROM p_recovery.pricing_snapshot
       OR p_current.policy_versions_snapshot IS DISTINCT FROM
            p_recovery.policy_versions_snapshot
       OR NOT public.analysis_v2_valid_launch_snapshot(p_current.launch_status_snapshot)
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(p_current.plan_catalog_snapshot)
       OR NOT public.analysis_v2_valid_pricing_snapshot(p_current.pricing_snapshot)
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(
            p_current.policy_versions_snapshot
       ) THEN
        RETURN FALSE;
    END IF;

    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_catalog := p_current.plan_catalog_snapshot->v_plan_id;
        v_launch := p_current.launch_status_snapshot->>v_plan_id;
        IF v_catalog->>'launchStatus' IS DISTINCT FROM v_launch THEN RETURN FALSE; END IF;
        IF v_capacity_rank IS NULL
           AND p_current.target_followers_count
                <= (v_catalog->'relationshipCapacity'->>'followers')::INTEGER
           AND p_current.target_following_count
                <= (v_catalog->'relationshipCapacity'->>'following')::INTEGER THEN
            v_capacity_rank := v_plan_rank;
            v_capacity := v_plan_id;
        END IF;
    END LOOP;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        IF v_required_rank IS NULL AND v_plan_rank >= v_capacity_rank
           AND p_current.launch_status_snapshot->>v_plan_id = 'production' THEN
            v_required_rank := v_plan_rank;
            v_required := v_plan_id;
        END IF;
    END LOOP;
    IF v_capacity_rank IS NULL OR v_required_rank IS NULL THEN RETURN FALSE; END IF;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_catalog := p_current.plan_catalog_snapshot->v_plan_id;
        v_launch := p_current.launch_status_snapshot->>v_plan_id;
        IF v_plan_rank < v_capacity_rank THEN
            v_state := 'unavailable'; v_reason := 'below_required_plan';
        ELSIF v_launch <> 'production' THEN
            v_state := 'unavailable'; v_reason := 'launch_gate';
        ELSIF v_plan_id = v_required THEN
            v_state := 'required'; v_reason := NULL;
        ELSE
            v_state := 'available_upgrade'; v_reason := NULL;
        END IF;
        v_cards := v_cards || pg_catalog.jsonb_build_object(
            v_plan_id, pg_catalog.jsonb_build_object(
                'launchStatus', v_launch,
                'relationshipCapacity', v_catalog->'relationshipCapacity',
                'detailedMutualLimit', v_catalog->'detailedMutualLimit',
                'selectionState', v_state, 'unavailableReason', v_reason
            )
        );
    END LOOP;
    v_selected := v_cards->p_order.plan_id;
    RETURN public.analysis_v2_valid_plan_cards_snapshot(v_cards)
       AND p_current.capacity_required_plan_id = v_capacity
       AND p_current.required_plan_id = v_required
       AND p_current.plan_cards_snapshot = v_cards
       AND v_selected->>'launchStatus' = 'production'
       AND v_selected->>'selectionState' IN ('required', 'available_upgrade')
       AND p_order.target_followers_count
            <= (v_selected->'relationshipCapacity'->>'followers')::INTEGER
       AND p_order.target_following_count
            <= (v_selected->'relationshipCapacity'->>'following')::INTEGER
       AND p_current.admission_status = 'ready'
       AND p_current.admission_selected_plan_id = p_order.plan_id
       AND p_current.admission_target_followers_count =
            p_current.target_followers_count
       AND p_current.admission_target_following_count =
            p_current.target_following_count
       AND p_current.admission_capacity_required_plan_id = v_capacity
       AND p_current.admission_required_plan_id = v_required
       AND p_current.admission_plan_cards_snapshot = v_cards;
END;
$$;


--
-- Name: analysis_v2_valid_profile_outcomes(jsonb, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_profile_outcomes(p_outcomes jsonb, p_expected_usernames text[], p_attempt text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT p_attempt IN ('primary', 'fallback', 'repair')
       AND public.analysis_v2_valid_profile_username_list(p_expected_usernames, FALSE)
       AND pg_catalog.jsonb_typeof(p_outcomes) = 'array'
       AND pg_catalog.jsonb_array_length(p_outcomes) = pg_catalog.cardinality(p_expected_usernames)
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_outcomes)
                WITH ORDINALITY AS outcome(value, ordinal)
            WHERE pg_catalog.jsonb_typeof(outcome.value) <> 'object'
               OR NOT outcome.value ?& ARRAY[
                    'username', 'source', 'status', 'failure_category', 'http_status',
                    'request_count', 'latency_ms', 'captured_at', 'profile'
               ]
               OR EXISTS (
                    SELECT 1
                    FROM pg_catalog.jsonb_object_keys(outcome.value) AS outcome_key(value)
                    WHERE outcome_key.value <> ALL(ARRAY[
                        'username', 'source', 'status', 'failure_category', 'http_status',
                        'request_count', 'latency_ms', 'captured_at', 'profile'
                    ])
               )
               OR pg_catalog.jsonb_typeof(outcome.value->'username') <> 'string'
               OR outcome.value->>'username' <> p_expected_usernames[outcome.ordinal::INTEGER]
               OR (
                    p_attempt = 'primary'
                    AND outcome.value->>'source' NOT IN ('cache', 'selfhosted')
               )
               OR (
                    p_attempt IN ('fallback', 'repair')
                    AND outcome.value->>'source' <> 'apify'
               )
               OR outcome.value->>'status' NOT IN ('success', 'unavailable', 'failed')
               OR pg_catalog.jsonb_typeof(outcome.value->'request_count') <> 'number'
               OR outcome.value->>'request_count' !~ '^([0-9]|10)$'
               OR pg_catalog.jsonb_typeof(outcome.value->'latency_ms') <> 'number'
               OR outcome.value->>'latency_ms' !~ '^(0|[1-9][0-9]{0,5})$'
               OR (outcome.value->>'latency_ms')::INTEGER > 300000
               OR pg_catalog.jsonb_typeof(outcome.value->'captured_at') <> 'string'
               OR outcome.value->>'captured_at' !~
                    '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$'
               OR (
                    outcome.value->>'status' = 'success'
                    AND (
                        outcome.value->'failure_category' <> 'null'::JSONB
                        OR outcome.value->'http_status' <> 'null'::JSONB
                        OR NOT public.analysis_v2_valid_profile_snapshot(outcome.value->'profile')
                        OR outcome.value->'profile'->>'username' <> outcome.value->>'username'
                    )
               )
               OR (
                    outcome.value->>'status' = 'unavailable'
                    AND (
                        outcome.value->>'failure_category' NOT IN ('not_found', 'empty_user')
                        OR NOT (
                            outcome.value->'http_status' = 'null'::JSONB
                            OR (
                                pg_catalog.jsonb_typeof(outcome.value->'http_status') = 'number'
                                AND outcome.value->>'http_status' = '404'
                            )
                        )
                        OR outcome.value->'profile' <> 'null'::JSONB
                    )
               )
               OR (
                    outcome.value->>'status' = 'failed'
                    AND (
                        outcome.value->>'failure_category' NOT IN (
                            'auth', 'rate_limit', 'timeout', 'incomplete', 'schema',
                            'transport', 'http', 'unknown'
                        )
                        OR NOT (
                            outcome.value->'http_status' = 'null'::JSONB
                            OR (
                                pg_catalog.jsonb_typeof(outcome.value->'http_status') = 'number'
                                AND outcome.value->>'http_status' ~ '^[45][0-9]{2}$'
                            )
                        )
                        OR outcome.value->'profile' <> 'null'::JSONB
                    )
               )
       );
$_$;


--
-- Name: analysis_v2_valid_profile_snapshot(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_profile_snapshot(p_profile jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
    SELECT NOT EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(
            CASE
                WHEN pg_catalog.jsonb_typeof(p_profile->'latestPosts') = 'array'
                    THEN p_profile->'latestPosts'
                ELSE '[]'::JSONB
            END
        ) AS post(value)
        WHERE (
                post.value ? 'likesCountHidden'
                AND (
                    pg_catalog.jsonb_typeof(post.value->'likesCountHidden') <> 'boolean'
                    OR post.value->>'likesCountHidden' <> 'true'
                )
            )
           OR (
                post.value ? 'commentsCountHidden'
                AND (
                    pg_catalog.jsonb_typeof(post.value->'commentsCountHidden') <> 'boolean'
                    OR post.value->>'commentsCountHidden' <> 'true'
                )
            )
    )
    AND (
        NOT p_profile ? 'profilePicUrlHD'
        OR (
            pg_catalog.jsonb_typeof(p_profile->'profilePicUrlHD') = 'string'
            AND pg_catalog.char_length(p_profile->>'profilePicUrlHD') BETWEEN 1 AND 8192
            AND p_profile->>'profilePicUrlHD' ~ '^https?://[^[:space:]]+$'
        )
    )
    AND public.analysis_v2_valid_profile_snapshot_without_hidden_counts(
        (
            CASE
                WHEN pg_catalog.jsonb_typeof(p_profile->'latestPosts') = 'array' THEN
                    (p_profile - 'latestPosts')
                    || pg_catalog.jsonb_build_object(
                        'latestPosts',
                        COALESCE((
                            SELECT pg_catalog.jsonb_agg(
                                post.value - 'likesCountHidden' - 'commentsCountHidden'
                                ORDER BY post.ordinality
                            )
                            FROM pg_catalog.jsonb_array_elements(p_profile->'latestPosts')
                                WITH ORDINALITY AS post(value, ordinality)
                        ), '[]'::JSONB)
                    )
                ELSE p_profile
            END
        ) - 'profilePicUrlHD'
    );
$_$;


--
-- Name: analysis_v2_valid_profile_snapshot_without_hidden_counts(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_profile_snapshot_without_hidden_counts(p_profile jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
    SELECT pg_catalog.jsonb_typeof(p_profile) = 'object'
       AND p_profile ?& ARRAY[
            'username', 'followersCount', 'followingCount', 'postsCount',
            'isPrivate', 'isVerified'
       ]
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_object_keys(p_profile) AS profile_key(value)
            WHERE profile_key.value <> ALL(ARRAY[
                'username', 'fullName', 'bio', 'externalUrl', 'profilePicUrl',
                'followersCount', 'followingCount', 'postsCount', 'isPrivate',
                'isVerified', 'latestPosts'
            ])
       )
       AND pg_catalog.jsonb_typeof(p_profile->'username') = 'string'
       AND p_profile->>'username' ~ '^[a-z0-9._]{1,30}$'
       AND (
            NOT p_profile ? 'fullName'
            OR (
                pg_catalog.jsonb_typeof(p_profile->'fullName') = 'string'
                AND pg_catalog.char_length(p_profile->>'fullName') <= 150
            )
       )
       AND (
            NOT p_profile ? 'bio'
            OR (
                pg_catalog.jsonb_typeof(p_profile->'bio') = 'string'
                AND pg_catalog.char_length(p_profile->>'bio') <= 2200
            )
       )
       AND (
            NOT p_profile ? 'externalUrl'
            OR (
                pg_catalog.jsonb_typeof(p_profile->'externalUrl') = 'string'
                AND pg_catalog.char_length(p_profile->>'externalUrl') BETWEEN 1 AND 8192
                AND p_profile->>'externalUrl' ~ '^https?://[^[:space:]]+$'
            )
       )
       AND (
            NOT p_profile ? 'profilePicUrl'
            OR (
                pg_catalog.jsonb_typeof(p_profile->'profilePicUrl') = 'string'
                AND pg_catalog.char_length(p_profile->>'profilePicUrl') BETWEEN 1 AND 8192
                AND p_profile->>'profilePicUrl' ~ '^https?://[^[:space:]]+$'
            )
       )
       AND pg_catalog.jsonb_typeof(p_profile->'followersCount') = 'number'
       AND p_profile->>'followersCount' ~ '^(0|[1-9][0-9]{0,9})$'
       AND (p_profile->>'followersCount')::NUMERIC <= 2000000000
       AND pg_catalog.jsonb_typeof(p_profile->'followingCount') = 'number'
       AND p_profile->>'followingCount' ~ '^(0|[1-9][0-9]{0,9})$'
       AND (p_profile->>'followingCount')::NUMERIC <= 2000000000
       AND pg_catalog.jsonb_typeof(p_profile->'postsCount') = 'number'
       AND p_profile->>'postsCount' ~ '^(0|[1-9][0-9]{0,9})$'
       AND (p_profile->>'postsCount')::NUMERIC <= 2000000000
       AND pg_catalog.jsonb_typeof(p_profile->'isPrivate') = 'boolean'
       AND pg_catalog.jsonb_typeof(p_profile->'isVerified') = 'boolean'
       AND (
            NOT p_profile ? 'latestPosts'
            OR (
                pg_catalog.jsonb_typeof(p_profile->'latestPosts') = 'array'
                AND pg_catalog.jsonb_array_length(p_profile->'latestPosts') <= 8
                AND NOT EXISTS (
                    SELECT 1
                    FROM pg_catalog.jsonb_array_elements(p_profile->'latestPosts') AS post(value)
                    WHERE pg_catalog.jsonb_typeof(post.value) <> 'object'
                       OR NOT post.value ?& ARRAY[
                            'id', 'shortCode', 'type', 'likesCount', 'commentsCount',
                            'timestamp', 'taggedUsers', 'mentionedUsers'
                       ]
                       OR EXISTS (
                            SELECT 1
                            FROM pg_catalog.jsonb_object_keys(post.value) AS post_key(value)
                            WHERE post_key.value <> ALL(ARRAY[
                                'id', 'shortCode', 'caption', 'hashtags', 'imageUrl',
                                'thumbnailUrl', 'videoUrl', 'type', 'mediaItems',
                                'declaredMediaCount', 'childrenComplete', 'likesCount',
                                'commentsCount', 'timestamp', 'taggedUsers', 'mentionedUsers'
                            ])
                       )
                       OR pg_catalog.jsonb_typeof(post.value->'id') <> 'string'
                       OR pg_catalog.char_length(post.value->>'id') NOT BETWEEN 1 AND 255
                       OR pg_catalog.jsonb_typeof(post.value->'shortCode') <> 'string'
                       OR pg_catalog.char_length(post.value->>'shortCode') NOT BETWEEN 1 AND 100
                       OR pg_catalog.jsonb_typeof(post.value->'type') <> 'string'
                       OR post.value->>'type' NOT IN ('image', 'video', 'carousel', 'reel')
                       OR pg_catalog.jsonb_typeof(post.value->'likesCount') <> 'number'
                       OR post.value->>'likesCount' !~ '^(0|[1-9][0-9]{0,9})$'
                       OR (post.value->>'likesCount')::NUMERIC > 2000000000
                       OR pg_catalog.jsonb_typeof(post.value->'commentsCount') <> 'number'
                       OR post.value->>'commentsCount' !~ '^(0|[1-9][0-9]{0,9})$'
                       OR (post.value->>'commentsCount')::NUMERIC > 2000000000
                       OR pg_catalog.jsonb_typeof(post.value->'timestamp') <> 'string'
                       OR pg_catalog.char_length(post.value->>'timestamp') > 64
                       OR (
                            post.value ? 'caption'
                            AND (
                                pg_catalog.jsonb_typeof(post.value->'caption') <> 'string'
                                OR pg_catalog.char_length(post.value->>'caption') > 2200
                            )
                       )
                       OR (
                            post.value ? 'hashtags'
                            AND (
                                pg_catalog.jsonb_typeof(post.value->'hashtags') <> 'array'
                                OR pg_catalog.jsonb_array_length(post.value->'hashtags') > 30
                                OR EXISTS (
                                    SELECT 1
                                    FROM pg_catalog.jsonb_array_elements(post.value->'hashtags') AS hashtag(value)
                                    WHERE pg_catalog.jsonb_typeof(hashtag.value) <> 'string'
                                       OR pg_catalog.char_length(hashtag.value #>> '{}') NOT BETWEEN 1 AND 100
                                )
                            )
                       )
                       OR EXISTS (
                            SELECT 1
                            FROM pg_catalog.unnest(ARRAY['imageUrl', 'thumbnailUrl', 'videoUrl']) AS media_key(value)
                            WHERE post.value ? media_key.value
                              AND (
                                pg_catalog.jsonb_typeof(post.value->media_key.value) <> 'string'
                                OR pg_catalog.char_length(post.value->>media_key.value) NOT BETWEEN 1 AND 8192
                                OR post.value->>media_key.value !~ '^https?://[^[:space:]]+$'
                              )
                       )
                       OR pg_catalog.jsonb_typeof(post.value->'taggedUsers') <> 'array'
                       OR pg_catalog.jsonb_array_length(post.value->'taggedUsers') > 50
                       OR EXISTS (
                            SELECT 1
                            FROM pg_catalog.jsonb_array_elements(post.value->'taggedUsers') AS username(value)
                            WHERE pg_catalog.jsonb_typeof(username.value) <> 'string'
                               OR username.value #>> '{}' !~ '^[a-z0-9._]{1,30}$'
                       )
                       OR pg_catalog.jsonb_typeof(post.value->'mentionedUsers') <> 'array'
                       OR pg_catalog.jsonb_array_length(post.value->'mentionedUsers') > 50
                       OR EXISTS (
                            SELECT 1
                            FROM pg_catalog.jsonb_array_elements(post.value->'mentionedUsers') AS username(value)
                            WHERE pg_catalog.jsonb_typeof(username.value) <> 'string'
                               OR username.value #>> '{}' !~ '^[a-z0-9._]{1,30}$'
                       )
                       OR (
                            post.value->>'type' <> 'carousel'
                            AND (
                                post.value ? 'mediaItems'
                                OR post.value ? 'declaredMediaCount'
                                OR post.value ? 'childrenComplete'
                            )
                       )
                       OR (
                            post.value ? 'declaredMediaCount'
                            AND (
                                pg_catalog.jsonb_typeof(post.value->'declaredMediaCount') <> 'number'
                                OR post.value->>'declaredMediaCount' !~ '^([1-9]|1[0-9]|20)$'
                            )
                       )
                       OR (
                            post.value ? 'childrenComplete'
                            AND pg_catalog.jsonb_typeof(post.value->'childrenComplete') <> 'boolean'
                       )
                       OR (
                            post.value ? 'mediaItems'
                            AND (
                                pg_catalog.jsonb_typeof(post.value->'mediaItems') <> 'array'
                                OR pg_catalog.jsonb_array_length(post.value->'mediaItems') > 20
                                OR EXISTS (
                                    SELECT 1
                                    FROM pg_catalog.jsonb_array_elements(post.value->'mediaItems') AS media(value)
                                    WHERE pg_catalog.jsonb_typeof(media.value) <> 'object'
                                       OR NOT media.value ? 'type'
                                       OR EXISTS (
                                            SELECT 1
                                            FROM pg_catalog.jsonb_object_keys(media.value) AS media_item_key(value)
                                            WHERE media_item_key.value <> ALL(ARRAY[
                                                'id', 'type', 'caption', 'imageUrl', 'thumbnailUrl', 'videoUrl'
                                            ])
                                       )
                                       OR media.value->>'type' NOT IN ('image', 'video', 'reel')
                                       OR (
                                            media.value ? 'id'
                                            AND (
                                                pg_catalog.jsonb_typeof(media.value->'id') <> 'string'
                                                OR pg_catalog.char_length(media.value->>'id') NOT BETWEEN 1 AND 255
                                            )
                                       )
                                       OR (
                                            media.value ? 'caption'
                                            AND (
                                                pg_catalog.jsonb_typeof(media.value->'caption') <> 'string'
                                                OR pg_catalog.char_length(media.value->>'caption') > 2200
                                            )
                                       )
                                       OR NOT (
                                            media.value ? 'imageUrl'
                                            OR media.value ? 'thumbnailUrl'
                                            OR media.value ? 'videoUrl'
                                       )
                                       OR EXISTS (
                                            SELECT 1
                                            FROM pg_catalog.unnest(ARRAY['imageUrl', 'thumbnailUrl', 'videoUrl']) AS media_url_key(value)
                                            WHERE media.value ? media_url_key.value
                                              AND (
                                                pg_catalog.jsonb_typeof(media.value->media_url_key.value) <> 'string'
                                                OR pg_catalog.char_length(media.value->>media_url_key.value) NOT BETWEEN 1 AND 8192
                                                OR media.value->>media_url_key.value !~ '^https?://[^[:space:]]+$'
                                              )
                                       )
                                )
                            )
                       )
                       OR (
                            post.value->>'childrenComplete' = 'true'
                            AND (
                                NOT post.value ? 'declaredMediaCount'
                                OR NOT post.value ? 'mediaItems'
                                OR (post.value->>'declaredMediaCount')::INTEGER
                                    <> pg_catalog.jsonb_array_length(post.value->'mediaItems')
                            )
                       )
                )
            )
       );
$_$;


--
-- Name: analysis_v2_valid_profile_username_list(text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_profile_username_list(p_usernames text[], p_allow_empty boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT p_usernames IS NOT NULL
       AND pg_catalog.cardinality(p_usernames) BETWEEN
            CASE WHEN p_allow_empty THEN 0 ELSE 1 END AND 30
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.unnest(p_usernames) AS username(value)
            WHERE username.value IS NULL
               OR pg_catalog.char_length(username.value) NOT BETWEEN 1 AND 30
               OR username.value !~ '^[a-z0-9._]+$'
       )
       AND pg_catalog.cardinality(p_usernames) = (
            SELECT pg_catalog.count(DISTINCT username.value)::INTEGER
            FROM pg_catalog.unnest(p_usernames) AS username(value)
       );
$_$;


--
-- Name: analysis_v2_valid_progress_event(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_progress_event(p_event jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT p_event IS NOT NULL
       AND pg_catalog.jsonb_typeof(p_event) = 'object'
       AND p_event ?& ARRAY['state', 'eventCode', 'copyCode', 'aggregateCount']
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_object_keys(p_event) AS event_key(value)
            WHERE event_key.value <> ALL (
                ARRAY['state', 'eventCode', 'copyCode', 'aggregateCount']
            )
       )
       AND p_event->>'state' IN ('provisional', 'confirmed', 'corrected')
       AND p_event->>'eventCode' IN (
            'TARGET_PROFILE_READY',
            'RELATIONSHIP_PROGRESS',
            'PROFILE_SCREENED',
            'SHORTLIST_READY',
            'POTENTIAL_HIGH_RISK_FOUND',
            'FINDING_CORRECTED',
            'FINDING_CONFIRMED',
            'ANALYSIS_COMPLETED'
       )
       AND p_event->>'copyCode' ~ '^[A-Z][A-Z0-9_]{0,63}$'
       AND (
            pg_catalog.jsonb_typeof(p_event->'aggregateCount') = 'null'
            OR (
                pg_catalog.jsonb_typeof(p_event->'aggregateCount') = 'number'
                AND p_event->>'aggregateCount' ~ '^(0|[1-9][0-9]{0,4})$'
                AND (p_event->>'aggregateCount')::INTEGER BETWEEN 0 AND 10000
            )
       )
       AND (
            p_event->>'eventCode' <> 'POTENTIAL_HIGH_RISK_FOUND'
            OR p_event->>'state' = 'provisional'
       )
       AND (
            p_event->>'eventCode' <> 'FINDING_CORRECTED'
            OR p_event->>'state' = 'corrected'
       )
       AND (
            p_event->>'eventCode' NOT IN (
                'SHORTLIST_READY', 'FINDING_CONFIRMED', 'ANALYSIS_COMPLETED'
            )
            OR p_event->>'state' = 'confirmed'
       );
$_$;


--
-- Name: analysis_v2_valid_progress_track(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_progress_track(p_track jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT p_track IS NOT NULL
       AND pg_catalog.jsonb_typeof(p_track) = 'object'
       AND p_track ?& ARRAY['state', 'stageCode', 'done', 'total', 'progressBp']
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_object_keys(p_track) AS track_key(value)
            WHERE track_key.value <> ALL (
                ARRAY['state', 'stageCode', 'done', 'total', 'progressBp']
            )
       )
       AND p_track->>'state' IN ('pending', 'running', 'completed', 'failed')
       AND p_track->>'stageCode' ~ '^[A-Z][A-Z0-9_]{0,63}$'
       AND pg_catalog.jsonb_typeof(p_track->'done') = 'number'
       AND p_track->>'done' ~ '^(0|[1-9][0-9]{0,6})$'
       AND (p_track->>'done')::INTEGER BETWEEN 0 AND 1000000
       AND pg_catalog.jsonb_typeof(p_track->'total') = 'number'
       AND p_track->>'total' ~ '^(0|[1-9][0-9]{0,6})$'
       AND (p_track->>'total')::INTEGER BETWEEN 0 AND 1000000
       AND (p_track->>'done')::INTEGER <= (p_track->>'total')::INTEGER
       AND pg_catalog.jsonb_typeof(p_track->'progressBp') = 'number'
       AND p_track->>'progressBp' ~ '^(0|[1-9][0-9]{0,4})$'
       -- A merge may retain an already durable high-water progress value
       -- while totals are extended. It may never exceed the bounded cap or
       -- fall below the progress implied by its own durable counters.
       AND (p_track->>'progressBp')::INTEGER >= CASE
            WHEN (p_track->>'total')::INTEGER = 0 THEN 0
            ELSE pg_catalog.floor(
                (p_track->>'done')::NUMERIC * 10000
                / (p_track->>'total')::NUMERIC
            )::INTEGER
       END
       AND (p_track->>'progressBp')::INTEGER BETWEEN 0 AND 10000
       AND (p_track->>'state' <> 'pending' OR (p_track->>'done')::INTEGER = 0)
       AND (
            p_track->>'state' <> 'completed'
            OR (p_track->>'done')::INTEGER = (p_track->>'total')::INTEGER
       );
$_$;


--
-- Name: analysis_v2_valid_provider_evidence_source(uuid, text, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_provider_evidence_source(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_provider text, p_run_id text, p_credential_slot text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = p_request_id
          AND provider_run.job_key = p_job_key
          AND provider_run.operation_key = p_operation_key
          AND provider_run.job_claim_token = p_claim_token
          AND provider_run.input_hash = p_input_hash
          AND provider_run.logical_provider = p_provider
          AND provider_run.run_id = p_run_id
          AND provider_run.status = 'succeeded'
          AND (p_credential_slot IS NULL OR provider_run.credential_slot = p_credential_slot)
        UNION ALL
        SELECT 1
        FROM public.analysis_v2_recovery_provider_run_adoptions AS adoption
        JOIN public.analysis_v2_provider_runs AS provider_run
          ON provider_run.request_id = adoption.source_request_id
         AND provider_run.job_key = adoption.source_job_key
         AND provider_run.operation_key = adoption.source_operation_key
         AND provider_run.run_id = adoption.source_run_id
        JOIN public.analysis_pipeline_jobs AS job
          ON job.request_id = adoption.request_id AND job.job_key = adoption.job_key
        WHERE adoption.request_id = p_request_id
          AND adoption.job_key = p_job_key
          AND adoption.operation_key = p_operation_key
          AND adoption.destination_input_hash = p_input_hash
          AND job.status = 'processing'
          AND job.lease_token = p_claim_token
          AND job.lease_expires_at > pg_catalog.clock_timestamp()
          AND provider_run.logical_provider = p_provider
          AND provider_run.run_id = p_run_id
          AND provider_run.status = 'succeeded'
          AND provider_run.actual_usage_usd IS NOT NULL
          AND provider_run.usage_reconciled_at IS NOT NULL
          AND (p_credential_slot IS NULL OR provider_run.credential_slot = p_credential_slot)
    );
$$;


--
-- Name: analysis_v2_valid_recovery_adoption_preflights(public.earlybird_orders, public.analysis_preflights, public.analysis_preflights); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_recovery_adoption_preflights(p_order public.earlybird_orders, p_recovery public.analysis_preflights, p_current public.analysis_preflights) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_normalized public.analysis_preflights%ROWTYPE;
    v_entitlement_hash TEXT;
BEGIN
    IF p_recovery.admission_status <> 'pending' THEN
        RETURN public.analysis_v2_valid_pre_hybrid_recovery_adoption_preflights(
            p_order, p_recovery, p_current
        );
    END IF;

    v_entitlement_hash := pg_catalog.encode(extensions.digest(
        pg_catalog.convert_to(
            'earlybird-fulfillment-admission-v1'
            || pg_catalog.chr(10) || pg_catalog.lower(p_order.id::TEXT),
            'UTF8'
        ),
        'sha256'
    ), 'hex');
    IF p_recovery.status <> 'expired'
       OR p_recovery.pii_scrubbed_at IS NULL
       OR p_recovery.pii_scrubbed_at < p_recovery.expires_at
       OR p_recovery.target_instagram_id IS DISTINCT FROM (
            'retained.' || pg_catalog.substr(
                pg_catalog.replace(p_recovery.id::TEXT, '-', ''), 1, 20
            )
       )
       OR p_recovery.target_full_name IS NOT NULL
       OR p_recovery.target_bio IS NOT NULL
       OR p_recovery.target_profile_image_url IS NOT NULL
       OR p_recovery.target_followers_count IS NOT NULL
       OR p_recovery.target_following_count IS NOT NULL
       OR p_recovery.target_is_private IS NOT NULL
       OR p_recovery.capacity_required_plan_id IS NOT NULL
       OR p_recovery.required_plan_id IS NOT NULL
       OR p_recovery.plan_cards_snapshot IS NOT NULL
       OR p_recovery.exclusion_decision <> 'skip'
       OR p_recovery.excluded_instagram_id IS NOT NULL
       OR p_recovery.admission_selected_plan_id IS DISTINCT FROM p_order.plan_id
       OR p_recovery.admission_entitlement_jti_hash IS DISTINCT FROM
            v_entitlement_hash
       OR p_recovery.admission_token IS NULL
       OR p_recovery.admission_requested_at IS NULL
       OR p_recovery.admission_refreshed_at IS NOT NULL
       OR p_recovery.admission_claim_token IS NOT NULL
       OR p_recovery.admission_lease_expires_at IS NOT NULL
       OR p_recovery.admission_dispatch_state <> 'enqueued'
       OR p_recovery.admission_dispatch_generation < 1
       OR p_recovery.admission_dispatch_token IS NULL
       OR p_recovery.admission_dispatch_reserved_at IS NULL
       OR p_recovery.admission_dispatched_at IS NULL
       OR p_recovery.admission_requested_at
            > p_recovery.admission_dispatch_reserved_at
       OR p_recovery.admission_dispatch_reserved_at
            > p_recovery.admission_dispatched_at
       OR p_recovery.admission_dispatched_at > p_recovery.pii_scrubbed_at
       OR p_recovery.admission_error_code IS NOT NULL
       OR p_recovery.admission_target_followers_count IS NOT NULL
       OR p_recovery.admission_target_following_count IS NOT NULL
       OR p_recovery.admission_capacity_required_plan_id IS NOT NULL
       OR p_recovery.admission_required_plan_id IS NOT NULL
       OR p_recovery.admission_plan_cards_snapshot IS NOT NULL
       OR p_recovery.admission_failure_count <> 0
       OR p_recovery.admission_last_error_code IS NOT NULL THEN
        RETURN FALSE;
    END IF;

    v_normalized := p_recovery;
    v_normalized.admission_status := 'idle';
    v_normalized.admission_generation := 0;
    v_normalized.admission_selected_plan_id := NULL;
    v_normalized.admission_entitlement_jti_hash := NULL;
    v_normalized.admission_token := NULL;
    v_normalized.admission_requested_at := NULL;
    v_normalized.admission_refreshed_at := NULL;
    v_normalized.admission_claim_token := NULL;
    v_normalized.admission_lease_expires_at := NULL;
    v_normalized.admission_dispatch_state := 'idle';
    v_normalized.admission_dispatch_generation := 0;
    v_normalized.admission_dispatch_token := NULL;
    v_normalized.admission_dispatch_reserved_at := NULL;
    v_normalized.admission_dispatched_at := NULL;
    v_normalized.admission_error_code := NULL;
    v_normalized.admission_target_followers_count := NULL;
    v_normalized.admission_target_following_count := NULL;
    v_normalized.admission_capacity_required_plan_id := NULL;
    v_normalized.admission_required_plan_id := NULL;
    v_normalized.admission_plan_cards_snapshot := NULL;
    v_normalized.admission_failure_count := 0;
    v_normalized.admission_last_error_code := NULL;

    RETURN public.analysis_v2_valid_pre_hybrid_recovery_adoption_preflights(
        p_order, v_normalized, p_current
    );
END;
$$;


--
-- Name: analysis_v2_valid_relationship_rows(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_relationship_rows(p_rows jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT p_rows IS NOT NULL
       AND pg_catalog.jsonb_typeof(p_rows) = 'array'
       AND pg_catalog.jsonb_array_length(p_rows) <= 1200
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_rows) AS relationship_row(value)
            WHERE pg_catalog.jsonb_typeof(relationship_row.value) <> 'object'
               OR NOT relationship_row.value ?& ARRAY[
                    'username', 'is_private', 'is_verified', 'full_name', 'profile_pic_url'
               ]
               OR relationship_row.value - ARRAY[
                    'username', 'is_private', 'is_verified', 'full_name', 'profile_pic_url'
               ] <> '{}'::JSONB
               OR pg_catalog.jsonb_typeof(relationship_row.value->'username') <> 'string'
               OR relationship_row.value->>'username' !~ '^[a-z0-9._]{1,30}$'
               OR pg_catalog.jsonb_typeof(relationship_row.value->'is_private') <> 'boolean'
               OR pg_catalog.jsonb_typeof(relationship_row.value->'is_verified') <> 'boolean'
               OR NOT (
                    relationship_row.value->'full_name' = 'null'::JSONB
                    OR (
                        pg_catalog.jsonb_typeof(relationship_row.value->'full_name') = 'string'
                        AND pg_catalog.char_length(relationship_row.value->>'full_name')
                            BETWEEN 1 AND 200
                        AND pg_catalog.octet_length(relationship_row.value->>'full_name') <= 800
                        AND relationship_row.value->>'full_name' !~ '[[:cntrl:]]'
                    )
               )
               OR NOT (
                    relationship_row.value->'profile_pic_url' = 'null'::JSONB
                    OR (
                        pg_catalog.jsonb_typeof(relationship_row.value->'profile_pic_url') = 'string'
                        AND pg_catalog.char_length(relationship_row.value->>'profile_pic_url')
                            BETWEEN 9 AND 8192
                        AND relationship_row.value->>'profile_pic_url' ~ '^https://'
                        AND relationship_row.value->>'profile_pic_url' !~ '[[:cntrl:]]'
                    )
               )
       )
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_rows) AS relationship_row(value)
            GROUP BY relationship_row.value->>'username'
            HAVING pg_catalog.count(*) > 1
       );
$_$;


--
-- Name: analysis_v2_valid_retained_admission_adoption_preflights(public.earlybird_orders, public.analysis_preflights, public.analysis_preflights); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_retained_admission_adoption_preflights(p_order public.earlybird_orders, p_recovery public.analysis_preflights, p_current public.analysis_preflights) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_plan_id TEXT;
    v_plan_rank INTEGER;
    v_catalog JSONB;
    v_launch TEXT;
    v_admission_capacity TEXT;
    v_admission_required TEXT;
    v_admission_capacity_rank INTEGER;
    v_admission_required_rank INTEGER;
    v_current_capacity TEXT;
    v_current_required TEXT;
    v_current_capacity_rank INTEGER;
    v_current_required_rank INTEGER;
    v_admission_cards JSONB := '{}'::JSONB;
    v_current_cards JSONB := '{}'::JSONB;
    v_state TEXT;
    v_reason TEXT;
    v_selected_rank INTEGER;
BEGIN
    IF p_order.plan_id NOT IN ('basic', 'standard')
       OR p_recovery.admission_target_followers_count IS NULL
       OR p_recovery.admission_target_following_count IS NULL
       OR p_order.target_followers_count IS NULL
       OR p_order.target_following_count IS NULL
       OR p_current.target_followers_count IS NULL
       OR p_current.target_following_count IS NULL
       OR p_current.launch_status_snapshot IS DISTINCT FROM p_recovery.launch_status_snapshot
       OR p_current.plan_catalog_snapshot IS DISTINCT FROM p_recovery.plan_catalog_snapshot THEN
        RETURN FALSE;
    END IF;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_catalog := p_recovery.plan_catalog_snapshot->v_plan_id;
        v_launch := p_recovery.launch_status_snapshot->>v_plan_id;
        IF v_catalog->>'launchStatus' IS DISTINCT FROM v_launch THEN RETURN FALSE; END IF;
        IF v_admission_capacity_rank IS NULL
           AND p_recovery.admission_target_followers_count
                <= (v_catalog->'relationshipCapacity'->>'followers')::INTEGER
           AND p_recovery.admission_target_following_count
                <= (v_catalog->'relationshipCapacity'->>'following')::INTEGER THEN
            v_admission_capacity_rank := v_plan_rank;
            v_admission_capacity := v_plan_id;
        END IF;
        IF v_current_capacity_rank IS NULL
           AND p_order.target_followers_count
                <= (v_catalog->'relationshipCapacity'->>'followers')::INTEGER
           AND p_order.target_following_count
                <= (v_catalog->'relationshipCapacity'->>'following')::INTEGER THEN
            v_current_capacity_rank := v_plan_rank;
            v_current_capacity := v_plan_id;
        END IF;
    END LOOP;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        IF v_admission_required_rank IS NULL
           AND v_plan_rank >= v_admission_capacity_rank
           AND p_recovery.launch_status_snapshot->>v_plan_id = 'production' THEN
            v_admission_required_rank := v_plan_rank;
            v_admission_required := v_plan_id;
        END IF;
        IF v_current_required_rank IS NULL
           AND v_plan_rank >= v_current_capacity_rank
           AND p_recovery.launch_status_snapshot->>v_plan_id = 'production' THEN
            v_current_required_rank := v_plan_rank;
            v_current_required := v_plan_id;
        END IF;
    END LOOP;
    v_selected_rank := CASE p_order.plan_id WHEN 'basic' THEN 1 ELSE 2 END;
    IF v_admission_required_rank IS NULL OR v_current_required_rank IS NULL
       OR v_selected_rank < v_admission_required_rank
       OR v_selected_rank < v_current_required_rank THEN
        RETURN FALSE;
    END IF;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_catalog := p_recovery.plan_catalog_snapshot->v_plan_id;
        v_launch := p_recovery.launch_status_snapshot->>v_plan_id;
        IF v_plan_rank < v_admission_capacity_rank THEN
            v_state := 'unavailable'; v_reason := 'below_required_plan';
        ELSIF v_launch <> 'production' THEN
            v_state := 'unavailable'; v_reason := 'launch_gate';
        ELSIF v_plan_id = v_admission_required THEN
            v_state := 'required'; v_reason := NULL;
        ELSE
            v_state := 'available_upgrade'; v_reason := NULL;
        END IF;
        v_admission_cards := v_admission_cards || pg_catalog.jsonb_build_object(
            v_plan_id, pg_catalog.jsonb_build_object(
                'launchStatus', v_launch,
                'relationshipCapacity', v_catalog->'relationshipCapacity',
                'detailedMutualLimit', v_catalog->'detailedMutualLimit',
                'selectionState', v_state, 'unavailableReason', v_reason
            )
        );
        IF v_plan_rank < v_current_capacity_rank THEN
            v_state := 'unavailable'; v_reason := 'below_required_plan';
        ELSIF v_launch <> 'production' THEN
            v_state := 'unavailable'; v_reason := 'launch_gate';
        ELSIF v_plan_id = v_current_required THEN
            v_state := 'required'; v_reason := NULL;
        ELSE
            v_state := 'available_upgrade'; v_reason := NULL;
        END IF;
        v_current_cards := v_current_cards || pg_catalog.jsonb_build_object(
            v_plan_id, pg_catalog.jsonb_build_object(
                'launchStatus', v_launch,
                'relationshipCapacity', v_catalog->'relationshipCapacity',
                'detailedMutualLimit', v_catalog->'detailedMutualLimit',
                'selectionState', v_state, 'unavailableReason', v_reason
            )
        );
    END LOOP;
    RETURN public.analysis_v2_valid_plan_cards_snapshot(v_admission_cards)
       AND public.analysis_v2_valid_plan_cards_snapshot(v_current_cards)
       AND p_recovery.admission_capacity_required_plan_id = v_admission_capacity
       AND p_recovery.admission_required_plan_id = v_admission_required
       AND p_recovery.admission_plan_cards_snapshot = v_admission_cards
       AND p_current.capacity_required_plan_id = v_current_capacity
       AND p_current.required_plan_id = v_current_required
       AND p_current.plan_cards_snapshot = v_current_cards
       AND p_current.plan_cards_snapshot->p_order.plan_id->>'launchStatus' = 'production'
       AND p_current.plan_cards_snapshot->p_order.plan_id->>'selectionState'
            IN ('required', 'available_upgrade')
       AND p_recovery.admission_plan_cards_snapshot->p_order.plan_id->>'launchStatus'
            = 'production'
       AND p_recovery.admission_plan_cards_snapshot->p_order.plan_id->>'selectionState'
            IN ('required', 'available_upgrade');
END;
$$;


--
-- Name: analysis_v2_valid_scheduler_policy_snapshot_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_scheduler_policy_snapshot_v1(p_snapshot jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT public.analysis_v2_scheduler_reader_valid_policy_snapshot_v1(p_snapshot)
       AND pg_catalog.jsonb_typeof(p_snapshot) = 'object'
       AND p_snapshot ?& ARRAY['pipeline', 'risk', 'aiStage', 'scheduler']
       AND NOT EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_object_keys(p_snapshot) AS key_row(policy_key)
           WHERE key_row.policy_key <> ALL (
               ARRAY['pipeline', 'risk', 'aiStage', 'scheduler']::TEXT[]
           )
       )
       AND p_snapshot->>'scheduler' = 'ai-scheduler-v1';
$$;


--
-- Name: analysis_v2_valid_scope_snapshot(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_scope_snapshot(p_snapshot jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
    capacity JSONB;
BEGIN
    IF p_snapshot IS NULL
       OR pg_catalog.jsonb_typeof(p_snapshot) <> 'object'
       OR NOT (p_snapshot ?& ARRAY['relationshipCapacity', 'detailedMutualLimit'])
       OR p_snapshot - ARRAY['relationshipCapacity', 'detailedMutualLimit'] <> '{}'::JSONB
       OR pg_catalog.jsonb_typeof(p_snapshot->'detailedMutualLimit') <> 'number'
       OR p_snapshot->>'detailedMutualLimit' !~ '^[0-9]+$'
       OR (p_snapshot->>'detailedMutualLimit')::NUMERIC < 1
       OR (p_snapshot->>'detailedMutualLimit')::NUMERIC > 100000 THEN
        RETURN FALSE;
    END IF;

    capacity := p_snapshot->'relationshipCapacity';
    RETURN pg_catalog.jsonb_typeof(capacity) = 'object'
        AND capacity ?& ARRAY['followers', 'following']
        AND capacity - ARRAY['followers', 'following'] = '{}'::JSONB
        AND pg_catalog.jsonb_typeof(capacity->'followers') = 'number'
        AND pg_catalog.jsonb_typeof(capacity->'following') = 'number'
        AND capacity->>'followers' ~ '^[0-9]+$'
        AND capacity->>'following' ~ '^[0-9]+$'
        AND (capacity->>'followers')::NUMERIC <= 10000000
        AND (capacity->>'following')::NUMERIC <= 10000000;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN FALSE;
END;
$_$;


--
-- Name: analysis_v2_valid_selfhosted_auth_evidence_source(uuid, text, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_selfhosted_auth_evidence_source(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_provider text, p_run_id text, p_account_slot text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT p_provider = 'selfhosted_auth'
       AND p_account_slot = 'primary'
       AND EXISTS (
            SELECT 1
            FROM public.analysis_v2_selfhosted_auth_runs AS receipt
            JOIN public.analysis_pipeline_jobs AS job
              ON job.request_id = receipt.request_id AND job.job_key = receipt.job_key
            WHERE receipt.request_id = p_request_id
              AND receipt.job_key = p_job_key
              AND receipt.operation_key = p_operation_key
              AND receipt.input_hash = p_input_hash
              AND receipt.job_claim_token = p_claim_token
              AND receipt.run_id = p_run_id
              AND receipt.account_slot = p_account_slot
              AND job.status = 'processing'
              AND job.lease_token = p_claim_token
              AND job.lease_expires_at > pg_catalog.clock_timestamp()
       );
$$;


--
-- Name: analysis_v2_valid_source_adoption_preflights(public.earlybird_orders, public.analysis_preflights, public.analysis_preflights, public.analysis_preflights, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_source_adoption_preflights(p_order public.earlybird_orders, p_recovery public.analysis_preflights, p_source public.analysis_preflights, p_current public.analysis_preflights, p_failed_request_id uuid, p_current_request_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_plan_id TEXT;
    v_plan_rank INTEGER;
    v_catalog JSONB;
    v_launch TEXT;
    v_source_capacity TEXT;
    v_source_required TEXT;
    v_source_capacity_rank INTEGER;
    v_source_required_rank INTEGER;
    v_current_capacity TEXT;
    v_current_required TEXT;
    v_current_capacity_rank INTEGER;
    v_current_required_rank INTEGER;
    v_order_capacity TEXT;
    v_order_capacity_rank INTEGER;
    v_order_required_rank INTEGER;
    v_selected_rank INTEGER;
    v_source_cards JSONB := '{}'::JSONB;
    v_current_cards JSONB := '{}'::JSONB;
    v_state TEXT;
    v_reason TEXT;
    v_entitlement_hash TEXT;
BEGIN
    v_entitlement_hash := pg_catalog.encode(extensions.digest(
        pg_catalog.convert_to(
            'earlybird-fulfillment-admission-v1'
            || pg_catalog.chr(10) || pg_catalog.lower(p_order.id::TEXT),
            'UTF8'
        ), 'sha256'
    ), 'hex');
    IF p_order.plan_id NOT IN ('basic', 'standard')
       OR p_order.target_followers_count NOT BETWEEN 0 AND 1200
       OR p_order.target_following_count NOT BETWEEN 0 AND 1200
       OR p_source.id IS NULL
       OR p_source.user_id IS DISTINCT FROM p_order.user_id
       OR p_source.access_mode <> 'production'
       OR p_source.status <> 'consumed'
       OR p_source.consumed_request_id IS DISTINCT FROM p_failed_request_id
       OR p_source.target_followers_count NOT BETWEEN 0 AND 1200
       OR p_source.target_following_count NOT BETWEEN 0 AND 1200
       OR p_source.target_followers_count IS DISTINCT FROM
            p_source.admission_target_followers_count
       OR p_source.target_following_count IS DISTINCT FROM
            p_source.admission_target_following_count
       OR p_source.admission_status <> 'ready'
       OR p_source.admission_selected_plan_id IS DISTINCT FROM p_order.plan_id
       OR p_source.admission_entitlement_jti_hash IS DISTINCT FROM v_entitlement_hash
       OR p_current.user_id IS DISTINCT FROM p_order.user_id
       OR p_current.access_mode <> 'production'
       OR p_current.status <> 'consumed'
       OR p_current.consumed_request_id IS DISTINCT FROM p_current_request_id
       OR p_current.target_followers_count NOT BETWEEN 0 AND 1200
       OR p_current.target_following_count NOT BETWEEN 0 AND 1200
       OR p_current.admission_status <> 'ready'
       OR p_current.admission_selected_plan_id IS DISTINCT FROM p_order.plan_id
       OR p_current.admission_entitlement_jti_hash IS DISTINCT FROM v_entitlement_hash
       OR p_current.admission_target_followers_count IS DISTINCT FROM
            p_current.target_followers_count
       OR p_current.admission_target_following_count IS DISTINCT FROM
            p_current.target_following_count
       OR p_source.launch_status_snapshot IS DISTINCT FROM
            p_recovery.launch_status_snapshot
       OR p_source.plan_catalog_snapshot IS DISTINCT FROM
            p_recovery.plan_catalog_snapshot
       OR p_source.pricing_version IS DISTINCT FROM p_recovery.pricing_version
       OR p_source.pricing_snapshot IS DISTINCT FROM p_recovery.pricing_snapshot
       OR p_source.policy_versions_snapshot IS DISTINCT FROM
            p_recovery.policy_versions_snapshot
       OR p_current.launch_status_snapshot IS DISTINCT FROM
            p_recovery.launch_status_snapshot
       OR p_current.plan_catalog_snapshot IS DISTINCT FROM
            p_recovery.plan_catalog_snapshot
       OR p_current.pricing_version IS DISTINCT FROM p_recovery.pricing_version
       OR p_current.pricing_snapshot IS DISTINCT FROM p_recovery.pricing_snapshot
       OR p_current.policy_versions_snapshot IS DISTINCT FROM
            p_recovery.policy_versions_snapshot
       OR NOT public.analysis_v2_valid_launch_snapshot(p_recovery.launch_status_snapshot)
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(
            p_recovery.plan_catalog_snapshot
       )
       OR NOT public.analysis_v2_valid_pricing_snapshot(p_recovery.pricing_snapshot)
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(
            p_recovery.policy_versions_snapshot
       ) THEN
        RETURN FALSE;
    END IF;

    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_catalog := p_recovery.plan_catalog_snapshot->v_plan_id;
        v_launch := p_recovery.launch_status_snapshot->>v_plan_id;
        IF v_catalog->>'launchStatus' IS DISTINCT FROM v_launch
           OR COALESCE(v_catalog->'relationshipCapacity'->>'followers', '')
                !~ '^[0-9]+$'
           OR COALESCE(v_catalog->'relationshipCapacity'->>'following', '')
                !~ '^[0-9]+$' THEN
            RETURN FALSE;
        END IF;
        IF v_source_capacity_rank IS NULL
           AND p_source.admission_target_followers_count
                <= (v_catalog->'relationshipCapacity'->>'followers')::INTEGER
           AND p_source.admission_target_following_count
                <= (v_catalog->'relationshipCapacity'->>'following')::INTEGER THEN
            v_source_capacity_rank := v_plan_rank;
            v_source_capacity := v_plan_id;
        END IF;
        IF v_current_capacity_rank IS NULL
           AND p_current.target_followers_count
                <= (v_catalog->'relationshipCapacity'->>'followers')::INTEGER
           AND p_current.target_following_count
                <= (v_catalog->'relationshipCapacity'->>'following')::INTEGER THEN
            v_current_capacity_rank := v_plan_rank;
            v_current_capacity := v_plan_id;
        END IF;
        IF v_order_capacity_rank IS NULL
           AND p_order.target_followers_count
                <= (v_catalog->'relationshipCapacity'->>'followers')::INTEGER
           AND p_order.target_following_count
                <= (v_catalog->'relationshipCapacity'->>'following')::INTEGER THEN
            v_order_capacity_rank := v_plan_rank;
            v_order_capacity := v_plan_id;
        END IF;
    END LOOP;
    IF v_source_capacity_rank IS NULL OR v_current_capacity_rank IS NULL
       OR v_order_capacity_rank IS NULL THEN
        RETURN FALSE;
    END IF;

    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        IF v_source_required_rank IS NULL AND v_plan_rank >= v_source_capacity_rank
           AND p_recovery.launch_status_snapshot->>v_plan_id = 'production' THEN
            v_source_required_rank := v_plan_rank; v_source_required := v_plan_id;
        END IF;
        IF v_current_required_rank IS NULL AND v_plan_rank >= v_current_capacity_rank
           AND p_recovery.launch_status_snapshot->>v_plan_id = 'production' THEN
            v_current_required_rank := v_plan_rank; v_current_required := v_plan_id;
        END IF;
        IF v_order_required_rank IS NULL AND v_plan_rank >= v_order_capacity_rank
           AND p_recovery.launch_status_snapshot->>v_plan_id = 'production' THEN
            v_order_required_rank := v_plan_rank;
        END IF;
    END LOOP;
    v_selected_rank := CASE p_order.plan_id WHEN 'basic' THEN 1 ELSE 2 END;
    IF v_source_required_rank IS NULL OR v_current_required_rank IS NULL
       OR v_order_required_rank IS NULL
       OR v_selected_rank < v_source_required_rank
       OR v_selected_rank < v_current_required_rank
       OR v_selected_rank < v_order_required_rank
       OR p_recovery.launch_status_snapshot->>p_order.plan_id <> 'production' THEN
        RETURN FALSE;
    END IF;

    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_catalog := p_recovery.plan_catalog_snapshot->v_plan_id;
        v_launch := p_recovery.launch_status_snapshot->>v_plan_id;
        IF v_plan_rank < v_source_capacity_rank THEN
            v_state := 'unavailable'; v_reason := 'below_required_plan';
        ELSIF v_launch <> 'production' THEN
            v_state := 'unavailable'; v_reason := 'launch_gate';
        ELSIF v_plan_id = v_source_required THEN
            v_state := 'required'; v_reason := NULL;
        ELSE
            v_state := 'available_upgrade'; v_reason := NULL;
        END IF;
        v_source_cards := v_source_cards || pg_catalog.jsonb_build_object(
            v_plan_id, pg_catalog.jsonb_build_object(
                'launchStatus', v_launch,
                'relationshipCapacity', v_catalog->'relationshipCapacity',
                'detailedMutualLimit', v_catalog->'detailedMutualLimit',
                'selectionState', v_state, 'unavailableReason', v_reason
            )
        );
        IF v_plan_rank < v_current_capacity_rank THEN
            v_state := 'unavailable'; v_reason := 'below_required_plan';
        ELSIF v_launch <> 'production' THEN
            v_state := 'unavailable'; v_reason := 'launch_gate';
        ELSIF v_plan_id = v_current_required THEN
            v_state := 'required'; v_reason := NULL;
        ELSE
            v_state := 'available_upgrade'; v_reason := NULL;
        END IF;
        v_current_cards := v_current_cards || pg_catalog.jsonb_build_object(
            v_plan_id, pg_catalog.jsonb_build_object(
                'launchStatus', v_launch,
                'relationshipCapacity', v_catalog->'relationshipCapacity',
                'detailedMutualLimit', v_catalog->'detailedMutualLimit',
                'selectionState', v_state, 'unavailableReason', v_reason
            )
        );
    END LOOP;

    RETURN public.analysis_v2_valid_plan_cards_snapshot(v_source_cards)
       AND public.analysis_v2_valid_plan_cards_snapshot(v_current_cards)
       AND p_source.capacity_required_plan_id = v_source_capacity
       AND p_source.required_plan_id = v_source_required
       AND p_source.plan_cards_snapshot = v_source_cards
       AND p_source.admission_capacity_required_plan_id = v_source_capacity
       AND p_source.admission_required_plan_id = v_source_required
       AND p_source.admission_plan_cards_snapshot = v_source_cards
       AND p_current.capacity_required_plan_id = v_current_capacity
       AND p_current.required_plan_id = v_current_required
       AND p_current.plan_cards_snapshot = v_current_cards
       AND p_current.admission_capacity_required_plan_id = v_current_capacity
       AND p_current.admission_required_plan_id = v_current_required
       AND p_current.admission_plan_cards_snapshot = v_current_cards
       AND p_source.admission_plan_cards_snapshot->p_order.plan_id->>'selectionState'
            IN ('required', 'available_upgrade')
       AND p_current.plan_cards_snapshot->p_order.plan_id->>'selectionState'
            IN ('required', 'available_upgrade')
       AND p_order.target_followers_count <=
            (p_recovery.plan_catalog_snapshot->p_order.plan_id
                ->'relationshipCapacity'->>'followers')::INTEGER
       AND p_order.target_following_count <=
            (p_recovery.plan_catalog_snapshot->p_order.plan_id
                ->'relationshipCapacity'->>'following')::INTEGER;
END;
$_$;


--
-- Name: analysis_v2_valid_target_evidence_rows(jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_target_evidence_rows(p_rows jsonb, p_target_username text, p_excluded_username text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT p_rows IS NOT NULL
       AND p_target_username ~ '^[a-z0-9._]{1,30}$'
       AND (
            p_excluded_username IS NULL
            OR (
                p_excluded_username ~ '^[a-z0-9._]{1,30}$'
                AND p_excluded_username <> p_target_username
            )
       )
       AND pg_catalog.jsonb_typeof(p_rows) = 'array'
       AND pg_catalog.jsonb_array_length(p_rows) <= 690
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_rows) AS evidence(value)
            WHERE pg_catalog.jsonb_typeof(evidence.value) <> 'object'
               OR NOT evidence.value ?& ARRAY[
                    'actor_username', 'post_id', 'signal', 'source_interaction_id',
                    'occurred_at', 'content'
               ]
               OR evidence.value - ARRAY[
                    'actor_username', 'post_id', 'signal', 'source_interaction_id',
                    'occurred_at', 'content'
               ] <> '{}'::JSONB
               OR pg_catalog.jsonb_typeof(evidence.value->'actor_username') <> 'string'
               OR evidence.value->>'actor_username' !~ '^[a-z0-9._]{1,30}$'
               OR evidence.value->>'actor_username' = p_target_username
               OR evidence.value->>'actor_username' = p_excluded_username
               OR pg_catalog.jsonb_typeof(evidence.value->'post_id') <> 'string'
               OR pg_catalog.char_length(evidence.value->>'post_id') NOT BETWEEN 1 AND 255
               OR evidence.value->>'post_id' ~ '[[:cntrl:]]'
               OR pg_catalog.jsonb_typeof(evidence.value->'source_interaction_id') <> 'string'
               OR pg_catalog.char_length(evidence.value->>'source_interaction_id')
                    NOT BETWEEN 1 AND 255
               OR evidence.value->>'source_interaction_id' ~ '[[:cntrl:]]'
               OR pg_catalog.jsonb_typeof(evidence.value->'signal') <> 'string'
               OR evidence.value->>'signal' NOT IN (
                    'target_post_like', 'target_post_comment'
               )
               OR NOT (
                    evidence.value->'occurred_at' = 'null'::JSONB
                    OR (
                        pg_catalog.jsonb_typeof(evidence.value->'occurred_at') = 'string'
                        AND public.analysis_v2_valid_iso_timestamp(
                            evidence.value->>'occurred_at'
                        )
                    )
               )
               OR NOT (
                    evidence.value->'content' = 'null'::JSONB
                    OR (
                        pg_catalog.jsonb_typeof(evidence.value->'content') = 'string'
                        AND pg_catalog.char_length(evidence.value->>'content') BETWEEN 1 AND 1000
                        AND pg_catalog.octet_length(evidence.value->>'content') <= 4000
                        AND evidence.value->>'content' !~ '[[:cntrl:]]'
                        AND evidence.value->>'content' !~ '[<>]'
                    )
               )
               OR (
                    evidence.value->>'signal' = 'target_post_like'
                    AND evidence.value->'content' <> 'null'::JSONB
               )
       )
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_rows) AS evidence(value)
            GROUP BY
                evidence.value->>'signal',
                evidence.value->>'source_interaction_id'
            HAVING pg_catalog.count(*) > 1
       )
       AND (
            SELECT pg_catalog.count(DISTINCT evidence.value->>'post_id')
            FROM pg_catalog.jsonb_array_elements(p_rows) AS evidence(value)
            WHERE evidence.value->>'signal' = 'target_post_like'
       ) <= 4
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_rows) AS evidence(value)
            WHERE evidence.value->>'signal' = 'target_post_like'
            GROUP BY evidence.value->>'post_id'
            HAVING pg_catalog.count(*) > 150
       )
       AND (
            SELECT pg_catalog.count(DISTINCT evidence.value->>'post_id')
            FROM pg_catalog.jsonb_array_elements(p_rows) AS evidence(value)
            WHERE evidence.value->>'signal' = 'target_post_comment'
       ) <= 6
       AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_rows) AS evidence(value)
            WHERE evidence.value->>'signal' = 'target_post_comment'
            GROUP BY evidence.value->>'post_id'
            HAVING pg_catalog.count(*) > 15
       );
$_$;


--
-- Name: analysis_v2_valid_test_operation_slot_map(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_valid_test_operation_slot_map(p_map jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT COALESCE(
        pg_catalog.jsonb_typeof(p_map) = 'object'
        AND p_map ?& ARRAY[
            'target-profile',
            'relationship-followers',
            'relationship-following',
            'profile-fallback',
            'target-likers',
            'target-comments',
            'candidate-likers'
        ]
        AND p_map - ARRAY[
            'target-profile',
            'relationship-followers',
            'relationship-following',
            'profile-fallback',
            'target-likers',
            'target-comments',
            'candidate-likers'
        ] = '{}'::JSONB
        AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_each(p_map)
                AS entry(operation_kind, slot_value)
            WHERE pg_catalog.jsonb_typeof(entry.slot_value) <> 'string'
               OR entry.slot_value #>> '{}' NOT IN (
                    'primary', 'secondary', 'tertiary',
                    'quaternary', 'quinary', 'senary'
               )
        )
        AND p_map->>'target-profile' = p_map->>'profile-fallback'
        AND p_map->>'relationship-followers' <> p_map->>'relationship-following'
        AND p_map->>'target-likers' <> p_map->>'candidate-likers',
        FALSE
    );
$$;


--
-- Name: analysis_v2_validate_candidate_gender_resolution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_validate_candidate_gender_resolution() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
    v_profile_job_key TEXT;
BEGIN
    IF NEW.baseline_classification IS NULL THEN
        NEW.baseline_classification := NEW.terminal_classification;
    END IF;
    IF NEW.classification_source IS NULL THEN
        NEW.classification_source := CASE
            WHEN NEW.terminal_classification = 'verified_non_female'
                 AND NEW.feature_operation_key IS NULL THEN 'triage'
            WHEN NEW.terminal_classification IN ('verified_female', 'verified_non_female')
                THEN 'feature'
            WHEN NEW.terminal_classification IN ('unresolved', 'unresolved_stage_conflict')
                THEN 'unknown'
            ELSE 'unavailable'
        END;
    END IF;
    IF NEW.gender_resolution_status IS NULL THEN
        NEW.gender_resolution_status := 'disabled';
    END IF;
    IF NEW.gender_resolution_status IN (
        'ready_applied', 'ready_not_needed', 'ready_inconclusive'
    ) THEN
        SELECT manifest.producer_job_key INTO v_profile_job_key
        FROM public.analysis_v2_candidate_feature_manifests AS manifest
        WHERE manifest.request_id = NEW.request_id AND manifest.batch = NEW.batch;
        IF v_profile_job_key IS NULL OR NOT EXISTS (
            SELECT 1
            FROM public.analysis_v2_ai_result_checkpoints AS result
            WHERE result.request_id = NEW.request_id
              AND result.operation_key = NEW.gender_resolution_operation_key
              AND result.stage = 'genderResolution'
              AND result.cache_scope = 'request'
              AND result.result_hash = NEW.gender_resolution_result_hash
              AND (
                    result.job_key = v_profile_job_key
                    OR (
                        result.job_key = 'coordinator:join:primary-evidence'
                        AND EXISTS (
                            SELECT 1 FROM public.analysis_revenue_resolver_passes AS pass
                            WHERE pass.request_id = NEW.request_id
                              AND pass.job_key = result.job_key
                        )
                    )
              )
        ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_GENDER_RESOLUTION_RESULT_FENCE_MISMATCH',
                ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: analysis_v2_validate_unconfirmed_start_resolution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analysis_v2_validate_unconfirmed_start_resolution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_quiet_before TIMESTAMP WITH TIME ZONE;
    v_intent_job_key TEXT;
    v_request public.analysis_requests%ROWTYPE;
    v_failed_job public.analysis_pipeline_jobs%ROWTYPE;
    v_intent public.analysis_v2_provider_cleanup_intents%ROWTYPE;
    v_run public.analysis_v2_provider_runs%ROWTYPE;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_RESOLUTION_IMMUTABLE',
            ERRCODE = 'P0001';
    END IF;

    PERFORM 1 FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = NEW.request_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_RESOLUTION_NOT_READY',
            ERRCODE = 'P0001';
    END IF;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = NEW.request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND OR v_request.status NOT IN ('pending', 'processing') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_RESOLUTION_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    SELECT intent.failed_job_key INTO v_intent_job_key
    FROM public.analysis_v2_provider_cleanup_intents AS intent
    WHERE intent.request_id = NEW.request_id AND intent.completed_at IS NULL;
    IF v_intent_job_key IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_RESOLUTION_NOT_READY',
            ERRCODE = 'P0001';
    END IF;
    SELECT job.* INTO v_failed_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = NEW.request_id AND job.job_key = v_intent_job_key
    FOR UPDATE;
    SELECT intent.* INTO v_intent
    FROM public.analysis_v2_provider_cleanup_intents AS intent
    WHERE intent.request_id = NEW.request_id
    FOR UPDATE;
    SELECT provider_run.* INTO v_run
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.reservation_token = NEW.reservation_token
    FOR UPDATE;

    v_now := pg_catalog.clock_timestamp();
    v_quiet_before := v_now - INTERVAL '30 minutes';
    IF v_intent.request_id IS NULL OR v_intent.completed_at IS NOT NULL
       OR v_intent.failed_job_key IS DISTINCT FROM v_intent_job_key
       OR v_failed_job.request_id IS NULL
       OR v_failed_job.status <> 'processing'
       OR v_failed_job.input_hash IS DISTINCT FROM v_intent.failed_job_input_hash
       OR v_failed_job.lease_token IS DISTINCT FROM v_intent.failed_claim_token
       OR v_failed_job.lease_expires_at IS NULL
       OR v_failed_job.lease_expires_at > v_quiet_before
       OR v_intent.requested_at > v_quiet_before
       OR EXISTS (
            SELECT 1 FROM public.analysis_pipeline_jobs AS live_job
            WHERE live_job.request_id = NEW.request_id
              AND live_job.status = 'processing'
              AND live_job.lease_expires_at > v_quiet_before
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_RESOLUTION_NOT_QUIESCENT',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.reservation_token IS NULL OR v_run.status <> 'starting'
       OR v_run.run_id IS NOT NULL
       OR v_run.reserved_at > v_quiet_before
       OR v_run.updated_at > v_quiet_before
       OR v_run.request_id IS DISTINCT FROM NEW.request_id
       OR v_run.job_key IS DISTINCT FROM NEW.job_key
       OR v_run.operation_key IS DISTINCT FROM NEW.operation_key
       OR v_run.input_hash IS DISTINCT FROM NEW.input_hash
       OR v_run.logical_provider IS DISTINCT FROM NEW.logical_provider
       OR v_run.actor_id IS DISTINCT FROM NEW.actor_id
       OR v_run.credential_slot IS DISTINCT FROM NEW.credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM NEW.max_charge_usd THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_RESOLUTION_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    NEW.database_actor := SESSION_USER;
    NEW.confirmed_at := v_now;
    RETURN NEW;
END;
$$;


--
-- Name: append_account_lifecycle_v1(uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_account_lifecycle_v1(p_account_id uuid, p_event_kind text, p_state text, p_payload jsonb DEFAULT '{}'::jsonb, p_content_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_id BIGINT;
BEGIN
    IF p_account_id IS NULL
       OR p_event_kind NOT IN (
           'classification', 'paid_evidence', 'deletion_requested',
           'objects_purged', 'database_purged', 'retired', 'e2e'
       )
       OR p_state IS NULL OR pg_catalog.length(pg_catalog.btrim(p_state)) = 0
       OR p_payload IS NULL OR pg_catalog.jsonb_typeof(p_payload) <> 'object'
       OR p_content_hash IS NULL OR p_content_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ACCOUNT_LIFECYCLE_INPUT_INVALID', ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.account_lifecycle(account_id, event_kind, state, content_hash, payload)
    VALUES (p_account_id, p_event_kind, p_state, p_content_hash, p_payload)
    RETURNING id INTO v_id;
    RETURN pg_catalog.jsonb_build_object('status', 'recorded', 'id', v_id);
END;
$_$;


--
-- Name: apply_analysis_v2_v211_legacy_secondary_text_only_revision(uuid, text, text, text, integer, smallint, smallint, smallint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_analysis_v2_v211_legacy_secondary_text_only_revision(p_request_id uuid, p_source_fingerprint text, p_semantic_input_fingerprint text, p_idempotency_key text, p_expected_current_revision integer, p_male_count smallint, p_female_count smallint, p_unknown_count smallint, p_female_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_source JSONB; v_expected JSONB; v_actual JSONB;
BEGIN
    v_source := public.read_analysis_v2_test_entitlement_v211_text_only_source(p_request_id);
    IF (v_source->'canonicalCounts') <> pg_catalog.jsonb_build_object('male', p_male_count, 'female', p_female_count, 'unknown', p_unknown_count)
       OR p_female_count <> pg_catalog.jsonb_array_length(p_female_rows) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_V211_TEXT_ONLY_COUNT_DRIFT', ERRCODE = 'P0001';
    END IF;
    SELECT pg_catalog.jsonb_agg(item.value - 'oneLineOverview' ORDER BY (item.value->>'sortOrdinal')::INTEGER, item.value->>'candidateId') INTO v_expected
    FROM pg_catalog.jsonb_array_elements(v_source->'originalFemaleRows') AS item(value);
    SELECT pg_catalog.jsonb_agg(item.value - 'oneLineOverview' ORDER BY (item.value->>'sortOrdinal')::INTEGER, item.value->>'candidateId') INTO v_actual
    FROM pg_catalog.jsonb_array_elements(p_female_rows) AS item(value);
    IF v_expected IS DISTINCT FROM v_actual THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_V211_TEXT_ONLY_IMMUTABLE_ROW_DRIFT', ERRCODE = 'P0001';
    END IF;
    RETURN public.apply_analysis_v2_v211_result_revision(p_request_id, p_source_fingerprint,
        p_semantic_input_fingerprint, p_idempotency_key, p_expected_current_revision,
        p_male_count, p_female_count, p_unknown_count, p_female_rows);
END; $$;


--
-- Name: apply_analysis_v2_v211_result_revision(uuid, text, text, text, integer, smallint, smallint, smallint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_analysis_v2_v211_result_revision(p_request_id uuid, p_source_fingerprint text, p_semantic_input_fingerprint text, p_idempotency_key text, p_expected_current_revision integer, p_male_count smallint, p_female_count smallint, p_unknown_count smallint, p_female_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_summary public.analysis_v2_result_summaries%ROWTYPE;
    v_current public.analysis_v2_result_revisions%ROWTYPE;
    v_existing public.analysis_v2_result_revisions%ROWTYPE;
    v_source_fingerprint TEXT;
    v_payload_hash TEXT;
    v_revision public.analysis_v2_result_revisions%ROWTYPE;
    v_row_count INTEGER;
BEGIN
    IF p_request_id IS NULL
       OR p_source_fingerprint !~ '^[a-f0-9]{64}$'
       OR p_semantic_input_fingerprint !~ '^[a-f0-9]{64}$'
       OR p_idempotency_key !~ '^[a-f0-9]{64}$'
       OR p_expected_current_revision IS NULL OR p_expected_current_revision NOT BETWEEN 0 AND 999
       OR p_male_count IS NULL OR p_male_count < 0
       OR p_female_count IS NULL OR p_female_count < 0
       OR p_unknown_count IS NULL OR p_unknown_count < 0
       OR p_female_rows IS NULL OR pg_catalog.jsonb_typeof(p_female_rows) <> 'array'
       OR pg_catalog.jsonb_array_length(p_female_rows) > 900
       OR pg_catalog.octet_length(p_female_rows::TEXT) > 4194304 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_V211_REVISION_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id FOR UPDATE;
    SELECT summary.* INTO v_summary
    FROM public.analysis_v2_result_summaries AS summary
    WHERE summary.request_id = p_request_id FOR UPDATE;
    IF NOT FOUND
       OR v_request.status <> 'completed'
       OR v_request.pipeline_version <> 'v2'
       OR v_request.selected_plan_id_snapshot <> 'standard'
       OR v_request.plan_access_mode_snapshot <> 'test_entitlement'
       OR v_request.analysis_entry_channel <> 'standard'
       OR v_request.test_entitlement_jti_hash IS NULL
       OR v_request.policy_versions_snapshot <> '{"pipeline":"v2","risk":"risk-policy-v2.5","aiStage":"ai-stage-policy-v2.10","scheduler":"ai-scheduler-v1"}'::JSONB
       OR v_summary.score_policy_version <> 'risk-policy-v2.5' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_V211_REVISION_SOURCE_INELIGIBLE', ERRCODE = 'P0001';
    END IF;

    v_source_fingerprint := public.analysis_v2_v211_maintenance_source_fingerprint(p_request_id);
    IF v_source_fingerprint IS NULL OR v_source_fingerprint IS DISTINCT FROM p_source_fingerprint THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_V211_REVISION_SOURCE_DRIFT', ERRCODE = 'P0001';
    END IF;
    v_payload_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
        pg_catalog.concat_ws(E'\n', 'analysis-v2-v211-revision-payload:v1',
            p_request_id::TEXT, p_source_fingerprint, p_semantic_input_fingerprint,
            p_male_count::TEXT, p_female_count::TEXT, p_unknown_count::TEXT,
            p_female_rows::TEXT), 'UTF8'), 'sha256'), 'hex');

    SELECT revision.* INTO v_existing
    FROM public.analysis_v2_result_revisions AS revision
    WHERE revision.request_id = p_request_id AND revision.idempotency_key = p_idempotency_key;
    IF FOUND THEN
        IF v_existing.source_fingerprint IS DISTINCT FROM p_source_fingerprint
           OR v_existing.semantic_input_fingerprint IS DISTINCT FROM p_semantic_input_fingerprint
           OR v_existing.male_count IS DISTINCT FROM p_male_count
           OR v_existing.female_count IS DISTINCT FROM p_female_count
           OR v_existing.unknown_count IS DISTINCT FROM p_unknown_count
           OR v_existing.payload_hash IS DISTINCT FROM v_payload_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_V211_REVISION_IDEMPOTENCY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'revisionId', v_existing.revision_id,
            'revisionNumber', v_existing.revision_number,
            'idempotent', true
        );
    END IF;

    SELECT revision.* INTO v_current
    FROM public.analysis_v2_result_revisions AS revision
    WHERE revision.request_id = p_request_id AND revision.state = 'published'
    FOR UPDATE;
    IF COALESCE(v_current.revision_number, 0) <> p_expected_current_revision THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_V211_REVISION_CONCURRENT_MODIFICATION', ERRCODE = 'P0001';
    END IF;
    IF p_male_count + p_female_count + p_unknown_count <> v_summary.screened_mutuals
       OR p_female_count <> pg_catalog.jsonb_array_length(p_female_rows) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_V211_REVISION_GENDER_COUNT_DRIFT', ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_female_rows) AS item(value)
        WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
           OR NOT (item.value ?& ARRAY[
                'candidateId', 'sortOrdinal', 'instagramId', 'fullName', 'profileImageUrl',
                'bio', 'displayScore', 'riskBand', 'featuredRank', 'recentMutualRank',
                'analysisDepth', 'oneLineOverview', 'highRiskNarrative'
           ])
           OR item.value - ARRAY[
                'candidateId', 'sortOrdinal', 'instagramId', 'fullName', 'profileImageUrl',
                'bio', 'displayScore', 'riskBand', 'featuredRank', 'recentMutualRank',
                'analysisDepth', 'oneLineOverview', 'highRiskNarrative'
           ] <> '{}'::JSONB
           OR item.value->>'candidateId' !~ '^[A-Za-z0-9._:-]{1,128}$'
           OR item.value->>'instagramId' !~ '^[a-z0-9._]{1,30}$'
           OR item.value->>'sortOrdinal' !~ '^[1-9][0-9]{0,2}$'
           OR (item.value->>'sortOrdinal')::INTEGER NOT BETWEEN 1 AND 900
           OR pg_catalog.jsonb_typeof(item.value->'fullName') NOT IN ('string', 'null')
           OR pg_catalog.jsonb_typeof(item.value->'profileImageUrl') NOT IN ('string', 'null')
           OR pg_catalog.jsonb_typeof(item.value->'bio') NOT IN ('string', 'null')
           OR pg_catalog.jsonb_typeof(item.value->'displayScore') <> 'number'
           OR item.value->>'riskBand' NOT IN ('normal', 'caution', 'high_risk')
           OR item.value->>'analysisDepth' NOT IN ('features', 'narrative')
           OR NOT public.analysis_v2_result_valid_public_copy(item.value->>'oneLineOverview', 180)
           OR (item.value->'profileImageUrl' <> 'null'::JSONB
                AND NOT public.analysis_v2_result_valid_image_path(item.value->>'profileImageUrl'))
           OR pg_catalog.jsonb_typeof(item.value->'featuredRank') NOT IN ('number', 'null')
           OR pg_catalog.jsonb_typeof(item.value->'recentMutualRank') NOT IN ('number', 'null')
           OR pg_catalog.jsonb_typeof(item.value->'highRiskNarrative') NOT IN ('array', 'null')
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_V211_REVISION_ROW_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT pg_catalog.count(*) INTO v_row_count
    FROM pg_catalog.jsonb_array_elements(p_female_rows) AS item(value);
    IF (SELECT pg_catalog.count(DISTINCT item.value->>'candidateId') FROM pg_catalog.jsonb_array_elements(p_female_rows) AS item(value)) <> v_row_count
       OR (SELECT pg_catalog.count(DISTINCT item.value->>'instagramId') FROM pg_catalog.jsonb_array_elements(p_female_rows) AS item(value)) <> v_row_count
       OR (SELECT pg_catalog.count(DISTINCT (item.value->>'sortOrdinal')::INTEGER) FROM pg_catalog.jsonb_array_elements(p_female_rows) AS item(value)) <> v_row_count
       OR EXISTS (
            SELECT 1 FROM pg_catalog.generate_series(1, v_row_count) AS expected(ordinal)
            WHERE NOT EXISTS (
                SELECT 1 FROM pg_catalog.jsonb_array_elements(p_female_rows) AS item(value)
                WHERE (item.value->>'sortOrdinal')::INTEGER = expected.ordinal
            )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_V211_REVISION_ROW_ORDER_DRIFT', ERRCODE = 'P0001';
    END IF;

    IF v_current.revision_id IS NOT NULL THEN
        UPDATE public.analysis_v2_result_revisions SET state = 'superseded'
        WHERE revision_id = v_current.revision_id;
    END IF;
    INSERT INTO public.analysis_v2_result_revisions (
        request_id, revision_number, state, source_ai_stage_policy,
        evaluation_ai_stage_policy, source_fingerprint, original_finalizer_input_hash,
        semantic_input_fingerprint, payload_hash, idempotency_key,
        male_count, female_count, unknown_count
    ) VALUES (
        p_request_id, COALESCE(v_current.revision_number, 0) + 1, 'published',
        'ai-stage-policy-v2.10', 'ai-stage-policy-v2.11', p_source_fingerprint,
        v_summary.finalizer_input_hash, p_semantic_input_fingerprint, v_payload_hash,
        p_idempotency_key, p_male_count, p_female_count, p_unknown_count
    ) RETURNING * INTO v_revision;
    INSERT INTO public.analysis_v2_result_revision_female_rows (
        revision_id, candidate_id, sort_ordinal, instagram_id, full_name,
        profile_image_url, bio, display_score, risk_band, featured_rank,
        recent_mutual_rank, analysis_depth, one_line_overview,
        narrative_line_one, narrative_line_two
    )
    SELECT v_revision.revision_id, item.value->>'candidateId',
        (item.value->>'sortOrdinal')::SMALLINT, item.value->>'instagramId',
        NULLIF(item.value->>'fullName', ''), NULLIF(item.value->>'profileImageUrl', ''),
        NULLIF(item.value->>'bio', ''), (item.value->>'displayScore')::NUMERIC,
        item.value->>'riskBand', NULLIF(item.value->>'featuredRank', '')::SMALLINT,
        NULLIF(item.value->>'recentMutualRank', '')::SMALLINT,
        item.value->>'analysisDepth', item.value->>'oneLineOverview',
        CASE WHEN item.value->'highRiskNarrative' = 'null'::JSONB THEN NULL ELSE item.value->'highRiskNarrative'->>0 END,
        CASE WHEN item.value->'highRiskNarrative' = 'null'::JSONB THEN NULL ELSE item.value->'highRiskNarrative'->>1 END
    FROM pg_catalog.jsonb_array_elements(p_female_rows) AS item(value);
    RETURN pg_catalog.jsonb_build_object(
        'revisionId', v_revision.revision_id,
        'revisionNumber', v_revision.revision_number,
        'payloadHash', v_revision.payload_hash,
        'idempotent', false
    );
END;
$_$;


--
-- Name: archive_earlybird_concierge_snapshot_conflict_recovery(uuid, uuid, text, character varying, character varying, timestamp with time zone, timestamp with time zone, integer, integer, integer, integer, integer, integer, timestamp with time zone, timestamp with time zone, text, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_earlybird_concierge_snapshot_conflict_recovery(p_order_id uuid, p_preflight_id uuid, p_provider_operation_key text, p_provider_input_hash character varying, p_provider_run_id_hash character varying, p_expected_manual_review_at timestamp with time zone, p_expected_admission_refreshed_at timestamp with time zone, p_old_order_followers_count integer, p_old_order_following_count integer, p_old_preflight_followers_count integer, p_old_preflight_following_count integer, p_new_witness_followers_count integer, p_new_witness_following_count integer, p_old_snapshot_recorded_at timestamp with time zone, p_new_witness_recorded_at timestamp with time zone, p_recovery_reason text, p_followers_absolute_delta integer, p_following_absolute_delta integer, p_created_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE
    v_payload JSONB;
    v_target_key_hash TEXT;
    v_state TEXT;
    v_existing_payload JSONB;
    v_existing_content_hash TEXT;
    v_content_hash TEXT;
BEGIN
    IF p_order_id IS NULL OR p_preflight_id IS NULL
       OR p_provider_operation_key IS DISTINCT FROM 'target-profile-fresh-admission:g3'
       OR p_provider_input_hash IS NULL OR p_provider_input_hash !~ '^[a-f0-9]{64}$'
       OR p_provider_run_id_hash IS NULL OR p_provider_run_id_hash !~ '^[a-f0-9]{32}$'
       OR p_expected_manual_review_at IS NULL OR p_expected_admission_refreshed_at IS NULL
       OR p_old_order_followers_count IS DISTINCT FROM 158
       OR p_old_order_following_count IS DISTINCT FROM 361
       OR p_old_preflight_followers_count IS DISTINCT FROM 158
       OR p_old_preflight_following_count IS DISTINCT FROM 361
       OR p_new_witness_followers_count IS DISTINCT FROM 158
       OR p_new_witness_following_count IS DISTINCT FROM 362
       OR p_old_snapshot_recorded_at IS NULL OR p_new_witness_recorded_at IS NULL
       OR p_recovery_reason IS DISTINCT FROM 'bounded_time_snapshot_drift'
       OR p_followers_absolute_delta IS DISTINCT FROM 0
       OR p_following_absolute_delta IS DISTINCT FROM 1
       OR p_created_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_SNAPSHOT_RECEIPT_INVALID', ERRCODE = 'P0001';
    END IF;
    v_payload := pg_catalog.jsonb_build_object(
        'legacy_source_table', 'earlybird_concierge_snapshot_conflict_recoveries',
        'legacy_primary_key', pg_catalog.jsonb_build_object('order_id', p_order_id),
        'legacy_row', pg_catalog.jsonb_build_object(
            'order_id', p_order_id, 'preflight_id', p_preflight_id,
            'provider_operation_key', p_provider_operation_key,
            'provider_input_hash', p_provider_input_hash,
            'provider_run_id_hash', p_provider_run_id_hash,
            'expected_manual_review_at', p_expected_manual_review_at,
            'expected_admission_refreshed_at', p_expected_admission_refreshed_at,
            'old_order_followers_count', p_old_order_followers_count,
            'old_order_following_count', p_old_order_following_count,
            'old_preflight_followers_count', p_old_preflight_followers_count,
            'old_preflight_following_count', p_old_preflight_following_count,
            'new_witness_followers_count', p_new_witness_followers_count,
            'new_witness_following_count', p_new_witness_following_count,
            'old_snapshot_recorded_at', p_old_snapshot_recorded_at,
            'new_witness_recorded_at', p_new_witness_recorded_at,
            'recovery_reason', p_recovery_reason,
            'followers_absolute_delta', p_followers_absolute_delta,
            'following_absolute_delta', p_following_absolute_delta,
            'created_at', p_created_at
        ),
        'schema_version', 1
    );
    v_target_key_hash := pg_catalog.encode(extensions.digest(convert_to(
        'supabase-22-legacy-earlybird-retirement-v1:recovery:earlybird_concierge_snapshot_conflict_recoveries:'
        || (v_payload->'legacy_primary_key')::TEXT, 'UTF8'), 'sha256'), 'hex');
    v_content_hash := pg_catalog.encode(
        extensions.digest(convert_to(v_payload::TEXT, 'UTF8'), 'sha256'), 'hex'
    );
    SELECT job.state, job.payload, job.content_hash
      INTO v_state, v_existing_payload, v_existing_content_hash
    FROM public.maintenance_jobs AS job
    WHERE job.kind = 'recovery'
      AND job.target_key_hash = v_target_key_hash
    FOR UPDATE;
    IF FOUND THEN
        IF v_state IS DISTINCT FROM 'succeeded'
           OR v_existing_payload IS DISTINCT FROM v_payload
           OR v_existing_content_hash IS DISTINCT FROM v_content_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_SNAPSHOT_RECEIPT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN;
    END IF;
    INSERT INTO public.maintenance_jobs(kind, target_key_hash, state, payload, content_hash)
    VALUES ('recovery', v_target_key_hash, 'succeeded', v_payload, v_content_hash);
END;
$_$;


--
-- Name: archive_earlybird_schema_failure_recovery(uuid, uuid, uuid, smallint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_earlybird_schema_failure_recovery(p_order_id uuid, p_failed_request_id uuid, p_recovery_preflight_id uuid, p_prior_attempt_count smallint, p_created_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
    v_payload JSONB;
    v_target_key_hash TEXT;
    v_state TEXT;
    v_existing_payload JSONB;
    v_existing_content_hash TEXT;
BEGIN
    IF p_order_id IS NULL OR p_failed_request_id IS NULL
       OR p_recovery_preflight_id IS NULL OR p_prior_attempt_count IS NULL
       OR p_prior_attempt_count NOT BETWEEN 0 AND 10 OR p_created_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCHEMA_RECEIPT_INVALID', ERRCODE = 'P0001';
    END IF;
    v_payload := pg_catalog.jsonb_build_object(
        'legacy_source_table', 'earlybird_schema_failure_recoveries',
        'legacy_primary_key', pg_catalog.jsonb_build_object('order_id', p_order_id),
        'legacy_row', pg_catalog.jsonb_build_object(
            'order_id', p_order_id,
            'failed_request_id', p_failed_request_id,
            'recovery_preflight_id', p_recovery_preflight_id,
            'prior_attempt_count', p_prior_attempt_count,
            'created_at', p_created_at
        ),
        'schema_version', 1
    );
    v_target_key_hash := pg_catalog.encode(extensions.digest(convert_to(
        'supabase-22-legacy-earlybird-retirement-v1:recovery:earlybird_schema_failure_recoveries:'
        || (v_payload->'legacy_primary_key')::TEXT, 'UTF8'), 'sha256'), 'hex');
    SELECT job.state, job.payload, job.content_hash
      INTO v_state, v_existing_payload, v_existing_content_hash
    FROM public.maintenance_jobs AS job
    WHERE job.kind = 'recovery'
      AND job.target_key_hash = v_target_key_hash
    FOR UPDATE;
    IF FOUND THEN
        IF v_state IS DISTINCT FROM 'succeeded'
           OR v_existing_payload IS DISTINCT FROM v_payload
           OR v_existing_content_hash IS DISTINCT FROM pg_catalog.encode(
                extensions.digest(convert_to(v_payload::TEXT, 'UTF8'), 'sha256'), 'hex'
              ) THEN
            RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCHEMA_RECEIPT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN;
    END IF;
    INSERT INTO public.maintenance_jobs(kind, target_key_hash, state, payload, content_hash)
    VALUES (
        'recovery', v_target_key_hash, 'succeeded', v_payload,
        pg_catalog.encode(extensions.digest(convert_to(v_payload::TEXT, 'UTF8'), 'sha256'), 'hex')
    );
END;
$$;


--
-- Name: archive_earlybird_v211_concierge_replay(uuid, uuid, uuid, uuid, uuid, uuid, smallint, timestamp with time zone, uuid, uuid, text, uuid, jsonb, jsonb, character varying, timestamp with time zone, character varying, character varying, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_earlybird_v211_concierge_replay(p_order_id uuid, p_original_failed_request_id uuid, p_first_relationship_failed_request_id uuid, p_second_relationship_failed_request_id uuid, p_failed_preflight_id uuid, p_rearmed_preflight_id uuid, p_expected_fulfillment_attempt_count smallint, p_expected_manual_review_at timestamp with time zone, p_reviewed_source_request_id uuid, p_reviewed_source_owner_id uuid, p_reviewed_source_target_instagram_id text, p_reviewed_source_result_request_id uuid, p_reviewed_source_target_posts jsonb, p_reviewed_source_target_evidence jsonb, p_reviewed_source_fingerprint character varying, p_reviewed_source_registered_at timestamp with time zone, p_published_source_fingerprint character varying, p_published_result_hash character varying, p_published_at timestamp with time zone, p_created_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
    v_payload JSONB;
    v_target_key_hash TEXT;
    v_content_hash TEXT;
    v_state TEXT;
    v_existing_payload JSONB;
    v_existing_content_hash TEXT;
BEGIN
    IF p_order_id IS NULL OR p_original_failed_request_id IS NULL
       OR p_first_relationship_failed_request_id IS NULL
       OR p_second_relationship_failed_request_id IS NULL
       OR p_failed_preflight_id IS NULL OR p_rearmed_preflight_id IS NULL
       OR p_expected_fulfillment_attempt_count IS DISTINCT FROM 1
       OR p_expected_manual_review_at IS NULL OR p_created_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_REPLAY_RECEIPT_INVALID', ERRCODE = 'P0001';
    END IF;
    v_payload := pg_catalog.jsonb_build_object(
        'legacy_source_table', 'earlybird_v211_concierge_replays',
        'legacy_primary_key', pg_catalog.jsonb_build_object('order_id', p_order_id),
        'legacy_row', pg_catalog.jsonb_build_object(
            'order_id', p_order_id,
            'original_failed_request_id', p_original_failed_request_id,
            'first_relationship_failed_request_id', p_first_relationship_failed_request_id,
            'second_relationship_failed_request_id', p_second_relationship_failed_request_id,
            'failed_preflight_id', p_failed_preflight_id,
            'rearmed_preflight_id', p_rearmed_preflight_id,
            'expected_fulfillment_attempt_count', p_expected_fulfillment_attempt_count,
            'expected_manual_review_at', p_expected_manual_review_at,
            'created_at', p_created_at,
            'reviewed_source_request_id', p_reviewed_source_request_id,
            'reviewed_source_owner_id', p_reviewed_source_owner_id,
            'reviewed_source_target_instagram_id', p_reviewed_source_target_instagram_id,
            'reviewed_source_result_request_id', p_reviewed_source_result_request_id,
            'reviewed_source_target_posts', p_reviewed_source_target_posts,
            'reviewed_source_target_evidence', p_reviewed_source_target_evidence,
            'reviewed_source_fingerprint', p_reviewed_source_fingerprint,
            'reviewed_source_registered_at', p_reviewed_source_registered_at,
            'published_source_fingerprint', p_published_source_fingerprint,
            'published_result_hash', p_published_result_hash,
            'published_at', p_published_at
        ),
        'schema_version', 1
    );
    v_target_key_hash := pg_catalog.encode(extensions.digest(convert_to(
        'supabase-22-legacy-earlybird-retirement-v1:replay:earlybird_v211_concierge_replays:'
        || (v_payload->'legacy_primary_key')::TEXT, 'UTF8'), 'sha256'), 'hex');
    v_content_hash := pg_catalog.encode(
        extensions.digest(convert_to(v_payload::TEXT, 'UTF8'), 'sha256'), 'hex'
    );
    SELECT job.state, job.payload, job.content_hash
      INTO v_state, v_existing_payload, v_existing_content_hash
    FROM public.maintenance_jobs AS job
    WHERE job.kind = 'replay'
      AND job.target_key_hash = v_target_key_hash
    FOR UPDATE;
    IF FOUND THEN
        IF v_state IS DISTINCT FROM 'succeeded'
           OR v_existing_payload IS DISTINCT FROM v_payload
           OR v_existing_content_hash IS DISTINCT FROM v_content_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_REPLAY_RECEIPT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN;
    END IF;
    INSERT INTO public.maintenance_jobs(kind, target_key_hash, state, payload, content_hash)
    VALUES ('replay', v_target_key_hash, 'succeeded', v_payload, v_content_hash);
END;
$$;


--
-- Name: archive_earlybird_v211_concierge_reviewed_source(uuid, uuid, uuid, text, uuid, jsonb, jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_earlybird_v211_concierge_reviewed_source(p_order_id uuid, p_source_request_id uuid, p_owner_id uuid, p_target_instagram_id text, p_result_request_id uuid, p_target_posts jsonb, p_target_evidence jsonb, p_source_fingerprint text, p_registered_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
    v_id UUID;
    v_payload JSONB;
    v_row JSONB;
    v_next_payload JSONB;
BEGIN
    PERFORM public.assert_earlybird_receipt_archive_purge_safe();
    SELECT job.id, job.payload INTO v_id, v_payload
    FROM public.maintenance_jobs AS job
    WHERE job.kind = 'replay'
      AND job.state = 'succeeded'
      AND job.payload->>'legacy_source_table' = 'earlybird_v211_concierge_replays'
      AND job.payload->'legacy_primary_key'->>'order_id' = p_order_id::TEXT
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_REVIEWED_SOURCE_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    v_row := v_payload->'legacy_row';
    IF v_row->>'reviewed_source_fingerprint' IS NOT NULL THEN
        IF v_row->>'reviewed_source_fingerprint' = p_source_fingerprint
           AND v_row->>'reviewed_source_request_id' = p_source_request_id::TEXT
           AND v_row->>'reviewed_source_owner_id' = p_owner_id::TEXT
           AND v_row->>'reviewed_source_target_instagram_id' = p_target_instagram_id
           AND v_row->>'reviewed_source_result_request_id' = p_result_request_id::TEXT
           AND v_row->'reviewed_source_target_posts' IS NOT DISTINCT FROM p_target_posts
           AND v_row->'reviewed_source_target_evidence' IS NOT DISTINCT FROM p_target_evidence THEN
            RETURN FALSE;
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_REVIEWED_SOURCE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF p_source_request_id IS NULL OR p_owner_id IS NULL OR p_result_request_id IS NULL
       OR p_target_instagram_id IS NULL OR p_target_posts IS NULL OR p_target_evidence IS NULL
       OR p_source_fingerprint IS NULL OR p_registered_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_REVIEWED_SOURCE_INVALID', ERRCODE = 'P0001';
    END IF;
    v_next_payload := pg_catalog.jsonb_set(
        v_payload, '{legacy_row}',
        v_row || pg_catalog.jsonb_build_object(
            'reviewed_source_request_id', p_source_request_id,
            'reviewed_source_owner_id', p_owner_id,
            'reviewed_source_target_instagram_id', p_target_instagram_id,
            'reviewed_source_result_request_id', p_result_request_id,
            'reviewed_source_target_posts', p_target_posts,
            'reviewed_source_target_evidence', p_target_evidence,
            'reviewed_source_fingerprint', p_source_fingerprint,
            'reviewed_source_registered_at', p_registered_at
        )
    );
    UPDATE public.maintenance_jobs
    SET payload = v_next_payload,
        content_hash = pg_catalog.encode(
            extensions.digest(convert_to(v_next_payload::TEXT, 'UTF8'), 'sha256'), 'hex'
        ),
        updated_at = pg_catalog.clock_timestamp()
    WHERE id = v_id;
    RETURN TRUE;
END;
$$;


--
-- Name: archive_fully_settled_analysis_beta_apify_credit_allocations(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_fully_settled_analysis_beta_apify_credit_allocations(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '1s'
    SET statement_timeout TO '5s'
    AS $$
DECLARE v_id UUID; DECLARE v_count INTEGER:=0; BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_SETTLEMENT_INVALID', ERRCODE='P0001'; END IF;
 FOR v_id IN SELECT allocation.id FROM public.analysis_beta_pool_allocations allocation JOIN public.users users ON users.id=allocation.user_id
  -- Preserve the short idempotent terminal replay window. Capacity was already
  -- released by settlement; archival itself is deliberately not urgent.
  WHERE allocation.lifecycle_state='settled' AND allocation.settled_at <= pg_catalog.clock_timestamp() - INTERVAL '1 hour' ORDER BY allocation.updated_at,allocation.id LIMIT p_limit FOR UPDATE OF users SKIP LOCKED LOOP
  BEGIN
  IF (SELECT pg_catalog.count(*) FROM public.analysis_beta_pool_reservations reservation WHERE reservation.allocation_id=v_id) <> 8
     OR EXISTS (SELECT 1 FROM public.analysis_beta_pool_reservations reservation WHERE reservation.allocation_id=v_id AND reservation.lifecycle_state <> 'settled') THEN
    RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_POOL_ARCHIVE_CONFLICT', ERRCODE='P0001';
  END IF;
  INSERT INTO public.analysis_beta_pool_reservation_archive(allocation_id,operation_family,credential_slot,reserved_usd,actual_usd,released_usd,reconciliation_watermark,settled_at,settlement_reason,archive_state,unabsorbed_debit_usd)
   SELECT reservation.allocation_id,reservation.operation_family,reservation.credential_slot,reservation.reserved_usd,reservation.actual_usd,reservation.released_usd,reservation.reconciliation_watermark,reservation.settled_at,reservation.settlement_reason,'settled',reservation.actual_usd FROM public.analysis_beta_pool_reservations reservation WHERE reservation.allocation_id=v_id
   ON CONFLICT (allocation_id,operation_family) DO NOTHING;
  IF (SELECT pg_catalog.count(*) FROM public.analysis_beta_pool_reservation_archive archive WHERE archive.allocation_id=v_id) <> 8
     OR EXISTS (SELECT 1 FROM public.analysis_beta_pool_reservations reservation LEFT JOIN public.analysis_beta_pool_reservation_archive archive ON archive.allocation_id=reservation.allocation_id AND archive.operation_family=reservation.operation_family WHERE reservation.allocation_id=v_id AND (archive.operation_family IS NULL OR archive.credential_slot IS DISTINCT FROM reservation.credential_slot OR archive.reserved_usd IS DISTINCT FROM reservation.reserved_usd OR archive.actual_usd IS DISTINCT FROM reservation.actual_usd OR archive.released_usd IS DISTINCT FROM reservation.released_usd OR archive.reconciliation_watermark IS DISTINCT FROM reservation.reconciliation_watermark OR archive.settled_at IS DISTINCT FROM reservation.settled_at OR archive.settlement_reason IS DISTINCT FROM reservation.settlement_reason OR archive.archive_state <> 'settled' OR archive.unabsorbed_debit_usd IS DISTINCT FROM reservation.actual_usd)) THEN
    RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_POOL_ARCHIVE_CONFLICT', ERRCODE='P0001';
  END IF;
  DELETE FROM public.analysis_beta_pool_allocations allocation WHERE allocation.id=v_id; v_count:=v_count+1;
  EXCEPTION WHEN SQLSTATE 'P0001' THEN
    -- Corrupt/partial immutable history stays live for explicit operator repair;
    -- the exception subtransaction rolls back any attempted archive inserts.
    NULL;
  END;
 END LOOP; RETURN v_count;
END; $$;


--
-- Name: archive_settled_analysis_beta_apify_credit_allocations(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_settled_analysis_beta_apify_credit_allocations(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '1s'
    SET statement_timeout TO '5s'
    AS $$ SELECT public.archive_fully_settled_analysis_beta_apify_credit_allocations(p_limit) $$;


--
-- Name: arm_analysis_v2_replay_capture(uuid, text, text, text, integer, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.arm_analysis_v2_replay_capture(p_preflight_id uuid, p_expected_policy_hash text, p_expected_context_hash text, p_recipient_key_fingerprint text, p_expected_public_count integer, p_expected_private_count integer, p_expected_fragment_count integer, p_operator_fingerprint text, p_reason_code text) RETURNS TABLE(capture_id uuid, write_lease_token uuid, write_lease_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_capture_id UUID;
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_policy_hash TEXT;
    v_snapshot_hash TEXT;
    v_context_hash TEXT;
    v_target TEXT;
    v_target_commitment TEXT;
    v_write_lease_token UUID;
    v_write_lease_expires_at TIMESTAMPTZ;
BEGIN
    IF p_expected_policy_hash !~ '^[a-f0-9]{64}$'
       OR p_expected_context_hash !~ '^[a-f0-9]{64}$'
       OR p_recipient_key_fingerprint !~ '^[a-f0-9]{64}$'
       OR p_operator_fingerprint !~ '^[a-f0-9]{64}$'
       OR p_reason_code !~ '^[A-Z0-9_]{1,64}$'
       OR p_expected_public_count NOT BETWEEN 0 AND 256
       OR p_expected_private_count NOT BETWEEN 0 AND 256
       OR p_expected_fragment_count NOT BETWEEN 1 AND 128 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_CAPTURE_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.status = 'ready'
      AND preflight.access_mode = 'production'
      AND preflight.consumed_request_id IS NULL
      AND preflight.expires_at > v_now
      AND preflight.user_id IS NOT NULL
      AND pg_catalog.lower(pg_catalog.btrim(preflight.target_instagram_id))
            ~ '^[a-z0-9._]{1,30}$'
      AND public.analysis_v2_replay_capture_policy_is_exact(
            preflight.policy_versions_snapshot
      )
      AND preflight.plan_cards_snapshot->'standard'->>'launchStatus' = 'production'
      AND preflight.plan_cards_snapshot->'standard'->>'selectionState' IN ('required', 'available_upgrade')
      AND preflight.target_followers_count BETWEEN 0
          AND (preflight.plan_cards_snapshot->'standard'->'relationshipCapacity'->>'followers')::INTEGER
      AND preflight.target_following_count BETWEEN 0
          AND (preflight.plan_cards_snapshot->'standard'->'relationshipCapacity'->>'following')::INTEGER
      AND (preflight.plan_cards_snapshot->'standard'->'relationshipCapacity'->>'followers')::INTEGER BETWEEN 1 AND 10000000
      AND (preflight.plan_cards_snapshot->'standard'->'relationshipCapacity'->>'following')::INTEGER BETWEEN 1 AND 10000000
      AND (preflight.plan_cards_snapshot->'standard'->>'detailedMutualLimit')::INTEGER BETWEEN 1 AND 100000
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_CAPTURE_PREFLIGHT_REJECTED', ERRCODE = 'P0001';
    END IF;
    IF EXISTS (SELECT 1 FROM public.analysis_v2_replay_capture_authorizations WHERE preflight_id = p_preflight_id) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_CAPTURE_ALREADY_ARMED', ERRCODE = 'P0001';
    END IF;
    v_target := pg_catalog.lower(pg_catalog.btrim(v_preflight.target_instagram_id));
    v_policy_hash := pg_catalog.encode(extensions.digest(v_preflight.policy_versions_snapshot::TEXT, 'sha256'), 'hex');
    IF v_policy_hash IS DISTINCT FROM p_expected_policy_hash THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_CAPTURE_POLICY_MISMATCH', ERRCODE = 'P0001';
    END IF;
    v_context_hash := pg_catalog.encode(
        extensions.digest(
            'replay-capture-context-v1' || pg_catalog.chr(10)
            || v_preflight.user_id::TEXT || pg_catalog.chr(10)
            || v_target || pg_catalog.chr(10)
            || v_preflight.policy_versions_snapshot::TEXT,
            'sha256'
        ),
        'hex'
    );
    IF v_context_hash IS DISTINCT FROM p_expected_context_hash THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_CAPTURE_CONTEXT_MISMATCH', ERRCODE = 'P0001';
    END IF;
    v_target_commitment := pg_catalog.encode(
        extensions.digest(
            'replay-target-v1' || pg_catalog.chr(10)
            || v_preflight.user_id::TEXT || pg_catalog.chr(10) || v_target,
            'sha256'
        ),
        'hex'
    );
    v_snapshot_hash := pg_catalog.encode(extensions.digest(pg_catalog.jsonb_build_object('policy', v_preflight.policy_versions_snapshot, 'planCards', v_preflight.plan_cards_snapshot)::TEXT, 'sha256'), 'hex');
    v_write_lease_token := extensions.gen_random_uuid();
    v_write_lease_expires_at := v_now + INTERVAL '15 minutes';
    INSERT INTO public.analysis_v2_replay_capture_authorizations AS inserted_authorization (
        preflight_id, owner_user_id, target_handle_commitment,
        recipient_key_fingerprint, expected_policy_hash, expected_snapshot_hash,
        expected_context_hash, scheduler_policy_version,
        armed_at, arm_expires_at, artifact_expires_at,
        write_lease_token, write_lease_acquired_at, write_lease_expires_at,
        expected_public_count, expected_private_count, expected_fragment_count
    ) VALUES (
        p_preflight_id, v_preflight.user_id, v_target_commitment,
        p_recipient_key_fingerprint, p_expected_policy_hash, v_snapshot_hash,
        p_expected_context_hash, 'ai-scheduler-v1',
        v_now,
        v_now + INTERVAL '4 hours', v_now + INTERVAL '24 hours',
        v_write_lease_token, v_now, v_write_lease_expires_at,
        p_expected_public_count, p_expected_private_count, p_expected_fragment_count
    ) RETURNING inserted_authorization.capture_id INTO v_capture_id;
    INSERT INTO public.analysis_v2_replay_capture_audit_events (capture_id, event_type, operator_fingerprint, reason_code)
    VALUES (v_capture_id, 'arm', p_operator_fingerprint, p_reason_code);
    RETURN QUERY SELECT
        v_capture_id,
        v_write_lease_token,
        v_write_lease_expires_at;
END;
$_$;


--
-- Name: assemble_analysis_order_audit_bundle(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assemble_analysis_order_audit_bundle(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_summary public.analysis_v2_result_summaries%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_existing public.analysis_order_audit_bundles%ROWTYPE;
    v_latest public.analysis_order_audit_bundles%ROWTYPE;
    v_followers RECORD;
    v_following RECORD;
    v_relationship RECORD;
    v_target_evidence RECORD;
    v_cost RECORD;
    v_order_id UUID;
    v_target_username TEXT;
    v_risk_policy TEXT;
    v_ai_policy TEXT;
    v_scheduler_policy TEXT;
    v_plan_id TEXT;
    v_access_mode TEXT;
    v_target_profile_available BOOLEAN := FALSE;
    v_target_posts_available BOOLEAN := FALSE;
    v_target_post_count INTEGER;
    v_followers_declared INTEGER;
    v_followers_collected INTEGER;
    v_following_declared INTEGER;
    v_following_collected INTEGER;
    v_mutual_total INTEGER := 0;
    v_public_total INTEGER := 0;
    v_private_total INTEGER := 0;
    v_screened_total INTEGER := 0;
    v_mutual_rows_collected INTEGER := 0;
    v_candidate_declared INTEGER := 0;
    v_candidate_collected INTEGER := 0;
    v_interaction_declared INTEGER := 0;
    v_interaction_collected INTEGER := 0;
    v_target_likes_declared INTEGER;
    v_target_likes_collected INTEGER;
    v_target_comments_declared INTEGER;
    v_target_comments_collected INTEGER;
    v_candidate_likes_declared INTEGER;
    v_candidate_likes_collected INTEGER;
    v_candidate_likes_evidence_collected INTEGER;
    v_score_collected INTEGER := 0;
    v_tags_declared INTEGER;
    v_tags_collected INTEGER;
    v_mentions_declared INTEGER;
    v_mentions_collected INTEGER;
    v_target_interaction_max_ordinal INTEGER := 0;
    v_reverse_manifest_exists BOOLEAN := FALSE;
    v_mutual_list_hash VARCHAR(64);
    v_source_set_json JSONB := '{}'::JSONB;
    v_retained_source_set_hash VARCHAR(64);
    v_source_set_hash VARCHAR(64);
    v_cost_source_hash VARCHAR(64);
    v_provider_runs JSONB := '[]'::JSONB;
    v_stage_status JSONB := '{}'::JSONB;
    v_candidate_key_coverage JSONB := '{}'::JSONB;
    v_bundle_hash VARCHAR(64);
    v_previous_hash VARCHAR(64);
    v_version INTEGER;
    v_gaps TEXT[] := ARRAY[]::TEXT[];
    v_cost_missing TEXT[] := ARRAY[]::TEXT[];
    v_cost_status TEXT := 'not_available';
    v_cost_known NUMERIC;
    v_cost_conservative NUMERIC;
    v_total_known NUMERIC;
    v_total_conservative NUMERIC;
    v_cost_usage_unknown BOOLEAN := TRUE;
    v_cost_complete BOOLEAN := FALSE;
    v_cost_provenance JSONB := '{}'::JSONB;
    v_preflight_usage_unknown INTEGER := 0;
    v_provider_usage_unknown INTEGER := 0;
    v_ai_usage_unknown INTEGER := 0;
    v_vertex_unmatched INTEGER := 0;
    v_vertex_usage_unknown INTEGER := 0;
    v_vertex_duplicate INTEGER := 0;
    v_vertex_mismatch INTEGER := 0;
    v_relationship_ready BOOLEAN := FALSE;
    v_target_evidence_ready BOOLEAN := FALSE;
    v_features_ready BOOLEAN := FALSE;
    v_scores_ready BOOLEAN := FALSE;
    v_finalized BOOLEAN := FALSE;
    v_inconsistent BOOLEAN := FALSE;
    v_reuse_latest BOOLEAN := FALSE;
    v_queue_fenced BOOLEAN := FALSE;
    v_purge_fenced_at TIMESTAMPTZ;
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_ORDER_AUDIT_INVALID_REQUEST', ERRCODE = 'P0001';
    END IF;

    -- One request lock covers queue state, source reads, append, and the retry purge fence.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_request_id::TEXT, 0)
    );

    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id AND request.pipeline_version = 'v2';
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    SELECT bundle.* INTO v_latest
    FROM public.analysis_order_audit_bundles AS bundle
    WHERE bundle.request_id = p_request_id
    ORDER BY bundle.version DESC
    LIMIT 1;
    SELECT queue.purge_fenced_at IS NOT NULL, queue.purge_fenced_at
      INTO v_queue_fenced, v_purge_fenced_at
    FROM public.analysis_order_audit_assembly_queue AS queue
    WHERE queue.request_id = p_request_id;
    v_queue_fenced := COALESCE(v_queue_fenced, FALSE);
    -- Keep the durable freshness fence strict even when the database clock has only millisecond
    -- resolution or moves backwards between the failed terminal attempt and its retry.
    IF v_purge_fenced_at IS NOT NULL AND v_now <= v_purge_fenced_at THEN
        v_now := v_purge_fenced_at + INTERVAL '1 microsecond';
    END IF;

    INSERT INTO public.analysis_order_audit_assembly_queue(request_id, status, updated_at)
    VALUES (p_request_id, 'processing', v_now)
    ON CONFLICT (request_id) DO UPDATE SET
        status = 'processing',
        lease_token = NULL,
        lease_expires_at = NULL,
        updated_at = v_now;

    SELECT summary.* INTO v_summary
    FROM public.analysis_v2_result_summaries AS summary
    WHERE summary.request_id = p_request_id;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_request.preflight_id;
    SELECT earlybird_order.id INTO v_order_id
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.result_request_id = p_request_id
    ORDER BY earlybird_order.id
    LIMIT 1;

    v_target_username := COALESCE(
        NULLIF(v_summary.target_instagram_id, ''),
        NULLIF(v_preflight.target_instagram_id, '')
    );
    v_target_profile_available := v_summary.request_id IS NOT NULL
        OR (
            v_preflight.target_followers_count IS NOT NULL
            AND v_preflight.target_following_count IS NOT NULL
        );
    v_plan_id := COALESCE(
        NULLIF(v_request.selected_plan_id_snapshot, ''),
        NULLIF(v_summary.plan_id, '')
    );
    v_access_mode := v_request.plan_access_mode_snapshot;
    v_risk_policy := COALESCE(
        v_request.policy_versions_snapshot->>'risk',
        v_summary.score_policy_version
    );
    v_ai_policy := v_request.policy_versions_snapshot->>'aiStage';
    v_scheduler_policy := v_request.policy_versions_snapshot->>'scheduler';
    v_finalized := v_request.status IN ('completed', 'failed');

    IF v_target_username IS NULL THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'TARGET_ID_MISSING');
    END IF;
    IF NOT v_target_profile_available THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'TARGET_PROFILE_MISSING');
    END IF;
    IF v_summary.request_id IS NULL THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'RESULT_SUMMARY_MISSING');
    END IF;

    SELECT side.declared_count, side.collected_count, side.result_hash,
           side.input_hash, side.provider, side.provider_run_id,
           side.provider_operation_key, side.provider_credential_slot,
           side.job_key
      INTO v_followers
      FROM public.analysis_v2_relationship_sides AS side
     WHERE side.request_id = p_request_id AND side.side = 'followers'
     ORDER BY side.updated_at DESC NULLS LAST, side.job_key DESC
     LIMIT 1;
    SELECT side.declared_count, side.collected_count, side.result_hash,
           side.input_hash, side.provider, side.provider_run_id,
           side.provider_operation_key, side.provider_credential_slot,
           side.job_key
      INTO v_following
      FROM public.analysis_v2_relationship_sides AS side
     WHERE side.request_id = p_request_id AND side.side = 'following'
     ORDER BY side.updated_at DESC NULLS LAST, side.job_key DESC
     LIMIT 1;

    IF v_followers.declared_count IS NULL THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'FOLLOWERS_SOURCE_MISSING');
    ELSE
        v_followers_declared := v_followers.declared_count;
        v_followers_collected := v_followers.collected_count;
        v_relationship_ready := TRUE;
    END IF;
    IF v_following.declared_count IS NULL THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'FOLLOWING_SOURCE_MISSING');
        v_relationship_ready := FALSE;
    ELSE
        v_following_declared := v_following.declared_count;
        v_following_collected := v_following.collected_count;
    END IF;
    IF v_followers.declared_count IS NOT NULL
       AND v_following.declared_count IS NOT NULL
       AND (
           v_followers.collected_count IS DISTINCT FROM v_followers.declared_count
           OR v_following.collected_count IS DISTINCT FROM v_following.declared_count
       ) THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'RELATIONSHIP_COUNT_GAP');
        v_inconsistent := TRUE;
    END IF;

    SELECT manifest.job_key, manifest.result_hash, manifest.mutual_count,
           manifest.public_count, manifest.private_count,
           manifest.detailed_public_count, manifest.excluded_username,
           manifest.exclusion_decision_hash, manifest.followers_result_hash,
           manifest.following_result_hash, manifest.detailed_mutual_limit
      INTO v_relationship
      FROM public.analysis_v2_relationship_manifests AS manifest
     WHERE manifest.request_id = p_request_id
     ORDER BY manifest.updated_at DESC NULLS LAST, manifest.job_key DESC
     LIMIT 1;
    IF v_relationship.mutual_count IS NULL THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'MUTUAL_MANIFEST_MISSING');
    ELSE
        v_mutual_total := v_relationship.mutual_count;
        v_public_total := COALESCE(v_relationship.public_count, 0);
        v_private_total := COALESCE(v_relationship.private_count, 0);
        v_screened_total := COALESCE(v_relationship.detailed_public_count, 0);
    END IF;

    -- The relationship intersection itself is authoritative. Compare its keys with the copied
    -- mutual rows, retaining an explicit gap for both omissions and unexpected extras.
    IF v_relationship.job_key IS NOT NULL
       AND EXISTS (
           WITH follower_keys AS (
               SELECT DISTINCT row.username
               FROM public.analysis_v2_relationship_rows AS row
               WHERE row.request_id = p_request_id
                 AND row.job_key = v_relationship.job_key
                 AND row.side = 'followers'
           ),
           following_keys AS (
               SELECT DISTINCT row.username
               FROM public.analysis_v2_relationship_rows AS row
               WHERE row.request_id = p_request_id
                 AND row.job_key = v_relationship.job_key
                 AND row.side = 'following'
           ),
           expected_keys AS (
               SELECT username FROM follower_keys
               INTERSECT
               SELECT username FROM following_keys
           ),
           copied_keys AS (
               SELECT DISTINCT mutual.username
               FROM public.analysis_v2_mutual_rows AS mutual
               WHERE mutual.request_id = p_request_id
                 AND mutual.job_key = v_relationship.job_key
           )
           SELECT 1
           FROM (
               (SELECT username FROM expected_keys
                EXCEPT SELECT username FROM copied_keys)
               UNION ALL
               (SELECT username FROM copied_keys
                EXCEPT SELECT username FROM expected_keys)
           ) AS difference
       ) THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'CANDIDATE_KEY_SET_GAP');
        v_inconsistent := TRUE;
    END IF;

    SELECT target_manifest.job_key, target_manifest.result_hash,
           target_manifest.input_hash, target_manifest.target_username,
           target_manifest.interactor_count, target_manifest.liker_count,
           target_manifest.comment_count, target_manifest.liker_source,
           target_manifest.comment_source, target_manifest.liker_source_hash,
           target_manifest.comment_source_hash
      INTO v_target_evidence
     FROM public.analysis_v2_target_evidence_manifests AS target_manifest
     WHERE target_manifest.request_id = p_request_id
     ORDER BY target_manifest.updated_at DESC NULLS LAST, target_manifest.job_key DESC
     LIMIT 1;
    IF v_target_evidence.job_key IS NULL
       OR v_target_evidence.interactor_count IS NULL
       OR v_target_evidence.liker_count IS NULL
       OR v_target_evidence.comment_count IS NULL
       OR NOT public.analysis_v2_valid_target_evidence_source(
           'target_post_like', v_target_evidence.liker_source
       )
       OR NOT public.analysis_v2_valid_target_evidence_source(
           'target_post_comment', v_target_evidence.comment_source
       )
       OR v_target_evidence.liker_count + v_target_evidence.comment_count
            IS DISTINCT FROM v_target_evidence.interactor_count THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'TARGET_POSTS_MISSING');
    ELSE
        SELECT pg_catalog.count(*)::INTEGER
          INTO v_target_post_count
          FROM (
              SELECT coverage.value->>'post_id' AS post_id
              FROM pg_catalog.jsonb_array_elements(
                  v_target_evidence.liker_source->'coverage'
              ) AS coverage(value)
              UNION
              SELECT coverage.value->>'post_id' AS post_id
              FROM pg_catalog.jsonb_array_elements(
                  v_target_evidence.comment_source->'coverage'
              ) AS coverage(value)
          ) AS target_posts;
        v_target_posts_available := v_target_post_count > 0;
        v_target_evidence_ready := TRUE;
        v_target_likes_declared := v_target_evidence.liker_count;
        v_target_comments_declared := v_target_evidence.comment_count;
    END IF;

    SELECT pg_catalog.count(*)::INTEGER
      INTO v_mutual_rows_collected
      FROM public.analysis_v2_mutual_rows AS mutual
     WHERE mutual.request_id = p_request_id
       AND (
           v_relationship.job_key IS NULL
           OR mutual.job_key = v_relationship.job_key
       );
    v_candidate_declared := COALESCE(v_relationship.mutual_count, v_mutual_rows_collected);
    v_candidate_collected := v_mutual_rows_collected;
    IF v_relationship.mutual_count IS NOT NULL
       AND v_mutual_rows_collected <> v_relationship.mutual_count THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'MUTUAL_ROWS_MISSING');
        v_inconsistent := TRUE;
    ELSIF v_relationship.mutual_count IS NULL AND v_mutual_rows_collected = 0 THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'MUTUAL_ROWS_MISSING');
    END IF;

    IF v_mutual_rows_collected > 0 THEN
        v_mutual_list_hash := public.analysis_order_audit_digest(COALESCE((
            SELECT pg_catalog.jsonb_agg(
                public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(mutual))
                ORDER BY mutual.mutual_ordinal, mutual.username
            )::TEXT
            FROM public.analysis_v2_mutual_rows AS mutual
            WHERE mutual.request_id = p_request_id
              AND (
                  v_relationship.job_key IS NULL
                  OR mutual.job_key = v_relationship.job_key
              )
        ), '[]'));
    ELSE
        v_mutual_list_hash := public.analysis_order_audit_digest('[]');
    END IF;

    v_candidate_key_coverage :=
        public.analysis_order_audit_candidate_key_coverage(p_request_id);
    IF pg_catalog.jsonb_array_length(
           COALESCE(v_candidate_key_coverage->'missing', '[]'::JSONB)
       ) > 0
       OR pg_catalog.jsonb_array_length(
           COALESCE(v_candidate_key_coverage->'extra', '[]'::JSONB)
       ) > 0 THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'CANDIDATE_KEY_SET_GAP');
        v_inconsistent := TRUE;
    END IF;
    v_features_ready := COALESCE((v_candidate_key_coverage->>'complete')::BOOLEAN, FALSE);
    IF v_public_total > 0 AND NOT v_features_ready THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'CANDIDATE_FEATURES_MISSING');
    END IF;

    SELECT
        count(*) FILTER (WHERE interaction.signal = 'target_post_like')::INTEGER,
        count(*) FILTER (WHERE interaction.signal = 'target_post_comment')::INTEGER,
        COALESCE(max(interaction.ordinal), 0)::INTEGER
      INTO v_target_likes_collected, v_target_comments_collected,
           v_target_interaction_max_ordinal
      FROM public.analysis_target_interactors AS interaction
     WHERE interaction.request_id = p_request_id
       AND (
           v_target_evidence.job_key IS NULL
           OR interaction.job_key = v_target_evidence.job_key
       );
    IF NOT v_target_evidence_ready
       AND v_target_likes_collected = 0
       AND v_target_comments_collected = 0 THEN
        v_target_likes_collected := NULL;
        v_target_comments_collected := NULL;
    END IF;
    IF v_target_evidence.interactor_count IS NOT NULL
       AND v_target_likes_collected + v_target_comments_collected
            IS DISTINCT FROM v_target_evidence.interactor_count THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'INTERACTION_ROWS_GAP');
        v_inconsistent := TRUE;
    END IF;
    IF v_target_likes_declared IS NOT NULL
       AND v_target_likes_collected <> v_target_likes_declared THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'TARGET_LIKES_ROWS_GAP');
        v_inconsistent := TRUE;
    END IF;
    IF v_target_comments_declared IS NOT NULL
       AND v_target_comments_collected <> v_target_comments_declared THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'TARGET_COMMENTS_ROWS_GAP');
        v_inconsistent := TRUE;
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM public.analysis_v2_reverse_like_manifests AS manifest
        WHERE manifest.request_id = p_request_id
    ) INTO v_reverse_manifest_exists;
    IF v_reverse_manifest_exists THEN
        SELECT manifest.item_count
          INTO v_candidate_likes_declared
          FROM public.analysis_v2_reverse_like_manifests AS manifest
         WHERE manifest.request_id = p_request_id;
    END IF;
    SELECT count(*)::INTEGER,
           COALESCE(sum(pg_catalog.cardinality(reverse.evidence_ref_ids)), 0)::INTEGER
      INTO v_candidate_likes_collected, v_candidate_likes_evidence_collected
      FROM public.analysis_v2_reverse_like_rows AS reverse
      WHERE reverse.request_id = p_request_id
       AND EXISTS (
           SELECT 1
           FROM public.analysis_v2_mutual_rows AS mutual
           LEFT JOIN public.analysis_v2_candidate_feature_rows AS feature
             ON feature.request_id = mutual.request_id
            AND feature.instagram_id = mutual.username
           LEFT JOIN public.analysis_v2_private_name_rows AS private_name
             ON private_name.request_id = mutual.request_id
            AND private_name.instagram_id = mutual.username
           WHERE mutual.request_id = p_request_id
             AND (
                 v_relationship.job_key IS NULL
                 OR mutual.job_key = v_relationship.job_key
             )
             AND COALESCE(
                 feature.candidate_id, private_name.candidate_id,
                 'username:' || mutual.username
             ) = reverse.candidate_id
       );
    IF NOT v_reverse_manifest_exists
       AND v_candidate_likes_collected = 0 THEN
        v_candidate_likes_collected := NULL;
        v_candidate_likes_evidence_collected := NULL;
    END IF;
    IF NOT v_reverse_manifest_exists THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'CANDIDATE_LIKES_SOURCE_MISSING');
    ELSIF v_candidate_likes_declared IS DISTINCT FROM v_candidate_likes_collected THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'CANDIDATE_LIKES_ROWS_GAP');
        v_inconsistent := TRUE;
    END IF;

    -- Tags and mentions have no authoritative V2 row ledger. Keep their unknown declaration
    -- explicit and prevent an empty child page from looking complete.
    v_gaps := pg_catalog.array_append(v_gaps, 'TAGS_SOURCE_MISSING');
    v_gaps := pg_catalog.array_append(v_gaps, 'MENTIONS_SOURCE_MISSING');

    v_interaction_declared :=
        COALESCE(v_target_likes_declared, 0)
        + COALESCE(v_target_comments_declared, 0)
        ;
    v_interaction_collected :=
        COALESCE(v_target_likes_collected, 0)
        + COALESCE(v_target_comments_collected, 0)
        + COALESCE(v_candidate_likes_evidence_collected, 0);

    SELECT count(*)::INTEGER
      INTO v_score_collected
      FROM public.analysis_v2_candidate_score_rows AS score
     WHERE score.request_id = p_request_id;
    v_scores_ready := v_score_collected >= COALESCE(v_summary.female_count, 0);
    IF COALESCE(v_summary.female_count, 0) > 0 AND NOT v_scores_ready THEN
        v_gaps := pg_catalog.array_append(v_gaps, 'RISK_SCORES_MISSING');
    END IF;

    SELECT rollup.* INTO v_cost
    FROM public.analysis_v2_cost_rollups AS rollup
    WHERE rollup.request_id = p_request_id
    LIMIT 1;
    v_cost_source_hash := public.analysis_order_audit_cost_source_hash(p_request_id);
    IF v_cost.request_id IS NULL THEN
        v_cost_missing := pg_catalog.array_append(v_cost_missing, 'COST_SOURCE_MISSING');
        v_gaps := pg_catalog.array_append(v_gaps, 'COST_SOURCE_MISSING');
    ELSE
        v_total_known := v_cost.total_known_cost_usd;
        v_total_conservative := v_cost.total_conservative_cost_usd;
        v_cost_usage_unknown := COALESCE(v_cost.usage_unknown, TRUE);
        v_cost_complete := COALESCE(v_cost.directly_attributable_cost_complete, FALSE)
            AND NOT v_cost_usage_unknown;
        v_cost_provenance := public.analysis_order_audit_redact_json(
            COALESCE(v_cost.cost_provenance, '{}'::JSONB)
        );
        v_preflight_usage_unknown := COALESCE(v_cost.preflight_usage_unknown_count, 0);
        v_provider_usage_unknown := COALESCE(v_cost.provider_usage_unknown_count, 0);
        v_ai_usage_unknown := COALESCE(v_cost.ai_usage_unknown_count, 0);
        v_vertex_unmatched := COALESCE(v_cost.vertex_budget_unmatched_count, 0);
        v_vertex_usage_unknown := COALESCE(v_cost.vertex_budget_usage_unknown_count, 0);
        v_vertex_duplicate := COALESCE(v_cost.vertex_budget_duplicate_count, 0);
        v_vertex_mismatch := COALESCE(v_cost.vertex_budget_mismatch_count, 0);
        IF v_cost_usage_unknown THEN
            v_cost_missing := pg_catalog.array_append(v_cost_missing, 'COST_USAGE_UNKNOWN');
            v_gaps := pg_catalog.array_append(v_gaps, 'COST_USAGE_UNKNOWN');
        END IF;
        IF v_preflight_usage_unknown > 0 THEN
            v_cost_missing := pg_catalog.array_append(v_cost_missing, 'PREFLIGHT_USAGE_UNKNOWN');
            v_gaps := pg_catalog.array_append(v_gaps, 'PREFLIGHT_USAGE_UNKNOWN');
        END IF;
        IF v_provider_usage_unknown > 0 THEN
            v_cost_missing := pg_catalog.array_append(v_cost_missing, 'PROVIDER_USAGE_UNKNOWN');
            v_gaps := pg_catalog.array_append(v_gaps, 'PROVIDER_USAGE_UNKNOWN');
        END IF;
        IF v_ai_usage_unknown > 0 THEN
            v_cost_missing := pg_catalog.array_append(v_cost_missing, 'AI_USAGE_UNKNOWN');
            v_gaps := pg_catalog.array_append(v_gaps, 'AI_USAGE_UNKNOWN');
        END IF;
        IF v_vertex_unmatched + v_vertex_usage_unknown + v_vertex_duplicate
             + v_vertex_mismatch > 0 THEN
            v_cost_missing := pg_catalog.array_append(v_cost_missing, 'VERTEX_USAGE_GAP');
            v_gaps := pg_catalog.array_append(v_gaps, 'VERTEX_USAGE_GAP');
        END IF;
    END IF;
    v_cost_status := CASE
        WHEN v_cost.request_id IS NULL THEN 'not_available'
        WHEN v_cost_complete THEN 'complete'
        WHEN v_cost_usage_unknown THEN 'unknown'
        ELSE 'partial'
    END;
    IF NOT v_cost_usage_unknown THEN
        v_cost_known := v_total_known;
    END IF;
    v_cost_conservative := v_total_conservative;
    -- Resolve the authoritative order identity before hashing the request lineage.
    v_order_id := COALESCE(v_order_id, v_cost.order_id);

    -- Once terminal cleanup has removed source rows, carry the immutable rich evidence forward.
    v_reuse_latest := v_latest.request_id IS NOT NULL
        AND v_finalized
        AND v_followers.declared_count IS NULL
        AND v_following.declared_count IS NULL
        AND v_relationship.mutual_count IS NULL
        AND v_target_evidence.interactor_count IS NULL;
    IF v_reuse_latest THEN
        v_retained_source_set_hash := COALESCE(
            v_latest.stage_status->>'retainedEvidenceSourceSetHash',
            v_latest.source_set_hash
        );
        v_target_username := v_latest.target_instagram_id;
        v_target_profile_available := v_latest.target_profile_available;
        v_target_posts_available := v_latest.target_posts_available;
        v_target_post_count := v_latest.target_post_count;
        v_followers_declared := v_latest.followers_declared;
        v_followers_collected := v_latest.followers_collected;
        v_following_declared := v_latest.following_declared;
        v_following_collected := v_latest.following_collected;
        v_mutual_total := v_latest.mutual_total;
        v_mutual_list_hash := v_latest.mutual_list_hash;
        v_public_total := v_latest.public_total;
        v_private_total := v_latest.private_total;
        v_screened_total := v_latest.screened_total;
        v_candidate_declared := v_latest.candidate_declared;
        v_candidate_collected := v_latest.candidate_collected;
        v_interaction_declared := v_latest.interaction_declared;
        v_interaction_collected := v_latest.interaction_collected;
        v_target_likes_declared := v_latest.target_likes_declared;
        v_target_likes_collected := v_latest.target_likes_collected;
        v_target_comments_declared := v_latest.target_comments_declared;
        v_target_comments_collected := v_latest.target_comments_collected;
        v_candidate_likes_declared := v_latest.candidate_likes_declared;
        v_candidate_likes_collected := v_latest.candidate_likes_collected;
        v_candidate_likes_evidence_collected := v_latest.candidate_likes_evidence_collected;
        v_tags_declared := v_latest.tags_declared;
        v_tags_collected := v_latest.tags_collected;
        v_mentions_declared := v_latest.mentions_declared;
        v_mentions_collected := v_latest.mentions_collected;
        v_candidate_key_coverage := v_latest.candidate_key_coverage;
        v_finalized := TRUE;
        v_inconsistent := v_latest.completeness_status = 'inconsistent';
        v_relationship_ready := COALESCE(v_latest.stage_status->>'relationships' = 'true', FALSE);
        v_target_evidence_ready := COALESCE(v_latest.stage_status->>'targetEvidence' = 'true', FALSE);
        v_features_ready := COALESCE(v_latest.stage_status->>'candidateFeatures' = 'true', FALSE);
        v_scores_ready := COALESCE(v_latest.stage_status->>'riskScores' = 'true', FALSE);
        v_risk_policy := COALESCE(v_latest.risk_policy_version, v_risk_policy);
        v_ai_policy := COALESCE(v_latest.ai_policy_version, v_ai_policy);
        v_scheduler_policy := COALESCE(v_latest.scheduler_policy_version, v_scheduler_policy);
        SELECT COALESCE(pg_catalog.array_agg(code ORDER BY code), ARRAY[]::TEXT[])
          INTO v_gaps
          FROM pg_catalog.unnest(v_latest.gap_codes) AS gap(code)
         WHERE code NOT IN (
             'COST_SOURCE_MISSING', 'COST_USAGE_UNKNOWN', 'PREFLIGHT_USAGE_UNKNOWN',
             'PROVIDER_USAGE_UNKNOWN', 'AI_USAGE_UNKNOWN', 'VERTEX_USAGE_GAP'
         );
        v_gaps := v_gaps || v_cost_missing;
    END IF;

    -- Hash the canonical redacted projections of every copied immutable source field. Arrays are
    -- ordered by stable keys; JSONB itself canonicalizes object key order.
    IF v_reuse_latest THEN
        v_source_set_json := pg_catalog.jsonb_build_object(
            'request', pg_catalog.jsonb_build_object(
                'pipelineVersion', v_request.pipeline_version,
                'policyVersions', public.analysis_order_audit_redact_json(
                    COALESCE(v_request.policy_versions_snapshot, '{}'::JSONB)
                ),
                'preflightId', v_request.preflight_id,
                'planId', v_plan_id,
                'accessMode', v_access_mode,
                'orderId', v_order_id,
                'targetUsername', v_target_username,
                'targetProfileAvailable', v_target_profile_available,
                'targetPostsAvailable', v_target_posts_available,
                'targetPostCount', v_target_post_count,
                'finalized', v_finalized
            ),
            'retainedEvidenceSourceSetHash', v_retained_source_set_hash,
            'costSourceHash', v_cost_source_hash
        );
    ELSE
        v_source_set_json := pg_catalog.jsonb_build_object(
            'request', pg_catalog.jsonb_build_object(
                'pipelineVersion', v_request.pipeline_version,
                'policyVersions', public.analysis_order_audit_redact_json(
                    COALESCE(v_request.policy_versions_snapshot, '{}'::JSONB)
                ),
                'preflightId', v_request.preflight_id,
                'planId', v_plan_id,
                'accessMode', v_access_mode,
                'orderId', v_order_id,
                'targetUsername', v_target_username,
                'targetProfileAvailable', v_target_profile_available,
                'targetPostsAvailable', v_target_posts_available,
                'targetPostCount', v_target_post_count,
                'finalized', v_finalized
            ),
            'relationshipSides', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    pg_catalog.jsonb_build_object(
                        'side', side.side,
                        'jobKey', side.job_key,
                        'logicalProvider', side.provider,
                        'credentialSlot', side.provider_credential_slot,
                        'runId', side.provider_run_id,
                        'operationKey', side.provider_operation_key,
                        'inputHash', side.input_hash,
                        'resultHash', side.result_hash,
                        'declared', side.declared_count,
                        'collected', side.collected_count
                    ) ORDER BY side.side, side.job_key
                )
                FROM public.analysis_v2_relationship_sides AS side
                WHERE side.request_id = p_request_id
                  AND (
                      (side.side = 'followers' AND side.job_key = v_followers.job_key)
                      OR (side.side = 'following' AND side.job_key = v_following.job_key)
                  )
            ), '[]'::JSONB),
            'relationshipManifest', COALESCE((
                SELECT public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(manifest))
                FROM public.analysis_v2_relationship_manifests AS manifest
                WHERE manifest.request_id = p_request_id
                ORDER BY manifest.updated_at DESC NULLS LAST, manifest.job_key DESC
                LIMIT 1
            ), '{}'::JSONB),
            'relationshipRows', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(row))
                    ORDER BY row.side, row.ordinal, row.username
                )
                FROM public.analysis_v2_relationship_rows AS row
                WHERE row.request_id = p_request_id
                  AND (
                      v_relationship.job_key IS NULL
                      OR row.job_key = v_relationship.job_key
                  )
            ), '[]'::JSONB),
            'mutualRows', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(mutual))
                    ORDER BY mutual.mutual_ordinal, mutual.username
                )
                FROM public.analysis_v2_mutual_rows AS mutual
                WHERE mutual.request_id = p_request_id
                  AND (
                      v_relationship.job_key IS NULL
                      OR mutual.job_key = v_relationship.job_key
                  )
            ), '[]'::JSONB),
            'targetEvidenceManifest', COALESCE((
                SELECT public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(manifest))
                FROM public.analysis_v2_target_evidence_manifests AS manifest
                WHERE manifest.request_id = p_request_id
                ORDER BY manifest.updated_at DESC NULLS LAST, manifest.job_key DESC
                LIMIT 1
            ), '{}'::JSONB),
            'targetInteractors', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    pg_catalog.jsonb_build_object(
                        'jobKey', interaction.job_key,
                        'ordinal', interaction.ordinal,
                        'actorUsername', interaction.actor_username,
                        'postId', interaction.post_id,
                        'signal', interaction.signal,
                        'sourceInteractionId', interaction.source_interaction_id,
                        'occurredAt', interaction.occurred_at,
                        'commentText', interaction.comment_text,
                        'details', public.analysis_order_audit_redact_json(
                            NULLIF(to_jsonb(interaction)->'details', 'null'::JSONB)
                        )
                    ) ORDER BY interaction.ordinal, interaction.signal,
                        interaction.source_interaction_id
                )
                FROM public.analysis_target_interactors AS interaction
                WHERE interaction.request_id = p_request_id
                  AND (
                      v_target_evidence.job_key IS NULL
                      OR interaction.job_key = v_target_evidence.job_key
                  )
            ), '[]'::JSONB),
            'candidateFeatures', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(feature))
                    ORDER BY feature.instagram_id, feature.candidate_id
                )
                FROM public.analysis_v2_candidate_feature_rows AS feature
                WHERE feature.request_id = p_request_id
            ), '[]'::JSONB),
            'privateNames', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(private_name))
                    ORDER BY private_name.instagram_id, private_name.candidate_id
                )
                FROM public.analysis_v2_private_name_rows AS private_name
                WHERE private_name.request_id = p_request_id
            ), '[]'::JSONB),
            'scoreManifest', COALESCE((
                SELECT public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(manifest))
                FROM public.analysis_v2_candidate_score_manifests AS manifest
                WHERE manifest.request_id = p_request_id
                LIMIT 1
            ), '{}'::JSONB),
            'scoreRows', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(score))
                    ORDER BY score.candidate_id
                )
                FROM public.analysis_v2_candidate_score_rows AS score
                WHERE score.request_id = p_request_id
            ), '[]'::JSONB),
            'femaleResults', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(result))
                    ORDER BY result.sort_ordinal, result.candidate_id
                )
                FROM public.analysis_v2_female_results AS result
                WHERE result.request_id = p_request_id
            ), '[]'::JSONB),
            'aiCheckpoints', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    pg_catalog.jsonb_build_object(
                        'operationKey', checkpoint.operation_key,
                        'stage', checkpoint.stage,
                        'model', checkpoint.model_name,
                        'inputHash', checkpoint.input_hash,
                        'resultHash', checkpoint.result_hash,
                        'result', public.analysis_order_audit_redact_json(checkpoint.result_json)
                    ) ORDER BY checkpoint.operation_key
                )
                FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
                WHERE checkpoint.request_id = p_request_id
            ), '[]'::JSONB),
            'reverseLikeManifest', COALESCE((
                SELECT public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(manifest))
                FROM public.analysis_v2_reverse_like_manifests AS manifest
                WHERE manifest.request_id = p_request_id
                LIMIT 1
            ), '{}'::JSONB),
            'reverseLikeRows', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    public.analysis_order_audit_redact_json(pg_catalog.to_jsonb(reverse))
                    ORDER BY reverse.candidate_id
                )
                FROM public.analysis_v2_reverse_like_rows AS reverse
                WHERE reverse.request_id = p_request_id
            ), '[]'::JSONB),
            'candidateKeyCoverage', v_candidate_key_coverage,
            'candidateFeatureManifestHash', public.analysis_order_audit_source_table_hash(
                'analysis_v2_candidate_feature_manifests', p_request_id
            ),
            'preliminaryScoreManifestHash', public.analysis_order_audit_source_table_hash(
                'analysis_v2_preliminary_score_manifests', p_request_id
            ),
            'partnerSafetyManifestHash', public.analysis_order_audit_source_table_hash(
                'analysis_v2_partner_safety_manifests', p_request_id
            ),
            'narrativeManifestHash', public.analysis_order_audit_source_table_hash(
                'analysis_v2_narrative_manifests', p_request_id
            ),
            'privateNameManifestHash', public.analysis_order_audit_source_table_hash(
                'analysis_v2_private_name_manifests', p_request_id
            ),
            'finalResolution', pg_catalog.jsonb_build_object(
                'summary', public.analysis_order_audit_redact_json(
                    COALESCE(pg_catalog.to_jsonb(v_summary), '{}'::JSONB)
                ),
                'finalizerInputHash', v_summary.finalizer_input_hash
            ),
            'costSourceHash', v_cost_source_hash
        );
        v_retained_source_set_hash := public.analysis_order_audit_digest(
            'analysis-order-audit-retained-v2' || E'\n'
            || (v_source_set_json - 'costSourceHash')::TEXT
        );
    END IF;
    v_source_set_hash := public.analysis_order_audit_digest(
        'analysis-order-audit-source-set-v2' || E'\n' || v_source_set_json::TEXT
    );

    SELECT bundle.* INTO v_existing
    FROM public.analysis_order_audit_bundles AS bundle
    WHERE bundle.request_id = p_request_id
      AND bundle.source_set_hash = v_source_set_hash;
    IF FOUND THEN
        UPDATE public.analysis_order_audit_assembly_queue
           SET status = 'completed', lease_token = NULL, lease_expires_at = NULL,
               updated_at = pg_catalog.clock_timestamp()
         WHERE request_id = p_request_id;
        IF v_queue_fenced AND v_finalized THEN
            PERFORM public.analysis_v2_purge_result_working_set(p_request_id, TRUE);
        END IF;
        RETURN public.analysis_order_audit_bundle_payload(v_existing);
    END IF;

    SELECT bundle.* INTO v_latest
    FROM public.analysis_order_audit_bundles AS bundle
    WHERE bundle.request_id = p_request_id
    ORDER BY bundle.version DESC
    LIMIT 1;
    v_version := COALESCE(v_latest.version, 0) + 1;
    v_previous_hash := v_latest.bundle_hash;
    v_bundle_hash := public.analysis_order_audit_digest(
        'analysis-order-audit-bundle-v2' || E'\n'
        || p_request_id::TEXT || E'\n' || v_version::TEXT || E'\n'
        || COALESCE(v_previous_hash, 'none') || E'\n' || v_source_set_hash
    );

    SELECT COALESCE(pg_catalog.array_agg(code ORDER BY code), ARRAY[]::TEXT[])
      INTO v_gaps
      FROM (
          SELECT DISTINCT code
          FROM pg_catalog.unnest(v_gaps) AS gap(code)
      ) AS unique_gaps;
    SELECT COALESCE(pg_catalog.array_agg(code ORDER BY code), ARRAY[]::TEXT[])
      INTO v_cost_missing
      FROM (
          SELECT DISTINCT code
          FROM pg_catalog.unnest(v_cost_missing) AS gap(code)
      ) AS unique_gaps;

    -- Only the safe lineage aliases are serialized. Source records and provider/account metadata
    -- never cross this boundary.
    SELECT COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
            'stage', run.stage,
            'logicalProvider', run.logical_provider,
            'credentialSlot', run.credential_slot,
            'runId', run.run_id,
            'operationKey', run.operation_key,
            'inputHash', run.input_hash,
            'resultHash', run.result_hash
        ) ORDER BY run.stage
    ), '[]'::JSONB)
      INTO v_provider_runs
      FROM (
          SELECT 'followers'::TEXT AS stage, v_followers.provider AS logical_provider,
                 v_followers.provider_credential_slot AS credential_slot,
                 v_followers.provider_run_id AS run_id,
                 v_followers.provider_operation_key AS operation_key,
                 v_followers.input_hash AS input_hash, v_followers.result_hash AS result_hash
          WHERE v_followers.provider_run_id IS NOT NULL
          UNION ALL
          SELECT 'following', v_following.provider, v_following.provider_credential_slot,
                 v_following.provider_run_id, v_following.provider_operation_key,
                 v_following.input_hash, v_following.result_hash
          WHERE v_following.provider_run_id IS NOT NULL
          UNION ALL
          SELECT 'target_likers', v_target_evidence.liker_source->>'provider',
                 v_target_evidence.liker_source->>'provider_credential_slot',
                 v_target_evidence.liker_source->>'provider_run_id',
                 v_target_evidence.liker_source->>'provider_operation_key',
                 v_target_evidence.liker_source->>'input_hash',
                 v_target_evidence.liker_source_hash
          WHERE v_target_evidence.liker_source->>'provider_run_id' IS NOT NULL
          UNION ALL
          SELECT 'target_comments', v_target_evidence.comment_source->>'provider',
                 v_target_evidence.comment_source->>'provider_credential_slot',
                 v_target_evidence.comment_source->>'provider_run_id',
                 v_target_evidence.comment_source->>'provider_operation_key',
                 v_target_evidence.comment_source->>'input_hash',
                 v_target_evidence.comment_source_hash
          WHERE v_target_evidence.comment_source->>'provider_run_id' IS NOT NULL
      ) AS run;

    v_stage_status := pg_catalog.jsonb_build_object(
        'relationships', v_relationship_ready,
        'targetEvidence', v_target_evidence_ready,
        'candidateFeatures', v_features_ready,
        'riskScores', v_scores_ready,
        'finalized', v_finalized,
        'cost', v_cost_status,
        'costSourceHash', v_cost_source_hash,
        'candidateKeyCoverage', v_candidate_key_coverage,
        'targetLikes', v_target_likes_declared IS NOT NULL,
        'targetComments', v_target_comments_declared IS NOT NULL,
        'candidateLikes', v_candidate_likes_declared IS NOT NULL,
        'tags', FALSE,
        'mentions', FALSE,
        'retainedEvidenceSourceSetHash', v_retained_source_set_hash
    );
    IF v_reuse_latest THEN
        v_provider_runs := v_latest.provider_runs;
        v_stage_status := pg_catalog.jsonb_set(
            COALESCE(v_latest.stage_status, '{}'::JSONB),
            ARRAY['costSourceHash'], pg_catalog.to_jsonb(v_cost_source_hash), TRUE
        );
        v_stage_status := pg_catalog.jsonb_set(
            v_stage_status, ARRAY['retainedEvidenceSourceSetHash'],
            pg_catalog.to_jsonb(v_retained_source_set_hash), TRUE
        );
        v_stage_status := pg_catalog.jsonb_set(
            v_stage_status, ARRAY['finalized'], pg_catalog.to_jsonb(v_finalized), TRUE
        );
    END IF;

    INSERT INTO public.analysis_order_audit_bundles (
        request_id, version, bundle_hash, previous_version_hash, source_set_hash,
        pipeline_version, pipeline_policy, risk_policy_version, ai_policy_version,
        scheduler_policy_version, plan_id, access_mode, order_id, preflight_id,
        target_instagram_id, target_profile_available, target_posts_available,
        target_post_count, followers_declared, followers_collected,
        following_declared, following_collected, mutual_total, mutual_list_hash,
        public_total, private_total, screened_total, candidate_declared,
        candidate_collected, interaction_declared, interaction_collected,
        target_likes_declared, target_likes_collected,
        target_comments_declared, target_comments_collected,
        candidate_likes_declared, candidate_likes_collected,
        candidate_likes_evidence_collected,
        tags_declared, tags_collected, mentions_declared, mentions_collected,
        candidate_key_coverage, provider_runs, stage_status,
        completeness_status, gap_codes, cost_currency, cost_status,
        cost_known_usd, cost_conservative_usd, total_known_cost_usd,
        total_conservative_cost_usd, cost_usage_unknown, usage_unknown,
        cost_missing_source_codes, cost_provenance, assembled_at
    ) VALUES (
        p_request_id, v_version, v_bundle_hash, v_previous_hash, v_source_set_hash,
        v_request.pipeline_version, public.analysis_order_audit_redact_json(
            COALESCE(v_request.policy_versions_snapshot, '{}'::JSONB)
        ), v_risk_policy, v_ai_policy, v_scheduler_policy, v_plan_id, v_access_mode,
        v_order_id, v_request.preflight_id, v_target_username,
        v_target_profile_available, v_target_posts_available, v_target_post_count,
        v_followers_declared, v_followers_collected, v_following_declared,
        v_following_collected, v_mutual_total, v_mutual_list_hash,
        v_public_total, v_private_total, v_screened_total, v_candidate_declared,
        v_candidate_collected, v_interaction_declared, v_interaction_collected,
        v_target_likes_declared, v_target_likes_collected,
        v_target_comments_declared, v_target_comments_collected,
        v_candidate_likes_declared, v_candidate_likes_collected,
        v_candidate_likes_evidence_collected,
        v_tags_declared, v_tags_collected, v_mentions_declared, v_mentions_collected,
        v_candidate_key_coverage, v_provider_runs, v_stage_status,
        CASE WHEN pg_catalog.cardinality(v_gaps) = 0 THEN 'complete'
             WHEN v_inconsistent THEN 'inconsistent' ELSE 'partial' END,
        v_gaps, 'USD', v_cost_status, v_cost_known, v_cost_conservative,
        v_total_known, v_total_conservative, v_cost_usage_unknown,
        v_cost_usage_unknown, v_cost_missing, v_cost_provenance, v_now
    ) ON CONFLICT (request_id, source_set_hash) DO NOTHING
      RETURNING * INTO v_existing;
    IF NOT FOUND THEN
        SELECT bundle.* INTO v_existing
        FROM public.analysis_order_audit_bundles AS bundle
        WHERE bundle.request_id = p_request_id
          AND bundle.source_set_hash = v_source_set_hash;
        UPDATE public.analysis_order_audit_assembly_queue
           SET status = 'completed', lease_token = NULL, lease_expires_at = NULL,
               updated_at = pg_catalog.clock_timestamp()
         WHERE request_id = p_request_id;
        IF v_queue_fenced AND v_finalized THEN
            PERFORM public.analysis_v2_purge_result_working_set(p_request_id, TRUE);
        END IF;
        RETURN public.analysis_order_audit_bundle_payload(v_existing);
    END IF;

    IF v_reuse_latest THEN
        INSERT INTO public.analysis_order_audit_candidates (
            request_id, version, candidate_id, username, mutual_ordinal,
            following_ordinal, is_private, is_verified, profile_available,
            profile_image_available, profile_failure_code, initial_gender_output,
            initial_gender_model, initial_gender_confidence, initial_gender_reason,
            final_gender_output, final_gender_model, final_gender_confidence,
            final_gender_reason, gender_operation_key, gender_result_hash,
            gender_resolution_operation_key, gender_resolution_result_hash,
            feature_operation_key, feature_result_hash, evidence_checkpoint_ids,
            account_context, final_inclusion_state, risk_components,
            risk_formula_version, pre_score, raw_score, public_score, final_score,
            risk_band, final_rank, featured_rank, recent_mutual_rank,
            partner_safety_operation_key, partner_safety_result_hash
        )
        SELECT p_request_id, v_version, candidate.candidate_id, candidate.username,
            candidate.mutual_ordinal, candidate.following_ordinal, candidate.is_private,
            candidate.is_verified, candidate.profile_available,
            candidate.profile_image_available, candidate.profile_failure_code,
            candidate.initial_gender_output, candidate.initial_gender_model,
            candidate.initial_gender_confidence, candidate.initial_gender_reason,
            candidate.final_gender_output, candidate.final_gender_model,
            candidate.final_gender_confidence, candidate.final_gender_reason,
            candidate.gender_operation_key, candidate.gender_result_hash,
            candidate.gender_resolution_operation_key, candidate.gender_resolution_result_hash,
            candidate.feature_operation_key, candidate.feature_result_hash,
            candidate.evidence_checkpoint_ids, candidate.account_context,
            candidate.final_inclusion_state, candidate.risk_components,
            candidate.risk_formula_version, candidate.pre_score, candidate.raw_score,
            candidate.public_score, candidate.final_score, candidate.risk_band,
            candidate.final_rank, candidate.featured_rank, candidate.recent_mutual_rank,
            candidate.partner_safety_operation_key, candidate.partner_safety_result_hash
        FROM public.analysis_order_audit_candidates AS candidate
        WHERE candidate.request_id = p_request_id
          AND candidate.version = v_latest.version;
    ELSE
        INSERT INTO public.analysis_order_audit_candidates (
            request_id, version, candidate_id, username, mutual_ordinal,
            following_ordinal, is_private, is_verified, profile_available,
            profile_image_available, profile_failure_code, initial_gender_output,
            initial_gender_model, initial_gender_confidence, initial_gender_reason,
            final_gender_output, final_gender_model, final_gender_confidence,
            final_gender_reason, gender_operation_key, gender_result_hash,
            gender_resolution_operation_key, gender_resolution_result_hash,
            feature_operation_key, feature_result_hash, evidence_checkpoint_ids,
            account_context, final_inclusion_state, risk_components,
            risk_formula_version, pre_score, raw_score, public_score, final_score,
            risk_band, final_rank, featured_rank, recent_mutual_rank,
            partner_safety_operation_key, partner_safety_result_hash
        )
        SELECT p_request_id, v_version,
            COALESCE(feature.candidate_id, private_name.candidate_id,
                'username:' || mutual.username),
            mutual.username, mutual.mutual_ordinal, mutual.following_ordinal,
            mutual.is_private, mutual.is_verified,
            (feature.candidate_id IS NOT NULL OR private_name.candidate_id IS NOT NULL)
                AND COALESCE(feature.terminal_classification, 'available')
                    NOT IN ('unavailable', 'media_unavailable'),
            (feature.profile_image_url IS NOT NULL OR private_name.profile_image_url IS NOT NULL),
            CASE WHEN feature.terminal_classification IN ('unavailable', 'media_unavailable')
                THEN feature.terminal_classification ELSE NULL END,
            CASE COALESCE(feature.baseline_classification, feature.terminal_classification)
                WHEN 'verified_female' THEN 'female'
                WHEN 'verified_non_female' THEN 'male'
                WHEN 'unavailable' THEN 'unavailable'
                WHEN 'media_unavailable' THEN 'unavailable'
                ELSE 'unknown'
            END,
            initial_checkpoint.model_name,
            initial_checkpoint.result_json->'assessment'->>'confidence',
            COALESCE(initial_checkpoint.result_json->>'routingReason',
                feature.classification_source),
            CASE COALESCE(feature.terminal_classification, feature.baseline_classification)
                WHEN 'verified_female' THEN 'female'
                WHEN 'verified_non_female' THEN 'male'
                WHEN 'unavailable' THEN 'unavailable'
                WHEN 'media_unavailable' THEN 'unavailable'
                ELSE 'unknown'
            END,
            final_checkpoint.model_name,
            final_checkpoint.result_json->'assessment'->>'confidence',
            COALESCE(final_checkpoint.result_json->>'reason',
                feature.gender_resolution_status, feature.classification_source),
            feature.gender_operation_key, feature.gender_result_hash,
            feature.gender_resolution_operation_key, feature.gender_resolution_result_hash,
            feature.feature_operation_key, feature.feature_result_hash,
            ARRAY_REMOVE(ARRAY[
                feature.gender_operation_key, feature.gender_resolution_operation_key,
                feature.feature_operation_key, score.partner_safety_operation_key
            ], NULL),
            CASE
                WHEN feature.media_context->>'accountContext' IN (
                    'personal', 'individual_creator', 'official_group_or_brand', 'uncertain'
                ) THEN feature.media_context->>'accountContext'
                ELSE 'uncertain'
            END,
            CASE
                WHEN mutual.is_private THEN 'private'
                WHEN result.candidate_id IS NOT NULL THEN 'included'
                WHEN feature.terminal_classification IN ('unavailable', 'media_unavailable')
                    THEN 'unavailable'
                WHEN feature.candidate_id IS NOT NULL THEN 'excluded'
                ELSE 'unknown'
            END,
            public.analysis_order_audit_redact_json(score.components),
            COALESCE(score_manifest.risk_policy_version, v_risk_policy),
            score.pre_score, score.raw_score, score.public_score,
            result.display_score, COALESCE(result.risk_band, score.risk_band),
            result.sort_ordinal, COALESCE(result.featured_rank, score.featured_rank),
            COALESCE(result.recent_mutual_rank, score.recent_mutual_rank),
            score.partner_safety_operation_key, score.partner_safety_result_hash
        FROM public.analysis_v2_mutual_rows AS mutual
        LEFT JOIN public.analysis_v2_candidate_feature_rows AS feature
          ON feature.request_id = mutual.request_id
         AND feature.instagram_id = mutual.username
        LEFT JOIN public.analysis_v2_private_name_rows AS private_name
          ON private_name.request_id = mutual.request_id
         AND private_name.instagram_id = mutual.username
        LEFT JOIN public.analysis_v2_ai_result_checkpoints AS initial_checkpoint
          ON initial_checkpoint.request_id = mutual.request_id
         AND initial_checkpoint.operation_key = feature.gender_operation_key
        LEFT JOIN public.analysis_v2_ai_result_checkpoints AS final_checkpoint
          ON final_checkpoint.request_id = mutual.request_id
         AND final_checkpoint.operation_key = feature.gender_resolution_operation_key
        LEFT JOIN public.analysis_v2_candidate_score_rows AS score
          ON score.request_id = mutual.request_id
         AND score.candidate_id = COALESCE(feature.candidate_id, private_name.candidate_id)
        LEFT JOIN public.analysis_v2_candidate_score_manifests AS score_manifest
          ON score_manifest.request_id = mutual.request_id
        LEFT JOIN public.analysis_v2_female_results AS result
          ON result.request_id = mutual.request_id
         AND result.candidate_id = score.candidate_id
        WHERE mutual.request_id = p_request_id
          AND (
              v_relationship.job_key IS NULL
              OR mutual.job_key = v_relationship.job_key
          );
    END IF;

    IF v_reuse_latest THEN
        INSERT INTO public.analysis_order_audit_interactions (
            request_id, version, ordinal, candidate_id, username, signal,
            source_post_id, evidence_id, occurred_at, comment_text, details,
            reverse_like_status, reverse_component_score,
            completeness_status, gap_codes
        )
        SELECT p_request_id, v_version, interaction.ordinal, interaction.candidate_id,
            interaction.username, interaction.signal, interaction.source_post_id,
            interaction.evidence_id, interaction.occurred_at, interaction.comment_text,
            interaction.details, interaction.reverse_like_status,
            interaction.reverse_component_score, interaction.completeness_status,
            interaction.gap_codes
        FROM public.analysis_order_audit_interactions AS interaction
        WHERE interaction.request_id = p_request_id
          AND interaction.version = v_latest.version;
    ELSE
        INSERT INTO public.analysis_order_audit_interactions (
            request_id, version, ordinal, candidate_id, username, signal,
            source_post_id, evidence_id, occurred_at, comment_text, details,
            reverse_like_status, reverse_component_score,
            completeness_status, gap_codes
        )
        SELECT p_request_id, v_version, interaction.ordinal,
            candidate.candidate_id, interaction.actor_username, interaction.signal,
            interaction.post_id, interaction.source_interaction_id, interaction.occurred_at,
            interaction.comment_text, public.analysis_order_audit_redact_json(
                NULLIF(to_jsonb(interaction)->'details', 'null'::JSONB)
            ),
            NULL, NULL,
            CASE
                WHEN interaction.signal = 'target_post_like'
                     AND v_target_likes_declared IS NOT NULL
                     AND v_target_likes_collected = v_target_likes_declared THEN 'complete'
                WHEN interaction.signal = 'target_post_comment'
                     AND v_target_comments_declared IS NOT NULL
                     AND v_target_comments_collected = v_target_comments_declared THEN 'complete'
                ELSE 'partial'
            END,
            CASE
                WHEN interaction.signal = 'target_post_like'
                     AND v_target_likes_declared IS NOT NULL
                     AND v_target_likes_collected <> v_target_likes_declared
                    THEN ARRAY['TARGET_LIKES_ROWS_GAP']::TEXT[]
                WHEN interaction.signal = 'target_post_comment'
                     AND v_target_comments_declared IS NOT NULL
                     AND v_target_comments_collected <> v_target_comments_declared
                    THEN ARRAY['TARGET_COMMENTS_ROWS_GAP']::TEXT[]
                ELSE ARRAY[]::TEXT[]
            END
        FROM public.analysis_target_interactors AS interaction
        LEFT JOIN public.analysis_order_audit_candidates AS candidate
          ON candidate.request_id = p_request_id
         AND candidate.version = v_version
         AND candidate.username = interaction.actor_username
        WHERE interaction.request_id = p_request_id
          AND (
              v_target_evidence.job_key IS NULL
              OR interaction.job_key = v_target_evidence.job_key
          )
        ORDER BY interaction.ordinal;

        INSERT INTO public.analysis_order_audit_interactions (
            request_id, version, ordinal, candidate_id, username, signal,
            source_post_id, evidence_id, occurred_at, comment_text, details,
            reverse_like_status, reverse_component_score,
            completeness_status, gap_codes
        )
        SELECT p_request_id, v_version,
            (v_target_interaction_max_ordinal + row_number() OVER (
                ORDER BY reverse.candidate_id, refs.value
            ))::INTEGER,
            candidate.candidate_id, candidate.username, 'candidate_post_like', NULL,
            refs.value, NULL, NULL,
            public.analysis_order_audit_redact_json(
                pg_catalog.jsonb_build_object(
                    'reverseLikeStatus', reverse.reverse_like_status,
                    'componentScore', reverse.component_score
                )
            ),
            reverse.reverse_like_status, reverse.component_score,
            CASE WHEN v_reverse_manifest_exists THEN 'complete' ELSE 'partial' END,
            CASE WHEN v_reverse_manifest_exists THEN ARRAY[]::TEXT[]
                ELSE ARRAY['CANDIDATE_LIKES_SOURCE_MISSING']::TEXT[] END
        FROM public.analysis_v2_reverse_like_rows AS reverse
        CROSS JOIN LATERAL unnest(reverse.evidence_ref_ids) AS refs(value)
        JOIN public.analysis_order_audit_candidates AS candidate
          ON candidate.request_id = p_request_id
         AND candidate.version = v_version
         AND candidate.candidate_id = reverse.candidate_id
        WHERE reverse.request_id = p_request_id;
    END IF;

    UPDATE public.analysis_order_audit_assembly_queue
       SET status = 'completed', lease_token = NULL, lease_expires_at = NULL,
           last_error_code = NULL, last_error_at = NULL,
           updated_at = pg_catalog.clock_timestamp()
     WHERE request_id = p_request_id;

    IF v_queue_fenced AND v_finalized THEN
        PERFORM public.analysis_v2_purge_result_working_set(p_request_id, TRUE);
    END IF;
    RETURN public.analysis_order_audit_bundle_payload(v_existing);
EXCEPTION WHEN OTHERS THEN
    BEGIN
        UPDATE public.analysis_order_audit_assembly_queue
           SET status = 'failed',
               next_attempt_at = pg_catalog.clock_timestamp() + INTERVAL '30 seconds',
               lease_token = NULL, lease_expires_at = NULL,
               last_error_code = CASE
                   WHEN SQLSTATE = 'P0001' THEN SQLERRM
                   ELSE 'ANALYSIS_ORDER_AUDIT_ASSEMBLY_FAILED'
               END,
               last_error_at = pg_catalog.clock_timestamp(),
               updated_at = pg_catalog.clock_timestamp()
         WHERE request_id = p_request_id;
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;
    IF v_finalized THEN
        BEGIN
            PERFORM public.analysis_order_audit_purge_fence(
                p_request_id, 'ANALYSIS_ORDER_AUDIT_ASSEMBLY_FAILED'
            );
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END IF;
    RAISE;
END;
$$;


--
-- Name: assert_analysis_provider_admission_claim(text, text, text, uuid, text, text, uuid, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_analysis_provider_admission_claim(p_workload_role text, p_logical_provider text, p_credential_slot text, p_request_id uuid, p_job_key text, p_operation_key text, p_job_claim_token uuid, p_provider_claim_token uuid, p_provider_fence bigint, p_now timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_request_found BOOLEAN;
    v_job_found BOOLEAN;
    v_preflight_run public.analysis_preflight_provider_runs%ROWTYPE;
    v_v2_run public.analysis_v2_provider_runs%ROWTYPE;
    v_provider_run_found BOOLEAN;
    v_preflight_found BOOLEAN;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_operation_family TEXT;
    v_policy_slot TEXT;
    v_preflight_order_slot TEXT;
    v_beta_allocation_state TEXT;
    v_beta_reservation_slot TEXT;
    v_beta_reservation_state TEXT;
    v_gemini_lease public.analysis_v2_gemini_leases%ROWTYPE;
    v_gemini_attempt INTEGER;
BEGIN
    -- Initial profile work belongs to the preflight claim. Fresh paid profile
    -- admission uses the paid worker route but still claims the durable
    -- preflight admission row before it may start the provider.
    IF p_workload_role = 'preflight' THEN
        IF p_logical_provider <> 'apify' OR p_job_key <> 'preflight:provider'
           OR p_operation_key <> 'target-profile-fallback' THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
        END IF;
        SELECT preflight.* INTO v_preflight
        FROM public.analysis_preflights AS preflight
        WHERE preflight.id = p_request_id
        FOR SHARE;
        v_preflight_found := FOUND;
        -- A betatest preflight-held target profile is a paid-budget
        -- compatibility path. Never let a caller relabel it as ordinary
        -- preflight work to consume the primary/quinary/senary pool.
        IF v_preflight_found AND (
            v_preflight.analysis_entry_channel = 'betatest'
            OR EXISTS (
                SELECT 1
                FROM public.analysis_beta_pool_allocations AS allocation
                JOIN public.analysis_beta_pool_reservations AS reservation
                  ON reservation.allocation_id = allocation.id
                 AND reservation.operation_family = 'target-profile'
                WHERE allocation.preflight_id = p_request_id
                  AND allocation.lifecycle_state = 'preflight_held'
                  AND reservation.lifecycle_state = 'preflight_held'
            )
        ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        IF NOT v_preflight_found
           OR v_preflight.expires_at <= p_now
           OR v_preflight.status IS DISTINCT FROM 'processing'
           OR v_preflight.lease_token IS DISTINCT FROM p_job_claim_token
           OR p_provider_claim_token IS DISTINCT FROM p_job_claim_token
           OR v_preflight.lease_expires_at IS NULL
           OR v_preflight.lease_expires_at <= p_now THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
        END IF;
        SELECT provider_run.* INTO v_preflight_run
        FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.preflight_id = p_request_id
          AND provider_run.operation_key = p_operation_key;
        v_provider_run_found := FOUND;
        IF v_provider_run_found
           AND (v_preflight_run.logical_provider IS DISTINCT FROM p_logical_provider
                OR v_preflight_run.credential_slot IS DISTINCT FROM p_credential_slot) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        -- Ordinary preflight has no V2 request policy. Its provider-run row
        -- and the preflight claim above are the only durable identity checks.
        -- In particular, do not interpret a policy row keyed by an unrelated
        -- request id as authority for this preflight.
        RETURN;
    END IF;

    -- B-lite is dispatched on the preflight queue, but its Gemini work must
    -- consume the shared paid Gemini budget.  The B-lite cache lease is the
    -- authoritative task claim for this narrow identity; do not substitute a
    -- caller-provided role or request/job tuple.
    IF p_workload_role = 'paid'
       AND p_logical_provider = 'gemini'
       AND p_job_key = 'preflight:blite'
       AND p_operation_key = 'gemini:legacy:unknown:attempt:1' THEN
        IF NOT EXISTS (
            SELECT 1
            FROM public.analysis_preflights AS preflight
            JOIN public.precheckout_blite_cache AS cache
              ON cache.preflight_id = preflight.id
            WHERE preflight.id = p_request_id
              AND preflight.status = 'ready'
              AND preflight.expires_at > p_now
              AND cache.state = 'pending'
              AND cache.lease_token = p_job_claim_token
              AND cache.lease_expires_at IS NOT NULL
              AND cache.lease_expires_at > p_now
        ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
        END IF;
        -- B-lite uses the precheckout cache lease as its job claim, but the
        -- shared eight-slot Gemini row remains the authoritative provider
        -- fence.  Keep those identities separate and require every durable
        -- slot attribute to match the admission request.
        SELECT gemini_lease.* INTO v_gemini_lease
        FROM public.analysis_v2_gemini_leases AS gemini_lease
        WHERE gemini_lease.state = 'leased'
          AND gemini_lease.request_id = p_request_id
          AND gemini_lease.job_key = 'preflight:blite'
          AND gemini_lease.attempt = 1
          AND gemini_lease.lease_claim_token = p_provider_claim_token
          AND gemini_lease.fence = p_provider_fence
          AND gemini_lease.expires_at > p_now
          AND p_credential_slot = ('gemini-' || gemini_lease.slot::TEXT)
        FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN;
    END IF;

    -- A betatest target profile is dispatched on the preflight route for
    -- compatibility, but its service-owned preflight-held credit must consume
    -- the paid Apify global/slot budget.  This narrow branch is intentionally
    -- keyed by the immutable processing claim and held target-profile
    -- reservation; a caller cannot opt into it with a role flag or slot name.
    IF p_workload_role = 'paid'
       AND p_logical_provider = 'apify'
       AND p_job_key = 'preflight:provider'
       AND p_operation_key = 'target-profile-fallback' THEN
        SELECT preflight.* INTO v_preflight
        FROM public.analysis_preflights AS preflight
        WHERE preflight.id = p_request_id
        FOR SHARE;
        IF NOT FOUND
           OR v_preflight.expires_at <= p_now
           OR v_preflight.status IS DISTINCT FROM 'processing'
           OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'betatest'
           OR v_preflight.lease_token IS DISTINCT FROM p_job_claim_token
           OR p_provider_claim_token IS DISTINCT FROM p_job_claim_token
           OR v_preflight.lease_expires_at IS NULL
           OR v_preflight.lease_expires_at <= p_now THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
        END IF;
        SELECT allocation.lifecycle_state,
               reservation.credential_slot,
               reservation.lifecycle_state
        INTO v_beta_allocation_state,
             v_beta_reservation_slot,
             v_beta_reservation_state
        FROM public.analysis_beta_pool_allocations AS allocation
        JOIN public.analysis_beta_pool_reservations AS reservation
          ON reservation.allocation_id = allocation.id
         AND reservation.operation_family = 'target-profile'
        WHERE allocation.preflight_id = p_request_id
          AND allocation.lifecycle_state = 'preflight_held'
          AND reservation.lifecycle_state = 'preflight_held'
        FOR SHARE;
        IF NOT FOUND
           OR v_beta_allocation_state IS DISTINCT FROM 'preflight_held'
           OR v_beta_reservation_state IS DISTINCT FROM 'preflight_held'
           OR v_beta_reservation_slot IS DISTINCT FROM p_credential_slot
           OR (v_preflight.order_scoped_apify_credential_slot IS NOT NULL
               AND v_preflight.order_scoped_apify_credential_slot
                    IS DISTINCT FROM p_credential_slot) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        SELECT provider_run.* INTO v_preflight_run
        FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.preflight_id = p_request_id
          AND provider_run.operation_key = p_operation_key;
        v_provider_run_found := FOUND;
        IF v_provider_run_found
           AND (v_preflight_run.logical_provider IS DISTINCT FROM p_logical_provider
                OR v_preflight_run.credential_slot IS DISTINCT FROM p_credential_slot) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN;
    END IF;

    IF p_workload_role = 'paid'
       AND p_logical_provider = 'apify'
       AND p_job_key = 'paid:target-profile'
       AND p_operation_key ~ '^target-profile-fresh-admission:g([1-9]|[1-9][0-9]|100)$' THEN
        SELECT preflight.* INTO v_preflight
        FROM public.analysis_preflights AS preflight
        WHERE preflight.id = p_request_id
        FOR SHARE;
        IF NOT FOUND
           OR v_preflight.expires_at <= p_now
           OR v_preflight.status IS DISTINCT FROM 'ready'
           OR v_preflight.consumed_request_id IS NOT NULL
           OR v_preflight.admission_status IS DISTINCT FROM 'processing'
           OR v_preflight.admission_claim_token IS DISTINCT FROM p_job_claim_token
           OR p_provider_claim_token IS DISTINCT FROM p_job_claim_token
           OR v_preflight.admission_lease_expires_at IS NULL
           OR v_preflight.admission_lease_expires_at <= p_now THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
        END IF;
        SELECT provider_run.* INTO v_preflight_run
        FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.preflight_id = p_request_id
          AND provider_run.operation_key = p_operation_key;
        v_provider_run_found := FOUND;
        IF v_provider_run_found
           AND (v_preflight_run.logical_provider IS DISTINCT FROM p_logical_provider
                OR v_preflight_run.credential_slot IS DISTINCT FROM p_credential_slot) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        -- Fresh admission is keyed by the preflight id, so an execution
        -- policy (which is created only after request consumption) cannot
        -- authorize this route. Validate the immutable lineage instead:
        -- order-scoped slots and the betatest preflight-held target-profile
        -- reservation are both service-owned facts.
        IF v_preflight.order_scoped_apify_credential_slot IS NOT NULL
           AND v_preflight.order_scoped_apify_credential_slot
                IS DISTINCT FROM p_credential_slot THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        IF v_preflight.analysis_entry_channel = 'betatest' THEN
            SELECT allocation.lifecycle_state,
                   reservation.credential_slot,
                   reservation.lifecycle_state
            INTO v_beta_allocation_state,
                 v_beta_reservation_slot,
                 v_beta_reservation_state
            FROM public.analysis_beta_pool_allocations AS allocation
            JOIN public.analysis_beta_pool_reservations AS reservation
              ON reservation.allocation_id = allocation.id
             AND reservation.operation_family = 'target-profile'
            WHERE allocation.preflight_id = p_request_id
              AND allocation.lifecycle_state = 'preflight_held'
              AND reservation.lifecycle_state = 'preflight_held'
            FOR SHARE;
            IF NOT FOUND
               OR v_beta_allocation_state IS DISTINCT FROM 'preflight_held'
               OR v_beta_reservation_state IS DISTINCT FROM 'preflight_held'
               OR v_beta_reservation_slot IS DISTINCT FROM p_credential_slot THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
            END IF;
        END IF;
        RETURN;
    END IF;

    IF p_workload_role = 'paid' THEN
        SELECT analysis_request.* INTO v_request
        FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = p_request_id
          AND analysis_request.pipeline_version = 'v2'
          AND analysis_request.status IN ('pending', 'processing')
        FOR SHARE;
        v_request_found := FOUND;
        SELECT job.* INTO v_job
        FROM public.analysis_pipeline_jobs AS job
        WHERE job.request_id = p_request_id
          AND job.job_key = p_job_key
          AND job.status = 'processing'
          AND job.lease_token = p_job_claim_token
          AND job.lease_expires_at IS NOT NULL
          AND job.lease_expires_at > p_now
        FOR SHARE;
        v_job_found := FOUND;
        IF NOT v_request_found OR NOT v_job_found THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
        END IF;

        IF p_logical_provider = 'gemini' THEN
            IF p_credential_slot !~ '^gemini-[1-8]$'
               OR p_operation_key !~ ':attempt:([1-4])$' THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
            END IF;
            v_gemini_attempt := substring(
                p_operation_key FROM ':attempt:([1-4])$'
            )::INTEGER;
            SELECT gemini_lease.* INTO v_gemini_lease
            FROM public.analysis_v2_gemini_leases AS gemini_lease
            WHERE gemini_lease.slot = substring(
                p_credential_slot FROM '^gemini-([1-8])$'
            )::SMALLINT
            FOR SHARE;
            IF NOT FOUND
               OR v_gemini_lease.state <> 'leased'
               OR v_gemini_lease.request_id IS DISTINCT FROM p_request_id
               OR v_gemini_lease.job_key IS DISTINCT FROM p_job_key
               OR v_gemini_lease.attempt IS DISTINCT FROM v_gemini_attempt
               OR v_gemini_lease.lease_claim_token IS DISTINCT FROM p_provider_claim_token
               OR v_gemini_lease.fence IS DISTINCT FROM p_provider_fence
               OR v_gemini_lease.expires_at IS NULL
               OR v_gemini_lease.expires_at <= p_now THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
            END IF;
            RETURN;
        END IF;

        v_operation_family := CASE
            WHEN p_operation_key LIKE 'target-profile-fresh-admission:%' THEN 'target-profile'
            ELSE pg_catalog.split_part(p_operation_key, ':', 1)
        END;
        -- A consumed preflight can carry an immutable order-scoped slot. It
        -- takes precedence over the ordinary relationship default; the
        -- request policy, when present, must still agree with it.
        SELECT preflight.order_scoped_apify_credential_slot
        INTO v_preflight_order_slot
        FROM public.analysis_preflights AS preflight
        WHERE preflight.id = v_request.preflight_id;
        IF v_preflight_order_slot IS NOT NULL
           AND v_preflight_order_slot IS DISTINCT FROM p_credential_slot THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        SELECT policy.* INTO v_policy
        FROM public.analysis_v2_provider_execution_policies AS policy
        WHERE policy.request_id = p_request_id;
        IF FOUND THEN
            v_policy_slot := v_policy.operation_slot_map ->> v_operation_family;
            -- Historical authorized-test policies intentionally contain the
            -- seven-operation map without a profile-repair key. The runtime
            -- reserve RPC already aliases this internal repair prefix to the
            -- frozen profile-fallback slot; keep admission validation in the
            -- same compatibility contract. Beta policies have an explicit
            -- profile-repair reservation and must not be aliased here.
            IF v_policy.mode = 'test_operation_split'
               AND v_operation_family = 'profile-repair' THEN
                v_policy_slot := v_policy.operation_slot_map ->> 'profile-fallback';
            END IF;
            IF v_policy_slot IS NULL OR v_policy_slot IS DISTINCT FROM p_credential_slot
               OR (v_preflight_order_slot IS NOT NULL
                   AND v_policy_slot IS DISTINCT FROM v_preflight_order_slot) THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
            END IF;
        ELSIF v_preflight_order_slot IS NULL
              AND v_operation_family IN ('relationship-followers', 'relationship-following')
              AND p_credential_slot <> 'secondary' THEN
            -- Ordinary production relationship collection remains secondary
            -- only when no frozen request/preflight contract authorizes a
            -- different slot.
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CREDENTIAL_FORBIDDEN', ERRCODE = 'P0001';
        END IF;
        IF p_logical_provider <> 'apify'
           OR p_provider_claim_token IS DISTINCT FROM p_job_claim_token THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
        END IF;
        SELECT provider_run.* INTO v_v2_run
        FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = p_request_id
          AND provider_run.job_key = p_job_key
          AND provider_run.operation_key = p_operation_key
        FOR SHARE;
        v_provider_run_found := FOUND;
        IF v_provider_run_found
           AND (v_v2_run.logical_provider IS DISTINCT FROM p_logical_provider
                OR v_v2_run.credential_slot IS DISTINCT FROM p_credential_slot) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN;
    END IF;

    RAISE EXCEPTION USING
        MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
END;
$_$;


--
-- Name: assert_analysis_revenue_dispatch_guard_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_analysis_revenue_dispatch_guard_v1(p_request_id uuid, p_job_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_guard public.analysis_revenue_dispatch_guards%ROWTYPE;
    v_strict BOOLEAN := FALSE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REVENUE_DISPATCH_FENCE', ERRCODE = 'P0001';
    END IF;

    SELECT * INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    SELECT * INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    SELECT * INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    SELECT * INTO v_policy
    FROM public.analysis_v2_provider_execution_policies AS policy
    WHERE policy.request_id = p_request_id
    FOR UPDATE;
    SELECT * INTO v_parent
    FROM public.analysis_revenue_run_ledgers AS ledger
    WHERE ledger.request_id = p_request_id
    FOR UPDATE;
    SELECT * INTO v_guard
    FROM public.analysis_revenue_dispatch_guards AS dispatch_guard
    WHERE dispatch_guard.request_id = p_request_id
    FOR UPDATE;

    v_strict := v_request.id IS NOT NULL
        AND v_request.plan_access_mode_snapshot = 'test_entitlement'
        AND v_request.selected_plan_id_snapshot IN ('basic', 'standard')
        AND v_policy.request_id IS NOT NULL
        AND v_policy.mode = 'test_operation_split'
        AND v_policy.policy_version = 'authorized-free-e2e-v1';
    IF NOT v_strict THEN
        RETURN;
    END IF;

    IF v_preflight.id IS NULL
       OR v_job.request_id IS NULL
       OR v_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_preflight.status IS DISTINCT FROM 'consumed'
       OR v_preflight.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_parent.request_id IS NULL
       OR v_parent.status IS DISTINCT FROM 'running'
       OR v_parent.preflight_id IS DISTINCT FROM v_request.preflight_id
       OR v_parent.user_id IS DISTINCT FROM v_request.user_id
       OR v_parent.plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_parent.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_parent.target_username_hmac IS DISTINCT FROM v_preflight.target_input_hash
       OR v_parent.preflight_refreshed_at IS DISTINCT FROM v_preflight.admission_refreshed_at
       OR v_parent.request_started_at IS DISTINCT FROM v_request.created_at
       OR v_guard.request_id IS NULL
       OR v_guard.state IS DISTINCT FROM 'active'
       OR v_guard.reason_code IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REVENUE_DISPATCH_FENCE', ERRCODE = 'P0001';
    END IF;
END;
$_$;


--
-- Name: assert_analysis_revenue_fresh_provider_admission_v1(uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_analysis_revenue_fresh_provider_admission_v1(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_operation_key text, p_provider_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_provider public.analysis_v2_provider_runs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_claim_token IS NULL
       OR p_job_key IS NULL
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_job_input_hash IS NULL OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_provider_input_hash IS NULL OR p_provider_input_hash !~ '^[a-f0-9]{64}$'
       OR p_operation_key IS NULL
       OR NOT public.analysis_revenue_valid_fresh_provider_operation_key_v1(p_operation_key) THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_FENCE', ERRCODE = 'P0001';
    END IF;

    -- Canonical locking order shared with the live-cost RPCs:
    -- preflight → request → job → provider/source → revenue parent.
    SELECT * INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    SELECT * INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    SELECT * INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    SELECT * INTO v_provider
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    FOR UPDATE;
    SELECT * INTO v_parent
    FROM public.analysis_revenue_run_ledgers AS ledger
    WHERE ledger.request_id = p_request_id
    FOR UPDATE;

    IF v_parent.request_id IS NULL
       OR v_request.id IS NULL
       OR v_preflight.id IS NULL
       OR v_job.request_id IS NULL
       OR v_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_parent.preflight_id IS DISTINCT FROM v_request.preflight_id
       OR v_parent.user_id IS DISTINCT FROM v_request.user_id
       OR v_parent.plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_parent.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_parent.plan_id NOT IN ('basic', 'standard')
       OR v_parent.status IS DISTINCT FROM 'running'
       OR v_parent.target_username_hmac IS DISTINCT FROM v_preflight.target_input_hash
       OR v_parent.preflight_refreshed_at IS DISTINCT FROM v_preflight.admission_refreshed_at
       OR v_parent.request_started_at IS DISTINCT FROM v_request.created_at
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status IS DISTINCT FROM 'processing'
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_preflight.status IS DISTINCT FROM 'consumed'
       OR v_preflight.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.status IS DISTINCT FROM 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_job_claim_token
       OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_FENCE', ERRCODE = 'P0001';
    END IF;
    IF v_provider.request_id IS NULL OR (
        v_provider.input_hash IS DISTINCT FROM p_provider_input_hash
        OR v_provider.job_claim_token IS DISTINCT FROM p_job_claim_token
        OR v_provider.logical_provider IS DISTINCT FROM 'apify'
        OR v_provider.reserved_at < v_parent.preflight_refreshed_at
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_NOT_FRESH', ERRCODE = 'P0001';
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'disposition', 'admitted', 'created', FALSE, 'replayed', TRUE
    );
END;
$_$;


--
-- Name: assert_demo_analysis_fixture_payload(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_demo_analysis_fixture_payload() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
    duplicate_count INTEGER;
BEGIN
    IF TG_OP = 'INSERT' AND NEW.status = 'published' THEN
        RAISE EXCEPTION 'draft fixtures require the controlled publish procedure';
    END IF;
    IF jsonb_typeof(NEW.payload) <> 'object'
       OR NOT (NEW.payload ? 'target' AND NEW.payload ? 'summary' AND NEW.payload ? 'public' AND NEW.payload ? 'private')
       OR jsonb_typeof(NEW.payload->'target') <> 'object'
       OR jsonb_typeof(NEW.payload->'summary') <> 'object'
       OR jsonb_typeof(NEW.payload->'public') <> 'array'
       OR jsonb_typeof(NEW.payload->'private') <> 'array'
       OR jsonb_array_length(NEW.payload->'public') <> 84
       OR jsonb_array_length(NEW.payload->'private') <> 145 THEN
        RAISE EXCEPTION 'invalid demo fixture payload shape';
    END IF;
    IF (SELECT count(*) FROM jsonb_object_keys(NEW.payload)) <> 4
       OR (SELECT count(*) FROM jsonb_object_keys(NEW.payload->'target')) <> 7
       OR NOT (NEW.payload->'target' ?& ARRAY['username', 'fullName', 'bio', 'profileImage', 'followersCount', 'followingCount', 'isPrivate'])
       OR NOT (NEW.payload->'summary' ?& ARRAY['targetInstagramId', 'targetFullName', 'targetProfileImage', 'planId', 'followers', 'following', 'detectedMutuals', 'publicMutuals', 'privateMutuals', 'screenedMutuals', 'genderStats', 'notScreenedMutuals', 'exclusionApplied', 'scorePolicyVersion'])
       OR NEW.payload->'target'->>'username' <> 'junho_dem'
       OR NEW.payload->'summary'->>'targetInstagramId' <> 'junho_dem'
       OR COALESCE((NEW.payload->'target'->>'isPrivate')::BOOLEAN, TRUE) THEN
        RAISE EXCEPTION 'demo fixture target contract failed';
    END IF;
    IF NEW.payload::TEXT ~ 'https?://' OR NEW.payload::TEXT ~ 'www[.]'
       OR (NEW.payload->'target'->>'profileImage') !~ '^/demo-avatars/demo-v3-target-[0-9]{3}[.]webp$'
       OR (NEW.payload->'summary'->>'targetProfileImage') !~ '^/demo-avatars/demo-v3-target-[0-9]{3}[.]webp$' THEN
        RAISE EXCEPTION 'demo fixture must use only local blurred avatars';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(NEW.payload->'public') AS account(value)
        WHERE jsonb_typeof(account.value) <> 'object'
           OR (SELECT count(*) FROM jsonb_object_keys(account.value)) <> 11
           OR NOT (account.value ?& ARRAY['instagramId', 'fullName', 'profileImage', 'bio', 'displayScore', 'riskBand', 'featuredRank', 'recentMutualRank', 'analysisDepth', 'oneLineOverview', 'highRiskNarrative'])
           OR account.value->>'profileImage' !~ '^/demo-avatars/demo-v3-female-[0-9]{3}[.]webp$'
    ) OR EXISTS (
        SELECT 1 FROM jsonb_array_elements(NEW.payload->'private') AS account(value)
        WHERE jsonb_typeof(account.value) <> 'object'
           OR (SELECT count(*) FROM jsonb_object_keys(account.value)) <> 3
           OR NOT (account.value ?& ARRAY['instagramId', 'fullName', 'profileImage'])
           OR account.value->>'profileImage' !~ '^/demo-avatars/demo-v3-private-[0-9]{3}[.]webp$'
    ) THEN
        RAISE EXCEPTION 'demo fixture account contract failed';
    END IF;
    SELECT COUNT(*) INTO duplicate_count
    FROM (
        SELECT lower(account.value->>'instagramId') AS instagram_id FROM jsonb_array_elements(NEW.payload->'public') AS account(value)
        UNION ALL
        SELECT lower(account.value->>'instagramId') AS instagram_id FROM jsonb_array_elements(NEW.payload->'private') AS account(value)
    ) AS ids GROUP BY instagram_id HAVING instagram_id IS NULL OR COUNT(*) > 1;
    IF duplicate_count > 0 THEN RAISE EXCEPTION 'demo fixture Instagram IDs must be unique'; END IF;
    IF NEW.version = 'operator-editable-fixture-v2' THEN
        IF NEW.payload->'target'->>'bio' IS NOT NULL
           OR NEW.payload->'summary'->>'detectedMutuals' <> '313'
           OR NEW.payload->'summary'->>'publicMutuals' <> '168'
           OR NEW.payload->'summary'->>'privateMutuals' <> '145'
           OR NEW.payload->'summary'->>'screenedMutuals' <> '168'
           OR NEW.payload->'summary'->>'notScreenedMutuals' <> '0'
           OR NEW.payload->'summary'->'genderStats' <> '{"male": 74, "female": 84, "unknown": 10}'::JSONB
           OR EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.payload->'public') AS account(value) WHERE account.value->>'bio' IS NOT NULL) THEN
            RAISE EXCEPTION 'demo fixture v2 synthetic count and bio contract failed';
        END IF;
    ELSIF NEW.payload->'summary'->>'publicMutuals' <> '84'
       OR NEW.payload->'summary'->>'privateMutuals' <> '145'
       OR NEW.payload->'summary'->>'screenedMutuals' <> '84' THEN
        RAISE EXCEPTION 'demo fixture summary count contract failed';
    END IF;
    NEW.updated_at := clock_timestamp();
    RETURN NEW;
END;
$_$;


--
-- Name: assert_earlybird_receipt_archive_purge_safe(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_earlybird_receipt_archive_purge_safe() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    -- A missing key is not equivalent to a NULL value for retention.  The
    -- explicit source branches below fail closed before purge evaluates its
    -- typed archive projections; invalid scalar casts fail in those branches.
    IF EXISTS (
        SELECT 1
        FROM public.maintenance_jobs AS job
        WHERE job.payload->>'legacy_source_table' IN (
            'earlybird_adoption_policy_failure_rearms',
            'earlybird_concierge_snapshot_conflict_recoveries',
            'earlybird_pfe_target_evidence_start_rejection_rearms',
            'earlybird_pfe3_media_artifact_rearms',
            'earlybird_profile_fetch_exhaustion_recoveries',
            'earlybird_schema_failure_recoveries',
            'earlybird_terminal_unavailable_exhaustion_rearms',
            'earlybird_v211_apify_transient_replays',
            'earlybird_v211_concierge_replays',
            'earlybird_v211_lease_policy_failure_rearms',
            'earlybird_v211_policy_identity_replays',
            'earlybird_v211_profile_ai_diagnostic_replays',
            'earlybird_v211_relationship_lineage_failure_rearms'
        )
        AND (
            job.state IS DISTINCT FROM 'succeeded'
            OR job.legacy_pending_user_id IS NOT NULL
            OR job.kind IS DISTINCT FROM CASE job.payload->>'legacy_source_table'
                WHEN 'earlybird_adoption_policy_failure_rearms' THEN 'rearm'
                WHEN 'earlybird_concierge_snapshot_conflict_recoveries' THEN 'recovery'
                WHEN 'earlybird_pfe_target_evidence_start_rejection_rearms' THEN 'rearm'
                WHEN 'earlybird_pfe3_media_artifact_rearms' THEN 'rearm'
                WHEN 'earlybird_profile_fetch_exhaustion_recoveries' THEN 'recovery'
                WHEN 'earlybird_schema_failure_recoveries' THEN 'recovery'
                WHEN 'earlybird_terminal_unavailable_exhaustion_rearms' THEN 'rearm'
                WHEN 'earlybird_v211_apify_transient_replays' THEN 'replay'
                WHEN 'earlybird_v211_concierge_replays' THEN 'replay'
                WHEN 'earlybird_v211_lease_policy_failure_rearms' THEN 'rearm'
                WHEN 'earlybird_v211_policy_identity_replays' THEN 'replay'
                WHEN 'earlybird_v211_profile_ai_diagnostic_replays' THEN 'replay'
                WHEN 'earlybird_v211_relationship_lineage_failure_rearms' THEN 'rearm'
            END
            OR pg_catalog.jsonb_typeof(job.payload) IS DISTINCT FROM 'object'
            OR pg_catalog.jsonb_typeof(job.payload->'legacy_primary_key') IS DISTINCT FROM 'object'
            OR pg_catalog.jsonb_typeof(job.payload->'legacy_row') IS DISTINCT FROM 'object'
            OR job.payload->'schema_version' IS DISTINCT FROM '1'::JSONB
            OR NOT (job.payload->'legacy_primary_key' ?& ARRAY['order_id'])
            OR job.payload->'legacy_primary_key'->>'order_id' IS NULL
            OR pg_catalog.jsonb_typeof(
                job.payload->'legacy_primary_key'->'order_id'
            ) IS DISTINCT FROM 'string'
            OR job.payload->'legacy_primary_key' IS DISTINCT FROM
                pg_catalog.jsonb_build_object(
                    'order_id', job.payload->'legacy_row'->'order_id'
                )
            OR job.content_hash IS DISTINCT FROM pg_catalog.encode(
                extensions.digest(
                    convert_to(job.payload::TEXT, 'UTF8'), 'sha256'
                ), 'hex'
            )
            OR job.target_key_hash IS DISTINCT FROM pg_catalog.encode(
                extensions.digest(
                    convert_to(
                        'supabase-22-legacy-earlybird-retirement-v1:'
                        || job.kind || ':'
                        || (job.payload->>'legacy_source_table') || ':'
                        || (job.payload->'legacy_primary_key')::TEXT,
                        'UTF8'
                    ), 'sha256'
                ), 'hex'
            )
            OR (job.payload->>'legacy_source_table' = 'earlybird_adoption_policy_failure_rearms'
                AND (NOT (job.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','policy_failed_request_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at'])
                     OR job.payload->'legacy_row'->>'order_id' IS NULL
                     OR job.payload->'legacy_row'->>'original_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'policy_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'rearmed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'expected_fulfillment_attempt_count' IS NULL
                     OR job.payload->'legacy_row'->>'expected_manual_review_at' IS NULL
                     OR job.payload->'legacy_row'->>'created_at' IS NULL))
            OR (job.payload->>'legacy_source_table' = 'earlybird_concierge_snapshot_conflict_recoveries'
                AND (NOT (job.payload->'legacy_row' ?& ARRAY['order_id','preflight_id','provider_operation_key','provider_input_hash','provider_run_id_hash','expected_manual_review_at','expected_admission_refreshed_at','old_order_followers_count','old_order_following_count','old_preflight_followers_count','old_preflight_following_count','new_witness_followers_count','new_witness_following_count','old_snapshot_recorded_at','new_witness_recorded_at','recovery_reason','followers_absolute_delta','following_absolute_delta','created_at'])
                     OR job.payload->'legacy_row'->>'order_id' IS NULL
                     OR job.payload->'legacy_row'->>'preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'provider_operation_key' IS NULL
                     OR job.payload->'legacy_row'->>'provider_input_hash' IS NULL
                     OR job.payload->'legacy_row'->>'provider_run_id_hash' IS NULL
                     OR job.payload->'legacy_row'->>'expected_manual_review_at' IS NULL
                     OR job.payload->'legacy_row'->>'expected_admission_refreshed_at' IS NULL
                     OR job.payload->'legacy_row'->>'old_order_followers_count' IS NULL
                     OR job.payload->'legacy_row'->>'old_order_following_count' IS NULL
                     OR job.payload->'legacy_row'->>'old_preflight_followers_count' IS NULL
                     OR job.payload->'legacy_row'->>'old_preflight_following_count' IS NULL
                     OR job.payload->'legacy_row'->>'new_witness_followers_count' IS NULL
                     OR job.payload->'legacy_row'->>'new_witness_following_count' IS NULL
                     OR job.payload->'legacy_row'->>'old_snapshot_recorded_at' IS NULL
                     OR job.payload->'legacy_row'->>'new_witness_recorded_at' IS NULL
                     OR job.payload->'legacy_row'->>'recovery_reason' IS NULL
                     OR job.payload->'legacy_row'->>'followers_absolute_delta' IS NULL
                     OR job.payload->'legacy_row'->>'following_absolute_delta' IS NULL
                     OR job.payload->'legacy_row'->>'created_at' IS NULL))
            OR (job.payload->>'legacy_source_table' = 'earlybird_pfe_target_evidence_start_rejection_rearms'
                AND (NOT (job.payload->'legacy_row' ?& ARRAY['order_id','pfe_original_failed_request_id','rejected_successor_request_id','rearmed_preflight_id','prior_attempt_count','expected_manual_review_at','created_at'])
                     OR job.payload->'legacy_row'->>'order_id' IS NULL
                     OR job.payload->'legacy_row'->>'pfe_original_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'rejected_successor_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'rearmed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'prior_attempt_count' IS NULL
                     OR job.payload->'legacy_row'->>'expected_manual_review_at' IS NULL
                     OR job.payload->'legacy_row'->>'created_at' IS NULL))
            OR (job.payload->>'legacy_source_table' = 'earlybird_pfe3_media_artifact_rearms'
                AND (NOT (job.payload->'legacy_row' ?& ARRAY['order_id','pfe_original_failed_request_id','pfe2_rejected_successor_request_id','media_failed_request_id','rearmed_preflight_id','prior_attempt_count','expected_manual_review_at','created_at'])
                     OR job.payload->'legacy_row'->>'order_id' IS NULL
                     OR job.payload->'legacy_row'->>'pfe_original_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'pfe2_rejected_successor_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'media_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'rearmed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'prior_attempt_count' IS NULL
                     OR job.payload->'legacy_row'->>'expected_manual_review_at' IS NULL
                     OR job.payload->'legacy_row'->>'created_at' IS NULL))
            OR (job.payload->>'legacy_source_table' = 'earlybird_profile_fetch_exhaustion_recoveries'
                AND (NOT (job.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','expected_manual_review_at','created_at'])
                     OR job.payload->'legacy_row'->>'order_id' IS NULL
                     OR job.payload->'legacy_row'->>'failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'recovery_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'prior_attempt_count' IS NULL
                     OR job.payload->'legacy_row'->>'expected_manual_review_at' IS NULL
                     OR job.payload->'legacy_row'->>'created_at' IS NULL))
            OR (job.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
                AND (NOT (job.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at'])
                     OR job.payload->'legacy_row'->>'order_id' IS NULL
                     OR job.payload->'legacy_row'->>'failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'recovery_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'prior_attempt_count' IS NULL
                     OR job.payload->'legacy_row'->>'created_at' IS NULL))
            OR (job.payload->>'legacy_source_table' = 'earlybird_terminal_unavailable_exhaustion_rearms'
                AND (NOT (job.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at'])
                     OR job.payload->'legacy_row'->>'order_id' IS NULL
                     OR job.payload->'legacy_row'->>'failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'rearmed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'expected_fulfillment_attempt_count' IS NULL
                     OR job.payload->'legacy_row'->>'expected_manual_review_at' IS NULL
                     OR job.payload->'legacy_row'->>'created_at' IS NULL))
            OR (job.payload->>'legacy_source_table' = 'earlybird_v211_apify_transient_replays'
                AND (NOT (job.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','policy_identity_failed_request_id','transient_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at'])
                     OR job.payload->'legacy_row'->>'order_id' IS NULL
                     OR job.payload->'legacy_row'->>'original_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'policy_identity_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'transient_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'failed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'rearmed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'expected_fulfillment_attempt_count' IS NULL
                     OR job.payload->'legacy_row'->>'expected_manual_review_at' IS NULL
                     OR job.payload->'legacy_row'->>'created_at' IS NULL))
            OR (job.payload->>'legacy_source_table' = 'earlybird_v211_concierge_replays'
                AND (NOT (job.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','first_relationship_failed_request_id','second_relationship_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at','reviewed_source_request_id','reviewed_source_owner_id','reviewed_source_target_instagram_id','reviewed_source_result_request_id','reviewed_source_target_posts','reviewed_source_target_evidence','reviewed_source_fingerprint','reviewed_source_registered_at','published_source_fingerprint','published_result_hash','published_at'])
                     OR job.payload->'legacy_row'->>'order_id' IS NULL
                     OR job.payload->'legacy_row'->>'original_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'first_relationship_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'second_relationship_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'failed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'rearmed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'expected_fulfillment_attempt_count' IS NULL
                     OR job.payload->'legacy_row'->>'expected_manual_review_at' IS NULL
                     OR job.payload->'legacy_row'->>'created_at' IS NULL))
            OR (job.payload->>'legacy_source_table' = 'earlybird_v211_lease_policy_failure_rearms'
                AND (NOT (job.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','source_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at'])
                     OR job.payload->'legacy_row'->>'order_id' IS NULL
                     OR job.payload->'legacy_row'->>'failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'source_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'rearmed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'expected_fulfillment_attempt_count' IS NULL
                     OR job.payload->'legacy_row'->>'expected_manual_review_at' IS NULL
                     OR job.payload->'legacy_row'->>'created_at' IS NULL))
            OR (job.payload->>'legacy_source_table' = 'earlybird_v211_policy_identity_replays'
                AND (NOT (job.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','policy_identity_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at'])
                     OR job.payload->'legacy_row'->>'order_id' IS NULL
                     OR job.payload->'legacy_row'->>'original_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'policy_identity_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'failed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'rearmed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'expected_fulfillment_attempt_count' IS NULL
                     OR job.payload->'legacy_row'->>'expected_manual_review_at' IS NULL
                     OR job.payload->'legacy_row'->>'created_at' IS NULL))
            OR (job.payload->>'legacy_source_table' = 'earlybird_v211_profile_ai_diagnostic_replays'
                AND (NOT (job.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','profile_ai_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at'])
                     OR job.payload->'legacy_row'->>'order_id' IS NULL
                     OR job.payload->'legacy_row'->>'original_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'profile_ai_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'failed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'rearmed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'expected_fulfillment_attempt_count' IS NULL
                     OR job.payload->'legacy_row'->>'expected_manual_review_at' IS NULL
                     OR job.payload->'legacy_row'->>'created_at' IS NULL))
            OR (job.payload->>'legacy_source_table' = 'earlybird_v211_relationship_lineage_failure_rearms'
                AND (NOT (job.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','relationship_failed_request_id','source_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at'])
                     OR job.payload->'legacy_row'->>'order_id' IS NULL
                     OR job.payload->'legacy_row'->>'original_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'relationship_failed_request_id' IS NULL
                     OR job.payload->'legacy_row'->>'source_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'rearmed_preflight_id' IS NULL
                     OR job.payload->'legacy_row'->>'expected_fulfillment_attempt_count' IS NULL
                     OR job.payload->'legacy_row'->>'expected_manual_review_at' IS NULL
                     OR job.payload->'legacy_row'->>'created_at' IS NULL))
        )) THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_RECEIPT_PURGE_ARCHIVE_INVALID', ERRCODE = 'P0001';
    END IF;
END;
$$;


--
-- Name: auto_admit_eligible_earlybird_fulfillments(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_admit_eligible_earlybird_fulfillments(p_limit integer DEFAULT 20) RETURNS TABLE(order_id uuid, fulfillment_status text, preflight_id uuid, user_id uuid, plan_id text, request_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_candidate RECORD;
    v_admitted RECORD;
    v_user_id_hint UUID;
    v_locked_user_id UUID;
    v_locked_fulfillment_status TEXT;
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    FOR v_candidate IN
        SELECT fulfillment.order_id
        FROM public.earlybird_fulfillments AS fulfillment
        INNER JOIN public.earlybird_orders AS earlybird_order
            ON earlybird_order.id = fulfillment.order_id
        INNER JOIN public.analysis_preflights AS preflight
            ON preflight.id = earlybird_order.preflight_id
        WHERE fulfillment.status = 'awaiting_operator'
          AND earlybird_order.status = 'paid'
          AND earlybird_order.seller_reference_confirmed_at IS NOT NULL
          AND earlybird_order.payment_id IS NOT NULL
          AND earlybird_order.actual_amount_krw IS NOT NULL
          AND earlybird_order.actual_amount_krw
                BETWEEN 0 AND earlybird_order.expected_amount_krw
          AND earlybird_order.actual_groble_product_id
                IS NOT DISTINCT FROM earlybird_order.expected_groble_product_id
          AND earlybird_order.plan_id IN ('basic', 'standard')
          AND preflight.user_id IS NOT DISTINCT FROM earlybird_order.user_id
          AND preflight.access_mode = 'production'
          AND preflight.consumed_request_id IS NULL
          AND preflight.plan_catalog_snapshot IS NOT NULL
          AND public.analysis_v2_valid_launch_snapshot(
              preflight.launch_status_snapshot
          )
          AND public.analysis_v2_valid_plan_catalog_snapshot(
              preflight.plan_catalog_snapshot
          )
          AND public.analysis_v2_valid_pricing_snapshot(
              preflight.pricing_snapshot
          )
          AND public.analysis_v2_valid_policy_versions_snapshot(
              preflight.policy_versions_snapshot
          )
          AND preflight.plan_catalog_snapshot
                ->earlybird_order.plan_id->>'launchStatus' = 'production'
        ORDER BY fulfillment.created_at, fulfillment.order_id
        LIMIT p_limit
    LOOP
        -- Claim only the state transition, in the same order as shared rebind.
        -- The candidate snapshot may be duplicated across sweep transactions;
        -- this locked recheck ensures only the awaiting_operator winner calls
        -- admit and therefore only that winner can return an admitted row.
        SELECT earlybird_order.user_id INTO v_user_id_hint
        FROM public.earlybird_orders AS earlybird_order
        WHERE earlybird_order.id = v_candidate.order_id;
        IF NOT FOUND THEN
            CONTINUE;
        END IF;
        PERFORM 1
        FROM public.users AS admission_user
        WHERE admission_user.id = v_user_id_hint
        FOR KEY SHARE;
        IF NOT FOUND THEN
            CONTINUE;
        END IF;
        SELECT earlybird_order.user_id INTO v_locked_user_id
        FROM public.earlybird_orders AS earlybird_order
        WHERE earlybird_order.id = v_candidate.order_id
        FOR UPDATE;
        IF NOT FOUND OR v_locked_user_id IS DISTINCT FROM v_user_id_hint THEN
            CONTINUE;
        END IF;
        SELECT fulfillment.status INTO v_locked_fulfillment_status
        FROM public.earlybird_fulfillments AS fulfillment
        WHERE fulfillment.order_id = v_candidate.order_id
        FOR UPDATE;
        IF NOT FOUND
           OR v_locked_fulfillment_status <> 'awaiting_operator' THEN
            CONTINUE;
        END IF;

        BEGIN
            SELECT * INTO v_admitted
            FROM public.admit_earlybird_fulfillment(v_candidate.order_id);
        EXCEPTION
            WHEN SQLSTATE 'P0001' THEN
                IF SQLERRM IN (
                    'EARLYBIRD_FULFILLMENT_PAYMENT_INVALID',
                    'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT',
                    'EARLYBIRD_FULFILLMENT_STATE_INVALID',
                    'EARLYBIRD_FULFILLMENT_MANUAL_REVIEW'
                ) THEN
                    CONTINUE;
                END IF;
                RAISE;
        END;

        IF v_admitted.fulfillment_status = 'admission_pending' THEN
            RETURN QUERY SELECT
                v_admitted.order_id,
                v_admitted.fulfillment_status,
                v_admitted.preflight_id,
                v_admitted.user_id,
                v_admitted.plan_id,
                v_admitted.request_id;
        END IF;
    END LOOP;
END;
$$;


--
-- Name: backfill_account_deletion_jobs_v1(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backfill_account_deletion_jobs_v1(p_limit integer DEFAULT 100, p_cursor_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '2min'
    SET lock_timeout TO '5s'
    AS $_$
DECLARE
    v_source RECORD;
    v_mirror_result JSONB;
    v_canonical_state TEXT;
    v_processed INTEGER := 0;
    v_mirrored INTEGER := 0;
    v_duplicates INTEGER := 0;
    v_blocked INTEGER := 0;
    v_seen INTEGER := 0;
    v_has_more BOOLEAN := FALSE;
    v_next_cursor_hash TEXT;
BEGIN
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_DELETION_BACKFILL_LIMIT_INVALID',
            ERRCODE = 'P0001';
    END IF;
    IF p_cursor_hash IS NOT NULL
       AND p_cursor_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_DELETION_BACKFILL_CURSOR_INVALID',
            ERRCODE = 'P0001';
    END IF;

    FOR v_source IN
        SELECT source_job.account_id,
               public.canonical_json_hash_v1(
                   'account-deletion-target',
                   pg_catalog.jsonb_build_object('account_id', source_job.account_id::TEXT)
               ) AS target_key_hash
        FROM public.account_deletion_jobs AS source_job
        WHERE p_cursor_hash IS NULL
           OR public.canonical_json_hash_v1(
               'account-deletion-target',
               pg_catalog.jsonb_build_object('account_id', source_job.account_id::TEXT)
           ) > p_cursor_hash
        ORDER BY target_key_hash
        LIMIT p_limit + 1
    LOOP
        v_seen := v_seen + 1;
        IF v_seen > p_limit THEN
            v_has_more := TRUE;
            EXIT;
        END IF;

        v_processed := v_processed + 1;
        v_next_cursor_hash := v_source.target_key_hash;
        v_mirror_result := public.mirror_account_deletion_job_v1(v_source.account_id);

        SELECT maintenance_job.state
        INTO v_canonical_state
        FROM public.maintenance_jobs AS maintenance_job
        WHERE maintenance_job.kind = 'purge'
          AND maintenance_job.target_key_hash = v_source.target_key_hash;

        IF v_canonical_state = 'blocked' THEN
            v_blocked := v_blocked + 1;
        ELSIF COALESCE((v_mirror_result->>'duplicate')::BOOLEAN, FALSE) THEN
            v_duplicates := v_duplicates + 1;
        ELSE
            v_mirrored := v_mirrored + 1;
        END IF;
    END LOOP;

    -- A hash-cursor pass is never evidence of parity or retirement. Callers
    -- must collect the separate parity snapshot after the final page; a
    -- mismatch requires restarting the pass with a NULL cursor.
    RETURN pg_catalog.jsonb_build_object(
        'schema_version', 'supabase-22-account-deletion-backfill-v1',
        'status', CASE
            WHEN v_blocked > 0 THEN 'blocked'
            WHEN v_has_more THEN 'progressed'
            ELSE 'parity_required'
        END,
        'processed', v_processed,
        'mirrored', v_mirrored,
        'duplicates', v_duplicates,
        'blocked', v_blocked,
        'has_more', v_has_more,
        'next_cursor_hash', v_next_cursor_hash
    );
END;
$_$;


--
-- Name: begin_account_deletion_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_account_deletion_v1(p_account_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_account public.users%ROWTYPE;
    v_job public.account_deletion_jobs%ROWTYPE;
    v_object_keys JSONB;
BEGIN
    SELECT * INTO v_account
    FROM public.users AS account
    WHERE account.id = p_account_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ACCOUNT_DELETION_ACCOUNT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_account.account_class <> 'production' OR v_account.traffic_class <> 'external' THEN
        RAISE EXCEPTION USING MESSAGE = 'ACCOUNT_DELETION_NOT_ALLOWED', ERRCODE = 'P0001';
    END IF;

    IF v_account.lifecycle = 'active' THEN
        UPDATE public.users AS account
        SET lifecycle = 'retired', updated_at = pg_catalog.clock_timestamp()
        WHERE account.id = p_account_id;

        INSERT INTO public.account_classification_audit (
            account_id, command_version, reason_code,
            previous_account_class, previous_traffic_class, previous_lifecycle,
            next_account_class, next_traffic_class, next_lifecycle
        ) VALUES (
            p_account_id, 'account_deletion_v1', 'USER_REQUESTED_DELETION',
            v_account.account_class, v_account.traffic_class, v_account.lifecycle,
            v_account.account_class, v_account.traffic_class, 'retired'
        );
    END IF;

    INSERT INTO public.account_deletion_jobs(account_id)
    VALUES (p_account_id)
    ON CONFLICT (account_id) DO NOTHING;

    UPDATE public.analysis_requests AS request
    SET share_enabled = FALSE, share_token = NULL
    WHERE request.user_id = p_account_id;

    SELECT * INTO v_job
    FROM public.account_deletion_jobs AS job
    WHERE job.account_id = p_account_id;

    SELECT COALESCE(pg_catalog.jsonb_agg(image_object.object_key ORDER BY image_object.object_key), '[]'::JSONB)
    INTO v_object_keys
    FROM public.analysis_v2_result_image_objects AS image_object
    JOIN public.analysis_requests AS request ON request.id = image_object.request_id
    WHERE request.user_id = p_account_id AND image_object.object_key IS NOT NULL;

    RETURN pg_catalog.jsonb_build_object('state', v_job.state, 'objectKeys', v_object_keys);
END;
$$;


--
-- Name: begin_analysis_revenue_cost_ledger_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_analysis_revenue_cost_ledger_v1(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_entitlement public.analysis_v2_test_entitlement_consumptions%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_fallback public.analysis_preflight_provider_runs%ROWTYPE;
    v_fresh public.analysis_preflight_provider_runs%ROWTYPE;
    v_existing public.analysis_revenue_run_ledgers%ROWTYPE;
    v_child public.analysis_revenue_cost_operations%ROWTYPE;
    v_runner_plan TEXT; v_target_hash TEXT; v_count INTEGER; v_total INTEGER;
    v_fallback_hash TEXT; v_fresh_hash TEXT; v_fallback_owner TEXT; v_fresh_owner TEXT;
BEGIN
    IF p_request_id IS NULL THEN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_LEDGER_INVALID'; END IF;
    -- Canonical begin order: consumed preflight -> request -> entitlement ->
    -- policy -> exact preflight source rows -> parent -> child.
    SELECT * INTO v_preflight FROM public.analysis_preflights WHERE consumed_request_id = p_request_id FOR UPDATE;
    SELECT * INTO v_request FROM public.analysis_requests WHERE id = p_request_id FOR UPDATE;
    IF v_preflight.id IS NULL OR v_request.id IS NULL OR v_request.preflight_id IS DISTINCT FROM v_preflight.id THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_LEDGER_FENCE';
    END IF;
    SELECT * INTO v_entitlement FROM public.analysis_v2_test_entitlement_consumptions WHERE request_id = p_request_id FOR UPDATE;
    SELECT * INTO v_policy FROM public.analysis_v2_provider_execution_policies WHERE request_id = p_request_id FOR UPDATE;
    SELECT runner_plan INTO v_runner_plan FROM public.load_e2e_test_runner_v1(v_request.user_id);
    IF v_entitlement.request_id IS NULL OR v_policy.request_id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot NOT IN ('basic', 'standard')
       OR v_preflight.status IS DISTINCT FROM 'consumed' OR v_preflight.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_preflight.admission_generation IS DISTINCT FROM 1 OR v_preflight.admission_status IS DISTINCT FROM 'ready'
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_preflight.admission_entitlement_jti_hash IS DISTINCT FROM v_request.test_entitlement_jti_hash
       OR v_preflight.admission_refreshed_at IS NULL OR v_preflight.admission_target_followers_count IS NULL OR v_preflight.admission_target_following_count IS NULL
       OR v_preflight.user_id IS DISTINCT FROM v_request.user_id
       OR pg_catalog.lower(v_preflight.target_instagram_id) IS DISTINCT FROM pg_catalog.lower(v_request.target_instagram_id)
       OR v_entitlement.user_id IS DISTINCT FROM v_request.user_id OR v_entitlement.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_entitlement.selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_entitlement.entitlement_jti_hash IS DISTINCT FROM v_request.test_entitlement_jti_hash
       OR v_policy.mode IS DISTINCT FROM 'test_operation_split' OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR v_policy.entitlement_jti_hash IS DISTINCT FROM v_entitlement.entitlement_jti_hash
       OR pg_catalog.lower(v_policy.target_instagram_id) IS DISTINCT FROM pg_catalog.lower(v_preflight.target_instagram_id)
       OR v_runner_plan IS DISTINCT FROM v_request.selected_plan_id_snapshot THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_LEDGER_FENCE';
    END IF;
    SELECT * INTO v_fallback FROM public.analysis_preflight_provider_runs
      WHERE preflight_id = v_preflight.id AND operation_key = 'target-profile-fallback' FOR UPDATE;
    SELECT * INTO v_fresh FROM public.analysis_preflight_provider_runs
      WHERE preflight_id = v_preflight.id AND operation_key = 'target-profile-fresh-admission:g1' FOR UPDATE;
    SELECT pg_catalog.count(*)::INTEGER INTO v_count FROM public.analysis_preflight_provider_runs WHERE preflight_id = v_preflight.id;
    IF v_count <> 2 OR v_fallback.preflight_id IS NULL OR v_fresh.preflight_id IS NULL
       OR v_fallback.status IS DISTINCT FROM 'succeeded' OR v_fresh.status IS DISTINCT FROM 'succeeded'
       OR v_fallback.actual_usage_usd IS NULL OR v_fresh.actual_usage_usd IS NULL
       OR v_fallback.terminalized_at IS NULL OR v_fresh.terminalized_at IS NULL
       OR v_fallback.usage_reconciled_at IS NULL OR v_fresh.usage_reconciled_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_LEDGER_TARGET_LINEAGE';
    END IF;
    v_target_hash := v_preflight.target_input_hash;
    IF v_target_hash IS NULL OR v_target_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_LEDGER_TARGET_LINEAGE'; END IF;
    v_fallback_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_fallback.operation_key, 'UTF8'), 'sha256'), 'hex');
    v_fresh_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_fresh.operation_key, 'UTF8'), 'sha256'), 'hex');
    v_fallback_owner := pg_catalog.encode(extensions.digest(pg_catalog.convert_to('revenue-cost/preflight-owner/v1:' || p_request_id::TEXT || ':' || v_fallback.operation_key, 'UTF8'), 'sha256'), 'hex');
    v_fresh_owner := pg_catalog.encode(extensions.digest(pg_catalog.convert_to('revenue-cost/preflight-owner/v1:' || p_request_id::TEXT || ':' || v_fresh.operation_key, 'UTF8'), 'sha256'), 'hex');
    v_total := public.analysis_revenue_cost_ceil_krw(v_fallback.actual_usage_usd) + public.analysis_revenue_cost_ceil_krw(v_fresh.actual_usage_usd);
    SELECT * INTO v_existing FROM public.analysis_revenue_run_ledgers WHERE request_id = p_request_id FOR UPDATE;
    IF FOUND THEN
        IF v_existing.preflight_id IS DISTINCT FROM v_preflight.id OR v_existing.user_id IS DISTINCT FROM v_request.user_id
           OR v_existing.plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot OR v_existing.access_mode IS DISTINCT FROM 'test_entitlement'
           OR v_existing.target_username_hmac IS DISTINCT FROM v_target_hash
           OR v_existing.pricing_snapshot_version IS DISTINCT FROM 'revenue-e2e-cost-2026-08-10-v1'
           OR v_existing.buffered_fx_krw_per_usd IS DISTINCT FROM 1450
           OR v_existing.preflight_refreshed_at IS DISTINCT FROM v_preflight.admission_refreshed_at
           OR v_existing.request_started_at IS DISTINCT FROM v_request.created_at
           OR v_existing.cost_cap_krw IS DISTINCT FROM (CASE WHEN v_request.selected_plan_id_snapshot = 'basic' THEN 1808 ELSE 3634 END)
           OR v_existing.margin_target_krw IS DISTINCT FROM (CASE WHEN v_request.selected_plan_id_snapshot = 'basic' THEN 904 ELSE 1817 END)
           OR v_existing.economic_actual_krw IS DISTINCT FROM v_total OR v_existing.actual_cost_krw IS DISTINCT FROM v_total
           OR v_existing.billed_actual_krw IS DISTINCT FROM 0
           OR v_existing.reserved_cost_krw IS DISTINCT FROM 0 OR v_existing.status IS DISTINCT FROM 'running'
           OR v_existing.selected_manifest_scope_hash IS NOT NULL OR v_existing.manual_review_reason IS NOT NULL
           OR (SELECT pg_catalog.count(*) FROM public.analysis_revenue_cost_operations WHERE request_id = p_request_id) <> 2 THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_LEDGER_DRIFT';
        END IF;
        FOR v_child IN SELECT * FROM public.analysis_revenue_cost_operations WHERE request_id = p_request_id ORDER BY attempt FOR UPDATE LOOP
            IF NOT (
                v_child.owner_kind = 'preflight_provider_run' AND v_child.operation_kind = 'target_profile'
                AND v_child.source_job_key = 'preflight' AND v_child.source_attempt = 0 AND v_child.units = 1
                AND v_child.selected_manifest_scope_hash IS NULL AND v_child.denial_reason IS NULL AND v_child.lifecycle_anomaly IS NULL
                AND v_child.billed_actual_usd = 0 AND v_child.billed_actual_krw = 0 AND v_child.reserved_krw = 0 AND v_child.status = 'settled'
                AND ((v_child.attempt = 1 AND v_child.owner_key_hash = v_fallback_owner AND v_child.source_operation_key_hash = v_fallback_hash
                     AND v_child.estimated_economic_usd = v_fallback.actual_usage_usd AND v_child.economic_actual_usd = v_fallback.actual_usage_usd
                     AND v_child.economic_actual_krw = public.analysis_revenue_cost_ceil_krw(v_fallback.actual_usage_usd)
                     AND v_child.started_at = v_fallback.terminalized_at AND v_child.terminal_at = v_fallback.usage_reconciled_at)
                 OR (v_child.attempt = 2 AND v_child.owner_key_hash = v_fresh_owner AND v_child.source_operation_key_hash = v_fresh_hash
                     AND v_child.estimated_economic_usd = v_fresh.actual_usage_usd AND v_child.economic_actual_usd = v_fresh.actual_usage_usd
                     AND v_child.economic_actual_krw = public.analysis_revenue_cost_ceil_krw(v_fresh.actual_usage_usd)
                     AND v_child.started_at = v_fresh.terminalized_at AND v_child.terminal_at = v_fresh.usage_reconciled_at)
                )
            ) THEN
                RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_LEDGER_DRIFT';
            END IF;
        END LOOP;
        RETURN pg_catalog.jsonb_build_object('disposition', 'begun', 'created', FALSE, 'replayed', TRUE, 'requestId', p_request_id);
    END IF;
    INSERT INTO public.analysis_revenue_run_ledgers (
        request_id, preflight_id, user_id, plan_id, access_mode, target_username_hmac, preflight_refreshed_at, request_started_at,
        cost_cap_krw, margin_target_krw, economic_actual_krw, actual_cost_krw, billed_actual_krw
    ) VALUES (p_request_id, v_preflight.id, v_request.user_id, v_request.selected_plan_id_snapshot, 'test_entitlement', v_target_hash,
        v_preflight.admission_refreshed_at, v_request.created_at,
        CASE WHEN v_request.selected_plan_id_snapshot = 'basic' THEN 1808 ELSE 3634 END,
        CASE WHEN v_request.selected_plan_id_snapshot = 'basic' THEN 904 ELSE 1817 END, v_total, v_total, 0);
    INSERT INTO public.analysis_revenue_cost_operations (
        request_id, owner_kind, owner_key_hash, attempt, operation_kind, units, source_job_key, source_operation_key_hash, source_attempt,
        estimated_economic_usd, economic_actual_usd, billed_actual_usd, reserved_krw, economic_actual_krw, billed_actual_krw, status, started_at, terminal_at
    ) VALUES
      (p_request_id, 'preflight_provider_run', v_fallback_owner, 1, 'target_profile', 1, 'preflight', v_fallback_hash, 0,
       v_fallback.actual_usage_usd, v_fallback.actual_usage_usd, 0, 0, public.analysis_revenue_cost_ceil_krw(v_fallback.actual_usage_usd), 0, 'settled', v_fallback.terminalized_at, v_fallback.usage_reconciled_at),
      (p_request_id, 'preflight_provider_run', v_fresh_owner, 2, 'target_profile', 1, 'preflight', v_fresh_hash, 0,
       v_fresh.actual_usage_usd, v_fresh.actual_usage_usd, 0, 0, public.analysis_revenue_cost_ceil_krw(v_fresh.actual_usage_usd), 0, 'settled', v_fresh.terminalized_at, v_fresh.usage_reconciled_at);
    RETURN pg_catalog.jsonb_build_object('disposition', 'begun', 'created', TRUE, 'replayed', FALSE, 'requestId', p_request_id);
END; $_$;


--
-- Name: begin_analysis_revenue_resolver_pass_v1(uuid, text, uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_analysis_revenue_resolver_pass_v1(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_plan_hash text, p_screened_count integer, p_unknown_burden_count integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_existing public.analysis_revenue_resolver_passes%ROWTYPE;
    v_limit SMALLINT;
BEGIN
    IF p_job_key IS DISTINCT FROM 'coordinator:join:primary-evidence'
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_plan_hash !~ '^[a-f0-9]{64}$'
       OR p_screened_count IS NULL
       OR p_unknown_burden_count IS NULL
       OR p_screened_count < 1
       OR p_unknown_burden_count < 1
       OR p_unknown_burden_count > p_screened_count
       OR p_unknown_burden_count * 10 <= p_screened_count * 3 THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    PERFORM public.analysis_revenue_ai_cost_assert_lineage_v1(
        p_request_id, p_job_key, p_job_claim_token, p_job_input_hash, TRUE
    );
    PERFORM public.analysis_revenue_ai_cost_assert_parent_v1(p_request_id);
    SELECT * INTO v_parent
      FROM public.analysis_revenue_run_ledgers
     WHERE request_id = p_request_id
     FOR UPDATE;
    v_limit := CASE v_parent.plan_id WHEN 'basic' THEN 20 ELSE 40 END;
    SELECT * INTO v_existing
      FROM public.analysis_revenue_resolver_passes
     WHERE request_id = p_request_id
     FOR UPDATE;
    IF v_existing.request_id IS NOT NULL THEN
        IF v_existing.job_key IS DISTINCT FROM p_job_key
           OR v_existing.job_input_hash IS DISTINCT FROM p_job_input_hash
           OR v_existing.plan_id IS DISTINCT FROM v_parent.plan_id
           OR v_existing.capacity_limit IS DISTINCT FROM v_limit
           OR v_existing.plan_hash IS DISTINCT FROM p_plan_hash
           OR v_existing.screened_count IS DISTINCT FROM p_screened_count
           OR v_existing.unknown_burden_count IS DISTINCT FROM p_unknown_burden_count THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_DRIFT';
        END IF;
        IF v_parent.status = 'running' AND v_parent.manual_review_reason IS NULL THEN
            RETURN pg_catalog.jsonb_build_object(
                'disposition', 'accepted', 'created', FALSE, 'replayed', TRUE
            );
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'manual_review', 'created', FALSE, 'replayed', TRUE
        );
    END IF;
    IF v_parent.status IS DISTINCT FROM 'running' OR v_parent.manual_review_reason IS NOT NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'manual_review', 'created', TRUE, 'replayed', FALSE
        );
    END IF;
    INSERT INTO public.analysis_revenue_resolver_passes(
        request_id, job_key, job_input_hash, plan_id, capacity_limit, plan_hash,
        screened_count, unknown_burden_count
    ) VALUES (
        p_request_id, p_job_key, p_job_input_hash, v_parent.plan_id, v_limit,
        p_plan_hash, p_screened_count, p_unknown_burden_count
    );
    RETURN pg_catalog.jsonb_build_object(
        'disposition', 'accepted', 'created', TRUE, 'replayed', FALSE
    );
END;
$_$;


--
-- Name: begin_analysis_v2_gender_routing_manifest(uuid, text, uuid, text, text, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_analysis_v2_gender_routing_manifest(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_relationship_checkpoint_id text, p_policy_version text, p_plan_id text, p_canonical_input_hmac text, p_population_count integer, p_detailed_cap integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_relationship public.analysis_v2_relationship_manifests%ROWTYPE;
    v_manifest public.analysis_v2_gender_routing_manifests%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key <> 'track:relationships:collect'
       OR p_claim_token IS NULL
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_relationship_checkpoint_id !~ '^[a-f0-9]{64}$'
       OR p_policy_version <> 'gender-routing-v1'
       OR p_canonical_input_hmac !~ '^[a-f0-9]{64}$'
       OR (p_plan_id = 'basic' AND (p_detailed_cap <> 100 OR p_population_count NOT BETWEEN 0 AND 400))
       OR (p_plan_id = 'standard' AND (p_detailed_cap <> 200 OR p_population_count NOT BETWEEN 0 AND 800))
       OR p_plan_id NOT IN ('basic', 'standard') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    SELECT policy.* INTO v_policy
    FROM public.analysis_v2_provider_execution_policies AS policy
    WHERE policy.request_id = p_request_id
    FOR UPDATE;
    SELECT relationship_manifest.* INTO v_relationship
    FROM public.analysis_v2_relationship_manifests AS relationship_manifest
    WHERE relationship_manifest.request_id = p_request_id
      AND relationship_manifest.job_key = p_job_key
      AND relationship_manifest.result_hash = p_relationship_checkpoint_id
    FOR UPDATE;

    IF v_request.id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot IS DISTINCT FROM p_plan_id
       OR v_policy.request_id IS NULL
       OR v_policy.mode IS DISTINCT FROM 'test_operation_split'
       OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR v_job.request_id IS NULL
       OR v_job.status IS DISTINCT FROM 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now
       OR v_relationship.request_id IS NULL
       OR v_relationship.public_count IS DISTINCT FROM p_population_count THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT routing_manifest.* INTO v_manifest
    FROM public.analysis_v2_gender_routing_manifests AS routing_manifest
    WHERE routing_manifest.request_id = p_request_id
      AND routing_manifest.relationship_checkpoint_id = p_relationship_checkpoint_id
      AND routing_manifest.policy_version = p_policy_version
    FOR UPDATE;

    IF FOUND THEN
        IF v_manifest.relationship_job_key IS DISTINCT FROM p_job_key
           OR v_manifest.relationship_job_input_hash IS DISTINCT FROM p_job_input_hash
           OR v_manifest.plan_id IS DISTINCT FROM p_plan_id
           OR v_manifest.detailed_cap IS DISTINCT FROM p_detailed_cap
           OR v_manifest.population_count IS DISTINCT FROM p_population_count
           OR v_manifest.canonical_input_hmac IS DISTINCT FROM p_canonical_input_hmac THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_DRIFT', ERRCODE = 'P0001';
        END IF;
        IF v_manifest.status = 'complete' THEN
            RETURN public.analysis_v2_gender_routing_manifest_json(v_manifest);
        END IF;
        IF v_manifest.status = 'invalidated' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALIDATED', ERRCODE = 'P0001';
        END IF;
        UPDATE public.analysis_v2_gender_routing_manifests AS routing_manifest
        SET attempt_count = routing_manifest.attempt_count + 1,
            updated_at = v_now
        WHERE routing_manifest.request_id = p_request_id
          AND routing_manifest.relationship_checkpoint_id = p_relationship_checkpoint_id
          AND routing_manifest.policy_version = p_policy_version
        RETURNING * INTO v_manifest;
        RETURN public.analysis_v2_gender_routing_manifest_json(v_manifest);
    END IF;

    INSERT INTO public.analysis_v2_gender_routing_manifests (
        request_id, relationship_job_key, relationship_job_input_hash, relationship_checkpoint_id, policy_version,
        plan_id, detailed_cap, population_count, canonical_input_hmac, status,
        attempt_count, created_at, updated_at
    ) VALUES (
        p_request_id, p_job_key, p_job_input_hash, p_relationship_checkpoint_id, p_policy_version,
        p_plan_id, p_detailed_cap, p_population_count, p_canonical_input_hmac, 'building',
        1, v_now, v_now
    ) RETURNING * INTO v_manifest;
    RETURN public.analysis_v2_gender_routing_manifest_json(v_manifest);
END;
$_$;


--
-- Name: begin_analysis_v2_profile_provider_canary_terminalization(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_analysis_v2_profile_provider_canary_terminalization(p_source_request_id uuid, p_terminal_reason text, p_cleanup_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_experiment public.analysis_v2_profile_provider_canary_experiments%ROWTYPE;
    v_terminal_run_count INTEGER;
    v_unready_run_count INTEGER;
BEGIN
    IF p_source_request_id IS NULL OR p_cleanup_claim_token IS NULL
       OR p_terminal_reason NOT IN (
            'strict_failure', 'verified_no_run', 'completed',
            'aborted_by_operator', 'expired_waiting_for_repetition'
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT experiment.* INTO v_experiment
    FROM public.analysis_v2_profile_provider_canary_experiments AS experiment
    WHERE experiment.source_request_id = p_source_request_id
      AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_experiment.state = 'experiment_terminal' THEN
        IF v_experiment.terminal_reason IS DISTINCT FROM p_terminal_reason THEN
            RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_STATE_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_profile_provider_canary_experiment_json(v_experiment);
    END IF;
    IF v_experiment.state = 'terminalizing'
       AND v_experiment.cleanup_claim_token = p_cleanup_claim_token
       AND v_experiment.terminal_reason = p_terminal_reason THEN
        RETURN public.analysis_v2_profile_provider_canary_experiment_json(v_experiment);
    END IF;
    IF v_experiment.state = 'terminalizing'
       AND v_experiment.terminal_reason IS DISTINCT FROM p_terminal_reason THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_experiment.state = 'terminalizing'
       AND v_experiment.cleanup_lease_expires_at > v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.count(*)::INTEGER,
        pg_catalog.count(*) FILTER (WHERE
            canary_run.state IN ('starting', 'ambiguous', 'running')
            OR (canary_run.state IN ('succeeded', 'failed') AND (
                canary_run.cost_status <> 'actual' OR canary_run.cleanup_completed_at IS NULL
            ))
        )::INTEGER
    INTO v_terminal_run_count, v_unready_run_count
    FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1';
    IF v_terminal_run_count < 1 OR v_unready_run_count <> 0 THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_NOT_READY', ERRCODE = 'P0001';
    END IF;
    IF p_terminal_reason = 'aborted_by_operator' AND (
        v_experiment.state <> 'awaiting_repetition_2'
        OR EXISTS (
            SELECT 1 FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
            WHERE canary_run.source_request_id = p_source_request_id
              AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
              AND canary_run.repetition = 2
        )
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF p_terminal_reason = 'verified_no_run' AND NOT EXISTS (
        SELECT 1 FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
        WHERE canary_run.source_request_id = p_source_request_id
          AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
          AND canary_run.state = 'verified_no_run'
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF p_terminal_reason = 'completed' AND NOT EXISTS (
        SELECT 1 FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
        WHERE canary_run.source_request_id = p_source_request_id
          AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
          AND canary_run.repetition = 2
          AND canary_run.gate_passed = TRUE
          AND canary_run.cleanup_completed_at IS NOT NULL
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF p_terminal_reason = 'strict_failure' AND NOT EXISTS (
        SELECT 1 FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
        WHERE canary_run.source_request_id = p_source_request_id
          AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
          AND canary_run.gate_passed = FALSE
          AND canary_run.cleanup_completed_at IS NOT NULL
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF p_terminal_reason = 'expired_waiting_for_repetition' THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_v2_profile_provider_canary_experiments AS experiment
    SET state = 'terminalizing', terminal_reason = p_terminal_reason,
        cleanup_claim_token = p_cleanup_claim_token, cleanup_claimed_at = v_now,
        cleanup_lease_expires_at = v_now + INTERVAL '10 minutes', updated_at = v_now
    WHERE experiment.source_request_id = p_source_request_id
      AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
    RETURNING experiment.* INTO v_experiment;
    RETURN public.analysis_v2_profile_provider_canary_experiment_json(v_experiment);
END;
$$;


--
-- Name: begin_analysis_v2_result_image_manifest(uuid, text, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_analysis_v2_result_image_manifest(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_ordered_manifest_hash text, p_expected_rows integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_existing public.analysis_v2_result_image_manifests%ROWTYPE;
BEGIN
    IF p_ordered_manifest_hash !~ '^[a-f0-9]{64}$'
       OR p_expected_rows NOT BETWEEN 0 AND 50001 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    PERFORM public.analysis_v2_assert_result_image_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );

    SELECT manifest.* INTO v_existing
    FROM public.analysis_v2_result_image_manifests AS manifest
    WHERE manifest.request_id = p_request_id
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.producer_job_key IS DISTINCT FROM p_job_key
           OR v_existing.producer_input_hash IS DISTINCT FROM p_job_input_hash
           OR v_existing.ordered_manifest_hash IS DISTINCT FROM
                p_ordered_manifest_hash
           OR v_existing.expected_rows IS DISTINCT FROM p_expected_rows THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        UPDATE public.analysis_v2_result_image_manifests AS manifest
        SET producer_claim_token = p_claim_token
        WHERE manifest.request_id = p_request_id
          AND manifest.producer_claim_token IS DISTINCT FROM p_claim_token;
        RETURN pg_catalog.jsonb_build_object(
            'requestId', p_request_id,
            'orderedManifestHash', v_existing.ordered_manifest_hash,
            'expectedRows', v_existing.expected_rows,
            'sealed', v_existing.sealed_at IS NOT NULL
        );
    END IF;

    INSERT INTO public.analysis_v2_result_image_manifests (
        request_id, producer_job_key, producer_input_hash,
        producer_claim_token, ordered_manifest_hash, expected_rows
    ) VALUES (
        p_request_id, p_job_key, p_job_input_hash,
        p_claim_token, p_ordered_manifest_hash, p_expected_rows
    );
    RETURN pg_catalog.jsonb_build_object(
        'requestId', p_request_id,
        'orderedManifestHash', p_ordered_manifest_hash,
        'expectedRows', p_expected_rows,
        'sealed', FALSE
    );
END;
$_$;


--
-- Name: bind_analysis_revenue_fresh_provider_dataset_v1(uuid, text, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_analysis_revenue_fresh_provider_dataset_v1(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_operation_key text, p_provider_input_hash text, p_provider_run_hash text, p_provider_dataset_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_provider public.analysis_v2_provider_runs%ROWTYPE;
    v_existing public.analysis_revenue_fresh_provider_evidence%ROWTYPE;
    v_operation_hash TEXT;
    v_expected_run_hash TEXT;
BEGIN
    IF p_provider_run_hash IS NULL OR p_provider_run_hash !~ '^[a-f0-9]{64}$'
       OR p_provider_dataset_hash IS NULL OR p_provider_dataset_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_FENCE', ERRCODE = 'P0001';
    END IF;
    -- Admission locks preflight → request → job → provider/source → revenue parent
    -- before this source can acquire an immutable Dataset binding.
    PERFORM public.assert_analysis_revenue_fresh_provider_admission_v1(
        p_request_id, p_job_key, p_job_claim_token, p_job_input_hash,
        p_operation_key, p_provider_input_hash
    );
    SELECT * INTO v_provider
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    FOR UPDATE;
    IF v_provider.request_id IS NULL
       OR v_provider.logical_provider IS DISTINCT FROM 'apify'
       OR v_provider.input_hash IS DISTINCT FROM p_provider_input_hash
       OR v_provider.status IS DISTINCT FROM 'succeeded'
       OR v_provider.run_id IS NULL OR v_provider.run_started_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_NOT_FRESH', ERRCODE = 'P0001';
    END IF;
    v_operation_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
        'analysis-revenue-fresh-provider-operation/v1|'
        || pg_catalog.octet_length(p_operation_key)::TEXT || ':' || p_operation_key,
        'UTF8'
    ), 'sha256'), 'hex');
    v_expected_run_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
        'analysis-revenue-fresh-provider-run/v1|'
        || pg_catalog.octet_length(p_request_id::TEXT)::TEXT || ':' || p_request_id::TEXT || '|'
        || pg_catalog.octet_length(p_job_key)::TEXT || ':' || p_job_key || '|'
        || pg_catalog.octet_length(p_operation_key)::TEXT || ':' || p_operation_key || '|'
        || pg_catalog.octet_length(v_provider.run_id)::TEXT || ':' || v_provider.run_id,
        'UTF8'
    ), 'sha256'), 'hex');
    IF p_provider_run_hash IS DISTINCT FROM v_expected_run_hash THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_DRIFT', ERRCODE = 'P0001';
    END IF;
    SELECT * INTO v_existing
    FROM public.analysis_revenue_fresh_provider_evidence AS evidence
    WHERE evidence.request_id = p_request_id
      AND evidence.job_key = p_job_key
      AND evidence.operation_key_hash = v_operation_hash
    FOR UPDATE;
    IF NOT FOUND
       OR v_existing.job_input_hash IS DISTINCT FROM p_job_input_hash
       OR v_existing.provider IS DISTINCT FROM 'apify'
       OR v_existing.provider_input_hash IS DISTINCT FROM p_provider_input_hash
       OR v_existing.provider_run_hash IS DISTINCT FROM v_expected_run_hash
       OR NOT v_existing.no_reuse OR NOT v_existing.no_adoption OR NOT v_existing.no_cache THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_DRIFT', ERRCODE = 'P0001';
    END IF;
    IF v_existing.provider_dataset_hash IS NULL THEN
        UPDATE public.analysis_revenue_fresh_provider_evidence
        SET provider_dataset_hash = p_provider_dataset_hash,
            dataset_bound_at = pg_catalog.clock_timestamp()
        WHERE request_id = p_request_id
          AND job_key = p_job_key
          AND operation_key_hash = v_operation_hash;
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'bound', 'created', TRUE, 'replayed', FALSE
        );
    END IF;
    IF v_existing.provider_dataset_hash IS DISTINCT FROM p_provider_dataset_hash THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_DRIFT', ERRCODE = 'P0001';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'disposition', 'bound', 'created', FALSE, 'replayed', TRUE
    );
END;
$_$;


--
-- Name: bind_analysis_v2_authorized_test_provider_policy(uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_analysis_v2_authorized_test_provider_policy(p_request_id uuid, p_user_id uuid, p_entitlement_jti_hash text, p_target_instagram_id text, p_policy_version text, p_operation_slot_map jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_existing public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_policy_hash TEXT;
BEGIN
    IF p_request_id IS NULL
       OR p_user_id IS NULL
       OR p_entitlement_jti_hash IS NULL
       OR p_entitlement_jti_hash !~ '^[a-f0-9]{64}$'
       OR p_target_instagram_id IS NULL
       OR p_target_instagram_id !~ '^[a-z0-9._]{1,30}$'
       OR p_policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR NOT public.analysis_v2_valid_test_operation_slot_map(p_operation_slot_map) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AUTHORIZED_TEST_POLICY_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;

    IF NOT FOUND
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.user_id IS DISTINCT FROM p_user_id
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.test_entitlement_jti_hash IS DISTINCT FROM p_entitlement_jti_hash
       OR pg_catalog.lower(v_request.target_instagram_id)
            IS DISTINCT FROM p_target_instagram_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AUTHORIZED_TEST_POLICY_SCOPE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    v_policy_hash := pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                p_policy_version || E'\n'
                || p_target_instagram_id || E'\n'
                || p_operation_slot_map::TEXT,
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );

    SELECT policy.*
    INTO v_existing
    FROM public.analysis_v2_provider_execution_policies AS policy
    WHERE policy.request_id = p_request_id
    FOR UPDATE;

    IF FOUND THEN
        IF v_existing.mode IS DISTINCT FROM 'test_operation_split'
           OR v_existing.policy_version IS DISTINCT FROM p_policy_version
           OR v_existing.entitlement_jti_hash IS DISTINCT FROM p_entitlement_jti_hash
           OR v_existing.target_instagram_id IS DISTINCT FROM p_target_instagram_id
           OR v_existing.operation_slot_map IS DISTINCT FROM p_operation_slot_map
           OR v_existing.policy_hash IS DISTINCT FROM v_policy_hash THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_AUTHORIZED_TEST_POLICY_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'mode', v_existing.mode,
            'policyVersion', v_existing.policy_version,
            'operationSlots', v_existing.operation_slot_map,
            'policyHash', v_existing.policy_hash
        );
    END IF;

    IF v_request.status IS DISTINCT FROM 'pending'
       OR v_request.background_processing IS DISTINCT FROM FALSE
       OR EXISTS (
            SELECT 1
            FROM public.analysis_pipeline_jobs AS job
            WHERE job.request_id = p_request_id
              AND (job.status <> 'pending' OR job.dispatch_state <> 'pending')
       )
       OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_provider_runs AS provider_run
            WHERE provider_run.request_id = p_request_id
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AUTHORIZED_TEST_POLICY_TOO_LATE', ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.analysis_v2_provider_execution_policies (
        request_id,
        mode,
        policy_version,
        entitlement_jti_hash,
        target_instagram_id,
        operation_slot_map,
        policy_hash
    ) VALUES (
        p_request_id,
        'test_operation_split',
        p_policy_version,
        p_entitlement_jti_hash,
        p_target_instagram_id,
        p_operation_slot_map,
        v_policy_hash
    ) RETURNING * INTO v_existing;

    RETURN pg_catalog.jsonb_build_object(
        'mode', v_existing.mode,
        'policyVersion', v_existing.policy_version,
        'operationSlots', v_existing.operation_slot_map,
        'policyHash', v_existing.policy_hash
    );
END;
$_$;


--
-- Name: bind_analysis_v2_replay_capture(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_analysis_v2_replay_capture(p_capture_id uuid, p_request_id uuid, p_operator_fingerprint text, p_reason_code text) RETURNS TABLE(write_lease_token uuid, write_lease_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_capture public.analysis_v2_replay_capture_authorizations%ROWTYPE;
    v_policy_hash TEXT;
    v_snapshot_hash TEXT;
    v_context_hash TEXT;
    v_target_commitment TEXT;
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_write_lease_token UUID;
    v_write_lease_expires_at TIMESTAMPTZ;
BEGIN
    IF p_operator_fingerprint !~ '^[a-f0-9]{64}$' OR p_reason_code !~ '^[A-Z0-9_]{1,64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_CAPTURE_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT * INTO v_capture FROM public.analysis_v2_replay_capture_authorizations WHERE capture_id = p_capture_id FOR UPDATE;
    IF NOT FOUND OR v_capture.state <> 'armed'
       OR v_capture.arm_expires_at <= v_now
       OR v_capture.artifact_expires_at <= v_now
       OR v_capture.request_id IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_CAPTURE_BIND_REJECTED', ERRCODE = 'P0001';
    END IF;
    SELECT
        pg_catalog.encode(extensions.digest(analysis_request.policy_versions_snapshot::TEXT, 'sha256'), 'hex'),
        pg_catalog.encode(extensions.digest(pg_catalog.jsonb_build_object('policy', analysis_request.policy_versions_snapshot, 'planCards', analysis_request.plan_cards_snapshot)::TEXT, 'sha256'), 'hex'),
        pg_catalog.encode(extensions.digest(
            'replay-capture-context-v1' || pg_catalog.chr(10)
            || analysis_request.user_id::TEXT || pg_catalog.chr(10)
            || pg_catalog.lower(pg_catalog.btrim(analysis_request.target_instagram_id))
            || pg_catalog.chr(10) || analysis_request.policy_versions_snapshot::TEXT,
            'sha256'
        ), 'hex'),
        pg_catalog.encode(extensions.digest(
            'replay-target-v1' || pg_catalog.chr(10)
            || analysis_request.user_id::TEXT || pg_catalog.chr(10)
            || pg_catalog.lower(pg_catalog.btrim(analysis_request.target_instagram_id)),
            'sha256'
        ), 'hex')
    INTO v_policy_hash, v_snapshot_hash, v_context_hash, v_target_commitment
    FROM public.analysis_requests AS analysis_request
    JOIN public.analysis_preflights AS preflight ON preflight.id = analysis_request.preflight_id
    WHERE analysis_request.id = p_request_id
      AND analysis_request.preflight_id = v_capture.preflight_id
      AND analysis_request.pipeline_version = 'v2'
      AND analysis_request.status IN ('pending', 'processing')
      AND analysis_request.selected_plan_id_snapshot = 'standard'
      AND analysis_request.plan_access_mode_snapshot = 'production'
      AND analysis_request.user_id = preflight.user_id
      AND analysis_request.user_id = v_capture.owner_user_id
      AND pg_catalog.lower(pg_catalog.btrim(analysis_request.target_instagram_id))
            = pg_catalog.lower(pg_catalog.btrim(preflight.target_instagram_id))
      AND public.analysis_v2_replay_capture_policy_is_exact(
            analysis_request.policy_versions_snapshot
      )
      AND preflight.status = 'consumed'
      AND preflight.consumed_request_id = analysis_request.id;
    IF NOT FOUND
       OR v_policy_hash IS DISTINCT FROM v_capture.expected_policy_hash
       OR v_snapshot_hash IS DISTINCT FROM v_capture.expected_snapshot_hash
       OR v_context_hash IS DISTINCT FROM v_capture.expected_context_hash
       OR v_target_commitment IS DISTINCT FROM v_capture.target_handle_commitment THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_CAPTURE_BIND_REJECTED', ERRCODE = 'P0001';
    END IF;
    v_write_lease_token := extensions.gen_random_uuid();
    v_write_lease_expires_at := CASE
        WHEN v_now + INTERVAL '15 minutes' < v_capture.arm_expires_at
            THEN v_now + INTERVAL '15 minutes'
        ELSE v_capture.arm_expires_at
    END;
    UPDATE public.analysis_v2_replay_capture_authorizations
    SET request_id = p_request_id,
        state = 'capturing',
        bound_at = v_now,
        write_lease_token = v_write_lease_token,
        write_lease_acquired_at = v_now,
        write_lease_expires_at = v_write_lease_expires_at,
        updated_at = v_now
    WHERE capture_id = p_capture_id;
    INSERT INTO public.analysis_v2_replay_capture_audit_events (capture_id, event_type, operator_fingerprint, reason_code)
    VALUES (p_capture_id, 'bind', p_operator_fingerprint, p_reason_code);
    RETURN QUERY SELECT v_write_lease_token, v_write_lease_expires_at;
END;
$_$;


--
-- Name: bind_earlybird_order_scoped_apify_slot(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_earlybird_order_scoped_apify_slot(p_order_id uuid, p_credential_slot text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_order public.earlybird_orders%ROWTYPE;
BEGIN
    IF p_order_id IS NULL
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
    THEN RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_ORDER_CREDENTIAL_SLOT_INVALID', ERRCODE = 'P0001'; END IF;
    SELECT * INTO v_order FROM public.earlybird_orders WHERE id = p_order_id FOR UPDATE;
    IF NOT FOUND OR v_order.status <> 'paid'
       OR v_order.payment_id IS NULL
       OR v_order.preflight_id IS NULL
       OR EXISTS (SELECT 1 FROM public.earlybird_fulfillments f WHERE f.order_id = v_order.id AND f.request_id IS NOT NULL)
    THEN RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_ORDER_CREDENTIAL_SLOT_INELIGIBLE', ERRCODE = 'P0001'; END IF;
    IF v_order.concierge_apify_credential_slot IS NOT NULL
       AND v_order.concierge_apify_credential_slot <> p_credential_slot
    THEN RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_ORDER_CREDENTIAL_SLOT_IMMUTABLE', ERRCODE = 'P0001'; END IF;
    UPDATE public.earlybird_orders
    SET concierge_apify_credential_slot = p_credential_slot, updated_at = pg_catalog.clock_timestamp()
    WHERE id = p_order_id;
    UPDATE public.analysis_preflights
    SET order_scoped_apify_credential_slot = p_credential_slot,
        updated_at = pg_catalog.clock_timestamp()
    WHERE id = v_order.preflight_id;
    RETURN TRUE;
END;
$$;


--
-- Name: bind_landing_lead_journey_to_preflight(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_landing_lead_journey_to_preflight(p_journey_id uuid, p_source_preflight_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    UPDATE public.landing_leads
    SET source_preflight_id = p_source_preflight_id,
        mapping_source = CASE
            WHEN mapping_source = 'legacy_import_v1' THEN mapping_source
            ELSE 'preflight_v1'
        END
    WHERE journey_id = p_journey_id
      AND input_context = 'target'
      AND (
          source_preflight_id IS NULL
          OR source_preflight_id = p_source_preflight_id
      )
      AND mapping_status <> 'unlinked_after_deletion';
    RETURN FOUND;
END;
$$;


--
-- Name: block_analysis_beta_preflight_capacity(uuid, uuid, integer, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_analysis_beta_preflight_capacity(p_preflight_id uuid, p_user_id uuid, p_prepare_generation integer, p_prepare_token uuid, p_claim_token uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE v_gate_enabled BOOLEAN; v_grant public.analysis_beta_access_grants%ROWTYPE;
DECLARE v_preflight public.analysis_preflights%ROWTYPE;
DECLARE v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
DECLARE v_reservation public.analysis_beta_pool_reservations%ROWTYPE;
DECLARE v_has_allocation BOOLEAN := FALSE;
BEGIN
    SELECT gate_row.enabled INTO v_gate_enabled
    FROM public.analysis_beta_runtime_gate AS gate_row
    WHERE gate_row.singleton=TRUE FOR SHARE;
    PERFORM 1 FROM public.users AS owner_user
    WHERE owner_user.id=p_user_id FOR KEY SHARE;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight
    WHERE preflight.id=p_preflight_id AND preflight.user_id=p_user_id FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.beta_entry_provenance IS DISTINCT FROM 'betatest_service_v1'
       OR v_preflight.beta_prepare_generation IS DISTINCT FROM p_prepare_generation
       OR v_preflight.beta_prepare_token IS DISTINCT FROM p_prepare_token THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_PREPARE_FENCE_MISMATCH', ERRCODE='P0001';
    END IF;
    IF v_preflight.beta_prepare_state='capacity_blocked' THEN RETURN 'blocked'; END IF;
    IF v_preflight.beta_prepare_state='prepared' THEN RETURN 'prepared'; END IF;
    IF v_preflight.beta_prepare_state='retry_exhausted' THEN RETURN 'retry_exhausted'; END IF;
    IF v_preflight.beta_prepare_state='expired' THEN RETURN 'expired'; END IF;
    IF NOT (
        (
            v_preflight.beta_prepare_state='reserved'
            AND p_claim_token IS NULL
            AND v_preflight.analysis_entry_channel='standard'
        ) OR (
            v_preflight.beta_prepare_state='preparing'
            AND p_claim_token IS NOT NULL
            AND v_preflight.beta_prepare_lease_token IS NOT DISTINCT FROM p_claim_token
        )
    ) THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_PREPARE_FENCE_MISMATCH', ERRCODE='P0001';
    END IF;
    SELECT allocation.* INTO v_allocation FROM public.analysis_beta_pool_allocations AS allocation
    WHERE allocation.preflight_id=p_preflight_id FOR UPDATE;
    v_has_allocation := FOUND;
    IF v_has_allocation THEN
        SELECT reservation.* INTO v_reservation FROM public.analysis_beta_pool_reservations AS reservation
        WHERE reservation.allocation_id=v_allocation.id AND reservation.operation_family='target-profile' FOR UPDATE;
        IF NOT FOUND OR v_allocation.lifecycle_state IS DISTINCT FROM 'preflight_held'
           OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'betatest'
           OR v_reservation.lifecycle_state IS DISTINCT FROM 'preflight_held' THEN
            RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE='P0001';
        END IF;
    END IF;
    SELECT grant_row.* INTO v_grant
    FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id=p_user_id FOR SHARE;
    IF v_has_allocation THEN
        UPDATE public.analysis_preflights SET beta_prepare_state='prepared',
            beta_prepare_dispatch_state='completed',beta_prepare_lease_token=NULL,
            beta_prepare_lease_expires_at=NULL,beta_prepare_retry_exhausted_at=NULL,
            beta_prepare_completed_at=pg_catalog.clock_timestamp(),
            updated_at=pg_catalog.clock_timestamp() WHERE id=p_preflight_id;
        RETURN 'prepared';
    END IF;
    UPDATE public.analysis_preflights SET analysis_entry_channel='betatest',
        status='blocked',error_code='BETA_CAPACITY_UNAVAILABLE',
        blocked_at=pg_catalog.clock_timestamp(),beta_prepare_state='capacity_blocked',
        beta_prepare_dispatch_state='completed',beta_prepare_lease_token=NULL,
        beta_prepare_lease_expires_at=NULL,beta_prepare_retry_exhausted_at=NULL,
        beta_prepare_completed_at=pg_catalog.clock_timestamp(),
        updated_at=pg_catalog.clock_timestamp() WHERE id=p_preflight_id;
    RETURN 'blocked';
END;
$$;


--
-- Name: block_analysis_v2_preflight(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_analysis_v2_preflight(p_preflight_id uuid, p_user_id uuid, p_claim_token uuid, p_error_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_error_code IS NULL
       OR p_error_code NOT IN (
           'TARGET_NOT_FOUND',
           'TARGET_PRIVATE',
           'TARGET_UNSUPPORTED',
           'OVER_PLUS_CAPACITY',
           'EXCLUSION_REQUIRED',
           'INVALID_EXCLUSION',
           'PLAN_UPGRADE_REQUIRED',
           'RELATIONSHIP_INCOMPLETE',
           'PROFILE_EVIDENCE_INCOMPLETE',
           'QUEUE_UNAVAILABLE',
           'AI_RATE_LIMITED',
           'AI_AMBIGUOUS_RESULT',
           'ANALYSIS_FAILED'
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_BLOCK_INPUT', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.expires_at <= v_now OR v_preflight.status = 'expired' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_EXPIRED', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status = 'blocked' THEN
        IF v_preflight.error_code = p_error_code THEN
            RETURN FALSE;
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_BLOCK_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status = 'processing' THEN
        IF p_claim_token IS NULL
           OR v_preflight.lease_token IS DISTINCT FROM p_claim_token
           OR v_preflight.lease_expires_at <= v_now THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_LEASE_LOST', ERRCODE = 'P0001';
        END IF;
    ELSIF v_preflight.status = 'pending' THEN
        IF p_error_code <> 'QUEUE_UNAVAILABLE' OR p_claim_token IS NOT NULL THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
        END IF;
    ELSE
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights
    SET status = 'blocked',
        error_code = p_error_code,
        blocked_at = v_now,
        lease_token = NULL,
        lease_expires_at = NULL,
        updated_at = v_now
    WHERE id = v_preflight.id;
    RETURN TRUE;
END;
$$;


--
-- Name: block_analysis_v2_preflight_admission(uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_analysis_v2_preflight_admission(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid, p_error_code text) RETURNS TABLE(admission_status text, admission_error_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    IF p_error_code IS NULL OR p_error_code NOT IN (
        'ANALYSIS_V2_TARGET_NOT_FOUND',
        'ANALYSIS_V2_TARGET_PRIVATE'
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_FRESH_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET admission_status = 'blocked',
        admission_refreshed_at = v_now,
        admission_claim_token = NULL,
        admission_lease_expires_at = NULL,
        admission_error_code = p_error_code,
        admission_target_followers_count = NULL,
        admission_target_following_count = NULL,
        admission_capacity_required_plan_id = NULL,
        admission_required_plan_id = NULL,
        admission_plan_cards_snapshot = NULL,
        updated_at = v_now
    WHERE preflight.id = p_preflight_id
      AND preflight.admission_generation = p_admission_generation
      AND preflight.admission_status = 'processing'
      AND preflight.admission_claim_token = p_claim_token;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    RETURN QUERY SELECT 'blocked'::TEXT, p_error_code;
END;
$$;


--
-- Name: block_anonymous_analysis_v2_preflight(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_anonymous_analysis_v2_preflight(p_preflight_id uuid, p_claim_token uuid, p_error_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_claim_token IS NULL
       OR p_error_code IS NULL
       OR p_error_code NOT IN (
           'TARGET_NOT_FOUND', 'TARGET_PRIVATE', 'TARGET_UNSUPPORTED',
           'OVER_PLUS_CAPACITY', 'EXCLUSION_REQUIRED', 'INVALID_EXCLUSION',
           'PLAN_UPGRADE_REQUIRED', 'RELATIONSHIP_INCOMPLETE',
           'PROFILE_EVIDENCE_INCOMPLETE', 'QUEUE_UNAVAILABLE', 'AI_RATE_LIMITED',
           'AI_AMBIGUOUS_RESULT', 'ANALYSIS_FAILED'
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_INVALID_BLOCK_INPUT', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id IS NULL
      AND preflight.provider_selector = 'anonymous_apify'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.expires_at <= v_now OR v_preflight.status = 'expired' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_EXPIRED', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status = 'blocked' THEN
        IF v_preflight.error_code = p_error_code THEN RETURN FALSE; END IF;
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_BLOCK_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status <> 'processing'
       OR v_preflight.lease_token IS DISTINCT FROM p_claim_token
       OR v_preflight.lease_expires_at IS NULL
       OR v_preflight.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_LEASE_LOST', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights
    SET status = 'blocked',
        error_code = p_error_code,
        blocked_at = v_now,
        lease_token = NULL,
        lease_expires_at = NULL,
        updated_at = v_now
    WHERE id = v_preflight.id;
    RETURN TRUE;
END;
$$;


--
-- Name: bootstrap_earlybird_v211_concierge_first_order(uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, text, text, smallint, integer, integer, integer, integer, integer, text, text, jsonb, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bootstrap_earlybird_v211_concierge_first_order(p_order_id uuid, p_owner_id uuid, p_source_request_id uuid, p_first_relationship_request_id uuid, p_second_relationship_request_id uuid, p_failed_preflight_id uuid, p_rearmed_preflight_id uuid, p_result_request_id uuid, p_target_instagram_id text, p_expected_fulfillment_status text, p_expected_fulfillment_attempt_count smallint, p_exact_mutual integer, p_hydrated integer, p_public integer, p_private integer, p_unresolved integer, p_source_fingerprint text, p_result_hash text, p_artifact_hashes jsonb, p_followers jsonb, p_following jsonb, p_target_evidence jsonb, p_publication_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_candidate_count INTEGER;
    v_intersection_count INTEGER;
    v_recovery_rows INTEGER;
    v_recovery_table TEXT;
    v_replay RECORD;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_source public.analysis_requests%ROWTYPE;
    v_result public.analysis_requests%ROWTYPE;
    v_target TEXT;
    v_artifact_keys TEXT[] := ARRAY[
        'allPublicClassifications', 'resultHash', 'sourceFingerprint',
        'targetEvidenceManifest', 'unknownReviewCsv'
    ];
BEGIN
    PERFORM public.assert_earlybird_receipt_archive_purge_safe();
    v_target := pg_catalog.lower(
        pg_catalog.regexp_replace(pg_catalog.btrim(p_target_instagram_id), '^@', '')
    );

    IF p_order_id IS NULL
       OR p_owner_id IS NULL
       OR p_source_request_id IS NULL
       OR p_first_relationship_request_id IS NULL
       OR p_second_relationship_request_id IS NULL
       OR p_failed_preflight_id IS NULL
       OR p_rearmed_preflight_id IS NULL
       OR p_result_request_id IS NULL
       OR (
            p_source_request_id IN (
                p_first_relationship_request_id, p_second_relationship_request_id,
                p_result_request_id
            )
            AND NOT (
                p_first_relationship_request_id = p_source_request_id
                AND p_second_relationship_request_id = p_source_request_id
            )
       )
       OR (
            p_first_relationship_request_id = p_second_relationship_request_id
            AND p_first_relationship_request_id <> p_source_request_id
       )
       OR p_first_relationship_request_id = p_result_request_id
       OR p_second_relationship_request_id = p_result_request_id
       OR v_target IS NULL
       OR v_target !~ '^[a-z0-9._]{1,30}$'
       OR p_expected_fulfillment_status IS DISTINCT FROM 'analysis_in_progress'
       OR p_expected_fulfillment_attempt_count IS DISTINCT FROM 2
       OR p_exact_mutual IS DISTINCT FROM 149
       OR p_hydrated IS DISTINCT FROM 148
       OR p_public IS DISTINCT FROM 53
       OR p_private IS DISTINCT FROM 95
       OR p_unresolved IS DISTINCT FROM 1
       OR p_source_fingerprint IS NULL
       OR p_source_fingerprint !~ '^[a-f0-9]{64}$'
       OR p_result_hash IS NULL
       OR p_result_hash !~ '^[a-f0-9]{64}$'
       OR p_artifact_hashes IS NULL
       OR pg_catalog.jsonb_typeof(p_artifact_hashes) IS DISTINCT FROM 'object'
       OR p_artifact_hashes - v_artifact_keys <> '{}'::JSONB
       OR NOT p_artifact_hashes ?& v_artifact_keys
       OR p_artifact_hashes->>'sourceFingerprint' IS DISTINCT FROM p_source_fingerprint
       OR p_artifact_hashes->>'resultHash' IS DISTINCT FROM p_result_hash
       OR p_artifact_hashes->>'targetEvidenceManifest' IS NULL
       OR p_artifact_hashes->>'targetEvidenceManifest' !~ '^[a-f0-9]{64}$'
       OR p_artifact_hashes->>'allPublicClassifications'
            IS DISTINCT FROM '47a657f1c534680043e24ca44f9e2eaa16854b55cd34ab65e3bb2a8dee7fa8cb'
       OR p_artifact_hashes->>'unknownReviewCsv'
            IS DISTINCT FROM '1c66ac59cb97a18441c613178a77202f6a9501d22d5de85e561e0208a568e367'
       OR pg_catalog.jsonb_typeof(p_followers) IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(p_following) IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(p_target_evidence) IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(p_publication_payload) IS DISTINCT FROM 'object'
       OR pg_catalog.jsonb_typeof(p_publication_payload->'femaleRows') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(p_publication_payload->'privateRows') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(p_publication_payload->'unresolvedUsernames') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(p_publication_payload->'unavailablePublicUsernames') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(p_publication_payload->'publicGender') IS DISTINCT FROM 'object'
       OR (p_publication_payload->'publicGender') - ARRAY['male', 'female', 'unknown'] <> '{}'::JSONB
       OR NOT ((p_publication_payload->'publicGender') ?& ARRAY['male', 'female', 'unknown'])
       OR p_publication_payload->'publicGender'->>'male' !~ '^[0-9]{1,3}$'
       OR p_publication_payload->'publicGender'->>'female' !~ '^[0-9]{1,3}$'
       OR p_publication_payload->'publicGender'->>'unknown' !~ '^[0-9]{1,3}$'
       OR (
            (p_publication_payload->'publicGender'->>'male')::INTEGER
            + (p_publication_payload->'publicGender'->>'female')::INTEGER
            + (p_publication_payload->'publicGender'->>'unknown')::INTEGER
       ) IS DISTINCT FROM p_public
       OR p_publication_payload->>'sourceFingerprint' IS DISTINCT FROM p_source_fingerprint
       OR p_publication_payload->>'resultHash' IS DISTINCT FROM p_result_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_FIRST_ORDER_BOOTSTRAP_INPUT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- The supplied CSV is the reviewed immutable file.  The prior manifest
    -- hash is intentionally not accepted, even if every other field matches.
    IF pg_catalog.jsonb_array_length(p_followers) <> 157
       OR pg_catalog.jsonb_array_length(p_following) <> 361
       OR pg_catalog.jsonb_array_length(p_target_evidence) <> 95 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_BOOTSTRAP_RELATIONSHIP_ARTIFACT_MISSING',
            ERRCODE = 'P0001';
    END IF;

    IF pg_catalog.jsonb_array_length(p_publication_payload->'femaleRows')
           <> (p_publication_payload->'publicGender'->>'female')::INTEGER
       OR pg_catalog.jsonb_array_length(p_publication_payload->'privateRows') <> p_private THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_BOOTSTRAP_PUBLICATION_PAYLOAD_INVALID',
            ERRCODE = 'P0001';
    END IF;

    IF pg_catalog.jsonb_array_length(p_publication_payload->'unresolvedUsernames') <> p_unresolved
       OR (
            SELECT pg_catalog.count(*)
            FROM pg_catalog.jsonb_array_elements(p_publication_payload->'unresolvedUsernames') AS item
            WHERE pg_catalog.jsonb_typeof(item) IS DISTINCT FROM 'string'
               OR item #>> '{}' !~ '^[a-z0-9._]{1,30}$'
       ) <> 0
       OR (
            SELECT pg_catalog.count(*)
            FROM pg_catalog.jsonb_array_elements_text(p_publication_payload->'unresolvedUsernames') AS item(username)
       ) <> (
            SELECT pg_catalog.count(DISTINCT item.username)
            FROM pg_catalog.jsonb_array_elements_text(p_publication_payload->'unresolvedUsernames') AS item(username)
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_BOOTSTRAP_UNRESOLVED_PROVENANCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    IF (
        SELECT pg_catalog.count(*)
        FROM pg_catalog.jsonb_array_elements(p_publication_payload->'unavailablePublicUsernames') AS item
        WHERE pg_catalog.jsonb_typeof(item) IS DISTINCT FROM 'string'
           OR item #>> '{}' !~ '^[a-z0-9._]{1,30}$'
    ) <> 0
       OR (
            SELECT pg_catalog.count(*)
            FROM pg_catalog.jsonb_array_elements_text(p_publication_payload->'unavailablePublicUsernames') AS item(username)
       ) <> (
            SELECT pg_catalog.count(DISTINCT item.username)
            FROM pg_catalog.jsonb_array_elements_text(p_publication_payload->'unavailablePublicUsernames') AS item(username)
       )
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements_text(p_publication_payload->'unavailablePublicUsernames') AS unavailable(username)
            WHERE NOT EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_array_elements(p_followers) AS follower
                JOIN pg_catalog.jsonb_array_elements(p_following) AS following
                  ON following->>'username' = follower->>'username'
                WHERE follower->>'username' = unavailable.username
            )
            OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_array_elements(p_publication_payload->'privateRows') AS private_row
                WHERE private_row->>'instagram_id' = unavailable.username
            )
            OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_array_elements(p_publication_payload->'femaleRows') AS female_row
                WHERE female_row->>'suspect_instagram_id' = unavailable.username
            )
            OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_array_elements_text(p_publication_payload->'unresolvedUsernames') AS unresolved(username)
                WHERE unresolved.username = unavailable.username
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_BOOTSTRAP_PROFILE_UNAVAILABLE_PROVENANCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements_text(p_publication_payload->'unresolvedUsernames') AS unresolved(username)
        WHERE NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_followers) AS follower
            JOIN pg_catalog.jsonb_array_elements(p_following) AS following
              ON following->>'username' = follower->>'username'
            WHERE follower->>'username' = unresolved.username
        )
        OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_publication_payload->'privateRows') AS private_row
            WHERE private_row->>'instagram_id' = unresolved.username
        )
        OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_publication_payload->'femaleRows') AS female_row
            WHERE female_row->>'suspect_instagram_id' = unresolved.username
        )
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_BOOTSTRAP_UNRESOLVED_PROVENANCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_publication_payload->'femaleRows') AS item
        WHERE item->>'suspect_instagram_id' IS NULL
           OR item->>'suspect_instagram_id' !~ '^[a-z0-9._]{1,30}$'
           OR item->>'risk_grade' IS NULL
           OR item->>'risk_grade' NOT IN ('normal', 'caution', 'high_risk')
           OR item->>'gender_status' IS DISTINCT FROM 'confirmed'
           OR item->>'one_line_overview' IS NULL
           OR pg_catalog.char_length(item->>'one_line_overview') NOT BETWEEN 1 AND 180
           OR pg_catalog.jsonb_typeof(item->'risk_analysis') IS DISTINCT FROM 'array'
           OR (item->>'risk_grade' = 'high_risk'
               AND pg_catalog.jsonb_array_length(item->'risk_analysis') <> 2)
           OR (item->>'risk_grade' <> 'high_risk'
               AND pg_catalog.jsonb_array_length(item->'risk_analysis') <> 0)
    ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_publication_payload->'privateRows') AS item
        WHERE item->>'instagram_id' IS NULL
           OR item->>'instagram_id' !~ '^[a-z0-9._]{1,30}$'
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_BOOTSTRAP_PUBLICATION_PAYLOAD_INVALID',
            ERRCODE = 'P0001';
    END IF;
    IF (
        SELECT pg_catalog.count(*)
        FROM pg_catalog.jsonb_array_elements(p_publication_payload->'femaleRows') AS item
    ) <> (
        SELECT pg_catalog.count(DISTINCT item->>'suspect_instagram_id')
        FROM pg_catalog.jsonb_array_elements(p_publication_payload->'femaleRows') AS item
    ) OR (
        SELECT pg_catalog.count(*)
        FROM pg_catalog.jsonb_array_elements(p_publication_payload->'privateRows') AS item
    ) <> (
        SELECT pg_catalog.count(DISTINCT item->>'instagram_id')
        FROM pg_catalog.jsonb_array_elements(p_publication_payload->'privateRows') AS item
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_BOOTSTRAP_PUBLICATION_PAYLOAD_INVALID',
            ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_followers) AS item
        WHERE pg_catalog.jsonb_typeof(item) IS DISTINCT FROM 'object'
           OR item->>'username' IS NULL
           OR item->>'username' !~ '^[a-z0-9._]{1,30}$'
    ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_following) AS item
        WHERE pg_catalog.jsonb_typeof(item) IS DISTINCT FROM 'object'
           OR item->>'username' IS NULL
           OR item->>'username' !~ '^[a-z0-9._]{1,30}$'
    ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_target_evidence) AS item
        WHERE pg_catalog.jsonb_typeof(item) IS DISTINCT FROM 'object'
           OR item->>'actorUsername' IS NULL
           OR item->>'actorUsername' !~ '^[a-z0-9._]{1,30}$'
           OR item->>'postId' IS NULL
           OR item->>'sourceInteractionId' IS NULL
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_BOOTSTRAP_RELATIONSHIP_ARTIFACT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    IF (
        SELECT pg_catalog.count(*)
        FROM pg_catalog.jsonb_array_elements(p_followers) AS item
    ) <> (
        SELECT pg_catalog.count(DISTINCT item->>'username')
        FROM pg_catalog.jsonb_array_elements(p_followers) AS item
    ) OR (
        SELECT pg_catalog.count(*)
        FROM pg_catalog.jsonb_array_elements(p_following) AS item
    ) <> (
        SELECT pg_catalog.count(DISTINCT item->>'username')
        FROM pg_catalog.jsonb_array_elements(p_following) AS item
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_BOOTSTRAP_RELATIONSHIP_ARTIFACT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.count(*) INTO v_intersection_count
    FROM (
        SELECT DISTINCT item->>'username' AS username
        FROM pg_catalog.jsonb_array_elements(p_followers) AS item
    ) AS followers
    JOIN (
        SELECT DISTINCT item->>'username' AS username
        FROM pg_catalog.jsonb_array_elements(p_following) AS item
    ) AS following USING (username);
    IF v_intersection_count <> p_exact_mutual THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_BOOTSTRAP_RELATIONSHIP_COUNT_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_target_evidence) AS item
        GROUP BY item->>'actorUsername', item->>'postId', item->>'sourceInteractionId'
        HAVING pg_catalog.count(*) > 1
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_BOOTSTRAP_TARGET_EVIDENCE_DUPLICATE',
            ERRCODE = 'P0001';
    END IF;

    IF p_exact_mutual <> p_hydrated + p_unresolved
       OR p_hydrated <> p_public + p_private THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_BOOTSTRAP_COUNT_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    -- This lock is independent from normal admission/rearm locks.  It covers
    -- only the one historical first-paid Basic concierge scope.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'earlybird-v211-concierge-first-paid-basic:2026-08-12', 0
        )
    );

    SELECT pg_catalog.count(*) INTO v_candidate_count
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.plan_id = 'basic'
      AND earlybird_order.status = 'completed'
      AND earlybird_order.paid_at >= '2026-08-12T00:00:00Z'::TIMESTAMPTZ
      AND earlybird_order.paid_at < '2026-08-13T00:00:00Z'::TIMESTAMPTZ
      AND earlybird_order.payment_id IS NOT NULL
      AND earlybird_order.expected_amount_krw = 990
      AND earlybird_order.actual_amount_krw = 990
      AND earlybird_order.seller_reference_confirmed_at IS NOT NULL
      AND earlybird_order.actual_groble_product_id
            IS NOT DISTINCT FROM earlybird_order.expected_groble_product_id
      AND NOT EXISTS (
          SELECT 1
          FROM public.earlybird_webhook_events AS refund_event
          WHERE refund_event.event_type = 'payment.refunded'
            AND refund_event.payment_id = earlybird_order.payment_id
            AND refund_event.product_id = earlybird_order.actual_groble_product_id
            AND refund_event.amount_krw = earlybird_order.actual_amount_krw
            AND refund_event.refund_amount_krw = earlybird_order.actual_amount_krw
            AND refund_event.partial_refund IS FALSE
      );
    IF v_candidate_count <> 1 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_FIRST_ORDER_BOOTSTRAP_ORDER_SCOPE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    SELECT source_request.* INTO v_source
    FROM public.analysis_requests AS source_request
    WHERE source_request.id = p_source_request_id
    FOR UPDATE;
    SELECT result_request.* INTO v_result
    FROM public.analysis_requests AS result_request
    WHERE result_request.id = p_result_request_id
    FOR UPDATE;

    -- The order row lock is held before checking all recovery ledgers, so a
    -- concurrent admission/rearm path that uses the order lock cannot race a
    -- zero-row precondition into this one-shot scope.  Resolve the table list
    -- at runtime so minimal contract schemas can still install the function
    -- while production checks every deployed recovery ledger.
    
    IF EXISTS (
        SELECT 1
        FROM public.maintenance_jobs AS archive_source
        CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
            archive_source.payload->'legacy_row'
        ) AS archive_row(order_id UUID)
        WHERE archive_source.state = 'succeeded'
          AND archive_source.legacy_pending_user_id IS NULL
          AND archive_source.kind = 'replay'
          AND archive_source.payload->>'legacy_source_table' =
              'earlybird_v211_apify_transient_replays'
          AND archive_source.payload->>'schema_version' = '1'
          AND archive_source.payload->'legacy_row' ?& ARRAY['order_id']::TEXT[]
          AND archive_row.order_id = p_order_id
    ) OR EXISTS (
        SELECT 1
        FROM public.maintenance_jobs AS archive_source
        CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
            archive_source.payload->'legacy_row'
        ) AS archive_row(order_id UUID)
        WHERE archive_source.state = 'succeeded'
          AND archive_source.legacy_pending_user_id IS NULL
          AND archive_source.kind = 'replay'
          AND archive_source.payload->>'legacy_source_table' =
              'earlybird_v211_profile_ai_diagnostic_replays'
          AND archive_source.payload->>'schema_version' = '1'
          AND archive_source.payload->'legacy_row' ?& ARRAY['order_id']::TEXT[]
          AND archive_row.order_id = p_order_id
    ) OR EXISTS (
        SELECT 1
        FROM public.maintenance_jobs AS archive_source
        CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
            archive_source.payload->'legacy_row'
        ) AS archive_row(order_id UUID)
        WHERE archive_source.state = 'succeeded'
          AND archive_source.legacy_pending_user_id IS NULL
          AND archive_source.kind = 'replay'
          AND archive_source.payload->>'legacy_source_table' =
              'earlybird_v211_policy_identity_replays'
          AND archive_source.payload->>'schema_version' = '1'
          AND archive_source.payload->'legacy_row' ?& ARRAY['order_id']::TEXT[]
          AND archive_row.order_id = p_order_id
    ) OR EXISTS (
        SELECT 1
        FROM public.maintenance_jobs AS archive_source
        CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
            archive_source.payload->'legacy_row'
        ) AS archive_row(order_id UUID)
        WHERE archive_source.state = 'succeeded'
          AND archive_source.legacy_pending_user_id IS NULL
          AND archive_source.kind = 'rearm'
          AND archive_source.payload->>'legacy_source_table' =
              'earlybird_v211_relationship_lineage_failure_rearms'
          AND archive_source.payload->>'schema_version' = '1'
          AND archive_source.payload->'legacy_row' ?& ARRAY['order_id']::TEXT[]
          AND archive_row.order_id = p_order_id
    ) OR EXISTS (
        SELECT 1
        FROM public.maintenance_jobs AS archive_source
        CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
            archive_source.payload->'legacy_row'
        ) AS archive_row(order_id UUID)
        WHERE archive_source.state = 'succeeded'
          AND archive_source.legacy_pending_user_id IS NULL
          AND archive_source.kind = 'rearm'
          AND archive_source.payload->>'legacy_source_table' =
              'earlybird_v211_lease_policy_failure_rearms'
          AND archive_source.payload->>'schema_version' = '1'
          AND archive_source.payload->'legacy_row' ?& ARRAY['order_id']::TEXT[]
          AND archive_row.order_id = p_order_id
    ) OR EXISTS (
        SELECT 1
        FROM public.maintenance_jobs AS archive_source
        CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
            archive_source.payload->'legacy_row'
        ) AS archive_row(order_id UUID)
        WHERE archive_source.state = 'succeeded'
          AND archive_source.legacy_pending_user_id IS NULL
          AND archive_source.kind = 'recovery'
          AND archive_source.payload->>'legacy_source_table' =
              'earlybird_schema_failure_recoveries'
          AND archive_source.payload->>'schema_version' = '1'
          AND archive_source.payload->'legacy_row' ?& ARRAY['order_id']::TEXT[]
          AND archive_row.order_id = p_order_id
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_FIRST_ORDER_BOOTSTRAP_RECOVERY_SCOPE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;


    IF v_order.id IS NULL
       OR v_order.user_id IS DISTINCT FROM p_owner_id
       OR v_order.preflight_id IS DISTINCT FROM p_rearmed_preflight_id
       OR pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id))
            IS DISTINCT FROM v_target
       OR v_order.result_request_id IS DISTINCT FROM p_result_request_id
       OR v_order.status IS DISTINCT FROM 'completed'
       OR v_order.plan_id IS DISTINCT FROM 'basic'
       OR v_order.expected_amount_krw IS DISTINCT FROM 990
       OR v_order.actual_amount_krw IS DISTINCT FROM 990
       OR v_order.payment_id IS NULL
       OR v_order.seller_reference_confirmed_at IS NULL
       OR (
            v_order.exclusion_decision IS NULL
            OR (
                v_order.exclusion_decision = 'skip'
                AND v_order.excluded_instagram_id IS NOT NULL
            )
            OR (
                v_order.exclusion_decision <> 'skip'
                AND NOT (
                    v_order.exclusion_decision = 'exclude'
                    AND v_order.excluded_instagram_id IS NOT NULL
                    AND pg_catalog.lower(pg_catalog.btrim(v_order.excluded_instagram_id))
                        ~ '^[a-z0-9._]{1,30}$'
                    AND pg_catalog.lower(pg_catalog.btrim(v_order.excluded_instagram_id))
                        IS DISTINCT FROM v_target
                )
            )
       )
       OR v_order.paid_at < '2026-08-12T00:00:00Z'::TIMESTAMPTZ
       OR v_order.paid_at >= '2026-08-13T00:00:00Z'::TIMESTAMPTZ THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_FIRST_ORDER_BOOTSTRAP_ORDER_SCOPE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM public.earlybird_webhook_events AS refund_event
        WHERE refund_event.event_type = 'payment.refunded'
          AND refund_event.payment_id = v_order.payment_id
          AND refund_event.product_id = v_order.actual_groble_product_id
          AND refund_event.amount_krw = v_order.actual_amount_krw
          AND refund_event.refund_amount_krw = v_order.actual_amount_krw
          AND refund_event.partial_refund IS FALSE
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_FIRST_ORDER_BOOTSTRAP_REFUND_REJECTED',
            ERRCODE = 'P0001';
    END IF;
    IF v_fulfillment.order_id IS NULL
       OR v_fulfillment.status IS DISTINCT FROM p_expected_fulfillment_status
       OR v_fulfillment.attempt_count IS DISTINCT FROM p_expected_fulfillment_attempt_count
       OR v_fulfillment.request_id IS DISTINCT FROM p_source_request_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_FIRST_ORDER_BOOTSTRAP_FULFILLMENT_SCOPE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_source.id IS NULL
       OR v_source.user_id IS DISTINCT FROM p_owner_id
       OR v_source.preflight_id IS DISTINCT FROM p_failed_preflight_id
       OR pg_catalog.lower(pg_catalog.btrim(v_source.target_instagram_id))
            IS DISTINCT FROM v_target
       OR v_source.pipeline_version IS DISTINCT FROM 'v2'
       OR v_source.status IS DISTINCT FROM 'failed'
       OR v_result.id IS NULL
       OR v_result.user_id IS DISTINCT FROM p_owner_id
       OR pg_catalog.lower(pg_catalog.btrim(v_result.target_instagram_id))
            IS DISTINCT FROM v_target
       OR v_result.pipeline_version IS DISTINCT FROM 'v1'
       OR v_result.status IS DISTINCT FROM 'completed' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_FIRST_ORDER_BOOTSTRAP_SOURCE_SCOPE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF p_first_relationship_request_id = p_source_request_id
       AND p_second_relationship_request_id = p_source_request_id THEN
        -- This historical request persisted both relationship provider runs on
        -- the same failed V2 source request.  Bind that exact request only when
        -- the durable provider ledger proves one succeeded Apify run per side;
        -- never synthesize a pair of failed request IDs.
        IF pg_catalog.to_regclass('public.analysis_v2_provider_runs') IS NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'CONCIERGE_FIRST_ORDER_BOOTSTRAP_RELATIONSHIP_SCOPE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        EXECUTE $relationship_runs$
            SELECT CASE WHEN
                count(*) FILTER (
                    WHERE operation_key ~ '^relationship-followers:[a-f0-9]{64}$'
                ) = 1
                AND count(*) FILTER (
                    WHERE operation_key ~ '^relationship-following:[a-f0-9]{64}$'
                ) = 1
                AND count(*) = 2
            THEN 0 ELSE 1 END
            FROM public.analysis_v2_provider_runs
            WHERE request_id = $1
              AND job_key = 'track:relationships:collect'
              AND logical_provider = 'apify'
              AND credential_slot = 'tertiary'
              AND status = 'succeeded'
              AND run_id IS NOT NULL
              AND operation_key ~ '^relationship-(followers|following):[a-f0-9]{64}$'
        $relationship_runs$ INTO v_recovery_rows USING p_source_request_id;
        IF v_recovery_rows <> 0 THEN
            RAISE EXCEPTION USING
                MESSAGE = 'CONCIERGE_FIRST_ORDER_BOOTSTRAP_RELATIONSHIP_SCOPE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
    ELSIF (
        SELECT pg_catalog.count(*)
        FROM public.analysis_requests AS relationship_request
        WHERE relationship_request.id IN (
            p_first_relationship_request_id, p_second_relationship_request_id
        )
          AND relationship_request.user_id = p_owner_id
          AND relationship_request.preflight_id = p_failed_preflight_id
          AND relationship_request.pipeline_version = 'v2'
          AND relationship_request.status = 'failed'
    ) <> 2 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_FIRST_ORDER_BOOTSTRAP_RELATIONSHIP_SCOPE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT replay.* INTO v_replay
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, first_relationship_failed_request_id UUID, second_relationship_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ, reviewed_source_request_id UUID, reviewed_source_owner_id UUID, reviewed_source_target_instagram_id TEXT, reviewed_source_result_request_id UUID, reviewed_source_target_posts JSONB, reviewed_source_target_evidence JSONB, reviewed_source_fingerprint VARCHAR(64), reviewed_source_registered_at TIMESTAMPTZ, published_source_fingerprint VARCHAR(64), published_result_hash VARCHAR(64), published_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_concierge_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','first_relationship_failed_request_id','second_relationship_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at','reviewed_source_request_id','reviewed_source_owner_id','reviewed_source_target_instagram_id','reviewed_source_result_request_id','reviewed_source_target_posts','reviewed_source_target_evidence','reviewed_source_fingerprint','reviewed_source_registered_at','published_source_fingerprint','published_result_hash','published_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.first_relationship_failed_request_id IS NOT NULL AND decoded.second_relationship_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS replay
    WHERE replay.order_id = p_order_id
    FOR UPDATE;
    IF FOUND THEN
        IF v_replay.original_failed_request_id IS DISTINCT FROM p_source_request_id
           OR v_replay.first_relationship_failed_request_id
                IS DISTINCT FROM p_first_relationship_request_id
           OR v_replay.second_relationship_failed_request_id
                IS DISTINCT FROM p_second_relationship_request_id
           OR v_replay.failed_preflight_id IS DISTINCT FROM p_failed_preflight_id
           OR v_replay.rearmed_preflight_id IS DISTINCT FROM p_rearmed_preflight_id
           OR v_replay.reviewed_source_owner_id IS DISTINCT FROM p_owner_id
           OR v_replay.reviewed_source_target_instagram_id IS DISTINCT FROM v_target
           OR v_replay.reviewed_source_result_request_id IS DISTINCT FROM p_result_request_id
           OR v_replay.reviewed_source_target_evidence IS DISTINCT FROM p_target_evidence
           OR v_replay.reviewed_source_fingerprint IS DISTINCT FROM p_source_fingerprint
           OR v_replay.published_source_fingerprint IS DISTINCT FROM p_source_fingerprint
           OR v_replay.published_result_hash IS DISTINCT FROM p_result_hash
           OR v_result.step_data->'conciergeBootstrap'->'artifactHashes'
                IS DISTINCT FROM p_artifact_hashes THEN
            RAISE EXCEPTION USING
                MESSAGE = 'CONCIERGE_BOOTSTRAP_PUBLICATION_CAS_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'already_published',
            'orderId', p_order_id,
            'resultRequestId', p_result_request_id,
            'sourceFingerprint', p_source_fingerprint,
            'resultHash', p_result_hash
        );
    END IF;
    -- Keep the existing order result pointer and the failed V2 source audit
    -- untouched.  This insert adds only the exact one-shot replay lineage.
    PERFORM public.archive_earlybird_v211_concierge_replay(
        p_order_id, p_source_request_id,
        p_first_relationship_request_id, p_second_relationship_request_id,
        p_failed_preflight_id, p_rearmed_preflight_id,
        -- Existing concierge replay rows intentionally record the single
        -- replay admission attempt.  The deployed fulfillment's current
        -- attempt 2 is bound separately by the guard above; keep the legacy
        -- replay-table check and generic readiness rules unchanged.
        1,
        COALESCE(v_fulfillment.manual_review_at, pg_catalog.clock_timestamp()),
        p_source_request_id, p_owner_id, v_target, p_result_request_id,
        '[]'::JSONB, p_target_evidence, p_source_fingerprint,
        pg_catalog.clock_timestamp(), p_source_fingerprint, p_result_hash,
        pg_catalog.clock_timestamp()
    );

    -- The payload is the already-reviewed V1 publication.  Result rows are
    -- replaced only inside this transaction and only after all scope/CAS
    -- guards above have passed.
    DELETE FROM public.analysis_results
    WHERE request_id = p_result_request_id;
    INSERT INTO public.analysis_results (
        request_id, rank, suspect_instagram_id, suspect_profile_image,
        suspect_full_name, bio, risk_score, risk_grade, gender_status,
        one_line_overview, risk_analysis
    )
    SELECT p_result_request_id, rows.rank, rows.suspect_instagram_id,
           rows.suspect_profile_image, rows.suspect_full_name, rows.bio,
           rows.risk_score, rows.risk_grade, rows.gender_status,
           rows.one_line_overview, rows.risk_analysis
    FROM pg_catalog.jsonb_to_recordset(p_publication_payload->'femaleRows') AS rows(
        rank INTEGER, suspect_instagram_id TEXT, suspect_profile_image TEXT,
        suspect_full_name TEXT, bio TEXT, risk_score INTEGER, risk_grade TEXT,
        gender_status TEXT, one_line_overview TEXT, risk_analysis JSONB
    );
    DELETE FROM public.private_accounts
    WHERE request_id = p_result_request_id;
    INSERT INTO public.private_accounts(request_id, instagram_id, profile_image, full_name)
    SELECT p_result_request_id, rows.instagram_id, rows.profile_image, rows.full_name
    FROM pg_catalog.jsonb_to_recordset(p_publication_payload->'privateRows') AS rows(
        instagram_id TEXT, profile_image TEXT, full_name TEXT
    );

    UPDATE public.analysis_requests
    SET mutual_follows = p_exact_mutual,
        opposite_gender_count = (p_publication_payload->'publicGender'->>'female')::INTEGER,
        gender_stats = p_publication_payload->'publicGender',
        step_data = pg_catalog.jsonb_set(
            CASE WHEN pg_catalog.jsonb_typeof(step_data) = 'object'
                 THEN step_data ELSE '{}'::JSONB END,
            '{conciergeBootstrap}',
            pg_catalog.jsonb_build_object(
                'exactMutual', p_exact_mutual, 'hydrated', p_hydrated,
                'public', p_public, 'private', p_private,
                'unresolved', p_unresolved,
                'unresolvedUsernames', p_publication_payload->'unresolvedUsernames',
                'unavailablePublicUsernames', p_publication_payload->'unavailablePublicUsernames',
                'sourceFingerprint', p_source_fingerprint,
                'resultHash', p_result_hash,
                'artifactHashes', p_artifact_hashes
            ), TRUE
        )
    WHERE id = p_result_request_id;

    RETURN pg_catalog.jsonb_build_object(
        'disposition', 'published',
        'orderId', p_order_id,
        'resultRequestId', p_result_request_id,
        'sourceFingerprint', p_source_fingerprint,
        'resultHash', p_result_hash
    );
END;
$_$;


--
-- Name: bridge_earlybird_v211_lease_rearm_admission(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bridge_earlybird_v211_lease_rearm_admission(p_order_id uuid, p_expected_failed_request_id uuid, p_expected_request_conflict_at timestamp with time zone) RETURNS TABLE(order_id uuid, fulfillment_status text, preflight_id uuid, failed_request_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_user_id_hint UUID;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_incident RECORD;
    v_failed_request public.analysis_requests%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_recovery RECORD;
    v_base_request_key TEXT;
BEGIN
    IF p_order_id IS NULL
       OR p_expected_failed_request_id IS NULL
       OR p_expected_request_conflict_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_ADMISSION_BRIDGE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.user_id INTO v_user_id_hint
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_ADMISSION_BRIDGE_INELIGIBLE',
            ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.users AS recovery_user
    WHERE recovery_user.id = v_user_id_hint
    FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_ADMISSION_BRIDGE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    SELECT incident.* INTO v_incident
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, failed_request_id UUID, source_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'rearm'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_lease_policy_failure_rearms'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','source_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.source_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS incident
    WHERE incident.order_id = p_order_id;
    SELECT failed_request.* INTO v_failed_request
    FROM public.analysis_requests AS failed_request
    WHERE failed_request.id = p_expected_failed_request_id
    FOR UPDATE;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id
    FOR UPDATE;
    SELECT recovery.* INTO v_recovery
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
    WHERE recovery.order_id = p_order_id
    FOR UPDATE;

    v_base_request_key := 'earlybird:' || pg_catalog.lower(v_order.id::TEXT);

    IF v_order.id IS NULL
       OR v_order.user_id IS DISTINCT FROM v_user_id_hint
       OR v_fulfillment.order_id IS NULL
       OR v_incident.order_id IS NULL
       OR v_failed_request.id IS NULL
       OR v_preflight.id IS NULL
       OR v_incident.failed_request_id
            IS DISTINCT FROM p_expected_failed_request_id
       OR v_incident.source_preflight_id
            IS DISTINCT FROM v_failed_request.preflight_id
       OR v_incident.rearmed_preflight_id IS DISTINCT FROM v_preflight.id
       OR v_incident.expected_fulfillment_attempt_count <> 1
       OR v_order.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_order.plan_id <> 'basic'
       OR v_order.expected_amount_krw <> 990
       OR v_order.actual_amount_krw <> 990
       OR v_order.payment_id IS NULL
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_order.actual_groble_product_id
            IS DISTINCT FROM v_order.expected_groble_product_id
       OR v_failed_request.user_id IS DISTINCT FROM v_order.user_id
       OR v_failed_request.pipeline_version <> 'v2'
       OR v_failed_request.status <> 'failed'
       OR v_failed_request.error_message <>
            'ANALYSIS_V2_JOB_HANDLER_FAILED'
       OR v_failed_request.policy_versions_snapshot <>
            pg_catalog.jsonb_build_object(
                'pipeline', 'v2',
                'risk', 'risk-policy-v2.5',
                'aiStage', 'ai-stage-policy-v2.11',
                'scheduler', 'ai-scheduler-v1'
            )
       OR v_preflight.user_id IS DISTINCT FROM v_order.user_id
       OR v_preflight.target_instagram_id
            IS DISTINCT FROM v_order.target_instagram_id
       OR v_preflight.idempotency_key <>
            'earlybird.fulfillment.'
            || pg_catalog.replace(v_order.id::TEXT, '-', '') || '.r4'
       OR v_preflight.access_mode <> 'production'
       OR v_preflight.status <> 'ready'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.admission_status <> 'ready'
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM v_order.plan_id
       OR v_preflight.admission_target_followers_count
            IS DISTINCT FROM v_preflight.target_followers_count
       OR v_preflight.admission_target_following_count
            IS DISTINCT FROM v_preflight.target_following_count
       OR NOT public.analysis_v2_valid_recovery_adoption_preflights(
            v_order, v_preflight, v_preflight
       )
       OR NOT EXISTS (
            SELECT 1
            FROM public.analysis_v2_failure_receipts AS receipt
            WHERE receipt.request_id = v_failed_request.id
              AND receipt.failed_job_key = 'track:profile-ai:batch:0'
              AND receipt.error_code = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
       )
       OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_ai_attempts AS attempt
            WHERE attempt.request_id = v_failed_request.id
       )
       OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
            WHERE checkpoint.request_id = v_failed_request.id
       )
       OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_gemini_leases AS lease
            WHERE lease.request_id = v_failed_request.id
       )
       OR 7 <> (
            SELECT pg_catalog.count(*)
            FROM public.analysis_v2_provider_runs AS provider_run
            WHERE provider_run.request_id = v_failed_request.id
       )
       OR 6 <> (
            SELECT pg_catalog.count(*)
            FROM public.analysis_v2_provider_runs AS provider_run
            WHERE provider_run.request_id = v_failed_request.id
              AND provider_run.status = 'succeeded'
              AND provider_run.run_id IS NOT NULL
              AND provider_run.actual_usage_usd IS NOT NULL
              AND provider_run.usage_reconciled_at IS NOT NULL
       )
       OR 1 <> (
            SELECT pg_catalog.count(*)
            FROM public.analysis_v2_provider_runs AS provider_run
            WHERE provider_run.request_id = v_failed_request.id
              AND provider_run.status = 'aborted'
              AND provider_run.run_id IS NOT NULL
              AND provider_run.actual_usage_usd IS NOT NULL
              AND provider_run.usage_reconciled_at IS NOT NULL
       )
       OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_provider_cleanup_intents AS cleanup
            WHERE cleanup.request_id = v_failed_request.id
              AND cleanup.completed_at IS NULL
       )
       OR EXISTS (
            SELECT 1
            FROM public.analysis_requests AS successor
            WHERE successor.user_id = v_order.user_id
              AND successor.idempotency_key ~ (
                  '^' || v_base_request_key || '[.]r[0-9]{1,3}$'
              )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_ADMISSION_BRIDGE_INELIGIBLE',
            ERRCODE = 'P0001';
    END IF;

    IF v_recovery.order_id IS NULL THEN
        IF v_order.status <> 'paid'
           OR v_order.result_request_id IS NOT NULL
           OR v_fulfillment.status <> 'manual_review'
           OR v_fulfillment.request_id IS NOT NULL
           OR v_fulfillment.last_error_code <> 'REQUEST_CONFLICT'
           OR v_fulfillment.last_error_at
                IS DISTINCT FROM p_expected_request_conflict_at
           OR v_fulfillment.manual_review_at
                IS DISTINCT FROM p_expected_request_conflict_at
           OR v_fulfillment.lease_token IS NOT NULL
           OR v_fulfillment.lease_expires_at IS NOT NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_V211_ADMISSION_BRIDGE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;

        PERFORM public.archive_earlybird_schema_failure_recovery(
            v_order.id, v_incident.failed_request_id,
            v_incident.rearmed_preflight_id,
            v_incident.expected_fulfillment_attempt_count
        );
    ELSE
        IF v_recovery.failed_request_id
                IS DISTINCT FROM v_incident.failed_request_id
           OR v_recovery.recovery_preflight_id
                IS DISTINCT FROM v_incident.rearmed_preflight_id
           OR v_recovery.prior_attempt_count
                IS DISTINCT FROM v_incident.expected_fulfillment_attempt_count THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_V211_ADMISSION_BRIDGE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
    END IF;

    UPDATE public.earlybird_fulfillments AS fulfillment
    SET status = 'admission_pending', attempt_count = 0,
        lease_token = NULL, lease_expires_at = NULL,
        next_attempt_at = v_now, operator_admitted_at = v_now,
        last_error_code = NULL, last_error_at = NULL,
        manual_review_at = NULL, updated_at = v_now
    WHERE fulfillment.order_id = v_order.id;

    RETURN QUERY SELECT
        v_order.id, 'admission_pending'::TEXT,
        v_preflight.id, v_failed_request.id;
END;
$_$;


--
-- Name: build_account_ledger_classification_plan_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_account_ledger_classification_plan_v1(p_legacy_candidate_ids jsonb, p_operator_account_ids jsonb, p_internal_tester_account_ids jsonb) RETURNS TABLE(assignments jsonb, total_count integer, legacy_e2e_count integer, operator_count integer, internal_tester_count integer, production_external_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_legacy_ids JSONB;
    v_operator_ids JSONB;
    v_internal_tester_ids JSONB;
    v_actual_legacy_ids JSONB;
    v_total_count INTEGER;
    v_legacy_count INTEGER;
    v_operator_count INTEGER;
    v_internal_tester_count INTEGER;
    v_production_external_count INTEGER;
    v_assignments JSONB;
BEGIN
    IF p_legacy_candidate_ids IS NULL
       OR p_operator_account_ids IS NULL
       OR p_internal_tester_account_ids IS NULL
       OR pg_catalog.jsonb_typeof(p_legacy_candidate_ids) <> 'array'
       OR pg_catalog.jsonb_typeof(p_operator_account_ids) <> 'array'
       OR pg_catalog.jsonb_typeof(p_internal_tester_account_ids) <> 'array'
       OR pg_catalog.jsonb_array_length(p_legacy_candidate_ids) NOT BETWEEN 1 AND 100
       OR pg_catalog.jsonb_array_length(p_operator_account_ids) NOT BETWEEN 1 AND 16
       OR pg_catalog.jsonb_array_length(p_internal_tester_account_ids) NOT BETWEEN 1 AND 16
       OR EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_array_elements(p_legacy_candidate_ids) AS item
           WHERE pg_catalog.jsonb_typeof(item) <> 'string'
              OR item #>> '{}' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       )
       OR EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_array_elements(p_operator_account_ids) AS item
           WHERE pg_catalog.jsonb_typeof(item) <> 'string'
              OR item #>> '{}' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       )
       OR EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_array_elements(p_internal_tester_account_ids) AS item
           WHERE pg_catalog.jsonb_typeof(item) <> 'string'
              OR item #>> '{}' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_CLASSIFICATION_INPUT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value) ORDER BY value)
    INTO v_legacy_ids
    FROM pg_catalog.jsonb_array_elements_text(p_legacy_candidate_ids) AS value;
    SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value) ORDER BY value)
    INTO v_operator_ids
    FROM pg_catalog.jsonb_array_elements_text(p_operator_account_ids) AS value;
    SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value) ORDER BY value)
    INTO v_internal_tester_ids
    FROM pg_catalog.jsonb_array_elements_text(p_internal_tester_account_ids) AS value;

    IF (
        SELECT pg_catalog.count(*)
        FROM (
            SELECT value FROM pg_catalog.jsonb_array_elements_text(v_legacy_ids)
            UNION ALL
            SELECT value FROM pg_catalog.jsonb_array_elements_text(v_operator_ids)
            UNION ALL
            SELECT value FROM pg_catalog.jsonb_array_elements_text(v_internal_tester_ids)
        ) AS supplied_id
    ) <> (
        SELECT pg_catalog.count(DISTINCT value)
        FROM (
            SELECT value FROM pg_catalog.jsonb_array_elements_text(v_legacy_ids)
            UNION ALL
            SELECT value FROM pg_catalog.jsonb_array_elements_text(v_operator_ids)
            UNION ALL
            SELECT value FROM pg_catalog.jsonb_array_elements_text(v_internal_tester_ids)
        ) AS supplied_id
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_CLASSIFICATION_INPUT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(
        pg_catalog.jsonb_agg(pg_catalog.to_jsonb(candidate.account_id) ORDER BY candidate.account_id),
        '[]'::JSONB
    )
    INTO v_actual_legacy_ids
    FROM public.account_ledger_legacy_e2e_candidate_ids_v1() AS candidate;
    IF v_legacy_ids IS DISTINCT FROM v_actual_legacy_ids THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_CLASSIFICATION_LEGACY_CANDIDATE_DRIFT',
            ERRCODE = 'P0001';
    END IF;

    IF (
        SELECT pg_catalog.count(*)
        FROM public.users AS account
        WHERE account.id IN (
            SELECT value::UUID
            FROM pg_catalog.jsonb_array_elements_text(v_operator_ids)
            UNION ALL
            SELECT value::UUID
            FROM pg_catalog.jsonb_array_elements_text(v_internal_tester_ids)
        )
          AND account.classification_version IS NULL
    ) <> pg_catalog.jsonb_array_length(v_operator_ids)
        + pg_catalog.jsonb_array_length(v_internal_tester_ids) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_CLASSIFICATION_IDENTIFIER_NOT_PENDING',
            ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.count(*)::INTEGER
    INTO v_total_count
    FROM public.users AS account
    WHERE account.classification_version IS NULL;
    IF v_total_count NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_CLASSIFICATION_PLAN_SIZE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
            'account_id', account.id,
            'account_class', CASE
                WHEN account.id::TEXT IN (
                    SELECT value FROM pg_catalog.jsonb_array_elements_text(v_legacy_ids)
                ) OR account.id::TEXT IN (
                    SELECT value FROM pg_catalog.jsonb_array_elements_text(v_internal_tester_ids)
                ) THEN 'e2e_test'
                WHEN account.id::TEXT IN (
                    SELECT value FROM pg_catalog.jsonb_array_elements_text(v_operator_ids)
                ) THEN 'production'
                ELSE 'production'
            END,
            'traffic_class', CASE
                WHEN account.id::TEXT IN (
                    SELECT value FROM pg_catalog.jsonb_array_elements_text(v_legacy_ids)
                ) THEN 'e2e_test'
                WHEN account.id::TEXT IN (
                    SELECT value FROM pg_catalog.jsonb_array_elements_text(v_internal_tester_ids)
                ) THEN 'internal_tester'
                WHEN account.id::TEXT IN (
                    SELECT value FROM pg_catalog.jsonb_array_elements_text(v_operator_ids)
                ) THEN 'operator'
                ELSE 'external'
            END,
            'lifecycle', CASE
                WHEN account.id::TEXT IN (
                    SELECT value FROM pg_catalog.jsonb_array_elements_text(v_legacy_ids)
                ) OR account.id::TEXT IN (
                    SELECT value FROM pg_catalog.jsonb_array_elements_text(v_internal_tester_ids)
                ) THEN 'retired'
                ELSE 'active'
            END,
            'reason_code', CASE
                WHEN account.id::TEXT IN (
                    SELECT value FROM pg_catalog.jsonb_array_elements_text(v_legacy_ids)
                ) THEN 'LEGACY_E2E_HMAC_VERIFIED'
                WHEN account.id::TEXT IN (
                    SELECT value FROM pg_catalog.jsonb_array_elements_text(v_internal_tester_ids)
                ) THEN 'INTERNAL_TESTER_KEYCHAIN_VERIFIED'
                WHEN account.id::TEXT IN (
                    SELECT value FROM pg_catalog.jsonb_array_elements_text(v_operator_ids)
                ) THEN 'OPERATOR_KEYCHAIN_VERIFIED'
                ELSE 'PRODUCTION_EXTERNAL_DEFAULT'
            END
        )
        ORDER BY account.id
    )
    INTO v_assignments
    FROM public.users AS account
    WHERE account.classification_version IS NULL;

    SELECT pg_catalog.count(*)::INTEGER
    INTO v_legacy_count
    FROM public.users AS account
    WHERE account.classification_version IS NULL
      AND account.id::TEXT IN (
          SELECT value FROM pg_catalog.jsonb_array_elements_text(v_legacy_ids)
      );
    SELECT pg_catalog.count(*)::INTEGER
    INTO v_operator_count
    FROM public.users AS account
    WHERE account.classification_version IS NULL
      AND account.id::TEXT IN (
          SELECT value FROM pg_catalog.jsonb_array_elements_text(v_operator_ids)
      );
    SELECT pg_catalog.count(*)::INTEGER
    INTO v_internal_tester_count
    FROM public.users AS account
    WHERE account.classification_version IS NULL
      AND account.id::TEXT IN (
          SELECT value FROM pg_catalog.jsonb_array_elements_text(v_internal_tester_ids)
      );
    v_production_external_count := v_total_count - v_legacy_count
        - v_operator_count - v_internal_tester_count;

    RETURN QUERY
    SELECT v_assignments,
        v_total_count,
        v_legacy_count,
        v_operator_count,
        v_internal_tester_count,
        v_production_external_count;
END;
$_$;


--
-- Name: cancel_vertex_ai_budget(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_vertex_ai_budget(p_reservation_key text, p_reservation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_row public.vertex_ai_budget_reservations%ROWTYPE;
BEGIN
    IF p_reservation_key IS NULL OR p_reservation_id IS NULL THEN
        RAISE EXCEPTION 'VERTEX_AI_BUDGET_CANCELLATION_INVALID';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('vertex-ai-budget:all-scopes', 0)
    );
    SELECT reservation.*
      INTO v_row
      FROM public.vertex_ai_budget_reservations AS reservation
     WHERE reservation.reservation_key = p_reservation_key
     FOR UPDATE;
    IF NOT FOUND OR v_row.reservation_id IS DISTINCT FROM p_reservation_id THEN
        RAISE EXCEPTION 'VERTEX_AI_BUDGET_RESERVATION_UNKNOWN';
    END IF;
    IF v_row.state = 'reserved' THEN
        UPDATE public.vertex_ai_budget_reservations AS reservation
           SET state = 'cancelled', updated_at = pg_catalog.clock_timestamp()
         WHERE reservation.reservation_key = p_reservation_key;
    END IF;
END;
$$;


--
-- Name: canonical_json_hash_v1(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_json_hash_v1(p_namespace text, p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF pg_catalog.length(p_namespace) = 0
       OR pg_catalog.strpos(p_namespace, pg_catalog.chr(10)) > 0 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CANONICAL_JSON_NAMESPACE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    RETURN pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                p_namespace || pg_catalog.chr(10)
                    || public.canonical_json_v1(p_value),
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );
END;
$$;


--
-- Name: canonical_json_number_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_json_number_v1(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO ''
    SET extra_float_digits TO '3'
    AS $$
DECLARE
    v_number DOUBLE PRECISION;
    v_number_text TEXT;
    v_mantissa TEXT;
    v_exponent INTEGER;
    v_decimal TEXT;
    v_unsigned_mantissa TEXT;
    v_digits TEXT;
    v_decimal_position INTEGER;
BEGIN
    IF pg_catalog.jsonb_typeof(p_value) <> 'number' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CANONICAL_JSON_NUMBER_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_number := (p_value #>> '{}')::DOUBLE PRECISION;
    v_number_text := v_number::TEXT;
    IF v_number <> v_number
       OR v_number_text IN ('Infinity', '-Infinity', 'NaN') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CANONICAL_JSON_NUMBER_INVALID',
            ERRCODE = 'P0001';
    END IF;
    IF v_number = 0 THEN
        RETURN '0';
    END IF;

    -- JSON.stringify uses decimal notation in [1e-6, 1e21), even when the
    -- PostgreSQL float formatter chooses scientific notation.
    IF pg_catalog.abs(v_number) >= 1e-6
       AND pg_catalog.abs(v_number) < 1e21 THEN
        v_number_text := pg_catalog.lower(v_number::TEXT);
        v_decimal := v_number_text;
        -- Expand PostgreSQL's shortest float representation when it uses
        -- scientific notation; this keeps all significant digits instead of
        -- going through numeric's lower-precision display cast.
        IF pg_catalog.strpos(v_number_text, 'e') > 0 THEN
            v_mantissa := pg_catalog.split_part(v_number_text, 'e', 1);
            v_exponent := pg_catalog.split_part(v_number_text, 'e', 2)::INTEGER;
            v_unsigned_mantissa := pg_catalog.ltrim(v_mantissa, '+-');
            v_digits := pg_catalog.replace(v_unsigned_mantissa, '.', '');
            v_decimal_position := (
                CASE
                    WHEN pg_catalog.strpos(v_unsigned_mantissa, '.') > 0
                    THEN pg_catalog.strpos(v_unsigned_mantissa, '.') - 1
                    ELSE pg_catalog.length(v_unsigned_mantissa)
                END
            ) + v_exponent;
            IF v_decimal_position <= 0 THEN
                v_decimal := CASE WHEN pg_catalog.left(v_mantissa, 1) = '-' THEN '-' ELSE '' END
                    || '0.'
                    || pg_catalog.repeat('0', -v_decimal_position)
                    || v_digits;
            ELSIF v_decimal_position >= pg_catalog.length(v_digits) THEN
                v_decimal := CASE WHEN pg_catalog.left(v_mantissa, 1) = '-' THEN '-' ELSE '' END
                    || v_digits
                    || pg_catalog.repeat('0', v_decimal_position - pg_catalog.length(v_digits));
            ELSE
                v_decimal := CASE WHEN pg_catalog.left(v_mantissa, 1) = '-' THEN '-' ELSE '' END
                    || pg_catalog.substr(v_digits, 1, v_decimal_position)
                    || '.'
                    || pg_catalog.substr(v_digits, v_decimal_position + 1);
            END IF;
        END IF;
        IF pg_catalog.strpos(v_decimal, '.') > 0 THEN
            v_decimal := pg_catalog.rtrim(pg_catalog.rtrim(v_decimal, '0'), '.');
        END IF;
        RETURN v_decimal;
    END IF;

    v_number_text := pg_catalog.lower(v_number_text);
    IF pg_catalog.strpos(v_number_text, 'e') = 0 THEN
        RETURN v_number_text;
    END IF;
    v_mantissa := pg_catalog.split_part(v_number_text, 'e', 1);
    v_exponent := pg_catalog.split_part(v_number_text, 'e', 2)::INTEGER;
    IF pg_catalog.strpos(v_mantissa, '.') > 0 THEN
        v_mantissa := pg_catalog.rtrim(pg_catalog.rtrim(v_mantissa, '0'), '.');
    END IF;
    RETURN v_mantissa || 'e'
        || CASE WHEN v_exponent >= 0 THEN '+' ELSE '' END
        || v_exponent::TEXT;
END;
$$;


--
-- Name: canonical_json_string_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_json_string_v1(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.to_json(p_value)::TEXT;
$$;


--
-- Name: canonical_json_v1(jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_json_v1(p_value jsonb, p_depth integer DEFAULT 0) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_result TEXT;
BEGIN
    IF p_depth IS NULL OR p_depth NOT BETWEEN 0 AND 8 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CANONICAL_JSON_DEPTH_LIMIT',
            ERRCODE = 'P0001';
    END IF;

    CASE pg_catalog.jsonb_typeof(p_value)
        WHEN 'object' THEN
            IF (
                SELECT pg_catalog.count(*)
                FROM pg_catalog.jsonb_object_keys(p_value)
            ) > 100
            OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_object_keys(p_value) AS object_key(key)
                WHERE object_key.key IS NULL
                   OR pg_catalog.length(object_key.key) = 0
                   OR pg_catalog.length(object_key.key) > 128
            ) THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'CANONICAL_JSON_KEY_INVALID',
                    ERRCODE = 'P0001';
            END IF;
            SELECT '{' || COALESCE(pg_catalog.string_agg(
                public.canonical_json_string_v1(entry.key) || ':'
                    || public.canonical_json_v1(entry.value, p_depth + 1),
                ',' ORDER BY pg_catalog.encode(
                    pg_catalog.convert_to(entry.key, 'UTF8'),
                    'hex'
                ) COLLATE "C"
            ), '') || '}'
            INTO v_result
            FROM pg_catalog.jsonb_each(p_value) AS entry(key, value);
        WHEN 'array' THEN
            IF pg_catalog.jsonb_array_length(p_value) > 100 THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'CANONICAL_JSON_ARRAY_LIMIT',
                    ERRCODE = 'P0001';
            END IF;
            SELECT '[' || COALESCE(pg_catalog.string_agg(
                public.canonical_json_v1(entry.value, p_depth + 1),
                ',' ORDER BY entry.ordinality
            ), '') || ']'
            INTO v_result
            FROM pg_catalog.jsonb_array_elements(p_value)
                WITH ORDINALITY AS entry(value, ordinality);
        WHEN 'string' THEN
            IF pg_catalog.length(p_value #>> '{}') > 8192 THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'CANONICAL_JSON_STRING_LIMIT',
                    ERRCODE = 'P0001';
            END IF;
            v_result := public.canonical_json_string_v1(p_value #>> '{}');
        WHEN 'number' THEN
            v_result := public.canonical_json_number_v1(p_value);
        WHEN 'boolean' THEN
            v_result := p_value #>> '{}';
        WHEN 'null' THEN
            v_result := 'null';
        ELSE
            RAISE EXCEPTION USING
                MESSAGE = 'CANONICAL_JSON_VALUE_INVALID',
                ERRCODE = 'P0001';
    END CASE;

    IF pg_catalog.octet_length(v_result) > 262144 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CANONICAL_JSON_SIZE_LIMIT',
            ERRCODE = 'P0001';
    END IF;
    RETURN v_result;
END;
$$;


--
-- Name: capture_analysis_order_audit_parity_attestation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_analysis_order_audit_parity_attestation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_current JSONB;
    v_previous JSONB;
    v_attestation JSONB;
BEGIN
    IF NEW.status <> 'completed'
       OR (TG_OP = 'UPDATE' AND OLD.status = 'completed') THEN
        RETURN NEW;
    END IF;

    v_current := public.read_analysis_order_audit_parity_snapshot(NEW.request_id);
    IF v_current IS NULL
       OR v_current->'bundle'->>'present' IS DISTINCT FROM 'true' THEN
        RETURN NEW;
    END IF;

    SELECT queue.parity_attestation
      INTO v_previous
      FROM public.analysis_order_audit_assembly_queue AS queue
     WHERE queue.request_id = NEW.request_id;

    v_attestation := pg_catalog.jsonb_build_object(
        'request', pg_catalog.jsonb_build_object(
            'completed', COALESCE(
                NULLIF(v_current->'request'->'completed', 'null'::JSONB),
                v_previous->'request'->'completed'
            ),
            'productionOrder', COALESCE(
                NULLIF(v_current->'request'->'productionOrder', 'null'::JSONB),
                v_previous->'request'->'productionOrder'
            ),
            'sourceDataPresent', (
                COALESCE((v_current->'request'->>'sourceDataPresent')::BOOLEAN, FALSE)
                OR COALESCE((v_previous->'request'->>'sourceDataPresent')::BOOLEAN, FALSE)
            )
        ),
        'bundle', v_current->'bundle',
        'recovery', v_current->'recovery',
        'sections', pg_catalog.jsonb_build_object(
            'relationships', CASE
                WHEN COALESCE(
                    pg_catalog.jsonb_typeof(v_current->'sections'->'relationships') <> 'object',
                    TRUE
                ) THEN v_previous->'sections'->'relationships'
                ELSE v_current->'sections'->'relationships' || pg_catalog.jsonb_build_object(
                    'sourceCount', COALESCE(
                        NULLIF(v_current->'sections'->'relationships'->'sourceCount', 'null'::JSONB),
                        v_previous->'sections'->'relationships'->'sourceCount'
                    ),
                    'bundleCount', COALESCE(
                        NULLIF(v_current->'sections'->'relationships'->'bundleCount', 'null'::JSONB),
                        v_previous->'sections'->'relationships'->'bundleCount'
                    ),
                    'sourceChecksum', COALESCE(
                        NULLIF(v_current->'sections'->'relationships'->'sourceChecksum', 'null'::JSONB),
                        v_previous->'sections'->'relationships'->'sourceChecksum'
                    ),
                    'bundleChecksum', COALESCE(
                        NULLIF(v_current->'sections'->'relationships'->'bundleChecksum', 'null'::JSONB),
                        v_previous->'sections'->'relationships'->'bundleChecksum'
                    ),
                    'sourceComplete', COALESCE(
                        NULLIF(v_current->'sections'->'relationships'->'sourceComplete', 'null'::JSONB),
                        v_previous->'sections'->'relationships'->'sourceComplete'
                    ),
                    'bundleComplete', COALESCE(
                        NULLIF(v_current->'sections'->'relationships'->'bundleComplete', 'null'::JSONB),
                        v_previous->'sections'->'relationships'->'bundleComplete'
                    )
                )
            END,
            'targetEvidence', CASE
                WHEN COALESCE(
                    pg_catalog.jsonb_typeof(v_current->'sections'->'targetEvidence') <> 'object',
                    TRUE
                ) THEN v_previous->'sections'->'targetEvidence'
                ELSE v_current->'sections'->'targetEvidence' || pg_catalog.jsonb_build_object(
                    'sourceCount', COALESCE(
                        NULLIF(v_current->'sections'->'targetEvidence'->'sourceCount', 'null'::JSONB),
                        v_previous->'sections'->'targetEvidence'->'sourceCount'
                    ),
                    'bundleCount', COALESCE(
                        NULLIF(v_current->'sections'->'targetEvidence'->'bundleCount', 'null'::JSONB),
                        v_previous->'sections'->'targetEvidence'->'bundleCount'
                    ),
                    'sourceChecksum', COALESCE(
                        NULLIF(v_current->'sections'->'targetEvidence'->'sourceChecksum', 'null'::JSONB),
                        v_previous->'sections'->'targetEvidence'->'sourceChecksum'
                    ),
                    'bundleChecksum', COALESCE(
                        NULLIF(v_current->'sections'->'targetEvidence'->'bundleChecksum', 'null'::JSONB),
                        v_previous->'sections'->'targetEvidence'->'bundleChecksum'
                    ),
                    'sourceComplete', COALESCE(
                        NULLIF(v_current->'sections'->'targetEvidence'->'sourceComplete', 'null'::JSONB),
                        v_previous->'sections'->'targetEvidence'->'sourceComplete'
                    ),
                    'bundleComplete', COALESCE(
                        NULLIF(v_current->'sections'->'targetEvidence'->'bundleComplete', 'null'::JSONB),
                        v_previous->'sections'->'targetEvidence'->'bundleComplete'
                    )
                )
            END,
            'candidates', CASE
                WHEN COALESCE(
                    pg_catalog.jsonb_typeof(v_current->'sections'->'candidates') <> 'object',
                    TRUE
                ) THEN v_previous->'sections'->'candidates'
                ELSE v_current->'sections'->'candidates' || pg_catalog.jsonb_build_object(
                    'sourceCount', COALESCE(
                        NULLIF(v_current->'sections'->'candidates'->'sourceCount', 'null'::JSONB),
                        v_previous->'sections'->'candidates'->'sourceCount'
                    ),
                    'bundleCount', COALESCE(
                        NULLIF(v_current->'sections'->'candidates'->'bundleCount', 'null'::JSONB),
                        v_previous->'sections'->'candidates'->'bundleCount'
                    ),
                    'sourceChecksum', COALESCE(
                        NULLIF(v_current->'sections'->'candidates'->'sourceChecksum', 'null'::JSONB),
                        v_previous->'sections'->'candidates'->'sourceChecksum'
                    ),
                    'bundleChecksum', COALESCE(
                        NULLIF(v_current->'sections'->'candidates'->'bundleChecksum', 'null'::JSONB),
                        v_previous->'sections'->'candidates'->'bundleChecksum'
                    ),
                    'sourceComplete', COALESCE(
                        NULLIF(v_current->'sections'->'candidates'->'sourceComplete', 'null'::JSONB),
                        v_previous->'sections'->'candidates'->'sourceComplete'
                    ),
                    'bundleComplete', COALESCE(
                        NULLIF(v_current->'sections'->'candidates'->'bundleComplete', 'null'::JSONB),
                        v_previous->'sections'->'candidates'->'bundleComplete'
                    )
                )
            END,
            'risk', CASE
                WHEN COALESCE(
                    pg_catalog.jsonb_typeof(v_current->'sections'->'risk') <> 'object',
                    TRUE
                ) THEN v_previous->'sections'->'risk'
                ELSE v_current->'sections'->'risk' || pg_catalog.jsonb_build_object(
                    'sourceCount', COALESCE(
                        NULLIF(v_current->'sections'->'risk'->'sourceCount', 'null'::JSONB),
                        v_previous->'sections'->'risk'->'sourceCount'
                    ),
                    'bundleCount', COALESCE(
                        NULLIF(v_current->'sections'->'risk'->'bundleCount', 'null'::JSONB),
                        v_previous->'sections'->'risk'->'bundleCount'
                    ),
                    'sourceChecksum', COALESCE(
                        NULLIF(v_current->'sections'->'risk'->'sourceChecksum', 'null'::JSONB),
                        v_previous->'sections'->'risk'->'sourceChecksum'
                    ),
                    'bundleChecksum', COALESCE(
                        NULLIF(v_current->'sections'->'risk'->'bundleChecksum', 'null'::JSONB),
                        v_previous->'sections'->'risk'->'bundleChecksum'
                    ),
                    'sourceComplete', COALESCE(
                        NULLIF(v_current->'sections'->'risk'->'sourceComplete', 'null'::JSONB),
                        v_previous->'sections'->'risk'->'sourceComplete'
                    ),
                    'bundleComplete', COALESCE(
                        NULLIF(v_current->'sections'->'risk'->'bundleComplete', 'null'::JSONB),
                        v_previous->'sections'->'risk'->'bundleComplete'
                    )
                )
            END,
            'costLedger', CASE
                WHEN COALESCE(
                    pg_catalog.jsonb_typeof(v_current->'sections'->'costLedger') <> 'object',
                    TRUE
                ) THEN v_previous->'sections'->'costLedger'
                ELSE v_current->'sections'->'costLedger' || pg_catalog.jsonb_build_object(
                    'sourceCount', COALESCE(
                        NULLIF(v_current->'sections'->'costLedger'->'sourceCount', 'null'::JSONB),
                        v_previous->'sections'->'costLedger'->'sourceCount'
                    ),
                    'bundleCount', COALESCE(
                        NULLIF(v_current->'sections'->'costLedger'->'bundleCount', 'null'::JSONB),
                        v_previous->'sections'->'costLedger'->'bundleCount'
                    ),
                    'sourceChecksum', COALESCE(
                        NULLIF(v_current->'sections'->'costLedger'->'sourceChecksum', 'null'::JSONB),
                        v_previous->'sections'->'costLedger'->'sourceChecksum'
                    ),
                    'bundleChecksum', COALESCE(
                        NULLIF(v_current->'sections'->'costLedger'->'bundleChecksum', 'null'::JSONB),
                        v_previous->'sections'->'costLedger'->'bundleChecksum'
                    ),
                    'sourceComplete', COALESCE(
                        NULLIF(v_current->'sections'->'costLedger'->'sourceComplete', 'null'::JSONB),
                        v_previous->'sections'->'costLedger'->'sourceComplete'
                    ),
                    'bundleComplete', COALESCE(
                        NULLIF(v_current->'sections'->'costLedger'->'bundleComplete', 'null'::JSONB),
                        v_previous->'sections'->'costLedger'->'bundleComplete'
                    )
                )
            END
        )
    );

    UPDATE public.analysis_order_audit_assembly_queue
       SET parity_attestation = v_attestation
     WHERE request_id = NEW.request_id;
    RETURN NEW;
END;
$$;


--
-- Name: capture_analysis_provider_cost_expectation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_analysis_provider_cost_expectation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.request_id IS NULL THEN
        RETURN NEW;
    END IF;

    INSERT INTO public.analysis_provider_usage_expectations (
        request_id,
        operation_key,
        logical_provider,
        actor_id,
        max_charge_usd,
        created_at
    ) VALUES (
        NEW.request_id,
        NEW.operation_key,
        NEW.logical_provider,
        NEW.actor_id,
        NEW.max_charge_usd,
        NEW.created_at
    )
    ON CONFLICT (request_id, operation_key) DO UPDATE
    SET logical_provider = EXCLUDED.logical_provider,
        actor_id = EXCLUDED.actor_id,
        max_charge_usd = EXCLUDED.max_charge_usd
    WHERE public.analysis_provider_usage_expectations.logical_provider = EXCLUDED.logical_provider
      AND public.analysis_provider_usage_expectations.actor_id = EXCLUDED.actor_id
      AND public.analysis_provider_usage_expectations.max_charge_usd = EXCLUDED.max_charge_usd;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PROVIDER_COST_EXPECTATION_MISMATCH',
            ERRCODE = '22023';
    END IF;
    RETURN NEW;
END;
$$;


