--
-- Name: capture_analysis_v2_profile_fetch_telemetry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_analysis_v2_profile_fetch_telemetry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_source TEXT := CASE
        WHEN NEW.attempt = 'fresh_apify' THEN 'fresh_apify'
        WHEN NEW.attempt = 'fallback' THEN 'fallback'
        WHEN NEW.attempt = 'repair' THEN 'repair'
        ELSE NEW.source
    END;
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    INSERT INTO public.analysis_v2_profile_fetch_telemetry (
        request_id,
        job_key,
        source,
        status,
        failure_category,
        http_status,
        outcome_count,
        request_count_total,
        latency_ms_total,
        latency_ms_max,
        first_captured_at,
        last_captured_at,
        created_at,
        updated_at
    ) VALUES (
        NEW.request_id,
        NEW.job_key,
        v_source,
        NEW.status,
        NEW.failure_category,
        NEW.http_status,
        1,
        NEW.request_count,
        NEW.latency_ms,
        NEW.latency_ms,
        NEW.captured_at,
        NEW.captured_at,
        v_now,
        v_now
    )
    ON CONFLICT (
        request_id, job_key, source, status, failure_category_key, http_status_key
    ) DO UPDATE
    SET outcome_count = public.analysis_v2_profile_fetch_telemetry.outcome_count + 1,
        request_count_total =
            public.analysis_v2_profile_fetch_telemetry.request_count_total
            + EXCLUDED.request_count_total,
        latency_ms_total = public.analysis_v2_profile_fetch_telemetry.latency_ms_total
            + EXCLUDED.latency_ms_total,
        latency_ms_max = GREATEST(
            public.analysis_v2_profile_fetch_telemetry.latency_ms_max,
            EXCLUDED.latency_ms_max
        ),
        first_captured_at = LEAST(
            public.analysis_v2_profile_fetch_telemetry.first_captured_at,
            EXCLUDED.first_captured_at
        ),
        last_captured_at = GREATEST(
            public.analysis_v2_profile_fetch_telemetry.last_captured_at,
            EXCLUDED.last_captured_at
        ),
        updated_at = v_now;
    RETURN NULL;
END;
$$;


--
-- Name: capture_analysis_v2_result_coverage_telemetry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_analysis_v2_result_coverage_telemetry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    INSERT INTO public.analysis_v2_result_coverage_telemetry (
        request_id, plan_id,
        followers_declared, followers_collected,
        following_declared, following_collected,
        detected_mutuals, public_mutuals, private_mutuals,
        screened_mutuals, not_screened_mutuals,
        fetch_unavailable_count, media_unavailable_count,
        analysis_unavailable_count
    ) VALUES (
        NEW.request_id, NEW.plan_id,
        NEW.followers_declared, NEW.followers_collected,
        NEW.following_declared, NEW.following_collected,
        NEW.detected_mutuals, NEW.public_mutuals, NEW.private_mutuals,
        NEW.screened_mutuals, NEW.not_screened_mutuals,
        NEW.fetch_unavailable_count, NEW.media_unavailable_count,
        NEW.analysis_unavailable_count
    )
    ON CONFLICT (request_id) DO UPDATE
    SET plan_id = EXCLUDED.plan_id,
        followers_declared = EXCLUDED.followers_declared,
        followers_collected = EXCLUDED.followers_collected,
        following_declared = EXCLUDED.following_declared,
        following_collected = EXCLUDED.following_collected,
        detected_mutuals = EXCLUDED.detected_mutuals,
        public_mutuals = EXCLUDED.public_mutuals,
        private_mutuals = EXCLUDED.private_mutuals,
        screened_mutuals = EXCLUDED.screened_mutuals,
        not_screened_mutuals = EXCLUDED.not_screened_mutuals,
        fetch_unavailable_count = EXCLUDED.fetch_unavailable_count,
        media_unavailable_count = EXCLUDED.media_unavailable_count,
        analysis_unavailable_count = EXCLUDED.analysis_unavailable_count;
    RETURN NULL;
END;
$$;


--
-- Name: capture_analysis_v2_score_audit_source(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_analysis_v2_score_audit_source(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_intent public.analysis_v2_score_audit_intents%ROWTYPE;
    v_stage public.analysis_v2_ai_scoring_stage_checkpoints%ROWTYPE;
    v_existing public.analysis_v2_score_audit_sources%ROWTYPE;
    v_policy TEXT;
    v_ai_policy TEXT;
    v_safe_candidates JSONB := '[]'::JSONB;
    v_safe_payload JSONB;
    v_status TEXT := 'queued';
    v_reason TEXT;
    v_count INTEGER := 0;
BEGIN
    SELECT intent.* INTO v_intent
    FROM public.analysis_v2_score_audit_intents AS intent
    WHERE intent.request_id = p_request_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT source.* INTO v_existing
    FROM public.analysis_v2_score_audit_sources AS source
    WHERE source.request_id = p_request_id
      AND source.source_result_hash = v_intent.source_result_hash
      AND source.source_generation = v_intent.source_generation;
    IF FOUND THEN
        RETURN pg_catalog.jsonb_build_object(
            'status', v_existing.source_status,
            'generation', v_intent.source_generation,
            'count', v_existing.captured_count, 'reason', v_existing.reason
        );
    END IF;
    SELECT stage.* INTO v_stage
    FROM public.analysis_v2_ai_scoring_stage_checkpoints AS stage
    WHERE stage.request_id = p_request_id
      AND stage.stage_kind = 'final_score' AND stage.batch_key = -1
      AND stage.result_hash = v_intent.source_result_hash;
    SELECT request.policy_versions_snapshot->>'risk',
           request.policy_versions_snapshot->>'aiStage'
    INTO v_policy, v_ai_policy
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id AND request.pipeline_version = 'v2';
    IF v_stage.request_id IS NULL THEN
        v_status := 'partial';
        v_reason := 'FINAL_SCORE_CHECKPOINT_MISSING';
    ELSIF v_policy NOT IN ('risk-policy-v2.4', 'risk-policy-v2.5')
       OR v_stage.payload->>'riskPolicyVersion' IS DISTINCT FROM v_policy
       OR pg_catalog.jsonb_typeof(v_stage.payload->'candidates') <> 'array'
       OR pg_catalog.jsonb_array_length(v_stage.payload->'candidates') > 900
       OR pg_catalog.jsonb_array_length(v_stage.payload->'candidates')
            <> v_intent.checkpoint_item_count THEN
        v_status := 'partial';
        v_reason := 'UNSUPPORTED_OR_MALFORMED_POLICY_SNAPSHOT';
    ELSE
        v_count := pg_catalog.jsonb_array_length(v_stage.payload->'candidates');
        SELECT COALESCE(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'candidateId', item.value->'candidateId',
                'username', item.value->'username',
                'accountContext', item.value->'accountContext',
                'uniqueTargetPostsLikedByCandidate',
                    item.value->'uniqueTargetPostsLikedByCandidate',
                'boundedCandidateCommentsOnTarget',
                    item.value->'boundedCandidateCommentsOnTarget',
                'hasCandidateToTargetTagOrCaptionMention',
                    item.value->'hasCandidateToTargetTagOrCaptionMention',
                'hasTargetToCandidateTagOrCaptionMention',
                    item.value->'hasTargetToCandidateTagOrCaptionMention',
                'reverseLikeStatus', item.value->'reverseLikeStatus',
                'recentFemaleMutualRank', item.value->'recentFemaleMutualRank',
                'appearanceGrade', item.value->'appearanceGrade',
                'exposureScore', item.value->'exposureScore',
                'hasWeakPartnerEvidence', item.value->'hasWeakPartnerEvidence',
                'hasStrongPartnerEvidence', item.value->'hasStrongPartnerEvidence',
                'relativeTierApplied', item.value->'relativeTierApplied',
                'displayScore', item.value->'displayScore',
                'riskBand', item.value->'riskBand',
                'featuredRank', item.value->'featuredRank',
                'risk', pg_catalog.jsonb_build_object(
                    'policyVersion', item.value->'risk'->'policyVersion',
                    'components', item.value->'risk'->'components',
                    'weakPartnerAdjustment',
                        item.value->'risk'->'weakPartnerAdjustment',
                    'preScore', item.value->'risk'->'preScore',
                    'rawScore', item.value->'risk'->'rawScore',
                    'publicScore', item.value->'risk'->'publicScore',
                    'displayScore', item.value->'risk'->'displayScore',
                    'riskBand', item.value->'risk'->'riskBand',
                    'partnerCapApplied', item.value->'risk'->'partnerCapApplied'
                ),
                'genderProvenance', 'unavailable'
            ) ORDER BY item.ordinality
        ), '[]'::JSONB) INTO v_safe_candidates
        FROM pg_catalog.jsonb_array_elements(v_stage.payload->'candidates')
            WITH ORDINALITY AS item(value, ordinality);
        v_safe_payload := pg_catalog.jsonb_build_object(
            'riskPolicyVersion', v_policy,
            'candidates', v_safe_candidates
        );
        IF pg_catalog.octet_length(v_safe_payload::TEXT) > 4194304 THEN
            v_status := 'partial';
            v_reason := 'SAFE_SOURCE_PAYLOAD_TOO_LARGE';
            v_count := 0;
            v_safe_payload := NULL;
        END IF;
    END IF;
    INSERT INTO public.analysis_v2_score_audit_sources (
        request_id, source_result_hash, risk_policy_version, ai_policy_version,
        source_status, reason, captured_count, source_generation, source_payload
    ) VALUES (
        p_request_id, v_intent.source_result_hash,
        COALESCE(v_policy, 'unknown'), v_ai_policy, v_status, v_reason,
        CASE WHEN v_status = 'queued' THEN v_count ELSE 0 END,
        v_intent.source_generation,
        CASE WHEN v_status = 'queued' THEN v_safe_payload ELSE NULL END
    ) ON CONFLICT (request_id, source_result_hash) DO NOTHING;
    RETURN pg_catalog.jsonb_build_object(
        'status', v_status, 'generation', v_intent.source_generation,
        'count', CASE WHEN v_status = 'queued' THEN v_count ELSE 0 END,
        'reason', v_reason
    );
EXCEPTION WHEN OTHERS THEN
    RETURN pg_catalog.jsonb_build_object(
        'status','partial','reason','SOURCE_CAPTURE_FAILED'
    );
END;
$$;


--
-- Name: checkpoint_analysis_preflight_provider_run_started(uuid, uuid, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_preflight_provider_run_started(p_preflight_id uuid, p_claim_token uuid, p_input_hash text, p_credential_slot text, p_max_charge_usd numeric, p_run_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_claim_token IS NULL
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS DISTINCT FROM 0.002600000000
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_preflight.expires_at <= v_now
       OR NOT (
            (
                v_preflight.status = 'processing'
                AND v_preflight.lease_token IS NOT DISTINCT FROM p_claim_token
                AND v_preflight.lease_expires_at IS NOT NULL
                AND v_preflight.lease_expires_at > v_now
            )
            OR (
                v_preflight.status = 'ready'
                AND v_preflight.consumed_request_id IS NULL
                AND v_preflight.admission_status = 'processing'
                AND v_preflight.admission_claim_token IS NOT DISTINCT FROM p_claim_token
                AND v_preflight.admission_lease_expires_at IS NOT NULL
                AND v_preflight.admission_lease_expires_at > v_now
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = 'target-profile-fallback'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.input_hash IS DISTINCT FROM p_input_hash
       OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM p_max_charge_usd THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.status <> 'starting' THEN
        IF v_run.run_id IS DISTINCT FROM p_run_id THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_RUN_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_preflight_provider_run_json(v_run);
    END IF;

    UPDATE public.analysis_preflight_provider_runs AS provider_run
    SET status = 'running',
        run_id = p_run_id,
        run_started_at = v_now,
        updated_at = v_now
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = 'target-profile-fallback'
    RETURNING provider_run.* INTO v_run;

    RETURN public.analysis_preflight_provider_run_json(v_run);
END;
$_$;


--
-- Name: checkpoint_analysis_preflight_provider_run_terminal(uuid, uuid, text, text, numeric, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_preflight_provider_run_terminal(p_preflight_id uuid, p_claim_token uuid, p_input_hash text, p_credential_slot text, p_max_charge_usd numeric, p_run_id text, p_status text, p_actual_usage_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_claim_token IS NULL
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS DISTINCT FROM 0.002600000000
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_status IS NULL
       OR p_status NOT IN ('succeeded', 'failed', 'aborted', 'timed_out')
       OR (
            p_actual_usage_usd IS NOT NULL
            AND (
                p_actual_usage_usd NOT BETWEEN 0 AND 100000
                OR p_actual_usage_usd <> pg_catalog.round(p_actual_usage_usd, 12)
                OR p_actual_usage_usd > p_max_charge_usd + 0.000000001
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_preflight.expires_at <= v_now
       OR NOT (
            (
                v_preflight.status = 'processing'
                AND v_preflight.lease_token IS NOT DISTINCT FROM p_claim_token
                AND v_preflight.lease_expires_at IS NOT NULL
                AND v_preflight.lease_expires_at > v_now
            )
            OR (
                v_preflight.status = 'ready'
                AND v_preflight.consumed_request_id IS NULL
                AND v_preflight.admission_status = 'processing'
                AND v_preflight.admission_claim_token IS NOT DISTINCT FROM p_claim_token
                AND v_preflight.admission_lease_expires_at IS NOT NULL
                AND v_preflight.admission_lease_expires_at > v_now
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = 'target-profile-fallback'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.input_hash IS DISTINCT FROM p_input_hash
       OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM p_max_charge_usd THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.run_id IS DISTINCT FROM p_run_id OR v_run.status = 'starting' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_RUN_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.status IN ('succeeded', 'failed', 'aborted', 'timed_out') THEN
        IF v_run.status IS DISTINCT FROM p_status
           OR (
                p_actual_usage_usd IS NOT NULL
                AND v_run.actual_usage_usd IS NOT NULL
                AND v_run.actual_usage_usd IS DISTINCT FROM p_actual_usage_usd
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_TERMINAL_CONFLICT',
                ERRCODE = 'P0001';
        END IF;

        IF p_actual_usage_usd IS NOT NULL AND v_run.actual_usage_usd IS NULL THEN
            UPDATE public.analysis_preflight_provider_runs AS provider_run
            SET actual_usage_usd = p_actual_usage_usd,
                usage_reconciled_at = v_now,
                updated_at = v_now
            WHERE provider_run.preflight_id = p_preflight_id
              AND provider_run.operation_key = 'target-profile-fallback'
            RETURNING provider_run.* INTO v_run;
        END IF;
        IF v_run.actual_usage_usd IS NOT NULL THEN
            PERFORM public.record_analysis_preflight_provider_cost_event(
                v_run.run_id,
                v_run.logical_provider,
                v_run.actor_id,
                v_run.credential_slot,
                v_run.status,
                v_run.max_charge_usd,
                v_run.actual_usage_usd,
                (v_run.terminalized_at AT TIME ZONE 'UTC')::DATE
            );
        END IF;
        RETURN public.analysis_preflight_provider_run_json(v_run);
    END IF;

    IF v_run.status <> 'running' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_STATE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflight_provider_runs AS provider_run
    SET status = p_status,
        actual_usage_usd = p_actual_usage_usd,
        terminalized_at = v_now,
        usage_reconciled_at = CASE
            WHEN p_actual_usage_usd IS NULL THEN NULL
            ELSE v_now
        END,
        updated_at = v_now
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = 'target-profile-fallback'
    RETURNING provider_run.* INTO v_run;

    IF v_run.actual_usage_usd IS NOT NULL THEN
        PERFORM public.record_analysis_preflight_provider_cost_event(
            v_run.run_id,
            v_run.logical_provider,
            v_run.actor_id,
            v_run.credential_slot,
            v_run.status,
            v_run.max_charge_usd,
            v_run.actual_usage_usd,
            (v_run.terminalized_at AT TIME ZONE 'UTC')::DATE
        );
    END IF;

    RETURN public.analysis_preflight_provider_run_json(v_run);
END;
$_$;


--
-- Name: checkpoint_analysis_provider_run(uuid, uuid, text, text, text, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_provider_run(p_request_id uuid, p_user_id uuid, p_expected_step text, p_operation_key text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric, p_run_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    affected_rows INTEGER;
BEGIN
    IF p_request_id IS NULL
       OR p_user_id IS NULL
       OR p_expected_step IS NULL
       OR p_operation_key IS NULL
       OR p_operation_key !~ '^(profile:target|profiles:(0|[1-9][0-9]{0,6})|relationship:(followers|following)|interaction:(target_likers|target_comments|candidate_likers):(0|[1-9][0-9]{0,6}))$'
       OR NOT (
           (p_expected_step = 'collect' AND p_operation_key ~ '^(profile:target|relationship:)')
           OR (p_expected_step = 'profiles' AND p_operation_key ~ '^profiles:')
           OR (p_expected_step = 'interactions' AND p_operation_key ~ '^interaction:')
       )
       OR p_logical_provider IS NULL
       OR p_logical_provider NOT IN ('apify', 'coderx')
       OR p_actor_id IS NULL
       OR p_actor_id !~ '^[A-Za-z0-9][A-Za-z0-9._~/-]{2,199}$'
       OR p_credential_slot IS NULL
       OR p_credential_slot NOT IN ('primary', 'secondary')
       OR p_max_charge_usd IS NULL
       OR p_max_charge_usd::TEXT IN ('NaN', 'Infinity', '-Infinity')
       OR p_max_charge_usd < 0
       OR p_max_charge_usd > 100000
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PROVIDER_RUN_INVALID',
            ERRCODE = '22023';
    END IF;

    PERFORM 1
    FROM public.analysis_requests
    WHERE id = p_request_id
      AND user_id = p_user_id
      AND status IN ('pending', 'processing')
      AND COALESCE(current_step, 'pending') = p_expected_step
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    UPDATE public.analysis_provider_runs
    SET status = 'running',
        run_id = p_run_id,
        updated_at = clock_timestamp()
    WHERE request_id = p_request_id
      AND operation_key = p_operation_key
      AND logical_provider = p_logical_provider
      AND actor_id = p_actor_id
      AND credential_slot = p_credential_slot
      AND max_charge_usd = p_max_charge_usd
      AND status = 'starting'
      AND run_id IS NULL;

    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    RETURN affected_rows = 1;
END;
$_$;


--
-- Name: checkpoint_analysis_relationship_list(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_relationship_list(p_request_id uuid, p_user_id uuid, p_kind text, p_rows jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    affected_rows INTEGER;
BEGIN
    IF p_kind NOT IN ('followers', 'following') THEN
        RAISE EXCEPTION 'invalid relationship checkpoint kind';
    END IF;
    IF p_rows IS NULL
       OR jsonb_typeof(p_rows) <> 'array'
       OR jsonb_array_length(p_rows) > 1000 THEN
        RAISE EXCEPTION 'invalid relationship checkpoint rows';
    END IF;

    UPDATE public.analysis_requests
    SET step_data = jsonb_set(
        jsonb_set(
            COALESCE(step_data, '{}'::JSONB),
            '{relationshipCheckpoint}',
            COALESCE(step_data->'relationshipCheckpoint', '{}'::JSONB),
            TRUE
        ),
        ARRAY['relationshipCheckpoint', p_kind],
        p_rows,
        TRUE
    )
    WHERE id = p_request_id
      AND user_id = p_user_id
      AND status IN ('pending', 'processing')
      AND COALESCE(current_step, 'pending') = 'collect';

    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    RETURN affected_rows = 1;
END;
$$;


--
-- Name: checkpoint_analysis_revenue_primary_quality_v1(uuid, text, uuid, text, integer, integer, integer, integer, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_revenue_primary_quality_v1(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_public_mutual_count integer, p_screened_count integer, p_not_screened_count integer, p_initial_unknown_burden_count integer, p_final_unknown_burden_count integer, p_coverage_valid boolean, p_resolver_pass_started boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_existing public.analysis_revenue_primary_quality_checkpoints%ROWTYPE;
    v_pass public.analysis_revenue_resolver_passes%ROWTYPE;
    v_valid BOOLEAN;
BEGIN
    IF p_job_key IS DISTINCT FROM 'coordinator:join:primary-evidence'
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_public_mutual_count IS NULL
       OR p_screened_count IS NULL
       OR p_not_screened_count IS NULL
       OR p_initial_unknown_burden_count IS NULL
       OR p_final_unknown_burden_count IS NULL
       OR p_resolver_pass_started IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    PERFORM public.analysis_revenue_ai_cost_assert_lineage_v1(
        p_request_id, p_job_key, p_job_claim_token, p_job_input_hash, TRUE
    );
    PERFORM public.analysis_revenue_ai_cost_assert_parent_v1(p_request_id);
    SELECT * INTO v_parent FROM public.analysis_revenue_run_ledgers
     WHERE request_id = p_request_id FOR UPDATE;

    v_valid := p_coverage_valid IS TRUE
        AND p_public_mutual_count >= 0
        AND p_screened_count >= 0
        AND p_not_screened_count >= 0
        AND p_initial_unknown_burden_count BETWEEN 0 AND p_screened_count
        AND p_final_unknown_burden_count BETWEEN 0 AND p_screened_count
        AND p_screened_count + p_not_screened_count = p_public_mutual_count
        AND (p_public_mutual_count = 0 OR p_screened_count > 0)
        AND p_resolver_pass_started = (
            p_initial_unknown_burden_count * 10 > p_screened_count * 3
        )
        AND p_final_unknown_burden_count * 10 <= p_screened_count * 3;

    SELECT * INTO v_existing
    FROM public.analysis_revenue_primary_quality_checkpoints
    WHERE request_id = p_request_id FOR UPDATE;
    IF v_existing.request_id IS NOT NULL THEN
        IF v_existing.job_key IS DISTINCT FROM p_job_key
           OR v_existing.job_input_hash IS DISTINCT FROM p_job_input_hash
           OR v_existing.public_mutual_count IS DISTINCT FROM p_public_mutual_count
           OR v_existing.screened_count IS DISTINCT FROM p_screened_count
           OR v_existing.not_screened_count IS DISTINCT FROM p_not_screened_count
           OR v_existing.initial_unknown_burden_count
                IS DISTINCT FROM p_initial_unknown_burden_count
           OR v_existing.final_unknown_burden_count
                IS DISTINCT FROM p_final_unknown_burden_count
           OR v_existing.resolver_pass_started IS DISTINCT FROM p_resolver_pass_started THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_DRIFT';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'disposition', v_existing.disposition,
            'created', FALSE,
            'replayed', TRUE
        );
    END IF;

    IF p_resolver_pass_started THEN
        SELECT * INTO v_pass FROM public.analysis_revenue_resolver_passes
        WHERE request_id = p_request_id FOR UPDATE;
        IF v_pass.request_id IS NULL THEN
            -- An incoherent profile cohort is never allowed to enter the
            -- resolver boundary merely to satisfy a ratio.  Persist its
            -- manual-review quality receipt directly; a valid cohort above
            -- the threshold still requires the immutable pass row below.
            IF p_coverage_valid IS TRUE THEN
                RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
            END IF;
        ELSE
            IF v_pass.job_key IS DISTINCT FROM p_job_key
               OR v_pass.job_input_hash IS DISTINCT FROM p_job_input_hash
               OR v_pass.screened_count IS DISTINCT FROM p_screened_count
               OR v_pass.unknown_burden_count
                    IS DISTINCT FROM p_initial_unknown_burden_count THEN
                RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
            END IF;
            IF v_pass.disposition = 'started' THEN
                UPDATE public.analysis_revenue_resolver_passes
                   SET final_unknown_burden_count = p_final_unknown_burden_count,
                       disposition = CASE WHEN v_valid THEN 'accepted' ELSE 'manual_review' END,
                       completed_at = pg_catalog.clock_timestamp()
                 WHERE request_id = p_request_id;
            ELSIF v_pass.final_unknown_burden_count
                      IS DISTINCT FROM p_final_unknown_burden_count
                  OR v_pass.disposition IS DISTINCT FROM (
                        CASE WHEN v_valid THEN 'accepted' ELSE 'manual_review' END
                  ) THEN
                RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_DRIFT';
            END IF;
        END IF;
    ELSIF EXISTS (
        SELECT 1 FROM public.analysis_revenue_resolver_passes
        WHERE request_id = p_request_id
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_DRIFT';
    END IF;

    INSERT INTO public.analysis_revenue_primary_quality_checkpoints(
        request_id, job_key, job_input_hash, public_mutual_count, screened_count,
        not_screened_count, initial_unknown_burden_count, final_unknown_burden_count,
        resolver_pass_started, disposition
    ) VALUES (
        p_request_id, p_job_key, p_job_input_hash, p_public_mutual_count,
        p_screened_count, p_not_screened_count, p_initial_unknown_burden_count,
        p_final_unknown_burden_count, p_resolver_pass_started,
        CASE WHEN v_valid AND v_parent.status = 'running'
                  AND v_parent.manual_review_reason IS NULL
            THEN 'accepted' ELSE 'manual_review' END
    );

    IF v_valid AND v_parent.status = 'running' AND v_parent.manual_review_reason IS NULL THEN
        UPDATE public.analysis_revenue_run_ledgers
           SET public_mutual_count = p_public_mutual_count,
               screened_count = p_screened_count,
               not_screened_count = p_not_screened_count,
               unknown_burden_count = p_final_unknown_burden_count
         WHERE request_id = p_request_id;
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'accepted', 'created', TRUE, 'replayed', FALSE
        );
    END IF;

    UPDATE public.analysis_revenue_run_ledgers
       SET public_mutual_count = p_public_mutual_count,
           screened_count = p_screened_count,
           not_screened_count = p_not_screened_count,
           unknown_burden_count = p_final_unknown_burden_count,
           status = 'manual_review',
           manual_review_reason = CASE
               WHEN manual_review_reason IN (
                   'cost_overrun', 'cost_denied', 'ambiguous_external_call'
               ) THEN manual_review_reason
               ELSE 'routing_failure'
           END
     WHERE request_id = p_request_id;
    RETURN pg_catalog.jsonb_build_object(
        'disposition', 'manual_review', 'created', TRUE, 'replayed', FALSE
    );
END;
$_$;


--
-- Name: checkpoint_analysis_v2_active_profile_heartbeat(uuid, text, uuid, text, timestamp with time zone, integer, text, text, text[], text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_active_profile_heartbeat(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_started_at timestamp with time zone, p_total_count integer, p_masked_username text, p_image_url text DEFAULT NULL::text, p_feed_image_urls text[] DEFAULT '{}'::text[], p_candidate_key text DEFAULT NULL::text, p_current_ordinal integer DEFAULT 0, p_call_phase text DEFAULT 'fetching'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_expected_total INTEGER;
    v_advanced BOOLEAN := FALSE;
BEGIN
    IF p_request_id IS NULL OR p_job_key IS NULL
       OR p_job_key !~ '^track:(profiles|profile-ai):batch:[0-9]+$'
       OR p_claim_token IS NULL OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_started_at IS NULL
       OR p_started_at < v_now - INTERVAL '30 minutes'
       OR p_started_at > v_now + INTERVAL '5 minutes'
       OR p_total_count IS NULL OR p_total_count NOT BETWEEN 1 AND 30
       OR p_current_ordinal IS NULL
       OR p_current_ordinal NOT BETWEEN 0 AND p_total_count
       OR p_call_phase IS NULL
       OR p_call_phase NOT IN ('fetching', 'analyzing', 'persisting')
       OR p_masked_username IS NULL
       OR p_masked_username !~ '^[A-Za-z0-9._]*\*[A-Za-z0-9._*]*$'
       OR pg_catalog.char_length(p_masked_username) NOT BETWEEN 1 AND 30
       OR (
            p_image_url IS NOT NULL AND (
                pg_catalog.char_length(p_image_url) NOT BETWEEN 1 AND 2048
                OR p_image_url NOT LIKE '/api/image-proxy?%'
            )
       )
       OR NOT public.analysis_v2_valid_active_profile_feed_image_urls(
            p_feed_image_urls
       )
       OR (
            p_candidate_key IS NOT NULL
            AND p_candidate_key !~ '^[a-f0-9]{64}$'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROGRESS_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND OR v_job.status <> 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROGRESS_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT topology.item_count INTO v_expected_total
    FROM public.analysis_v2_dag_batch_topology AS topology
    WHERE topology.request_id = p_request_id
      AND topology.topology_kind = 'profile'
      AND topology.batch = pg_catalog.substring(p_job_key, '([0-9]+)$')::INTEGER;
    IF NOT FOUND OR v_expected_total IS DISTINCT FROM p_total_count THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROGRESS_TOPOLOGY_MISMATCH', ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.analysis_v2_active_profile_heartbeats (
        request_id, job_key, job_input_hash, claim_token, started_at,
        completed_count, total_count, masked_username, image_url,
        feed_image_urls, candidate_key, call_phase, updated_at
    ) VALUES (
        p_request_id, p_job_key, p_job_input_hash, p_claim_token, p_started_at,
        p_current_ordinal, p_total_count, p_masked_username, p_image_url,
        p_feed_image_urls, p_candidate_key, p_call_phase, v_now
    )
    ON CONFLICT (request_id, job_key) DO UPDATE
    SET job_input_hash = EXCLUDED.job_input_hash,
        claim_token = EXCLUDED.claim_token,
        started_at = EXCLUDED.started_at,
        completed_count = EXCLUDED.completed_count,
        total_count = EXCLUDED.total_count,
        -- Identity and media are updated as one ordinal-paired record. A
        -- lower ordinal from a concurrent provider call is rejected below,
        -- so it can never overwrite the higher ordinal's label or phase.
        masked_username = EXCLUDED.masked_username,
        image_url = EXCLUDED.image_url,
        feed_image_urls = EXCLUDED.feed_image_urls,
        candidate_key = EXCLUDED.candidate_key,
        call_phase = EXCLUDED.call_phase,
        updated_at = EXCLUDED.updated_at
    WHERE EXCLUDED.claim_token
            IS DISTINCT FROM public.analysis_v2_active_profile_heartbeats.claim_token
       OR (
            EXCLUDED.claim_token
                IS NOT DISTINCT FROM public.analysis_v2_active_profile_heartbeats.claim_token
            AND EXCLUDED.completed_count
                >= public.analysis_v2_active_profile_heartbeats.completed_count
            AND (
                EXCLUDED.started_at
                    > public.analysis_v2_active_profile_heartbeats.started_at
                OR (
                    EXCLUDED.started_at
                        = public.analysis_v2_active_profile_heartbeats.started_at
                    AND (
                        EXCLUDED.completed_count
                            > public.analysis_v2_active_profile_heartbeats.completed_count
                        OR EXCLUDED.masked_username IS DISTINCT FROM
                            public.analysis_v2_active_profile_heartbeats.masked_username
                        OR EXCLUDED.image_url IS DISTINCT FROM
                            public.analysis_v2_active_profile_heartbeats.image_url
                        OR EXCLUDED.feed_image_urls IS DISTINCT FROM
                            public.analysis_v2_active_profile_heartbeats.feed_image_urls
                        OR EXCLUDED.candidate_key IS DISTINCT FROM
                            public.analysis_v2_active_profile_heartbeats.candidate_key
                        OR EXCLUDED.call_phase IS DISTINCT FROM
                            public.analysis_v2_active_profile_heartbeats.call_phase
                    )
                )
            )
       )
    RETURNING TRUE INTO v_advanced;

    RETURN COALESCE(v_advanced, FALSE);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_ai_global_cache_hit(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_ai_global_cache_hit(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_result_identity jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_checkpoint public.analysis_v2_ai_result_checkpoints%ROWTYPE;
    v_cached public.analysis_v2_ai_global_result_cache%ROWTYPE;
    v_cache_key TEXT;
    v_now TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_operation_key IS NULL
       OR p_result_identity IS NULL
       OR NOT public.analysis_v2_valid_ai_result_identity(p_result_identity)
       OR p_result_identity->>'cache_scope' <> 'global_ttl'
       OR p_operation_key IS DISTINCT FROM
            public.analysis_v2_ai_result_operation_key(p_result_identity) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_RESULT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_cache_key := public.analysis_v2_ai_result_cache_key(p_result_identity);

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_RESULT_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_RESULT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT checkpoint.*
    INTO v_checkpoint
    FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
    WHERE checkpoint.request_id = p_request_id
      AND checkpoint.operation_key = p_operation_key
    FOR UPDATE;

    IF FOUND THEN
        IF v_checkpoint.job_key IS DISTINCT FROM p_job_key
           OR v_checkpoint.cache_key IS DISTINCT FROM v_cache_key
           OR v_checkpoint.stage IS DISTINCT FROM p_result_identity->>'stage'
           OR v_checkpoint.model_name IS DISTINCT FROM p_result_identity->>'model_name'
           OR v_checkpoint.thinking_level IS DISTINCT FROM
                NULLIF(p_result_identity->>'thinking_level', '')
           OR v_checkpoint.media_resolution IS DISTINCT FROM
                NULLIF(p_result_identity->>'media_resolution', '')
           OR v_checkpoint.prompt_version IS DISTINCT FROM
                p_result_identity->>'prompt_version'
           OR v_checkpoint.schema_version IS DISTINCT FROM
                (p_result_identity->>'schema_version')::SMALLINT
           OR v_checkpoint.max_output_tokens IS DISTINCT FROM
                (p_result_identity->>'max_output_tokens')::INTEGER
           OR v_checkpoint.input_hash IS DISTINCT FROM p_result_identity->>'input_hash'
           OR v_checkpoint.media_snapshot_hash IS DISTINCT FROM
                p_result_identity->>'media_snapshot_hash'
           OR v_checkpoint.cache_scope IS DISTINCT FROM 'global_ttl' THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_AI_RESULT_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_ai_result_checkpoint_json(v_checkpoint);
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'analysis-v2-ai-result-cache-key:' || v_cache_key,
            0
        )
    );
    v_now := pg_catalog.clock_timestamp();

    DELETE FROM public.analysis_v2_ai_global_result_cache AS cache
    WHERE cache.cache_key = v_cache_key
      AND cache.expires_at <= v_now;

    SELECT cache.*
    INTO v_cached
    FROM public.analysis_v2_ai_global_result_cache AS cache
    WHERE cache.cache_key = v_cache_key
      AND cache.expires_at > v_now
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    IF v_cached.stage IS DISTINCT FROM p_result_identity->>'stage'
       OR v_cached.model_name IS DISTINCT FROM p_result_identity->>'model_name'
       OR v_cached.thinking_level IS DISTINCT FROM
            NULLIF(p_result_identity->>'thinking_level', '')
       OR v_cached.media_resolution IS DISTINCT FROM
            NULLIF(p_result_identity->>'media_resolution', '')
       OR v_cached.prompt_version IS DISTINCT FROM p_result_identity->>'prompt_version'
       OR v_cached.schema_version IS DISTINCT FROM
            (p_result_identity->>'schema_version')::SMALLINT
       OR v_cached.max_output_tokens IS DISTINCT FROM
            (p_result_identity->>'max_output_tokens')::INTEGER
       OR v_cached.input_hash IS DISTINCT FROM p_result_identity->>'input_hash'
       OR v_cached.media_snapshot_hash IS DISTINCT FROM
            p_result_identity->>'media_snapshot_hash' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_RESULT_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF NOT public.analysis_v2_valid_ai_result_envelope(
        v_cached.result_json,
        v_cached.result_canonical_json,
        v_cached.result_hash
    ) THEN
        DELETE FROM public.analysis_v2_ai_global_result_cache AS cache
        WHERE cache.cache_key = v_cache_key;
        RETURN NULL;
    END IF;

    UPDATE public.analysis_v2_ai_global_result_cache AS cache
    SET last_accessed_at = v_now,
        hit_count = CASE
            WHEN cache.hit_count < 1000000000 THEN cache.hit_count + 1
            ELSE cache.hit_count
        END
    WHERE cache.cache_key = v_cache_key;

    INSERT INTO public.analysis_v2_ai_result_checkpoints (
        request_id,
        job_key,
        operation_key,
        cache_key,
        stage,
        model_name,
        thinking_level,
        media_resolution,
        prompt_version,
        schema_version,
        max_output_tokens,
        input_hash,
        media_snapshot_hash,
        cache_scope,
        source,
        attempt,
        reservation_token,
        result_json,
        result_canonical_json,
        result_hash,
        created_at
    ) VALUES (
        p_request_id,
        p_job_key,
        p_operation_key,
        v_cache_key,
        p_result_identity->>'stage',
        p_result_identity->>'model_name',
        NULLIF(p_result_identity->>'thinking_level', ''),
        NULLIF(p_result_identity->>'media_resolution', ''),
        p_result_identity->>'prompt_version',
        (p_result_identity->>'schema_version')::SMALLINT,
        (p_result_identity->>'max_output_tokens')::INTEGER,
        p_result_identity->>'input_hash',
        p_result_identity->>'media_snapshot_hash',
        'global_ttl',
        'global_cache',
        NULL,
        NULL,
        v_cached.result_json,
        v_cached.result_canonical_json,
        v_cached.result_hash,
        v_now
    )
    RETURNING * INTO v_checkpoint;

    RETURN public.analysis_v2_ai_result_checkpoint_json(v_checkpoint);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_ai_scoring_stage(uuid, text, uuid, text, text, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_ai_scoring_stage(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_stage_kind text, p_batch integer, p_item_count integer, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_batch_key INTEGER;
    v_result_hash TEXT;
    v_existing public.analysis_v2_ai_scoring_stage_checkpoints%ROWTYPE;
    v_stored public.analysis_v2_ai_scoring_stage_checkpoints%ROWTYPE;
BEGIN
    IF p_stage_kind NOT IN (
        'profile_ai_batch', 'primary_join', 'screening', 'reverse_likes',
        'partner_safety', 'final_score', 'narrative'
    ) OR p_item_count IS NULL OR p_item_count < 0 OR p_item_count > 1200
      OR p_payload IS NULL OR pg_catalog.jsonb_typeof(p_payload) <> 'object'
      OR pg_catalog.octet_length(p_payload::TEXT) > 8388608 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_SCORING_STAGE_INVALID', ERRCODE = 'P0001';
    END IF;

    v_job := public.analysis_v2_assert_result_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    PERFORM public.analysis_v2_assert_ai_scoring_stage_producer(
        v_job, p_stage_kind, p_batch
    );
    v_batch_key := COALESCE(p_batch, -1);
    v_result_hash := pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'analysis-v2-ai-scoring-stage-v1' || E'\n'
                || p_stage_kind || E'\n' || v_batch_key::TEXT || E'\n'
                || p_payload::TEXT,
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );

    SELECT checkpoint.* INTO v_existing
    FROM public.analysis_v2_ai_scoring_stage_checkpoints AS checkpoint
    WHERE checkpoint.request_id = p_request_id
      AND checkpoint.stage_kind = p_stage_kind
      AND checkpoint.batch_key = v_batch_key
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.producer_job_key <> p_job_key
           OR v_existing.producer_input_hash <> p_job_input_hash
           OR v_existing.item_count <> p_item_count
           OR v_existing.result_hash <> v_result_hash
           OR v_existing.payload <> p_payload THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_AI_SCORING_STAGE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        IF v_existing.producer_claim_token <> p_claim_token THEN
            UPDATE public.analysis_v2_ai_scoring_stage_checkpoints AS checkpoint
            SET producer_claim_token = p_claim_token
            WHERE checkpoint.request_id = p_request_id
              AND checkpoint.stage_kind = p_stage_kind
              AND checkpoint.batch_key = v_batch_key
            RETURNING checkpoint.* INTO v_existing;
        END IF;
        RETURN public.analysis_v2_ai_scoring_stage_envelope(v_existing);
    END IF;

    INSERT INTO public.analysis_v2_ai_scoring_stage_checkpoints (
        request_id, stage_kind, batch_key, producer_job_key,
        producer_input_hash, producer_claim_token, item_count, result_hash, payload
    ) VALUES (
        p_request_id, p_stage_kind, v_batch_key, p_job_key,
        p_job_input_hash, p_claim_token, p_item_count, v_result_hash, p_payload
    ) RETURNING * INTO v_stored;
    RETURN public.analysis_v2_ai_scoring_stage_envelope(v_stored);
END;
$$;


--
-- Name: checkpoint_analysis_v2_candidate_features(uuid, text, uuid, text, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_candidate_features(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_batch integer, p_analyzed_count integer, p_rows jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT public.analysis_v2_checkpoint_candidate_features_complete(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash,
        p_batch, p_analyzed_count, p_rows
    );
$$;


--
-- Name: checkpoint_analysis_v2_candidate_scores(uuid, text, uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_candidate_scores(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_rows jsonb, p_risk_policy_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_rows JSONB;
    v_count INTEGER;
    v_hash TEXT;
    v_existing public.analysis_v2_candidate_score_manifests%ROWTYPE;
BEGIN
    IF p_risk_policy_version NOT IN ('risk-policy-v2.3', 'risk-policy-v2.4', 'risk-policy-v2.5')
       OR p_rows IS NULL OR pg_catalog.jsonb_typeof(p_rows) <> 'array'
       OR pg_catalog.jsonb_array_length(p_rows) > 900
       OR pg_catalog.octet_length(p_rows::TEXT) > 4194304
       OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR NOT (
                    (
                        p_risk_policy_version = 'risk-policy-v2.3'
                        AND item.value ?& ARRAY[
                            'candidateId', 'displayScore', 'riskBand', 'featuredRank',
                            'recentMutualRank', 'verificationShortlistRank',
                            'partnerSafetySource', 'partnerSafetyOperationKey',
                            'partnerSafetyResultHash', 'components', 'preScore', 'rawScore',
                            'possibleUpperBound', 'publicScore', 'possibleUpperPublicScore',
                            'weakPartnerAdjustment', 'partnerCapApplied',
                            'partnerEvidenceSelectionIds'
                        ]
                        AND item.value - ARRAY[
                            'candidateId', 'displayScore', 'riskBand', 'featuredRank',
                            'recentMutualRank', 'verificationShortlistRank',
                            'partnerSafetySource', 'partnerSafetyOperationKey',
                            'partnerSafetyResultHash', 'components', 'preScore', 'rawScore',
                            'possibleUpperBound', 'publicScore', 'possibleUpperPublicScore',
                            'weakPartnerAdjustment', 'partnerCapApplied',
                            'partnerEvidenceSelectionIds'
                        ] = '{}'::JSONB
                        AND item.value->'components' ?& ARRAY[
                            'candidateToTargetLikes', 'candidateToTargetComments',
                            'targetToCandidateLike', 'tagOrCaptionMention',
                            'recentMutual', 'appearanceExposure'
                        ]
                        AND (item.value->'components') - ARRAY[
                            'candidateToTargetLikes', 'candidateToTargetComments',
                            'targetToCandidateLike', 'tagOrCaptionMention',
                            'recentMutual', 'appearanceExposure'
                        ] = '{}'::JSONB
                    ) OR (
                        p_risk_policy_version IN ('risk-policy-v2.4', 'risk-policy-v2.5')
                        AND item.value ?& ARRAY[
                            'candidateId', 'displayScore', 'riskBand', 'featuredRank',
                            'recentMutualRank', 'verificationShortlistRank',
                            'partnerSafetySource', 'partnerSafetyOperationKey',
                            'partnerSafetyResultHash', 'components', 'preScore', 'rawScore',
                            'possibleUpperBound', 'publicScore', 'possibleUpperPublicScore',
                            'weakPartnerAdjustment', 'partnerCapApplied',
                            'partnerEvidenceSelectionIds', 'accountContext'
                        ]
                        AND item.value - ARRAY[
                            'candidateId', 'displayScore', 'riskBand', 'featuredRank',
                            'recentMutualRank', 'verificationShortlistRank',
                            'partnerSafetySource', 'partnerSafetyOperationKey',
                            'partnerSafetyResultHash', 'components', 'preScore', 'rawScore',
                            'possibleUpperBound', 'publicScore', 'possibleUpperPublicScore',
                            'weakPartnerAdjustment', 'partnerCapApplied',
                            'partnerEvidenceSelectionIds', 'accountContext'
                        ] = '{}'::JSONB
                        AND pg_catalog.jsonb_typeof(item.value->'accountContext') = 'string'
                        AND item.value->>'accountContext' IN (
                            'personal', 'individual_creator', 'official_group_or_brand', 'uncertain'
                        )
                        AND item.value->'components' ?& ARRAY[
                            'candidateToTargetLikes', 'candidateToTargetComments',
                            'candidateToTargetTagOrCaptionMention',
                            'targetToCandidateTagOrCaptionMention',
                            'targetToCandidateLike', 'recentMutual', 'appearanceExposure'
                        ]
                        AND (item.value->'components') - ARRAY[
                            'candidateToTargetLikes', 'candidateToTargetComments',
                            'candidateToTargetTagOrCaptionMention',
                            'targetToCandidateTagOrCaptionMention',
                            'targetToCandidateLike', 'recentMutual', 'appearanceExposure'
                        ] = '{}'::JSONB
                    )
                )
               OR item.value->>'candidateId' !~ '^[A-Za-z0-9._:-]{1,128}$'
               OR item.value->>'riskBand' NOT IN ('normal', 'caution', 'high_risk')
               OR item.value->>'partnerSafetySource' NOT IN (
                    'not_collected', 'feature_only', 'gemini', 'safe_fallback'
               )
               OR NOT public.analysis_v2_result_valid_score_components(
                    item.value->'components'
               )
               OR pg_catalog.jsonb_typeof(item.value->'partnerCapApplied') <> 'boolean'
               OR pg_catalog.jsonb_typeof(item.value->'partnerEvidenceSelectionIds') <> 'array'
               OR pg_catalog.jsonb_array_length(item.value->'partnerEvidenceSelectionIds') > 8
               OR EXISTS (
                    SELECT 1
                    FROM pg_catalog.jsonb_each(item.value) AS field(key, field_value)
                    WHERE field.key IN (
                        'displayScore', 'preScore', 'rawScore', 'possibleUpperBound',
                        'publicScore', 'possibleUpperPublicScore',
                        'weakPartnerAdjustment'
                    )
                      AND pg_catalog.jsonb_typeof(field.field_value) <> 'number'
               )
               OR pg_catalog.jsonb_typeof(item.value->'featuredRank') NOT IN ('number', 'null')
               OR pg_catalog.jsonb_typeof(item.value->'recentMutualRank') NOT IN ('number', 'null')
               OR pg_catalog.jsonb_typeof(item.value->'verificationShortlistRank')
                    NOT IN ('number', 'null')
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
        WHERE (item.value->>'weakPartnerAdjustment')::NUMERIC NOT IN (-5, 0)
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;

    v_job := public.analysis_v2_assert_result_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    IF v_job.job_key <> 'coordinator:join:final-score'
       OR v_job.track <> 'coordinator' OR v_job.kind <> 'join'
       OR v_job.batch IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = p_request_id
          AND analysis_request.policy_versions_snapshot->>'risk' = p_risk_policy_version
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(
        pg_catalog.jsonb_agg(item.value ORDER BY item.value->>'candidateId'),
        '[]'::JSONB
    ) INTO v_rows
    FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value);
    v_count := pg_catalog.jsonb_array_length(v_rows);
    IF v_count <> (
        SELECT pg_catalog.count(*)
        FROM public.analysis_v2_preliminary_score_rows AS preliminary
        WHERE preliminary.request_id = p_request_id
    ) OR (
        SELECT pg_catalog.count(DISTINCT item.value->>'candidateId')
        FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
    ) <> v_count OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
        LEFT JOIN public.analysis_v2_preliminary_score_rows AS preliminary
          ON preliminary.request_id = p_request_id
         AND preliminary.candidate_id = item.value->>'candidateId'
        LEFT JOIN public.analysis_v2_reverse_like_rows AS reverse_like
          ON reverse_like.request_id = p_request_id
         AND reverse_like.candidate_id = item.value->>'candidateId'
        LEFT JOIN public.analysis_v2_partner_safety_rows AS partner
          ON partner.request_id = p_request_id
         AND partner.candidate_id = item.value->>'candidateId'
        CROSS JOIN LATERAL (
            SELECT
                (item.value->'components'->>'candidateToTargetLikes')::NUMERIC
                    + (item.value->'components'->>'candidateToTargetComments')::NUMERIC
                    + (item.value->'components'->>'targetToCandidateLike')::NUMERIC
                    + CASE
                        WHEN p_risk_policy_version = 'risk-policy-v2.3'
                            THEN (item.value->'components'->>'tagOrCaptionMention')::NUMERIC
                        ELSE (item.value->'components'->>'candidateToTargetTagOrCaptionMention')::NUMERIC
                            + (item.value->'components'->>'targetToCandidateTagOrCaptionMention')::NUMERIC
                    END
                    + (item.value->'components'->>'recentMutual')::NUMERIC
                    + (item.value->'components'->>'appearanceExposure')::NUMERIC
                    AS component_total,
                (item.value->'components'->>'candidateToTargetLikes')::NUMERIC
                    + (item.value->'components'->>'candidateToTargetComments')::NUMERIC
                    + CASE
                        WHEN p_risk_policy_version = 'risk-policy-v2.3'
                            THEN (item.value->'components'->>'tagOrCaptionMention')::NUMERIC
                        ELSE (item.value->'components'->>'candidateToTargetTagOrCaptionMention')::NUMERIC
                            + (item.value->'components'->>'targetToCandidateTagOrCaptionMention')::NUMERIC
                    END
                    + (item.value->'components'->>'recentMutual')::NUMERIC
                    + (item.value->'components'->>'appearanceExposure')::NUMERIC
                    AS preliminary_component_total
        ) AS component_sum
        CROSS JOIN LATERAL (
            SELECT
                GREATEST(0, LEAST(
                    component_sum.preliminary_component_total
                        + (item.value->>'weakPartnerAdjustment')::NUMERIC,
                    CASE WHEN p_risk_policy_version = 'risk-policy-v2.3'
                        THEN 97 ELSE 95 END
                )) AS expected_pre_score,
                GREATEST(0, LEAST(
                    component_sum.component_total
                        + (item.value->>'weakPartnerAdjustment')::NUMERIC,
                    100
                )) AS expected_raw_score
        ) AS expected_score
        WHERE preliminary.candidate_id IS NULL
           OR reverse_like.candidate_id IS NULL
           OR partner.candidate_id IS NULL
           OR item.value->'components' IS DISTINCT FROM pg_catalog.jsonb_set(
                preliminary.components,
                ARRAY['targetToCandidateLike'],
                pg_catalog.to_jsonb(
                    CASE
                        WHEN p_risk_policy_version IN ('risk-policy-v2.4', 'risk-policy-v2.5')
                            AND reverse_like.reverse_like_status = 'observed'
                            AND reverse_like.component_score = 3
                        THEN 5::NUMERIC
                        ELSE reverse_like.component_score
                    END
                ),
                TRUE
            )
           OR (item.value->>'weakPartnerAdjustment')::NUMERIC IS DISTINCT FROM
                CASE WHEN partner.has_weak_partner_evidence
                          AND NOT partner.has_strong_partner_evidence
                    THEN -5::NUMERIC ELSE 0::NUMERIC END
           OR pg_catalog.abs(
                (item.value->>'preScore')::NUMERIC - expected_score.expected_pre_score
              ) > 0.0001
           OR pg_catalog.abs(
                (item.value->>'rawScore')::NUMERIC
                - expected_score.expected_raw_score
           ) > 0.0001
           OR pg_catalog.abs(
                (item.value->>'possibleUpperBound')::NUMERIC
                - CASE reverse_like.reverse_like_status
                    WHEN 'not_collected' THEN LEAST(
                        expected_score.expected_pre_score
                    + CASE WHEN p_risk_policy_version = 'risk-policy-v2.3'
                        THEN 3 ELSE 5 END, 100
                    )
                    ELSE expected_score.expected_raw_score
                  END
           ) > 0.0001
           OR item.value->'recentMutualRank' IS DISTINCT FROM
                COALESCE(pg_catalog.to_jsonb(preliminary.recent_mutual_rank), 'null'::JSONB)
           OR item.value->'verificationShortlistRank' IS DISTINCT FROM
                COALESCE(
                    pg_catalog.to_jsonb(preliminary.verification_shortlist_rank),
                    'null'::JSONB
                )
           OR item.value->>'partnerSafetySource' IS DISTINCT FROM partner.source
           OR item.value->'partnerSafetyOperationKey' IS DISTINCT FROM
                COALESCE(pg_catalog.to_jsonb(partner.operation_key), 'null'::JSONB)
           OR item.value->'partnerSafetyResultHash' IS DISTINCT FROM
                COALESCE(pg_catalog.to_jsonb(partner.ai_result_hash), 'null'::JSONB)
           OR ARRAY(
                SELECT selection_id.value
                FROM pg_catalog.jsonb_array_elements_text(
                    item.value->'partnerEvidenceSelectionIds'
                ) WITH ORDINALITY AS selection_id(value, ordinality)
                ORDER BY selection_id.ordinality
              ) IS DISTINCT FROM partner.evidence_selection_ids
           OR pg_catalog.abs(
                (item.value->>'publicScore')::NUMERIC
                - CASE WHEN partner.has_strong_partner_evidence
                    THEN LEAST(
                        1 + 9 * expected_score.expected_raw_score / 100,
                        3.4
                    )
                    ELSE 1 + 9 * expected_score.expected_raw_score / 100
                  END
           ) > 0.0001
           OR pg_catalog.abs(
                (item.value->>'possibleUpperPublicScore')::NUMERIC
                - CASE WHEN partner.has_strong_partner_evidence
                    THEN LEAST(1 + 9 * (item.value->>'possibleUpperBound')::NUMERIC / 100, 3.4)
                    ELSE 1 + 9 * (item.value->>'possibleUpperBound')::NUMERIC / 100
                  END
           ) > 0.0001
           OR (item.value->>'partnerCapApplied')::BOOLEAN IS DISTINCT FROM (
                partner.has_strong_partner_evidence
                AND 1 + 9 * expected_score.expected_raw_score / 100 > 3.4
           )
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;


    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
        JOIN public.analysis_v2_expected_relative_risk_rows(
            v_rows,
            ARRAY(
                SELECT partner.candidate_id
                FROM public.analysis_v2_partner_safety_rows AS partner
                WHERE partner.request_id = p_request_id
                  AND partner.has_strong_partner_evidence
                ORDER BY partner.candidate_id
            )
        , p_risk_policy_version
        ) AS expected
          ON expected.candidate_id = item.value->>'candidateId'
        WHERE pg_catalog.abs(
                (item.value->>'displayScore')::NUMERIC - expected.display_score
              ) > 0.0001
           OR item.value->>'riskBand' IS DISTINCT FROM expected.risk_band
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    v_hash := public.analysis_v2_result_staging_hash('candidate_scores_v2', NULL, v_rows);
    SELECT manifest.* INTO v_existing
    FROM public.analysis_v2_candidate_score_manifests AS manifest
    WHERE manifest.request_id = p_request_id FOR UPDATE;
    IF FOUND THEN
        IF v_existing.producer_job_key <> p_job_key
           OR v_existing.producer_input_hash <> p_job_input_hash
           OR v_existing.producer_claim_token <> p_claim_token
           OR v_existing.risk_policy_version <> p_risk_policy_version
           OR v_existing.item_count <> v_count OR v_existing.result_hash <> v_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_result_checkpoint_json(
            p_request_id, p_job_key, NULL, v_count, v_count, v_hash
        );
    END IF;

    INSERT INTO public.analysis_v2_candidate_score_manifests (
        request_id, producer_job_key, producer_input_hash, producer_claim_token,
        risk_policy_version, item_count, result_hash
    ) VALUES (
        p_request_id, p_job_key, p_job_input_hash, p_claim_token,
        p_risk_policy_version, v_count, v_hash
    );
    INSERT INTO public.analysis_v2_candidate_score_rows (
        request_id, candidate_id, display_score, risk_band, featured_rank,
        recent_mutual_rank, verification_shortlist_rank, partner_safety_source,
        partner_safety_operation_key, partner_safety_result_hash, components,
        weak_partner_adjustment, pre_score, raw_score, possible_upper_bound, public_score,
        possible_upper_public_score, partner_cap_applied, partner_evidence_selection_ids
    )
    SELECT p_request_id, item.value->>'candidateId',
        (item.value->>'displayScore')::NUMERIC, item.value->>'riskBand',
        CASE WHEN item.value->'featuredRank' = 'null'::JSONB THEN NULL
            ELSE (item.value->>'featuredRank')::SMALLINT END,
        CASE WHEN item.value->'recentMutualRank' = 'null'::JSONB THEN NULL
            ELSE (item.value->>'recentMutualRank')::SMALLINT END,
        CASE WHEN item.value->'verificationShortlistRank' = 'null'::JSONB THEN NULL
            ELSE (item.value->>'verificationShortlistRank')::SMALLINT END,
        item.value->>'partnerSafetySource',
        NULLIF(item.value->>'partnerSafetyOperationKey', ''),
        NULLIF(item.value->>'partnerSafetyResultHash', ''), item.value->'components',
        (item.value->>'weakPartnerAdjustment')::NUMERIC,
        (item.value->>'preScore')::NUMERIC, (item.value->>'rawScore')::NUMERIC,
        (item.value->>'possibleUpperBound')::NUMERIC,
        (item.value->>'publicScore')::NUMERIC,
        (item.value->>'possibleUpperPublicScore')::NUMERIC,
        (item.value->>'partnerCapApplied')::BOOLEAN,
        ARRAY(
            SELECT selection_id.value
            FROM pg_catalog.jsonb_array_elements_text(
                item.value->'partnerEvidenceSelectionIds'
            ) WITH ORDINALITY AS selection_id(value, ordinality)
            ORDER BY selection_id.ordinality
        )
    FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value);

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT score.candidate_id, score.risk_band, score.featured_rank,
                pg_catalog.row_number() OVER (
                    PARTITION BY score.risk_band
                    ORDER BY score.display_score DESC, score.candidate_id
                , p_risk_policy_version
        ) AS expected_rank
            FROM public.analysis_v2_candidate_score_rows AS score
            WHERE score.request_id = p_request_id
              AND score.risk_band IN ('high_risk', 'caution')
        ) AS ranked
        WHERE ranked.featured_rank IS DISTINCT FROM CASE
            WHEN ranked.risk_band = 'high_risk' AND ranked.expected_rank <= 3
                THEN ranked.expected_rank::SMALLINT
            WHEN ranked.risk_band = 'caution'
                            AND ranked.expected_rank <= CASE
                                WHEN p_risk_policy_version = 'risk-policy-v2.3' THEN 15
                                ELSE 10
                            END
                THEN ranked.expected_rank::SMALLINT
            ELSE NULL
        END
    ) OR EXISTS (
        SELECT 1 FROM public.analysis_v2_candidate_score_rows AS score
        WHERE score.request_id = p_request_id
          AND score.risk_band = 'normal' AND score.featured_rank IS NOT NULL
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    RETURN public.analysis_v2_result_checkpoint_json(
        p_request_id, p_job_key, NULL, v_count, v_count, v_hash
    );
END;
$_$;


--
-- Name: checkpoint_analysis_v2_dag_manifest(uuid, text, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_dag_manifest(p_request_id uuid, p_job_key text, p_input_hash text, p_claim_token uuid, p_manifest_kind text, p_manifest jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_scope public.analysis_v2_dag_scopes%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_relationship_manifest public.analysis_v2_relationship_manifests%ROWTYPE;
    v_routing_manifest public.analysis_v2_gender_routing_manifests%ROWTYPE;
    v_stage public.analysis_v2_dag_stage_manifests%ROWTYPE;
    v_detected INTEGER;
    v_public INTEGER;
    v_private INTEGER;
    v_detailed INTEGER;
    v_not_screened INTEGER;
    v_revision INTEGER;
    v_result_hash TEXT;
    v_profile_batches JSONB;
    v_private_batches JSONB;
    v_existing_batches JSONB;
    v_selection JSONB;
    v_selection_plan TEXT;
    v_population INTEGER;
    v_selected INTEGER;
    v_population_cap INTEGER;
    v_detailed_cap INTEGER;
    v_all_candidates INTEGER;
    v_selected_candidates INTEGER;
    v_min_ordinal INTEGER;
    v_max_ordinal INTEGER;
BEGIN
    IF p_manifest IS NULL
       OR pg_catalog.jsonb_typeof(p_manifest) <> 'object'
       OR NOT (p_manifest ? 'relationshipSelectionPolicy') THEN
        RETURN public.checkpoint_analysis_v2_dag_manifest_legacy(
            p_request_id, p_job_key, p_input_hash, p_claim_token, p_manifest_kind, p_manifest
        );
    END IF;

    IF p_request_id IS NULL
       OR p_claim_token IS NULL
       OR p_job_key <> 'track:relationships:collect'
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[a-f0-9]{64}$'
       OR p_manifest_kind <> 'relationships'
       OR pg_catalog.octet_length(p_manifest::TEXT) > 65536
       OR NOT (p_manifest ?& ARRAY[
            'revision', 'resultHash', 'detectedMutualCount', 'publicCount', 'privateCount',
            'detailedSelectedPublicCount', 'notScreenedPublicCount', 'profileBatches',
            'privateNameBatches', 'relationshipSelectionPolicy'
       ])
       OR p_manifest - ARRAY[
            'revision', 'resultHash', 'detectedMutualCount', 'publicCount', 'privateCount',
            'detailedSelectedPublicCount', 'notScreenedPublicCount', 'profileBatches',
            'privateNameBatches', 'relationshipSelectionPolicy'
       ]::TEXT[] <> '{}'::JSONB
       OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'revision', 1, 1000000)
       OR pg_catalog.jsonb_typeof(p_manifest->'resultHash') <> 'string'
       OR p_manifest->>'resultHash' !~ '^[a-f0-9]{64}$'
       OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'detectedMutualCount', 0, 1200)
       OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'publicCount', 0, 1200)
       OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'privateCount', 0, 1200)
       OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'detailedSelectedPublicCount', 0, 200)
       OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'notScreenedPublicCount', 0, 1200)
       OR pg_catalog.jsonb_typeof(p_manifest->'profileBatches') <> 'array'
       OR pg_catalog.jsonb_typeof(p_manifest->'privateNameBatches') <> 'array'
       OR pg_catalog.jsonb_typeof(p_manifest->'relationshipSelectionPolicy') <> 'object' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
    END IF;

    v_selection := p_manifest->'relationshipSelectionPolicy';
    IF NOT (v_selection ?& ARRAY[
            'policyVersion', 'relationshipCheckpointId', 'relationshipJobInputHash', 'planId',
            'publicPopulationCount', 'selectedCount'
       ])
       OR v_selection - ARRAY[
            'policyVersion', 'relationshipCheckpointId', 'relationshipJobInputHash', 'planId',
            'publicPopulationCount', 'selectedCount'
       ]::TEXT[] <> '{}'::JSONB
       OR v_selection->>'policyVersion' <> 'gender-routing-v1'
       OR pg_catalog.jsonb_typeof(v_selection->'relationshipCheckpointId') <> 'string'
       OR v_selection->>'relationshipCheckpointId' !~ '^[a-f0-9]{64}$'
       OR pg_catalog.jsonb_typeof(v_selection->'relationshipJobInputHash') <> 'string'
       OR v_selection->>'relationshipJobInputHash' !~ '^[a-f0-9]{64}$'
       OR v_selection->>'planId' NOT IN ('basic', 'standard')
       OR NOT public.analysis_v2_dag_bounded_integer(v_selection->'publicPopulationCount', 0, 1200)
       OR NOT public.analysis_v2_dag_bounded_integer(v_selection->'selectedCount', 0, 200) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
    END IF;

    v_revision := (p_manifest->>'revision')::INTEGER;
    v_result_hash := p_manifest->>'resultHash';
    v_detected := (p_manifest->>'detectedMutualCount')::INTEGER;
    v_public := (p_manifest->>'publicCount')::INTEGER;
    v_private := (p_manifest->>'privateCount')::INTEGER;
    v_detailed := (p_manifest->>'detailedSelectedPublicCount')::INTEGER;
    v_not_screened := (p_manifest->>'notScreenedPublicCount')::INTEGER;
    v_profile_batches := p_manifest->'profileBatches';
    v_private_batches := p_manifest->'privateNameBatches';
    v_selection_plan := v_selection->>'planId';
    v_population := (v_selection->>'publicPopulationCount')::INTEGER;
    v_selected := (v_selection->>'selectedCount')::INTEGER;
    v_population_cap := CASE WHEN v_selection_plan = 'basic' THEN 400 ELSE 800 END;
    v_detailed_cap := CASE WHEN v_selection_plan = 'basic' THEN 100 ELSE 200 END;

    IF v_public + v_private <> v_detected
       OR v_detected > v_population_cap
       OR v_population <> v_public
       OR v_selected <> v_detailed
       OR v_selected <> LEAST(v_population, v_detailed_cap)
       OR v_not_screened <> v_public - v_detailed
       OR pg_catalog.jsonb_array_length(v_profile_batches)
            <> (CASE WHEN v_detailed = 0 THEN 0 ELSE (v_detailed + 29) / 30 END)
       OR pg_catalog.jsonb_array_length(v_private_batches)
            <> (CASE WHEN v_private = 0 THEN 0 ELSE (v_private + 99) / 100 END)
       OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements(v_profile_batches) WITH ORDINALITY AS item(value, ordinal)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR NOT (item.value ?& ARRAY['batch', 'itemCount', 'inputHash'])
               OR item.value - ARRAY['batch', 'itemCount', 'inputHash']::TEXT[] <> '{}'::JSONB
               OR NOT public.analysis_v2_dag_bounded_integer(item.value->'batch', 0, 100000)
               OR NOT public.analysis_v2_dag_bounded_integer(item.value->'itemCount', 1, 30)
               OR pg_catalog.jsonb_typeof(item.value->'inputHash') <> 'string'
               OR item.value->>'inputHash' !~ '^[a-f0-9]{64}$'
               OR (item.value->>'batch')::INTEGER <> item.ordinal - 1
               OR (item.value->>'itemCount')::INTEGER <> LEAST(30, v_detailed - ((item.ordinal - 1) * 30))
       )
       OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements(v_private_batches) WITH ORDINALITY AS item(value, ordinal)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR NOT (item.value ?& ARRAY['batch', 'itemCount', 'inputHash'])
               OR item.value - ARRAY['batch', 'itemCount', 'inputHash']::TEXT[] <> '{}'::JSONB
               OR NOT public.analysis_v2_dag_bounded_integer(item.value->'batch', 0, 100000)
               OR NOT public.analysis_v2_dag_bounded_integer(item.value->'itemCount', 1, 100)
               OR pg_catalog.jsonb_typeof(item.value->'inputHash') <> 'string'
               OR item.value->>'inputHash' !~ '^[a-f0-9]{64}$'
               OR (item.value->>'batch')::INTEGER <> item.ordinal - 1
               OR (item.value->>'itemCount')::INTEGER <> LEAST(100, v_private - ((item.ordinal - 1) * 100))
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    SELECT scope.* INTO v_scope
    FROM public.analysis_v2_dag_scopes AS scope
    WHERE scope.request_id = p_request_id FOR SHARE;
    SELECT policy.* INTO v_policy
    FROM public.analysis_v2_provider_execution_policies AS policy
    WHERE policy.request_id = p_request_id FOR UPDATE;
    SELECT relationship_manifest.* INTO v_relationship_manifest
    FROM public.analysis_v2_relationship_manifests AS relationship_manifest
    WHERE relationship_manifest.request_id = p_request_id
      AND relationship_manifest.job_key = p_job_key
      AND relationship_manifest.result_hash = v_result_hash FOR UPDATE;
    SELECT routing_manifest.* INTO v_routing_manifest
    FROM public.analysis_v2_gender_routing_manifests AS routing_manifest
    WHERE routing_manifest.request_id = p_request_id
      AND routing_manifest.relationship_checkpoint_id = v_result_hash
      AND routing_manifest.policy_version = 'gender-routing-v1' FOR UPDATE;

    IF v_request.id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot IS DISTINCT FROM v_selection_plan
       OR v_scope.request_id IS NULL
       OR v_scope.plan_id IS DISTINCT FROM v_selection_plan
       OR v_job.request_id IS NULL
       OR v_job.track IS DISTINCT FROM 'relationships'
       OR v_job.kind IS DISTINCT FROM 'collection'
       OR v_job.batch IS NOT NULL
       OR v_job.input_hash IS DISTINCT FROM p_input_hash
       OR v_job.status IS DISTINCT FROM 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now
       OR v_policy.request_id IS NULL
       OR v_policy.mode IS DISTINCT FROM 'test_operation_split'
       OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR v_relationship_manifest.request_id IS NULL
       OR v_relationship_manifest.public_count IS DISTINCT FROM v_public
       OR v_selection->>'relationshipCheckpointId' IS DISTINCT FROM v_result_hash
       OR v_selection->>'relationshipJobInputHash' IS DISTINCT FROM p_input_hash
       OR v_routing_manifest.request_id IS NULL
       OR v_routing_manifest.status IS DISTINCT FROM 'complete'
       OR v_routing_manifest.relationship_job_key IS DISTINCT FROM p_job_key
       OR v_routing_manifest.relationship_job_input_hash IS DISTINCT FROM p_input_hash
       OR v_routing_manifest.plan_id IS DISTINCT FROM v_selection_plan
       OR v_routing_manifest.detailed_cap IS DISTINCT FROM v_detailed_cap
       OR v_routing_manifest.population_count IS DISTINCT FROM v_population
       OR v_routing_manifest.selected_count IS DISTINCT FROM v_selected THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.count(*)::INTEGER,
           pg_catalog.count(*) FILTER (WHERE candidate.selected)::INTEGER,
           COALESCE(pg_catalog.min(candidate.ordinal) FILTER (WHERE candidate.selected), 1),
           COALESCE(pg_catalog.max(candidate.ordinal) FILTER (WHERE candidate.selected), 0)
    INTO v_all_candidates, v_selected_candidates, v_min_ordinal, v_max_ordinal
    FROM public.analysis_v2_gender_routing_candidates AS candidate
    WHERE candidate.request_id = p_request_id
      AND candidate.relationship_checkpoint_id = v_result_hash
      AND candidate.policy_version = 'gender-routing-v1';
    IF v_all_candidates IS DISTINCT FROM v_population
       OR v_selected_candidates IS DISTINCT FROM v_selected
       OR v_min_ordinal <> 1
       OR v_max_ordinal <> v_selected THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT stage.* INTO v_stage
    FROM public.analysis_v2_dag_stage_manifests AS stage
    WHERE stage.request_id = p_request_id AND stage.stage_kind = 'relationships' FOR UPDATE;
    IF FOUND THEN
        IF v_stage.producer_job_key <> p_job_key
           OR v_stage.producer_input_hash <> p_input_hash
           OR v_stage.revision <> v_revision
           OR v_stage.result_hash <> v_result_hash
           OR v_stage.detected_mutual_count <> v_detected
           OR v_stage.public_count <> v_public
           OR v_stage.private_count <> v_private
           OR v_stage.detailed_selected_public_count <> v_detailed
           OR v_stage.not_screened_public_count <> v_not_screened
           OR v_stage.relationship_selection_policy_version <> 'gender-routing-v1'
           OR v_stage.relationship_selection_checkpoint_id <> v_result_hash
           OR v_stage.relationship_selection_job_input_hash <> p_input_hash
           OR v_stage.relationship_selection_plan_id <> v_selection_plan
           OR v_stage.relationship_selection_public_population_count <> v_population
           OR v_stage.relationship_selection_selected_count <> v_selected THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_CONFLICT', ERRCODE = 'P0001';
        END IF;
    ELSE
        INSERT INTO public.analysis_v2_dag_stage_manifests (
            request_id, stage_kind, producer_job_key, producer_input_hash, revision, result_hash,
            detected_mutual_count, public_count, private_count, detailed_selected_public_count,
            not_screened_public_count, relationship_selection_policy_version,
            relationship_selection_checkpoint_id, relationship_selection_job_input_hash,
            relationship_selection_plan_id, relationship_selection_public_population_count,
            relationship_selection_selected_count
        ) VALUES (
            p_request_id, 'relationships', p_job_key, p_input_hash, v_revision, v_result_hash,
            v_detected, v_public, v_private, v_detailed, v_not_screened, 'gender-routing-v1',
            v_result_hash, p_input_hash, v_selection_plan, v_population, v_selected
        );
        INSERT INTO public.analysis_v2_dag_batch_topology (
            request_id, topology_kind, batch, item_count, input_hash,
            producer_job_key, producer_input_hash
        )
        SELECT p_request_id, 'profile', (item.value->>'batch')::INTEGER,
               (item.value->>'itemCount')::INTEGER, item.value->>'inputHash', p_job_key, p_input_hash
        FROM pg_catalog.jsonb_array_elements(v_profile_batches) AS item(value);
        INSERT INTO public.analysis_v2_dag_batch_topology (
            request_id, topology_kind, batch, item_count, input_hash,
            producer_job_key, producer_input_hash
        )
        SELECT p_request_id, 'private_name', (item.value->>'batch')::INTEGER,
               (item.value->>'itemCount')::INTEGER, item.value->>'inputHash', p_job_key, p_input_hash
        FROM pg_catalog.jsonb_array_elements(v_private_batches) AS item(value);
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.analysis_v2_dag_batch_topology AS topology
        WHERE topology.request_id = p_request_id
          AND (topology.producer_job_key <> p_job_key OR topology.producer_input_hash <> p_input_hash)
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'batch', topology.batch, 'itemCount', topology.item_count, 'inputHash', topology.input_hash
    ) ORDER BY topology.batch), '[]'::JSONB)
    INTO v_existing_batches
    FROM public.analysis_v2_dag_batch_topology AS topology
    WHERE topology.request_id = p_request_id AND topology.topology_kind = 'profile';
    IF v_existing_batches <> v_profile_batches THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'batch', topology.batch, 'itemCount', topology.item_count, 'inputHash', topology.input_hash
    ) ORDER BY topology.batch), '[]'::JSONB)
    INTO v_existing_batches
    FROM public.analysis_v2_dag_batch_topology AS topology
    WHERE topology.request_id = p_request_id AND topology.topology_kind = 'private_name';
    IF v_existing_batches <> v_private_batches THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    RETURN public.analysis_v2_dag_state_json(p_request_id);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_dag_manifest_legacy(uuid, text, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_dag_manifest_legacy(p_request_id uuid, p_job_key text, p_input_hash text, p_claim_token uuid, p_manifest_kind text, p_manifest jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_scope public.analysis_v2_dag_scopes%ROWTYPE;
    v_stage public.analysis_v2_dag_stage_manifests%ROWTYPE;
    v_batch_result public.analysis_v2_dag_batch_results%ROWTYPE;
    v_stage_exists BOOLEAN := FALSE;
    v_result_kind TEXT;
    v_topology_kind TEXT;
    v_expected_job_key TEXT;
    v_revision INTEGER;
    v_result_hash TEXT;
    v_batch INTEGER;
    v_item_count INTEGER;
    v_detected INTEGER;
    v_public INTEGER;
    v_private INTEGER;
    v_detailed INTEGER;
    v_not_screened INTEGER;
    v_interactor INTEGER;
    v_verified INTEGER;
    v_shortlist INTEGER;
    v_shortlist_hash TEXT;
    v_featured INTEGER;
    v_narrative INTEGER;
    v_narrative_batch_hash TEXT;
    v_profile_batches JSONB;
    v_private_batches JSONB;
    v_existing_batches JSONB;
    v_profile_limit INTEGER;
    v_relationship public.analysis_v2_dag_stage_manifests%ROWTYPE;
    v_dependency public.analysis_v2_dag_stage_manifests%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_claim_token IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[a-f0-9]{64}$'
       OR p_manifest_kind IS NULL
       OR p_manifest_kind NOT IN (
            'relationships', 'target_evidence', 'profile_fetch_batch',
            'profile_ai_batch', 'private_name_batch', 'primary_join',
            'screening', 'reverse_likes', 'partner_safety', 'final_score', 'narrative'
       )
       OR p_manifest IS NULL
       OR pg_catalog.jsonb_typeof(p_manifest) <> 'object'
       OR pg_catalog.octet_length(p_manifest::TEXT) > 65536 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND OR v_request.status NOT IN ('pending', 'processing') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_job.input_hash <> p_input_hash
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT scope.*
    INTO v_scope
    FROM public.analysis_v2_dag_scopes AS scope
    WHERE scope.request_id = p_request_id
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_SCOPE_MISSING', ERRCODE = 'P0001';
    END IF;

    IF NOT (p_manifest ?& ARRAY['revision', 'resultHash'])
       OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'revision', 1, 1000000)
       OR pg_catalog.jsonb_typeof(p_manifest->'resultHash') <> 'string'
       OR p_manifest->>'resultHash' !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
    END IF;
    v_revision := (p_manifest->>'revision')::INTEGER;
    v_result_hash := p_manifest->>'resultHash';

    IF p_manifest_kind IN ('profile_fetch_batch', 'profile_ai_batch', 'private_name_batch') THEN
        IF NOT (p_manifest ?& ARRAY[
                'batch', 'itemCount', 'producerInputHash', 'revision', 'resultHash'
            ])
           OR p_manifest - ARRAY[
                'batch', 'itemCount', 'producerInputHash', 'revision', 'resultHash'
            ]::TEXT[] <> '{}'::JSONB
           OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'batch', 0, 100000)
           OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'itemCount', 1, 100)
           OR pg_catalog.jsonb_typeof(p_manifest->'producerInputHash') <> 'string'
           OR p_manifest->>'producerInputHash' <> p_input_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;

        v_batch := (p_manifest->>'batch')::INTEGER;
        v_item_count := (p_manifest->>'itemCount')::INTEGER;
        v_result_kind := CASE p_manifest_kind
            WHEN 'profile_fetch_batch' THEN 'profile_fetch'
            WHEN 'profile_ai_batch' THEN 'profile_ai'
            ELSE 'private_name'
        END;
        v_topology_kind := CASE
            WHEN v_result_kind = 'private_name' THEN 'private_name'
            ELSE 'profile'
        END;
        v_expected_job_key := CASE v_result_kind
            WHEN 'profile_fetch' THEN 'track:profiles:batch:' || v_batch::TEXT
            WHEN 'profile_ai' THEN 'track:profile-ai:batch:' || v_batch::TEXT
            ELSE 'track:private-names:batch:' || v_batch::TEXT
        END;
        IF p_job_key <> v_expected_job_key
           OR NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_dag_batch_topology AS topology
                WHERE topology.request_id = p_request_id
                  AND topology.topology_kind = v_topology_kind
                  AND topology.batch = v_batch
                  AND topology.item_count = v_item_count
           )
           OR (
                v_result_kind = 'profile_ai'
                AND NOT EXISTS (
                    SELECT 1
                    FROM public.analysis_v2_dag_batch_results AS result
                    WHERE result.request_id = p_request_id
                      AND result.result_kind = 'profile_fetch'
                      AND result.batch = v_batch
                      AND result.item_count = v_item_count
                )
           ) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;

        SELECT result.*
        INTO v_batch_result
        FROM public.analysis_v2_dag_batch_results AS result
        WHERE result.request_id = p_request_id
          AND result.result_kind = v_result_kind
          AND result.batch = v_batch
        FOR UPDATE;
        IF FOUND THEN
            IF v_batch_result.item_count <> v_item_count
               OR v_batch_result.producer_job_key <> p_job_key
               OR v_batch_result.producer_input_hash <> p_input_hash
               OR v_batch_result.revision <> v_revision
               OR v_batch_result.result_hash <> v_result_hash THEN
                RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_CONFLICT', ERRCODE = 'P0001';
            END IF;
        ELSE
            INSERT INTO public.analysis_v2_dag_batch_results (
                request_id,
                result_kind,
                batch,
                item_count,
                producer_job_key,
                producer_input_hash,
                revision,
                result_hash
            ) VALUES (
                p_request_id,
                v_result_kind,
                v_batch,
                v_item_count,
                p_job_key,
                p_input_hash,
                v_revision,
                v_result_hash
            );
        END IF;
        RETURN public.analysis_v2_dag_state_json(p_request_id);
    END IF;

    v_expected_job_key := CASE p_manifest_kind
        WHEN 'relationships' THEN 'track:relationships:collect'
        WHEN 'target_evidence' THEN 'track:target-evidence:collect'
        WHEN 'primary_join' THEN 'coordinator:join:primary-evidence'
        WHEN 'screening' THEN 'coordinator:candidate-screening'
        WHEN 'reverse_likes' THEN 'track:reverse-likes:collect'
        WHEN 'partner_safety' THEN 'track:partner-safety:batch:0'
        WHEN 'final_score' THEN 'coordinator:join:final-score'
        WHEN 'narrative' THEN 'track:narratives:batch:0'
    END;
    IF p_job_key <> v_expected_job_key THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
    END IF;

    IF p_manifest_kind = 'relationships' THEN
        IF NOT (p_manifest ?& ARRAY[
                'revision', 'resultHash', 'detectedMutualCount', 'publicCount',
                'privateCount', 'detailedSelectedPublicCount', 'notScreenedPublicCount',
                'profileBatches', 'privateNameBatches'
            ])
           OR p_manifest - ARRAY[
                'revision', 'resultHash', 'detectedMutualCount', 'publicCount',
                'privateCount', 'detailedSelectedPublicCount', 'notScreenedPublicCount',
                'profileBatches', 'privateNameBatches'
            ]::TEXT[] <> '{}'::JSONB
           OR NOT public.analysis_v2_dag_bounded_integer(
                p_manifest->'detectedMutualCount', 0, 1200
           )
           OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'publicCount', 0, 1200)
           OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'privateCount', 0, 1200)
           OR NOT public.analysis_v2_dag_bounded_integer(
                p_manifest->'detailedSelectedPublicCount', 0, 900
           )
           OR NOT public.analysis_v2_dag_bounded_integer(
                p_manifest->'notScreenedPublicCount', 0, 1200
           )
           OR pg_catalog.jsonb_typeof(p_manifest->'profileBatches') <> 'array'
           OR pg_catalog.jsonb_typeof(p_manifest->'privateNameBatches') <> 'array' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
        v_detected := (p_manifest->>'detectedMutualCount')::INTEGER;
        v_public := (p_manifest->>'publicCount')::INTEGER;
        v_private := (p_manifest->>'privateCount')::INTEGER;
        v_detailed := (p_manifest->>'detailedSelectedPublicCount')::INTEGER;
        v_not_screened := (p_manifest->>'notScreenedPublicCount')::INTEGER;
        v_profile_batches := p_manifest->'profileBatches';
        v_private_batches := p_manifest->'privateNameBatches';
        v_profile_limit := CASE v_scope.plan_id
            WHEN 'basic' THEN 300 WHEN 'standard' THEN 600 ELSE 900
        END;
        IF v_detected > (CASE v_scope.plan_id
                WHEN 'basic' THEN 400 WHEN 'standard' THEN 800 ELSE 1200
            END)
           OR v_public + v_private <> v_detected
           OR v_detailed <> LEAST(v_public, v_profile_limit)
           OR v_not_screened <> v_public - v_detailed
           OR pg_catalog.jsonb_array_length(v_profile_batches)
                <> (CASE WHEN v_detailed = 0 THEN 0 ELSE (v_detailed + 29) / 30 END)
           OR pg_catalog.jsonb_array_length(v_private_batches)
                <> (CASE WHEN v_private = 0 THEN 0 ELSE (v_private + 99) / 100 END) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;

        IF EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(v_profile_batches) AS item(value)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR NOT (item.value ?& ARRAY['batch', 'itemCount', 'inputHash'])
               OR item.value - ARRAY['batch', 'itemCount', 'inputHash']::TEXT[] <> '{}'::JSONB
               OR NOT public.analysis_v2_dag_bounded_integer(item.value->'batch', 0, 100000)
               OR NOT public.analysis_v2_dag_bounded_integer(item.value->'itemCount', 1, 30)
               OR pg_catalog.jsonb_typeof(item.value->'inputHash') <> 'string'
               OR item.value->>'inputHash' !~ '^[a-f0-9]{64}$'
        ) OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(v_private_batches) AS item(value)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR NOT (item.value ?& ARRAY['batch', 'itemCount', 'inputHash'])
               OR item.value - ARRAY['batch', 'itemCount', 'inputHash']::TEXT[] <> '{}'::JSONB
               OR NOT public.analysis_v2_dag_bounded_integer(item.value->'batch', 0, 100000)
               OR NOT public.analysis_v2_dag_bounded_integer(item.value->'itemCount', 1, 100)
               OR pg_catalog.jsonb_typeof(item.value->'inputHash') <> 'string'
               OR item.value->>'inputHash' !~ '^[a-f0-9]{64}$'
        ) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
        IF EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(v_profile_batches) WITH ORDINALITY AS item(value, ordinal)
            WHERE (item.value->>'batch')::INTEGER <> item.ordinal - 1
               OR (item.value->>'itemCount')::INTEGER
                    <> LEAST(30, v_detailed - ((item.ordinal - 1) * 30))
        ) OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(v_private_batches) WITH ORDINALITY AS item(value, ordinal)
            WHERE (item.value->>'batch')::INTEGER <> item.ordinal - 1
               OR (item.value->>'itemCount')::INTEGER
                    <> LEAST(100, v_private - ((item.ordinal - 1) * 100))
        ) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
    ELSIF p_manifest_kind = 'target_evidence' THEN
        IF NOT (p_manifest ?& ARRAY['revision', 'resultHash', 'interactorCount'])
           OR p_manifest - ARRAY['revision', 'resultHash', 'interactorCount']::TEXT[] <> '{}'::JSONB
           OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'interactorCount', 0, 690) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
        v_interactor := (p_manifest->>'interactorCount')::INTEGER;
    ELSIF p_manifest_kind = 'primary_join' THEN
        IF NOT (p_manifest ?& ARRAY['revision', 'resultHash', 'verifiedFemaleCount'])
           OR p_manifest - ARRAY['revision', 'resultHash', 'verifiedFemaleCount']::TEXT[] <> '{}'::JSONB
           OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'verifiedFemaleCount', 0, 900) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
        v_verified := (p_manifest->>'verifiedFemaleCount')::INTEGER;
        SELECT stage.* INTO v_relationship
        FROM public.analysis_v2_dag_stage_manifests AS stage
        WHERE stage.request_id = p_request_id AND stage.stage_kind = 'relationships';
        IF NOT FOUND
           OR v_verified > v_relationship.detailed_selected_public_count
           OR NOT EXISTS (
                SELECT 1 FROM public.analysis_v2_dag_stage_manifests AS stage
                WHERE stage.request_id = p_request_id AND stage.stage_kind = 'target_evidence'
           )
           OR EXISTS (
                SELECT 1 FROM public.analysis_v2_dag_batch_topology AS topology
                WHERE topology.request_id = p_request_id AND topology.topology_kind = 'profile'
                  AND (
                    NOT EXISTS (
                        SELECT 1 FROM public.analysis_v2_dag_batch_results AS result
                        WHERE result.request_id = p_request_id
                          AND result.result_kind = 'profile_fetch'
                          AND result.batch = topology.batch
                          AND result.item_count = topology.item_count
                    )
                    OR NOT EXISTS (
                        SELECT 1 FROM public.analysis_v2_dag_batch_results AS result
                        WHERE result.request_id = p_request_id
                          AND result.result_kind = 'profile_ai'
                          AND result.batch = topology.batch
                          AND result.item_count = topology.item_count
                    )
                  )
           ) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
    ELSIF p_manifest_kind = 'screening' THEN
        IF NOT (p_manifest ?& ARRAY[
                'revision', 'resultHash', 'verifiedFemaleCount', 'shortlistCount', 'shortlistHash'
            ])
           OR p_manifest - ARRAY[
                'revision', 'resultHash', 'verifiedFemaleCount', 'shortlistCount', 'shortlistHash'
            ]::TEXT[] <> '{}'::JSONB
           OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'verifiedFemaleCount', 0, 900)
           OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'shortlistCount', 0, 10)
           OR pg_catalog.jsonb_typeof(p_manifest->'shortlistHash') <> 'string'
           OR p_manifest->>'shortlistHash' !~ '^[a-f0-9]{64}$' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
        v_verified := (p_manifest->>'verifiedFemaleCount')::INTEGER;
        v_shortlist := (p_manifest->>'shortlistCount')::INTEGER;
        v_shortlist_hash := p_manifest->>'shortlistHash';
        SELECT stage.* INTO v_dependency
        FROM public.analysis_v2_dag_stage_manifests AS stage
        WHERE stage.request_id = p_request_id AND stage.stage_kind = 'primary_join';
        IF NOT FOUND
           OR v_verified <> v_dependency.verified_female_count
           OR v_shortlist <> LEAST(v_verified, 10) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
    ELSIF p_manifest_kind IN ('reverse_likes', 'partner_safety') THEN
        IF NOT (p_manifest ?& ARRAY['revision', 'resultHash', 'shortlistCount'])
           OR p_manifest - ARRAY['revision', 'resultHash', 'shortlistCount']::TEXT[] <> '{}'::JSONB
           OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'shortlistCount', 0, 10) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
        v_shortlist := (p_manifest->>'shortlistCount')::INTEGER;
        SELECT stage.* INTO v_dependency
        FROM public.analysis_v2_dag_stage_manifests AS stage
        WHERE stage.request_id = p_request_id AND stage.stage_kind = 'screening';
        IF NOT FOUND OR v_shortlist <> v_dependency.shortlist_count THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
    ELSIF p_manifest_kind = 'final_score' THEN
        IF NOT (p_manifest ?& ARRAY[
                'revision', 'resultHash', 'featuredHighRiskCount',
                'narrativeCount', 'narrativeBatchHash'
            ])
           OR p_manifest - ARRAY[
                'revision', 'resultHash', 'featuredHighRiskCount',
                'narrativeCount', 'narrativeBatchHash'
            ]::TEXT[] <> '{}'::JSONB
           OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'featuredHighRiskCount', 0, 3)
           OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'narrativeCount', 0, 3)
           OR pg_catalog.jsonb_typeof(p_manifest->'narrativeBatchHash') <> 'string'
           OR p_manifest->>'narrativeBatchHash' !~ '^[a-f0-9]{64}$' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
        v_featured := (p_manifest->>'featuredHighRiskCount')::INTEGER;
        v_narrative := (p_manifest->>'narrativeCount')::INTEGER;
        v_narrative_batch_hash := p_manifest->>'narrativeBatchHash';
        SELECT stage.* INTO v_dependency
        FROM public.analysis_v2_dag_stage_manifests AS stage
        WHERE stage.request_id = p_request_id AND stage.stage_kind = 'screening';
        IF NOT FOUND
           OR v_featured > LEAST(v_dependency.verified_female_count, 3)
           OR v_narrative <> v_featured
           OR NOT EXISTS (
                SELECT 1 FROM public.analysis_v2_dag_stage_manifests AS stage
                WHERE stage.request_id = p_request_id AND stage.stage_kind = 'reverse_likes'
           )
           OR NOT EXISTS (
                SELECT 1 FROM public.analysis_v2_dag_stage_manifests AS stage
                WHERE stage.request_id = p_request_id AND stage.stage_kind = 'partner_safety'
           ) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
    ELSE
        IF NOT (p_manifest ?& ARRAY['revision', 'resultHash', 'narrativeCount'])
           OR p_manifest - ARRAY['revision', 'resultHash', 'narrativeCount']::TEXT[] <> '{}'::JSONB
           OR NOT public.analysis_v2_dag_bounded_integer(p_manifest->'narrativeCount', 0, 3) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
        v_narrative := (p_manifest->>'narrativeCount')::INTEGER;
        SELECT stage.* INTO v_dependency
        FROM public.analysis_v2_dag_stage_manifests AS stage
        WHERE stage.request_id = p_request_id AND stage.stage_kind = 'final_score';
        IF NOT FOUND OR v_narrative <> v_dependency.narrative_count THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
        END IF;
    END IF;

    SELECT stage.*
    INTO v_stage
    FROM public.analysis_v2_dag_stage_manifests AS stage
    WHERE stage.request_id = p_request_id
      AND stage.stage_kind = p_manifest_kind
    FOR UPDATE;
    v_stage_exists := FOUND;
    IF v_stage_exists THEN
        IF v_stage.producer_job_key <> p_job_key
           OR v_stage.producer_input_hash <> p_input_hash
           OR v_stage.revision <> v_revision
           OR v_stage.result_hash <> v_result_hash
           OR v_stage.detected_mutual_count IS DISTINCT FROM v_detected
           OR v_stage.public_count IS DISTINCT FROM v_public
           OR v_stage.private_count IS DISTINCT FROM v_private
           OR v_stage.detailed_selected_public_count IS DISTINCT FROM v_detailed
           OR v_stage.not_screened_public_count IS DISTINCT FROM v_not_screened
           OR v_stage.interactor_count IS DISTINCT FROM v_interactor
           OR v_stage.verified_female_count IS DISTINCT FROM v_verified
           OR v_stage.shortlist_count IS DISTINCT FROM v_shortlist
           OR v_stage.shortlist_hash IS DISTINCT FROM v_shortlist_hash
           OR v_stage.featured_high_risk_count IS DISTINCT FROM v_featured
           OR v_stage.narrative_count IS DISTINCT FROM v_narrative
           OR v_stage.narrative_batch_hash IS DISTINCT FROM v_narrative_batch_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_CONFLICT', ERRCODE = 'P0001';
        END IF;
    ELSE
        INSERT INTO public.analysis_v2_dag_stage_manifests (
            request_id,
            stage_kind,
            producer_job_key,
            producer_input_hash,
            revision,
            result_hash,
            detected_mutual_count,
            public_count,
            private_count,
            detailed_selected_public_count,
            not_screened_public_count,
            interactor_count,
            verified_female_count,
            shortlist_count,
            shortlist_hash,
            featured_high_risk_count,
            narrative_count,
            narrative_batch_hash
        ) VALUES (
            p_request_id,
            p_manifest_kind,
            p_job_key,
            p_input_hash,
            v_revision,
            v_result_hash,
            v_detected,
            v_public,
            v_private,
            v_detailed,
            v_not_screened,
            v_interactor,
            v_verified,
            v_shortlist,
            v_shortlist_hash,
            v_featured,
            v_narrative,
            v_narrative_batch_hash
        );
    END IF;

    IF p_manifest_kind = 'relationships' THEN
        IF NOT v_stage_exists THEN
            INSERT INTO public.analysis_v2_dag_batch_topology (
                request_id,
                topology_kind,
                batch,
                item_count,
                input_hash,
                producer_job_key,
                producer_input_hash
            )
            SELECT
                p_request_id,
                'profile',
                (item.value->>'batch')::INTEGER,
                (item.value->>'itemCount')::INTEGER,
                item.value->>'inputHash',
                p_job_key,
                p_input_hash
            FROM pg_catalog.jsonb_array_elements(v_profile_batches) AS item(value);

            INSERT INTO public.analysis_v2_dag_batch_topology (
                request_id,
                topology_kind,
                batch,
                item_count,
                input_hash,
                producer_job_key,
                producer_input_hash
            )
            SELECT
                p_request_id,
                'private_name',
                (item.value->>'batch')::INTEGER,
                (item.value->>'itemCount')::INTEGER,
                item.value->>'inputHash',
                p_job_key,
                p_input_hash
            FROM pg_catalog.jsonb_array_elements(v_private_batches) AS item(value);
        END IF;

        IF EXISTS (
            SELECT 1
            FROM public.analysis_v2_dag_batch_topology AS topology
            WHERE topology.request_id = p_request_id
              AND (
                topology.producer_job_key <> p_job_key
                OR topology.producer_input_hash <> p_input_hash
              )
        ) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_CONFLICT', ERRCODE = 'P0001';
        END IF;

        SELECT COALESCE(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'batch', topology.batch,
                'itemCount', topology.item_count,
                'inputHash', topology.input_hash
            ) ORDER BY topology.batch
        ), '[]'::JSONB)
        INTO v_existing_batches
        FROM public.analysis_v2_dag_batch_topology AS topology
        WHERE topology.request_id = p_request_id AND topology.topology_kind = 'profile';
        IF v_existing_batches <> v_profile_batches THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_CONFLICT', ERRCODE = 'P0001';
        END IF;

        SELECT COALESCE(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'batch', topology.batch,
                'itemCount', topology.item_count,
                'inputHash', topology.input_hash
            ) ORDER BY topology.batch
        ), '[]'::JSONB)
        INTO v_existing_batches
        FROM public.analysis_v2_dag_batch_topology AS topology
        WHERE topology.request_id = p_request_id AND topology.topology_kind = 'private_name';
        IF v_existing_batches <> v_private_batches THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_CONFLICT', ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN public.analysis_v2_dag_state_json(p_request_id);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_fresh_admission_provider_run_started(uuid, integer, uuid, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_fresh_admission_provider_run_started(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid, p_input_hash text, p_credential_slot text, p_max_charge_usd numeric, p_run_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_operation_key TEXT;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_claim_token IS NULL
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS DISTINCT FROM 0.002600000000
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;
    v_operation_key := 'target-profile-fresh-admission:g' || p_admission_generation::TEXT;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status IS DISTINCT FROM 'ready'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.expires_at <= v_now
       OR v_preflight.admission_generation IS DISTINCT FROM p_admission_generation
       OR v_preflight.admission_status IS DISTINCT FROM 'processing'
       OR v_preflight.admission_claim_token IS DISTINCT FROM p_claim_token
       OR v_preflight.admission_lease_expires_at IS NULL
       OR v_preflight.admission_lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    PERFORM public.adopt_legacy_fresh_admission_provider_run(
        p_preflight_id, v_operation_key, v_preflight.admission_requested_at
    );

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = v_operation_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.input_hash IS DISTINCT FROM p_input_hash
       OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM p_max_charge_usd THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.status <> 'starting' THEN
        IF v_run.run_id IS DISTINCT FROM p_run_id THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_RUN_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_preflight_provider_run_json(v_run);
    END IF;

    UPDATE public.analysis_preflight_provider_runs AS provider_run
    SET status = 'running',
        run_id = p_run_id,
        run_started_at = v_now,
        updated_at = v_now
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = v_operation_key
    RETURNING provider_run.* INTO v_run;
    RETURN public.analysis_preflight_provider_run_json(v_run);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_fresh_admission_provider_run_terminal(uuid, integer, uuid, text, text, numeric, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_fresh_admission_provider_run_terminal(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid, p_input_hash text, p_credential_slot text, p_max_charge_usd numeric, p_run_id text, p_status text, p_actual_usage_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_operation_key TEXT;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_claim_token IS NULL
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS DISTINCT FROM 0.002600000000
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_status IS NULL
       OR p_status NOT IN ('succeeded', 'failed', 'aborted', 'timed_out')
       OR (
            p_actual_usage_usd IS NOT NULL
            AND (
                p_actual_usage_usd NOT BETWEEN 0 AND 100000
                OR p_actual_usage_usd <> pg_catalog.round(p_actual_usage_usd, 12)
                OR p_actual_usage_usd > p_max_charge_usd + 0.000000001
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;
    v_operation_key := 'target-profile-fresh-admission:g' || p_admission_generation::TEXT;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status IS DISTINCT FROM 'ready'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.expires_at <= v_now
       OR v_preflight.admission_generation IS DISTINCT FROM p_admission_generation
       OR v_preflight.admission_status IS DISTINCT FROM 'processing'
       OR v_preflight.admission_claim_token IS DISTINCT FROM p_claim_token
       OR v_preflight.admission_lease_expires_at IS NULL
       OR v_preflight.admission_lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    PERFORM public.adopt_legacy_fresh_admission_provider_run(
        p_preflight_id, v_operation_key, v_preflight.admission_requested_at
    );

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = v_operation_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.input_hash IS DISTINCT FROM p_input_hash
       OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM p_max_charge_usd THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.run_id IS DISTINCT FROM p_run_id OR v_run.status = 'starting' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_RUN_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.status IN ('succeeded', 'failed', 'aborted', 'timed_out') THEN
        IF v_run.status IS DISTINCT FROM p_status
           OR (
                p_actual_usage_usd IS NOT NULL
                AND v_run.actual_usage_usd IS NOT NULL
                AND v_run.actual_usage_usd IS DISTINCT FROM p_actual_usage_usd
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_TERMINAL_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        IF p_actual_usage_usd IS NOT NULL AND v_run.actual_usage_usd IS NULL THEN
            UPDATE public.analysis_preflight_provider_runs AS provider_run
            SET actual_usage_usd = p_actual_usage_usd,
                usage_reconciled_at = v_now,
                updated_at = v_now
            WHERE provider_run.preflight_id = p_preflight_id
              AND provider_run.operation_key = v_operation_key
            RETURNING provider_run.* INTO v_run;
        END IF;
        IF v_run.actual_usage_usd IS NOT NULL THEN
            PERFORM public.record_analysis_preflight_provider_cost_event(
                v_run.run_id,
                v_run.logical_provider,
                v_run.actor_id,
                v_run.credential_slot,
                v_run.status,
                v_run.max_charge_usd,
                v_run.actual_usage_usd,
                (v_run.terminalized_at AT TIME ZONE 'UTC')::DATE
            );
        END IF;
        RETURN public.analysis_preflight_provider_run_json(v_run);
    END IF;
    IF v_run.status <> 'running' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_STATE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflight_provider_runs AS provider_run
    SET status = p_status,
        actual_usage_usd = p_actual_usage_usd,
        terminalized_at = v_now,
        usage_reconciled_at = CASE
            WHEN p_actual_usage_usd IS NULL THEN NULL
            ELSE v_now
        END,
        updated_at = v_now
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = v_operation_key
    RETURNING provider_run.* INTO v_run;
    IF v_run.actual_usage_usd IS NOT NULL THEN
        PERFORM public.record_analysis_preflight_provider_cost_event(
            v_run.run_id,
            v_run.logical_provider,
            v_run.actor_id,
            v_run.credential_slot,
            v_run.status,
            v_run.max_charge_usd,
            v_run.actual_usage_usd,
            (v_run.terminalized_at AT TIME ZONE 'UTC')::DATE
        );
    END IF;
    RETURN public.analysis_preflight_provider_run_json(v_run);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_narratives(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_narratives(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_rows JSONB;
    v_count INTEGER;
    v_hash TEXT;
    v_existing public.analysis_v2_narrative_manifests%ROWTYPE;
BEGIN
    IF p_rows IS NULL OR pg_catalog.jsonb_typeof(p_rows) <> 'array'
       OR pg_catalog.jsonb_array_length(p_rows) > 3
       OR pg_catalog.octet_length(p_rows::TEXT) > 65536
       OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR NOT (item.value ?& ARRAY[
                    'candidateId', 'lines', 'source', 'operationKey', 'aiResultHash'
               ])
               OR item.value - ARRAY[
                    'candidateId', 'lines', 'source', 'operationKey', 'aiResultHash'
               ] <> '{}'::JSONB
               OR item.value->>'candidateId' !~ '^[A-Za-z0-9._:-]{1,128}$'
               OR pg_catalog.jsonb_typeof(item.value->'lines') <> 'array'
               OR pg_catalog.jsonb_array_length(item.value->'lines') <> 2
               OR NOT public.analysis_v2_result_valid_public_copy(item.value->'lines'->>0, 180)
               OR NOT public.analysis_v2_result_valid_public_copy(item.value->'lines'->>1, 180)
               OR item.value->>'source' NOT IN ('checkpoint', 'safe_fallback')
               OR item.value->>'operationKey' !~ '^high-risk-narrative:[a-f0-9]{64}$'
               OR (
                    item.value->>'source' = 'checkpoint'
                    AND (
                        item.value->'aiResultHash' = 'null'::JSONB
                        OR item.value->>'aiResultHash' !~ '^[a-f0-9]{64}$'
                    )
               )
               OR (
                    item.value->>'source' = 'safe_fallback'
                    AND item.value->'aiResultHash' <> 'null'::JSONB
               )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;
    v_job := public.analysis_v2_assert_result_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    IF v_job.job_key <> 'track:narratives:batch:0'
       OR v_job.track <> 'narratives' OR v_job.kind <> 'ai' OR v_job.batch <> 0 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT COALESCE(
        pg_catalog.jsonb_agg(item.value ORDER BY item.value->>'candidateId'),
        '[]'::JSONB
    ) INTO v_rows FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value);
    v_count := pg_catalog.jsonb_array_length(v_rows);
    IF v_count <> (
        SELECT pg_catalog.count(*)
        FROM public.analysis_v2_candidate_score_rows AS score
        WHERE score.request_id = p_request_id
          AND score.risk_band = 'high_risk' AND score.featured_rank BETWEEN 1 AND 3
    ) OR (
        SELECT pg_catalog.count(DISTINCT item.value->>'candidateId')
        FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
    ) <> v_count OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
        WHERE NOT EXISTS (
                SELECT 1 FROM public.analysis_v2_candidate_score_rows AS score
                WHERE score.request_id = p_request_id
                  AND score.candidate_id = item.value->>'candidateId'
                  AND score.risk_band = 'high_risk' AND score.featured_rank BETWEEN 1 AND 3
              )
           OR (
                item.value->>'source' = 'checkpoint'
                AND NOT EXISTS (
                    SELECT 1 FROM public.analysis_v2_ai_result_checkpoints AS ai_result
                    WHERE ai_result.request_id = p_request_id
                      AND ai_result.job_key = p_job_key
                      AND ai_result.operation_key = item.value->>'operationKey'
                      AND ai_result.stage = 'highRiskNarrative'
                      AND ai_result.result_hash = item.value->>'aiResultHash'
                )
              )
           OR (
                item.value->>'source' = 'safe_fallback'
                AND NOT EXISTS (
                    SELECT 1 FROM public.analysis_v2_ai_attempts AS ai_attempt
                    WHERE ai_attempt.request_id = p_request_id
                      AND ai_attempt.job_key = p_job_key
                      AND ai_attempt.operation_key = item.value->>'operationKey'
                      AND ai_attempt.stage = 'highRiskNarrative'
                      AND public.analysis_v2_ai_fallback_evidence_matches(
                      p_request_id,
                      p_job_key,
                      item.value->>'operationKey',
                      'highRiskNarrative'
                  )
                )
              )
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    v_hash := public.analysis_v2_result_staging_hash('narratives_v2', NULL, v_rows);
    SELECT manifest.* INTO v_existing
    FROM public.analysis_v2_narrative_manifests AS manifest
    WHERE manifest.request_id = p_request_id FOR UPDATE;
    IF FOUND THEN
        IF v_existing.producer_job_key <> p_job_key
           OR v_existing.producer_input_hash <> p_job_input_hash
           OR v_existing.producer_claim_token <> p_claim_token
           OR v_existing.item_count <> v_count OR v_existing.result_hash <> v_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_result_checkpoint_json(
            p_request_id, p_job_key, NULL, v_count, v_count, v_hash
        );
    END IF;
    INSERT INTO public.analysis_v2_narrative_manifests (
        request_id, producer_job_key, producer_input_hash, producer_claim_token,
        item_count, result_hash
    ) VALUES (
        p_request_id, p_job_key, p_job_input_hash, p_claim_token, v_count, v_hash
    );
    INSERT INTO public.analysis_v2_narrative_rows (
        request_id, candidate_id, line_one, line_two, source, operation_key, ai_result_hash
    )
    SELECT p_request_id, item.value->>'candidateId', item.value->'lines'->>0,
        item.value->'lines'->>1, item.value->>'source', item.value->>'operationKey',
        NULLIF(item.value->>'aiResultHash', '')
    FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value);
    RETURN public.analysis_v2_result_checkpoint_json(
        p_request_id, p_job_key, NULL, v_count, v_count, v_hash
    );
END;
$_$;


--
-- Name: checkpoint_analysis_v2_partner_safety(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_partner_safety(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_rows JSONB;
    v_count INTEGER;
    v_hash TEXT;
    v_existing public.analysis_v2_partner_safety_manifests%ROWTYPE;
BEGIN
    IF p_rows IS NULL OR pg_catalog.jsonb_typeof(p_rows) <> 'array'
       OR pg_catalog.jsonb_array_length(p_rows) > 900
       OR pg_catalog.octet_length(p_rows::TEXT) > 2097152
       OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR NOT (item.value ?& ARRAY[
                'candidateId', 'source', 'hasStrongPartnerEvidence',
                'hasWeakPartnerEvidence',
                'strongEvidenceBasis', 'evidenceSelectionIds', 'bundleId',
                    'operationKey', 'aiResultHash'
               ])
               OR item.value - ARRAY[
                'candidateId', 'source', 'hasStrongPartnerEvidence',
                'hasWeakPartnerEvidence',
                'strongEvidenceBasis', 'evidenceSelectionIds', 'bundleId',
                    'operationKey', 'aiResultHash'
               ] <> '{}'::JSONB
               OR item.value->>'candidateId' !~ '^[A-Za-z0-9._:-]{1,128}$'
               OR item.value->>'source' NOT IN (
                    'not_collected', 'feature_only', 'gemini', 'safe_fallback'
               )
               OR pg_catalog.jsonb_typeof(item.value->'hasStrongPartnerEvidence') <> 'boolean'
               OR pg_catalog.jsonb_typeof(item.value->'hasWeakPartnerEvidence') <> 'boolean'
               OR item.value->>'strongEvidenceBasis' NOT IN (
                    'none', 'feature', 'contact_sheet', 'both'
               )
               OR pg_catalog.jsonb_typeof(item.value->'evidenceSelectionIds') <> 'array'
               OR pg_catalog.jsonb_array_length(item.value->'evidenceSelectionIds') > 8
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;
    v_job := public.analysis_v2_assert_result_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    IF v_job.job_key <> 'track:partner-safety:batch:0'
       OR v_job.track <> 'partner_safety' OR v_job.kind <> 'ai' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(item.value ORDER BY item.value->>'candidateId'), '[]')
    INTO v_rows FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value);
    v_count := pg_catalog.jsonb_array_length(v_rows);
    IF v_count <> (
        SELECT pg_catalog.count(*) FROM public.analysis_v2_preliminary_score_rows AS score
        WHERE score.request_id = p_request_id
    ) OR EXISTS (
        SELECT 1 FROM public.analysis_v2_preliminary_score_rows AS score
        WHERE score.request_id = p_request_id
          AND NOT EXISTS (
              SELECT 1 FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
              WHERE item.value->>'candidateId' = score.candidate_id
          )
    ) OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
        JOIN public.analysis_v2_preliminary_score_rows AS preliminary
          ON preliminary.request_id = p_request_id
         AND preliminary.candidate_id = item.value->>'candidateId'
        WHERE (
                preliminary.verification_shortlist_rank IS NULL
                AND item.value->>'source' <> 'not_collected'
              )
           OR (
                preliminary.verification_shortlist_rank IS NOT NULL
                AND item.value->>'source' = 'not_collected'
              )
           OR NOT public.analysis_v2_result_partner_safety_row_matches(
                p_request_id,
                p_job_key,
                item.value
              )
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    v_hash := public.analysis_v2_result_staging_hash('partner_safety', NULL, v_rows);
    SELECT manifest.* INTO v_existing
    FROM public.analysis_v2_partner_safety_manifests AS manifest
    WHERE manifest.request_id = p_request_id FOR UPDATE;
    IF FOUND THEN
        IF v_existing.producer_job_key <> p_job_key
           OR v_existing.producer_input_hash <> p_job_input_hash
           OR v_existing.producer_claim_token <> p_claim_token
           OR v_existing.item_count <> v_count OR v_existing.result_hash <> v_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_result_checkpoint_json(
            p_request_id, p_job_key, NULL, v_count, v_count, v_hash
        );
    END IF;
    INSERT INTO public.analysis_v2_partner_safety_manifests (
        request_id, producer_job_key, producer_input_hash, producer_claim_token,
        item_count, result_hash
    ) VALUES (p_request_id, p_job_key, p_job_input_hash, p_claim_token, v_count, v_hash);
    INSERT INTO public.analysis_v2_partner_safety_rows (
        request_id, candidate_id, source, has_strong_partner_evidence,
        has_weak_partner_evidence, strong_evidence_basis, evidence_selection_ids,
        bundle_id, operation_key, ai_result_hash
    )
    SELECT p_request_id, item.value->>'candidateId', item.value->>'source',
        (item.value->>'hasStrongPartnerEvidence')::BOOLEAN,
        (item.value->>'hasWeakPartnerEvidence')::BOOLEAN,
        item.value->>'strongEvidenceBasis',
        ARRAY(
            SELECT evidence.value
            FROM pg_catalog.jsonb_array_elements_text(item.value->'evidenceSelectionIds')
                WITH ORDINALITY AS evidence(value, ordinality)
            ORDER BY evidence.ordinality
        ),
        NULLIF(item.value->>'bundleId', ''),
        NULLIF(item.value->>'operationKey', ''),
        NULLIF(item.value->>'aiResultHash', '')
    FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value);
    RETURN public.analysis_v2_result_checkpoint_json(
        p_request_id, p_job_key, NULL, v_count, v_count, v_hash
    );
END;
$_$;


--
-- Name: checkpoint_analysis_v2_preliminary_scores(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_preliminary_scores(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_rows JSONB;
    v_count INTEGER;
    v_shortlist INTEGER;
    v_hash TEXT;
    v_existing RECORD;
BEGIN
    IF p_rows IS NULL OR pg_catalog.jsonb_typeof(p_rows) <> 'array'
       OR pg_catalog.jsonb_array_length(p_rows) > 900
       OR pg_catalog.octet_length(p_rows::TEXT) > 2097152
       OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR NOT (item.value ?& ARRAY[
                    'candidateId', 'components', 'preScore', 'possibleUpperBound',
                    'recentMutualRank', 'verificationShortlistRank'
               ])
               OR item.value - ARRAY[
                    'candidateId', 'components', 'preScore', 'possibleUpperBound',
                    'recentMutualRank', 'verificationShortlistRank'
               ] <> '{}'::JSONB
               OR item.value->>'candidateId' !~ '^[A-Za-z0-9._:-]{1,128}$'
               OR NOT public.analysis_v2_result_valid_score_components(item.value->'components')
               OR (item.value->'components'->>'targetToCandidateLike')::NUMERIC <> 0
               OR pg_catalog.jsonb_typeof(item.value->'preScore') <> 'number'
               OR (item.value->>'preScore')::NUMERIC NOT BETWEEN 0 AND 97
               OR pg_catalog.jsonb_typeof(item.value->'possibleUpperBound') <> 'number'
               OR (item.value->>'possibleUpperBound')::NUMERIC NOT BETWEEN 0 AND 100
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
        WHERE pg_catalog.abs(
                (item.value->>'preScore')::NUMERIC
                - (
                    (item.value->'components'->>'candidateToTargetLikes')::NUMERIC
                    + (item.value->'components'->>'candidateToTargetComments')::NUMERIC
                    + (item.value->'components'->>'tagOrCaptionMention')::NUMERIC
                    + (item.value->'components'->>'recentMutual')::NUMERIC
                    + (item.value->'components'->>'appearanceExposure')::NUMERIC
                )
              ) > 0.0001
           OR pg_catalog.abs(
                (item.value->>'possibleUpperBound')::NUMERIC
                - LEAST((item.value->>'preScore')::NUMERIC + 3, 100)
              ) > 0.0001
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;
    v_job := public.analysis_v2_assert_result_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    IF v_job.job_key <> 'coordinator:candidate-screening'
       OR v_job.track <> 'coordinator' OR v_job.kind <> 'screening' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(item.value ORDER BY item.value->>'candidateId'), '[]')
    INTO v_rows FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value);
    v_count := pg_catalog.jsonb_array_length(v_rows);
    v_shortlist := LEAST(v_count, 10);
    IF v_count <> (
        SELECT pg_catalog.count(*) FROM public.analysis_v2_candidate_feature_rows AS feature
        WHERE feature.request_id = p_request_id
          AND feature.terminal_classification = 'verified_female'
    ) OR EXISTS (
        SELECT 1 FROM public.analysis_v2_candidate_feature_rows AS feature
        WHERE feature.request_id = p_request_id
          AND feature.terminal_classification = 'verified_female'
          AND NOT EXISTS (
              SELECT 1 FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
              WHERE item.value->>'candidateId' = feature.candidate_id
          )
    ) OR (
        SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
        WHERE item.value->'verificationShortlistRank' <> 'null'::JSONB
    ) <> v_shortlist OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
        WHERE (
                item.value->'recentMutualRank' <> 'null'::JSONB
                AND item.value->>'recentMutualRank' !~ '^(?:[1-9]|10)$'
              )
           OR (
                item.value->'verificationShortlistRank' <> 'null'::JSONB
                AND item.value->>'verificationShortlistRank' !~ '^(?:[1-9]|10)$'
              )
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    v_hash := public.analysis_v2_result_staging_hash('preliminary_scores', NULL, v_rows);
    SELECT manifest.* INTO v_existing
    FROM public.analysis_v2_preliminary_score_manifests AS manifest
    WHERE manifest.request_id = p_request_id FOR UPDATE;
    IF FOUND THEN
        IF v_existing.producer_job_key <> p_job_key
           OR v_existing.producer_input_hash <> p_job_input_hash
           OR v_existing.producer_claim_token <> p_claim_token
           OR v_existing.item_count <> v_count OR v_existing.result_hash <> v_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_result_checkpoint_json(
            p_request_id, p_job_key, NULL, v_count, v_count, v_hash
        );
    END IF;
    INSERT INTO public.analysis_v2_preliminary_score_manifests (
        request_id, producer_job_key, producer_input_hash, producer_claim_token,
        item_count, result_hash
    ) VALUES (p_request_id, p_job_key, p_job_input_hash, p_claim_token, v_count, v_hash);
    INSERT INTO public.analysis_v2_preliminary_score_rows (
        request_id, candidate_id, components, pre_score, possible_upper_bound,
        recent_mutual_rank, verification_shortlist_rank
    )
    SELECT p_request_id, item.value->>'candidateId', item.value->'components',
        (item.value->>'preScore')::NUMERIC,
        (item.value->>'possibleUpperBound')::NUMERIC,
        CASE WHEN item.value->'recentMutualRank' = 'null'::JSONB THEN NULL
            ELSE (item.value->>'recentMutualRank')::SMALLINT END,
        CASE WHEN item.value->'verificationShortlistRank' = 'null'::JSONB THEN NULL
            ELSE (item.value->>'verificationShortlistRank')::SMALLINT END
    FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value);
    RETURN public.analysis_v2_result_checkpoint_json(
        p_request_id, p_job_key, NULL, v_count, v_count, v_hash
    );
END;
$_$;


--
-- Name: checkpoint_analysis_v2_preliminary_scores_v24(uuid, text, uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_preliminary_scores_v24(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_rows jsonb, p_risk_policy_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_rows JSONB;
    v_count INTEGER;
    v_shortlist INTEGER;
    v_hash TEXT;
    v_existing RECORD;
BEGIN
    IF p_risk_policy_version NOT IN ('risk-policy-v2.4', 'risk-policy-v2.5')
       OR p_rows IS NULL OR pg_catalog.jsonb_typeof(p_rows) <> 'array'
       OR pg_catalog.jsonb_array_length(p_rows) > 900
       OR pg_catalog.octet_length(p_rows::TEXT) > 2097152
       OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR NOT (item.value ?& ARRAY[
                    'candidateId', 'components', 'preScore', 'possibleUpperBound',
                    'recentMutualRank', 'verificationShortlistRank'
               ])
               OR item.value - ARRAY[
                    'candidateId', 'components', 'preScore', 'possibleUpperBound',
                    'recentMutualRank', 'verificationShortlistRank'
               ] <> '{}'::JSONB
               OR item.value->>'candidateId' !~ '^[A-Za-z0-9._:-]{1,128}$'
               OR NOT public.analysis_v2_result_valid_score_components(item.value->'components')
               OR NOT (item.value->'components' ?& ARRAY[
                    'candidateToTargetLikes', 'candidateToTargetComments',
                    'candidateToTargetTagOrCaptionMention',
                    'targetToCandidateTagOrCaptionMention', 'targetToCandidateLike',
                    'recentMutual', 'appearanceExposure'
               ])
               OR (item.value->'components') - ARRAY[
                    'candidateToTargetLikes', 'candidateToTargetComments',
                    'candidateToTargetTagOrCaptionMention',
                    'targetToCandidateTagOrCaptionMention', 'targetToCandidateLike',
                    'recentMutual', 'appearanceExposure'
               ] <> '{}'::JSONB
               OR (item.value->'components'->>'targetToCandidateLike')::NUMERIC <> 0
               OR pg_catalog.jsonb_typeof(item.value->'preScore') <> 'number'
               OR (item.value->>'preScore')::NUMERIC NOT BETWEEN 0 AND 95
               OR pg_catalog.jsonb_typeof(item.value->'possibleUpperBound') <> 'number'
               OR (item.value->>'possibleUpperBound')::NUMERIC NOT BETWEEN 0 AND 100
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;
    IF EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
        WHERE pg_catalog.abs(
                (item.value->>'preScore')::NUMERIC - (
                    (item.value->'components'->>'candidateToTargetLikes')::NUMERIC
                    + (item.value->'components'->>'candidateToTargetComments')::NUMERIC
                    + (item.value->'components'->>'candidateToTargetTagOrCaptionMention')::NUMERIC
                    + (item.value->'components'->>'targetToCandidateTagOrCaptionMention')::NUMERIC
                    + (item.value->'components'->>'recentMutual')::NUMERIC
                    + (item.value->'components'->>'appearanceExposure')::NUMERIC
                )
              ) > 0.0001
           OR pg_catalog.abs(
                (item.value->>'possibleUpperBound')::NUMERIC
                - LEAST((item.value->>'preScore')::NUMERIC + 5, 100)
              ) > 0.0001
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;
    v_job := public.analysis_v2_assert_result_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    IF v_job.job_key <> 'coordinator:candidate-screening'
       OR v_job.track <> 'coordinator' OR v_job.kind <> 'screening'
       OR NOT EXISTS (
            SELECT 1 FROM public.analysis_requests AS analysis_request
            WHERE analysis_request.id = p_request_id
              AND analysis_request.policy_versions_snapshot->>'risk' = p_risk_policy_version
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(item.value ORDER BY item.value->>'candidateId'), '[]')
    INTO v_rows FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value);
    v_count := pg_catalog.jsonb_array_length(v_rows);
    v_shortlist := LEAST(v_count, 10);
    IF v_count <> (
        SELECT pg_catalog.count(*) FROM public.analysis_v2_candidate_feature_rows AS feature
        WHERE feature.request_id = p_request_id
          AND feature.terminal_classification = 'verified_female'
    ) OR EXISTS (
        SELECT 1 FROM public.analysis_v2_candidate_feature_rows AS feature
        WHERE feature.request_id = p_request_id
          AND feature.terminal_classification = 'verified_female'
          AND NOT EXISTS (
              SELECT 1 FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
              WHERE item.value->>'candidateId' = feature.candidate_id
          )
    ) OR (
        SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
        WHERE item.value->'verificationShortlistRank' <> 'null'::JSONB
    ) <> v_shortlist OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
        WHERE (
                item.value->'recentMutualRank' <> 'null'::JSONB
                AND item.value->>'recentMutualRank' !~ '^(?:[1-9]|10)$'
              )
           OR (
                item.value->'verificationShortlistRank' <> 'null'::JSONB
                AND item.value->>'verificationShortlistRank' !~ '^(?:[1-9]|10)$'
              )
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    v_hash := public.analysis_v2_result_staging_hash('preliminary_scores', NULL, v_rows);
    SELECT manifest.* INTO v_existing FROM public.analysis_v2_preliminary_score_manifests AS manifest
    WHERE manifest.request_id = p_request_id FOR UPDATE;
    IF FOUND THEN
        IF v_existing.producer_job_key <> p_job_key
           OR v_existing.producer_input_hash <> p_job_input_hash
           OR v_existing.producer_claim_token <> p_claim_token
           OR v_existing.item_count <> v_count OR v_existing.result_hash <> v_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_result_checkpoint_json(
            p_request_id, p_job_key, NULL, v_count, v_count, v_hash
        );
    END IF;
    INSERT INTO public.analysis_v2_preliminary_score_manifests (
        request_id, producer_job_key, producer_input_hash, producer_claim_token,
        item_count, result_hash
    ) VALUES (p_request_id, p_job_key, p_job_input_hash, p_claim_token, v_count, v_hash);
    INSERT INTO public.analysis_v2_preliminary_score_rows (
        request_id, candidate_id, components, pre_score, possible_upper_bound,
        recent_mutual_rank, verification_shortlist_rank
    )
    SELECT p_request_id, item.value->>'candidateId', item.value->'components',
        (item.value->>'preScore')::NUMERIC, (item.value->>'possibleUpperBound')::NUMERIC,
        CASE WHEN item.value->'recentMutualRank' = 'null'::JSONB THEN NULL
            ELSE (item.value->>'recentMutualRank')::SMALLINT END,
        CASE WHEN item.value->'verificationShortlistRank' = 'null'::JSONB THEN NULL
            ELSE (item.value->>'verificationShortlistRank')::SMALLINT END
    FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value);
    RETURN public.analysis_v2_result_checkpoint_json(
        p_request_id, p_job_key, NULL, v_count, v_count, v_hash
    );
END;
$_$;


--
-- Name: checkpoint_analysis_v2_private_names(uuid, text, uuid, text, integer, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_private_names(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_batch integer, p_source text, p_operation_key text, p_ai_result_hash text, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_rows JSONB;
    v_count INTEGER;
    v_hash TEXT;
    v_expected_count INTEGER;
    v_existing public.analysis_v2_private_name_manifests%ROWTYPE;
BEGIN
    IF p_batch IS NULL OR p_batch NOT BETWEEN 0 AND 100000
       OR p_source NOT IN ('checkpoint', 'safe_fallback')
       OR p_operation_key !~ '^private-account-name:[a-f0-9]{64}$'
       OR (p_source = 'checkpoint' AND (
            p_ai_result_hash IS NULL OR p_ai_result_hash !~ '^[a-f0-9]{64}$'
       ))
       OR (p_source = 'safe_fallback' AND p_ai_result_hash IS NOT NULL)
       OR p_rows IS NULL OR pg_catalog.jsonb_typeof(p_rows) <> 'array'
       OR pg_catalog.jsonb_array_length(p_rows) NOT BETWEEN 1 AND 100
       OR pg_catalog.octet_length(p_rows::TEXT) > 1048576
       OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR NOT (item.value ?& ARRAY[
                    'candidateId', 'instagramId', 'fullName', 'profileImageUrl',
                    'nameFemaleScore', 'nameIsName', 'nameConfidence'
               ])
               OR item.value - ARRAY[
                    'candidateId', 'instagramId', 'fullName', 'profileImageUrl',
                    'nameFemaleScore', 'nameIsName', 'nameConfidence'
               ] <> '{}'::JSONB
               OR item.value->>'candidateId' !~ '^[A-Za-z0-9._:-]{1,128}$'
               OR item.value->>'instagramId' !~ '^[a-z0-9._]{1,30}$'
               OR item.value->>'candidateId' <> public.analysis_v2_result_candidate_id(
                    item.value->>'instagramId'
               )
               OR pg_catalog.jsonb_typeof(item.value->'fullName') NOT IN ('string', 'null')
               OR pg_catalog.jsonb_typeof(item.value->'profileImageUrl') NOT IN ('string', 'null')
               OR NOT public.analysis_v2_result_valid_image_path(
                    NULLIF(item.value->>'profileImageUrl', '')
               )
               OR pg_catalog.jsonb_typeof(item.value->'nameFemaleScore') <> 'number'
               OR (item.value->>'nameFemaleScore')::NUMERIC NOT BETWEEN 0 AND 1
               OR pg_catalog.jsonb_typeof(item.value->'nameIsName') <> 'boolean'
               OR pg_catalog.jsonb_typeof(item.value->'nameConfidence') <> 'number'
               OR (item.value->>'nameConfidence')::NUMERIC NOT BETWEEN 0 AND 1
               OR (
                    NOT (item.value->>'nameIsName')::BOOLEAN
                    AND (item.value->>'nameFemaleScore')::NUMERIC <> 0.5
               )
               OR (
                    p_source = 'safe_fallback'
                    AND (
                        (item.value->>'nameFemaleScore')::NUMERIC <> 0.5
                        OR (item.value->>'nameIsName')::BOOLEAN
                        OR (item.value->>'nameConfidence')::NUMERIC <> 0
                    )
               )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;

    v_job := public.analysis_v2_assert_result_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    IF v_job.job_key <> 'track:private-names:batch:' || p_batch::TEXT
       OR v_job.track <> 'private_names' OR v_job.kind <> 'ai'
       OR v_job.batch IS DISTINCT FROM p_batch THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT topology.item_count INTO v_expected_count
    FROM public.analysis_v2_dag_batch_topology AS topology
    WHERE topology.request_id = p_request_id
      AND topology.topology_kind = 'private_name' AND topology.batch = p_batch
;
    IF v_expected_count IS NULL OR v_expected_count <> pg_catalog.jsonb_array_length(p_rows)
       OR (
            p_source = 'checkpoint'
            AND NOT EXISTS (
                SELECT 1 FROM public.analysis_v2_ai_result_checkpoints AS ai_result
                WHERE ai_result.request_id = p_request_id
                  AND ai_result.job_key = p_job_key
                  AND ai_result.operation_key = p_operation_key
                  AND ai_result.stage = 'privateAccountName'
                  AND ai_result.result_hash = p_ai_result_hash
            )
       ) OR (
            p_source = 'safe_fallback'
            AND NOT EXISTS (
                SELECT 1 FROM public.analysis_v2_ai_attempts AS ai_attempt
                WHERE ai_attempt.request_id = p_request_id
                  AND ai_attempt.job_key = p_job_key
                  AND ai_attempt.operation_key = p_operation_key
                  AND ai_attempt.stage = 'privateAccountName'
                  AND public.analysis_v2_ai_fallback_evidence_matches(
                      p_request_id,
                      p_job_key,
                      p_operation_key,
                      'privateAccountName'
                  )
            )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(
        pg_catalog.jsonb_agg(item.value ORDER BY item.value->>'candidateId'),
        '[]'::JSONB
    ) INTO v_rows FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value);
    v_count := pg_catalog.jsonb_array_length(v_rows);
    IF (
        SELECT pg_catalog.count(DISTINCT item.value->>'candidateId')
        FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
    ) <> v_count OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
        WHERE NOT EXISTS (
            SELECT 1
            FROM (
                SELECT mutual.username,
                    pg_catalog.row_number() OVER (ORDER BY mutual.mutual_ordinal) AS private_rank
                FROM public.analysis_v2_mutual_rows AS mutual
                WHERE mutual.request_id = p_request_id
                  AND mutual.job_key = 'track:relationships:collect'
                  AND mutual.is_private
            ) AS private_mutual
            WHERE (private_mutual.private_rank - 1) / 100 = p_batch
              AND private_mutual.username = item.value->>'instagramId'
        )
    ) OR v_count <> (
        SELECT pg_catalog.count(*)
        FROM (
            SELECT pg_catalog.row_number() OVER (ORDER BY mutual.mutual_ordinal) AS private_rank
            FROM public.analysis_v2_mutual_rows AS mutual
            WHERE mutual.request_id = p_request_id
              AND mutual.job_key = 'track:relationships:collect'
              AND mutual.is_private
        ) AS private_mutual
        WHERE (private_mutual.private_rank - 1) / 100 = p_batch
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    v_hash := public.analysis_v2_result_staging_hash('private_names', p_batch, v_rows);
    SELECT manifest.* INTO v_existing
    FROM public.analysis_v2_private_name_manifests AS manifest
    WHERE manifest.request_id = p_request_id AND manifest.batch = p_batch FOR UPDATE;
    IF FOUND THEN
        IF v_existing.producer_job_key <> p_job_key
           OR v_existing.producer_input_hash <> p_job_input_hash
           OR v_existing.producer_claim_token <> p_claim_token
           OR v_existing.item_count <> v_count OR v_existing.source <> p_source
           OR v_existing.operation_key <> p_operation_key
           OR v_existing.ai_result_hash IS DISTINCT FROM p_ai_result_hash
           OR v_existing.result_hash <> v_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_result_checkpoint_json(
            p_request_id, p_job_key, p_batch, v_count, v_count, v_hash
        );
    END IF;

    INSERT INTO public.analysis_v2_private_name_manifests (
        request_id, batch, producer_job_key, producer_input_hash, producer_claim_token,
        item_count, source, operation_key, ai_result_hash, result_hash
    ) VALUES (
        p_request_id, p_batch, p_job_key, p_job_input_hash, p_claim_token,
        v_count, p_source, p_operation_key, p_ai_result_hash, v_hash
    );
    INSERT INTO public.analysis_v2_private_name_rows (
        request_id, batch, candidate_id, instagram_id, full_name, profile_image_url,
        name_female_score, name_is_name, name_confidence
    )
    SELECT p_request_id, p_batch, item.value->>'candidateId', item.value->>'instagramId',
        NULLIF(item.value->>'fullName', ''), NULLIF(item.value->>'profileImageUrl', ''),
        (item.value->>'nameFemaleScore')::NUMERIC,
        (item.value->>'nameIsName')::BOOLEAN,
        (item.value->>'nameConfidence')::NUMERIC
    FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value);
    RETURN public.analysis_v2_result_checkpoint_json(
        p_request_id, p_job_key, p_batch, v_count, v_count, v_hash
    );
END;
$_$;


--
-- Name: checkpoint_analysis_v2_profile_fallback(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_profile_fallback(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_outcomes jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_batch public.analysis_v2_profile_fetch_batches%ROWTYPE;
    v_payload_hash TEXT;
    v_completed_at TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR pg_catalog.jsonb_typeof(p_outcomes) <> 'array' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND OR v_request.pipeline_version IS DISTINCT FROM 'v2' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_completed_at := pg_catalog.clock_timestamp();
    IF v_request.status NOT IN ('pending', 'processing')
       OR v_job.status <> 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_completed_at THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT batch.*
    INTO v_batch
    FROM public.analysis_v2_profile_fetch_batches AS batch
    WHERE batch.request_id = p_request_id
      AND batch.job_key = p_job_key
    FOR UPDATE;
    v_completed_at := pg_catalog.clock_timestamp();
    IF v_job.lease_expires_at <= v_completed_at THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    IF NOT FOUND
       OR pg_catalog.cardinality(v_batch.frozen_unresolved_usernames) = 0
       OR NOT public.analysis_v2_valid_profile_outcomes(
            p_outcomes,
            v_batch.frozen_unresolved_usernames,
            'fallback'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    v_payload_hash := pg_catalog.encode(
        extensions.digest(p_outcomes::TEXT, 'sha256'),
        'hex'
    );
    IF v_batch.fallback_completed_at IS NOT NULL THEN
        IF v_batch.fallback_payload_hash <> v_payload_hash THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROFILE_FALLBACK_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_profile_checkpoint_snapshot(p_request_id, p_job_key);
    END IF;

    INSERT INTO public.analysis_v2_profile_fetch_outcomes (
        request_id,
        job_key,
        attempt,
        ordinal,
        username,
        source,
        status,
        failure_category,
        http_status,
        request_count,
        latency_ms,
        captured_at,
        profile_snapshot
    )
    SELECT
        p_request_id,
        p_job_key,
        'fallback',
        outcome.ordinal::SMALLINT,
        outcome.value->>'username',
        outcome.value->>'source',
        outcome.value->>'status',
        NULLIF(outcome.value->>'failure_category', ''),
        CASE
            WHEN outcome.value->'http_status' = 'null'::JSONB THEN NULL
            ELSE (outcome.value->>'http_status')::SMALLINT
        END,
        (outcome.value->>'request_count')::SMALLINT,
        (outcome.value->>'latency_ms')::INTEGER,
        (outcome.value->>'captured_at')::TIMESTAMP WITH TIME ZONE,
        CASE
            WHEN outcome.value->'profile' = 'null'::JSONB THEN NULL
            ELSE outcome.value->'profile'
        END
    FROM pg_catalog.jsonb_array_elements(p_outcomes)
        WITH ORDINALITY AS outcome(value, ordinal)
    ORDER BY outcome.ordinal;

    v_completed_at := clock_timestamp();
    UPDATE public.analysis_v2_profile_fetch_batches AS batch
    SET fallback_payload_hash = v_payload_hash,
        fallback_completed_at = v_completed_at,
        updated_at = v_completed_at
    WHERE batch.request_id = p_request_id
      AND batch.job_key = p_job_key;

    RETURN public.analysis_v2_profile_checkpoint_snapshot(p_request_id, p_job_key);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_profile_fresh_apify_earlybird_v1(uuid, text, uuid, text, text[], jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_profile_fresh_apify_earlybird_v1(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_requested_usernames text[], p_outcomes jsonb, p_operation_key text, p_provider_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_order_id UUID;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_provider public.analysis_v2_provider_runs%ROWTYPE;
    v_batch public.analysis_v2_profile_fetch_batches%ROWTYPE;
    v_selected_card JSONB;
    v_expected_scope JSONB;
    v_unresolved TEXT[];
    v_payload_hash TEXT;
    v_now TIMESTAMP WITH TIME ZONE;
    v_existing_outcome_count INTEGER;
    v_existing_fresh_count INTEGER;
BEGIN
    -- The paid route is intentionally narrower than the generic provider-key
    -- validator: only target hydration and the matching profile batch can use
    -- this RPC.  Relationships and interaction jobs have their own admissions.
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_provider_input_hash IS NULL
       OR p_provider_input_hash !~ '^[a-f0-9]{64}$'
       OR p_operation_key IS NULL
       OR p_operation_key !~ '^(target-profile|profile-fallback):[a-f0-9]{64}$'
       OR NOT public.analysis_v2_valid_profile_username_list(
            p_requested_usernames,
            FALSE
       )
       OR NOT public.analysis_v2_valid_profile_outcomes(
            p_outcomes,
            p_requested_usernames,
            'fallback'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- Resolve without taking a child lock.  All subsequent locks follow the
    -- reconciliation order fulfillment -> order -> preflight -> request ->
    -- job -> provider -> batch.
    SELECT fulfillment.order_id
    INTO v_order_id
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.request_id = p_request_id;
    IF v_order_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT fulfillment.*
    INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = v_order_id
    FOR UPDATE;
    SELECT earlybird_order.*
    INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = v_order_id
    FOR UPDATE;
    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id
    FOR UPDATE;
    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    SELECT provider_run.*
    INTO v_provider
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    FOR UPDATE;
    SELECT batch.*
    INTO v_batch
    FROM public.analysis_v2_profile_fetch_batches AS batch
    WHERE batch.request_id = p_request_id
      AND batch.job_key = p_job_key
    FOR UPDATE;

    IF v_order.id IS NULL
       OR v_fulfillment.order_id IS NULL
       OR v_preflight.id IS NULL
       OR v_request.id IS NULL
       OR v_job.request_id IS NULL
       OR v_provider.request_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    IF v_order.status IS DISTINCT FROM 'analysis_in_progress'
       OR v_fulfillment.status IS DISTINCT FROM 'analysis_in_progress'
       OR v_fulfillment.order_id IS DISTINCT FROM v_order.id
       OR v_fulfillment.request_id IS DISTINCT FROM p_request_id
       OR v_fulfillment.manual_review_at IS NOT NULL
       OR v_order.result_request_id IS DISTINCT FROM p_request_id
       OR v_order.payment_id IS NULL
       OR v_order.paid_at IS NULL
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_order.actual_amount_krw IS NULL
       OR v_order.actual_amount_krw < 0
       OR v_order.actual_amount_krw > v_order.expected_amount_krw
       OR v_order.actual_groble_product_id IS DISTINCT FROM v_order.expected_groble_product_id
       OR v_order.plan_id NOT IN ('basic', 'standard')
       OR v_order.user_id IS DISTINCT FROM v_preflight.user_id
       OR v_order.user_id IS DISTINCT FROM v_request.user_id
       OR v_order.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_preflight.consumed_request_id IS DISTINCT FROM p_request_id
       OR v_preflight.status IS DISTINCT FROM 'consumed'
       OR v_order.target_instagram_id IS DISTINCT FROM v_preflight.target_instagram_id
       OR v_order.target_instagram_id IS DISTINCT FROM v_request.target_instagram_id
       OR v_preflight.admission_target_followers_count IS DISTINCT FROM v_preflight.target_followers_count
       OR v_preflight.admission_target_following_count IS DISTINCT FROM v_preflight.target_following_count
       OR v_order.excluded_instagram_id IS DISTINCT FROM v_preflight.excluded_instagram_id
       OR v_order.excluded_instagram_id IS DISTINCT FROM v_request.excluded_instagram_id
       OR v_order.exclusion_decision IS DISTINCT FROM v_preflight.exclusion_decision
       OR v_order.exclusion_decision IS DISTINCT FROM v_request.exclusion_decision_snapshot
       OR v_preflight.admission_required_plan_id IS DISTINCT FROM v_preflight.required_plan_id
       OR v_preflight.admission_capacity_required_plan_id IS DISTINCT FROM v_preflight.capacity_required_plan_id
       OR v_order.plan_id IS DISTINCT FROM v_preflight.admission_selected_plan_id
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_preflight.capacity_required_plan_id IS DISTINCT FROM v_request.capacity_required_plan_id_snapshot
       OR v_preflight.required_plan_id IS DISTINCT FROM v_request.required_plan_id_snapshot
       OR v_order.plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_preflight.required_plan_id IS NULL
       OR v_preflight.required_plan_id NOT IN ('basic', 'standard', 'plus')
       OR v_preflight.capacity_required_plan_id IS NULL
       OR v_preflight.capacity_required_plan_id NOT IN ('basic', 'standard', 'plus')
       OR v_preflight.admission_required_plan_id IS NULL
       OR v_preflight.admission_required_plan_id NOT IN ('basic', 'standard', 'plus')
       OR v_preflight.admission_capacity_required_plan_id IS NULL
       OR v_preflight.admission_capacity_required_plan_id NOT IN ('basic', 'standard', 'plus')
       OR v_request.required_plan_id_snapshot IS NULL
       OR v_request.required_plan_id_snapshot NOT IN ('basic', 'standard', 'plus')
       OR v_request.capacity_required_plan_id_snapshot IS NULL
       OR v_request.capacity_required_plan_id_snapshot NOT IN ('basic', 'standard', 'plus')
       OR v_request.selected_plan_id_snapshot IS NULL
       OR v_request.selected_plan_id_snapshot NOT IN ('basic', 'standard')
       OR (
            CASE v_preflight.required_plan_id
                WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3
            END < CASE v_preflight.capacity_required_plan_id
                WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3
            END
       )
       OR (
            CASE v_order.plan_id
                WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3
            END < CASE v_preflight.required_plan_id
                WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3
            END
       )
       OR v_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status IS DISTINCT FROM 'processing'
       OR v_preflight.access_mode IS DISTINCT FROM 'production'
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'production'
       OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'standard'
       OR v_request.analysis_entry_channel IS DISTINCT FROM 'standard'
       OR v_request.test_entitlement_jti_hash IS NOT NULL
       OR v_order.concierge_apify_credential_slot IS DISTINCT FROM 'secondary'
       OR v_preflight.order_scoped_apify_credential_slot IS DISTINCT FROM 'secondary'
       OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_provider_execution_policies AS policy
            WHERE policy.request_id = p_request_id
       )
       OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_test_entitlement_consumptions AS consumption
            WHERE consumption.request_id = p_request_id
       )
       OR EXISTS (
            SELECT 1
            FROM public.analysis_revenue_run_ledgers AS ledger
            WHERE ledger.request_id = p_request_id
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    v_selected_card := v_preflight.plan_cards_snapshot->v_order.plan_id;
    v_expected_scope := pg_catalog.jsonb_build_object(
        'relationshipCapacity', v_selected_card->'relationshipCapacity',
        'detailedMutualLimit', v_selected_card->'detailedMutualLimit'
    );
    IF v_preflight.plan_cards_snapshot IS NULL
       OR NOT public.analysis_v2_valid_plan_cards_snapshot(
            v_preflight.plan_cards_snapshot
       )
       OR v_selected_card IS NULL
       OR v_selected_card->>'launchStatus' IS DISTINCT FROM 'production'
       OR v_selected_card->>'selectionState' NOT IN ('required', 'available_upgrade')
       OR COALESCE(v_selected_card->'relationshipCapacity'->>'followers', '')
            !~ '^[0-9]+$'
       OR COALESCE(v_selected_card->'relationshipCapacity'->>'following', '')
            !~ '^[0-9]+$'
       OR v_order.target_followers_count IS NULL
       OR v_order.target_followers_count < 0
       OR v_order.target_following_count IS NULL
       OR v_order.target_following_count < 0
       OR v_preflight.target_followers_count IS NULL
       OR v_preflight.target_followers_count < 0
       OR v_preflight.target_following_count IS NULL
       OR v_preflight.target_following_count < 0
       OR v_order.target_followers_count
            > (v_selected_card->'relationshipCapacity'->>'followers')::INTEGER
       OR v_order.target_following_count
            > (v_selected_card->'relationshipCapacity'->>'following')::INTEGER
       OR v_preflight.target_followers_count
            > (v_selected_card->'relationshipCapacity'->>'followers')::INTEGER
       OR v_preflight.target_following_count
            > (v_selected_card->'relationshipCapacity'->>'following')::INTEGER
       OR NOT public.analysis_v2_valid_scope_snapshot(v_expected_scope)
       OR v_request.analysis_scope_snapshot IS DISTINCT FROM v_expected_scope THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    IF p_job_key = 'track:target-evidence:collect' THEN
        IF v_job.track IS DISTINCT FROM 'target_evidence'
           OR v_job.kind IS DISTINCT FROM 'collection'
           OR v_job.batch IS NOT NULL
           OR p_operation_key !~ '^target-profile:[a-f0-9]{64}$'
           OR pg_catalog.cardinality(p_requested_usernames) <> 1
           OR p_requested_usernames[1] IS DISTINCT FROM v_request.target_instagram_id THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
                ERRCODE = 'P0001';
        END IF;
    ELSIF p_job_key ~ '^track:profiles:batch:[0-9]+$' THEN
        IF v_job.track IS DISTINCT FROM 'profiles'
           OR v_job.kind IS DISTINCT FROM 'profile_fetch'
           OR v_job.batch IS NULL
           OR v_job.batch < 0
           OR v_job.batch > 999
           OR v_job.batch <> pg_catalog.regexp_replace(p_job_key, '^.*:', '')::INTEGER
           OR p_operation_key !~ '^profile-fallback:[a-f0-9]{64}$' THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
                ERRCODE = 'P0001';
        END IF;
    ELSE
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    IF v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.status IS DISTINCT FROM 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= pg_catalog.clock_timestamp()
       OR v_provider.input_hash IS DISTINCT FROM p_provider_input_hash
       OR v_provider.job_claim_token IS DISTINCT FROM p_claim_token
       OR v_provider.logical_provider IS DISTINCT FROM 'apify'
       OR v_provider.actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper'
       OR v_provider.credential_slot IS DISTINCT FROM 'secondary'
       OR v_provider.status IS DISTINCT FROM 'succeeded'
       OR v_provider.run_id IS NULL
       OR v_provider.run_started_at IS NULL
       OR v_provider.terminalized_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    -- v_provider.usage_reconciled_at is intentionally not part of admission:
    -- the current request-owned terminal run is sufficient evidence here.

    v_payload_hash := pg_catalog.encode(
        extensions.digest(
            pg_catalog.jsonb_build_object(
                'requested_usernames', pg_catalog.to_jsonb(p_requested_usernames),
                'outcomes', p_outcomes
            )::TEXT,
            'sha256'
        ),
        'hex'
    );
    SELECT COALESCE(
        pg_catalog.array_agg(outcome.value->>'username' ORDER BY outcome.ordinal),
        '{}'::TEXT[]
    )
    INTO v_unresolved
    FROM pg_catalog.jsonb_array_elements(p_outcomes)
        WITH ORDINALITY AS outcome(value, ordinal)
    WHERE outcome.value->>'status' <> 'success';

    IF v_batch.request_id IS NOT NULL THEN
        -- Replay is accepted only for the same direct-fresh primary.  Any
        -- fallback/repair timestamp or row means provenance was mixed and is
        -- rejected before a caller can treat it as direct Apify evidence.
        IF v_batch.request_id IS NULL
           OR v_batch.requested_usernames IS DISTINCT FROM p_requested_usernames
           OR v_batch.frozen_unresolved_usernames IS DISTINCT FROM v_unresolved
           OR v_batch.primary_payload_hash IS DISTINCT FROM v_payload_hash
           OR v_batch.fallback_completed_at IS NOT NULL
           OR v_batch.repair_completed_at IS NOT NULL
           OR v_batch.fallback_payload_hash IS NOT NULL
           OR v_batch.repair_payload_hash IS NOT NULL
           OR v_batch.repair_usernames IS NOT NULL
           OR EXISTS (
                SELECT 1
                FROM public.analysis_v2_profile_fetch_outcomes AS outcome
                WHERE outcome.request_id = p_request_id
                  AND outcome.job_key = p_job_key
                  AND outcome.attempt IN ('fallback', 'repair')
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROFILE_FRESH_APIFY_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        SELECT pg_catalog.count(*)::INTEGER,
               pg_catalog.count(*) FILTER (
                   WHERE outcome.attempt = 'fresh_apify'
                     AND outcome.source = 'apify'
               )::INTEGER
        INTO v_existing_outcome_count, v_existing_fresh_count
        FROM public.analysis_v2_profile_fetch_outcomes AS outcome
        WHERE outcome.request_id = p_request_id
          AND outcome.job_key = p_job_key;
        IF v_existing_outcome_count IS DISTINCT FROM pg_catalog.cardinality(p_requested_usernames)
           OR v_existing_fresh_count IS DISTINCT FROM pg_catalog.cardinality(p_requested_usernames)
           OR EXISTS (
                SELECT 1
                FROM public.analysis_v2_profile_fetch_outcomes AS outcome
                WHERE outcome.request_id = p_request_id
                  AND outcome.job_key = p_job_key
                  AND outcome.attempt <> 'fresh_apify'
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROFILE_FRESH_APIFY_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_profile_checkpoint_snapshot(p_request_id, p_job_key);
    END IF;

    -- A batch row and its outcome rows are one physical checkpoint.  A
    -- detached fallback/repair/fresh row is not an admissible new direct run;
    -- reject it rather than attempting to reconstruct provenance.
    IF EXISTS (
        SELECT 1
        FROM public.analysis_v2_profile_fetch_outcomes AS outcome
        WHERE outcome.request_id = p_request_id
          AND outcome.job_key = p_job_key
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_FRESH_APIFY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    v_now := pg_catalog.clock_timestamp();
    INSERT INTO public.analysis_v2_profile_fetch_batches (
        request_id,
        job_key,
        requested_usernames,
        frozen_unresolved_usernames,
        primary_payload_hash,
        primary_completed_at,
        created_at,
        updated_at
    ) VALUES (
        p_request_id,
        p_job_key,
        p_requested_usernames,
        v_unresolved,
        v_payload_hash,
        v_now,
        v_now,
        v_now
    );

    INSERT INTO public.analysis_v2_profile_fetch_outcomes (
        request_id,
        job_key,
        attempt,
        ordinal,
        username,
        source,
        status,
        failure_category,
        http_status,
        request_count,
        latency_ms,
        captured_at,
        profile_snapshot
    )
    SELECT
        p_request_id,
        p_job_key,
        'fresh_apify',
        outcome.ordinal::SMALLINT,
        outcome.value->>'username',
        outcome.value->>'source',
        outcome.value->>'status',
        NULLIF(outcome.value->>'failure_category', ''),
        CASE
            WHEN outcome.value->'http_status' = 'null'::JSONB THEN NULL
            ELSE (outcome.value->>'http_status')::SMALLINT
        END,
        (outcome.value->>'request_count')::SMALLINT,
        (outcome.value->>'latency_ms')::INTEGER,
        (outcome.value->>'captured_at')::TIMESTAMPTZ,
        CASE
            WHEN outcome.value->'profile' = 'null'::JSONB THEN NULL
            ELSE outcome.value->'profile'
        END
    FROM pg_catalog.jsonb_array_elements(p_outcomes)
        WITH ORDINALITY AS outcome(value, ordinal)
    ORDER BY outcome.ordinal;

    RETURN public.analysis_v2_profile_checkpoint_snapshot(p_request_id, p_job_key);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_profile_fresh_apify_v1(uuid, text, uuid, text, text[], jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_profile_fresh_apify_v1(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_requested_usernames text[], p_outcomes jsonb, p_operation_key text, p_provider_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_provider public.analysis_v2_provider_runs%ROWTYPE;
    v_evidence public.analysis_revenue_fresh_provider_evidence%ROWTYPE;
    v_batch public.analysis_v2_profile_fetch_batches%ROWTYPE;
    v_operation_hash TEXT;
    v_expected_run_hash TEXT;
    v_payload_hash TEXT;
    v_unresolved TEXT[];
    v_completed_at TIMESTAMPTZ;
    v_existing_outcome_count INTEGER;
    v_existing_fresh_count INTEGER;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_provider_input_hash IS NULL OR p_provider_input_hash !~ '^[a-f0-9]{64}$'
       OR p_operation_key IS NULL
       OR NOT public.analysis_revenue_valid_fresh_provider_operation_key_v1(p_operation_key)
       OR NOT public.analysis_v2_valid_profile_username_list(p_requested_usernames, FALSE)
       -- The established fallback validator is the exact bounded Apify outcome
       -- grammar.  It is intentionally reused rather than widening primary.
       OR NOT public.analysis_v2_valid_profile_outcomes(
            p_outcomes, p_requested_usernames, 'fallback'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- Lock and prove the test-entitlement parent, live job claim, and exact
    -- Apify source before touching a profile checkpoint. The admission gate
    -- and the materialized reads below both use preflight → request → job →
    -- provider/source → revenue parent, matching live-cost RPCs.
    PERFORM public.assert_analysis_revenue_fresh_provider_admission_v1(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash,
        p_operation_key, p_provider_input_hash
    );

    SELECT * INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    SELECT * INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    SELECT * INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    SELECT * INTO v_provider
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    FOR UPDATE;
    SELECT * INTO v_parent
    FROM public.analysis_revenue_run_ledgers AS ledger
    WHERE ledger.request_id = p_request_id
    FOR UPDATE;

    v_operation_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
        'analysis-revenue-fresh-provider-operation/v1|'
        || pg_catalog.octet_length(p_operation_key)::TEXT || ':' || p_operation_key,
        'UTF8'
    ), 'sha256'), 'hex');
    IF v_provider.request_id IS NULL
       OR v_provider.logical_provider IS DISTINCT FROM 'apify'
       OR v_provider.input_hash IS DISTINCT FROM p_provider_input_hash
       OR v_provider.job_claim_token IS DISTINCT FROM p_claim_token
       OR v_provider.status IS DISTINCT FROM 'succeeded'
       OR v_provider.run_id IS NULL
       OR v_provider.run_started_at IS NULL
       OR v_provider.reserved_at < v_parent.preflight_refreshed_at
       OR v_provider.run_started_at < v_parent.preflight_refreshed_at THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_NOT_FRESH', ERRCODE = 'P0001';
    END IF;
    v_expected_run_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
        'analysis-revenue-fresh-provider-run/v1|'
        || pg_catalog.octet_length(p_request_id::TEXT)::TEXT || ':' || p_request_id::TEXT || '|'
        || pg_catalog.octet_length(p_job_key)::TEXT || ':' || p_job_key || '|'
        || pg_catalog.octet_length(p_operation_key)::TEXT || ':' || p_operation_key || '|'
        || pg_catalog.octet_length(v_provider.run_id)::TEXT || ':' || v_provider.run_id,
        'UTF8'
    ), 'sha256'), 'hex');
    SELECT * INTO v_evidence
    FROM public.analysis_revenue_fresh_provider_evidence AS evidence
    WHERE evidence.request_id = p_request_id
      AND evidence.job_key = p_job_key
      AND evidence.operation_key_hash = v_operation_hash
    FOR UPDATE;
    IF v_evidence.request_id IS NULL
       OR v_evidence.job_input_hash IS DISTINCT FROM p_job_input_hash
       OR v_evidence.provider IS DISTINCT FROM 'apify'
       OR v_evidence.provider_input_hash IS DISTINCT FROM p_provider_input_hash
       OR v_evidence.provider_run_hash IS DISTINCT FROM v_expected_run_hash
       OR v_evidence.provider_run_started_at IS DISTINCT FROM v_provider.run_started_at
       OR v_evidence.provider_dataset_hash IS NULL
       OR v_evidence.dataset_bound_at IS NULL
       OR NOT v_evidence.no_reuse
       OR NOT v_evidence.no_adoption
       OR NOT v_evidence.no_cache THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_NOT_FRESH', ERRCODE = 'P0001';
    END IF;

    IF v_request.id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR v_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_job.request_id IS NULL
       OR v_job.status IS DISTINCT FROM 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    v_payload_hash := pg_catalog.encode(extensions.digest(
        pg_catalog.jsonb_build_object(
            'requested_usernames', pg_catalog.to_jsonb(p_requested_usernames),
            'outcomes', p_outcomes
        )::TEXT,
        'sha256'
    ), 'hex');
    SELECT * INTO v_batch
    FROM public.analysis_v2_profile_fetch_batches AS batch
    WHERE batch.request_id = p_request_id
      AND batch.job_key = p_job_key
    FOR UPDATE;
    IF FOUND THEN
        IF v_batch.requested_usernames IS DISTINCT FROM p_requested_usernames
           OR v_batch.primary_payload_hash IS DISTINCT FROM v_payload_hash THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROFILE_FRESH_APIFY_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        SELECT pg_catalog.count(*)::INTEGER,
               pg_catalog.count(*) FILTER (
                   WHERE outcome.attempt = 'fresh_apify' AND outcome.source = 'apify'
               )::INTEGER
        INTO v_existing_outcome_count, v_existing_fresh_count
        FROM public.analysis_v2_profile_fetch_outcomes AS outcome
        WHERE outcome.request_id = p_request_id
          AND outcome.job_key = p_job_key;
        IF v_existing_outcome_count IS DISTINCT FROM pg_catalog.cardinality(p_requested_usernames)
           OR v_existing_fresh_count IS DISTINCT FROM pg_catalog.cardinality(p_requested_usernames) THEN
            RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_NOT_FRESH', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_profile_checkpoint_snapshot(p_request_id, p_job_key);
    END IF;

    SELECT COALESCE(
        pg_catalog.array_agg(outcome.value->>'username' ORDER BY outcome.ordinal),
        '{}'::TEXT[]
    )
    INTO v_unresolved
    FROM pg_catalog.jsonb_array_elements(p_outcomes)
        WITH ORDINALITY AS outcome(value, ordinal)
    WHERE outcome.value->>'status' <> 'success';

    v_completed_at := pg_catalog.clock_timestamp();
    INSERT INTO public.analysis_v2_profile_fetch_batches (
        request_id,
        job_key,
        requested_usernames,
        frozen_unresolved_usernames,
        primary_payload_hash,
        primary_completed_at,
        created_at,
        updated_at
    ) VALUES (
        p_request_id,
        p_job_key,
        p_requested_usernames,
        v_unresolved,
        v_payload_hash,
        v_completed_at,
        v_completed_at,
        v_completed_at
    );

    INSERT INTO public.analysis_v2_profile_fetch_outcomes (
        request_id,
        job_key,
        attempt,
        ordinal,
        username,
        source,
        status,
        failure_category,
        http_status,
        request_count,
        latency_ms,
        captured_at,
        profile_snapshot
    )
    SELECT
        p_request_id,
        p_job_key,
        'fresh_apify',
        outcome.ordinal::SMALLINT,
        outcome.value->>'username',
        outcome.value->>'source',
        outcome.value->>'status',
        NULLIF(outcome.value->>'failure_category', ''),
        CASE
            WHEN outcome.value->'http_status' = 'null'::JSONB THEN NULL
            ELSE (outcome.value->>'http_status')::SMALLINT
        END,
        (outcome.value->>'request_count')::SMALLINT,
        (outcome.value->>'latency_ms')::INTEGER,
        (outcome.value->>'captured_at')::TIMESTAMPTZ,
        CASE
            WHEN outcome.value->'profile' = 'null'::JSONB THEN NULL
            ELSE outcome.value->'profile'
        END
    FROM pg_catalog.jsonb_array_elements(p_outcomes)
        WITH ORDINALITY AS outcome(value, ordinal)
    ORDER BY outcome.ordinal;

    RETURN public.analysis_v2_profile_checkpoint_snapshot(p_request_id, p_job_key);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_profile_primary(uuid, text, uuid, text, text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_profile_primary(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_requested_usernames text[], p_outcomes jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_batch public.analysis_v2_profile_fetch_batches%ROWTYPE;
    v_unresolved TEXT[];
    v_payload_hash TEXT;
    v_completed_at TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR NOT public.analysis_v2_valid_profile_username_list(
            p_requested_usernames,
            FALSE
       )
       OR NOT public.analysis_v2_valid_profile_outcomes(
            p_outcomes,
            p_requested_usernames,
            'primary'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- Match the terminal-capable V2 lock order even though this function does not terminalize.
    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND OR v_request.pipeline_version IS DISTINCT FROM 'v2' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_now := pg_catalog.clock_timestamp();
    IF v_request.status NOT IN ('pending', 'processing')
       OR v_job.status <> 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    v_payload_hash := pg_catalog.encode(
        extensions.digest(
            pg_catalog.jsonb_build_object(
                'requested_usernames', pg_catalog.to_jsonb(p_requested_usernames),
                'outcomes', p_outcomes
            )::TEXT,
            'sha256'
        ),
        'hex'
    );

    SELECT batch.*
    INTO v_batch
    FROM public.analysis_v2_profile_fetch_batches AS batch
    WHERE batch.request_id = p_request_id
      AND batch.job_key = p_job_key
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    IF FOUND THEN
        IF v_batch.requested_usernames IS DISTINCT FROM p_requested_usernames
           OR v_batch.primary_payload_hash <> v_payload_hash THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROFILE_PRIMARY_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_profile_checkpoint_snapshot(p_request_id, p_job_key);
    END IF;

    SELECT COALESCE(
        pg_catalog.array_agg(outcome.value->>'username' ORDER BY outcome.ordinal),
        '{}'::TEXT[]
    )
    INTO v_unresolved
    FROM pg_catalog.jsonb_array_elements(p_outcomes)
        WITH ORDINALITY AS outcome(value, ordinal)
    WHERE outcome.value->>'status' <> 'success';

    v_completed_at := clock_timestamp();
    INSERT INTO public.analysis_v2_profile_fetch_batches (
        request_id,
        job_key,
        requested_usernames,
        frozen_unresolved_usernames,
        primary_payload_hash,
        primary_completed_at,
        created_at,
        updated_at
    ) VALUES (
        p_request_id,
        p_job_key,
        p_requested_usernames,
        v_unresolved,
        v_payload_hash,
        v_completed_at,
        v_completed_at,
        v_completed_at
    );

    INSERT INTO public.analysis_v2_profile_fetch_outcomes (
        request_id,
        job_key,
        attempt,
        ordinal,
        username,
        source,
        status,
        failure_category,
        http_status,
        request_count,
        latency_ms,
        captured_at,
        profile_snapshot
    )
    SELECT
        p_request_id,
        p_job_key,
        'primary',
        outcome.ordinal::SMALLINT,
        outcome.value->>'username',
        outcome.value->>'source',
        outcome.value->>'status',
        NULLIF(outcome.value->>'failure_category', ''),
        CASE
            WHEN outcome.value->'http_status' = 'null'::JSONB THEN NULL
            ELSE (outcome.value->>'http_status')::SMALLINT
        END,
        (outcome.value->>'request_count')::SMALLINT,
        (outcome.value->>'latency_ms')::INTEGER,
        (outcome.value->>'captured_at')::TIMESTAMP WITH TIME ZONE,
        CASE
            WHEN outcome.value->'profile' = 'null'::JSONB THEN NULL
            ELSE outcome.value->'profile'
        END
    FROM pg_catalog.jsonb_array_elements(p_outcomes)
        WITH ORDINALITY AS outcome(value, ordinal)
    ORDER BY outcome.ordinal;

    RETURN public.analysis_v2_profile_checkpoint_snapshot(p_request_id, p_job_key);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_profile_provider_canary_run_started(uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_profile_provider_canary_run_started(p_source_request_id uuid, p_repetition integer, p_reservation_token uuid, p_run_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_experiment public.analysis_v2_profile_provider_canary_experiments%ROWTYPE;
    v_run public.analysis_v2_profile_provider_canary_runs%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL OR p_repetition NOT IN (1, 2)
       OR p_reservation_token IS NULL OR p_run_id !~ '^[A-Za-z0-9]{8,64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT canary_run.* INTO v_run
    FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.repetition = p_repetition
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_run.reservation_token IS DISTINCT FROM p_reservation_token THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_run.state = 'starting' THEN
        UPDATE public.analysis_v2_profile_provider_canary_runs AS canary_run
        SET state = 'running', run_id = p_run_id, run_started_at = v_now, updated_at = v_now
        WHERE canary_run.source_request_id = p_source_request_id
          AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
          AND canary_run.repetition = p_repetition
        RETURNING canary_run.* INTO v_run;
    ELSIF v_run.state = 'ambiguous' THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_STATE_CONFLICT', ERRCODE = 'P0001';
    ELSIF v_run.run_id IS DISTINCT FROM p_run_id THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    RETURN public.analysis_v2_profile_provider_canary_run_json(v_run);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_profile_repair(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_profile_repair(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_outcomes jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_batch public.analysis_v2_profile_fetch_batches%ROWTYPE;
    v_repair TEXT[];
    v_payload_hash TEXT;
    v_completed_at TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR pg_catalog.jsonb_typeof(p_outcomes) <> 'array' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND OR v_request.pipeline_version IS DISTINCT FROM 'v2' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_completed_at := pg_catalog.clock_timestamp();
    IF v_request.status NOT IN ('pending', 'processing')
       OR v_job.status <> 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_completed_at THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT batch.*
    INTO v_batch
    FROM public.analysis_v2_profile_fetch_batches AS batch
    WHERE batch.request_id = p_request_id
      AND batch.job_key = p_job_key
    FOR UPDATE;
    v_completed_at := pg_catalog.clock_timestamp();
    IF v_job.lease_expires_at <= v_completed_at THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    v_repair := public.analysis_v2_profile_repair_username_set(p_request_id, p_job_key);
    IF NOT FOUND
       OR v_batch.fallback_completed_at IS NULL
       OR pg_catalog.cardinality(v_repair) = 0
       OR NOT public.analysis_v2_valid_profile_outcomes(
            p_outcomes,
            v_repair,
            'repair'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    v_payload_hash := pg_catalog.encode(
        extensions.digest(p_outcomes::TEXT, 'sha256'),
        'hex'
    );
    IF v_batch.repair_completed_at IS NOT NULL THEN
        IF v_batch.repair_payload_hash <> v_payload_hash THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROFILE_REPAIR_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_profile_checkpoint_snapshot(p_request_id, p_job_key);
    END IF;

    INSERT INTO public.analysis_v2_profile_fetch_outcomes (
        request_id,
        job_key,
        attempt,
        ordinal,
        username,
        source,
        status,
        failure_category,
        http_status,
        request_count,
        latency_ms,
        captured_at,
        profile_snapshot
    )
    SELECT
        p_request_id,
        p_job_key,
        'repair',
        outcome.ordinal::SMALLINT,
        outcome.value->>'username',
        outcome.value->>'source',
        outcome.value->>'status',
        NULLIF(outcome.value->>'failure_category', ''),
        CASE
            WHEN outcome.value->'http_status' = 'null'::JSONB THEN NULL
            ELSE (outcome.value->>'http_status')::SMALLINT
        END,
        (outcome.value->>'request_count')::SMALLINT,
        (outcome.value->>'latency_ms')::INTEGER,
        (outcome.value->>'captured_at')::TIMESTAMP WITH TIME ZONE,
        CASE
            WHEN outcome.value->'profile' = 'null'::JSONB THEN NULL
            ELSE outcome.value->'profile'
        END
    FROM pg_catalog.jsonb_array_elements(p_outcomes)
        WITH ORDINALITY AS outcome(value, ordinal)
    ORDER BY outcome.ordinal;

    v_completed_at := clock_timestamp();
    UPDATE public.analysis_v2_profile_fetch_batches AS batch
    SET repair_usernames = v_repair,
        repair_payload_hash = v_payload_hash,
        repair_completed_at = v_completed_at,
        updated_at = v_completed_at
    WHERE batch.request_id = p_request_id
      AND batch.job_key = p_job_key;

    RETURN public.analysis_v2_profile_checkpoint_snapshot(p_request_id, p_job_key);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_profile_repair_canary_run_started(uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_profile_repair_canary_run_started(p_source_request_id uuid, p_repetition integer, p_reservation_token uuid, p_run_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_run public.analysis_v2_profile_repair_canary_runs%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL
       OR p_repetition NOT IN (1, 2)
       OR p_reservation_token IS NULL
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;
    SELECT canary_run.* INTO v_run
    FROM public.analysis_v2_profile_repair_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-repair-canary-v1'
      AND canary_run.repetition = p_repetition
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.reservation_token IS DISTINCT FROM p_reservation_token THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.state = 'starting' THEN
        UPDATE public.analysis_v2_profile_repair_canary_runs AS canary_run
        SET state = 'running',
            run_id = p_run_id,
            run_started_at = v_now,
            updated_at = v_now
        WHERE canary_run.source_request_id = p_source_request_id
          AND canary_run.canary_version = 'profile-repair-canary-v1'
          AND canary_run.repetition = p_repetition
        RETURNING canary_run.* INTO v_run;
    ELSIF v_run.run_id IS DISTINCT FROM p_run_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_RUN_CONFLICT',
            ERRCODE = 'P0001';
    ELSIF v_run.state = 'ambiguous' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_STATE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    RETURN public.analysis_v2_profile_repair_canary_run_json(v_run);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_progress(uuid, text, uuid, text, text, integer, boolean, jsonb, jsonb, jsonb, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_progress(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_status text, p_progress_bp integer, p_background_processing boolean, p_tracks jsonb, p_active_profile jsonb, p_eta_range jsonb, p_snapshot_fingerprint text, p_event jsonb DEFAULT NULL::jsonb, p_event_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_lock INTEGER;
    v_previous_tracks JSONB;
    v_previous_status TEXT;
    v_previous_background_processing BOOLEAN;
    v_previous_active_profile JSONB;
    v_previous_eta_range JSONB;
    v_previous_fingerprint TEXT;
    v_canonical_tracks JSONB := p_tracks;
    v_canonical_progress_bp INTEGER := p_progress_bp;
    v_track_canonicalized BOOLEAN := FALSE;
    v_effective_fingerprint TEXT := p_snapshot_fingerprint;
    v_effective_event JSONB := p_event;
    v_effective_event_key TEXT := p_event_key;
BEGIN
    EXECUTE 'SELECT 1 FROM public.analysis_preflights AS preflight
             WHERE preflight.consumed_request_id = $1 FOR UPDATE'
        INTO v_lock USING p_request_id;
    EXECUTE 'SELECT 1 FROM public.analysis_requests AS analysis_request
             WHERE analysis_request.id = $1 FOR UPDATE'
        INTO v_lock USING p_request_id;
    EXECUTE 'SELECT 1 FROM public.analysis_pipeline_jobs AS job
             WHERE job.request_id = $1 AND job.job_key = $2 FOR UPDATE'
        INTO v_lock USING p_request_id, p_job_key;
    EXECUTE 'SELECT progress_state.status,
                    progress_state.background_processing,
                    progress_state.tracks,
                    progress_state.active_profile,
                    progress_state.eta_range,
                    progress_state.snapshot_fingerprint
             FROM public.analysis_progress_state AS progress_state
             WHERE progress_state.request_id = $1 FOR UPDATE'
        INTO v_previous_status,
             v_previous_background_processing,
             v_previous_tracks,
             v_previous_active_profile,
             v_previous_eta_range,
             v_previous_fingerprint
        USING p_request_id;

    IF v_previous_tracks IS NOT NULL
       AND public.analysis_v2_valid_progress_tracks(p_tracks) THEN
        v_canonical_tracks := public.analysis_v2_progress_canonical_tracks(
            v_previous_tracks, p_tracks
        );
        v_track_canonicalized := v_canonical_tracks IS DISTINCT FROM p_tracks;
        v_canonical_progress_bp := public.analysis_v2_calculate_progress_bp(
            v_canonical_tracks, p_status
        );
        IF v_canonical_tracks IS NOT DISTINCT FROM v_previous_tracks
           AND v_previous_status IS NOT DISTINCT FROM p_status
           AND v_previous_background_processing IS NOT DISTINCT FROM p_background_processing
           AND v_previous_active_profile IS NOT DISTINCT FROM p_active_profile
           AND v_previous_eta_range IS NOT DISTINCT FROM p_eta_range THEN
            v_effective_fingerprint := v_previous_fingerprint;
            IF v_track_canonicalized THEN
                v_effective_event := NULL;
                v_effective_event_key := NULL;
            END IF;
        ELSIF v_track_canonicalized THEN
            v_effective_fingerprint := public.analysis_v2_progress_snapshot_fingerprint(
                p_status,
                p_background_processing,
                v_canonical_tracks,
                p_active_profile,
                p_eta_range
            );
            v_effective_event := NULL;
            v_effective_event_key := NULL;
        END IF;
    END IF;

    RETURN public.checkpoint_analysis_v2_progress_v1(
        p_request_id,
        p_job_key,
        p_claim_token,
        p_job_input_hash,
        p_status,
        v_canonical_progress_bp,
        p_background_processing,
        v_canonical_tracks,
        p_active_profile,
        p_eta_range,
        v_effective_fingerprint,
        v_effective_event,
        v_effective_event_key
    );
END;
$_$;


--
-- Name: checkpoint_analysis_v2_progress_v1(uuid, text, uuid, text, text, integer, boolean, jsonb, jsonb, jsonb, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_progress_v1(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_status text, p_progress_bp integer, p_background_processing boolean, p_tracks jsonb, p_active_profile jsonb, p_eta_range jsonb, p_snapshot_fingerprint text, p_event jsonb DEFAULT NULL::jsonb, p_event_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_state public.analysis_progress_state%ROWTYPE;
    v_event public.analysis_progress_events%ROWTYPE;
    v_existing_event public.analysis_progress_events%ROWTYPE;
    v_calculated_progress INTEGER;
    v_stored_progress INTEGER;
    v_payload_changed BOOLEAN;
    v_event_new BOOLEAN := FALSE;
    v_advanced BOOLEAN;
    v_next_revision BIGINT;
    v_next_sequence BIGINT;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_status IS NULL
       OR p_status NOT IN ('queued', 'processing', 'completed', 'failed', 'upgrade_required')
       OR p_progress_bp IS NULL
       OR p_background_processing IS NULL
       OR NOT public.analysis_v2_valid_progress_tracks(p_tracks)
       OR NOT public.analysis_v2_valid_progress_active_profile(p_active_profile)
       OR NOT public.analysis_v2_valid_progress_eta(p_eta_range)
       OR p_snapshot_fingerprint IS NULL
       OR p_snapshot_fingerprint !~ '^[a-f0-9]{64}$'
       OR ((p_event IS NULL) IS DISTINCT FROM (p_event_key IS NULL))
       OR (p_event IS NOT NULL AND (
            NOT public.analysis_v2_valid_progress_event(p_event)
            OR p_event_key !~ '^[a-f0-9]{64}$'
       ))
       OR (
            p_status IN ('queued', 'processing')
            AND NOT p_background_processing
       )
       OR (
            p_status IN ('completed', 'failed', 'upgrade_required')
            AND (
                p_background_processing
                OR p_active_profile IS NOT NULL
                OR p_eta_range IS NOT NULL
            )
       )
       OR (
            p_event->>'eventCode' = 'ANALYSIS_COMPLETED'
            AND p_status <> 'completed'
       )
       OR (
            p_status IN ('failed', 'upgrade_required')
            AND p_event IS NOT NULL
       )
       OR (
            p_status = 'completed'
            AND (
                p_event->>'eventCode' IS DISTINCT FROM 'ANALYSIS_COMPLETED'
                OR p_tracks->'relationshipAi'->>'state' IS DISTINCT FROM 'completed'
                OR p_tracks->'interactions'->>'state' IS DISTINCT FROM 'completed'
                OR p_tracks->'finalization'->>'state' IS DISTINCT FROM 'completed'
            )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_INVALID', ERRCODE = 'P0001';
    END IF;

    v_calculated_progress := public.analysis_v2_calculate_progress_bp(p_tracks, p_status);
    IF p_progress_bp IS DISTINCT FROM v_calculated_progress THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_INVALID', ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    -- Refresh after lock acquisition so a lease cannot remain live only at function entry.
    v_now := pg_catalog.clock_timestamp();
    IF v_job.status <> 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT progress_state.*
    INTO v_state
    FROM public.analysis_progress_state AS progress_state
    WHERE progress_state.request_id = p_request_id
    FOR UPDATE;

    IF NOT FOUND THEN
        IF p_job_key <> 'coordinator:bootstrap' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_NOT_READY', ERRCODE = 'P0001';
        END IF;
        v_payload_changed := TRUE;
        v_stored_progress := v_calculated_progress;
        v_next_revision := 1;
        v_next_sequence := CASE WHEN p_event IS NULL THEN 0 ELSE 1 END;
        v_event_new := p_event IS NOT NULL;

        INSERT INTO public.analysis_progress_state (
            request_id,
            revision,
            status,
            progress_bp,
            background_processing,
            tracks,
            active_profile,
            eta_range,
            last_event_seq,
            snapshot_fingerprint,
            created_at,
            updated_at
        ) VALUES (
            p_request_id,
            v_next_revision,
            p_status,
            v_stored_progress,
            p_background_processing,
            p_tracks,
            p_active_profile,
            p_eta_range,
            v_next_sequence,
            p_snapshot_fingerprint,
            v_now,
            v_now
        ) RETURNING * INTO v_state;
    ELSE
        IF v_state.status IN ('completed', 'failed', 'upgrade_required')
           AND p_status IS DISTINCT FROM v_state.status THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_REGRESSION', ERRCODE = 'P0001';
        END IF;
        IF v_state.status = 'processing' AND p_status = 'queued' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_REGRESSION', ERRCODE = 'P0001';
        END IF;
        IF NOT public.analysis_v2_progress_track_transition_valid(
                v_state.tracks->'relationshipAi', p_tracks->'relationshipAi'
            )
           OR NOT public.analysis_v2_progress_track_transition_valid(
                v_state.tracks->'interactions', p_tracks->'interactions'
            )
           OR NOT public.analysis_v2_progress_track_transition_valid(
                v_state.tracks->'finalization', p_tracks->'finalization'
            ) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_REGRESSION', ERRCODE = 'P0001';
        END IF;

        v_payload_changed := v_state.status IS DISTINCT FROM p_status
            OR v_state.background_processing IS DISTINCT FROM p_background_processing
            OR v_state.tracks IS DISTINCT FROM p_tracks
            OR v_state.active_profile IS DISTINCT FROM p_active_profile
            OR v_state.eta_range IS DISTINCT FROM p_eta_range;
        IF v_payload_changed = (v_state.snapshot_fingerprint = p_snapshot_fingerprint) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_CONFLICT', ERRCODE = 'P0001';
        END IF;

        IF p_event IS NOT NULL THEN
            SELECT progress_event.*
            INTO v_existing_event
            FROM public.analysis_progress_events AS progress_event
            WHERE progress_event.request_id = p_request_id
              AND progress_event.event_key = p_event_key
            FOR UPDATE;
            IF FOUND THEN
                IF v_existing_event.snapshot_fingerprint IS DISTINCT FROM p_snapshot_fingerprint
                   OR v_existing_event.event_state IS DISTINCT FROM p_event->>'state'
                   OR v_existing_event.event_code IS DISTINCT FROM p_event->>'eventCode'
                   OR v_existing_event.copy_code IS DISTINCT FROM p_event->>'copyCode'
                   OR v_existing_event.aggregate_count IS DISTINCT FROM (CASE
                        WHEN pg_catalog.jsonb_typeof(p_event->'aggregateCount') = 'null' THEN NULL
                        ELSE (p_event->>'aggregateCount')::INTEGER
                   END) THEN
                    RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_EVENT_CONFLICT', ERRCODE = 'P0001';
                END IF;
            ELSE
                v_event_new := TRUE;
            END IF;
        END IF;

        v_advanced := v_payload_changed OR v_event_new;
        v_next_revision := v_state.revision + CASE WHEN v_advanced THEN 1 ELSE 0 END;
        v_next_sequence := v_state.last_event_seq + CASE WHEN v_event_new THEN 1 ELSE 0 END;
        IF v_next_revision > 9007199254740991 OR v_next_sequence > 9007199254740991 THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROGRESS_CONFLICT', ERRCODE = 'P0001';
        END IF;
        v_stored_progress := GREATEST(v_state.progress_bp, v_calculated_progress);

        IF v_advanced THEN
            UPDATE public.analysis_progress_state AS progress_state
            SET revision = v_next_revision,
                status = p_status,
                progress_bp = v_stored_progress,
                background_processing = p_background_processing,
                tracks = p_tracks,
                active_profile = p_active_profile,
                eta_range = p_eta_range,
                last_event_seq = v_next_sequence,
                snapshot_fingerprint = p_snapshot_fingerprint,
                updated_at = v_now
            WHERE progress_state.request_id = p_request_id
            RETURNING * INTO v_state;
        END IF;
    END IF;

    IF v_event_new THEN
        INSERT INTO public.analysis_progress_events (
            request_id,
            seq,
            event_key,
            revision,
            snapshot_fingerprint,
            occurred_at,
            event_state,
            event_code,
            copy_code,
            aggregate_count
        ) VALUES (
            p_request_id,
            v_state.last_event_seq,
            p_event_key,
            v_state.revision,
            p_snapshot_fingerprint,
            v_now,
            p_event->>'state',
            p_event->>'eventCode',
            p_event->>'copyCode',
            CASE
                WHEN pg_catalog.jsonb_typeof(p_event->'aggregateCount') = 'null' THEN NULL
                ELSE (p_event->>'aggregateCount')::INTEGER
            END
        ) RETURNING * INTO v_event;
    ELSIF p_event IS NOT NULL THEN
        v_event := v_existing_event;
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'snapshot', public.analysis_v2_progress_snapshot_json(v_state),
        'event', CASE
            WHEN p_event IS NULL THEN NULL
            ELSE public.analysis_v2_progress_event_json(v_event)
        END,
        'advanced', COALESCE(v_payload_changed, FALSE) OR v_event_new
    );
END;
$_$;


--
-- Name: checkpoint_analysis_v2_provider_run_started(uuid, text, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_provider_run_started(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_reservation_token uuid, p_run_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight_id UUID;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_run public.analysis_v2_provider_runs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_operation_key IS NULL
       OR NOT public.analysis_v2_valid_provider_operation_key(p_operation_key)
       OR p_reservation_token IS NULL
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.id
    INTO v_preflight_id
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND OR v_request.status NOT IN ('pending', 'processing') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_ACTIVE',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.reservation_token IS DISTINCT FROM p_reservation_token
       OR v_run.job_claim_token IS DISTINCT FROM p_claim_token THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.status <> 'starting' THEN
        IF v_run.run_id IS DISTINCT FROM p_run_id THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_RUN_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_provider_run_json(v_run);
    END IF;

    UPDATE public.analysis_v2_provider_runs AS provider_run
    SET status = 'running',
        run_id = p_run_id,
        run_started_at = v_now,
        updated_at = v_now
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    RETURNING provider_run.* INTO v_run;

    RETURN public.analysis_v2_provider_run_json(v_run);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_provider_run_terminal(uuid, text, uuid, text, uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_provider_run_terminal(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_reservation_token uuid, p_run_id text, p_status text, p_actual_usage_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight_id UUID;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_run public.analysis_v2_provider_runs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_operation_key IS NULL
       OR NOT public.analysis_v2_valid_provider_operation_key(p_operation_key)
       OR p_reservation_token IS NULL
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_status IS NULL
       OR p_status NOT IN ('succeeded', 'failed', 'aborted', 'timed_out')
       OR (
            p_actual_usage_usd IS NOT NULL
            AND (
                p_actual_usage_usd NOT BETWEEN 0 AND 100000
                OR p_actual_usage_usd <> pg_catalog.round(p_actual_usage_usd, 12)
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- Terminal persistence deliberately takes the canonical locks but does not require a live
    -- lease. The row's stored reservation and claim are the response-loss fence.
    SELECT preflight.id
    INTO v_preflight_id
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.reservation_token IS DISTINCT FROM p_reservation_token
       OR v_run.job_claim_token IS DISTINCT FROM p_claim_token THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.run_id IS DISTINCT FROM p_run_id OR v_run.status = 'starting' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_RUN_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.status IN ('succeeded', 'failed', 'aborted', 'timed_out') THEN
        IF v_run.status IS DISTINCT FROM p_status THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_TERMINAL_CONFLICT',
                ERRCODE = 'P0001';
        END IF;

        -- Null is "not yet observed". It may be replayed after reconciliation; a concrete
        -- amount can fill the value once but can never replace another concrete amount.
        IF p_actual_usage_usd IS NOT NULL
           AND v_run.actual_usage_usd IS NOT NULL
           AND v_run.actual_usage_usd IS DISTINCT FROM p_actual_usage_usd THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_TERMINAL_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        IF p_actual_usage_usd IS NOT NULL AND v_run.actual_usage_usd IS NULL THEN
            UPDATE public.analysis_v2_provider_runs AS provider_run
            SET actual_usage_usd = p_actual_usage_usd,
                usage_reconciled_at = v_now,
                updated_at = v_now
            WHERE provider_run.request_id = p_request_id
              AND provider_run.job_key = p_job_key
              AND provider_run.operation_key = p_operation_key
            RETURNING provider_run.* INTO v_run;
        END IF;
        RETURN public.analysis_v2_provider_run_json(v_run);
    END IF;

    IF v_run.status <> 'running' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_STATE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_v2_provider_runs AS provider_run
    SET status = p_status,
        actual_usage_usd = p_actual_usage_usd,
        terminalized_at = v_now,
        usage_reconciled_at = CASE
            WHEN p_actual_usage_usd IS NULL THEN NULL
            ELSE v_now
        END,
        updated_at = v_now
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    RETURNING provider_run.* INTO v_run;

    RETURN public.analysis_v2_provider_run_json(v_run);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_relationship_side(uuid, text, uuid, text, text, integer, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_relationship_side(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_side text, p_declared_count integer, p_input_hash text, p_result_hash text, p_provider text, p_provider_run_id text, p_provider_operation_key text, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_side public.analysis_v2_relationship_sides%ROWTYPE;
    v_provider_run public.analysis_v2_provider_runs%ROWTYPE;
    v_provider_credential_slot TEXT;
    v_collected_count INTEGER;
    v_coverage_bps INTEGER;
    v_computed_hash TEXT;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_job_key <> 'track:relationships:collect'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[0-9a-f]{64}$'
       OR p_side IS NULL
       OR p_side NOT IN ('followers', 'following')
       OR p_declared_count IS NULL
       OR p_declared_count NOT BETWEEN 0 AND 1200
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_result_hash IS NULL
       OR p_result_hash !~ '^[0-9a-f]{64}$'
       OR p_provider IS NULL
       OR p_provider NOT IN ('apify', 'coderx', 'selfhosted_auth')
       OR p_provider_run_id IS NULL
       OR p_provider_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_provider_operation_key IS NULL
       OR p_provider_operation_key !~
            ('^relationship-' || p_side || ':[0-9a-f]{64}$')
       OR NOT public.analysis_v2_valid_relationship_rows(p_rows) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_collected_count := pg_catalog.jsonb_array_length(p_rows);
    IF v_collected_count > p_declared_count
       OR v_collected_count * 100 < p_declared_count * 99 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RELATIONSHIP_INCOMPLETE',
            ERRCODE = 'P0001';
    END IF;
    v_coverage_bps := CASE
        WHEN p_declared_count = 0 THEN 10000
        ELSE (v_collected_count * 10000) / p_declared_count
    END;
    v_computed_hash := public.analysis_v2_relationship_rows_hash(p_side, p_rows);
    IF v_computed_hash IS DISTINCT FROM p_result_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.status <> 'consumed'
       OR v_preflight.target_followers_count IS NULL
       OR v_preflight.target_following_count IS NULL
       OR p_declared_count IS DISTINCT FROM (CASE p_side
            WHEN 'followers' THEN v_preflight.target_followers_count
            ELSE v_preflight.target_following_count
       END) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RELATIONSHIP_INCOMPLETE',
            ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR p_declared_count > (
            v_request.analysis_scope_snapshot->'relationshipCapacity'->>p_side
       )::INTEGER THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_NOT_ACTIVE',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_job.job_key <> 'track:relationships:collect'
       OR v_job.track <> 'relationships'
       OR v_job.kind <> 'collection'
       OR v_job.batch IS NOT NULL
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    v_now := pg_catalog.clock_timestamp();
    IF v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    IF p_provider <> 'selfhosted_auth'
       AND NOT public.analysis_v2_valid_provider_evidence_source(
        p_request_id, p_job_key, p_claim_token, p_provider_operation_key,
        p_input_hash, p_provider, p_provider_run_id, NULL
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;


    IF p_provider = 'selfhosted_auth' THEN
        SELECT source.account_slot INTO STRICT v_provider_credential_slot
        FROM public.analysis_v2_load_selfhosted_auth_evidence_source(
            p_request_id, p_job_key, p_claim_token, p_provider_operation_key,
            p_input_hash, p_provider, p_provider_run_id, 'primary'
        ) AS source;
    ELSE
        SELECT source.* INTO STRICT v_provider_run
        FROM public.analysis_v2_load_provider_evidence_source(
            p_request_id, p_job_key, p_claim_token, p_provider_operation_key,
            p_input_hash, p_provider, p_provider_run_id, NULL
        ) AS source;
        v_provider_credential_slot := v_provider_run.credential_slot;
    END IF;
    SELECT relationship_side.*
    INTO v_side
    FROM public.analysis_v2_relationship_sides AS relationship_side
    WHERE relationship_side.request_id = p_request_id
      AND relationship_side.job_key = p_job_key
      AND relationship_side.side = p_side
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    IF FOUND THEN
        IF v_side.provider IS DISTINCT FROM p_provider
           OR v_side.provider_run_id IS DISTINCT FROM p_provider_run_id
           OR v_side.provider_operation_key IS DISTINCT FROM p_provider_operation_key
           OR v_side.provider_credential_slot IS DISTINCT FROM v_provider_credential_slot
           OR v_side.declared_count IS DISTINCT FROM p_declared_count
           OR v_side.collected_count IS DISTINCT FROM v_collected_count
           OR v_side.coverage_bps IS DISTINCT FROM v_coverage_bps
           OR v_side.input_hash IS DISTINCT FROM p_input_hash
           OR v_side.result_hash IS DISTINCT FROM p_result_hash THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_RELATIONSHIP_SIDE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        UPDATE public.analysis_v2_relationship_sides AS relationship_side
        SET job_claim_token = p_claim_token,
            updated_at = v_now
        WHERE relationship_side.request_id = p_request_id
          AND relationship_side.job_key = p_job_key
          AND relationship_side.side = p_side
        RETURNING relationship_side.* INTO v_side;
        RETURN public.analysis_v2_relationship_side_json(v_side);
    END IF;

    INSERT INTO public.analysis_v2_relationship_sides (
        request_id,
        job_key,
        side,
        job_claim_token,
        provider,
        provider_run_id,
        provider_operation_key,
        provider_credential_slot,
        declared_count,
        collected_count,
        coverage_bps,
        input_hash,
        result_hash,
        completed_at,
        created_at,
        updated_at
    ) VALUES (
        p_request_id,
        p_job_key,
        p_side,
        p_claim_token,
        p_provider,
        p_provider_run_id,
        p_provider_operation_key,
        v_provider_credential_slot,
        p_declared_count,
        v_collected_count,
        v_coverage_bps,
        p_input_hash,
        p_result_hash,
        v_now,
        v_now,
        v_now
    )
    RETURNING * INTO v_side;

    INSERT INTO public.analysis_v2_relationship_rows (
        request_id,
        job_key,
        side,
        ordinal,
        username,
        is_private,
        is_verified,
        full_name,
        profile_pic_url
    )
    SELECT
        p_request_id,
        p_job_key,
        p_side,
        relationship_row.ordinal::SMALLINT,
        relationship_row.value->>'username',
        (relationship_row.value->>'is_private')::BOOLEAN,
        (relationship_row.value->>'is_verified')::BOOLEAN,
        NULLIF(relationship_row.value->>'full_name', ''),
        NULLIF(relationship_row.value->>'profile_pic_url', '')
    FROM pg_catalog.jsonb_array_elements(p_rows)
        WITH ORDINALITY AS relationship_row(value, ordinal)
    ORDER BY relationship_row.ordinal;

    RETURN public.analysis_v2_relationship_side_json(v_side);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_relationship_side_not_applicable(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_relationship_side_not_applicable(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_side text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_side public.analysis_v2_relationship_sides%ROWTYPE;
    v_input_hash TEXT;
    v_result_hash TEXT;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_job_key <> 'track:relationships:collect'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[0-9a-f]{64}$'
       OR p_side IS NULL
       OR p_side NOT IN ('followers', 'following') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_input_hash := public.analysis_v2_relationship_not_applicable_input_hash(p_side);
    v_result_hash := public.analysis_v2_relationship_rows_hash(p_side, '[]'::JSONB);

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.status <> 'consumed'
       OR v_preflight.target_followers_count IS NULL
       OR v_preflight.target_following_count IS NULL
       OR (CASE p_side
            WHEN 'followers' THEN v_preflight.target_followers_count
            ELSE v_preflight.target_following_count
       END) IS DISTINCT FROM 0 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RELATIONSHIP_INCOMPLETE',
            ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR v_request.analysis_scope_snapshot IS NULL
       OR v_request.analysis_scope_snapshot->'relationshipCapacity'->>p_side IS NULL
       OR (v_request.analysis_scope_snapshot->'relationshipCapacity'->>p_side)::INTEGER < 0 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_NOT_ACTIVE',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_job.job_key <> 'track:relationships:collect'
       OR v_job.track <> 'relationships'
       OR v_job.kind <> 'collection'
       OR v_job.batch IS NOT NULL
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    v_now := pg_catalog.clock_timestamp();
    IF v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT relationship_side.*
    INTO v_side
    FROM public.analysis_v2_relationship_sides AS relationship_side
    WHERE relationship_side.request_id = p_request_id
      AND relationship_side.job_key = p_job_key
      AND relationship_side.side = p_side
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    IF FOUND THEN
        IF v_side.source_status IS DISTINCT FROM 'not_applicable'
           OR v_side.provider IS NOT NULL
           OR v_side.provider_run_id IS NOT NULL
           OR v_side.provider_operation_key IS NOT NULL
           OR v_side.provider_credential_slot IS NOT NULL
           OR v_side.declared_count IS DISTINCT FROM 0
           OR v_side.collected_count IS DISTINCT FROM 0
           OR v_side.coverage_bps IS DISTINCT FROM 10000
           OR v_side.input_hash IS DISTINCT FROM v_input_hash
           OR v_side.result_hash IS DISTINCT FROM v_result_hash THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_RELATIONSHIP_SIDE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        UPDATE public.analysis_v2_relationship_sides AS relationship_side
        SET job_claim_token = p_claim_token,
            updated_at = v_now
        WHERE relationship_side.request_id = p_request_id
          AND relationship_side.job_key = p_job_key
          AND relationship_side.side = p_side
        RETURNING relationship_side.* INTO v_side;
        RETURN public.analysis_v2_relationship_side_json(v_side);
    END IF;

    INSERT INTO public.analysis_v2_relationship_sides (
        request_id,
        job_key,
        side,
        job_claim_token,
        source_status,
        provider,
        provider_run_id,
        provider_operation_key,
        provider_credential_slot,
        declared_count,
        collected_count,
        coverage_bps,
        input_hash,
        result_hash,
        completed_at,
        created_at,
        updated_at
    ) VALUES (
        p_request_id,
        p_job_key,
        p_side,
        p_claim_token,
        'not_applicable',
        NULL,
        NULL,
        NULL,
        NULL,
        0,
        0,
        10000,
        v_input_hash,
        v_result_hash,
        v_now,
        v_now,
        v_now
    )
    RETURNING * INTO v_side;

    RETURN public.analysis_v2_relationship_side_json(v_side);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_revenue_resolver_outcomes_v1(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_revenue_resolver_outcomes_v1(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_pass public.analysis_revenue_resolver_passes%ROWTYPE;
BEGIN
    IF p_job_key IS DISTINCT FROM 'coordinator:join:primary-evidence'
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_rows IS NULL
       OR pg_catalog.jsonb_typeof(p_rows) <> 'array'
       OR pg_catalog.jsonb_array_length(p_rows) > 40
       OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR NOT (item.value ?& ARRAY[
                    'candidateId', 'classification', 'operationKey', 'resultHash'
               ])
               OR item.value - ARRAY[
                    'candidateId', 'classification', 'operationKey', 'resultHash'
               ] <> '{}'::JSONB
               OR item.value->>'candidateId' !~ '^[A-Za-z0-9._:-]{1,128}$'
               OR item.value->>'classification' NOT IN ('verified_female', 'verified_non_female')
               OR item.value->>'operationKey' !~ '^gender-resolution:[a-f0-9]{64}$'
               OR item.value->>'resultHash' !~ '^[a-f0-9]{64}$'
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF (
        SELECT pg_catalog.count(*)
        FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
    ) <> (
        SELECT pg_catalog.count(DISTINCT item.value->>'candidateId')
        FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    PERFORM public.analysis_revenue_ai_cost_assert_lineage_v1(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash, TRUE
    );
    PERFORM public.analysis_revenue_ai_cost_assert_parent_v1(p_request_id);
    SELECT * INTO v_pass FROM public.analysis_revenue_resolver_passes
    WHERE request_id = p_request_id FOR UPDATE;
    IF v_pass.request_id IS NULL
       OR v_pass.job_key IS DISTINCT FROM p_job_key
       OR v_pass.job_input_hash IS DISTINCT FROM p_job_input_hash THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
        LEFT JOIN public.analysis_v2_candidate_feature_rows AS feature
          ON feature.request_id = p_request_id
         AND feature.candidate_id = item.value->>'candidateId'
        LEFT JOIN public.analysis_v2_ai_result_checkpoints AS ai_result
          ON ai_result.request_id = p_request_id
         AND ai_result.job_key = p_job_key
         AND ai_result.operation_key = item.value->>'operationKey'
         AND ai_result.stage = 'genderResolution'
         AND ai_result.result_hash = item.value->>'resultHash'
        LEFT JOIN public.analysis_revenue_resolver_capacity_reservations AS reservation
          ON reservation.request_id = p_request_id
         AND reservation.operation_key_hash = pg_catalog.encode(
                extensions.digest(
                    pg_catalog.convert_to(item.value->>'operationKey', 'UTF8'), 'sha256'
                ), 'hex'
            )
         AND reservation.disposition = 'accepted'
        WHERE feature.request_id IS NULL
           OR feature.baseline_classification NOT IN (
                'unresolved', 'unresolved_stage_conflict',
                'media_unavailable', 'analysis_unavailable'
           )
           OR ai_result.request_id IS NULL
           OR reservation.request_id IS NULL
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
        JOIN public.analysis_revenue_resolver_outcome_overlays AS existing
          ON existing.request_id = p_request_id
         AND existing.candidate_id = item.value->>'candidateId'
        WHERE existing.job_key IS DISTINCT FROM p_job_key
           OR existing.job_input_hash IS DISTINCT FROM p_job_input_hash
           OR existing.classification IS DISTINCT FROM item.value->>'classification'
           OR existing.operation_key IS DISTINCT FROM item.value->>'operationKey'
           OR existing.result_hash IS DISTINCT FROM item.value->>'resultHash'
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_DRIFT';
    END IF;

    INSERT INTO public.analysis_revenue_resolver_outcome_overlays(
        request_id, candidate_id, job_key, job_input_hash, classification, operation_key, result_hash
    )
    SELECT p_request_id, item.value->>'candidateId', p_job_key, p_job_input_hash,
        item.value->>'classification', item.value->>'operationKey', item.value->>'resultHash'
    FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
    ON CONFLICT (request_id, candidate_id) DO NOTHING;

    -- The overlay is deliberately the sole resolver authority.  When a
    -- baseline row already has a feature, its public result materialization
    -- is reconstructed server-side from the sealed profile-AI checkpoint;
    -- the caller never sends feature content through this revenue RPC.  Rows
    -- with no feature (the normal analysis/media-unavailable case) retain
    -- only the overlay: they count as resolved primary membership, while
    -- screening naturally excludes them because no detail feature exists.
    WITH resolver_rows AS (
        SELECT item.value AS item
        FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
    ), source_feature AS (
        SELECT resolver.item, source.outcome
        FROM resolver_rows AS resolver
        JOIN LATERAL (
            SELECT outcome.value AS outcome
            FROM public.analysis_v2_ai_scoring_stage_checkpoints AS checkpoint
            CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
                checkpoint.payload->'outcomes'
            ) AS outcome(value)
            WHERE checkpoint.request_id = p_request_id
              AND checkpoint.stage_kind = 'profile_ai_batch'
              AND outcome.value->>'candidateId' = resolver.item->>'candidateId'
              AND pg_catalog.jsonb_typeof(outcome.value->'feature') = 'object'
              AND pg_catalog.jsonb_typeof(
                    outcome.value->'feature'->'features'
              ) = 'object'
            LIMIT 1
        ) AS source ON TRUE
        WHERE (source.outcome->'feature'->'features'->>'appearanceGrade') ~ '^[1-5]$'
          AND (source.outcome->'feature'->'features'->>'exposureScore') ~ '^[0-5]$'
          AND pg_catalog.jsonb_typeof(
                source.outcome->'feature'->'features'->'oneLineOverview'
              ) = 'string'
          AND pg_catalog.char_length(
                source.outcome->'feature'->'features'->>'oneLineOverview'
              ) BETWEEN 1 AND 180
    )
    UPDATE public.analysis_v2_candidate_feature_rows AS feature
       SET terminal_classification = source.item->>'classification',
           classification_source = 'gender_resolution',
           gender_resolution_status = 'ready_applied',
           gender_resolution_operation_key = source.item->>'operationKey',
           gender_resolution_result_hash = source.item->>'resultHash',
           appearance_grade = CASE WHEN source.item->>'classification' = 'verified_female'
                THEN (source.outcome->'feature'->'features'->>'appearanceGrade')::SMALLINT
                ELSE NULL END,
           exposure_score = CASE WHEN source.item->>'classification' = 'verified_female'
                THEN (source.outcome->'feature'->'features'->>'exposureScore')::SMALLINT
                ELSE NULL END,
           is_business_account = CASE WHEN source.item->>'classification' = 'verified_female'
                THEN COALESCE(
                    source.outcome->>'accountContextOverride',
                    source.outcome->'feature'->'features'->>'accountContext'
                ) IN ('individual_creator', 'official_group_or_brand')
                ELSE NULL END,
           feature_partner_evidence_strong = CASE
                WHEN source.item->>'classification' = 'verified_female' THEN (
                    source.outcome->'feature'->'features'->>'partnerExclusionContext' = 'none'
                    AND (
                        source.outcome->'feature'->'features'->>'marriageEvidence' = 'strong'
                        OR source.outcome->'feature'->'features'->>'partnerEvidence' = 'strong'
                    )
                )
                ELSE NULL
            END,
           one_line_overview = CASE WHEN source.item->>'classification' = 'verified_female'
                THEN source.outcome->'feature'->'features'->>'oneLineOverview' ELSE NULL END
     FROM source_feature AS source
     WHERE feature.request_id = p_request_id
       AND feature.candidate_id = source.item->>'candidateId'
       -- The reviewed feature-row invariant permits a resolver mutation only
       -- from the existing unresolved baselines.  Analysis/media-unavailable
       -- candidates are intentionally featureless and remain overlay-only;
       -- this guards a malformed historical rich payload from accidentally
       -- relaxing that invariant.
       AND feature.baseline_classification IN (
            'unresolved', 'unresolved_stage_conflict'
       );

    RETURN public.load_analysis_v2_revenue_resolver_outcomes_v1(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
END;
$_$;


--
-- Name: checkpoint_analysis_v2_reverse_likes(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_reverse_likes(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_rows JSONB;
    v_count INTEGER;
    v_hash TEXT;
    v_existing public.analysis_v2_reverse_like_manifests%ROWTYPE;
BEGIN
    IF p_rows IS NULL OR pg_catalog.jsonb_typeof(p_rows) <> 'array'
       OR pg_catalog.jsonb_array_length(p_rows) > 900
       OR pg_catalog.octet_length(p_rows::TEXT) > 1048576
       OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR NOT (item.value ?& ARRAY[
                    'candidateId', 'status', 'componentScore', 'evidenceRefIds'
               ])
               OR item.value - ARRAY[
                    'candidateId', 'status', 'componentScore', 'evidenceRefIds'
               ] <> '{}'::JSONB
               OR item.value->>'candidateId' !~ '^[A-Za-z0-9._:-]{1,128}$'
               OR item.value->>'status' NOT IN ('observed', 'not_observed', 'not_collected')
               OR item.value->>'componentScore' NOT IN ('0', '3', '5')
               OR pg_catalog.jsonb_typeof(item.value->'evidenceRefIds') <> 'array'
               OR pg_catalog.jsonb_array_length(item.value->'evidenceRefIds') > 8
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;
    v_job := public.analysis_v2_assert_result_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    IF v_job.job_key <> 'track:reverse-likes:collect'
       OR v_job.track <> 'reverse_likes' OR v_job.kind <> 'collection' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(item.value ORDER BY item.value->>'candidateId'), '[]')
    INTO v_rows FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value);
    v_count := pg_catalog.jsonb_array_length(v_rows);
    IF v_count <> (
        SELECT pg_catalog.count(*) FROM public.analysis_v2_preliminary_score_rows AS score
        WHERE score.request_id = p_request_id
    ) OR EXISTS (
        SELECT 1 FROM public.analysis_v2_preliminary_score_rows AS score
        WHERE score.request_id = p_request_id
          AND NOT EXISTS (
              SELECT 1 FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
              WHERE item.value->>'candidateId' = score.candidate_id
          )
    ) OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value)
        JOIN public.analysis_v2_preliminary_score_rows AS preliminary
          ON preliminary.request_id = p_request_id
         AND preliminary.candidate_id = item.value->>'candidateId'
        WHERE (
                preliminary.verification_shortlist_rank IS NULL
                AND (
                    item.value->>'status' <> 'not_collected'
                    OR item.value->>'componentScore' <> '0'
                    OR pg_catalog.jsonb_array_length(item.value->'evidenceRefIds') <> 0
                )
              )
           OR (
                item.value->>'status' = 'observed'
                AND (
                    item.value->>'componentScore' NOT IN ('3', '5')
                    OR pg_catalog.jsonb_array_length(item.value->'evidenceRefIds') = 0
                )
              )
           OR (
                item.value->>'status' <> 'observed'
                AND (
                    item.value->>'componentScore' <> '0'
                    OR pg_catalog.jsonb_array_length(item.value->'evidenceRefIds') <> 0
                )
              )
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    v_hash := public.analysis_v2_result_staging_hash('reverse_likes', NULL, v_rows);
    SELECT manifest.* INTO v_existing
    FROM public.analysis_v2_reverse_like_manifests AS manifest
    WHERE manifest.request_id = p_request_id FOR UPDATE;
    IF FOUND THEN
        IF v_existing.producer_job_key <> p_job_key
           OR v_existing.producer_input_hash <> p_job_input_hash
           OR v_existing.producer_claim_token <> p_claim_token
           OR v_existing.item_count <> v_count OR v_existing.result_hash <> v_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_result_checkpoint_json(
            p_request_id, p_job_key, NULL, v_count, v_count, v_hash
        );
    END IF;
    INSERT INTO public.analysis_v2_reverse_like_manifests (
        request_id, producer_job_key, producer_input_hash, producer_claim_token,
        item_count, result_hash
    ) VALUES (p_request_id, p_job_key, p_job_input_hash, p_claim_token, v_count, v_hash);
    INSERT INTO public.analysis_v2_reverse_like_rows (
        request_id, candidate_id, reverse_like_status, component_score, evidence_ref_ids
    )
    SELECT p_request_id, item.value->>'candidateId', item.value->>'status',
        (item.value->>'componentScore')::NUMERIC,
        ARRAY(
            SELECT evidence.value
            FROM pg_catalog.jsonb_array_elements_text(item.value->'evidenceRefIds')
                WITH ORDINALITY AS evidence(value, ordinality)
            ORDER BY evidence.ordinality
        )
    FROM pg_catalog.jsonb_array_elements(v_rows) AS item(value);
    RETURN public.analysis_v2_result_checkpoint_json(
        p_request_id, p_job_key, NULL, v_count, v_count, v_hash
    );
END;
$_$;


--
-- Name: checkpoint_analysis_v2_selfhosted_auth_run(uuid, text, uuid, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_selfhosted_auth_run(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_operation_key text, p_input_hash text, p_run_id text, p_account_slot text, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_receipt public.analysis_v2_selfhosted_auth_runs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_claim_token IS NULL
       OR p_job_key IS NULL
       OR p_job_input_hash IS NULL
       OR p_operation_key IS NULL
       OR p_input_hash IS NULL
       OR p_run_id IS NULL
       OR p_account_slot IS NULL
       OR p_items IS NULL
       OR p_job_key NOT IN (
            'track:relationships:collect',
            'track:target-evidence:collect',
            'track:reverse-likes:collect'
       )
       OR p_job_input_hash !~ '^[0-9a-f]{64}$'
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_run_id !~ '^[0-9a-f]{32}$'
       OR p_account_slot <> 'primary'
       OR pg_catalog.jsonb_typeof(p_items) <> 'array'
       OR pg_catalog.jsonb_array_length(p_items) > (CASE
            WHEN p_operation_key ~ '^relationship-' THEN 1200
            WHEN p_operation_key ~ '^target-comments:' THEN 150
            ELSE 1500
       END)
       OR pg_catalog.octet_length(p_items::TEXT) > 4194304
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_items) AS item(value)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
       )
       OR p_operation_key !~ '^(relationship-(followers|following)|target-(likers|comments)|candidate-likers):[0-9a-f]{64}$'
       OR (
            p_job_key = 'track:relationships:collect'
            AND p_operation_key !~ '^relationship-(followers|following):[0-9a-f]{64}$'
       )
       OR (
            p_job_key = 'track:target-evidence:collect'
            AND p_operation_key !~ '^target-(likers|comments):[0-9a-f]{64}$'
       )
       OR (
            p_job_key = 'track:reverse-likes:collect'
            AND p_operation_key !~ '^candidate-likers:[0-9a-f]{64}$'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SELFHOSTED_AUTH_RUN_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= pg_catalog.clock_timestamp()
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SELFHOSTED_AUTH_RUN_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT receipt.* INTO v_receipt
    FROM public.analysis_v2_selfhosted_auth_runs AS receipt
    WHERE receipt.request_id = p_request_id
      AND receipt.job_key = p_job_key
      AND receipt.operation_key = p_operation_key
    FOR UPDATE;
    IF FOUND THEN
        IF v_receipt.input_hash IS DISTINCT FROM p_input_hash
           OR v_receipt.run_id IS DISTINCT FROM p_run_id
           OR v_receipt.account_slot IS DISTINCT FROM p_account_slot
           OR v_receipt.items IS DISTINCT FROM p_items THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_SELFHOSTED_AUTH_RUN_CONFLICT', ERRCODE = 'P0001';
        END IF;
        UPDATE public.analysis_v2_selfhosted_auth_runs AS receipt
        SET job_claim_token = p_claim_token,
            updated_at = pg_catalog.clock_timestamp()
        WHERE receipt.request_id = p_request_id
          AND receipt.job_key = p_job_key
          AND receipt.operation_key = p_operation_key
        RETURNING receipt.* INTO v_receipt;
    ELSE
        INSERT INTO public.analysis_v2_selfhosted_auth_runs (
            request_id, job_key, operation_key, input_hash, job_claim_token, run_id, account_slot,
            items
        ) VALUES (
            p_request_id, p_job_key, p_operation_key, p_input_hash,
            p_claim_token, p_run_id, p_account_slot, p_items
        ) ON CONFLICT DO NOTHING
        RETURNING * INTO v_receipt;

        -- A retry with the same claim may race between the initial SELECT and
        -- INSERT. Treat the winner's identical receipt as an idempotent replay;
        -- a run_id collision on a different operation remains a hard conflict.
        IF NOT FOUND THEN
            SELECT receipt.* INTO v_receipt
            FROM public.analysis_v2_selfhosted_auth_runs AS receipt
            WHERE receipt.request_id = p_request_id
              AND receipt.job_key = p_job_key
              AND receipt.operation_key = p_operation_key
            FOR UPDATE;
            IF NOT FOUND
               OR v_receipt.input_hash IS DISTINCT FROM p_input_hash
               OR v_receipt.run_id IS DISTINCT FROM p_run_id
               OR v_receipt.account_slot IS DISTINCT FROM p_account_slot
               OR v_receipt.items IS DISTINCT FROM p_items THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ANALYSIS_V2_SELFHOSTED_AUTH_RUN_CONFLICT', ERRCODE = 'P0001';
            END IF;
            UPDATE public.analysis_v2_selfhosted_auth_runs AS receipt
            SET job_claim_token = p_claim_token,
                updated_at = pg_catalog.clock_timestamp()
            WHERE receipt.request_id = p_request_id
              AND receipt.job_key = p_job_key
              AND receipt.operation_key = p_operation_key
            RETURNING receipt.* INTO v_receipt;
        END IF;
    END IF;

    RETURN public.analysis_v2_selfhosted_auth_run_json(v_receipt);
END;
$_$;


--
-- Name: checkpoint_analysis_v2_target_evidence(uuid, text, uuid, text, text, text, text, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_analysis_v2_target_evidence(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_target_username text, p_excluded_username text, p_input_hash text, p_result_hash text, p_liker_source jsonb, p_comment_source jsonb, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_manifest public.analysis_v2_target_evidence_manifests%ROWTYPE;
    v_liker_provider_run public.analysis_v2_provider_runs%ROWTYPE;
    v_comment_provider_run public.analysis_v2_provider_runs%ROWTYPE;
    v_computed_hash TEXT;
    v_liker_source_hash TEXT;
    v_comment_source_hash TEXT;
    v_interactor_count INTEGER;
    v_liker_count INTEGER;
    v_comment_count INTEGER;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_job_key <> 'track:target-evidence:collect'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[0-9a-f]{64}$'
       OR p_target_username IS NULL
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_result_hash IS NULL
       OR p_result_hash !~ '^[0-9a-f]{64}$'
       OR NOT public.analysis_v2_valid_target_evidence_source(
            'target_post_like', p_liker_source
       )
       OR NOT public.analysis_v2_valid_target_evidence_source(
            'target_post_comment', p_comment_source
       )
       OR NOT public.analysis_v2_valid_target_evidence_rows(
            p_rows,
            p_target_username,
            p_excluded_username
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_computed_hash := public.analysis_v2_target_evidence_result_hash(
        p_rows,
        p_liker_source,
        p_comment_source
    );
    IF v_computed_hash IS DISTINCT FROM p_result_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    v_interactor_count := pg_catalog.jsonb_array_length(p_rows);
    SELECT
        pg_catalog.count(*) FILTER (
            WHERE evidence.value->>'signal' = 'target_post_like'
        )::INTEGER,
        pg_catalog.count(*) FILTER (
            WHERE evidence.value->>'signal' = 'target_post_comment'
        )::INTEGER
    INTO v_liker_count, v_comment_count
    FROM pg_catalog.jsonb_array_elements(p_rows) AS evidence(value);

    IF (p_liker_source->>'status' = 'not_applicable' AND v_liker_count <> 0)
       OR (p_comment_source->>'status' = 'not_applicable' AND v_comment_count <> 0)
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_rows) AS evidence(value)
            WHERE NOT EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_array_elements(
                    CASE evidence.value->>'signal'
                        WHEN 'target_post_like' THEN p_liker_source->'coverage'
                        ELSE p_comment_source->'coverage'
                    END
                ) AS coverage(value)
                WHERE coverage.value->>'post_id' = evidence.value->>'post_id'
            )
       )
       OR v_liker_count > COALESCE((
            SELECT pg_catalog.sum((coverage.value->>'returned_count')::INTEGER)
            FROM pg_catalog.jsonb_array_elements(p_liker_source->'coverage') AS coverage(value)
       ), 0)
       OR v_comment_count > COALESCE((
            SELECT pg_catalog.sum((coverage.value->>'returned_count')::INTEGER)
            FROM pg_catalog.jsonb_array_elements(p_comment_source->'coverage') AS coverage(value)
       ), 0) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    v_liker_source_hash := public.analysis_v2_target_evidence_source_hash(
        'target_post_like', p_liker_source
    );
    v_comment_source_hash := public.analysis_v2_target_evidence_source_hash(
        'target_post_comment', p_comment_source
    );

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_NOT_ACTIVE',
            ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR pg_catalog.lower(v_request.target_instagram_id) IS DISTINCT FROM p_target_username
       OR v_request.excluded_instagram_id IS DISTINCT FROM p_excluded_username THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_NOT_ACTIVE',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_job.job_key <> 'track:target-evidence:collect'
       OR v_job.track <> 'target_evidence'
       OR v_job.kind <> 'collection'
       OR v_job.batch IS NOT NULL
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    v_now := pg_catalog.clock_timestamp();
    IF v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    IF p_liker_source->>'status' = 'collected' THEN
        IF p_liker_source->>'provider' <> 'selfhosted_auth'
           AND NOT public.analysis_v2_valid_provider_evidence_source(
            p_request_id, p_job_key, p_claim_token,
            p_liker_source->>'provider_operation_key',
            p_liker_source->>'input_hash', p_liker_source->>'provider',
            p_liker_source->>'provider_run_id',
            p_liker_source->>'provider_credential_slot'
        ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_EVIDENCE_INVALID',
                ERRCODE = 'P0001';
        END IF;


        IF p_liker_source->>'provider' = 'selfhosted_auth' THEN
            PERFORM source.operation_key
            FROM public.analysis_v2_load_selfhosted_auth_evidence_source(
                p_request_id, p_job_key, p_claim_token,
                p_liker_source->>'provider_operation_key',
                p_liker_source->>'input_hash', p_liker_source->>'provider',
                p_liker_source->>'provider_run_id',
                p_liker_source->>'provider_credential_slot'
            ) AS source;
        ELSE
            SELECT source.* INTO STRICT v_liker_provider_run
            FROM public.analysis_v2_load_provider_evidence_source(
                p_request_id, p_job_key, p_claim_token,
                p_liker_source->>'provider_operation_key',
                p_liker_source->>'input_hash', p_liker_source->>'provider',
                p_liker_source->>'provider_run_id',
                p_liker_source->>'provider_credential_slot'
            ) AS source;
        END IF;    END IF;

    IF p_comment_source->>'status' = 'collected' THEN
        IF p_comment_source->>'provider' <> 'selfhosted_auth'
           AND NOT public.analysis_v2_valid_provider_evidence_source(
            p_request_id, p_job_key, p_claim_token,
            p_comment_source->>'provider_operation_key',
            p_comment_source->>'input_hash', p_comment_source->>'provider',
            p_comment_source->>'provider_run_id',
            p_comment_source->>'provider_credential_slot'
        ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_EVIDENCE_INVALID',
                ERRCODE = 'P0001';
        END IF;


        IF p_comment_source->>'provider' = 'selfhosted_auth' THEN
            PERFORM source.operation_key
            FROM public.analysis_v2_load_selfhosted_auth_evidence_source(
                p_request_id, p_job_key, p_claim_token,
                p_comment_source->>'provider_operation_key',
                p_comment_source->>'input_hash', p_comment_source->>'provider',
                p_comment_source->>'provider_run_id',
                p_comment_source->>'provider_credential_slot'
            ) AS source;
        ELSE
            SELECT source.* INTO STRICT v_comment_provider_run
            FROM public.analysis_v2_load_provider_evidence_source(
                p_request_id, p_job_key, p_claim_token,
                p_comment_source->>'provider_operation_key',
                p_comment_source->>'input_hash', p_comment_source->>'provider',
                p_comment_source->>'provider_run_id',
                p_comment_source->>'provider_credential_slot'
            ) AS source;
        END IF;    END IF;

    SELECT target_manifest.*
    INTO v_manifest
    FROM public.analysis_v2_target_evidence_manifests AS target_manifest
    WHERE target_manifest.request_id = p_request_id
      AND target_manifest.job_key = p_job_key
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    IF FOUND THEN
        IF v_manifest.target_username IS DISTINCT FROM p_target_username
           OR v_manifest.excluded_username IS DISTINCT FROM p_excluded_username
           OR v_manifest.input_hash IS DISTINCT FROM p_input_hash
           OR v_manifest.liker_source IS DISTINCT FROM p_liker_source
           OR v_manifest.comment_source IS DISTINCT FROM p_comment_source
           OR v_manifest.liker_source_hash IS DISTINCT FROM v_liker_source_hash
           OR v_manifest.comment_source_hash IS DISTINCT FROM v_comment_source_hash
           OR v_manifest.result_hash IS DISTINCT FROM p_result_hash
           OR v_manifest.interactor_count IS DISTINCT FROM v_interactor_count
           OR v_manifest.liker_count IS DISTINCT FROM v_liker_count
           OR v_manifest.comment_count IS DISTINCT FROM v_comment_count THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_TARGET_EVIDENCE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        UPDATE public.analysis_v2_target_evidence_manifests AS target_manifest
        SET job_claim_token = p_claim_token,
            updated_at = v_now
        WHERE target_manifest.request_id = p_request_id
          AND target_manifest.job_key = p_job_key
        RETURNING target_manifest.* INTO v_manifest;
        RETURN public.analysis_v2_target_evidence_manifest_json(v_manifest);
    END IF;

    INSERT INTO public.analysis_v2_target_evidence_manifests (
        request_id,
        job_key,
        job_claim_token,
        target_username,
        excluded_username,
        input_hash,
        liker_source,
        comment_source,
        liker_source_hash,
        comment_source_hash,
        result_hash,
        interactor_count,
        liker_count,
        comment_count,
        frozen_at,
        created_at,
        updated_at
    ) VALUES (
        p_request_id,
        p_job_key,
        p_claim_token,
        p_target_username,
        p_excluded_username,
        p_input_hash,
        p_liker_source,
        p_comment_source,
        v_liker_source_hash,
        v_comment_source_hash,
        p_result_hash,
        v_interactor_count,
        v_liker_count,
        v_comment_count,
        v_now,
        v_now,
        v_now
    )
    RETURNING * INTO v_manifest;

    INSERT INTO public.analysis_target_interactors (
        request_id,
        job_key,
        ordinal,
        actor_username,
        post_id,
        signal,
        source_interaction_id,
        occurred_at,
        comment_text
    )
    SELECT
        p_request_id,
        p_job_key,
        evidence.ordinal::SMALLINT,
        evidence.value->>'actor_username',
        evidence.value->>'post_id',
        evidence.value->>'signal',
        evidence.value->>'source_interaction_id',
        NULLIF(evidence.value->>'occurred_at', ''),
        NULLIF(evidence.value->>'content', '')
    FROM pg_catalog.jsonb_array_elements(p_rows)
        WITH ORDINALITY AS evidence(value, ordinal)
    ORDER BY evidence.ordinal;

    RETURN public.analysis_v2_target_evidence_manifest_json(v_manifest);
END;
$_$;


--
-- Name: claim_analysis_beta_preflight_prepare(uuid, uuid, integer, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_beta_preflight_prepare(p_preflight_id uuid, p_user_id uuid, p_prepare_generation integer, p_prepare_token uuid, p_claim_token uuid, p_lease_seconds integer) RETURNS TABLE(claimed boolean, prepare_state text, claim_disposition text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE;
    v_gate_enabled BOOLEAN;
    v_grant public.analysis_beta_access_grants%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
    v_reservation public.analysis_beta_pool_reservations%ROWTYPE;
BEGIN
    IF p_claim_token IS NULL OR p_lease_seconds NOT BETWEEN 30 AND 300 THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_PREPARE_INVALID', ERRCODE='P0001';
    END IF;
    SELECT gate_row.enabled INTO v_gate_enabled
    FROM public.analysis_beta_runtime_gate AS gate_row
    WHERE gate_row.singleton=TRUE FOR SHARE;
    PERFORM 1 FROM public.users AS owner_user
    WHERE owner_user.id=p_user_id FOR KEY SHARE;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight
    WHERE preflight.id=p_preflight_id AND preflight.user_id=p_user_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'missing'::TEXT, 'missing'::TEXT; RETURN;
    END IF;
    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.status='pending'
       AND v_preflight.beta_prepare_state IN ('reserved','preparing')
       AND v_preflight.expires_at <= v_now THEN
        UPDATE public.analysis_preflights AS preflight
        SET status='expired', updated_at=v_now
        WHERE preflight.id=v_preflight.id;
        RETURN QUERY SELECT FALSE, 'expired'::TEXT, 'terminal'::TEXT;
        RETURN;
    END IF;
    IF v_preflight.beta_entry_provenance IS DISTINCT FROM 'betatest_service_v1'
       OR v_preflight.beta_prepare_generation IS DISTINCT FROM p_prepare_generation
       OR v_preflight.beta_prepare_token IS DISTINCT FROM p_prepare_token THEN
        RETURN QUERY SELECT FALSE, v_preflight.beta_prepare_state, 'stale'::TEXT; RETURN;
    END IF;
    IF v_preflight.beta_prepare_state IN (
        'prepared','capacity_blocked','retry_exhausted','expired'
    ) THEN
        RETURN QUERY SELECT FALSE, v_preflight.beta_prepare_state, 'terminal'::TEXT; RETURN;
    END IF;
    -- Recover the only historical split-commit shape before evaluating the
    -- current gate. New workers perform hold+promotion atomically.
    IF v_preflight.beta_prepare_state = 'preparing'
       AND v_preflight.analysis_entry_channel = 'betatest' THEN
        SELECT allocation.* INTO v_allocation
        FROM public.analysis_beta_pool_allocations AS allocation
        WHERE allocation.preflight_id = p_preflight_id
        FOR UPDATE;
        SELECT reservation.* INTO v_reservation
        FROM public.analysis_beta_pool_reservations AS reservation
        WHERE reservation.allocation_id = v_allocation.id
          AND reservation.operation_family = 'target-profile'
        FOR UPDATE;
        IF NOT FOUND
           OR v_allocation.lifecycle_state IS DISTINCT FROM 'preflight_held'
           OR v_reservation.lifecycle_state IS DISTINCT FROM 'preflight_held' THEN
            RAISE EXCEPTION USING
                MESSAGE='ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE='P0001';
        END IF;
        UPDATE public.analysis_preflights AS preflight
        SET beta_prepare_state='prepared',
            beta_prepare_dispatch_state='completed',
            beta_prepare_lease_token=NULL,
            beta_prepare_lease_expires_at=NULL,
            beta_prepare_retry_exhausted_at=NULL,
            beta_prepare_completed_at=v_now,
            updated_at=v_now
        WHERE preflight.id=v_preflight.id;
        RETURN QUERY SELECT FALSE, 'prepared'::TEXT, 'terminal'::TEXT;
        RETURN;
    END IF;
    SELECT grant_row.* INTO v_grant
    FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id=p_user_id FOR SHARE;
    v_now := pg_catalog.clock_timestamp();
    IF v_gate_enabled IS DISTINCT FROM TRUE OR v_grant.user_id IS NULL
       OR v_grant.enabled IS DISTINCT FROM TRUE
       OR (v_grant.expires_at IS NOT NULL AND (
            NOT pg_catalog.isfinite(v_grant.expires_at)
            OR v_grant.expires_at <= v_now
       )) THEN
        UPDATE public.analysis_preflights AS preflight
        SET analysis_entry_channel='betatest', status='blocked',
            error_code='BETA_CAPACITY_UNAVAILABLE', blocked_at=v_now,
            beta_prepare_state='capacity_blocked',
            beta_prepare_dispatch_state='completed',
            beta_prepare_lease_token=NULL,
            beta_prepare_lease_expires_at=NULL,
            beta_prepare_retry_exhausted_at=NULL,
            beta_prepare_completed_at=v_now,
            updated_at=v_now
        WHERE preflight.id=v_preflight.id;
        RETURN QUERY SELECT FALSE, 'capacity_blocked'::TEXT, 'terminal'::TEXT;
        RETURN;
    END IF;
    IF v_preflight.beta_prepare_state='preparing'
       AND v_preflight.beta_prepare_lease_expires_at > v_now THEN
        RETURN QUERY SELECT FALSE, v_preflight.beta_prepare_state, 'busy'::TEXT;
        RETURN;
    END IF;
    IF v_preflight.status IS DISTINCT FROM 'pending'
       OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'standard'
       OR v_preflight.dispatch_state IS DISTINCT FROM 'unreserved'
       OR v_preflight.beta_prepare_state NOT IN ('reserved','preparing') THEN
        RETURN QUERY SELECT FALSE, v_preflight.beta_prepare_state, 'terminal'::TEXT;
        RETURN;
    END IF;
    UPDATE public.analysis_preflights AS preflight
    SET beta_prepare_state='preparing', beta_prepare_lease_token=p_claim_token,
        beta_prepare_lease_expires_at=v_now+pg_catalog.make_interval(secs=>p_lease_seconds),
        updated_at=v_now WHERE preflight.id=v_preflight.id;
    RETURN QUERY SELECT TRUE, 'preparing'::TEXT, 'claimed'::TEXT;
END;
$$;


--
-- Name: claim_analysis_lifecycle_event(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_lifecycle_event(p_request_id uuid, p_event_name text, p_error_code text DEFAULT NULL::text) RETURNS TABLE(request_id uuid, event_name text, user_id uuid, plan_id text, preflight_id uuid, occurred_at timestamp with time zone, insert_id text, duration_ms integer, error_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_request RECORD;
    v_event RECORD;
    v_started_at TIMESTAMP WITH TIME ZONE;
    v_occurred_at TIMESTAMP WITH TIME ZONE;
    v_error_code TEXT;
    v_duration_ms INTEGER;
BEGIN
    IF p_event_name NOT IN ('analysis_started', 'analysis_completed', 'analysis_failed') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYTICS_LIFECYCLE_INVALID_EVENT', ERRCODE = 'P0001';
    END IF;

    SELECT
        request.id,
        request.user_id,
        request.selected_plan_id_snapshot,
        request.preflight_id,
        request.created_at
    INTO v_request
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id
      AND request.pipeline_version = 'v2';
    IF NOT FOUND THEN
        RETURN;
    END IF;

    v_error_code := CASE
        WHEN p_event_name <> 'analysis_failed' THEN NULL
        WHEN p_error_code IN (
            'INTERNAL_ERROR', 'HANDLE_FORMAT_INVALID', 'NETWORK_ERROR', 'NOT_FOUND',
            'TARGET_NOT_FOUND', 'TARGET_PRIVATE', 'PLAN_CAPACITY_EXCEEDED',
            'EXCLUSION_RULE_VIOLATION', 'PROVIDER_ERROR', 'PROVIDER_TEMPORARY_FAILURE',
            'RATE_LIMITED', 'TIMEOUT', 'UNAUTHORIZED', 'UNKNOWN', 'VALIDATION_ERROR'
        ) THEN p_error_code
        ELSE 'UNKNOWN'
    END;
    v_occurred_at := pg_catalog.clock_timestamp();

    INSERT INTO public.analysis_lifecycle_events (
        request_id,
        event_name,
        user_id,
        plan_id,
        preflight_id,
        error_code,
        occurred_at,
        insert_id
    ) VALUES (
        v_request.id,
        p_event_name,
        v_request.user_id,
        v_request.selected_plan_id_snapshot,
        v_request.preflight_id,
        v_error_code,
        v_occurred_at,
        'analysis:' || v_request.id::TEXT || ':' || p_event_name
    )
    ON CONFLICT (request_id, event_name) DO NOTHING;

    SELECT event.*
    INTO v_event
    FROM public.analysis_lifecycle_events AS event
    WHERE event.request_id = p_request_id
      AND event.event_name = p_event_name
    FOR UPDATE;
    IF NOT FOUND OR v_event.sent_at IS NOT NULL THEN
        RETURN;
    END IF;

    UPDATE public.analysis_lifecycle_events
    SET delivery_attempts = delivery_attempts + 1
    WHERE analysis_lifecycle_events.request_id = p_request_id
      AND analysis_lifecycle_events.event_name = p_event_name;

    SELECT started.occurred_at
    INTO v_started_at
    FROM public.analysis_lifecycle_events AS started
    WHERE started.request_id = p_request_id
      AND started.event_name = 'analysis_started';
    v_duration_ms := LEAST(
        86400000,
        GREATEST(
            0,
            FLOOR(EXTRACT(EPOCH FROM (
                v_event.occurred_at - COALESCE(v_started_at, v_request.created_at)
            )) * 1000)::INTEGER
        )
    );

    RETURN QUERY SELECT
        v_event.request_id,
        v_event.event_name,
        v_event.user_id,
        v_event.plan_id,
        v_event.preflight_id,
        v_event.occurred_at,
        v_event.insert_id,
        v_duration_ms,
        v_event.error_code;
END;
$$;


--
-- Name: claim_analysis_order_audit_bundle(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_order_audit_bundle(p_request_id uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_queue public.analysis_order_audit_assembly_queue%ROWTYPE;
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_lease UUID := extensions.gen_random_uuid();
BEGIN
    IF p_request_id IS NULL OR p_lease_seconds NOT BETWEEN 30 AND 1800 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_ORDER_AUDIT_INVALID_CLAIM', ERRCODE = 'P0001';
    END IF;

    SELECT queue.*
      INTO v_queue
      FROM public.analysis_order_audit_assembly_queue AS queue
     WHERE queue.request_id = p_request_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    IF v_queue.status = 'processing'
       AND v_queue.lease_expires_at IS NOT NULL
       AND v_queue.lease_expires_at > v_now THEN
        RETURN NULL;
    END IF;
    IF v_queue.status = 'completed' THEN
        RETURN NULL;
    END IF;
    IF v_queue.next_attempt_at > v_now THEN
        RETURN NULL;
    END IF;

    UPDATE public.analysis_order_audit_assembly_queue
       SET status = 'processing',
           attempt_count = v_queue.attempt_count + 1,
           lease_token = v_lease,
           lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
           updated_at = v_now
     WHERE request_id = p_request_id;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', p_request_id::TEXT,
        'leaseToken', v_lease::TEXT,
        'attemptCount', v_queue.attempt_count + 1,
        'leaseExpiresAt', v_now + make_interval(secs => p_lease_seconds)
    );
END;
$$;


--
-- Name: claim_analysis_v2_job(uuid, text, integer, uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_v2_job(p_request_id uuid, p_job_key text, p_dispatch_generation integer, p_dispatch_token uuid, p_claim_token uuid, p_lease_seconds integer DEFAULT 120, p_max_attempts integer DEFAULT 7) RETURNS TABLE(claimed boolean, job_status text, attempt_count integer, lease_expires_at timestamp with time zone, track text, job_kind text, batch integer, input_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    PERFORM public.assert_analysis_revenue_dispatch_guard_v1(p_request_id, p_job_key);
    RETURN QUERY
    SELECT * FROM public.claim_analysis_v2_job_unfenced_20260811(
        p_request_id, p_job_key, p_dispatch_generation, p_dispatch_token,
        p_claim_token, p_lease_seconds, p_max_attempts
    );
END;
$$;


--
-- Name: claim_analysis_v2_job_unfenced_20260811(uuid, text, integer, uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_v2_job_unfenced_20260811(p_request_id uuid, p_job_key text, p_dispatch_generation integer, p_dispatch_token uuid, p_claim_token uuid, p_lease_seconds integer DEFAULT 120, p_max_attempts integer DEFAULT 7) RETURNS TABLE(claimed boolean, job_status text, attempt_count integer, lease_expires_at timestamp with time zone, track text, job_kind text, batch integer, input_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_intent public.analysis_v2_provider_cleanup_intents%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 1000
       OR p_dispatch_token IS NULL
       OR p_claim_token IS NULL
       OR p_lease_seconds IS NULL
       OR p_lease_seconds NOT BETWEEN 30 AND 600
       OR p_max_attempts IS NULL
       OR p_max_attempts NOT BETWEEN 1 AND 20
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_INVALID_JOB_CLAIM_INPUT', ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;

    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    IF v_job.status IN ('completed', 'failed', 'cancelled')
       OR v_request.status NOT IN ('pending', 'processing') THEN
        RETURN QUERY SELECT
            FALSE, v_job.status::TEXT, v_job.attempt_count,
            v_job.lease_expires_at, v_job.track::TEXT, v_job.kind::TEXT,
            v_job.batch, v_job.input_hash::TEXT;
        RETURN;
    END IF;

    IF v_job.dispatch_generation <> p_dispatch_generation
       OR v_job.dispatch_reservation_token <> p_dispatch_token THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_DISPATCH_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF v_job.dispatch_state = 'reserved' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_DISPATCH_NOT_READY', ERRCODE = 'P0001';
    END IF;
    IF v_job.dispatch_state NOT IN ('enqueued', 'delivered') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_DISPATCH_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    IF v_job.status = 'processing' AND v_job.lease_expires_at > v_now THEN
        RETURN QUERY SELECT
            v_job.lease_token = p_claim_token, v_job.status::TEXT,
            v_job.attempt_count, v_job.lease_expires_at, v_job.track::TEXT,
            v_job.kind::TEXT, v_job.batch, v_job.input_hash::TEXT;
        RETURN;
    END IF;

    IF v_job.attempt_count >= p_max_attempts
       AND EXISTS (
            SELECT 1
            FROM public.analysis_v2_provider_cleanup_intents AS intent
            WHERE intent.request_id = p_request_id
              AND intent.failed_job_key = p_job_key
              AND intent.failed_job_input_hash = v_job.input_hash
              AND intent.completed_at IS NULL
       ) THEN
        -- The durable intent owns terminalization. Return the still-processing
        -- job so the worker can invoke the tightly fenced takeover RPC.
        RETURN QUERY SELECT
            FALSE,
            v_job.status::TEXT,
            v_job.attempt_count,
            v_job.lease_expires_at,
            v_job.track::TEXT,
            v_job.kind::TEXT,
            v_job.batch,
            v_job.input_hash::TEXT;
        RETURN;
    END IF;

    IF v_job.attempt_count >= p_max_attempts THEN
        UPDATE public.analysis_pipeline_jobs AS job
        SET status = 'processing',
            dispatch_state = 'delivered',
            delivered_at = COALESCE(job.delivered_at, v_now),
            lease_token = p_claim_token,
            lease_expires_at = v_now
                + p_lease_seconds * INTERVAL '1 second',
            last_error_code = 'JOB_ATTEMPTS_EXHAUSTED',
            last_error_at = v_now,
            updated_at = v_now
        WHERE job.request_id = p_request_id AND job.job_key = p_job_key
        RETURNING job.* INTO v_job;

        SELECT intent.* INTO v_intent
        FROM public.analysis_v2_provider_cleanup_intents AS intent
        WHERE intent.request_id = p_request_id
        FOR UPDATE;
        IF FOUND THEN
            IF v_intent.failed_job_key IS DISTINCT FROM p_job_key
               OR v_intent.failed_job_input_hash IS DISTINCT FROM v_job.input_hash
               OR v_intent.completed_at IS NOT NULL THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_INTENT_CONFLICT',
                    ERRCODE = 'P0001';
            END IF;
            UPDATE public.analysis_v2_provider_cleanup_intents AS intent
            SET failed_claim_token = p_claim_token
            WHERE intent.request_id = p_request_id;
        ELSE
            INSERT INTO public.analysis_v2_provider_cleanup_intents (
                request_id, failed_job_key, failed_job_input_hash,
                failed_claim_token, error_code
            ) VALUES (
                p_request_id, p_job_key, v_job.input_hash,
                p_claim_token, 'JOB_ATTEMPTS_EXHAUSTED'
            );
        END IF;

        UPDATE public.analysis_requests AS analysis_request
        SET status = 'processing', background_processing = TRUE
        WHERE analysis_request.id = p_request_id
          AND analysis_request.status IN ('pending', 'processing');

        RETURN QUERY SELECT
            TRUE, v_job.status::TEXT, v_job.attempt_count,
            v_job.lease_expires_at, v_job.track::TEXT, v_job.kind::TEXT,
            v_job.batch, v_job.input_hash::TEXT;
        RETURN;
    END IF;

    UPDATE public.analysis_pipeline_jobs AS job
    SET status = 'processing',
        dispatch_state = 'delivered',
        delivered_at = COALESCE(job.delivered_at, v_now),
        lease_token = p_claim_token,
        lease_expires_at = v_now + p_lease_seconds * INTERVAL '1 second',
        attempt_count = job.attempt_count + 1,
        first_started_at = COALESCE(job.first_started_at, v_now),
        updated_at = v_now
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    RETURNING job.* INTO v_job;

    UPDATE public.analysis_requests AS analysis_request
    SET status = 'processing', background_processing = TRUE
    WHERE analysis_request.id = p_request_id
      AND analysis_request.status IN ('pending', 'processing');

    RETURN QUERY SELECT
        TRUE, v_job.status::TEXT, v_job.attempt_count,
        v_job.lease_expires_at, v_job.track::TEXT, v_job.kind::TEXT,
        v_job.batch, v_job.input_hash::TEXT;
END;
$_$;


--
-- Name: claim_analysis_v2_job_v2(uuid, text, integer, uuid, uuid, integer, integer, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_v2_job_v2(p_request_id uuid, p_job_key text, p_dispatch_generation integer, p_dispatch_token uuid, p_claim_token uuid, p_lease_seconds integer DEFAULT 120, p_max_attempts integer DEFAULT 7, p_workload_role text DEFAULT 'paid'::text, p_contract_version smallint DEFAULT 2) RETURNS TABLE(claimed boolean, job_status text, attempt_count integer, lease_expires_at timestamp with time zone, track text, job_kind text, batch integer, input_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_result RECORD;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'paid' OR p_contract_version IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT job.* INTO v_job FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    IF NOT FOUND
       OR v_job.dispatch_workload_role IS DISTINCT FROM 'paid'
       OR v_job.dispatch_contract_version IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT claimed.* INTO v_result FROM public.claim_analysis_v2_job(
        p_request_id, p_job_key, p_dispatch_generation, p_dispatch_token,
        p_claim_token, p_lease_seconds, p_max_attempts
    ) AS claimed;
    IF v_result.claimed THEN
        UPDATE public.analysis_pipeline_jobs AS job
        SET claim_workload_role = 'paid', claim_contract_version = 2
        WHERE job.request_id = p_request_id AND job.job_key = p_job_key
          AND job.status = 'processing' AND job.lease_token = p_claim_token;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH', ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN QUERY SELECT v_result.claimed, v_result.job_status, v_result.attempt_count,
        v_result.lease_expires_at, v_result.track, v_result.job_kind, v_result.batch,
        v_result.input_hash;
END;
$$;


--
-- Name: claim_analysis_v2_media_artifact_cleanup(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_v2_media_artifact_cleanup(p_limit integer DEFAULT 100, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_result JSONB;
BEGIN
    IF p_limit NOT BETWEEN 1 AND 500 OR p_lease_seconds NOT BETWEEN 30 AND 900 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_MEDIA_ARTIFACT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    WITH candidates AS (
        SELECT artifact.request_id, artifact.artifact_key
        FROM public.analysis_v2_media_artifacts AS artifact
        JOIN public.analysis_requests AS analysis_request
          ON analysis_request.id = artifact.request_id
        WHERE artifact.deleted_at IS NULL
          AND analysis_request.status IN ('completed', 'failed')
          AND (
              artifact.cleanup_token IS NULL
              OR artifact.cleanup_lease_expires_at <= v_now
          )
        ORDER BY artifact.expires_at, artifact.request_id, artifact.artifact_key
        LIMIT p_limit
        FOR UPDATE OF artifact SKIP LOCKED
    ), claimed AS (
        UPDATE public.analysis_v2_media_artifacts AS artifact
        SET cleanup_token = extensions.gen_random_uuid(),
            cleanup_lease_expires_at = v_now
                + pg_catalog.make_interval(secs => p_lease_seconds)
        FROM candidates
        WHERE artifact.request_id = candidates.request_id
          AND artifact.artifact_key = candidates.artifact_key
        RETURNING artifact.*
    )
    SELECT COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
            'requestId', claimed.request_id,
            'artifactKey', claimed.artifact_key,
            'artifactKind', claimed.artifact_kind,
            'contentSha256', claimed.content_sha256,
            'contentType', claimed.content_type,
            'objectName', claimed.object_name,
            'objectGeneration', claimed.object_generation,
            'byteSize', claimed.byte_size,
            'cleanupToken', claimed.cleanup_token
        )
        ORDER BY claimed.expires_at, claimed.request_id, claimed.artifact_key
    ), '[]'::JSONB)
    INTO v_result
    FROM claimed;

    RETURN v_result;
END;
$$;


--
-- Name: claim_analysis_v2_preflight(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_v2_preflight(p_preflight_id uuid, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(preflight_id uuid, user_id uuid, claimed boolean, target_instagram_id text, access_mode text, analysis_entry_channel text, plan_catalog_snapshot jsonb, pricing_version text, pricing_snapshot jsonb, worker_attempt_count integer, lease_expires_at timestamp with time zone, preflight_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_lease_expires_at TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_preflight_id IS NULL OR p_claim_token IS NULL OR p_lease_seconds IS NULL
       OR p_lease_seconds < 30 OR p_lease_seconds > 300 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_CLAIM_INPUT', ERRCODE = 'P0001';
    END IF;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001'; END IF;
    IF v_preflight.expires_at <= v_now THEN
        IF v_preflight.status IN ('pending','processing','ready') THEN
            UPDATE public.analysis_preflights SET status='expired', lease_token=NULL,
                lease_expires_at=NULL, updated_at=v_now WHERE id=v_preflight.id;
        END IF;
        RETURN QUERY SELECT v_preflight.id,v_preflight.user_id,FALSE,NULL::TEXT,
            v_preflight.access_mode::TEXT,v_preflight.analysis_entry_channel::TEXT,
            v_preflight.plan_catalog_snapshot,v_preflight.pricing_version::TEXT,
            v_preflight.pricing_snapshot,v_preflight.worker_attempt_count,NULL::TIMESTAMPTZ,'expired'::TEXT; RETURN;
    END IF;
    IF v_preflight.status='processing' AND v_preflight.lease_token=p_claim_token
       AND v_preflight.lease_expires_at > v_now THEN
        v_lease_expires_at:=LEAST(v_preflight.expires_at,v_now+pg_catalog.make_interval(secs=>p_lease_seconds));
        UPDATE public.analysis_preflights SET lease_expires_at=v_lease_expires_at,updated_at=v_now WHERE id=v_preflight.id;
        RETURN QUERY SELECT v_preflight.id,v_preflight.user_id,TRUE,v_preflight.target_instagram_id::TEXT,
            v_preflight.access_mode::TEXT,v_preflight.analysis_entry_channel::TEXT,v_preflight.plan_catalog_snapshot,
            v_preflight.pricing_version::TEXT,v_preflight.pricing_snapshot,v_preflight.worker_attempt_count,v_lease_expires_at,'processing'::TEXT; RETURN;
    END IF;
    IF v_preflight.status='processing' AND v_preflight.lease_expires_at > v_now THEN
        RETURN QUERY SELECT v_preflight.id,v_preflight.user_id,FALSE,NULL::TEXT,v_preflight.access_mode::TEXT,
            v_preflight.analysis_entry_channel::TEXT,v_preflight.plan_catalog_snapshot,v_preflight.pricing_version::TEXT,
            v_preflight.pricing_snapshot,v_preflight.worker_attempt_count,v_preflight.lease_expires_at,'processing'::TEXT; RETURN;
    END IF;
    IF v_preflight.status NOT IN ('pending','processing') THEN
        RETURN QUERY SELECT v_preflight.id,v_preflight.user_id,FALSE,NULL::TEXT,v_preflight.access_mode::TEXT,
            v_preflight.analysis_entry_channel::TEXT,v_preflight.plan_catalog_snapshot,v_preflight.pricing_version::TEXT,
            v_preflight.pricing_snapshot,v_preflight.worker_attempt_count,NULL::TIMESTAMPTZ,v_preflight.status::TEXT; RETURN;
    END IF;
    IF v_preflight.worker_attempt_count >= 7 THEN
        UPDATE public.analysis_preflights SET status='blocked',error_code='ANALYSIS_FAILED',blocked_at=v_now,
            lease_token=NULL,lease_expires_at=NULL,updated_at=v_now WHERE id=v_preflight.id;
        RETURN QUERY SELECT v_preflight.id,v_preflight.user_id,FALSE,NULL::TEXT,v_preflight.access_mode::TEXT,
            v_preflight.analysis_entry_channel::TEXT,v_preflight.plan_catalog_snapshot,v_preflight.pricing_version::TEXT,
            v_preflight.pricing_snapshot,v_preflight.worker_attempt_count,NULL::TIMESTAMPTZ,'blocked'::TEXT; RETURN;
    END IF;
    v_lease_expires_at:=LEAST(v_preflight.expires_at,v_now+pg_catalog.make_interval(secs=>p_lease_seconds));
    UPDATE public.analysis_preflights AS preflight SET status='processing',worker_attempt_count=preflight.worker_attempt_count+1,
        lease_token=p_claim_token,lease_expires_at=v_lease_expires_at,claimed_at=v_now,updated_at=v_now WHERE preflight.id=v_preflight.id;
    RETURN QUERY SELECT v_preflight.id,v_preflight.user_id,TRUE,v_preflight.target_instagram_id::TEXT,
        v_preflight.access_mode::TEXT,v_preflight.analysis_entry_channel::TEXT,v_preflight.plan_catalog_snapshot,
        v_preflight.pricing_version::TEXT,v_preflight.pricing_snapshot,v_preflight.worker_attempt_count+1,v_lease_expires_at,'processing'::TEXT;
END;
$$;


--
-- Name: claim_analysis_v2_preflight_admission(uuid, integer, integer, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_v2_preflight_admission(p_preflight_id uuid, p_admission_generation integer, p_dispatch_generation integer, p_dispatch_token uuid, p_claim_token uuid, p_lease_seconds integer) RETURNS TABLE(claimed boolean, admission_status text, target_instagram_id text, analysis_entry_channel text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp(); v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL OR p_admission_generation IS NULL OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_generation IS NULL OR p_dispatch_generation NOT BETWEEN 1 AND 100 OR p_dispatch_token IS NULL
       OR p_claim_token IS NULL OR p_lease_seconds IS NULL OR p_lease_seconds NOT BETWEEN 30 AND 300 THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_V2_FRESH_ADMISSION_INVALID', ERRCODE='P0001';
    END IF;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight WHERE preflight.id=p_preflight_id FOR UPDATE;
    IF NOT FOUND OR v_preflight.status <> 'ready' OR v_preflight.consumed_request_id IS NOT NULL OR v_preflight.expires_at <= v_now
       OR v_preflight.admission_generation <> p_admission_generation
       OR v_preflight.admission_dispatch_generation <> p_dispatch_generation
       OR v_preflight.admission_dispatch_token IS DISTINCT FROM p_dispatch_token
       OR v_preflight.admission_dispatch_state NOT IN ('reserved','enqueued') THEN
        RETURN QUERY SELECT FALSE,'blocked'::TEXT,NULL::TEXT,COALESCE(v_preflight.analysis_entry_channel::TEXT,'standard'::TEXT); RETURN;
    END IF;
    IF v_preflight.admission_status IN ('idle','ready','blocked') THEN
        RETURN QUERY SELECT FALSE,CASE WHEN v_preflight.admission_status='idle' THEN 'blocked' ELSE v_preflight.admission_status END,
            NULL::TEXT,v_preflight.analysis_entry_channel::TEXT; RETURN;
    END IF;
    IF v_preflight.admission_status='processing' AND v_preflight.admission_lease_expires_at > v_now THEN
        RETURN QUERY SELECT FALSE,'processing'::TEXT,NULL::TEXT,v_preflight.analysis_entry_channel::TEXT; RETURN;
    END IF;
    UPDATE public.analysis_preflights AS preflight SET admission_status='processing',admission_claim_token=p_claim_token,
        admission_lease_expires_at=v_now+pg_catalog.make_interval(secs=>p_lease_seconds),admission_dispatch_state='enqueued',
        admission_dispatched_at=COALESCE(preflight.admission_dispatched_at,v_now),updated_at=v_now WHERE preflight.id=v_preflight.id;
    RETURN QUERY SELECT TRUE,'processing'::TEXT,v_preflight.target_instagram_id::TEXT,v_preflight.analysis_entry_channel::TEXT;
END;
$$;


--
-- Name: claim_analysis_v2_preflight_admission_v2(uuid, integer, integer, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_v2_preflight_admission_v2(p_preflight_id uuid, p_admission_generation integer, p_dispatch_generation integer, p_dispatch_token uuid, p_claim_token uuid, p_lease_seconds integer) RETURNS TABLE(claimed boolean, admission_status text, target_instagram_id text, analysis_entry_channel text, access_mode text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp(); v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL OR p_admission_generation IS NULL OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_generation IS NULL OR p_dispatch_generation NOT BETWEEN 1 AND 100 OR p_dispatch_token IS NULL
       OR p_claim_token IS NULL OR p_lease_seconds IS NULL OR p_lease_seconds NOT BETWEEN 30 AND 300 THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_V2_FRESH_ADMISSION_INVALID', ERRCODE='P0001';
    END IF;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight WHERE preflight.id=p_preflight_id FOR UPDATE;
    IF NOT FOUND OR v_preflight.status <> 'ready' OR v_preflight.consumed_request_id IS NOT NULL OR v_preflight.expires_at <= v_now
       OR v_preflight.admission_generation <> p_admission_generation
       OR v_preflight.admission_dispatch_generation <> p_dispatch_generation
       OR v_preflight.admission_dispatch_token IS DISTINCT FROM p_dispatch_token
       OR v_preflight.admission_dispatch_state NOT IN ('reserved','enqueued') THEN
        RETURN QUERY SELECT FALSE,'blocked'::TEXT,NULL::TEXT,COALESCE(v_preflight.analysis_entry_channel::TEXT,'standard'::TEXT),v_preflight.access_mode::TEXT; RETURN;
    END IF;
    IF v_preflight.admission_status IN ('idle','ready','blocked') THEN
        RETURN QUERY SELECT FALSE,CASE WHEN v_preflight.admission_status='idle' THEN 'blocked' ELSE v_preflight.admission_status END,
            NULL::TEXT,v_preflight.analysis_entry_channel::TEXT,v_preflight.access_mode::TEXT; RETURN;
    END IF;
    IF v_preflight.admission_status='processing' AND v_preflight.admission_lease_expires_at > v_now THEN
        RETURN QUERY SELECT FALSE,'processing'::TEXT,NULL::TEXT,v_preflight.analysis_entry_channel::TEXT,v_preflight.access_mode::TEXT; RETURN;
    END IF;
    UPDATE public.analysis_preflights AS preflight SET admission_status='processing',admission_claim_token=p_claim_token,
        admission_lease_expires_at=v_now+pg_catalog.make_interval(secs=>p_lease_seconds),admission_dispatch_state='enqueued',
        admission_dispatched_at=COALESCE(preflight.admission_dispatched_at,v_now),updated_at=v_now WHERE preflight.id=v_preflight.id;
    RETURN QUERY SELECT TRUE,'processing'::TEXT,v_preflight.target_instagram_id::TEXT,v_preflight.analysis_entry_channel::TEXT,v_preflight.access_mode::TEXT;
END;
$$;


--
-- Name: claim_analysis_v2_preflight_admission_v3(uuid, integer, integer, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_v2_preflight_admission_v3(p_preflight_id uuid, p_admission_generation integer, p_dispatch_generation integer, p_dispatch_token uuid, p_claim_token uuid, p_lease_seconds integer) RETURNS TABLE(claimed boolean, admission_status text, target_instagram_id text, analysis_entry_channel text, access_mode text, order_scoped_credential_slot text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp(); v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL OR p_admission_generation IS NULL OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_generation IS NULL OR p_dispatch_generation NOT BETWEEN 1 AND 100 OR p_dispatch_token IS NULL
       OR p_claim_token IS NULL OR p_lease_seconds IS NULL OR p_lease_seconds NOT BETWEEN 30 AND 300 THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_V2_FRESH_ADMISSION_INVALID', ERRCODE='P0001';
    END IF;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight WHERE preflight.id=p_preflight_id FOR UPDATE;
    IF NOT FOUND OR v_preflight.status <> 'ready' OR v_preflight.consumed_request_id IS NOT NULL OR v_preflight.expires_at <= v_now
       OR v_preflight.admission_generation <> p_admission_generation
       OR v_preflight.admission_dispatch_generation <> p_dispatch_generation
       OR v_preflight.admission_dispatch_token IS DISTINCT FROM p_dispatch_token
       OR v_preflight.admission_dispatch_state NOT IN ('reserved','enqueued') THEN
        RETURN QUERY SELECT FALSE,'blocked'::TEXT,NULL::TEXT,COALESCE(v_preflight.analysis_entry_channel::TEXT,'standard'::TEXT),v_preflight.access_mode::TEXT,v_preflight.order_scoped_apify_credential_slot; RETURN;
    END IF;
    IF v_preflight.admission_status IN ('idle','ready','blocked') THEN
        RETURN QUERY SELECT FALSE,CASE WHEN v_preflight.admission_status='idle' THEN 'blocked' ELSE v_preflight.admission_status END,
            NULL::TEXT,v_preflight.analysis_entry_channel::TEXT,v_preflight.access_mode::TEXT,v_preflight.order_scoped_apify_credential_slot; RETURN;
    END IF;
    IF v_preflight.admission_status='processing' AND v_preflight.admission_lease_expires_at > v_now THEN
        RETURN QUERY SELECT FALSE,'processing'::TEXT,NULL::TEXT,v_preflight.analysis_entry_channel::TEXT,v_preflight.access_mode::TEXT,v_preflight.order_scoped_apify_credential_slot; RETURN;
    END IF;
    UPDATE public.analysis_preflights AS preflight SET admission_status='processing',admission_claim_token=p_claim_token,
        admission_lease_expires_at=v_now+pg_catalog.make_interval(secs=>p_lease_seconds),admission_dispatch_state='enqueued',
        admission_dispatched_at=COALESCE(preflight.admission_dispatched_at,v_now),updated_at=v_now WHERE preflight.id=v_preflight.id;
    RETURN QUERY SELECT TRUE,'processing'::TEXT,v_preflight.target_instagram_id::TEXT,v_preflight.analysis_entry_channel::TEXT,v_preflight.access_mode::TEXT,v_preflight.order_scoped_apify_credential_slot;
END;
$$;


--
-- Name: claim_analysis_v2_preflight_admission_v4(uuid, integer, integer, uuid, uuid, integer, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_v2_preflight_admission_v4(p_preflight_id uuid, p_admission_generation integer, p_dispatch_generation integer, p_dispatch_token uuid, p_claim_token uuid, p_lease_seconds integer, p_workload_role text DEFAULT 'paid'::text, p_contract_version smallint DEFAULT 2) RETURNS TABLE(claimed boolean, admission_status text, target_instagram_id text, analysis_entry_channel text, access_mode text, order_scoped_credential_slot text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_result RECORD;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'paid' OR p_contract_version IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.admission_dispatch_workload_role IS DISTINCT FROM 'paid'
       OR v_preflight.admission_dispatch_contract_version IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT claimed.* INTO v_result
    FROM public.claim_analysis_v2_preflight_admission_v3(
        p_preflight_id, p_admission_generation, p_dispatch_generation,
        p_dispatch_token, p_claim_token, p_lease_seconds
    ) AS claimed;
    IF v_result.claimed THEN
        UPDATE public.analysis_preflights AS preflight
        SET admission_claim_workload_role = 'paid', admission_claim_contract_version = 2
        WHERE preflight.id = p_preflight_id
          AND preflight.admission_claim_token = p_claim_token
          AND preflight.admission_status = 'processing';
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_FRESH_ADMISSION_CLAIM_FENCE_LOST', ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN QUERY SELECT v_result.claimed, v_result.admission_status,
        v_result.target_instagram_id, v_result.analysis_entry_channel,
        v_result.access_mode, v_result.order_scoped_credential_slot;
END;
$$;


--
-- Name: claim_analysis_v2_preflight_v2(uuid, integer, uuid, uuid, integer, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_v2_preflight_v2(p_preflight_id uuid, p_dispatch_generation integer, p_dispatch_token uuid, p_claim_token uuid, p_lease_seconds integer DEFAULT 300, p_workload_role text DEFAULT 'preflight'::text, p_contract_version smallint DEFAULT 2) RETURNS TABLE(preflight_id uuid, user_id uuid, claimed boolean, target_instagram_id text, access_mode text, analysis_entry_channel text, plan_catalog_snapshot jsonb, pricing_version text, pricing_snapshot jsonb, worker_attempt_count integer, lease_expires_at timestamp with time zone, preflight_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_result RECORD;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'preflight'
       OR p_contract_version IS DISTINCT FROM 2
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.dispatch_workload_role IS DISTINCT FROM 'preflight'
       OR v_preflight.dispatch_contract_version IS DISTINCT FROM 2
       OR v_preflight.dispatch_state IS DISTINCT FROM 'enqueued'
       OR v_preflight.dispatch_generation IS DISTINCT FROM p_dispatch_generation
       OR v_preflight.last_dispatch_token IS DISTINCT FROM p_dispatch_token THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_DISPATCH_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT claimed.* INTO v_result
    FROM public.claim_analysis_v2_preflight(
            p_preflight_id, p_claim_token, p_lease_seconds
    ) AS claimed;
    IF v_result.claimed THEN
        UPDATE public.analysis_preflights AS preflight
        SET claim_workload_role = 'preflight', claim_contract_version = 2
        WHERE preflight.id = p_preflight_id
          AND preflight.lease_token = p_claim_token
          AND preflight.status = 'processing';
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_CLAIM_FENCE_LOST', ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN QUERY SELECT v_result.preflight_id, v_result.user_id, v_result.claimed,
        v_result.target_instagram_id, v_result.access_mode, v_result.analysis_entry_channel,
        v_result.plan_catalog_snapshot,
        v_result.pricing_version, v_result.pricing_snapshot, v_result.worker_attempt_count,
        v_result.lease_expires_at, v_result.preflight_status;
END;
$$;


--
-- Name: claim_analysis_v2_result_image_purges(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_v2_result_image_purges(p_claim_token uuid, p_limit integer, p_lease_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_rows JSONB;
BEGIN
    IF p_claim_token IS NULL
       OR p_limit NOT BETWEEN 1 AND 100
       OR p_lease_seconds NOT BETWEEN 30 AND 900 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.analysis_v2_result_image_purge_outbox (
        object_key, request_id, kind, candidate_locator, reason
    )
    SELECT image_object.object_key, image_object.request_id,
        image_object.kind, image_object.candidate_locator, 'expired'
    FROM public.analysis_v2_result_image_objects AS image_object
    WHERE image_object.status = 'ready'
      AND image_object.expires_at <= v_now
    ON CONFLICT (object_key) DO NOTHING;

    WITH claimable AS (
        SELECT purge.object_key
        FROM public.analysis_v2_result_image_purge_outbox AS purge
        WHERE purge.available_at <= v_now
          AND (
            purge.status = 'pending'
            OR (
                purge.status = 'claimed'
                AND purge.lease_expires_at <= v_now
            )
          )
        ORDER BY purge.available_at, purge.object_key
        LIMIT p_limit
        FOR UPDATE SKIP LOCKED
    ),
    claimed AS (
        UPDATE public.analysis_v2_result_image_purge_outbox AS purge
        SET status = 'claimed',
            claim_token = p_claim_token,
            lease_expires_at = v_now
                + pg_catalog.make_interval(secs => p_lease_seconds),
            attempt_count = purge.attempt_count + 1,
            updated_at = v_now
        FROM claimable
        WHERE purge.object_key = claimable.object_key
        RETURNING purge.object_key, purge.reason
    )
    SELECT COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
            'objectKey', claimed.object_key,
            'reason', claimed.reason
        )
        ORDER BY claimed.object_key
    ), '[]'::JSONB)
    INTO v_rows
    FROM claimed;
    RETURN v_rows;
END;
$$;


--
-- Name: claim_analysis_v2_scheduler_operation(uuid, text, uuid, text, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_v2_scheduler_operation(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_operation_key text, p_stage text, p_operation_claim_token uuid, p_lease_seconds integer) RETURNS TABLE(decision text, operation_claim_token uuid, recovery_only boolean, result_json jsonb, not_before_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_operation public.analysis_v2_scheduler_operations%ROWTYPE;
    v_has_attempt BOOLEAN := FALSE;
    v_has_unsafe_attempt BOOLEAN := FALSE;
    v_has_result BOOLEAN := FALSE;
BEGIN
    IF p_request_id IS NULL OR p_job_claim_token IS NULL OR p_operation_claim_token IS NULL
       OR p_operation_key IS NULL OR p_stage IS NULL OR p_lease_seconds NOT BETWEEN 240 AND 360
       OR p_job_key IS NULL OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR NOT public.analysis_v2_valid_ai_operation_key(p_operation_key)
       OR NOT ((p_stage = 'genderTriage' AND p_operation_key ~ '^gender-triage:[0-9a-f]{64}$')
            OR (p_stage = 'featureAnalysis' AND p_operation_key ~ '^feature-analysis:[0-9a-f]{64}$')
            OR (p_stage = 'privateAccountName' AND p_operation_key ~ '^private-account-name:[0-9a-f]{64}$')) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_SCHEDULER_OPERATION_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT request.* INTO v_request FROM public.analysis_requests AS request
    WHERE request.id = p_request_id AND request.pipeline_version = 'v2' FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_SCHEDULER_OPERATION_POLICY_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF v_request.status NOT IN ('pending', 'processing') OR NOT (
        (v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.4', 'aiStage', 'ai-stage-policy-v2.8', 'scheduler', 'ai-scheduler-v1') OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.5', 'aiStage', 'ai-stage-policy-v2.8', 'scheduler', 'ai-scheduler-v1'))
        OR (v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.4', 'aiStage', 'ai-stage-policy-v2.9', 'scheduler', 'ai-scheduler-v1') OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.5', 'aiStage', 'ai-stage-policy-v2.9', 'scheduler', 'ai-scheduler-v1'))
        OR (v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.4', 'aiStage', 'ai-stage-policy-v2.10', 'scheduler', 'ai-scheduler-v1') OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.5', 'aiStage', 'ai-stage-policy-v2.10', 'scheduler', 'ai-scheduler-v1') OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.4', 'aiStage', 'ai-stage-policy-v2.11', 'scheduler', 'ai-scheduler-v1') OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.5', 'aiStage', 'ai-stage-policy-v2.11', 'scheduler', 'ai-scheduler-v1')
            OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.4', 'aiStage', 'ai-stage-policy-v2.12', 'scheduler', 'ai-scheduler-v1')
            OR v_request.policy_versions_snapshot = pg_catalog.jsonb_build_object('pipeline', 'v2', 'risk', 'risk-policy-v2.5', 'aiStage', 'ai-stage-policy-v2.12', 'scheduler', 'ai-scheduler-v1'))
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_SCHEDULER_OPERATION_POLICY_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT job.* INTO v_job FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    IF NOT FOUND OR v_job.status <> 'processing' OR v_job.lease_token IS DISTINCT FROM p_job_claim_token
       OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT operation.* INTO v_operation FROM public.analysis_v2_scheduler_operations AS operation
    WHERE operation.request_id = p_request_id AND operation.operation_key = p_operation_key FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO public.analysis_v2_scheduler_operations (
            request_id, job_key, operation_key, stage, status, claim_token, lease_expires_at,
            not_before_at, recovery_deadline_at
        ) VALUES (
            p_request_id, p_job_key, p_operation_key, p_stage, 'claimed', p_operation_claim_token,
            v_now + pg_catalog.make_interval(secs => p_lease_seconds), v_now, v_now + INTERVAL '6 minutes'
        ) RETURNING * INTO v_operation;
        RETURN QUERY SELECT 'execute'::TEXT, v_operation.claim_token, FALSE, NULL::JSONB, NULL::TIMESTAMP WITH TIME ZONE;
        RETURN;
    END IF;
    IF v_operation.job_key <> p_job_key OR v_operation.stage <> p_stage THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_SCHEDULER_OPERATION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_operation.status = 'ready' THEN
        RETURN QUERY SELECT 'ready'::TEXT, NULL::UUID, FALSE, v_operation.result_json, NULL::TIMESTAMP WITH TIME ZONE;
        RETURN;
    END IF;
    IF v_operation.status = 'terminal_unavailable' THEN
        UPDATE public.analysis_v2_scheduler_operations AS operation
        SET claim_token = p_operation_claim_token, lease_expires_at = v_now + pg_catalog.make_interval(secs => p_lease_seconds), updated_at = v_now
        WHERE operation.request_id = p_request_id AND operation.operation_key = p_operation_key RETURNING * INTO v_operation;
        RETURN QUERY SELECT 'terminal_unavailable'::TEXT, v_operation.claim_token, TRUE, NULL::JSONB, NULL::TIMESTAMP WITH TIME ZONE;
        RETURN;
    END IF;

    SELECT EXISTS (SELECT 1 FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
        WHERE checkpoint.request_id = p_request_id AND checkpoint.job_key = p_job_key
          AND checkpoint.operation_key = p_operation_key AND checkpoint.stage = p_stage) INTO v_has_result;
    IF v_has_result THEN
        UPDATE public.analysis_v2_scheduler_operations AS operation
        SET claim_token = p_operation_claim_token, lease_expires_at = v_now + pg_catalog.make_interval(secs => p_lease_seconds), updated_at = v_now
        WHERE operation.request_id = p_request_id AND operation.operation_key = p_operation_key RETURNING * INTO v_operation;
        RETURN QUERY SELECT 'execute'::TEXT, v_operation.claim_token, TRUE, NULL::JSONB, NULL::TIMESTAMP WITH TIME ZONE;
        RETURN;
    END IF;

    SELECT EXISTS (SELECT 1 FROM public.analysis_v2_ai_attempts AS attempt
        WHERE attempt.request_id = p_request_id AND attempt.job_key = p_job_key AND attempt.operation_key = p_operation_key) INTO v_has_attempt;
    SELECT EXISTS (SELECT 1 FROM public.analysis_v2_ai_attempts AS attempt
        WHERE attempt.request_id = p_request_id AND attempt.job_key = p_job_key
          AND attempt.operation_key = p_operation_key AND attempt.status <> 'rate_limited') INTO v_has_unsafe_attempt;
    IF v_operation.not_before_at > v_now THEN
        RETURN QUERY SELECT 'deferred'::TEXT, NULL::UUID, FALSE, NULL::JSONB, v_operation.not_before_at;
        RETURN;
    END IF;
    IF v_has_attempt AND NOT v_has_unsafe_attempt AND v_operation.lease_expires_at <= v_now THEN
        UPDATE public.analysis_v2_scheduler_operations AS operation
        SET claim_token = p_operation_claim_token, lease_expires_at = v_now + pg_catalog.make_interval(secs => p_lease_seconds), recovery_deadline_at = v_now + INTERVAL '6 minutes', updated_at = v_now
        WHERE operation.request_id = p_request_id AND operation.operation_key = p_operation_key RETURNING * INTO v_operation;
        RETURN QUERY SELECT 'execute'::TEXT, v_operation.claim_token, FALSE, NULL::JSONB, NULL::TIMESTAMP WITH TIME ZONE;
        RETURN;
    END IF;
    IF v_operation.lease_expires_at <= v_now AND NOT v_has_attempt THEN
        UPDATE public.analysis_v2_scheduler_operations AS operation
        SET claim_token = p_operation_claim_token, lease_expires_at = v_now + pg_catalog.make_interval(secs => p_lease_seconds), recovery_deadline_at = v_now + INTERVAL '6 minutes', updated_at = v_now
        WHERE operation.request_id = p_request_id AND operation.operation_key = p_operation_key RETURNING * INTO v_operation;
        RETURN QUERY SELECT 'execute'::TEXT, v_operation.claim_token, FALSE, NULL::JSONB, NULL::TIMESTAMP WITH TIME ZONE;
        RETURN;
    END IF;
    IF v_has_unsafe_attempt THEN
        IF v_operation.recovery_deadline_at <= v_now THEN
            UPDATE public.analysis_v2_scheduler_operations AS operation
            SET status = 'terminal_unavailable', claim_token = p_operation_claim_token,
                lease_expires_at = v_now + pg_catalog.make_interval(secs => p_lease_seconds), updated_at = v_now
            WHERE operation.request_id = p_request_id AND operation.operation_key = p_operation_key RETURNING * INTO v_operation;
            RETURN QUERY SELECT 'terminal_unavailable'::TEXT, v_operation.claim_token, TRUE, NULL::JSONB, NULL::TIMESTAMP WITH TIME ZONE;
            RETURN;
        END IF;
        RETURN QUERY SELECT 'deferred'::TEXT, NULL::UUID, FALSE, NULL::JSONB, v_operation.recovery_deadline_at;
        RETURN;
    END IF;
    RETURN QUERY SELECT 'deferred'::TEXT, NULL::UUID, FALSE, NULL::JSONB, v_operation.lease_expires_at;
END;
$_$;


--
-- Name: claim_analysis_v2_score_audit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_analysis_v2_score_audit(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_intent public.analysis_v2_score_audit_intents%ROWTYPE;
    v_run public.analysis_v2_score_audit_runs%ROWTYPE;
    v_source public.analysis_v2_score_audit_sources%ROWTYPE;
    v_summary public.analysis_v2_result_summaries%ROWTYPE;
    v_token UUID := extensions.gen_random_uuid();
BEGIN
    -- Global audit lock order: intent -> summary -> run -> checkpoint.
    -- The hard-TTL purge starts from the same intent-row lock.
    SELECT intent.* INTO v_intent
    FROM public.analysis_v2_score_audit_intents AS intent
    WHERE intent.request_id = p_request_id
    FOR UPDATE;
    SELECT summary.* INTO v_summary
    FROM public.analysis_v2_result_summaries AS summary
    JOIN public.analysis_requests AS request ON request.id = summary.request_id
    WHERE summary.request_id = p_request_id AND request.status = 'completed'
    FOR UPDATE OF summary;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT source.* INTO v_source
    FROM public.analysis_v2_score_audit_sources AS source
    WHERE source.request_id = p_request_id
      AND source.source_result_hash = v_intent.source_result_hash
      AND source.source_generation = v_intent.source_generation;
    IF v_intent.request_id IS NOT NULL
       AND v_intent.retain_until <= pg_catalog.clock_timestamp() THEN
        INSERT INTO public.analysis_v2_score_audit_runs (
            request_id, source_result_hash, source_generation,
            risk_policy_version, ai_policy_version, status, reason
        ) VALUES (
            p_request_id, v_intent.source_result_hash, v_intent.source_generation,
            v_summary.score_policy_version, v_source.ai_policy_version,
            'partial', 'SOURCE_EVIDENCE_EXPIRED'
        ) ON CONFLICT (request_id) DO UPDATE SET
            source_result_hash = EXCLUDED.source_result_hash,
            source_generation = EXCLUDED.source_generation,
            risk_policy_version = EXCLUDED.risk_policy_version,
            ai_policy_version = EXCLUDED.ai_policy_version,
            status = 'partial', reason = 'SOURCE_EVIDENCE_EXPIRED',
            lease_token = NULL, lease_expires_at = NULL,
            updated_at = pg_catalog.clock_timestamp();
        UPDATE public.analysis_v2_score_audit_intents
        SET intent_status = 'released', updated_at = pg_catalog.clock_timestamp()
        WHERE request_id = p_request_id
          AND source_result_hash = v_intent.source_result_hash
          AND source_generation = v_intent.source_generation;
        DELETE FROM public.analysis_v2_ai_scoring_stage_checkpoints
        WHERE request_id = p_request_id AND stage_kind = 'final_score'
          AND batch_key = -1 AND result_hash = v_intent.source_result_hash;
        RETURN NULL;
    END IF;
    IF v_intent.request_id IS NULL THEN
        IF v_summary.created_at > pg_catalog.clock_timestamp() - INTERVAL '5 minutes' THEN
            RETURN NULL;
        END IF;
        INSERT INTO public.analysis_v2_score_audit_runs (
            request_id, source_generation, risk_policy_version, status, reason
        ) VALUES (
            p_request_id, 0, v_summary.score_policy_version,
            'partial', 'SOURCE_EVIDENCE_EXPIRED'
        ) ON CONFLICT (request_id) DO UPDATE SET
            status = 'partial', reason = 'SOURCE_EVIDENCE_EXPIRED',
            lease_token = NULL, lease_expires_at = NULL,
            updated_at = pg_catalog.clock_timestamp();
        RETURN NULL;
    END IF;
    IF v_source.request_id IS NOT NULL AND v_source.source_status = 'partial' THEN
        INSERT INTO public.analysis_v2_score_audit_runs (
            request_id, source_result_hash, source_generation,
            risk_policy_version, ai_policy_version, status, reason
        ) VALUES (
            p_request_id, v_intent.source_result_hash, v_intent.source_generation,
            COALESCE(v_source.risk_policy_version, v_summary.score_policy_version),
            v_source.ai_policy_version, 'partial',
            COALESCE(v_source.reason, 'SOURCE_EVIDENCE_UNAVAILABLE')
        ) ON CONFLICT (request_id) DO UPDATE SET
            source_result_hash = EXCLUDED.source_result_hash,
            source_generation = EXCLUDED.source_generation,
            risk_policy_version = EXCLUDED.risk_policy_version,
            ai_policy_version = EXCLUDED.ai_policy_version,
            status = 'partial', reason = EXCLUDED.reason,
            lease_token = NULL, lease_expires_at = NULL,
            updated_at = pg_catalog.clock_timestamp();
        UPDATE public.analysis_v2_score_audit_intents
        SET intent_status = 'released', updated_at = pg_catalog.clock_timestamp()
        WHERE request_id = p_request_id
          AND source_result_hash = v_intent.source_result_hash
          AND source_generation = v_intent.source_generation;
        DELETE FROM public.analysis_v2_ai_scoring_stage_checkpoints
        WHERE request_id = p_request_id AND stage_kind = 'final_score'
          AND batch_key = -1 AND result_hash = v_intent.source_result_hash;
        RETURN NULL;
    END IF;
    IF v_summary.score_policy_version NOT IN ('risk-policy-v2.4', 'risk-policy-v2.5')
       OR (
            v_source.request_id IS NOT NULL
            AND v_source.risk_policy_version IS DISTINCT FROM v_summary.score_policy_version
       ) THEN
        INSERT INTO public.analysis_v2_score_audit_runs (
            request_id, source_result_hash, source_generation, risk_policy_version,
            ai_policy_version, status, reason
        ) VALUES (
            p_request_id, v_intent.source_result_hash, v_intent.source_generation,
            COALESCE(v_source.risk_policy_version, v_summary.score_policy_version),
            v_source.ai_policy_version, 'partial', 'UNSUPPORTED_SCORE_POLICY_VERSION'
        ) ON CONFLICT (request_id) DO UPDATE SET
            source_result_hash = EXCLUDED.source_result_hash,
            source_generation = EXCLUDED.source_generation,
            risk_policy_version = EXCLUDED.risk_policy_version,
            ai_policy_version = EXCLUDED.ai_policy_version,
            status = 'partial', reason = 'UNSUPPORTED_SCORE_POLICY_VERSION',
            lease_token = NULL, lease_expires_at = NULL,
            updated_at = pg_catalog.clock_timestamp();
        UPDATE public.analysis_v2_score_audit_intents
        SET intent_status = 'released', updated_at = pg_catalog.clock_timestamp()
        WHERE request_id = p_request_id
          AND source_result_hash = v_intent.source_result_hash
          AND source_generation = v_intent.source_generation;
        DELETE FROM public.analysis_v2_ai_scoring_stage_checkpoints
        WHERE request_id = p_request_id AND stage_kind = 'final_score'
          AND batch_key = -1 AND result_hash = v_intent.source_result_hash;
        RETURN NULL;
    END IF;
    INSERT INTO public.analysis_v2_score_audit_runs (
        request_id, source_result_hash, source_generation,
        risk_policy_version, ai_policy_version, status
    ) VALUES (
        p_request_id, v_intent.source_result_hash, v_intent.source_generation,
        COALESCE(v_source.risk_policy_version, v_summary.score_policy_version),
        v_source.ai_policy_version, 'queued'
    ) ON CONFLICT (request_id) DO UPDATE SET
        source_result_hash = EXCLUDED.source_result_hash,
        source_generation = EXCLUDED.source_generation,
        risk_policy_version = EXCLUDED.risk_policy_version,
        ai_policy_version = EXCLUDED.ai_policy_version,
        status = 'queued', reason = NULL,
        attempt_count = CASE
            WHEN analysis_v2_score_audit_runs.source_result_hash
                    IS DISTINCT FROM EXCLUDED.source_result_hash
              OR analysis_v2_score_audit_runs.source_generation
                    IS DISTINCT FROM EXCLUDED.source_generation
            THEN 0
            ELSE analysis_v2_score_audit_runs.attempt_count
        END,
        lease_token = NULL, lease_expires_at = NULL,
        updated_at = pg_catalog.clock_timestamp()
    WHERE analysis_v2_score_audit_runs.source_result_hash
                IS DISTINCT FROM EXCLUDED.source_result_hash
       OR analysis_v2_score_audit_runs.source_generation
                IS DISTINCT FROM EXCLUDED.source_generation
       OR (
            analysis_v2_score_audit_runs.status = 'partial'
            AND analysis_v2_score_audit_runs.reason IN (
                'SOURCE_EVIDENCE_UNAVAILABLE','SOURCE_EVIDENCE_EXPIRED',
                'SOURCE_CAPTURE_FAILED'
            )
       );
    SELECT * INTO v_run FROM public.analysis_v2_score_audit_runs
    WHERE request_id = p_request_id FOR UPDATE;
    IF v_run.status NOT IN ('queued','processing')
       OR (v_run.status = 'processing' AND v_run.lease_expires_at > pg_catalog.clock_timestamp())
       THEN RETURN NULL; END IF;
    IF v_run.attempt_count >= 20 THEN
        UPDATE public.analysis_v2_score_audit_runs SET status = 'partial',
            reason = 'RETRY_LIMIT_REACHED', lease_token = NULL,
            lease_expires_at = NULL, updated_at = pg_catalog.clock_timestamp()
        WHERE request_id = p_request_id;
        UPDATE public.analysis_v2_score_audit_intents
        SET intent_status = 'released', updated_at = pg_catalog.clock_timestamp()
        WHERE request_id = p_request_id
          AND source_result_hash = v_run.source_result_hash
          AND source_generation = v_run.source_generation;
        DELETE FROM public.analysis_v2_ai_scoring_stage_checkpoints
        WHERE request_id = p_request_id AND stage_kind = 'final_score'
          AND batch_key = -1 AND result_hash = v_run.source_result_hash;
        RETURN NULL;
    END IF;
    UPDATE public.analysis_v2_score_audit_runs
    SET status = 'processing', attempt_count = attempt_count + 1,
        lease_token = v_token, lease_expires_at = pg_catalog.clock_timestamp() + INTERVAL '2 minutes',
        updated_at = pg_catalog.clock_timestamp()
    WHERE request_id = p_request_id;
    RETURN pg_catalog.jsonb_build_object(
        'leaseToken', v_token::TEXT,
        'sourceResultHash', v_run.source_result_hash,
        'sourceGeneration', v_run.source_generation
    );
END;
$$;


--
-- Name: claim_anonymous_analysis_v2_preflight(uuid, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_anonymous_analysis_v2_preflight(p_preflight_id uuid, p_claim_token_hash character varying, p_user_id uuid) RETURNS TABLE(claimed boolean, preflight_status text, owner_preflight_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT helper.claimed, helper.preflight_status, helper.owner_preflight_id
    FROM private.claim_anonymous_analysis_v2_preflight(
        p_preflight_id,
        p_claim_token_hash,
        p_user_id
    ) AS helper;
END;
$$;


--
-- Name: claim_anonymous_analysis_v2_preflight_with_landing(uuid, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_anonymous_analysis_v2_preflight_with_landing(p_preflight_id uuid, p_claim_token_hash character varying, p_user_id uuid) RETURNS TABLE(claimed boolean, preflight_status text, owner_preflight_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_claimed BOOLEAN;
    v_preflight_status TEXT;
    v_owner_preflight_id UUID;
BEGIN
    SELECT result.claimed, result.preflight_status, result.owner_preflight_id
    INTO v_claimed, v_preflight_status, v_owner_preflight_id
    FROM private.claim_anonymous_analysis_v2_preflight(
        p_preflight_id,
        p_claim_token_hash,
        p_user_id
    ) AS result;

    IF v_claimed IS TRUE
       AND NOT public.claim_landing_lead_journey(p_preflight_id, p_user_id) THEN
        RAISE EXCEPTION 'LANDING_LEAD_JOURNEY_CLAIM_FAILED';
    END IF;

    RETURN QUERY SELECT
        COALESCE(v_claimed, FALSE),
        v_preflight_status,
        v_owner_preflight_id;
END;
$$;


--
-- Name: claim_anonymous_profile_cache_lock(character varying, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_anonymous_profile_cache_lock(p_target_input_hash character varying, p_lease_token uuid, p_lease_seconds integer DEFAULT 60) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_rows INTEGER;
BEGIN
    IF p_target_input_hash !~ '^[0-9a-f]{64}$'
       OR p_lease_token IS NULL
       OR p_lease_seconds IS NULL
       OR p_lease_seconds NOT BETWEEN 5 AND 300 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PROFILE_CACHE_INVALID_LOCK_INPUT', ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.analysis_anonymous_profile_cache_locks(
        target_input_hash, lease_token, lease_expires_at
    ) VALUES (
        p_target_input_hash,
        p_lease_token,
        v_now + make_interval(secs => p_lease_seconds)
    ) ON CONFLICT (target_input_hash) DO NOTHING;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 1 THEN RETURN TRUE; END IF;

    UPDATE public.analysis_anonymous_profile_cache_locks
    SET lease_token = p_lease_token,
        lease_expires_at = v_now + make_interval(secs => p_lease_seconds)
    WHERE target_input_hash = p_target_input_hash
      AND lease_expires_at <= v_now;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    RETURN v_rows = 1;
END;
$_$;


--
-- Name: claim_earlybird_fulfillment(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_earlybird_fulfillment(p_order_id uuid, p_lease_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(claimed boolean, fulfillment_status text, lease_token uuid, lease_fence bigint, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_expected_admission_hash TEXT;
    v_is_admitted BOOLEAN;
BEGIN
    IF p_order_id IS NULL
       OR p_lease_token IS NULL
       OR p_lease_seconds IS NULL
       OR p_lease_seconds NOT BETWEEN 60 AND 600 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    v_is_admitted := v_fulfillment.status IN ('admission_pending', 'retryable_failure');
    IF NOT v_is_admitted
       OR v_fulfillment.operator_admitted_at IS NULL
       OR v_fulfillment.request_id IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_STATE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    IF v_fulfillment.lease_token IS NOT NULL
       AND v_fulfillment.lease_expires_at > v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_LEASE_BUSY',
            ERRCODE = 'P0001';
    END IF;

    v_expected_admission_hash := pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'earlybird-fulfillment-admission-v1'
                    || pg_catalog.chr(10)
                    || pg_catalog.lower(p_order_id::TEXT),
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );
    IF v_order.status <> 'paid'
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_preflight.status <> 'ready'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.admission_status <> 'ready'
       OR v_preflight.admission_selected_plan_id
            IS DISTINCT FROM v_order.plan_id
       OR v_preflight.admission_entitlement_jti_hash
            IS DISTINCT FROM v_expected_admission_hash
       OR v_preflight.admission_token IS NULL
       OR v_preflight.admission_refreshed_at IS NULL
       OR (
            v_preflight.admission_refreshed_at < v_now - INTERVAL '2 minutes'
            AND NOT public.earlybird_concierge_snapshot_conflict_receipt_authorized(
                v_order.id,
                v_preflight.id,
                v_order.target_followers_count,
                v_order.target_following_count,
                v_preflight.target_followers_count,
                v_preflight.target_following_count,
                v_preflight.admission_target_followers_count,
                v_preflight.admission_target_following_count,
                v_preflight.admission_generation,
                v_preflight.admission_refreshed_at
            )
       )
       OR v_preflight.admission_refreshed_at > v_now + INTERVAL '30 seconds'
       OR v_preflight.admission_plan_cards_snapshot
            ->v_order.plan_id->>'selectionState'
            NOT IN ('required', 'available_upgrade') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_ADMISSION_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    IF v_fulfillment.attempt_count >= 10 THEN
        UPDATE public.earlybird_fulfillments AS fulfillment
        SET status = 'manual_review',
            lease_token = NULL,
            lease_expires_at = NULL,
            last_error_code = 'ATTEMPT_EXHAUSTED',
            last_error_at = v_now,
            manual_review_at = v_now,
            updated_at = v_now
        WHERE fulfillment.order_id = p_order_id
        RETURNING fulfillment.* INTO v_fulfillment;
        RETURN QUERY SELECT
            FALSE,
            v_fulfillment.status,
            NULL::UUID,
            v_fulfillment.lease_fence,
            v_fulfillment.attempt_count::INTEGER;
        RETURN;
    END IF;

    UPDATE public.earlybird_fulfillments AS fulfillment
    SET status = 'admission_pending',
        attempt_count = v_fulfillment.attempt_count + 1,
        lease_fence = v_fulfillment.lease_fence + 1,
        lease_token = p_lease_token,
        lease_expires_at = v_now + p_lease_seconds * INTERVAL '1 second',
        last_error_code = NULL,
        last_error_at = NULL,
        updated_at = v_now
    WHERE fulfillment.order_id = p_order_id
    RETURNING fulfillment.* INTO v_fulfillment;

    RETURN QUERY SELECT
        TRUE,
        v_fulfillment.status,
        v_fulfillment.lease_token,
        v_fulfillment.lease_fence,
        v_fulfillment.attempt_count::INTEGER;
END;
$$;


--
-- Name: claim_earlybird_payment_discord_outbox(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_earlybird_payment_discord_outbox(p_limit integer DEFAULT 1) RETURNS TABLE(id uuid, order_id uuid, claim_token uuid, plan_id text, paid_at timestamp with time zone, buyer_name text, gender text, attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RETURN QUERY
    WITH candidates AS (
        SELECT outbox.id
        FROM public.earlybird_payment_discord_outbox AS outbox
        JOIN public.earlybird_orders AS earlybird_order
            ON earlybird_order.id = outbox.order_id
        WHERE outbox.status = 'pending'
          AND outbox.next_attempt_at <= clock_timestamp()
          AND earlybird_order.status = 'paid'
        ORDER BY outbox.created_at
        FOR UPDATE OF outbox SKIP LOCKED
        LIMIT LEAST(GREATEST(COALESCE(p_limit, 1), 1), 10)
    ), claimed AS (
        UPDATE public.earlybird_payment_discord_outbox AS outbox
        SET status = 'sending',
            attempts = outbox.attempts + 1,
            claim_token = uuid_generate_v4(),
            claimed_at = clock_timestamp(),
            updated_at = clock_timestamp()
        FROM candidates
        WHERE outbox.id = candidates.id
        RETURNING outbox.*
    )
    SELECT claimed.id,
           claimed.order_id,
           claimed.claim_token,
           earlybird_order.plan_id::text,
           earlybird_order.paid_at,
           buyer.name::text,
           buyer.gender::text,
           claimed.attempts
    FROM claimed
    JOIN public.earlybird_orders AS earlybird_order
        ON earlybird_order.id = claimed.order_id
    LEFT JOIN public.users AS buyer
        ON buyer.id = earlybird_order.user_id;
END;
$$;


--
-- Name: claim_earlybird_payment_discord_outbox_v2(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_earlybird_payment_discord_outbox_v2(p_limit integer DEFAULT 1) RETURNS TABLE(id uuid, order_id uuid, claim_token uuid, plan_id text, actual_amount_krw integer, paid_at timestamp with time zone, buyer_name text, gender text, attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    RETURN QUERY
    WITH candidates AS (
        SELECT outbox.id
        FROM public.earlybird_payment_discord_outbox AS outbox
        JOIN public.earlybird_orders AS earlybird_order
            ON earlybird_order.id = outbox.order_id
        WHERE outbox.status = 'pending'
          AND outbox.next_attempt_at <= pg_catalog.clock_timestamp()
          AND earlybird_order.status = 'paid'
        ORDER BY outbox.created_at
        FOR UPDATE OF outbox SKIP LOCKED
        LIMIT least(
            greatest(coalesce(p_limit, 1), 1),
            10
        )
    ), claimed AS (
        UPDATE public.earlybird_payment_discord_outbox AS outbox
        SET status = 'sending',
            attempts = outbox.attempts + 1,
            claim_token = public.uuid_generate_v4(),
            claimed_at = pg_catalog.clock_timestamp(),
            updated_at = pg_catalog.clock_timestamp()
        FROM candidates
        WHERE outbox.id = candidates.id
        RETURNING outbox.*
    )
    SELECT claimed.id,
           claimed.order_id,
           claimed.claim_token,
           earlybird_order.plan_id::text,
           earlybird_order.actual_amount_krw,
           earlybird_order.paid_at,
           buyer.name::text,
           buyer.gender::text,
           claimed.attempts
    FROM claimed
    JOIN public.earlybird_orders AS earlybird_order
        ON earlybird_order.id = claimed.order_id
    LEFT JOIN public.users AS buyer
        ON buyer.id = earlybird_order.user_id;
END;
$$;


--
-- Name: claim_expired_analysis_v2_profile_provider_canary_cleanup(integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_expired_analysis_v2_profile_provider_canary_cleanup(p_limit integer DEFAULT 4, p_cleanup_claim_token uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_claimed JSONB;
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 16
       OR p_cleanup_claim_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_INVALID', ERRCODE = 'P0001';
    END IF;
    WITH candidate_keys AS MATERIALIZED (
        SELECT experiment.source_request_id, experiment.canary_version
        FROM public.analysis_v2_profile_provider_canary_experiments AS experiment
        WHERE (
            experiment.state = 'awaiting_repetition_2'
            AND experiment.rep2_approval_deadline_at <= v_now
            AND NOT EXISTS (
                SELECT 1 FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
                WHERE canary_run.source_request_id = experiment.source_request_id
                  AND canary_run.canary_version = experiment.canary_version
                  AND canary_run.repetition = 2
            )
        ) OR (
            experiment.state = 'terminalizing'
            AND experiment.cleanup_lease_expires_at <= v_now
        )
        ORDER BY experiment.rep2_approval_deadline_at, experiment.source_request_id
        FOR UPDATE SKIP LOCKED
        LIMIT p_limit
    ), claimed AS (
        UPDATE public.analysis_v2_profile_provider_canary_experiments AS experiment
        SET state = 'terminalizing',
            terminal_reason = CASE
                WHEN experiment.state = 'awaiting_repetition_2'
                    THEN 'expired_waiting_for_repetition'
                ELSE experiment.terminal_reason END,
            cleanup_claim_token = p_cleanup_claim_token,
            cleanup_claimed_at = v_now,
            cleanup_lease_expires_at = v_now + INTERVAL '10 minutes',
            updated_at = v_now
        FROM candidate_keys AS candidate
        WHERE experiment.source_request_id = candidate.source_request_id
          AND experiment.canary_version = candidate.canary_version
        RETURNING experiment.*
    )
    SELECT COALESCE(pg_catalog.jsonb_agg(
        public.analysis_v2_profile_provider_canary_experiment_json(claimed)
        ORDER BY claimed.source_request_id
    ), '[]'::JSONB)
    INTO v_claimed FROM claimed;
    RETURN v_claimed;
END;
$$;


--
-- Name: claim_kakao_signup_discord_outbox(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_kakao_signup_discord_outbox(p_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 1) RETURNS TABLE(id uuid, claim_token uuid, masked_name text, birthyear character, gender text, signed_up_at timestamp with time zone, attribution_label text, attribution_origin text, attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ BEGIN RETURN QUERY WITH candidates AS (SELECT o.id FROM public.kakao_signup_discord_outbox o WHERE o.status='pending' AND o.profile_staged_at IS NOT NULL AND o.next_attempt_at<=clock_timestamp() AND (p_user_id IS NULL OR o.user_id=p_user_id) ORDER BY o.created_at FOR UPDATE SKIP LOCKED LIMIT LEAST(GREATEST(COALESCE(p_limit,1),1),10)),claimed AS (UPDATE public.kakao_signup_discord_outbox o SET status='sending',attempts=o.attempts+1,claim_token=uuid_generate_v4(),claimed_at=clock_timestamp(),updated_at=clock_timestamp() FROM candidates WHERE o.id=candidates.id RETURNING o.*) SELECT claimed.id,claimed.claim_token,claimed.masked_name,claimed.birthyear,claimed.gender,claimed.signed_up_at,claimed.attribution_label,claimed.attribution_origin,claimed.attempts FROM claimed; END; $$;


--
-- Name: claim_landing_lead_journey(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_landing_lead_journey(p_journey_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_has_rows BOOLEAN;
    v_conflict BOOLEAN;
BEGIN
    SELECT pg_catalog.count(*) > 0,
           pg_catalog.bool_or(auth_user_id IS NOT NULL AND auth_user_id <> p_user_id)
    INTO v_has_rows, v_conflict
    FROM public.landing_leads
    WHERE (journey_id = p_journey_id OR source_preflight_id = p_journey_id)
      AND mapping_status <> 'unlinked_after_deletion';
    IF NOT v_has_rows THEN
        RETURN FALSE;
    END IF;
    IF COALESCE(v_conflict, FALSE) THEN
        RAISE EXCEPTION 'LANDING_LEAD_JOURNEY_CLAIM_CONFLICT';
    END IF;
    UPDATE public.landing_leads
    SET auth_user_id = p_user_id,
        mapping_status = 'authenticated_user',
        mapping_source = 'preflight_v1',
        linked_at = COALESCE(linked_at, pg_catalog.clock_timestamp())
    WHERE (journey_id = p_journey_id OR source_preflight_id = p_journey_id)
      AND auth_user_id IS NULL
      AND mapping_status <> 'unlinked_after_deletion';
    RETURN TRUE;
END;
$$;


--
-- Name: maintenance_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.maintenance_jobs (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    kind text NOT NULL,
    target_key_hash text NOT NULL,
    state text NOT NULL,
    attempt_count smallint DEFAULT 0 NOT NULL,
    lease_generation bigint DEFAULT 0 NOT NULL,
    lease_token uuid,
    lease_holder_hash text,
    lease_expires_at timestamp with time zone,
    next_attempt_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    terminal_at timestamp with time zone,
    last_error_code text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    content_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    legacy_pending_user_id uuid,
    CONSTRAINT maintenance_jobs_attempt_count_check CHECK (((attempt_count >= 0) AND (attempt_count <= 1000))),
    CONSTRAINT maintenance_jobs_content_hash_check CHECK ((content_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT maintenance_jobs_kind_check CHECK ((kind = ANY (ARRAY['recovery'::text, 'replay'::text, 'rearm'::text, 'cleanup'::text, 'terminalize'::text, 'purge'::text, 'audit_assembly'::text]))),
    CONSTRAINT maintenance_jobs_lease_generation_check CHECK ((lease_generation >= 0)),
    CONSTRAINT maintenance_jobs_lease_holder_hash_check CHECK (((lease_holder_hash IS NULL) OR (lease_holder_hash ~ '^[a-f0-9]{64}$'::text))),
    CONSTRAINT maintenance_jobs_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT maintenance_jobs_pending_archive_user_fk_check CHECK ((((legacy_pending_user_id IS NULL) AND (((kind = 'audit_assembly'::text) AND (state = 'succeeded'::text) AND ((payload ->> 'archive_operation'::text) = 'pending_analysis_retirement'::text) AND ((payload ->> 'legacy_source_table'::text) = 'pending_analysis'::text)) IS NOT TRUE)) OR ((legacy_pending_user_id IS NOT NULL) AND (((kind = 'audit_assembly'::text) AND (state = 'succeeded'::text) AND ((payload ->> 'archive_operation'::text) = 'pending_analysis_retirement'::text) AND ((payload ->> 'legacy_source_table'::text) = 'pending_analysis'::text)) IS TRUE) AND (NOT (((payload -> 'legacy_row'::text) ->> 'user_id'::text) IS DISTINCT FROM (legacy_pending_user_id)::text))))),
    CONSTRAINT maintenance_jobs_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'leased'::text, 'succeeded'::text, 'retryable'::text, 'blocked'::text]))),
    CONSTRAINT maintenance_jobs_target_key_hash_check CHECK ((target_key_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY public.maintenance_jobs FORCE ROW LEVEL SECURITY;


--
-- Name: claim_maintenance_jobs_v1(integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_maintenance_jobs_v1(p_limit integer, p_holder_hash text, p_lease_seconds integer) RETURNS SETOF public.maintenance_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
BEGIN
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100
       OR p_holder_hash IS NULL OR p_holder_hash !~ '^[a-f0-9]{64}$'
       OR p_lease_seconds IS NULL OR p_lease_seconds < 60 OR p_lease_seconds > 600 THEN
        RAISE EXCEPTION USING MESSAGE = 'MAINTENANCE_CLAIM_INPUT_INVALID', ERRCODE = 'P0001';
    END IF;
    RETURN QUERY
    WITH candidates AS (
        SELECT maintenance.id
        FROM public.maintenance_jobs AS maintenance
        WHERE maintenance.state IN ('queued', 'retryable')
          AND maintenance.attempt_count < 1000
          AND maintenance.next_attempt_at <= pg_catalog.clock_timestamp()
          AND (maintenance.lease_expires_at IS NULL OR maintenance.lease_expires_at <= pg_catalog.clock_timestamp())
        ORDER BY maintenance.next_attempt_at, maintenance.created_at
        LIMIT p_limit
        FOR UPDATE SKIP LOCKED
    )
    UPDATE public.maintenance_jobs AS maintenance
    SET state = 'leased',
        attempt_count = maintenance.attempt_count + 1,
        lease_generation = maintenance.lease_generation + 1,
        lease_token = extensions.gen_random_uuid(),
        lease_holder_hash = p_holder_hash,
        lease_expires_at = pg_catalog.clock_timestamp() + pg_catalog.make_interval(secs => p_lease_seconds),
        updated_at = pg_catalog.clock_timestamp()
    FROM candidates
    WHERE maintenance.id = candidates.id
    RETURNING maintenance.*;
END;
$_$;


--
-- Name: claim_precheckout_blite_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_precheckout_blite_v1(p_preflight_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_lease UUID := extensions.gen_random_uuid();
    v_cache public.precheckout_blite_cache%ROWTYPE;
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.analysis_preflights AS preflight
        WHERE preflight.id = p_preflight_id
          AND preflight.status = 'ready'
          AND preflight.ready_at IS NOT NULL
          AND preflight.expires_at > v_now
          AND NOT preflight.precheckout_blite_cohort
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.precheckout_blite_cache (
        preflight_id, state, lease_token, lease_expires_at, created_at, updated_at
    ) VALUES (
        p_preflight_id, 'pending', v_lease, v_now + INTERVAL '2 minutes', v_now, v_now
    ) ON CONFLICT (preflight_id) DO NOTHING;

    SELECT cache.* INTO v_cache
    FROM public.precheckout_blite_cache AS cache
    WHERE cache.preflight_id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();

    IF v_cache.state = 'complete' THEN
        RETURN pg_catalog.jsonb_build_object('disposition', 'complete', 'dto', v_cache.dto);
    END IF;
    -- A DB-first v1 caller can observe a terminal v2 row. Preserve the legacy result
    -- vocabulary and leave its immutable failed state entirely untouched.
    IF v_cache.state = 'failed' THEN
        RETURN pg_catalog.jsonb_build_object('disposition', 'pending');
    END IF;
    IF v_cache.lease_token = v_lease THEN
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'claimed', 'leaseToken', v_cache.lease_token
        );
    END IF;
    IF v_cache.lease_expires_at <= v_now THEN
        UPDATE public.precheckout_blite_cache
        SET lease_token = v_lease,
            lease_expires_at = v_now + INTERVAL '2 minutes',
            updated_at = v_now
        WHERE preflight_id = p_preflight_id;
        RETURN pg_catalog.jsonb_build_object('disposition', 'claimed', 'leaseToken', v_lease);
    END IF;
    RETURN pg_catalog.jsonb_build_object('disposition', 'pending');
END;
$$;


--
-- Name: claim_precheckout_blite_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_precheckout_blite_v2(p_preflight_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_lease UUID := extensions.gen_random_uuid();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_source public.precheckout_blite_sources%ROWTYPE;
    v_cache public.precheckout_blite_cache%ROWTYPE;
    v_reason TEXT;
BEGIN
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND
       OR NOT v_preflight.precheckout_blite_cohort
       OR v_preflight.status <> 'ready'
       OR v_preflight.ready_at IS NULL
       OR v_preflight.pii_scrubbed_at IS NOT NULL
       OR v_preflight.expires_at <= v_now
       OR v_preflight.deadline_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT cache.* INTO v_cache
    FROM public.precheckout_blite_cache AS cache
    WHERE cache.preflight_id = v_preflight.id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND THEN
        INSERT INTO public.precheckout_blite_cache (
            preflight_id, state, lease_token, lease_expires_at,
            attempt_count, created_at, updated_at
        ) VALUES (
            v_preflight.id, 'pending', v_lease, v_now,
            0, v_now, v_now
        ) RETURNING * INTO v_cache;
    END IF;

    IF v_cache.state = 'complete' THEN
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'complete', 'dto', v_cache.dto,
            'completedAt', v_cache.completed_at
        );
    END IF;
    IF v_cache.state = 'failed' THEN
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'failed', 'reason', v_cache.failure_reason,
            'failedAt', v_cache.failed_at
        );
    END IF;

    SELECT source.* INTO v_source
    FROM public.precheckout_blite_sources AS source
    WHERE source.preflight_id = v_preflight.id
    FOR UPDATE;

    -- Evaluate expiry/deadline only after every row-lock wait has completed.
    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    IF NOT FOUND THEN
        v_reason := 'source_missing';
    ELSIF NOT (v_source.expires_at > v_now) THEN
        v_reason := 'source_expired';
    ELSIF v_source.target_input_hash IS DISTINCT FROM v_preflight.target_input_hash
       OR v_source.provider_run_id IS DISTINCT FROM v_preflight.id
       OR v_source.payload_bytes > 262144
       OR pg_catalog.jsonb_typeof(v_source.payload) <> 'object' THEN
        v_reason := 'source_invalid';
    ELSIF NOT (v_preflight.deadline_at - INTERVAL '4 seconds' > v_now) THEN
        v_reason := 'inference_timeout';
    ELSIF v_cache.attempt_count >= 2 THEN
        v_reason := 'attempts_exhausted';
    ELSE
        v_reason := NULL;
    END IF;

    IF v_reason IS NOT NULL THEN
        UPDATE public.precheckout_blite_cache
        SET state = 'failed', failure_reason = v_reason, failed_at = v_now,
            updated_at = v_now
        WHERE preflight_id = v_preflight.id
          AND state = 'pending';
        DELETE FROM public.precheckout_blite_sources
        WHERE preflight_id = v_preflight.id;
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'failed', 'reason', v_reason, 'failedAt', v_now
        );
    END IF;

    IF v_cache.lease_expires_at > v_now THEN
        RETURN pg_catalog.jsonb_build_object('disposition', 'pending');
    END IF;

    UPDATE public.precheckout_blite_cache
    SET lease_token = v_lease,
        lease_expires_at = v_now + INTERVAL '2 minutes',
        attempt_count = v_cache.attempt_count + 1,
        updated_at = v_now
    WHERE preflight_id = v_preflight.id
      AND state = 'pending'
      AND lease_token = v_cache.lease_token
      AND lease_expires_at <= v_now
      AND attempt_count < 2;
    IF NOT FOUND THEN
        RETURN pg_catalog.jsonb_build_object('disposition', 'pending');
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'disposition', 'claimed', 'leaseToken', v_lease,
        'source', v_source.payload,
        'submittedAt', v_preflight.submitted_at,
        'deadlineAt', v_preflight.deadline_at,
        'followersCount', v_preflight.target_followers_count,
        'followingCount', v_preflight.target_following_count
    );
END;
$$;


--
-- Name: claim_precheckout_blite_v3(uuid, integer, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_precheckout_blite_v3(p_preflight_id uuid, p_dispatch_generation integer, p_dispatch_token uuid, p_workload_role text DEFAULT 'preflight'::text, p_contract_version smallint DEFAULT 2) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_dispatch public.precheckout_blite_dispatches%ROWTYPE;
    v_result JSONB;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'preflight'
       OR p_contract_version IS DISTINCT FROM 2
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT dispatch.* INTO v_dispatch FROM public.precheckout_blite_dispatches AS dispatch
    WHERE dispatch.preflight_id = p_preflight_id FOR SHARE;
    IF NOT FOUND
       OR v_dispatch.state IS DISTINCT FROM 'enqueued'
       OR v_dispatch.dispatch_generation IS DISTINCT FROM p_dispatch_generation
       OR v_dispatch.last_dispatch_token IS DISTINCT FROM p_dispatch_token
       OR v_dispatch.dispatch_workload_role IS DISTINCT FROM 'preflight'
       OR v_dispatch.dispatch_contract_version IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING MESSAGE = 'PRECHECKOUT_BLITE_DISPATCH_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    v_result := public.claim_precheckout_blite_v2(p_preflight_id);
    IF v_result->>'disposition' = 'claimed' THEN
        UPDATE public.precheckout_blite_cache AS cache
        SET claim_workload_role = 'preflight', claim_contract_version = 2
        WHERE cache.preflight_id = p_preflight_id;
    END IF;
    RETURN v_result;
END;
$$;


--
-- Name: claim_sentry_discord_alert_outbox(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_sentry_discord_alert_outbox(p_limit integer DEFAULT 10, p_dedupe_key text DEFAULT NULL::text) RETURNS TABLE(id uuid, claim_token uuid, project_slug text, occurred_at timestamp with time zone, issue_url text, issue_short_id text, error_type text, release text, attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RETURN QUERY WITH candidates AS (
        SELECT outbox.id FROM public.sentry_discord_alert_outbox AS outbox
        WHERE outbox.status = 'pending' AND outbox.next_attempt_at <= clock_timestamp()
          AND (p_dedupe_key IS NULL OR outbox.dedupe_key = p_dedupe_key)
        ORDER BY outbox.created_at FOR UPDATE SKIP LOCKED
        LIMIT LEAST(GREATEST(COALESCE(p_limit, 10), 1), 10)
    ), claimed AS (
        UPDATE public.sentry_discord_alert_outbox AS outbox
        SET status = 'sending', attempts = outbox.attempts + 1, claim_token = public.uuid_generate_v4(),
            claimed_at = clock_timestamp(), delivery_started_at = NULL, updated_at = clock_timestamp()
        FROM candidates WHERE outbox.id = candidates.id RETURNING outbox.*
    ) SELECT claimed.id, claimed.claim_token, claimed.project_slug, claimed.occurred_at, claimed.issue_url,
        claimed.issue_short_id, claimed.error_type, claimed.release, claimed.attempts FROM claimed;
END;
$$;


--
-- Name: classify_account_principals_v1(jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classify_account_principals_v1(p_assignments jsonb, p_command_version text, p_activate_paid_ever boolean DEFAULT false) RETURNS TABLE(updated_count integer, evidence_count integer, paid_account_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_assignment JSONB;
    v_account public.users%ROWTYPE;
    v_account_id UUID;
    v_account_class TEXT;
    v_traffic_class TEXT;
    v_lifecycle TEXT;
    v_reason_code TEXT;
    v_updated_count INTEGER := 0;
    v_event RECORD;
    v_activation_replay BOOLEAN := FALSE;
    v_rollout_state TEXT;
    v_rollout_command_version TEXT;
BEGIN
    IF p_command_version IS NULL
       OR p_command_version !~ '^[a-z0-9._-]{1,64}$'
       OR p_assignments IS NULL
       OR pg_catalog.jsonb_typeof(p_assignments) IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_array_length(p_assignments) NOT BETWEEN 1 AND 100
       OR (
            SELECT pg_catalog.count(*)
            FROM (
                SELECT assignment ->> 'account_id'
                FROM pg_catalog.jsonb_array_elements(p_assignments)
                    AS assignment
                GROUP BY assignment ->> 'account_id'
                HAVING pg_catalog.count(*) > 1
            ) AS duplicate_assignment
       ) > 0 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_CLASSIFICATION_INPUT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    IF p_activate_paid_ever IS TRUE THEN
        SELECT rollout.paid_ever_state,
            rollout.classification_command_version
        INTO v_rollout_state, v_rollout_command_version
        FROM public.account_ledger_rollout_state AS rollout
        WHERE rollout.singleton IS TRUE;

        IF v_rollout_state = 'active'
           AND v_rollout_command_version IS DISTINCT FROM p_command_version THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ACCOUNT_PAID_EVER_ACTIVATION_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
    ELSE
        SELECT rollout.paid_ever_state
        INTO v_rollout_state
        FROM public.account_ledger_rollout_state AS rollout
        WHERE rollout.singleton IS TRUE;

        IF v_rollout_state = 'active' THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ACCOUNT_CLASSIFICATION_ROLLOUT_ACTIVE',
                ERRCODE = 'P0001';
        END IF;
    END IF;

    FOR v_assignment IN
        SELECT assignment
        FROM pg_catalog.jsonb_array_elements(p_assignments) AS assignment
        ORDER BY assignment ->> 'account_id'
    LOOP
        IF pg_catalog.jsonb_typeof(v_assignment) <> 'object'
           OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_object_keys(v_assignment) AS assignment_key
                WHERE assignment_key NOT IN (
                    'account_id', 'account_class', 'traffic_class',
                    'lifecycle', 'reason_code'
                )
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ACCOUNT_CLASSIFICATION_INPUT_INVALID',
                ERRCODE = 'P0001';
        END IF;

        BEGIN
            v_account_id := (v_assignment ->> 'account_id')::UUID;
        EXCEPTION WHEN invalid_text_representation THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ACCOUNT_CLASSIFICATION_INPUT_INVALID',
                ERRCODE = 'P0001';
        END;
        IF v_account_id IS NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ACCOUNT_CLASSIFICATION_INPUT_INVALID',
                ERRCODE = 'P0001';
        END IF;
        v_account_class := v_assignment ->> 'account_class';
        v_traffic_class := v_assignment ->> 'traffic_class';
        v_lifecycle := v_assignment ->> 'lifecycle';
        v_reason_code := v_assignment ->> 'reason_code';

        IF v_account_class IS NULL
           OR v_account_class NOT IN ('production', 'e2e_test')
           OR v_traffic_class IS NULL
           OR v_traffic_class NOT IN (
                'external', 'operator', 'e2e_test', 'internal_tester'
           )
           OR (
                v_account_class = 'production'
                AND v_traffic_class NOT IN ('external', 'operator')
           )
           OR (
                v_account_class = 'e2e_test'
                AND v_traffic_class NOT IN ('e2e_test', 'internal_tester')
           )
           OR v_lifecycle IS NULL
           OR v_lifecycle NOT IN ('active', 'retired')
           OR v_reason_code IS NULL
           OR v_reason_code !~ '^[A-Z0-9_]{1,64}$' THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ACCOUNT_CLASSIFICATION_INPUT_INVALID',
                ERRCODE = 'P0001';
        END IF;

        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(v_account_id::TEXT, 0)
        );

        SELECT account.*
        INTO v_account
        FROM public.users AS account
        WHERE account.id = v_account_id
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ACCOUNT_CLASSIFICATION_ACCOUNT_NOT_FOUND',
                ERRCODE = 'P0001';
        END IF;

        -- The first rollout read is only an early rejection. A pending
        -- command can have waited for this account lock while activation
        -- completed, so recheck in the account -> rollout lock order before
        -- writing the classification.
        IF p_activate_paid_ever IS NOT TRUE THEN
            SELECT rollout.paid_ever_state
            INTO v_rollout_state
            FROM public.account_ledger_rollout_state AS rollout
            WHERE rollout.singleton IS TRUE
            FOR SHARE;

            IF v_rollout_state = 'active' THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ACCOUNT_CLASSIFICATION_ROLLOUT_ACTIVE',
                    ERRCODE = 'P0001';
            END IF;
        END IF;

        IF p_activate_paid_ever IS TRUE THEN
            SELECT rollout.paid_ever_state,
                rollout.classification_command_version
            INTO v_rollout_state, v_rollout_command_version
            FROM public.account_ledger_rollout_state AS rollout
            WHERE rollout.singleton IS TRUE;

            IF v_rollout_state = 'active' THEN
                IF v_rollout_command_version IS DISTINCT FROM p_command_version THEN
                    RAISE EXCEPTION USING
                        MESSAGE = 'ACCOUNT_PAID_EVER_ACTIVATION_CONFLICT',
                        ERRCODE = 'P0001';
                END IF;
                IF v_account.classification_version IS DISTINCT FROM p_command_version
                   OR v_account.account_class IS DISTINCT FROM v_account_class
                   OR v_account.traffic_class IS DISTINCT FROM v_traffic_class
                   OR v_account.lifecycle IS DISTINCT FROM v_lifecycle
                   OR NOT EXISTS (
                        SELECT 1
                        FROM public.account_classification_audit AS audit
                        WHERE audit.account_id = v_account_id
                          AND audit.command_version = p_command_version
                          AND audit.reason_code = v_reason_code
                          AND audit.next_account_class = v_account_class
                          AND audit.next_traffic_class = v_traffic_class
                          AND audit.next_lifecycle = v_lifecycle
                   ) THEN
                    RAISE EXCEPTION USING
                        MESSAGE = 'ACCOUNT_PAID_EVER_ACTIVATION_CONFLICT',
                        ERRCODE = 'P0001';
                END IF;
                v_activation_replay := TRUE;
            END IF;
        END IF;

        IF NOT v_activation_replay THEN
            INSERT INTO public.account_classification_audit (
                account_id, command_version, reason_code,
                previous_account_class, previous_traffic_class,
                previous_lifecycle, next_account_class, next_traffic_class,
                next_lifecycle
            ) VALUES (
                v_account_id, p_command_version, v_reason_code,
                v_account.account_class, v_account.traffic_class,
                v_account.lifecycle, v_account_class, v_traffic_class,
                v_lifecycle
            );

            UPDATE public.users AS account
            SET account_class = v_account_class,
                traffic_class = v_traffic_class,
                lifecycle = v_lifecycle,
                classification_version = p_command_version
            WHERE account.id = v_account_id;
            v_updated_count := v_updated_count + 1;
        END IF;
    END LOOP;

    IF p_activate_paid_ever THEN
        IF NOT v_activation_replay THEN
            IF EXISTS (
                SELECT 1
                FROM public.users AS account
                WHERE account.classification_version IS NULL
            ) THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ACCOUNT_CLASSIFICATION_INCOMPLETE',
                    ERRCODE = 'P0001';
            END IF;

            UPDATE public.account_ledger_rollout_state AS rollout
            SET paid_ever_state = 'active',
                classification_command_version = p_command_version,
                classification_completed_at = pg_catalog.clock_timestamp(),
                updated_at = pg_catalog.clock_timestamp()
            WHERE rollout.singleton IS TRUE
              AND rollout.paid_ever_state = 'pending';

            IF NOT FOUND AND NOT EXISTS (
                SELECT 1
                FROM public.account_ledger_rollout_state AS rollout
                WHERE rollout.singleton IS TRUE
                  AND rollout.paid_ever_state = 'active'
                  AND rollout.classification_command_version = p_command_version
            ) THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ACCOUNT_PAID_EVER_ACTIVATION_CONFLICT',
                    ERRCODE = 'P0001';
            END IF;
        END IF;

        FOR v_event IN
            SELECT webhook_event.order_id,
                webhook_event.event_id
            FROM public.earlybird_webhook_events AS webhook_event
            JOIN public.earlybird_orders AS paid_order
              ON paid_order.id = webhook_event.order_id
            WHERE webhook_event.event_type = 'payment.completed'
              AND webhook_event.disposition = 'accepted'
              AND webhook_event.order_id IS NOT NULL
              AND webhook_event.payment_id = paid_order.payment_id
              AND webhook_event.product_id
                    = paid_order.actual_groble_product_id
              AND webhook_event.amount_krw = paid_order.actual_amount_krw
              AND paid_order.actual_amount_krw > 0
              AND paid_order.status IN (
                    'paid',
                    'analysis_in_progress',
                    'completed',
                    'overflow_refund_required',
                    'refund_pending',
                    'refunded'
              )
            ORDER BY webhook_event.order_id::TEXT
        LOOP
            PERFORM public.record_external_paid_ever(
                v_event.order_id, v_event.event_id
            );
        END LOOP;
    END IF;

    RETURN QUERY
    SELECT v_updated_count,
        (
            SELECT pg_catalog.count(*)::INTEGER
            FROM public.account_paid_evidence
        ),
        (
            SELECT pg_catalog.count(*)::INTEGER
            FROM public.users AS account
            WHERE account.is_paid_user IS TRUE
        );
END;
$_$;


--
-- Name: clear_analysis_v2_apify_secret_ref_prune_fence(text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_analysis_v2_apify_secret_ref_prune_fence(p_drop_slots text[], p_expected_owner_source_commit_sha text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_drop_slots TEXT[];
    v_guard public.analysis_v2_apify_secret_ref_prune_guard%ROWTYPE;
BEGIN
    IF NOT public.analysis_v2_valid_apify_secret_ref_prune_slots(p_drop_slots)
       OR p_expected_owner_source_commit_sha IS NULL
       OR p_expected_owner_source_commit_sha !~ '^[0-9a-f]{40}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_FENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    v_drop_slots :=
        public.analysis_v2_normalize_apify_secret_ref_prune_slots(p_drop_slots);

    SELECT guard.*
    INTO v_guard
    FROM public.analysis_v2_apify_secret_ref_prune_guard AS guard
    WHERE guard.singleton IS TRUE
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_GUARD_CORRUPT',
            ERRCODE = 'P0001';
    END IF;
    IF v_guard.drop_slots IS NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'active', FALSE,
            'cleared', FALSE,
            'dropSlots', pg_catalog.to_jsonb(v_drop_slots)
        );
    END IF;
    IF v_guard.drop_slots IS DISTINCT FROM v_drop_slots
       OR v_guard.owner_source_commit_sha
            IS DISTINCT FROM p_expected_owner_source_commit_sha THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_FENCE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_v2_apify_secret_ref_prune_guard AS guard
    SET drop_slots = NULL,
        owner_source_commit_sha = NULL,
        fenced_at = NULL,
        updated_at = pg_catalog.clock_timestamp()
    WHERE guard.singleton IS TRUE;

    RETURN pg_catalog.jsonb_build_object(
        'active', FALSE,
        'cleared', TRUE,
        'dropSlots', pg_catalog.to_jsonb(v_drop_slots)
    );
END;
$_$;


--
-- Name: clear_groble_buyer_contacts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_groble_buyer_contacts() RETURNS trigger
