--
-- Name: collect_account_deletion_parity_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collect_account_deletion_parity_v1() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '2min'
    AS $$
WITH source_rows AS (
    SELECT public.canonical_json_hash_v1(
               'account-deletion-target',
               pg_catalog.jsonb_build_object('account_id', source_job.account_id::TEXT)
           ) AS target_key_hash,
           'purge'::TEXT AS kind,
           CASE
               WHEN source_job.state = 'completed' THEN 'succeeded'
               ELSE 'queued'
           END AS canonical_state,
           pg_catalog.jsonb_build_object(
               'source_table', 'account_deletion_jobs',
               'source_key_hash', public.canonical_json_hash_v1(
                   'account-deletion-target',
                   pg_catalog.jsonb_build_object('account_id', source_job.account_id::TEXT)
               ),
               'legacy_state', source_job.state,
               'requested_at', pg_catalog.to_char(
                   source_job.requested_at AT TIME ZONE 'UTC',
                   'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
               ),
               'objects_purged_at', CASE
                   WHEN source_job.objects_purged_at IS NULL THEN NULL
                   ELSE pg_catalog.to_char(
                       source_job.objects_purged_at AT TIME ZONE 'UTC',
                       'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
                   )
               END,
               'database_purged_at', CASE
                   WHEN source_job.database_purged_at IS NULL THEN NULL
                   ELSE pg_catalog.to_char(
                       source_job.database_purged_at AT TIME ZONE 'UTC',
                       'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
                   )
               END,
               'completed_at', CASE
                   WHEN source_job.completed_at IS NULL THEN NULL
                   ELSE pg_catalog.to_char(
                       source_job.completed_at AT TIME ZONE 'UTC',
                       'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
                   )
               END,
               'source_updated_at', pg_catalog.to_char(
                   source_job.updated_at AT TIME ZONE 'UTC',
                   'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
               )
           ) AS payload
    FROM public.account_deletion_jobs AS source_job
), source_projection AS (
    SELECT source_row.target_key_hash,
           source_row.kind,
           source_row.canonical_state,
           source_row.payload,
           public.canonical_json_hash_v1(
               'account-deletion-maintenance-content',
               source_row.payload
           ) AS content_hash
    FROM source_rows AS source_row
), canonical_projection AS (
    SELECT maintenance_job.target_key_hash,
           maintenance_job.kind,
           maintenance_job.state AS canonical_state,
           maintenance_job.payload,
           maintenance_job.content_hash
    FROM public.maintenance_jobs AS maintenance_job
    WHERE maintenance_job.payload->>'source_table' = 'account_deletion_jobs'
), source_summary AS (
    SELECT pg_catalog.count(*)::BIGINT AS source_count,
           CASE
               WHEN pg_catalog.count(*) = 0 THEN NULL
               ELSE pg_catalog.encode(
                   extensions.digest(
                       pg_catalog.convert_to(
                           pg_catalog.string_agg(
                               pg_catalog.length(source_row.target_key_hash)::TEXT
                                   || ':' || source_row.target_key_hash || E'\n'
                                   || source_row.kind || E'\n'
                                   || source_row.canonical_state || E'\n'
                                   || pg_catalog.length(source_row.content_hash)::TEXT
                                   || ':' || source_row.content_hash,
                               E'\n' ORDER BY source_row.target_key_hash
                           ) || E'\n',
                           'UTF8'
                       ),
                       'sha256'
                   ),
                   'hex'
               )
           END AS source_checksum
    FROM source_projection AS source_row
), canonical_summary AS (
    SELECT pg_catalog.count(*)::BIGINT AS canonical_count,
           CASE
               WHEN pg_catalog.count(*) = 0 THEN NULL
               ELSE pg_catalog.encode(
                   extensions.digest(
                       pg_catalog.convert_to(
                           pg_catalog.string_agg(
                               pg_catalog.length(canonical_row.target_key_hash)::TEXT
                                   || ':' || canonical_row.target_key_hash || E'\n'
                                   || canonical_row.kind || E'\n'
                                   || canonical_row.canonical_state || E'\n'
                                   || pg_catalog.length(canonical_row.content_hash)::TEXT
                                   || ':' || canonical_row.content_hash,
                               E'\n' ORDER BY canonical_row.target_key_hash
                           ) || E'\n',
                           'UTF8'
                       ),
                       'sha256'
                   ),
                   'hex'
               )
           END AS canonical_checksum
    FROM canonical_projection AS canonical_row
), canonical_duplicate_keys AS (
    SELECT canonical_row.target_key_hash
    FROM canonical_projection AS canonical_row
    GROUP BY canonical_row.target_key_hash
    HAVING pg_catalog.count(*) > 1
), comparisons AS (
    SELECT source_row.target_key_hash AS source_key,
           canonical_row.target_key_hash AS canonical_key,
           source_row.kind AS source_kind,
           canonical_row.kind AS canonical_kind,
           source_row.canonical_state AS source_state,
           canonical_row.canonical_state AS canonical_state,
           source_row.content_hash AS source_content_hash,
           canonical_row.content_hash AS canonical_content_hash,
           source_row.payload AS source_payload,
           canonical_row.payload AS canonical_payload
    FROM source_projection AS source_row
    FULL OUTER JOIN canonical_projection AS canonical_row
        ON canonical_row.target_key_hash = source_row.target_key_hash
), mismatch_fields AS (
    SELECT 'record_count'::TEXT AS field
    FROM source_summary, canonical_summary
    WHERE source_summary.source_count <> canonical_summary.canonical_count
    UNION
    SELECT 'duplicate_key'::TEXT
    FROM canonical_duplicate_keys
    UNION
    SELECT 'missing_record'::TEXT
    FROM comparisons
    WHERE comparisons.source_key IS NULL OR comparisons.canonical_key IS NULL
    UNION
    SELECT 'kind'::TEXT
    FROM comparisons
    WHERE comparisons.canonical_key IS NOT NULL
      AND comparisons.canonical_kind IS DISTINCT FROM 'purge'
    UNION
    SELECT 'state'::TEXT
    FROM comparisons
    WHERE comparisons.source_key IS NOT NULL
      AND comparisons.canonical_key IS NOT NULL
      AND comparisons.source_state IS DISTINCT FROM comparisons.canonical_state
    UNION
    SELECT 'content_hash'::TEXT
    FROM comparisons
    WHERE comparisons.source_key IS NOT NULL
      AND comparisons.canonical_key IS NOT NULL
      AND comparisons.source_content_hash IS DISTINCT FROM comparisons.canonical_content_hash
    UNION
    SELECT 'payload'::TEXT
    FROM comparisons
    WHERE comparisons.source_key IS NOT NULL
      AND comparisons.canonical_key IS NOT NULL
      AND comparisons.source_payload IS DISTINCT FROM comparisons.canonical_payload
)
SELECT pg_catalog.jsonb_build_object(
    'schema_version', 'supabase-22-account-deletion-parity-v1',
    'status', CASE
        WHEN EXISTS (SELECT 1 FROM mismatch_fields) THEN 'mismatch'
        ELSE 'match'
    END,
    'source_count', source_summary.source_count,
    'canonical_count', canonical_summary.canonical_count,
    'source_checksum', source_summary.source_checksum,
    'canonical_checksum', canonical_summary.canonical_checksum,
    'mismatch_fields', COALESCE(
        (
            SELECT pg_catalog.jsonb_agg(field ORDER BY field)
            FROM mismatch_fields
        ),
        '[]'::JSONB
    )
)
FROM source_summary, canonical_summary;
$$;


--
-- Name: commit_analysis_v2_scheduler_operation(uuid, text, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commit_analysis_v2_scheduler_operation(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_operation_key text, p_stage text, p_operation_claim_token uuid, p_result_json jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_operation public.analysis_v2_scheduler_operations%ROWTYPE;
BEGIN
    IF p_request_id IS NULL OR p_job_claim_token IS NULL
       OR p_operation_claim_token IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_operation_key IS NULL
       OR p_stage IS NULL
       OR NOT public.analysis_v2_valid_ai_operation_key(p_operation_key)
       OR NOT (
            (p_stage = 'genderTriage' AND p_operation_key ~ '^gender-triage:[0-9a-f]{64}$')
            OR (
                p_stage = 'featureAnalysis'
                AND p_operation_key ~ '^feature-analysis:[0-9a-f]{64}$'
            )
            OR (
                p_stage = 'privateAccountName'
                AND p_operation_key ~ '^private-account-name:[0-9a-f]{64}$'
            )
       )
       OR p_result_json IS NULL
       OR pg_catalog.jsonb_typeof(p_result_json) <> 'object'
       OR pg_catalog.octet_length(p_result_json::TEXT) NOT BETWEEN 2 AND 524288 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SCHEDULER_OPERATION_INVALID',
            ERRCODE = 'P0001';
    END IF;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_job_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    SELECT operation.* INTO v_operation
    FROM public.analysis_v2_scheduler_operations AS operation
    WHERE operation.request_id = p_request_id
      AND operation.operation_key = p_operation_key
    FOR UPDATE;
    IF NOT FOUND OR v_operation.job_key <> p_job_key OR v_operation.stage <> p_stage THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SCHEDULER_OPERATION_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_operation.status = 'ready' THEN
        IF v_operation.result_json = p_result_json THEN
            RETURN TRUE;
        END IF;
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SCHEDULER_OPERATION_RESULT_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_operation.claim_token IS DISTINCT FROM p_operation_claim_token
       OR v_operation.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SCHEDULER_OPERATION_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_v2_scheduler_operations AS operation
    SET status = 'ready',
        result_json = p_result_json,
        completed_at = v_now,
        updated_at = v_now
    WHERE operation.request_id = p_request_id
      AND operation.operation_key = p_operation_key;
    RETURN TRUE;
END;
$_$;


--
-- Name: complete_account_deletion_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_account_deletion_v1(p_account_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    UPDATE public.account_deletion_jobs
    SET state = 'completed', completed_at = pg_catalog.clock_timestamp(), updated_at = pg_catalog.clock_timestamp()
    WHERE account_id = p_account_id AND state = 'database_purged';
    RETURN FOUND;
END;
$$;


--
-- Name: complete_analysis_request_and_purge_staging(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_analysis_request_and_purge_staging(p_request_id uuid, p_user_id uuid, p_step_data jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    affected_rows INTEGER;
BEGIN
    IF p_step_data IS NULL OR pg_catalog.jsonb_typeof(p_step_data) <> 'object' THEN
        RAISE EXCEPTION 'invalid compact analysis step data';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_object_keys(p_step_data) AS keys(key_name)
        WHERE keys.key_name NOT IN ('mutualFollows', 'targetProfileImage')
    ) THEN
        RAISE EXCEPTION 'compact analysis step data contains unsupported keys';
    END IF;
    IF p_step_data ? 'mutualFollows'
       AND pg_catalog.jsonb_typeof(p_step_data->'mutualFollows') <> 'array' THEN
        RAISE EXCEPTION 'invalid compact mutual follows';
    END IF;
    IF p_step_data ? 'mutualFollows'
       AND pg_catalog.jsonb_array_length(p_step_data->'mutualFollows') > 10 THEN
        RAISE EXCEPTION 'too many compact mutual follows';
    END IF;
    IF p_step_data ? 'mutualFollows'
       AND EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_array_elements(
               p_step_data->'mutualFollows'
           ) AS mutual(username)
           WHERE pg_catalog.jsonb_typeof(mutual.username) <> 'string'
              OR pg_catalog.char_length(mutual.username #>> '{}') > 30
              OR (mutual.username #>> '{}') !~ '^[a-z0-9._]{1,30}$'
       ) THEN
        RAISE EXCEPTION 'invalid compact mutual follow username';
    END IF;
    IF p_step_data ? 'targetProfileImage'
       AND pg_catalog.jsonb_typeof(p_step_data->'targetProfileImage') <> 'string' THEN
        RAISE EXCEPTION 'invalid compact target profile image';
    END IF;
    IF p_step_data ? 'targetProfileImage'
       AND pg_catalog.char_length(p_step_data->>'targetProfileImage') > 8192 THEN
        RAISE EXCEPTION 'compact target profile image is too long';
    END IF;

    UPDATE public.analysis_requests AS analysis_request
    SET status = 'completed',
        current_step = 'completed',
        progress = 100,
        progress_step = '분석 완료!',
        completed_at = pg_catalog.clock_timestamp(),
        background_processing = FALSE,
        step_data = p_step_data,
        processing_lease_token = NULL,
        processing_lease_expires_at = NULL
    WHERE analysis_request.id = p_request_id
      AND analysis_request.user_id = p_user_id
      AND analysis_request.pipeline_version IS DISTINCT FROM 'v2'
      AND analysis_request.status IN ('pending', 'processing')
      AND COALESCE(analysis_request.current_step, 'pending') = 'finalize';

    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    IF affected_rows <> 1 THEN
        RETURN FALSE;
    END IF;

    DELETE FROM public.analysis_interaction_jobs
    WHERE request_id = p_request_id;
    DELETE FROM public.analysis_interaction_evidence
    WHERE request_id = p_request_id;
    DELETE FROM public.analysis_interaction_scores
    WHERE request_id = p_request_id;
    RETURN TRUE;
END;
$_$;


--
-- Name: complete_analysis_v2_job_and_fanout(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_analysis_v2_job_and_fanout(p_request_id uuid, p_job_key text, p_claim_token uuid, p_successors jsonb DEFAULT '[]'::jsonb) RETURNS TABLE(request_id uuid, completed boolean, job_status text, dispatchable_job_keys text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_successor public.analysis_pipeline_jobs%ROWTYPE;
    v_spec JSONB;
    v_job_key TEXT;
    v_track TEXT;
    v_kind TEXT;
    v_batch INTEGER;
    v_input_hash TEXT;
    v_required_keys TEXT[];
    v_fanout_hash TEXT;
    v_was_completed BOOLEAN := FALSE;
    v_dispatchable TEXT[] := '{}'::TEXT[];
BEGIN
    IF p_request_id IS NULL
       OR p_claim_token IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_successors IS NULL
       OR pg_catalog.jsonb_typeof(p_successors) <> 'array'
       OR pg_catalog.jsonb_array_length(p_successors) > 100
       OR pg_catalog.octet_length(p_successors::TEXT) > 65536 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_JOB_FANOUT_INPUT', ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_successors) AS successor(spec)
        GROUP BY successor.spec->>'jobKey'
        HAVING pg_catalog.count(*) > 1
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_JOB_FANOUT_INPUT', ERRCODE = 'P0001';
    END IF;

    v_fanout_hash := pg_catalog.md5(p_successors::TEXT);

    -- The request row serializes all predecessor completions. The second of two concurrent
    -- completions therefore observes the first commit and opens a join exactly once.
    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    IF v_job.status = 'completed' THEN
        IF v_job.completion_token <> p_claim_token
           OR v_job.completion_fanout_hash <> v_fanout_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_FENCE_MISMATCH', ERRCODE = 'P0001';
        END IF;
        v_was_completed := TRUE;
    ELSIF v_job.status = 'processing' THEN
        IF v_request.status NOT IN ('pending', 'processing')
           OR v_job.lease_token <> p_claim_token
           OR v_job.lease_expires_at <= v_now THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH', ERRCODE = 'P0001';
        END IF;

        UPDATE public.analysis_pipeline_jobs AS job
        SET status = 'completed',
            lease_token = NULL,
            lease_expires_at = NULL,
            completion_token = p_claim_token,
            completion_fanout_hash = v_fanout_hash,
            completed_at = v_now,
            updated_at = v_now
        WHERE job.request_id = p_request_id
          AND job.job_key = p_job_key
        RETURNING job.* INTO v_job;
    ELSE
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    IF v_request.status NOT IN ('pending', 'processing') THEN
        RETURN QUERY SELECT
            p_request_id,
            NOT v_was_completed,
            v_job.status::TEXT,
            '{}'::TEXT[];
        RETURN;
    END IF;

    FOR v_spec IN
        SELECT successor.spec
        FROM pg_catalog.jsonb_array_elements(p_successors) AS successor(spec)
    LOOP
        IF pg_catalog.jsonb_typeof(v_spec) <> 'object'
           OR v_spec - ARRAY[
                'jobKey',
                'track',
                'kind',
                'batch',
                'inputHash',
                'requiredJobKeys'
           ]::TEXT[] <> '{}'::JSONB
           OR NOT (v_spec ?& ARRAY['jobKey', 'track', 'kind', 'batch', 'inputHash'])
           OR pg_catalog.jsonb_typeof(v_spec->'jobKey') <> 'string'
           OR pg_catalog.jsonb_typeof(v_spec->'track') <> 'string'
           OR pg_catalog.jsonb_typeof(v_spec->'kind') <> 'string'
           OR pg_catalog.jsonb_typeof(v_spec->'inputHash') <> 'string'
           OR (
                v_spec ? 'requiredJobKeys'
                AND pg_catalog.jsonb_typeof(v_spec->'requiredJobKeys') <> 'array'
           ) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_JOB_FANOUT_INPUT', ERRCODE = 'P0001';
        END IF;

        v_job_key := v_spec->>'jobKey';
        v_track := v_spec->>'track';
        v_kind := v_spec->>'kind';
        v_input_hash := v_spec->>'inputHash';

        IF pg_catalog.char_length(v_job_key) NOT BETWEEN 1 AND 160
           OR v_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
           OR v_job_key = p_job_key
           OR pg_catalog.char_length(v_track) NOT BETWEEN 1 AND 50
           OR v_track !~ '^[a-z][a-z0-9_]{0,49}$'
           OR pg_catalog.char_length(v_kind) NOT BETWEEN 1 AND 50
           OR v_kind !~ '^[a-z][a-z0-9_]{0,49}$'
           OR v_input_hash !~ '^[a-f0-9]{64}$' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_JOB_FANOUT_INPUT', ERRCODE = 'P0001';
        END IF;

        IF pg_catalog.jsonb_typeof(v_spec->'batch') = 'null' THEN
            v_batch := NULL;
        ELSIF pg_catalog.jsonb_typeof(v_spec->'batch') = 'number'
              AND v_spec->>'batch' ~ '^(0|[1-9][0-9]{0,5})$'
              AND (v_spec->>'batch')::INTEGER BETWEEN 0 AND 100000 THEN
            v_batch := (v_spec->>'batch')::INTEGER;
        ELSE
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_JOB_FANOUT_INPUT', ERRCODE = 'P0001';
        END IF;

        SELECT COALESCE(
            pg_catalog.array_agg(required_key.value ORDER BY required_key.value),
            '{}'::TEXT[]
        )
        INTO v_required_keys
        FROM pg_catalog.jsonb_array_elements_text(
            COALESCE(v_spec->'requiredJobKeys', '[]'::JSONB)
        ) AS required_key(value);

        IF NOT public.analysis_v2_valid_job_keys(v_required_keys)
           OR v_job_key = ANY(v_required_keys) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_JOB_FANOUT_INPUT', ERRCODE = 'P0001';
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM pg_catalog.unnest(v_required_keys) AS required_key(value)
            LEFT JOIN public.analysis_pipeline_jobs AS required_job
              ON required_job.request_id = p_request_id
             AND required_job.job_key = required_key.value
            WHERE required_job.request_id IS NULL
               OR required_job.status <> 'completed'
        ) THEN
            INSERT INTO public.analysis_pipeline_jobs (
                request_id,
                job_key,
                track,
                kind,
                batch,
                input_hash,
                required_job_keys
            ) VALUES (
                p_request_id,
                v_job_key,
                v_track,
                v_kind,
                v_batch,
                v_input_hash,
                v_required_keys
            )
            ON CONFLICT ON CONSTRAINT analysis_pipeline_jobs_pkey DO NOTHING;

            SELECT successor.*
            INTO v_successor
            FROM public.analysis_pipeline_jobs AS successor
            WHERE successor.request_id = p_request_id
              AND successor.job_key = v_job_key
            FOR UPDATE;

            IF NOT FOUND
               OR v_successor.track <> v_track
               OR v_successor.kind <> v_kind
               OR v_successor.batch IS DISTINCT FROM v_batch
               OR v_successor.input_hash <> v_input_hash
               OR v_successor.required_job_keys <> v_required_keys THEN
                RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_FANOUT_CONFLICT', ERRCODE = 'P0001';
            END IF;

            IF v_successor.status = 'pending' THEN
                v_dispatchable := pg_catalog.array_append(v_dispatchable, v_job_key);
            END IF;
        END IF;
    END LOOP;

    SELECT COALESCE(
        pg_catalog.array_agg(DISTINCT dispatchable_key.value ORDER BY dispatchable_key.value),
        '{}'::TEXT[]
    )
    INTO v_dispatchable
    FROM pg_catalog.unnest(v_dispatchable) AS dispatchable_key(value);

    RETURN QUERY SELECT
        p_request_id,
        NOT v_was_completed,
        v_job.status::TEXT,
        v_dispatchable;
END;
$_$;


--
-- Name: complete_analysis_v2_media_artifact_cleanup(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_analysis_v2_media_artifact_cleanup(p_request_id uuid, p_artifact_key text, p_object_generation text, p_cleanup_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_updated INTEGER;
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    IF p_request_id IS NULL
       OR p_artifact_key IS NULL
       OR p_object_generation IS NULL
       OR p_artifact_key !~ '^[a-f0-9]{64}$'
       OR p_object_generation !~ '^[1-9][0-9]{0,31}$'
       OR p_cleanup_token IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_MEDIA_ARTIFACT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_v2_media_artifacts AS artifact
    SET deleted_at = v_now,
        cleanup_token = NULL,
        cleanup_lease_expires_at = NULL
    WHERE artifact.request_id = p_request_id
      AND artifact.artifact_key = p_artifact_key
      AND artifact.object_generation = p_object_generation
      AND artifact.cleanup_token = p_cleanup_token
      AND artifact.cleanup_lease_expires_at > v_now
      AND artifact.deleted_at IS NULL;
    GET DIAGNOSTICS v_updated = ROW_COUNT;

    IF v_updated = 1 THEN
        RETURN TRUE;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM public.analysis_v2_media_artifacts AS artifact
        WHERE artifact.request_id = p_request_id
          AND artifact.artifact_key = p_artifact_key
          AND artifact.object_generation = p_object_generation
          AND artifact.deleted_at IS NOT NULL
    ) THEN
        RETURN FALSE;
    END IF;

    RAISE EXCEPTION USING
        MESSAGE = 'ANALYSIS_V2_MEDIA_ARTIFACT_CLEANUP_FENCE_MISMATCH',
        ERRCODE = 'P0001';
END;
$_$;


--
-- Name: complete_analysis_v2_preflight(uuid, uuid, uuid, text, text, text, integer, integer, boolean, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_analysis_v2_preflight(p_preflight_id uuid, p_user_id uuid, p_claim_token uuid, p_target_full_name text, p_target_bio text, p_target_profile_image_url text, p_target_followers_count integer, p_target_following_count integer, p_target_is_private boolean, p_capacity_required_plan_id text, p_required_plan_id text, p_plan_cards_snapshot jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_plan_id TEXT;
    v_plan_card JSONB;
    v_capacity JSONB;
    v_capacity_rank INTEGER;
    v_required_rank INTEGER;
    v_loop_rank INTEGER;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_claim_token IS NULL
       OR p_target_is_private IS NULL
       OR p_target_is_private
       OR p_target_followers_count IS NULL
       OR p_target_following_count IS NULL
       OR p_target_followers_count < 0
       OR p_target_followers_count > 10000000
       OR p_target_following_count < 0
       OR p_target_following_count > 10000000
       OR p_capacity_required_plan_id IS NULL
       OR p_capacity_required_plan_id NOT IN ('basic', 'standard', 'plus')
       OR p_required_plan_id IS NULL
       OR p_required_plan_id NOT IN ('basic', 'standard', 'plus')
       OR NOT public.analysis_v2_valid_plan_cards_snapshot(p_plan_cards_snapshot)
       OR (p_target_full_name IS NOT NULL AND pg_catalog.char_length(p_target_full_name) > 200)
       OR (p_target_bio IS NOT NULL AND pg_catalog.char_length(p_target_bio) > 2200)
       OR (
           p_target_profile_image_url IS NOT NULL
           AND (
               pg_catalog.char_length(p_target_profile_image_url) > 8192
               OR p_target_profile_image_url !~* '^https://'
           )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_READY_SNAPSHOT', ERRCODE = 'P0001';
    END IF;

    v_capacity_rank := CASE p_capacity_required_plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
    v_required_rank := CASE p_required_plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
    IF v_required_rank < v_capacity_rank
       OR p_plan_cards_snapshot->p_required_plan_id->>'selectionState' <> 'required' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.expires_at <= v_now OR v_preflight.status = 'expired' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_EXPIRED', ERRCODE = 'P0001';
    END IF;

    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        IF p_plan_cards_snapshot->v_plan_id->>'launchStatus'
            IS DISTINCT FROM v_preflight.launch_status_snapshot->>v_plan_id
           OR p_plan_cards_snapshot->v_plan_id->'relationshipCapacity'
            IS DISTINCT FROM v_preflight.plan_catalog_snapshot
                ->v_plan_id->'relationshipCapacity'
           OR p_plan_cards_snapshot->v_plan_id->'detailedMutualLimit'
            IS DISTINCT FROM v_preflight.plan_catalog_snapshot
                ->v_plan_id->'detailedMutualLimit' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
        END IF;
    END LOOP;

    v_plan_card := p_plan_cards_snapshot->p_capacity_required_plan_id;
    v_capacity := v_plan_card->'relationshipCapacity';
    IF p_target_followers_count > (v_capacity->>'followers')::INTEGER
       OR p_target_following_count > (v_capacity->>'following')::INTEGER THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
    END IF;

    v_loop_rank := 0;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_loop_rank := v_loop_rank + 1;
        EXIT WHEN v_loop_rank >= v_capacity_rank;
        v_capacity := p_plan_cards_snapshot->v_plan_id->'relationshipCapacity';
        IF p_target_followers_count <= (v_capacity->>'followers')::INTEGER
           AND p_target_following_count <= (v_capacity->>'following')::INTEGER THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
        END IF;
    END LOOP;

    IF (
        v_preflight.access_mode = 'production'
        AND p_plan_cards_snapshot->p_required_plan_id->>'launchStatus' <> 'production'
    ) OR (
        v_preflight.access_mode = 'test_entitlement'
        AND p_plan_cards_snapshot->p_required_plan_id->>'launchStatus' = 'disabled'
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
    END IF;

    IF v_preflight.status = 'ready' THEN
        IF v_preflight.target_full_name IS NOT DISTINCT FROM p_target_full_name
           AND v_preflight.target_bio IS NOT DISTINCT FROM p_target_bio
           AND v_preflight.target_profile_image_url IS NOT DISTINCT FROM p_target_profile_image_url
           AND v_preflight.target_followers_count = p_target_followers_count
           AND v_preflight.target_following_count = p_target_following_count
           AND v_preflight.target_is_private = p_target_is_private
           AND v_preflight.capacity_required_plan_id = p_capacity_required_plan_id
           AND v_preflight.required_plan_id = p_required_plan_id
           AND v_preflight.plan_cards_snapshot = p_plan_cards_snapshot THEN
            RETURN FALSE;
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_COMPLETION_CONFLICT', ERRCODE = 'P0001';
    END IF;

    IF v_preflight.status <> 'processing' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.lease_token IS DISTINCT FROM p_claim_token
       OR v_preflight.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_LEASE_LOST', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights
    SET status = 'ready',
        target_full_name = p_target_full_name,
        target_bio = p_target_bio,
        target_profile_image_url = p_target_profile_image_url,
        target_followers_count = p_target_followers_count,
        target_following_count = p_target_following_count,
        target_is_private = FALSE,
        capacity_required_plan_id = p_capacity_required_plan_id,
        required_plan_id = p_required_plan_id,
        plan_cards_snapshot = p_plan_cards_snapshot,
        ready_at = v_now,
        lease_token = NULL,
        lease_expires_at = NULL,
        updated_at = v_now
    WHERE id = v_preflight.id;
    RETURN TRUE;
END;
$$;


--
-- Name: complete_analysis_v2_preflight_admission(uuid, integer, uuid, text, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_analysis_v2_preflight_admission(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid, p_target_instagram_id text, p_target_followers_count integer, p_target_following_count integer, p_target_is_private boolean) RETURNS TABLE(admission_status text, admission_error_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_card JSONB;
    v_capacity_rank INTEGER;
    v_required_rank INTEGER;
    v_selected_rank INTEGER;
    v_card_followers INTEGER;
    v_card_following INTEGER;
    v_required_card_count INTEGER;
    v_plan_id TEXT;
    v_status TEXT := 'ready';
    v_error_code TEXT;
BEGIN
    IF p_preflight_id IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_claim_token IS NULL
       OR p_target_instagram_id !~ '^[a-z0-9._]{1,30}$'
       OR p_target_followers_count IS NULL
       OR p_target_followers_count NOT BETWEEN 0 AND 10000000
       OR p_target_following_count IS NULL
       OR p_target_following_count NOT BETWEEN 0 AND 10000000
       OR p_target_is_private IS DISTINCT FROM FALSE THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_FRESH_ADMISSION_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.admission_generation = p_admission_generation
      AND preflight.admission_status = 'processing'
      AND preflight.admission_claim_token = p_claim_token
    FOR UPDATE;

    IF NOT FOUND OR NOT EXISTS (
        SELECT 1
        
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
        WHERE recovery.recovery_preflight_id = p_preflight_id
    ) OR EXISTS (
        SELECT 1
        
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, failed_request_id UUID, source_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'rearm'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_lease_policy_failure_rearms'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','source_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.source_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS incident
          ON incident.order_id = recovery.order_id
         AND incident.failed_request_id = recovery.failed_request_id
         AND incident.rearmed_preflight_id = recovery.recovery_preflight_id
        JOIN public.earlybird_orders AS earlybird_order
          ON earlybird_order.id = recovery.order_id
        JOIN public.earlybird_fulfillments AS fulfillment
          ON fulfillment.order_id = recovery.order_id
        JOIN public.analysis_requests AS failed_request
          ON failed_request.id = recovery.failed_request_id
        WHERE recovery.recovery_preflight_id = p_preflight_id
          AND incident.rearmed_preflight_id = v_preflight.id
          AND incident.source_preflight_id = failed_request.preflight_id
          AND incident.expected_fulfillment_attempt_count = 1
          AND recovery.prior_attempt_count = 1
          AND earlybird_order.preflight_id = v_preflight.id
          AND earlybird_order.user_id = v_preflight.user_id
          AND earlybird_order.target_instagram_id = v_preflight.target_instagram_id
          AND earlybird_order.status = 'paid'
          AND earlybird_order.plan_id = 'basic'
          AND earlybird_order.expected_amount_krw = 990
          AND earlybird_order.actual_amount_krw = 990
          AND earlybird_order.payment_id IS NOT NULL
          AND earlybird_order.seller_reference_confirmed_at IS NOT NULL
          AND earlybird_order.actual_groble_product_id
              IS NOT DISTINCT FROM earlybird_order.expected_groble_product_id
          AND earlybird_order.result_request_id IS NULL
          AND fulfillment.status = 'admission_pending'
          AND fulfillment.request_id IS NULL
          AND failed_request.user_id = earlybird_order.user_id
          AND failed_request.pipeline_version = 'v2'
          AND failed_request.status = 'failed'
          AND failed_request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          AND failed_request.policy_versions_snapshot =
              pg_catalog.jsonb_build_object(
                  'pipeline', 'v2',
                  'risk', 'risk-policy-v2.5',
                  'aiStage', 'ai-stage-policy-v2.11',
                  'scheduler', 'ai-scheduler-v1'
              )
          AND v_preflight.status = 'ready'
          AND v_preflight.consumed_request_id IS NULL
          AND v_preflight.access_mode = 'production'
          AND v_preflight.admission_selected_plan_id = earlybird_order.plan_id
          AND v_preflight.idempotency_key =
              'earlybird.fulfillment.'
              || pg_catalog.replace(earlybird_order.id::TEXT, '-', '') || '.r4'
          AND EXISTS (
              SELECT 1
              FROM public.analysis_v2_failure_receipts AS receipt
              WHERE receipt.request_id = failed_request.id
                AND receipt.failed_job_key = 'track:profile-ai:batch:0'
                AND receipt.error_code = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = failed_request.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
              WHERE checkpoint.request_id = failed_request.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_gemini_leases AS lease
              WHERE lease.request_id = failed_request.id
          )
          AND 7 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = failed_request.id
          )
          AND 6 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = failed_request.id
                AND provider_run.status = 'succeeded'
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = failed_request.id
                AND provider_run.status = 'aborted'
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_provider_cleanup_intents AS cleanup
              WHERE cleanup.request_id = failed_request.id
                AND cleanup.completed_at IS NULL
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_requests AS successor
              WHERE successor.user_id = earlybird_order.user_id
                AND successor.idempotency_key ~ (
                    '^earlybird:' || pg_catalog.lower(earlybird_order.id::TEXT)
                    || '[.]r[0-9]{1,3}$'
                )
          )
    ) THEN
        RETURN QUERY SELECT *
        FROM public.complete_analysis_v2_preflight_admission_core_20260730140000(
            p_preflight_id, p_admission_generation, p_claim_token,
            p_target_instagram_id, p_target_followers_count,
            p_target_following_count, p_target_is_private
        );
        RETURN;
    END IF;

    SELECT earlybird_order.* INTO v_order
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
    INNER JOIN public.earlybird_orders AS earlybird_order
        ON earlybird_order.id = recovery.order_id
    WHERE recovery.recovery_preflight_id = v_preflight.id
      AND earlybird_order.preflight_id = v_preflight.id
    FOR UPDATE OF earlybird_order;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = v_order.id
    FOR UPDATE;
    IF NOT FOUND
       OR v_order.user_id IS DISTINCT FROM v_preflight.user_id
       OR v_order.status <> 'paid'
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_order.payment_id IS NULL
       OR v_order.actual_amount_krw IS NULL
       OR v_order.actual_amount_krw < 0
       OR v_order.actual_amount_krw > v_order.expected_amount_krw
       OR v_order.actual_groble_product_id
            IS DISTINCT FROM v_order.expected_groble_product_id
       OR v_order.plan_id NOT IN ('basic', 'standard')
       OR v_fulfillment.status <> 'admission_pending'
       OR v_preflight.target_instagram_id IS DISTINCT FROM p_target_instagram_id
       OR v_preflight.status <> 'ready'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.expires_at <= v_now
       OR v_preflight.access_mode <> 'production'
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM v_order.plan_id
       OR NOT public.analysis_v2_valid_plan_cards_snapshot(
            v_preflight.plan_cards_snapshot
       )
       OR v_preflight.target_followers_count
            IS DISTINCT FROM v_order.target_followers_count
       OR v_preflight.target_following_count
            IS DISTINCT FROM v_order.target_following_count THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    v_capacity_rank := CASE v_preflight.capacity_required_plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 WHEN 'plus' THEN 3 ELSE NULL END;
    v_required_rank := CASE v_preflight.required_plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 WHEN 'plus' THEN 3 ELSE NULL END;
    v_selected_rank := CASE v_order.plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE NULL END;
    v_required_card_count := 0;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_card := v_preflight.plan_cards_snapshot->v_plan_id;
        IF v_card->>'selectionState' = 'required' THEN
            v_required_card_count := v_required_card_count + 1;
        END IF;
    END LOOP;
    v_card := v_preflight.plan_cards_snapshot->v_order.plan_id;
    IF v_capacity_rank IS NULL
       OR v_required_rank IS NULL
       OR v_selected_rank IS NULL
       OR v_required_rank < v_capacity_rank
       OR v_selected_rank < v_required_rank
       OR v_required_card_count <> 1
       OR v_preflight.plan_cards_snapshot
            ->v_preflight.required_plan_id->>'selectionState'
            IS DISTINCT FROM 'required'
       OR v_preflight.plan_cards_snapshot
            ->v_preflight.required_plan_id->>'launchStatus'
            IS DISTINCT FROM 'production'
       OR v_card->>'launchStatus' IS DISTINCT FROM 'production'
       OR COALESCE(v_card->>'selectionState', '')
            NOT IN ('required', 'available_upgrade')
       OR COALESCE(v_card->'relationshipCapacity'->>'followers', '')
            !~ '^[0-9]+$'
       OR COALESCE(v_card->'relationshipCapacity'->>'following', '')
            !~ '^[0-9]+$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED',
            ERRCODE = 'P0001';
    END IF;
    v_card_followers :=
        (v_card->'relationshipCapacity'->>'followers')::INTEGER;
    v_card_following :=
        (v_card->'relationshipCapacity'->>'following')::INTEGER;
    IF p_target_followers_count > v_card_followers
       OR p_target_following_count > v_card_following THEN
        v_status := 'blocked';
        v_error_code := 'ANALYSIS_V2_PLAN_NOT_ALLOWED';
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET target_followers_count = CASE WHEN v_status = 'ready'
            THEN p_target_followers_count ELSE preflight.target_followers_count END,
        target_following_count = CASE WHEN v_status = 'ready'
            THEN p_target_following_count ELSE preflight.target_following_count END,
        target_is_private = CASE WHEN v_status = 'ready'
            THEN FALSE ELSE preflight.target_is_private END,
        admission_status = v_status,
        admission_refreshed_at = v_now,
        admission_claim_token = NULL,
        admission_lease_expires_at = NULL,
        admission_error_code = v_error_code,
        admission_target_followers_count = p_target_followers_count,
        admission_target_following_count = p_target_following_count,
        admission_capacity_required_plan_id =
            v_preflight.capacity_required_plan_id,
        admission_required_plan_id = v_preflight.required_plan_id,
        admission_plan_cards_snapshot = v_preflight.plan_cards_snapshot,
        updated_at = v_now
    WHERE preflight.id = v_preflight.id;

    RETURN QUERY SELECT v_status, v_error_code;
END;
$_$;


--
-- Name: complete_analysis_v2_preflight_admission_core_20260730140000(uuid, integer, uuid, text, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_analysis_v2_preflight_admission_core_20260730140000(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid, p_target_instagram_id text, p_target_followers_count integer, p_target_following_count integer, p_target_is_private boolean) RETURNS TABLE(admission_status text, admission_error_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_plan_ids CONSTANT TEXT[] := ARRAY['basic', 'standard', 'plus'];
    v_plan_id TEXT;
    v_plan_rank INTEGER;
    v_capacity_rank INTEGER;
    v_required_rank INTEGER;
    v_capacity_required_plan_id TEXT;
    v_required_plan_id TEXT;
    v_catalog_plan JSONB;
    v_capacity JSONB;
    v_launch_status TEXT;
    v_selection_state TEXT;
    v_unavailable_reason TEXT;
    v_cards JSONB := '{}'::JSONB;
    v_status TEXT := 'ready';
    v_error_code TEXT;
BEGIN
    IF p_preflight_id IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_claim_token IS NULL
       OR p_target_instagram_id !~ '^[a-z0-9._]{1,30}$'
       OR p_target_followers_count IS NULL
       OR p_target_followers_count NOT BETWEEN 0 AND 10000000
       OR p_target_following_count IS NULL
       OR p_target_following_count NOT BETWEEN 0 AND 10000000
       OR p_target_is_private IS DISTINCT FROM FALSE THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_FRESH_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.admission_generation = p_admission_generation
      AND preflight.admission_status = 'processing'
      AND preflight.admission_claim_token = p_claim_token
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.target_instagram_id IS DISTINCT FROM p_target_instagram_id THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_TARGET_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status <> 'ready'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.expires_at <= v_now
       OR v_preflight.access_mode NOT IN ('production', 'test_entitlement')
       OR NOT public.analysis_v2_valid_launch_snapshot(
           v_preflight.launch_status_snapshot
       )
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(
           v_preflight.plan_catalog_snapshot
       )
       OR NOT public.analysis_v2_valid_pricing_snapshot(
           v_preflight.pricing_snapshot
       )
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(
           v_preflight.policy_versions_snapshot
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    FOREACH v_plan_id IN ARRAY v_plan_ids LOOP
        IF v_preflight.plan_catalog_snapshot->v_plan_id->>'launchStatus'
            IS DISTINCT FROM v_preflight.launch_status_snapshot->>v_plan_id THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
        END IF;
    END LOOP;

    FOREACH v_plan_id IN ARRAY v_plan_ids LOOP
        v_plan_rank := CASE v_plan_id
            WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_capacity := v_preflight.plan_catalog_snapshot
            ->v_plan_id->'relationshipCapacity';
        IF v_capacity_rank IS NULL
           AND p_target_followers_count <= (v_capacity->>'followers')::INTEGER
           AND p_target_following_count <= (v_capacity->>'following')::INTEGER THEN
            v_capacity_rank := v_plan_rank;
            v_capacity_required_plan_id := v_plan_id;
        END IF;
    END LOOP;

    IF v_capacity_rank IS NOT NULL THEN
        FOREACH v_plan_id IN ARRAY v_plan_ids LOOP
            v_plan_rank := CASE v_plan_id
                WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
            v_launch_status := v_preflight.launch_status_snapshot->>v_plan_id;
            IF v_required_rank IS NULL
               AND v_plan_rank >= v_capacity_rank
               AND (
                   (
                       v_preflight.access_mode = 'test_entitlement'
                       AND v_launch_status <> 'disabled'
                   )
                   OR (
                       v_preflight.access_mode = 'production'
                       AND v_launch_status = 'production'
                   )
               ) THEN
                v_required_rank := v_plan_rank;
                v_required_plan_id := v_plan_id;
            END IF;
        END LOOP;
    END IF;

    IF v_capacity_rank IS NULL THEN
        v_status := 'blocked';
        v_error_code := 'ANALYSIS_V2_OVER_PLUS_CAPACITY';
    ELSIF v_required_rank IS NULL THEN
        v_status := 'blocked';
        v_error_code := 'ANALYSIS_V2_PLAN_NOT_ALLOWED';
    END IF;

    FOREACH v_plan_id IN ARRAY v_plan_ids LOOP
        v_plan_rank := CASE v_plan_id
            WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_catalog_plan := v_preflight.plan_catalog_snapshot->v_plan_id;
        v_launch_status := v_preflight.launch_status_snapshot->>v_plan_id;

        IF v_capacity_rank IS NULL THEN
            v_selection_state := 'unavailable';
            v_unavailable_reason := 'over_plus_capacity';
        ELSIF v_plan_rank < v_capacity_rank THEN
            v_selection_state := 'unavailable';
            v_unavailable_reason := 'below_required_plan';
        ELSIF (
            v_preflight.access_mode = 'test_entitlement'
            AND v_launch_status = 'disabled'
        ) OR (
            v_preflight.access_mode = 'production'
            AND v_launch_status <> 'production'
        ) THEN
            v_selection_state := 'unavailable';
            v_unavailable_reason := 'launch_gate';
        ELSIF v_plan_id = v_required_plan_id THEN
            v_selection_state := 'required';
            v_unavailable_reason := NULL;
        ELSE
            v_selection_state := 'available_upgrade';
            v_unavailable_reason := NULL;
        END IF;

        v_cards := v_cards || pg_catalog.jsonb_build_object(
            v_plan_id,
            pg_catalog.jsonb_build_object(
                'launchStatus', v_launch_status,
                'relationshipCapacity', v_catalog_plan->'relationshipCapacity',
                'detailedMutualLimit', v_catalog_plan->'detailedMutualLimit',
                'selectionState', v_selection_state,
                'unavailableReason', v_unavailable_reason
            )
        );
    END LOOP;

    IF v_status = 'ready' AND NOT public.analysis_v2_valid_plan_cards_snapshot(v_cards) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET target_followers_count = CASE WHEN v_status = 'ready'
            THEN p_target_followers_count ELSE preflight.target_followers_count END,
        target_following_count = CASE WHEN v_status = 'ready'
            THEN p_target_following_count ELSE preflight.target_following_count END,
        target_is_private = CASE WHEN v_status = 'ready'
            THEN FALSE ELSE preflight.target_is_private END,
        capacity_required_plan_id = CASE WHEN v_status = 'ready'
            THEN v_capacity_required_plan_id ELSE preflight.capacity_required_plan_id END,
        required_plan_id = CASE WHEN v_status = 'ready'
            THEN v_required_plan_id ELSE preflight.required_plan_id END,
        plan_cards_snapshot = CASE WHEN v_status = 'ready'
            THEN v_cards ELSE preflight.plan_cards_snapshot END,
        admission_status = v_status,
        admission_refreshed_at = v_now,
        admission_claim_token = NULL,
        admission_lease_expires_at = NULL,
        admission_error_code = v_error_code,
        admission_target_followers_count = p_target_followers_count,
        admission_target_following_count = p_target_following_count,
        admission_capacity_required_plan_id = v_capacity_required_plan_id,
        admission_required_plan_id = v_required_plan_id,
        admission_plan_cards_snapshot = v_cards,
        updated_at = v_now
    WHERE preflight.id = v_preflight.id;

    RETURN QUERY SELECT v_status, v_error_code;
END;
$_$;


--
-- Name: complete_analysis_v2_preflight_with_blite_source_v1(uuid, uuid, uuid, character varying, uuid, text, text, text, text, text, integer, integer, boolean, text, text, jsonb, jsonb, character varying, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_analysis_v2_preflight_with_blite_source_v1(p_preflight_id uuid, p_user_id uuid, p_claim_token uuid, p_target_input_hash character varying, p_provider_run_id uuid, p_provider_operation_key text, p_provider_run_reference text, p_target_full_name text, p_target_bio text, p_target_profile_image_url text, p_target_followers_count integer, p_target_following_count integer, p_target_is_private boolean, p_capacity_required_plan_id text, p_required_plan_id text, p_plan_cards_snapshot jsonb, p_payload jsonb, p_payload_hash character varying, p_collected_at timestamp with time zone, p_expires_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF p_user_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'PRECHECKOUT_BLITE_PREFLIGHT_FENCE_LOST', ERRCODE = 'P0001';
    END IF;
    RETURN public.finalize_preflight_blite_source_v1(
        p_preflight_id, p_user_id, p_claim_token, p_target_input_hash,
        p_provider_run_id, p_provider_operation_key, p_provider_run_reference,
        p_target_full_name, p_target_bio,
        p_target_profile_image_url, p_target_followers_count, p_target_following_count,
        p_target_is_private, p_capacity_required_plan_id, p_required_plan_id,
        p_plan_cards_snapshot, p_payload, p_payload_hash, p_collected_at, p_expires_at
    );
END;
$$;


--
-- Name: complete_analysis_v2_profile_provider_canary_cleanup(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_analysis_v2_profile_provider_canary_cleanup(p_source_request_id uuid, p_cleanup_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_experiment public.analysis_v2_profile_provider_canary_experiments%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL OR p_cleanup_claim_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT experiment.* INTO v_experiment
    FROM public.analysis_v2_profile_provider_canary_experiments AS experiment
    WHERE experiment.source_request_id = p_source_request_id
      AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_experiment.state = 'experiment_terminal'
       AND v_experiment.cleanup_claim_token = p_cleanup_claim_token THEN
        RETURN public.analysis_v2_profile_provider_canary_experiment_json(v_experiment);
    END IF;
    IF v_experiment.state IS DISTINCT FROM 'terminalizing'
       OR v_experiment.cleanup_claim_token IS DISTINCT FROM p_cleanup_claim_token THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_experiment.source_kvs_cleanup_state IS DISTINCT FROM 'verified_absent'
       OR v_experiment.source_dataset_cleanup_state IS DISTINCT FROM 'verified_absent'
       OR v_experiment.source_request_queue_cleanup_state IS DISTINCT FROM 'verified_absent'
       OR EXISTS (
            SELECT 1 FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
            WHERE canary_run.source_request_id = p_source_request_id
              AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
              AND (
                    canary_run.state IN ('starting', 'ambiguous', 'running')
                    OR (canary_run.run_id IS NOT NULL AND (
                        canary_run.cost_status <> 'actual'
                        OR canary_run.cleanup_completed_at IS NULL
                        OR canary_run.kvs_cleanup_state <> 'verified_absent'
                        OR canary_run.dataset_cleanup_state <> 'verified_absent'
                        OR canary_run.request_queue_cleanup_state <> 'verified_absent'
                    ))
              )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_NOT_READY', ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_v2_profile_provider_canary_experiments AS experiment
    SET state = 'experiment_terminal', ordered_set_hmac = NULL,
        hmac_cleared_at = v_now, experiment_terminal_at = v_now, updated_at = v_now
    WHERE experiment.source_request_id = p_source_request_id
      AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
    RETURNING experiment.* INTO v_experiment;
    RETURN public.analysis_v2_profile_provider_canary_experiment_json(v_experiment);
END;
$$;


--
-- Name: complete_analysis_v2_result_and_purge(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_analysis_v2_result_and_purge(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_target_profile_image_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    v_result := public.analysis_v2_complete_result_and_purge_before_v28_tone(
        p_request_id,
        p_job_key,
        p_claim_token,
        p_job_input_hash,
        p_target_profile_image_url
    );
    PERFORM public.analysis_v2_apply_v28_summary_tone(p_request_id);
    PERFORM public.analysis_v2_apply_v211_summary_tone(p_request_id);
    RETURN v_result;
END;
$$;


--
-- Name: complete_analysis_v2_result_and_purge_with_images(uuid, text, uuid, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_analysis_v2_result_and_purge_with_images(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_target_profile_image_url text, p_image_manifest_hash text, p_image_expected_rows integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_manifest public.analysis_v2_result_image_manifests%ROWTYPE;
BEGIN
    SELECT manifest.* INTO v_manifest
    FROM public.analysis_v2_result_image_manifests AS manifest
    WHERE manifest.request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_manifest.producer_job_key IS DISTINCT FROM p_job_key
       OR v_manifest.producer_input_hash IS DISTINCT FROM p_job_input_hash
       OR v_manifest.producer_claim_token IS DISTINCT FROM p_claim_token
       OR v_manifest.ordered_manifest_hash IS DISTINCT FROM p_image_manifest_hash
       OR v_manifest.expected_rows IS DISTINCT FROM p_image_expected_rows
       OR v_manifest.sealed_at IS NULL
       OR NOT public.analysis_v2_result_image_coverage_ok(
            v_manifest.expected_rows,
            v_manifest.durable_rows,
            v_manifest.sourced_images,
            v_manifest.ready_images,
            v_manifest.capture_failed_images
       )
       OR EXISTS (
            SELECT 1 FROM public.analysis_v2_result_image_objects AS image_object
            WHERE image_object.request_id = p_request_id
              AND image_object.is_mandatory
              AND image_object.status <> 'ready'
       )
       OR EXISTS (
            SELECT 1 FROM public.analysis_v2_result_image_objects AS image_object
            WHERE image_object.request_id = p_request_id
              AND image_object.status = 'ready'
              AND image_object.expires_at <= pg_catalog.clock_timestamp()
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_MANIFEST_NOT_READY', ERRCODE = 'P0001';
    END IF;
    RETURN public.complete_analysis_v2_result_and_purge(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash, p_target_profile_image_url
    );
END;
$$;


--
-- Name: complete_analysis_v2_result_image_purge(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_analysis_v2_result_image_purge(p_object_key text, p_claim_token uuid, p_deleted boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request_id UUID;
    v_kind TEXT;
    v_candidate_locator TEXT;
BEGIN
    IF p_claim_token IS NULL
       OR p_object_key !~
            '^v1/[a-f0-9]{32}/(target|female|private)/[a-f0-9]{32}[.]webp$'
       OR NOT p_deleted THEN
        RETURN FALSE;
    END IF;
    DELETE FROM public.analysis_v2_result_image_purge_outbox AS purge
    WHERE purge.object_key = p_object_key
      AND purge.status = 'claimed'
      AND purge.claim_token = p_claim_token
      AND purge.lease_expires_at > v_now
    RETURNING purge.request_id, purge.kind, purge.candidate_locator
    INTO v_request_id, v_kind, v_candidate_locator;
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;
    DELETE FROM public.analysis_v2_result_image_objects AS image_object
    WHERE image_object.request_id = v_request_id
      AND image_object.kind = v_kind
      AND image_object.candidate_locator = v_candidate_locator
      AND image_object.object_key = p_object_key
      AND image_object.expires_at <= v_now;
    RETURN TRUE;
END;
$_$;


--
-- Name: complete_anonymous_analysis_v2_preflight(uuid, uuid, text, text, text, integer, integer, boolean, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_anonymous_analysis_v2_preflight(p_preflight_id uuid, p_claim_token uuid, p_target_full_name text, p_target_bio text, p_target_profile_image_url text, p_target_followers_count integer, p_target_following_count integer, p_target_is_private boolean, p_capacity_required_plan_id text, p_required_plan_id text, p_plan_cards_snapshot jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_plan_id TEXT;
    v_capacity JSONB;
    v_capacity_rank INTEGER;
    v_required_rank INTEGER;
    v_loop_rank INTEGER := 0;
BEGIN
    IF p_preflight_id IS NULL
       OR p_claim_token IS NULL
       OR p_target_is_private IS DISTINCT FROM FALSE
       OR p_target_followers_count IS NULL
       OR p_target_following_count IS NULL
       OR p_target_followers_count < 0
       OR p_target_followers_count > 10000000
       OR p_target_following_count < 0
       OR p_target_following_count > 10000000
       OR p_capacity_required_plan_id IS NULL
       OR p_capacity_required_plan_id NOT IN ('basic', 'standard', 'plus')
       OR p_required_plan_id IS NULL
       OR p_required_plan_id NOT IN ('basic', 'standard', 'plus')
       OR NOT public.analysis_v2_valid_plan_cards_snapshot(p_plan_cards_snapshot)
       OR (p_target_full_name IS NOT NULL AND pg_catalog.char_length(p_target_full_name) > 200)
       OR (p_target_bio IS NOT NULL AND pg_catalog.char_length(p_target_bio) > 2200)
       OR (
           p_target_profile_image_url IS NOT NULL
           AND (
               pg_catalog.char_length(p_target_profile_image_url) > 8192
               OR p_target_profile_image_url !~* '^https://'
           )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_INVALID_READY_SNAPSHOT', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id IS NULL
      AND preflight.provider_selector = 'anonymous_apify'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.expires_at <= v_now OR v_preflight.status = 'expired' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_EXPIRED', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status = 'ready' THEN
        RETURN FALSE;
    END IF;
    IF v_preflight.status <> 'processing'
       OR v_preflight.lease_token IS DISTINCT FROM p_claim_token
       OR v_preflight.lease_expires_at IS NULL
       OR v_preflight.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_LEASE_LOST', ERRCODE = 'P0001';
    END IF;

    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        IF p_plan_cards_snapshot->v_plan_id->>'launchStatus'
                IS DISTINCT FROM v_preflight.launch_status_snapshot->>v_plan_id
           OR p_plan_cards_snapshot->v_plan_id->'relationshipCapacity'
                IS DISTINCT FROM v_preflight.plan_catalog_snapshot->v_plan_id->'relationshipCapacity'
           OR p_plan_cards_snapshot->v_plan_id->>'detailedMutualLimit'
                IS DISTINCT FROM v_preflight.plan_catalog_snapshot->v_plan_id->>'detailedMutualLimit' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
        END IF;
    END LOOP;

    v_capacity_rank := CASE p_capacity_required_plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
    v_required_rank := CASE p_required_plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
    IF v_required_rank < v_capacity_rank
       OR p_plan_cards_snapshot->p_required_plan_id->>'selectionState' <> 'required'
       OR p_plan_cards_snapshot->p_required_plan_id->>'launchStatus' <> 'production' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
    END IF;

    v_capacity := p_plan_cards_snapshot->p_capacity_required_plan_id->'relationshipCapacity';
    IF p_target_followers_count > (v_capacity->>'followers')::INTEGER
       OR p_target_following_count > (v_capacity->>'following')::INTEGER THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
    END IF;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_loop_rank := v_loop_rank + 1;
        EXIT WHEN v_loop_rank >= v_capacity_rank;
        v_capacity := p_plan_cards_snapshot->v_plan_id->'relationshipCapacity';
        IF p_target_followers_count <= (v_capacity->>'followers')::INTEGER
           AND p_target_following_count <= (v_capacity->>'following')::INTEGER THEN
            RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
        END IF;
    END LOOP;

    UPDATE public.analysis_preflights
    SET status = 'ready',
        target_full_name = p_target_full_name,
        target_bio = p_target_bio,
        target_profile_image_url = p_target_profile_image_url,
        target_followers_count = p_target_followers_count,
        target_following_count = p_target_following_count,
        target_is_private = FALSE,
        capacity_required_plan_id = p_capacity_required_plan_id,
        required_plan_id = p_required_plan_id,
        plan_cards_snapshot = p_plan_cards_snapshot,
        ready_at = v_now,
        lease_token = NULL,
        lease_expires_at = NULL,
        updated_at = v_now
    WHERE id = v_preflight.id;
    RETURN TRUE;
END;
$$;


--
-- Name: complete_anonymous_analysis_v2_preflight_with_blite_source_v1(uuid, uuid, character varying, uuid, text, text, text, text, text, integer, integer, boolean, text, text, jsonb, jsonb, character varying, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_anonymous_analysis_v2_preflight_with_blite_source_v1(p_preflight_id uuid, p_claim_token uuid, p_target_input_hash character varying, p_provider_run_id uuid, p_provider_operation_key text, p_provider_run_reference text, p_target_full_name text, p_target_bio text, p_target_profile_image_url text, p_target_followers_count integer, p_target_following_count integer, p_target_is_private boolean, p_capacity_required_plan_id text, p_required_plan_id text, p_plan_cards_snapshot jsonb, p_payload jsonb, p_payload_hash character varying, p_collected_at timestamp with time zone, p_expires_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    RETURN public.finalize_preflight_blite_source_v1(
        p_preflight_id, NULL, p_claim_token, p_target_input_hash,
        p_provider_run_id, p_provider_operation_key, p_provider_run_reference,
        p_target_full_name, p_target_bio,
        p_target_profile_image_url, p_target_followers_count, p_target_following_count,
        p_target_is_private, p_capacity_required_plan_id, p_required_plan_id,
        p_plan_cards_snapshot, p_payload, p_payload_hash, p_collected_at, p_expires_at
    );
END;
$$;


--
-- Name: complete_earlybird_concierge_snapshot_recovery(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_earlybird_concierge_snapshot_recovery(p_order_id uuid, p_preflight_id uuid, p_request_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_payment_id_hint TEXT;
    v_recovery RECORD;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
BEGIN
    IF p_order_id IS NULL OR p_preflight_id IS NULL OR p_request_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_COMPLETION_INVALID',
            ERRCODE = 'P0001';
    END IF;
    SELECT earlybird_order.payment_id INTO v_payment_id_hint
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    IF NOT FOUND OR v_payment_id_hint IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_COMPLETION_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(v_payment_id_hint, 0)
    );
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    SELECT recovery.* INTO v_recovery
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, preflight_id UUID, provider_operation_key TEXT, provider_input_hash VARCHAR(64), provider_run_id_hash VARCHAR(32), expected_manual_review_at TIMESTAMPTZ, expected_admission_refreshed_at TIMESTAMPTZ, old_order_followers_count INTEGER, old_order_following_count INTEGER, old_preflight_followers_count INTEGER, old_preflight_following_count INTEGER, new_witness_followers_count INTEGER, new_witness_following_count INTEGER, old_snapshot_recorded_at TIMESTAMPTZ, new_witness_recorded_at TIMESTAMPTZ, recovery_reason TEXT, followers_absolute_delta INTEGER, following_absolute_delta INTEGER, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_concierge_snapshot_conflict_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','preflight_id','provider_operation_key','provider_input_hash','provider_run_id_hash','expected_manual_review_at','expected_admission_refreshed_at','old_order_followers_count','old_order_following_count','old_preflight_followers_count','old_preflight_following_count','new_witness_followers_count','new_witness_following_count','old_snapshot_recorded_at','new_witness_recorded_at','recovery_reason','followers_absolute_delta','following_absolute_delta','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.preflight_id IS NOT NULL AND decoded.provider_operation_key IS NOT NULL AND decoded.provider_input_hash IS NOT NULL AND decoded.provider_run_id_hash IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.expected_admission_refreshed_at IS NOT NULL AND decoded.old_order_followers_count IS NOT NULL AND decoded.old_order_following_count IS NOT NULL AND decoded.old_preflight_followers_count IS NOT NULL AND decoded.old_preflight_following_count IS NOT NULL AND decoded.new_witness_followers_count IS NOT NULL AND decoded.new_witness_following_count IS NOT NULL AND decoded.old_snapshot_recorded_at IS NOT NULL AND decoded.new_witness_recorded_at IS NOT NULL AND decoded.recovery_reason IS NOT NULL AND decoded.followers_absolute_delta IS NOT NULL AND decoded.following_absolute_delta IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
    WHERE recovery.order_id = p_order_id
      AND recovery.preflight_id = p_preflight_id
    FOR UPDATE;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF v_fulfillment.order_id IS NULL
       OR v_order.id IS NULL
       OR v_preflight.id IS NULL
       OR v_recovery.order_id IS NULL
       OR v_request.id IS NULL
       OR v_order.payment_id IS DISTINCT FROM v_payment_id_hint
       OR v_order.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_order.result_request_id IS DISTINCT FROM v_request.id
       OR v_fulfillment.request_id IS DISTINCT FROM v_request.id
       OR v_preflight.consumed_request_id IS DISTINCT FROM v_request.id
       OR v_request.user_id IS DISTINCT FROM v_order.user_id
       OR v_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status IS DISTINCT FROM 'completed'
       OR EXISTS (
            SELECT 1
            FROM public.analysis_pipeline_jobs AS active_job
            WHERE active_job.request_id = v_request.id
              AND active_job.status IN ('pending', 'processing')
       )
       OR NOT public.earlybird_concierge_snapshot_conflict_receipt_authorized(
            v_order.id,
            v_preflight.id,
            v_order.target_followers_count,
            v_order.target_following_count,
            v_preflight.target_followers_count,
            v_preflight.target_following_count,
            v_preflight.admission_target_followers_count,
            v_preflight.admission_target_following_count,
            v_preflight.admission_generation,
            v_preflight.admission_refreshed_at
       )
       OR EXISTS (
            SELECT 1
            FROM public.earlybird_webhook_events AS refund_event
            WHERE refund_event.payment_id = v_order.payment_id
              AND refund_event.event_type = 'payment.refunded'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_COMPLETION_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_order.status = 'completed'
       AND v_fulfillment.status = 'completed' THEN
        RETURN FALSE;
    END IF;
    IF v_order.status IS DISTINCT FROM 'analysis_in_progress'
       OR v_fulfillment.status IS DISTINCT FROM 'analysis_in_progress' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_COMPLETION_CAS_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    UPDATE public.earlybird_fulfillments AS fulfillment
    SET status = 'completed',
        completed_at = v_now,
        updated_at = v_now
    WHERE fulfillment.order_id = v_order.id
      AND fulfillment.status = 'analysis_in_progress'
      AND fulfillment.request_id = v_request.id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_COMPLETION_CAS_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    UPDATE public.earlybird_orders AS earlybird_order
    SET status = 'completed',
        updated_at = v_now
    WHERE earlybird_order.id = v_order.id
      AND earlybird_order.status = 'analysis_in_progress'
      AND earlybird_order.result_request_id = v_request.id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_COMPLETION_CAS_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    RETURN TRUE;
END;
$$;


--
-- Name: complete_earlybird_payment_discord_outbox(uuid, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_earlybird_payment_discord_outbox(p_outbox_id uuid, p_claim_token uuid, p_outcome text, p_failure_code text DEFAULT NULL::text, p_retry_after_seconds integer DEFAULT 0) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_attempts integer;
BEGIN
    IF p_outcome NOT IN ('sent', 'retry', 'failed', 'ambiguous_failed') THEN
        RAISE EXCEPTION 'EARLYBIRD_PAYMENT_DISCORD_OUTBOX_OUTCOME_INVALID';
    END IF;

    SELECT attempts
    INTO v_attempts
    FROM public.earlybird_payment_discord_outbox
    WHERE id = p_outbox_id
      AND status = 'sending'
      AND claim_token = p_claim_token
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'EARLYBIRD_PAYMENT_DISCORD_OUTBOX_CLAIM_NOT_FOUND';
    END IF;

    UPDATE public.earlybird_payment_discord_outbox
    SET status = CASE
            WHEN p_outcome = 'sent' THEN 'sent'
            WHEN p_outcome = 'retry' AND v_attempts < 3 THEN 'pending'
            WHEN p_outcome = 'ambiguous_failed' THEN 'ambiguous_failed'
            ELSE 'failed'
        END,
        next_attempt_at = CASE
            WHEN p_outcome = 'retry' AND v_attempts < 3
                THEN clock_timestamp()
                    + make_interval(secs => LEAST(
                        GREATEST(COALESCE(p_retry_after_seconds, 1), 1),
                        900
                    ))
            ELSE next_attempt_at
        END,
        sent_at = CASE WHEN p_outcome = 'sent' THEN clock_timestamp() ELSE sent_at END,
        failure_code = CASE WHEN p_outcome = 'sent' THEN NULL ELSE p_failure_code END,
        claim_token = NULL,
        claimed_at = NULL,
        updated_at = clock_timestamp()
    WHERE id = p_outbox_id;
END;
$$;


--
-- Name: complete_kakao_signup_discord_outbox(uuid, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_kakao_signup_discord_outbox(p_outbox_id uuid, p_claim_token uuid, p_outcome text, p_failure_code text DEFAULT NULL::text, p_retry_after_seconds integer DEFAULT 0) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_attempts integer;
BEGIN
    SELECT attempts INTO v_attempts
    FROM public.kakao_signup_discord_outbox
    WHERE id = p_outbox_id AND status = 'sending' AND claim_token = p_claim_token
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'KAKAO_SIGNUP_OUTBOX_CLAIM_NOT_FOUND';
    END IF;

    UPDATE public.kakao_signup_discord_outbox
    SET status = CASE
            WHEN p_outcome = 'sent' THEN 'sent'
            WHEN p_outcome = 'retry' AND v_attempts < 3 THEN 'pending'
            WHEN p_outcome = 'ambiguous_failed' THEN 'ambiguous_failed'
            ELSE 'failed'
        END,
        next_attempt_at = CASE
            WHEN p_outcome = 'retry' AND v_attempts < 3
                THEN clock_timestamp() + make_interval(secs => LEAST(GREATEST(p_retry_after_seconds, 1), 900))
            ELSE next_attempt_at
        END,
        sent_at = CASE WHEN p_outcome = 'sent' THEN clock_timestamp() ELSE sent_at END,
        failure_code = CASE WHEN p_outcome = 'sent' THEN NULL ELSE p_failure_code END,
        claim_token = NULL,
        updated_at = clock_timestamp()
    WHERE id = p_outbox_id;
END;
$$;


--
-- Name: complete_precheckout_blite_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_precheckout_blite_v1(p_preflight_id uuid, p_lease_token uuid, p_dto jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF p_dto IS NULL OR pg_catalog.jsonb_typeof(p_dto) <> 'object' THEN
        RETURN FALSE;
    END IF;
    UPDATE public.precheckout_blite_cache
       SET state = 'complete', dto = p_dto,
           completed_at = pg_catalog.clock_timestamp(),
           updated_at = pg_catalog.clock_timestamp()
     WHERE preflight_id = p_preflight_id
       AND state = 'pending'
       AND lease_token = p_lease_token
       AND lease_expires_at > pg_catalog.clock_timestamp();
    RETURN FOUND;
END;
$$;


--
-- Name: complete_precheckout_blite_v2(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_precheckout_blite_v2(p_preflight_id uuid, p_lease_token uuid, p_dto jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_cache public.precheckout_blite_cache%ROWTYPE;
    v_source public.precheckout_blite_sources%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_lease_token IS NULL
       OR p_dto IS NULL
       OR public.precheckout_blite_v1_dto_is_valid(p_dto) IS DISTINCT FROM TRUE THEN
        RETURN FALSE;
    END IF;

    -- Every lifecycle path takes these locks in parent -> cache -> source order.
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND
       OR NOT v_preflight.precheckout_blite_cohort
       OR v_preflight.status <> 'ready'
       OR v_preflight.pii_scrubbed_at IS NOT NULL
       OR v_preflight.deadline_at IS NULL THEN
        RETURN FALSE;
    END IF;

    SELECT cache.* INTO v_cache
    FROM public.precheckout_blite_cache AS cache
    WHERE cache.preflight_id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND
       OR v_cache.state <> 'pending'
       OR v_cache.lease_token IS DISTINCT FROM p_lease_token
       OR v_cache.lease_expires_at <= v_now THEN
        RETURN FALSE;
    END IF;

    SELECT source.* INTO v_source
    FROM public.precheckout_blite_sources AS source
    WHERE source.preflight_id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND THEN
        UPDATE public.precheckout_blite_cache
        SET state = 'failed', failure_reason = 'source_missing', failed_at = v_now,
            updated_at = v_now
        WHERE preflight_id = p_preflight_id
          AND state = 'pending'
          AND lease_token = p_lease_token
          AND lease_expires_at > v_now;
        RETURN FALSE;
    END IF;

    IF v_source.expires_at <= v_now THEN
        UPDATE public.precheckout_blite_cache
        SET state = 'failed', failure_reason = 'source_expired', failed_at = v_now,
            updated_at = v_now
        WHERE preflight_id = p_preflight_id
          AND state = 'pending'
          AND lease_token = p_lease_token
          AND lease_expires_at > v_now;
        DELETE FROM public.precheckout_blite_sources
        WHERE preflight_id = p_preflight_id;
        RETURN FALSE;
    END IF;

    IF v_source.target_input_hash IS DISTINCT FROM v_preflight.target_input_hash
       OR v_source.provider_run_id IS DISTINCT FROM v_preflight.id
       OR v_source.payload_bytes > 262144
       OR pg_catalog.jsonb_typeof(v_source.payload) <> 'object' THEN
        UPDATE public.precheckout_blite_cache
        SET state = 'failed', failure_reason = 'source_invalid', failed_at = v_now,
            updated_at = v_now
        WHERE preflight_id = p_preflight_id
          AND state = 'pending'
          AND lease_token = p_lease_token
          AND lease_expires_at > v_now;
        DELETE FROM public.precheckout_blite_sources
        WHERE preflight_id = p_preflight_id;
        RETURN FALSE;
    END IF;

    -- A two-minute crash lease does not extend the shared T+56 inference cutoff.
    IF NOT (v_preflight.deadline_at - INTERVAL '4 seconds' > v_now) THEN
        UPDATE public.precheckout_blite_cache
        SET state = 'failed', failure_reason = 'inference_timeout', failed_at = v_now,
            updated_at = v_now
        WHERE preflight_id = p_preflight_id
          AND state = 'pending'
          AND lease_token = p_lease_token
          AND lease_expires_at > v_now;
        DELETE FROM public.precheckout_blite_sources
        WHERE preflight_id = p_preflight_id;
        RETURN FALSE;
    END IF;

    UPDATE public.precheckout_blite_cache
    SET state = 'complete', dto = p_dto, completed_at = v_now,
        updated_at = v_now
    WHERE preflight_id = p_preflight_id
      AND state = 'pending'
      AND lease_token = p_lease_token
      AND lease_expires_at > v_now;
    IF NOT FOUND THEN RETURN FALSE; END IF;

    DELETE FROM public.precheckout_blite_sources
    WHERE preflight_id = p_preflight_id;
    RETURN TRUE;
END;
$$;


--
-- Name: complete_sentry_discord_alert_outbox(uuid, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_sentry_discord_alert_outbox(p_outbox_id uuid, p_claim_token uuid, p_outcome text, p_failure_code text DEFAULT NULL::text, p_retry_after_seconds integer DEFAULT 0) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_attempts integer;
BEGIN
    IF p_outcome NOT IN ('sent', 'retry', 'failed', 'ambiguous_failed') THEN
        RAISE EXCEPTION 'SENTRY_DISCORD_OUTBOX_INVALID_OUTCOME';
    END IF;

    SELECT attempts INTO v_attempts
    FROM public.sentry_discord_alert_outbox
    WHERE id = p_outbox_id AND status = 'sending' AND claim_token = p_claim_token
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'SENTRY_DISCORD_OUTBOX_CLAIM_NOT_FOUND';
    END IF;

    UPDATE public.sentry_discord_alert_outbox
    SET status = CASE
            WHEN p_outcome = 'sent' THEN 'sent'
            WHEN p_outcome = 'retry' AND v_attempts < 3 THEN 'pending'
            WHEN p_outcome = 'ambiguous_failed' THEN 'ambiguous_failed'
            ELSE 'failed'
        END,
        next_attempt_at = CASE
            WHEN p_outcome = 'retry' AND v_attempts < 3 THEN clock_timestamp()
                + make_interval(secs => LEAST(GREATEST(COALESCE(p_retry_after_seconds, 1), 1), 900))
            ELSE next_attempt_at
        END,
        sent_at = CASE WHEN p_outcome = 'sent' THEN clock_timestamp() ELSE sent_at END,
        failure_code = CASE WHEN p_outcome = 'sent' THEN NULL ELSE p_failure_code END,
        claim_token = NULL,
        updated_at = clock_timestamp()
    WHERE id = p_outbox_id;
END;
$$;


--
-- Name: consume_analysis_quota_and_create_request(uuid, text, text, text, text, jsonb, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_analysis_quota_and_create_request(p_user_id uuid, p_email text, p_auth_provider text, p_target_instagram_id text, p_target_gender text, p_scraper_options jsonb, p_idempotency_key text, p_free_analysis_limit integer) RETURNS TABLE(request_id uuid, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    account users%ROWTYPE;
    existing_request_id UUID;
    existing_target_instagram_id TEXT;
    existing_target_gender TEXT;
    existing_scraper_options JSONB;
    new_request_id UUID;
BEGIN
    IF p_email IS NULL OR p_email = '' THEN
        RAISE EXCEPTION 'invalid authenticated email';
    END IF;
    IF p_auth_provider NOT IN ('google', 'kakao') THEN
        RAISE EXCEPTION 'invalid auth provider';
    END IF;
    IF p_target_instagram_id !~ '^[a-z0-9._]+$' THEN
        RAISE EXCEPTION 'invalid Instagram username';
    END IF;
    IF p_target_gender NOT IN ('male', 'female') THEN
        RAISE EXCEPTION 'invalid target gender';
    END IF;
    IF p_scraper_options IS NULL OR jsonb_typeof(p_scraper_options) <> 'object' THEN
        RAISE EXCEPTION 'invalid scraper options';
    END IF;
    IF p_idempotency_key IS NULL
       OR length(p_idempotency_key) < 16
       OR length(p_idempotency_key) > 128
       OR p_idempotency_key !~ '^[A-Za-z0-9._:-]+$' THEN
        RAISE EXCEPTION 'invalid idempotency key';
    END IF;
    IF p_free_analysis_limit < 0 OR p_free_analysis_limit > 100 THEN
        RAISE EXCEPTION 'invalid free analysis limit';
    END IF;

    INSERT INTO users (id, email, provider, analysis_count, is_paid_user)
    VALUES (p_user_id, p_email, p_auth_provider, 0, FALSE)
    ON CONFLICT (id) DO NOTHING;

    SELECT *
    INTO account
    FROM users
    WHERE id = p_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'authenticated user row unavailable';
    END IF;

    SELECT
        id,
        target_instagram_id,
        target_gender,
        COALESCE(step_data->'scraperOptions', '{}'::JSONB)
    INTO
        existing_request_id,
        existing_target_instagram_id,
        existing_target_gender,
        existing_scraper_options
    FROM analysis_requests
    WHERE user_id = p_user_id
      AND idempotency_key = p_idempotency_key;

    IF existing_request_id IS NOT NULL THEN
        IF existing_target_instagram_id IS DISTINCT FROM p_target_instagram_id
           OR existing_target_gender IS DISTINCT FROM p_target_gender
           OR existing_scraper_options IS DISTINCT FROM p_scraper_options THEN
            RAISE EXCEPTION 'ANALYSIS_IDEMPOTENCY_CONFLICT';
        END IF;
        RETURN QUERY SELECT existing_request_id, FALSE;
        RETURN;
    END IF;

    IF NOT (COALESCE(account.is_unlimited, FALSE) OR COALESCE(account.is_paid_user, FALSE))
       AND COALESCE(account.analysis_count, 0) >= p_free_analysis_limit THEN
        RAISE EXCEPTION 'ANALYSIS_LIMIT_EXCEEDED';
    END IF;

    UPDATE users
    SET analysis_count = COALESCE(analysis_count, 0) + 1
    WHERE id = p_user_id;

    INSERT INTO analysis_requests (
        user_id,
        target_instagram_id,
        target_gender,
        status,
        progress,
        progress_step,
        step_data,
        idempotency_key
    ) VALUES (
        p_user_id,
        p_target_instagram_id,
        p_target_gender,
        'pending',
        0,
        '분석 대기 중...',
        CASE
            WHEN p_scraper_options = '{}'::JSONB THEN '{}'::JSONB
            ELSE jsonb_build_object('scraperOptions', p_scraper_options)
        END,
        p_idempotency_key
    )
    RETURNING id INTO new_request_id;

    RETURN QUERY SELECT new_request_id, TRUE;
END;
$_$;


--
-- Name: consume_analysis_v2_authorized_test_entitlement(uuid, uuid, text, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_analysis_v2_authorized_test_entitlement(p_preflight_id uuid, p_user_id uuid, p_selected_plan_id text, p_entitlement_jti_hash text, p_admission_token uuid, p_target_instagram_id text, p_policy_version text, p_operation_slot_map jsonb) RETURNS TABLE(request_id uuid, created boolean, initial_job_key text, request_status text, background_processing boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_consumed RECORD;
    v_settlement JSONB;
BEGIN
    IF p_selected_plan_id IN ('basic', 'standard')
       AND p_policy_version IS NOT DISTINCT FROM 'authorized-free-e2e-v1' THEN
        -- Keep the lock order identical to the base consume RPC
        -- (JTI advisory lock -> user row -> preflight row). The readiness
        -- helper then takes the already-owned preflight lock reentrantly,
        -- so it cannot form a preflight -> JTI cycle with a concurrent
        -- base consume/replay.
        IF p_entitlement_jti_hash IS NOT NULL
           AND p_entitlement_jti_hash ~ '^[a-f0-9]{64}$' THEN
            PERFORM pg_catalog.pg_advisory_xact_lock(
                pg_catalog.hashtextextended(p_entitlement_jti_hash, 0)
            );
            PERFORM 1
            FROM public.users AS account
            WHERE account.id = p_user_id
            FOR UPDATE;
        END IF;

        v_settlement := public.prepare_analysis_v2_authorized_revenue_settlement_admission(
            p_preflight_id,
            p_user_id,
            p_selected_plan_id,
            p_entitlement_jti_hash
        );
        IF v_settlement->>'disposition' = 'pending' THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_REVENUE_SETTLEMENT_PENDING',
                ERRCODE = 'P0001';
        ELSIF v_settlement->>'disposition' = 'ready' THEN
            -- A caller supplied token is part of the signed admission
            -- capability. Never replace it with the canonical DB token:
            -- demand an exact match before handing off to base consumption.
            IF p_admission_token IS DISTINCT FROM (v_settlement->>'admissionToken')::UUID THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ANALYSIS_V2_REVENUE_SETTLEMENT_FENCE',
                    ERRCODE = 'P0001';
            END IF;
        ELSIF v_settlement->>'disposition' NOT IN ('not_applicable', 'replayable') THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_REVENUE_SETTLEMENT_FENCE',
                ERRCODE = 'P0001';
        END IF;
    END IF;

    SELECT consumed.*
    INTO v_consumed
    FROM public.consume_analysis_v2_test_entitlement(
        p_preflight_id,
        p_user_id,
        p_selected_plan_id,
        p_entitlement_jti_hash,
        p_admission_token
    ) AS consumed;

    PERFORM public.bind_analysis_v2_authorized_test_provider_policy(
        v_consumed.request_id,
        p_user_id,
        p_entitlement_jti_hash,
        p_target_instagram_id,
        p_policy_version,
        p_operation_slot_map
    );

    RETURN QUERY SELECT
        v_consumed.request_id::UUID,
        v_consumed.created::BOOLEAN,
        v_consumed.initial_job_key::TEXT,
        v_consumed.request_status::TEXT,
        v_consumed.background_processing::BOOLEAN;
END;
$_$;


--
-- Name: consume_analysis_v2_test_entitlement(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_analysis_v2_test_entitlement(p_preflight_id uuid, p_user_id uuid, p_selected_plan_id text, p_entitlement_jti_hash text, p_admission_token uuid) RETURNS TABLE(request_id uuid, created boolean, initial_job_key text, request_status text, background_processing boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_selected_card JSONB;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_selected_plan_id IS NULL
       OR p_selected_plan_id NOT IN ('basic', 'standard', 'plus')
       OR p_entitlement_jti_hash IS NULL
       OR p_entitlement_jti_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_ENTITLEMENT_INPUT', ERRCODE = 'P0001';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_entitlement_jti_hash, 0)
    );
    PERFORM 1 FROM public.users WHERE id = p_user_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    IF v_preflight.status <> 'consumed' THEN
        IF v_preflight.expires_at <= v_now OR v_preflight.status = 'expired' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_EXPIRED', ERRCODE = 'P0001';
        END IF;
        IF v_preflight.status <> 'ready'
           OR v_preflight.admission_status <> 'ready'
           OR v_preflight.admission_refreshed_at IS NULL
           OR v_preflight.admission_selected_plan_id IS DISTINCT FROM p_selected_plan_id
           OR v_preflight.admission_entitlement_jti_hash
                IS DISTINCT FROM p_entitlement_jti_hash
           OR v_preflight.admission_token IS DISTINCT FROM p_admission_token
           OR v_preflight.admission_refreshed_at < v_now - INTERVAL '2 minutes'
           OR v_preflight.admission_refreshed_at > v_now + INTERVAL '30 seconds' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
        END IF;

        v_selected_card := v_preflight.plan_cards_snapshot->p_selected_plan_id;
        IF v_preflight.target_followers_count IS NULL
           OR v_preflight.target_following_count IS NULL
           OR v_preflight.capacity_required_plan_id IS NULL
           OR v_preflight.required_plan_id IS NULL
           OR NOT public.analysis_v2_valid_plan_cards_snapshot(
               v_preflight.plan_cards_snapshot
           )
           OR v_selected_card->>'selectionState'
                NOT IN ('required', 'available_upgrade')
           OR v_preflight.target_followers_count
                > (v_selected_card->'relationshipCapacity'->>'followers')::INTEGER
           OR v_preflight.target_following_count
                > (v_selected_card->'relationshipCapacity'->>'following')::INTEGER THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN QUERY
    SELECT consumed.request_id,
           consumed.created,
           consumed.initial_job_key,
           consumed.request_status,
           consumed.background_processing
    FROM public.analysis_v2_consume_entitlement_after_admission_internal(
        p_preflight_id,
        p_user_id,
        p_selected_plan_id,
        p_entitlement_jti_hash
    ) AS consumed;
END;
$_$;


--
-- Name: consume_analysis_v2_test_entitlement_pre_job(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_analysis_v2_test_entitlement_pre_job(p_preflight_id uuid, p_user_id uuid, p_selected_plan_id text, p_entitlement_jti_hash text) RETURNS TABLE(request_id uuid, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_existing_request public.analysis_requests%ROWTYPE;
    v_existing_consumption public.analysis_v2_test_entitlement_consumptions%ROWTYPE;
    v_request_id UUID;
    v_idempotency_key TEXT;
    v_selected_card JSONB;
    v_scope_snapshot JSONB;
    v_required_rank INTEGER;
    v_selected_rank INTEGER;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_selected_plan_id IS NULL
       OR p_selected_plan_id NOT IN ('basic', 'standard', 'plus')
       OR p_entitlement_jti_hash IS NULL
       OR p_entitlement_jti_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_ENTITLEMENT_INPUT', ERRCODE = 'P0001';
    END IF;

    -- Serialize a JTI even before its first consumption row exists, so a concurrent use receives
    -- the bounded conflict below instead of a raw unique-constraint error.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_entitlement_jti_hash, 0)
    );

    PERFORM 1
    FROM public.users
    WHERE id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    IF v_preflight.status = 'consumed' THEN
        SELECT analysis_request.*
        INTO v_existing_request
        FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = v_preflight.consumed_request_id
          AND analysis_request.preflight_id = v_preflight.id
          AND analysis_request.user_id = v_preflight.user_id
        FOR UPDATE;

        IF FOUND
           AND v_existing_request.pipeline_version = 'v2'
           AND v_existing_request.plan_access_mode_snapshot = 'test_entitlement'
           AND v_existing_request.selected_plan_id_snapshot = p_selected_plan_id
           AND v_existing_request.test_entitlement_jti_hash = p_entitlement_jti_hash THEN
            RETURN QUERY SELECT v_existing_request.id, FALSE;
            RETURN;
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_ENTITLEMENT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    IF v_preflight.expires_at <= v_now OR v_preflight.status = 'expired' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_EXPIRED', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status <> 'ready' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.exclusion_decision = 'pending' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_EXCLUSION_REQUIRED', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.access_mode <> 'test_entitlement' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
    END IF;

    v_selected_card := v_preflight.plan_cards_snapshot->p_selected_plan_id;
    IF v_selected_card IS NULL
       OR v_selected_card->>'selectionState' NOT IN ('required', 'available_upgrade')
       OR v_selected_card->>'launchStatus' = 'disabled'
       OR v_preflight.pricing_snapshot->p_selected_plan_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
    END IF;

    v_required_rank := CASE v_preflight.required_plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 WHEN 'plus' THEN 3 ELSE NULL END;
    v_selected_rank := CASE p_selected_plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
    IF v_required_rank IS NULL OR v_selected_rank < v_required_rank THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
    END IF;

    SELECT consumption.*
    INTO v_existing_consumption
    FROM public.analysis_v2_test_entitlement_consumptions AS consumption
    WHERE consumption.entitlement_jti_hash = p_entitlement_jti_hash
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing_consumption.preflight_id = v_preflight.id
           AND v_existing_consumption.user_id = v_preflight.user_id
           AND v_existing_consumption.selected_plan_id = p_selected_plan_id THEN
            SELECT analysis_request.*
            INTO v_existing_request
            FROM public.analysis_requests AS analysis_request
            WHERE analysis_request.id = v_existing_consumption.request_id
            FOR UPDATE;
            IF FOUND
               AND v_existing_request.preflight_id = v_preflight.id
               AND v_existing_request.test_entitlement_jti_hash = p_entitlement_jti_hash THEN
                RETURN QUERY SELECT v_existing_request.id, FALSE;
                RETURN;
            END IF;
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_ENTITLEMENT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_existing_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.preflight_id = v_preflight.id
    FOR UPDATE;
    IF FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_ENTITLEMENT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.analysis_requests AS active_request
        WHERE active_request.user_id = p_user_id
          AND active_request.status IN ('pending', 'processing')
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_ALREADY_IN_PROGRESS', ERRCODE = 'P0001';
    END IF;

    v_idempotency_key := 'v2-preflight:' || v_preflight.id::TEXT;
    IF EXISTS (
        SELECT 1
        FROM public.analysis_requests AS idempotent_request
        WHERE idempotent_request.user_id = p_user_id
          AND idempotent_request.idempotency_key = v_idempotency_key
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_ENTITLEMENT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    v_scope_snapshot := pg_catalog.jsonb_build_object(
        'relationshipCapacity', v_selected_card->'relationshipCapacity',
        'detailedMutualLimit', v_selected_card->'detailedMutualLimit'
    );
    IF NOT public.analysis_v2_valid_scope_snapshot(v_scope_snapshot) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PLAN_NOT_ALLOWED', ERRCODE = 'P0001';
    END IF;

    v_request_id := extensions.gen_random_uuid();
    INSERT INTO public.analysis_requests (
        id,
        user_id,
        target_instagram_id,
        target_gender,
        status,
        progress,
        progress_step,
        current_step,
        step_data,
        gender_stats,
        plan_type,
        background_processing,
        idempotency_key,
        pipeline_version,
        preflight_id,
        excluded_instagram_id,
        exclusion_decision_snapshot,
        plan_access_mode_snapshot,
        capacity_required_plan_id_snapshot,
        required_plan_id_snapshot,
        selected_plan_id_snapshot,
        plan_launch_status_snapshot,
        plan_cards_snapshot,
        pricing_version_snapshot,
        pricing_snapshot,
        analysis_scope_snapshot,
        policy_versions_snapshot,
        test_entitlement_jti_hash
    ) VALUES (
        v_request_id,
        v_preflight.user_id,
        v_preflight.target_instagram_id,
        'male',
        'pending',
        0,
        '분석 대기 중...',
        'pending',
        '{}'::JSONB,
        '{}'::JSONB,
        p_selected_plan_id,
        FALSE,
        v_idempotency_key,
        'v2',
        v_preflight.id,
        v_preflight.excluded_instagram_id,
        v_preflight.exclusion_decision,
        v_preflight.access_mode,
        v_preflight.capacity_required_plan_id,
        v_preflight.required_plan_id,
        p_selected_plan_id,
        v_preflight.launch_status_snapshot,
        v_preflight.plan_cards_snapshot,
        v_preflight.pricing_version,
        v_preflight.pricing_snapshot,
        v_scope_snapshot,
        v_preflight.policy_versions_snapshot,
        p_entitlement_jti_hash
    );

    UPDATE public.analysis_preflights
    SET status = 'consumed',
        consumed_at = v_now,
        consumed_request_id = v_request_id,
        updated_at = v_now
    WHERE id = v_preflight.id;

    INSERT INTO public.analysis_v2_test_entitlement_consumptions (
        entitlement_jti_hash,
        preflight_id,
        request_id,
        user_id,
        selected_plan_id,
        consumed_at
    ) VALUES (
        p_entitlement_jti_hash,
        v_preflight.id,
        v_request_id,
        v_preflight.user_id,
        p_selected_plan_id,
        v_now
    );

    RETURN QUERY SELECT v_request_id, TRUE;
END;
$_$;


--
-- Name: continue_analysis_v2_scheduler_job(uuid, text, uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.continue_analysis_v2_scheduler_job(p_request_id uuid, p_job_key text, p_claim_token uuid, p_dispatch_token uuid, p_error_code text, p_delay_seconds integer) RETURNS TABLE(reserved boolean, dispatch_generation integer, reservation_token uuid, job_status text, dispatch_state text, task_name text, attempt_count integer, request_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    PERFORM public.assert_analysis_revenue_dispatch_guard_v1(p_request_id, p_job_key);
    RETURN QUERY
    SELECT * FROM public.continue_analysis_v2_scheduler_job_unfenced_20260811(
        p_request_id, p_job_key, p_claim_token, p_dispatch_token,
        p_error_code, p_delay_seconds
    );
END;
$$;


--
-- Name: continue_analysis_v2_scheduler_job_unfenced_20260811(uuid, text, uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.continue_analysis_v2_scheduler_job_unfenced_20260811(p_request_id uuid, p_job_key text, p_claim_token uuid, p_dispatch_token uuid, p_error_code text, p_delay_seconds integer) RETURNS TABLE(reserved boolean, dispatch_generation integer, reservation_token uuid, job_status text, dispatch_state text, task_name text, attempt_count integer, request_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL OR p_claim_token IS NULL OR p_dispatch_token IS NULL
       OR p_error_code IS NULL
       OR p_delay_seconds IS NULL OR p_delay_seconds NOT BETWEEN 1 AND 300
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_error_code NOT IN (
            'ANALYSIS_V2_AI_DEADLINE_TOO_SHORT',
            'ANALYSIS_V2_AI_RESULT_RECOVERY_PENDING',
            'ANALYSIS_V2_AI_CAPACITY_PENDING',
            'ANALYSIS_V2_AI_QUARANTINE_ACTIVE'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SCHEDULER_CONTINUATION_INVALID',
            ERRCODE = 'P0001';
    END IF;
    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id
      AND request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND OR v_request.status NOT IN ('pending', 'processing')
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now
       OR v_job.attempt_count < 1
       OR v_job.dispatch_generation NOT BETWEEN 1 AND 999 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_pipeline_jobs AS job
    SET status = 'pending',
        dispatch_state = 'reserved',
        dispatch_generation = job.dispatch_generation + 1,
        dispatch_reservation_token = p_dispatch_token,
        dispatch_reserved_at = v_now,
        dispatched_at = NULL,
        dispatch_task_name = NULL,
        delivered_at = NULL,
        lease_token = NULL,
        lease_expires_at = NULL,
        attempt_count = job.attempt_count - 1,
        first_started_at = CASE
            WHEN job.attempt_count = 1 THEN NULL
            ELSE job.first_started_at
        END,
        ai_capacity_deferral_count = job.ai_capacity_deferral_count + 1,
        last_error_code = p_error_code,
        last_error_at = v_now,
        scheduler_not_before_at =
            v_now + pg_catalog.make_interval(secs => p_delay_seconds),
        updated_at = v_now
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    RETURNING job.* INTO v_job;

    RETURN QUERY SELECT
        TRUE,
        v_job.dispatch_generation,
        v_job.dispatch_reservation_token,
        v_job.status::TEXT,
        v_job.dispatch_state::TEXT,
        NULL::TEXT,
        v_job.attempt_count,
        v_request.status::TEXT;
END;
$_$;


--
-- Name: copy_earlybird_order_scoped_apify_slot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copy_earlybird_order_scoped_apify_slot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.preflight_id IS DISTINCT FROM OLD.preflight_id
       AND NEW.preflight_id IS NOT NULL
       AND NEW.concierge_apify_credential_slot IS NOT NULL THEN
        UPDATE public.analysis_preflights
        SET order_scoped_apify_credential_slot = NEW.concierge_apify_credential_slot
        WHERE id = NEW.preflight_id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: create_anonymous_analysis_v2_preflight(text, character varying, character varying, character varying, timestamp with time zone, jsonb, jsonb, character varying, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_anonymous_analysis_v2_preflight(p_target_instagram_id text, p_target_input_hash character varying, p_idempotency_key character varying, p_claim_token_hash character varying, p_claim_expires_at timestamp with time zone, p_launch_status_snapshot jsonb, p_plan_catalog_snapshot jsonb, p_pricing_version character varying, p_pricing_snapshot jsonb, p_policy_versions_snapshot jsonb) RETURNS TABLE(preflight_id uuid, expires_at timestamp with time zone, created boolean, preflight_status text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_existing public.analysis_preflights%ROWTYPE;
    v_id UUID;
    v_expires TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_target_instagram_id IS NULL
       OR p_target_instagram_id !~ '^[a-z0-9._]{1,30}$'
       OR p_target_input_hash !~ '^[0-9a-f]{64}$'
       OR p_idempotency_key IS NULL
       OR p_idempotency_key !~ '^[A-Za-z0-9._:-]{16,128}$'
       OR p_claim_token_hash !~ '^[0-9a-f]{64}$'
       OR p_claim_expires_at IS NULL
       OR p_claim_expires_at <= v_now
       OR p_claim_expires_at > v_now + INTERVAL '30 minutes'
       OR NOT public.analysis_v2_valid_launch_snapshot(p_launch_status_snapshot)
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(p_plan_catalog_snapshot)
       OR NOT public.analysis_v2_valid_pricing_snapshot(p_pricing_snapshot)
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(p_policy_versions_snapshot) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_INVALID_INPUT', ERRCODE = 'P0001';
    END IF;

    PERFORM pg_catalog.set_config(
        'app.anonymous_preflight_claim_hash', p_claim_token_hash, TRUE
    );
    PERFORM pg_catalog.set_config(
        'app.anonymous_preflight_idempotency_key', p_idempotency_key, TRUE
    );
    PERFORM pg_catalog.set_config(
        'app.anonymous_preflight_target_hash', p_target_input_hash, TRUE
    );

    -- Serialize the replay/create decision for one anonymous idempotency key.
    -- The partial unique index remains the database invariant.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('anonymous-preflight-idempotency:' || p_idempotency_key, 0)
    );

    SELECT preflight.* INTO v_existing
    FROM public.analysis_preflights AS preflight
    WHERE preflight.user_id IS NULL
      AND preflight.idempotency_key = p_idempotency_key
    ORDER BY preflight.created_at DESC
    LIMIT 1
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.status = 'expired' OR v_existing.expires_at <= v_now THEN
            UPDATE public.analysis_preflights
            SET status = 'expired',
                claim_token_hash = NULL,
                claim_expires_at = NULL,
                lease_token = NULL,
                lease_expires_at = NULL,
                updated_at = v_now
            WHERE id = v_existing.id;
        ELSE
            IF v_existing.target_instagram_id IS DISTINCT FROM p_target_instagram_id
               OR v_existing.target_input_hash IS DISTINCT FROM p_target_input_hash
               OR v_existing.provider_selector IS DISTINCT FROM 'anonymous_apify' THEN
                RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_IDEMPOTENCY_CONFLICT', ERRCODE = 'P0001';
            END IF;
            UPDATE public.analysis_preflights
            SET claim_token_hash = p_claim_token_hash,
                claim_expires_at = p_claim_expires_at,
                updated_at = v_now
            WHERE id = v_existing.id
              AND v_existing.status IN ('pending', 'processing', 'ready', 'blocked');
            RETURN QUERY SELECT v_existing.id, v_existing.expires_at, FALSE, v_existing.status;
            RETURN;
        END IF;
    END IF;

    v_id := extensions.gen_random_uuid();
    v_expires := v_now + INTERVAL '30 minutes';
    INSERT INTO public.analysis_preflights(
        id, user_id, idempotency_key, target_instagram_id, status,
        exclusion_decision, access_mode, launch_status_snapshot,
        plan_catalog_snapshot, pricing_version, pricing_snapshot,
        policy_versions_snapshot, created_at, expires_at, claim_token_hash,
        claim_expires_at, target_input_hash, provider_selector
    ) VALUES (
        v_id, NULL, p_idempotency_key, p_target_instagram_id, 'pending',
        'pending', 'production', p_launch_status_snapshot,
        p_plan_catalog_snapshot, p_pricing_version, p_pricing_snapshot,
        p_policy_versions_snapshot, v_now, v_expires, p_claim_token_hash,
        p_claim_expires_at, p_target_input_hash, 'anonymous_apify'
    );
    RETURN QUERY SELECT v_id, v_expires, TRUE, 'pending'::TEXT;
END;
$_$;


