-- Name: create_demo_analysis_fixture_draft(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_demo_analysis_fixture_draft(p_version text, p_payload jsonb) RETURNS void
