    SET search_path TO ''
    AS $$
BEGIN
    INSERT INTO public.demo_analysis_fixtures (version, status, payload)
    VALUES (p_version, 'draft', p_payload);
END;
$$;


--
-- Name: create_demo_analysis_preflight(uuid, text, text, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_demo_analysis_preflight(p_user_id uuid, p_target_instagram_id text, p_idempotency_key text, p_duration_seconds integer, p_fixture_version text, p_fixture_payload jsonb) RETURNS TABLE(id uuid, user_id uuid, target_instagram_id text, fixture_version text, idempotency_key text, duration_seconds integer, created_at timestamp with time zone, started_at timestamp with time zone, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    inserted_count INTEGER := 0;
    v_fixture_version TEXT;
BEGIN
    IF p_target_instagram_id <> 'junho_dem'
       OR p_idempotency_key !~ '^[A-Za-z0-9._:-]{16,128}$'
       OR (p_fixture_version = 'operator-editable-fixture-v2' AND p_duration_seconds <> 300)
       OR (p_fixture_version <> 'operator-editable-fixture-v2'
           AND (p_fixture_version !~ '^operator-editable-fixture-[a-z0-9][a-z0-9._-]{1,99}$'
               OR p_duration_seconds NOT BETWEEN 30 AND 45)) THEN
        RAISE EXCEPTION 'invalid database demo run input';
    END IF;
    IF EXISTS (SELECT 1 FROM public.demo_analysis_runs AS run WHERE run.user_id = p_user_id AND run.idempotency_key = p_idempotency_key) THEN
        RETURN QUERY SELECT run.id, run.user_id, run.target_instagram_id, run.fixture_version,
            run.idempotency_key, run.duration_seconds, run.created_at, run.started_at, FALSE
        FROM public.demo_analysis_runs AS run WHERE run.user_id = p_user_id AND run.idempotency_key = p_idempotency_key;
        RETURN;
    END IF;
    SELECT fixture.version INTO v_fixture_version
    FROM public.demo_analysis_fixtures AS fixture
    WHERE fixture.status = 'published' AND fixture.version = p_fixture_version AND fixture.payload = p_fixture_payload
    FOR SHARE;
    IF v_fixture_version IS NULL THEN RETURN; END IF;
    INSERT INTO public.demo_analysis_runs (user_id, target_instagram_id, fixture_version, plan_id, idempotency_key, duration_seconds)
    VALUES (p_user_id, p_target_instagram_id, v_fixture_version, 'standard', p_idempotency_key, p_duration_seconds)
    ON CONFLICT ON CONSTRAINT demo_analysis_runs_user_id_idempotency_key_key DO NOTHING;
    GET DIAGNOSTICS inserted_count = ROW_COUNT;
    RETURN QUERY SELECT run.id, run.user_id, run.target_instagram_id, run.fixture_version,
        run.idempotency_key, run.duration_seconds, run.created_at, run.started_at, inserted_count > 0
    FROM public.demo_analysis_runs AS run WHERE run.user_id = p_user_id AND run.idempotency_key = p_idempotency_key;
END;
$_$;


--
-- Name: create_earlybird_checkout(uuid, uuid, text, text, integer, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_earlybird_checkout(p_user_id uuid, p_preflight_id uuid, p_plan_id text, p_expected_product_id text, p_expected_amount_krw integer, p_pricing_version text, p_disclosure_version text, p_disclosure_text text, p_disclosure_accepted_at timestamp with time zone) RETURNS TABLE(order_id uuid, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_existing public.earlybird_orders%ROWTYPE;
    v_order_id UUID;
    v_required_rank INTEGER;
    v_selected_rank INTEGER;
    v_snapshot_amount TEXT;
    v_user_provider TEXT;
    v_user_phone_number TEXT;
    v_user_phone_number_normalized TEXT;
    v_user_phone_number_verification_source TEXT;
    v_user_phone_number_verified_at TIMESTAMP WITH TIME ZONE;
    v_legacy_disclosure BOOLEAN := FALSE;
BEGIN
    IF p_plan_id IS NULL OR p_plan_id NOT IN ('basic', 'standard') THEN
        RAISE EXCEPTION 'EARLYBIRD_PAID_PLAN_REQUIRED';
    END IF;
    IF p_pricing_version IS NULL
       OR p_pricing_version NOT IN (
            'earlybird-2026-07-v1',
            'earlybird-2026-07-v2',
            'earlybird-2026-08-v3',
            'earlybird-2026-08-v4',
            'earlybird-2026-08-v5'
       )
       OR p_disclosure_accepted_at IS NULL THEN
        RAISE EXCEPTION 'EARLYBIRD_CONSENT_INVALID';
    END IF;
    IF p_disclosure_version = 'earlybird-auto-start-v2'
       AND p_disclosure_text = '결제 확인 후 판독이 자동으로 시작됩니다.' THEN
        NULL;
    ELSIF p_disclosure_version = 'earlybird-24h-v1'
       AND p_disclosure_text = '현재 얼리버드 기간에는 즉시 자동 판독이 아닌, 결제 완료 후 24시간 이내 판독 결과를 제공합니다.' THEN
        v_legacy_disclosure := TRUE;
    ELSE
        RAISE EXCEPTION 'EARLYBIRD_CONSENT_INVALID';
    END IF;
    IF p_expected_product_id IS NULL
       OR p_expected_product_id !~ '^[A-Za-z0-9_-]{1,128}$' THEN
        RAISE EXCEPTION 'EARLYBIRD_PRODUCT_INVALID';
    END IF;
    IF p_expected_amount_krw IS NULL
       OR (p_pricing_version = 'earlybird-2026-07-v1' AND (
            (p_plan_id = 'basic' AND p_expected_amount_krw <> 14900)
            OR (p_plan_id = 'standard' AND p_expected_amount_krw <> 19900)
       ))
       OR (p_pricing_version = 'earlybird-2026-07-v2' AND (
            (p_plan_id = 'basic' AND p_expected_amount_krw <> 6900)
            OR (p_plan_id = 'standard' AND p_expected_amount_krw <> 9900)
       ))
       OR (p_pricing_version = 'earlybird-2026-08-v3' AND (
            (p_plan_id = 'basic' AND p_expected_amount_krw <> 990)
            OR (p_plan_id = 'standard' AND p_expected_amount_krw <> 1990)
       ))
       OR (p_pricing_version = 'earlybird-2026-08-v4' AND (
            (p_plan_id = 'basic' AND p_expected_amount_krw <> 1990)
            OR (p_plan_id = 'standard' AND p_expected_amount_krw <> 2990)
       ))
       OR (p_pricing_version = 'earlybird-2026-08-v5' AND (
            (p_plan_id = 'basic' AND p_expected_amount_krw <> 9900)
            OR (p_plan_id = 'standard' AND p_expected_amount_krw <> 19900)
       )) THEN
        RAISE EXCEPTION 'EARLYBIRD_PRICE_INVALID';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'earlybird:groble:product:' || p_expected_product_id, 0));
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_user_id::TEXT, 0));

    SELECT buyer.provider, buyer.phone_number, buyer.phone_number_normalized,
        buyer.phone_number_verification_source, buyer.phone_number_verified_at
    INTO v_user_provider, v_user_phone_number, v_user_phone_number_normalized,
        v_user_phone_number_verification_source, v_user_phone_number_verified_at
    FROM public.users AS buyer WHERE buyer.id = p_user_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'PREFLIGHT_NOT_VALID'; END IF;
    IF v_user_provider <> 'kakao'
       OR v_user_phone_number_verification_source IS DISTINCT FROM 'kakao_rest_api'
       OR v_user_phone_number_verified_at IS NULL
       OR v_user_phone_number_verified_at < pg_catalog.clock_timestamp() - INTERVAL '24 hours'
       OR v_user_phone_number_normalized IS NULL
       OR public.normalize_kr_mobile_e164(v_user_phone_number)
            IS DISTINCT FROM v_user_phone_number_normalized THEN
        RAISE EXCEPTION 'CHECKOUT_PHONE_REQUIRED';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id AND preflight.user_id = p_user_id FOR UPDATE;
    IF NOT FOUND OR v_preflight.status <> 'ready'
       OR v_preflight.expires_at <= pg_catalog.clock_timestamp()
       OR v_preflight.exclusion_decision NOT IN ('skip', 'exclude')
       OR v_preflight.target_followers_count IS NULL
       OR v_preflight.target_following_count IS NULL
       OR v_preflight.required_plan_id IS NULL THEN
        RAISE EXCEPTION 'PREFLIGHT_NOT_VALID';
    END IF;

    SELECT existing_order.* INTO v_existing
    FROM public.earlybird_orders AS existing_order
    WHERE existing_order.preflight_id = p_preflight_id;
    IF v_legacy_disclosure AND (NOT FOUND
        OR v_existing.disclosure_version IS DISTINCT FROM 'earlybird-24h-v1'
        OR v_existing.disclosure_text IS DISTINCT FROM '현재 얼리버드 기간에는 즉시 자동 판독이 아닌, 결제 완료 후 24시간 이내 판독 결과를 제공합니다.') THEN
        RAISE EXCEPTION 'EARLYBIRD_CONSENT_INVALID';
    END IF;
    IF FOUND THEN
        IF v_existing.user_id <> p_user_id OR v_existing.plan_id <> p_plan_id
           OR v_existing.expected_groble_product_id <> p_expected_product_id
           OR v_existing.buyer_match_policy <> 'verified_kakao_phone'
           OR v_existing.expected_buyer_phone_number_normalized IS DISTINCT FROM v_user_phone_number_normalized
           OR v_existing.expected_buyer_phone_verification_source IS DISTINCT FROM v_user_phone_number_verification_source THEN
            RAISE EXCEPTION 'EARLYBIRD_ORDER_CONFLICT';
        END IF;
        IF v_existing.status = 'payment_pending' THEN
            IF v_existing.expected_amount_krw < p_expected_amount_krw THEN
                RAISE EXCEPTION 'EARLYBIRD_CHECKOUT_ACTIVE_PENDING_LINEAGE:STALE_PRICING_LINEAGE';
            END IF;
            RETURN QUERY SELECT v_existing.id, FALSE;
            RETURN;
        END IF;
        IF v_existing.status = 'cancelled' AND v_existing.payment_id IS NULL THEN
            IF v_existing.pricing_version <> 'earlybird-2026-08-v5' THEN
                RAISE EXCEPTION 'EARLYBIRD_CHECKOUT_CANCELLED_UNRESOLVED_LINEAGE:STALE_PRICING_LINEAGE';
            END IF;
            RAISE EXCEPTION 'EARLYBIRD_CHECKOUT_CANCELLED_UNRESOLVED_LINEAGE:SUPERSEDED_LINEAGE';
        END IF;
        RAISE EXCEPTION 'EARLYBIRD_ORDER_CONFLICT';
    END IF;

    IF EXISTS (SELECT 1 FROM public.analysis_preflights AS newer
        WHERE newer.user_id = p_user_id AND newer.status = 'ready'
          AND newer.expires_at > pg_catalog.clock_timestamp()
          AND newer.exclusion_decision IN ('skip', 'exclude')
          AND (newer.created_at > v_preflight.created_at
            OR (newer.created_at = v_preflight.created_at AND newer.id::TEXT > v_preflight.id::TEXT))) THEN
        RAISE EXCEPTION 'PREFLIGHT_NOT_LATEST';
    END IF;
    IF p_pricing_version <> 'earlybird-2026-08-v5'
       OR v_preflight.pricing_version IN ('earlybird-2026-07-v1', 'earlybird-2026-07-v2', 'earlybird-2026-08-v3', 'earlybird-2026-08-v4') THEN
        RAISE EXCEPTION 'EARLYBIRD_PRICING_REFRESH_REQUIRED';
    END IF;
    IF v_preflight.pricing_version <> p_pricing_version
       OR v_preflight.pricing_snapshot->p_plan_id->>'status' <> 'quoted'
       OR v_preflight.pricing_snapshot->p_plan_id->>'currency' <> 'KRW'
       OR v_preflight.pricing_snapshot->p_plan_id->>'amountKrw' !~ '^[0-9]+$' THEN
        RAISE EXCEPTION 'EARLYBIRD_PRICE_SNAPSHOT_INVALID';
    END IF;
    v_snapshot_amount := v_preflight.pricing_snapshot->p_plan_id->>'amountKrw';
    IF v_snapshot_amount::INTEGER <> p_expected_amount_krw THEN
        RAISE EXCEPTION 'EARLYBIRD_PRICE_SNAPSHOT_INVALID';
    END IF;
    v_required_rank := CASE v_preflight.required_plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 WHEN 'plus' THEN 3 ELSE 99 END;
    v_selected_rank := CASE p_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 99 END;
    IF v_selected_rank < v_required_rank THEN RAISE EXCEPTION 'PLAN_UPGRADE_REQUIRED'; END IF;
    IF v_required_rank = 3 THEN RAISE EXCEPTION 'EARLYBIRD_WAITLIST_REQUIRED'; END IF;
    IF v_preflight.plan_cards_snapshot->p_plan_id->>'selectionState' IS NULL
       OR v_preflight.plan_cards_snapshot->p_plan_id->>'selectionState' = 'unavailable' THEN
        RAISE EXCEPTION 'PLAN_SELECTION_UNAVAILABLE';
    END IF;

    SELECT unresolved_order.* INTO v_existing
    FROM public.earlybird_orders AS unresolved_order
    WHERE unresolved_order.user_id = p_user_id
      AND unresolved_order.expected_groble_product_id = p_expected_product_id
      AND unresolved_order.status = 'cancelled' AND unresolved_order.payment_id IS NULL
    ORDER BY unresolved_order.created_at, unresolved_order.id LIMIT 1;
    IF FOUND THEN
        IF v_existing.pricing_version <> 'earlybird-2026-08-v5' THEN
            RAISE EXCEPTION 'EARLYBIRD_CHECKOUT_CANCELLED_UNRESOLVED_LINEAGE:STALE_PRICING_LINEAGE';
        END IF;
        RAISE EXCEPTION 'EARLYBIRD_CHECKOUT_CANCELLED_UNRESOLVED_LINEAGE:SUPERSEDED_LINEAGE';
    END IF;

    SELECT pending_order.* INTO v_existing
    FROM public.earlybird_orders AS pending_order
    WHERE pending_order.user_id = p_user_id AND pending_order.status = 'payment_pending'
    ORDER BY pending_order.created_at, pending_order.id LIMIT 1;
    IF FOUND THEN
        IF v_existing.expected_groble_product_id <> p_expected_product_id THEN
            RAISE EXCEPTION 'EARLYBIRD_ORDER_CONFLICT';
        END IF;
        IF v_existing.pricing_version <> 'earlybird-2026-08-v5' THEN
            RAISE EXCEPTION 'EARLYBIRD_CHECKOUT_ACTIVE_PENDING_LINEAGE:STALE_PRICING_LINEAGE';
        END IF;
        RAISE EXCEPTION 'EARLYBIRD_CHECKOUT_ACTIVE_PENDING_LINEAGE:SUPERSEDED_LINEAGE';
    END IF;

    INSERT INTO public.earlybird_orders (
        user_id, preflight_id, target_instagram_id, target_followers_count,
        target_following_count, exclusion_decision, excluded_instagram_id,
        plan_id, pricing_version, expected_amount_krw,
        expected_groble_product_id, buyer_match_policy,
        expected_buyer_phone_number_normalized,
        expected_buyer_phone_verification_source,
        expected_buyer_phone_verified_at, disclosure_version, disclosure_text,
        disclosure_accepted_at
    ) VALUES (
        p_user_id, p_preflight_id, v_preflight.target_instagram_id,
        v_preflight.target_followers_count, v_preflight.target_following_count,
        v_preflight.exclusion_decision, v_preflight.excluded_instagram_id,
        p_plan_id, p_pricing_version, p_expected_amount_krw,
        p_expected_product_id, 'verified_kakao_phone',
        v_user_phone_number_normalized, v_user_phone_number_verification_source,
        v_user_phone_number_verified_at, p_disclosure_version, p_disclosure_text,
        p_disclosure_accepted_at
    ) RETURNING id INTO v_order_id;
    RETURN QUERY SELECT v_order_id, TRUE;
END;
$_$;


--
-- Name: create_earlybird_checkout_before_product_fence(uuid, uuid, text, text, integer, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_earlybird_checkout_before_product_fence(p_user_id uuid, p_preflight_id uuid, p_plan_id text, p_expected_product_id text, p_expected_amount_krw integer, p_pricing_version text, p_disclosure_version text, p_disclosure_text text, p_disclosure_accepted_at timestamp with time zone) RETURNS TABLE(order_id uuid, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_existing public.earlybird_orders%ROWTYPE;
    v_order_id UUID;
    v_required_rank INTEGER;
    v_selected_rank INTEGER;
    v_snapshot_amount TEXT;
BEGIN
    IF p_plan_id NOT IN ('basic', 'standard') THEN
        RAISE EXCEPTION 'EARLYBIRD_PAID_PLAN_REQUIRED';
    END IF;
    IF p_pricing_version <> 'earlybird-2026-07-v1'
       OR p_disclosure_version <> 'earlybird-48h-v1'
       OR p_disclosure_text <> '현재 얼리버드 기간에는 즉시 자동 판독이 아닌, 결제 완료 후 48시간 이내 판독 결과를 제공합니다.'
       OR p_disclosure_accepted_at IS NULL THEN
        RAISE EXCEPTION 'EARLYBIRD_CONSENT_INVALID';
    END IF;
    IF p_expected_product_id IS NULL
       OR p_expected_product_id !~ '^[A-Za-z0-9_-]{1,128}$' THEN
        RAISE EXCEPTION 'EARLYBIRD_PRODUCT_INVALID';
    END IF;
    IF (p_plan_id = 'basic' AND p_expected_amount_krw <> 14900)
       OR (p_plan_id = 'standard' AND p_expected_amount_krw <> 19900) THEN
        RAISE EXCEPTION 'EARLYBIRD_PRICE_INVALID';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_user_id::TEXT, 0)
    );

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
    FOR UPDATE;

    IF NOT FOUND
       OR v_preflight.status <> 'ready'
       OR v_preflight.expires_at <= pg_catalog.clock_timestamp()
       OR v_preflight.exclusion_decision NOT IN ('skip', 'exclude')
       OR v_preflight.target_followers_count IS NULL
       OR v_preflight.target_following_count IS NULL
       OR v_preflight.required_plan_id IS NULL THEN
        RAISE EXCEPTION 'PREFLIGHT_NOT_VALID';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.analysis_preflights AS newer
        WHERE newer.user_id = p_user_id
          AND newer.status = 'ready'
          AND newer.expires_at > pg_catalog.clock_timestamp()
          AND newer.exclusion_decision IN ('skip', 'exclude')
          AND (
              newer.created_at > v_preflight.created_at
              OR (
                  newer.created_at = v_preflight.created_at
                  AND newer.id::TEXT > v_preflight.id::TEXT
              )
          )
    ) THEN
        RAISE EXCEPTION 'PREFLIGHT_NOT_LATEST';
    END IF;

    IF v_preflight.pricing_version <> p_pricing_version
       OR v_preflight.pricing_snapshot->p_plan_id->>'status' <> 'quoted'
       OR v_preflight.pricing_snapshot->p_plan_id->>'currency' <> 'KRW'
       OR v_preflight.pricing_snapshot->p_plan_id->>'amountKrw' !~ '^[0-9]+$' THEN
        RAISE EXCEPTION 'EARLYBIRD_PRICE_SNAPSHOT_INVALID';
    END IF;
    v_snapshot_amount := v_preflight.pricing_snapshot->p_plan_id->>'amountKrw';
    IF v_snapshot_amount::INTEGER <> p_expected_amount_krw THEN
        RAISE EXCEPTION 'EARLYBIRD_PRICE_SNAPSHOT_INVALID';
    END IF;
    v_required_rank := CASE v_preflight.required_plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 WHEN 'plus' THEN 3 ELSE 99 END;
    v_selected_rank := CASE p_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 99 END;
    IF v_selected_rank < v_required_rank THEN
        RAISE EXCEPTION 'PLAN_UPGRADE_REQUIRED';
    END IF;
    IF v_required_rank = 3 THEN
        RAISE EXCEPTION 'EARLYBIRD_WAITLIST_REQUIRED';
    END IF;
    IF v_preflight.plan_cards_snapshot->p_plan_id->>'selectionState' IS NULL
       OR v_preflight.plan_cards_snapshot->p_plan_id->>'selectionState' = 'unavailable' THEN
        RAISE EXCEPTION 'PLAN_SELECTION_UNAVAILABLE';
    END IF;

    SELECT existing_order.*
    INTO v_existing
    FROM public.earlybird_orders AS existing_order
    WHERE existing_order.preflight_id = p_preflight_id;
    IF FOUND THEN
        IF v_existing.user_id <> p_user_id
           OR v_existing.plan_id <> p_plan_id
           OR v_existing.expected_amount_krw <> p_expected_amount_krw
           OR v_existing.expected_groble_product_id <> p_expected_product_id
           OR v_existing.status <> 'payment_pending' THEN
            RAISE EXCEPTION 'EARLYBIRD_ORDER_CONFLICT';
        END IF;
        RETURN QUERY SELECT v_existing.id, FALSE;
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.earlybird_orders AS unresolved_order
        WHERE unresolved_order.user_id = p_user_id
          AND unresolved_order.expected_groble_product_id = p_expected_product_id
          AND unresolved_order.status = 'cancelled'
          AND unresolved_order.payment_id IS NULL
    ) THEN
        -- A superseded window for this product is still payable and Groble supplies no
        -- application intent ID that could distinguish it from the requested snapshot.
        RAISE EXCEPTION 'EARLYBIRD_CHECKOUT_ALREADY_PENDING';
    END IF;

    SELECT pending_order.*
    INTO v_existing
    FROM public.earlybird_orders AS pending_order
    WHERE pending_order.user_id = p_user_id
      AND pending_order.status = 'payment_pending'
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.expected_groble_product_id = p_expected_product_id THEN
            -- Groble's completion event identifies the product and buyer, but carries no
            -- application checkout-intent ID. Two live intents for the same buyer/product
            -- therefore cannot be attributed without risking the immutable order snapshot.
            RAISE EXCEPTION 'EARLYBIRD_CHECKOUT_ALREADY_PENDING';
        END IF;
        UPDATE public.earlybird_orders AS superseded_order
        SET status = 'cancelled',
            updated_at = pg_catalog.clock_timestamp()
        WHERE superseded_order.id = v_existing.id;
    END IF;

    INSERT INTO public.earlybird_orders (
        user_id,
        preflight_id,
        target_instagram_id,
        target_followers_count,
        target_following_count,
        exclusion_decision,
        excluded_instagram_id,
        plan_id,
        pricing_version,
        expected_amount_krw,
        expected_groble_product_id,
        disclosure_version,
        disclosure_text,
        disclosure_accepted_at
    ) VALUES (
        p_user_id,
        p_preflight_id,
        v_preflight.target_instagram_id,
        v_preflight.target_followers_count,
        v_preflight.target_following_count,
        v_preflight.exclusion_decision,
        v_preflight.excluded_instagram_id,
        p_plan_id,
        p_pricing_version,
        p_expected_amount_krw,
        p_expected_product_id,
        p_disclosure_version,
        p_disclosure_text,
        p_disclosure_accepted_at
    )
    RETURNING id INTO v_order_id;

    RETURN QUERY SELECT v_order_id, TRUE;
END;
$_$;


--
-- Name: create_earlybird_checkout_with_lineage_marker(uuid, uuid, text, text, integer, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_earlybird_checkout_with_lineage_marker(p_user_id uuid, p_preflight_id uuid, p_plan_id text, p_expected_product_id text, p_expected_amount_krw integer, p_pricing_version text, p_disclosure_version text, p_disclosure_text text, p_disclosure_accepted_at timestamp with time zone) RETURNS TABLE(order_id uuid, created boolean, disposition text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE
    v_order_id UUID;
    v_created BOOLEAN;
    v_error_message TEXT;
    v_pending_count INTEGER;
    v_pending public.earlybird_orders%ROWTYPE;
    v_current_preflight public.analysis_preflights%ROWTYPE;
    v_pending_preflight public.analysis_preflights%ROWTYPE;
    v_blocked_at TIMESTAMP WITH TIME ZONE;
    v_blocked_reason TEXT;
    v_updated_count INTEGER;
BEGIN
    BEGIN
        SELECT created_row.order_id, created_row.created
        INTO v_order_id, v_created
        FROM public.create_earlybird_checkout(
            p_user_id,
            p_preflight_id,
            p_plan_id,
            p_expected_product_id,
            p_expected_amount_krw,
            p_pricing_version,
            p_disclosure_version,
            p_disclosure_text,
            p_disclosure_accepted_at
        ) AS created_row;
    EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
        IF v_error_message <> 'EARLYBIRD_CHECKOUT_ACTIVE_PENDING_LINEAGE:SUPERSEDED_LINEAGE' THEN
            RAISE;
        END IF;

        -- Locks acquired by the legacy call were held in the failed inner
        -- subtransaction and were rolled back with it. Reacquire its exact
        -- product/user/user-row lock order before reproving any rows, so a
        -- competing create cannot change the candidate between checks.
        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(
                'earlybird:groble:product:' || p_expected_product_id,
                0
            )
        );
        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(p_user_id::TEXT, 0)
        );
        PERFORM 1
        FROM public.users AS buyer
        WHERE buyer.id = p_user_id
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
                ERRCODE = 'P0001';
        END IF;

        SELECT current_preflight.*
        INTO v_current_preflight
        FROM public.analysis_preflights AS current_preflight
        WHERE current_preflight.id = p_preflight_id
          AND current_preflight.user_id = p_user_id
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
                ERRCODE = 'P0001';
        END IF;

        SELECT pg_catalog.count(*)::INTEGER
        INTO v_pending_count
        FROM public.earlybird_orders AS pending_order
        WHERE pending_order.user_id = p_user_id
          AND pending_order.expected_groble_product_id = p_expected_product_id
          AND pending_order.status = 'payment_pending';
        IF v_pending_count <> 1 THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
                ERRCODE = 'P0001';
        END IF;

        SELECT pending_order.*
        INTO v_pending
        FROM public.earlybird_orders AS pending_order
        WHERE pending_order.user_id = p_user_id
          AND pending_order.expected_groble_product_id = p_expected_product_id
          AND pending_order.status = 'payment_pending'
        ORDER BY pending_order.created_at, pending_order.id
        LIMIT 1
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
                ERRCODE = 'P0001';
        END IF;

        -- A durable marker is the checkout authority on replay. It is safe to
        -- return superseded without consulting mutable preflight lineage, but
        -- only after the marker itself has been validated by the constraint.
        IF v_pending.checkout_blocked_at IS NOT NULL
           AND v_pending.checkout_blocked_reason = 'SUPERSEDED_LINEAGE' THEN
            RETURN QUERY SELECT v_pending.id, FALSE, 'superseded'::TEXT;
            RETURN;
        END IF;

        SELECT pending_preflight.*
        INTO v_pending_preflight
        FROM public.analysis_preflights AS pending_preflight
        WHERE pending_preflight.id = v_pending.preflight_id
          AND pending_preflight.user_id = p_user_id
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
                ERRCODE = 'P0001';
        END IF;
        IF NOT (
            v_current_preflight.created_at > v_pending_preflight.created_at
            OR (
                v_current_preflight.created_at = v_pending_preflight.created_at
                AND v_current_preflight.id::TEXT > v_pending_preflight.id::TEXT
            )
        ) THEN
            -- The old RPC's error is only durable evidence of supersession if
            -- the requested preflight is actually newer than the pending row.
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
                ERRCODE = 'P0001';
        END IF;

        IF v_pending.payment_id IS NOT NULL
           OR v_pending.actual_groble_product_id IS NOT NULL
           OR v_pending.actual_amount_krw IS NOT NULL
           OR v_pending.paid_at IS NOT NULL
           OR v_pending.seller_reference_confirmed_at IS NOT NULL THEN
            -- Never turn ambiguous provider/payment evidence into a checkout
            -- marker. Abort the wrapper instead.
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
                ERRCODE = 'P0001';
        END IF;
        IF EXISTS (
               SELECT 1
               FROM public.earlybird_fulfillments AS fulfillment
               WHERE fulfillment.order_id = v_pending.id
           )
           OR EXISTS (
               SELECT 1
               FROM public.analysis_requests AS analysis_request
               WHERE analysis_request.id = v_pending.result_request_id
           )
           OR EXISTS (
               SELECT 1
               FROM public.earlybird_webhook_events AS webhook_event
               WHERE webhook_event.order_id = v_pending.id
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
                ERRCODE = 'P0001';
        END IF;

        UPDATE public.earlybird_orders AS superseded_order
        SET checkout_blocked_at = COALESCE(
                superseded_order.checkout_blocked_at,
                pg_catalog.clock_timestamp()
            ),
            checkout_blocked_reason = 'SUPERSEDED_LINEAGE',
            updated_at = pg_catalog.clock_timestamp()
        WHERE superseded_order.id = v_pending.id
          AND superseded_order.user_id = p_user_id
          AND superseded_order.expected_groble_product_id = p_expected_product_id
          AND superseded_order.status = 'payment_pending'
          AND superseded_order.payment_id IS NULL
          AND superseded_order.actual_groble_product_id IS NULL
          AND superseded_order.actual_amount_krw IS NULL
          AND superseded_order.paid_at IS NULL
          AND superseded_order.seller_reference_confirmed_at IS NULL
          AND superseded_order.checkout_blocked_at IS NULL
          AND superseded_order.checkout_blocked_reason IS NULL
          AND NOT EXISTS (
              SELECT 1
              FROM public.earlybird_fulfillments AS fulfillment
              WHERE fulfillment.order_id = superseded_order.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_requests AS analysis_request
              WHERE analysis_request.id = superseded_order.result_request_id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.earlybird_webhook_events AS webhook_event
              WHERE webhook_event.order_id = superseded_order.id
          );
        GET DIAGNOSTICS v_updated_count = ROW_COUNT;
        IF v_updated_count <> 1 THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
                ERRCODE = 'P0001';
        END IF;

        RETURN QUERY SELECT v_pending.id, FALSE, 'superseded'::TEXT;
        RETURN;
    END;

    IF v_order_id IS NULL OR v_created IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
            ERRCODE = 'P0001';
    END IF;

    SELECT checkout_blocked_at, checkout_blocked_reason
    INTO v_blocked_at, v_blocked_reason
    FROM public.earlybird_orders
    WHERE id = v_order_id
      AND user_id = p_user_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
            ERRCODE = 'P0001';
    END IF;

    IF v_blocked_at IS NOT NULL OR v_blocked_reason IS NOT NULL THEN
        RETURN QUERY SELECT v_order_id, FALSE, 'superseded'::TEXT;
        RETURN;
    END IF;

    RETURN QUERY SELECT v_order_id, v_created,
        CASE WHEN v_created THEN 'created' ELSE 'replayed' END;
END;
$$;


--
-- Name: create_earlybird_concierge_snapshot_recovery_request(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_earlybird_concierge_snapshot_recovery_request(p_order_id uuid, p_preflight_id uuid, p_lease_token uuid) RETURNS TABLE(order_id uuid, fulfillment_status text, request_id uuid, created boolean, initial_job_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_payment_id_hint TEXT;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_claim RECORD;
    v_created RECORD;
BEGIN
    IF p_order_id IS NULL OR p_preflight_id IS NULL OR p_lease_token IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_REQUEST_INVALID',
            ERRCODE = 'P0001';
    END IF;
    SELECT earlybird_order.payment_id INTO v_payment_id_hint
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    IF NOT FOUND OR v_payment_id_hint IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_REQUEST_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(v_payment_id_hint, 0)
    );
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF v_fulfillment.order_id IS NULL
       OR v_order.id IS NULL
       OR v_preflight.id IS NULL
       OR v_order.payment_id IS DISTINCT FROM v_payment_id_hint
       OR v_order.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_order.status IS DISTINCT FROM 'paid'
       OR v_order.result_request_id IS NOT NULL
       OR v_fulfillment.status IS DISTINCT FROM 'retryable_failure'
       OR v_fulfillment.request_id IS NOT NULL
       OR v_fulfillment.lease_token IS NOT NULL
       OR v_fulfillment.lease_expires_at IS NOT NULL
       OR v_preflight.consumed_request_id IS NOT NULL
       OR NOT public.earlybird_concierge_snapshot_conflict_receipt_authorized(
            v_order.id,
            v_preflight.id,
            v_order.target_followers_count,
            v_order.target_following_count,
            v_preflight.target_followers_count,
            v_preflight.target_following_count,
            v_preflight.admission_target_followers_count,
            v_preflight.admission_target_following_count,
            v_preflight.admission_generation,
            v_preflight.admission_refreshed_at
       )
       OR EXISTS (
            SELECT 1
            FROM public.earlybird_webhook_events AS refund_event
            WHERE refund_event.payment_id = v_order.payment_id
              AND refund_event.event_type = 'payment.refunded'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_REQUEST_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    SELECT * INTO v_claim
    FROM public.claim_earlybird_fulfillment(
        p_order_id, p_lease_token, 300
    );
    IF v_claim.claimed IS DISTINCT FROM TRUE
       OR v_claim.fulfillment_status IS DISTINCT FROM 'admission_pending'
       OR v_claim.lease_token IS DISTINCT FROM p_lease_token
       OR v_claim.lease_fence IS NULL
       OR v_claim.lease_fence < 1 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_REQUEST_CLAIM_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    SELECT * INTO v_created
    FROM public.create_or_replay_earlybird_fulfillment_request(
        p_order_id, p_lease_token, v_claim.lease_fence
    );
    IF v_created.order_id IS DISTINCT FROM p_order_id
       OR v_created.fulfillment_status IS DISTINCT FROM 'analysis_in_progress'
       OR v_created.request_id IS NULL
       OR v_created.initial_job_key IS DISTINCT FROM 'coordinator:bootstrap' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_REQUEST_CREATION_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    RETURN QUERY SELECT
        v_created.order_id,
        v_created.fulfillment_status::TEXT,
        v_created.request_id,
        v_created.created,
        v_created.initial_job_key::TEXT;
END;
$$;


--
-- Name: create_or_replay_analysis_v2_betatest_preflight(uuid, text, text, text, text, jsonb, jsonb, text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_or_replay_analysis_v2_betatest_preflight(p_user_id uuid, p_email text, p_auth_provider text, p_target_instagram_id text, p_idempotency_key text, p_launch_status_snapshot jsonb, p_plan_catalog_snapshot jsonb, p_pricing_version text, p_pricing_snapshot jsonb, p_policy_versions_snapshot jsonb, p_beta_prepare_token uuid) RETURNS TABLE(preflight_id uuid, created boolean, preflight_status text, expires_at timestamp with time zone, prepare_generation integer, prepare_token uuid, should_enqueue boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE;
    v_gate_enabled BOOLEAN;
    v_grant public.analysis_beta_access_grants%ROWTYPE;
    v_created RECORD;
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_beta_prepare_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_PREPARE_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT gate_row.enabled INTO v_gate_enabled
    FROM public.analysis_beta_runtime_gate AS gate_row
    WHERE gate_row.singleton = TRUE FOR SHARE;
    PERFORM 1 FROM public.users AS owner_user
    WHERE owner_user.id = p_user_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ACCESS_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;
    -- Existing rows are locked before the grant. For a new key, the stronger
    -- users FOR UPDATE lock is the same-user insertion serializer.
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.user_id = p_user_id
      AND preflight.idempotency_key = p_idempotency_key
    FOR UPDATE;
    SELECT grant_row.* INTO v_grant
    FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id = p_user_id FOR SHARE;
    v_now := pg_catalog.clock_timestamp();
    IF v_gate_enabled IS DISTINCT FROM TRUE OR NOT FOUND
       OR v_grant.enabled IS DISTINCT FROM TRUE
       OR (v_grant.expires_at IS NOT NULL AND (
            NOT pg_catalog.isfinite(v_grant.expires_at)
            OR v_grant.expires_at <= v_now
       )) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ACCESS_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;
    SELECT * INTO v_created
    FROM public.analysis_v2_create_or_replay_preflight_unfenced_20260802(
        p_user_id,p_email,p_auth_provider,p_target_instagram_id,p_idempotency_key,
        'production',p_launch_status_snapshot,p_plan_catalog_snapshot,
        p_pricing_version,p_pricing_snapshot,p_policy_versions_snapshot
    );
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_created.preflight_id FOR UPDATE;
    -- The private predecessor may wait on its rate-limit/advisory serializer.
    -- Re-sample current access before attaching or rearming beta provenance;
    -- a rejection rolls back any newly inserted ordinary row as well.
    v_now:=pg_catalog.clock_timestamp();
    IF v_gate_enabled IS DISTINCT FROM TRUE
       OR v_grant.user_id IS NULL
       OR v_grant.enabled IS DISTINCT FROM TRUE
       OR (v_grant.expires_at IS NOT NULL AND (
            NOT pg_catalog.isfinite(v_grant.expires_at)
            OR v_grant.expires_at<=v_now
       )) THEN
        RAISE EXCEPTION USING
            MESSAGE='ANALYSIS_BETA_ACCESS_UNAVAILABLE', ERRCODE='P0001';
    END IF;
    IF v_preflight.analysis_entry_channel IS DISTINCT FROM 'standard'
       AND v_preflight.beta_entry_provenance IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PREFLIGHT_IDEMPOTENCY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_created.created THEN
        UPDATE public.analysis_preflights AS preflight
        SET beta_entry_provenance = 'betatest_service_v1',
            beta_prepare_generation = 1,
            beta_prepare_token = p_beta_prepare_token,
            beta_prepare_state = 'reserved',
            beta_prepare_dispatch_state = 'reserved',
            updated_at = v_now
        WHERE preflight.id = v_preflight.id
        RETURNING preflight.* INTO v_preflight;
    ELSIF v_preflight.beta_entry_provenance IS DISTINCT FROM 'betatest_service_v1' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PREFLIGHT_IDEMPOTENCY_CONFLICT', ERRCODE = 'P0001';
    ELSIF v_preflight.status = 'pending'
       AND v_preflight.analysis_entry_channel = 'standard'
       AND (
            v_preflight.beta_prepare_retry_exhausted_at IS NOT NULL
            OR (
                v_preflight.beta_prepare_state = 'preparing'
                AND v_preflight.beta_prepare_lease_expires_at <= v_now
            )
       ) THEN
        IF v_preflight.beta_prepare_generation >= 100 THEN
            RAISE EXCEPTION USING
                MESSAGE='ANALYSIS_BETA_PREPARE_EXHAUSTED', ERRCODE='P0001';
        END IF;
        UPDATE public.analysis_preflights AS preflight
        SET beta_prepare_generation=preflight.beta_prepare_generation + 1,
            beta_prepare_token=p_beta_prepare_token,
            beta_prepare_state='reserved',
            beta_prepare_dispatch_state='reserved',
            beta_prepare_dispatched_at=NULL,
            beta_prepare_lease_token=NULL,
            beta_prepare_lease_expires_at=NULL,
            beta_prepare_retry_exhausted_at=NULL,
            updated_at=v_now
        WHERE preflight.id=v_preflight.id
        RETURNING preflight.* INTO v_preflight;
    END IF;
    RETURN QUERY SELECT v_preflight.id, v_created.created,
        v_preflight.status, v_preflight.expires_at,
        v_preflight.beta_prepare_generation, v_preflight.beta_prepare_token,
        (v_preflight.status = 'pending'
            AND v_preflight.beta_prepare_state IN ('reserved','preparing'));
END;
$$;


--
-- Name: create_or_replay_analysis_v2_preflight(uuid, text, text, text, text, text, jsonb, jsonb, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_or_replay_analysis_v2_preflight(p_user_id uuid, p_email text, p_auth_provider text, p_target_instagram_id text, p_idempotency_key text, p_access_mode text, p_launch_status_snapshot jsonb, p_plan_catalog_snapshot jsonb, p_pricing_version text, p_pricing_snapshot jsonb, p_policy_versions_snapshot jsonb) RETURNS TABLE(preflight_id uuid, created boolean, preflight_status text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_target_instagram_id TEXT;
    v_existing public.analysis_preflights%ROWTYPE;
    v_preflight_id UUID;
    v_plan_id TEXT;
    v_recent_preflight_count INTEGER;
    v_global_preflight_count INTEGER;
BEGIN
    IF p_user_id IS NULL
       OR p_email IS NULL
       OR pg_catalog.char_length(pg_catalog.btrim(p_email)) < 3
       OR pg_catalog.char_length(pg_catalog.btrim(p_email)) > 255
       OR pg_catalog.strpos(p_email, '@') < 2
       OR p_auth_provider IS NULL
       OR p_auth_provider !~ '^[a-z0-9._:-]{1,50}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_AUTH_INPUT', ERRCODE = 'P0001';
    END IF;

    v_target_instagram_id := pg_catalog.lower(pg_catalog.btrim(p_target_instagram_id));
    IF v_target_instagram_id IS NULL
       OR v_target_instagram_id !~ '^[a-z0-9._]{1,30}$'
       OR p_idempotency_key IS NULL
       OR pg_catalog.char_length(p_idempotency_key) < 16
       OR pg_catalog.char_length(p_idempotency_key) > 128
       OR p_idempotency_key !~ '^[A-Za-z0-9._:-]+$'
       OR p_access_mode IS NULL
       OR p_access_mode NOT IN ('production', 'test_entitlement')
       OR NOT public.analysis_v2_valid_launch_snapshot(p_launch_status_snapshot)
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(p_plan_catalog_snapshot)
       OR p_pricing_version IS NULL
       OR pg_catalog.char_length(p_pricing_version) < 1
       OR pg_catalog.char_length(p_pricing_version) > 64
       OR p_pricing_version !~ '^[A-Za-z0-9._:-]+$'
       OR NOT public.analysis_v2_valid_pricing_snapshot(p_pricing_snapshot)
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(p_policy_versions_snapshot) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_PREFLIGHT_INPUT', ERRCODE = 'P0001';
    END IF;

    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        IF p_plan_catalog_snapshot->v_plan_id->>'launchStatus'
            IS DISTINCT FROM p_launch_status_snapshot->>v_plan_id THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_PREFLIGHT_INPUT', ERRCODE = 'P0001';
        END IF;
    END LOOP;

    INSERT INTO public.users (id, email, provider, analysis_count, is_paid_user)
    VALUES (
        p_user_id,
        pg_catalog.btrim(p_email),
        p_auth_provider,
        0,
        FALSE
    )
    ON CONFLICT (id) DO NOTHING;

    PERFORM 1
    FROM public.users
    WHERE id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_AUTH_INPUT', ERRCODE = 'P0001';
    END IF;

    -- This user row is already locked, so user-scoped retention cannot invert lock order with
    -- another request. Cross-user maintenance runs only in the dedicated scheduled worker.
    UPDATE public.analysis_preflights AS preflight
    SET status = 'expired',
        target_instagram_id = 'retained.'
            || pg_catalog.substr(pg_catalog.replace(preflight.id::TEXT, '-', ''), 1, 20),
        target_full_name = NULL,
        target_bio = NULL,
        target_profile_image_url = NULL,
        target_followers_count = NULL,
        target_following_count = NULL,
        target_is_private = NULL,
        capacity_required_plan_id = NULL,
        required_plan_id = NULL,
        plan_cards_snapshot = NULL,
        error_code = NULL,
        blocked_at = NULL,
        ready_at = NULL,
        exclusion_decision = 'skip',
        excluded_instagram_id = NULL,
        lease_token = NULL,
        lease_expires_at = NULL,
        pii_scrubbed_at = v_now,
        updated_at = v_now
    WHERE preflight.user_id = p_user_id
      AND preflight.status IN ('pending', 'processing', 'ready')
      AND preflight.expires_at <= v_now;

    SELECT preflight.*
    INTO v_existing
    FROM public.analysis_preflights AS preflight
    WHERE preflight.user_id = p_user_id
      AND preflight.idempotency_key = p_idempotency_key
    FOR UPDATE;

    IF FOUND THEN
        IF v_existing.status = 'expired' THEN
            RETURN QUERY SELECT v_existing.id, FALSE, 'expired'::TEXT, v_existing.expires_at;
            RETURN;
        END IF;
        IF v_existing.target_instagram_id IS DISTINCT FROM v_target_instagram_id
           OR v_existing.access_mode IS DISTINCT FROM p_access_mode THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_IDEMPOTENCY_CONFLICT', ERRCODE = 'P0001';
        END IF;

        RETURN QUERY SELECT v_existing.id, FALSE, v_existing.status, v_existing.expires_at;
        RETURN;
    END IF;

    SELECT preflight.* INTO v_existing
    FROM public.analysis_preflights AS preflight
    WHERE preflight.user_id = p_user_id
      AND preflight.target_instagram_id = v_target_instagram_id
      AND preflight.access_mode = p_access_mode
      AND preflight.beta_entry_provenance IS NULL
      AND preflight.status IN ('pending', 'processing', 'ready')
      AND preflight.expires_at > v_now
    ORDER BY preflight.created_at DESC
    LIMIT 1
    FOR UPDATE;
    IF FOUND THEN
        RETURN QUERY SELECT v_existing.id, FALSE, v_existing.status, v_existing.expires_at;
        RETURN;
    END IF;

    -- Serialize only fresh global-budget checks. Idempotent replays returned above do not consume
    -- capacity or contend on this circuit breaker.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('analysis-v2-preflight-global-hourly-budget', 0)
    );
    SELECT pg_catalog.count(*)::INTEGER
    INTO v_global_preflight_count
    FROM public.analysis_preflights AS recent_preflight
    WHERE recent_preflight.created_at > v_now - INTERVAL '1 hour';

    SELECT pg_catalog.count(*)::INTEGER
    INTO v_recent_preflight_count
    FROM public.analysis_preflights AS recent_preflight
    WHERE recent_preflight.user_id = p_user_id
      AND recent_preflight.created_at > v_now - INTERVAL '1 hour';

    IF v_recent_preflight_count >= 5 OR EXISTS (
        SELECT 1
        FROM public.analysis_preflights AS recent_preflight
        WHERE recent_preflight.user_id = p_user_id
          AND recent_preflight.created_at > v_now - INTERVAL '10 seconds'
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_RATE_LIMITED', ERRCODE = 'P0001';
    END IF;

    -- A fresh idempotency key intentionally supersedes an unfinished free preflight. The consumed
    -- analysis is immutable and is not part of this active-preflight set.
    UPDATE public.analysis_preflights AS preflight
    SET status = 'expired',
        lease_token = NULL,
        lease_expires_at = NULL,
        updated_at = v_now
    WHERE preflight.user_id = p_user_id
      AND preflight.status IN ('pending', 'processing', 'ready');

    v_preflight_id := extensions.gen_random_uuid();
    INSERT INTO public.analysis_preflights (
        id,
        user_id,
        idempotency_key,
        target_instagram_id,
        status,
        exclusion_decision,
        access_mode,
        launch_status_snapshot,
        plan_catalog_snapshot,
        pricing_version,
        pricing_snapshot,
        policy_versions_snapshot,
        created_at,
        updated_at,
        expires_at
    ) VALUES (
        v_preflight_id,
        p_user_id,
        p_idempotency_key,
        v_target_instagram_id,
        'pending',
        'pending',
        p_access_mode,
        p_launch_status_snapshot,
        p_plan_catalog_snapshot,
        p_pricing_version,
        p_pricing_snapshot,
        p_policy_versions_snapshot,
        v_now,
        v_now,
        v_now + INTERVAL '30 minutes'
    );

    RETURN QUERY
    SELECT v_preflight_id, TRUE, 'pending'::TEXT, v_now + INTERVAL '30 minutes';
END;
$_$;


--
-- Name: create_or_replay_analysis_v2_preflight_with_target_hash(uuid, text, text, text, text, text, jsonb, jsonb, text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_or_replay_analysis_v2_preflight_with_target_hash(p_user_id uuid, p_email text, p_auth_provider text, p_target_instagram_id text, p_idempotency_key text, p_access_mode text, p_launch_status_snapshot jsonb, p_plan_catalog_snapshot jsonb, p_pricing_version text, p_pricing_snapshot jsonb, p_policy_versions_snapshot jsonb, p_target_input_hash text) RETURNS TABLE(preflight_id uuid, created boolean, preflight_status text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $_$
DECLARE
    v_created RECORD;
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_target_input_hash IS NULL
       OR p_target_input_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PREFLIGHT_TARGET_HASH_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT created_row.* INTO v_created
    FROM public.create_or_replay_analysis_v2_preflight(
        p_user_id,
        p_email,
        p_auth_provider,
        p_target_instagram_id,
        p_idempotency_key,
        p_access_mode,
        p_launch_status_snapshot,
        p_plan_catalog_snapshot,
        p_pricing_version,
        p_pricing_snapshot,
        p_policy_versions_snapshot
    ) AS created_row;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_created.preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    IF v_preflight.target_input_hash IS NULL THEN
        UPDATE public.analysis_preflights
        SET target_input_hash = p_target_input_hash,
            updated_at = pg_catalog.clock_timestamp()
        WHERE id = v_preflight.id
          AND target_input_hash IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PREFLIGHT_TARGET_HASH_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        v_preflight.target_input_hash := p_target_input_hash;
    ELSIF v_preflight.target_input_hash IS DISTINCT FROM p_target_input_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PREFLIGHT_TARGET_HASH_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    RETURN QUERY
    SELECT v_preflight.id,
           v_created.created,
           v_preflight.status,
           v_preflight.expires_at;
END;
$_$;


--
-- Name: create_or_replay_earlybird_fulfillment_request(uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_or_replay_earlybird_fulfillment_request(p_order_id uuid, p_lease_token uuid, p_lease_fence bigint) RETURNS TABLE(order_id uuid, fulfillment_status text, request_id uuid, created boolean, initial_job_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := public.earlybird_fulfillment_clock();
    v_initial_job_key CONSTANT TEXT := 'coordinator:bootstrap';
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_request_id UUID;
    v_selected_card JSONB;
    v_scope_snapshot JSONB;
    v_input_hash TEXT;
    c_max_request_generations CONSTANT INTEGER := 10;
    v_request_base_key TEXT;
    v_request_generation_prefix TEXT;
    v_request_last_generation INTEGER;
    v_request_generation INTEGER;
    v_request_idempotency_key TEXT;
    v_conflicting_request public.analysis_requests%ROWTYPE;
    v_recovery RECORD;
    v_recovery_preflight public.analysis_preflights%ROWTYPE;
    v_rebind_preflight_base_key TEXT;
    v_rebind_preflight_generation_prefix TEXT;
    v_first15_rearm_ready BOOLEAN := FALSE;
    v_first15_rearm_failed_request_id UUID;
BEGIN
    IF p_order_id IS NULL OR p_lease_token IS NULL OR p_lease_fence IS NULL OR p_lease_fence < 1 THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT fulfillment.* INTO v_fulfillment FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_NOT_FOUND', ERRCODE = 'P0001'; END IF;
    SELECT earlybird_order.* INTO v_order FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id FOR UPDATE;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT', ERRCODE = 'P0001'; END IF;

    IF v_fulfillment.request_id IS NOT NULL OR v_order.result_request_id IS NOT NULL
       OR v_preflight.consumed_request_id IS NOT NULL THEN
        IF v_fulfillment.request_id IS NULL OR v_order.result_request_id IS DISTINCT FROM v_fulfillment.request_id
           OR v_preflight.consumed_request_id IS DISTINCT FROM v_fulfillment.request_id THEN
            UPDATE public.earlybird_fulfillments AS fulfillment SET status = 'manual_review', lease_token = NULL,
                lease_expires_at = NULL, last_error_code = 'REQUEST_CONFLICT', last_error_at = v_now,
                manual_review_at = v_now, updated_at = v_now WHERE fulfillment.order_id = p_order_id;
            RETURN QUERY SELECT p_order_id, 'manual_review'::TEXT, NULL::UUID, FALSE, NULL::TEXT; RETURN;
        END IF;
        SELECT analysis_request.* INTO v_request FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = v_fulfillment.request_id AND analysis_request.user_id = v_order.user_id
          AND analysis_request.preflight_id = v_order.preflight_id AND analysis_request.pipeline_version = 'v2'
          AND analysis_request.plan_access_mode_snapshot = 'production'
          AND analysis_request.selected_plan_id_snapshot = v_order.plan_id;
        IF NOT FOUND THEN
            UPDATE public.earlybird_fulfillments AS fulfillment SET status = 'manual_review', lease_token = NULL,
                lease_expires_at = NULL, last_error_code = 'REQUEST_CONFLICT', last_error_at = v_now,
                manual_review_at = v_now, updated_at = v_now WHERE fulfillment.order_id = p_order_id;
            RETURN QUERY SELECT p_order_id, 'manual_review'::TEXT, NULL::UUID, FALSE, NULL::TEXT; RETURN;
        END IF;
        UPDATE public.earlybird_fulfillments AS fulfillment
        SET status = CASE WHEN v_request.status = 'completed' THEN 'completed' ELSE 'analysis_in_progress' END,
            lease_token = NULL, lease_expires_at = NULL,
            completed_at = CASE WHEN v_request.status = 'completed' THEN v_now ELSE NULL END, updated_at = v_now
        WHERE fulfillment.order_id = p_order_id;
        RETURN QUERY SELECT p_order_id, CASE WHEN v_request.status = 'completed' THEN 'completed'::TEXT ELSE 'analysis_in_progress'::TEXT END,
            v_request.id, FALSE, v_initial_job_key; RETURN;
    END IF;
    IF v_fulfillment.lease_token IS DISTINCT FROM p_lease_token OR v_fulfillment.lease_fence IS DISTINCT FROM p_lease_fence
       OR v_fulfillment.lease_expires_at IS NULL OR v_fulfillment.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_LEASE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    IF v_order.status <> 'paid' OR v_order.seller_reference_confirmed_at IS NULL OR v_order.payment_id IS NULL
       OR v_order.actual_amount_krw IS NULL OR v_order.actual_amount_krw < 0
       OR v_order.actual_amount_krw > v_order.expected_amount_krw
       OR v_order.actual_groble_product_id IS DISTINCT FROM v_order.expected_groble_product_id
       OR v_order.target_followers_count IS NULL OR v_order.target_following_count IS NULL
       OR v_preflight.user_id IS DISTINCT FROM v_order.user_id OR v_preflight.status <> 'ready'
       OR v_preflight.access_mode <> 'production' OR v_preflight.target_instagram_id IS DISTINCT FROM v_order.target_instagram_id
       OR v_preflight.exclusion_decision IS DISTINCT FROM v_order.exclusion_decision
       OR v_preflight.excluded_instagram_id IS DISTINCT FROM v_order.excluded_instagram_id
       OR v_preflight.admission_status <> 'ready'
       OR v_preflight.target_followers_count IS NULL OR v_preflight.target_following_count IS NULL
       OR v_preflight.admission_target_followers_count IS NULL OR v_preflight.admission_target_following_count IS NULL
       OR NOT public.earlybird_concierge_snapshot_conflict_counts_authorized(
            v_order.id,
            v_preflight.id,
            v_order.target_followers_count,
            v_order.target_following_count,
            v_preflight.target_followers_count,
            v_preflight.target_following_count,
            v_preflight.admission_target_followers_count,
            v_preflight.admission_target_following_count,
            v_preflight.admission_generation,
            v_preflight.admission_refreshed_at
       )
       OR v_preflight.admission_capacity_required_plan_id IS DISTINCT FROM v_preflight.capacity_required_plan_id
       OR v_preflight.admission_required_plan_id IS DISTINCT FROM v_preflight.required_plan_id
       OR v_preflight.admission_plan_cards_snapshot IS DISTINCT FROM v_preflight.plan_cards_snapshot
       OR NOT public.analysis_v2_valid_launch_snapshot(v_preflight.launch_status_snapshot)
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(v_preflight.plan_catalog_snapshot)
       OR NOT public.analysis_v2_valid_plan_cards_snapshot(v_preflight.plan_cards_snapshot)
       OR NOT public.analysis_v2_valid_pricing_snapshot(v_preflight.pricing_snapshot)
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(v_preflight.policy_versions_snapshot) THEN
        UPDATE public.earlybird_fulfillments AS fulfillment SET status = 'manual_review', lease_token = NULL,
            lease_expires_at = NULL, last_error_code = 'SNAPSHOT_CONFLICT', last_error_at = v_now,
            manual_review_at = v_now, updated_at = v_now WHERE fulfillment.order_id = p_order_id;
        RETURN QUERY SELECT p_order_id, 'manual_review'::TEXT, NULL::UUID, FALSE, NULL::TEXT; RETURN;
    END IF;
    v_selected_card := v_preflight.plan_cards_snapshot->v_order.plan_id;
    IF v_order.plan_id NOT IN ('basic', 'standard') OR v_preflight.admission_selected_plan_id IS DISTINCT FROM v_order.plan_id
       OR v_selected_card IS NULL OR v_selected_card->>'launchStatus' <> 'production'
       OR v_selected_card->>'selectionState' NOT IN ('required', 'available_upgrade')
       OR COALESCE(v_selected_card->'relationshipCapacity'->>'followers', '') !~ '^[0-9]+$'
       OR COALESCE(v_selected_card->'relationshipCapacity'->>'following', '') !~ '^[0-9]+$'
       OR v_preflight.target_followers_count > (v_selected_card->'relationshipCapacity'->>'followers')::INTEGER
       OR v_preflight.target_following_count > (v_selected_card->'relationshipCapacity'->>'following')::INTEGER
       OR v_order.target_followers_count > (v_selected_card->'relationshipCapacity'->>'followers')::INTEGER
       OR v_order.target_following_count > (v_selected_card->'relationshipCapacity'->>'following')::INTEGER THEN
        UPDATE public.earlybird_fulfillments AS fulfillment SET status = 'manual_review', lease_token = NULL,
            lease_expires_at = NULL, last_error_code = 'PLAN_NOT_ALLOWED', last_error_at = v_now,
            manual_review_at = v_now, updated_at = v_now WHERE fulfillment.order_id = p_order_id;
        RETURN QUERY SELECT p_order_id, 'manual_review'::TEXT, NULL::UUID, FALSE, NULL::TEXT; RETURN;
    END IF;
    IF v_preflight.admission_refreshed_at IS NOT NULL
       AND v_preflight.admission_refreshed_at < v_now - INTERVAL '2 minutes'
       AND NOT public.earlybird_concierge_snapshot_conflict_receipt_authorized(
            v_order.id,
            v_preflight.id,
            v_order.target_followers_count,
            v_order.target_following_count,
            v_preflight.target_followers_count,
            v_preflight.target_following_count,
            v_preflight.admission_target_followers_count,
            v_preflight.admission_target_following_count,
            v_preflight.admission_generation,
            v_preflight.admission_refreshed_at
       ) THEN
        UPDATE public.earlybird_fulfillments AS fulfillment SET status = 'retryable_failure', lease_token = NULL,
            lease_expires_at = NULL, next_attempt_at = v_now, last_error_code = 'ADMISSION_FRESHNESS_EXPIRED',
            last_error_at = v_now, manual_review_at = NULL, updated_at = v_now WHERE fulfillment.order_id = p_order_id;
        RETURN QUERY SELECT p_order_id, 'retryable_failure'::TEXT, NULL::UUID, FALSE, NULL::TEXT; RETURN;
    END IF;
    IF v_preflight.admission_refreshed_at IS NULL OR v_preflight.admission_refreshed_at > v_now + INTERVAL '30 seconds' THEN
        UPDATE public.earlybird_fulfillments AS fulfillment SET status = 'manual_review', lease_token = NULL,
            lease_expires_at = NULL, last_error_code = 'SNAPSHOT_CONFLICT', last_error_at = v_now,
            manual_review_at = v_now, updated_at = v_now WHERE fulfillment.order_id = p_order_id;
        RETURN QUERY SELECT p_order_id, 'manual_review'::TEXT, NULL::UUID, FALSE, NULL::TEXT; RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM public.analysis_requests AS active_request WHERE active_request.user_id = v_order.user_id
        AND active_request.status IN ('pending', 'processing')) THEN
        UPDATE public.earlybird_fulfillments AS fulfillment SET status = 'manual_review', lease_token = NULL,
            lease_expires_at = NULL, last_error_code = 'ACTIVE_REQUEST_CONFLICT', last_error_at = v_now,
            manual_review_at = v_now, updated_at = v_now WHERE fulfillment.order_id = p_order_id;
        RETURN QUERY SELECT p_order_id, 'manual_review'::TEXT, NULL::UUID, FALSE, NULL::TEXT; RETURN;
    END IF;
    v_scope_snapshot := pg_catalog.jsonb_build_object('relationshipCapacity', v_selected_card->'relationshipCapacity',
        'detailedMutualLimit', v_selected_card->'detailedMutualLimit');
    IF NOT public.analysis_v2_valid_scope_snapshot(v_scope_snapshot) THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;
    v_request_base_key := 'earlybird:' || pg_catalog.lower(v_order.id::TEXT);
    v_request_idempotency_key := v_request_base_key;
    SELECT analysis_request.* INTO v_conflicting_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.user_id = v_order.user_id
      AND analysis_request.idempotency_key = v_request_base_key
    FOR UPDATE;
    IF FOUND THEN
        SELECT recovery.* INTO v_recovery
        
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
        WHERE recovery.order_id = v_order.id
          AND recovery.failed_request_id = v_conflicting_request.id
        FOR UPDATE;
        IF FOUND THEN
            SELECT recovery_preflight.* INTO v_recovery_preflight
            FROM public.analysis_preflights AS recovery_preflight
            WHERE recovery_preflight.id = v_recovery.recovery_preflight_id
            FOR UPDATE;
        END IF;
        v_rebind_preflight_base_key := 'earlybird.fulfillment.'
            || pg_catalog.replace(v_order.id::TEXT, '-', '');
        v_rebind_preflight_generation_prefix :=
            v_rebind_preflight_base_key || '.r';
        SELECT rearm.source_request_id
        INTO v_first15_rearm_failed_request_id
        FROM public.earlybird_first15_canary_provider_rearms AS rearm
        WHERE rearm.order_id = v_order.id
          AND rearm.rearmed_preflight_id = v_preflight.id
          AND rearm.rearm_generation IN (2, 3)
        FOR KEY SHARE;
        IF v_first15_rearm_failed_request_id IS NOT NULL THEN
            SELECT analysis_request.* INTO v_conflicting_request
            FROM public.analysis_requests AS analysis_request
            WHERE analysis_request.id = v_first15_rearm_failed_request_id
            FOR KEY SHARE;
        END IF;
        v_first15_rearm_ready :=
            public.earlybird_first15_canary_provider_rearm_request_ready(
                v_order.id,
                COALESCE(
                    v_first15_rearm_failed_request_id,
                    v_conflicting_request.id
                ),
                v_preflight.id
            );
        IF (
                v_recovery.order_id IS NULL
                AND NOT v_first15_rearm_ready
            )
           OR (
                v_recovery_preflight.id IS NULL
                AND NOT v_first15_rearm_ready
            )
           OR v_conflicting_request.status <> 'failed'
           OR v_conflicting_request.pipeline_version <> 'v2'
           OR v_conflicting_request.error_message IS NULL
           OR NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_failure_receipts AS receipt
                WHERE receipt.request_id = v_conflicting_request.id
                  AND receipt.error_code = v_conflicting_request.error_message
           )
           OR (
                NOT v_first15_rearm_ready
                AND v_preflight.id IS DISTINCT FROM v_recovery.recovery_preflight_id
                AND (
                    v_preflight.user_id
                        IS DISTINCT FROM v_recovery_preflight.user_id
                    OR v_preflight.user_id IS DISTINCT FROM v_order.user_id
                    OR v_preflight.target_instagram_id
                        IS DISTINCT FROM v_order.target_instagram_id
                    OR v_preflight.exclusion_decision
                        IS DISTINCT FROM v_order.exclusion_decision
                    OR v_preflight.excluded_instagram_id
                        IS DISTINCT FROM v_order.excluded_instagram_id
                    OR v_preflight.access_mode <> 'production'
                    OR v_recovery_preflight.access_mode <> 'production'
                    OR v_preflight.launch_status_snapshot
                        IS DISTINCT FROM v_recovery_preflight.launch_status_snapshot
                    OR v_preflight.plan_catalog_snapshot
                        IS DISTINCT FROM v_recovery_preflight.plan_catalog_snapshot
                    OR v_preflight.pricing_version
                        IS DISTINCT FROM v_recovery_preflight.pricing_version
                    OR v_preflight.pricing_snapshot
                        IS DISTINCT FROM v_recovery_preflight.pricing_snapshot
                    OR v_preflight.policy_versions_snapshot
                        IS DISTINCT FROM v_recovery_preflight.policy_versions_snapshot
                    OR v_preflight.created_at < v_recovery_preflight.created_at
                    OR (
                        v_preflight.idempotency_key
                            <> v_rebind_preflight_base_key
                        AND NOT (
                            pg_catalog.left(
                                v_preflight.idempotency_key,
                                pg_catalog.char_length(
                                    v_rebind_preflight_generation_prefix
                                )
                            ) = v_rebind_preflight_generation_prefix
                            AND pg_catalog.substr(
                                v_preflight.idempotency_key,
                                pg_catalog.char_length(
                                    v_rebind_preflight_generation_prefix
                                ) + 1
                            ) ~ '^[1-9]$'
                        )
                    )
                )
           ) THEN
            UPDATE public.earlybird_fulfillments AS fulfillment
            SET status = 'manual_review', lease_token = NULL,
                lease_expires_at = NULL, last_error_code = 'REQUEST_CONFLICT',
                last_error_at = v_now, manual_review_at = v_now,
                updated_at = v_now
            WHERE fulfillment.order_id = p_order_id;
            RETURN QUERY SELECT p_order_id, 'manual_review'::TEXT,
                NULL::UUID, FALSE, NULL::TEXT;
            RETURN;
        END IF;

        IF EXISTS (
            SELECT 1
            FROM public.analysis_v2_provider_runs AS provider_run
            WHERE provider_run.request_id = v_conflicting_request.id
        ) AND NOT public.earlybird_provider_run_adoption_ready(
            v_order.id, v_conflicting_request.id, v_preflight.id
        ) THEN
            UPDATE public.earlybird_fulfillments AS fulfillment
            SET status = 'manual_review', lease_token = NULL,
                lease_expires_at = NULL,
                last_error_code = 'PROVIDER_RUN_ADOPTION_REQUIRED',
                last_error_at = v_now, manual_review_at = v_now,
                updated_at = v_now
            WHERE fulfillment.order_id = p_order_id;
            RETURN QUERY SELECT p_order_id, 'manual_review'::TEXT,
                NULL::UUID, FALSE, NULL::TEXT;
            RETURN;
        END IF;

        v_request_generation_prefix := v_request_base_key || '.r';
        SELECT pg_catalog.max(
            CASE
                WHEN analysis_request.idempotency_key = v_request_base_key THEN 0
                ELSE (pg_catalog.substr(
                    analysis_request.idempotency_key,
                    pg_catalog.char_length(v_request_generation_prefix) + 1
                ))::INTEGER
            END
        ) INTO v_request_last_generation
        FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.user_id = v_order.user_id
          AND (
              analysis_request.idempotency_key = v_request_base_key
              OR (
                  pg_catalog.left(
                      analysis_request.idempotency_key,
                      pg_catalog.char_length(v_request_generation_prefix)
                  ) = v_request_generation_prefix
                  AND pg_catalog.substr(
                      analysis_request.idempotency_key,
                      pg_catalog.char_length(v_request_generation_prefix) + 1
                  ) ~ '^[0-9]{1,3}$'
              )
          );
        v_request_generation := COALESCE(v_request_last_generation + 1, 1);
        IF v_request_generation >= c_max_request_generations THEN
            UPDATE public.earlybird_fulfillments AS fulfillment
            SET status = 'manual_review', lease_token = NULL,
                lease_expires_at = NULL,
                last_error_code = 'REQUEST_IDEMPOTENCY_EXHAUSTED',
                last_error_at = v_now, manual_review_at = v_now,
                updated_at = v_now
            WHERE fulfillment.order_id = p_order_id;
            RETURN QUERY SELECT p_order_id, 'manual_review'::TEXT,
                NULL::UUID, FALSE, NULL::TEXT;
            RETURN;
        END IF;
        v_request_idempotency_key := v_request_generation_prefix
            || v_request_generation::TEXT;
    END IF;

    v_request_id := extensions.gen_random_uuid();
    INSERT INTO public.analysis_requests(id,user_id,target_instagram_id,target_gender,status,progress,progress_step,current_step,step_data,gender_stats,plan_type,background_processing,idempotency_key,pipeline_version,preflight_id,excluded_instagram_id,exclusion_decision_snapshot,plan_access_mode_snapshot,capacity_required_plan_id_snapshot,required_plan_id_snapshot,selected_plan_id_snapshot,plan_launch_status_snapshot,plan_cards_snapshot,pricing_version_snapshot,pricing_snapshot,analysis_scope_snapshot,policy_versions_snapshot)
    VALUES (v_request_id,v_order.user_id,v_order.target_instagram_id,'male','pending',0,'분석 대기 중...','pending','{}'::JSONB,'{}'::JSONB,v_order.plan_id,TRUE,v_request_idempotency_key,'v2',v_preflight.id,v_order.excluded_instagram_id,v_order.exclusion_decision,'production',v_preflight.capacity_required_plan_id,v_preflight.required_plan_id,v_order.plan_id,v_preflight.launch_status_snapshot,v_preflight.plan_cards_snapshot,v_preflight.pricing_version,v_preflight.pricing_snapshot,v_scope_snapshot,v_preflight.policy_versions_snapshot);
    UPDATE public.analysis_preflights AS preflight SET status = 'consumed', consumed_at = v_now,
        consumed_request_id = v_request_id, updated_at = v_now WHERE preflight.id = v_preflight.id;
    v_input_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to('analysis-v2-job-input-v1' || pg_catalog.chr(10)
        || pg_catalog.lower(v_request_id::TEXT) || pg_catalog.chr(10) || v_initial_job_key,'UTF8'),'sha256'),'hex');
    INSERT INTO public.analysis_pipeline_jobs(request_id,job_key,track,kind,batch,input_hash,required_job_keys)
    VALUES(v_request_id,v_initial_job_key,'coordinator','bootstrap',NULL,v_input_hash,'{}'::TEXT[])
    ON CONFLICT ON CONSTRAINT analysis_pipeline_jobs_pkey DO NOTHING;
    SELECT job.* INTO v_job FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = v_request_id AND job.job_key = v_initial_job_key FOR UPDATE;
    IF NOT FOUND OR v_job.track <> 'coordinator' OR v_job.kind <> 'bootstrap' OR v_job.batch IS NOT NULL
       OR v_job.input_hash <> v_input_hash OR v_job.required_job_keys <> '{}'::TEXT[] THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_REQUEST_CONFLICT', ERRCODE = 'P0001';
    END IF;
    UPDATE public.earlybird_orders AS earlybird_order SET status = 'analysis_in_progress', result_request_id = v_request_id,
        updated_at = v_now WHERE earlybird_order.id = p_order_id;
    UPDATE public.earlybird_fulfillments AS fulfillment SET status = 'analysis_in_progress', request_id = v_request_id,
        lease_token = NULL, lease_expires_at = NULL, next_attempt_at = v_now, last_error_code = NULL,
        last_error_at = NULL, updated_at = v_now WHERE fulfillment.order_id = p_order_id;
    RETURN QUERY SELECT p_order_id, 'analysis_in_progress'::TEXT, v_request_id, TRUE, v_initial_job_key;
END;
$_$;


--
-- Name: create_or_replay_landing_lead_capture(uuid, text, text, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_or_replay_landing_lead_capture(p_journey_id uuid, p_instagram_id text, p_input_context text, p_anonymous_principal_hash character varying, p_capture_token_hash character varying) RETURNS TABLE(journey_id uuid, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_existing public.landing_leads%ROWTYPE;
BEGIN
    -- Exclusions must carry source_preflight_id and are persisted through the
    -- dedicated exclusion RPC below. This capture RPC is target-only so an
    -- omitted source preflight can never violate the context shape contract.
    IF p_input_context <> 'target'
       OR p_instagram_id !~ '^[a-z0-9._]{1,30}$'
       OR p_anonymous_principal_hash !~ '^[a-f0-9]{64}$'
       OR p_capture_token_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION 'LANDING_LEAD_INPUT_INVALID';
    END IF;
    INSERT INTO public.landing_leads(
        journey_id, instagram_id, input_context,
        anonymous_principal_hash, capture_token_hash,
        mapping_status, mapping_source, created_at
    ) VALUES (
        p_journey_id, lower(p_instagram_id), p_input_context,
        p_anonymous_principal_hash, p_capture_token_hash,
        'anonymous_device', 'capture_v1', pg_catalog.clock_timestamp()
    )
    ON CONFLICT (capture_token_hash) DO NOTHING;
    IF FOUND THEN
        RETURN QUERY SELECT p_journey_id, TRUE;
        RETURN;
    END IF;
    SELECT lead.* INTO v_existing
    FROM public.landing_leads AS lead
    WHERE lead.capture_token_hash = p_capture_token_hash
    LIMIT 1;
    IF NOT FOUND
       OR v_existing.journey_id IS DISTINCT FROM p_journey_id
       OR v_existing.instagram_id IS DISTINCT FROM lower(p_instagram_id)
       OR v_existing.input_context IS DISTINCT FROM p_input_context
       OR v_existing.anonymous_principal_hash IS DISTINCT FROM p_anonymous_principal_hash THEN
        RAISE EXCEPTION 'LANDING_LEAD_CAPTURE_MISMATCH';
    END IF;
    RETURN QUERY SELECT v_existing.journey_id, FALSE;
END;
$_$;


--
-- Name: create_or_replay_landing_lead_exclusion(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_or_replay_landing_lead_exclusion(p_source_preflight_id uuid, p_instagram_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_target public.landing_leads%ROWTYPE;
    v_existing public.landing_leads%ROWTYPE;
    v_inserted INTEGER;
BEGIN
    IF p_instagram_id !~ '^[a-z0-9._]{1,30}$' THEN
        RAISE EXCEPTION 'LANDING_LEAD_INPUT_INVALID';
    END IF;
    SELECT * INTO v_target
    FROM public.landing_leads
    WHERE source_preflight_id = p_source_preflight_id
      AND input_context = 'target'
    ORDER BY created_at ASC, id ASC
    LIMIT 1;
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;
    INSERT INTO public.landing_leads(
        journey_id, instagram_id, input_context,
        anonymous_principal_hash, auth_user_id,
        source_preflight_id, mapping_status, mapping_source, linked_at, created_at
    ) VALUES (
        v_target.journey_id, p_instagram_id, 'excluded',
        v_target.anonymous_principal_hash, v_target.auth_user_id,
        p_source_preflight_id, v_target.mapping_status, 'preflight_v1', v_target.linked_at,
        pg_catalog.clock_timestamp()
    )
    ON CONFLICT (source_preflight_id) WHERE input_context = 'excluded' DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted = 1 THEN
        RETURN TRUE;
    END IF;

    -- A legacy excluded row may already occupy the partial unique key.  It is
    -- replay-compatible only when it remains bound to the same target
    -- journey, mapping role, and principal/owner identity.  Do not let
    -- ON CONFLICT turn a mismatched row into a successful durable decision.
    SELECT * INTO v_existing
    FROM public.landing_leads
    WHERE source_preflight_id = p_source_preflight_id
      AND input_context = 'excluded'
    FOR UPDATE;
    IF NOT FOUND
       OR v_existing.instagram_id IS DISTINCT FROM p_instagram_id
       OR v_existing.journey_id IS DISTINCT FROM v_target.journey_id
       OR v_existing.mapping_status IS DISTINCT FROM v_target.mapping_status
       OR v_existing.anonymous_principal_hash IS DISTINCT FROM v_target.anonymous_principal_hash
       OR v_existing.auth_user_id IS DISTINCT FROM v_target.auth_user_id THEN
        RAISE EXCEPTION 'LANDING_LEAD_TARGET_MISMATCH';
    END IF;
    RETURN TRUE;
END;
$_$;


--
-- Name: cutoff_analysis_v2_gemini_lease_v2(integer, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cutoff_analysis_v2_gemini_lease_v2(p_slot integer, p_claim_token uuid, p_fence bigint, p_operation_key text) RETURNS TABLE(cutoff boolean, lease_state text, fence bigint, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_lease public.analysis_v2_gemini_leases%ROWTYPE;
BEGIN
    SELECT lease.* INTO v_lease
    FROM public.analysis_v2_gemini_leases AS lease
    WHERE lease.slot = p_slot
    FOR UPDATE;
    IF v_lease.state = 'leased'
       AND v_lease.stage = 'genderResolution'
       AND v_lease.lease_claim_token = p_claim_token
       AND v_lease.fence = p_fence
       AND v_lease.operation_key = p_operation_key THEN
        UPDATE public.analysis_v2_gemini_leases AS lease
        SET state = 'quarantined',
            quarantined_at = v_now,
            updated_at = v_now
        WHERE lease.slot = p_slot
        RETURNING lease.* INTO v_lease;
        RETURN QUERY SELECT
            TRUE, v_lease.state::TEXT, v_lease.fence, v_lease.expires_at;
        RETURN;
    END IF;
    RETURN QUERY SELECT
        FALSE, v_lease.state::TEXT, v_lease.fence, v_lease.expires_at;
END;
$$;


--
-- Name: cutoff_analysis_v2_gender_resolution_attempt(uuid, text, uuid, text, smallint, uuid, jsonb, integer, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cutoff_analysis_v2_gender_resolution_attempt(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_operation_key text, p_attempt smallint, p_reservation_token uuid, p_telemetry jsonb, p_slot integer, p_lease_claim_token uuid, p_lease_fence bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_attempt_status TEXT;
    v_attempt public.analysis_v2_ai_attempts%ROWTYPE;
    v_lease public.analysis_v2_gemini_leases%ROWTYPE;
    v_message TEXT;
    v_outcome TEXT := 'cutoff';
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR p_job_claim_token IS NULL
       OR p_operation_key IS NULL
       OR p_attempt IS NULL
       OR p_reservation_token IS NULL
       OR p_telemetry IS NULL
       OR p_slot IS NULL OR p_slot NOT BETWEEN 1 AND 8
       OR p_lease_claim_token IS NULL
       OR p_lease_fence IS NULL OR p_lease_fence < 1
       OR p_telemetry->>'stage' IS DISTINCT FROM 'genderResolution'
       OR NOT public.analysis_v2_valid_ai_operation_key(p_operation_key)
       OR NOT public.analysis_v2_ai_operation_matches_stage(
            p_operation_key,
            'genderResolution'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GENDER_RESOLUTION_CUTOFF_INVALID',
            ERRCODE = 'P0001';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('analysis-v2-gemini-leases', 0)
    );

    BEGIN
        PERFORM public.analysis_v2_terminalize_ai_attempt_internal(
            p_request_id,
            p_job_key,
            p_job_claim_token,
            p_operation_key,
            p_attempt,
            p_reservation_token,
            'cutoff',
            p_telemetry
        );
    EXCEPTION
        WHEN SQLSTATE 'P0001' THEN
            GET STACKED DIAGNOSTICS v_message = MESSAGE_TEXT;
            IF v_message IS DISTINCT FROM 'ANALYSIS_V2_AI_ATTEMPT_CONFLICT' THEN
                RAISE;
            END IF;
            SELECT ai_attempt.*
            INTO v_attempt
            FROM public.analysis_v2_ai_attempts AS ai_attempt
            WHERE ai_attempt.request_id = p_request_id
              AND ai_attempt.job_key = p_job_key
              AND ai_attempt.job_claim_token = p_job_claim_token
              AND ai_attempt.operation_key = p_operation_key
              AND ai_attempt.attempt = p_attempt
              AND ai_attempt.reservation_token = p_reservation_token
              AND ai_attempt.stage = 'genderResolution'
            FOR UPDATE;
            IF NOT FOUND OR v_attempt.status NOT IN ('success', 'cutoff') THEN
                RAISE;
            END IF;
            v_outcome := 'already_terminal';
            v_attempt_status := v_attempt.status;
    END;

    IF v_attempt_status IS NULL THEN
        v_attempt_status := 'cutoff';
    END IF;

    SELECT lease.*
    INTO v_lease
    FROM public.analysis_v2_gemini_leases AS lease
    WHERE lease.slot = p_slot
    FOR UPDATE;

    IF v_attempt_status = 'success' THEN
        IF v_lease.fence IS DISTINCT FROM p_lease_fence
           OR v_lease.state NOT IN ('available', 'leased', 'quarantined') THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_GENDER_RESOLUTION_CUTOFF_FENCE_MISMATCH',
                ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'outcome', v_outcome,
            'attempt_status', v_attempt_status,
            'lease_state', v_lease.state,
            'fence', v_lease.fence,
            'expires_at', COALESCE(v_lease.expires_at, v_now)
        );
    END IF;

    IF v_lease.state NOT IN ('leased', 'quarantined')
       OR v_lease.request_id IS DISTINCT FROM p_request_id
       OR v_lease.job_key IS DISTINCT FROM p_job_key
       OR v_lease.operation_key IS DISTINCT FROM p_operation_key
       OR v_lease.attempt IS DISTINCT FROM p_attempt
       OR v_lease.stage IS DISTINCT FROM 'genderResolution'
       OR v_lease.lease_claim_token IS DISTINCT FROM p_lease_claim_token
       OR v_lease.fence IS DISTINCT FROM p_lease_fence THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GENDER_RESOLUTION_CUTOFF_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    IF v_lease.state = 'leased' THEN
        UPDATE public.analysis_v2_gemini_leases AS lease
        SET state = 'quarantined',
            quarantined_at = v_now,
            updated_at = v_now
        WHERE lease.slot = p_slot
          AND lease.lease_claim_token = p_lease_claim_token
          AND lease.fence = p_lease_fence
          AND lease.operation_key = p_operation_key
        RETURNING lease.* INTO v_lease;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_GENDER_RESOLUTION_CUTOFF_FENCE_MISMATCH',
                ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'outcome', v_outcome,
        'attempt_status', v_attempt_status,
        'lease_state', v_lease.state,
        'fence', v_lease.fence,
        'expires_at', v_lease.expires_at
    );
END;
$$;


--
-- Name: defer_analysis_preflight_for_provider_capacity(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.defer_analysis_preflight_for_provider_capacity(p_preflight_id uuid, p_claim_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    IF p_preflight_id IS NULL OR p_claim_token IS NULL THEN
        RETURN FALSE;
    END IF;
    UPDATE public.analysis_preflights AS preflight
    SET status = 'pending',
        lease_token = NULL,
        lease_expires_at = NULL,
        worker_attempt_count = CASE
            WHEN preflight.worker_attempt_count > 0 THEN preflight.worker_attempt_count - 1
            ELSE 0
        END,
        updated_at = v_now
    WHERE preflight.id = p_preflight_id
      AND preflight.status = 'processing'
      AND preflight.lease_token = p_claim_token
      AND preflight.lease_expires_at > v_now
      AND preflight.worker_attempt_count >= 1
      AND preflight.expires_at > v_now
      AND preflight.dispatch_state = 'enqueued';
    RETURN FOUND;
END;
$$;


--
-- Name: defer_analysis_preflight_for_provider_capacity_v2(uuid, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.defer_analysis_preflight_for_provider_capacity_v2(p_preflight_id uuid, p_claim_token uuid, p_workload_role text, p_contract_version smallint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'preflight' OR p_contract_version IS DISTINCT FROM 2 THEN
        RETURN FALSE;
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.dispatch_workload_role IS DISTINCT FROM 'preflight'
       OR v_preflight.dispatch_contract_version IS DISTINCT FROM 2
       OR v_preflight.claim_workload_role IS DISTINCT FROM 'preflight'
       OR v_preflight.claim_contract_version IS DISTINCT FROM 2 THEN
        RETURN FALSE;
    END IF;
    RETURN public.defer_analysis_preflight_for_provider_capacity(
        p_preflight_id, p_claim_token
    );
END;
$$;


--
-- Name: defer_analysis_v2_job_for_ai_capacity(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.defer_analysis_v2_job_for_ai_capacity(p_request_id uuid, p_job_key text, p_claim_token uuid, p_error_code text) RETURNS TABLE(released boolean, job_status text, attempt_count integer, request_status text, ai_capacity_deferral_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL OR p_claim_token IS NULL
       OR p_error_code NOT IN (
            'ANALYSIS_V2_AI_CAPACITY_PENDING',
            'ANALYSIS_V2_PROVIDER_ADMISSION_CAPACITY_PENDING',
            'ANALYSIS_V2_AI_DEADLINE_TOO_SHORT',
            'ANALYSIS_V2_AI_QUARANTINE_ACTIVE',
            'ANALYSIS_V2_AI_RESULT_RECOVERY_PENDING'
       )
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_CAPACITY_DEFER_INVALID', ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND OR v_request.status NOT IN ('pending', 'processing') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_CAPACITY_DEFER_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now
       OR v_job.attempt_count < 1 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_pipeline_jobs AS job
    SET status = 'pending',
        lease_token = NULL,
        lease_expires_at = NULL,
        attempt_count = CASE
            WHEN job.attempt_count > 0 THEN job.attempt_count - 1
            ELSE 0
        END,
        first_started_at = CASE
            WHEN job.attempt_count = 1 THEN NULL
            ELSE job.first_started_at
        END,
        ai_capacity_deferral_count = job.ai_capacity_deferral_count + 1,
        last_error_code = p_error_code,
        last_error_at = v_now,
        updated_at = v_now
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
      AND job.status = 'processing'
      AND job.lease_token = p_claim_token
    RETURNING job.* INTO v_job;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    RETURN QUERY SELECT
        TRUE,
        v_job.status::TEXT,
        v_job.attempt_count,
        v_request.status::TEXT,
        v_job.ai_capacity_deferral_count;
END;
$_$;


--
-- Name: defer_analysis_v2_job_recovery(uuid, text, integer, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.defer_analysis_v2_job_recovery(p_request_id uuid, p_job_key text, p_dispatch_generation integer, p_dispatch_token uuid, p_expected_status text, p_expected_lease_expires_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_deferred BOOLEAN;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 1000
       OR p_dispatch_token IS NULL
       OR p_expected_status IS NULL
       OR p_expected_status NOT IN ('pending', 'processing')
       OR (
            p_expected_status = 'pending'
            AND p_expected_lease_expires_at IS NOT NULL
       )
       OR (
            p_expected_status = 'processing'
            AND p_expected_lease_expires_at IS NULL
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_INVALID_RECOVERY_DEFER_INPUT', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_pipeline_jobs AS job
    SET recovery_checked_at = v_now,
        recovery_not_before = v_now + INTERVAL '5 minutes'
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
      AND job.status = p_expected_status
      AND job.dispatch_state IN ('enqueued', 'delivered')
      AND job.dispatch_generation = p_dispatch_generation
      AND job.dispatch_reservation_token = p_dispatch_token
      AND job.lease_expires_at IS NOT DISTINCT FROM p_expected_lease_expires_at
      AND job.recovery_not_before <= v_now
      AND (
            (
                job.status = 'pending'
                AND job.updated_at <= v_now - INTERVAL '2 minutes'
            )
            OR (
                job.status = 'processing'
                AND job.lease_expires_at <= v_now
            )
      )
      AND EXISTS (
            SELECT 1
            FROM public.analysis_requests AS analysis_request
            WHERE analysis_request.id = job.request_id
              AND analysis_request.pipeline_version = 'v2'
              AND analysis_request.status IN ('pending', 'processing')
      )
    RETURNING TRUE INTO v_deferred;

    RETURN COALESCE(v_deferred, FALSE);
END;
$_$;


--
-- Name: defer_analysis_v2_preflight_admission_for_provider_capacity(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.defer_analysis_v2_preflight_admission_for_provider_capacity(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    IF p_preflight_id IS NULL OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_claim_token IS NULL THEN
        RETURN FALSE;
    END IF;
    UPDATE public.analysis_preflights AS preflight
    SET admission_status = 'pending',
        admission_claim_token = NULL,
        admission_lease_expires_at = NULL,
        updated_at = v_now
    WHERE preflight.id = p_preflight_id
      AND preflight.admission_status = 'processing'
      AND preflight.admission_generation = p_admission_generation
      AND preflight.admission_claim_token = p_claim_token
      AND preflight.admission_lease_expires_at > v_now
      AND preflight.expires_at > v_now
      AND preflight.admission_dispatch_state = 'enqueued';
    RETURN FOUND;
END;
$$;


--
-- Name: defer_analysis_v2_preflight_admission_for_provider_capacity_v2(uuid, integer, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.defer_analysis_v2_preflight_admission_for_provider_capacity_v2(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid, p_workload_role text, p_contract_version smallint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'paid' OR p_contract_version IS DISTINCT FROM 2 THEN
        RETURN FALSE;
    END IF;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.admission_dispatch_workload_role IS DISTINCT FROM 'paid'
       OR v_preflight.admission_dispatch_contract_version IS DISTINCT FROM 2
       OR v_preflight.admission_claim_workload_role IS DISTINCT FROM 'paid'
       OR v_preflight.admission_claim_contract_version IS DISTINCT FROM 2 THEN
        RETURN FALSE;
    END IF;
    RETURN public.defer_analysis_v2_preflight_admission_for_provider_capacity(
        p_preflight_id, p_admission_generation, p_claim_token
    );
END;
$$;


--
-- Name: defer_analysis_v2_scheduler_operation(uuid, text, uuid, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.defer_analysis_v2_scheduler_operation(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_operation_key text, p_stage text, p_operation_claim_token uuid, p_reason text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_operation public.analysis_v2_scheduler_operations%ROWTYPE;
    v_delay INTERVAL;
BEGIN
    IF p_reason = 'ANALYSIS_V2_AI_CAPACITY_PENDING' THEN
        v_delay := INTERVAL '5 seconds';
    ELSIF p_reason = 'ANALYSIS_V2_AI_DEADLINE_TOO_SHORT' THEN
        v_delay := INTERVAL '30 seconds';
    ELSIF p_reason = 'ANALYSIS_V2_AI_QUARANTINE_ACTIVE' THEN
        v_delay := INTERVAL '60 seconds';
    ELSE
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SCHEDULER_OPERATION_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_job_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT operation.* INTO v_operation
    FROM public.analysis_v2_scheduler_operations AS operation
    WHERE operation.request_id = p_request_id
      AND operation.operation_key = p_operation_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_operation.job_key <> p_job_key
       OR v_operation.stage <> p_stage
       OR v_operation.status <> 'claimed'
       OR v_operation.claim_token IS DISTINCT FROM p_operation_claim_token
       OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_ai_attempts AS attempt
            WHERE attempt.request_id = p_request_id
              AND attempt.job_key = p_job_key
              AND attempt.operation_key = p_operation_key
              AND attempt.status <> 'rate_limited'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SCHEDULER_OPERATION_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_v2_scheduler_operations AS operation
    SET lease_expires_at = v_now,
        not_before_at = v_now + v_delay,
        updated_at = v_now
    WHERE operation.request_id = p_request_id
      AND operation.operation_key = p_operation_key
    RETURNING * INTO v_operation;
    RETURN v_operation.not_before_at;
END;
$$;


--
-- Name: defer_analysis_v2_terminal_cleanup(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.defer_analysis_v2_terminal_cleanup(p_request_id uuid, p_job_key text, p_claim_token uuid) RETURNS TABLE(released boolean, job_status text, attempt_count integer, request_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_intent public.analysis_v2_provider_cleanup_intents%ROWTYPE;
BEGIN
    IF p_request_id IS NULL OR p_claim_token IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_INVALID_TERMINAL_CLEANUP_DEFER_INPUT',
            ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_TERMINAL_CLEANUP_DEFER_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_request.pipeline_version <> 'v2'
       OR v_request.status NOT IN ('pending', 'processing') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_TERMINAL_CLEANUP_DEFER_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT intent.* INTO v_intent
    FROM public.analysis_v2_provider_cleanup_intents AS intent
    WHERE intent.request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND OR v_intent.completed_at IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_TERMINAL_CLEANUP_DEFER_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_pipeline_jobs AS job
    SET status = 'pending',
        lease_token = NULL,
        lease_expires_at = NULL,
        last_error_code = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_REQUIRED',
        last_error_at = v_now,
        updated_at = v_now
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
      AND job.status = 'processing'
      AND job.lease_token = p_claim_token
    RETURNING job.* INTO v_job;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    RETURN QUERY SELECT
        TRUE, v_job.status::TEXT, v_job.attempt_count, v_request.status::TEXT;
END;
$_$;


--
-- Name: defer_precheckout_blite_v2_capacity(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.defer_precheckout_blite_v2_capacity(p_preflight_id uuid, p_lease_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_cache public.precheckout_blite_cache%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL OR p_lease_token IS NULL THEN
        RETURN FALSE;
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND OR v_preflight.status IS DISTINCT FROM 'ready'
       OR v_preflight.precheckout_blite_cohort IS DISTINCT FROM TRUE THEN
        RETURN FALSE;
    END IF;
    SELECT cache.* INTO v_cache
    FROM public.precheckout_blite_cache AS cache
    WHERE cache.preflight_id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND
       OR v_cache.state IS DISTINCT FROM 'pending'
       OR v_cache.lease_token IS DISTINCT FROM p_lease_token THEN
        RETURN FALSE;
    END IF;
    UPDATE public.precheckout_blite_cache AS cache
    SET lease_token = extensions.gen_random_uuid(),
        lease_expires_at = v_now,
        attempt_count = CASE
            WHEN cache.attempt_count > 0 THEN cache.attempt_count - 1
            ELSE 0
        END,
        updated_at = v_now
    WHERE cache.preflight_id = p_preflight_id
      AND cache.state = 'pending'
      AND cache.lease_token = p_lease_token;
    RETURN FOUND;
END;
$$;


--
-- Name: defer_precheckout_blite_v2_capacity_v2(uuid, uuid, integer, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.defer_precheckout_blite_v2_capacity_v2(p_preflight_id uuid, p_lease_token uuid, p_dispatch_generation integer, p_dispatch_token uuid, p_workload_role text, p_contract_version smallint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_cache public.precheckout_blite_cache%ROWTYPE;
    v_dispatch public.precheckout_blite_dispatches%ROWTYPE;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'preflight'
       OR p_contract_version IS DISTINCT FROM 2
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_token IS NULL THEN
        RETURN FALSE;
    END IF;
    SELECT dispatch.* INTO v_dispatch FROM public.precheckout_blite_dispatches AS dispatch
    WHERE dispatch.preflight_id = p_preflight_id FOR UPDATE;
    IF NOT FOUND
       OR v_dispatch.state IS DISTINCT FROM 'enqueued'
       OR v_dispatch.dispatch_generation IS DISTINCT FROM p_dispatch_generation
       OR v_dispatch.last_dispatch_token IS DISTINCT FROM p_dispatch_token
       OR v_dispatch.dispatch_workload_role IS DISTINCT FROM 'preflight'
       OR v_dispatch.dispatch_contract_version IS DISTINCT FROM 2 THEN
        RETURN FALSE;
    END IF;
    SELECT cache.* INTO v_cache FROM public.precheckout_blite_cache AS cache
    WHERE cache.preflight_id = p_preflight_id FOR UPDATE;
    IF NOT FOUND
       OR v_cache.claim_workload_role IS DISTINCT FROM 'preflight'
       OR v_cache.claim_contract_version IS DISTINCT FROM 2 THEN
        RETURN FALSE;
    END IF;
    RETURN public.defer_precheckout_blite_v2_capacity(p_preflight_id, p_lease_token);
END;
$$;


--
-- Name: delete_precheckout_blite_cache_on_pii_scrub_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_precheckout_blite_cache_on_pii_scrub_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.pii_scrubbed_at IS NOT NULL
       AND OLD.pii_scrubbed_at IS DISTINCT FROM NEW.pii_scrubbed_at THEN
        PERFORM 1
        FROM public.precheckout_blite_cache AS cache
        WHERE cache.preflight_id = NEW.id
        FOR UPDATE;
        PERFORM 1
        FROM public.precheckout_blite_sources AS source
        WHERE source.preflight_id = NEW.id
        FOR UPDATE;
        PERFORM 1
        FROM public.precheckout_blite_dispatches AS dispatch
        WHERE dispatch.preflight_id = NEW.id
        FOR UPDATE;
        DELETE FROM public.precheckout_blite_cache WHERE preflight_id = NEW.id;
        DELETE FROM public.precheckout_blite_sources WHERE preflight_id = NEW.id;
        DELETE FROM public.precheckout_blite_dispatches WHERE preflight_id = NEW.id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: earlybird_concierge_batch_failed_request_eligible(uuid, text, uuid, uuid, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earlybird_concierge_batch_failed_request_eligible(p_request_id uuid, p_error_code text, p_fulfillment_request_id uuid, p_request_owner_id uuid, p_order_owner_id uuid, p_request_preflight_id uuid, p_order_preflight_id uuid, p_request_target text, p_order_target text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT p_fulfillment_request_id IS NOT DISTINCT FROM p_request_id
       AND p_request_owner_id IS NOT DISTINCT FROM p_order_owner_id
       AND p_request_preflight_id IS NOT DISTINCT FROM p_order_preflight_id
       AND pg_catalog.lower(pg_catalog.btrim(p_request_target))
            IS NOT DISTINCT FROM pg_catalog.lower(pg_catalog.btrim(p_order_target))
       AND p_error_code IN (
               'SCRAPING_INCOMPLETE_ERROR',
               'SCRAPING_PROVIDER_QUOTA_ERROR',
               'SCRAPING_PROVIDER_START_REJECTED_ERROR',
               'ANALYSIS_V2_JOB_HANDLER_FAILED',
               'ANALYSIS_V2_STAGE_SCHEMA_VALIDATION_ERROR'
           )
       AND NOT EXISTS (
           SELECT 1
           FROM public.analysis_pipeline_jobs AS job
           WHERE job.request_id = p_request_id
             AND job.status IN ('pending', 'processing', 'retryable')
       )
       AND NOT EXISTS (
           SELECT 1
           FROM public.analysis_v2_provider_runs AS provider_run
           WHERE provider_run.request_id = p_request_id
             AND provider_run.status IN ('starting', 'running')
       )
       AND NOT EXISTS (
           SELECT 1
           FROM public.analysis_v2_provider_runs AS provider_run
           WHERE provider_run.request_id = p_request_id
             AND provider_run.status IN ('succeeded', 'failed', 'aborted', 'timed_out')
             AND provider_run.max_charge_usd > 0
             AND (
                 provider_run.actual_usage_usd IS NULL
                 OR provider_run.usage_reconciled_at IS NULL
             )
       );
$$;


--
-- Name: earlybird_concierge_snapshot_conflict_counts_authorized(uuid, uuid, integer, integer, integer, integer, integer, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earlybird_concierge_snapshot_conflict_counts_authorized(p_order_id uuid, p_preflight_id uuid, p_order_followers_count integer, p_order_following_count integer, p_preflight_followers_count integer, p_preflight_following_count integer, p_admission_followers_count integer, p_admission_following_count integer, p_admission_generation integer, p_admission_refreshed_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT COALESCE(
        (
            p_admission_followers_count = p_preflight_followers_count
            AND p_admission_following_count = p_preflight_following_count
        )
        OR public.earlybird_concierge_snapshot_conflict_receipt_authorized(
            p_order_id,
            p_preflight_id,
            p_order_followers_count,
            p_order_following_count,
            p_preflight_followers_count,
            p_preflight_following_count,
            p_admission_followers_count,
            p_admission_following_count,
            p_admission_generation,
            p_admission_refreshed_at
        ),
        FALSE
    );
$$;


--
-- Name: earlybird_concierge_snapshot_conflict_receipt_authorized(uuid, uuid, integer, integer, integer, integer, integer, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earlybird_concierge_snapshot_conflict_receipt_authorized(p_order_id uuid, p_preflight_id uuid, p_order_followers_count integer, p_order_following_count integer, p_preflight_followers_count integer, p_preflight_following_count integer, p_admission_followers_count integer, p_admission_following_count integer, p_admission_generation integer, p_admission_refreshed_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT COALESCE(
        EXISTS (
            SELECT 1
            
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, preflight_id UUID, provider_operation_key TEXT, provider_input_hash VARCHAR(64), provider_run_id_hash VARCHAR(32), expected_manual_review_at TIMESTAMPTZ, expected_admission_refreshed_at TIMESTAMPTZ, old_order_followers_count INTEGER, old_order_following_count INTEGER, old_preflight_followers_count INTEGER, old_preflight_following_count INTEGER, new_witness_followers_count INTEGER, new_witness_following_count INTEGER, old_snapshot_recorded_at TIMESTAMPTZ, new_witness_recorded_at TIMESTAMPTZ, recovery_reason TEXT, followers_absolute_delta INTEGER, following_absolute_delta INTEGER, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_concierge_snapshot_conflict_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','preflight_id','provider_operation_key','provider_input_hash','provider_run_id_hash','expected_manual_review_at','expected_admission_refreshed_at','old_order_followers_count','old_order_following_count','old_preflight_followers_count','old_preflight_following_count','new_witness_followers_count','new_witness_following_count','old_snapshot_recorded_at','new_witness_recorded_at','recovery_reason','followers_absolute_delta','following_absolute_delta','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.preflight_id IS NOT NULL AND decoded.provider_operation_key IS NOT NULL AND decoded.provider_input_hash IS NOT NULL AND decoded.provider_run_id_hash IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.expected_admission_refreshed_at IS NOT NULL AND decoded.old_order_followers_count IS NOT NULL AND decoded.old_order_following_count IS NOT NULL AND decoded.old_preflight_followers_count IS NOT NULL AND decoded.old_preflight_following_count IS NOT NULL AND decoded.new_witness_followers_count IS NOT NULL AND decoded.new_witness_following_count IS NOT NULL AND decoded.old_snapshot_recorded_at IS NOT NULL AND decoded.new_witness_recorded_at IS NOT NULL AND decoded.recovery_reason IS NOT NULL AND decoded.followers_absolute_delta IS NOT NULL AND decoded.following_absolute_delta IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
            WHERE recovery.order_id = p_order_id
              AND recovery.preflight_id = p_preflight_id
              AND recovery.old_order_followers_count = p_order_followers_count
              AND recovery.old_order_following_count = p_order_following_count
              AND recovery.old_preflight_followers_count =
                    p_preflight_followers_count
              AND recovery.old_preflight_following_count =
                    p_preflight_following_count
              AND recovery.new_witness_followers_count =
                    p_admission_followers_count
              AND recovery.new_witness_following_count =
                    p_admission_following_count
              AND p_admission_generation = 3
              AND p_admission_refreshed_at = recovery.new_witness_recorded_at
              AND recovery.recovery_reason = 'bounded_time_snapshot_drift'
              AND EXISTS (
                    SELECT 1
                    FROM public.analysis_preflight_provider_runs AS provider_run
                    WHERE provider_run.preflight_id = p_preflight_id
                      AND provider_run.operation_key = recovery.provider_operation_key
                      AND provider_run.operation_key =
                            'target-profile-fresh-admission:g3'
                      AND provider_run.input_hash = recovery.provider_input_hash
                      AND pg_catalog.md5(provider_run.run_id) =
                            recovery.provider_run_id_hash
                      AND provider_run.status = 'succeeded'
              )
              AND 3 = (
                    SELECT pg_catalog.count(*)::INTEGER
                    FROM public.analysis_preflight_provider_runs AS provider_lineage
                    WHERE provider_lineage.preflight_id = p_preflight_id
                      AND provider_lineage.operation_key IN (
                            'target-profile-fresh-admission:g1',
                            'target-profile-fresh-admission:g2',
                            'target-profile-fresh-admission:g3'
                      )
                      AND provider_lineage.input_hash = recovery.provider_input_hash
                      AND provider_lineage.status = 'succeeded'
                      AND provider_lineage.logical_provider = 'apify'
                      AND provider_lineage.actor_id =
                            'apify/instagram-profile-scraper'
                      AND provider_lineage.credential_slot = 'tertiary'
                      AND provider_lineage.run_id IS NOT NULL
                      AND provider_lineage.terminalized_at IS NOT NULL
                      AND provider_lineage.actual_usage_usd IS NOT NULL
                      AND provider_lineage.usage_reconciled_at IS NOT NULL
                      AND provider_lineage.reusable_profile_schema_version = 1
              )
              AND public.earlybird_snapshot_count_drift_within_tolerance(
                    p_preflight_followers_count,
                    p_admission_followers_count
              )
              AND public.earlybird_snapshot_count_drift_within_tolerance(
                    p_preflight_following_count,
                    p_admission_following_count
              )
        ),
        FALSE
    );
$$;


--
-- Name: earlybird_first15_canary_provider_rearm_request_ready(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earlybird_first15_canary_provider_rearm_request_ready(p_order_id uuid, p_failed_request_id uuid, p_recovery_preflight_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.earlybird_first15_canary_provider_rearms AS rearm
        JOIN public.earlybird_orders AS earlybird_order
          ON earlybird_order.id = rearm.order_id
        JOIN public.earlybird_fulfillments AS fulfillment
          ON fulfillment.order_id = earlybird_order.id
        JOIN public.analysis_requests AS failed_request
          ON failed_request.id = rearm.source_request_id
        JOIN public.analysis_preflights AS source_preflight
          ON source_preflight.id = rearm.source_preflight_id
        JOIN public.analysis_preflights AS rearmed_preflight
          ON rearmed_preflight.id = rearm.rearmed_preflight_id
        LEFT JOIN public.earlybird_first15_canary_provider_rearms AS parent_rearm
          ON parent_rearm.order_id = rearm.order_id
         AND parent_rearm.rearmed_preflight_id = rearm.source_preflight_id
        WHERE rearm.order_id = p_order_id
          AND rearm.source_request_id = p_failed_request_id
          AND rearm.rearmed_preflight_id = p_recovery_preflight_id
          AND earlybird_order.preflight_id = rearm.rearmed_preflight_id
          AND earlybird_order.status = 'paid'
          AND earlybird_order.result_request_id IS NULL
          AND earlybird_order.concierge_apify_credential_slot
                = rearm.fallback_credential_slot
          AND fulfillment.status = 'admission_pending'
          AND fulfillment.request_id IS NULL
          AND fulfillment.lease_token IS NOT NULL
          AND fulfillment.lease_fence >= 1
          AND fulfillment.lease_expires_at > pg_catalog.clock_timestamp()
          AND failed_request.user_id = earlybird_order.user_id
          AND failed_request.preflight_id = rearm.source_preflight_id
          AND failed_request.pipeline_version = 'v2'
          AND failed_request.status = 'failed'
          AND failed_request.current_step = 'failed'
          AND failed_request.error_message = rearm.source_failure_code
          AND (
              (
                  rearm.rearm_generation = 1
                  AND rearm.source_failure_code IN (
                      'SCRAPING_INCOMPLETE_ERROR',
                      'SCRAPING_PROVIDER_QUOTA_ERROR',
                      'SCRAPING_PROVIDER_START_REJECTED_ERROR'
                  )
                  AND EXISTS (
                      SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                      WHERE receipt.request_id = failed_request.id
                        AND receipt.error_code = failed_request.error_message
                        AND receipt.failed_job_key IN (
                            'track:relationships:collect',
                            'track:target-evidence:collect'
                        )
                  )
              )
              OR (
                  rearm.rearm_generation = 2
                  AND parent_rearm.order_id IS NOT NULL
                  AND parent_rearm.rearm_generation = 1
                  AND parent_rearm.fallback_credential_slot = rearm.source_credential_slot
                  AND rearm.source_credential_slot = 'tertiary'
                  AND rearm.fallback_credential_slot = 'quinary'
                  AND (
                      (parent_rearm.source_failure_code = 'SCRAPING_INCOMPLETE_ERROR'
                       AND rearm.source_failure_code = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
                       AND EXISTS (
                           SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                           WHERE receipt.request_id = failed_request.id
                             AND receipt.failed_job_key = 'track:relationships:collect'
                             AND receipt.error_code = rearm.source_failure_code
                       ))
                      OR (parent_rearm.source_failure_code = 'SCRAPING_PROVIDER_START_REJECTED_ERROR'
                       AND rearm.source_failure_code = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
                       AND EXISTS (
                           SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                           WHERE receipt.request_id = failed_request.id
                             AND receipt.failed_job_key = 'track:target-evidence:collect'
                             AND receipt.error_code = rearm.source_failure_code
                       ))
                      OR (parent_rearm.source_failure_code = 'SCRAPING_PROVIDER_QUOTA_ERROR'
                       AND rearm.source_failure_code = 'ANALYSIS_V2_MEDIA_ARTIFACT_OBJECT_ERROR'
                       AND EXISTS (
                           SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                           WHERE receipt.request_id = failed_request.id
                             AND receipt.failed_job_key = 'track:profile-ai:batch:2'
                             AND receipt.error_code = rearm.source_failure_code
                       ))
                  )
              )
              OR (
                  rearm.rearm_generation = 3
                  AND parent_rearm.order_id IS NOT NULL
                  AND parent_rearm.rearm_generation = 2
                  AND parent_rearm.fallback_credential_slot = rearm.source_credential_slot
                  AND rearm.source_credential_slot = 'quinary'
                  AND rearm.fallback_credential_slot = 'primary'
                  AND (
                      (parent_rearm.source_failure_code = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
                       AND rearm.source_failure_code IN (
                           'SCRAPING_INCOMPLETE_ERROR',
                           'SCRAPING_PROVIDER_START_REJECTED_ERROR'
                       )
                       AND EXISTS (
                           SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                           WHERE receipt.request_id = failed_request.id
                             AND receipt.error_code = rearm.source_failure_code
                             AND (
                                 (rearm.source_failure_code = 'SCRAPING_INCOMPLETE_ERROR'
                                  AND receipt.failed_job_key = 'track:relationships:collect')
                                 OR (rearm.source_failure_code = 'SCRAPING_PROVIDER_START_REJECTED_ERROR'
                                  AND receipt.failed_job_key = 'track:target-evidence:collect')
                             )
                       ))
                      OR (parent_rearm.source_failure_code = 'ANALYSIS_V2_MEDIA_ARTIFACT_OBJECT_ERROR'
                       AND rearm.source_failure_code = 'JOB_ATTEMPTS_EXHAUSTED'
                       AND EXISTS (
                           SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                           WHERE receipt.request_id = failed_request.id
                             AND receipt.failed_job_key = 'track:profile-ai:batch:2'
                             AND receipt.error_code = rearm.source_failure_code
                       ))
                  )
              )
          )
          AND source_preflight.user_id = earlybird_order.user_id
          AND source_preflight.status = 'consumed'
          AND source_preflight.consumed_request_id = failed_request.id
          AND rearmed_preflight.user_id = earlybird_order.user_id
          AND rearmed_preflight.status = 'ready'
          AND rearmed_preflight.access_mode = 'production'
          AND rearmed_preflight.target_instagram_id = earlybird_order.target_instagram_id
          AND rearmed_preflight.admission_status = 'ready'
          AND rearmed_preflight.admission_selected_plan_id = earlybird_order.plan_id
          AND rearmed_preflight.idempotency_key =
              'earlybird.fulfillment.'
              || pg_catalog.replace(earlybird_order.id::TEXT, '-', '')
              || '.first15r' || rearm.rearm_generation::TEXT
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_pipeline_jobs AS job
              WHERE job.request_id = failed_request.id
                AND job.status IN ('pending', 'processing', 'retryable')
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_v2_provider_runs AS source_run
              WHERE source_run.request_id = failed_request.id
                AND source_run.status IN ('starting', 'running')
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_v2_provider_runs AS source_run
              WHERE source_run.request_id = failed_request.id
                AND source_run.status IN ('succeeded', 'aborted', 'failed', 'timed_out')
                AND source_run.run_id IS NOT NULL
                AND (
                    source_run.actual_usage_usd IS NULL
                    OR source_run.usage_reconciled_at IS NULL
                )
          )
          AND (
              EXISTS (
                  SELECT 1 FROM public.analysis_v2_provider_runs AS source_run
                  WHERE source_run.request_id = failed_request.id
              )
              OR (
                  rearm.rearm_generation = 2
                  AND parent_rearm.source_failure_code IN (
                      'SCRAPING_INCOMPLETE_ERROR',
                      'SCRAPING_PROVIDER_START_REJECTED_ERROR'
                  )
                  AND NOT EXISTS (
                      SELECT 1 FROM public.analysis_v2_provider_runs AS source_run
                      WHERE source_run.request_id = failed_request.id
                  )
              )
              OR (
                  rearm.rearm_generation = 3
                  AND parent_rearm.order_id IS NOT NULL
                  AND parent_rearm.rearm_generation = 2
                  AND parent_rearm.fallback_credential_slot = rearm.source_credential_slot
                  AND rearm.source_credential_slot = 'quinary'
                  AND rearm.fallback_credential_slot = 'primary'
                  AND parent_rearm.source_failure_code = 'ANALYSIS_V2_MEDIA_ARTIFACT_OBJECT_ERROR'
                  AND rearm.source_failure_code = 'JOB_ATTEMPTS_EXHAUSTED'
                  AND EXISTS (
                      SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                      WHERE receipt.request_id = failed_request.id
                        AND receipt.failed_job_key = 'track:profile-ai:batch:2'
                        AND receipt.error_code = rearm.source_failure_code
                  )
                  AND NOT EXISTS (
                      SELECT 1 FROM public.analysis_v2_provider_runs AS source_run
                      WHERE source_run.request_id = failed_request.id
                  )
              )
          )
    );
$$;


