--
-- Name: earlybird_pfe3_media_artifact_adoption_ready(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earlybird_pfe3_media_artifact_adoption_ready(p_order_id uuid, p_failed_request_id uuid, p_recovery_preflight_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    -- earlybird_pfe3_media_artifact_rearms is immutable, so matching the
    -- order/original-failed-request/rearmed-preflight triple exactly is
    -- sufficient: this lineage never produces a second '.r2'-generation
    -- preflight to drift to.
    SELECT EXISTS (
        SELECT 1
        
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, pfe_original_failed_request_id UUID, pfe2_rejected_successor_request_id UUID, media_failed_request_id UUID, rearmed_preflight_id UUID, prior_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'rearm'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_pfe3_media_artifact_rearms'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','pfe_original_failed_request_id','pfe2_rejected_successor_request_id','media_failed_request_id','rearmed_preflight_id','prior_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.pfe_original_failed_request_id IS NOT NULL AND decoded.pfe2_rejected_successor_request_id IS NOT NULL AND decoded.media_failed_request_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS rearm
        JOIN public.earlybird_orders AS earlybird_order
          ON earlybird_order.id = rearm.order_id
        JOIN public.analysis_preflights AS rearmed_preflight
          ON rearmed_preflight.id = rearm.rearmed_preflight_id
        WHERE rearm.order_id = p_order_id
          AND rearm.pfe_original_failed_request_id = p_failed_request_id
          AND rearm.rearmed_preflight_id = p_recovery_preflight_id
          AND earlybird_order.preflight_id = rearm.rearmed_preflight_id
          -- Same paid order the rearm admitted: still paid, and not yet
          -- bound to any result request -- exactly the state the creator's
          -- own admission checks already guarantee before it ever reaches
          -- this readiness gate.
          AND earlybird_order.status = 'paid'
          AND earlybird_order.result_request_id IS NULL
          AND rearmed_preflight.status = 'ready'
          AND rearmed_preflight.access_mode = 'production'
          AND rearmed_preflight.idempotency_key =
              'earlybird.fulfillment.'
              || pg_catalog.replace(earlybird_order.id::TEXT, '-', '')
              || '.r2'
          -- The readiness bar is against the *original* job-exhausted
          -- request's own dataset -- the one create_or_replay always
          -- rediscovers as the conflicting request -- not either
          -- intervening successor, which contributed nothing adoptable
          -- through this architecture.
          AND EXISTS (
              SELECT 1
              FROM public.analysis_v2_provider_runs AS source_run
              WHERE source_run.request_id = rearm.pfe_original_failed_request_id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_provider_runs AS source_run
              WHERE source_run.request_id = rearm.pfe_original_failed_request_id
                AND (
                    source_run.status IS DISTINCT FROM 'succeeded'
                    OR source_run.run_id IS NULL
                    OR source_run.actual_usage_usd IS NULL
                    OR source_run.usage_reconciled_at IS NULL
                )
          )
    );
$$;


