CREATE FUNCTION public.earlybird_profile_fetch_exhaustion_provider_run_adoption_ready(p_order_id uuid, p_failed_request_id uuid, p_recovery_preflight_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    -- earlybird_profile_fetch_exhaustion_recoveries is immutable (see the
    -- mutation-preventing trigger above), so matching it exactly -- order,
    -- failed request, and recovery preflight all at once -- is sufficient:
    -- unlike schema-failure recovery's own multi-generation rearms, this
    -- lineage never produces a second preflight generation to drift to.
    SELECT EXISTS (
        SELECT 1
        
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_profile_fetch_exhaustion_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
        JOIN public.earlybird_orders AS earlybird_order
          ON earlybird_order.id = recovery.order_id
        JOIN public.analysis_preflights AS recovery_preflight
          ON recovery_preflight.id = recovery.recovery_preflight_id
        WHERE recovery.order_id = p_order_id
          AND recovery.failed_request_id = p_failed_request_id
          AND recovery.recovery_preflight_id = p_recovery_preflight_id
          AND earlybird_order.preflight_id = recovery.recovery_preflight_id
          -- Same paid order the recovery admitted: still paid, and not yet
          -- bound to any result request -- exactly the state the creator's
          -- own admission checks already guarantee before it ever reaches
          -- this readiness gate.
          AND earlybird_order.status = 'paid'
          AND earlybird_order.result_request_id IS NULL
          AND recovery_preflight.status = 'ready'
          AND recovery_preflight.access_mode = 'production'
          AND recovery_preflight.idempotency_key =
              'earlybird.schema-recovery.'
              || pg_catalog.replace(earlybird_order.id::TEXT, '-', '')
          -- At least one source provider run must exist, and every one of
          -- them must be fully succeeded and reconciled: the same narrower-
          -- than-terminal bar the admitting recover_earlybird_profile_fetch_
          -- exhaustion_fulfillment function itself enforced at admission
          -- time. A plain NOT EXISTS(bad row) alone would be vacuously true
          -- for zero runs, so the existence half is required too.
          AND EXISTS (
              SELECT 1
              FROM public.analysis_v2_provider_runs AS source_run
              WHERE source_run.request_id = recovery.failed_request_id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_provider_runs AS source_run
