--
-- Name: earlybird_snapshot_count_drift_within_tolerance(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earlybird_snapshot_count_drift_within_tolerance(p_old_count integer, p_new_count integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT COALESCE(
        p_old_count >= 0
        AND p_new_count >= 0
        AND pg_catalog.abs(p_new_count - p_old_count) <= 3
        AND (
            p_new_count = p_old_count
            OR (
                p_old_count > 0
                AND pg_catalog.abs(p_new_count - p_old_count)::NUMERIC * 100
                    <= p_old_count::NUMERIC
            )
        ),
        FALSE
    );
$$;


--
-- Name: earlybird_v211_apify_transient_failure_ready(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earlybird_v211_apify_transient_failure_ready(p_order_id uuid, p_original_failed_request_id uuid, p_failed_request_id uuid, p_failed_preflight_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1
        
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, policy_identity_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_policy_identity_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','policy_identity_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.policy_identity_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS policy_replay
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, original_failed_request_id UUID, profile_ai_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_profile_ai_diagnostic_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','profile_ai_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.profile_ai_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS diagnostic
          ON diagnostic.order_id = policy_replay.order_id
         AND diagnostic.original_failed_request_id =
                policy_replay.original_failed_request_id
         AND diagnostic.rearmed_preflight_id = policy_replay.failed_preflight_id
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, original_failed_request_id UUID, first_relationship_failed_request_id UUID, second_relationship_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ, reviewed_source_request_id UUID, reviewed_source_owner_id UUID, reviewed_source_target_instagram_id TEXT, reviewed_source_result_request_id UUID, reviewed_source_target_posts JSONB, reviewed_source_target_evidence JSONB, reviewed_source_fingerprint VARCHAR(64), reviewed_source_registered_at TIMESTAMPTZ, published_source_fingerprint VARCHAR(64), published_result_hash VARCHAR(64), published_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_concierge_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','first_relationship_failed_request_id','second_relationship_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at','reviewed_source_request_id','reviewed_source_owner_id','reviewed_source_target_instagram_id','reviewed_source_result_request_id','reviewed_source_target_posts','reviewed_source_target_evidence','reviewed_source_fingerprint','reviewed_source_registered_at','published_source_fingerprint','published_result_hash','published_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.first_relationship_failed_request_id IS NOT NULL AND decoded.second_relationship_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS concierge
          ON concierge.order_id = policy_replay.order_id
         AND concierge.original_failed_request_id =
                policy_replay.original_failed_request_id
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
          ON recovery.order_id = policy_replay.order_id
         AND recovery.failed_request_id =
                policy_replay.original_failed_request_id
        JOIN public.earlybird_orders AS earlybird_order
          ON earlybird_order.id = policy_replay.order_id
        JOIN public.analysis_requests AS original_request
          ON original_request.id = policy_replay.original_failed_request_id
        JOIN public.analysis_requests AS policy_request
          ON policy_request.id = policy_replay.policy_identity_failed_request_id
        JOIN public.analysis_requests AS failed_request
          ON failed_request.id = p_failed_request_id
        JOIN public.analysis_preflights AS failed_preflight
          ON failed_preflight.id = p_failed_preflight_id
        WHERE policy_replay.order_id = p_order_id
          AND policy_replay.original_failed_request_id =
                p_original_failed_request_id
          AND policy_replay.rearmed_preflight_id = p_failed_preflight_id
          AND failed_request.preflight_id = failed_preflight.id
          AND failed_request.user_id = earlybird_order.user_id
          AND failed_request.pipeline_version = 'v2'
          AND failed_request.status = 'failed'
          AND failed_request.current_step = 'failed'
          AND NOT failed_request.background_processing
          AND failed_request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          AND failed_request.idempotency_key =
                'earlybird:' || pg_catalog.lower(earlybird_order.id::TEXT) || '.r5'
          AND failed_request.target_instagram_id = (
                'retained.' || pg_catalog.substr(
                    pg_catalog.replace(failed_request.id::TEXT, '-', ''), 1, 20
                )
          )
          AND failed_request.policy_versions_snapshot =
                pg_catalog.jsonb_build_object(
                    'pipeline', 'v2',
                    'risk', 'risk-policy-v2.5',
                    'aiStage', 'ai-stage-policy-v2.11',
                    'scheduler', 'ai-scheduler-v1'
                )
          AND failed_preflight.user_id = earlybird_order.user_id
          AND failed_preflight.access_mode = 'production'
          AND failed_preflight.status = 'consumed'
          AND failed_preflight.consumed_request_id = failed_request.id
          AND failed_preflight.idempotency_key =
                'earlybird.fulfillment.'
                || pg_catalog.replace(earlybird_order.id::TEXT, '-', '') || '.r8'
          AND failed_preflight.pii_scrubbed_at IS NOT NULL
          AND failed_preflight.target_instagram_id = (
                'retained.' || pg_catalog.substr(
                    pg_catalog.replace(failed_preflight.id::TEXT, '-', ''), 1, 20
                )
          )
          AND failed_preflight.admission_status = 'ready'
          AND failed_preflight.admission_selected_plan_id = 'basic'
          AND public.analysis_v2_valid_launch_snapshot(
                failed_preflight.launch_status_snapshot
          )
          AND public.analysis_v2_valid_plan_catalog_snapshot(
                failed_preflight.plan_catalog_snapshot
          )
          AND public.analysis_v2_valid_plan_cards_snapshot(
                failed_preflight.plan_cards_snapshot
          )
          AND public.analysis_v2_valid_pricing_snapshot(
                failed_preflight.pricing_snapshot
          )
          AND public.analysis_v2_valid_policy_versions_snapshot(
                failed_preflight.policy_versions_snapshot
          )
          AND original_request.user_id = earlybird_order.user_id
          AND original_request.pipeline_version = 'v2'
          AND original_request.status = 'failed'
          AND original_request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          AND policy_request.user_id = earlybird_order.user_id
          AND policy_request.pipeline_version = 'v2'
          AND policy_request.status = 'failed'
          AND policy_request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          AND earlybird_order.plan_id = 'basic'
          AND earlybird_order.expected_amount_krw = 990
          AND earlybird_order.actual_amount_krw = 990
          AND earlybird_order.payment_id IS NOT NULL
          AND earlybird_order.seller_reference_confirmed_at IS NOT NULL
          AND earlybird_order.actual_groble_product_id
                IS NOT DISTINCT FROM earlybird_order.expected_groble_product_id
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_failure_receipts AS receipt
              WHERE receipt.request_id = failed_request.id
                AND receipt.failed_job_key = 'track:profiles:batch:3'
                AND receipt.error_code = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_failure_receipts AS receipt
              WHERE receipt.request_id = failed_request.id
          )
          AND 11 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_pipeline_jobs AS job
              WHERE job.request_id = failed_request.id
          )
          AND 6 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_pipeline_jobs AS job
              WHERE job.request_id = failed_request.id
                AND job.status = 'completed'
          )
          AND 4 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_pipeline_jobs AS job
              WHERE job.request_id = failed_request.id
                AND job.status = 'cancelled'
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_pipeline_jobs AS job
              WHERE job.request_id = failed_request.id
                AND job.job_key = 'track:profiles:batch:3'
                AND job.status = 'failed'
                AND job.attempt_count = 2
                AND job.last_error_code = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_pipeline_jobs AS job
              WHERE job.request_id = failed_request.id
                AND job.status IN ('pending', 'processing')
          )
          AND 3 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = failed_request.id
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = failed_request.id
                AND provider_run.job_key = 'track:profiles:batch:2'
                AND provider_run.status = 'aborted'
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = failed_request.id
                AND provider_run.job_key = 'track:profiles:batch:4'
                AND provider_run.status = 'succeeded'
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = failed_request.id
                AND provider_run.job_key = 'track:relationships:collect'
                AND provider_run.status = 'succeeded'
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_provider_cleanup_intents AS cleanup
              WHERE cleanup.request_id = failed_request.id
                AND cleanup.completed_at IS NULL
          )
          AND 30 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = failed_request.id
                AND attempt.terminalized_at IS NOT NULL
          )
          AND 14 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = failed_request.id
                AND attempt.stage = 'genderTriage'
                AND attempt.status = 'success'
                AND attempt.terminalized_at IS NOT NULL
          )
          AND 8 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = failed_request.id
                AND attempt.stage = 'featureAnalysis'
                AND attempt.status = 'success'
                AND attempt.terminalized_at IS NOT NULL
          )
          AND 2 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = failed_request.id
                AND attempt.status = 'response_rejected'
                AND attempt.terminalized_at IS NOT NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = failed_request.id
                AND attempt.stage = 'privateAccountName'
                AND attempt.status = 'cutoff'
                AND attempt.terminalized_at IS NOT NULL
          )
          AND 24 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_scheduler_operations AS operation
              WHERE operation.request_id = failed_request.id
          )
          AND 22 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_scheduler_operations AS operation
              WHERE operation.request_id = failed_request.id
                AND operation.status = 'ready'
                AND operation.completed_at IS NOT NULL
          )
          AND 2 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_scheduler_operations AS operation
              WHERE operation.request_id = failed_request.id
                AND operation.status = 'terminal_unavailable'
                AND operation.completed_at IS NULL
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_gemini_leases AS lease
              WHERE lease.request_id = failed_request.id
          )
    );
$$;


--
-- Name: earlybird_v211_apify_transient_replay_ready(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earlybird_v211_apify_transient_replay_ready(p_order_id uuid, p_original_failed_request_id uuid, p_recovery_preflight_id uuid, p_current_preflight_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
    SELECT EXISTS (
        SELECT 1
        
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, policy_identity_failed_request_id UUID, transient_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_apify_transient_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','policy_identity_failed_request_id','transient_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.policy_identity_failed_request_id IS NOT NULL AND decoded.transient_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS replay
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
          ON recovery.order_id = replay.order_id
         AND recovery.failed_request_id = replay.original_failed_request_id
        JOIN public.earlybird_orders AS earlybird_order
          ON earlybird_order.id = replay.order_id
        JOIN public.analysis_preflights AS failed_preflight
          ON failed_preflight.id = replay.failed_preflight_id
        JOIN public.analysis_preflights AS current_preflight
          ON current_preflight.id = replay.rearmed_preflight_id
        WHERE replay.order_id = p_order_id
          AND replay.original_failed_request_id = p_original_failed_request_id
          AND recovery.recovery_preflight_id = p_recovery_preflight_id
          AND replay.rearmed_preflight_id = p_current_preflight_id
          AND replay.expected_fulfillment_attempt_count = 1
          AND public.earlybird_v211_apify_transient_failure_ready(
                replay.order_id,
                replay.original_failed_request_id,
                replay.transient_failed_request_id,
                replay.failed_preflight_id
          )
          AND earlybird_order.preflight_id = current_preflight.id
          AND earlybird_order.user_id = current_preflight.user_id
          AND earlybird_order.status IN ('paid', 'analysis_in_progress')
          AND earlybird_order.plan_id = 'basic'
          AND earlybird_order.expected_amount_krw = 990
          AND earlybird_order.actual_amount_krw = 990
          AND earlybird_order.payment_id IS NOT NULL
          AND earlybird_order.seller_reference_confirmed_at IS NOT NULL
          AND earlybird_order.actual_groble_product_id
                IS NOT DISTINCT FROM earlybird_order.expected_groble_product_id
          AND current_preflight.user_id = earlybird_order.user_id
          AND current_preflight.access_mode = 'production'
          AND current_preflight.status IN ('ready', 'consumed')
          AND current_preflight.pii_scrubbed_at IS NULL
          AND current_preflight.idempotency_key =
                'earlybird.fulfillment.'
                || pg_catalog.replace(earlybird_order.id::TEXT, '-', '') || '.r9'
          AND current_preflight.target_instagram_id =
                earlybird_order.target_instagram_id
          AND current_preflight.admission_status = 'ready'
          AND current_preflight.admission_selected_plan_id = 'basic'
          AND current_preflight.admission_target_followers_count =
                current_preflight.target_followers_count
          AND current_preflight.admission_target_following_count =
                current_preflight.target_following_count
          AND current_preflight.admission_capacity_required_plan_id
                IS NOT DISTINCT FROM current_preflight.capacity_required_plan_id
          AND current_preflight.admission_required_plan_id
                IS NOT DISTINCT FROM current_preflight.required_plan_id
          AND current_preflight.admission_plan_cards_snapshot =
                current_preflight.plan_cards_snapshot
          AND current_preflight.launch_status_snapshot =
                failed_preflight.launch_status_snapshot
          AND current_preflight.plan_catalog_snapshot =
                failed_preflight.plan_catalog_snapshot
          AND current_preflight.plan_cards_snapshot =
                failed_preflight.plan_cards_snapshot
          AND current_preflight.pricing_version = failed_preflight.pricing_version
          AND current_preflight.pricing_snapshot = failed_preflight.pricing_snapshot
          AND current_preflight.policy_versions_snapshot =
                failed_preflight.policy_versions_snapshot
          AND public.analysis_v2_valid_plan_cards_snapshot(
                current_preflight.plan_cards_snapshot
          )
          AND current_preflight.plan_cards_snapshot
                -> 'basic' ->> 'launchStatus' = 'production'
          AND current_preflight.plan_cards_snapshot
                -> 'basic' ->> 'selectionState'
                IN ('required', 'available_upgrade')
          AND current_preflight.target_followers_count BETWEEN 0 AND CASE
                WHEN COALESCE(
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'followers',
                    ''
                ) ~ '^[0-9]+$' THEN (
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'followers'
                )::INTEGER
                ELSE -1
          END
          AND current_preflight.target_following_count BETWEEN 0 AND CASE
                WHEN COALESCE(
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'following',
                    ''
                ) ~ '^[0-9]+$' THEN (
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'following'
                )::INTEGER
                ELSE -1
          END
          AND earlybird_order.target_followers_count BETWEEN 0 AND CASE
                WHEN COALESCE(
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'followers',
                    ''
                ) ~ '^[0-9]+$' THEN (
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'followers'
                )::INTEGER
                ELSE -1
          END
          AND earlybird_order.target_following_count BETWEEN 0 AND CASE
                WHEN COALESCE(
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'following',
                    ''
                ) ~ '^[0-9]+$' THEN (
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'following'
                )::INTEGER
                ELSE -1
          END
    );
$_$;


--
-- Name: earlybird_v211_concierge_replay_ready(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earlybird_v211_concierge_replay_ready(p_order_id uuid, p_original_failed_request_id uuid, p_recovery_preflight_id uuid, p_current_preflight_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1
        
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, first_relationship_failed_request_id UUID, second_relationship_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ, reviewed_source_request_id UUID, reviewed_source_owner_id UUID, reviewed_source_target_instagram_id TEXT, reviewed_source_result_request_id UUID, reviewed_source_target_posts JSONB, reviewed_source_target_evidence JSONB, reviewed_source_fingerprint VARCHAR(64), reviewed_source_registered_at TIMESTAMPTZ, published_source_fingerprint VARCHAR(64), published_result_hash VARCHAR(64), published_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_concierge_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','first_relationship_failed_request_id','second_relationship_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at','reviewed_source_request_id','reviewed_source_owner_id','reviewed_source_target_instagram_id','reviewed_source_result_request_id','reviewed_source_target_posts','reviewed_source_target_evidence','reviewed_source_fingerprint','reviewed_source_registered_at','published_source_fingerprint','published_result_hash','published_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.first_relationship_failed_request_id IS NOT NULL AND decoded.second_relationship_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS concierge
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, original_failed_request_id UUID, relationship_failed_request_id UUID, source_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'rearm'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_relationship_lineage_failure_rearms'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','relationship_failed_request_id','source_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.relationship_failed_request_id IS NOT NULL AND decoded.source_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS first_rearm
          ON first_rearm.order_id = concierge.order_id
         AND first_rearm.original_failed_request_id =
                concierge.original_failed_request_id
         AND first_rearm.relationship_failed_request_id =
                concierge.first_relationship_failed_request_id
         AND first_rearm.rearmed_preflight_id = concierge.failed_preflight_id
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, failed_request_id UUID, source_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'rearm'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_lease_policy_failure_rearms'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','source_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.source_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS incident
          ON incident.order_id = concierge.order_id
         AND incident.failed_request_id = concierge.original_failed_request_id
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
          ON recovery.order_id = concierge.order_id
         AND recovery.failed_request_id = concierge.original_failed_request_id
        JOIN public.earlybird_orders AS earlybird_order
          ON earlybird_order.id = concierge.order_id
        JOIN public.analysis_requests AS original_request
          ON original_request.id = concierge.original_failed_request_id
        JOIN public.analysis_requests AS second_request
          ON second_request.id = concierge.second_relationship_failed_request_id
        JOIN public.analysis_preflights AS failed_preflight
          ON failed_preflight.id = concierge.failed_preflight_id
        JOIN public.analysis_preflights AS current_preflight
          ON current_preflight.id = concierge.rearmed_preflight_id
        JOIN public.analysis_preflights AS source_preflight
          ON source_preflight.id = original_request.preflight_id
        WHERE concierge.order_id = p_order_id
          AND concierge.original_failed_request_id = p_original_failed_request_id
          AND recovery.recovery_preflight_id = p_recovery_preflight_id
          AND concierge.rearmed_preflight_id = p_current_preflight_id
          AND concierge.expected_fulfillment_attempt_count = 1
          AND recovery.prior_attempt_count = 1
          AND incident.rearmed_preflight_id = recovery.recovery_preflight_id
          AND earlybird_order.preflight_id = current_preflight.id
          AND earlybird_order.user_id = current_preflight.user_id
          AND earlybird_order.plan_id = 'basic'
          AND earlybird_order.expected_amount_krw = 990
          AND earlybird_order.actual_amount_krw = 990
          AND earlybird_order.payment_id IS NOT NULL
          AND earlybird_order.seller_reference_confirmed_at IS NOT NULL
          AND earlybird_order.actual_groble_product_id
                IS NOT DISTINCT FROM earlybird_order.expected_groble_product_id
          AND original_request.user_id = earlybird_order.user_id
          AND original_request.pipeline_version = 'v2'
          AND original_request.status = 'failed'
          AND original_request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          AND original_request.policy_versions_snapshot =
                pg_catalog.jsonb_build_object(
                    'pipeline', 'v2',
                    'risk', 'risk-policy-v2.5',
                    'aiStage', 'ai-stage-policy-v2.11',
                    'scheduler', 'ai-scheduler-v1'
                )
          AND second_request.user_id = earlybird_order.user_id
          AND second_request.preflight_id = failed_preflight.id
          AND second_request.pipeline_version = 'v2'
          AND second_request.status = 'failed'
          AND second_request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          AND second_request.idempotency_key =
                'earlybird:' || pg_catalog.lower(earlybird_order.id::TEXT) || '.r2'
          AND failed_preflight.user_id = earlybird_order.user_id
          AND failed_preflight.status = 'consumed'
          AND failed_preflight.consumed_request_id = second_request.id
          AND failed_preflight.pii_scrubbed_at IS NOT NULL
          AND failed_preflight.idempotency_key =
                'earlybird.fulfillment.'
                || pg_catalog.replace(earlybird_order.id::TEXT, '-', '') || '.r5'
          AND current_preflight.user_id = earlybird_order.user_id
          AND current_preflight.access_mode = 'production'
          AND current_preflight.status IN ('ready', 'consumed')
          AND current_preflight.idempotency_key =
                'earlybird.fulfillment.'
                || pg_catalog.replace(earlybird_order.id::TEXT, '-', '') || '.r6'
          AND current_preflight.target_instagram_id =
                earlybird_order.target_instagram_id
          AND current_preflight.target_followers_count =
                source_preflight.admission_target_followers_count
          AND current_preflight.target_following_count =
                source_preflight.admission_target_following_count
          AND current_preflight.admission_status = 'ready'
          AND current_preflight.admission_selected_plan_id = 'basic'
          AND current_preflight.admission_target_followers_count =
                current_preflight.target_followers_count
          AND current_preflight.admission_target_following_count =
                current_preflight.target_following_count
          AND current_preflight.launch_status_snapshot =
                failed_preflight.launch_status_snapshot
          AND current_preflight.plan_catalog_snapshot =
                failed_preflight.plan_catalog_snapshot
          AND current_preflight.pricing_version = failed_preflight.pricing_version
          AND current_preflight.pricing_snapshot = failed_preflight.pricing_snapshot
          AND current_preflight.policy_versions_snapshot =
                failed_preflight.policy_versions_snapshot
          AND EXISTS (
              SELECT 1
              FROM public.analysis_v2_failure_receipts AS receipt
              WHERE receipt.request_id = second_request.id
                AND receipt.failed_job_key = 'track:relationships:collect'
                AND receipt.error_code = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          )
          AND 2 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_recovery_provider_run_adoptions AS adoption
              WHERE adoption.request_id = second_request.id
                AND adoption.source_request_id = original_request.id
                AND adoption.job_key = 'track:relationships:collect'
                AND adoption.source_job_key = 'track:relationships:collect'
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = second_request.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_provider_cost_ledger AS cost
              WHERE cost.request_id = second_request.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = second_request.id
          )
          AND 7 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = original_request.id
          )
          AND 6 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = original_request.id
                AND provider_run.status = 'succeeded'
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = original_request.id
                AND provider_run.status = 'aborted'
                AND provider_run.job_key = 'track:profiles:batch:4'
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = original_request.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
              WHERE checkpoint.request_id = original_request.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_v2_gemini_leases AS lease
              WHERE lease.request_id = original_request.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_provider_cleanup_intents AS cleanup
              WHERE cleanup.request_id = original_request.id
                AND cleanup.completed_at IS NULL
          )
    );
$$;


--
-- Name: earlybird_v211_policy_identity_replay_ready(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earlybird_v211_policy_identity_replay_ready(p_order_id uuid, p_original_failed_request_id uuid, p_recovery_preflight_id uuid, p_current_preflight_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
    SELECT EXISTS (
        SELECT 1
        
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, policy_identity_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_policy_identity_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','policy_identity_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.policy_identity_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS replay
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, original_failed_request_id UUID, profile_ai_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_profile_ai_diagnostic_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','profile_ai_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.profile_ai_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS diagnostic
          ON diagnostic.order_id = replay.order_id
         AND diagnostic.original_failed_request_id = replay.original_failed_request_id
         AND diagnostic.rearmed_preflight_id = replay.failed_preflight_id
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, original_failed_request_id UUID, first_relationship_failed_request_id UUID, second_relationship_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ, reviewed_source_request_id UUID, reviewed_source_owner_id UUID, reviewed_source_target_instagram_id TEXT, reviewed_source_result_request_id UUID, reviewed_source_target_posts JSONB, reviewed_source_target_evidence JSONB, reviewed_source_fingerprint VARCHAR(64), reviewed_source_registered_at TIMESTAMPTZ, published_source_fingerprint VARCHAR(64), published_result_hash VARCHAR(64), published_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_concierge_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','first_relationship_failed_request_id','second_relationship_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at','reviewed_source_request_id','reviewed_source_owner_id','reviewed_source_target_instagram_id','reviewed_source_result_request_id','reviewed_source_target_posts','reviewed_source_target_evidence','reviewed_source_fingerprint','reviewed_source_registered_at','published_source_fingerprint','published_result_hash','published_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.first_relationship_failed_request_id IS NOT NULL AND decoded.second_relationship_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS concierge
          ON concierge.order_id = replay.order_id
         AND concierge.original_failed_request_id = replay.original_failed_request_id
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
          ON recovery.order_id = replay.order_id
         AND recovery.failed_request_id = replay.original_failed_request_id
        JOIN public.earlybird_orders AS earlybird_order
          ON earlybird_order.id = replay.order_id
        JOIN public.analysis_requests AS original_request
          ON original_request.id = replay.original_failed_request_id
        JOIN public.analysis_requests AS policy_request
          ON policy_request.id = replay.policy_identity_failed_request_id
        JOIN public.analysis_preflights AS failed_preflight
          ON failed_preflight.id = replay.failed_preflight_id
        JOIN public.analysis_preflights AS current_preflight
          ON current_preflight.id = replay.rearmed_preflight_id
        JOIN public.analysis_preflights AS source_preflight
          ON source_preflight.id = original_request.preflight_id
        WHERE replay.order_id = p_order_id
          AND replay.original_failed_request_id = p_original_failed_request_id
          AND recovery.recovery_preflight_id = p_recovery_preflight_id
          AND replay.rearmed_preflight_id = p_current_preflight_id
          AND replay.expected_fulfillment_attempt_count = 1
          AND diagnostic.expected_fulfillment_attempt_count = 1
          AND recovery.prior_attempt_count = 1
          AND earlybird_order.preflight_id = current_preflight.id
          AND earlybird_order.user_id = current_preflight.user_id
          AND earlybird_order.status IN ('paid', 'analysis_in_progress')
          AND earlybird_order.plan_id = 'basic'
          AND earlybird_order.expected_amount_krw = 990
          AND earlybird_order.actual_amount_krw = 990
          AND earlybird_order.payment_id IS NOT NULL
          AND earlybird_order.seller_reference_confirmed_at IS NOT NULL
          AND earlybird_order.actual_groble_product_id
                IS NOT DISTINCT FROM earlybird_order.expected_groble_product_id
          AND original_request.user_id = earlybird_order.user_id
          AND original_request.pipeline_version = 'v2'
          AND original_request.status = 'failed'
          AND original_request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          AND original_request.policy_versions_snapshot =
                pg_catalog.jsonb_build_object(
                    'pipeline', 'v2',
                    'risk', 'risk-policy-v2.5',
                    'aiStage', 'ai-stage-policy-v2.11',
                    'scheduler', 'ai-scheduler-v1'
                )
          AND policy_request.user_id = earlybird_order.user_id
          AND policy_request.preflight_id = failed_preflight.id
          AND policy_request.pipeline_version = 'v2'
          AND policy_request.status = 'failed'
          AND policy_request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          AND policy_request.idempotency_key =
                'earlybird:' || pg_catalog.lower(earlybird_order.id::TEXT) || '.r4'
          AND failed_preflight.user_id = earlybird_order.user_id
          AND failed_preflight.status = 'consumed'
          AND failed_preflight.consumed_request_id = policy_request.id
          AND failed_preflight.pii_scrubbed_at IS NOT NULL
          AND failed_preflight.idempotency_key =
                'earlybird.fulfillment.'
                || pg_catalog.replace(earlybird_order.id::TEXT, '-', '') || '.r7'
          AND current_preflight.user_id = earlybird_order.user_id
          AND current_preflight.access_mode = 'production'
          AND current_preflight.status IN ('ready', 'consumed')
          AND current_preflight.idempotency_key =
                'earlybird.fulfillment.'
                || pg_catalog.replace(earlybird_order.id::TEXT, '-', '') || '.r8'
          AND current_preflight.target_instagram_id =
                earlybird_order.target_instagram_id
          AND source_preflight.admission_target_followers_count IS NOT NULL
          AND source_preflight.admission_target_followers_count >= 0
          AND source_preflight.admission_target_following_count IS NOT NULL
          AND source_preflight.admission_target_following_count >= 0
          AND earlybird_order.target_followers_count IS NOT NULL
          AND earlybird_order.target_followers_count >= 0
          AND earlybird_order.target_following_count IS NOT NULL
          AND earlybird_order.target_following_count >= 0
          AND current_preflight.target_followers_count IS NOT NULL
          AND current_preflight.target_followers_count >= 0
          AND current_preflight.target_following_count IS NOT NULL
          AND current_preflight.target_following_count >= 0
          AND current_preflight.admission_status = 'ready'
          AND current_preflight.admission_selected_plan_id = 'basic'
          AND current_preflight.admission_target_followers_count =
                current_preflight.target_followers_count
          AND current_preflight.admission_target_following_count =
                current_preflight.target_following_count
          AND current_preflight.launch_status_snapshot =
                failed_preflight.launch_status_snapshot
          AND current_preflight.plan_catalog_snapshot =
                failed_preflight.plan_catalog_snapshot
          AND current_preflight.pricing_version = failed_preflight.pricing_version
          AND current_preflight.pricing_snapshot = failed_preflight.pricing_snapshot
          AND current_preflight.policy_versions_snapshot =
                failed_preflight.policy_versions_snapshot
          AND current_preflight.plan_cards_snapshot =
                failed_preflight.plan_cards_snapshot
          AND current_preflight.admission_plan_cards_snapshot =
                current_preflight.plan_cards_snapshot
          AND current_preflight.admission_capacity_required_plan_id
                IS NOT DISTINCT FROM current_preflight.capacity_required_plan_id
          AND current_preflight.admission_required_plan_id
                IS NOT DISTINCT FROM current_preflight.required_plan_id
          AND public.analysis_v2_valid_plan_cards_snapshot(
                current_preflight.plan_cards_snapshot
          )
          AND current_preflight.plan_cards_snapshot
                -> 'basic' ->> 'launchStatus' = 'production'
          AND current_preflight.plan_cards_snapshot
                -> 'basic' ->> 'selectionState'
                IN ('required', 'available_upgrade')
          AND COALESCE(
                current_preflight.plan_cards_snapshot
                    -> 'basic' -> 'relationshipCapacity' ->> 'followers',
                ''
          ) ~ '^[0-9]+$'
          AND COALESCE(
                current_preflight.plan_cards_snapshot
                    -> 'basic' -> 'relationshipCapacity' ->> 'following',
                ''
          ) ~ '^[0-9]+$'
          AND source_preflight.admission_target_followers_count <= CASE
                WHEN COALESCE(
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'followers',
                    ''
                ) ~ '^[0-9]+$' THEN (
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'followers'
                )::INTEGER
                ELSE -1
          END
          AND earlybird_order.target_followers_count <= CASE
                WHEN COALESCE(
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'followers',
                    ''
                ) ~ '^[0-9]+$' THEN (
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'followers'
                )::INTEGER
                ELSE -1
          END
          AND current_preflight.target_followers_count <= CASE
                WHEN COALESCE(
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'followers',
                    ''
                ) ~ '^[0-9]+$' THEN (
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'followers'
                )::INTEGER
                ELSE -1
          END
          AND source_preflight.admission_target_following_count <= CASE
                WHEN COALESCE(
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'following',
                    ''
                ) ~ '^[0-9]+$' THEN (
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'following'
                )::INTEGER
                ELSE -1
          END
          AND earlybird_order.target_following_count <= CASE
                WHEN COALESCE(
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'following',
                    ''
                ) ~ '^[0-9]+$' THEN (
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'following'
                )::INTEGER
                ELSE -1
          END
          AND current_preflight.target_following_count <= CASE
                WHEN COALESCE(
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'following',
                    ''
                ) ~ '^[0-9]+$' THEN (
                    current_preflight.plan_cards_snapshot
                        -> 'basic' -> 'relationshipCapacity' ->> 'following'
                )::INTEGER
                ELSE -1
          END
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_failure_receipts AS receipt
              WHERE receipt.request_id = policy_request.id
                AND receipt.failed_job_key = 'track:profile-ai:batch:3'
                AND receipt.error_code = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_failure_receipts AS receipt
              WHERE receipt.request_id = policy_request.id
          )
          AND 12 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_pipeline_jobs AS job
              WHERE job.request_id = policy_request.id
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_pipeline_jobs AS job
              WHERE job.request_id = policy_request.id
                AND job.job_key = 'track:profile-ai:batch:3'
                AND job.status = 'failed'
                AND job.attempt_count = 1
                AND job.last_error_code = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          )
          AND 6 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_recovery_provider_run_adoptions AS adoption
              WHERE adoption.request_id = policy_request.id
                AND adoption.source_request_id = original_request.id
          )
          AND 4 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = policy_request.id
                AND provider_run.status IN ('succeeded', 'aborted')
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_provider_cleanup_intents AS cleanup
              WHERE cleanup.request_id = policy_request.id
                AND cleanup.completed_at IS NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = policy_request.id
                AND attempt.job_key = 'track:private-names:batch:0'
                AND attempt.stage = 'privateAccountName'
                AND attempt.status = 'success'
                AND attempt.terminalized_at IS NOT NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = policy_request.id
          )
          AND 12 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_scheduler_operations AS operation
              WHERE operation.request_id = policy_request.id
          )
          AND 5 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_scheduler_operations AS operation
              WHERE operation.request_id = policy_request.id
                AND operation.job_key = 'track:profile-ai:batch:0'
                AND operation.stage = 'genderTriage'
                AND operation.status = 'claimed'
                AND operation.completed_at IS NULL
          )
          AND 6 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_scheduler_operations AS operation
              WHERE operation.request_id = policy_request.id
                AND operation.job_key = 'track:profile-ai:batch:3'
                AND operation.stage = 'genderTriage'
                AND operation.status = 'claimed'
                AND operation.completed_at IS NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_scheduler_operations AS operation
              WHERE operation.request_id = policy_request.id
                AND operation.job_key = 'track:private-names:batch:0'
                AND operation.stage = 'privateAccountName'
                AND operation.status = 'ready'
                AND operation.completed_at IS NOT NULL
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_v2_gemini_leases AS lease
              WHERE lease.request_id = policy_request.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
              WHERE checkpoint.request_id = policy_request.id
          )
          AND 7 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = original_request.id
          )
          AND 6 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = original_request.id
                AND provider_run.status = 'succeeded'
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = original_request.id
                AND provider_run.status = 'aborted'
                AND provider_run.job_key = 'track:profiles:batch:4'
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_provider_cleanup_intents AS cleanup
              WHERE cleanup.request_id = original_request.id
                AND cleanup.completed_at IS NULL
          )
    ) OR public.earlybird_v211_apify_transient_replay_ready(
        p_order_id,
        p_original_failed_request_id,
        p_recovery_preflight_id,
        p_current_preflight_id
    );
$_$;


--
-- Name: earlybird_v211_profile_ai_diagnostic_replay_ready(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earlybird_v211_profile_ai_diagnostic_replay_ready(p_order_id uuid, p_original_failed_request_id uuid, p_recovery_preflight_id uuid, p_current_preflight_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1
        
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, profile_ai_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_profile_ai_diagnostic_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','profile_ai_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.profile_ai_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS diagnostic
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, original_failed_request_id UUID, first_relationship_failed_request_id UUID, second_relationship_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ, reviewed_source_request_id UUID, reviewed_source_owner_id UUID, reviewed_source_target_instagram_id TEXT, reviewed_source_result_request_id UUID, reviewed_source_target_posts JSONB, reviewed_source_target_evidence JSONB, reviewed_source_fingerprint VARCHAR(64), reviewed_source_registered_at TIMESTAMPTZ, published_source_fingerprint VARCHAR(64), published_result_hash VARCHAR(64), published_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_concierge_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','first_relationship_failed_request_id','second_relationship_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at','reviewed_source_request_id','reviewed_source_owner_id','reviewed_source_target_instagram_id','reviewed_source_result_request_id','reviewed_source_target_posts','reviewed_source_target_evidence','reviewed_source_fingerprint','reviewed_source_registered_at','published_source_fingerprint','published_result_hash','published_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.first_relationship_failed_request_id IS NOT NULL AND decoded.second_relationship_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS concierge
          ON concierge.order_id = diagnostic.order_id
         AND concierge.original_failed_request_id =
                diagnostic.original_failed_request_id
         AND concierge.rearmed_preflight_id = diagnostic.failed_preflight_id
         AND concierge.second_relationship_failed_request_id IS NOT NULL
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
          ON recovery.order_id = diagnostic.order_id
         AND recovery.failed_request_id = diagnostic.original_failed_request_id
        JOIN public.earlybird_orders AS earlybird_order
          ON earlybird_order.id = diagnostic.order_id
        JOIN public.analysis_requests AS original_request
          ON original_request.id = diagnostic.original_failed_request_id
        JOIN public.analysis_requests AS profile_ai_request
          ON profile_ai_request.id = diagnostic.profile_ai_failed_request_id
        JOIN public.analysis_preflights AS failed_preflight
          ON failed_preflight.id = diagnostic.failed_preflight_id
        JOIN public.analysis_preflights AS current_preflight
          ON current_preflight.id = diagnostic.rearmed_preflight_id
        JOIN public.analysis_preflights AS source_preflight
          ON source_preflight.id = original_request.preflight_id
        WHERE diagnostic.order_id = p_order_id
          AND diagnostic.original_failed_request_id =
                p_original_failed_request_id
          AND recovery.recovery_preflight_id = p_recovery_preflight_id
          AND diagnostic.rearmed_preflight_id = p_current_preflight_id
          AND diagnostic.expected_fulfillment_attempt_count = 1
          AND recovery.prior_attempt_count = 1
          AND earlybird_order.preflight_id = current_preflight.id
          AND earlybird_order.user_id = current_preflight.user_id
          AND earlybird_order.plan_id = 'basic'
          AND earlybird_order.expected_amount_krw = 990
          AND earlybird_order.actual_amount_krw = 990
          AND earlybird_order.payment_id IS NOT NULL
          AND earlybird_order.seller_reference_confirmed_at IS NOT NULL
          AND earlybird_order.actual_groble_product_id
                IS NOT DISTINCT FROM earlybird_order.expected_groble_product_id
          AND original_request.user_id = earlybird_order.user_id
          AND original_request.pipeline_version = 'v2'
          AND original_request.status = 'failed'
          AND original_request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          AND original_request.policy_versions_snapshot =
                pg_catalog.jsonb_build_object(
                    'pipeline', 'v2',
                    'risk', 'risk-policy-v2.5',
                    'aiStage', 'ai-stage-policy-v2.11',
                    'scheduler', 'ai-scheduler-v1'
                )
          AND profile_ai_request.user_id = earlybird_order.user_id
          AND profile_ai_request.preflight_id = failed_preflight.id
          AND profile_ai_request.pipeline_version = 'v2'
          AND profile_ai_request.status = 'failed'
          AND profile_ai_request.error_message =
                'ANALYSIS_V2_JOB_HANDLER_FAILED'
          AND profile_ai_request.idempotency_key =
                'earlybird:' || pg_catalog.lower(earlybird_order.id::TEXT) || '.r3'
          AND failed_preflight.user_id = earlybird_order.user_id
          AND failed_preflight.status = 'consumed'
          AND failed_preflight.consumed_request_id = profile_ai_request.id
          AND failed_preflight.pii_scrubbed_at IS NOT NULL
          AND failed_preflight.idempotency_key =
                'earlybird.fulfillment.'
                || pg_catalog.replace(earlybird_order.id::TEXT, '-', '') || '.r6'
          AND current_preflight.user_id = earlybird_order.user_id
          AND current_preflight.access_mode = 'production'
          AND current_preflight.status IN ('ready', 'consumed')
          AND current_preflight.idempotency_key =
                'earlybird.fulfillment.'
                || pg_catalog.replace(earlybird_order.id::TEXT, '-', '') || '.r7'
          AND current_preflight.target_instagram_id =
                earlybird_order.target_instagram_id
          AND current_preflight.target_followers_count =
                source_preflight.admission_target_followers_count
          AND current_preflight.target_following_count =
                source_preflight.admission_target_following_count
          AND current_preflight.admission_status = 'ready'
          AND current_preflight.admission_selected_plan_id = 'basic'
          AND current_preflight.admission_target_followers_count =
                current_preflight.target_followers_count
          AND current_preflight.admission_target_following_count =
                current_preflight.target_following_count
          AND current_preflight.launch_status_snapshot =
                failed_preflight.launch_status_snapshot
          AND current_preflight.plan_catalog_snapshot =
                failed_preflight.plan_catalog_snapshot
          AND current_preflight.pricing_version = failed_preflight.pricing_version
          AND current_preflight.pricing_snapshot = failed_preflight.pricing_snapshot
          AND current_preflight.policy_versions_snapshot =
                failed_preflight.policy_versions_snapshot
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_failure_receipts AS receipt
              WHERE receipt.request_id = profile_ai_request.id
                AND receipt.failed_job_key = 'track:profile-ai:batch:2'
                AND receipt.error_code = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_failure_receipts AS receipt
              WHERE receipt.request_id = profile_ai_request.id
          )
          AND 6 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_recovery_provider_run_adoptions AS adoption
              WHERE adoption.request_id = profile_ai_request.id
                AND adoption.source_request_id = original_request.id
          )
          AND 5 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = profile_ai_request.id
                AND provider_run.status IN ('succeeded', 'aborted')
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_provider_cleanup_intents AS cleanup
              WHERE cleanup.request_id = profile_ai_request.id
                AND cleanup.completed_at IS NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = profile_ai_request.id
                AND attempt.job_key = 'track:private-names:batch:0'
                AND attempt.stage = 'privateAccountName'
                AND attempt.status = 'success'
                AND attempt.terminalized_at IS NOT NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = profile_ai_request.id
          )
          AND 7 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_scheduler_operations AS operation
              WHERE operation.request_id = profile_ai_request.id
          )
          AND 6 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_scheduler_operations AS operation
              WHERE operation.request_id = profile_ai_request.id
                AND operation.job_key = 'track:profile-ai:batch:2'
                AND operation.stage = 'genderTriage'
                AND operation.status = 'claimed'
                AND operation.completed_at IS NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_scheduler_operations AS operation
              WHERE operation.request_id = profile_ai_request.id
                AND operation.job_key = 'track:private-names:batch:0'
                AND operation.stage = 'privateAccountName'
                AND operation.status = 'ready'
                AND operation.completed_at IS NOT NULL
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_v2_gemini_leases AS lease
              WHERE lease.request_id = profile_ai_request.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
              WHERE checkpoint.request_id = profile_ai_request.id
          )
          AND 7 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = original_request.id
          )
          AND 6 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = original_request.id
                AND provider_run.status = 'succeeded'
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = original_request.id
                AND provider_run.status = 'aborted'
                AND provider_run.job_key = 'track:profiles:batch:4'
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_provider_cleanup_intents AS cleanup
              WHERE cleanup.request_id = original_request.id
                AND cleanup.completed_at IS NULL
          )
    );
$$;


--
-- Name: earlybird_v211_relationship_lineage_rearm_ready(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.earlybird_v211_relationship_lineage_rearm_ready(p_order_id uuid, p_original_failed_request_id uuid, p_source_preflight_id uuid, p_current_preflight_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1
        
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, relationship_failed_request_id UUID, source_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'rearm'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_relationship_lineage_failure_rearms'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','relationship_failed_request_id','source_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.relationship_failed_request_id IS NOT NULL AND decoded.source_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS rearm
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, failed_request_id UUID, source_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'rearm'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_lease_policy_failure_rearms'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','source_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.source_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS incident
          ON incident.order_id = rearm.order_id
         AND incident.failed_request_id = rearm.original_failed_request_id
         AND incident.rearmed_preflight_id = rearm.source_preflight_id
        
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
          ON recovery.order_id = rearm.order_id
         AND recovery.failed_request_id = rearm.original_failed_request_id
         AND recovery.recovery_preflight_id = rearm.source_preflight_id
        JOIN public.earlybird_orders AS earlybird_order
          ON earlybird_order.id = rearm.order_id
        JOIN public.analysis_requests AS original_request
          ON original_request.id = rearm.original_failed_request_id
        JOIN public.analysis_requests AS relationship_request
          ON relationship_request.id = rearm.relationship_failed_request_id
        JOIN public.analysis_preflights AS source_preflight
          ON source_preflight.id = rearm.source_preflight_id
        JOIN public.analysis_preflights AS current_preflight
          ON current_preflight.id = rearm.rearmed_preflight_id
        WHERE rearm.order_id = p_order_id
          AND rearm.original_failed_request_id = p_original_failed_request_id
          AND rearm.source_preflight_id = p_source_preflight_id
          AND rearm.rearmed_preflight_id = p_current_preflight_id
          AND rearm.expected_fulfillment_attempt_count = 1
          AND recovery.prior_attempt_count = 1
          AND earlybird_order.preflight_id = current_preflight.id
          AND earlybird_order.user_id = current_preflight.user_id
          AND earlybird_order.plan_id = 'basic'
          AND earlybird_order.expected_amount_krw = 990
          AND earlybird_order.actual_amount_krw = 990
          AND earlybird_order.payment_id IS NOT NULL
          AND earlybird_order.seller_reference_confirmed_at IS NOT NULL
          AND earlybird_order.actual_groble_product_id
                IS NOT DISTINCT FROM earlybird_order.expected_groble_product_id
          AND original_request.user_id = earlybird_order.user_id
          AND original_request.preflight_id = incident.source_preflight_id
          AND original_request.pipeline_version = 'v2'
          AND original_request.status = 'failed'
          AND original_request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          AND original_request.policy_versions_snapshot =
                pg_catalog.jsonb_build_object(
                    'pipeline', 'v2',
                    'risk', 'risk-policy-v2.5',
                    'aiStage', 'ai-stage-policy-v2.11',
                    'scheduler', 'ai-scheduler-v1'
                )
          AND relationship_request.user_id = earlybird_order.user_id
          AND relationship_request.preflight_id = source_preflight.id
          AND relationship_request.pipeline_version = 'v2'
          AND relationship_request.status = 'failed'
          AND relationship_request.error_message =
                'ANALYSIS_V2_JOB_HANDLER_FAILED'
          AND relationship_request.idempotency_key =
                'earlybird:' || pg_catalog.lower(earlybird_order.id::TEXT) || '.r1'
          AND source_preflight.user_id = earlybird_order.user_id
          AND source_preflight.status = 'consumed'
          AND source_preflight.consumed_request_id = relationship_request.id
          AND source_preflight.pii_scrubbed_at IS NOT NULL
          AND source_preflight.target_instagram_id =
                'retained.' || pg_catalog.substr(
                    pg_catalog.replace(source_preflight.id::TEXT, '-', ''), 1, 20
                )
          AND source_preflight.idempotency_key =
                'earlybird.fulfillment.'
                || pg_catalog.replace(earlybird_order.id::TEXT, '-', '') || '.r4'
          AND source_preflight.admission_status = 'ready'
          AND source_preflight.admission_selected_plan_id = 'basic'
          AND current_preflight.user_id = earlybird_order.user_id
          AND current_preflight.access_mode = 'production'
          AND current_preflight.idempotency_key =
                'earlybird.fulfillment.'
                || pg_catalog.replace(earlybird_order.id::TEXT, '-', '') || '.r5'
          AND current_preflight.status IN ('ready', 'consumed')
          AND current_preflight.admission_status = 'ready'
          AND current_preflight.admission_selected_plan_id = 'basic'
          AND current_preflight.target_instagram_id =
                earlybird_order.target_instagram_id
          AND current_preflight.launch_status_snapshot =
                source_preflight.launch_status_snapshot
          AND current_preflight.plan_catalog_snapshot =
                source_preflight.plan_catalog_snapshot
          AND current_preflight.pricing_version = source_preflight.pricing_version
          AND current_preflight.pricing_snapshot = source_preflight.pricing_snapshot
          AND current_preflight.policy_versions_snapshot =
                source_preflight.policy_versions_snapshot
          AND EXISTS (
              SELECT 1
              FROM public.analysis_v2_failure_receipts AS receipt
              WHERE receipt.request_id = relationship_request.id
                AND receipt.failed_job_key = 'track:relationships:collect'
                AND receipt.error_code = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
          )
          AND 3 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_pipeline_jobs AS job
              WHERE job.request_id = relationship_request.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = relationship_request.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_recovery_provider_run_adoptions AS adoption
              WHERE adoption.request_id = relationship_request.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_provider_cost_ledger AS cost
              WHERE cost.request_id = relationship_request.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = relationship_request.id
          )
          AND 7 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = original_request.id
          )
          AND 6 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = original_request.id
                AND provider_run.status = 'succeeded'
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND 1 = (
              SELECT pg_catalog.count(*)
              FROM public.analysis_v2_provider_runs AS provider_run
              WHERE provider_run.request_id = original_request.id
                AND provider_run.status = 'aborted'
                AND provider_run.job_key = 'track:profiles:batch:4'
                AND provider_run.run_id IS NOT NULL
                AND provider_run.actual_usage_usd IS NOT NULL
                AND provider_run.usage_reconciled_at IS NOT NULL
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_ai_attempts AS attempt
              WHERE attempt.request_id = original_request.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
              WHERE checkpoint.request_id = original_request.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_gemini_leases AS lease
              WHERE lease.request_id = original_request.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_v2_provider_cleanup_intents AS cleanup
              WHERE cleanup.request_id = original_request.id
                AND cleanup.completed_at IS NULL
          )
    );
$$;


--
-- Name: enforce_account_paid_ever_monotonic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_account_paid_ever_monotonic() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF OLD.first_paid_at IS NOT NULL
       AND (
            NEW.first_paid_at IS NULL
            OR NEW.first_paid_at > OLD.first_paid_at
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_FIRST_PAID_AT_REGRESSION',
            ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_earlybird_preflight_fixed_ttl(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_earlybird_preflight_fixed_ttl() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM public.earlybird_orders AS earlybird_order
        WHERE earlybird_order.preflight_id = OLD.id
    ) THEN
        NEW.expires_at := NEW.created_at + INTERVAL '30 minutes';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_precheckout_blite_preflight_clock_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_precheckout_blite_preflight_clock_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.created_at IS DISTINCT FROM OLD.created_at THEN
            RAISE EXCEPTION USING
                MESSAGE = 'PRECHECKOUT_BLITE_CREATED_AT_IMMUTABLE', ERRCODE = 'P0001';
        END IF;
        IF NEW.precheckout_blite_deadline_seconds IS DISTINCT FROM OLD.precheckout_blite_deadline_seconds THEN
            RAISE EXCEPTION USING
                MESSAGE = 'PRECHECKOUT_BLITE_CLOCK_IMMUTABLE', ERRCODE = 'P0001';
        END IF;
        IF OLD.precheckout_blite_cohort THEN
            IF NEW.precheckout_blite_cohort IS DISTINCT FROM TRUE
               OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
               OR NEW.deadline_at IS DISTINCT FROM OLD.deadline_at THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'PRECHECKOUT_BLITE_CLOCK_IMMUTABLE', ERRCODE = 'P0001';
            END IF;
            -- A legacy T+60 row is immutable. Do not normalize it to T+90 on an update.
            RETURN NEW;
        END IF;
    END IF;

    IF TG_OP = 'INSERT' THEN
        -- Every row created after this migration carries the new deadline version, even while
        -- it is still outside the cohort. Existing rows retain the additive default of 60.
        NEW.precheckout_blite_deadline_seconds := 90;
    END IF;

    IF NEW.precheckout_blite_cohort THEN
        IF NEW.submitted_at IS NOT NULL AND NEW.submitted_at IS DISTINCT FROM NEW.created_at THEN
            RAISE EXCEPTION USING
                MESSAGE = 'PRECHECKOUT_BLITE_CLOCK_ORIGIN_FORBIDDEN', ERRCODE = 'P0001';
        END IF;
        NEW.submitted_at := NEW.created_at;
        IF NEW.precheckout_blite_deadline_seconds = 90 THEN
            IF NEW.deadline_at IS NOT NULL
               AND NEW.deadline_at IS DISTINCT FROM NEW.created_at + INTERVAL '90 seconds' THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'PRECHECKOUT_BLITE_CLOCK_ORIGIN_FORBIDDEN', ERRCODE = 'P0001';
            END IF;
            NEW.deadline_at := NEW.created_at + INTERVAL '90 seconds';
        ELSE
            IF NEW.deadline_at IS NOT NULL
               AND NEW.deadline_at IS DISTINCT FROM NEW.created_at + INTERVAL '60 seconds' THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'PRECHECKOUT_BLITE_CLOCK_ORIGIN_FORBIDDEN', ERRCODE = 'P0001';
            END IF;
            IF NEW.precheckout_blite_deadline_seconds <> 60 THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'PRECHECKOUT_BLITE_CLOCK_ORIGIN_FORBIDDEN', ERRCODE = 'P0001';
            END IF;
            NEW.deadline_at := NEW.created_at + INTERVAL '60 seconds';
        END IF;
    ELSIF NEW.submitted_at IS NOT NULL OR NEW.deadline_at IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_NON_COHORT_CLOCK_FORBIDDEN', ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: enforce_precheckout_blite_terminal_immutability_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_precheckout_blite_terminal_immutability_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF OLD.state IN ('complete', 'failed') AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_TERMINAL_IMMUTABLE', ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_user_phone_verification_provenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_user_phone_verification_provenance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_identity_changed BOOLEAN := FALSE;
    v_verification_changed BOOLEAN := FALSE;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        v_identity_changed := NEW.provider IS DISTINCT FROM OLD.provider
            OR NEW.phone_number IS DISTINCT FROM OLD.phone_number
            OR NEW.phone_number_normalized IS DISTINCT FROM OLD.phone_number_normalized
            OR NEW.phone_number_verification_source
                IS DISTINCT FROM OLD.phone_number_verification_source;
        v_verification_changed := NEW.phone_number_verified_at
            IS DISTINCT FROM OLD.phone_number_verified_at;

        -- A rolling old writer changes raw/profile phone fields without presenting
        -- a new verification timestamp. Degrade the row instead of retaining stale trust.
        IF v_identity_changed
           AND NEW.phone_number_verified_at
                IS NOT DISTINCT FROM OLD.phone_number_verified_at THEN
            NEW.phone_number_normalized := NULL;
            NEW.phone_number_verification_source := NULL;
            NEW.phone_number_verified_at := NULL;
            RETURN NEW;
        END IF;
    END IF;

    IF (
           TG_OP = 'INSERT'
           OR v_identity_changed
           OR v_verification_changed
       )
       AND NEW.provider = 'kakao'
       AND NEW.phone_number IS NOT NULL
       AND NEW.phone_number_normalized IS NOT NULL
       AND NEW.phone_number_verification_source = 'kakao_rest_api'
       AND NEW.phone_number_verified_at IS NOT NULL
       AND public.normalize_kr_mobile_e164(NEW.phone_number)
            IS NOT DISTINCT FROM NEW.phone_number_normalized THEN
        NEW.phone_number_verified_at := pg_catalog.clock_timestamp();
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: enqueue_analysis_order_audit_bundle(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_analysis_order_audit_bundle(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_latest public.analysis_order_audit_bundles%ROWTYPE;
    v_cost_hash VARCHAR(64);
    v_reopen BOOLEAN := FALSE;
BEGIN
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_ORDER_AUDIT_INVALID_REQUEST', ERRCODE = 'P0001';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.analysis_requests AS request
        WHERE request.id = p_request_id AND request.pipeline_version = 'v2'
    ) THEN
        RETURN NULL;
    END IF;

    v_cost_hash := public.analysis_order_audit_cost_source_hash(p_request_id);
    SELECT bundle.* INTO v_latest
    FROM public.analysis_order_audit_bundles AS bundle
    WHERE bundle.request_id = p_request_id
    ORDER BY bundle.version DESC
    LIMIT 1;
    v_reopen := v_latest.request_id IS NOT NULL
        AND v_latest.stage_status->>'costSourceHash' IS DISTINCT FROM v_cost_hash;

    INSERT INTO public.analysis_order_audit_assembly_queue (
        request_id, status, attempt_count, next_attempt_at, lease_token,
        lease_expires_at, last_error_code, last_error_at, updated_at
    ) VALUES (
        p_request_id, 'queued', 0, pg_catalog.clock_timestamp(), NULL,
        NULL, NULL, NULL, pg_catalog.clock_timestamp()
    )
    ON CONFLICT (request_id) DO UPDATE SET
        status = CASE
            WHEN public.analysis_order_audit_assembly_queue.status = 'completed'
                 AND NOT v_reopen THEN 'completed'
            WHEN public.analysis_order_audit_assembly_queue.status = 'processing'
                 AND public.analysis_order_audit_assembly_queue.lease_expires_at
                     > pg_catalog.clock_timestamp()
                 AND NOT v_reopen THEN 'processing'
            ELSE 'queued'
        END,
        next_attempt_at = CASE
            WHEN public.analysis_order_audit_assembly_queue.status = 'completed'
                 AND NOT v_reopen
                THEN public.analysis_order_audit_assembly_queue.next_attempt_at
            WHEN public.analysis_order_audit_assembly_queue.status = 'processing'
                 AND public.analysis_order_audit_assembly_queue.lease_expires_at
                     > pg_catalog.clock_timestamp()
                 AND NOT v_reopen
                THEN public.analysis_order_audit_assembly_queue.next_attempt_at
            ELSE pg_catalog.clock_timestamp()
        END,
        lease_token = CASE
            WHEN public.analysis_order_audit_assembly_queue.status = 'processing'
                 AND public.analysis_order_audit_assembly_queue.lease_expires_at
                     > pg_catalog.clock_timestamp()
                 AND NOT v_reopen
                THEN public.analysis_order_audit_assembly_queue.lease_token
            ELSE NULL
        END,
        lease_expires_at = CASE
            WHEN public.analysis_order_audit_assembly_queue.status = 'processing'
                 AND public.analysis_order_audit_assembly_queue.lease_expires_at
                     > pg_catalog.clock_timestamp()
                 AND NOT v_reopen
                THEN public.analysis_order_audit_assembly_queue.lease_expires_at
            ELSE NULL
        END,
        last_error_code = CASE
            WHEN public.analysis_order_audit_assembly_queue.status IN ('completed', 'processing')
                 AND NOT v_reopen
                THEN public.analysis_order_audit_assembly_queue.last_error_code
            ELSE NULL
        END,
        last_error_at = CASE
            WHEN public.analysis_order_audit_assembly_queue.status IN ('completed', 'processing')
                 AND NOT v_reopen
                THEN public.analysis_order_audit_assembly_queue.last_error_at
            ELSE NULL
        END,
        -- A late cost source changes the immutable version but must not erase a terminal purge
        -- fence; the retry assembler will purge only after the new finalized bundle is durable.
        purge_fenced_at = public.analysis_order_audit_assembly_queue.purge_fenced_at,
        purge_fence_reason = public.analysis_order_audit_assembly_queue.purge_fence_reason,
        purged_at = CASE WHEN v_reopen THEN NULL
            ELSE public.analysis_order_audit_assembly_queue.purged_at END,
        updated_at = pg_catalog.clock_timestamp();

    RETURN pg_catalog.jsonb_build_object(
        'status', 'queued',
        'requestId', p_request_id::TEXT,
        'costSourceHash', v_cost_hash
    );
END;
$$;


--
-- Name: enqueue_analysis_v2_result_image_purges_before_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_analysis_v2_result_image_purges_before_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    INSERT INTO public.analysis_v2_result_image_purge_outbox (
        object_key, request_id, kind, candidate_locator, reason
    )
    SELECT image_object.object_key, image_object.request_id,
        image_object.kind, image_object.candidate_locator, 'owner_delete'
    FROM public.analysis_v2_result_image_objects AS image_object
    WHERE image_object.request_id = OLD.id
      AND image_object.status = 'ready'
    ON CONFLICT (object_key) DO NOTHING;
    RETURN OLD;
END;
$$;


--
-- Name: enqueue_analysis_v2_score_audit_from_stage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_analysis_v2_score_audit_from_stage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '100ms'
    AS $$
BEGIN
    IF NEW.stage_kind = 'final_score' AND NEW.batch_key = -1 THEN
        BEGIN
            INSERT INTO public.analysis_v2_score_audit_intents (
                request_id, source_result_hash, source_generation,
                checkpoint_item_count
            ) VALUES (
                NEW.request_id, NEW.result_hash, 1, NEW.item_count
            )
            ON CONFLICT (request_id) DO UPDATE SET
                source_result_hash = EXCLUDED.source_result_hash,
                source_generation = CASE
                    WHEN analysis_v2_score_audit_intents.source_result_hash
                            IS DISTINCT FROM EXCLUDED.source_result_hash
                      OR analysis_v2_score_audit_intents.checkpoint_item_count
                            IS DISTINCT FROM EXCLUDED.checkpoint_item_count
                    THEN analysis_v2_score_audit_intents.source_generation + 1
                    ELSE analysis_v2_score_audit_intents.source_generation
                END,
                checkpoint_item_count = EXCLUDED.checkpoint_item_count,
                intent_status = 'queued',
                retain_until = CASE
                    WHEN analysis_v2_score_audit_intents.source_result_hash
                            IS DISTINCT FROM EXCLUDED.source_result_hash
                      OR analysis_v2_score_audit_intents.checkpoint_item_count
                            IS DISTINCT FROM EXCLUDED.checkpoint_item_count
                    THEN pg_catalog.clock_timestamp() + INTERVAL '30 minutes'
                    ELSE analysis_v2_score_audit_intents.retain_until
                END,
                updated_at = CASE
                    WHEN analysis_v2_score_audit_intents.source_result_hash
                            IS DISTINCT FROM EXCLUDED.source_result_hash
                      OR analysis_v2_score_audit_intents.checkpoint_item_count
                            IS DISTINCT FROM EXCLUDED.checkpoint_item_count
                    THEN pg_catalog.clock_timestamp()
                    ELSE analysis_v2_score_audit_intents.updated_at
                END;
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_earlybird_fulfillment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_earlybird_fulfillment(p_order_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_order public.earlybird_orders%ROWTYPE;
    v_status TEXT;
BEGIN
    IF p_order_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_ORDER_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    IF v_order.status = 'paid'
       AND v_order.seller_reference_confirmed_at IS NOT NULL
       AND v_order.payment_id IS NOT NULL
       AND v_order.actual_amount_krw IS NOT NULL
       AND v_order.actual_amount_krw BETWEEN 0 AND v_order.expected_amount_krw
       AND v_order.actual_groble_product_id
            IS NOT DISTINCT FROM v_order.expected_groble_product_id THEN
        INSERT INTO public.earlybird_fulfillments(
            order_id,
            status
        ) VALUES (
            v_order.id,
            'awaiting_operator'
        )
        ON CONFLICT (order_id) DO NOTHING;
    END IF;

    SELECT fulfillment.status INTO v_status
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id;
    RETURN v_status;
END;
$$;


--
-- Name: enqueue_earlybird_payment_discord_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_earlybird_payment_discord_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NEW.status = 'paid'
       AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'paid') THEN
        INSERT INTO public.earlybird_payment_discord_outbox (order_id)
        VALUES (NEW.id)
        ON CONFLICT (order_id) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_kakao_signup_discord_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_kakao_signup_discord_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NEW.raw_app_meta_data ->> 'provider' = 'kakao' THEN
        INSERT INTO public.kakao_signup_discord_outbox (user_id, signed_up_at)
        VALUES (NEW.id, NEW.created_at)
        ON CONFLICT (user_id) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_maintenance_job_v1(text, text, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_maintenance_job_v1(p_kind text, p_target_key_hash text, p_payload jsonb DEFAULT '{}'::jsonb, p_content_hash text DEFAULT NULL::text, p_requeue boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_existing public.maintenance_jobs%ROWTYPE;
BEGIN
    IF p_kind NOT IN (
           'recovery', 'replay', 'rearm', 'cleanup',
           'terminalize', 'purge', 'audit_assembly'
       )
       OR p_target_key_hash IS NULL OR p_target_key_hash !~ '^[a-f0-9]{64}$'
       OR p_payload IS NULL OR pg_catalog.jsonb_typeof(p_payload) <> 'object'
       OR p_content_hash IS NULL OR p_content_hash !~ '^[a-f0-9]{64}$'
       OR p_requeue IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'MAINTENANCE_JOB_INPUT_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT maintenance.*
    INTO v_existing
    FROM public.maintenance_jobs AS maintenance
    WHERE maintenance.kind = p_kind
      AND maintenance.target_key_hash = p_target_key_hash
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.content_hash = p_content_hash AND v_existing.payload = p_payload THEN
            IF p_requeue AND v_existing.state = 'blocked' THEN
                UPDATE public.maintenance_jobs
                SET state = 'queued',
                    attempt_count = 0,
                    next_attempt_at = pg_catalog.clock_timestamp(),
                    terminal_at = NULL,
                    last_error_code = NULL,
                    lease_token = NULL,
                    lease_holder_hash = NULL,
                    lease_expires_at = NULL,
                    updated_at = pg_catalog.clock_timestamp()
                WHERE id = v_existing.id;
                RETURN pg_catalog.jsonb_build_object('status', 'queued', 'duplicate', TRUE);
            END IF;
            RETURN pg_catalog.jsonb_build_object('status', v_existing.state, 'duplicate', TRUE);
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'MAINTENANCE_CONTENT_CONFLICT', ERRCODE = 'P0001';
    END IF;
    INSERT INTO public.maintenance_jobs(kind, target_key_hash, state, payload, content_hash)
    VALUES (p_kind, p_target_key_hash, 'queued', p_payload, p_content_hash)
    ON CONFLICT DO NOTHING;
    IF FOUND THEN
        RETURN pg_catalog.jsonb_build_object('status', 'queued', 'duplicate', FALSE);
    END IF;
    SELECT maintenance.*
    INTO v_existing
    FROM public.maintenance_jobs AS maintenance
    WHERE maintenance.kind = p_kind
      AND maintenance.target_key_hash = p_target_key_hash;
    IF FOUND AND v_existing.content_hash = p_content_hash AND v_existing.payload = p_payload THEN
        IF p_requeue AND v_existing.state = 'blocked' THEN
            UPDATE public.maintenance_jobs
            SET state = 'queued',
                attempt_count = 0,
                next_attempt_at = pg_catalog.clock_timestamp(),
                terminal_at = NULL,
                last_error_code = NULL,
                lease_token = NULL,
                lease_holder_hash = NULL,
                lease_expires_at = NULL,
                updated_at = pg_catalog.clock_timestamp()
            WHERE id = v_existing.id;
            RETURN pg_catalog.jsonb_build_object('status', 'queued', 'duplicate', TRUE);
        END IF;
        RETURN pg_catalog.jsonb_build_object('status', v_existing.state, 'duplicate', TRUE);
    END IF;
    RAISE EXCEPTION USING MESSAGE = 'MAINTENANCE_CONTENT_CONFLICT', ERRCODE = 'P0001';
END;
$_$;


