--
-- Name: enqueue_sentry_discord_alert_outbox(character, text, timestamp with time zone, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_sentry_discord_alert_outbox(p_dedupe_key character, p_project_slug text, p_occurred_at timestamp with time zone, p_issue_url text, p_issue_short_id text, p_error_type text, p_release text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
BEGIN
    INSERT INTO public.sentry_discord_alert_outbox (
        dedupe_key, project_slug, occurred_at, issue_url, issue_short_id, error_type, release
    ) VALUES (
        lower(p_dedupe_key),
        CASE WHEN p_project_slug ~ '^[A-Za-z0-9][A-Za-z0-9-]{0,99}$' THEN p_project_slug ELSE NULL END,
        p_occurred_at, p_issue_url,
        CASE WHEN p_issue_short_id ~ '^[A-Z][A-Z0-9_-]{0,49}-[0-9]{1,12}$' THEN p_issue_short_id ELSE NULL END,
        CASE WHEN length(p_error_type) <= 120 AND p_error_type ~ '^[A-Za-z_$][A-Za-z0-9_$.]*(::[A-Za-z_$][A-Za-z0-9_$.]*)*$' THEN p_error_type ELSE NULL END,
        CASE WHEN length(p_release) <= 80 AND p_release ~ '^[0-9A-Za-z][0-9A-Za-z._+-]*$' AND p_release !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN p_release ELSE NULL END
    ) ON CONFLICT (dedupe_key) DO NOTHING;
    RETURN FOUND;
END;
$_$;


--
-- Name: enroll_analysis_beta_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enroll_analysis_beta_user(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE
    v_gate_enabled BOOLEAN; v_policy_mode TEXT; v_now TIMESTAMP WITH TIME ZONE;
    v_grant public.analysis_beta_access_grants%ROWTYPE;
BEGIN
    IF p_user_id IS NULL THEN RETURN FALSE; END IF;
    SELECT gate_row.enabled INTO v_gate_enabled FROM public.analysis_beta_runtime_gate AS gate_row
    WHERE gate_row.singleton=TRUE FOR SHARE;
    SELECT policy_row.mode INTO v_policy_mode FROM public.analysis_beta_access_policy AS policy_row
    WHERE policy_row.singleton=TRUE FOR SHARE;
    IF v_gate_enabled IS DISTINCT FROM TRUE THEN RETURN FALSE; END IF;
    IF v_policy_mode='grant_only' THEN
        RETURN EXISTS(SELECT 1 FROM public.analysis_beta_access_grants AS grant_row
            WHERE grant_row.user_id=p_user_id AND grant_row.grant_source='operator'
              AND grant_row.enabled=TRUE
              AND (grant_row.expires_at IS NULL OR grant_row.expires_at>pg_catalog.clock_timestamp()));
    END IF;
    IF v_policy_mode IS DISTINCT FROM 'all_authenticated' THEN RETURN FALSE; END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analysis-beta-grant:' || pg_catalog.lower(p_user_id::TEXT),0));
    PERFORM users.id FROM public.users AS users WHERE users.id=p_user_id FOR KEY SHARE;
    IF NOT FOUND THEN RETURN FALSE; END IF;
    SELECT grant_row.* INTO v_grant FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id=p_user_id FOR UPDATE;
    v_now:=pg_catalog.clock_timestamp();
    IF NOT FOUND THEN
        INSERT INTO public.analysis_beta_access_grants(
            user_id,enabled,expires_at,audit_reference_hash,grant_source,granted_at,updated_at
        ) VALUES (p_user_id,TRUE,NULL,pg_catalog.encode(extensions.digest(
            'automatic-betatest-enrollment-v1:' || p_user_id::TEXT,'sha256'),'hex'),
            'automatic',v_now,v_now);
        RETURN TRUE;
    END IF;
    IF v_grant.grant_source='automatic' AND v_grant.enabled=TRUE AND v_grant.expires_at IS NULL THEN
        RETURN TRUE;
    END IF;
    IF v_grant.enabled IS DISTINCT FROM TRUE
       OR (v_grant.expires_at IS NOT NULL AND v_grant.expires_at<=v_now) THEN
        UPDATE public.analysis_beta_access_grants AS grant_row SET
            enabled=TRUE, expires_at=NULL, grant_source='automatic',
            audit_reference_hash=pg_catalog.encode(extensions.digest(
                'automatic-betatest-enrollment-v1:' || p_user_id::TEXT,'sha256'),'hex'),
            updated_at=v_now
        WHERE grant_row.user_id=p_user_id;
        RETURN TRUE;
    END IF;
    IF v_grant.grant_source='automatic' THEN
        UPDATE public.analysis_beta_access_grants AS grant_row SET
            enabled=TRUE, expires_at=NULL,
            audit_reference_hash=pg_catalog.encode(extensions.digest(
                'automatic-betatest-enrollment-v1:' || p_user_id::TEXT,'sha256'),'hex'),
            updated_at=v_now
        WHERE grant_row.user_id=p_user_id;
    END IF;
    RETURN TRUE;
END; $$;


--
-- Name: ensure_account_principal_v1(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_account_principal_v1(p_user_id uuid, p_email text, p_provider text, p_profile jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(id uuid, email character varying, provider character varying, analysis_count integer, is_paid_user boolean, is_unlimited boolean, created_at timestamp with time zone, updated_at timestamp with time zone, name character varying, nickname character varying, profile_image text, gender character varying, birthyear character varying, account_class text, traffic_class text, lifecycle text, first_paid_at timestamp with time zone, has_active_purchase boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_existing public.users%ROWTYPE;
BEGIN
    IF p_user_id IS NULL
       OR p_email IS NULL
       OR pg_catalog.btrim(p_email) = ''
       OR pg_catalog.char_length(p_email) > 255
       OR p_provider IS NULL
       OR p_provider NOT IN ('google', 'kakao')
       OR NOT public.account_profile_patch_valid(p_profile, FALSE) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_PRINCIPAL_INPUT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT account.*
    INTO v_existing
    FROM public.users AS account
    WHERE account.id = p_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        INSERT INTO public.users (
            id, email, provider, analysis_count, is_paid_user, is_unlimited,
            name, nickname, profile_image, gender, birthyear,
            account_class, traffic_class, lifecycle, classification_version
        ) VALUES (
            p_user_id,
            pg_catalog.btrim(p_email),
            p_provider,
            0,
            FALSE,
            FALSE,
            NULLIF(p_profile ->> 'name', ''),
            NULLIF(p_profile ->> 'nickname', ''),
            NULLIF(p_profile ->> 'profile_image', ''),
            NULLIF(p_profile ->> 'gender', ''),
            NULLIF(p_profile ->> 'birthyear', ''),
            'production',
            'external',
            'active',
            'runtime_default_v1'
        );
    ELSE
        IF v_existing.lifecycle <> 'active' THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ACCOUNT_RETIRED',
                ERRCODE = 'P0001';
        END IF;
        UPDATE public.users AS account
        SET name = COALESCE(
                account.name, NULLIF(p_profile ->> 'name', '')
            ),
            nickname = COALESCE(
                account.nickname, NULLIF(p_profile ->> 'nickname', '')
            ),
            profile_image = COALESCE(
                account.profile_image,
                NULLIF(p_profile ->> 'profile_image', '')
            ),
            gender = COALESCE(
                account.gender, NULLIF(p_profile ->> 'gender', '')
            ),
            birthyear = COALESCE(
                account.birthyear, NULLIF(p_profile ->> 'birthyear', '')
            )
        WHERE account.id = p_user_id;
    END IF;

    RETURN QUERY
    SELECT principal.*
    FROM public.load_account_principal_v1(p_user_id) AS principal;
END;
$$;


--
-- Name: fail_analysis_request_and_purge_staging(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_analysis_request_and_purge_staging(p_request_id uuid, p_user_id uuid, p_expected_step text, p_error_message text, p_step_data jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    affected_rows INTEGER;
BEGIN
    IF p_expected_step IS NULL
       OR pg_catalog.char_length(p_expected_step) NOT BETWEEN 1 AND 50 THEN
        RAISE EXCEPTION 'invalid expected analysis step';
    END IF;
    IF p_error_message IS NULL
       OR pg_catalog.char_length(p_error_message) NOT BETWEEN 1 AND 1000 THEN
        RAISE EXCEPTION 'invalid analysis failure message';
    END IF;
    IF p_step_data IS NULL OR pg_catalog.jsonb_typeof(p_step_data) <> 'object' THEN
        RAISE EXCEPTION 'invalid compact analysis step data';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_object_keys(p_step_data) AS keys(key_name)
        WHERE keys.key_name NOT IN ('mutualFollows', 'targetProfileImage')
    ) THEN
        RAISE EXCEPTION 'compact analysis step data contains unsupported keys';
    END IF;
    IF p_step_data ? 'mutualFollows'
       AND pg_catalog.jsonb_typeof(p_step_data->'mutualFollows') <> 'array' THEN
        RAISE EXCEPTION 'invalid compact mutual follows';
    END IF;
    IF p_step_data ? 'mutualFollows'
       AND pg_catalog.jsonb_array_length(p_step_data->'mutualFollows') > 10 THEN
        RAISE EXCEPTION 'too many compact mutual follows';
    END IF;
    IF p_step_data ? 'mutualFollows'
       AND EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_array_elements(
               p_step_data->'mutualFollows'
           ) AS mutual(username)
           WHERE pg_catalog.jsonb_typeof(mutual.username) <> 'string'
              OR pg_catalog.char_length(mutual.username #>> '{}') > 30
              OR (mutual.username #>> '{}') !~ '^[a-z0-9._]{1,30}$'
       ) THEN
        RAISE EXCEPTION 'invalid compact mutual follow username';
    END IF;
    IF p_step_data ? 'targetProfileImage'
       AND pg_catalog.jsonb_typeof(p_step_data->'targetProfileImage') <> 'string' THEN
        RAISE EXCEPTION 'invalid compact target profile image';
    END IF;
    IF p_step_data ? 'targetProfileImage'
       AND pg_catalog.char_length(p_step_data->>'targetProfileImage') > 8192 THEN
        RAISE EXCEPTION 'compact target profile image is too long';
    END IF;

    UPDATE public.analysis_requests AS analysis_request
    SET status = 'failed',
        current_step = 'failed',
        progress_step = '분석 처리 중 오류가 발생했습니다.',
        error_message = p_error_message,
        background_processing = FALSE,
        step_data = p_step_data,
        processing_lease_token = NULL,
        processing_lease_expires_at = NULL
    WHERE analysis_request.id = p_request_id
      AND analysis_request.user_id = p_user_id
      AND analysis_request.pipeline_version IS DISTINCT FROM 'v2'
      AND analysis_request.status IN ('pending', 'processing')
      AND COALESCE(analysis_request.current_step, 'pending') = p_expected_step;

    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    IF affected_rows <> 1 THEN
        RETURN FALSE;
    END IF;

    DELETE FROM public.analysis_interaction_jobs WHERE request_id = p_request_id;
    DELETE FROM public.analysis_interaction_evidence WHERE request_id = p_request_id;
    DELETE FROM public.analysis_interaction_scores WHERE request_id = p_request_id;
    DELETE FROM public.analysis_results WHERE request_id = p_request_id;
    DELETE FROM public.private_accounts WHERE request_id = p_request_id;
    RETURN TRUE;
END;
$_$;


--
-- Name: fail_analysis_v2_request_from_job(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_analysis_v2_request_from_job(p_request_id uuid, p_job_key text, p_error_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_intent public.analysis_v2_provider_cleanup_intents%ROWTYPE;
    v_progress public.analysis_progress_state%ROWTYPE;
    v_tracks JSONB;
    v_fingerprint TEXT;
BEGIN
    IF p_request_id IS NULL OR p_job_key IS NULL
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_error_code IS NULL
       OR p_error_code !~ '^[A-Z][A-Z0-9_]{0,63}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_INVALID_JOB_FAILURE_INPUT', ERRCODE = 'P0001';
    END IF;

    PERFORM 1 FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_NOT_READY', ERRCODE = 'P0001';
    END IF;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    SELECT intent.* INTO v_intent
    FROM public.analysis_v2_provider_cleanup_intents AS intent
    WHERE intent.request_id = p_request_id
    FOR UPDATE;

    v_now := pg_catalog.clock_timestamp();
    IF v_request.id IS NULL OR v_request.status NOT IN ('pending', 'processing')
       OR v_job.request_id IS NULL OR v_job.status <> 'processing'
       OR v_job.lease_token IS NULL OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now
       OR v_intent.request_id IS NULL
       OR v_intent.failed_job_key IS DISTINCT FROM p_job_key
       OR v_intent.failed_job_input_hash IS DISTINCT FROM v_job.input_hash
       OR v_intent.failed_claim_token IS DISTINCT FROM v_job.lease_token
       OR v_intent.error_code IS DISTINCT FROM p_error_code
       OR v_intent.completed_at IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_NOT_READY', ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = p_request_id
          AND (
              provider_run.status = 'running'
              OR (
                  provider_run.status = 'starting'
                  AND NOT EXISTS (
                      SELECT 1
                      FROM public.analysis_v2_unconfirmed_start_resolutions AS resolution
                      WHERE resolution.reservation_token = provider_run.reservation_token
                  )
              )
          )
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_REQUIRED', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_pipeline_jobs AS job
    SET status = 'failed', lease_token = NULL, lease_expires_at = NULL,
        last_error_code = p_error_code, last_error_at = v_now,
        completed_at = v_now, updated_at = v_now
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
      AND job.status = 'processing';
    UPDATE public.analysis_pipeline_jobs AS job
    SET status = 'cancelled', lease_token = NULL, lease_expires_at = NULL,
        last_error_code = COALESCE(job.last_error_code, 'REQUEST_TERMINATED'),
        last_error_at = COALESCE(job.last_error_at, v_now),
        completed_at = v_now, updated_at = v_now
    WHERE job.request_id = p_request_id AND job.job_key <> p_job_key
      AND job.status IN ('pending', 'processing');

    SELECT progress_state.* INTO v_progress
    FROM public.analysis_progress_state AS progress_state
    WHERE progress_state.request_id = p_request_id FOR UPDATE;
    IF v_progress.request_id IS NOT NULL
       AND v_progress.status IN ('queued', 'processing') THEN
        v_tracks := pg_catalog.jsonb_build_object(
            'relationshipAi', pg_catalog.jsonb_set(
                v_progress.tracks->'relationshipAi', ARRAY['state'],
                pg_catalog.to_jsonb(CASE
                    WHEN v_progress.tracks->'relationshipAi'->>'state' = 'completed'
                        THEN 'completed' ELSE 'failed' END::TEXT)
            ),
            'interactions', pg_catalog.jsonb_set(
                v_progress.tracks->'interactions', ARRAY['state'],
                pg_catalog.to_jsonb(CASE
                    WHEN v_progress.tracks->'interactions'->>'state' = 'completed'
                        THEN 'completed' ELSE 'failed' END::TEXT)
            ),
            'finalization', pg_catalog.jsonb_set(
                v_progress.tracks->'finalization', ARRAY['state'],
                pg_catalog.to_jsonb(CASE
                    WHEN v_progress.tracks->'finalization'->>'state' = 'completed'
                        THEN 'completed' ELSE 'failed' END::TEXT)
            )
        );
        v_fingerprint := public.analysis_v2_dag_hash_json(
            pg_catalog.jsonb_build_object(
                'domain', 'analysis-v2-progress-snapshot-v1',
                'requestId', p_request_id, 'status', 'failed',
                'progressBp', v_progress.progress_bp,
                'backgroundProcessing', FALSE,
                'tracks', v_tracks, 'activeProfile', NULL,
                'etaRange', NULL, 'errorCode', p_error_code
            )
        );
        UPDATE public.analysis_progress_state AS progress_state
        SET revision = progress_state.revision + 1,
            status = 'failed', background_processing = FALSE,
            tracks = v_tracks, active_profile = NULL, eta_range = NULL,
            snapshot_fingerprint = v_fingerprint, updated_at = v_now
        WHERE progress_state.request_id = p_request_id;
    END IF;

    UPDATE public.analysis_requests AS analysis_request
    SET status = 'failed', background_processing = FALSE,
        progress_step = 'V2 analysis failed', current_step = 'failed',
        error_message = p_error_code,
        completed_at = COALESCE(analysis_request.completed_at, v_now)
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
      AND analysis_request.status IN ('pending', 'processing');

    PERFORM public.analysis_v2_purge_result_working_set(p_request_id, FALSE);
    PERFORM public.analysis_v2_scrub_terminal_request_pii(p_request_id, v_now);
END;
$_$;


--
-- Name: fail_analysis_v2_result_and_purge(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_analysis_v2_result_and_purge(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_intent public.analysis_v2_provider_cleanup_intents%ROWTYPE;
    v_result JSONB;
BEGIN
    -- Freeze new starts with the same canonical lock order before checking cleanup.
    PERFORM 1 FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id FOR UPDATE;
    PERFORM 1 FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id FOR UPDATE;
    PERFORM 1 FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    SELECT intent.* INTO v_intent
    FROM public.analysis_v2_provider_cleanup_intents AS intent
    WHERE intent.request_id = p_request_id FOR UPDATE;
    IF v_intent.request_id IS NULL
       OR v_intent.failed_job_key IS DISTINCT FROM p_job_key
       OR v_intent.failed_job_input_hash IS DISTINCT FROM p_job_input_hash
       OR v_intent.failed_claim_token IS DISTINCT FROM p_claim_token
       OR v_intent.error_code IS DISTINCT FROM p_error_code
       OR v_intent.completed_at IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_NOT_READY', ERRCODE = 'P0001';
    END IF;
    IF EXISTS (
        SELECT 1 FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = p_request_id
          AND (
            provider_run.status = 'running'
            OR (
                provider_run.status = 'starting'
                AND NOT EXISTS (
                    SELECT 1
                    FROM public.analysis_v2_unconfirmed_start_resolutions AS resolution
                    WHERE resolution.reservation_token = provider_run.reservation_token
                )
            )
          )
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_REQUIRED', ERRCODE = 'P0001';
    END IF;

    v_result := public.analysis_v2_fail_result_and_purge_internal(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash, p_error_code
    );
    UPDATE public.analysis_v2_provider_cleanup_intents AS intent
    SET completed_at = pg_catalog.clock_timestamp()
    WHERE intent.request_id = p_request_id;
    RETURN v_result;
END;
$$;


--
-- Name: fail_precheckout_blite_v2(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_precheckout_blite_v2(p_preflight_id uuid, p_lease_token uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_cache public.precheckout_blite_cache%ROWTYPE;
    v_source public.precheckout_blite_sources%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_lease_token IS NULL
       OR p_reason IS NULL
       OR p_reason NOT IN ('source_missing', 'source_expired', 'source_invalid', 'source_insufficient', 'dispatch_failed', 'inference_timeout', 'inference_rate_limited', 'inference_provider_failed', 'inference_response_invalid', 'persistence_failed', 'attempts_exhausted') THEN
        RETURN FALSE;
    END IF;

    -- Failure remains available after the deadline to clean up a valid current lease.
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND
       OR NOT v_preflight.precheckout_blite_cohort
       OR v_preflight.pii_scrubbed_at IS NOT NULL THEN
        RETURN FALSE;
    END IF;

    SELECT cache.* INTO v_cache
    FROM public.precheckout_blite_cache AS cache
    WHERE cache.preflight_id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND
       OR v_cache.state <> 'pending'
       OR v_cache.lease_token IS DISTINCT FROM p_lease_token
       OR v_cache.lease_expires_at <= v_now THEN
        RETURN FALSE;
    END IF;

    SELECT source.* INTO v_source
    FROM public.precheckout_blite_sources AS source
    WHERE source.preflight_id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();

    UPDATE public.precheckout_blite_cache
    SET state = 'failed', failure_reason = p_reason, failed_at = v_now,
        updated_at = v_now
    WHERE preflight_id = p_preflight_id
      AND state = 'pending'
      AND lease_token = p_lease_token
      AND lease_expires_at > v_now;
    IF NOT FOUND THEN RETURN FALSE; END IF;

    DELETE FROM public.precheckout_blite_sources
    WHERE preflight_id = p_preflight_id;
    RETURN TRUE;
END;
$$;


--
-- Name: fence_landing_leads_on_account_retirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_landing_leads_on_account_retirement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.lifecycle = 'retired' AND OLD.lifecycle IS DISTINCT FROM NEW.lifecycle THEN
        PERFORM public.unlink_landing_lead_journey_after_deletion(NEW.id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: finalize_account_deletion_database_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_account_deletion_database_v1(p_account_id uuid, p_deleted_object_keys jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_job public.account_deletion_jobs%ROWTYPE;
    v_expected_keys JSONB;
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    SELECT * INTO v_job
    FROM public.account_deletion_jobs AS job
    WHERE job.account_id = p_account_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ACCOUNT_DELETION_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_job.state IN ('database_purged', 'completed') THEN
        RETURN pg_catalog.jsonb_build_object('state', v_job.state);
    END IF;
    IF pg_catalog.jsonb_typeof(p_deleted_object_keys) <> 'array' THEN
        RAISE EXCEPTION USING MESSAGE = 'ACCOUNT_DELETION_OBJECT_PROOF_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(pg_catalog.jsonb_agg(image_object.object_key ORDER BY image_object.object_key), '[]'::JSONB)
    INTO v_expected_keys
    FROM public.analysis_v2_result_image_objects AS image_object
    JOIN public.analysis_requests AS request ON request.id = image_object.request_id
    WHERE request.user_id = p_account_id AND image_object.object_key IS NOT NULL;
    IF v_expected_keys <> p_deleted_object_keys THEN
        RAISE EXCEPTION USING MESSAGE = 'ACCOUNT_DELETION_OBJECT_PROOF_MISMATCH', ERRCODE = 'P0001';
    END IF;

    UPDATE public.account_deletion_jobs SET state = 'objects_purged', objects_purged_at = v_now, updated_at = v_now
    WHERE account_id = p_account_id AND state = 'requested';

    DELETE FROM public.analysis_result_share_observations AS observation
    USING public.analysis_requests AS request
    WHERE observation.request_id = request.id AND request.user_id = p_account_id;
    DELETE FROM public.analysis_results AS result
    USING public.analysis_requests AS request
    WHERE result.request_id = request.id AND request.user_id = p_account_id;
    DELETE FROM public.private_accounts AS private_account
    USING public.analysis_requests AS request
    WHERE private_account.request_id = request.id AND request.user_id = p_account_id;
    DELETE FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
    USING public.analysis_requests AS request
    WHERE checkpoint.request_id = request.id AND request.user_id = p_account_id;
    DELETE FROM public.analysis_v2_private_name_manifests AS manifest
    USING public.analysis_requests AS request
    WHERE manifest.request_id = request.id AND request.user_id = p_account_id;
    DELETE FROM public.analysis_v2_narrative_manifests AS manifest
    USING public.analysis_requests AS request
    WHERE manifest.request_id = request.id AND request.user_id = p_account_id;
    DELETE FROM public.analysis_v2_score_audit_intents AS audit
    USING public.analysis_requests AS request
    WHERE audit.request_id = request.id AND request.user_id = p_account_id;
    DELETE FROM public.analysis_v2_score_audit_sources AS audit
    USING public.analysis_requests AS request
    WHERE audit.request_id = request.id AND request.user_id = p_account_id;
    DELETE FROM public.analysis_v2_score_audit_scan_locators AS audit
    USING public.analysis_requests AS request
    WHERE audit.request_id = request.id AND request.user_id = p_account_id;
    DELETE FROM public.analysis_v2_result_coverage_telemetry AS telemetry
    USING public.analysis_requests AS request
    WHERE telemetry.request_id = request.id AND request.user_id = p_account_id;
    DELETE FROM public.analysis_v2_result_summaries AS summary
    USING public.analysis_requests AS request
    WHERE summary.request_id = request.id AND request.user_id = p_account_id;
    DELETE FROM public.analysis_v2_result_image_objects AS image_object
    USING public.analysis_requests AS request
    WHERE image_object.request_id = request.id AND request.user_id = p_account_id;
    DELETE FROM public.analysis_v2_result_image_manifests AS manifest
    USING public.analysis_requests AS request
    WHERE manifest.request_id = request.id AND request.user_id = p_account_id;

    UPDATE public.analysis_requests AS request
    SET target_instagram_id = 'deleted', share_enabled = FALSE, share_token = NULL,
        step_data = '{}'::JSONB, gender_stats = '{}'::JSONB,
        error_message = NULL, progress_step = NULL
    WHERE request.user_id = p_account_id;

    UPDATE public.analysis_preflights AS preflight
    SET target_instagram_id = 'deleted', target_full_name = NULL, target_bio = NULL,
        target_profile_image_url = NULL, excluded_instagram_id = NULL,
        exclusion_decision = 'skip', pii_scrubbed_at = COALESCE(preflight.pii_scrubbed_at, v_now)
    WHERE preflight.user_id = p_account_id;

    UPDATE public.earlybird_orders AS earlybird_order
    SET target_instagram_id = 'deleted', target_followers_count = 0, target_following_count = 0,
        exclusion_decision = 'skip', excluded_instagram_id = NULL,
        expected_buyer_phone_number_normalized = NULL,
        expected_buyer_phone_verification_source = NULL,
        expected_buyer_phone_verified_at = NULL,
        buyer_match_policy = 'legacy_email', groble_buyer_email = NULL,
        groble_buyer_phone_number = NULL, groble_buyer_display_name = NULL,
        disclosure_text = 'retained_order_ledger', result_request_id = NULL,
        updated_at = v_now
    WHERE earlybird_order.user_id = p_account_id;

    DELETE FROM public.earlybird_waitlist AS waitlist WHERE waitlist.user_id = p_account_id;

    UPDATE public.users AS account
    SET email = 'retired+' || pg_catalog.replace(account.id::TEXT, '-', '') || '@deleted.invalid',
        provider = 'retired', analysis_count = 0, name = NULL, nickname = NULL,
        profile_image = NULL, phone_number = NULL, phone_number_normalized = NULL,
        phone_number_verification_source = NULL, phone_number_verified_at = NULL,
        gender = NULL, birthyear = NULL, updated_at = v_now
    WHERE account.id = p_account_id AND account.lifecycle = 'retired';

    UPDATE public.account_deletion_jobs
    SET state = 'database_purged', objects_purged_at = COALESCE(objects_purged_at, v_now),
        database_purged_at = v_now, updated_at = v_now
    WHERE account_id = p_account_id;
    RETURN pg_catalog.jsonb_build_object('state', 'database_purged');
END;
$$;


--
-- Name: finalize_analysis_provider_cost(text, text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_analysis_provider_cost(p_run_id text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_status text, p_usage_total_usd numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    existing public.analysis_provider_cost_ledger%ROWTYPE;
BEGIN
    IF p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_logical_provider NOT IN ('apify', 'coderx')
       OR p_actor_id IS NULL
       OR p_actor_id !~ '^[A-Za-z0-9][A-Za-z0-9._~/-]{2,199}$'
       OR p_credential_slot NOT IN ('primary', 'secondary')
       OR p_status NOT IN ('succeeded', 'failed', 'aborted', 'timed_out')
       OR p_usage_total_usd IS NULL
       OR p_usage_total_usd::TEXT IN ('NaN', 'Infinity', '-Infinity')
       OR p_usage_total_usd < 0
       OR p_usage_total_usd > 100000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PROVIDER_COST_FINALIZE_INVALID',
            ERRCODE = '22023';
    END IF;

    SELECT *
    INTO existing
    FROM public.analysis_provider_cost_ledger
    WHERE run_id = p_run_id
    FOR UPDATE;

    IF NOT FOUND
       OR existing.logical_provider <> p_logical_provider
       OR existing.actor_id <> p_actor_id
       OR existing.credential_slot <> p_credential_slot
       OR existing.status <> p_status THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PROVIDER_COST_FINALIZE_CONFLICT',
            ERRCODE = '23505';
    END IF;

    IF p_usage_total_usd > existing.max_charge_usd + 0.000000001 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PROVIDER_COST_FINALIZE_OVER_CAP',
            ERRCODE = '22023';
    END IF;

    IF existing.cost_finalized_at IS NOT NULL THEN
        IF existing.usage_total_usd IS DISTINCT FROM p_usage_total_usd THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_COST_FINALIZE_MISMATCH',
                ERRCODE = '23505';
        END IF;
        RETURN TRUE;
    END IF;

    UPDATE public.analysis_provider_cost_ledger
    SET usage_total_usd = p_usage_total_usd,
        cost_finalized_at = clock_timestamp(),
        updated_at = clock_timestamp()
    WHERE run_id = p_run_id;
    RETURN TRUE;
END;
$_$;


--
-- Name: finalize_analysis_v2_request(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_analysis_v2_request(p_request_id uuid, p_job_key text, p_claim_token uuid, p_terminal_status text, p_error_code text DEFAULT NULL::text) RETURNS TABLE(finalized boolean, request_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_claim_token IS NULL
       OR p_terminal_status IS NULL
       OR p_terminal_status NOT IN ('completed', 'failed')
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR (
            p_terminal_status = 'completed'
            AND p_error_code IS NOT NULL
       )
       OR (
            p_terminal_status = 'failed'
            AND (
                p_error_code IS NULL
                OR p_error_code !~ '^[A-Z][A-Z0-9_]{0,63}$'
            )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_FINALIZE_INPUT', ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    IF p_terminal_status = 'completed'
       AND (
            p_job_key <> 'coordinator:finalize'
            OR v_job.track <> 'coordinator'
            OR v_job.kind <> 'finalizer'
            OR pg_catalog.cardinality(v_job.required_job_keys) < 1
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_FINALIZER', ERRCODE = 'P0001';
    END IF;

    IF v_request.status IN ('completed', 'failed') THEN
        IF v_request.status = p_terminal_status THEN
            RETURN QUERY SELECT FALSE, v_request.status::TEXT;
            RETURN;
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_FINALIZE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    IF v_job.status <> 'processing'
       OR v_job.lease_token <> p_claim_token
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    IF p_terminal_status = 'completed' AND (
        EXISTS (
            SELECT 1
            FROM pg_catalog.unnest(v_job.required_job_keys) AS required_key(value)
            LEFT JOIN public.analysis_pipeline_jobs AS required_job
              ON required_job.request_id = p_request_id
             AND required_job.job_key = required_key.value
            WHERE required_job.request_id IS NULL
               OR required_job.status <> 'completed'
        )
        OR EXISTS (
            SELECT 1
            FROM public.analysis_pipeline_jobs AS sibling
            WHERE sibling.request_id = p_request_id
              AND sibling.job_key <> p_job_key
              AND sibling.status IN ('pending', 'processing')
        )
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_FINALIZE_NOT_READY', ERRCODE = 'P0001';
    END IF;

    IF p_terminal_status = 'failed' THEN
        PERFORM public.fail_analysis_v2_request_from_job(
            p_request_id,
            p_job_key,
            p_error_code
        );
    ELSE
        UPDATE public.analysis_pipeline_jobs AS job
        SET status = 'completed',
            lease_token = NULL,
            lease_expires_at = NULL,
            completion_token = p_claim_token,
            completion_fanout_hash = pg_catalog.md5('[]'),
            completed_at = v_now,
            updated_at = v_now
        WHERE job.request_id = p_request_id
          AND job.job_key = p_job_key;

        UPDATE public.analysis_requests AS analysis_request
        SET status = 'completed',
            progress = 100,
            background_processing = FALSE,
            progress_step = 'V2 analysis completed',
            current_step = 'completed',
            error_message = NULL,
            completed_at = v_now
        WHERE analysis_request.id = p_request_id
          AND analysis_request.status IN ('pending', 'processing');

        UPDATE public.analysis_preflights AS preflight
        SET target_instagram_id = 'retained.'
                || pg_catalog.substr(pg_catalog.replace(preflight.id::TEXT, '-', ''), 1, 20),
            target_full_name = NULL,
            target_bio = NULL,
            target_profile_image_url = NULL,
            exclusion_decision = 'skip',
            excluded_instagram_id = NULL,
            pii_scrubbed_at = COALESCE(preflight.pii_scrubbed_at, v_now),
            updated_at = v_now
        WHERE preflight.consumed_request_id = p_request_id
          AND preflight.status = 'consumed';
    END IF;

    RETURN QUERY SELECT TRUE, p_terminal_status;
END;
$_$;


--
-- Name: finalize_earlybird_groble_cancel_request(text, text, text, timestamp with time zone, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_earlybird_groble_cancel_request(p_event_id text, p_idempotency_key text, p_event_type text, p_occurred_at timestamp with time zone, p_payment_id text, p_product_id text, p_amount_krw integer, p_requested_at timestamp with time zone) RETURNS TABLE(disposition text, order_id uuid, status text, plan_sequence smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_event public.earlybird_webhook_events%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
BEGIN
    IF p_event_type <> 'payment.cancel_requested'
       OR p_event_id IS NULL OR pg_catalog.char_length(p_event_id) NOT BETWEEN 1 AND 256
       OR p_idempotency_key IS NULL
          OR pg_catalog.char_length(p_idempotency_key) NOT BETWEEN 1 AND 256
       OR p_payment_id IS NULL OR pg_catalog.char_length(p_payment_id) NOT BETWEEN 1 AND 256
       OR p_product_id IS NULL OR p_product_id !~ '^[A-Za-z0-9_-]{1,128}$'
       OR p_amount_krw IS NULL OR p_amount_krw < 0
       OR p_occurred_at IS NULL OR p_requested_at IS NULL THEN
        RAISE EXCEPTION 'GROBLE_CANCEL_EVIDENCE_INVALID';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_payment_id, 0)
    );

    SELECT webhook_event.*
    INTO v_event
    FROM public.earlybird_webhook_events AS webhook_event
    WHERE webhook_event.event_id = p_event_id
       OR webhook_event.idempotency_key = p_idempotency_key
    ORDER BY webhook_event.processed_at
    LIMIT 1;
    IF FOUND THEN
        IF v_event.order_id IS NOT NULL THEN
            SELECT existing_order.*
            INTO v_order
            FROM public.earlybird_orders AS existing_order
            WHERE existing_order.id = v_event.order_id;
        END IF;
        RETURN QUERY SELECT
            'cancel_duplicate_event'::TEXT,
            v_order.id,
            v_order.status,
            v_order.plan_sequence;
        RETURN;
    END IF;

    SELECT paid_order.*
    INTO v_order
    FROM public.earlybird_orders AS paid_order
    WHERE paid_order.payment_id = p_payment_id
    FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO public.earlybird_webhook_events (
            event_id, idempotency_key, event_type, occurred_at,
            payment_id, product_id, amount_krw, disposition
        ) VALUES (
            p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
            p_payment_id, p_product_id, p_amount_krw, 'cancel_unmatched'
        );
        RETURN QUERY SELECT
            'cancel_unmatched'::TEXT,
            NULL::UUID,
            NULL::TEXT,
            NULL::SMALLINT;
        RETURN;
    END IF;

    IF v_order.actual_groble_product_id <> p_product_id
       OR v_order.actual_amount_krw <> p_amount_krw THEN
        INSERT INTO public.earlybird_webhook_events (
            event_id, idempotency_key, event_type, occurred_at,
            payment_id, product_id, amount_krw, disposition, order_id
        ) VALUES (
            p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
            p_payment_id, p_product_id, p_amount_krw, 'cancel_mismatch', v_order.id
        );
        RETURN QUERY SELECT
            'cancel_mismatch'::TEXT,
            v_order.id,
            v_order.status,
            v_order.plan_sequence;
        RETURN;
    END IF;

    IF v_order.status IN ('paid', 'analysis_in_progress', 'completed') THEN
        UPDATE public.earlybird_orders AS cancelled_order
        SET status = 'refund_pending',
            updated_at = pg_catalog.clock_timestamp()
        WHERE cancelled_order.id = v_order.id
        RETURNING cancelled_order.* INTO v_order;
    END IF;

    INSERT INTO public.earlybird_webhook_events (
        event_id, idempotency_key, event_type, occurred_at,
        payment_id, product_id, amount_krw, disposition, order_id
    ) VALUES (
        p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
        p_payment_id, p_product_id, p_amount_krw, 'cancel_requested', v_order.id
    );

    RETURN QUERY SELECT
        'cancel_requested'::TEXT,
        v_order.id,
        v_order.status,
        v_order.plan_sequence;
END;
$_$;


--
-- Name: finalize_earlybird_groble_payment(text, text, text, timestamp with time zone, text, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_earlybird_groble_payment(p_event_id text, p_idempotency_key text, p_event_type text, p_occurred_at timestamp with time zone, p_payment_id text, p_buyer_email text, p_product_id text, p_amount_krw integer, p_paid_at timestamp with time zone) RETURNS TABLE(disposition text, order_id uuid, status text, plan_sequence smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_result RECORD;
    v_accepted_event_id TEXT;
BEGIN
    SELECT finalized.* INTO v_result
    FROM public.finalize_earlybird_groble_payment_refund_aware(
        NULL::UUID, TRUE, p_event_id, p_idempotency_key, p_event_type,
        p_occurred_at, p_payment_id, p_buyer_email, NULL::TEXT, NULL::TEXT,
        NULL::TEXT, p_product_id, p_amount_krw, p_paid_at
    ) AS finalized;

    SELECT webhook_event.event_id
    INTO v_accepted_event_id
    FROM public.earlybird_webhook_events AS webhook_event
    WHERE webhook_event.order_id = v_result.order_id
      AND webhook_event.event_type = 'payment.completed'
      AND webhook_event.disposition = 'accepted'
    ORDER BY (webhook_event.event_id = p_event_id) DESC,
        webhook_event.processed_at,
        webhook_event.event_id
    LIMIT 1;
    IF FOUND THEN
        PERFORM public.record_external_paid_ever(
            v_result.order_id, v_accepted_event_id
        );
    END IF;

    RETURN QUERY SELECT v_result.disposition::TEXT, v_result.order_id::UUID,
        v_result.status::TEXT, v_result.plan_sequence::SMALLINT;
END;
$$;


--
-- Name: finalize_earlybird_groble_payment(text, text, text, timestamp with time zone, text, text, text, text, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_earlybird_groble_payment(p_event_id text, p_idempotency_key text, p_event_type text, p_occurred_at timestamp with time zone, p_payment_id text, p_buyer_email text, p_buyer_phone_normalized text, p_buyer_phone_raw text, p_buyer_display_name text, p_product_id text, p_amount_krw integer, p_paid_at timestamp with time zone) RETURNS TABLE(disposition text, order_id uuid, status text, plan_sequence smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_result RECORD;
    v_accepted_event_id TEXT;
BEGIN
    SELECT finalized.* INTO v_result
    FROM public.finalize_earlybird_groble_payment_refund_aware(
        NULL::UUID, FALSE, p_event_id, p_idempotency_key, p_event_type,
        p_occurred_at, p_payment_id, p_buyer_email, p_buyer_phone_normalized,
        p_buyer_phone_raw, p_buyer_display_name, p_product_id, p_amount_krw,
        p_paid_at
    ) AS finalized;

    SELECT webhook_event.event_id
    INTO v_accepted_event_id
    FROM public.earlybird_webhook_events AS webhook_event
    WHERE webhook_event.order_id = v_result.order_id
      AND webhook_event.event_type = 'payment.completed'
      AND webhook_event.disposition = 'accepted'
    ORDER BY (webhook_event.event_id = p_event_id) DESC,
        webhook_event.processed_at,
        webhook_event.event_id
    LIMIT 1;
    IF FOUND THEN
        PERFORM public.record_external_paid_ever(
            v_result.order_id, v_accepted_event_id
        );
    END IF;

    RETURN QUERY SELECT v_result.disposition::TEXT, v_result.order_id::UUID,
        v_result.status::TEXT, v_result.plan_sequence::SMALLINT;
END;
$$;


--
-- Name: finalize_earlybird_groble_payment_by_reference(text, text, text, text, timestamp with time zone, text, text, text, text, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_earlybird_groble_payment_by_reference(p_seller_reference text, p_event_id text, p_idempotency_key text, p_event_type text, p_occurred_at timestamp with time zone, p_payment_id text, p_buyer_email text, p_buyer_phone_normalized text, p_buyer_phone_raw text, p_buyer_display_name text, p_product_id text, p_amount_krw integer, p_paid_at timestamp with time zone) RETURNS TABLE(disposition text, order_id uuid, status text, plan_sequence smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_referenced_order_id UUID;
    v_result RECORD;
    v_accepted_event_id TEXT;
BEGIN
    IF p_seller_reference IS NULL
       OR p_seller_reference !~ '^ord[.][a-f0-9]{32}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SELLER_REFERENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT paid_order.id INTO v_referenced_order_id
    FROM public.earlybird_orders AS paid_order
    WHERE paid_order.groble_seller_reference = p_seller_reference;
    IF v_referenced_order_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SELLER_REFERENCE_UNMATCHED',
            ERRCODE = 'P0001';
    END IF;

    SELECT finalized.* INTO v_result
    FROM public.finalize_earlybird_groble_payment_refund_aware(
        v_referenced_order_id, FALSE, p_event_id, p_idempotency_key,
        p_event_type, p_occurred_at, p_payment_id, p_buyer_email,
        p_buyer_phone_normalized, p_buyer_phone_raw, p_buyer_display_name,
        p_product_id, p_amount_krw, p_paid_at
    ) AS finalized;

    IF v_result.order_id = v_referenced_order_id
       AND v_result.status IN ('paid', 'analysis_in_progress', 'completed') THEN
        UPDATE public.earlybird_orders AS paid_order
        SET seller_reference_confirmed_at = COALESCE(
                paid_order.seller_reference_confirmed_at,
                pg_catalog.clock_timestamp()
            ),
            updated_at = pg_catalog.clock_timestamp()
        WHERE paid_order.id = v_referenced_order_id;
    END IF;

    SELECT webhook_event.event_id
    INTO v_accepted_event_id
    FROM public.earlybird_webhook_events AS webhook_event
    WHERE webhook_event.order_id = v_result.order_id
      AND webhook_event.event_type = 'payment.completed'
      AND webhook_event.disposition = 'accepted'
    ORDER BY (webhook_event.event_id = p_event_id) DESC,
        webhook_event.processed_at,
        webhook_event.event_id
    LIMIT 1;
    IF FOUND THEN
        PERFORM public.record_external_paid_ever(
            v_result.order_id, v_accepted_event_id
        );
    END IF;

    RETURN QUERY SELECT v_result.disposition::TEXT, v_result.order_id::UUID,
        v_result.status::TEXT, v_result.plan_sequence::SMALLINT;
END;
$_$;


--
-- Name: finalize_earlybird_groble_payment_pre_reconciliation(text, text, text, timestamp with time zone, text, text, text, text, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_earlybird_groble_payment_pre_reconciliation(p_event_id text, p_idempotency_key text, p_event_type text, p_occurred_at timestamp with time zone, p_payment_id text, p_buyer_email text, p_buyer_phone_normalized text, p_buyer_phone_raw text, p_buyer_display_name text, p_product_id text, p_amount_krw integer, p_paid_at timestamp with time zone) RETURNS TABLE(disposition text, order_id uuid, status text, plan_sequence smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_event public.earlybird_webhook_events%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
    v_candidate_count INTEGER := 0;
    v_candidate_order_id UUID;
    v_sequence SMALLINT;
    v_user_id UUID;
    v_lock_user_id UUID;
    v_email_user_count INTEGER;
    v_match_method TEXT;
BEGIN
    IF p_event_type IS DISTINCT FROM 'payment.completed'
       OR p_event_id IS NULL
          OR pg_catalog.char_length(p_event_id) NOT BETWEEN 1 AND 256
       OR p_idempotency_key IS NULL
          OR pg_catalog.char_length(p_idempotency_key) NOT BETWEEN 1 AND 256
       OR p_payment_id IS NULL
          OR pg_catalog.char_length(p_payment_id) NOT BETWEEN 1 AND 256
       OR p_product_id IS NULL OR p_product_id !~ '^[A-Za-z0-9_-]{1,128}$'
       OR p_amount_krw IS NULL OR p_amount_krw < 0
       OR p_buyer_email IS NULL OR pg_catalog.char_length(p_buyer_email) > 320
       OR (
           p_buyer_phone_normalized IS NOT NULL
           AND p_buyer_phone_normalized !~ '^\+8210[0-9]{8}$'
       )
       OR (
           p_buyer_phone_raw IS NOT NULL
           AND pg_catalog.char_length(p_buyer_phone_raw) NOT BETWEEN 1 AND 64
       )
       OR (
           p_buyer_display_name IS NOT NULL
           AND pg_catalog.char_length(p_buyer_display_name) NOT BETWEEN 1 AND 100
       )
       OR p_occurred_at IS NULL OR p_paid_at IS NULL THEN
        RAISE EXCEPTION 'GROBLE_PAYMENT_EVIDENCE_INVALID';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_payment_id, 0)
    );

    SELECT webhook_event.*
    INTO v_event
    FROM public.earlybird_webhook_events AS webhook_event
    WHERE webhook_event.event_id = p_event_id
       OR webhook_event.idempotency_key = p_idempotency_key
    ORDER BY webhook_event.processed_at
    LIMIT 1;
    IF FOUND THEN
        IF v_event.order_id IS NOT NULL THEN
            SELECT existing_order.*
            INTO v_order
            FROM public.earlybird_orders AS existing_order
            WHERE existing_order.id = v_event.order_id;
            RETURN QUERY SELECT
                'duplicate_event'::TEXT,
                v_order.id,
                v_order.status,
                v_order.plan_sequence;
        ELSE
            RETURN QUERY SELECT
                'duplicate_event'::TEXT,
                NULL::UUID,
                NULL::TEXT,
                NULL::SMALLINT;
        END IF;
        RETURN;
    END IF;

    SELECT existing_order.*
    INTO v_order
    FROM public.earlybird_orders AS existing_order
    WHERE existing_order.payment_id = p_payment_id;
    IF FOUND THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(v_order.user_id::TEXT, 0)
        );
        SELECT existing_order.*
        INTO v_order
        FROM public.earlybird_orders AS existing_order
        WHERE existing_order.id = v_order.id
        FOR UPDATE;

        INSERT INTO public.earlybird_webhook_events (
            event_id, idempotency_key, event_type, occurred_at,
            payment_id, product_id, amount_krw, disposition, order_id
        ) VALUES (
            p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
            p_payment_id, p_product_id, p_amount_krw, 'duplicate_payment', v_order.id
        );
        RETURN QUERY SELECT
            'duplicate_payment'::TEXT,
            v_order.id,
            v_order.status,
            v_order.plan_sequence;
        RETURN;
    END IF;

    -- Lock every user that could gain or already own a matching snapshot. The order
    -- is stable across competing payments, preventing multi-user advisory deadlocks.
    FOR v_lock_user_id IN
        SELECT potential_user.user_id
        FROM (
            SELECT phone_order.user_id
            FROM public.earlybird_orders AS phone_order
            WHERE p_buyer_phone_normalized IS NOT NULL
              AND phone_order.status IN ('payment_pending', 'cancelled')
              AND phone_order.payment_id IS NULL
              AND phone_order.buyer_match_policy = 'verified_kakao_phone'
              AND phone_order.expected_buyer_phone_verification_source
                    = 'kakao_rest_api'
              AND phone_order.expected_buyer_phone_verified_at IS NOT NULL
              AND phone_order.expected_groble_product_id = p_product_id
              AND phone_order.expected_buyer_phone_number_normalized
                    = p_buyer_phone_normalized

            UNION

            SELECT buyer.id AS user_id
            FROM public.users AS buyer
            WHERE pg_catalog.lower(pg_catalog.btrim(buyer.email))
                = pg_catalog.lower(pg_catalog.btrim(p_buyer_email))
        ) AS potential_user
        ORDER BY potential_user.user_id::TEXT
    LOOP
        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(v_lock_user_id::TEXT, 0)
        );
    END LOOP;

    -- Counts below are authoritative because checkout and payment finalization use
    -- the same per-user advisory locks acquired above.
    IF p_buyer_phone_normalized IS NOT NULL THEN
        SELECT pg_catalog.count(*)::INTEGER
        INTO v_candidate_count
        FROM public.earlybird_orders AS candidate
        WHERE candidate.status = 'payment_pending'
          AND candidate.buyer_match_policy = 'verified_kakao_phone'
          AND candidate.expected_buyer_phone_verification_source
                = 'kakao_rest_api'
          AND candidate.expected_buyer_phone_verified_at IS NOT NULL
          AND candidate.expected_groble_product_id = p_product_id
          AND candidate.expected_buyer_phone_number_normalized
                = p_buyer_phone_normalized;

        IF v_candidate_count > 1 THEN
            INSERT INTO public.earlybird_webhook_events (
                event_id, idempotency_key, event_type, occurred_at,
                payment_id, product_id, amount_krw, disposition
            ) VALUES (
                p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                p_payment_id, p_product_id, p_amount_krw, 'ambiguous_buyer'
            );
            RETURN QUERY SELECT
                'ambiguous_buyer'::TEXT,
                NULL::UUID,
                NULL::TEXT,
                NULL::SMALLINT;
            RETURN;
        ELSIF v_candidate_count = 1 THEN
            SELECT candidate.id, candidate.user_id
            INTO v_candidate_order_id, v_user_id
            FROM public.earlybird_orders AS candidate
            WHERE candidate.status = 'payment_pending'
              AND candidate.buyer_match_policy = 'verified_kakao_phone'
              AND candidate.expected_buyer_phone_verification_source
                    = 'kakao_rest_api'
              AND candidate.expected_buyer_phone_verified_at IS NOT NULL
              AND candidate.expected_groble_product_id = p_product_id
              AND candidate.expected_buyer_phone_number_normalized
                    = p_buyer_phone_normalized;
            v_match_method := 'phone';
        ELSE
            SELECT pg_catalog.count(*)::INTEGER
            INTO v_candidate_count
            FROM public.earlybird_orders AS cancelled_candidate
            WHERE cancelled_candidate.status = 'cancelled'
              AND cancelled_candidate.payment_id IS NULL
              AND cancelled_candidate.buyer_match_policy = 'verified_kakao_phone'
              AND cancelled_candidate.expected_buyer_phone_verification_source
                    = 'kakao_rest_api'
              AND cancelled_candidate.expected_buyer_phone_verified_at IS NOT NULL
              AND cancelled_candidate.expected_buyer_phone_number_normalized
                    = p_buyer_phone_normalized
              AND cancelled_candidate.expected_groble_product_id = p_product_id
              AND cancelled_candidate.expected_amount_krw >= p_amount_krw
              AND p_amount_krw >= 0;

            IF v_candidate_count > 1 THEN
                INSERT INTO public.earlybird_webhook_events (
                    event_id, idempotency_key, event_type, occurred_at,
                    payment_id, product_id, amount_krw, disposition
                ) VALUES (
                    p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                    p_payment_id, p_product_id, p_amount_krw, 'ambiguous_buyer'
                );
                RETURN QUERY SELECT
                    'ambiguous_buyer'::TEXT,
                    NULL::UUID,
                    NULL::TEXT,
                    NULL::SMALLINT;
                RETURN;
            ELSIF v_candidate_count = 1 THEN
                SELECT cancelled_candidate.*
                INTO v_order
                FROM public.earlybird_orders AS cancelled_candidate
                WHERE cancelled_candidate.status = 'cancelled'
                  AND cancelled_candidate.payment_id IS NULL
                  AND cancelled_candidate.buyer_match_policy = 'verified_kakao_phone'
                  AND cancelled_candidate.expected_buyer_phone_verification_source
                        = 'kakao_rest_api'
                  AND cancelled_candidate.expected_buyer_phone_verified_at IS NOT NULL
                  AND cancelled_candidate.expected_buyer_phone_number_normalized
                        = p_buyer_phone_normalized
                  AND cancelled_candidate.expected_groble_product_id = p_product_id
                  AND cancelled_candidate.expected_amount_krw >= p_amount_krw
                  AND p_amount_krw >= 0
                FOR UPDATE;

                IF NOT FOUND THEN
                    INSERT INTO public.earlybird_webhook_events (
                        event_id, idempotency_key, event_type, occurred_at,
                        payment_id, product_id, amount_krw, disposition
                    ) VALUES (
                        p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                        p_payment_id, p_product_id, p_amount_krw, 'unmatched'
                    );
                    RETURN QUERY SELECT
                        'unmatched'::TEXT,
                        NULL::UUID,
                        NULL::TEXT,
                        NULL::SMALLINT;
                    RETURN;
                END IF;

                UPDATE public.earlybird_orders AS late_order
                SET status = 'refund_pending',
                    payment_id = p_payment_id,
                    actual_groble_product_id = p_product_id,
                    actual_amount_krw = p_amount_krw,
                    paid_at = p_paid_at,
                    updated_at = pg_catalog.clock_timestamp()
                WHERE late_order.id = v_order.id
                RETURNING late_order.* INTO v_order;

                INSERT INTO public.earlybird_webhook_events (
                    event_id, idempotency_key, event_type, occurred_at,
                    payment_id, product_id, amount_krw, disposition, order_id
                ) VALUES (
                    p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                    p_payment_id, p_product_id, p_amount_krw,
                    'late_cancelled_payment', v_order.id
                );
                RETURN QUERY SELECT
                    'late_cancelled_payment'::TEXT,
                    v_order.id,
                    v_order.status,
                    NULL::SMALLINT;
                RETURN;
            END IF;
        END IF;
    END IF;

    IF p_buyer_phone_normalized IS NULL OR v_candidate_count = 0 THEN
        v_match_method := 'email';
        v_candidate_order_id := NULL;
        v_user_id := NULL;

        SELECT pg_catalog.count(*)::INTEGER
        INTO v_candidate_count
        FROM public.earlybird_orders AS candidate
        JOIN public.users AS buyer ON buyer.id = candidate.user_id
        WHERE candidate.status = 'payment_pending'
          AND candidate.buyer_match_policy = 'legacy_email'
          AND candidate.expected_groble_product_id = p_product_id
          AND pg_catalog.lower(pg_catalog.btrim(buyer.email))
                = pg_catalog.lower(pg_catalog.btrim(p_buyer_email));

        IF v_candidate_count > 1 THEN
            INSERT INTO public.earlybird_webhook_events (
                event_id, idempotency_key, event_type, occurred_at,
                payment_id, product_id, amount_krw, disposition
            ) VALUES (
                p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                p_payment_id, p_product_id, p_amount_krw, 'ambiguous_buyer'
            );
            RETURN QUERY SELECT
                'ambiguous_buyer'::TEXT,
                NULL::UUID,
                NULL::TEXT,
                NULL::SMALLINT;
            RETURN;
        ELSIF v_candidate_count = 1 THEN
            SELECT candidate.id, candidate.user_id
            INTO v_candidate_order_id, v_user_id
            FROM public.earlybird_orders AS candidate
            JOIN public.users AS buyer ON buyer.id = candidate.user_id
            WHERE candidate.status = 'payment_pending'
              AND candidate.buyer_match_policy = 'legacy_email'
              AND candidate.expected_groble_product_id = p_product_id
              AND pg_catalog.lower(pg_catalog.btrim(buyer.email))
                    = pg_catalog.lower(pg_catalog.btrim(p_buyer_email));
        ELSE
            SELECT pg_catalog.count(*)::INTEGER
            INTO v_email_user_count
            FROM public.users AS buyer
            WHERE pg_catalog.lower(pg_catalog.btrim(buyer.email))
                = pg_catalog.lower(pg_catalog.btrim(p_buyer_email));
            IF v_email_user_count = 1 THEN
                SELECT buyer.id
                INTO v_user_id
                FROM public.users AS buyer
                WHERE pg_catalog.lower(pg_catalog.btrim(buyer.email))
                    = pg_catalog.lower(pg_catalog.btrim(p_buyer_email));
            END IF;
        END IF;
    END IF;

    IF v_candidate_count = 0 THEN
        IF v_user_id IS NOT NULL THEN
            SELECT pg_catalog.count(*)::INTEGER
            INTO v_candidate_count
            FROM public.earlybird_orders AS cancelled_order
            WHERE cancelled_order.user_id = v_user_id
              AND cancelled_order.status = 'cancelled'
              AND cancelled_order.payment_id IS NULL
              AND cancelled_order.buyer_match_policy = 'legacy_email'
              AND cancelled_order.expected_groble_product_id = p_product_id
              AND cancelled_order.expected_amount_krw >= p_amount_krw
              AND p_amount_krw >= 0;

            IF v_candidate_count > 1 THEN
                INSERT INTO public.earlybird_webhook_events (
                    event_id, idempotency_key, event_type, occurred_at,
                    payment_id, product_id, amount_krw, disposition
                ) VALUES (
                    p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                    p_payment_id, p_product_id, p_amount_krw, 'ambiguous_buyer'
                );
                RETURN QUERY SELECT
                    'ambiguous_buyer'::TEXT,
                    NULL::UUID,
                    NULL::TEXT,
                    NULL::SMALLINT;
                RETURN;
            ELSIF v_candidate_count = 1 THEN
                SELECT cancelled_order.*
                INTO v_order
                FROM public.earlybird_orders AS cancelled_order
                WHERE cancelled_order.user_id = v_user_id
                  AND cancelled_order.status = 'cancelled'
                  AND cancelled_order.payment_id IS NULL
                  AND cancelled_order.buyer_match_policy = 'legacy_email'
                  AND cancelled_order.expected_groble_product_id = p_product_id
                  AND cancelled_order.expected_amount_krw >= p_amount_krw
                  AND p_amount_krw >= 0
                FOR UPDATE;

                IF NOT FOUND THEN
                    v_candidate_count := 0;
                ELSE
                    UPDATE public.earlybird_orders AS late_order
                    SET status = 'refund_pending',
                        payment_id = p_payment_id,
                        actual_groble_product_id = p_product_id,
                        actual_amount_krw = p_amount_krw,
                        paid_at = p_paid_at,
                        updated_at = pg_catalog.clock_timestamp()
                    WHERE late_order.id = v_order.id
                    RETURNING late_order.* INTO v_order;

                    INSERT INTO public.earlybird_webhook_events (
                        event_id, idempotency_key, event_type, occurred_at,
                        payment_id, product_id, amount_krw, disposition, order_id
                    ) VALUES (
                        p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                        p_payment_id, p_product_id, p_amount_krw,
                        'late_cancelled_payment', v_order.id
                    );
                    RETURN QUERY SELECT
                        'late_cancelled_payment'::TEXT,
                        v_order.id,
                        v_order.status,
                        NULL::SMALLINT;
                    RETURN;
                END IF;
            END IF;
        END IF;

        INSERT INTO public.earlybird_webhook_events (
            event_id, idempotency_key, event_type, occurred_at,
            payment_id, product_id, amount_krw, disposition
        ) VALUES (
            p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
            p_payment_id, p_product_id, p_amount_krw, 'unmatched'
        );
        RETURN QUERY SELECT
            'unmatched'::TEXT,
            NULL::UUID,
            NULL::TEXT,
            NULL::SMALLINT;
        RETURN;
    END IF;

    SELECT candidate.*
    INTO v_order
    FROM public.earlybird_orders AS candidate
    WHERE candidate.id = v_candidate_order_id
      AND candidate.user_id = v_user_id
      AND candidate.status = 'payment_pending'
      AND candidate.expected_groble_product_id = p_product_id
      AND (
          (
              v_match_method = 'phone'
              AND candidate.buyer_match_policy = 'verified_kakao_phone'
              AND candidate.expected_buyer_phone_verification_source
                    = 'kakao_rest_api'
              AND candidate.expected_buyer_phone_verified_at IS NOT NULL
              AND candidate.expected_buyer_phone_number_normalized
                    = p_buyer_phone_normalized
          )
          OR (
              v_match_method = 'email'
              AND candidate.buyer_match_policy = 'legacy_email'
              AND EXISTS (
                  SELECT 1
                  FROM public.users AS buyer
                  WHERE buyer.id = candidate.user_id
                    AND pg_catalog.lower(pg_catalog.btrim(buyer.email))
                        = pg_catalog.lower(pg_catalog.btrim(p_buyer_email))
              )
          )
      )
    FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO public.earlybird_webhook_events (
            event_id, idempotency_key, event_type, occurred_at,
            payment_id, product_id, amount_krw, disposition
        ) VALUES (
            p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
            p_payment_id, p_product_id, p_amount_krw, 'unmatched'
        );
        RETURN QUERY SELECT
            'unmatched'::TEXT,
            NULL::UUID,
            NULL::TEXT,
            NULL::SMALLINT;
        RETURN;
    END IF;

    -- 0 <= 실결제액 <= 정가 는 전부 정상 결제로 인정한다(할인 쿠폰 포함).
    -- 정가를 초과하는 금액만 여전히 mismatch 로 남긴다.
    IF v_order.expected_groble_product_id <> p_product_id
       OR p_amount_krw > v_order.expected_amount_krw THEN
        UPDATE public.earlybird_orders AS mismatch_order
        SET status = 'payment_failed',
            payment_id = p_payment_id,
            actual_groble_product_id = p_product_id,
            actual_amount_krw = p_amount_krw,
            paid_at = p_paid_at,
            updated_at = pg_catalog.clock_timestamp()
        WHERE mismatch_order.id = v_order.id
        RETURNING mismatch_order.* INTO v_order;

        INSERT INTO public.earlybird_webhook_events (
            event_id, idempotency_key, event_type, occurred_at,
            payment_id, product_id, amount_krw, disposition, order_id
        ) VALUES (
            p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
            p_payment_id, p_product_id, p_amount_krw, 'mismatch', v_order.id
        );
        RETURN QUERY SELECT 'mismatch'::TEXT, v_order.id, v_order.status, NULL::SMALLINT;
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.earlybird_webhook_events AS prior_cancellation
        WHERE prior_cancellation.payment_id = p_payment_id
          AND prior_cancellation.event_type = 'payment.cancel_requested'
    ) THEN
        UPDATE public.earlybird_orders AS cancelled_before_confirmation
        SET status = 'refund_pending',
            payment_id = p_payment_id,
            actual_groble_product_id = p_product_id,
            actual_amount_krw = p_amount_krw,
            paid_at = p_paid_at,
            updated_at = pg_catalog.clock_timestamp()
        WHERE cancelled_before_confirmation.id = v_order.id
        RETURNING cancelled_before_confirmation.* INTO v_order;

        UPDATE public.earlybird_webhook_events AS prior_cancellation
        SET disposition = 'cancel_requested',
            order_id = v_order.id
        WHERE prior_cancellation.payment_id = p_payment_id
          AND prior_cancellation.event_type = 'payment.cancel_requested';

        INSERT INTO public.earlybird_webhook_events (
            event_id, idempotency_key, event_type, occurred_at,
            payment_id, product_id, amount_krw, disposition, order_id
        ) VALUES (
            p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
            p_payment_id, p_product_id, p_amount_krw,
            'cancel_before_payment', v_order.id
        );
        RETURN QUERY SELECT
            'cancel_before_payment'::TEXT,
            v_order.id,
            v_order.status,
            NULL::SMALLINT;
        RETURN;
    END IF;

    -- Groble owns paid-plan inventory. Do not allocate or reject
    -- against the legacy server-side counter.
    v_sequence := NULL;

    UPDATE public.earlybird_orders AS accepted_order
    SET status = 'paid',
        payment_id = p_payment_id,
        actual_groble_product_id = p_product_id,
        actual_amount_krw = p_amount_krw,
        paid_at = p_paid_at,
        due_at = p_paid_at + INTERVAL '24 hours',
        plan_sequence = v_sequence,
        updated_at = pg_catalog.clock_timestamp()
    WHERE accepted_order.id = v_order.id
    RETURNING accepted_order.* INTO v_order;

    INSERT INTO public.earlybird_webhook_events (
        event_id, idempotency_key, event_type, occurred_at,
        payment_id, product_id, amount_krw, disposition, order_id
    ) VALUES (
        p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
        p_payment_id, p_product_id, p_amount_krw, 'accepted', v_order.id
    );

    RETURN QUERY SELECT 'accepted'::TEXT, v_order.id, v_order.status, v_order.plan_sequence;
END;
$_$;


--
-- Name: finalize_earlybird_groble_payment_reconciliation_aware(uuid, boolean, text, text, text, timestamp with time zone, text, text, text, text, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_earlybird_groble_payment_reconciliation_aware(p_referenced_order_id uuid, p_require_legacy_email_only boolean, p_event_id text, p_idempotency_key text, p_event_type text, p_occurred_at timestamp with time zone, p_payment_id text, p_buyer_email text, p_buyer_phone_normalized text, p_buyer_phone_raw text, p_buyer_display_name text, p_product_id text, p_amount_krw integer, p_paid_at timestamp with time zone) RETURNS TABLE(disposition text, order_id uuid, status text, plan_sequence smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_event public.earlybird_webhook_events%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
    v_reference_order public.earlybird_orders%ROWTYPE;
    v_result RECORD;
    v_candidate_order_id UUID;
    v_lock_user_id UUID;
    v_reconciliation_history_count INTEGER := 0;
    v_reconciled_count INTEGER := 0;
    v_live_count INTEGER := 0;
    v_reference_is_reconciled BOOLEAN := FALSE;
    v_reference_matches BOOLEAN := FALSE;
BEGIN
    IF p_event_type IS DISTINCT FROM 'payment.completed'
       OR p_event_id IS NULL
          OR pg_catalog.char_length(p_event_id) NOT BETWEEN 1 AND 256
       OR p_idempotency_key IS NULL
          OR pg_catalog.char_length(p_idempotency_key) NOT BETWEEN 1 AND 256
       OR p_payment_id IS NULL
          OR pg_catalog.char_length(p_payment_id) NOT BETWEEN 1 AND 256
       OR p_product_id IS NULL OR p_product_id !~ '^[A-Za-z0-9_-]{1,128}$'
       OR p_amount_krw IS NULL OR p_amount_krw < 0
       OR p_buyer_email IS NULL OR pg_catalog.char_length(p_buyer_email) > 320
       OR (
           p_buyer_phone_normalized IS NOT NULL
           AND p_buyer_phone_normalized !~ '^\+8210[0-9]{8}$'
       )
       OR (
           p_buyer_phone_raw IS NOT NULL
           AND pg_catalog.char_length(p_buyer_phone_raw) NOT BETWEEN 1 AND 64
       )
       OR (
           p_buyer_display_name IS NOT NULL
           AND pg_catalog.char_length(p_buyer_display_name) NOT BETWEEN 1 AND 100
       )
       OR p_occurred_at IS NULL OR p_paid_at IS NULL THEN
        RAISE EXCEPTION 'GROBLE_PAYMENT_EVIDENCE_INVALID';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_payment_id, 0)
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'earlybird:groble:product:' || p_product_id,
            0
        )
    );

    -- Keep every entry point on the same payment -> product -> sorted-users
    -- lock order. Include owners from both candidate lineage and immutable
    -- duplicate attribution before any duplicate path can return.
    FOR v_lock_user_id IN
        SELECT potential_user.user_id
        FROM (
            SELECT candidate.user_id
            FROM public.earlybird_orders AS candidate
            WHERE candidate.expected_groble_product_id = p_product_id
              AND (
                  candidate.status IN ('payment_pending', 'cancelled')
                  OR EXISTS (
                      SELECT 1
                      FROM public.earlybird_checkout_reconciliations AS reconciliation
                      WHERE reconciliation.order_id = candidate.id
                  )
              )

            UNION

            SELECT referenced.user_id
            FROM public.earlybird_orders AS referenced
            WHERE referenced.id = p_referenced_order_id

            UNION

            SELECT payment_order.user_id
            FROM public.earlybird_orders AS payment_order
            WHERE payment_order.payment_id = p_payment_id

            UNION

            SELECT attributed_order.user_id
            FROM public.earlybird_webhook_events AS attributed_event
            JOIN public.earlybird_orders AS attributed_order
              ON attributed_order.id = attributed_event.order_id
            WHERE attributed_event.event_id = p_event_id
               OR attributed_event.idempotency_key = p_idempotency_key
               OR (
                   attributed_event.payment_id = p_payment_id
                   AND attributed_event.event_type = 'payment.completed'
               )

            UNION

            SELECT buyer.id
            FROM public.users AS buyer
            WHERE pg_catalog.lower(pg_catalog.btrim(buyer.email))
                = pg_catalog.lower(pg_catalog.btrim(p_buyer_email))
        ) AS potential_user
        ORDER BY potential_user.user_id::TEXT
    LOOP
        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(v_lock_user_id::TEXT, 0)
        );
    END LOOP;

    SELECT webhook_event.*
    INTO v_event
    FROM public.earlybird_webhook_events AS webhook_event
    WHERE webhook_event.event_id = p_event_id
       OR webhook_event.idempotency_key = p_idempotency_key
    ORDER BY webhook_event.processed_at
    LIMIT 1;
    IF FOUND THEN
        IF v_event.order_id IS NOT NULL THEN
            SELECT existing_order.*
            INTO v_order
            FROM public.earlybird_orders AS existing_order
            WHERE existing_order.id = v_event.order_id;
            RETURN QUERY SELECT
                'duplicate_event'::TEXT,
                v_order.id,
                v_order.status,
                v_order.plan_sequence;
        ELSE
            RETURN QUERY SELECT
                'duplicate_event'::TEXT,
                NULL::UUID,
                NULL::TEXT,
                NULL::SMALLINT;
        END IF;
        RETURN;
    END IF;

    SELECT webhook_event.*
    INTO v_event
    FROM public.earlybird_webhook_events AS webhook_event
    WHERE webhook_event.payment_id = p_payment_id
      AND webhook_event.event_type = 'payment.completed'
    ORDER BY webhook_event.processed_at
    LIMIT 1;
    IF FOUND THEN
        IF v_event.order_id IS NOT NULL THEN
            SELECT existing_order.*
            INTO v_order
            FROM public.earlybird_orders AS existing_order
            WHERE existing_order.id = v_event.order_id;
            RETURN QUERY SELECT
                'duplicate_payment'::TEXT,
                v_order.id,
                v_order.status,
                v_order.plan_sequence;
        ELSE
            RETURN QUERY SELECT
                'duplicate_payment'::TEXT,
                NULL::UUID,
                NULL::TEXT,
                NULL::SMALLINT;
        END IF;
        RETURN;
    END IF;

    SELECT existing_order.*
    INTO v_order
    FROM public.earlybird_orders AS existing_order
    WHERE existing_order.payment_id = p_payment_id;
    IF FOUND THEN
        RETURN QUERY SELECT
            'duplicate_payment'::TEXT,
            v_order.id,
            v_order.status,
            v_order.plan_sequence;
        RETURN;
    END IF;

    SELECT pg_catalog.count(*)::INTEGER
    INTO v_reconciliation_history_count
    FROM public.earlybird_orders AS candidate
    JOIN public.earlybird_checkout_reconciliations AS reconciliation
      ON reconciliation.order_id = candidate.id
    WHERE candidate.expected_groble_product_id = p_product_id
      AND (
          (
              candidate.buyer_match_policy = 'verified_kakao_phone'
              AND candidate.expected_buyer_phone_verification_source
                    = 'kakao_rest_api'
              AND candidate.expected_buyer_phone_verified_at IS NOT NULL
              AND (
                  (
                      p_buyer_phone_normalized IS NOT NULL
                      AND candidate.expected_buyer_phone_number_normalized
                            = p_buyer_phone_normalized
                  )
                  OR (
                      p_require_legacy_email_only IS TRUE
                      AND p_buyer_phone_normalized IS NULL
                  )
              )
          )
          OR (
              candidate.buyer_match_policy = 'legacy_email'
              AND EXISTS (
                  SELECT 1
                  FROM public.users AS buyer
                  WHERE buyer.id = candidate.user_id
                    AND pg_catalog.lower(pg_catalog.btrim(buyer.email))
                        = pg_catalog.lower(pg_catalog.btrim(p_buyer_email))
              )
          )
      );

    SELECT pg_catalog.count(*)::INTEGER, pg_catalog.min(candidate.id::TEXT)::UUID
    INTO v_reconciled_count, v_candidate_order_id
    FROM public.earlybird_orders AS candidate
    JOIN public.earlybird_checkout_reconciliations AS reconciliation
      ON reconciliation.order_id = candidate.id
    WHERE candidate.status = 'payment_failed'
      AND candidate.payment_id IS NULL
      AND candidate.actual_amount_krw IS NULL
      AND candidate.paid_at IS NULL
      AND candidate.seller_reference_confirmed_at IS NULL
      AND candidate.result_request_id IS NULL
      AND candidate.expected_groble_product_id = p_product_id
      AND (
          (
              p_buyer_phone_normalized IS NOT NULL
              AND candidate.buyer_match_policy = 'verified_kakao_phone'
              AND candidate.expected_buyer_phone_verification_source
                    = 'kakao_rest_api'
              AND candidate.expected_buyer_phone_verified_at IS NOT NULL
              AND candidate.expected_buyer_phone_number_normalized
                    = p_buyer_phone_normalized
          )
          OR (
              candidate.buyer_match_policy = 'legacy_email'
              AND EXISTS (
                  SELECT 1
                  FROM public.users AS buyer
                  WHERE buyer.id = candidate.user_id
                    AND pg_catalog.lower(pg_catalog.btrim(buyer.email))
                        = pg_catalog.lower(pg_catalog.btrim(p_buyer_email))
              )
          )
      );

    SELECT pg_catalog.count(*)::INTEGER
    INTO v_live_count
    FROM public.earlybird_orders AS candidate
    WHERE candidate.status IN ('payment_pending', 'cancelled')
      AND candidate.payment_id IS NULL
      AND candidate.expected_groble_product_id = p_product_id
      AND (
          (
              p_buyer_phone_normalized IS NOT NULL
              AND candidate.buyer_match_policy = 'verified_kakao_phone'
              AND candidate.expected_buyer_phone_verification_source
                    = 'kakao_rest_api'
              AND candidate.expected_buyer_phone_verified_at IS NOT NULL
              AND candidate.expected_buyer_phone_number_normalized
                    = p_buyer_phone_normalized
          )
          OR (
              candidate.buyer_match_policy = 'legacy_email'
              AND EXISTS (
                  SELECT 1
                  FROM public.users AS buyer
                  WHERE buyer.id = candidate.user_id
                    AND pg_catalog.lower(pg_catalog.btrim(buyer.email))
                        = pg_catalog.lower(pg_catalog.btrim(p_buyer_email))
              )
          )
      );

    IF p_referenced_order_id IS NULL
       AND p_require_legacy_email_only IS TRUE
       AND v_reconciliation_history_count = 0 THEN
        IF EXISTS (
            SELECT 1
            FROM public.earlybird_orders AS candidate
            WHERE candidate.buyer_match_policy = 'verified_kakao_phone'
              AND candidate.expected_groble_product_id = p_product_id
              AND (
                  candidate.status = 'payment_pending'
                  OR (
                      candidate.status = 'cancelled'
                      AND candidate.payment_id IS NULL
                  )
              )
        ) THEN
            RAISE EXCEPTION 'GROBLE_CANONICAL_PHONE_REQUIRED';
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM public.earlybird_orders AS candidate
            JOIN public.users AS buyer ON buyer.id = candidate.user_id
            WHERE candidate.buyer_match_policy = 'legacy_email'
              AND candidate.status IN ('payment_pending', 'cancelled')
              AND candidate.payment_id IS NULL
              AND candidate.expected_groble_product_id = p_product_id
              AND (
                  candidate.status = 'payment_pending'
                  OR (
                      candidate.expected_amount_krw >= p_amount_krw
                      AND p_amount_krw >= 0
                  )
              )
              AND pg_catalog.lower(pg_catalog.btrim(buyer.email))
                    = pg_catalog.lower(pg_catalog.btrim(p_buyer_email))
        ) THEN
            RAISE EXCEPTION 'GROBLE_CANONICAL_PHONE_REQUIRED';
        END IF;
    END IF;

    IF p_referenced_order_id IS NOT NULL THEN
        SELECT referenced.*
        INTO v_reference_order
        FROM public.earlybird_orders AS referenced
        WHERE referenced.id = p_referenced_order_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_SELLER_REFERENCE_UNMATCHED',
                ERRCODE = 'P0001';
        END IF;

        SELECT EXISTS (
            SELECT 1
            FROM public.earlybird_checkout_reconciliations AS reconciliation
            WHERE reconciliation.order_id = p_referenced_order_id
        ) INTO v_reference_is_reconciled;

        v_reference_matches := (
            v_reference_order.expected_groble_product_id = p_product_id
            AND (
                (
                    p_buyer_phone_normalized IS NOT NULL
                    AND v_reference_order.buyer_match_policy
                        = 'verified_kakao_phone'
                    AND v_reference_order.expected_buyer_phone_verification_source
                        = 'kakao_rest_api'
                    AND v_reference_order.expected_buyer_phone_verified_at IS NOT NULL
                    AND v_reference_order.expected_buyer_phone_number_normalized
                        = p_buyer_phone_normalized
                )
                OR (
                    v_reference_order.buyer_match_policy = 'legacy_email'
                    AND EXISTS (
                        SELECT 1
                        FROM public.users AS buyer
                        WHERE buyer.id = v_reference_order.user_id
                          AND pg_catalog.lower(pg_catalog.btrim(buyer.email))
                            = pg_catalog.lower(pg_catalog.btrim(p_buyer_email))
                    )
                )
            )
        );

        IF v_reference_is_reconciled THEN
            IF v_reference_order.status = 'payment_failed'
               AND v_reference_order.payment_id IS NULL
               AND v_reference_order.actual_amount_krw IS NULL
               AND v_reference_order.paid_at IS NULL
               AND v_reference_order.seller_reference_confirmed_at IS NULL
               AND v_reference_order.result_request_id IS NULL
               AND v_reference_matches IS TRUE THEN
                UPDATE public.earlybird_orders AS reconciled_order
                SET status = 'refund_pending',
                    payment_id = p_payment_id,
                    actual_groble_product_id = p_product_id,
                    actual_amount_krw = p_amount_krw,
                    paid_at = p_paid_at,
                    updated_at = pg_catalog.clock_timestamp()
                WHERE reconciled_order.id = v_reference_order.id
                RETURNING reconciled_order.* INTO v_order;

                INSERT INTO public.earlybird_webhook_events (
                    event_id, idempotency_key, event_type, occurred_at,
                    payment_id, product_id, amount_krw, disposition, order_id
                ) VALUES (
                    p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                    p_payment_id, p_product_id, p_amount_krw,
                    'late_cancelled_payment', v_order.id
                );
                RETURN QUERY SELECT
                    'late_cancelled_payment'::TEXT,
                    v_order.id,
                    v_order.status,
                    NULL::SMALLINT;
                RETURN;
            END IF;

            INSERT INTO public.earlybird_webhook_events (
                event_id, idempotency_key, event_type, occurred_at,
                payment_id, product_id, amount_krw, disposition, order_id
            ) VALUES (
                p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                p_payment_id, p_product_id, p_amount_krw, 'ambiguous_buyer',
                p_referenced_order_id
            );
            RETURN QUERY SELECT
                'ambiguous_buyer'::TEXT,
                v_reference_order.id,
                v_reference_order.status,
                NULL::SMALLINT;
            RETURN;
        END IF;

        IF v_reference_matches IS NOT TRUE
           OR v_reference_order.status NOT IN ('payment_pending', 'cancelled')
           OR v_reference_order.payment_id IS NOT NULL
           OR v_live_count <> 1 THEN
            INSERT INTO public.earlybird_webhook_events (
                event_id, idempotency_key, event_type, occurred_at,
                payment_id, product_id, amount_krw, disposition, order_id
            ) VALUES (
                p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                p_payment_id, p_product_id, p_amount_krw, 'ambiguous_buyer',
                p_referenced_order_id
            );
            RETURN QUERY SELECT
                'ambiguous_buyer'::TEXT,
                v_reference_order.id,
                v_reference_order.status,
                NULL::SMALLINT;
            RETURN;
        END IF;
    ELSE
        IF v_reconciliation_history_count > 1
           OR (
               v_reconciliation_history_count > 0
               AND v_live_count > 0
           )
           OR (
               v_reconciliation_history_count > 0
               AND v_reconciled_count <> 1
           ) THEN
            INSERT INTO public.earlybird_webhook_events (
                event_id, idempotency_key, event_type, occurred_at,
                payment_id, product_id, amount_krw, disposition
            ) VALUES (
                p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                p_payment_id, p_product_id, p_amount_krw, 'ambiguous_buyer'
            );
            RETURN QUERY SELECT
                'ambiguous_buyer'::TEXT,
                NULL::UUID,
                NULL::TEXT,
                NULL::SMALLINT;
            RETURN;
        ELSIF v_reconciled_count = 1 THEN
            SELECT candidate.*
            INTO v_order
            FROM public.earlybird_orders AS candidate
            JOIN public.earlybird_checkout_reconciliations AS reconciliation
              ON reconciliation.order_id = candidate.id
            WHERE candidate.id = v_candidate_order_id
              AND candidate.status = 'payment_failed'
              AND candidate.payment_id IS NULL
              AND candidate.actual_amount_krw IS NULL
              AND candidate.paid_at IS NULL
              AND candidate.seller_reference_confirmed_at IS NULL
              AND candidate.result_request_id IS NULL
            FOR UPDATE OF candidate;

            IF NOT FOUND THEN
                INSERT INTO public.earlybird_webhook_events (
                    event_id, idempotency_key, event_type, occurred_at,
                    payment_id, product_id, amount_krw, disposition
                ) VALUES (
                    p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                    p_payment_id, p_product_id, p_amount_krw, 'ambiguous_buyer'
                );
                RETURN QUERY SELECT
                    'ambiguous_buyer'::TEXT,
                    NULL::UUID,
                    NULL::TEXT,
                    NULL::SMALLINT;
                RETURN;
            END IF;

            UPDATE public.earlybird_orders AS reconciled_order
            SET status = 'refund_pending',
                payment_id = p_payment_id,
                actual_groble_product_id = p_product_id,
                actual_amount_krw = p_amount_krw,
                paid_at = p_paid_at,
                updated_at = pg_catalog.clock_timestamp()
            WHERE reconciled_order.id = v_order.id
            RETURNING reconciled_order.* INTO v_order;

            INSERT INTO public.earlybird_webhook_events (
                event_id, idempotency_key, event_type, occurred_at,
                payment_id, product_id, amount_krw, disposition, order_id
            ) VALUES (
                p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                p_payment_id, p_product_id, p_amount_krw,
                'late_cancelled_payment', v_order.id
            );
            RETURN QUERY SELECT
                'late_cancelled_payment'::TEXT,
                v_order.id,
                v_order.status,
                NULL::SMALLINT;
            RETURN;
        END IF;
    END IF;

    BEGIN
        SELECT canonical_result.*
        INTO v_result
        FROM public.finalize_earlybird_groble_payment_pre_reconciliation(
            p_event_id => p_event_id,
            p_idempotency_key => p_idempotency_key,
            p_event_type => p_event_type,
            p_occurred_at => p_occurred_at,
            p_payment_id => p_payment_id,
            p_buyer_email => p_buyer_email,
            p_buyer_phone_normalized => p_buyer_phone_normalized,
            p_buyer_phone_raw => p_buyer_phone_raw,
            p_buyer_display_name => p_buyer_display_name,
            p_product_id => p_product_id,
            p_amount_krw => p_amount_krw,
            p_paid_at => p_paid_at
        ) AS canonical_result;

        IF p_referenced_order_id IS NOT NULL
           AND v_result.order_id IS NOT NULL
           AND v_result.order_id IS DISTINCT FROM p_referenced_order_id THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_SELLER_REFERENCE_CONFLICT',
                ERRCODE = 'ZX001';
        END IF;
    EXCEPTION
        WHEN SQLSTATE 'ZX001' THEN
            INSERT INTO public.earlybird_webhook_events (
                event_id, idempotency_key, event_type, occurred_at,
                payment_id, product_id, amount_krw, disposition, order_id
            ) VALUES (
                p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
                p_payment_id, p_product_id, p_amount_krw, 'ambiguous_buyer',
                p_referenced_order_id
            );
            RETURN QUERY SELECT
                'ambiguous_buyer'::TEXT,
                v_reference_order.id,
                v_reference_order.status,
                NULL::SMALLINT;
            RETURN;
    END;

    RETURN QUERY SELECT
        v_result.disposition::TEXT,
        v_result.order_id::UUID,
        v_result.status::TEXT,
        v_result.plan_sequence::SMALLINT;
END;
$_$;


--
-- Name: finalize_earlybird_groble_payment_refund_aware(uuid, boolean, text, text, text, timestamp with time zone, text, text, text, text, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_earlybird_groble_payment_refund_aware(p_referenced_order_id uuid, p_require_legacy_email_only boolean, p_event_id text, p_idempotency_key text, p_event_type text, p_occurred_at timestamp with time zone, p_payment_id text, p_buyer_email text, p_buyer_phone_normalized text, p_buyer_phone_raw text, p_buyer_display_name text, p_product_id text, p_amount_krw integer, p_paid_at timestamp with time zone) RETURNS TABLE(disposition text, order_id uuid, status text, plan_sequence smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_result RECORD;
    v_order public.earlybird_orders%ROWTYPE;
BEGIN
    -- The delegated finalizer validates evidence and acquires this same lock
    -- before it can attribute a payment. It remains held through this wrapper.
    SELECT finalized.*
    INTO v_result
    FROM public.finalize_earlybird_groble_payment_reconciliation_aware(
        p_referenced_order_id,
        p_require_legacy_email_only,
        p_event_id,
        p_idempotency_key,
        p_event_type,
        p_occurred_at,
        p_payment_id,
        p_buyer_email,
        p_buyer_phone_normalized,
        p_buyer_phone_raw,
        p_buyer_display_name,
        p_product_id,
        p_amount_krw,
        p_paid_at
    ) AS finalized;

    IF v_result.order_id IS NULL
       OR NOT EXISTS (
            SELECT 1
            FROM public.earlybird_webhook_events AS refund_event
            WHERE refund_event.event_type = 'payment.refunded'
              AND refund_event.payment_id = p_payment_id
              AND refund_event.product_id = p_product_id
              AND refund_event.amount_krw = p_amount_krw
              AND refund_event.refund_amount_krw = p_amount_krw
              AND refund_event.partial_refund IS FALSE
       ) THEN
        RETURN QUERY SELECT
            v_result.disposition::TEXT,
            v_result.order_id::UUID,
            v_result.status::TEXT,
            v_result.plan_sequence::SMALLINT;
        RETURN;
    END IF;

    SELECT earlybird_order.*
    INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = v_result.order_id
      AND earlybird_order.expected_groble_product_id = p_product_id
      AND earlybird_order.actual_groble_product_id = p_product_id
      AND earlybird_order.actual_amount_krw = p_amount_krw
    FOR UPDATE;

    IF NOT FOUND OR v_order.status NOT IN (
        'paid', 'refund_pending', 'analysis_in_progress', 'completed', 'refunded'
    ) THEN
        RETURN QUERY SELECT
            v_result.disposition::TEXT,
            v_result.order_id::UUID,
            v_result.status::TEXT,
            v_result.plan_sequence::SMALLINT;
        RETURN;
    END IF;

    IF v_order.status <> 'refunded' THEN
        UPDATE public.earlybird_orders AS earlybird_order
        SET status = 'refunded',
            updated_at = pg_catalog.clock_timestamp()
        WHERE earlybird_order.id = v_order.id
        RETURNING earlybird_order.* INTO v_order;
    END IF;

    -- Attach the previously unmatched, full-refund evidence to the now
    -- attributed order. Partial refunds are deliberately excluded above.
    UPDATE public.earlybird_webhook_events AS refund_event
    SET disposition = 'refunded',
        order_id = v_order.id
    WHERE refund_event.event_type = 'payment.refunded'
      AND refund_event.payment_id = p_payment_id
      AND refund_event.product_id = p_product_id
      AND refund_event.amount_krw = p_amount_krw
      AND refund_event.refund_amount_krw = p_amount_krw
      AND refund_event.partial_refund IS FALSE
      AND refund_event.disposition = 'refund_unmatched';

    RETURN QUERY SELECT
        'refunded'::TEXT,
        v_order.id,
        v_order.status,
        v_order.plan_sequence;
END;
$$;


--
-- Name: finalize_earlybird_groble_refund(text, text, text, timestamp with time zone, text, text, integer, integer, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_earlybird_groble_refund(p_event_id text, p_idempotency_key text, p_event_type text, p_occurred_at timestamp with time zone, p_payment_id text, p_product_id text, p_amount_krw integer, p_refund_amount_krw integer, p_partial_refund boolean, p_refunded_at timestamp with time zone) RETURNS TABLE(disposition text, order_id uuid, status text, plan_sequence smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_event public.earlybird_webhook_events%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
BEGIN
    IF p_event_type IS DISTINCT FROM 'payment.refunded'
       OR p_event_id IS NULL
          OR pg_catalog.char_length(p_event_id) NOT BETWEEN 1 AND 256
       OR p_idempotency_key IS NULL
          OR pg_catalog.char_length(p_idempotency_key) NOT BETWEEN 1 AND 256
       OR p_payment_id IS NULL
          OR pg_catalog.char_length(p_payment_id) NOT BETWEEN 1 AND 256
       OR p_product_id IS NULL OR p_product_id !~ '^[A-Za-z0-9_-]{1,128}$'
       OR p_amount_krw IS NULL OR p_amount_krw < 0
       OR p_refund_amount_krw IS NULL OR p_refund_amount_krw < 0
       OR p_partial_refund IS NULL
       OR p_occurred_at IS NULL OR p_refunded_at IS NULL THEN
        RAISE EXCEPTION 'GROBLE_REFUND_EVIDENCE_INVALID';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_payment_id, 0)
    );

    SELECT webhook_event.*
    INTO v_event
    FROM public.earlybird_webhook_events AS webhook_event
    WHERE webhook_event.event_id = p_event_id
       OR webhook_event.idempotency_key = p_idempotency_key
    ORDER BY webhook_event.processed_at
    LIMIT 1;
    IF FOUND THEN
        IF v_event.order_id IS NOT NULL THEN
            SELECT earlybird_order.*
            INTO v_order
            FROM public.earlybird_orders AS earlybird_order
            WHERE earlybird_order.id = v_event.order_id;
        END IF;
        RETURN QUERY SELECT
            'refund_duplicate_event'::TEXT,
            v_order.id,
            v_order.status,
            v_order.plan_sequence;
        RETURN;
    END IF;

    SELECT earlybird_order.*
    INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.payment_id = p_payment_id
    FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO public.earlybird_webhook_events (
            event_id, idempotency_key, event_type, occurred_at,
            payment_id, product_id, amount_krw,
            refund_amount_krw, partial_refund, refunded_at,
            disposition
        ) VALUES (
            p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
            p_payment_id, p_product_id, p_amount_krw,
            p_refund_amount_krw, p_partial_refund, p_refunded_at,
            'refund_unmatched'
        );
        RETURN QUERY SELECT
            'refund_unmatched'::TEXT,
            NULL::UUID,
            NULL::TEXT,
            NULL::SMALLINT;
        RETURN;
    END IF;

    IF v_order.expected_groble_product_id IS DISTINCT FROM p_product_id
       OR v_order.actual_groble_product_id IS DISTINCT FROM p_product_id
       OR v_order.actual_amount_krw IS DISTINCT FROM p_amount_krw
       OR p_refund_amount_krw > p_amount_krw
       OR (p_partial_refund IS FALSE AND p_refund_amount_krw <> p_amount_krw) THEN
        INSERT INTO public.earlybird_webhook_events (
            event_id, idempotency_key, event_type, occurred_at,
            payment_id, product_id, amount_krw,
            refund_amount_krw, partial_refund, refunded_at,
            disposition, order_id
        ) VALUES (
            p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
            p_payment_id, p_product_id, p_amount_krw,
            p_refund_amount_krw, p_partial_refund, p_refunded_at,
            'refund_mismatch', v_order.id
        );
        RETURN QUERY SELECT
            'refund_mismatch'::TEXT,
            v_order.id,
            v_order.status,
            v_order.plan_sequence;
        RETURN;
    END IF;

    IF p_partial_refund THEN
        INSERT INTO public.earlybird_webhook_events (
            event_id, idempotency_key, event_type, occurred_at,
            payment_id, product_id, amount_krw,
            refund_amount_krw, partial_refund, refunded_at,
            disposition, order_id
        ) VALUES (
            p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
            p_payment_id, p_product_id, p_amount_krw,
            p_refund_amount_krw, p_partial_refund, p_refunded_at,
            'partial_refund_recorded', v_order.id
        );
        RETURN QUERY SELECT
            'partial_refund_recorded'::TEXT,
            v_order.id,
            v_order.status,
            v_order.plan_sequence;
        RETURN;
    END IF;

    IF v_order.status IN ('paid', 'refund_pending', 'analysis_in_progress', 'completed') THEN
        UPDATE public.earlybird_orders AS earlybird_order
        SET status = 'refunded',
            updated_at = pg_catalog.clock_timestamp()
        WHERE earlybird_order.id = v_order.id
        RETURNING earlybird_order.* INTO v_order;
    ELSIF v_order.status <> 'refunded' THEN
        INSERT INTO public.earlybird_webhook_events (
            event_id, idempotency_key, event_type, occurred_at,
            payment_id, product_id, amount_krw,
            refund_amount_krw, partial_refund, refunded_at,
            disposition, order_id
        ) VALUES (
            p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
            p_payment_id, p_product_id, p_amount_krw,
            p_refund_amount_krw, p_partial_refund, p_refunded_at,
            'refund_mismatch', v_order.id
        );
        RETURN QUERY SELECT
            'refund_mismatch'::TEXT,
            v_order.id,
            v_order.status,
            v_order.plan_sequence;
        RETURN;
    END IF;

    INSERT INTO public.earlybird_webhook_events (
        event_id, idempotency_key, event_type, occurred_at,
        payment_id, product_id, amount_krw,
        refund_amount_krw, partial_refund, refunded_at,
        disposition, order_id
    ) VALUES (
        p_event_id, p_idempotency_key, p_event_type, p_occurred_at,
        p_payment_id, p_product_id, p_amount_krw,
        p_refund_amount_krw, p_partial_refund, p_refunded_at,
        'refunded', v_order.id
    );
    RETURN QUERY SELECT
        'refunded'::TEXT,
        v_order.id,
        v_order.status,
        v_order.plan_sequence;
END;
$_$;


--
-- Name: finalize_preflight_blite_source_v1(uuid, uuid, uuid, character varying, uuid, text, text, text, text, text, integer, integer, boolean, text, text, jsonb, jsonb, character varying, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_preflight_blite_source_v1(p_preflight_id uuid, p_user_id uuid, p_claim_token uuid, p_target_input_hash character varying, p_provider_run_id uuid, p_provider_operation_key text, p_provider_run_reference text, p_target_full_name text, p_target_bio text, p_target_profile_image_url text, p_target_followers_count integer, p_target_following_count integer, p_target_is_private boolean, p_capacity_required_plan_id text, p_required_plan_id text, p_plan_cards_snapshot jsonb, p_payload jsonb, p_payload_hash character varying, p_collected_at timestamp with time zone, p_expires_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_provider_run public.analysis_preflight_provider_runs%ROWTYPE;
    v_source public.precheckout_blite_sources%ROWTYPE;
    v_payload_bytes INTEGER;
    v_payload_hash VARCHAR(64);
    v_completed BOOLEAN;
BEGIN
    IF p_preflight_id IS NULL
       OR p_claim_token IS NULL
       OR p_target_input_hash IS NULL
       OR p_target_input_hash !~ '^[0-9a-f]{64}$'
       OR p_provider_run_id IS NULL
       OR p_provider_run_id IS DISTINCT FROM p_preflight_id
       OR p_provider_operation_key IS NULL
       OR NOT (
            p_provider_operation_key = 'target-profile-fallback'
            OR p_provider_operation_key ~ '^target-profile-fresh-admission:g([1-9]|[1-9][0-9]|100)$'
       )
       OR p_provider_run_reference IS NULL
       OR p_provider_run_reference !~ '^[A-Za-z0-9]{8,64}$'
       OR p_payload IS NULL
       OR pg_catalog.jsonb_typeof(p_payload) <> 'object'
       OR p_payload_hash IS NULL
       OR p_payload_hash !~ '^[0-9a-f]{64}$'
       OR p_collected_at IS NULL
       OR p_expires_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_SOURCE_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND
       OR NOT v_preflight.precheckout_blite_cohort
       OR v_preflight.pii_scrubbed_at IS NOT NULL
       OR v_preflight.submitted_at IS NULL
       OR v_preflight.deadline_at IS NULL
       OR NOT (v_preflight.deadline_at > v_now)
       OR v_preflight.target_input_hash IS DISTINCT FROM p_target_input_hash
       OR v_preflight.user_id IS DISTINCT FROM p_user_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_PREFLIGHT_FENCE_LOST', ERRCODE = 'P0001';
    END IF;

    IF p_expires_at > v_preflight.expires_at
       OR p_expires_at > p_collected_at + INTERVAL '30 minutes'
       OR p_expires_at <> LEAST(
            p_collected_at + INTERVAL '30 minutes',
            v_preflight.expires_at
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_SOURCE_EXPIRY_INVALID', ERRCODE = 'P0001';
    END IF;

    v_payload_bytes := pg_catalog.octet_length(
        pg_catalog.convert_to(p_payload::TEXT, 'UTF8')
    );
    IF v_payload_bytes > 262144 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_SOURCE_TOO_LARGE', ERRCODE = 'P0001';
    END IF;
    v_payload_hash := pg_catalog.encode(
        extensions.digest(pg_catalog.convert_to(p_payload::TEXT, 'UTF8'), 'sha256'),
        'hex'
    );

    SELECT provider_run.* INTO v_provider_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = v_preflight.id
      AND provider_run.operation_key = p_provider_operation_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_provider_run.input_hash IS DISTINCT FROM p_target_input_hash
       OR v_provider_run.logical_provider IS DISTINCT FROM 'apify'
       OR v_provider_run.status IS DISTINCT FROM 'succeeded'
       OR p_provider_run_id IS DISTINCT FROM v_provider_run.preflight_id
       OR p_provider_run_reference IS DISTINCT FROM v_provider_run.run_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_PROVIDER_LINEAGE_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT source.* INTO v_source
    FROM public.precheckout_blite_sources AS source
    WHERE source.preflight_id = v_preflight.id
    FOR UPDATE;
    IF FOUND THEN
        IF v_source.schema_version = 1
           AND v_source.target_input_hash = p_target_input_hash
           AND v_source.provider_run_id = p_provider_run_id
           AND v_source.provider_operation_key = p_provider_operation_key
           AND v_source.provider_run_reference = p_provider_run_reference
           AND v_source.payload_hash = v_payload_hash
           AND v_source.collected_at = p_collected_at
           AND v_source.expires_at = p_expires_at
           AND v_preflight.status = 'ready' THEN
            RETURN FALSE;
        END IF;
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_SOURCE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    -- Provider/source lock waits consume the same deadline as work execution.
    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.status <> 'processing'
       OR v_preflight.lease_token IS DISTINCT FROM p_claim_token
       OR v_preflight.lease_expires_at IS NULL
       OR v_preflight.lease_expires_at <= v_now
       OR v_preflight.deadline_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_PREFLIGHT_FENCE_LOST', ERRCODE = 'P0001';
    END IF;

    IF v_preflight.user_id IS NULL THEN
        v_completed := public.complete_anonymous_analysis_v2_preflight(
            p_preflight_id, p_claim_token,
            p_target_full_name, p_target_bio, p_target_profile_image_url,
            p_target_followers_count, p_target_following_count, p_target_is_private,
            p_capacity_required_plan_id, p_required_plan_id, p_plan_cards_snapshot
        );
    ELSE
        v_completed := public.complete_analysis_v2_preflight(
            p_preflight_id, p_user_id, p_claim_token,
            p_target_full_name, p_target_bio, p_target_profile_image_url,
            p_target_followers_count, p_target_following_count, p_target_is_private,
            p_capacity_required_plan_id, p_required_plan_id, p_plan_cards_snapshot
        );
    END IF;
    IF NOT v_completed THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_READY_CONFLICT', ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.precheckout_blite_sources (
        preflight_id, schema_version, target_input_hash, provider_run_id,
        provider_operation_key, provider_run_reference, payload, payload_bytes, payload_hash,
        collected_at, expires_at, created_at, updated_at
    ) VALUES (
        v_preflight.id, 1, p_target_input_hash, p_provider_run_id,
        p_provider_operation_key, p_provider_run_reference, p_payload, v_payload_bytes, v_payload_hash,
        p_collected_at, p_expires_at, v_now, v_now
    );

    INSERT INTO public.precheckout_blite_cache (
        preflight_id, state, lease_token, lease_expires_at,
        attempt_count, created_at, updated_at
    ) VALUES (
        v_preflight.id, 'pending', extensions.gen_random_uuid(), v_now,
        0, v_now, v_now
    ) ON CONFLICT (preflight_id) DO NOTHING;

    RETURN TRUE;
END;
$_$;


--
-- Name: finish_maintenance_job_v1(uuid, uuid, bigint, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_maintenance_job_v1(p_job_id uuid, p_lease_token uuid, p_lease_generation bigint, p_outcome text, p_error_code text DEFAULT NULL::text, p_retry_after_seconds integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_row public.maintenance_jobs%ROWTYPE;
    v_state TEXT;
BEGIN
    IF p_job_id IS NULL OR p_lease_token IS NULL OR p_lease_generation IS NULL OR p_lease_generation < 0
       OR p_outcome NOT IN ('succeeded', 'retryable', 'blocked')
       OR p_retry_after_seconds IS NULL OR p_retry_after_seconds < 0 OR p_retry_after_seconds > 3600 THEN
        RAISE EXCEPTION USING MESSAGE = 'MAINTENANCE_FINISH_INPUT_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT maintenance.*
    INTO v_row
    FROM public.maintenance_jobs AS maintenance
    WHERE maintenance.id = p_job_id
    FOR UPDATE;
    IF NOT FOUND OR v_row.lease_token IS DISTINCT FROM p_lease_token
       OR v_row.lease_generation IS DISTINCT FROM p_lease_generation
       OR v_row.state <> 'leased' THEN
        RAISE EXCEPTION USING MESSAGE = 'MAINTENANCE_FENCE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    v_state := CASE
        WHEN p_outcome = 'succeeded' THEN 'succeeded'
        WHEN p_outcome = 'blocked' OR v_row.attempt_count >= 1000 THEN 'blocked'
        ELSE 'retryable'
    END;
    UPDATE public.maintenance_jobs
    SET state = v_state,
        next_attempt_at = CASE WHEN v_state = 'retryable'
            THEN pg_catalog.clock_timestamp() + pg_catalog.make_interval(secs => p_retry_after_seconds)
            ELSE next_attempt_at END,
        terminal_at = CASE WHEN v_state = 'blocked' THEN pg_catalog.clock_timestamp() ELSE terminal_at END,
        last_error_code = p_error_code,
        lease_token = NULL,
        lease_holder_hash = NULL,
        lease_expires_at = NULL,
        updated_at = pg_catalog.clock_timestamp()
    WHERE id = p_job_id;
    RETURN pg_catalog.jsonb_build_object('status', v_state, 'duplicate', FALSE);
END;
$$;


--
-- Name: freeze_analysis_v2_relationships(uuid, text, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_analysis_v2_relationships(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_detailed_mutual_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_followers public.analysis_v2_relationship_sides%ROWTYPE;
    v_following public.analysis_v2_relationship_sides%ROWTYPE;
    v_manifest public.analysis_v2_relationship_manifests%ROWTYPE;
    v_excluded_username TEXT;
    v_exclusion_hash TEXT;
    v_mutual_rows JSONB;
    v_mutual_count INTEGER;
    v_public_count INTEGER;
    v_private_count INTEGER;
    v_detailed_count INTEGER;
    v_result_hash TEXT;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_job_key <> 'track:relationships:collect'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[0-9a-f]{64}$'
       OR p_detailed_mutual_limit IS NULL
       OR p_detailed_mutual_limit NOT IN (300, 600, 900) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_NOT_ACTIVE',
            ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR (v_request.analysis_scope_snapshot->>'detailedMutualLimit')::INTEGER
            IS DISTINCT FROM p_detailed_mutual_limit THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_NOT_ACTIVE',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_job.job_key <> 'track:relationships:collect'
       OR v_job.track <> 'relationships'
       OR v_job.kind <> 'collection'
       OR v_job.batch IS NOT NULL
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    v_now := pg_catalog.clock_timestamp();
    IF v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT relationship_side.*
    INTO v_followers
    FROM public.analysis_v2_relationship_sides AS relationship_side
    WHERE relationship_side.request_id = p_request_id
      AND relationship_side.job_key = p_job_key
      AND relationship_side.side = 'followers'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RELATIONSHIP_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    SELECT relationship_side.*
    INTO v_following
    FROM public.analysis_v2_relationship_sides AS relationship_side
    WHERE relationship_side.request_id = p_request_id
      AND relationship_side.job_key = p_job_key
      AND relationship_side.side = 'following'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RELATIONSHIP_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    v_excluded_username := v_request.excluded_instagram_id;
    v_exclusion_hash := pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'analysis-v2-girlfriend-exclusion-v1'
                    || pg_catalog.chr(10)
                    || CASE
                        WHEN v_excluded_username IS NULL THEN 'skip'
                        ELSE 'exclude:' || v_excluded_username
                    END,
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );

    SELECT relationship_manifest.*
    INTO v_manifest
    FROM public.analysis_v2_relationship_manifests AS relationship_manifest
    WHERE relationship_manifest.request_id = p_request_id
      AND relationship_manifest.job_key = p_job_key
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    IF FOUND THEN
        IF v_manifest.excluded_username IS DISTINCT FROM v_excluded_username
           OR v_manifest.exclusion_decision_hash IS DISTINCT FROM v_exclusion_hash
           OR v_manifest.detailed_mutual_limit IS DISTINCT FROM p_detailed_mutual_limit
           OR v_manifest.followers_result_hash IS DISTINCT FROM v_followers.result_hash
           OR v_manifest.following_result_hash IS DISTINCT FROM v_following.result_hash THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_RELATIONSHIP_FREEZE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        UPDATE public.analysis_v2_relationship_manifests AS relationship_manifest
        SET job_claim_token = p_claim_token,
            updated_at = v_now
        WHERE relationship_manifest.request_id = p_request_id
          AND relationship_manifest.job_key = p_job_key
        RETURNING relationship_manifest.* INTO v_manifest;
        RETURN public.analysis_v2_relationship_manifest_json(v_manifest);
    END IF;

    WITH intersected AS (
        SELECT
            following_row.ordinal AS following_ordinal,
            following_row.username,
            following_row.is_private,
            following_row.is_verified,
            COALESCE(following_row.full_name, follower_row.full_name) AS full_name,
            COALESCE(
                following_row.profile_pic_url,
                follower_row.profile_pic_url
            ) AS profile_pic_url
        FROM public.analysis_v2_relationship_rows AS following_row
        INNER JOIN public.analysis_v2_relationship_rows AS follower_row
            ON follower_row.request_id = following_row.request_id
           AND follower_row.job_key = following_row.job_key
           AND follower_row.side = 'followers'
           AND follower_row.username = following_row.username
        WHERE following_row.request_id = p_request_id
          AND following_row.job_key = p_job_key
          AND following_row.side = 'following'
          AND following_row.username IS DISTINCT FROM v_excluded_username
    ), numbered AS (
        SELECT
            pg_catalog.row_number() OVER (
                ORDER BY intersected.following_ordinal
            )::INTEGER AS mutual_ordinal,
            intersected.*,
            pg_catalog.count(*) FILTER (WHERE NOT intersected.is_private) OVER (
                ORDER BY intersected.following_ordinal
                ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
            )::INTEGER AS public_ordinal
        FROM intersected
    )
    SELECT
        COALESCE(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'mutual_ordinal', numbered.mutual_ordinal,
                'following_ordinal', numbered.following_ordinal,
                'username', numbered.username,
                'is_private', numbered.is_private,
                'is_verified', numbered.is_verified,
                'full_name', numbered.full_name,
                'profile_pic_url', numbered.profile_pic_url,
                'detailed_ordinal', CASE
                    WHEN NOT numbered.is_private
                     AND numbered.public_ordinal <= p_detailed_mutual_limit
                    THEN numbered.public_ordinal
                    ELSE NULL
                END
            )
            ORDER BY numbered.mutual_ordinal
        ), '[]'::JSONB),
        pg_catalog.count(*)::INTEGER,
        pg_catalog.count(*) FILTER (WHERE NOT numbered.is_private)::INTEGER,
        pg_catalog.count(*) FILTER (WHERE numbered.is_private)::INTEGER,
        pg_catalog.count(*) FILTER (
            WHERE NOT numbered.is_private
              AND numbered.public_ordinal <= p_detailed_mutual_limit
        )::INTEGER
    INTO
        v_mutual_rows,
        v_mutual_count,
        v_public_count,
        v_private_count,
        v_detailed_count
    FROM numbered;

    IF v_mutual_count > 1200 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_result_hash := public.analysis_v2_relationship_freeze_hash(
        v_followers.result_hash,
        v_following.result_hash,
        v_exclusion_hash,
        p_detailed_mutual_limit,
        v_mutual_rows
    );

    INSERT INTO public.analysis_v2_relationship_manifests (
        request_id,
        job_key,
        job_claim_token,
        excluded_username,
        exclusion_decision_hash,
        detailed_mutual_limit,
        followers_result_hash,
        following_result_hash,
        result_hash,
        mutual_count,
        public_count,
        private_count,
        detailed_public_count,
        frozen_at,
        created_at,
        updated_at
    ) VALUES (
        p_request_id,
        p_job_key,
        p_claim_token,
        v_excluded_username,
        v_exclusion_hash,
        p_detailed_mutual_limit,
        v_followers.result_hash,
        v_following.result_hash,
        v_result_hash,
        v_mutual_count,
        v_public_count,
        v_private_count,
        v_detailed_count,
        v_now,
        v_now,
        v_now
    )
    RETURNING * INTO v_manifest;

    INSERT INTO public.analysis_v2_mutual_rows (
        request_id,
        job_key,
        mutual_ordinal,
        following_ordinal,
        username,
        is_private,
        is_verified,
        full_name,
        profile_pic_url,
        detailed_ordinal
    )
    SELECT
        p_request_id,
        p_job_key,
        (mutual.value->>'mutual_ordinal')::SMALLINT,
        (mutual.value->>'following_ordinal')::SMALLINT,
        mutual.value->>'username',
        (mutual.value->>'is_private')::BOOLEAN,
        (mutual.value->>'is_verified')::BOOLEAN,
        NULLIF(mutual.value->>'full_name', ''),
        NULLIF(mutual.value->>'profile_pic_url', ''),
        CASE
            WHEN mutual.value->'detailed_ordinal' = 'null'::JSONB THEN NULL
            ELSE (mutual.value->>'detailed_ordinal')::SMALLINT
        END
    FROM pg_catalog.jsonb_array_elements(v_mutual_rows) AS mutual(value);

    RETURN public.analysis_v2_relationship_manifest_json(v_manifest);
END;
$_$;


--
-- Name: freeze_concierge_batch_cohort(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_concierge_batch_cohort(p_expected_manifest_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_cohort_key CONSTANT TEXT := 'concierge-fallback-20260816';
    v_count INTEGER;
    v_manifest_hash TEXT;
    v_existing_hash TEXT;
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    IF p_expected_manifest_hash IS NULL
       OR p_expected_manifest_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_BATCH_EXPECTED_HASH_REQUIRED', ERRCODE = 'P0001';
    END IF;
    LOCK TABLE public.earlybird_concierge_batch_cohort_members IN SHARE ROW EXCLUSIVE MODE;
    SELECT pg_catalog.count(*), pg_catalog.min(member.manifest_hash), pg_catalog.max(member.manifest_hash)
      INTO v_count, v_existing_hash, v_manifest_hash
    FROM public.earlybird_concierge_batch_cohort_members AS member
    WHERE member.cohort_key = v_cohort_key;
    IF v_count > 0 THEN
        IF v_count <> 30
           OR v_existing_hash IS NULL
           OR v_existing_hash IS DISTINCT FROM v_manifest_hash
           OR v_existing_hash IS DISTINCT FROM p_expected_manifest_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_BATCH_COHORT_MANIFEST_INVALID', ERRCODE = 'P0001';
        END IF;
        RETURN (
            SELECT pg_catalog.jsonb_build_object(
                'cohortKey', v_cohort_key,
                'manifestHash', v_existing_hash,
                'members', COALESCE(
                    pg_catalog.jsonb_agg(
                        pg_catalog.jsonb_build_object(
                            'orderId', member.order_id,
                            'ownerId', member.owner_id,
                            'targetUsername', member.target_username,
                            'planId', member.plan_id,
                            'cohort', member.cohort,
                            'preflightId', member.preflight_id,
                            'originalResultRequestId', member.original_result_request_id,
                            'targetFollowersCount', member.target_followers_count,
                            'targetFollowingCount', member.target_following_count,
                            'snapshotOrderStatus', member.snapshot_order_status,
                            'snapshotFulfillmentStatus', member.snapshot_fulfillment_status,
                            'snapshotRequestStatus', member.snapshot_request_status,
                            'snapshotErrorCode', member.snapshot_error_code,
                            'paymentIdFingerprint', member.payment_id_fingerprint,
                            'expectedAmountKrw', member.expected_amount_krw,
                            'expectedProductId', member.expected_product_id,
                            'actualAmountKrw', member.actual_amount_krw,
                            'actualProductId', member.actual_product_id,
                            'paidAt', member.paid_at,
                            'evidenceHash', member.evidence_hash,
                            'manifestHash', member.manifest_hash,
                            'frozenAt', member.frozen_at,
                            'currentOrderStatus', earlybird_order.status,
                            'currentFulfillmentStatus', fulfillment.status,
                            'currentRequestStatus', request.status,
                            'published', (
                                earlybird_order.status = 'completed'
                                OR COALESCE(request.step_data#>>'{conciergeBatchPublication,version}', '0') ~ '^[1-9][0-9]*$'
                            )
                        ) ORDER BY member.order_id
                    ), '[]'::JSONB
                )
            )
            FROM public.earlybird_concierge_batch_cohort_members AS member
            JOIN public.earlybird_orders AS earlybird_order
              ON earlybird_order.id = member.order_id
            JOIN public.earlybird_fulfillments AS fulfillment
              ON fulfillment.order_id = member.order_id
            LEFT JOIN public.analysis_requests AS request
              ON request.id = earlybird_order.result_request_id
            WHERE member.cohort_key = v_cohort_key
        );
    END IF;

    -- Lock only the exact first-pass candidate shape before counting or
    -- hashing. Any concurrent payment/refund/status mutation therefore either
    -- waits for this transaction or is rejected by the rechecked count.
    PERFORM earlybird_order.id
    FROM public.earlybird_orders AS earlybird_order
    JOIN public.earlybird_fulfillments AS fulfillment
      ON fulfillment.order_id = earlybird_order.id
    LEFT JOIN public.analysis_requests AS request
      ON request.id = earlybird_order.result_request_id
    WHERE earlybird_order.paid_at IS NOT NULL
      AND earlybird_order.payment_id IS NOT NULL
      AND earlybird_order.target_instagram_id ~ '^[a-z0-9._]{1,30}$'
      AND earlybird_order.plan_id IN ('basic', 'standard')
      AND (
          (earlybird_order.status = 'paid'
           AND fulfillment.status = 'awaiting_operator'
           AND earlybird_order.result_request_id IS NULL)
          OR (
              earlybird_order.status = 'analysis_in_progress'
              AND fulfillment.status = 'analysis_in_progress'
              AND request.id = earlybird_order.result_request_id
              AND request.pipeline_version = 'v2'
              AND request.status = 'failed'
              AND request.current_step = 'failed'
              AND public.earlybird_concierge_batch_failed_request_eligible(request.id, request.error_message, fulfillment.request_id, request.user_id, earlybird_order.user_id, request.preflight_id, earlybird_order.preflight_id, request.target_instagram_id, earlybird_order.target_instagram_id)
          )
      )
    FOR UPDATE OF earlybird_order, fulfillment;

    PERFORM request.id
    FROM public.analysis_requests AS request
    JOIN public.earlybird_orders AS earlybird_order
      ON earlybird_order.result_request_id = request.id
    JOIN public.earlybird_fulfillments AS fulfillment
      ON fulfillment.order_id = earlybird_order.id
    WHERE earlybird_order.paid_at IS NOT NULL
      AND earlybird_order.payment_id IS NOT NULL
      AND earlybird_order.status = 'analysis_in_progress'
      AND fulfillment.status = 'analysis_in_progress'
      AND request.pipeline_version = 'v2'
      AND request.status = 'failed'
      AND request.current_step = 'failed'
      AND public.earlybird_concierge_batch_failed_request_eligible(request.id, request.error_message, fulfillment.request_id, request.user_id, earlybird_order.user_id, request.preflight_id, earlybird_order.preflight_id, request.target_instagram_id, earlybird_order.target_instagram_id)
    FOR UPDATE OF request;

    SELECT pg_catalog.count(*)
      INTO v_count
    FROM public.earlybird_orders AS earlybird_order
    JOIN public.earlybird_fulfillments AS fulfillment
      ON fulfillment.order_id = earlybird_order.id
    LEFT JOIN public.analysis_requests AS request
      ON request.id = earlybird_order.result_request_id
    WHERE earlybird_order.paid_at IS NOT NULL
      AND earlybird_order.payment_id IS NOT NULL
      AND earlybird_order.target_instagram_id ~ '^[a-z0-9._]{1,30}$'
      AND earlybird_order.plan_id IN ('basic', 'standard')
      AND (
          (earlybird_order.status = 'paid'
           AND fulfillment.status = 'awaiting_operator'
           AND earlybird_order.result_request_id IS NULL)
          OR (
              earlybird_order.status = 'analysis_in_progress'
              AND fulfillment.status = 'analysis_in_progress'
              AND request.id = earlybird_order.result_request_id
              AND request.pipeline_version = 'v2'
              AND request.status = 'failed'
              AND request.current_step = 'failed'
              AND public.earlybird_concierge_batch_failed_request_eligible(request.id, request.error_message, fulfillment.request_id, request.user_id, earlybird_order.user_id, request.preflight_id, earlybird_order.preflight_id, request.target_instagram_id, earlybird_order.target_instagram_id)
          )
      );
    IF v_count <> 30 THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_BATCH_COHORT_COUNT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
        pg_catalog.string_agg(
            pg_catalog.concat_ws('|',
                earlybird_order.id::TEXT,
                earlybird_order.user_id::TEXT,
                pg_catalog.lower(pg_catalog.btrim(earlybird_order.target_instagram_id)),
                earlybird_order.plan_id,
                CASE
                    WHEN earlybird_order.status = 'paid' THEN 'awaiting_operator'
                    ELSE 'failed_canary'
                END,
                earlybird_order.preflight_id::TEXT,
                COALESCE(earlybird_order.result_request_id::TEXT, ''),
                earlybird_order.target_followers_count::TEXT,
                earlybird_order.target_following_count::TEXT,
                earlybird_order.status,
                fulfillment.status,
                COALESCE(request.status, ''),
                COALESCE(request.error_message, ''),
                pg_catalog.encode(extensions.digest(pg_catalog.convert_to(earlybird_order.payment_id, 'UTF8'), 'sha256'), 'hex'),
                earlybird_order.expected_amount_krw::TEXT,
                earlybird_order.expected_groble_product_id,
                COALESCE(earlybird_order.actual_amount_krw::TEXT, ''),
                COALESCE(earlybird_order.actual_groble_product_id, ''),
                earlybird_order.paid_at::TEXT
            ), '||' ORDER BY earlybird_order.id
        ), 'UTF8'), 'sha256'), 'hex')
    INTO v_manifest_hash
    FROM public.earlybird_orders AS earlybird_order
    JOIN public.earlybird_fulfillments AS fulfillment
      ON fulfillment.order_id = earlybird_order.id
    LEFT JOIN public.analysis_requests AS request
      ON request.id = earlybird_order.result_request_id
    WHERE earlybird_order.paid_at IS NOT NULL
      AND earlybird_order.payment_id IS NOT NULL
      AND earlybird_order.target_instagram_id ~ '^[a-z0-9._]{1,30}$'
      AND earlybird_order.plan_id IN ('basic', 'standard')
      AND (
          (earlybird_order.status = 'paid'
           AND fulfillment.status = 'awaiting_operator'
           AND earlybird_order.result_request_id IS NULL)
          OR (
              earlybird_order.status = 'analysis_in_progress'
              AND fulfillment.status = 'analysis_in_progress'
              AND request.id = earlybird_order.result_request_id
              AND request.pipeline_version = 'v2'
              AND request.status = 'failed'
              AND request.current_step = 'failed'
              AND public.earlybird_concierge_batch_failed_request_eligible(request.id, request.error_message, fulfillment.request_id, request.user_id, earlybird_order.user_id, request.preflight_id, earlybird_order.preflight_id, request.target_instagram_id, earlybird_order.target_instagram_id)
          )
      );

    IF v_manifest_hash IS DISTINCT FROM p_expected_manifest_hash THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_BATCH_COHORT_EXPECTED_HASH_CONFLICT', ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.earlybird_concierge_batch_cohort_members (
        cohort_key, order_id, owner_id, target_username, plan_id, cohort,
        preflight_id, original_result_request_id, target_followers_count,
        target_following_count, snapshot_order_status, snapshot_fulfillment_status,
        snapshot_request_status, snapshot_error_code, payment_id_fingerprint,
        expected_amount_krw, expected_product_id, actual_amount_krw,
        actual_product_id, paid_at, evidence_hash, manifest_hash, frozen_at
    )
    SELECT v_cohort_key,
        earlybird_order.id,
        earlybird_order.user_id,
        pg_catalog.lower(pg_catalog.btrim(earlybird_order.target_instagram_id)),
        earlybird_order.plan_id,
        CASE WHEN earlybird_order.status = 'paid' THEN 'awaiting_operator' ELSE 'failed_canary' END,
        earlybird_order.preflight_id,
        earlybird_order.result_request_id,
        earlybird_order.target_followers_count,
        earlybird_order.target_following_count,
        earlybird_order.status,
        fulfillment.status,
        request.status,
        request.error_message,
        pg_catalog.encode(extensions.digest(pg_catalog.convert_to(earlybird_order.payment_id, 'UTF8'), 'sha256'), 'hex'),
        earlybird_order.expected_amount_krw,
        earlybird_order.expected_groble_product_id,
        earlybird_order.actual_amount_krw,
        earlybird_order.actual_groble_product_id,
        earlybird_order.paid_at,
        pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
            pg_catalog.concat_ws('|', earlybird_order.id::TEXT, earlybird_order.user_id::TEXT,
                pg_catalog.lower(pg_catalog.btrim(earlybird_order.target_instagram_id)),
                earlybird_order.preflight_id::TEXT, earlybird_order.payment_id,
                earlybird_order.paid_at::TEXT), 'UTF8'), 'sha256'), 'hex'),
        v_manifest_hash,
        v_now
    FROM public.earlybird_orders AS earlybird_order
    JOIN public.earlybird_fulfillments AS fulfillment
      ON fulfillment.order_id = earlybird_order.id
    LEFT JOIN public.analysis_requests AS request
      ON request.id = earlybird_order.result_request_id
    WHERE earlybird_order.paid_at IS NOT NULL
      AND earlybird_order.payment_id IS NOT NULL
      AND earlybird_order.target_instagram_id ~ '^[a-z0-9._]{1,30}$'
      AND earlybird_order.plan_id IN ('basic', 'standard')
      AND (
          (earlybird_order.status = 'paid'
           AND fulfillment.status = 'awaiting_operator'
           AND earlybird_order.result_request_id IS NULL)
          OR (
              earlybird_order.status = 'analysis_in_progress'
              AND fulfillment.status = 'analysis_in_progress'
              AND request.id = earlybird_order.result_request_id
              AND request.pipeline_version = 'v2'
              AND request.status = 'failed'
              AND request.current_step = 'failed'
              AND public.earlybird_concierge_batch_failed_request_eligible(request.id, request.error_message, fulfillment.request_id, request.user_id, earlybird_order.user_id, request.preflight_id, earlybird_order.preflight_id, request.target_instagram_id, earlybird_order.target_instagram_id)
          )
      );

    RETURN (
        SELECT pg_catalog.jsonb_build_object(
            'cohortKey', v_cohort_key,
            'manifestHash', v_manifest_hash,
            'members', COALESCE(
                pg_catalog.jsonb_agg(
                    pg_catalog.jsonb_build_object(
                        'orderId', member.order_id,
                        'ownerId', member.owner_id,
                        'targetUsername', member.target_username,
                        'planId', member.plan_id,
                        'cohort', member.cohort,
                        'preflightId', member.preflight_id,
                        'originalResultRequestId', member.original_result_request_id,
                        'targetFollowersCount', member.target_followers_count,
                        'targetFollowingCount', member.target_following_count,
                        'snapshotOrderStatus', member.snapshot_order_status,
                        'snapshotFulfillmentStatus', member.snapshot_fulfillment_status,
                        'snapshotRequestStatus', member.snapshot_request_status,
                        'snapshotErrorCode', member.snapshot_error_code,
                        'paymentIdFingerprint', member.payment_id_fingerprint,
                        'expectedAmountKrw', member.expected_amount_krw,
                        'expectedProductId', member.expected_product_id,
                        'actualAmountKrw', member.actual_amount_krw,
                        'actualProductId', member.actual_product_id,
                        'paidAt', member.paid_at,
                        'evidenceHash', member.evidence_hash,
                        'manifestHash', member.manifest_hash,
                        'frozenAt', member.frozen_at,
                        'currentOrderStatus', earlybird_order.status,
                        'currentFulfillmentStatus', fulfillment.status,
                        'currentRequestStatus', request.status,
                        'published', (
                            earlybird_order.status = 'completed'
                            OR COALESCE(request.step_data#>>'{conciergeBatchPublication,version}', '0') ~ '^[1-9][0-9]*$'
                        )
                    ) ORDER BY member.order_id
                ), '[]'::JSONB
            )
        )
        FROM public.earlybird_concierge_batch_cohort_members AS member
        JOIN public.earlybird_orders AS earlybird_order
          ON earlybird_order.id = member.order_id
        JOIN public.earlybird_fulfillments AS fulfillment
          ON fulfillment.order_id = member.order_id
        LEFT JOIN public.analysis_requests AS request
          ON request.id = earlybird_order.result_request_id
        WHERE member.cohort_key = v_cohort_key
    );
END;
$_$;


--
-- Name: guard_analysis_beta_pool_reservation_headroom(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_analysis_beta_pool_reservation_headroom() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_snapshot public.analysis_apify_credit_snapshots%ROWTYPE;
    v_capacity NUMERIC;
    v_locked INTEGER := 0;
BEGIN
    PERFORM public.analysis_beta_pool_lock();
    FOR v_snapshot IN
        SELECT snapshot.* FROM public.analysis_apify_credit_snapshots AS snapshot
        WHERE public.analysis_beta_valid_apify_credential_slot(snapshot.credential_slot)
        ORDER BY CASE snapshot.credential_slot
            WHEN 'primary' THEN 1 WHEN 'tertiary' THEN 2
            WHEN 'quaternary' THEN 3 WHEN 'quinary' THEN 4
            WHEN 'senary' THEN 5 WHEN 'septenary' THEN 6
            WHEN 'octonary' THEN 7 WHEN 'nonary' THEN 8 WHEN 'tenth' THEN 9
        END
        FOR UPDATE
    LOOP
        v_locked := v_locked + 1;
    END LOOP;
    IF v_locked <> 9 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INCOMPLETE', ERRCODE = 'P0001';
    END IF;
    SELECT snapshot.* INTO v_snapshot
    FROM public.analysis_apify_credit_snapshots AS snapshot
    WHERE snapshot.credential_slot = NEW.credential_slot;
    SELECT capacity.effective_capacity_usd INTO v_capacity
    FROM public.analysis_beta_pool_effective_capacity_snapshot() AS capacity
    WHERE capacity.credential_slot = NEW.credential_slot;
    IF NOT FOUND
       OR v_snapshot.health_state IS DISTINCT FROM 'healthy'
       OR v_snapshot.observed_at IS NULL
       OR public.analysis_apify_account_is_excluded(NEW.credential_slot)
       OR v_capacity IS NULL
       OR v_capacity < NEW.reserved_usd THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_CAPACITY_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_analysis_v2_provider_run_manual_resolution_immutability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_analysis_v2_provider_run_manual_resolution_immutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    IF OLD.manual_resolution_kind IS NOT NULL
       AND (
           NEW.manual_resolution_kind IS DISTINCT FROM OLD.manual_resolution_kind
           OR NEW.manual_resolution_evidence_hash IS DISTINCT FROM OLD.manual_resolution_evidence_hash
           OR NEW.manual_resolved_at IS DISTINCT FROM OLD.manual_resolved_at
           OR NEW.actual_usage_usd IS DISTINCT FROM OLD.actual_usage_usd
           OR NEW.usage_reconciled_at IS DISTINCT FROM OLD.usage_reconciled_at
           OR NEW.max_charge_usd IS DISTINCT FROM OLD.max_charge_usd
           OR NEW.input_hash IS DISTINCT FROM OLD.input_hash
           OR NEW.job_claim_token IS DISTINCT FROM OLD.job_claim_token
           OR NEW.reservation_token IS DISTINCT FROM OLD.reservation_token
           OR NEW.actor_id IS DISTINCT FROM OLD.actor_id
           OR NEW.reserved_at IS DISTINCT FROM OLD.reserved_at
           OR NEW.request_id IS DISTINCT FROM OLD.request_id
           OR NEW.job_key IS DISTINCT FROM OLD.job_key
           OR NEW.operation_key IS DISTINCT FROM OLD.operation_key
           OR NEW.status IS DISTINCT FROM OLD.status
           OR NEW.run_id IS DISTINCT FROM OLD.run_id
           OR NEW.run_started_at IS DISTINCT FROM OLD.run_started_at
           OR NEW.terminalized_at IS DISTINCT FROM OLD.terminalized_at
           OR NEW.logical_provider IS DISTINCT FROM OLD.logical_provider
           OR NEW.credential_slot IS DISTINCT FROM OLD.credential_slot
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_MANUAL_RESOLUTION_IMMUTABLE';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_earlybird_checkout_block_marker(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_earlybird_checkout_block_marker() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.checkout_blocked_at IS NULL
           AND NEW.checkout_blocked_reason IS NULL THEN
            RETURN NEW;
        END IF;
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
            ERRCODE = 'P0001';
    END IF;

    IF OLD.checkout_blocked_at IS NULL
       AND OLD.checkout_blocked_reason IS NULL THEN
        IF NEW.checkout_blocked_at IS NULL
           AND NEW.checkout_blocked_reason IS NULL THEN
            RETURN NEW;
        END IF;

        IF OLD.status <> 'payment_pending'
           OR NEW.status <> 'payment_pending'
           OR NEW.checkout_blocked_at IS NULL
           OR NEW.checkout_blocked_reason IS DISTINCT FROM 'SUPERSEDED_LINEAGE'
           OR OLD.payment_id IS NOT NULL
           OR OLD.actual_groble_product_id IS NOT NULL
           OR OLD.actual_amount_krw IS NOT NULL
           OR OLD.paid_at IS NOT NULL
           OR OLD.seller_reference_confirmed_at IS NOT NULL
           OR NEW.payment_id IS NOT NULL
           OR NEW.actual_groble_product_id IS NOT NULL
           OR NEW.actual_amount_krw IS NOT NULL
           OR NEW.paid_at IS NOT NULL
           OR NEW.seller_reference_confirmed_at IS NOT NULL
           OR NEW.checkout_blocked_at IS NULL
           OR EXISTS (
               SELECT 1
               FROM public.earlybird_fulfillments AS fulfillment
               WHERE fulfillment.order_id = NEW.id
           )
           OR EXISTS (
               SELECT 1
               FROM public.analysis_requests AS analysis_request
               WHERE analysis_request.id IN (OLD.result_request_id, NEW.result_request_id)
           )
           OR EXISTS (
               SELECT 1
               FROM public.earlybird_webhook_events AS webhook_event
               WHERE webhook_event.order_id = NEW.id
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
                ERRCODE = 'P0001';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.checkout_blocked_at IS NOT NULL
       AND OLD.checkout_blocked_reason = 'SUPERSEDED_LINEAGE' THEN
        IF NEW.checkout_blocked_at IS DISTINCT FROM OLD.checkout_blocked_at
           OR NEW.checkout_blocked_reason IS DISTINCT FROM OLD.checkout_blocked_reason THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_IMMUTABLE',
                ERRCODE = 'P0001';
        END IF;
        RETURN NEW;
    END IF;

    RAISE EXCEPTION USING
        MESSAGE = 'EARLYBIRD_CHECKOUT_SUPERSESSION_MARKER_FAILED',
        ERRCODE = 'P0001';
END;
$$;


--
-- Name: guard_legacy_fresh_admission_provider_run_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_legacy_fresh_admission_provider_run_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF NEW.operation_key <> 'target-profile-fallback' THEN
        RETURN NEW;
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = NEW.preflight_id;
    IF FOUND
       AND v_preflight.status = 'ready'
       AND v_preflight.admission_status = 'processing'
       AND v_preflight.admission_generation BETWEEN 1 AND 100
       AND v_preflight.admission_requested_at IS NOT NULL
       AND NEW.reserved_at >= v_preflight.admission_requested_at
       AND EXISTS (
           SELECT 1
           FROM public.analysis_preflight_provider_runs AS current_generation
           WHERE current_generation.preflight_id = NEW.preflight_id
             AND current_generation.operation_key =
                'target-profile-fresh-admission:g'
                    || v_preflight.admission_generation::TEXT
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_LEGACY_FRESH_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: hold_analysis_beta_apify_preflight_credit(uuid, uuid, text, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hold_analysis_beta_apify_preflight_credit(p_preflight_id uuid, p_user_id uuid, p_credential_slot text, p_target_profile_budget_usd numeric, p_max_snapshot_age_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
BEGIN
    -- The historical signature cannot carry the persisted generation/token
    -- and claim token. Keep it present for schema compatibility, but make it
    -- unusable after the fenced lifecycle is installed.
    RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_PREPARE_REQUIRED', ERRCODE='P0001';
END;
$$;


--
-- Name: hold_analysis_beta_apify_preflight_credit_pre_capacity_hardenin(uuid, uuid, text, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hold_analysis_beta_apify_preflight_credit_pre_capacity_hardenin(p_preflight_id uuid, p_user_id uuid, p_credential_slot text, p_target_profile_budget_usd numeric, p_max_snapshot_age_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_existing public.analysis_beta_pool_allocations%ROWTYPE;
    v_created public.analysis_beta_pool_allocations%ROWTYPE;
    v_existing_reservation public.analysis_beta_pool_reservations%ROWTYPE;
    v_grant public.analysis_beta_access_grants%ROWTYPE;
    v_locked_snapshot public.analysis_apify_credit_snapshots%ROWTYPE;
    v_selected_snapshot public.analysis_apify_credit_snapshots%ROWTYPE;
    v_common_observed_at TIMESTAMP WITH TIME ZONE;
    v_lock_count INTEGER := 0;
    v_snapshot_unhealthy BOOLEAN := FALSE;
    v_snapshot_stale BOOLEAN := FALSE;
    v_snapshot_split BOOLEAN := FALSE;
    v_reserved_usd NUMERIC := 0;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_credential_slot IS NULL
       OR NOT public.analysis_beta_valid_apify_credential_slot(
            p_credential_slot
       )
       OR p_target_profile_budget_usd IS NULL
       OR p_target_profile_budget_usd NOT BETWEEN 0.000000000001 AND 1000
       OR p_target_profile_budget_usd
            <> pg_catalog.round(p_target_profile_budget_usd, 12)
       OR p_max_snapshot_age_seconds IS NULL
       OR NOT (p_max_snapshot_age_seconds BETWEEN 1 AND 900) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_ALLOCATION_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- Match the repository-wide user -> preflight lock order. The eventual
    -- allocation insert needs this same KEY SHARE lock for its user FK; taking
    -- it first avoids a cycle with concurrent user deletion and its cascades.
    PERFORM users.id
    FROM public.users AS users
    WHERE users.id = p_user_id
    FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_PREFLIGHT_NOT_ELIGIBLE',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_PREFLIGHT_NOT_ELIGIBLE',
            ERRCODE = 'P0001';
    END IF;

    SELECT allocation.*
    INTO v_existing
    FROM public.analysis_beta_pool_allocations AS allocation
    WHERE allocation.preflight_id = p_preflight_id
    FOR UPDATE;
    IF FOUND THEN
        SELECT reservation.*
        INTO v_existing_reservation
        FROM public.analysis_beta_pool_reservations AS reservation
        WHERE reservation.allocation_id = v_existing.id
          AND reservation.operation_family = 'target-profile'
        FOR UPDATE;

        IF NOT FOUND
           OR v_existing.user_id IS DISTINCT FROM p_user_id
           OR v_existing.policy_version
                IS DISTINCT FROM 'betatest-free-pool-v1'
           OR v_existing_reservation.credential_slot
                IS DISTINCT FROM p_credential_slot
           OR v_existing_reservation.reserved_usd
                IS DISTINCT FROM p_target_profile_budget_usd THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT',
                ERRCODE = 'P0001';
        END IF;

        RETURN public.analysis_beta_pool_allocation_json(v_existing);
    END IF;

    IF p_target_profile_budget_usd IS DISTINCT FROM 0.005200000000
       OR v_preflight.user_id IS DISTINCT FROM p_user_id
       OR v_preflight.status IS DISTINCT FROM 'pending'
       OR v_preflight.access_mode IS DISTINCT FROM 'production'
       OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'standard'
       OR v_preflight.dispatch_state IS DISTINCT FROM 'unreserved'
       OR v_preflight.dispatch_generation <> 0
       OR v_preflight.dispatch_token IS NOT NULL
       OR v_preflight.dispatch_reserved_at IS NOT NULL
       OR v_preflight.dispatched_at IS NOT NULL
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.expires_at <= v_now
       OR EXISTS (
            SELECT 1
            FROM public.analysis_preflight_provider_runs AS provider_run
            WHERE provider_run.preflight_id = p_preflight_id
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_PREFLIGHT_NOT_ELIGIBLE',
            ERRCODE = 'P0001';
    END IF;

    SELECT grant_row.*
    INTO v_grant
    FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_ACCESS_UNAVAILABLE',
            ERRCODE = 'P0001';
    END IF;

    FOR v_locked_snapshot IN
        SELECT snapshot.*
        FROM public.analysis_apify_credit_snapshots AS snapshot
        ORDER BY CASE snapshot.credential_slot
            WHEN 'primary' THEN 1
            WHEN 'tertiary' THEN 2
            WHEN 'quaternary' THEN 3
            WHEN 'quinary' THEN 4
            WHEN 'senary' THEN 5
            WHEN 'septenary' THEN 6
        END
        FOR UPDATE
    LOOP
        v_lock_count := v_lock_count + 1;
        IF v_locked_snapshot.credential_slot = p_credential_slot THEN
            v_selected_snapshot := v_locked_snapshot;
        END IF;
        IF v_locked_snapshot.health_state <> 'healthy'
           OR v_locked_snapshot.monthly_limit_usd IS NULL
           OR v_locked_snapshot.monthly_usage_usd IS NULL
           OR v_locked_snapshot.billing_cycle_start_at IS NULL
           OR v_locked_snapshot.billing_cycle_end_at IS NULL
           OR v_locked_snapshot.observed_at IS NULL THEN
            v_snapshot_unhealthy := TRUE;
        ELSE
            IF v_common_observed_at IS NULL THEN
                v_common_observed_at := v_locked_snapshot.observed_at;
            ELSIF v_locked_snapshot.observed_at
                    IS DISTINCT FROM v_common_observed_at THEN
                v_snapshot_split := TRUE;
            END IF;
        END IF;
    END LOOP;

    -- Refresh database time only after the current grant and all six snapshot
    -- rows are locked. Recheck every time-sensitive predicate on those locked
    -- values so lock waits cannot turn an expired state into an admission.
    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_PREFLIGHT_NOT_ELIGIBLE',
            ERRCODE = 'P0001';
    END IF;
    IF v_grant.enabled IS DISTINCT FROM TRUE
       OR (
            v_grant.expires_at IS NOT NULL
            AND (
                NOT pg_catalog.isfinite(v_grant.expires_at)
                OR v_grant.expires_at <= v_now
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_ACCESS_UNAVAILABLE',
            ERRCODE = 'P0001';
    END IF;

    FOR v_locked_snapshot IN
        SELECT snapshot.*
        FROM public.analysis_apify_credit_snapshots AS snapshot
        ORDER BY CASE snapshot.credential_slot
            WHEN 'primary' THEN 1
            WHEN 'tertiary' THEN 2
            WHEN 'quaternary' THEN 3
            WHEN 'quinary' THEN 4
            WHEN 'senary' THEN 5
            WHEN 'septenary' THEN 6
        END
    LOOP
        IF v_locked_snapshot.observed_at < v_now
                - pg_catalog.make_interval(
                    secs => p_max_snapshot_age_seconds
                )
           OR v_locked_snapshot.observed_at > v_now + INTERVAL '1 minute'
           OR v_locked_snapshot.billing_cycle_start_at > v_now
           OR v_locked_snapshot.billing_cycle_end_at <= v_now THEN
            v_snapshot_stale := TRUE;
        END IF;
    END LOOP;

    IF v_lock_count <> 6 OR v_snapshot_split THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INCOMPLETE',
            ERRCODE = 'P0001';
    END IF;
    IF v_snapshot_unhealthy THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_UNHEALTHY',
            ERRCODE = 'P0001';
    END IF;
    IF v_snapshot_stale THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_STALE',
            ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(pg_catalog.sum(reservation.reserved_usd), 0::NUMERIC)
    INTO v_reserved_usd
    FROM public.analysis_beta_pool_reservations AS reservation
    WHERE reservation.credential_slot = p_credential_slot
      AND reservation.lifecycle_state IN ('preflight_held', 'active');

    IF v_selected_snapshot.monthly_limit_usd
            - v_selected_snapshot.monthly_usage_usd
            - v_reserved_usd
            < p_target_profile_budget_usd THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_POOL_CAPACITY_UNAVAILABLE',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET analysis_entry_channel = 'betatest'
    WHERE preflight.id = p_preflight_id;

    INSERT INTO public.analysis_beta_pool_allocations (
        preflight_id,
        user_id,
        lifecycle_state,
        policy_version,
        expires_at,
        created_at,
        updated_at
    ) VALUES (
        p_preflight_id,
        p_user_id,
        'preflight_held',
        'betatest-free-pool-v1',
        v_preflight.expires_at,
        v_now,
        v_now
    )
    RETURNING * INTO v_created;

    INSERT INTO public.analysis_beta_pool_reservations (
        allocation_id,
        operation_family,
        credential_slot,
        reserved_usd,
        lifecycle_state,
        created_at,
        updated_at
    ) VALUES (
        v_created.id,
        'target-profile',
        p_credential_slot,
        p_target_profile_budget_usd,
        'preflight_held',
        v_now,
        v_now
    );

    RETURN public.analysis_beta_pool_allocation_json(v_created);
END;
$$;


--
-- Name: hold_analysis_beta_apify_preflight_credit_unfenced_20260802(uuid, uuid, text, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hold_analysis_beta_apify_preflight_credit_unfenced_20260802(p_preflight_id uuid, p_user_id uuid, p_credential_slot text, p_target_profile_budget_usd numeric, p_max_snapshot_age_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_existing public.analysis_beta_pool_allocations%ROWTYPE;
    v_created public.analysis_beta_pool_allocations%ROWTYPE;
    v_existing_reservation public.analysis_beta_pool_reservations%ROWTYPE;
    v_grant public.analysis_beta_access_grants%ROWTYPE;
    v_locked_snapshot public.analysis_apify_credit_snapshots%ROWTYPE;
    v_lock_count INTEGER := 0;
    v_selected_slot TEXT;
    v_capacity NUMERIC;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR (p_credential_slot IS NOT NULL
           AND NOT public.analysis_beta_valid_apify_credential_slot(p_credential_slot))
       OR p_target_profile_budget_usd IS NULL
       OR p_target_profile_budget_usd NOT BETWEEN 0.000000000001 AND 1000
       OR p_target_profile_budget_usd <> pg_catalog.round(p_target_profile_budget_usd, 12)
       OR p_max_snapshot_age_seconds IS NULL
       OR p_max_snapshot_age_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ALLOCATION_INVALID', ERRCODE = 'P0001';
    END IF;

    PERFORM users.id FROM public.users AS users WHERE users.id = p_user_id FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_PREFLIGHT_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_PREFLIGHT_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    SELECT allocation.* INTO v_existing
    FROM public.analysis_beta_pool_allocations AS allocation
    WHERE allocation.preflight_id = p_preflight_id
    FOR UPDATE;
    IF FOUND THEN
        SELECT reservation.* INTO v_existing_reservation
        FROM public.analysis_beta_pool_reservations AS reservation
        WHERE reservation.allocation_id = v_existing.id
          AND reservation.operation_family = 'target-profile'
        FOR UPDATE;
        IF NOT FOUND
           OR v_existing.user_id IS DISTINCT FROM p_user_id
           OR v_existing.policy_version IS DISTINCT FROM 'betatest-free-pool-v1'
           OR (p_credential_slot IS NOT NULL
               AND v_existing_reservation.credential_slot IS DISTINCT FROM p_credential_slot)
           OR v_existing_reservation.reserved_usd IS DISTINCT FROM p_target_profile_budget_usd THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_beta_pool_allocation_json(v_existing);
    END IF;

    IF p_target_profile_budget_usd IS DISTINCT FROM 0.005200000000
       OR v_preflight.user_id IS DISTINCT FROM p_user_id
       OR v_preflight.status IS DISTINCT FROM 'pending'
       OR v_preflight.access_mode IS DISTINCT FROM 'production'
       OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'standard'
       OR v_preflight.dispatch_state IS DISTINCT FROM 'unreserved'
       OR v_preflight.dispatch_generation <> 0
       OR v_preflight.dispatch_token IS NOT NULL
       OR v_preflight.dispatch_reserved_at IS NOT NULL
       OR v_preflight.dispatched_at IS NOT NULL
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.expires_at <= v_now
       OR EXISTS (
            SELECT 1 FROM public.analysis_preflight_provider_runs AS provider_run
            WHERE provider_run.preflight_id = p_preflight_id
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_PREFLIGHT_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    SELECT grant_row.* INTO v_grant
    FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ACCESS_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;

    PERFORM public.analysis_beta_pool_lock();
    FOR v_locked_snapshot IN
        SELECT snapshot.*
        FROM public.analysis_apify_credit_snapshots AS snapshot
        WHERE public.analysis_beta_valid_apify_credential_slot(snapshot.credential_slot)
        ORDER BY CASE snapshot.credential_slot
            WHEN 'primary' THEN 1 WHEN 'tertiary' THEN 2
            WHEN 'quaternary' THEN 3 WHEN 'quinary' THEN 4
            WHEN 'senary' THEN 5 WHEN 'septenary' THEN 6
            WHEN 'octonary' THEN 7 WHEN 'nonary' THEN 8 WHEN 'tenth' THEN 9
        END
        FOR UPDATE
    LOOP
        v_lock_count := v_lock_count + 1;
    END LOOP;

    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_PREFLIGHT_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;
    IF v_grant.enabled IS DISTINCT FROM TRUE
       OR (v_grant.expires_at IS NOT NULL AND (
            NOT pg_catalog.isfinite(v_grant.expires_at) OR v_grant.expires_at <= v_now
       )) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ACCESS_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;
    IF v_lock_count <> 9 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INCOMPLETE', ERRCODE = 'P0001';
    END IF;

    SELECT capacity.credential_slot, capacity.effective_capacity_usd
    INTO v_selected_slot, v_capacity
    FROM public.analysis_beta_pool_effective_capacity_snapshot() AS capacity
    JOIN public.analysis_apify_credit_snapshots AS snapshot
      ON snapshot.credential_slot = capacity.credential_slot
    WHERE snapshot.health_state = 'healthy'
      AND snapshot.monthly_limit_usd IS NOT NULL
      AND snapshot.monthly_usage_usd IS NOT NULL
      AND snapshot.observed_at IS NOT NULL
      AND snapshot.billing_cycle_start_at <= v_now
      AND snapshot.billing_cycle_end_at > v_now
      AND snapshot.observed_at >= v_now - pg_catalog.make_interval(secs => p_max_snapshot_age_seconds)
      AND snapshot.observed_at <= v_now + INTERVAL '1 minute'
      AND snapshot.manually_excluded IS NOT TRUE
      AND capacity.effective_capacity_usd >= p_target_profile_budget_usd
      AND (p_credential_slot IS NULL OR capacity.credential_slot = p_credential_slot)
    ORDER BY capacity.effective_capacity_usd - p_target_profile_budget_usd,
        CASE capacity.credential_slot
            WHEN 'primary' THEN 1 WHEN 'tertiary' THEN 2
            WHEN 'quaternary' THEN 3 WHEN 'quinary' THEN 4
            WHEN 'senary' THEN 5 WHEN 'septenary' THEN 6
            WHEN 'octonary' THEN 7 WHEN 'nonary' THEN 8 WHEN 'tenth' THEN 9
        END
    LIMIT 1;
    IF v_selected_slot IS NULL OR v_capacity < p_target_profile_budget_usd THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_CAPACITY_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET analysis_entry_channel = 'betatest'
    WHERE preflight.id = p_preflight_id;
    INSERT INTO public.analysis_beta_pool_allocations(
        preflight_id, user_id, lifecycle_state, policy_version,
        expires_at, created_at, updated_at
    ) VALUES (
        p_preflight_id, p_user_id, 'preflight_held', 'betatest-free-pool-v1',
        v_preflight.expires_at, v_now, v_now
    ) RETURNING * INTO v_created;
    INSERT INTO public.analysis_beta_pool_reservations(
        allocation_id, operation_family, credential_slot, reserved_usd,
        lifecycle_state, created_at, updated_at
    ) VALUES (
        v_created.id, 'target-profile', v_selected_slot,
        p_target_profile_budget_usd, 'preflight_held', v_now, v_now
    );
    RETURN public.analysis_beta_pool_allocation_json(v_created);
END;
$$;


--
-- Name: increment_analysis_semantic_retry(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_analysis_semantic_retry(p_request_id uuid, p_user_id uuid, p_expected_step text, p_state_key text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    current_state_key TEXT;
    current_retry_count INTEGER;
    next_retry_count INTEGER;
    state_key_prefix TEXT;
BEGIN
    IF p_expected_step IS NULL
       OR p_expected_step NOT IN (
           'pending',
           'collect',
           'profiles',
           'analyze',
           'interactions',
           'deep_analysis',
           'finalize',
           'gender',
           'features'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_RETRY_INVALID_STEP',
            ERRCODE = '22023';
    END IF;

    state_key_prefix := 'v1:' || p_expected_step;
    IF p_state_key IS NULL
       OR char_length(p_state_key) NOT BETWEEN 4 AND 128
       OR p_state_key !~ '^v1:[a-z0-9:_=-]+$'
       OR NOT (
           p_state_key = state_key_prefix
           OR left(p_state_key, char_length(state_key_prefix) + 1)
               = state_key_prefix || ':'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_RETRY_INVALID_STATE_KEY',
            ERRCODE = '22023';
    END IF;

    SELECT retry_state_key, retry_count
    INTO current_state_key, current_retry_count
    FROM public.analysis_requests
    WHERE id = p_request_id
      AND user_id = p_user_id
      AND status IN ('pending', 'processing')
      AND COALESCE(current_step, 'pending') = p_expected_step
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    next_retry_count := CASE
        WHEN current_state_key = p_state_key
            THEN LEAST(current_retry_count + 1, 1000)
        ELSE 1
    END;

    UPDATE public.analysis_requests
    SET retry_state_key = p_state_key,
        retry_count = next_retry_count
    WHERE id = p_request_id;

    RETURN next_retry_count;
END;
$_$;


--
-- Name: initialize_analysis_v2_dag_scope(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.initialize_analysis_v2_dag_scope(p_request_id uuid, p_job_key text, p_input_hash text, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_scope public.analysis_v2_dag_scopes%ROWTYPE;
    v_request_hash TEXT;
    v_plan_hash TEXT;
    v_exclusion_hash TEXT;
    v_excluded_count SMALLINT;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key <> 'coordinator:bootstrap'
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[a-f0-9]{64}$'
       OR p_claim_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND OR v_request.status NOT IN ('pending', 'processing') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_job.track <> 'coordinator'
       OR v_job.kind <> 'bootstrap'
       OR v_job.batch IS NOT NULL
       OR v_job.input_hash <> p_input_hash
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    IF v_request.selected_plan_id_snapshot NOT IN ('basic', 'standard', 'plus')
       OR v_request.exclusion_decision_snapshot NOT IN ('exclude', 'skip') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_INVALID', ERRCODE = 'P0001';
    END IF;

    v_excluded_count := CASE
        WHEN v_request.exclusion_decision_snapshot = 'exclude' THEN 1
        ELSE 0
    END;
    v_request_hash := public.analysis_v2_dag_hash_json(pg_catalog.jsonb_build_object(
        'domain', 'analysis-v2-request-snapshot-v1',
        'requestId', p_request_id,
        'schemaVersion', 2,
        'pipelineVersion', v_request.pipeline_version,
        'preflightId', v_request.preflight_id,
        'targetInstagramId', pg_catalog.lower(v_request.target_instagram_id),
        'selectedPlanId', v_request.selected_plan_id_snapshot,
        'exclusionDecision', v_request.exclusion_decision_snapshot,
        'excludedInstagramId', v_request.excluded_instagram_id,
        'analysisScope', v_request.analysis_scope_snapshot,
        'policyVersions', v_request.policy_versions_snapshot,
        'pricingVersion', v_request.pricing_version_snapshot
    ));
    v_plan_hash := public.analysis_v2_dag_hash_json(pg_catalog.jsonb_build_object(
        'domain', 'analysis-v2-plan-snapshot-v1',
        'requestId', p_request_id,
        'planId', v_request.selected_plan_id_snapshot,
        'planCard', pg_catalog.jsonb_extract_path(
            v_request.plan_cards_snapshot,
            v_request.selected_plan_id_snapshot
        ),
        'analysisScope', v_request.analysis_scope_snapshot,
        'policyVersions', v_request.policy_versions_snapshot
    ));
    v_exclusion_hash := public.analysis_v2_dag_hash_json(pg_catalog.jsonb_build_object(
        'domain', 'analysis-v2-exclusion-decision-v1',
        'requestId', p_request_id,
        'decision', v_request.exclusion_decision_snapshot,
        'excludedInstagramId', v_request.excluded_instagram_id
    ));

    SELECT scope.*
    INTO v_scope
    FROM public.analysis_v2_dag_scopes AS scope
    WHERE scope.request_id = p_request_id
    FOR UPDATE;
    IF FOUND THEN
        IF v_scope.schema_version <> 2
           OR v_scope.request_snapshot_hash <> v_request_hash
           OR v_scope.plan_id <> v_request.selected_plan_id_snapshot
           OR v_scope.plan_snapshot_hash <> v_plan_hash
           OR v_scope.exclusion_decision_hash <> v_exclusion_hash
           OR v_scope.excluded_count <> v_excluded_count
           OR v_scope.initialized_by_job_key <> p_job_key
           OR v_scope.initialized_by_input_hash <> p_input_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DAG_STATE_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_dag_state_json(p_request_id);
    END IF;

    INSERT INTO public.analysis_v2_dag_scopes (
        request_id,
        request_snapshot_hash,
        plan_id,
        plan_snapshot_hash,
        exclusion_decision_hash,
        excluded_count,
        initialized_by_job_key,
        initialized_by_input_hash
    ) VALUES (
        p_request_id,
        v_request_hash,
        v_request.selected_plan_id_snapshot,
        v_plan_hash,
        v_exclusion_hash,
        v_excluded_count,
        p_job_key,
        p_input_hash
    );

    RETURN public.analysis_v2_dag_state_json(p_request_id);
END;
$_$;


--
-- Name: inspect_earlybird_concierge_snapshot_conflict_precheck(uuid, uuid, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inspect_earlybird_concierge_snapshot_conflict_precheck(p_order_id uuid, p_preflight_id uuid, p_expected_manual_review_at timestamp with time zone, p_expected_admission_refreshed_at timestamp with time zone, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_recovery RECORD;
    v_order_preflight_id UUID;
    v_provider_runs JSONB;
    v_active_request_count INTEGER;
    v_active_job_count INTEGER;
BEGIN
    IF p_order_id IS NULL
       OR p_preflight_id IS NULL
       OR p_expected_manual_review_at IS NULL
       OR p_expected_admission_refreshed_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_PRECHECK_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.preflight_id
    INTO v_order_preflight_id
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id;
    SELECT fulfillment.*
    INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id;
    SELECT recovery.*
    INTO v_recovery
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, preflight_id UUID, provider_operation_key TEXT, provider_input_hash VARCHAR(64), provider_run_id_hash VARCHAR(32), expected_manual_review_at TIMESTAMPTZ, expected_admission_refreshed_at TIMESTAMPTZ, old_order_followers_count INTEGER, old_order_following_count INTEGER, old_preflight_followers_count INTEGER, old_preflight_following_count INTEGER, new_witness_followers_count INTEGER, new_witness_following_count INTEGER, old_snapshot_recorded_at TIMESTAMPTZ, new_witness_recorded_at TIMESTAMPTZ, recovery_reason TEXT, followers_absolute_delta INTEGER, following_absolute_delta INTEGER, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_concierge_snapshot_conflict_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','preflight_id','provider_operation_key','provider_input_hash','provider_run_id_hash','expected_manual_review_at','expected_admission_refreshed_at','old_order_followers_count','old_order_following_count','old_preflight_followers_count','old_preflight_following_count','new_witness_followers_count','new_witness_following_count','old_snapshot_recorded_at','new_witness_recorded_at','recovery_reason','followers_absolute_delta','following_absolute_delta','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.preflight_id IS NOT NULL AND decoded.provider_operation_key IS NOT NULL AND decoded.provider_input_hash IS NOT NULL AND decoded.provider_run_id_hash IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.expected_admission_refreshed_at IS NOT NULL AND decoded.old_order_followers_count IS NOT NULL AND decoded.old_order_following_count IS NOT NULL AND decoded.old_preflight_followers_count IS NOT NULL AND decoded.old_preflight_following_count IS NOT NULL AND decoded.new_witness_followers_count IS NOT NULL AND decoded.new_witness_following_count IS NOT NULL AND decoded.old_snapshot_recorded_at IS NOT NULL AND decoded.new_witness_recorded_at IS NOT NULL AND decoded.recovery_reason IS NOT NULL AND decoded.followers_absolute_delta IS NOT NULL AND decoded.following_absolute_delta IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
    WHERE recovery.order_id = p_order_id
      AND recovery.preflight_id = p_preflight_id;
    IF v_order_preflight_id IS NULL
       OR v_order_preflight_id IS DISTINCT FROM p_preflight_id
       OR v_preflight.id IS NULL
       OR v_fulfillment.order_id IS NULL
       OR (
            v_recovery.order_id IS NOT NULL
            AND (
                v_recovery.expected_manual_review_at
                    IS DISTINCT FROM p_expected_manual_review_at
                OR v_recovery.expected_admission_refreshed_at
                    IS DISTINCT FROM p_expected_admission_refreshed_at
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_PRECHECK_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
            'operation_key', provider_run.operation_key,
            'input_hash', provider_run.input_hash,
            'logical_provider', provider_run.logical_provider,
            'actor_id', provider_run.actor_id,
            'credential_slot', provider_run.credential_slot,
            'status', provider_run.status,
            'run_id', provider_run.run_id,
            'terminalized_at', provider_run.terminalized_at,
            'actual_usage_usd', provider_run.actual_usage_usd,
            'usage_reconciled_at', provider_run.usage_reconciled_at,
            'reusable_profile_schema_version', provider_run.reusable_profile_schema_version
        ) ORDER BY provider_run.operation_key
    )
    INTO v_provider_runs
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key IN (
          'target-profile-fresh-admission:g1',
          'target-profile-fresh-admission:g2',
          'target-profile-fresh-admission:g3'
      );

    SELECT pg_catalog.count(*)::INTEGER
    INTO v_active_request_count
    FROM public.analysis_requests AS request
    WHERE request.preflight_id = p_preflight_id
      AND request.status IN ('pending', 'processing')
      AND (p_request_id IS NULL OR request.id IS DISTINCT FROM p_request_id)
      AND EXISTS (
          SELECT 1
          FROM public.earlybird_orders AS local_order
          WHERE local_order.id = p_order_id
            AND local_order.preflight_id = request.preflight_id
      );

    SELECT pg_catalog.count(*)::INTEGER
    INTO v_active_job_count
    FROM public.analysis_pipeline_jobs AS job
    JOIN public.analysis_requests AS request
      ON request.id = job.request_id
    WHERE request.preflight_id = p_preflight_id
      AND job.status IN ('pending', 'processing')
      AND (p_request_id IS NULL OR request.id IS DISTINCT FROM p_request_id)
      AND EXISTS (
          SELECT 1
          FROM public.earlybird_orders AS local_order
          WHERE local_order.id = p_order_id
            AND local_order.preflight_id = request.preflight_id
      );

    RETURN pg_catalog.jsonb_build_object(
        'fulfillment', pg_catalog.jsonb_build_object(
            'status', v_fulfillment.status,
            'request_id', v_fulfillment.request_id,
            'lease_token', v_fulfillment.lease_token,
            'lease_expires_at', v_fulfillment.lease_expires_at,
            'manual_review_at', v_fulfillment.manual_review_at,
            'last_error_code', v_fulfillment.last_error_code,
            'attempt_count', v_fulfillment.attempt_count
        ),
        'provider_runs', COALESCE(v_provider_runs, '[]'::JSONB),
        'active_request_count', v_active_request_count,
        'active_job_count', v_active_job_count
    );
END;
$$;


--
-- Name: inspect_earlybird_concierge_snapshot_recovery_execution(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inspect_earlybird_concierge_snapshot_recovery_execution(p_order_id uuid, p_preflight_id uuid, p_expected_manual_review_at timestamp with time zone, p_expected_admission_refreshed_at timestamp with time zone) RETURNS TABLE(recovered boolean, request_id uuid, request_status text, fulfillment_status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_recovery RECORD;
    v_request public.analysis_requests%ROWTYPE;
BEGIN
    IF p_order_id IS NULL
       OR p_preflight_id IS NULL
       OR p_expected_manual_review_at IS NULL
       OR p_expected_admission_refreshed_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_EXECUTION_INVALID',
            ERRCODE = 'P0001';
    END IF;
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id;
    IF v_order.id IS NULL
       OR v_fulfillment.order_id IS NULL
       OR v_preflight.id IS NULL
       OR v_order.preflight_id IS DISTINCT FROM v_preflight.id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_EXECUTION_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    SELECT recovery.* INTO v_recovery
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, preflight_id UUID, provider_operation_key TEXT, provider_input_hash VARCHAR(64), provider_run_id_hash VARCHAR(32), expected_manual_review_at TIMESTAMPTZ, expected_admission_refreshed_at TIMESTAMPTZ, old_order_followers_count INTEGER, old_order_following_count INTEGER, old_preflight_followers_count INTEGER, old_preflight_following_count INTEGER, new_witness_followers_count INTEGER, new_witness_following_count INTEGER, old_snapshot_recorded_at TIMESTAMPTZ, new_witness_recorded_at TIMESTAMPTZ, recovery_reason TEXT, followers_absolute_delta INTEGER, following_absolute_delta INTEGER, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_concierge_snapshot_conflict_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','preflight_id','provider_operation_key','provider_input_hash','provider_run_id_hash','expected_manual_review_at','expected_admission_refreshed_at','old_order_followers_count','old_order_following_count','old_preflight_followers_count','old_preflight_following_count','new_witness_followers_count','new_witness_following_count','old_snapshot_recorded_at','new_witness_recorded_at','recovery_reason','followers_absolute_delta','following_absolute_delta','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.preflight_id IS NOT NULL AND decoded.provider_operation_key IS NOT NULL AND decoded.provider_input_hash IS NOT NULL AND decoded.provider_run_id_hash IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.expected_admission_refreshed_at IS NOT NULL AND decoded.old_order_followers_count IS NOT NULL AND decoded.old_order_following_count IS NOT NULL AND decoded.old_preflight_followers_count IS NOT NULL AND decoded.old_preflight_following_count IS NOT NULL AND decoded.new_witness_followers_count IS NOT NULL AND decoded.new_witness_following_count IS NOT NULL AND decoded.old_snapshot_recorded_at IS NOT NULL AND decoded.new_witness_recorded_at IS NOT NULL AND decoded.recovery_reason IS NOT NULL AND decoded.followers_absolute_delta IS NOT NULL AND decoded.following_absolute_delta IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
    WHERE recovery.order_id = v_order.id
      AND recovery.preflight_id = v_preflight.id;
    IF NOT FOUND THEN
        RETURN QUERY SELECT
            FALSE, NULL::UUID, NULL::TEXT, v_fulfillment.status::TEXT;
        RETURN;
    END IF;
    IF v_recovery.expected_manual_review_at
            IS DISTINCT FROM p_expected_manual_review_at
       OR v_recovery.expected_admission_refreshed_at
            IS DISTINCT FROM p_expected_admission_refreshed_at
       OR NOT public.earlybird_concierge_snapshot_conflict_receipt_authorized(
            v_order.id,
            v_preflight.id,
            v_order.target_followers_count,
            v_order.target_following_count,
            v_preflight.target_followers_count,
            v_preflight.target_following_count,
            v_preflight.admission_target_followers_count,
            v_preflight.admission_target_following_count,
            v_preflight.admission_generation,
            v_preflight.admission_refreshed_at
       )
       OR EXISTS (
            SELECT 1
            FROM public.earlybird_webhook_events AS refund_event
            WHERE refund_event.payment_id = v_order.payment_id
              AND refund_event.event_type = 'payment.refunded'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_EXECUTION_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_order.result_request_id IS NULL THEN
        IF v_order.status IS DISTINCT FROM 'paid'
           OR v_fulfillment.status IS DISTINCT FROM 'retryable_failure'
           OR v_fulfillment.request_id IS NOT NULL
           OR v_preflight.consumed_request_id IS NOT NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'CONCIERGE_SNAPSHOT_EXECUTION_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN QUERY SELECT
            TRUE, NULL::UUID, NULL::TEXT, v_fulfillment.status::TEXT;
        RETURN;
    END IF;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = v_order.result_request_id;
    IF v_request.id IS NULL
       OR v_order.status NOT IN ('analysis_in_progress', 'completed')
       OR v_fulfillment.status NOT IN ('analysis_in_progress', 'completed')
       OR v_fulfillment.request_id IS DISTINCT FROM v_request.id
       OR v_preflight.consumed_request_id IS DISTINCT FROM v_request.id
       OR v_request.user_id IS DISTINCT FROM v_order.user_id
       OR v_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing', 'completed')
       OR (
            v_request.status = 'completed'
            AND (
                v_order.status NOT IN ('analysis_in_progress', 'completed')
                OR v_fulfillment.status NOT IN (
                    'analysis_in_progress', 'completed'
                )
            )
       )
       OR (
            v_request.status <> 'completed'
            AND (
                v_order.status <> 'analysis_in_progress'
                OR v_fulfillment.status <> 'analysis_in_progress'
            )
       )
       OR (
            (v_order.status = 'completed')
                IS DISTINCT FROM (v_fulfillment.status = 'completed')
       )
       OR (v_request.status = 'completed' AND EXISTS (
            SELECT 1
            FROM public.analysis_pipeline_jobs AS active_job
            WHERE active_job.request_id = v_request.id
              AND active_job.status IN ('pending', 'processing')
       )) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_EXECUTION_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    RETURN QUERY SELECT
        TRUE, v_request.id, v_request.status::TEXT, v_fulfillment.status::TEXT;
END;
$$;


--
-- Name: issue_earlybird_groble_seller_reference(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_earlybird_groble_seller_reference(p_order_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_order public.earlybird_orders%ROWTYPE;
    v_reference TEXT;
BEGIN
    IF p_order_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SELLER_REFERENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.*
    INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;

    IF NOT FOUND OR v_order.status IS DISTINCT FROM 'payment_pending' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SELLER_REFERENCE_UNAVAILABLE',
            ERRCODE = 'P0001';
    END IF;
    IF v_order.groble_seller_reference IS NOT NULL THEN
        RETURN v_order.groble_seller_reference;
    END IF;

    v_reference := 'ord.' || pg_catalog.replace(
        extensions.gen_random_uuid()::TEXT,
        '-',
        ''
    );
    UPDATE public.earlybird_orders AS earlybird_order
    SET groble_seller_reference = v_reference,
        updated_at = pg_catalog.clock_timestamp()
    WHERE earlybird_order.id = p_order_id
      AND earlybird_order.groble_seller_reference IS NULL
    RETURNING earlybird_order.groble_seller_reference
    INTO v_reference;

    IF NOT FOUND THEN
        SELECT earlybird_order.groble_seller_reference
        INTO v_reference
        FROM public.earlybird_orders AS earlybird_order
        WHERE earlybird_order.id = p_order_id;
    END IF;
    IF v_reference !~ '^ord[.][a-f0-9]{32}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SELLER_REFERENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    RETURN v_reference;
END;
$_$;


--
-- Name: join_earlybird_waitlist(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_earlybird_waitlist(p_user_id uuid, p_preflight_id uuid) RETURNS TABLE(waitlist_id uuid, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_existing public.earlybird_waitlist%ROWTYPE;
    v_waitlist_id UUID;
BEGIN
    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
    FOR UPDATE;

    IF NOT FOUND
       OR v_preflight.status <> 'ready'
       OR v_preflight.expires_at <= pg_catalog.clock_timestamp()
       OR v_preflight.exclusion_decision NOT IN ('skip', 'exclude')
       OR v_preflight.required_plan_id <> 'plus'
       OR v_preflight.plan_cards_snapshot->'plus'->>'selectionState' = 'unavailable' THEN
        RAISE EXCEPTION 'EARLYBIRD_WAITLIST_NOT_ELIGIBLE';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.analysis_preflights AS newer
        WHERE newer.user_id = p_user_id
          AND newer.status = 'ready'
          AND newer.expires_at > pg_catalog.clock_timestamp()
          AND newer.exclusion_decision IN ('skip', 'exclude')
          AND (
              newer.created_at > v_preflight.created_at
              OR (
                  newer.created_at = v_preflight.created_at
                  AND newer.id::TEXT > v_preflight.id::TEXT
              )
          )
    ) THEN
        RAISE EXCEPTION 'PREFLIGHT_NOT_LATEST';
    END IF;

    SELECT waitlist.*
    INTO v_existing
    FROM public.earlybird_waitlist AS waitlist
    WHERE waitlist.preflight_id = p_preflight_id;
    IF FOUND THEN
        RETURN QUERY SELECT v_existing.id, FALSE;
        RETURN;
    END IF;

    INSERT INTO public.earlybird_waitlist (
        user_id,
        preflight_id,
        target_instagram_id,
        target_followers_count,
        target_following_count,
        exclusion_decision,
        excluded_instagram_id
    ) VALUES (
        p_user_id,
        p_preflight_id,
        v_preflight.target_instagram_id,
        v_preflight.target_followers_count,
        v_preflight.target_following_count,
        v_preflight.exclusion_decision,
        v_preflight.excluded_instagram_id
    )
    RETURNING id INTO v_waitlist_id;

    RETURN QUERY SELECT v_waitlist_id, TRUE;
END;
$$;


--
-- Name: list_account_ledger_legacy_e2e_candidates_v1(); Type: FUNCTION; Schema: public; Owner: -
--

