--
-- Name: list_analysis_order_audit_bundle_recovery(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_analysis_order_audit_bundle_recovery(p_limit integer DEFAULT 10) RETURNS SETOF jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'requestId', queue.request_id::TEXT,
        'status', queue.status,
        'attemptCount', queue.attempt_count,
        'nextAttemptAt', queue.next_attempt_at,
        'lastErrorCode', queue.last_error_code
    )
    FROM public.analysis_order_audit_assembly_queue AS queue
    WHERE p_limit BETWEEN 1 AND 50
      AND (
          queue.status = 'queued'
          OR (
              queue.status = 'processing'
              AND queue.lease_expires_at < pg_catalog.clock_timestamp()
          )
          OR (
              queue.status = 'failed'
              AND queue.next_attempt_at <= pg_catalog.clock_timestamp()
          )
      )
    ORDER BY queue.next_attempt_at, queue.updated_at, queue.request_id
    LIMIT CASE WHEN p_limit BETWEEN 1 AND 50 THEN p_limit ELSE 0 END;
$$;


--
-- Name: list_analysis_order_audit_bundles(timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_analysis_order_audit_bundles(p_cursor_assembled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_request_id uuid DEFAULT NULL::uuid, p_page_size integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '5s'
    AS $$
DECLARE
    v_rows JSONB;
    v_has_more BOOLEAN;
    v_next_assembled_at TIMESTAMPTZ;
    v_next_request_id UUID;
BEGIN
    IF (p_cursor_assembled_at IS NULL) <> (p_cursor_request_id IS NULL)
       OR p_page_size IS NULL
       OR p_page_size NOT BETWEEN 1 AND 50 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_ORDER_AUDIT_INVALID_QUERY', ERRCODE = 'P0001';
    END IF;

    WITH latest AS (
        SELECT DISTINCT ON (bundle.request_id)
            bundle.request_id,
            bundle.order_id,
            bundle.target_instagram_id,
            bundle.plan_id,
            bundle.version,
            bundle.completeness_status,
            bundle.gap_codes,
            bundle.cost_status,
            bundle.cost_known_usd,
            bundle.cost_conservative_usd,
            bundle.cost_usage_unknown,
            bundle.stage_status,
            bundle.assembled_at
        FROM public.analysis_order_audit_bundles AS bundle
        ORDER BY bundle.request_id, bundle.version DESC
    ), candidates AS (
        SELECT latest.*
        FROM latest
        WHERE p_cursor_assembled_at IS NULL
           OR assembled_at < p_cursor_assembled_at
           OR (
               assembled_at = p_cursor_assembled_at
               AND request_id < p_cursor_request_id
           )
        ORDER BY assembled_at DESC, request_id DESC
        LIMIT p_page_size + 1
    ), ordered AS (
        SELECT candidates.*,
               pg_catalog.row_number() OVER (
                   ORDER BY assembled_at DESC, request_id DESC
               ) AS page_ordinal
        FROM candidates
    ), page AS (
        SELECT ordered.*
        FROM ordered
        WHERE ordered.page_ordinal <= p_page_size
    ), projected AS (
        SELECT page.*,
               public.analysis_order_audit_summary_counts(
                   page.request_id, page.version
               )->'gender' AS gender,
               public.analysis_order_audit_summary_counts(
                   page.request_id, page.version
               )->'risk' AS risk,
               public.analysis_order_audit_retention_payload(
                   page.request_id, page.version, page.assembled_at
               ) AS retention
        FROM page
    ), has_more AS (
        SELECT EXISTS (
            SELECT 1
            FROM ordered
            WHERE ordered.page_ordinal = p_page_size + 1
        ) AS value
    )
    SELECT
        COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'requestId', page.request_id,
                    'orderId', page.order_id,
                    'targetInstagramId', page.target_instagram_id,
                    'planId', page.plan_id,
                    'version', page.version,
                    'completenessStatus', page.completeness_status,
                    'gapCodes', COALESCE((
                        SELECT pg_catalog.jsonb_agg(bounded.code ORDER BY bounded.ordinality)
                        FROM (
                            SELECT gap.code, gap.ordinality
                            FROM pg_catalog.unnest(
                                COALESCE(page.gap_codes, ARRAY[]::TEXT[])
                            ) WITH ORDINALITY AS gap(code, ordinality)
                            WHERE pg_catalog.char_length(gap.code) BETWEEN 1 AND 96
                              AND gap.code !~ '[[:cntrl:]]'
                            ORDER BY gap.ordinality
                            LIMIT 32
                        ) AS bounded
                    ), '[]'::JSONB),
                    'cost', pg_catalog.jsonb_build_object(
                        'status', page.cost_status,
                        'knownUsd', page.cost_known_usd,
                        'conservativeUsd', page.cost_conservative_usd,
                        'usageUnknown', page.cost_usage_unknown
                    ),
                    'gender', page.gender,
                    'risk', page.risk,
                    'retention', page.retention,
                    'stageStatus', pg_catalog.jsonb_build_object(
                        'relationships', page.stage_status->>'relationships' = 'true',
                        'targetEvidence', page.stage_status->>'targetEvidence' = 'true',
                        'candidateFeatures', page.stage_status->>'candidateFeatures' = 'true',
                        'riskScores', page.stage_status->>'riskScores' = 'true',
                        'finalized', page.stage_status->>'finalized' = 'true'
                    ),
                    'assembledAt', page.assembled_at
                ) ORDER BY page.assembled_at DESC, page.request_id DESC
            )
            FROM projected AS page
        ), '[]'::JSONB),
        has_more.value,
        CASE WHEN has_more.value THEN (
            SELECT page.assembled_at
            FROM page
            ORDER BY page.assembled_at ASC, page.request_id ASC
            LIMIT 1
        ) ELSE NULL END,
        CASE WHEN has_more.value THEN (
            SELECT page.request_id
            FROM page
            ORDER BY page.assembled_at ASC, page.request_id ASC
            LIMIT 1
        ) ELSE NULL END
      INTO v_rows, v_has_more, v_next_assembled_at, v_next_request_id
      FROM has_more;

    RETURN pg_catalog.jsonb_build_object(
        'rows', v_rows,
        'nextCursor', CASE WHEN v_has_more THEN pg_catalog.jsonb_build_object(
            'assembledAt', v_next_assembled_at,
            'requestId', v_next_request_id
        ) ELSE NULL END
    );
END;
$$;


--
-- Name: list_analysis_preflight_ambiguous_identity_drift_candidates(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_analysis_preflight_ambiguous_identity_drift_candidates(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_candidates JSONB;
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_IDENTITY_DRIFT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    WITH candidates AS (
        SELECT provider_run.*
        FROM public.analysis_preflight_provider_runs AS provider_run
        JOIN public.analysis_preflights AS preflight
          ON preflight.id = provider_run.preflight_id
        WHERE provider_run.status = 'starting'
          AND provider_run.run_id IS NULL
          AND preflight.user_id IS NULL
          AND preflight.provider_selector = 'anonymous_apify'
          AND preflight.status = 'expired'
          AND preflight.pii_scrubbed_at IS NOT NULL
          AND preflight.expires_at <= v_now - INTERVAL '7 days'
          AND preflight.updated_at <= v_now - INTERVAL '7 days'
          AND preflight.target_input_hash IS NOT NULL
          AND provider_run.input_hash IS DISTINCT FROM preflight.target_input_hash
          AND provider_run.operation_key = 'target-profile-fallback'
          AND provider_run.reserved_at <= v_now - INTERVAL '7 days'
          AND provider_run.updated_at <= v_now - INTERVAL '7 days'
          AND (preflight.lease_expires_at IS NULL OR preflight.lease_expires_at <= v_now)
          AND (
              preflight.admission_lease_expires_at IS NULL
              OR preflight.admission_lease_expires_at <= v_now
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_provider_admission_leases AS admission
              WHERE admission.request_id = provider_run.preflight_id
                AND admission.logical_provider = provider_run.logical_provider
                AND admission.credential_slot = provider_run.credential_slot
                AND admission.state IN ('leased', 'recovery_required')
                AND admission.expires_at > v_now
          )
          AND EXISTS (
              SELECT 1
              FROM public.analysis_preflight_failures AS failure
              WHERE failure.preflight_id = provider_run.preflight_id
                AND failure.error_code = 'INTERNAL_ERROR'
          )
        ORDER BY provider_run.reserved_at,
            provider_run.preflight_id,
            provider_run.operation_key
        LIMIT p_limit
    )
    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'preflightId', candidate.preflight_id,
                'operationKey', candidate.operation_key,
                'inputHash', candidate.input_hash,
                'logicalProvider', candidate.logical_provider,
                'actorId', candidate.actor_id,
                'credentialSlot', candidate.credential_slot,
                'maxChargeUsd', candidate.max_charge_usd,
                'reservedAt', candidate.reserved_at
            ) ORDER BY candidate.reserved_at,
                candidate.preflight_id,
                candidate.operation_key
        ),
        '[]'::JSONB
    ) INTO v_candidates
    FROM candidates AS candidate;
    RETURN v_candidates;
END;
$$;


--
-- Name: list_analysis_preflight_ambiguous_start_candidates(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_analysis_preflight_ambiguous_start_candidates(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_candidates JSONB;
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_AMBIGUOUS_START_INVALID',
            ERRCODE = 'P0001';
    END IF;
    WITH candidates AS (
        SELECT provider_run.*
        FROM public.analysis_preflight_provider_runs AS provider_run
        JOIN public.analysis_preflights AS preflight
          ON preflight.id = provider_run.preflight_id
        WHERE provider_run.status = 'starting'
          AND provider_run.run_id IS NULL
          AND provider_run.reserved_at <= v_now - INTERVAL '30 minutes'
          AND provider_run.updated_at <= v_now - INTERVAL '30 minutes'
          AND preflight.expires_at <= v_now
          AND (preflight.lease_expires_at IS NULL OR preflight.lease_expires_at <= v_now)
          AND (
              preflight.admission_lease_expires_at IS NULL
              OR preflight.admission_lease_expires_at <= v_now
          )
          AND NOT (
              preflight.user_id IS NULL
              AND preflight.provider_selector = 'anonymous_apify'
              AND preflight.target_input_hash IS NOT NULL
              AND provider_run.input_hash IS DISTINCT FROM preflight.target_input_hash
          )
        ORDER BY provider_run.reserved_at,
            provider_run.preflight_id,
            provider_run.operation_key
        LIMIT p_limit
    )
    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'preflightId', candidate.preflight_id,
                'operationKey', candidate.operation_key,
                'inputHash', candidate.input_hash,
                'logicalProvider', candidate.logical_provider,
                'actorId', candidate.actor_id,
                'credentialSlot', candidate.credential_slot,
                'maxChargeUsd', candidate.max_charge_usd,
                'reservedAt', candidate.reserved_at
            ) ORDER BY candidate.reserved_at,
                candidate.preflight_id,
                candidate.operation_key
        ),
        '[]'::JSONB
    ) INTO v_candidates
    FROM candidates AS candidate;
    RETURN v_candidates;
END;
$$;


--
-- Name: list_analysis_preflight_dispatch_recovery_v2(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_analysis_preflight_dispatch_recovery_v2(p_limit integer DEFAULT 64) RETURNS TABLE(preflight_id uuid, dispatch_generation integer, dispatch_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 64 THEN
        RAISE EXCEPTION USING MESSAGE = 'PREFLIGHT_DISPATCH_RECOVERY_INVALID_LIMIT', ERRCODE = 'P0001';
    END IF;
    RETURN QUERY
    SELECT preflight.id, preflight.dispatch_generation, preflight.dispatch_token
    FROM public.analysis_preflights AS preflight
    WHERE preflight.status = 'pending'
      AND preflight.dispatch_state = 'reserved'
      AND preflight.dispatch_token IS NOT NULL
      AND preflight.dispatch_workload_role IS NOT DISTINCT FROM 'preflight'
      AND preflight.dispatch_contract_version IS NOT DISTINCT FROM 2
      AND preflight.dispatch_reserved_at <= v_now - INTERVAL '30 seconds'
    ORDER BY preflight.dispatch_reserved_at, preflight.id
    LIMIT p_limit;
END;
$$;


--
-- Name: list_analysis_preflight_unreconciled_provider_runs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_analysis_preflight_unreconciled_provider_runs(p_limit integer DEFAULT 17) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_runs JSONB;
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 64 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;

    WITH candidate_keys AS MATERIALIZED (
        SELECT provider_run.preflight_id, provider_run.operation_key
        FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.actual_usage_usd IS NULL
          AND provider_run.usage_reconciled_at IS NULL
          AND (
              (
                  provider_run.status = 'running'
                  AND provider_run.run_started_at <= v_now - INTERVAL '30 seconds'
              )
              OR (
                  provider_run.status IN ('succeeded', 'failed', 'aborted', 'timed_out')
                  AND provider_run.terminalized_at <= v_now - INTERVAL '30 seconds'
              )
          )
          AND (
              provider_run.usage_reconciliation_attempted_at IS NULL
              OR provider_run.usage_reconciliation_attempted_at <= v_now - INTERVAL '30 seconds'
          )
        ORDER BY
            provider_run.usage_reconciliation_attempted_at NULLS FIRST,
            COALESCE(provider_run.terminalized_at, provider_run.run_started_at),
            provider_run.preflight_id,
            provider_run.operation_key
        FOR UPDATE SKIP LOCKED
        LIMIT p_limit
    ), attempted AS (
        UPDATE public.analysis_preflight_provider_runs AS provider_run
        SET usage_reconciliation_attempt_count = LEAST(
                provider_run.usage_reconciliation_attempt_count + 1,
                100000
            ),
            usage_reconciliation_attempted_at = v_now,
            updated_at = v_now
        FROM candidate_keys AS candidate
        WHERE provider_run.preflight_id = candidate.preflight_id
          AND provider_run.operation_key = candidate.operation_key
        RETURNING provider_run.*
    )
    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            public.analysis_preflight_provider_run_json(candidate)
            ORDER BY COALESCE(candidate.terminalized_at, candidate.run_started_at),
                candidate.preflight_id,
                candidate.operation_key
        ),
        '[]'::JSONB
    ) INTO v_runs
    FROM attempted AS candidate;
    RETURN v_runs;
END;
$$;


--
-- Name: list_analysis_v2_active_provider_runs_for_cleanup(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_analysis_v2_active_provider_runs_for_cleanup(p_request_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 64) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_starting_count INTEGER;
    v_runs JSONB;
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 64 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_INVALID', ERRCODE = 'P0001';
    END IF;
    IF p_request_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.analysis_v2_provider_cleanup_intents AS intent
        WHERE intent.request_id = p_request_id AND intent.completed_at IS NULL
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.count(*)::INTEGER INTO v_starting_count
    FROM public.analysis_v2_provider_runs AS provider_run
    JOIN public.analysis_v2_provider_cleanup_intents AS intent
      ON intent.request_id = provider_run.request_id
     AND intent.completed_at IS NULL
    LEFT JOIN public.analysis_v2_unconfirmed_start_resolutions AS resolution
      ON resolution.reservation_token = provider_run.reservation_token
    WHERE provider_run.status = 'starting'
      AND resolution.reservation_token IS NULL
      AND (p_request_id IS NULL OR provider_run.request_id = p_request_id);

    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            public.analysis_v2_provider_run_json(candidate)
            ORDER BY candidate.reserved_at, candidate.request_id,
                candidate.job_key, candidate.operation_key
        ),
        '[]'::JSONB
    ) INTO v_runs
    FROM (
        SELECT provider_run.*
        FROM public.analysis_v2_provider_runs AS provider_run
        JOIN public.analysis_v2_provider_cleanup_intents AS intent
          ON intent.request_id = provider_run.request_id
         AND intent.completed_at IS NULL
        WHERE provider_run.status = 'running'
          AND (p_request_id IS NULL OR provider_run.request_id = p_request_id)
        ORDER BY provider_run.reserved_at, provider_run.request_id,
            provider_run.job_key, provider_run.operation_key
        LIMIT p_limit
    ) AS candidate;

    RETURN pg_catalog.jsonb_build_object(
        'startingCount', v_starting_count,
        'runs', v_runs
    );
END;
$$;


--
-- Name: list_analysis_v2_conservative_max_charge_candidates(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_analysis_v2_conservative_max_charge_candidates(p_limit integer DEFAULT 64) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_candidates JSONB;
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 64 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_LIMIT';
    END IF;

    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'requestId', candidate.request_id,
                'jobKey', candidate.job_key,
                'operationKey', candidate.operation_key,
                'inputHash', candidate.input_hash,
                'jobClaimToken', candidate.job_claim_token,
                'reservationToken', candidate.reservation_token,
                'runId', candidate.run_id,
                'logicalProvider', candidate.logical_provider,
                'actorId', candidate.actor_id,
                'credentialSlot', candidate.credential_slot,
                'maxChargeUsd', candidate.max_charge_usd,
                'reservedAt', candidate.reserved_at,
                'runStartedAt', candidate.run_started_at,
                'terminalizedAt', candidate.terminalized_at,
                'status', candidate.status,
                'revenueCostChildActive', candidate.revenue_cost_child_active
            )
            ORDER BY candidate.terminalized_at, candidate.request_id,
                candidate.job_key, candidate.operation_key
        ),
        '[]'::JSONB
    )
    INTO v_candidates
    FROM (
        SELECT
            provider_run.request_id,
            provider_run.job_key,
            provider_run.operation_key,
            provider_run.input_hash,
            provider_run.job_claim_token,
            provider_run.reservation_token,
            provider_run.run_id,
            provider_run.logical_provider,
            provider_run.actor_id,
            provider_run.credential_slot,
            provider_run.max_charge_usd,
            provider_run.reserved_at,
            provider_run.run_started_at,
            provider_run.terminalized_at,
            provider_run.status,
            EXISTS (
                SELECT 1
                FROM public.analysis_revenue_cost_operations AS child
                WHERE child.request_id = provider_run.request_id
                  AND child.owner_kind = 'provider_run'
                  AND child.source_job_key = provider_run.job_key
                  AND child.source_operation_key_hash =
                      pg_catalog.encode(
                          extensions.digest(
                              pg_catalog.convert_to(provider_run.operation_key, 'UTF8'),
                              'sha256'
                          ),
                          'hex'
                      )
                  AND child.source_attempt = 0
                  AND child.status IN ('reserved', 'started', 'ambiguous')
            ) AS revenue_cost_child_active
        FROM public.analysis_v2_provider_runs AS provider_run
        JOIN public.analysis_pipeline_jobs AS job
          ON job.request_id = provider_run.request_id
         AND job.job_key = provider_run.job_key
        JOIN public.analysis_requests AS analysis_request
          ON analysis_request.id = provider_run.request_id
        WHERE analysis_request.pipeline_version = 'v2'
          AND provider_run.status = 'succeeded'
          AND provider_run.logical_provider = 'apify'
          AND provider_run.credential_slot = 'tertiary'
          AND provider_run.run_id IS NOT NULL
          AND provider_run.run_started_at IS NOT NULL
          AND provider_run.terminalized_at IS NOT NULL
          AND provider_run.actual_usage_usd IS NULL
          AND provider_run.usage_reconciled_at IS NULL
          AND provider_run.manual_resolution_kind IS NULL
          AND provider_run.manual_resolution_evidence_hash IS NULL
          AND provider_run.manual_resolved_at IS NULL
          AND provider_run.terminalized_at <= v_now - INTERVAL '7 days'
          AND (
              (job.lease_token IS NULL AND job.lease_expires_at IS NULL)
              OR (
                  job.lease_token IS NOT NULL
                  AND job.lease_expires_at IS NOT NULL
                  AND job.lease_expires_at <= v_now
              )
          )
          AND (
              (analysis_request.processing_lease_token IS NULL
               AND analysis_request.processing_lease_expires_at IS NULL)
              OR (
                  analysis_request.processing_lease_token IS NOT NULL
                  AND analysis_request.processing_lease_expires_at IS NOT NULL
                  AND analysis_request.processing_lease_expires_at <= v_now
              )
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.analysis_provider_admission_leases AS admission
              WHERE admission.request_id = provider_run.request_id
                AND admission.job_key = provider_run.job_key
                AND admission.operation_key = provider_run.operation_key
                AND admission.logical_provider = provider_run.logical_provider
                AND admission.credential_slot = provider_run.credential_slot
                AND admission.state IN ('leased', 'recovery_required')
                AND (
                    admission.expires_at IS NULL
                    OR admission.expires_at > v_now
                )
          )
        ORDER BY provider_run.terminalized_at, provider_run.request_id,
            provider_run.job_key, provider_run.operation_key
        LIMIT p_limit
    ) AS candidate;

    RETURN v_candidates;
END;
$$;


--
-- Name: list_analysis_v2_dispatchable_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_analysis_v2_dispatchable_jobs(p_limit integer DEFAULT 100) RETURNS TABLE(request_id uuid, job_key text, job_status text, dispatch_state text, dispatch_generation integer, reservation_token uuid, dispatch_reserved_at timestamp with time zone, dispatched_at timestamp with time zone, task_name text, lease_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_INVALID_JOB_SCAN_INPUT',
            ERRCODE = 'P0001';
    END IF;
    RETURN QUERY
    SELECT
        job.request_id,
        job.job_key::TEXT,
        job.status::TEXT,
        job.dispatch_state::TEXT,
        job.dispatch_generation,
        job.dispatch_reservation_token,
        job.dispatch_reserved_at,
        job.dispatched_at,
        job.dispatch_task_name::TEXT,
        job.lease_expires_at
    FROM public.analysis_pipeline_jobs AS job
    JOIN public.analysis_requests AS analysis_request
      ON analysis_request.id = job.request_id
    WHERE analysis_request.pipeline_version = 'v2'
      AND analysis_request.status IN ('pending', 'processing')
      AND job.status IN ('pending', 'processing')
      AND job.recovery_not_before <= pg_catalog.clock_timestamp()
      AND (
            job.scheduler_not_before_at IS NULL
            OR job.scheduler_not_before_at <= pg_catalog.clock_timestamp()
      )
      AND NOT EXISTS (
            SELECT 1
            
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, preflight_id UUID, provider_operation_key TEXT, provider_input_hash VARCHAR(64), provider_run_id_hash VARCHAR(32), expected_manual_review_at TIMESTAMPTZ, expected_admission_refreshed_at TIMESTAMPTZ, old_order_followers_count INTEGER, old_order_following_count INTEGER, old_preflight_followers_count INTEGER, old_preflight_following_count INTEGER, new_witness_followers_count INTEGER, new_witness_following_count INTEGER, old_snapshot_recorded_at TIMESTAMPTZ, new_witness_recorded_at TIMESTAMPTZ, recovery_reason TEXT, followers_absolute_delta INTEGER, following_absolute_delta INTEGER, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_concierge_snapshot_conflict_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','preflight_id','provider_operation_key','provider_input_hash','provider_run_id_hash','expected_manual_review_at','expected_admission_refreshed_at','old_order_followers_count','old_order_following_count','old_preflight_followers_count','old_preflight_following_count','new_witness_followers_count','new_witness_following_count','old_snapshot_recorded_at','new_witness_recorded_at','recovery_reason','followers_absolute_delta','following_absolute_delta','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.preflight_id IS NOT NULL AND decoded.provider_operation_key IS NOT NULL AND decoded.provider_input_hash IS NOT NULL AND decoded.provider_run_id_hash IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.expected_admission_refreshed_at IS NOT NULL AND decoded.old_order_followers_count IS NOT NULL AND decoded.old_order_following_count IS NOT NULL AND decoded.old_preflight_followers_count IS NOT NULL AND decoded.old_preflight_following_count IS NOT NULL AND decoded.new_witness_followers_count IS NOT NULL AND decoded.new_witness_following_count IS NOT NULL AND decoded.old_snapshot_recorded_at IS NOT NULL AND decoded.new_witness_recorded_at IS NOT NULL AND decoded.recovery_reason IS NOT NULL AND decoded.followers_absolute_delta IS NOT NULL AND decoded.following_absolute_delta IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
            JOIN public.earlybird_orders AS local_order
              ON local_order.id = recovery.order_id
             AND local_order.preflight_id = recovery.preflight_id
            JOIN public.earlybird_fulfillments AS local_fulfillment
              ON local_fulfillment.order_id = local_order.id
            JOIN public.analysis_preflights AS local_preflight
              ON local_preflight.id = recovery.preflight_id
            WHERE local_order.result_request_id = job.request_id
              AND local_fulfillment.request_id = job.request_id
              AND local_preflight.consumed_request_id = job.request_id
              AND public.earlybird_concierge_snapshot_conflict_receipt_authorized(
                    local_order.id,
                    local_preflight.id,
                    local_order.target_followers_count,
                    local_order.target_following_count,
                    local_preflight.target_followers_count,
                    local_preflight.target_following_count,
                    local_preflight.admission_target_followers_count,
                    local_preflight.admission_target_following_count,
                    local_preflight.admission_generation,
                    local_preflight.admission_refreshed_at
              )
      )
    ORDER BY job.recovery_not_before, job.request_id, job.job_key
    LIMIT p_limit;
END;
$$;


--
-- Name: list_analysis_v2_preflight_admission_dispatch_recovery_v2(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_analysis_v2_preflight_admission_dispatch_recovery_v2(p_limit integer DEFAULT 64) RETURNS TABLE(preflight_id uuid, user_id uuid, admission_generation integer, dispatch_generation integer, dispatch_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 64 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_FRESH_DISPATCH_RECOVERY_INVALID_LIMIT', ERRCODE = 'P0001';
    END IF;
    RETURN QUERY
    SELECT preflight.id,
           preflight.user_id,
           preflight.admission_generation,
           preflight.admission_dispatch_generation,
           preflight.admission_dispatch_token
    FROM public.analysis_preflights AS preflight
    WHERE preflight.admission_status = 'pending'
      AND preflight.admission_dispatch_state = 'reserved'
      AND preflight.admission_dispatch_token IS NOT NULL
      AND preflight.admission_dispatch_workload_role IS NOT DISTINCT FROM 'paid'
      AND preflight.admission_dispatch_contract_version IS NOT DISTINCT FROM 2
      AND preflight.admission_dispatch_reserved_at <= v_now - INTERVAL '30 seconds'
      AND preflight.expires_at > v_now
    ORDER BY preflight.admission_dispatch_reserved_at, preflight.id
    LIMIT p_limit;
END;
$$;


--
-- Name: list_analysis_v2_score_audit_candidates(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_analysis_v2_score_audit_candidates(p_limit integer DEFAULT 5) RETURNS TABLE(request_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    WITH params AS MATERIALIZED (
        SELECT LEAST(GREATEST(p_limit, 1), 20) AS take,
               pg_catalog.clock_timestamp() AS scanned_at,
               pg_catalog.floor(EXTRACT(
                   EPOCH FROM pg_catalog.clock_timestamp()
               ))::BIGINT AS scanned_epoch
    ),
    reserved_expiry AS MATERIALIZED (
        SELECT locator.request_id, locator.retain_until AS sort_at, TRUE AS reserved
        FROM public.analysis_v2_score_audit_scan_locators AS locator
        CROSS JOIN params
        WHERE locator.active
          AND locator.retain_until <= params.scanned_at
        ORDER BY locator.retain_until, locator.request_id
        LIMIT (
            SELECT LEAST(5, GREATEST(1, (take + 2) / 3)) FROM params
        )
    ),
    capacity AS MATERIALIZED (
        SELECT GREATEST(params.take - (SELECT count(*) FROM reserved_expiry), 0)
                   AS remaining
        FROM params
    ),
    regular_retained AS MATERIALIZED (
        SELECT locator.request_id, locator.sort_at, FALSE AS reserved
        FROM public.analysis_v2_score_audit_scan_locators AS locator
        CROSS JOIN params
        WHERE locator.active
          AND locator.eligible_at <= params.scanned_at
          AND locator.retain_until > params.scanned_at
          AND locator.retention_deadline_epoch >= params.scanned_epoch
        ORDER BY locator.retention_deadline_epoch, locator.eligible_at,
                 locator.sort_at, locator.request_id
        LIMIT (SELECT remaining FROM capacity)
    ),
    regular_unretained AS MATERIALIZED (
        SELECT locator.request_id, locator.sort_at, FALSE AS reserved
        FROM public.analysis_v2_score_audit_scan_locators AS locator
        CROSS JOIN params
        WHERE locator.active
          AND locator.retain_until IS NULL
          AND locator.eligible_at <= params.scanned_at
        ORDER BY locator.eligible_at, locator.sort_at, locator.request_id
        LIMIT (SELECT remaining FROM capacity)
    )
    SELECT candidate.request_id
    FROM (
        SELECT * FROM reserved_expiry
        UNION ALL
        SELECT * FROM regular_retained
        UNION ALL
        SELECT * FROM regular_unretained
    ) AS candidate
    ORDER BY candidate.reserved DESC, candidate.sort_at, candidate.request_id
    LIMIT (SELECT take FROM params)
$$;


--
-- Name: list_analysis_v2_unreconciled_provider_runs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_analysis_v2_unreconciled_provider_runs(p_limit integer DEFAULT 64) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_runs JSONB;
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 64 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_INVALID', ERRCODE = 'P0001';
    END IF;

    WITH candidate_keys AS MATERIALIZED (
        SELECT
            provider_run.request_id,
            provider_run.job_key,
            provider_run.operation_key,
            revenue_child.revenue_cost_settlement_required
        FROM public.analysis_v2_provider_runs AS provider_run
        CROSS JOIN LATERAL (
            SELECT EXISTS (
                SELECT 1
                FROM public.analysis_revenue_cost_operations AS cost_operation
                INNER JOIN public.analysis_revenue_run_ledgers AS revenue_ledger
                    ON revenue_ledger.request_id = cost_operation.request_id
                WHERE cost_operation.request_id = provider_run.request_id
                  AND cost_operation.owner_kind = 'provider_run'
                  AND cost_operation.source_job_key = provider_run.job_key
                  AND cost_operation.source_operation_key_hash = pg_catalog.encode(
                      extensions.digest(
                          pg_catalog.convert_to(provider_run.operation_key, 'UTF8'),
                          'sha256'
                      ),
                      'hex'
                  )
                  AND cost_operation.source_attempt = 0
                  AND cost_operation.status IN ('reserved', 'started', 'ambiguous')
                  AND revenue_ledger.access_mode = 'test_entitlement'
                  AND revenue_ledger.plan_id IN ('basic', 'standard')
                  AND revenue_ledger.status IN ('running', 'manual_review')
            ) AS revenue_cost_settlement_required
        ) AS revenue_child
        WHERE provider_run.status IN (
                'rejected', 'succeeded', 'failed', 'aborted', 'timed_out'
            )
          AND provider_run.terminalized_at <= v_now - INTERVAL '30 seconds'
          AND (
              (
                  provider_run.status IN ('succeeded', 'failed', 'aborted', 'timed_out')
                  AND provider_run.actual_usage_usd IS NULL
                  AND provider_run.usage_reconciled_at IS NULL
              )
              OR (
                  revenue_child.revenue_cost_settlement_required
                  AND provider_run.actual_usage_usd IS NOT NULL
                  AND provider_run.usage_reconciled_at IS NOT NULL
              )
          )
          AND (
              provider_run.usage_reconciliation_attempted_at IS NULL
              OR provider_run.usage_reconciliation_attempted_at <= v_now
                  - pg_catalog.make_interval(
                      secs => LEAST(
                          3600,
                          30 * (1 << LEAST(
                              provider_run.usage_reconciliation_attempt_count,
                              7
                          ))
                      )::DOUBLE PRECISION
                  )
          )
        ORDER BY
            provider_run.usage_reconciliation_attempted_at NULLS FIRST,
            provider_run.terminalized_at,
            provider_run.request_id,
            provider_run.job_key,
            provider_run.operation_key
        FOR UPDATE OF provider_run SKIP LOCKED
        LIMIT p_limit
    ), attempted AS (
        UPDATE public.analysis_v2_provider_runs AS provider_run
        SET usage_reconciliation_attempt_count = LEAST(
                provider_run.usage_reconciliation_attempt_count + 1,
                100000
            ),
            usage_reconciliation_attempted_at = v_now,
            updated_at = v_now
        FROM candidate_keys AS candidate
        WHERE provider_run.request_id = candidate.request_id
          AND provider_run.job_key = candidate.job_key
          AND provider_run.operation_key = candidate.operation_key
        RETURNING provider_run.*
    )
    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'requestId', attempted.request_id,
                'jobKey', attempted.job_key,
                'operationKey', attempted.operation_key,
                'inputHash', attempted.input_hash,
                'reservationToken', attempted.reservation_token,
                'logicalProvider', attempted.logical_provider,
                'actorId', attempted.actor_id,
                'credentialSlot', attempted.credential_slot,
                'maxChargeUsd', attempted.max_charge_usd,
                'status', attempted.status,
                'runId', attempted.run_id,
                'actualUsageUsd', attempted.actual_usage_usd,
                'reservedAt', attempted.reserved_at,
                'runStartedAt', attempted.run_started_at,
                'terminalizedAt', attempted.terminalized_at,
                'usageReconciledAt', attempted.usage_reconciled_at,
                'revenueCostSettlementRequired',
                    candidate.revenue_cost_settlement_required
            )
            ORDER BY attempted.terminalized_at, attempted.request_id,
                attempted.job_key, attempted.operation_key
        ),
        '[]'::JSONB
    ) INTO v_runs
    FROM attempted
    INNER JOIN candidate_keys AS candidate
        ON candidate.request_id = attempted.request_id
       AND candidate.job_key = attempted.job_key
       AND candidate.operation_key = attempted.operation_key;

    RETURN v_runs;
END;
$$;


--
-- Name: list_concierge_batch_target_profile_artifacts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_concierge_batch_target_profile_artifacts(p_preflight_id uuid) RETURNS TABLE(operation_key text, actor_id text, credential_slot text, run_id text, status text)
    LANGUAGE sql STABLE STRICT SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT provider_run.operation_key::TEXT,
        provider_run.actor_id::TEXT,
        provider_run.credential_slot::TEXT,
        provider_run.run_id::TEXT,
        provider_run.status::TEXT
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.status = 'succeeded'
      AND provider_run.operation_key LIKE 'target-profile%'
    ORDER BY provider_run.operation_key DESC
    LIMIT 8;
$$;


--
-- Name: list_e2e_test_runner_plans_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_e2e_test_runner_plans_v1() RETURNS TABLE(runner_plan text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT runner.runner_plan
    FROM public.account_e2e_test_runners AS runner
    JOIN public.users AS account ON account.id = runner.account_id
    JOIN auth.users AS auth_user ON auth_user.id = runner.account_id
    JOIN public.account_ledger_rollout_state AS rollout ON rollout.singleton IS TRUE
    WHERE account.account_class = 'e2e_test'
      AND account.traffic_class = 'e2e_test'
      AND account.lifecycle = 'active'
      AND runner.command_version = account.classification_version
      AND runner.command_version = rollout.classification_command_version
      AND rollout.paid_ever_state = 'active'
      AND pg_catalog.lower(pg_catalog.btrim(auth_user.email))
            = pg_catalog.lower(pg_catalog.btrim(account.email))
      AND auth_user.raw_app_meta_data ->> 'analysis_test_runner_v1'
            = runner.runner_plan
    ORDER BY runner.runner_plan
$$;


--
-- Name: list_earlybird_first15_canary_provider_rearms(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_earlybird_first15_canary_provider_rearms() RETURNS TABLE(order_id uuid, rearmed_preflight_id uuid, rearm_generation smallint, source_failure_code text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT rearm.order_id,
        rearm.rearmed_preflight_id,
        rearm.rearm_generation,
        rearm.source_failure_code
    FROM public.earlybird_first15_canary_provider_rearms AS rearm
    ORDER BY rearm.created_at, rearm.order_id, rearm.rearm_generation
    LIMIT 13;
$$;


--
-- Name: list_earlybird_first15_canary_provider_recovery_candidates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_earlybird_first15_canary_provider_recovery_candidates() RETURNS TABLE(order_id uuid, request_id uuid, preflight_id uuid, error_code text, credential_slot text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT fulfillment.order_id,
        request.id AS request_id,
        request.preflight_id,
        request.error_message AS error_code,
        earlybird_order.concierge_apify_credential_slot AS credential_slot
    FROM public.earlybird_fulfillments AS fulfillment
    JOIN public.analysis_requests AS request
      ON request.id = fulfillment.request_id
    JOIN public.earlybird_orders AS earlybird_order
      ON earlybird_order.id = fulfillment.order_id
    WHERE fulfillment.status = 'analysis_in_progress'
      AND earlybird_order.status = 'analysis_in_progress'
      AND earlybird_order.result_request_id = request.id
      AND request.pipeline_version = 'v2'
      AND request.status = 'failed'
      AND request.current_step = 'failed'
      AND request.error_message IN (
          'SCRAPING_INCOMPLETE_ERROR',
          'SCRAPING_PROVIDER_QUOTA_ERROR',
          'SCRAPING_PROVIDER_START_REJECTED_ERROR'
      )

    UNION ALL

    SELECT parent.order_id,
        request.id AS request_id,
        request.preflight_id,
        parent.source_failure_code AS error_code,
        earlybird_order.concierge_apify_credential_slot AS credential_slot
    FROM public.earlybird_first15_canary_provider_rearms AS parent
    JOIN public.earlybird_orders AS earlybird_order
      ON earlybird_order.id = parent.order_id
    JOIN public.earlybird_fulfillments AS fulfillment
      ON fulfillment.order_id = parent.order_id
    JOIN public.analysis_requests AS request
      ON request.preflight_id = parent.rearmed_preflight_id
    WHERE parent.rearm_generation = 1
      AND NOT EXISTS (
          SELECT 1 FROM public.earlybird_first15_canary_provider_rearms AS child
          WHERE child.order_id = parent.order_id
            AND child.rearm_generation = 2
      )
      AND earlybird_order.status = 'analysis_in_progress'
      AND earlybird_order.result_request_id = request.id
      AND earlybird_order.concierge_apify_credential_slot = 'tertiary'
      AND fulfillment.status = 'analysis_in_progress'
      AND fulfillment.request_id = request.id
      AND request.pipeline_version = 'v2'
      AND request.status = 'failed'
      AND request.current_step = 'failed'
      AND (
          (parent.source_failure_code = 'SCRAPING_INCOMPLETE_ERROR'
            AND request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
            AND EXISTS (
                SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                WHERE receipt.request_id = request.id
                  AND receipt.failed_job_key = 'track:relationships:collect'
                  AND receipt.error_code = request.error_message
            ))
          OR (parent.source_failure_code = 'SCRAPING_PROVIDER_START_REJECTED_ERROR'
            AND request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
            AND EXISTS (
                SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                WHERE receipt.request_id = request.id
                  AND receipt.failed_job_key = 'track:target-evidence:collect'
                  AND receipt.error_code = request.error_message
            ))
          OR (parent.source_failure_code = 'SCRAPING_PROVIDER_QUOTA_ERROR'
            AND request.error_message = 'ANALYSIS_V2_MEDIA_ARTIFACT_OBJECT_ERROR'
            AND EXISTS (
                SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                WHERE receipt.request_id = request.id
                  AND receipt.failed_job_key = 'track:profile-ai:batch:2'
                  AND receipt.error_code = request.error_message
            ))
      )
      AND NOT EXISTS (
          SELECT 1 FROM public.analysis_pipeline_jobs AS job
          WHERE job.request_id = request.id
            AND job.status IN ('pending', 'processing', 'retryable')
      )
      AND NOT EXISTS (
          SELECT 1 FROM public.analysis_v2_provider_runs AS provider_run
          WHERE provider_run.request_id = request.id
            AND provider_run.status IN ('starting', 'running')
      )
    UNION ALL

    SELECT parent.order_id,
        request.id AS request_id,
        request.preflight_id,
        'SCRAPING_PROVIDER_QUOTA_ERROR'::TEXT AS error_code,
        earlybird_order.concierge_apify_credential_slot AS credential_slot
    FROM public.earlybird_first15_canary_provider_rearms AS parent
    JOIN public.earlybird_orders AS earlybird_order
      ON earlybird_order.id = parent.order_id
    JOIN public.earlybird_fulfillments AS fulfillment
      ON fulfillment.order_id = parent.order_id
    JOIN public.analysis_requests AS request
      ON request.preflight_id = parent.rearmed_preflight_id
    WHERE parent.rearm_generation = 2
      AND NOT EXISTS (
          SELECT 1 FROM public.earlybird_first15_canary_provider_rearms AS child
          WHERE child.order_id = parent.order_id
            AND child.rearm_generation = 3
      )
      AND parent.source_failure_code = 'ANALYSIS_V2_MEDIA_ARTIFACT_OBJECT_ERROR'
      AND earlybird_order.status = 'analysis_in_progress'
      AND earlybird_order.result_request_id = request.id
      AND earlybird_order.concierge_apify_credential_slot = 'quinary'
      AND fulfillment.status = 'analysis_in_progress'
      AND fulfillment.request_id = request.id
      AND request.pipeline_version = 'v2'
      AND request.status = 'failed'
      AND request.current_step = 'failed'
      AND request.error_message = 'JOB_ATTEMPTS_EXHAUSTED'
      AND EXISTS (
          SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
          WHERE receipt.request_id = request.id
            AND receipt.failed_job_key = 'track:profile-ai:batch:2'
            AND receipt.error_code = request.error_message
      )
      AND NOT EXISTS (
          SELECT 1 FROM public.analysis_pipeline_jobs AS job
          WHERE job.request_id = request.id
            AND job.status IN ('pending', 'processing', 'retryable')
      )
      AND NOT EXISTS (
          SELECT 1 FROM public.analysis_v2_provider_runs AS provider_run
          WHERE provider_run.request_id = request.id
            AND provider_run.status IN ('starting', 'running')
      )
    ORDER BY error_code, order_id
    LIMIT 24;
$$;


--
-- Name: list_earlybird_first15_canary_provider_runs(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_earlybird_first15_canary_provider_runs(p_request_ids uuid[]) RETURNS TABLE(request_id uuid, job_key text, operation_key text, input_hash text, reservation_token uuid, logical_provider text, actor_id text, credential_slot text, max_charge_usd numeric, status text, run_id text, actual_usage_usd numeric, reserved_at timestamp with time zone, run_started_at timestamp with time zone, terminalized_at timestamp with time zone, usage_reconciled_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_request_count INTEGER;
BEGIN
    v_request_count := pg_catalog.cardinality(p_request_ids);
    IF p_request_ids IS NULL
       OR v_request_count NOT BETWEEN 1 AND 3
       OR EXISTS (
           SELECT 1
           FROM pg_catalog.unnest(p_request_ids) AS requested(request_id)
           WHERE requested.request_id IS NULL
       )
       OR (
           SELECT pg_catalog.count(DISTINCT requested.request_id)
           FROM pg_catalog.unnest(p_request_ids) AS requested(request_id)
       ) <> v_request_count
       OR (
           SELECT pg_catalog.count(*)
           FROM public.list_earlybird_first15_canary_provider_recovery_candidates() AS candidate
           WHERE candidate.request_id = ANY (p_request_ids)
       ) <> v_request_count
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_CANARY_PROVIDER_READ_SCOPE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    RETURN QUERY
    SELECT provider_run.request_id,
        provider_run.job_key::TEXT,
        provider_run.operation_key::TEXT,
        provider_run.input_hash::TEXT,
        provider_run.reservation_token,
        provider_run.logical_provider::TEXT,
        provider_run.actor_id::TEXT,
        provider_run.credential_slot::TEXT,
        provider_run.max_charge_usd,
        provider_run.status::TEXT,
        provider_run.run_id::TEXT,
        provider_run.actual_usage_usd,
        provider_run.reserved_at,
        provider_run.run_started_at,
        provider_run.terminalized_at,
        provider_run.usage_reconciled_at
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = ANY (p_request_ids)
    ORDER BY provider_run.request_id, provider_run.job_key, provider_run.operation_key
    LIMIT 64;
END;
$$;


--
-- Name: list_expired_analysis_provider_admissions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_expired_analysis_provider_admissions(p_limit integer DEFAULT 64) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 64 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;
    -- Preserve the original one-argument RPC contract for mixed-version
    -- callers. The paginated implementation below adds only the cursor key;
    -- old callers must continue to receive the historical shape.
    RETURN public.list_expired_analysis_provider_admissions_page(
        p_limit, NULL, NULL, NULL
    ) - 'nextCursor';
END;
$$;


--
-- Name: list_expired_analysis_provider_admissions_page(integer, timestamp with time zone, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_expired_analysis_provider_admissions_page(p_limit integer DEFAULT 16, p_after_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_fence bigint DEFAULT NULL::bigint, p_after_admission_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 64
       OR ((p_after_expires_at IS NULL OR p_after_fence IS NULL OR p_after_admission_id IS NULL)
           AND NOT (p_after_expires_at IS NULL AND p_after_fence IS NULL AND p_after_admission_id IS NULL))
       OR (p_after_admission_id IS NOT NULL
           AND p_after_admission_id !~ '^[0-9a-f]{64}$') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;
    RETURN (
        WITH eligible AS (
            SELECT lease.admission_id, lease.fence, lease.expires_at
            FROM public.analysis_provider_admission_leases AS lease
            WHERE lease.state IN ('leased', 'recovery_required')
              AND lease.expires_at <= v_now
              AND (
                    p_after_expires_at IS NULL
                    OR (lease.expires_at, lease.fence, lease.admission_id)
                       > (p_after_expires_at, p_after_fence, p_after_admission_id)
              )
            ORDER BY lease.expires_at, lease.fence, lease.admission_id
            LIMIT p_limit + 1
        ), page AS (
            SELECT eligible.admission_id, eligible.fence, eligible.expires_at
            FROM eligible
            ORDER BY eligible.expires_at, eligible.fence, eligible.admission_id
            LIMIT p_limit
        ), overflow AS (
            SELECT count(*) > p_limit AS has_more
            FROM eligible
        ), next_cursor AS (
            SELECT page.expires_at, page.fence, page.admission_id
            FROM page
            ORDER BY page.expires_at DESC, page.fence DESC, page.admission_id DESC
            LIMIT 1
        )
        SELECT pg_catalog.jsonb_build_object(
            'candidates', COALESCE(
                (
                    SELECT pg_catalog.jsonb_agg(
                        pg_catalog.jsonb_build_object(
                            'admissionId', page.admission_id,
                            'fence', page.fence,
                            'expiresAt', page.expires_at
                        )
                        ORDER BY page.expires_at, page.fence, page.admission_id
                    )
                    FROM page
                ),
                '[]'::jsonb
            ),
            'hasMore', (SELECT overflow.has_more FROM overflow),
            'nextCursor', CASE
                WHEN (SELECT overflow.has_more FROM overflow) THEN (
                    SELECT pg_catalog.jsonb_build_object(
                        'expiresAt', next_cursor.expires_at,
                        'fence', next_cursor.fence,
                        'admissionId', next_cursor.admission_id
                    )
                    FROM next_cursor
                )
                ELSE NULL
            END
        )
    );
END;
$_$;


--
-- Name: list_precheckout_blite_dispatch_recovery_v2(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_precheckout_blite_dispatch_recovery_v2(p_limit integer DEFAULT 64) RETURNS TABLE(preflight_id uuid, dispatch_generation integer, dispatch_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 64 THEN
        RAISE EXCEPTION USING MESSAGE = 'PRECHECKOUT_BLITE_DISPATCH_RECOVERY_INVALID_LIMIT', ERRCODE = 'P0001';
    END IF;
    RETURN QUERY
    SELECT dispatch.preflight_id, dispatch.dispatch_generation, dispatch.dispatch_token
    FROM public.precheckout_blite_dispatches AS dispatch
    JOIN public.analysis_preflights AS preflight
      ON preflight.id = dispatch.preflight_id
    JOIN public.precheckout_blite_cache AS cache
      ON cache.preflight_id = dispatch.preflight_id
    WHERE dispatch.state = 'enqueuing'
      AND dispatch.dispatch_token IS NOT NULL
      AND dispatch.dispatch_workload_role IS NOT DISTINCT FROM 'preflight'
      AND dispatch.dispatch_contract_version IS NOT DISTINCT FROM 2
      AND cache.state = 'pending'
      AND preflight.status = 'ready'
      AND preflight.precheckout_blite_cohort = TRUE
      AND (
          dispatch.lease_expires_at <= v_now
          OR dispatch.updated_at <= v_now - INTERVAL '30 seconds'
      )
    ORDER BY dispatch.updated_at, dispatch.preflight_id
    LIMIT p_limit;
END;
$$;


--
-- Name: list_recoverable_earlybird_fulfillments(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_recoverable_earlybird_fulfillments(p_limit integer DEFAULT 20) RETURNS TABLE(order_id uuid, fulfillment_status text, preflight_id uuid, user_id uuid, plan_id text, request_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    RETURN QUERY
    SELECT
        fulfillment.order_id,
        fulfillment.status,
        earlybird_order.preflight_id,
        earlybird_order.user_id,
        earlybird_order.plan_id,
        fulfillment.request_id
    FROM public.earlybird_fulfillments AS fulfillment
    JOIN public.earlybird_orders AS earlybird_order
      ON earlybird_order.id = fulfillment.order_id
    WHERE fulfillment.status IN ('admission_pending', 'retryable_failure')
      AND fulfillment.operator_admitted_at IS NOT NULL
      AND fulfillment.next_attempt_at <= pg_catalog.clock_timestamp()
      AND (
          fulfillment.lease_token IS NULL
          OR fulfillment.lease_expires_at <= pg_catalog.clock_timestamp()
      )
    ORDER BY fulfillment.next_attempt_at, fulfillment.created_at
    LIMIT p_limit;
END;
$$;


--
-- Name: load_account_checkout_phone_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_account_checkout_phone_v1(p_user_id uuid) RETURNS TABLE(id uuid, provider character varying, phone_number character varying, phone_number_normalized text, phone_number_verification_source text, phone_number_verified_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_lifecycle TEXT;
BEGIN
    SELECT account.lifecycle
    INTO v_lifecycle
    FROM public.users AS account
    WHERE account.id = p_user_id;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    IF v_lifecycle <> 'active' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_RETIRED',
            ERRCODE = 'P0001';
    END IF;

    RETURN QUERY
    SELECT account.id,
        account.provider,
        account.phone_number,
        account.phone_number_normalized,
        account.phone_number_verification_source,
        account.phone_number_verified_at
    FROM public.users AS account
    WHERE account.id = p_user_id;
END;
$$;


--
-- Name: load_account_classification_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_account_classification_v1(p_user_id uuid) RETURNS TABLE(id uuid, account_class text, traffic_class text, lifecycle text, classification_version text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT account.id,
        account.account_class,
        account.traffic_class,
        account.lifecycle,
        account.classification_version
    FROM public.users AS account
    WHERE account.id = p_user_id
$$;


--
-- Name: load_account_ledger_rollout_state_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_account_ledger_rollout_state_v1() RETURNS TABLE(paid_ever_state text, classification_command_version text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT rollout.paid_ever_state, rollout.classification_command_version
    FROM public.account_ledger_rollout_state AS rollout
    WHERE rollout.singleton IS TRUE
$$;


--
-- Name: load_account_principal_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_account_principal_v1(p_user_id uuid) RETURNS TABLE(id uuid, email character varying, provider character varying, analysis_count integer, is_paid_user boolean, is_unlimited boolean, created_at timestamp with time zone, updated_at timestamp with time zone, name character varying, nickname character varying, profile_image text, gender character varying, birthyear character varying, account_class text, traffic_class text, lifecycle text, first_paid_at timestamp with time zone, has_active_purchase boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_lifecycle TEXT;
BEGIN
    SELECT account.lifecycle
    INTO v_lifecycle
    FROM public.users AS account
    WHERE account.id = p_user_id;

    IF NOT FOUND THEN
        RETURN;
    END IF;
    IF v_lifecycle <> 'active' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_RETIRED',
            ERRCODE = 'P0001';
    END IF;

    RETURN QUERY
    SELECT account.id,
        account.email,
        account.provider,
        COALESCE(account.analysis_count, 0),
        COALESCE(account.is_paid_user, FALSE),
        COALESCE(account.is_unlimited, FALSE),
        account.created_at,
        account.updated_at,
        account.name,
        account.nickname,
        account.profile_image,
        account.gender,
        account.birthyear,
        account.account_class,
        account.traffic_class,
        account.lifecycle,
        account.first_paid_at,
        EXISTS (
            SELECT 1
            FROM public.account_paid_evidence AS evidence
            JOIN public.earlybird_orders AS paid_order
              ON paid_order.id = evidence.order_id
            WHERE evidence.account_id = account.id
              AND evidence.counts_as_external IS TRUE
              AND paid_order.status IN (
                  'paid', 'analysis_in_progress', 'completed'
              )
        ) AS has_active_purchase
    FROM public.users AS account
    WHERE account.id = p_user_id;
END;
$$;


--
-- Name: load_analysis_apify_account_control_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_apify_account_control_state() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    WITH free_slots(credential_slot) AS (
        VALUES ('primary'::TEXT), ('tertiary'::TEXT),
               ('quaternary'::TEXT), ('quinary'::TEXT),
               ('senary'::TEXT), ('septenary'::TEXT),
               ('octonary'::TEXT), ('nonary'::TEXT), ('tenth'::TEXT)
    )
    SELECT COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
            'credentialSlot', free_slots.credential_slot,
            'excluded', COALESCE(snapshot.manually_excluded, FALSE),
            'updatedAt', snapshot.refreshed_at
        )
        ORDER BY CASE free_slots.credential_slot
            WHEN 'primary' THEN 1 WHEN 'tertiary' THEN 2
            WHEN 'quaternary' THEN 3 WHEN 'quinary' THEN 4
            WHEN 'senary' THEN 5 WHEN 'septenary' THEN 6
            WHEN 'octonary' THEN 7 WHEN 'nonary' THEN 8 WHEN 'tenth' THEN 9
        END
    ), '[]'::JSONB)
    FROM free_slots
    LEFT JOIN public.analysis_apify_credit_snapshots AS snapshot
      ON snapshot.credential_slot = free_slots.credential_slot;
$$;


--
-- Name: load_analysis_apify_account_credit_inventory(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_apify_account_credit_inventory(p_max_age_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_result JSONB;
BEGIN
    IF p_max_age_seconds IS NULL OR p_max_age_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_APIFY_ACCOUNT_INVENTORY_INVALID', ERRCODE = 'P0001';
    END IF;

    WITH required_slots(credential_slot, workload_role, slot_order) AS (
        VALUES
            ('primary'::TEXT, 'free'::TEXT, 1),
            ('secondary'::TEXT, 'paid'::TEXT, 2),
            ('tertiary'::TEXT, 'free'::TEXT, 3),
            ('quaternary'::TEXT, 'free'::TEXT, 4),
            ('quinary'::TEXT, 'free'::TEXT, 5),
            ('senary'::TEXT, 'free'::TEXT, 6),
            ('septenary'::TEXT, 'free'::TEXT, 7),
            ('octonary'::TEXT, 'free'::TEXT, 8),
            ('nonary'::TEXT, 'free'::TEXT, 9),
            ('tenth'::TEXT, 'free'::TEXT, 10)
    ), latest_exclusion AS (
        SELECT snapshot.credential_slot,
               snapshot.manually_excluded AS excluded
        FROM public.analysis_apify_credit_snapshots AS snapshot
        WHERE public.analysis_beta_valid_apify_credential_slot(snapshot.credential_slot)
    ), capacity AS (
        SELECT effective.credential_slot, effective.effective_capacity_usd
        FROM public.analysis_beta_pool_effective_capacity_snapshot() AS effective
    ), inventory AS (
        SELECT required_slots.credential_slot,
               required_slots.workload_role,
               required_slots.slot_order,
               snapshot.health_state,
               snapshot.monthly_limit_usd,
               snapshot.monthly_usage_usd,
               snapshot.billing_cycle_start_at,
               snapshot.billing_cycle_end_at,
               snapshot.observed_at,
               snapshot.refreshed_at,
               capacity.effective_capacity_usd,
               COALESCE(latest_exclusion.excluded, FALSE) AS manually_excluded,
               CASE
                   WHEN snapshot.credential_slot IS NULL
                     OR snapshot.health_state IS DISTINCT FROM 'healthy'
                     OR snapshot.monthly_limit_usd IS NULL
                     OR snapshot.monthly_usage_usd IS NULL
                     OR snapshot.billing_cycle_start_at IS NULL
                     OR snapshot.billing_cycle_end_at IS NULL
                     OR snapshot.observed_at IS NULL
                     THEN 'missing'
                   WHEN snapshot.observed_at < v_now - pg_catalog.make_interval(secs => p_max_age_seconds)
                     OR snapshot.observed_at > v_now + INTERVAL '1 minute'
                     OR snapshot.billing_cycle_start_at > v_now
                     OR snapshot.billing_cycle_end_at <= v_now
                     THEN 'stale'
                   ELSE 'fresh'
               END AS freshness_state
        FROM required_slots
        LEFT JOIN public.analysis_apify_credit_snapshots AS snapshot
          ON snapshot.credential_slot = required_slots.credential_slot
        LEFT JOIN capacity
          ON capacity.credential_slot = required_slots.credential_slot
        LEFT JOIN latest_exclusion
          ON latest_exclusion.credential_slot = required_slots.credential_slot
    )
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'credentialSlot', inventory.credential_slot,
        'workloadRole', inventory.workload_role,
        'healthState', COALESCE(inventory.health_state, 'missing'),
        'freshnessState', inventory.freshness_state,
        'monthlyLimitUsd', inventory.monthly_limit_usd,
        'monthlyUsageUsd', inventory.monthly_usage_usd,
        'effectiveRemainingUsd', CASE
            WHEN inventory.freshness_state <> 'fresh' THEN NULL
            WHEN inventory.workload_role = 'free' THEN inventory.effective_capacity_usd
            ELSE GREATEST(
                inventory.monthly_limit_usd - inventory.monthly_usage_usd,
                0::NUMERIC
            )
        END,
        'billingCycleStartAt', inventory.billing_cycle_start_at,
        'billingCycleEndAt', inventory.billing_cycle_end_at,
        'cycleResetAt', inventory.billing_cycle_end_at,
        'observedAt', inventory.observed_at,
        'refreshedAt', inventory.refreshed_at,
        'manuallyExcluded', CASE
            WHEN inventory.workload_role = 'free' THEN inventory.manually_excluded
            ELSE FALSE
        END
    ) ORDER BY inventory.slot_order)
    INTO v_result
    FROM inventory;

    RETURN COALESCE(v_result, '[]'::JSONB);
END;
$$;


--
-- Name: load_analysis_beta_apify_credit_pool(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_beta_apify_credit_pool(p_max_age_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_result JSONB;
BEGIN
    IF p_max_age_seconds IS NULL OR p_max_age_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INVALID', ERRCODE = 'P0001';
    END IF;
    WITH required_slots(credential_slot, slot_order) AS (
        VALUES ('primary'::TEXT, 1), ('tertiary'::TEXT, 2),
               ('quaternary'::TEXT, 3), ('quinary'::TEXT, 4),
               ('senary'::TEXT, 5), ('septenary'::TEXT, 6),
               ('octonary'::TEXT, 7), ('nonary'::TEXT, 8),
               ('tenth'::TEXT, 9)
    ), held AS (
        SELECT reservation.credential_slot,
               pg_catalog.sum(reservation.reserved_usd) AS reserved_usd
        FROM public.analysis_beta_pool_reservations AS reservation
        WHERE reservation.lifecycle_state IN ('preflight_held', 'active')
        GROUP BY reservation.credential_slot
    ), decorated AS (
        SELECT required_slots.credential_slot,
               required_slots.slot_order,
               snapshot.monthly_limit_usd,
               snapshot.monthly_usage_usd,
               snapshot.billing_cycle_start_at,
               snapshot.billing_cycle_end_at,
               snapshot.observed_at,
               COALESCE(snapshot.health_state, 'unhealthy') AS health_state,
               COALESCE(snapshot.manually_excluded, FALSE) AS manually_excluded,
               CASE
                   WHEN snapshot.credential_slot IS NULL
                     OR snapshot.health_state IS DISTINCT FROM 'healthy'
                     OR snapshot.monthly_limit_usd IS NULL
                     OR snapshot.monthly_usage_usd IS NULL
                     OR snapshot.billing_cycle_start_at IS NULL
                     OR snapshot.billing_cycle_end_at IS NULL
                     OR snapshot.observed_at IS NULL
                     THEN 'missing'
                   WHEN snapshot.observed_at < v_now - pg_catalog.make_interval(secs => p_max_age_seconds)
                     OR snapshot.observed_at > v_now + INTERVAL '1 minute'
                     OR snapshot.billing_cycle_start_at > v_now
                     OR snapshot.billing_cycle_end_at <= v_now
                     THEN 'stale'
                   ELSE 'fresh'
               END AS freshness_state,
               held.reserved_usd
        FROM required_slots
        LEFT JOIN public.analysis_apify_credit_snapshots AS snapshot
          ON snapshot.credential_slot = required_slots.credential_slot
        LEFT JOIN held ON held.credential_slot = required_slots.credential_slot
    )
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'credentialSlot', decorated.credential_slot,
        'monthlyLimitUsd', decorated.monthly_limit_usd,
        'monthlyUsageUsd', decorated.monthly_usage_usd,
        'billingCycleStartAt', decorated.billing_cycle_start_at,
        'billingCycleEndAt', decorated.billing_cycle_end_at,
        'observedAt', decorated.observed_at,
        'healthState', decorated.health_state,
        'freshnessState', decorated.freshness_state,
        'manuallyExcluded', decorated.manually_excluded,
        'effectiveHeadroomUsd', CASE
            WHEN decorated.freshness_state <> 'fresh' THEN NULL
            ELSE GREATEST(
                decorated.monthly_limit_usd - decorated.monthly_usage_usd
                - COALESCE(decorated.reserved_usd, 0::NUMERIC)
                - public.analysis_beta_pool_effective_local_debit_usd(
                    decorated.credential_slot, decorated.observed_at
                ), 0::NUMERIC)
        END
    ) ORDER BY decorated.slot_order)
    INTO v_result
    FROM decorated;
    RETURN v_result;
END;
$$;


--
-- Name: load_analysis_beta_apify_pool_observability(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_beta_apify_pool_observability(p_max_age_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '5s'
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_result JSONB;
BEGIN
    IF p_max_age_seconds IS NULL OR p_max_age_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_OBSERVABILITY_INVALID', ERRCODE = 'P0001';
    END IF;
    WITH required_slots(credential_slot) AS (
        VALUES ('primary'::TEXT), ('tertiary'::TEXT), ('quaternary'::TEXT),
               ('quinary'::TEXT), ('senary'::TEXT), ('septenary'::TEXT),
               ('octonary'::TEXT), ('nonary'::TEXT), ('tenth'::TEXT)
    ), capacity AS (
        SELECT effective.credential_slot, effective.effective_capacity_usd
        FROM public.analysis_beta_pool_effective_capacity_snapshot() AS effective
    ), snapshot_health AS (
        SELECT pg_catalog.count(*) FILTER (
            WHERE snapshot.credential_slot IS NULL
               OR snapshot.health_state IS DISTINCT FROM 'healthy'
               OR snapshot.monthly_limit_usd IS NULL
               OR snapshot.monthly_usage_usd IS NULL
               OR snapshot.observed_at IS NULL
               OR snapshot.billing_cycle_start_at IS NULL
               OR snapshot.billing_cycle_end_at IS NULL
               OR snapshot.observed_at < v_now - pg_catalog.make_interval(secs => p_max_age_seconds)
               OR snapshot.observed_at > v_now + INTERVAL '1 minute'
               OR snapshot.billing_cycle_start_at > v_now
               OR snapshot.billing_cycle_end_at <= v_now
        )::INTEGER AS stale_snapshot_count
        FROM required_slots
        LEFT JOIN public.analysis_apify_credit_snapshots AS snapshot
          ON snapshot.credential_slot = required_slots.credential_slot
    ), capacity_health AS (
        SELECT COALESCE(pg_catalog.sum(GREATEST(COALESCE(capacity.effective_capacity_usd, 0), 0)), 0::NUMERIC)
                   AS total_effective_headroom_usd,
               pg_catalog.count(*) FILTER (WHERE capacity.effective_capacity_usd < 0)::INTEGER
                   AS overcommitted_slot_count
        FROM required_slots
        LEFT JOIN capacity ON capacity.credential_slot = required_slots.credential_slot
    ), allocation_health AS (
        SELECT pg_catalog.count(*) FILTER (
            WHERE allocation.lifecycle_state IN ('preflight_held', 'active')
        )::INTEGER AS active_allocation_count
        FROM public.analysis_beta_pool_allocations AS allocation
    ), terminal_unsettled AS (
        SELECT COALESCE(request.completed_at, allocation.updated_at) AS terminal_at
        FROM public.analysis_beta_pool_allocations AS allocation
        JOIN public.analysis_requests AS request ON request.id = allocation.request_id
        WHERE allocation.lifecycle_state = 'active' AND request.status IN ('completed', 'failed')
        UNION ALL
        SELECT COALESCE(preflight.blocked_at,
                        CASE WHEN preflight.expires_at <= v_now THEN preflight.expires_at END,
                        preflight.updated_at, allocation.updated_at) AS terminal_at
        FROM public.analysis_beta_pool_allocations AS allocation
        JOIN public.analysis_preflights AS preflight ON preflight.id = allocation.preflight_id
        WHERE allocation.lifecycle_state = 'preflight_held'
          AND (preflight.status IN ('blocked', 'expired') OR preflight.expires_at <= v_now)
    ), settlement_health AS (
        SELECT COALESCE(pg_catalog.floor(LEAST(GREATEST(
            EXTRACT(EPOCH FROM (v_now - pg_catalog.min(terminal_at))) * 1000, 0
        ), 31536000000)), 0)::BIGINT AS settlement_lag_ms
        FROM terminal_unsettled
    )
    SELECT pg_catalog.jsonb_build_object(
        'schemaVersion', 1,
        'observedAt', v_now,
        'runtimeEnabled', COALESCE((
            SELECT gate_row.enabled FROM public.analysis_beta_runtime_gate AS gate_row
            WHERE gate_row.singleton = TRUE
        ), FALSE),
        'totalEffectiveHeadroomUsd', capacity_health.total_effective_headroom_usd,
        'staleSnapshotCount', snapshot_health.stale_snapshot_count,
        'activeAllocationCount', allocation_health.active_allocation_count,
        'settlementLagMs', settlement_health.settlement_lag_ms,
        'overcommittedSlotCount', capacity_health.overcommitted_slot_count
    ) INTO v_result
    FROM snapshot_health CROSS JOIN capacity_health
    CROSS JOIN allocation_health CROSS JOIN settlement_health;
    RETURN v_result;
END;
$$;


--
-- Name: load_analysis_beta_apify_preflight_hold(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_beta_apify_preflight_hold(p_preflight_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
    v_reservation public.analysis_beta_pool_reservations%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ALLOCATION_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT allocation.* INTO v_allocation
    FROM public.analysis_beta_pool_allocations AS allocation
    WHERE allocation.preflight_id = p_preflight_id
    FOR KEY SHARE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT reservation.* INTO v_reservation
    FROM public.analysis_beta_pool_reservations AS reservation
    WHERE reservation.allocation_id = v_allocation.id
      AND reservation.operation_family = 'target-profile'
    FOR KEY SHARE;
    IF NOT FOUND
       OR v_allocation.policy_version IS DISTINCT FROM 'betatest-free-pool-v1'
       OR v_allocation.lifecycle_state NOT IN ('preflight_held', 'active')
       OR NOT public.analysis_beta_valid_apify_credential_slot(v_reservation.credential_slot)
       OR v_reservation.reserved_usd IS DISTINCT FROM 0.005200000000
       OR v_reservation.lifecycle_state IS DISTINCT FROM v_allocation.lifecycle_state THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'allocationId', v_allocation.id,
        'preflightId', v_allocation.preflight_id,
        'credentialSlot', v_reservation.credential_slot,
        'targetProfileBudgetUsd', v_reservation.reserved_usd
    );
END;
$$;


--
-- Name: load_analysis_order_audit_bundle(uuid, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_order_audit_bundle(p_request_id uuid, p_section text DEFAULT 'summary'::text, p_cursor integer DEFAULT 0, p_page_size integer DEFAULT 25, p_filter text DEFAULT 'all'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_bundle public.analysis_order_audit_bundles%ROWTYPE;
    v_summary JSONB;
    v_rows JSONB := '[]'::JSONB;
    v_total INTEGER := 0;
    v_section TEXT := pg_catalog.lower(COALESCE(p_section, 'summary'));
    v_filter TEXT := pg_catalog.lower(COALESCE(p_filter, 'all'));
BEGIN
    IF p_request_id IS NULL
       OR p_cursor NOT BETWEEN 0 AND 100000
       OR p_page_size NOT BETWEEN 1 AND 50
       OR p_section IS NOT NULL
          AND NOT (p_section IN ('summary', 'mutuals', 'gender', 'interactions', 'risk'))
       OR v_section NOT IN ('summary', 'mutuals', 'gender', 'interactions', 'risk')
       OR v_filter NOT IN ('all', 'public', 'public_female', 'private', 'comments', 'likes',
                           'candidate_likes', 'tags', 'mentions')
       OR (v_filter = 'public_female' AND v_section <> 'risk') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_ORDER_AUDIT_INVALID_QUERY', ERRCODE = 'P0001';
    END IF;

    SELECT bundle.*
      INTO v_bundle
      FROM public.analysis_order_audit_bundles AS bundle
     WHERE bundle.request_id = p_request_id
     ORDER BY bundle.version DESC
     LIMIT 1;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    v_summary := public.analysis_order_audit_bundle_payload(v_bundle);

    IF v_section = 'summary' THEN
        RETURN pg_catalog.jsonb_build_object(
            'summary', v_summary,
            'section', v_section,
            'rows', '[]'::JSONB,
            'total', 0,
            'nextCursor', NULL
        );
    END IF;

    IF v_section IN ('mutuals', 'gender', 'risk') THEN
        SELECT pg_catalog.count(*)::INTEGER
          INTO v_total
          FROM public.analysis_order_audit_candidates AS candidate
         WHERE candidate.request_id = v_bundle.request_id
           AND candidate.version = v_bundle.version
           AND (
               v_filter = 'all'
               OR (v_filter = 'private' AND candidate.is_private)
               OR (v_filter = 'public' AND NOT candidate.is_private)
               OR (v_filter = 'public_female'
                   AND NOT candidate.is_private
                   AND candidate.final_gender_output = 'female')
           );

        IF v_section = 'mutuals' THEN
            SELECT COALESCE(pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'candidateId', page.candidate_id,
                    'username', page.username,
                    'mutualOrdinal', page.mutual_ordinal,
                    'followingOrdinal', page.following_ordinal,
                    'isPrivate', page.is_private,
                    'isVerified', page.is_verified,
                    'profileAvailable', page.profile_available,
                    'profileImageAvailable', page.profile_image_available,
                    'profileFailureCode', page.profile_failure_code,
                    'finalInclusionState', page.final_inclusion_state,
                    'completeness', CASE
                        WHEN page.profile_available THEN 'complete' ELSE 'partial' END
                ) ORDER BY page.mutual_ordinal NULLS LAST, page.username
            ), '[]'::JSONB)
              INTO v_rows
              FROM (
                  SELECT candidate.*
                    FROM public.analysis_order_audit_candidates AS candidate
                   WHERE candidate.request_id = v_bundle.request_id
                     AND candidate.version = v_bundle.version
                     AND (
                         v_filter = 'all'
                         OR (v_filter = 'private' AND candidate.is_private)
                         OR (v_filter = 'public' AND NOT candidate.is_private)
                         OR (v_filter = 'public_female'
                             AND NOT candidate.is_private
                             AND candidate.final_gender_output = 'female')
                     )
                   ORDER BY candidate.mutual_ordinal NULLS LAST, candidate.username
                   OFFSET p_cursor LIMIT p_page_size
              ) AS page;
        ELSIF v_section = 'gender' THEN
            SELECT COALESCE(pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'candidateId', page.candidate_id,
                    'username', page.username,
                    'isPrivate', page.is_private,
                    'initial', pg_catalog.jsonb_build_object(
                        'output', page.initial_gender_output,
                        'model', page.initial_gender_model,
                        'confidence', page.initial_gender_confidence,
                        'reason', page.initial_gender_reason,
                        'operationKey', page.gender_operation_key,
                        'resultHash', page.gender_result_hash
                    ),
                    'final', pg_catalog.jsonb_build_object(
                        'output', page.final_gender_output,
                        'model', page.final_gender_model,
                        'confidence', page.final_gender_confidence,
                        'reason', page.final_gender_reason,
                        'operationKey', page.gender_resolution_operation_key,
                        'resultHash', page.gender_resolution_result_hash
                    ),
                    'completeness', CASE
                        WHEN page.final_gender_output IS NULL THEN 'partial' ELSE 'complete' END
                ) ORDER BY page.mutual_ordinal NULLS LAST, page.username
            ), '[]'::JSONB)
              INTO v_rows
              FROM (
                  SELECT candidate.*
                    FROM public.analysis_order_audit_candidates AS candidate
                   WHERE candidate.request_id = v_bundle.request_id
                     AND candidate.version = v_bundle.version
                     AND (
                         v_filter = 'all'
                         OR (v_filter = 'private' AND candidate.is_private)
                         OR (v_filter = 'public' AND NOT candidate.is_private)
                         OR (v_filter = 'public_female'
                             AND NOT candidate.is_private
                             AND candidate.final_gender_output = 'female')
                     )
                   ORDER BY candidate.mutual_ordinal NULLS LAST, candidate.username
                   OFFSET p_cursor LIMIT p_page_size
              ) AS page;
        ELSE
            SELECT COALESCE(pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'candidateId', page.candidate_id,
                    'username', page.username,
                    'riskComponents', page.risk_components,
                    'riskFormulaVersion', page.risk_formula_version,
                    'preScore', page.pre_score,
                    'rawScore', page.raw_score,
                    'publicScore', page.public_score,
                    'finalScore', page.final_score,
                    'riskBand', page.risk_band,
                    'finalRank', page.final_rank,
                    'featuredRank', page.featured_rank,
                    'recentMutualRank', page.recent_mutual_rank,
                    'partnerSafety', pg_catalog.jsonb_build_object(
                        'operationKey', page.partner_safety_operation_key,
                        'resultHash', page.partner_safety_result_hash
                    ),
                    'completeness', CASE
                        WHEN page.final_score IS NULL THEN 'partial' ELSE 'complete' END
                ) ORDER BY page.final_rank NULLS LAST, page.username
            ), '[]'::JSONB)
              INTO v_rows
              FROM (
                  SELECT candidate.*
                    FROM public.analysis_order_audit_candidates AS candidate
                   WHERE candidate.request_id = v_bundle.request_id
                     AND candidate.version = v_bundle.version
                     AND (
                         v_filter = 'all'
                         OR (v_filter = 'private' AND candidate.is_private)
                         OR (v_filter = 'public' AND NOT candidate.is_private)
                         OR (v_filter = 'public_female'
                             AND NOT candidate.is_private
                             AND candidate.final_gender_output = 'female')
                     )
                   ORDER BY candidate.final_rank NULLS LAST, candidate.username
                   OFFSET p_cursor LIMIT p_page_size
              ) AS page;
        END IF;
    ELSE
        IF v_filter NOT IN ('all', 'comments', 'likes', 'candidate_likes', 'tags', 'mentions') THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_ORDER_AUDIT_INVALID_QUERY', ERRCODE = 'P0001';
        END IF;
        SELECT pg_catalog.count(*)::INTEGER
          INTO v_total
          FROM public.analysis_order_audit_interactions AS interaction
         WHERE interaction.request_id = v_bundle.request_id
           AND interaction.version = v_bundle.version
           AND (
               v_filter = 'all'
               OR (v_filter = 'comments' AND interaction.signal = 'target_post_comment')
               OR (v_filter = 'likes' AND interaction.signal = 'target_post_like')
               OR (v_filter = 'candidate_likes' AND interaction.signal = 'candidate_post_like')
               OR (v_filter = 'tags' AND interaction.signal = 'tag')
               OR (v_filter = 'mentions' AND interaction.signal = 'mention')
           );
        SELECT COALESCE(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'ordinal', page.ordinal,
                'candidateId', page.candidate_id,
                'username', page.username,
                'signal', page.signal,
                'sourcePostId', page.source_post_id,
                'evidenceId', page.evidence_id,
                'occurredAt', page.occurred_at,
                'commentText', page.comment_text,
                'details', public.analysis_order_audit_redact_json(page.details),
                'completeness', page.completeness_status,
                'gapCodes', pg_catalog.to_jsonb(page.gap_codes)
            ) ORDER BY page.ordinal
        ), '[]'::JSONB)
          INTO v_rows
          FROM (
              SELECT interaction.*
                FROM public.analysis_order_audit_interactions AS interaction
               WHERE interaction.request_id = v_bundle.request_id
                 AND interaction.version = v_bundle.version
                 AND (
                     v_filter = 'all'
                     OR (v_filter = 'comments' AND interaction.signal = 'target_post_comment')
                     OR (v_filter = 'likes' AND interaction.signal = 'target_post_like')
                     OR (v_filter = 'candidate_likes' AND interaction.signal = 'candidate_post_like')
                     OR (v_filter = 'tags' AND interaction.signal = 'tag')
                     OR (v_filter = 'mentions' AND interaction.signal = 'mention')
                 )
               ORDER BY interaction.ordinal
               OFFSET p_cursor LIMIT p_page_size
          ) AS page;
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'summary', v_summary,
        'section', v_section,
        'rows', v_rows,
        'total', v_total,
        'nextCursor', CASE
            WHEN p_cursor + p_page_size < v_total THEN p_cursor + p_page_size
            ELSE NULL
        END
    );
END;
$$;


--
-- Name: load_analysis_owner_history_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_owner_history_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_payload JSONB;
    v_items JSONB;
BEGIN
    v_payload := public.load_analysis_owner_history_v1_legacy();

    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            CASE
                WHEN item.value->>'status' = 'completed'
                     AND NOT public.analysis_result_publication_authorized(
                         (item.value->>'id')::UUID
                     )
                    THEN item.value || pg_catalog.jsonb_build_object(
                        'status', 'pending',
                        'publicFemaleCount', NULL
                    )
                ELSE item.value
            END
            ORDER BY item.ordinality
        ),
        '[]'::JSONB
    )
    INTO v_items
    FROM pg_catalog.jsonb_array_elements(
        COALESCE(v_payload->'items', '[]'::JSONB)
    ) WITH ORDINALITY AS item(value, ordinality);

    RETURN pg_catalog.jsonb_set(v_payload, '{items}', v_items, TRUE);
END;
$$;


--
-- Name: load_analysis_owner_history_v1_legacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_owner_history_v1_legacy() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_lifecycle TEXT;
    v_items JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_OWNER_HISTORY_AUTH_REQUIRED',
            ERRCODE = '42501';
    END IF;

    SELECT account.lifecycle
    INTO v_lifecycle
    FROM public.users AS account
    WHERE account.id = v_user_id;

    IF NOT FOUND OR v_lifecycle <> 'active' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_OWNER_HISTORY_ACCOUNT_RETIRED',
            ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'id', analysis_request.id,
                'targetInstagramId', CASE
                    WHEN analysis_request.pipeline_version = 'v2'
                         AND analysis_request.status = 'completed'
                        THEN result_summary.target_instagram_id
                    WHEN analysis_request.pipeline_version = 'v2'
                         AND analysis_request.target_instagram_id LIKE 'retained.%'
                        THEN NULL
                    ELSE analysis_request.target_instagram_id
                END,
                'status', analysis_request.status,
                'createdAt', analysis_request.created_at,
                'planType', analysis_request.plan_type,
                'pipelineVersion', CASE
                    WHEN analysis_request.pipeline_version = 'v2' THEN 'v2'
                    ELSE 'v1'
                END,
                'publicFemaleCount', CASE
                    WHEN analysis_request.pipeline_version = 'v2'
                         AND analysis_request.status = 'completed'
                        THEN result_summary.female_count
                    ELSE NULL
                END
            )
            ORDER BY analysis_request.created_at DESC NULLS LAST, analysis_request.id DESC
        ),
        '[]'::JSONB
    )
    INTO v_items
    FROM public.analysis_requests AS analysis_request
    LEFT JOIN public.analysis_v2_result_summaries AS result_summary
      ON result_summary.request_id = analysis_request.id
     AND analysis_request.pipeline_version = 'v2'
     AND analysis_request.status = 'completed'
    WHERE analysis_request.user_id = v_user_id
      AND analysis_request.status IN ('pending', 'processing', 'completed');

    RETURN pg_catalog.jsonb_build_object(
        'schemaVersion', 1,
        'items', v_items
    );
END;
$$;


--
-- Name: load_analysis_preflight_provider_run(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_preflight_provider_run(p_preflight_id uuid, p_claim_token uuid, p_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_claim_token IS NULL
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_preflight.expires_at <= v_now
       OR NOT (
            (
                v_preflight.status = 'processing'
                AND v_preflight.lease_token IS NOT DISTINCT FROM p_claim_token
                AND v_preflight.lease_expires_at IS NOT NULL
                AND v_preflight.lease_expires_at > v_now
            )
            OR (
                v_preflight.status = 'ready'
                AND v_preflight.consumed_request_id IS NULL
                AND v_preflight.admission_status = 'processing'
                AND v_preflight.admission_claim_token IS NOT DISTINCT FROM p_claim_token
                AND v_preflight.admission_lease_expires_at IS NOT NULL
                AND v_preflight.admission_lease_expires_at > v_now
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = 'target-profile-fallback';
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    IF v_run.input_hash IS DISTINCT FROM p_input_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    RETURN public.analysis_preflight_provider_run_json(v_run);
END;
$_$;


--
-- Name: load_analysis_v2_ai_operation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_ai_operation(p_request_id uuid, p_operation_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_attempts JSONB;
BEGIN
    IF p_request_id IS NULL
       OR p_operation_key IS NULL
       OR NOT public.analysis_v2_valid_ai_operation_key(p_operation_key)
       OR NOT EXISTS (
            SELECT 1
            FROM public.analysis_requests AS analysis_request
            WHERE analysis_request.id = p_request_id
              AND analysis_request.pipeline_version = 'v2'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            public.analysis_v2_ai_attempt_json(ai_attempt)
            ORDER BY ai_attempt.attempt
        ),
        '[]'::JSONB
    )
    INTO v_attempts
    FROM public.analysis_v2_ai_attempts AS ai_attempt
    WHERE ai_attempt.request_id = p_request_id
      AND ai_attempt.operation_key = p_operation_key;

    RETURN v_attempts;
END;
$$;


--
-- Name: load_analysis_v2_ai_result_checkpoint(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_ai_result_checkpoint(p_request_id uuid, p_operation_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_checkpoint public.analysis_v2_ai_result_checkpoints%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_operation_key IS NULL
       OR NOT public.analysis_v2_valid_ai_operation_key(p_operation_key) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_RESULT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_RESULT_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    SELECT checkpoint.*
    INTO v_checkpoint
    FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
    WHERE checkpoint.request_id = p_request_id
      AND checkpoint.operation_key = p_operation_key;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    RETURN public.analysis_v2_ai_result_checkpoint_json(v_checkpoint);
END;
$$;


--
-- Name: load_analysis_v2_ai_scoring_stage(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_ai_scoring_stage(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_stage_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_stored public.analysis_v2_ai_scoring_stage_checkpoints%ROWTYPE;
BEGIN
    IF p_stage_kind = 'profile_ai_batch' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_SCORING_STAGE_INVALID', ERRCODE = 'P0001';
    END IF;
    v_job := public.analysis_v2_assert_result_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    PERFORM public.analysis_v2_assert_ai_scoring_stage_consumer(v_job, p_stage_kind);
    SELECT checkpoint.* INTO v_stored
    FROM public.analysis_v2_ai_scoring_stage_checkpoints AS checkpoint
    WHERE checkpoint.request_id = p_request_id
      AND checkpoint.stage_kind = p_stage_kind
      AND checkpoint.batch_key = -1;
    IF NOT FOUND THEN RETURN NULL; END IF;
    RETURN public.analysis_v2_ai_scoring_stage_envelope(v_stored);
END;
$$;


--
-- Name: load_analysis_v2_ai_stage_policy_version(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_ai_stage_policy_version(p_request_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT analysis_request.policy_versions_snapshot->>'aiStage'
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2';
$$;


--
-- Name: load_analysis_v2_apify_secret_ref_prune_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_apify_secret_ref_prune_fence() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_guard public.analysis_v2_apify_secret_ref_prune_guard%ROWTYPE;
BEGIN
    SELECT guard.*
    INTO v_guard
    FROM public.analysis_v2_apify_secret_ref_prune_guard AS guard
    WHERE guard.singleton IS TRUE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_GUARD_CORRUPT',
            ERRCODE = 'P0001';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'active', v_guard.drop_slots IS NOT NULL,
        'dropSlots', pg_catalog.to_jsonb(v_guard.drop_slots),
        'ownerSourceCommitSha', v_guard.owner_source_commit_sha
    );
END;
$$;


--
-- Name: load_analysis_v2_betatest_consumed_replay(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_betatest_consumed_replay(p_preflight_id uuid, p_user_id uuid, p_selected_plan_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_replay JSONB;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_selected_plan_id IS NULL
       OR p_selected_plan_id NOT IN ('basic', 'standard', 'plus') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_REQUEST_NOT_ELIGIBLE', ERRCODE = 'P0001';
    END IF;

    -- Deliberately unlocked. Locking this row here would invert the canonical
    -- replay validator's user -> preflight order.
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id;

    IF NOT FOUND
       OR v_preflight.user_id IS DISTINCT FROM p_user_id
       OR v_preflight.beta_entry_provenance IS NULL
       OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'betatest' THEN
        RETURN NULL;
    END IF;

    IF v_preflight.status IS DISTINCT FROM 'consumed' THEN
        IF v_preflight.consumed_request_id IS NOT NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN NULL;
    END IF;

    IF v_preflight.admission_selected_plan_id
            IS DISTINCT FROM p_selected_plan_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_PLAN_REPLAY_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_preflight.consumed_request_id IS NULL
       OR v_preflight.admission_token IS NULL
       OR v_preflight.admission_generation IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
    END IF;

    v_replay := public.analysis_v2_betatest_plan_replay_internal(
        p_preflight_id,
        p_user_id,
        v_preflight.admission_token,
        v_preflight.admission_generation,
        p_selected_plan_id
    );
    IF v_replay IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_ALLOCATION_CONFLICT', ERRCODE = 'P0001';
    END IF;
    RETURN v_replay;
END;
$$;


--
-- Name: load_analysis_v2_betatest_plan_replay(uuid, uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_betatest_plan_replay(p_preflight_id uuid, p_user_id uuid, p_admission_token uuid, p_admission_generation integer, p_selected_plan_id text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT public.analysis_v2_betatest_plan_replay_internal(
        p_preflight_id,
        p_user_id,
        p_admission_token,
        p_admission_generation,
        p_selected_plan_id
    );
$$;


--
-- Name: load_analysis_v2_collection_context_with_policy(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_collection_context_with_policy(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE v_now TIMESTAMP WITH TIME ZONE;
DECLARE v_preflight public.analysis_preflights%ROWTYPE;
DECLARE v_request public.analysis_requests%ROWTYPE;
DECLARE v_job public.analysis_pipeline_jobs%ROWTYPE;
DECLARE v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
DECLARE v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
DECLARE v_beta_reservation_count INTEGER := 0;
DECLARE v_beta_reservation_drift BOOLEAN := FALSE;
DECLARE v_detailed_limit INTEGER;
BEGIN
    IF p_request_id IS NULL OR p_job_key IS NULL OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160 OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$' OR p_claim_token IS NULL OR p_job_input_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_COLLECTION_CONTEXT_INVALID', ERRCODE = 'P0001'; END IF;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight WHERE preflight.consumed_request_id = p_request_id FOR UPDATE;
    SELECT analysis_request.* INTO v_request FROM public.analysis_requests AS analysis_request WHERE analysis_request.id = p_request_id FOR UPDATE;
    SELECT job.* INTO v_job FROM public.analysis_pipeline_jobs AS job WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    SELECT policy.* INTO v_policy FROM public.analysis_v2_provider_execution_policies AS policy WHERE policy.request_id = p_request_id;
    IF v_request.analysis_entry_channel = 'betatest' THEN
        SELECT allocation.* INTO v_allocation FROM public.analysis_beta_pool_allocations AS allocation WHERE allocation.request_id = p_request_id FOR UPDATE;
        IF v_allocation.id IS NOT NULL THEN
            PERFORM 1 FROM public.analysis_beta_pool_reservations AS reservation WHERE reservation.allocation_id = v_allocation.id ORDER BY reservation.operation_family FOR UPDATE;
            SELECT pg_catalog.count(*)::INTEGER,
                   COALESCE(pg_catalog.bool_or(
                       reservation.lifecycle_state IS DISTINCT FROM 'active'
                       OR reservation.credential_slot IS DISTINCT FROM v_allocation.operation_slot_map->>reservation.operation_family
                       OR reservation.reserved_usd IS DISTINCT FROM (v_allocation.operation_budget_map->>reservation.operation_family)::NUMERIC
                   ), FALSE)
            INTO v_beta_reservation_count, v_beta_reservation_drift
            FROM public.analysis_beta_pool_reservations AS reservation
            WHERE reservation.allocation_id = v_allocation.id;
        END IF;
    END IF;
    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.id IS NULL OR v_preflight.status <> 'consumed' OR v_preflight.target_followers_count IS NULL OR v_preflight.target_following_count IS NULL OR v_preflight.target_instagram_id IS DISTINCT FROM pg_catalog.lower(v_request.target_instagram_id) OR v_preflight.excluded_instagram_id IS DISTINCT FROM v_request.excluded_instagram_id OR v_preflight.access_mode IS DISTINCT FROM v_request.plan_access_mode_snapshot OR v_request.id IS NULL OR v_request.pipeline_version IS DISTINCT FROM 'v2' OR v_request.status NOT IN ('pending','processing') OR v_request.plan_access_mode_snapshot NOT IN ('production','test_entitlement') OR (v_policy.request_id IS NOT NULL AND v_policy.target_instagram_id IS DISTINCT FROM pg_catalog.lower(v_request.target_instagram_id)) OR (v_request.plan_access_mode_snapshot = 'production' AND v_policy.request_id IS NOT NULL AND NOT (v_request.analysis_entry_channel = 'betatest' AND v_preflight.analysis_entry_channel = 'betatest' AND v_policy.mode = 'betatest_free_pool' AND v_policy.policy_version = 'betatest-free-pool-v1' AND v_policy.entitlement_jti_hash IS NULL AND v_allocation.lifecycle_state = 'active' AND v_allocation.request_id IS NOT DISTINCT FROM v_request.id AND v_allocation.preflight_id = v_preflight.id AND v_allocation.user_id IS NOT DISTINCT FROM v_request.user_id AND v_allocation.selected_plan_id IS NOT DISTINCT FROM v_request.selected_plan_id_snapshot AND v_allocation.policy_version IS NOT DISTINCT FROM v_policy.policy_version AND public.analysis_beta_valid_operation_slot_map(v_allocation.operation_slot_map) AND public.analysis_beta_valid_operation_budget_map(v_allocation.operation_budget_map) AND v_allocation.operation_slot_map IS NOT DISTINCT FROM v_policy.operation_slot_map AND v_policy.operation_slot_map IS NOT DISTINCT FROM v_allocation.operation_slot_map AND v_policy.policy_hash = public.analysis_beta_provider_policy_hash(pg_catalog.lower(v_request.target_instagram_id), v_policy.operation_slot_map) AND v_beta_reservation_count = 8 AND NOT v_beta_reservation_drift)) OR (v_request.analysis_entry_channel = 'betatest' AND (v_policy.request_id IS NULL OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'betatest' OR v_policy.mode IS DISTINCT FROM 'betatest_free_pool' OR v_policy.policy_version IS DISTINCT FROM 'betatest-free-pool-v1' OR v_policy.entitlement_jti_hash IS NOT NULL OR v_allocation.lifecycle_state IS DISTINCT FROM 'active' OR v_allocation.request_id IS DISTINCT FROM v_request.id OR v_allocation.preflight_id IS DISTINCT FROM v_preflight.id OR v_allocation.user_id IS DISTINCT FROM v_request.user_id OR v_allocation.selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot OR v_allocation.policy_version IS DISTINCT FROM v_policy.policy_version OR NOT public.analysis_beta_valid_operation_slot_map(v_allocation.operation_slot_map) OR NOT public.analysis_beta_valid_operation_budget_map(v_allocation.operation_budget_map) OR v_allocation.operation_slot_map IS DISTINCT FROM v_policy.operation_slot_map OR v_policy.policy_hash IS DISTINCT FROM public.analysis_beta_provider_policy_hash(pg_catalog.lower(v_request.target_instagram_id), v_policy.operation_slot_map) OR v_beta_reservation_count <> 8 OR v_beta_reservation_drift)) OR v_request.selected_plan_id_snapshot NOT IN ('basic','standard','plus') OR v_request.analysis_scope_snapshot IS NULL OR v_job.request_id IS NULL OR v_job.status <> 'processing' OR v_job.input_hash IS DISTINCT FROM p_job_input_hash OR v_job.lease_token IS DISTINCT FROM p_claim_token OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at <= v_now THEN RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_COLLECTION_CONTEXT_FENCE_MISMATCH', ERRCODE = 'P0001'; END IF;
    v_detailed_limit := (v_request.analysis_scope_snapshot->>'detailedMutualLimit')::INTEGER;
    IF v_detailed_limit NOT IN (300,600,900) OR v_preflight.target_followers_count > (v_request.analysis_scope_snapshot->'relationshipCapacity'->>'followers')::INTEGER OR v_preflight.target_following_count > (v_request.analysis_scope_snapshot->'relationshipCapacity'->>'following')::INTEGER THEN RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_COLLECTION_CONTEXT_INVALID', ERRCODE = 'P0001'; END IF;
    RETURN pg_catalog.jsonb_build_object('requestId',v_request.id,'targetUsername',pg_catalog.lower(v_request.target_instagram_id),'excludedUsername',v_request.excluded_instagram_id,'accessMode',v_request.plan_access_mode_snapshot,'providerExecutionPolicy',CASE WHEN v_policy.request_id IS NULL THEN NULL WHEN v_policy.mode = 'betatest_free_pool' THEN pg_catalog.jsonb_build_object('mode',v_policy.mode,'policyVersion',v_policy.policy_version,'operationSlots',v_policy.operation_slot_map,'operationBudgets',v_allocation.operation_budget_map) ELSE pg_catalog.jsonb_build_object('mode',v_policy.mode,'policyVersion',v_policy.policy_version,'operationSlots',v_policy.operation_slot_map) END,'planId',v_request.selected_plan_id_snapshot,'followersDeclaredCount',v_preflight.target_followers_count,'followingDeclaredCount',v_preflight.target_following_count,'detailedMutualLimit',v_detailed_limit);
END;
$_$;


--
-- Name: load_analysis_v2_collection_context_with_policy_v2(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_collection_context_with_policy_v2(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE v_now TIMESTAMP WITH TIME ZONE;
DECLARE v_preflight public.analysis_preflights%ROWTYPE;
DECLARE v_request public.analysis_requests%ROWTYPE;
DECLARE v_job public.analysis_pipeline_jobs%ROWTYPE;
DECLARE v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
DECLARE v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
DECLARE v_beta_reservation_count INTEGER := 0;
DECLARE v_beta_reservation_drift BOOLEAN := FALSE;
DECLARE v_detailed_limit INTEGER;
BEGIN
    IF p_request_id IS NULL OR p_job_key IS NULL OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160 OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$' OR p_claim_token IS NULL OR p_job_input_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_COLLECTION_CONTEXT_INVALID', ERRCODE = 'P0001'; END IF;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight WHERE preflight.consumed_request_id = p_request_id FOR UPDATE;
    SELECT analysis_request.* INTO v_request FROM public.analysis_requests AS analysis_request WHERE analysis_request.id = p_request_id FOR UPDATE;
    SELECT job.* INTO v_job FROM public.analysis_pipeline_jobs AS job WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    SELECT policy.* INTO v_policy FROM public.analysis_v2_provider_execution_policies AS policy WHERE policy.request_id = p_request_id;
    IF v_request.analysis_entry_channel = 'betatest' THEN
        SELECT allocation.* INTO v_allocation FROM public.analysis_beta_pool_allocations AS allocation WHERE allocation.request_id = p_request_id FOR UPDATE;
        IF v_allocation.id IS NOT NULL THEN
            PERFORM 1 FROM public.analysis_beta_pool_reservations AS reservation WHERE reservation.allocation_id = v_allocation.id ORDER BY reservation.operation_family FOR UPDATE;
            SELECT pg_catalog.count(*)::INTEGER,
                   COALESCE(pg_catalog.bool_or(
                       reservation.lifecycle_state IS DISTINCT FROM 'active'
                       OR reservation.credential_slot IS DISTINCT FROM v_allocation.operation_slot_map->>reservation.operation_family
                       OR reservation.reserved_usd IS DISTINCT FROM (v_allocation.operation_budget_map->>reservation.operation_family)::NUMERIC
                   ), FALSE)
            INTO v_beta_reservation_count, v_beta_reservation_drift
            FROM public.analysis_beta_pool_reservations AS reservation
            WHERE reservation.allocation_id = v_allocation.id;
        END IF;
    END IF;
    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.id IS NULL OR v_preflight.status <> 'consumed' OR v_preflight.target_followers_count IS NULL OR v_preflight.target_following_count IS NULL OR v_preflight.target_instagram_id IS DISTINCT FROM pg_catalog.lower(v_request.target_instagram_id) OR v_preflight.excluded_instagram_id IS DISTINCT FROM v_request.excluded_instagram_id OR v_preflight.access_mode IS DISTINCT FROM v_request.plan_access_mode_snapshot OR v_request.id IS NULL OR v_request.pipeline_version IS DISTINCT FROM 'v2' OR v_request.status NOT IN ('pending','processing') OR v_request.plan_access_mode_snapshot NOT IN ('production','test_entitlement') OR (v_policy.request_id IS NOT NULL AND v_policy.target_instagram_id IS DISTINCT FROM pg_catalog.lower(v_request.target_instagram_id)) OR (v_request.plan_access_mode_snapshot = 'production' AND v_policy.request_id IS NOT NULL AND NOT (v_request.analysis_entry_channel = 'betatest' AND v_preflight.analysis_entry_channel = 'betatest' AND v_policy.mode = 'betatest_free_pool' AND v_policy.policy_version = 'betatest-free-pool-v1' AND v_policy.entitlement_jti_hash IS NULL AND v_allocation.lifecycle_state = 'active' AND v_allocation.request_id IS NOT DISTINCT FROM v_request.id AND v_allocation.preflight_id = v_preflight.id AND v_allocation.user_id IS NOT DISTINCT FROM v_request.user_id AND v_allocation.selected_plan_id IS NOT DISTINCT FROM v_request.selected_plan_id_snapshot AND v_allocation.policy_version IS NOT DISTINCT FROM v_policy.policy_version AND public.analysis_beta_valid_operation_slot_map(v_allocation.operation_slot_map) AND public.analysis_beta_valid_operation_budget_map(v_allocation.operation_budget_map) AND v_allocation.operation_slot_map IS NOT DISTINCT FROM v_policy.operation_slot_map AND v_policy.operation_slot_map IS NOT DISTINCT FROM v_allocation.operation_slot_map AND v_policy.policy_hash = public.analysis_beta_provider_policy_hash(pg_catalog.lower(v_request.target_instagram_id), v_policy.operation_slot_map) AND v_beta_reservation_count = 8 AND NOT v_beta_reservation_drift)) OR (v_request.analysis_entry_channel = 'betatest' AND (v_policy.request_id IS NULL OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'betatest' OR v_policy.mode IS DISTINCT FROM 'betatest_free_pool' OR v_policy.policy_version IS DISTINCT FROM 'betatest-free-pool-v1' OR v_policy.entitlement_jti_hash IS NOT NULL OR v_allocation.lifecycle_state IS DISTINCT FROM 'active' OR v_allocation.request_id IS DISTINCT FROM v_request.id OR v_allocation.preflight_id IS DISTINCT FROM v_preflight.id OR v_allocation.user_id IS DISTINCT FROM v_request.user_id OR v_allocation.selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot OR v_allocation.policy_version IS DISTINCT FROM v_policy.policy_version OR NOT public.analysis_beta_valid_operation_slot_map(v_allocation.operation_slot_map) OR NOT public.analysis_beta_valid_operation_budget_map(v_allocation.operation_budget_map) OR v_allocation.operation_slot_map IS DISTINCT FROM v_policy.operation_slot_map OR v_policy.policy_hash IS DISTINCT FROM public.analysis_beta_provider_policy_hash(pg_catalog.lower(v_request.target_instagram_id), v_policy.operation_slot_map) OR v_beta_reservation_count <> 8 OR v_beta_reservation_drift)) OR v_request.selected_plan_id_snapshot NOT IN ('basic','standard','plus') OR v_request.analysis_scope_snapshot IS NULL OR v_job.request_id IS NULL OR v_job.status <> 'processing' OR v_job.input_hash IS DISTINCT FROM p_job_input_hash OR v_job.lease_token IS DISTINCT FROM p_claim_token OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at <= v_now THEN RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_COLLECTION_CONTEXT_FENCE_MISMATCH', ERRCODE = 'P0001'; END IF;
    v_detailed_limit := (v_request.analysis_scope_snapshot->>'detailedMutualLimit')::INTEGER;
    IF v_detailed_limit NOT IN (300,600,900) OR v_preflight.target_followers_count > (v_request.analysis_scope_snapshot->'relationshipCapacity'->>'followers')::INTEGER OR v_preflight.target_following_count > (v_request.analysis_scope_snapshot->'relationshipCapacity'->>'following')::INTEGER THEN RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_COLLECTION_CONTEXT_INVALID', ERRCODE = 'P0001'; END IF;
    RETURN pg_catalog.jsonb_build_object('requestId',v_request.id,'targetUsername',pg_catalog.lower(v_request.target_instagram_id),'excludedUsername',v_request.excluded_instagram_id,'accessMode',v_request.plan_access_mode_snapshot,'providerExecutionPolicy',CASE WHEN v_policy.request_id IS NULL THEN NULL WHEN v_policy.mode = 'betatest_free_pool' THEN pg_catalog.jsonb_build_object('mode',v_policy.mode,'policyVersion',v_policy.policy_version,'operationSlots',v_policy.operation_slot_map,'operationBudgets',v_allocation.operation_budget_map) ELSE pg_catalog.jsonb_build_object('mode',v_policy.mode,'policyVersion',v_policy.policy_version,'operationSlots',v_policy.operation_slot_map) END,'planId',v_request.selected_plan_id_snapshot,'followersDeclaredCount',v_preflight.target_followers_count,'followingDeclaredCount',v_preflight.target_following_count,'detailedMutualLimit',v_detailed_limit,'orderScopedCredentialSlot',(
            SELECT earlybird_order.concierge_apify_credential_slot
            FROM public.earlybird_fulfillments AS fulfillment
            JOIN public.earlybird_orders AS earlybird_order
              ON earlybird_order.id = fulfillment.order_id
            WHERE fulfillment.request_id = v_request.id
        ));
END;
$_$;


--
-- Name: load_analysis_v2_collection_request_context(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_collection_request_context(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_detailed_limit INTEGER;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_COLLECTION_CONTEXT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;

    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.id IS NULL
       OR v_preflight.status <> 'consumed'
       OR v_preflight.target_followers_count IS NULL
       OR v_preflight.target_following_count IS NULL
       OR v_preflight.target_instagram_id IS DISTINCT FROM
            pg_catalog.lower(v_request.target_instagram_id)
       OR v_preflight.excluded_instagram_id IS DISTINCT FROM
            v_request.excluded_instagram_id
       OR v_request.id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR v_request.selected_plan_id_snapshot NOT IN ('basic', 'standard', 'plus')
       OR v_request.analysis_scope_snapshot IS NULL
       OR v_job.request_id IS NULL
       OR v_job.status <> 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_COLLECTION_CONTEXT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    v_detailed_limit := (
        v_request.analysis_scope_snapshot->>'detailedMutualLimit'
    )::INTEGER;
    IF v_detailed_limit NOT IN (300, 600, 900)
       OR v_preflight.target_followers_count > (
            v_request.analysis_scope_snapshot->'relationshipCapacity'->>'followers'
       )::INTEGER
       OR v_preflight.target_following_count > (
            v_request.analysis_scope_snapshot->'relationshipCapacity'->>'following'
       )::INTEGER THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_COLLECTION_CONTEXT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', v_request.id,
        'targetUsername', pg_catalog.lower(v_request.target_instagram_id),
        'excludedUsername', v_request.excluded_instagram_id,
        'planId', v_request.selected_plan_id_snapshot,
        'followersDeclaredCount', v_preflight.target_followers_count,
        'followingDeclaredCount', v_preflight.target_following_count,
        'detailedMutualLimit', v_detailed_limit
    );
END;
$_$;


--
-- Name: load_analysis_v2_cost_rollup(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_cost_rollup(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_rollup JSONB;
BEGIN
    IF p_request_id IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT pg_catalog.to_jsonb(rollup)
      INTO v_rollup
      FROM public.analysis_v2_cost_rollups AS rollup
     WHERE rollup.request_id = p_request_id;
    IF v_rollup IS NOT NULL THEN
        RETURN v_rollup;
    END IF;

    SELECT pg_catalog.to_jsonb(snapshot)
      INTO v_rollup
      FROM public.analysis_v2_cost_rollup_snapshots AS snapshot
     WHERE snapshot.request_id = p_request_id;
    RETURN v_rollup;
END;
$$;


--
-- Name: load_analysis_v2_dag_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_dag_state(p_request_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT public.analysis_v2_dag_state_json(p_request_id);
$$;


--
-- Name: load_analysis_v2_finalizer_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_finalizer_readiness(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_payload JSONB;
BEGIN
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_OBSERVABILITY_INVALID',
            ERRCODE = 'P0001';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = p_request_id
          AND analysis_request.pipeline_version = 'v2'
    ) THEN
        RETURN NULL;
    END IF;

    WITH request_row AS (
        SELECT analysis_request.*
        FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = p_request_id
    ),
    preflight AS (
        SELECT analysis_preflight.*
        FROM public.analysis_preflights AS analysis_preflight
        WHERE analysis_preflight.consumed_request_id = p_request_id
    ),
    relationship AS (
        SELECT manifest.*
        FROM public.analysis_v2_relationship_manifests AS manifest
        WHERE manifest.request_id = p_request_id
          AND manifest.job_key = 'track:relationships:collect'
    ),
    followers AS (
        SELECT side.*
        FROM public.analysis_v2_relationship_sides AS side
        WHERE side.request_id = p_request_id
          AND side.job_key = 'track:relationships:collect'
          AND side.side = 'followers'
    ),
    following AS (
        SELECT side.*
        FROM public.analysis_v2_relationship_sides AS side
        WHERE side.request_id = p_request_id
          AND side.job_key = 'track:relationships:collect'
          AND side.side = 'following'
    ),
    counts AS (
        SELECT
            (
                SELECT pg_catalog.count(*)::INTEGER
                FROM public.analysis_v2_dag_stage_manifests AS stage
                WHERE stage.request_id = p_request_id
            ) AS stage_count,
            (
                SELECT COALESCE(pg_catalog.sum(topology.item_count), 0)::INTEGER
                FROM public.analysis_v2_dag_batch_topology AS topology
                WHERE topology.request_id = p_request_id
                  AND topology.topology_kind = 'profile'
            ) AS profile_topology_count,
            (
                SELECT COALESCE(pg_catalog.sum(topology.item_count), 0)::INTEGER
                FROM public.analysis_v2_dag_batch_topology AS topology
                WHERE topology.request_id = p_request_id
                  AND topology.topology_kind = 'private_name'
            ) AS private_topology_count,
            (
                SELECT pg_catalog.count(*)::INTEGER
                FROM public.analysis_v2_candidate_feature_rows AS feature
                WHERE feature.request_id = p_request_id
            ) AS feature_count,
            (
                SELECT pg_catalog.count(*)::INTEGER
                FROM public.analysis_v2_private_name_rows AS private_name
                WHERE private_name.request_id = p_request_id
            ) AS private_count,
            (
                SELECT pg_catalog.count(*)::INTEGER
                FROM public.analysis_v2_candidate_feature_rows AS feature
                WHERE feature.request_id = p_request_id
                  AND feature.terminal_classification = 'verified_female'
            ) AS verified_count,
            (
                SELECT pg_catalog.count(*)::INTEGER
                FROM public.analysis_v2_preliminary_score_rows AS preliminary
                WHERE preliminary.request_id = p_request_id
                  AND preliminary.verification_shortlist_rank IS NOT NULL
            ) AS shortlist_count
    ),
    checks AS (
        SELECT
            NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_provider_cleanup_intents AS intent
                WHERE intent.request_id = p_request_id
                  AND intent.completed_at IS NULL
            ) AND NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_provider_runs AS provider_run
                WHERE provider_run.request_id = p_request_id
                  AND provider_run.status IN ('starting', 'running')
            ) AS providerCleanupReady,
            EXISTS (
                SELECT 1
                FROM request_row
                JOIN preflight ON TRUE
                JOIN relationship ON TRUE
                JOIN followers ON TRUE
                JOIN following ON TRUE
                WHERE preflight.target_followers_count = followers.declared_count
                  AND preflight.target_following_count = following.declared_count
                  AND followers.collected_count * 100
                        >= followers.declared_count * 99
                  AND following.collected_count * 100
                        >= following.declared_count * 99
                  AND relationship.followers_result_hash = followers.result_hash
                  AND relationship.following_result_hash = following.result_hash
                  AND relationship.excluded_username
                        IS NOT DISTINCT FROM request_row.excluded_instagram_id
                  AND relationship.detailed_mutual_limit = (
                        request_row.analysis_scope_snapshot->>'detailedMutualLimit'
                  )::INTEGER
                  AND relationship.detailed_public_count = LEAST(
                        relationship.public_count,
                        relationship.detailed_mutual_limit
                  )
                  AND EXISTS (
                        SELECT 1
                        FROM public.analysis_v2_dag_scopes AS scope
                        WHERE scope.request_id = p_request_id
                          AND scope.plan_id =
                                request_row.selected_plan_id_snapshot
                          AND scope.excluded_count = CASE
                                WHEN request_row.exclusion_decision_snapshot = 'exclude'
                                THEN 1 ELSE 0
                          END
                          AND scope.exclusion_decision_hash =
                                
public.analysis_v2_dag_hash_json(
                                pg_catalog.jsonb_build_object(
                                    'domain', 'analysis-v2-exclusion-decision-v1',
                                    'requestId', p_request_id,
                                    'decision',
                                        request_row.exclusion_decision_snapshot,
                                    'excludedInstagramId',
                                        request_row.excluded_instagram_id
                                )
                          )
                  )
                  AND EXISTS (
                        SELECT 1
                        FROM public.analysis_v2_dag_stage_manifests AS stage
                        WHERE stage.request_id = p_request_id
                          AND stage.stage_kind = 'relationships'
                          AND stage.result_hash = relationship.result_hash
                          AND stage.detected_mutual_count =
                                relationship.mutual_count
                          AND stage.public_count = relationship.public_count
                          AND stage.private_count = relationship.private_count
                          AND stage.detailed_selected_public_count =
                                relationship.detailed_public_count
                  )
            ) AS relationshipEnvelopeReady,
            EXISTS (
                SELECT 1
                FROM public.analysis_v2_target_evidence_manifests AS evidence
                JOIN public.analysis_v2_dag_stage_manifests AS stage
                  ON stage.request_id = evidence.request_id
                 AND stage.stage_kind = 'target_evidence'
                 AND stage.result_hash = evidence.result_hash
                 AND stage.interactor_count = evidence.interactor_count
                CROSS JOIN request_row
                WHERE evidence.request_id = p_request_id
                  AND evidence.job_key = 'track:target-evidence:collect'
                  AND evidence.target_username =
                        pg_catalog.lower(request_row.target_instagram_id)
                  AND evidence.excluded_username IS NOT DISTINCT FROM
                        request_row.excluded_instagram_id
            ) AS targetEvidenceReady,
            counts.stage_count = 8 AS stageCountReady,
            counts.profile_topology_count = COALESCE(
                (SELECT relationship.detailed_public_count FROM relationship),
                -1
            )
                AND counts.profile_topology_count = counts.feature_count
                AS profileCountsReady,
            counts.private_topology_count = COALESCE(
                (SELECT relationship.private_count FROM relationship),
                -1
            )
                AND counts.private_topology_count = counts.private_count
                AS privateCountsReady,
            NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_dag_batch_topology AS topology
                LEFT JOIN public.analysis_v2_dag_batch_results AS fetch_result
                  ON fetch_result.request_id = topology.request_id
                 AND fetch_result.result_kind = 'profile_fetch'
                 AND fetch_result.batch = topology.batch
                 AND fetch_result.item_count = topology.item_count
                LEFT JOIN public.analysis_v2_dag_batch_results AS ai_result
                  ON ai_result.request_id = topology.request_id
                 AND ai_result.result_kind = 'profile_ai'
                 AND ai_result.batch = topology.batch
                 AND ai_result.item_count = topology.item_count
                LEFT JOIN public.analysis_v2_candidate_feature_manifests
                    AS feature_manifest
                  ON feature_manifest.request_id = topology.request_id
                 AND feature_manifest.batch = topology.batch
                 AND feature_manifest.item_count = topology.item_count
                 AND feature_manifest.row_count = topology.item_count
                 AND feature_manifest.producer_input_hash =
                        ai_result.producer_input_hash
                LEFT JOIN public.analysis_v2_ai_scoring_stage_checkpoints
                    AS rich_stage
                  ON rich_stage.request_id = topology.request_id
                 AND rich_stage.stage_kind = 'profile_ai_batch'
                 AND rich_stage.batch_key = topology.batch
                 AND rich_stage.producer_input_hash =
                        ai_result.producer_input_hash
                 AND rich_stage.result_hash = ai_result.result_hash
                 AND rich_stage.item_count = topology.item_count
                WHERE topology.request_id = p_request_id
                  AND topology.topology_kind = 'profile'
                  AND (
                        fetch_result.request_id IS NULL
                        OR ai_result.request_id IS NULL
                        OR feature_manifest.request_id IS NULL
                        OR rich_stage.request_id IS NULL
                  )
            ) AS profileBatchesReady,
            NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_dag_batch_topology AS topology
                LEFT JOIN public.analysis_v2_dag_batch_results AS private_result
                  ON private_result.request_id = topology.request_id
                 AND private_result.result_kind = 'private_name'
                 AND private_result.batch = topology.batch
                 AND private_result.item_count = topology.item_count
                LEFT JOIN public.analysis_v2_private_name_manifests
                    AS private_manifest
                  ON private_manifest.request_id = topology.request_id
                 AND private_manifest.batch = topology.batch
                 AND private_manifest.item_count = topology.item_count
                 AND private_manifest.producer_input_hash =
                        private_result.producer_input_hash
                 AND private_manifest.result_hash = private_result.result_hash
                WHERE topology.request_id = p_request_id
                  AND topology.topology_kind = 'private_name'
                  AND (
                        private_result.request_id IS NULL
                        OR private_manifest.request_id IS NULL
                  )
            ) AS privateBatchesReady,
            NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_candidate_feature_rows AS feature
                CROSS JOIN request_row
                WHERE feature.request_id = p_request_id
                  AND (
                    feature.candidate_id <>
                        public.analysis_v2_result_candidate_id(
                            feature.instagram_id
                        )
                    OR feature.instagram_id =
                        pg_catalog.lower(request_row.target_instagram_id)
                    OR feature.instagram_id =
                        request_row.excluded_instagram_id
                    OR NOT EXISTS (
                        SELECT 1
                        FROM public.analysis_v2_mutual_rows AS mutual
                        WHERE mutual.request_id = p_request_id
                          AND mutual.job_key = 'track:relationships:collect'
                          AND mutual.username = feature.instagram_id
                          AND NOT mutual.is_private
                          AND mutual.detailed_ordinal IS NOT NULL
                    )
                    OR NOT EXISTS (
                        SELECT 1
                        FROM public.analysis_v2_profile_fetch_batches
                            AS profile_batch
                        JOIN public.analysis_v2_profile_fetch_outcomes AS outcome
                          ON outcome.request_id = profile_batch.request_id
                         AND outcome.job_key = profile_batch.job_key
                         AND outcome.username = feature.instagram_id
                         AND outcome.attempt =
                            public.analysis_v2_profile_terminal_attempt(
                                profile_batch.request_id,
                                profile_batch.job_key,
                                feature.instagram_id,
                                profile_batch.frozen_unresolved_usernames
                            )
                        WHERE profile_batch.request_id = p_request_id
                          AND profile_batch.job_key =
                                'track:profiles:batch:' || feature.batch::TEXT
                          AND (
                            (
                                feature.terminal_classification = 'unavailable'
                                AND feature.unavailable_reason = 'profile_fetch'
                                AND outcome.status <> 'success'
                            )
                            OR (
                                feature.terminal_classification = 'unavailable'
                                AND feature.unavailable_reason = 'ai_response'
                                AND outcome.status = 'success'
                                AND EXISTS (
                                    SELECT 1
                                    FROM public.analysis_v2_ai_scoring_stage_checkpoints
                                        AS rich_stage
                                    CROSS JOIN LATERAL
                                        pg_catalog.jsonb_array_elements(
                                            rich_stage.payload->'outcomes'
                                        ) AS rich_outcome(value)
                                    WHERE rich_stage.request_id = p_request_id
                                      AND rich_stage.stage_kind =
                                            'profile_ai_batch'
                                      AND rich_stage.batch_key = feature.batch
                                      AND rich_outcome.value->>'candidateId' =
                                            feature.candidate_id
                                      AND rich_outcome.value->>'instagramId' =
                                            feature.instagram_id
                                      AND rich_outcome.value->>'status' =
                                            'analysis_unavailable'
                                )
                            )
                            OR (
                                feature.terminal_classification =
                                    'media_unavailable'
                                AND outcome.status = 'success'
                            )
                            OR (
                                feature.terminal_classification NOT IN (
                                    'unavailable', 'media_unavailable'
                                )
                                AND outcome.status = 'success'
                            )
                          )
                    )
                  )
            ) AS featureRowsReady,
            NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_private_name_rows AS private_name
                CROSS JOIN request_row
                WHERE private_name.request_id = p_request_id
                  AND (
                    private_name.candidate_id <>
                        public.analysis_v2_result_candidate_id(
                            private_name.instagram_id
                        )
                    OR private_name.instagram_id =
                        pg_catalog.lower(request_row.target_instagram_id)
                    OR private_name.instagram_id =
                        request_row.excluded_instagram_id
                    OR NOT EXISTS (
                        SELECT 1
                        FROM public.analysis_v2_mutual_rows AS mutual
                        WHERE mutual.request_id = p_request_id
                          AND mutual.job_key = 'track:relationships:collect'
                          AND mutual.username = private_name.instagram_id
                          AND mutual.is_private
                    )
                  )
            ) AS privateRowsReady,
            EXISTS (
                SELECT 1
                FROM public.analysis_v2_dag_stage_manifests AS primary_join
                JOIN public.analysis_v2_ai_scoring_stage_checkpoints
                    AS primary_rich
                  ON primary_rich.request_id = primary_join.request_id
                 AND primary_rich.stage_kind = 'primary_join'
                 AND primary_rich.batch_key = -1
                 AND primary_rich.producer_input_hash =
                        primary_join.producer_input_hash
                 AND primary_rich.result_hash = primary_join.result_hash
                JOIN public.analysis_v2_dag_stage_manifests AS screening
                  ON screening.request_id = primary_join.request_id
                 AND screening.stage_kind = 'screening'
                JOIN public.analysis_v2_ai_scoring_stage_checkpoints
                    AS screening_rich
                  ON screening_rich.request_id = screening.request_id
                 AND screening_rich.stage_kind = 'screening'
                 AND screening_rich.batch_key = -1
                 AND screening_rich.producer_input_hash =
                        screening.producer_input_hash
                 AND screening_rich.result_hash = screening.result_hash
                JOIN public.analysis_v2_preliminary_score_manifests
                    AS preliminary
                  ON preliminary.request_id = primary_join.request_id
                 AND preliminary.producer_input_hash =
                        screening.producer_input_hash
                CROSS JOIN counts
                WHERE primary_join.request_id = p_request_id
                  AND primary_join.stage_kind = 'primary_join'
                  AND primary_join.verified_female_count =
                        counts.verified_count
                  AND screening.verified_female_count =
                        counts.verified_count
                  AND preliminary.item_count = counts.verified_count
                  AND screening.shortlist_count = counts.shortlist_count
            ) AS primaryScreeningReady,
            EXISTS (
                SELECT 1
                FROM public.analysis_v2_dag_stage_manifests AS stage
                JOIN public.analysis_v2_ai_scoring_stage_checkpoints
                    AS rich_stage
                  ON rich_stage.request_id = stage.request_id
                 AND rich_stage.stage_kind = 'reverse_likes'
                 AND rich_stage.batch_key = -1
                 AND rich_stage.producer_input_hash =
                        stage.producer_input_hash
                 AND rich_stage.result_hash = stage.result_hash
                JOIN public.analysis_v2_reverse_like_manifests AS manifest
                  ON manifest.request_id = stage.request_id
                 AND manifest.producer_input_hash =
                        stage.producer_input_hash
                CROSS JOIN counts
                WHERE stage.request_id = p_request_id
                  AND stage.stage_kind = 'reverse_likes'
                  AND stage.shortlist_count = counts.shortlist_count
            ) AS reverseLikesReady,
            EXISTS (
                SELECT 1
                FROM public.analysis_v2_dag_stage_manifests AS stage
                JOIN public.analysis_v2_ai_scoring_stage_checkpoints
                    AS rich_stage
                  ON rich_stage.request_id = stage.request_id
                 AND rich_stage.stage_kind = 'partner_safety'
                 AND rich_stage.batch_key = -1
                 AND rich_stage.producer_input_hash =
                        stage.producer_input_hash
                 AND rich_stage.result_hash = stage.result_hash
                JOIN public.analysis_v2_partner_safety_manifests AS manifest
                  ON manifest.request_id = stage.request_id
                 AND manifest.producer_input_hash =
                        stage.producer_input_hash
                CROSS JOIN counts
                WHERE stage.request_id = p_request_id
                  AND stage.stage_kind = 'partner_safety'
                  AND stage.shortlist_count = counts.shortlist_count
            ) AS partnerSafetyReady,
            EXISTS (
                SELECT 1
                FROM public.analysis_v2_dag_stage_manifests AS final_stage
                JOIN public.analysis_v2_ai_scoring_stage_checkpoints
                    AS final_rich
                  ON final_rich.request_id = final_stage.request_id
                 AND final_rich.stage_kind = 'final_score'
                 AND final_rich.batch_key = -1
                 AND final_rich.producer_input_hash =
                        final_stage.producer_input_hash
                 AND final_rich.result_hash = final_stage.result_hash
                JOIN public.analysis_v2_candidate_score_manifests
                    AS score_manifest
                  ON score_manifest.request_id = final_stage.request_id
                 AND score_manifest.producer_input_hash =
                        final_stage.producer_input_hash
                JOIN public.analysis_v2_dag_stage_manifests AS narrative_stage
                  ON narrative_stage.request_id = final_stage.request_id
                 AND narrative_stage.stage_kind = 'narrative'
                JOIN public.analysis_v2_ai_scoring_stage_checkpoints
                    AS narrative_rich
                  ON narrative_rich.request_id = narrative_stage.request_id
                 AND narrative_rich.stage_kind = 'narrative'
                 AND narrative_rich.batch_key = -1
                 AND narrative_rich.producer_input_hash =
                        narrative_stage.producer_input_hash
                 AND narrative_rich.result_hash = narrative_stage.result_hash
                JOIN public.analysis_v2_narrative_manifests
                    AS narrative_manifest
                  ON narrative_manifest.request_id = final_stage.request_id
                 AND narrative_manifest.producer_input_hash =
                        narrative_stage.producer_input_hash
                CROSS JOIN counts
                WHERE final_stage.request_id = p_request_id
                  AND final_stage.stage_kind = 'final_score'
                  AND score_manifest.item_count = counts.verified_count
                  AND final_stage.featured_high_risk_count =
                        narrative_manifest.item_count
                  AND final_stage.narrative_count =
                        narrative_manifest.item_count
                  AND narrative_stage.narrative_count =
                        narrative_manifest.item_count
            ) AS finalNarrativeReady,
            EXISTS (
                SELECT 1
                FROM public.analysis_progress_state AS progress_state
                WHERE progress_state.request_id = p_request_id
                  AND progress_state.status IN ('queued', 'processing')
            ) AND NOT EXISTS (
                SELECT 1
                FROM public.analysis_progress_events AS progress_event
                WHERE progress_event.request_id = p_request_id
                  AND progress_event.event_code = 'ANALYSIS_COMPLETED'
            ) AS progressReady,
            counts.feature_count = COALESCE(
                (SELECT relationship.detailed_public_count FROM relationship),
                -1
            ) AS genderCountsReady,
            counts.*
        FROM counts
    ),
    readiness AS (
        SELECT
            checks.*,
            checks.providerCleanupReady
                AND checks.relationshipEnvelopeReady
                AND checks.targetEvidenceReady
                AND checks.stageCountReady
                AND checks.profileCountsReady
                AND checks.privateCountsReady
                AND checks.profileBatchesReady
                AND checks.privateBatchesReady
                AND checks.featureRowsReady
                AND checks.privateRowsReady
                AND checks.primaryScreeningReady
                AND checks.reverseLikesReady
                AND checks.partnerSafetyReady
                AND checks.finalNarrativeReady
                AND checks.progressReady
                AND checks.genderCountsReady AS ready
        FROM checks
    )
    SELECT pg_catalog.jsonb_build_object(
        'ready', readiness.ready,
        'providerCleanupReady', readiness.providerCleanupReady,
        'relationshipEnvelopeReady', readiness.relationshipEnvelopeReady,
        'targetEvidenceReady', readiness.targetEvidenceReady,
        'stageCountReady', readiness.stageCountReady,
        'profileCountsReady', readiness.profileCountsReady,
        'privateCountsReady', readiness.privateCountsReady,
        'profileBatchesReady', readiness.profileBatchesReady,
        'privateBatchesReady', readiness.privateBatchesReady,
        'featureRowsReady', readiness.featureRowsReady,
        'privateRowsReady', readiness.privateRowsReady,
        'primaryScreeningReady', readiness.primaryScreeningReady,
        'reverseLikesReady', readiness.reverseLikesReady,
        'partnerSafetyReady', readiness.partnerSafetyReady,
        'finalNarrativeReady', readiness.finalNarrativeReady,
        'progressReady', readiness.progressReady,
        'genderCountsReady', readiness.genderCountsReady,
        'stageCount', readiness.stage_count,
        'profileTopologyCount', readiness.profile_topology_count,
        'featureCount', readiness.feature_count,
        'privateTopologyCount', readiness.private_topology_count,
        'privateCount', readiness.private_count,
        'verifiedCount', readiness.verified_count,
        'shortlistCount', readiness.shortlist_count
    )
    INTO v_payload
    FROM readiness;

    RETURN v_payload;
END;
$$;


--
-- Name: load_analysis_v2_fresh_admission_provider_run(uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_fresh_admission_provider_run(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid, p_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_operation_key TEXT;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_claim_token IS NULL
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;
    v_operation_key := 'target-profile-fresh-admission:g' || p_admission_generation::TEXT;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status IS DISTINCT FROM 'ready'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.expires_at <= v_now
       OR v_preflight.admission_generation IS DISTINCT FROM p_admission_generation
       OR v_preflight.admission_status IS DISTINCT FROM 'processing'
       OR v_preflight.admission_claim_token IS DISTINCT FROM p_claim_token
       OR v_preflight.admission_lease_expires_at IS NULL
       OR v_preflight.admission_lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    PERFORM public.adopt_legacy_fresh_admission_provider_run(
        p_preflight_id, v_operation_key, v_preflight.admission_requested_at
    );

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = v_operation_key;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    IF v_run.input_hash IS DISTINCT FROM p_input_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    RETURN public.analysis_preflight_provider_run_json(v_run);
END;
$_$;


--
-- Name: load_analysis_v2_gender_resolution_quality(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_gender_resolution_quality(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_metrics public.analysis_v2_gender_resolution_metrics%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_summary public.analysis_v2_result_summaries%ROWTYPE;
    v_request_completed BOOLEAN;
    v_standard_plan BOOLEAN;
    v_result_archive_present BOOLEAN;
    v_request_passed BOOLEAN;
    v_unknown_evaluable BOOLEAN;
    v_unknown_passed BOOLEAN;
    v_provenance_passed BOOLEAN;
    v_immutability_passed BOOLEAN;
    v_purgeable_staging_sources_present BOOLEAN;
    v_metrics_finalized BOOLEAN;
    v_metrics_fresh BOOLEAN;
    v_all_resolver_attempts_terminal BOOLEAN;
    v_live_features RECORD;
    v_live_attempts RECORD;
    v_live_outcomes RECORD;
BEGIN
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GENDER_RESOLUTION_QUALITY_INVALID',
            ERRCODE = 'P0001';
    END IF;
    SELECT metrics.*
    INTO v_metrics
    FROM public.analysis_v2_gender_resolution_metrics AS metrics
    WHERE metrics.request_id = p_request_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GENDER_RESOLUTION_QUALITY_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    v_purgeable_staging_sources_present := EXISTS (
        SELECT 1
        FROM public.analysis_v2_candidate_feature_rows AS feature
        WHERE feature.request_id = p_request_id
    ) OR EXISTS (
        SELECT 1
        FROM public.analysis_v2_candidate_feature_manifests AS manifest
        WHERE manifest.request_id = p_request_id
    ) OR EXISTS (
        SELECT 1
        FROM public.analysis_v2_ai_scoring_stage_checkpoints AS checkpoint
        WHERE checkpoint.request_id = p_request_id
          AND checkpoint.stage_kind = 'profile_ai_batch'
    );

    SELECT
        pg_catalog.count(*)::INTEGER AS screened_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status
                NOT IN ('disabled', 'not_eligible')
        )::INTEGER AS resolver_eligible_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.baseline_classification
                NOT IN ('verified_female', 'verified_non_female')
        )::INTEGER AS baseline_unknown_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.terminal_classification
                NOT IN ('verified_female', 'verified_non_female')
        )::INTEGER AS final_unknown_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status IN (
                'ready_applied', 'ready_not_needed', 'ready_inconclusive'
            )
        )::INTEGER AS ready_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status = 'ready_applied'
        )::INTEGER AS applied_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status = 'ready_applied'
              AND feature.classification_source = 'gender_resolution'
              AND feature.gender_resolution_operation_key
                    ~ '^gender-resolution:[a-f0-9]{64}$'
              AND feature.gender_resolution_result_hash ~ '^[a-f0-9]{64}$'
        )::INTEGER AS applied_with_fenced_result_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.baseline_classification IN (
                    'verified_female', 'verified_non_female'
                )
              AND feature.terminal_classification
                    IS DISTINCT FROM feature.baseline_classification
        )::INTEGER AS verified_baseline_mutation_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status = 'ready_inconclusive'
        )::INTEGER AS inconclusive_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status = 'cutoff'
        )::INTEGER AS cutoff_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status = 'capacity_skipped'
        )::INTEGER AS capacity_skipped_count,
        pg_catalog.count(*) FILTER (
            WHERE feature.gender_resolution_status = 'terminal_unavailable'
        )::INTEGER AS terminal_unavailable_count
    INTO v_live_features
    FROM public.analysis_v2_candidate_feature_rows AS feature
    WHERE feature.request_id = p_request_id;

    SELECT
        pg_catalog.count(*)::INTEGER AS attempt_count,
        pg_catalog.count(*) FILTER (
            WHERE attempt.status = 'reserved'
        )::INTEGER AS nonterminal_count,
        pg_catalog.count(*) FILTER (
            WHERE attempt.usage_metadata_status = 'complete'
        )::INTEGER AS usage_complete_count,
        pg_catalog.count(*) FILTER (
            WHERE attempt.usage_metadata_status IS DISTINCT FROM 'complete'
        )::INTEGER AS usage_missing_count,
        COALESCE(pg_catalog.sum(attempt.prompt_tokens), 0)::BIGINT
            AS prompt_tokens,
        COALESCE(pg_catalog.sum(attempt.completion_tokens), 0)::BIGINT
            AS completion_tokens,
        COALESCE(pg_catalog.sum(attempt.total_tokens), 0)::BIGINT
            AS total_tokens,
        COALESCE(pg_catalog.sum(attempt.thinking_tokens), 0)::BIGINT
            AS thinking_tokens,
        pg_catalog.sum(attempt.estimated_cost_usd)::NUMERIC(18, 12)
            AS estimated_cost_usd,
        pg_catalog.count(attempt.estimated_cost_usd)::INTEGER
            AS cost_known_count
    INTO v_live_attempts
    FROM public.analysis_v2_ai_attempts AS attempt
    WHERE attempt.request_id = p_request_id
      AND attempt.stage = 'genderResolution';

    WITH outcomes AS (
        SELECT outcome.value
        FROM public.analysis_v2_ai_scoring_stage_checkpoints AS checkpoint
        CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
            checkpoint.payload->'outcomes'
        ) AS outcome(value)
        WHERE checkpoint.request_id = p_request_id
          AND checkpoint.stage_kind = 'profile_ai_batch'
    )
    SELECT
        pg_catalog.count(*)::INTEGER AS outcome_count,
        pg_catalog.count(*) FILTER (
            WHERE pg_catalog.jsonb_array_length(
                    outcome.value->'mediaCoverage'->'failures'
                ) > 0
              AND pg_catalog.jsonb_array_length(
                    outcome.value->'mediaCoverage'->'failures'
                ) * 5
                    <= (outcome.value->'mediaCoverage'->>'selectedCount')::INTEGER
        )::INTEGER AS partial_media_accepted_candidate_count,
        COALESCE(pg_catalog.sum(
            (outcome.value->'mediaCoverage'->>'selectedCount')::INTEGER
        ), 0)::INTEGER AS selected_media_total,
        COALESCE(pg_catalog.sum(
            (outcome.value->'mediaCoverage'->>'normalizedCount')::INTEGER
        ), 0)::INTEGER AS normalized_media_total
    INTO v_live_outcomes
    FROM outcomes AS outcome;

    v_metrics_finalized := v_metrics.metrics_finalized_at IS NOT NULL;
    v_all_resolver_attempts_terminal := v_metrics_finalized
        AND v_metrics.resolver_nonterminal_attempt_count = 0
        AND v_live_attempts.nonterminal_count = 0;
    v_metrics_fresh := v_metrics_finalized AND (
        NOT v_purgeable_staging_sources_present
        OR (
            v_metrics.screened_count = v_live_features.screened_count
            AND v_metrics.screened_count = v_live_outcomes.outcome_count
            AND v_metrics.resolver_eligible_count =
                v_live_features.resolver_eligible_count
            AND v_metrics.baseline_unknown_count =
                v_live_features.baseline_unknown_count
            AND v_metrics.final_unknown_count =
                v_live_features.final_unknown_count
            AND v_metrics.ready_count = v_live_features.ready_count
            AND v_metrics.applied_count = v_live_features.applied_count
            AND v_metrics.applied_with_fenced_result_count =
                v_live_features.applied_with_fenced_result_count
            AND v_metrics.verified_baseline_mutation_count =
                v_live_features.verified_baseline_mutation_count
            AND v_metrics.inconclusive_count =
                v_live_features.inconclusive_count
            AND v_metrics.cutoff_count = v_live_features.cutoff_count
            AND v_metrics.capacity_skipped_count =
                v_live_features.capacity_skipped_count
            AND v_metrics.terminal_unavailable_count =
                v_live_features.terminal_unavailable_count
            AND v_metrics.partial_media_accepted_candidate_count =
                v_live_outcomes.partial_media_accepted_candidate_count
            AND v_metrics.selected_media_total =
                v_live_outcomes.selected_media_total
            AND v_metrics.normalized_media_total =
                v_live_outcomes.normalized_media_total
            AND v_metrics.failed_media_total =
                v_live_outcomes.selected_media_total
                    - v_live_outcomes.normalized_media_total
        )
    )
        AND v_metrics.resolver_attempt_count =
            v_live_attempts.attempt_count
        AND v_metrics.resolver_usage_complete_count =
            v_live_attempts.usage_complete_count
        AND v_metrics.resolver_usage_missing_count =
            v_live_attempts.usage_missing_count
        AND v_metrics.resolver_prompt_tokens =
            v_live_attempts.prompt_tokens
        AND v_metrics.resolver_completion_tokens =
            v_live_attempts.completion_tokens
        AND v_metrics.resolver_total_tokens =
            v_live_attempts.total_tokens
        AND v_metrics.resolver_thinking_tokens =
            v_live_attempts.thinking_tokens
        AND v_metrics.resolver_estimated_cost_usd
            IS NOT DISTINCT FROM v_live_attempts.estimated_cost_usd
        AND v_metrics.resolver_cost_known_count =
            v_live_attempts.cost_known_count
        AND v_metrics.resolver_nonterminal_attempt_count =
            v_live_attempts.nonterminal_count;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id;
    SELECT summary.*
    INTO v_summary
    FROM public.analysis_v2_result_summaries AS summary
    WHERE summary.request_id = p_request_id;
    v_request_completed := v_request.id IS NOT NULL
        AND v_request.pipeline_version = 'v2'
        AND v_request.status = 'completed';
    v_standard_plan := v_request.id IS NOT NULL
        AND v_request.selected_plan_id_snapshot = 'standard';
    v_result_archive_present := v_summary.request_id IS NOT NULL
        AND v_summary.plan_id = 'standard';
    v_request_passed := v_request_completed
        AND v_standard_plan
        AND v_result_archive_present;
    v_unknown_evaluable := v_metrics.screened_count > 0;
    v_unknown_passed := v_unknown_evaluable
        AND v_metrics.final_unknown_count * 10 <= v_metrics.screened_count * 2;
    v_provenance_passed :=
        v_metrics.applied_with_fenced_result_count = v_metrics.applied_count;
    v_immutability_passed := v_metrics.verified_baseline_mutation_count = 0;

    RETURN pg_catalog.jsonb_build_object(
        'screenedCount', v_metrics.screened_count,
        'resolverEligibleCount', v_metrics.resolver_eligible_count,
        'baselineUnknownCount', v_metrics.baseline_unknown_count,
        'finalUnknownCount', v_metrics.final_unknown_count,
        'finalUnknownRatio', CASE
            WHEN v_unknown_evaluable THEN
                v_metrics.final_unknown_count::NUMERIC
                    / v_metrics.screened_count::NUMERIC
            ELSE NULL
        END,
        'readyCount', v_metrics.ready_count,
        'appliedCount', v_metrics.applied_count,
        'appliedWithFencedResultCount',
            v_metrics.applied_with_fenced_result_count,
        'verifiedBaselineMutationCount',
            v_metrics.verified_baseline_mutation_count,
        'inconclusiveCount', v_metrics.inconclusive_count,
        'cutoffCount', v_metrics.cutoff_count,
        'capacitySkippedCount', v_metrics.capacity_skipped_count,
        'terminalUnavailableCount', v_metrics.terminal_unavailable_count,
        'partialMediaAcceptedCandidateCount',
            v_metrics.partial_media_accepted_candidate_count,
        'selectedMediaTotal', v_metrics.selected_media_total,
        'normalizedMediaTotal', v_metrics.normalized_media_total,
        'failedMediaTotal', v_metrics.failed_media_total,
        'resolverAttemptCount', v_metrics.resolver_attempt_count,
        'resolverUsageCompleteCount', v_metrics.resolver_usage_complete_count,
        'resolverUsageMissingCount', v_metrics.resolver_usage_missing_count,
        'resolverEstimatedCostUsd', v_metrics.resolver_estimated_cost_usd,
        'resolverCostKnownCount', v_metrics.resolver_cost_known_count,
        'resolverNonterminalAttemptCount',
            v_metrics.resolver_nonterminal_attempt_count,
        'resolverConcurrencyLimit', 2,
        'sharedConcurrencyLimit', 8,
        'allResolverAttemptsTerminal', v_all_resolver_attempts_terminal,
        'metricsFinalized', v_metrics_finalized,
        'metricsFresh', v_metrics_fresh,
        'requestCompleted', v_request_completed,
        'standardPlan', v_standard_plan,
        'resultArchivePresent', v_result_archive_present,
        'requestGatePassed', v_request_passed,
        'unknownGateEvaluable', v_unknown_evaluable,
        'unknownGatePassed', v_unknown_passed,
        'provenanceGatePassed', v_provenance_passed,
        'immutabilityGatePassed', v_immutability_passed,
        'qualityGatePassed', v_request_passed
            AND v_unknown_evaluable
            AND v_unknown_passed
            AND v_provenance_passed
            AND v_immutability_passed
            AND v_all_resolver_attempts_terminal
            AND v_metrics_fresh
    );
END;
$_$;


--
-- Name: load_analysis_v2_gender_routing_selected(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_gender_routing_selected(p_request_id uuid, p_relationship_checkpoint_id text, p_policy_version text, p_plan_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_manifest public.analysis_v2_gender_routing_manifests%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_relationship public.analysis_v2_relationship_manifests%ROWTYPE;
    v_row_count INTEGER;
    v_selected_count INTEGER;
    v_min_ordinal INTEGER;
    v_max_ordinal INTEGER;
    v_rows JSONB;
BEGIN
    IF p_request_id IS NULL
       OR p_relationship_checkpoint_id !~ '^[a-f0-9]{64}$'
       OR p_policy_version <> 'gender-routing-v1'
       OR p_plan_id NOT IN ('basic', 'standard') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = 'track:relationships:collect'
    FOR UPDATE;
    SELECT policy.* INTO v_policy
    FROM public.analysis_v2_provider_execution_policies AS policy
    WHERE policy.request_id = p_request_id
    FOR UPDATE;
    SELECT relationship_manifest.* INTO v_relationship
    FROM public.analysis_v2_relationship_manifests AS relationship_manifest
    WHERE relationship_manifest.request_id = p_request_id
      AND relationship_manifest.job_key = 'track:relationships:collect'
      AND relationship_manifest.result_hash = p_relationship_checkpoint_id
    FOR UPDATE;
    SELECT routing_manifest.* INTO v_manifest
    FROM public.analysis_v2_gender_routing_manifests AS routing_manifest
    WHERE routing_manifest.request_id = p_request_id
      AND routing_manifest.relationship_checkpoint_id = p_relationship_checkpoint_id
      AND routing_manifest.policy_version = p_policy_version
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_MISSING', ERRCODE = 'P0001';
    END IF;
    IF v_manifest.plan_id IS DISTINCT FROM p_plan_id
       OR (p_plan_id = 'basic' AND (v_manifest.detailed_cap <> 100 OR v_manifest.population_count NOT BETWEEN 0 AND 400))
       OR (p_plan_id = 'standard' AND (v_manifest.detailed_cap <> 200 OR v_manifest.population_count NOT BETWEEN 0 AND 800)) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_DRIFT', ERRCODE = 'P0001';
    END IF;
    IF v_request.id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status IS DISTINCT FROM 'processing'
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot IS DISTINCT FROM p_plan_id
       OR v_policy.request_id IS NULL
       OR v_policy.mode IS DISTINCT FROM 'test_operation_split'
       OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR v_job.request_id IS NULL
       OR v_job.input_hash IS DISTINCT FROM v_manifest.relationship_job_input_hash
       OR v_relationship.request_id IS NULL
       OR v_relationship.public_count IS DISTINCT FROM v_manifest.population_count THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF v_manifest.status IS DISTINCT FROM 'complete' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_NOT_COMPLETE', ERRCODE = 'P0001';
    END IF;
    SELECT pg_catalog.count(*)::INTEGER,
           (SELECT pg_catalog.count(*)::INTEGER
            FROM public.analysis_v2_gender_routing_candidates AS all_candidate
            WHERE all_candidate.request_id = p_request_id
              AND all_candidate.relationship_checkpoint_id = p_relationship_checkpoint_id
              AND all_candidate.policy_version = p_policy_version),
           COALESCE(pg_catalog.min(candidate.ordinal), 1),
           COALESCE(pg_catalog.max(candidate.ordinal), 0),
           COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'mutualOrdinal', candidate.mutual_ordinal,
                'candidateKey', candidate.candidate_key,
                'selectionSlot', candidate.selection_slot,
                'ordinal', candidate.ordinal
           ) ORDER BY candidate.ordinal), '[]'::JSONB)
    INTO v_selected_count, v_row_count, v_min_ordinal, v_max_ordinal, v_rows
    FROM public.analysis_v2_gender_routing_candidates AS candidate
    WHERE candidate.request_id = p_request_id
      AND candidate.relationship_checkpoint_id = p_relationship_checkpoint_id
      AND candidate.policy_version = p_policy_version
      AND candidate.selected;
    IF v_row_count IS DISTINCT FROM v_manifest.population_count
       OR v_selected_count IS DISTINCT FROM v_manifest.selected_count
       OR v_manifest.selected_count IS DISTINCT FROM LEAST(v_manifest.population_count, v_manifest.detailed_cap)
       OR v_min_ordinal <> 1
       OR v_max_ordinal <> v_selected_count THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_CORRUPT', ERRCODE = 'P0001';
    END IF;
    RETURN pg_catalog.jsonb_build_object('selectedCount', v_manifest.selected_count, 'rows', v_rows);
END;
$_$;


--
-- Name: load_analysis_v2_gender_routing_selected_usernames(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_gender_routing_selected_usernames(p_request_id uuid, p_relationship_checkpoint_id text, p_policy_version text, p_plan_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_manifest public.analysis_v2_gender_routing_manifests%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_relationship public.analysis_v2_relationship_manifests%ROWTYPE;
    v_row_count INTEGER;
    v_selected_count INTEGER;
    v_min_ordinal INTEGER;
    v_max_ordinal INTEGER;
    v_rows JSONB;
BEGIN
    IF p_request_id IS NULL
       OR p_relationship_checkpoint_id !~ '^[a-f0-9]{64}$'
       OR p_policy_version <> 'gender-routing-v1'
       OR p_plan_id NOT IN ('basic', 'standard') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = 'track:relationships:collect'
    FOR UPDATE;
    SELECT policy.* INTO v_policy
    FROM public.analysis_v2_provider_execution_policies AS policy
    WHERE policy.request_id = p_request_id
    FOR UPDATE;
    SELECT relationship_manifest.* INTO v_relationship
    FROM public.analysis_v2_relationship_manifests AS relationship_manifest
    WHERE relationship_manifest.request_id = p_request_id
      AND relationship_manifest.job_key = 'track:relationships:collect'
      AND relationship_manifest.result_hash = p_relationship_checkpoint_id
    FOR UPDATE;
    SELECT routing_manifest.* INTO v_manifest
    FROM public.analysis_v2_gender_routing_manifests AS routing_manifest
    WHERE routing_manifest.request_id = p_request_id
      AND routing_manifest.relationship_checkpoint_id = p_relationship_checkpoint_id
      AND routing_manifest.policy_version = p_policy_version
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_MISSING', ERRCODE = 'P0001';
    END IF;
    IF v_manifest.plan_id IS DISTINCT FROM p_plan_id
       OR (p_plan_id = 'basic' AND (v_manifest.detailed_cap <> 100 OR v_manifest.population_count NOT BETWEEN 0 AND 400))
       OR (p_plan_id = 'standard' AND (v_manifest.detailed_cap <> 200 OR v_manifest.population_count NOT BETWEEN 0 AND 800)) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_DRIFT', ERRCODE = 'P0001';
    END IF;
    IF v_request.id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status IS DISTINCT FROM 'processing'
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot IS DISTINCT FROM p_plan_id
       OR v_policy.request_id IS NULL
       OR v_policy.mode IS DISTINCT FROM 'test_operation_split'
       OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR v_job.request_id IS NULL
       OR v_job.input_hash IS DISTINCT FROM v_manifest.relationship_job_input_hash
       OR v_relationship.request_id IS NULL
       OR v_relationship.public_count IS DISTINCT FROM v_manifest.population_count THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF v_manifest.status IS DISTINCT FROM 'complete' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_NOT_COMPLETE', ERRCODE = 'P0001';
    END IF;
    SELECT pg_catalog.count(*)::INTEGER,
           (SELECT pg_catalog.count(*)::INTEGER
            FROM public.analysis_v2_gender_routing_candidates AS all_candidate
            WHERE all_candidate.request_id = p_request_id
              AND all_candidate.relationship_checkpoint_id = p_relationship_checkpoint_id
              AND all_candidate.policy_version = p_policy_version),
           COALESCE(pg_catalog.min(candidate.ordinal), 1),
           COALESCE(pg_catalog.max(candidate.ordinal), 0),
           COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'mutualOrdinal', candidate.mutual_ordinal,
                'candidateKey', candidate.candidate_key,
                'selectionSlot', candidate.selection_slot,
                'ordinal', candidate.ordinal,
                'username', mutual_row.username
           ) ORDER BY candidate.ordinal), '[]'::JSONB)
    INTO v_selected_count, v_row_count, v_min_ordinal, v_max_ordinal, v_rows
    FROM public.analysis_v2_gender_routing_candidates AS candidate
    INNER JOIN public.analysis_v2_mutual_rows AS mutual_row
        ON mutual_row.request_id = candidate.request_id
       AND mutual_row.job_key = candidate.relationship_job_key
       AND mutual_row.mutual_ordinal = candidate.mutual_ordinal
    WHERE candidate.request_id = p_request_id
      AND candidate.relationship_checkpoint_id = p_relationship_checkpoint_id
      AND candidate.policy_version = p_policy_version
      AND candidate.selected
      AND NOT mutual_row.is_private;
    IF v_row_count IS DISTINCT FROM v_manifest.population_count
       OR v_selected_count IS DISTINCT FROM v_manifest.selected_count
       OR v_manifest.selected_count IS DISTINCT FROM LEAST(v_manifest.population_count, v_manifest.detailed_cap)
       OR v_min_ordinal <> 1
       OR v_max_ordinal <> v_selected_count THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_CORRUPT', ERRCODE = 'P0001';
    END IF;
    RETURN pg_catalog.jsonb_build_object('selectedCount', v_manifest.selected_count, 'rows', v_rows);
END;
$_$;


--
-- Name: load_analysis_v2_media_artifact(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_media_artifact(p_request_id uuid, p_job_key text, p_claim_token uuid, p_artifact_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_artifact public.analysis_v2_media_artifacts%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR p_claim_token IS NULL
       OR p_artifact_key IS NULL
       OR p_artifact_key !~ '^[a-f0-9]{64}$'
       OR NOT EXISTS (
            SELECT 1
            FROM public.analysis_requests AS analysis_request
            JOIN public.analysis_pipeline_jobs AS job
              ON job.request_id = analysis_request.id
            WHERE analysis_request.id = p_request_id
              AND analysis_request.pipeline_version = 'v2'
              AND analysis_request.status IN ('pending', 'processing')
              AND job.job_key = p_job_key
              AND job.status = 'processing'
              AND job.lease_token = p_claim_token
              AND job.lease_expires_at > pg_catalog.clock_timestamp()
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_MEDIA_ARTIFACT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT artifact.*
    INTO v_artifact
    FROM public.analysis_v2_media_artifacts AS artifact
    WHERE artifact.request_id = p_request_id
      AND artifact.artifact_key = p_artifact_key
      AND artifact.deleted_at IS NULL;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', v_artifact.request_id,
        'artifactKey', v_artifact.artifact_key,
        'artifactKind', v_artifact.artifact_kind,
        'contentSha256', v_artifact.content_sha256,
        'contentType', v_artifact.content_type,
        'objectName', v_artifact.object_name,
        'objectGeneration', v_artifact.object_generation,
        'byteSize', v_artifact.byte_size
    );
END;
$_$;


--
-- Name: load_analysis_v2_operational_observability(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_operational_observability(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_payload JSONB;
    v_analysis_unavailable_count SMALLINT;
BEGIN
    v_payload := public.analysis_v2_load_operational_observability_internal(p_request_id);
    IF v_payload IS NULL OR v_payload->'summary'->'resultCoverage' = 'null'::JSONB THEN
        RETURN v_payload;
    END IF;
    SELECT telemetry.analysis_unavailable_count INTO v_analysis_unavailable_count
    FROM public.analysis_v2_result_coverage_telemetry AS telemetry
    WHERE telemetry.request_id = p_request_id;
    RETURN pg_catalog.jsonb_set(
        v_payload,
        ARRAY['summary', 'resultCoverage', 'analysisUnavailableCount'],
        pg_catalog.to_jsonb(COALESCE(v_analysis_unavailable_count, 0)),
        TRUE
    );
END;
$$;


--
-- Name: load_analysis_v2_policy_versions_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_policy_versions_snapshot(p_request_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT analysis_request.policy_versions_snapshot
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
      AND public.analysis_v2_scheduler_reader_valid_policy_snapshot_v1(
          analysis_request.policy_versions_snapshot
      );
$$;


--
-- Name: load_analysis_v2_profile_ai_stage_batches(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_profile_ai_stage_batches(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_result JSONB;
BEGIN
    v_job := public.analysis_v2_assert_result_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    PERFORM public.analysis_v2_assert_ai_scoring_stage_consumer(
        v_job, 'profile_ai_batch'
    );
    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            public.analysis_v2_ai_scoring_stage_envelope(checkpoint)
            ORDER BY checkpoint.batch_key
        ),
        '[]'::JSONB
    ) INTO v_result
    FROM public.analysis_v2_ai_scoring_stage_checkpoints AS checkpoint
    WHERE checkpoint.request_id = p_request_id
      AND checkpoint.stage_kind = 'profile_ai_batch';
    RETURN v_result;
END;
$$;


--
-- Name: load_analysis_v2_profile_fetch_checkpoint(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_profile_fetch_checkpoint(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;

    v_now := pg_catalog.clock_timestamp();
    IF v_request.id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR v_job.request_id IS NULL
       OR v_job.status <> 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CHECKPOINT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    RETURN public.analysis_v2_profile_checkpoint_snapshot(p_request_id, p_job_key);
END;
$_$;


--
-- Name: load_analysis_v2_profile_fetch_checkpoint_for_retry(uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_profile_fetch_checkpoint_for_retry(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_operation_key text, p_provider_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_order_id UUID;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_provider public.analysis_v2_provider_runs%ROWTYPE;
    v_batch public.analysis_v2_profile_fetch_batches%ROWTYPE;
    v_outcome_count INTEGER;
    v_failed_count INTEGER;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR p_job_key !~ '^track:(target-evidence:collect|profiles:batch:[0-9]+)$'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_operation_key IS NULL
       OR p_operation_key !~ '^(target-profile|profile-fallback):[a-f0-9]{64}$'
       OR p_provider_input_hash IS NULL OR p_provider_input_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROFILE_RETRY_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT fulfillment.order_id INTO v_order_id
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.request_id = p_request_id;
    IF v_order_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROFILE_RETRY_ADMISSION_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = v_order_id FOR UPDATE;
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = v_order_id FOR UPDATE;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id FOR UPDATE;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    SELECT provider_run.* INTO v_provider
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    FOR UPDATE;
    SELECT batch.* INTO v_batch
    FROM public.analysis_v2_profile_fetch_batches AS batch
    WHERE batch.request_id = p_request_id AND batch.job_key = p_job_key
    FOR UPDATE;

    IF v_request.id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR v_job.request_id IS NULL
       OR v_job.status IS DISTINCT FROM 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROFILE_RETRY_ADMISSION_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    -- A new run has no retained checkpoint; the caller may proceed through
    -- ordinary reservation admission. Only an existing batch enters this
    -- claim-rebinding path.
    IF v_batch.request_id IS NULL THEN
        RETURN NULL;
    END IF;

    IF v_fulfillment.order_id IS NULL
       OR v_fulfillment.request_id IS DISTINCT FROM p_request_id
       OR v_fulfillment.status IS DISTINCT FROM 'analysis_in_progress'
       OR v_fulfillment.manual_review_at IS NOT NULL
       OR v_order.id IS NULL
       OR v_order.result_request_id IS DISTINCT FROM p_request_id
       OR v_order.status IS DISTINCT FROM 'analysis_in_progress'
       OR v_order.payment_id IS NULL
       OR v_order.paid_at IS NULL
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_preflight.id IS NULL
       OR v_preflight.consumed_request_id IS DISTINCT FROM p_request_id
       OR v_request.preflight_id IS DISTINCT FROM v_preflight.id THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROFILE_RETRY_ADMISSION_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    IF v_provider.request_id IS NULL
       OR v_provider.input_hash IS DISTINCT FROM p_provider_input_hash
       OR v_provider.logical_provider IS DISTINCT FROM 'apify'
       OR v_provider.actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper'
       OR v_provider.credential_slot IS DISTINCT FROM 'secondary'
       OR v_provider.status IS DISTINCT FROM 'succeeded'
       OR v_provider.run_id IS NULL
       OR v_provider.run_started_at IS NULL
       OR v_provider.terminalized_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROFILE_RETRY_ADMISSION_PROVIDER_NOT_SUCCEEDED', ERRCODE = 'P0001';
    END IF;

    SELECT count(*)::INTEGER INTO v_outcome_count
    FROM public.analysis_v2_profile_fetch_outcomes AS outcome
    WHERE outcome.request_id = p_request_id
      AND outcome.job_key = p_job_key
      AND outcome.attempt = 'fresh_apify';
    SELECT count(*)::INTEGER INTO v_failed_count
    FROM public.analysis_v2_profile_fetch_outcomes AS outcome
    WHERE outcome.request_id = p_request_id
      AND outcome.job_key = p_job_key
      AND outcome.attempt = 'fresh_apify'
      AND outcome.status = 'failed';
    IF v_batch.primary_completed_at IS NULL
       OR v_batch.primary_payload_hash IS NULL
       OR v_batch.primary_payload_hash !~ '^[a-f0-9]{64}$'
       OR NOT public.analysis_v2_valid_profile_username_list(
            v_batch.requested_usernames,
            FALSE
       )
       OR v_batch.fallback_completed_at IS NOT NULL
       OR v_batch.fallback_payload_hash IS NOT NULL
       OR v_batch.repair_completed_at IS NOT NULL
       OR v_batch.repair_payload_hash IS NOT NULL
       OR v_batch.repair_usernames IS NOT NULL
       OR v_outcome_count IS DISTINCT FROM pg_catalog.cardinality(v_batch.requested_usernames)
       OR v_failed_count > (
            pg_catalog.cardinality(v_batch.requested_usernames)
            - pg_catalog.ceil(
                pg_catalog.cardinality(v_batch.requested_usernames) * 0.9
              )::INTEGER
       )
       OR v_batch.frozen_unresolved_usernames IS DISTINCT FROM COALESCE((
            SELECT pg_catalog.array_agg(outcome.username::TEXT ORDER BY outcome.ordinal)
            FROM public.analysis_v2_profile_fetch_outcomes AS outcome
            WHERE outcome.request_id = p_request_id
              AND outcome.job_key = p_job_key
              AND outcome.attempt = 'fresh_apify'
              AND outcome.status <> 'success'
       ), '{}'::TEXT[])
       OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_profile_fetch_outcomes AS outcome
            WHERE outcome.request_id = p_request_id
              AND outcome.job_key = p_job_key
              AND (
                   outcome.attempt <> 'fresh_apify'
                   OR outcome.source <> 'apify'
                   OR outcome.ordinal < 1
                   OR outcome.ordinal > pg_catalog.cardinality(v_batch.requested_usernames)
                   OR outcome.username IS DISTINCT FROM
                        v_batch.requested_usernames[outcome.ordinal::INTEGER]
                   OR outcome.status NOT IN ('success', 'unavailable', 'failed')
                   OR (
                        outcome.status = 'success'
                        AND (
                            outcome.profile_snapshot IS NULL
                            OR outcome.profile_snapshot->>'username' IS DISTINCT FROM outcome.username
                        )
                   )
                   OR (
                        outcome.status = 'failed'
                        AND outcome.failure_category NOT IN ('incomplete', 'schema')
                   )
              )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROFILE_RETRY_ADMISSION_CHECKPOINT_UNUSABLE', ERRCODE = 'P0001';
    END IF;

    IF p_job_key = 'track:target-evidence:collect'
       AND p_operation_key !~ '^target-profile:' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROFILE_RETRY_ADMISSION_SCOPE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF p_job_key <> 'track:target-evidence:collect'
       AND p_operation_key !~ '^profile-fallback:' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROFILE_RETRY_ADMISSION_SCOPE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    -- The provider reservation identity remains unchanged; only its current
    -- execution fence follows the current, already-validated job claim.
    UPDATE public.analysis_v2_provider_runs AS provider_run
    SET job_claim_token = p_claim_token,
        updated_at = pg_catalog.clock_timestamp()
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
      AND provider_run.input_hash = p_provider_input_hash
      AND provider_run.status = 'succeeded';

    RETURN public.analysis_v2_profile_checkpoint_snapshot(p_request_id, p_job_key);
END;
$_$;


--
-- Name: load_analysis_v2_profile_fetch_for_consumer(uuid, text, uuid, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_profile_fetch_for_consumer(p_request_id uuid, p_consumer_job_key text, p_consumer_claim_token uuid, p_consumer_input_hash text, p_producer_job_key text, p_expected_producer_input_hash text, p_expected_item_count integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_consumer public.analysis_pipeline_jobs%ROWTYPE;
    v_producer public.analysis_pipeline_jobs%ROWTYPE;
    v_batch public.analysis_v2_profile_fetch_batches%ROWTYPE;
    v_target_username TEXT;
    v_batch_suffix TEXT;
BEGIN
    IF p_producer_job_key IS NULL
       OR pg_catalog.char_length(p_producer_job_key) NOT BETWEEN 1 AND 160
       OR p_producer_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_expected_item_count IS NULL
       OR p_expected_item_count NOT BETWEEN 1 AND 30
       OR (
            p_expected_producer_input_hash IS NOT NULL
            AND p_expected_producer_input_hash !~ '^[a-f0-9]{64}$'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CONSUMER_SCOPE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    v_consumer := public.analysis_v2_assert_result_job_fence(
        p_request_id,
        p_consumer_job_key,
        p_consumer_claim_token,
        p_consumer_input_hash
    );

    SELECT job.* INTO v_producer
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_producer_job_key
    FOR SHARE;
    SELECT batch.* INTO v_batch
    FROM public.analysis_v2_profile_fetch_batches AS batch
    WHERE batch.request_id = p_request_id
      AND batch.job_key = p_producer_job_key
    FOR SHARE;

    IF v_producer.request_id IS NULL
       OR v_producer.status <> 'completed'
       OR v_batch.request_id IS NULL
       OR pg_catalog.cardinality(v_batch.requested_usernames) <> p_expected_item_count
       OR (
            pg_catalog.cardinality(v_batch.frozen_unresolved_usernames) > 0
            AND v_batch.fallback_completed_at IS NULL
            AND NOT public.analysis_v2_profile_fetch_bounded_direct_fresh_apify_ready(
                p_request_id,
                p_producer_job_key,
                p_expected_item_count
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CONSUMER_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    IF p_producer_job_key LIKE 'track:profiles:batch:%' THEN
        v_batch_suffix := pg_catalog.substring(
            p_producer_job_key,
            '^track:profiles:batch:([0-9]+)$'
        );
        IF v_batch_suffix IS NULL
           OR p_expected_producer_input_hash IS NULL
           OR v_producer.input_hash IS DISTINCT FROM p_expected_producer_input_hash
           OR v_producer.track <> 'profiles'
           OR v_producer.kind <> 'profile_fetch'
           OR v_producer.batch IS DISTINCT FROM v_batch_suffix::INTEGER
           OR v_consumer.job_key <> 'track:profile-ai:batch:' || v_batch_suffix
           OR v_consumer.track <> 'profile_ai'
           OR v_consumer.kind <> 'ai'
           OR v_consumer.batch IS DISTINCT FROM v_batch_suffix::INTEGER THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROFILE_CONSUMER_SCOPE_MISMATCH',
                ERRCODE = 'P0001';
        END IF;
    ELSIF p_producer_job_key = 'track:target-evidence:collect' THEN
        SELECT preflight.target_instagram_id INTO v_target_username
        FROM public.analysis_preflights AS preflight
        WHERE preflight.consumed_request_id = p_request_id;
        IF p_expected_producer_input_hash IS NOT NULL
           OR p_expected_item_count <> 1
           OR v_producer.track <> 'target_evidence'
           OR v_producer.kind <> 'collection'
           OR v_batch.requested_usernames <> ARRAY[v_target_username]
           OR v_consumer.job_key NOT IN (
                'coordinator:candidate-screening',
                'track:reverse-likes:collect',
                'track:partner-safety:batch:0',
                'track:narratives:batch:0',
                'coordinator:finalize'
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROFILE_CONSUMER_SCOPE_MISMATCH',
                ERRCODE = 'P0001';
        END IF;
    ELSE
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROFILE_CONSUMER_SCOPE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    RETURN public.analysis_v2_profile_checkpoint_snapshot(
        p_request_id,
        p_producer_job_key
    );
END;
$_$;


--
-- Name: load_analysis_v2_profile_provider_canary_cleanup_inventory(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_profile_provider_canary_cleanup_inventory(p_source_request_id uuid, p_cleanup_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_experiment public.analysis_v2_profile_provider_canary_experiments%ROWTYPE;
    v_source_runs JSONB;
    v_canary_runs JSONB;
    v_source_count INTEGER;
    v_source_job_count INTEGER;
    v_source_run_id_count INTEGER;
BEGIN
    IF p_source_request_id IS NULL OR p_cleanup_claim_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT experiment.* INTO v_experiment
    FROM public.analysis_v2_profile_provider_canary_experiments AS experiment
    WHERE experiment.source_request_id = p_source_request_id
      AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
    FOR UPDATE;
    IF NOT FOUND OR v_experiment.state IS DISTINCT FROM 'terminalizing'
       OR v_experiment.cleanup_claim_token IS DISTINCT FROM p_cleanup_claim_token THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    SELECT pg_catalog.count(*)::INTEGER,
        pg_catalog.count(DISTINCT provider_run.job_key)::INTEGER,
        pg_catalog.count(DISTINCT provider_run.run_id)::INTEGER,
        COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'runId', provider_run.run_id,
            'credentialSlot', provider_run.credential_slot
        ) ORDER BY provider_run.job_key), '[]'::JSONB)
    INTO v_source_count, v_source_job_count, v_source_run_id_count, v_source_runs
    FROM public.analysis_v2_provider_runs AS provider_run
    JOIN public.analysis_v2_provider_execution_policies AS execution_policy
      ON execution_policy.request_id = provider_run.request_id
    WHERE provider_run.request_id = p_source_request_id
      AND provider_run.status = 'succeeded'
      AND provider_run.run_id ~ '^[A-Za-z0-9]{8,64}$'
      AND provider_run.actor_id = 'apify/instagram-profile-scraper'
      AND provider_run.job_key ~ '^track:profiles:batch:(?:0|[1-7])$'
      AND provider_run.operation_key ~ '^profile-fallback:[0-9a-f]{64}$'
      AND execution_policy.mode = 'test_operation_split'
      AND execution_policy.policy_version = 'authorized-free-e2e-v1'
      AND execution_policy.operation_slot_map->>'profile-fallback' = provider_run.credential_slot;
    IF v_source_count IS DISTINCT FROM 8
       OR v_source_job_count IS DISTINCT FROM 8
       OR v_source_run_id_count IS DISTINCT FROM 8 THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_INVENTORY_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'repetition', canary_run.repetition,
        'runId', canary_run.run_id,
        'credentialSlot', canary_run.credential_slot,
        'reservationToken', canary_run.reservation_token
    ) ORDER BY canary_run.repetition), '[]'::JSONB)
    INTO v_canary_runs
    FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.run_id IS NOT NULL;

    RETURN pg_catalog.jsonb_build_object(
        'sourceRequestId', p_source_request_id,
        'sourceRuns', v_source_runs,
        'canaryRuns', v_canary_runs
    );
END;
$_$;


--
-- Name: load_analysis_v2_profile_provider_canary_experiment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_profile_provider_canary_experiment(p_source_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_experiment public.analysis_v2_profile_provider_canary_experiments%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT experiment.* INTO v_experiment
    FROM public.analysis_v2_profile_provider_canary_experiments AS experiment
    WHERE experiment.source_request_id = p_source_request_id
      AND experiment.canary_version = 'profile-fallback-replacement-canary-v1';
    IF NOT FOUND THEN RETURN NULL; END IF;
    RETURN public.analysis_v2_profile_provider_canary_experiment_json(v_experiment);
END;
$$;


--
-- Name: load_analysis_v2_profile_provider_canary_run(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
