--
-- Name: load_analysis_v2_provider_run(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_provider_run(p_request_id uuid, p_job_key text, p_operation_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_run public.analysis_v2_provider_runs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_operation_key IS NULL
       OR NOT public.analysis_v2_valid_provider_operation_key(p_operation_key) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    RETURN public.analysis_v2_provider_run_json(v_run);
END;
$_$;


--
-- Name: load_analysis_v2_provider_run_cleanup_intent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_provider_run_cleanup_intent(p_request_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT CASE WHEN intent.request_id IS NULL THEN NULL ELSE
        pg_catalog.jsonb_build_object(
            'requestId', intent.request_id,
            'jobKey', intent.failed_job_key,
            'jobInputHash', intent.failed_job_input_hash,
            'errorCode', intent.error_code
        )
    END
    FROM (SELECT p_request_id AS requested_id) AS requested
    LEFT JOIN public.analysis_v2_provider_cleanup_intents AS intent
      ON intent.request_id = requested.requested_id
     AND intent.completed_at IS NULL;
$$;


--
-- Name: load_analysis_v2_provider_run_cleanup_intent_for_job(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_provider_run_cleanup_intent_for_job(p_request_id uuid, p_job_key text, p_job_input_hash text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT CASE WHEN intent.request_id IS NULL THEN NULL ELSE
        pg_catalog.jsonb_build_object(
            'requestId', intent.request_id,
            'jobKey', intent.failed_job_key,
            'jobInputHash', intent.failed_job_input_hash,
            'errorCode', intent.error_code
        )
    END
    FROM public.analysis_v2_provider_cleanup_intents AS intent
    JOIN public.analysis_pipeline_jobs AS failed_job
      ON failed_job.request_id = intent.request_id
     AND failed_job.job_key = intent.failed_job_key
     AND failed_job.input_hash = intent.failed_job_input_hash
    WHERE intent.request_id = p_request_id
      AND intent.failed_job_key = p_job_key
      AND failed_job.input_hash = p_job_input_hash
      AND intent.completed_at IS NULL;
$$;


--
-- Name: load_analysis_v2_relationship_staging(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_relationship_staging(p_request_id uuid, p_job_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_manifest public.analysis_v2_relationship_manifests%ROWTYPE;
    v_followers public.analysis_v2_relationship_sides%ROWTYPE;
    v_following public.analysis_v2_relationship_sides%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR NOT EXISTS (
            SELECT 1
            FROM public.analysis_requests AS analysis_request
            WHERE analysis_request.id = p_request_id
              AND analysis_request.pipeline_version = 'v2'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT relationship_manifest.*
    INTO v_manifest
    FROM public.analysis_v2_relationship_manifests AS relationship_manifest
    WHERE relationship_manifest.request_id = p_request_id
      AND relationship_manifest.job_key = p_job_key;
    IF NOT FOUND THEN RETURN NULL; END IF;

    SELECT relationship_side.*
    INTO STRICT v_followers
    FROM public.analysis_v2_relationship_sides AS relationship_side
    WHERE relationship_side.request_id = p_request_id
      AND relationship_side.job_key = p_job_key
      AND relationship_side.side = 'followers';
    SELECT relationship_side.*
    INTO STRICT v_following
    FROM public.analysis_v2_relationship_sides AS relationship_side
    WHERE relationship_side.request_id = p_request_id
      AND relationship_side.job_key = p_job_key
      AND relationship_side.side = 'following';

    RETURN pg_catalog.jsonb_build_object(
        'requestId', p_request_id,
        'jobKey', p_job_key,
        'excludedUsername', v_manifest.excluded_username,
        'detailedMutualLimit', v_manifest.detailed_mutual_limit,
        'manifest', public.analysis_v2_relationship_manifest_json(v_manifest),
        'followers', public.analysis_v2_relationship_side_json(v_followers)
            || pg_catalog.jsonb_build_object(
                'provider', v_followers.provider,
                'providerRunId', v_followers.provider_run_id,
                'providerOperationKey', v_followers.provider_operation_key,
                'providerCredentialSlot', v_followers.provider_credential_slot,
                'rows', COALESCE((
                    SELECT pg_catalog.jsonb_agg(
                        pg_catalog.jsonb_build_object(
                            'username', relationship_row.username,
                            'isPrivate', relationship_row.is_private,
                            'isVerified', relationship_row.is_verified,
                            'fullName', relationship_row.full_name,
                            'profilePicUrl', relationship_row.profile_pic_url
                        ) ORDER BY relationship_row.ordinal
                    )
                    FROM public.analysis_v2_relationship_rows AS relationship_row
                    WHERE relationship_row.request_id = p_request_id
                      AND relationship_row.job_key = p_job_key
                      AND relationship_row.side = 'followers'
                ), '[]'::JSONB)
            ),
        'following', public.analysis_v2_relationship_side_json(v_following)
            || pg_catalog.jsonb_build_object(
                'provider', v_following.provider,
                'providerRunId', v_following.provider_run_id,
                'providerOperationKey', v_following.provider_operation_key,
                'providerCredentialSlot', v_following.provider_credential_slot,
                'rows', COALESCE((
                    SELECT pg_catalog.jsonb_agg(
                        pg_catalog.jsonb_build_object(
                            'username', relationship_row.username,
                            'isPrivate', relationship_row.is_private,
                            'isVerified', relationship_row.is_verified,
                            'fullName', relationship_row.full_name,
                            'profilePicUrl', relationship_row.profile_pic_url
                        ) ORDER BY relationship_row.ordinal
                    )
                    FROM public.analysis_v2_relationship_rows AS relationship_row
                    WHERE relationship_row.request_id = p_request_id
                      AND relationship_row.job_key = p_job_key
                      AND relationship_row.side = 'following'
                ), '[]'::JSONB)
            ),
        'mutualRows', COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'mutualOrdinal', mutual.mutual_ordinal,
                    'followingOrdinal', mutual.following_ordinal,
                    'username', mutual.username,
                    'isPrivate', mutual.is_private,
                    'isVerified', mutual.is_verified,
                    'fullName', mutual.full_name,
                    'profilePicUrl', mutual.profile_pic_url,
                    'detailedOrdinal', mutual.detailed_ordinal
                ) ORDER BY mutual.mutual_ordinal
            )
            FROM public.analysis_v2_mutual_rows AS mutual
            WHERE mutual.request_id = p_request_id
              AND mutual.job_key = p_job_key
        ), '[]'::JSONB),
        'detailedPublicUsernames', COALESCE((
            SELECT pg_catalog.jsonb_agg(
                mutual.username ORDER BY mutual.detailed_ordinal
            )
            FROM public.analysis_v2_mutual_rows AS mutual
            WHERE mutual.request_id = p_request_id
              AND mutual.job_key = p_job_key
              AND mutual.detailed_ordinal IS NOT NULL
        ), '[]'::JSONB),
        'privateMutualUsernames', COALESCE((
            SELECT pg_catalog.jsonb_agg(
                mutual.username ORDER BY mutual.mutual_ordinal
            )
            FROM public.analysis_v2_mutual_rows AS mutual
            WHERE mutual.request_id = p_request_id
              AND mutual.job_key = p_job_key
              AND mutual.is_private
        ), '[]'::JSONB)
        ,
        'privateMutualRows', COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'mutualOrdinal', mutual.mutual_ordinal,
                    'followingOrdinal', mutual.following_ordinal,
                    'username', mutual.username,
                    'isPrivate', mutual.is_private,
                    'isVerified', mutual.is_verified,
                    'fullName', mutual.full_name,
                    'profilePicUrl', mutual.profile_pic_url,
                    'detailedOrdinal', mutual.detailed_ordinal
                ) ORDER BY mutual.mutual_ordinal
            )
            FROM public.analysis_v2_mutual_rows AS mutual
            WHERE mutual.request_id = p_request_id
              AND mutual.job_key = p_job_key
              AND mutual.is_private
        ), '[]'::JSONB)
    );
END;
$_$;


--
-- Name: load_analysis_v2_result_image_manifest_page(uuid, text, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_result_image_manifest_page(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_after_ordinal integer, p_page_size integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF p_after_ordinal NOT BETWEEN -1 AND 50000
       OR p_page_size NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    PERFORM public.analysis_v2_assert_result_image_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    RETURN COALESCE((
        SELECT pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'kind', page.kind,
                'candidateLocator', page.candidate_locator,
                'sortOrdinal', page.sort_ordinal,
                'sourceFingerprint', page.source_fingerprint,
                'status', page.status,
                'objectKey', page.object_key,
                'sha256', page.sha256,
                'byteSize', page.byte_size,
                'capturedAt', page.captured_at,
                'expiresAt', page.expires_at,
                'failureCode', page.failure_code,
                'isMandatory', page.is_mandatory
            )
            ORDER BY page.sort_ordinal
        )
        FROM (
            SELECT image_object.*
            FROM public.analysis_v2_result_image_objects AS image_object
            WHERE image_object.request_id = p_request_id
              AND image_object.sort_ordinal > p_after_ordinal
            ORDER BY image_object.sort_ordinal
            LIMIT p_page_size
        ) AS page
    ), '[]'::JSONB);
END;
$$;


--
-- Name: load_analysis_v2_result_image_object(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_result_image_object(p_request_id uuid, p_user_id uuid, p_kind text, p_candidate_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_locator TEXT;
    v_result JSONB;
BEGIN
    IF p_request_id IS NULL OR p_user_id IS NULL
       OR p_kind NOT IN ('target', 'female', 'private')
       OR (
            p_kind = 'target'
            AND p_candidate_id IS NOT NULL
       )
       OR (
            p_kind <> 'target'
            AND (
                p_candidate_id IS NULL
                OR p_candidate_id !~ '^[A-Za-z0-9._:-]{1,128}$'
                OR p_candidate_id ~* 'https?'
            )
       ) THEN
        RETURN NULL;
    END IF;
    v_locator := CASE
        WHEN p_kind = 'target' THEN 'target'
        ELSE p_candidate_id
    END;
    SELECT pg_catalog.jsonb_build_object(
        'objectKey', image_object.object_key,
        'sha256', image_object.sha256,
        'byteSize', image_object.byte_size,
        'expiresAt', image_object.expires_at
    )
    INTO v_result
    FROM public.analysis_requests AS analysis_request
    JOIN public.analysis_v2_result_image_objects AS image_object
      ON image_object.request_id = analysis_request.id
     AND image_object.kind = p_kind
     AND image_object.candidate_locator = v_locator
    WHERE analysis_request.id = p_request_id
      AND analysis_request.user_id = p_user_id
      AND analysis_request.pipeline_version = 'v2'
      AND analysis_request.status = 'completed'
      AND image_object.status = 'ready'
      AND image_object.expires_at > pg_catalog.clock_timestamp();
    RETURN v_result;
END;
$_$;


--
-- Name: load_analysis_v2_result_image_url(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_result_image_url(p_request_id uuid, p_user_id uuid, p_kind text, p_candidate_id text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_url TEXT;
BEGIN
    IF p_request_id IS NULL OR p_user_id IS NULL
       OR p_kind NOT IN ('target', 'female', 'private')
       OR (p_kind = 'target' AND p_candidate_id IS NOT NULL)
       OR (
            p_kind <> 'target'
            AND (p_candidate_id IS NULL OR p_candidate_id !~ '^[A-Za-z0-9._:-]{1,128}$')
       ) THEN
        RETURN NULL;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = p_request_id
          AND analysis_request.user_id = p_user_id
          AND analysis_request.pipeline_version = 'v2'
          AND analysis_request.status = 'completed'
    ) THEN
        RETURN NULL;
    END IF;
    IF p_kind = 'target' THEN
        SELECT summary.target_profile_image_url INTO v_url
        FROM public.analysis_v2_result_summaries AS summary
        WHERE summary.request_id = p_request_id;
    ELSIF p_kind = 'female' THEN
        SELECT female.profile_image_url INTO v_url
        FROM public.analysis_v2_effective_female_results(p_request_id) AS female
        WHERE female.candidate_id = p_candidate_id;
    ELSE
        SELECT private_result.profile_image_url INTO v_url
        FROM public.analysis_v2_private_results AS private_result
        WHERE private_result.request_id = p_request_id
          AND private_result.candidate_id = p_candidate_id;
    END IF;
    RETURN v_url;
END;
$_$;


--
-- Name: load_analysis_v2_result_page(uuid, uuid, integer, text, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_result_page(p_request_id uuid, p_user_id uuid, p_female_after_ordinal integer, p_female_after_candidate_id text, p_private_after_ordinal integer, p_private_after_candidate_id text, p_page_size integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_summary public.analysis_v2_result_summaries%ROWTYPE;
BEGIN
    IF p_request_id IS NULL OR p_user_id IS NULL
       OR p_page_size IS NULL OR p_page_size NOT BETWEEN 1 AND 50
       OR (p_female_after_ordinal IS NULL) <> (p_female_after_candidate_id IS NULL)
       OR (p_private_after_ordinal IS NULL) <> (p_private_after_candidate_id IS NULL)
       OR (
            p_female_after_ordinal IS NOT NULL
            AND (
                p_female_after_ordinal NOT BETWEEN 1 AND 900
                OR p_female_after_candidate_id !~ '^[A-Za-z0-9._:-]{1,128}$'
            )
       ) OR (
            p_private_after_ordinal IS NOT NULL
            AND (
                p_private_after_ordinal NOT BETWEEN 1 AND 1200
                OR p_private_after_candidate_id !~ '^[A-Za-z0-9._:-]{1,128}$'
            )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = p_request_id
          AND analysis_request.user_id = p_user_id
          AND analysis_request.pipeline_version = 'v2'
          AND analysis_request.status = 'completed'
    ) THEN
        RETURN NULL;
    END IF;
    SELECT summary.* INTO v_summary
    FROM public.analysis_v2_result_summaries AS summary
    WHERE summary.request_id = p_request_id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', p_request_id,
        'summary', public.analysis_v2_effective_result_summary_json(p_request_id, v_summary),
        'femaleAccounts', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'candidateId', page.candidate_id,
                'sortOrdinal', page.sort_ordinal,
                'row', pg_catalog.jsonb_build_object(
                    'instagramId', page.instagram_id,
                    'fullName', page.full_name,
                    'profileImageUrl', page.profile_image_url,
                    'bio', page.bio,
                    'displayScore', page.display_score,
                    'riskBand', page.risk_band,
                    'featuredRank', page.featured_rank,
                    'recentMutualRank', page.recent_mutual_rank,
                    'analysisDepth', page.analysis_depth,
                    'oneLineOverview', page.one_line_overview,
                    'highRiskNarrative', CASE
                        WHEN page.narrative_line_one IS NULL THEN NULL
                        ELSE pg_catalog.jsonb_build_array(
                            page.narrative_line_one, page.narrative_line_two
                        ) END
                )
            ) ORDER BY page.sort_ordinal, page.candidate_id)
            FROM (
                SELECT female.*
                FROM public.analysis_v2_effective_female_results(p_request_id) AS female
                WHERE female.request_id = p_request_id
                  AND (
                    p_female_after_ordinal IS NULL
                    OR female.sort_ordinal > p_female_after_ordinal
                    OR (
                        female.sort_ordinal = p_female_after_ordinal
                        AND female.candidate_id > p_female_after_candidate_id
                    )
                  )
                ORDER BY female.sort_ordinal, female.candidate_id
                LIMIT p_page_size + 1
            ) AS page
        ), '[]'::JSONB),
        'privateAccounts', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'candidateId', page.candidate_id,
                'sortOrdinal', page.sort_ordinal,
                'row', pg_catalog.jsonb_build_object(
                    'instagramId', page.instagram_id,
                    'fullName', page.full_name,
                    'profileImageUrl', page.profile_image_url
                )
            ) ORDER BY page.sort_ordinal, page.candidate_id)
            FROM (
                SELECT private_result.*
                FROM public.analysis_v2_private_results AS private_result
                WHERE private_result.request_id = p_request_id
                  AND (
                    p_private_after_ordinal IS NULL
                    OR private_result.sort_ordinal > p_private_after_ordinal
                    OR (
                        private_result.sort_ordinal = p_private_after_ordinal
                        AND private_result.candidate_id > p_private_after_candidate_id
                    )
                  )
                ORDER BY private_result.sort_ordinal, private_result.candidate_id
                LIMIT p_page_size + 1
            ) AS page
        ), '[]'::JSONB)
    );
END;
$_$;


--
-- Name: load_analysis_v2_result_snapshot(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_result_snapshot(p_request_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_summary public.analysis_v2_result_summaries%ROWTYPE;
BEGIN
    IF p_request_id IS NULL OR p_user_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = p_request_id
          AND analysis_request.user_id = p_user_id
          AND analysis_request.pipeline_version = 'v2'
          AND analysis_request.status = 'completed'
    ) THEN
        RETURN NULL;
    END IF;
    SELECT summary.* INTO v_summary
    FROM public.analysis_v2_result_summaries AS summary
    WHERE summary.request_id = p_request_id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', p_request_id,
        'summary', public.analysis_v2_effective_result_summary_json(p_request_id, v_summary),
        'femaleAccounts', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'candidateId', female.candidate_id,
                'sortOrdinal', female.sort_ordinal,
                'row', pg_catalog.jsonb_build_object(
                    'instagramId', female.instagram_id,
                    'fullName', female.full_name,
                    'profileImageUrl', female.profile_image_url,
                    'bio', female.bio,
                    'displayScore', female.display_score,
                    'riskBand', female.risk_band,
                    'featuredRank', female.featured_rank,
                    'recentMutualRank', female.recent_mutual_rank,
                    'analysisDepth', female.analysis_depth,
                    'oneLineOverview', female.one_line_overview,
                    'highRiskNarrative', CASE
                        WHEN female.narrative_line_one IS NULL THEN NULL
                        ELSE pg_catalog.jsonb_build_array(
                            female.narrative_line_one, female.narrative_line_two
                        ) END
                )
            ) ORDER BY female.sort_ordinal)
            FROM public.analysis_v2_effective_female_results(p_request_id) AS female
            WHERE female.request_id = p_request_id
        ), '[]'::JSONB),
        'privateAccounts', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'candidateId', private_result.candidate_id,
                'sortOrdinal', private_result.sort_ordinal,
                'row', pg_catalog.jsonb_build_object(
                    'instagramId', private_result.instagram_id,
                    'fullName', private_result.full_name,
                    'profileImageUrl', private_result.profile_image_url
                )
            ) ORDER BY private_result.sort_ordinal)
            FROM public.analysis_v2_private_results AS private_result
            WHERE private_result.request_id = p_request_id
        ), '[]'::JSONB)
    );
END;
$$;


--
-- Name: load_analysis_v2_result_stage_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_result_stage_snapshot(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_RESULT_INVALID', ERRCODE = 'P0001';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = p_request_id
          AND analysis_request.pipeline_version = 'v2'
    ) OR NOT EXISTS (
        SELECT 1 FROM public.analysis_v2_candidate_feature_manifests AS manifest
        WHERE manifest.request_id = p_request_id
    ) THEN
        RETURN NULL;
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', p_request_id,
        'profileClassifications', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'candidateId', feature.candidate_id,
                'instagramId', feature.instagram_id,
                'fullName', feature.full_name,
                'profileImageUrl', feature.profile_image_url,
                'bio', feature.bio,
                'classification', feature.terminal_classification,
                'mediaContext', feature.media_context,
                'genderOperationKey', feature.gender_operation_key,
                'genderResultHash', feature.gender_result_hash,
                'featureOperationKey', feature.feature_operation_key,
                'featureResultHash', feature.feature_result_hash,
                'feature', CASE WHEN feature.terminal_classification = 'verified_female'
                    THEN pg_catalog.jsonb_build_object(
                        'appearanceGrade', feature.appearance_grade,
                        'exposureScore', feature.exposure_score,
                        'isBusinessAccount', feature.is_business_account,
                        'featurePartnerEvidenceStrong',
                            feature.feature_partner_evidence_strong,
                        'oneLineOverview', feature.one_line_overview
                    ) ELSE NULL END
            ) ORDER BY feature.candidate_id)
            FROM public.analysis_v2_candidate_feature_rows AS feature
            WHERE feature.request_id = p_request_id
        ), '[]'::JSONB),
        'preliminaryScores', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'candidateId', score.candidate_id,
                'components', score.components,
                'preScore', score.pre_score,
                'possibleUpperBound', score.possible_upper_bound,
                'recentMutualRank', score.recent_mutual_rank,
                'verificationShortlistRank', score.verification_shortlist_rank
            ) ORDER BY score.candidate_id)
            FROM public.analysis_v2_preliminary_score_rows AS score
            WHERE score.request_id = p_request_id
        ), '[]'::JSONB),
        'reverseLikes', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'candidateId', reverse_like.candidate_id,
                'status', reverse_like.reverse_like_status,
                'componentScore', reverse_like.component_score,
                'evidenceRefIds', pg_catalog.to_jsonb(reverse_like.evidence_ref_ids)
            ) ORDER BY reverse_like.candidate_id)
            FROM public.analysis_v2_reverse_like_rows AS reverse_like
            WHERE reverse_like.request_id = p_request_id
        ), '[]'::JSONB),
        'partnerSafety', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'candidateId', partner.candidate_id,
                'source', partner.source,
                'hasStrongPartnerEvidence', partner.has_strong_partner_evidence,
                'hasWeakPartnerEvidence', partner.has_weak_partner_evidence,
                'strongEvidenceBasis', partner.strong_evidence_basis,
                'evidenceSelectionIds', pg_catalog.to_jsonb(partner.evidence_selection_ids),
                'bundleId', partner.bundle_id,
                'operationKey', partner.operation_key,
                'aiResultHash', partner.ai_result_hash
            ) ORDER BY partner.candidate_id)
            FROM public.analysis_v2_partner_safety_rows AS partner
            WHERE partner.request_id = p_request_id
        ), '[]'::JSONB),
        'finalScores', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'candidateId', score.candidate_id,
                'displayScore', score.display_score,
                'riskBand', score.risk_band,
                'featuredRank', score.featured_rank,
                'recentMutualRank', score.recent_mutual_rank,
                'verificationShortlistRank', score.verification_shortlist_rank,
                'partnerSafetySource', score.partner_safety_source,
                'partnerSafetyOperationKey', score.partner_safety_operation_key,
                'partnerSafetyResultHash', score.partner_safety_result_hash,
                'components', score.components,
                'weakPartnerAdjustment', score.weak_partner_adjustment,
                'preScore', score.pre_score,
                'rawScore', score.raw_score,
                'possibleUpperBound', score.possible_upper_bound,
                'publicScore', score.public_score,
                'possibleUpperPublicScore', score.possible_upper_public_score,
                'partnerCapApplied', score.partner_cap_applied,
                'partnerEvidenceSelectionIds',
                    pg_catalog.to_jsonb(score.partner_evidence_selection_ids)
            ) ORDER BY score.candidate_id)
            FROM public.analysis_v2_candidate_score_rows AS score
            WHERE score.request_id = p_request_id
        ), '[]'::JSONB),
        'privateNames', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'candidateId', private_name.candidate_id,
                'instagramId', private_name.instagram_id,
                'fullName', private_name.full_name,
                'profileImageUrl', private_name.profile_image_url,
                'nameFemaleScore', private_name.name_female_score,
                'nameIsName', private_name.name_is_name,
                'nameConfidence', private_name.name_confidence
            ) ORDER BY private_name.candidate_id)
            FROM public.analysis_v2_private_name_rows AS private_name
            WHERE private_name.request_id = p_request_id
        ), '[]'::JSONB),
        'narratives', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'candidateId', narrative.candidate_id,
                'lines', pg_catalog.jsonb_build_array(
                    narrative.line_one, narrative.line_two
                ),
                'source', narrative.source,
                'operationKey', narrative.operation_key,
                'aiResultHash', narrative.ai_result_hash
            ) ORDER BY narrative.candidate_id)
            FROM public.analysis_v2_narrative_rows AS narrative
            WHERE narrative.request_id = p_request_id
        ), '[]'::JSONB)
    );
END;
$$;


--
-- Name: load_analysis_v2_reusable_target_profile_run(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_reusable_target_profile_run(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_local JSONB;
BEGIN
    v_local := public.load_analysis_v2_reusable_target_profile_run_pre_first15(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    IF v_local IS NOT NULL THEN RETURN v_local; END IF;
    RETURN public.load_analysis_v2_reusable_target_profile_run_first15(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
END;
$$;


--
-- Name: load_analysis_v2_reusable_target_profile_run_first15(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_reusable_target_profile_run_first15(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_rearm public.earlybird_first15_canary_provider_rearms%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
    v_profile_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS DISTINCT FROM 'track:target-evidence:collect'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[0-9a-f]{64}$'
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_TARGET_PROFILE_REUSE_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id
    FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    SELECT rearm.* INTO v_rearm
    FROM public.earlybird_first15_canary_provider_rearms AS rearm
    WHERE rearm.rearmed_preflight_id = v_request.preflight_id
    FOR KEY SHARE;
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = v_rearm.order_id
    FOR KEY SHARE;
    IF v_request.id IS NULL
       OR v_job.request_id IS NULL
       OR v_rearm.order_id IS NULL
       OR v_order.id IS NULL
       OR v_request.pipeline_version <> 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR v_order.result_request_id IS DISTINCT FROM v_request.id
       OR v_order.status <> 'analysis_in_progress'
       OR v_order.concierge_apify_credential_slot
            IS DISTINCT FROM v_rearm.fallback_credential_slot
       OR v_job.status <> 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_TARGET_PROFILE_REUSE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT provider_run.* INTO v_profile_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = v_rearm.profile_source_preflight_id
      AND provider_run.operation_key = 'target-profile-fresh-admission:g1';
    IF NOT FOUND THEN RETURN NULL; END IF;
    IF v_profile_run.status <> 'succeeded'
       OR v_profile_run.logical_provider <> 'apify'
       OR v_profile_run.actor_id <> 'apify/instagram-profile-scraper'
       OR v_profile_run.run_id IS NULL
       OR v_profile_run.actual_usage_usd IS NULL
       OR v_profile_run.usage_reconciled_at IS NULL
       OR v_profile_run.reusable_profile_schema_version <> 1
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_TARGET_PROFILE_REUSE_SOURCE_UNAVAILABLE',
            ERRCODE = 'P0001';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'runId', v_profile_run.run_id,
        'inputHash', v_profile_run.input_hash,
        'credentialSlot', v_profile_run.credential_slot,
        'maxChargeUsd', v_profile_run.max_charge_usd,
        'actorId', v_profile_run.actor_id
    );
END;
$_$;


--
-- Name: load_analysis_v2_reusable_target_profile_run_pre_first15(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_reusable_target_profile_run_pre_first15(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS DISTINCT FROM 'track:target-evidence:collect'
       OR p_claim_token IS NULL
       OR p_job_input_hash IS NULL
       OR p_job_input_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REUSABLE_TARGET_PROFILE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- Preserve the terminal-capable preflight -> request -> job lock order.
    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;

    IF v_preflight.id IS NULL
       OR v_request.id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR v_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_job.request_id IS NULL
       OR v_job.status IS DISTINCT FROM 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REUSABLE_TARGET_PROFILE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    IF v_preflight.status IS DISTINCT FROM 'consumed'
       OR v_preflight.consumed_request_id IS DISTINCT FROM p_request_id
       OR v_preflight.target_instagram_id IS DISTINCT FROM pg_catalog.lower(v_request.target_instagram_id)
       OR v_preflight.admission_generation NOT BETWEEN 1 AND 100
       OR v_preflight.admission_status IS DISTINCT FROM 'ready' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REUSABLE_TARGET_PROFILE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = v_preflight.id
      AND provider_run.operation_key = 'target-profile-fresh-admission:g'
            || v_preflight.admission_generation::TEXT;
    IF NOT FOUND OR v_run.reusable_profile_schema_version IS NULL THEN
        RETURN NULL;
    END IF;
    IF v_run.reusable_profile_schema_version <> 1
       OR v_run.logical_provider IS DISTINCT FROM 'apify'
       OR v_run.actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper'
       OR NOT public.analysis_v2_valid_apify_credential_slot(v_run.credential_slot)
       OR v_run.max_charge_usd IS DISTINCT FROM 0.002600000000
       OR v_run.status IS DISTINCT FROM 'succeeded'
       OR v_run.run_id IS NULL
       OR v_run.terminalized_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REUSABLE_TARGET_PROFILE_RUN_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'runId', v_run.run_id,
        'inputHash', v_run.input_hash,
        'credentialSlot', v_run.credential_slot,
        'maxChargeUsd', v_run.max_charge_usd,
        'actorId', v_run.actor_id
    );
END;
$_$;


--
-- Name: load_analysis_v2_revenue_resolver_outcomes_v1(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_revenue_resolver_outcomes_v1(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
BEGIN
    IF p_job_key IS DISTINCT FROM 'coordinator:join:primary-evidence'
       OR p_job_input_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    PERFORM public.analysis_revenue_ai_cost_assert_lineage_v1(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash, TRUE
    );
    RETURN pg_catalog.jsonb_build_object('rows', COALESCE((
        SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'candidateId', overlay.candidate_id,
            'classification', overlay.classification,
            'operationKey', overlay.operation_key,
            'resultHash', overlay.result_hash
        ) ORDER BY overlay.candidate_id)
        FROM public.analysis_revenue_resolver_outcome_overlays AS overlay
        WHERE overlay.request_id = p_request_id
          AND overlay.job_key = p_job_key
          AND overlay.job_input_hash = p_job_input_hash
    ), '[]'::JSONB));
END;
$_$;


--
-- Name: load_analysis_v2_risk_policy_version(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_risk_policy_version(p_request_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT analysis_request.policy_versions_snapshot->>'risk'
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2';
$$;


--
-- Name: load_analysis_v2_score_audit(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_score_audit(p_request_id uuid, p_cursor integer DEFAULT 0, p_page_size integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_run public.analysis_v2_score_audit_runs%ROWTYPE;
    v_rows JSONB;
    v_next INTEGER;
    v_total INTEGER;
BEGIN
    IF p_cursor < 0 OR p_cursor > 100000 OR p_page_size NOT BETWEEN 1 AND 50 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_SCORE_AUDIT_INVALID_PAGE', ERRCODE = 'P0001';
    END IF;
    SELECT * INTO v_run FROM public.analysis_v2_score_audit_runs
    WHERE request_id = p_request_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT pg_catalog.count(*) INTO v_total
    FROM public.analysis_v2_score_audit_rows
    WHERE request_id = p_request_id AND source_result_hash = v_run.source_result_hash;
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'candidateId', audit.candidate_id, 'rank', audit.actual_rank,
        'instagramId', audit.instagram_id, 'genderProvenance', audit.gender_provenance,
        'accountContext', audit.account_context,
        'officialGroupExcluded', audit.official_group_excluded,
        'officialGroupReason', audit.official_group_reason,
        'components', audit.components, 'signals', audit.signals,
        'rawScoreUnits', audit.raw_score_units,
        'naturalDisplayScore', audit.natural_display_score,
        'displayScore', audit.display_score, 'riskBand', audit.risk_band,
        'featuredRank', audit.featured_rank,
        'relativeTierApplied', audit.relative_tier_applied,
        'partnerCapApplied', audit.partner_cap_applied,
        'strongPartnerEvidence', audit.strong_partner_evidence,
        'scoreConsistent', audit.score_consistent
    ) ORDER BY audit.actual_rank), '[]'::JSONB) INTO v_rows
    FROM (
        SELECT * FROM public.analysis_v2_score_audit_rows
        WHERE request_id = p_request_id AND source_result_hash = v_run.source_result_hash
        ORDER BY actual_rank OFFSET p_cursor LIMIT p_page_size
    ) AS audit;
    v_next := CASE WHEN p_cursor + p_page_size < v_total
        THEN p_cursor + p_page_size ELSE NULL END;
    RETURN pg_catalog.jsonb_build_object(
        'request', pg_catalog.jsonb_build_object(
            'requestId', v_run.request_id::TEXT, 'status', v_run.status,
            'riskPolicyVersion', v_run.risk_policy_version,
            'aiPolicyVersion', v_run.ai_policy_version,
            'resultHash', v_run.source_result_hash, 'reason', v_run.reason,
            'updatedAt', v_run.updated_at
        ),
        'rows', v_rows, 'nextCursor', v_next,
        'officialGroupCount', (
            SELECT pg_catalog.count(*) FROM public.analysis_v2_score_audit_rows
            WHERE request_id = p_request_id
              AND source_result_hash = v_run.source_result_hash
              AND official_group_excluded
        )
    );
END;
$$;


--
-- Name: load_analysis_v2_selfhosted_auth_run(uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_selfhosted_auth_run(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_operation_key text, p_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_receipt public.analysis_v2_selfhosted_auth_runs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_claim_token IS NULL
       OR p_job_key IS NULL
       OR p_job_input_hash IS NULL
       OR p_operation_key IS NULL
       OR p_input_hash IS NULL
       OR p_job_key NOT IN (
            'track:relationships:collect',
            'track:target-evidence:collect',
            'track:reverse-likes:collect'
       )
       OR p_job_input_hash !~ '^[0-9a-f]{64}$'
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_operation_key !~ '^(relationship-(followers|following)|target-(likers|comments)|candidate-likers):[0-9a-f]{64}$'
       OR (
            p_job_key = 'track:relationships:collect'
            AND p_operation_key !~ '^relationship-(followers|following):[0-9a-f]{64}$'
       )
       OR (
            p_job_key = 'track:target-evidence:collect'
            AND p_operation_key !~ '^target-(likers|comments):[0-9a-f]{64}$'
       )
       OR (
            p_job_key = 'track:reverse-likes:collect'
            AND p_operation_key !~ '^candidate-likers:[0-9a-f]{64}$'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SELFHOSTED_AUTH_RUN_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= pg_catalog.clock_timestamp()
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SELFHOSTED_AUTH_RUN_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT receipt.* INTO v_receipt
    FROM public.analysis_v2_selfhosted_auth_runs AS receipt
    WHERE receipt.request_id = p_request_id
      AND receipt.job_key = p_job_key
      AND receipt.operation_key = p_operation_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    IF v_receipt.input_hash IS DISTINCT FROM p_input_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SELFHOSTED_AUTH_RUN_CONFLICT', ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_v2_selfhosted_auth_runs AS receipt
    SET job_claim_token = p_claim_token,
        updated_at = pg_catalog.clock_timestamp()
    WHERE receipt.request_id = p_request_id
      AND receipt.job_key = p_job_key
      AND receipt.operation_key = p_operation_key
    RETURNING receipt.* INTO v_receipt;
    RETURN public.analysis_v2_selfhosted_auth_run_json(v_receipt);
END;
$_$;


--
-- Name: load_analysis_v2_target_evidence(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_analysis_v2_target_evidence(p_request_id uuid, p_job_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_manifest public.analysis_v2_target_evidence_manifests%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR NOT EXISTS (
            SELECT 1
            FROM public.analysis_requests AS analysis_request
            WHERE analysis_request.id = p_request_id
              AND analysis_request.pipeline_version = 'v2'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT target_manifest.*
    INTO v_manifest
    FROM public.analysis_v2_target_evidence_manifests AS target_manifest
    WHERE target_manifest.request_id = p_request_id
      AND target_manifest.job_key = p_job_key;
    IF NOT FOUND THEN RETURN NULL; END IF;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', p_request_id,
        'jobKey', p_job_key,
        'targetUsername', v_manifest.target_username,
        'excludedUsername', v_manifest.excluded_username,
        'manifest', public.analysis_v2_target_evidence_manifest_json(v_manifest),
        'likerSource', public.analysis_v2_target_evidence_source_json(
            v_manifest.liker_source
        ),
        'commentSource', public.analysis_v2_target_evidence_source_json(
            v_manifest.comment_source
        ),
        'rows', COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'actorUsername', evidence.actor_username,
                    'postId', evidence.post_id,
                    'signal', evidence.signal,
                    'sourceInteractionId', evidence.source_interaction_id,
                    'occurredAt', evidence.occurred_at,
                    'content', evidence.comment_text
                ) ORDER BY evidence.ordinal
            )
            FROM public.analysis_target_interactors AS evidence
            WHERE evidence.request_id = p_request_id
              AND evidence.job_key = p_job_key
        ), '[]'::JSONB)
    );
END;
$_$;


--
-- Name: load_current_analysis_v2_gender_routing_manifest(uuid, text, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_current_analysis_v2_gender_routing_manifest(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_relationship_checkpoint_id text, p_policy_version text, p_plan_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_relationship public.analysis_v2_relationship_manifests%ROWTYPE;
    v_manifest public.analysis_v2_gender_routing_manifests%ROWTYPE;
    v_row_count INTEGER;
    v_selected_count INTEGER;
    v_min_ordinal INTEGER;
    v_max_ordinal INTEGER;
    v_rows JSONB;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key <> 'track:relationships:collect'
       OR p_claim_token IS NULL
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_relationship_checkpoint_id !~ '^[a-f0-9]{64}$'
       OR p_policy_version <> 'gender-routing-v1'
       OR p_plan_id NOT IN ('basic', 'standard') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    SELECT policy.* INTO v_policy
    FROM public.analysis_v2_provider_execution_policies AS policy
    WHERE policy.request_id = p_request_id
    FOR UPDATE;
    SELECT relationship_manifest.* INTO v_relationship
    FROM public.analysis_v2_relationship_manifests AS relationship_manifest
    WHERE relationship_manifest.request_id = p_request_id
      AND relationship_manifest.job_key = p_job_key
      AND relationship_manifest.result_hash = p_relationship_checkpoint_id
    FOR UPDATE;
    IF v_request.id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status IS DISTINCT FROM 'processing'
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot IS DISTINCT FROM p_plan_id
       OR v_policy.request_id IS NULL
       OR v_policy.mode IS DISTINCT FROM 'test_operation_split'
       OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR v_job.request_id IS NULL
       OR v_job.status IS DISTINCT FROM 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now
       OR v_relationship.request_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT routing_manifest.* INTO v_manifest
    FROM public.analysis_v2_gender_routing_manifests AS routing_manifest
    WHERE routing_manifest.request_id = p_request_id
      AND routing_manifest.relationship_checkpoint_id = p_relationship_checkpoint_id
      AND routing_manifest.policy_version = p_policy_version
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    IF v_manifest.status = 'building' THEN
        RETURN NULL;
    END IF;
    IF v_manifest.status IS DISTINCT FROM 'complete' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_NOT_COMPLETE', ERRCODE = 'P0001';
    END IF;
    IF v_manifest.relationship_job_key IS DISTINCT FROM p_job_key
       OR v_manifest.relationship_job_input_hash IS DISTINCT FROM p_job_input_hash
       OR v_manifest.plan_id IS DISTINCT FROM p_plan_id
       OR (p_plan_id = 'basic' AND (v_manifest.detailed_cap <> 100 OR v_manifest.population_count NOT BETWEEN 0 AND 400))
       OR (p_plan_id = 'standard' AND (v_manifest.detailed_cap <> 200 OR v_manifest.population_count NOT BETWEEN 0 AND 800))
       OR v_relationship.public_count IS DISTINCT FROM v_manifest.population_count THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT pg_catalog.count(*)::INTEGER,
           (SELECT pg_catalog.count(*)::INTEGER
            FROM public.analysis_v2_gender_routing_candidates AS all_candidate
            WHERE all_candidate.request_id = p_request_id
              AND all_candidate.relationship_checkpoint_id = p_relationship_checkpoint_id
              AND all_candidate.policy_version = p_policy_version),
           COALESCE(pg_catalog.min(candidate.ordinal), 1),
           COALESCE(pg_catalog.max(candidate.ordinal), 0),
           COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'mutualOrdinal', candidate.mutual_ordinal,
                'candidateKey', candidate.candidate_key,
                'selectionSlot', candidate.selection_slot,
                'ordinal', candidate.ordinal
           ) ORDER BY candidate.ordinal), '[]'::JSONB)
    INTO v_selected_count, v_row_count, v_min_ordinal, v_max_ordinal, v_rows
    FROM public.analysis_v2_gender_routing_candidates AS candidate
    WHERE candidate.request_id = p_request_id
      AND candidate.relationship_checkpoint_id = p_relationship_checkpoint_id
      AND candidate.policy_version = p_policy_version
      AND candidate.selected;
    IF v_row_count IS DISTINCT FROM v_manifest.population_count
       OR v_selected_count IS DISTINCT FROM v_manifest.selected_count
       OR v_manifest.selected_count IS DISTINCT FROM LEAST(v_manifest.population_count, v_manifest.detailed_cap)
       OR v_min_ordinal <> 1
       OR v_max_ordinal <> v_selected_count THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_CORRUPT', ERRCODE = 'P0001';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'header', public.analysis_v2_gender_routing_manifest_json(v_manifest),
        'selected', pg_catalog.jsonb_build_object('selectedCount', v_manifest.selected_count, 'rows', v_rows)
    );
END;
$_$;


--
-- Name: load_e2e_test_runner_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_e2e_test_runner_v1(p_user_id uuid) RETURNS TABLE(runner_plan text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT runner.runner_plan
    FROM public.account_e2e_test_runners AS runner
    JOIN public.users AS account ON account.id = runner.account_id
    JOIN auth.users AS auth_user ON auth_user.id = runner.account_id
    JOIN public.account_ledger_rollout_state AS rollout ON rollout.singleton IS TRUE
    WHERE runner.account_id = p_user_id
      AND account.account_class = 'e2e_test'
      AND account.traffic_class = 'e2e_test'
      AND account.lifecycle = 'active'
      AND runner.command_version = account.classification_version
      AND runner.command_version = rollout.classification_command_version
      AND rollout.paid_ever_state = 'active'
      AND pg_catalog.lower(pg_catalog.btrim(auth_user.email))
            = pg_catalog.lower(pg_catalog.btrim(account.email))
      AND auth_user.raw_app_meta_data ->> 'analysis_test_runner_v1'
            = runner.runner_plan
$$;


--
-- Name: load_earlybird_demand_summary(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_earlybird_demand_summary(p_start_date date, p_end_date_exclusive date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_start_at TIMESTAMP WITH TIME ZONE;
    v_end_at TIMESTAMP WITH TIME ZONE;
    v_result JSONB;
BEGIN
    IF p_start_date IS NULL
       OR p_end_date_exclusive IS NULL
       OR p_end_date_exclusive <= p_start_date
       OR p_end_date_exclusive - p_start_date > 90 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_DEMAND_RANGE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_start_at := p_start_date::TIMESTAMP AT TIME ZONE 'UTC';
    v_end_at := p_end_date_exclusive::TIMESTAMP AT TIME ZONE 'UTC';

    WITH scoped_paid_orders AS (
        SELECT
            order_row.plan_id,
            order_row.status,
            order_row.actual_amount_krw,
            order_row.payment_id,
            order_row.seller_reference_confirmed_at,
            order_row.due_at
        FROM public.earlybird_orders AS order_row
        WHERE order_row.paid_at >= v_start_at
          AND order_row.paid_at < v_end_at
    ),
    order_metrics AS (
        SELECT
            pg_catalog.count(*) FILTER (
                WHERE scoped.status IN (
                    'paid',
                    'analysis_in_progress',
                    'completed'
                )
                  AND scoped.actual_amount_krw IS NOT NULL
                  AND scoped.payment_id IS NOT NULL
                  AND scoped.seller_reference_confirmed_at IS NOT NULL
            ) AS confirmed_count,
            COALESCE(pg_catalog.sum(scoped.actual_amount_krw) FILTER (
                WHERE scoped.status IN (
                    'paid',
                    'analysis_in_progress',
                    'completed'
                )
                  AND scoped.actual_amount_krw IS NOT NULL
                  AND scoped.payment_id IS NOT NULL
                  AND scoped.seller_reference_confirmed_at IS NOT NULL
            ), 0) AS confirmed_gross,
            pg_catalog.count(*) FILTER (
                WHERE scoped.status IN (
                    'paid',
                    'analysis_in_progress',
                    'completed'
                )
                  AND scoped.actual_amount_krw IS NOT NULL
                  AND scoped.payment_id IS NOT NULL
                  AND scoped.seller_reference_confirmed_at IS NULL
            ) AS unconfirmed_paid_count,
            pg_catalog.count(*) FILTER (
                WHERE scoped.status IN (
                    'refund_pending',
                    'overflow_refund_required'
                )
                  AND scoped.actual_amount_krw IS NOT NULL
                  AND scoped.payment_id IS NOT NULL
            ) AS refund_liability_count,
            pg_catalog.count(*) FILTER (
                WHERE scoped.status IN ('paid', 'analysis_in_progress')
                  AND scoped.actual_amount_krw IS NOT NULL
                  AND scoped.payment_id IS NOT NULL
                  AND scoped.due_at IS NOT NULL
                  AND scoped.due_at < pg_catalog.clock_timestamp()
            ) AS overdue_fulfillment_count
        FROM scoped_paid_orders AS scoped
    ),
    pending_metrics AS (
        SELECT pg_catalog.count(*) AS pending_checkout_count
        FROM public.earlybird_orders AS order_row
        WHERE order_row.status = 'payment_pending'
          AND order_row.created_at >= v_start_at
          AND order_row.created_at < v_end_at
    ),
    waitlist_metrics AS (
        SELECT pg_catalog.count(*) AS plus_waitlist_count
        FROM public.earlybird_waitlist AS waitlist_row
        WHERE waitlist_row.plan_id = 'plus'
          AND waitlist_row.created_at >= v_start_at
          AND waitlist_row.created_at < v_end_at
    )
    SELECT pg_catalog.jsonb_build_object(
        'startDate', p_start_date,
        'endDateExclusive', p_end_date_exclusive,
        'referenceConfirmedPaymentCount', metrics.confirmed_count,
        'referenceConfirmedGrossKrw', metrics.confirmed_gross,
        'unconfirmedPaidOrderCount', metrics.unconfirmed_paid_count,
        'refundLiabilityCount', metrics.refund_liability_count,
        'overdueFulfillmentCount', metrics.overdue_fulfillment_count,
        'pendingCheckoutCount', pending.pending_checkout_count,
        'plusWaitlistCount', waitlist.plus_waitlist_count,
        'plans', (
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'planId', inventory.plan_id,
                    'confirmedPaymentCount', (
                        SELECT pg_catalog.count(*)
                        FROM scoped_paid_orders AS plan_order
                        WHERE plan_order.plan_id = inventory.plan_id
                          AND plan_order.status IN (
                              'paid',
                              'analysis_in_progress',
                              'completed'
                          )
                          AND plan_order.actual_amount_krw IS NOT NULL
                          AND plan_order.payment_id IS NOT NULL
                          AND plan_order.seller_reference_confirmed_at IS NOT NULL
                    ),
                    'confirmedGrossKrw', COALESCE((
                        SELECT pg_catalog.sum(plan_order.actual_amount_krw)
                        FROM scoped_paid_orders AS plan_order
                        WHERE plan_order.plan_id = inventory.plan_id
                          AND plan_order.status IN (
                              'paid',
                              'analysis_in_progress',
                              'completed'
                          )
                          AND plan_order.actual_amount_krw IS NOT NULL
                          AND plan_order.payment_id IS NOT NULL
                          AND plan_order.seller_reference_confirmed_at IS NOT NULL
                    ), 0),
                    'remainingSlots',
                        GREATEST(
                            (inventory.sale_limit - inventory.sold_count)::INTEGER,
                            0
                        )
                )
                ORDER BY CASE inventory.plan_id
                    WHEN 'basic' THEN 1
                    WHEN 'standard' THEN 2
                    ELSE 99
                END
            )
            FROM public.earlybird_plan_inventory AS inventory
            WHERE inventory.plan_id IN ('basic', 'standard')
        )
    )
    INTO v_result
    FROM order_metrics AS metrics
    CROSS JOIN pending_metrics AS pending
    CROSS JOIN waitlist_metrics AS waitlist;

    RETURN v_result;
END;
$$;


--
-- Name: load_earlybird_fulfillment_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_earlybird_fulfillment_status(p_order_id uuid) RETURNS text
