$$;


--
-- Name: mark_analysis_beta_preflight_prepare_dispatched(uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_beta_preflight_prepare_dispatched(p_preflight_id uuid, p_user_id uuid, p_prepare_generation integer, p_prepare_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE v_now TIMESTAMPTZ;
DECLARE v_gate_enabled BOOLEAN; v_grant public.analysis_beta_access_grants%ROWTYPE;
DECLARE v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    SELECT gate_row.enabled INTO v_gate_enabled
    FROM public.analysis_beta_runtime_gate AS gate_row
    WHERE gate_row.singleton=TRUE FOR SHARE;
    PERFORM 1 FROM public.users AS owner_user
    WHERE owner_user.id=p_user_id FOR KEY SHARE;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id=p_preflight_id AND preflight.user_id=p_user_id FOR UPDATE;
    SELECT grant_row.* INTO v_grant
    FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id=p_user_id FOR SHARE;
    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.id IS NULL
       OR v_preflight.beta_entry_provenance IS DISTINCT FROM 'betatest_service_v1'
       OR v_preflight.beta_prepare_generation IS DISTINCT FROM p_prepare_generation
       OR v_preflight.beta_prepare_token IS DISTINCT FROM p_prepare_token THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_PREPARE_FENCE_MISMATCH', ERRCODE='P0001';
    END IF;
    IF v_gate_enabled IS DISTINCT FROM TRUE OR v_grant.user_id IS NULL
       OR v_grant.enabled IS DISTINCT FROM TRUE
       OR (v_grant.expires_at IS NOT NULL AND (
            NOT pg_catalog.isfinite(v_grant.expires_at)
            OR v_grant.expires_at<=v_now
       )) THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_ACCESS_UNAVAILABLE', ERRCODE='P0001';
    END IF;
    IF v_preflight.beta_prepare_dispatch_state IN ('enqueued','completed') THEN RETURN FALSE; END IF;
    IF v_preflight.beta_prepare_dispatch_state IS DISTINCT FROM 'reserved' THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_PREPARE_FENCE_MISMATCH', ERRCODE='P0001';
    END IF;
    UPDATE public.analysis_preflights SET beta_prepare_dispatch_state='enqueued',
        beta_prepare_dispatched_at=v_now,
        updated_at=v_now WHERE id=p_preflight_id;
    RETURN TRUE;
END;
$$;


--
-- Name: mark_analysis_beta_preflight_prepare_retry_exhausted(uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_beta_preflight_prepare_retry_exhausted(p_preflight_id uuid, p_user_id uuid, p_prepare_generation integer, p_prepare_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE v_now TIMESTAMPTZ;
DECLARE v_gate_enabled BOOLEAN; v_grant public.analysis_beta_access_grants%ROWTYPE;
DECLARE v_preflight public.analysis_preflights%ROWTYPE;
DECLARE v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
DECLARE v_has_allocation BOOLEAN := FALSE;
BEGIN
    SELECT gate_row.enabled INTO v_gate_enabled
    FROM public.analysis_beta_runtime_gate AS gate_row
    WHERE gate_row.singleton=TRUE FOR SHARE;
    PERFORM 1 FROM public.users AS owner_user
    WHERE owner_user.id=p_user_id FOR KEY SHARE;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id=p_preflight_id AND preflight.user_id=p_user_id
    FOR UPDATE;
    IF v_preflight.id IS NULL
       OR v_preflight.beta_entry_provenance IS DISTINCT FROM 'betatest_service_v1'
       OR v_preflight.beta_prepare_generation IS DISTINCT FROM p_prepare_generation
       OR v_preflight.beta_prepare_token IS DISTINCT FROM p_prepare_token THEN
        RETURN FALSE;
    END IF;
    IF v_preflight.status='expired'
       OR v_preflight.beta_prepare_state='expired' THEN
        RETURN FALSE;
    END IF;
    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.expires_at<=v_now THEN
        UPDATE public.analysis_preflights AS preflight
        SET status='expired', updated_at=v_now,
            error_code=NULL, blocked_at=NULL
        WHERE preflight.id=v_preflight.id;
        RETURN TRUE;
    END IF;
    IF v_preflight.beta_prepare_state IN (
        'prepared','capacity_blocked','retry_exhausted','expired'
    ) OR v_preflight.beta_prepare_retry_exhausted_at IS NOT NULL THEN
        RETURN FALSE;
    END IF;
    SELECT allocation.* INTO v_allocation
    FROM public.analysis_beta_pool_allocations AS allocation
    WHERE allocation.preflight_id=p_preflight_id
    FOR UPDATE;
    v_has_allocation := FOUND;
    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.expires_at<=v_now THEN
        UPDATE public.analysis_preflights AS preflight
        SET status='expired', updated_at=v_now,
            error_code=NULL, blocked_at=NULL
        WHERE preflight.id=v_preflight.id;
        RETURN TRUE;
    END IF;
    -- A historical split hold is recovered by the claim RPC. It must never be
    -- replaced with a queue failure after provider credit was held.
    IF v_has_allocation THEN RETURN FALSE; END IF;
    SELECT grant_row.* INTO v_grant
    FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id=p_user_id FOR SHARE;
    v_now := pg_catalog.clock_timestamp();
    IF v_preflight.expires_at<=v_now THEN
        UPDATE public.analysis_preflights AS preflight
        SET status='expired', updated_at=v_now,
            error_code=NULL, blocked_at=NULL
        WHERE preflight.id=v_preflight.id;
        RETURN TRUE;
    END IF;
    IF v_preflight.status IS DISTINCT FROM 'pending'
       OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'standard'
       OR v_preflight.dispatch_state IS DISTINCT FROM 'unreserved'
       OR v_preflight.dispatch_generation IS DISTINCT FROM 0
       OR v_preflight.beta_prepare_state NOT IN ('reserved','preparing')
       OR (
            v_preflight.beta_prepare_state='preparing'
            AND v_preflight.beta_prepare_lease_expires_at>v_now
       ) THEN
        RETURN FALSE;
    END IF;
    UPDATE public.analysis_preflights AS preflight
    SET analysis_entry_channel='betatest',
        status='blocked',
        error_code='QUEUE_UNAVAILABLE',
        blocked_at=v_now,
        beta_prepare_state='retry_exhausted',
        beta_prepare_dispatch_state='completed',
        beta_prepare_lease_token=NULL,
        beta_prepare_lease_expires_at=NULL,
        beta_prepare_retry_exhausted_at=v_now,
        beta_prepare_completed_at=v_now,
        updated_at=v_now
    WHERE preflight.id=v_preflight.id;
    RETURN TRUE;
END;
$$;


--
-- Name: mark_analysis_lifecycle_event_sent(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_lifecycle_event_sent(p_request_id uuid, p_event_name text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
    UPDATE public.analysis_lifecycle_events
    SET sent_at = COALESCE(sent_at, pg_catalog.clock_timestamp())
    WHERE request_id = p_request_id
      AND event_name = p_event_name
    RETURNING TRUE;
$$;


--
-- Name: mark_analysis_preflight_rearmed_dispatch_for_provider_capacity_(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_preflight_rearmed_dispatch_for_provider_capacity_(p_preflight_id uuid, p_dispatch_generation integer, p_dispatch_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_token IS NULL THEN
        RETURN FALSE;
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;
    -- Ordinary capacity replay is fenced exclusively by the ordinary preflight columns.
    -- In particular, an admission/fresh token must never settle this function.
    IF v_preflight.status = 'pending'
       AND v_preflight.dispatch_state = 'enqueued'
       AND v_preflight.dispatch_workload_role = 'preflight'
       AND v_preflight.dispatch_contract_version = 2
       AND v_preflight.dispatch_generation = p_dispatch_generation
       AND v_preflight.last_dispatch_token IS NOT DISTINCT FROM p_dispatch_token THEN
        -- Mark response-loss replay: this exact DB fence is already settled.
        RETURN TRUE;
    END IF;
    UPDATE public.analysis_preflights AS preflight
    SET dispatch_state = 'enqueued',
        dispatch_token = NULL,
        last_dispatch_token = p_dispatch_token,
        dispatched_at = v_now,
        updated_at = v_now
    WHERE preflight.id = p_preflight_id
      AND preflight.status = 'pending'
      AND preflight.dispatch_state = 'reserved'
      AND preflight.dispatch_workload_role = 'preflight'
      AND preflight.dispatch_contract_version = 2
      AND preflight.dispatch_generation = p_dispatch_generation
      AND preflight.dispatch_token = p_dispatch_token;
    RETURN FOUND;
END;
$$;


--
-- Name: mark_analysis_revenue_cost_operation_started_provider_v2(uuid, text, uuid, text, text, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_revenue_cost_operation_started_provider_v2(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_source_kind text, p_source_operation_key text, p_source_attempt smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE; v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE; v_provider public.analysis_v2_provider_runs%ROWTYPE;
    v_entitlement public.analysis_v2_test_entitlement_consumptions%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE; v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_child public.analysis_revenue_cost_operations%ROWTYPE; v_source_hash TEXT; v_owner_hash TEXT;
    v_runner_plan TEXT; v_operation_kind TEXT; v_expected_krw INTEGER; v_now TIMESTAMPTZ;
    v_active_reserved INTEGER; v_settled_economic INTEGER; v_settled_billed INTEGER;
BEGIN
    IF p_request_id IS NULL OR p_job_claim_token IS NULL OR p_job_key IS NULL OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_job_input_hash !~ '^[a-f0-9]{64}$' OR p_source_kind IS NULL OR p_source_kind NOT IN ('provider_run','ai_attempt') OR p_source_operation_key IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF p_source_kind = 'ai_attempt' THEN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT * INTO v_preflight FROM public.analysis_preflights WHERE consumed_request_id = p_request_id FOR UPDATE;
    SELECT * INTO v_request FROM public.analysis_requests WHERE id = p_request_id FOR UPDATE;
    SELECT * INTO v_entitlement FROM public.analysis_v2_test_entitlement_consumptions WHERE request_id=p_request_id;
    SELECT * INTO v_policy FROM public.analysis_v2_provider_execution_policies WHERE request_id=p_request_id;
    SELECT runner_plan INTO v_runner_plan FROM public.load_e2e_test_runner_v1(v_request.user_id);
    IF v_preflight.id IS NULL OR v_request.id IS NULL OR v_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_entitlement.request_id IS NULL OR v_policy.request_id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2' OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot NOT IN ('basic','standard') OR v_preflight.status IS DISTINCT FROM 'consumed'
       OR v_request.status IS NULL OR v_request.status NOT IN ('pending','processing')
       OR v_preflight.access_mode IS DISTINCT FROM 'test_entitlement' OR v_preflight.admission_generation IS DISTINCT FROM 1
       OR v_preflight.admission_status IS DISTINCT FROM 'ready' OR v_preflight.admission_selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_preflight.admission_entitlement_jti_hash IS DISTINCT FROM v_request.test_entitlement_jti_hash
       OR v_preflight.user_id IS DISTINCT FROM v_request.user_id
       OR pg_catalog.lower(v_preflight.target_instagram_id) IS DISTINCT FROM pg_catalog.lower(v_request.target_instagram_id)
       OR v_entitlement.preflight_id IS DISTINCT FROM v_preflight.id OR v_entitlement.user_id IS DISTINCT FROM v_request.user_id
       OR v_entitlement.selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_entitlement.entitlement_jti_hash IS DISTINCT FROM v_request.test_entitlement_jti_hash
       OR v_policy.mode IS DISTINCT FROM 'test_operation_split' OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR v_policy.entitlement_jti_hash IS DISTINCT FROM v_entitlement.entitlement_jti_hash
       OR pg_catalog.lower(v_policy.target_instagram_id) IS DISTINCT FROM pg_catalog.lower(v_preflight.target_instagram_id)
       OR v_runner_plan IS DISTINCT FROM v_request.selected_plan_id_snapshot THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    SELECT * INTO v_job FROM public.analysis_pipeline_jobs WHERE request_id=p_request_id AND job_key=p_job_key FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF v_job.request_id IS NULL OR v_job.status IS DISTINCT FROM 'processing' OR v_job.lease_token IS DISTINCT FROM p_job_claim_token
       OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at <= v_now OR v_job.input_hash IS DISTINCT FROM p_job_input_hash THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF p_source_attempt IS DISTINCT FROM 0 THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT * INTO v_provider FROM public.analysis_v2_provider_runs WHERE request_id=p_request_id AND job_key=p_job_key AND operation_key=p_source_operation_key FOR UPDATE;
    IF v_provider.request_id IS NULL OR v_provider.status IS DISTINCT FROM 'starting'
       OR v_provider.input_hash !~ '^[a-f0-9]{64}$' OR v_provider.job_claim_token IS DISTINCT FROM p_job_claim_token THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    v_operation_kind := CASE
        WHEN p_source_operation_key ~ '^target-profile:[a-f0-9]{64}$' THEN 'target_profile'
        WHEN p_source_operation_key ~ '^(profile-fallback|profile-repair):[a-f0-9]{64}$' THEN 'detail_profile'
        WHEN p_source_operation_key ~ '^relationship-followers:[a-f0-9]{64}$' THEN 'relationship_followers'
        WHEN p_source_operation_key ~ '^relationship-following:[a-f0-9]{64}$' THEN 'relationship_following'
        WHEN p_source_operation_key ~ '^(target-likers|target-comments|candidate-likers):[a-f0-9]{64}$' THEN 'detail_interaction'
        ELSE NULL END;
    IF v_operation_kind IS NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    v_source_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_source_operation_key, 'UTF8'), 'sha256'), 'hex');
    v_owner_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to('revenue-cost/live-provider-owner/v2:' || p_request_id::TEXT || ':' || p_job_key || ':' || p_source_operation_key || ':' || v_provider.input_hash, 'UTF8'), 'sha256'), 'hex');
    v_expected_krw := public.analysis_revenue_cost_ceil_krw(v_provider.max_charge_usd);
    SELECT * INTO v_parent FROM public.analysis_revenue_run_ledgers WHERE request_id=p_request_id FOR UPDATE;
    IF v_parent.request_id IS NULL OR v_parent.preflight_id IS DISTINCT FROM v_preflight.id OR v_parent.user_id IS DISTINCT FROM v_request.user_id
       OR v_parent.plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot OR v_parent.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_parent.target_username_hmac IS DISTINCT FROM v_preflight.target_input_hash
       OR v_parent.preflight_refreshed_at IS DISTINCT FROM v_preflight.admission_refreshed_at
       OR v_parent.request_started_at IS DISTINCT FROM v_request.created_at
       OR v_parent.pricing_snapshot_version IS DISTINCT FROM 'revenue-e2e-cost-2026-08-10-v1' OR v_parent.buffered_fx_krw_per_usd IS DISTINCT FROM 1450
       OR v_parent.cost_cap_krw IS DISTINCT FROM (CASE WHEN v_request.selected_plan_id_snapshot='basic' THEN 1808 ELSE 3634 END)
       OR v_parent.margin_target_krw IS DISTINCT FROM (CASE WHEN v_request.selected_plan_id_snapshot='basic' THEN 904 ELSE 1817 END)
       OR v_parent.status IS DISTINCT FROM 'running' OR v_parent.manual_review_reason IS NOT NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT
        COALESCE(pg_catalog.sum(CASE WHEN status IN ('reserved','started') THEN reserved_krw ELSE 0 END), 0)::INTEGER,
        COALESCE(pg_catalog.sum(CASE WHEN status = 'settled' THEN economic_actual_krw ELSE 0 END), 0)::INTEGER,
        COALESCE(pg_catalog.sum(CASE WHEN status = 'settled' THEN billed_actual_krw ELSE 0 END), 0)::INTEGER
    INTO v_active_reserved, v_settled_economic, v_settled_billed
    FROM public.analysis_revenue_cost_operations WHERE request_id = p_request_id;
    IF v_parent.reserved_cost_krw IS DISTINCT FROM v_active_reserved
       OR v_parent.economic_actual_krw IS DISTINCT FROM v_settled_economic
       OR v_parent.actual_cost_krw IS DISTINCT FROM v_settled_economic
       OR v_parent.billed_actual_krw IS DISTINCT FROM v_settled_billed THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    SELECT * INTO v_child FROM public.analysis_revenue_cost_operations WHERE request_id=p_request_id AND owner_kind=p_source_kind AND source_job_key=p_job_key AND source_operation_key_hash=v_source_hash AND source_attempt=p_source_attempt FOR UPDATE;
    IF NOT FOUND OR v_child.owner_key_hash IS DISTINCT FROM v_owner_hash OR v_child.attempt IS DISTINCT FROM 1
       OR v_child.operation_kind IS DISTINCT FROM v_operation_kind OR v_child.units IS DISTINCT FROM 1
       OR v_child.selected_manifest_scope_hash IS NOT NULL OR v_child.estimated_economic_usd IS DISTINCT FROM v_provider.max_charge_usd
       OR v_child.reserved_krw IS DISTINCT FROM v_expected_krw OR v_child.denial_reason IS NOT NULL
       OR v_child.economic_actual_usd IS NOT NULL OR v_child.billed_actual_usd IS NOT NULL
       OR v_child.economic_actual_krw IS NOT NULL OR v_child.billed_actual_krw IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF v_child.status='started' AND v_child.started_at IS NOT NULL AND v_child.terminal_at IS NULL THEN RETURN pg_catalog.jsonb_build_object('disposition','started','created',FALSE,'replayed',TRUE,'operationId',v_child.id); END IF;
    IF v_child.status IS DISTINCT FROM 'reserved' OR v_child.started_at IS NOT NULL OR v_child.terminal_at IS NOT NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    UPDATE public.analysis_revenue_cost_operations SET status='started', started_at=v_now WHERE id=v_child.id;
    RETURN pg_catalog.jsonb_build_object('disposition','started','created',TRUE,'replayed',FALSE,'operationId',v_child.id);
END; $_$;


--
-- Name: mark_analysis_revenue_cost_operation_started_v1(uuid, text, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_revenue_cost_operation_started_v1(p_request_id uuid, p_owner_kind text, p_owner_key_hash text, p_attempt smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_NOT_READY'; END; $$;


--
-- Name: mark_analysis_revenue_cost_operation_started_v2(uuid, text, uuid, text, text, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_revenue_cost_operation_started_v2(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_source_kind text, p_source_operation_key text, p_source_attempt smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_ai public.analysis_v2_ai_attempts%ROWTYPE;
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_child public.analysis_revenue_cost_operations%ROWTYPE;
    v_mapping JSONB;
    v_source_hash TEXT;
    v_owner_hash TEXT;
    v_expected_usd NUMERIC;
    v_expected_krw INTEGER;
    v_now TIMESTAMPTZ;
BEGIN
    IF p_source_kind='provider_run' THEN
        RETURN public.mark_analysis_revenue_cost_operation_started_provider_v2(
            p_request_id,p_job_key,p_job_claim_token,p_job_input_hash,
            p_source_kind,p_source_operation_key,p_source_attempt
        );
    END IF;
    IF p_source_kind IS DISTINCT FROM 'ai_attempt' OR p_source_attempt NOT BETWEEN 1 AND 4 THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    PERFORM public.analysis_revenue_ai_cost_assert_lineage_v1(
        p_request_id,p_job_key,p_job_claim_token,p_job_input_hash,TRUE
    );
    SELECT * INTO v_ai FROM public.analysis_v2_ai_attempts
      WHERE request_id=p_request_id AND job_key=p_job_key
        AND operation_key=p_source_operation_key AND attempt=p_source_attempt FOR UPDATE;
    IF v_ai.request_id IS NULL OR v_ai.status IS DISTINCT FROM 'reserved'
       OR v_ai.job_claim_token IS DISTINCT FROM p_job_claim_token
       OR v_ai.retry_count IS DISTINCT FROM p_source_attempt-1 THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    v_expected_usd:=public.analysis_revenue_ai_cost_max_usd_v1(v_ai.model_name,v_ai.location,v_ai.stage,v_ai.thinking_level,v_ai.media_count,v_ai.media_resolution,v_ai.prompt_version,v_ai.schema_version,v_ai.max_output_tokens);
    v_mapping:=public.analysis_revenue_ai_cost_operation_mapping_v1(
        p_request_id,p_job_key,p_job_input_hash,(SELECT selected_plan_id_snapshot FROM public.analysis_requests WHERE id=p_request_id),p_source_operation_key,p_source_attempt,v_ai.stage
    );
    v_source_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_source_operation_key,'UTF8'),'sha256'),'hex');
    v_owner_hash:=public.analysis_revenue_ai_cost_owner_hash_v1(p_request_id,p_job_key,p_source_operation_key,p_source_attempt,v_ai.reservation_token,v_ai.model_name,v_ai.location,v_ai.stage,v_ai.thinking_level,v_ai.media_count,v_ai.media_resolution,v_ai.prompt_version,v_ai.schema_version,v_ai.max_output_tokens,v_ai.retry_count);
    v_expected_krw:=public.analysis_revenue_cost_ceil_krw(v_expected_usd);
    PERFORM public.analysis_revenue_ai_cost_assert_parent_v1(p_request_id);
    SELECT * INTO v_parent FROM public.analysis_revenue_run_ledgers WHERE request_id=p_request_id FOR UPDATE;
    PERFORM public.analysis_revenue_ai_cost_assert_aggregates_v1(p_request_id);
    SELECT * INTO v_child FROM public.analysis_revenue_cost_operations
      WHERE request_id=p_request_id AND owner_kind='ai_attempt' AND source_job_key=p_job_key
        AND source_operation_key_hash=v_source_hash AND source_attempt=p_source_attempt FOR UPDATE;
    IF v_child.id IS NULL OR v_child.owner_key_hash IS DISTINCT FROM v_owner_hash
       OR v_child.attempt IS DISTINCT FROM p_source_attempt OR v_child.operation_kind IS DISTINCT FROM (v_mapping->>'operation_kind')
       OR v_child.selected_manifest_scope_hash IS DISTINCT FROM (v_mapping->>'selected_manifest_scope_hash')
       OR v_child.units IS DISTINCT FROM 1 OR v_child.estimated_economic_usd IS DISTINCT FROM v_expected_usd
       OR v_child.reserved_krw IS DISTINCT FROM v_expected_krw OR v_child.denial_reason IS NOT NULL
       OR v_parent.status IS DISTINCT FROM 'running' OR v_parent.manual_review_reason IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF v_child.status='started' AND v_child.started_at IS NOT NULL AND v_child.terminal_at IS NULL THEN
        RETURN pg_catalog.jsonb_build_object('disposition','started','created',FALSE,'replayed',TRUE,'operationId',v_child.id);
    END IF;
    IF v_child.status IS DISTINCT FROM 'reserved' OR v_child.started_at IS NOT NULL OR v_child.terminal_at IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    v_now:=pg_catalog.clock_timestamp();
    UPDATE public.analysis_revenue_cost_operations SET status='started',started_at=v_now WHERE id=v_child.id;
    RETURN pg_catalog.jsonb_build_object('disposition','started','created',TRUE,'replayed',FALSE,'operationId',v_child.id);
END;
$$;


--
-- Name: mark_analysis_revenue_manual_review_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_revenue_manual_review_v1(p_request_id uuid, p_reason_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF p_reason_code IS NULL OR p_reason_code NOT IN ('routing_failure', 'ambiguous_external_call', 'cost_overrun') THEN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_MANUAL_REVIEW_INVALID'; END IF;
    -- Review causes are monotonic: cost_overrun > cost_denied >
    -- ambiguous_external_call > routing_failure.  This RPC can introduce the
    -- three non-denial reasons but must never erase stronger cost evidence.
    UPDATE public.analysis_revenue_run_ledgers
       SET status = 'manual_review', manual_review_reason = CASE
           WHEN manual_review_reason = 'cost_overrun' THEN 'cost_overrun'
           WHEN p_reason_code = 'cost_overrun' THEN 'cost_overrun'
           WHEN manual_review_reason = 'cost_denied' THEN 'cost_denied'
           WHEN manual_review_reason = 'ambiguous_external_call' THEN 'ambiguous_external_call'
           ELSE p_reason_code
       END
     WHERE request_id = p_request_id;
    IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE'; END IF;
    RETURN pg_catalog.jsonb_build_object('disposition', 'manual_review', 'created', FALSE, 'replayed', FALSE);
END; $$;


--
-- Name: mark_analysis_v2_fresh_admission_profile_run_reusable_v1(uuid, integer, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_v2_fresh_admission_profile_run_reusable_v1(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid, p_input_hash text, p_run_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_operation_key TEXT;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_claim_token IS NULL
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REUSABLE_TARGET_PROFILE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    v_operation_key :=
        'target-profile-fresh-admission:g' || p_admission_generation::TEXT;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.status IS DISTINCT FROM 'ready'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.expires_at <= v_now
       OR v_preflight.admission_generation IS DISTINCT FROM p_admission_generation
       OR v_preflight.admission_status IS DISTINCT FROM 'processing'
       OR v_preflight.admission_claim_token IS DISTINCT FROM p_claim_token
       OR v_preflight.admission_lease_expires_at IS NULL
       OR v_preflight.admission_lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REUSABLE_TARGET_PROFILE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = v_operation_key
    FOR UPDATE;
    IF NOT FOUND
       OR v_run.input_hash IS DISTINCT FROM p_input_hash
       OR v_run.logical_provider IS DISTINCT FROM 'apify'
       OR v_run.actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper'
       OR NOT public.analysis_v2_valid_apify_credential_slot(v_run.credential_slot)
       OR v_run.max_charge_usd IS DISTINCT FROM 0.002600000000
       OR v_run.status IS DISTINCT FROM 'succeeded'
       OR v_run.run_id IS DISTINCT FROM p_run_id
       OR v_run.terminalized_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REUSABLE_TARGET_PROFILE_RUN_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.reusable_profile_schema_version = 1 THEN
        RETURN FALSE;
    END IF;

    UPDATE public.analysis_preflight_provider_runs AS provider_run
    SET reusable_profile_schema_version = 1,
        updated_at = v_now
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = v_operation_key;
    RETURN TRUE;
END;
$_$;


--
-- Name: mark_analysis_v2_job_dispatched(uuid, text, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_v2_job_dispatched(p_request_id uuid, p_job_key text, p_dispatch_generation integer, p_dispatch_token uuid, p_task_name text) RETURNS TABLE(marked boolean, job_status text, dispatch_state text, task_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    PERFORM public.assert_analysis_revenue_dispatch_guard_v1(p_request_id, p_job_key);
    RETURN QUERY
    SELECT * FROM public.mark_analysis_v2_job_dispatched_unfenced_20260811(
        p_request_id, p_job_key, p_dispatch_generation, p_dispatch_token, p_task_name
    );
END;
$$;


--
-- Name: mark_analysis_v2_job_dispatched_unfenced_20260811(uuid, text, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_v2_job_dispatched_unfenced_20260811(p_request_id uuid, p_job_key text, p_dispatch_generation integer, p_dispatch_token uuid, p_task_name text) RETURNS TABLE(marked boolean, job_status text, dispatch_state text, task_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_dispatch_token IS NULL
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 1000
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_task_name IS NULL
       OR pg_catalog.char_length(p_task_name) NOT BETWEEN 1 AND 512
       OR p_task_name !~ '^[A-Za-z0-9][A-Za-z0-9._:/=-]*$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_INVALID_JOB_DISPATCH_INPUT',
            ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    IF v_job.dispatch_state IN ('enqueued', 'delivered') THEN
        IF v_job.dispatch_generation = p_dispatch_generation
           AND v_job.dispatch_reservation_token = p_dispatch_token
           AND v_job.dispatch_task_name = p_task_name THEN
            RETURN QUERY SELECT
                TRUE,
                v_job.status::TEXT,
                v_job.dispatch_state::TEXT,
                v_job.dispatch_task_name::TEXT;
            RETURN;
        END IF;
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_DISPATCH_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    IF v_request.status NOT IN ('pending', 'processing')
       OR v_job.status <> 'pending'
       OR v_job.dispatch_state <> 'reserved'
       OR v_job.dispatch_generation <> p_dispatch_generation
       OR v_job.dispatch_reservation_token <> p_dispatch_token THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_DISPATCH_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_pipeline_jobs AS job
    SET dispatch_state = 'enqueued',
        dispatched_at = v_now,
        dispatch_task_name = p_task_name,
        updated_at = v_now
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    RETURNING job.* INTO v_job;

    UPDATE public.analysis_requests AS analysis_request
    SET status = 'processing',
        background_processing = TRUE,
        progress_step = 'V2 analysis queued',
        current_step = 'v2_pipeline'
    WHERE analysis_request.id = p_request_id
      AND analysis_request.status IN ('pending', 'processing');

    RETURN QUERY SELECT
        TRUE,
        v_job.status::TEXT,
        v_job.dispatch_state::TEXT,
        v_job.dispatch_task_name::TEXT;
END;
$_$;


--
-- Name: mark_analysis_v2_job_dispatched_v2(uuid, text, integer, uuid, text, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_v2_job_dispatched_v2(p_request_id uuid, p_job_key text, p_dispatch_generation integer, p_dispatch_token uuid, p_task_name text, p_workload_role text, p_contract_version smallint) RETURNS TABLE(marked boolean, job_status text, dispatch_state text, task_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_result RECORD;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'paid' OR p_contract_version IS DISTINCT FROM 2 THEN
        RETURN QUERY SELECT FALSE, NULL::TEXT, NULL::TEXT, NULL::TEXT; RETURN;
    END IF;
    SELECT job.* INTO v_job FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    IF NOT FOUND
       OR v_job.dispatch_workload_role IS DISTINCT FROM 'paid'
       OR v_job.dispatch_contract_version IS DISTINCT FROM 2 THEN
        RETURN QUERY SELECT FALSE, NULL::TEXT, NULL::TEXT, NULL::TEXT; RETURN;
    END IF;
    IF v_job.dispatch_state IN ('enqueued', 'delivered')
       AND v_job.dispatch_generation = p_dispatch_generation
       AND v_job.dispatch_reservation_token = p_dispatch_token
       AND v_job.dispatch_task_name = p_task_name THEN
        RETURN QUERY SELECT TRUE, v_job.status::TEXT, v_job.dispatch_state::TEXT,
            v_job.dispatch_task_name::TEXT; RETURN;
    END IF;
    SELECT marked.* INTO v_result FROM public.mark_analysis_v2_job_dispatched(
        p_request_id, p_job_key, p_dispatch_generation, p_dispatch_token, p_task_name
    ) AS marked;
    RETURN QUERY SELECT v_result.marked, v_result.job_status,
        v_result.dispatch_state, v_result.task_name;
END;
$$;


--
-- Name: mark_analysis_v2_preflight_admission_dispatched(uuid, uuid, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_v2_preflight_admission_dispatched(p_preflight_id uuid, p_user_id uuid, p_admission_generation integer, p_dispatch_generation integer, p_dispatch_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_FRESH_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.admission_generation <> p_admission_generation
       OR v_preflight.admission_dispatch_generation <> p_dispatch_generation
       OR v_preflight.admission_dispatch_token IS DISTINCT FROM p_dispatch_token THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_FRESH_ADMISSION_DISPATCH_LOST', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.admission_dispatch_state = 'enqueued' THEN
        RETURN FALSE;
    END IF;
    IF v_preflight.admission_dispatch_state <> 'reserved' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_FRESH_ADMISSION_DISPATCH_LOST', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET admission_dispatch_state = 'enqueued',
        admission_dispatched_at = v_now,
        updated_at = v_now
    WHERE preflight.id = v_preflight.id;
    RETURN TRUE;
END;
$$;


--
-- Name: mark_analysis_v2_preflight_admission_dispatched_v2(uuid, uuid, integer, integer, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_v2_preflight_admission_dispatched_v2(p_preflight_id uuid, p_user_id uuid, p_admission_generation integer, p_dispatch_generation integer, p_dispatch_token uuid, p_workload_role text, p_contract_version smallint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_marked BOOLEAN;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'paid' OR p_contract_version IS DISTINCT FROM 2 THEN
        RETURN FALSE;
    END IF;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id AND preflight.user_id = p_user_id FOR UPDATE;
    IF NOT FOUND THEN RETURN FALSE; END IF;
    IF v_preflight.admission_dispatch_state = 'enqueued'
       AND v_preflight.admission_generation = p_admission_generation
       AND v_preflight.admission_dispatch_generation = p_dispatch_generation
       AND v_preflight.admission_dispatch_token IS NOT DISTINCT FROM p_dispatch_token
       AND v_preflight.admission_dispatch_workload_role = 'paid'
       AND v_preflight.admission_dispatch_contract_version = 2 THEN
        RETURN TRUE;
    END IF;
    IF v_preflight.admission_dispatch_workload_role IS DISTINCT FROM 'paid'
       OR v_preflight.admission_dispatch_contract_version IS DISTINCT FROM 2
       OR v_preflight.admission_dispatch_state IS DISTINCT FROM 'reserved' THEN
        RETURN FALSE;
    END IF;
    v_marked := public.mark_analysis_v2_preflight_admission_dispatched(
        p_preflight_id, p_user_id, p_admission_generation,
        p_dispatch_generation, p_dispatch_token
    );
    RETURN v_marked;
END;
$$;


--
-- Name: mark_analysis_v2_preflight_admission_rearmed_dispatch_v2(uuid, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_v2_preflight_admission_rearmed_dispatch_v2(p_preflight_id uuid, p_admission_generation integer, p_dispatch_generation integer, p_dispatch_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_token IS NULL THEN
        RETURN FALSE;
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    -- Fresh-admission replay is fenced exclusively by the fresh admission columns.
    -- Do not inspect ordinary preflight status/dispatch fields here: the two domains can
    -- legitimately have different values during a mixed-version rollout.
    IF v_preflight.admission_status = 'pending'
       AND v_preflight.admission_dispatch_workload_role = 'paid'
       AND v_preflight.admission_dispatch_contract_version = 2
       AND v_preflight.admission_generation = p_admission_generation
       AND v_preflight.admission_dispatch_state = 'enqueued'
       AND v_preflight.admission_dispatch_generation = p_dispatch_generation
       AND v_preflight.admission_dispatch_token IS NOT DISTINCT FROM p_dispatch_token THEN
        RETURN TRUE;
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET admission_dispatch_state = 'enqueued',
        admission_dispatched_at = v_now,
        updated_at = v_now
    WHERE preflight.id = p_preflight_id
      AND preflight.admission_status = 'pending'
      AND preflight.admission_dispatch_workload_role = 'paid'
      AND preflight.admission_dispatch_contract_version = 2
      AND preflight.admission_generation = p_admission_generation
      AND preflight.admission_dispatch_state = 'reserved'
      AND preflight.admission_dispatch_generation = p_dispatch_generation
      AND preflight.admission_dispatch_token = p_dispatch_token;
    RETURN FOUND;
END;
$$;


--
-- Name: mark_analysis_v2_preflight_dispatched(uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_v2_preflight_dispatched(p_preflight_id uuid, p_user_id uuid, p_dispatch_generation integer, p_dispatch_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation < 1
       OR p_dispatch_generation > 100
       OR p_dispatch_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_DISPATCH_INPUT', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    IF v_preflight.dispatch_state = 'enqueued'
       AND v_preflight.dispatch_generation = p_dispatch_generation THEN
        RETURN FALSE;
    END IF;
    IF v_preflight.dispatch_state <> 'reserved'
       OR v_preflight.dispatch_generation <> p_dispatch_generation
       OR v_preflight.dispatch_token IS DISTINCT FROM p_dispatch_token THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DISPATCH_RESERVATION_LOST', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights
    SET dispatch_state = 'enqueued',
        dispatch_token = NULL,
        dispatched_at = v_now,
        updated_at = v_now
    WHERE id = v_preflight.id;
    RETURN TRUE;
END;
$$;


--
-- Name: mark_analysis_v2_preflight_dispatched_v2(uuid, uuid, integer, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_v2_preflight_dispatched_v2(p_preflight_id uuid, p_user_id uuid, p_dispatch_generation integer, p_dispatch_token uuid, p_workload_role text, p_contract_version smallint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    IF p_workload_role IS DISTINCT FROM 'preflight' OR p_contract_version IS DISTINCT FROM 2 THEN
        RETURN FALSE;
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id AND preflight.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN RETURN FALSE; END IF;
    IF v_preflight.dispatch_state = 'enqueued'
       AND v_preflight.dispatch_generation = p_dispatch_generation
       AND v_preflight.last_dispatch_token IS NOT DISTINCT FROM p_dispatch_token
       AND v_preflight.dispatch_workload_role = 'preflight'
       AND v_preflight.dispatch_contract_version = 2 THEN
        RETURN TRUE;
    END IF;
    IF v_preflight.dispatch_workload_role IS DISTINCT FROM 'preflight'
       OR v_preflight.dispatch_contract_version IS DISTINCT FROM 2
       OR v_preflight.dispatch_state IS DISTINCT FROM 'reserved' THEN
        RETURN FALSE;
    END IF;
    -- Do not delegate to the legacy mark RPC: it predates last_dispatch_token and
    -- clears dispatch_token without preserving the successor fence.  This single
    -- CAS is the only ordinary v2 mark transition and is replay-safe by the exact
    -- generation/token pair above.
    UPDATE public.analysis_preflights AS preflight
    SET dispatch_state = 'enqueued',
        dispatch_token = NULL,
        last_dispatch_token = p_dispatch_token,
        dispatched_at = v_now,
        updated_at = v_now
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
      AND preflight.status = 'pending'
      AND preflight.dispatch_state = 'reserved'
      AND preflight.dispatch_generation = p_dispatch_generation
      AND preflight.dispatch_token = p_dispatch_token
      AND preflight.dispatch_workload_role = 'preflight'
      AND preflight.dispatch_contract_version = 2;
    RETURN FOUND;
END;
$$;


--
-- Name: mark_analysis_v2_profile_provider_canary_run_ambiguous(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_v2_profile_provider_canary_run_ambiguous(p_source_request_id uuid, p_repetition integer, p_reservation_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_run public.analysis_v2_profile_provider_canary_runs%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL OR p_repetition NOT IN (1, 2)
       OR p_reservation_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT canary_run.* INTO v_run
    FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.repetition = p_repetition
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_run.reservation_token IS DISTINCT FROM p_reservation_token THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_run.state = 'starting' THEN
        UPDATE public.analysis_v2_profile_provider_canary_runs AS canary_run
        SET state = 'ambiguous', cost_status = 'unknown', ambiguous_at = v_now, updated_at = v_now
        WHERE canary_run.source_request_id = p_source_request_id
          AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
          AND canary_run.repetition = p_repetition
        RETURNING canary_run.* INTO v_run;
    ELSIF v_run.state <> 'ambiguous' THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    RETURN public.analysis_v2_profile_provider_canary_run_json(v_run);
END;
$$;


--
-- Name: mark_analysis_v2_profile_provider_canary_run_storage_clean(uuid, integer, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_v2_profile_provider_canary_run_storage_clean(p_source_request_id uuid, p_repetition integer, p_reservation_token uuid, p_run_id text, p_storage text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_experiment public.analysis_v2_profile_provider_canary_experiments%ROWTYPE;
    v_run public.analysis_v2_profile_provider_canary_runs%ROWTYPE;
    v_gate BOOLEAN;
BEGIN
    IF p_source_request_id IS NULL OR p_repetition NOT IN (1, 2)
       OR p_reservation_token IS NULL OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_storage NOT IN ('kvs', 'dataset', 'request_queue') THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT experiment.* INTO v_experiment
    FROM public.analysis_v2_profile_provider_canary_experiments AS experiment
    WHERE experiment.source_request_id = p_source_request_id
      AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    SELECT canary_run.* INTO v_run
    FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.repetition = p_repetition
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_run.reservation_token IS DISTINCT FROM p_reservation_token
       OR v_run.run_id IS DISTINCT FROM p_run_id THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_run.state NOT IN ('succeeded', 'failed')
       OR v_run.cost_status IS DISTINCT FROM 'actual'
       OR v_run.usage_reconciled_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_v2_profile_provider_canary_runs AS canary_run
    SET kvs_cleanup_state = CASE WHEN p_storage = 'kvs' THEN 'verified_absent'
            ELSE canary_run.kvs_cleanup_state END,
        kvs_cleaned_at = CASE WHEN p_storage = 'kvs' THEN COALESCE(canary_run.kvs_cleaned_at, v_now)
            ELSE canary_run.kvs_cleaned_at END,
        dataset_cleanup_state = CASE WHEN p_storage = 'dataset' THEN 'verified_absent'
            ELSE canary_run.dataset_cleanup_state END,
        dataset_cleaned_at = CASE WHEN p_storage = 'dataset' THEN COALESCE(canary_run.dataset_cleaned_at, v_now)
            ELSE canary_run.dataset_cleaned_at END,
        request_queue_cleanup_state = CASE WHEN p_storage = 'request_queue' THEN 'verified_absent'
            ELSE canary_run.request_queue_cleanup_state END,
        request_queue_cleaned_at = CASE WHEN p_storage = 'request_queue'
            THEN COALESCE(canary_run.request_queue_cleaned_at, v_now)
            ELSE canary_run.request_queue_cleaned_at END,
        updated_at = v_now
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.repetition = p_repetition
    RETURNING canary_run.* INTO v_run;

    IF v_run.kvs_cleanup_state = 'verified_absent'
       AND v_run.dataset_cleanup_state = 'verified_absent'
       AND v_run.request_queue_cleanup_state = 'verified_absent' THEN
        v_gate := v_run.state = 'succeeded'
            AND v_run.success_count = 15
            AND v_run.unavailable_count = 0
            AND v_run.incomplete_count = 0
            AND v_run.other_failure_count = 0
            AND v_run.critical_success_count = 3
            AND v_run.latency_ms <= 60000
            AND v_run.build_verified
            AND v_run.restricted_access_verified
            AND v_run.actual_usage_usd <= 0.050000000000;
        UPDATE public.analysis_v2_profile_provider_canary_runs AS canary_run
        SET gate_passed = v_gate, cleanup_completed_at = COALESCE(cleanup_completed_at, v_now),
            updated_at = v_now
        WHERE canary_run.source_request_id = p_source_request_id
          AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
          AND canary_run.repetition = p_repetition
        RETURNING canary_run.* INTO v_run;

        IF p_repetition = 1 AND v_gate THEN
            UPDATE public.analysis_v2_profile_provider_canary_experiments AS experiment
            SET state = 'awaiting_repetition_2',
                rep2_approval_deadline_at = v_run.terminalized_at + INTERVAL '1 hour',
                updated_at = v_now
            WHERE experiment.source_request_id = p_source_request_id
              AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
              AND experiment.state = 'active';
        END IF;
    END IF;
    RETURN public.analysis_v2_profile_provider_canary_run_json(v_run);
END;
$_$;


--
-- Name: mark_analysis_v2_profile_provider_canary_source_storage_clean(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_v2_profile_provider_canary_source_storage_clean(p_source_request_id uuid, p_cleanup_claim_token uuid, p_storage text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_experiment public.analysis_v2_profile_provider_canary_experiments%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL OR p_cleanup_claim_token IS NULL
       OR p_storage NOT IN ('kvs', 'dataset', 'request_queue') THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT experiment.* INTO v_experiment
    FROM public.analysis_v2_profile_provider_canary_experiments AS experiment
    WHERE experiment.source_request_id = p_source_request_id
      AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
    FOR UPDATE;
    IF NOT FOUND OR v_experiment.state IS DISTINCT FROM 'terminalizing'
       OR v_experiment.cleanup_claim_token IS DISTINCT FROM p_cleanup_claim_token THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_CLEANUP_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_v2_profile_provider_canary_experiments AS experiment
    SET source_kvs_cleanup_state = CASE WHEN p_storage = 'kvs' THEN 'verified_absent'
            ELSE experiment.source_kvs_cleanup_state END,
        source_kvs_cleaned_at = CASE WHEN p_storage = 'kvs'
            THEN COALESCE(experiment.source_kvs_cleaned_at, v_now)
            ELSE experiment.source_kvs_cleaned_at END,
        source_dataset_cleanup_state = CASE WHEN p_storage = 'dataset' THEN 'verified_absent'
            ELSE experiment.source_dataset_cleanup_state END,
        source_dataset_cleaned_at = CASE WHEN p_storage = 'dataset'
            THEN COALESCE(experiment.source_dataset_cleaned_at, v_now)
            ELSE experiment.source_dataset_cleaned_at END,
        source_request_queue_cleanup_state = CASE WHEN p_storage = 'request_queue'
            THEN 'verified_absent' ELSE experiment.source_request_queue_cleanup_state END,
        source_request_queue_cleaned_at = CASE WHEN p_storage = 'request_queue'
            THEN COALESCE(experiment.source_request_queue_cleaned_at, v_now)
            ELSE experiment.source_request_queue_cleaned_at END,
        updated_at = v_now
    WHERE experiment.source_request_id = p_source_request_id
      AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
    RETURNING experiment.* INTO v_experiment;
    RETURN public.analysis_v2_profile_provider_canary_experiment_json(v_experiment);
END;
$$;


--
-- Name: mark_analysis_v2_profile_repair_canary_run_ambiguous(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_analysis_v2_profile_repair_canary_run_ambiguous(p_source_request_id uuid, p_repetition integer, p_reservation_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_run public.analysis_v2_profile_repair_canary_runs%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL
       OR p_repetition NOT IN (1, 2)
       OR p_reservation_token IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;
    SELECT canary_run.* INTO v_run
    FROM public.analysis_v2_profile_repair_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-repair-canary-v1'
      AND canary_run.repetition = p_repetition
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.reservation_token IS DISTINCT FROM p_reservation_token THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.state = 'starting' THEN
        UPDATE public.analysis_v2_profile_repair_canary_runs AS canary_run
        SET state = 'ambiguous',
            cost_status = 'unknown',
            ambiguous_at = v_now,
            terminalized_at = v_now,
            updated_at = v_now
        WHERE canary_run.source_request_id = p_source_request_id
          AND canary_run.canary_version = 'profile-repair-canary-v1'
          AND canary_run.repetition = p_repetition
        RETURNING canary_run.* INTO v_run;
    ELSIF v_run.state <> 'ambiguous' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_STATE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    RETURN public.analysis_v2_profile_repair_canary_run_json(v_run);
END;
$$;


--
-- Name: mark_anonymous_analysis_v2_preflight_dispatched(uuid, character varying, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_anonymous_analysis_v2_preflight_dispatched(p_preflight_id uuid, p_claim_token_hash character varying, p_dispatch_generation integer, p_dispatch_token uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
BEGIN
    IF p_preflight_id IS NULL
       OR p_claim_token_hash !~ '^[0-9a-f]{64}$'
       OR p_dispatch_token IS NULL THEN
        RETURN FALSE;
    END IF;
    PERFORM pg_catalog.set_config(
        'app.anonymous_preflight_claim_hash', p_claim_token_hash, TRUE
    );
    UPDATE public.analysis_preflights
    SET dispatch_state = 'enqueued',
        dispatch_token = NULL,
        dispatched_at = COALESCE(dispatched_at, pg_catalog.clock_timestamp()),
        updated_at = pg_catalog.clock_timestamp()
    WHERE id = p_preflight_id
      AND user_id IS NULL
      AND claim_token_hash = p_claim_token_hash
      AND dispatch_generation = p_dispatch_generation
      AND dispatch_token = p_dispatch_token
      AND dispatch_state = 'reserved'
    ;
    RETURN FOUND;
END;
$_$;


--
-- Name: mark_anonymous_analysis_v2_preflight_dispatched_v2(uuid, character varying, integer, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_anonymous_analysis_v2_preflight_dispatched_v2(p_preflight_id uuid, p_claim_token_hash character varying, p_dispatch_generation integer, p_dispatch_token uuid, p_workload_role text, p_contract_version smallint) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    IF p_preflight_id IS NULL
       OR p_claim_token_hash IS NULL
       OR p_claim_token_hash !~ '^[0-9a-f]{64}$'
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_token IS NULL
       OR p_workload_role IS DISTINCT FROM 'preflight'
       OR p_contract_version IS DISTINCT FROM 2 THEN
        RETURN FALSE;
    END IF;
    PERFORM pg_catalog.set_config(
        'app.anonymous_preflight_claim_hash', p_claim_token_hash, TRUE
    );
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id IS NULL
      AND preflight.claim_token_hash = p_claim_token_hash
    FOR UPDATE;
    IF NOT FOUND THEN RETURN FALSE; END IF;
    IF v_preflight.dispatch_state = 'enqueued'
       AND v_preflight.dispatch_generation = p_dispatch_generation
       AND v_preflight.last_dispatch_token IS NOT DISTINCT FROM p_dispatch_token
       AND v_preflight.dispatch_workload_role IS NOT DISTINCT FROM 'preflight'
       AND v_preflight.dispatch_contract_version IS NOT DISTINCT FROM 2 THEN
        RETURN TRUE;
    END IF;
    IF v_preflight.dispatch_workload_role IS DISTINCT FROM 'preflight'
       OR v_preflight.dispatch_contract_version IS DISTINCT FROM 2
       OR v_preflight.dispatch_state IS DISTINCT FROM 'reserved' THEN
        RETURN FALSE;
    END IF;
    UPDATE public.analysis_preflights AS preflight
    SET dispatch_state = 'enqueued',
        dispatch_token = NULL,
        last_dispatch_token = p_dispatch_token,
        dispatched_at = COALESCE(preflight.dispatched_at, v_now),
        updated_at = v_now
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id IS NULL
      AND preflight.claim_token_hash = p_claim_token_hash
      AND preflight.dispatch_state = 'reserved'
      AND preflight.dispatch_generation = p_dispatch_generation
      AND preflight.dispatch_token = p_dispatch_token
      AND preflight.dispatch_workload_role = 'preflight'
      AND preflight.dispatch_contract_version = 2;
    RETURN FOUND;
END;
$_$;


--
-- Name: mark_earlybird_concierge_snapshot_recovery_job_local(uuid, uuid, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_earlybird_concierge_snapshot_recovery_job_local(p_order_id uuid, p_request_id uuid, p_job_key text, p_dispatch_generation integer, p_dispatch_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_payment_id_hint TEXT;
    v_task_name TEXT;
    v_recovery RECORD;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
BEGIN
    IF p_order_id IS NULL
       OR p_request_id IS NULL
       OR p_dispatch_token IS NULL
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 1000
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_LOCAL_JOB_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.payment_id INTO v_payment_id_hint
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    IF NOT FOUND OR v_payment_id_hint IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_LOCAL_JOB_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(v_payment_id_hint, 0)
    );

    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id
    FOR UPDATE;
    SELECT recovery.* INTO v_recovery
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, preflight_id UUID, provider_operation_key TEXT, provider_input_hash VARCHAR(64), provider_run_id_hash VARCHAR(32), expected_manual_review_at TIMESTAMPTZ, expected_admission_refreshed_at TIMESTAMPTZ, old_order_followers_count INTEGER, old_order_following_count INTEGER, old_preflight_followers_count INTEGER, old_preflight_following_count INTEGER, new_witness_followers_count INTEGER, new_witness_following_count INTEGER, old_snapshot_recorded_at TIMESTAMPTZ, new_witness_recorded_at TIMESTAMPTZ, recovery_reason TEXT, followers_absolute_delta INTEGER, following_absolute_delta INTEGER, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_concierge_snapshot_conflict_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','preflight_id','provider_operation_key','provider_input_hash','provider_run_id_hash','expected_manual_review_at','expected_admission_refreshed_at','old_order_followers_count','old_order_following_count','old_preflight_followers_count','old_preflight_following_count','new_witness_followers_count','new_witness_following_count','old_snapshot_recorded_at','new_witness_recorded_at','recovery_reason','followers_absolute_delta','following_absolute_delta','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.preflight_id IS NOT NULL AND decoded.provider_operation_key IS NOT NULL AND decoded.provider_input_hash IS NOT NULL AND decoded.provider_run_id_hash IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.expected_admission_refreshed_at IS NOT NULL AND decoded.old_order_followers_count IS NOT NULL AND decoded.old_order_following_count IS NOT NULL AND decoded.old_preflight_followers_count IS NOT NULL AND decoded.old_preflight_following_count IS NOT NULL AND decoded.new_witness_followers_count IS NOT NULL AND decoded.new_witness_following_count IS NOT NULL AND decoded.old_snapshot_recorded_at IS NOT NULL AND decoded.new_witness_recorded_at IS NOT NULL AND decoded.recovery_reason IS NOT NULL AND decoded.followers_absolute_delta IS NOT NULL AND decoded.following_absolute_delta IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
    WHERE recovery.order_id = p_order_id
      AND recovery.preflight_id = v_preflight.id
    FOR UPDATE;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;

    IF v_fulfillment.order_id IS NULL
       OR v_order.id IS NULL
       OR v_preflight.id IS NULL
       OR v_recovery.order_id IS NULL
       OR v_request.id IS NULL
       OR v_job.request_id IS NULL
       OR v_order.payment_id IS DISTINCT FROM v_payment_id_hint
       OR v_order.status IS DISTINCT FROM 'analysis_in_progress'
       OR v_order.result_request_id IS DISTINCT FROM p_request_id
       OR v_order.preflight_id IS DISTINCT FROM v_recovery.preflight_id
       OR v_fulfillment.status IS DISTINCT FROM 'analysis_in_progress'
       OR v_fulfillment.request_id IS DISTINCT FROM p_request_id
       OR v_preflight.consumed_request_id IS DISTINCT FROM p_request_id
       OR v_request.user_id IS DISTINCT FROM v_order.user_id
       OR v_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR NOT public.earlybird_concierge_snapshot_conflict_receipt_authorized(
            v_order.id,
            v_preflight.id,
            v_order.target_followers_count,
            v_order.target_following_count,
            v_preflight.target_followers_count,
            v_preflight.target_following_count,
            v_preflight.admission_target_followers_count,
            v_preflight.admission_target_following_count,
            v_preflight.admission_generation,
            v_preflight.admission_refreshed_at
       )
       OR EXISTS (
            SELECT 1
            FROM public.earlybird_webhook_events AS refund_event
            WHERE refund_event.payment_id = v_order.payment_id
              AND refund_event.event_type = 'payment.refunded'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_LOCAL_JOB_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    v_task_name := 'manual-local/concierge-snapshot-conflict/'
        || pg_catalog.md5(p_request_id::TEXT || pg_catalog.chr(10) || p_job_key)
        || '/g' || p_dispatch_generation::TEXT;
    IF v_job.status = 'pending'
       AND v_job.dispatch_state = 'reserved'
       AND v_job.dispatch_generation = p_dispatch_generation
       AND v_job.dispatch_reservation_token = p_dispatch_token THEN
        UPDATE public.analysis_pipeline_jobs AS job
        SET dispatch_state = 'enqueued',
            dispatched_at = v_now,
            dispatch_task_name = v_task_name,
            updated_at = v_now
        WHERE job.request_id = p_request_id
          AND job.job_key = p_job_key;
        RETURN TRUE;
    END IF;
    IF v_job.status IN ('pending', 'processing')
       AND v_job.dispatch_state IN ('enqueued', 'delivered')
       AND v_job.dispatch_generation = p_dispatch_generation
       AND v_job.dispatch_reservation_token = p_dispatch_token
       AND v_job.dispatch_task_name = v_task_name THEN
        RETURN FALSE;
    END IF;
    RAISE EXCEPTION USING
        MESSAGE = 'CONCIERGE_SNAPSHOT_LOCAL_JOB_CAS_MISMATCH',
        ERRCODE = 'P0001';
END;
$_$;


--
-- Name: mark_earlybird_fulfillment_manual_review(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_earlybird_fulfillment_manual_review(p_order_id uuid, p_error_code text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_status TEXT;
BEGIN
    IF p_order_id IS NULL
       OR p_error_code IS NULL
       OR p_error_code NOT IN (
            'TARGET_UNAVAILABLE',
            'PLAN_NOT_ALLOWED',
            'PAYMENT_STATE',
            'SNAPSHOT_CONFLICT',
            'REQUEST_CONFLICT',
            'ACTIVE_REQUEST_CONFLICT',
            'ATTEMPT_EXHAUSTED'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.earlybird_fulfillments AS fulfillment
    SET status = 'manual_review',
        lease_token = NULL,
        lease_expires_at = NULL,
        last_error_code = p_error_code,
        last_error_at = v_now,
        manual_review_at = v_now,
        updated_at = v_now
    WHERE fulfillment.order_id = p_order_id
      AND fulfillment.operator_admitted_at IS NOT NULL
      AND fulfillment.request_id IS NULL
      AND fulfillment.status IN ('admission_pending', 'retryable_failure')
    RETURNING fulfillment.status INTO v_status;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_STATE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    RETURN v_status;
END;
$$;


--
-- Name: mark_earlybird_v211_concierge_publication_source(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_earlybird_v211_concierge_publication_source(p_order_id uuid, p_source_fingerprint text, p_result_hash text, p_published_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE
    v_id UUID;
    v_payload JSONB;
    v_row JSONB;
    v_next_payload JSONB;
BEGIN
    PERFORM public.assert_earlybird_receipt_archive_purge_safe();
    SELECT job.id, job.payload INTO v_id, v_payload
    FROM public.maintenance_jobs AS job
    WHERE job.kind = 'replay'
      AND job.state = 'succeeded'
      AND job.payload->>'legacy_source_table' = 'earlybird_v211_concierge_replays'
      AND job.payload->'legacy_primary_key'->>'order_id' = p_order_id::TEXT
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_SOURCE_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    v_row := v_payload->'legacy_row';
    IF v_row->>'published_source_fingerprint' IS NOT NULL
       OR v_row->>'published_result_hash' IS NOT NULL
       OR v_row->>'published_at' IS NOT NULL THEN
        IF v_row->>'published_source_fingerprint' = p_source_fingerprint
           AND v_row->>'published_result_hash' = p_result_hash THEN
            RETURN FALSE;
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_SOURCE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_row->>'reviewed_source_fingerprint' IS DISTINCT FROM p_source_fingerprint
       OR p_source_fingerprint IS NULL OR p_source_fingerprint !~ '^[a-f0-9]{64}$'
       OR p_result_hash IS NULL OR p_result_hash !~ '^[a-f0-9]{64}$'
       OR p_published_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_SOURCE_INVALID', ERRCODE = 'P0001';
    END IF;
    v_next_payload := pg_catalog.jsonb_set(
        v_payload, '{legacy_row}',
        v_row || pg_catalog.jsonb_build_object(
            'published_source_fingerprint', p_source_fingerprint,
            'published_result_hash', p_result_hash,
            'published_at', p_published_at
        )
    );
    UPDATE public.maintenance_jobs
    SET payload = v_next_payload,
        content_hash = pg_catalog.encode(
            extensions.digest(convert_to(v_next_payload::TEXT, 'UTF8'), 'sha256'), 'hex'
        ),
        updated_at = pg_catalog.clock_timestamp()
    WHERE id = v_id;
    RETURN TRUE;
END;
$_$;


--
-- Name: mark_precheckout_blite_dispatch_enqueued_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_precheckout_blite_dispatch_enqueued_v1(p_preflight_id uuid, p_dispatch_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    UPDATE public.precheckout_blite_dispatches
    SET state = 'enqueued',
        dispatch_token = NULL,
        lease_expires_at = NULL,
        last_dispatch_token = p_dispatch_token,
        failure_reason = NULL,
        updated_at = v_now
    WHERE preflight_id = p_preflight_id
      AND (
        (state = 'enqueuing' AND dispatch_token = p_dispatch_token)
        OR (state = 'enqueued' AND last_dispatch_token = p_dispatch_token)
      );
    RETURN FOUND;
END;
$$;


--
-- Name: mark_precheckout_blite_dispatch_failed_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_precheckout_blite_dispatch_failed_v1(p_preflight_id uuid, p_dispatch_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    UPDATE public.precheckout_blite_dispatches
    SET state = 'idle', dispatch_token = NULL, lease_expires_at = NULL,
        last_dispatch_token = NULL, failure_reason = 'dispatch_failed', updated_at = v_now
    WHERE preflight_id = p_preflight_id
      AND state = 'enqueuing'
      AND dispatch_token = p_dispatch_token;
    RETURN FOUND;
END;
$$;


--
-- Name: mark_precheckout_blite_dispatch_v2(uuid, integer, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_precheckout_blite_dispatch_v2(p_preflight_id uuid, p_dispatch_generation integer, p_dispatch_token uuid, p_workload_role text, p_contract_version smallint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_dispatch public.precheckout_blite_dispatches%ROWTYPE;
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    IF p_workload_role IS DISTINCT FROM 'preflight'
       OR p_contract_version IS DISTINCT FROM 2
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_token IS NULL THEN
        RETURN FALSE;
    END IF;
    SELECT dispatch.* INTO v_dispatch FROM public.precheckout_blite_dispatches AS dispatch
    WHERE dispatch.preflight_id = p_preflight_id FOR UPDATE;
    IF NOT FOUND THEN RETURN FALSE; END IF;
    IF v_dispatch.state = 'enqueued'
       AND v_dispatch.dispatch_generation = p_dispatch_generation
       AND v_dispatch.last_dispatch_token IS NOT DISTINCT FROM p_dispatch_token
       AND v_dispatch.dispatch_workload_role = 'preflight'
       AND v_dispatch.dispatch_contract_version = 2 THEN
        RETURN TRUE;
    END IF;
    IF v_dispatch.dispatch_workload_role IS DISTINCT FROM 'preflight'
       OR v_dispatch.dispatch_contract_version IS DISTINCT FROM 2
       OR v_dispatch.state IS DISTINCT FROM 'enqueuing'
       OR v_dispatch.dispatch_generation IS DISTINCT FROM p_dispatch_generation
       OR v_dispatch.dispatch_token IS DISTINCT FROM p_dispatch_token THEN
        RETURN FALSE;
    END IF;
    -- Keep the legacy dispatch_token NULL invariant while retaining the exact
    -- last token for replay/recovery.  This CAS intentionally does not call the
    -- legacy mark, which has no generation parameter.
    UPDATE public.precheckout_blite_dispatches AS dispatch
    SET state = 'enqueued',
        dispatch_token = NULL,
        lease_expires_at = NULL,
        last_dispatch_token = p_dispatch_token,
        failure_reason = NULL,
        updated_at = v_now
    WHERE dispatch.preflight_id = p_preflight_id
      AND dispatch.state = 'enqueuing'
      AND dispatch.dispatch_generation = p_dispatch_generation
      AND dispatch.dispatch_token = p_dispatch_token
      AND dispatch.dispatch_workload_role = 'preflight'
      AND dispatch.dispatch_contract_version = 2;
    RETURN FOUND;
END;
$$;


--
-- Name: mark_sentry_discord_alert_delivery_started(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_sentry_discord_alert_delivery_started(p_outbox_id uuid, p_claim_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    UPDATE public.sentry_discord_alert_outbox
    SET delivery_started_at = clock_timestamp(),
        updated_at = clock_timestamp()
    WHERE id = p_outbox_id
      AND status = 'sending'
      AND claim_token = p_claim_token
      AND delivery_started_at IS NULL;
    RETURN FOUND;
END;
$$;


--
-- Name: materialize_analysis_v2_score_audit(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.materialize_analysis_v2_score_audit(p_request_id uuid, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_intent public.analysis_v2_score_audit_intents%ROWTYPE;
    v_run public.analysis_v2_score_audit_runs%ROWTYPE;
    v_source public.analysis_v2_score_audit_sources%ROWTYPE;
    v_summary public.analysis_v2_result_summaries%ROWTYPE;
    v_source_count INTEGER;
    v_result_count INTEGER;
    v_mismatch BOOLEAN;
    v_capture JSONB;
BEGIN
    SELECT * INTO v_intent FROM public.analysis_v2_score_audit_intents
    WHERE request_id = p_request_id FOR UPDATE;
    SELECT * INTO v_run FROM public.analysis_v2_score_audit_runs
    WHERE request_id = p_request_id FOR UPDATE;
    IF NOT FOUND OR v_run.status <> 'processing'
       OR v_run.lease_token IS DISTINCT FROM p_lease_token
       OR v_run.lease_expires_at <= pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_SCORE_AUDIT_LEASE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT * INTO v_summary FROM public.analysis_v2_result_summaries
    WHERE request_id = p_request_id;
    SELECT * INTO v_source FROM public.analysis_v2_score_audit_sources
    WHERE request_id = p_request_id
      AND source_result_hash = v_run.source_result_hash
      AND source_generation = v_run.source_generation;
    IF v_source.request_id IS NULL THEN
        v_capture := public.capture_analysis_v2_score_audit_source(p_request_id);
        SELECT * INTO v_source FROM public.analysis_v2_score_audit_sources
        WHERE request_id = p_request_id
          AND source_result_hash = v_run.source_result_hash
          AND source_generation = v_run.source_generation;
    END IF;
    IF v_source.source_status = 'queued' THEN
        PERFORM public.prepare_analysis_v2_score_audit_source(
            p_request_id, v_run.source_result_hash, v_run.source_generation
        );
        SELECT * INTO v_source FROM public.analysis_v2_score_audit_sources
        WHERE request_id = p_request_id
          AND source_result_hash = v_run.source_result_hash
          AND source_generation = v_run.source_generation;
    END IF;
    IF v_source.request_id IS NULL OR v_source.source_status <> 'ready' THEN
        UPDATE public.analysis_v2_score_audit_runs SET status = 'partial',
            reason = COALESCE(
                v_source.reason, v_capture->>'reason', 'SOURCE_EVIDENCE_UNAVAILABLE'
            ),
            lease_token = NULL, lease_expires_at = NULL,
            updated_at = pg_catalog.clock_timestamp()
        WHERE request_id = p_request_id;
        UPDATE public.analysis_v2_score_audit_intents
        SET intent_status = 'released', updated_at = pg_catalog.clock_timestamp()
        WHERE request_id = p_request_id
          AND source_result_hash = v_run.source_result_hash
          AND source_generation = v_run.source_generation;
        DELETE FROM public.analysis_v2_ai_scoring_stage_checkpoints
        WHERE request_id = p_request_id AND stage_kind = 'final_score'
          AND batch_key = -1 AND result_hash = v_run.source_result_hash;
        RETURN pg_catalog.jsonb_build_object('status','partial');
    END IF;
    IF v_run.risk_policy_version NOT IN ('risk-policy-v2.4', 'risk-policy-v2.5')
       OR v_source.risk_policy_version IS DISTINCT FROM v_run.risk_policy_version
       OR v_summary.score_policy_version IS DISTINCT FROM v_run.risk_policy_version THEN
        UPDATE public.analysis_v2_score_audit_runs SET status = 'partial',
            reason = 'UNSUPPORTED_SCORE_POLICY_VERSION',
            lease_token = NULL, lease_expires_at = NULL,
            updated_at = pg_catalog.clock_timestamp()
        WHERE request_id = p_request_id;
        UPDATE public.analysis_v2_score_audit_intents
        SET intent_status = 'released', updated_at = pg_catalog.clock_timestamp()
        WHERE request_id = p_request_id
          AND source_result_hash = v_run.source_result_hash
          AND source_generation = v_run.source_generation;
        DELETE FROM public.analysis_v2_ai_scoring_stage_checkpoints
        WHERE request_id = p_request_id AND stage_kind = 'final_score'
          AND batch_key = -1 AND result_hash = v_run.source_result_hash;
        RETURN pg_catalog.jsonb_build_object('status','partial');
    END IF;
    SELECT pg_catalog.count(*) INTO v_source_count
    FROM public.analysis_v2_score_audit_source_rows
    WHERE request_id = p_request_id AND source_result_hash = v_run.source_result_hash;
    SELECT pg_catalog.count(*) INTO v_result_count
    FROM public.analysis_v2_female_results WHERE request_id = p_request_id;
    IF v_source_count <> v_source.captured_count
       OR v_result_count <> v_summary.female_count
       OR v_source_count <> v_summary.female_count
       OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_female_results AS result
            FULL JOIN (
                SELECT * FROM public.analysis_v2_score_audit_source_rows
                WHERE request_id = p_request_id
                  AND source_result_hash = v_run.source_result_hash
            ) AS source
              ON source.request_id = result.request_id
             AND source.candidate_id = result.candidate_id
            WHERE COALESCE(result.request_id, source.request_id) = p_request_id
              AND (result.candidate_id IS NULL OR source.candidate_id IS NULL
                   OR result.instagram_id IS DISTINCT FROM source.instagram_id)
       ) THEN
        UPDATE public.analysis_v2_score_audit_runs SET status = 'partial',
            reason = 'PUBLIC_CANDIDATE_COMPLETENESS_MISMATCH',
            lease_token = NULL, lease_expires_at = NULL,
            updated_at = pg_catalog.clock_timestamp()
        WHERE request_id = p_request_id;
        UPDATE public.analysis_v2_score_audit_intents
        SET intent_status = 'released', updated_at = pg_catalog.clock_timestamp()
        WHERE request_id = p_request_id
          AND source_result_hash = v_run.source_result_hash
          AND source_generation = v_run.source_generation;
        DELETE FROM public.analysis_v2_ai_scoring_stage_checkpoints
        WHERE request_id = p_request_id AND stage_kind = 'final_score'
          AND batch_key = -1 AND result_hash = v_run.source_result_hash;
        RETURN pg_catalog.jsonb_build_object('status','partial');
    END IF;

    DELETE FROM public.analysis_v2_score_audit_rows
    WHERE request_id = p_request_id AND source_result_hash = v_run.source_result_hash;
    INSERT INTO public.analysis_v2_score_audit_rows (
        request_id, source_result_hash, candidate_id, actual_rank, instagram_id,
        gender_provenance, account_context, official_group_excluded,
        official_group_reason, components, signals, raw_score_units,
        natural_display_score, display_score, risk_band, featured_rank,
        relative_tier_applied, partner_cap_applied, strong_partner_evidence,
        score_consistent
    )
    SELECT source.request_id, source.source_result_hash, source.candidate_id,
        result.sort_ordinal, source.instagram_id, source.gender_provenance,
        source.account_context, source.account_context = 'official_group_or_brand',
        CASE WHEN source.account_context = 'official_group_or_brand'
            THEN 'OFFICIAL_GROUP_OR_BRAND' ELSE NULL END,
        pg_catalog.jsonb_build_array(
            pg_catalog.jsonb_build_object('key','candidateToTargetLikes','contributionUnits',pg_catalog.round((source.components->>'candidateToTargetLikes')::NUMERIC*10)::INTEGER),
            pg_catalog.jsonb_build_object('key','candidateToTargetComments','contributionUnits',pg_catalog.round((source.components->>'candidateToTargetComments')::NUMERIC*10)::INTEGER),
            pg_catalog.jsonb_build_object('key','candidateToTargetTagOrCaptionMention','contributionUnits',pg_catalog.round((source.components->>'candidateToTargetTagOrCaptionMention')::NUMERIC*10)::INTEGER),
            pg_catalog.jsonb_build_object('key','targetToCandidateTagOrCaptionMention','contributionUnits',pg_catalog.round((source.components->>'targetToCandidateTagOrCaptionMention')::NUMERIC*10)::INTEGER),
            pg_catalog.jsonb_build_object('key','targetToCandidateLike','contributionUnits',pg_catalog.round((source.components->>'targetToCandidateLike')::NUMERIC*10)::INTEGER),
            pg_catalog.jsonb_build_object('key','recentMutual','contributionUnits',pg_catalog.round((source.components->>'recentMutual')::NUMERIC*10)::INTEGER),
            pg_catalog.jsonb_build_object('key','appearanceExposure','contributionUnits',pg_catalog.round((source.components->>'appearanceExposure')::NUMERIC*10)::INTEGER),
            pg_catalog.jsonb_build_object('key','weakPartnerAdjustment','contributionUnits',pg_catalog.round(source.weak_partner_adjustment*10)::INTEGER)
        ), source.signals, pg_catalog.round(source.raw_score*10)::INTEGER,
        source.natural_display_score, pg_catalog.round(result.display_score, 1),
        result.risk_band, result.featured_rank, source.relative_tier_applied,
        source.partner_cap_applied, source.strong_partner_evidence,
        FALSE
    FROM public.analysis_v2_score_audit_source_rows AS source
    JOIN public.analysis_v2_female_results AS result
      ON result.request_id = source.request_id AND result.candidate_id = source.candidate_id
    WHERE source.request_id = p_request_id
      AND source.source_result_hash = v_run.source_result_hash
    ORDER BY result.sort_ordinal;

    WITH source_json AS (
        SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'candidateId', source.candidate_id, 'publicScore', source.public_score,
            'accountContext', source.account_context, 'components', source.components
        ) ORDER BY source.candidate_id) AS rows,
        ARRAY_AGG(source.candidate_id ORDER BY source.candidate_id)
            FILTER (WHERE source.strong_partner_evidence) AS strong_ids
        FROM public.analysis_v2_score_audit_source_rows AS source
        WHERE source.request_id = p_request_id
          AND source.source_result_hash = v_run.source_result_hash
    ), expected_relative AS (
        SELECT expected.*
        FROM source_json
        CROSS JOIN LATERAL public.analysis_v2_expected_relative_risk_rows(
            COALESCE(source_json.rows, '[]'::JSONB),
            COALESCE(source_json.strong_ids, ARRAY[]::TEXT[]),
            v_run.risk_policy_version
        ) AS expected
    ), expected_ranked AS (
        SELECT expected.*,
            pg_catalog.row_number() OVER (
                ORDER BY expected.display_score DESC, expected.candidate_id
            )::SMALLINT AS expected_sort_ordinal,
            pg_catalog.row_number() OVER (
                PARTITION BY expected.risk_band
                ORDER BY expected.display_score DESC, expected.candidate_id
            )::SMALLINT AS expected_band_rank
        FROM expected_relative AS expected
    ), checked AS (
        SELECT source.candidate_id,
            (
                NOT EXISTS (
                    SELECT 1
                    FROM pg_catalog.jsonb_each_text(expected_components.value)
                        AS expected_component(key, value)
                    WHERE pg_catalog.abs(
                        (source.components->>expected_component.key)::NUMERIC
                        - expected_component.value::NUMERIC
                    ) > 0.000000001
                )
                AND source.weak_partner_adjustment = CASE
                    WHEN (source.signals->>'hasWeakPartnerEvidence')::BOOLEAN THEN -5 ELSE 0
                END
                AND source.strong_partner_evidence
                    = (source.signals->>'hasStrongPartnerEvidence')::BOOLEAN
                AND source.pre_score = GREATEST(0, LEAST(
                    (source.components->>'candidateToTargetLikes')::NUMERIC
                    + (source.components->>'candidateToTargetComments')::NUMERIC
                    + (source.components->>'candidateToTargetTagOrCaptionMention')::NUMERIC
                    + (source.components->>'targetToCandidateTagOrCaptionMention')::NUMERIC
                    + (source.components->>'recentMutual')::NUMERIC
                    + (source.components->>'appearanceExposure')::NUMERIC
                    + source.weak_partner_adjustment, 95
                ))
                AND (source.components->>'targetToCandidateLike')::NUMERIC
                    = CASE WHEN source.signals->>'targetLikedCandidate' = 'observed' THEN 5 ELSE 0 END
                AND source.raw_score = GREATEST(0, LEAST(
                    source.pre_score + (source.components->>'targetToCandidateLike')::NUMERIC, 100
                ))
                AND pg_catalog.abs(
                    source.public_score - LEAST(
                        CASE WHEN source.strong_partner_evidence THEN 3.4 ELSE 10 END,
                        1 + 9 * source.raw_score / 100
                    )
                ) <= 0.0001
                AND source.partner_cap_applied = (
                    source.strong_partner_evidence AND (1 + 9 * source.raw_score / 100) > 3.4
                )
                AND source.natural_display_score = pg_catalog.round(source.public_score, 1)
                AND source.natural_risk_band = CASE
                    WHEN source.public_score < 4.2 THEN 'normal'
                    WHEN source.public_score < 6.8 THEN 'caution'
                    ELSE 'high_risk'
                END
                AND result.display_score = expected.display_score
                AND result.risk_band = expected.risk_band
                AND source.relative_tier_applied = expected.relative_tier_applied
                AND result.sort_ordinal = expected.expected_sort_ordinal
                AND result.display_score = source.final_display_score
                AND result.risk_band = source.final_risk_band
                AND source.featured_rank IS NOT DISTINCT FROM CASE
                    WHEN expected.risk_band = 'high_risk'
                         AND expected.expected_band_rank <= 3
                        THEN expected.expected_band_rank
                    WHEN expected.risk_band = 'caution'
                         AND expected.expected_band_rank <= 10
                        THEN expected.expected_band_rank
                    ELSE NULL
                END
                AND result.featured_rank IS NOT DISTINCT FROM CASE
                    WHEN expected.risk_band = 'high_risk'
                         AND expected.expected_band_rank <= 3
                        THEN expected.expected_band_rank
                    WHEN expected.risk_band = 'caution'
                         AND expected.expected_band_rank <= 10
                        THEN expected.expected_band_rank
                    ELSE NULL
                END
            ) AS consistent
        FROM public.analysis_v2_score_audit_source_rows AS source
        JOIN public.analysis_v2_female_results AS result
          ON result.request_id = source.request_id AND result.candidate_id = source.candidate_id
        JOIN expected_ranked AS expected ON expected.candidate_id = source.candidate_id
        CROSS JOIN LATERAL (
            SELECT public.analysis_v2_score_audit_expected_v24_components(
                source.signals, source.account_context
            ) AS value
        ) AS expected_components
        WHERE source.request_id = p_request_id
          AND source.source_result_hash = v_run.source_result_hash
    )
    UPDATE public.analysis_v2_score_audit_rows AS audit
    SET score_consistent = checked.consistent
    FROM checked
    WHERE audit.request_id = p_request_id
      AND audit.source_result_hash = v_run.source_result_hash
      AND audit.candidate_id = checked.candidate_id;

    SELECT EXISTS (
        SELECT 1 FROM public.analysis_v2_score_audit_rows
        WHERE request_id = p_request_id
          AND source_result_hash = v_run.source_result_hash
          AND NOT score_consistent
    ) INTO v_mismatch;
    UPDATE public.analysis_v2_score_audit_runs
    SET status = CASE WHEN v_mismatch THEN 'inconsistent' ELSE 'ready' END,
        reason = CASE WHEN v_mismatch THEN 'EXACT_SCORE_POLICY_MISMATCH' ELSE NULL END,
        lease_token = NULL, lease_expires_at = NULL,
        updated_at = pg_catalog.clock_timestamp()
    WHERE request_id = p_request_id
      AND source_result_hash = v_run.source_result_hash
      AND source_generation = v_run.source_generation
      AND lease_token = p_lease_token;
    UPDATE public.analysis_v2_score_audit_intents
    SET intent_status = 'released', updated_at = pg_catalog.clock_timestamp()
    WHERE request_id = p_request_id
      AND source_result_hash = v_run.source_result_hash
      AND source_generation = v_run.source_generation;
    DELETE FROM public.analysis_v2_ai_scoring_stage_checkpoints
    WHERE request_id = p_request_id AND stage_kind = 'final_score'
      AND batch_key = -1 AND result_hash = v_run.source_result_hash;
    RETURN pg_catalog.jsonb_build_object(
        'status', CASE WHEN v_mismatch THEN 'inconsistent' ELSE 'ready' END
    );
END;
$$;


--
-- Name: mirror_account_deletion_job_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mirror_account_deletion_job_v1(p_account_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_source public.account_deletion_jobs%ROWTYPE;
    v_existing public.maintenance_jobs%ROWTYPE;
    v_payload JSONB;
    v_target_key_hash TEXT;
    v_content_hash TEXT;
    v_canonical_state TEXT;
    v_final_state TEXT;
    v_final_error_code TEXT;
BEGIN
    IF p_account_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_DELETION_MIRROR_ACCOUNT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT source_job.*
    INTO v_source
    FROM public.account_deletion_jobs AS source_job
    WHERE source_job.account_id = p_account_id
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_DELETION_MIRROR_SOURCE_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    v_target_key_hash := public.canonical_json_hash_v1(
        'account-deletion-target',
        pg_catalog.jsonb_build_object('account_id', p_account_id::TEXT)
    );
    v_canonical_state := CASE
        WHEN v_source.state = 'completed' THEN 'succeeded'
        ELSE 'queued'
    END;
    v_payload := pg_catalog.jsonb_build_object(
        'source_table', 'account_deletion_jobs',
        'source_key_hash', v_target_key_hash,
        'legacy_state', v_source.state,
        'requested_at', pg_catalog.to_char(
            v_source.requested_at AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
        ),
        'objects_purged_at', CASE
            WHEN v_source.objects_purged_at IS NULL THEN NULL
            ELSE pg_catalog.to_char(
                v_source.objects_purged_at AT TIME ZONE 'UTC',
                'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
            )
        END,
        'database_purged_at', CASE
            WHEN v_source.database_purged_at IS NULL THEN NULL
            ELSE pg_catalog.to_char(
                v_source.database_purged_at AT TIME ZONE 'UTC',
                'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
            )
        END,
        'completed_at', CASE
            WHEN v_source.completed_at IS NULL THEN NULL
            ELSE pg_catalog.to_char(
                v_source.completed_at AT TIME ZONE 'UTC',
                'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
            )
        END,
        'source_updated_at', pg_catalog.to_char(
            v_source.updated_at AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
        )
    );
    v_content_hash := public.canonical_json_hash_v1(
        'account-deletion-maintenance-content',
        v_payload
    );

    SELECT maintenance_job.*
    INTO v_existing
    FROM public.maintenance_jobs AS maintenance_job
    WHERE maintenance_job.kind = 'purge'
      AND maintenance_job.target_key_hash = v_target_key_hash
    FOR UPDATE;

    IF NOT FOUND THEN
        INSERT INTO public.maintenance_jobs(
            kind,
            target_key_hash,
            state,
            next_attempt_at,
            terminal_at,
            payload,
            content_hash
        ) VALUES (
            'purge',
            v_target_key_hash,
            v_canonical_state,
            v_source.updated_at,
            CASE WHEN v_canonical_state = 'succeeded' THEN v_source.completed_at ELSE NULL END,
            v_payload,
            v_content_hash
        )
        ON CONFLICT (kind, target_key_hash) DO NOTHING;
        IF FOUND THEN
            RETURN pg_catalog.jsonb_build_object(
                'status', 'mirrored',
                'duplicate', FALSE,
                'state', v_source.state
            );
        END IF;
        SELECT maintenance_job.*
        INTO v_existing
        FROM public.maintenance_jobs AS maintenance_job
        WHERE maintenance_job.kind = 'purge'
          AND maintenance_job.target_key_hash = v_target_key_hash
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ACCOUNT_DELETION_MIRROR_CONCURRENCY_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
    END IF;

    IF v_existing.payload->>'source_table' IS DISTINCT FROM 'account_deletion_jobs' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_DELETION_MIRROR_CONTENT_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    v_final_error_code := CASE
        WHEN v_existing.state = 'succeeded' AND v_canonical_state = 'queued'
        THEN 'ACCOUNT_DELETION_SOURCE_REGRESSION'
        ELSE NULL
    END;
    v_final_state := CASE
        WHEN v_existing.state = 'blocked' THEN 'blocked'
        WHEN v_final_error_code IS NOT NULL THEN 'blocked'
        WHEN v_canonical_state = 'succeeded' THEN 'succeeded'
        WHEN v_existing.state = 'leased' THEN 'leased'
        ELSE 'queued'
    END;

    UPDATE public.maintenance_jobs
    SET state = v_final_state,
        next_attempt_at = CASE
            WHEN v_final_state = 'queued' THEN v_source.updated_at
            ELSE maintenance_jobs.next_attempt_at
        END,
        terminal_at = CASE
            WHEN v_final_state = 'succeeded' THEN v_source.completed_at
            WHEN v_final_state = 'blocked' THEN COALESCE(
                maintenance_jobs.terminal_at,
                pg_catalog.clock_timestamp()
            )
            ELSE NULL
        END,
        last_error_code = COALESCE(v_final_error_code, maintenance_jobs.last_error_code),
        lease_token = CASE
            WHEN v_final_state IN ('succeeded', 'blocked') THEN NULL
            ELSE maintenance_jobs.lease_token
        END,
        lease_holder_hash = CASE
            WHEN v_final_state IN ('succeeded', 'blocked') THEN NULL
            ELSE maintenance_jobs.lease_holder_hash
        END,
        lease_expires_at = CASE
            WHEN v_final_state IN ('succeeded', 'blocked') THEN NULL
            ELSE maintenance_jobs.lease_expires_at
        END,
        payload = v_payload,
        content_hash = v_content_hash,
        updated_at = pg_catalog.clock_timestamp()
    WHERE maintenance_jobs.id = v_existing.id;

    RETURN pg_catalog.jsonb_build_object(
        'status', 'mirrored',
        'duplicate', TRUE,
        'state', v_source.state
    );
END;
$$;


--
-- Name: normalize_analysis_beta_prepare_expiry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_analysis_beta_prepare_expiry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.status='expired'
       AND NEW.beta_entry_provenance IS NOT NULL THEN
        NEW.analysis_entry_channel:='betatest';
        NEW.beta_prepare_state:='expired';
        NEW.beta_prepare_dispatch_state:='completed';
        NEW.beta_prepare_lease_token:=NULL;
        NEW.beta_prepare_lease_expires_at:=NULL;
        NEW.beta_prepare_retry_exhausted_at:=NULL;
        NEW.beta_prepare_completed_at:=COALESCE(
            NEW.beta_prepare_completed_at,
            pg_catalog.clock_timestamp()
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: normalize_kr_mobile_e164(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_kr_mobile_e164(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
    WITH normalized AS (
        SELECT pg_catalog.regexp_replace(p_value, '[^0-9]', '', 'g') AS digits
    )
    SELECT CASE
        WHEN digits ~ '^010[0-9]{8}$'
            THEN '+82' || pg_catalog.substr(digits, 2)
        WHEN digits ~ '^8210[0-9]{8}$'
            THEN '+' || digits
        ELSE NULL
    END
    FROM normalized
$_$;


--
-- Name: precheckout_blite_v1_confidence_is_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.precheckout_blite_v1_confidence_is_valid(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    v_number NUMERIC;
BEGIN
    IF pg_catalog.jsonb_typeof(p_value) IS DISTINCT FROM 'number' THEN
        RETURN FALSE;
    END IF;
    v_number := (p_value #>> '{}')::NUMERIC;
    RETURN v_number BETWEEN 0 AND 1
       AND v_number = pg_catalog.round(v_number, 2);
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN FALSE;
END;
$$;


--
-- Name: precheckout_blite_v1_copy_is_valid(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.precheckout_blite_v1_copy_is_valid(p_value text, p_max_length integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT COALESCE(
        p_value IS NOT NULL
        AND p_value = pg_catalog.btrim(p_value)
        AND pg_catalog.char_length(p_value) BETWEEN 1 AND p_max_length
        AND p_value !~ E'[\\r\\n]'
        AND p_value ~ '[가-힣]'
        AND p_value !~* 'https?://'
        AND p_value !~* 'www[.]'
        AND p_value !~ '@',
        FALSE
    )
$$;


--
-- Name: precheckout_blite_v1_dto_is_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.precheckout_blite_v1_dto_is_valid(p_dto jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    v_value JSONB;
    v_reason JSONB;
    v_field JSONB;
    v_candidate_min NUMERIC;
    v_candidate_max NUMERIC;
    v_confidence NUMERIC;
    v_band TEXT;
    v_all_high BOOLEAN := TRUE;
    v_seen_fields TEXT[] := ARRAY[]::TEXT[];
    v_field_name TEXT;
BEGIN
    IF public.precheckout_blite_v1_has_exact_keys(
        p_dto,
        ARRAY['schemaVersion', 'persona', 'signals', 'candidateRange', 'genderRead', 'postCount', 'evidenceFields']
    ) IS DISTINCT FROM TRUE
       OR public.precheckout_blite_v1_integer_in_range(p_dto->'schemaVersion', 1, 1)
            IS DISTINCT FROM TRUE THEN
        RETURN FALSE;
    END IF;

    IF public.precheckout_blite_v1_has_exact_keys(
        p_dto->'persona', ARRAY['headline', 'summary']
    ) IS DISTINCT FROM TRUE
       OR pg_catalog.jsonb_typeof(p_dto->'persona'->'headline') IS DISTINCT FROM 'string'
       OR pg_catalog.jsonb_typeof(p_dto->'persona'->'summary') IS DISTINCT FROM 'string'
       OR public.precheckout_blite_v1_copy_is_valid(p_dto->'persona'->>'headline', 80)
            IS DISTINCT FROM TRUE
       OR public.precheckout_blite_v1_copy_is_valid(p_dto->'persona'->>'summary', 400)
            IS DISTINCT FROM TRUE THEN
        RETURN FALSE;
    END IF;

    IF pg_catalog.jsonb_typeof(p_dto->'signals') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_array_length(p_dto->'signals') <> 4 THEN
        RETURN FALSE;
    END IF;
    FOR v_value IN
        SELECT signal.value
        FROM pg_catalog.jsonb_array_elements(p_dto->'signals') AS signal(value)
    LOOP
        IF public.precheckout_blite_v1_has_exact_keys(
            v_value, ARRAY['claim', 'category', 'confidence', 'band']
        ) IS DISTINCT FROM TRUE
           OR pg_catalog.jsonb_typeof(v_value->'claim') IS DISTINCT FROM 'string'
           OR pg_catalog.jsonb_typeof(v_value->'category') IS DISTINCT FROM 'string'
           OR pg_catalog.jsonb_typeof(v_value->'band') IS DISTINCT FROM 'string'
           OR public.precheckout_blite_v1_copy_is_valid(v_value->>'claim', 120)
                IS DISTINCT FROM TRUE
           OR public.precheckout_blite_v1_copy_is_valid(v_value->>'category', 24)
                IS DISTINCT FROM TRUE
           OR public.precheckout_blite_v1_confidence_is_valid(v_value->'confidence')
                IS DISTINCT FROM TRUE THEN
            RETURN FALSE;
        END IF;
        v_confidence := (v_value->'confidence' #>> '{}')::NUMERIC;
        v_band := v_value->>'band';
        IF v_band IS DISTINCT FROM (
            CASE
                WHEN v_confidence >= 0.7 THEN 'high'
                WHEN v_confidence >= 0.5 THEN 'medium'
                ELSE 'low'
            END
        ) THEN
            RETURN FALSE;
        END IF;
        IF v_band <> 'high' THEN
            v_all_high := FALSE;
        END IF;
    END LOOP;
    IF v_all_high THEN
        RETURN FALSE;
    END IF;

    IF public.precheckout_blite_v1_has_exact_keys(
        p_dto->'candidateRange', ARRAY['min', 'max']
    ) IS DISTINCT FROM TRUE
       OR public.precheckout_blite_v1_integer_in_range(
            p_dto->'candidateRange'->'min', 0, 1000000000
       ) IS DISTINCT FROM TRUE
       OR public.precheckout_blite_v1_integer_in_range(
            p_dto->'candidateRange'->'max', 0, 1000000000
       ) IS DISTINCT FROM TRUE THEN
        RETURN FALSE;
    END IF;
    v_candidate_min := (p_dto->'candidateRange'->'min' #>> '{}')::NUMERIC;
    v_candidate_max := (p_dto->'candidateRange'->'max' #>> '{}')::NUMERIC;
    IF v_candidate_min >= v_candidate_max THEN
        RETURN FALSE;
    END IF;

    IF public.precheckout_blite_v1_has_exact_keys(
        p_dto->'genderRead', ARRAY['likelyFemale', 'confidence', 'reasons']
    ) IS DISTINCT FROM TRUE
       OR pg_catalog.jsonb_typeof(p_dto->'genderRead'->'likelyFemale') IS DISTINCT FROM 'boolean'
       OR public.precheckout_blite_v1_confidence_is_valid(p_dto->'genderRead'->'confidence')
            IS DISTINCT FROM TRUE
       OR pg_catalog.jsonb_typeof(p_dto->'genderRead'->'reasons') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_array_length(p_dto->'genderRead'->'reasons') <> 3 THEN
        RETURN FALSE;
    END IF;
    FOR v_reason IN
        SELECT reason.value
        FROM pg_catalog.jsonb_array_elements(p_dto->'genderRead'->'reasons') AS reason(value)
    LOOP
        IF pg_catalog.jsonb_typeof(v_reason) IS DISTINCT FROM 'string'
           OR public.precheckout_blite_v1_copy_is_valid(v_reason #>> '{}', 90)
                IS DISTINCT FROM TRUE THEN
            RETURN FALSE;
        END IF;
    END LOOP;

    IF public.precheckout_blite_v1_integer_in_range(p_dto->'postCount', 0, 100)
        IS DISTINCT FROM TRUE
       OR pg_catalog.jsonb_typeof(p_dto->'evidenceFields') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_array_length(p_dto->'evidenceFields') NOT BETWEEN 1 AND 15 THEN
        RETURN FALSE;
    END IF;
    FOR v_field IN
        SELECT field.value
        FROM pg_catalog.jsonb_array_elements(p_dto->'evidenceFields') AS field(value)
    LOOP
        IF pg_catalog.jsonb_typeof(v_field) IS DISTINCT FROM 'string' THEN
            RETURN FALSE;
        END IF;
        v_field_name := v_field #>> '{}';
        IF v_field_name NOT IN (
            'post.caption', 'post.hashtags', 'post.type', 'post.mediaItems',
            'post.declaredMediaCount', 'post.likesCount', 'post.commentsCount',
            'post.likesCountHidden', 'post.commentsCountHidden', 'post.taggedUsers',
            'post.mentionedUsers', 'post.imageUrl', 'post.thumbnailUrl',
            'profile.fullName', 'profile.profilePicUrl'
        ) OR v_field_name = ANY(v_seen_fields) THEN
            RETURN FALSE;
        END IF;
        v_seen_fields := pg_catalog.array_append(v_seen_fields, v_field_name);
    END LOOP;

    RETURN TRUE;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN FALSE;
END;
$$;


--
-- Name: precheckout_blite_v1_has_exact_keys(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.precheckout_blite_v1_has_exact_keys(p_value jsonb, p_expected_keys text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT COALESCE(
        p_value IS NOT NULL
        AND pg_catalog.jsonb_typeof(p_value) = 'object'
        AND (
            SELECT pg_catalog.count(*)
            FROM pg_catalog.jsonb_object_keys(p_value)
        ) = pg_catalog.array_length(p_expected_keys, 1)
        AND p_value ?& p_expected_keys,
        FALSE
    )
$$;


--
-- Name: precheckout_blite_v1_integer_in_range(jsonb, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.precheckout_blite_v1_integer_in_range(p_value jsonb, p_minimum numeric, p_maximum numeric) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    v_number NUMERIC;
BEGIN
    IF pg_catalog.jsonb_typeof(p_value) IS DISTINCT FROM 'number' THEN
        RETURN FALSE;
    END IF;
    v_number := (p_value #>> '{}')::NUMERIC;
    RETURN v_number = pg_catalog.trunc(v_number)
       AND v_number BETWEEN p_minimum AND p_maximum;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN FALSE;
END;
$$;


--
-- Name: prepare_analysis_beta_apify_preflight_credit(uuid, uuid, integer, uuid, uuid, text, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_analysis_beta_apify_preflight_credit(p_preflight_id uuid, p_user_id uuid, p_prepare_generation integer, p_prepare_token uuid, p_claim_token uuid, p_credential_slot text, p_target_profile_budget_usd numeric, p_max_snapshot_age_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE v_now TIMESTAMPTZ;
DECLARE v_gate_enabled BOOLEAN; v_grant public.analysis_beta_access_grants%ROWTYPE;
DECLARE v_preflight public.analysis_preflights%ROWTYPE;
DECLARE v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
DECLARE v_reservation public.analysis_beta_pool_reservations%ROWTYPE;
DECLARE v_result JSONB;
BEGIN
    SELECT gate_row.enabled INTO v_gate_enabled
    FROM public.analysis_beta_runtime_gate AS gate_row
    WHERE gate_row.singleton=TRUE FOR SHARE;
    PERFORM 1 FROM public.users AS owner_user
    WHERE owner_user.id=p_user_id FOR KEY SHARE;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id=p_preflight_id AND preflight.user_id=p_user_id
    FOR UPDATE;
    IF v_preflight.id IS NULL
       OR v_preflight.beta_entry_provenance IS DISTINCT FROM 'betatest_service_v1'
       OR v_preflight.beta_prepare_generation IS DISTINCT FROM p_prepare_generation
       OR v_preflight.beta_prepare_token IS DISTINCT FROM p_prepare_token
       OR v_preflight.beta_prepare_state IS DISTINCT FROM 'preparing'
       OR v_preflight.beta_prepare_lease_token IS DISTINCT FROM p_claim_token THEN
        RAISE EXCEPTION USING
            MESSAGE='ANALYSIS_BETA_PREPARE_FENCE_MISMATCH', ERRCODE='P0001';
    END IF;
    -- The predecessor takes this allocation lock before upgrading the grant.
    -- Prove the atomic path has no historical split hold, then take the final
    -- grant strength up front so the nested predecessor never upgrades.
    SELECT allocation.* INTO v_allocation
    FROM public.analysis_beta_pool_allocations AS allocation
    WHERE allocation.preflight_id=p_preflight_id
    FOR UPDATE;
    IF FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE='ANALYSIS_BETA_PREPARE_HOLD_CONFLICT', ERRCODE='P0001';
    END IF;
    SELECT grant_row.* INTO v_grant
    FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id=p_user_id FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF v_gate_enabled IS DISTINCT FROM TRUE
       OR v_grant.user_id IS NULL OR v_grant.enabled IS DISTINCT FROM TRUE
       OR (v_grant.expires_at IS NOT NULL AND (
            NOT pg_catalog.isfinite(v_grant.expires_at)
            OR v_grant.expires_at<=v_now
       ))
       OR v_preflight.beta_prepare_lease_expires_at<=v_now THEN
        RAISE EXCEPTION USING
            MESSAGE='ANALYSIS_BETA_PREPARE_FENCE_MISMATCH', ERRCODE='P0001';
    END IF;

    -- The internal exact-six hold and lifecycle promotion are one database
    -- transaction. There is no committed hold-before-complete crash window.
    v_result := public.hold_analysis_beta_apify_preflight_credit_unfenced_20260802(
        p_preflight_id,p_user_id,p_credential_slot,p_target_profile_budget_usd,
        p_max_snapshot_age_seconds);
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id=p_preflight_id FOR UPDATE;
    SELECT allocation.* INTO v_allocation
    FROM public.analysis_beta_pool_allocations AS allocation
    WHERE allocation.preflight_id=p_preflight_id FOR UPDATE;
    SELECT reservation.* INTO v_reservation
    FROM public.analysis_beta_pool_reservations AS reservation
    WHERE reservation.allocation_id=v_allocation.id
      AND reservation.operation_family='target-profile'
    FOR UPDATE;
    -- Snapshot locking inside the hold may have crossed the claim/grant expiry
    -- boundary. Re-sample database time and repeat every time-sensitive fence;
    -- raising here rolls the nested hold back with this transaction.
    v_now:=pg_catalog.clock_timestamp();
    IF v_gate_enabled IS DISTINCT FROM TRUE
       OR v_grant.enabled IS DISTINCT FROM TRUE
       OR (v_grant.expires_at IS NOT NULL AND (
            NOT pg_catalog.isfinite(v_grant.expires_at)
            OR v_grant.expires_at<=v_now
       ))
       OR v_preflight.beta_entry_provenance IS DISTINCT FROM 'betatest_service_v1'
       OR v_preflight.beta_prepare_generation IS DISTINCT FROM p_prepare_generation
       OR v_preflight.beta_prepare_token IS DISTINCT FROM p_prepare_token
       OR v_preflight.beta_prepare_state IS DISTINCT FROM 'preparing'
       OR v_preflight.beta_prepare_lease_token IS DISTINCT FROM p_claim_token
       OR v_preflight.beta_prepare_lease_expires_at<=v_now THEN
        RAISE EXCEPTION USING
            MESSAGE='ANALYSIS_BETA_PREPARE_FENCE_MISMATCH', ERRCODE='P0001';
    END IF;
    IF NOT FOUND
       OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'betatest'
       OR v_allocation.lifecycle_state IS DISTINCT FROM 'preflight_held'
       OR v_reservation.lifecycle_state IS DISTINCT FROM 'preflight_held' THEN
        RAISE EXCEPTION USING
            MESSAGE='ANALYSIS_BETA_PREPARE_HOLD_MISSING', ERRCODE='P0001';
    END IF;
    UPDATE public.analysis_preflights AS preflight
    SET beta_prepare_state='prepared',
        beta_prepare_dispatch_state='completed',
        beta_prepare_lease_token=NULL,
        beta_prepare_lease_expires_at=NULL,
        beta_prepare_retry_exhausted_at=NULL,
        beta_prepare_completed_at=v_now,
        updated_at=v_now
    WHERE preflight.id=p_preflight_id;
    RETURN v_result;
END;
$$;


