--
-- Name: prepare_analysis_v2_authorized_revenue_settlement_admission_int(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_analysis_v2_authorized_revenue_settlement_admission_int(p_preflight_id uuid, p_user_id uuid, p_selected_plan_id text, p_entitlement_jti_hash text, p_server_target_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_fallback public.analysis_preflight_provider_runs%ROWTYPE;
    v_fresh public.analysis_preflight_provider_runs%ROWTYPE;
    v_count INTEGER;
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_selected_plan_id IS NULL
       OR p_selected_plan_id NOT IN ('basic', 'standard')
       OR p_entitlement_jti_hash IS NULL
       OR p_entitlement_jti_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_INVALID_ENTITLEMENT_INPUT',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    IF v_preflight.status = 'consumed'
       AND v_preflight.admission_generation IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REVENUE_SETTLEMENT_FENCE',
            ERRCODE = 'P0001';
    END IF;

    IF v_preflight.status = 'consumed'
       AND v_preflight.consumed_request_id IS NOT NULL THEN
        RETURN pg_catalog.jsonb_build_object('disposition', 'replayable');
    END IF;

    IF v_preflight.status IS DISTINCT FROM 'ready'
       OR v_preflight.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_preflight.admission_status IS DISTINCT FROM 'ready'
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM p_selected_plan_id
       OR v_preflight.admission_entitlement_jti_hash
            IS DISTINCT FROM p_entitlement_jti_hash THEN
        RETURN pg_catalog.jsonb_build_object('disposition', 'not_applicable');
    END IF;

    IF v_preflight.admission_generation IS DISTINCT FROM 1
       OR v_preflight.admission_token IS NULL
       OR v_preflight.admission_refreshed_at IS NULL
       OR v_preflight.admission_refreshed_at > v_now + INTERVAL '30 seconds' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REVENUE_SETTLEMENT_FENCE',
            ERRCODE = 'P0001';
    END IF;

    IF v_preflight.expires_at <= v_now OR v_preflight.status = 'expired' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PREFLIGHT_EXPIRED',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_fallback
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = 'target-profile-fallback'
    FOR UPDATE;
    SELECT provider_run.*
    INTO v_fresh
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = 'target-profile-fresh-admission:g1'
    FOR UPDATE;
    SELECT pg_catalog.count(*)::INTEGER
    INTO v_count
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id;

    IF v_count <> 2
       OR v_fallback.preflight_id IS NULL
       OR v_fresh.preflight_id IS NULL
       OR v_fallback.status IS DISTINCT FROM 'succeeded'
       OR v_fresh.status IS DISTINCT FROM 'succeeded'
       OR v_fallback.input_hash IS NULL
       OR v_fresh.input_hash IS NULL
       OR v_fallback.input_hash !~ '^[a-f0-9]{64}$'
       OR v_fresh.input_hash !~ '^[a-f0-9]{64}$'
       OR v_fallback.input_hash IS DISTINCT FROM v_fresh.input_hash
       OR v_fallback.terminalized_at IS NULL
       OR v_fresh.terminalized_at IS NULL
       OR (v_fallback.actual_usage_usd IS NULL)
            <> (v_fallback.usage_reconciled_at IS NULL)
       OR (v_fresh.actual_usage_usd IS NULL)
            <> (v_fresh.usage_reconciled_at IS NULL) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REVENUE_SETTLEMENT_FENCE',
            ERRCODE = 'P0001';
    END IF;

    IF v_fallback.usage_reconciled_at IS NULL
       OR v_fresh.usage_reconciled_at IS NULL THEN
        RETURN pg_catalog.jsonb_build_object('disposition', 'pending');
    END IF;

    -- Provider input hashes prove their own immutable source, but cannot prove
    -- which mutable preflight target generated it.  A NULL preflight hash is
    -- therefore bindable only from the server-recomputed HMAC of the target
    -- currently stored on the locked row, with both provider rows agreeing.
    IF v_preflight.target_input_hash IS NULL THEN
        IF p_server_target_input_hash IS NULL
           OR p_server_target_input_hash !~ '^[a-f0-9]{64}$'
           OR v_fallback.input_hash IS DISTINCT FROM p_server_target_input_hash
           OR v_fresh.input_hash IS DISTINCT FROM p_server_target_input_hash THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_REVENUE_SETTLEMENT_FENCE',
                ERRCODE = 'P0001';
        END IF;
        UPDATE public.analysis_preflights AS preflight
        SET target_input_hash = p_server_target_input_hash,
            updated_at = v_now
        WHERE preflight.id = v_preflight.id
          AND preflight.user_id = p_user_id
          AND preflight.target_input_hash IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_REVENUE_SETTLEMENT_FENCE',
                ERRCODE = 'P0001';
        END IF;
        v_preflight.target_input_hash := p_server_target_input_hash;
    ELSIF v_preflight.target_input_hash !~ '^[a-f0-9]{64}$'
       OR v_fallback.input_hash IS DISTINCT FROM v_preflight.target_input_hash
       OR v_fresh.input_hash IS DISTINCT FROM v_preflight.target_input_hash
       OR (
           p_server_target_input_hash IS NOT NULL
           AND p_server_target_input_hash IS DISTINCT FROM v_preflight.target_input_hash
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REVENUE_SETTLEMENT_FENCE',
            ERRCODE = 'P0001';
    END IF;

    IF v_preflight.admission_refreshed_at < v_now - INTERVAL '2 minutes' THEN
        UPDATE public.analysis_preflights AS preflight
        SET admission_refreshed_at = v_now,
            updated_at = v_now
        WHERE preflight.id = v_preflight.id
          AND preflight.user_id = p_user_id
          AND preflight.status = 'ready'
          AND preflight.access_mode = 'test_entitlement'
          AND preflight.admission_status = 'ready'
          AND preflight.admission_selected_plan_id = p_selected_plan_id
          AND preflight.admission_entitlement_jti_hash = p_entitlement_jti_hash
          AND preflight.admission_token = v_preflight.admission_token;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_REVENUE_SETTLEMENT_FENCE',
                ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'disposition', 'ready',
        'admissionToken', v_preflight.admission_token
    );
END;
$_$;


--
-- Name: prepare_analysis_v2_score_audit_source(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_analysis_v2_score_audit_source(p_request_id uuid, p_result_hash text, p_generation integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_source public.analysis_v2_score_audit_sources%ROWTYPE;
    v_count INTEGER;
    v_invalid BOOLEAN;
BEGIN
    SELECT source.* INTO v_source
    FROM public.analysis_v2_score_audit_sources AS source
    WHERE source.request_id = p_request_id
      AND source.source_result_hash = p_result_hash
      AND source.source_generation = p_generation
    FOR UPDATE;
    IF NOT FOUND OR v_source.source_status <> 'queued' THEN
        RETURN pg_catalog.jsonb_build_object(
            'status', COALESCE(v_source.source_status, 'missing')
        );
    END IF;
    v_count := pg_catalog.jsonb_array_length(v_source.source_payload->'candidates');
    SELECT (
        v_source.source_payload->>'riskPolicyVersion'
            IS DISTINCT FROM v_source.risk_policy_version
    ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_source.source_payload->'candidates') AS item(value)
        WHERE public.analysis_v2_score_audit_valid_candidate(item.value)
                IS DISTINCT FROM TRUE
           OR item.value->'risk'->>'policyVersion'
                IS DISTINCT FROM v_source.risk_policy_version
           OR item.value->>'genderProvenance' NOT IN (
                'triage','feature','gender_resolution','unknown','unavailable'
           )
    ) OR (
        SELECT pg_catalog.count(DISTINCT item.value->>'candidateId') <> v_count
            OR pg_catalog.count(DISTINCT item.value->>'username') <> v_count
        FROM pg_catalog.jsonb_array_elements(v_source.source_payload->'candidates') AS item(value)
    ) INTO v_invalid;
    IF v_invalid THEN
        UPDATE public.analysis_v2_score_audit_sources
        SET source_status = 'partial', reason = 'MALFORMED_OR_DUPLICATE_SCORE_SOURCE',
            captured_count = 0, source_payload = NULL
        WHERE request_id = p_request_id AND source_result_hash = p_result_hash
          AND source_generation = p_generation;
        RETURN pg_catalog.jsonb_build_object('status','partial');
    END IF;
    INSERT INTO public.analysis_v2_score_audit_source_rows (
        request_id, source_result_hash, candidate_id, instagram_id, gender_provenance,
        account_context, components, signals, weak_partner_adjustment, pre_score,
        raw_score, public_score, natural_display_score, natural_risk_band,
        final_display_score, final_risk_band, featured_rank, relative_tier_applied,
        partner_cap_applied, strong_partner_evidence
    )
    SELECT p_request_id, p_result_hash, item.value->>'candidateId',
        item.value->>'username', item.value->>'genderProvenance',
        item.value->>'accountContext', item.value->'risk'->'components',
        pg_catalog.jsonb_build_object(
            'candidateLikes', (item.value->>'uniqueTargetPostsLikedByCandidate')::INTEGER,
            'candidateComments', (item.value->>'boundedCandidateCommentsOnTarget')::INTEGER,
            'candidateTagsTarget', (item.value->>'hasCandidateToTargetTagOrCaptionMention')::BOOLEAN,
            'targetTagsCandidate', (item.value->>'hasTargetToCandidateTagOrCaptionMention')::BOOLEAN,
            'targetLikedCandidate', item.value->>'reverseLikeStatus',
            'recentMutualRank', CASE WHEN item.value->'recentFemaleMutualRank' = 'null'::JSONB
                THEN NULL ELSE (item.value->>'recentFemaleMutualRank')::INTEGER END,
            'appearanceGrade', (item.value->>'appearanceGrade')::INTEGER,
            'exposureScore', (item.value->>'exposureScore')::NUMERIC,
            'hasWeakPartnerEvidence', (item.value->>'hasWeakPartnerEvidence')::BOOLEAN,
            'hasStrongPartnerEvidence', (item.value->>'hasStrongPartnerEvidence')::BOOLEAN
        ),
        (item.value->'risk'->>'weakPartnerAdjustment')::NUMERIC,
        (item.value->'risk'->>'preScore')::NUMERIC,
        (item.value->'risk'->>'rawScore')::NUMERIC,
        (item.value->'risk'->>'publicScore')::NUMERIC,
        (item.value->'risk'->>'displayScore')::NUMERIC,
        item.value->'risk'->>'riskBand',
        (item.value->>'displayScore')::NUMERIC, item.value->>'riskBand',
        CASE WHEN item.value->'featuredRank' = 'null'::JSONB THEN NULL
            ELSE (item.value->>'featuredRank')::SMALLINT END,
        (item.value->>'relativeTierApplied')::BOOLEAN,
        (item.value->'risk'->>'partnerCapApplied')::BOOLEAN,
        (item.value->>'hasStrongPartnerEvidence')::BOOLEAN
    FROM pg_catalog.jsonb_array_elements(v_source.source_payload->'candidates') AS item(value)
    ON CONFLICT (request_id, source_result_hash, candidate_id) DO NOTHING;
    IF (
        SELECT pg_catalog.count(*) FROM public.analysis_v2_score_audit_source_rows AS source
        WHERE source.request_id = p_request_id
          AND source.source_result_hash = p_result_hash
    ) <> v_count THEN
        DELETE FROM public.analysis_v2_score_audit_source_rows
        WHERE request_id = p_request_id AND source_result_hash = p_result_hash;
        UPDATE public.analysis_v2_score_audit_sources
        SET source_status = 'partial', reason = 'PUBLIC_CANDIDATE_SOURCE_INCOMPLETE',
            captured_count = 0, source_payload = NULL
        WHERE request_id = p_request_id AND source_result_hash = p_result_hash
          AND source_generation = p_generation;
        RETURN pg_catalog.jsonb_build_object('status','partial');
    END IF;
    UPDATE public.analysis_v2_score_audit_sources
    SET source_status = 'ready', reason = NULL, source_payload = NULL
    WHERE request_id = p_request_id AND source_result_hash = p_result_hash
      AND source_generation = p_generation AND source_status = 'queued';
    RETURN pg_catalog.jsonb_build_object('status','ready','count',v_count);
END;
$$;


--
-- Name: prepare_concierge_batch_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_concierge_batch_order(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $_$
DECLARE
    v_manifest public.earlybird_concierge_batch_cohort_members%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_current public.analysis_requests%ROWTYPE;
    v_source public.analysis_requests%ROWTYPE;
    v_source_id UUID;
    v_request_id UUID;
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_reused_source BOOLEAN := FALSE;
BEGIN
    IF p_order_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_BATCH_SCOPE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    SELECT member.*
      INTO v_manifest
    FROM public.earlybird_concierge_batch_cohort_members AS member
    WHERE member.cohort_key = 'concierge-fallback-20260816'
      AND member.order_id = p_order_id
    FOR UPDATE;

    SELECT earlybird_order.*
      INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;

    SELECT fulfillment.*
      INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;

    IF v_manifest.order_id IS NULL
       OR v_order.id IS NULL
       OR v_fulfillment.order_id IS NULL
       OR v_order.status NOT IN ('paid', 'analysis_in_progress')
       OR v_order.paid_at IS NULL
       OR v_order.payment_id IS NULL
       OR v_order.user_id IS DISTINCT FROM v_manifest.owner_id
       OR pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id))
            IS DISTINCT FROM v_manifest.target_username
       OR v_order.plan_id IS DISTINCT FROM v_manifest.plan_id
       OR v_order.preflight_id IS DISTINCT FROM v_manifest.preflight_id
       OR v_order.target_followers_count IS DISTINCT FROM v_manifest.target_followers_count
       OR v_order.target_following_count IS DISTINCT FROM v_manifest.target_following_count
       OR v_order.expected_amount_krw IS DISTINCT FROM v_manifest.expected_amount_krw
       OR v_order.expected_groble_product_id IS DISTINCT FROM v_manifest.expected_product_id
       OR v_order.actual_amount_krw IS DISTINCT FROM v_manifest.actual_amount_krw
       OR v_order.actual_groble_product_id IS DISTINCT FROM v_manifest.actual_product_id
       OR v_order.paid_at IS DISTINCT FROM v_manifest.paid_at
       OR pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_order.payment_id, 'UTF8'), 'sha256'), 'hex')
            IS DISTINCT FROM v_manifest.payment_id_fingerprint
       OR v_fulfillment.status IS DISTINCT FROM v_manifest.snapshot_fulfillment_status
       OR pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id))
            !~ '^[a-z0-9._]{1,30}$'
       OR v_order.plan_id NOT IN ('basic', 'standard') THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_BATCH_SCOPE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    -- A prior invocation is reusable only when this exact forward path marked
    -- the request. Existing failed V2 requests are retained as immutable source
    -- evidence and never retried or advanced here.
    IF v_order.result_request_id IS NOT NULL THEN
        SELECT request.*
          INTO v_current
        FROM public.analysis_requests AS request
        WHERE request.id = v_order.result_request_id
        FOR UPDATE;
        IF v_current.id IS NULL
           OR v_current.user_id IS DISTINCT FROM v_order.user_id
           OR pg_catalog.lower(pg_catalog.btrim(v_current.target_instagram_id))
                IS DISTINCT FROM pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id)) THEN
            RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_BATCH_SCOPE_CONFLICT', ERRCODE = 'P0001';
        END IF;
        IF COALESCE(v_current.step_data, '{}'::JSONB) ? 'conciergeBatchBootstrap' THEN
            IF COALESCE(v_current.step_data->'conciergeBatchBootstrap'->>'orderId', '')
                    IS DISTINCT FROM p_order_id::TEXT
               OR COALESCE(v_current.step_data->'conciergeBatchBootstrap'->>'preflightId', '')
                    IS DISTINCT FROM v_manifest.preflight_id::TEXT
               OR v_current.status NOT IN ('pending', 'failed') THEN
                RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_BATCH_REQUEST_CONFLICT', ERRCODE = 'P0001';
            END IF;
            v_source_id := (v_current.step_data->'conciergeBatchBootstrap'->>'sourceRequestId')::UUID;
            RETURN pg_catalog.jsonb_build_object(
                'orderId', p_order_id,
                'sourceRequestId', v_source_id,
                'requestId', v_current.id,
                'ownerId', v_order.user_id,
                'targetUsername', pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id)),
                'planId', v_order.plan_id,
                'preflightId', v_order.preflight_id,
                'manifestHash', v_manifest.manifest_hash,
                'evidenceHash', v_manifest.evidence_hash,
                'reused', TRUE
            );
        END IF;
        IF v_manifest.original_result_request_id IS NULL
           OR v_order.result_request_id IS DISTINCT FROM v_manifest.original_result_request_id
           OR v_current.status NOT IN ('failed', 'completed') THEN
            RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_BATCH_REQUEST_CONFLICT', ERRCODE = 'P0001';
        END IF;
        v_source := v_current;
        v_source_id := v_current.id;
        v_reused_source := TRUE;
    ELSIF v_manifest.original_result_request_id IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_BATCH_SCOPE_CONFLICT', ERRCODE = 'P0001';
    ELSE
        v_source_id := extensions.gen_random_uuid();
        INSERT INTO public.analysis_requests (
            id, user_id, target_instagram_id, target_gender, status, progress,
            progress_step, current_step, step_data, gender_stats, plan_type,
            background_processing, idempotency_key, pipeline_version
        ) VALUES (
            v_source_id, v_order.user_id,
            pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id)),
            'male', 'completed', 100, 'concierge source retained', 'completed',
            pg_catalog.jsonb_build_object(
                'conciergeBatchSource', TRUE,
                'orderId', p_order_id,
                'preflightId', v_order.preflight_id
            ), '{}'::JSONB, v_order.plan_id, FALSE,
            'concierge-batch-source:' || pg_catalog.lower(v_order.id::TEXT), 'v1'
        );
    END IF;

    v_request_id := extensions.gen_random_uuid();
    INSERT INTO public.analysis_requests (
        id, user_id, target_instagram_id, target_gender, status, progress,
        progress_step, current_step, step_data, gender_stats, plan_type,
        background_processing, idempotency_key, pipeline_version
    ) VALUES (
        v_request_id, v_order.user_id,
        pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id)),
        'male', 'pending', 0, 'concierge batch pending', 'pending',
        pg_catalog.jsonb_build_object(
            'conciergeBatchBootstrap', pg_catalog.jsonb_build_object(
                'sourceRequestId', v_source_id,
                'orderId', p_order_id,
                'preflightId', v_order.preflight_id,
                'createdAt', v_now
            )
        ), '{}'::JSONB, v_order.plan_id, FALSE,
        'concierge-batch-result:' || pg_catalog.lower(v_order.id::TEXT), 'v1'
    );

    UPDATE public.earlybird_orders
    SET status = 'analysis_in_progress',
        result_request_id = v_request_id,
        updated_at = v_now
    WHERE id = p_order_id
      AND status IN ('paid', 'analysis_in_progress')
      AND (result_request_id IS NULL OR result_request_id = v_source_id);
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_BATCH_SCOPE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'orderId', p_order_id,
        'sourceRequestId', v_source_id,
        'requestId', v_request_id,
        'ownerId', v_order.user_id,
        'targetUsername', pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id)),
        'planId', v_order.plan_id,
        'preflightId', v_order.preflight_id,
        'manifestHash', v_manifest.manifest_hash,
        'evidenceHash', v_manifest.evidence_hash,
        'reused', v_reused_source
    );
END;
$_$;


