--
-- Name: prevent_immutable_demo_analysis_fixture(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_immutable_demo_analysis_fixture() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    IF current_setting('app.demo_fixture_publish', TRUE) = '1'
       AND TG_OP = 'UPDATE'
       AND OLD.status = 'draft'
       AND NEW.status = 'published'
       AND NEW.version IS NOT DISTINCT FROM OLD.version
       AND NEW.payload IS NOT DISTINCT FROM OLD.payload
       AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at THEN
        RETURN NEW;
    END IF;
    IF current_setting('app.demo_fixture_publish', TRUE) = '1'
       AND TG_OP = 'UPDATE'
       AND OLD.status = 'published'
       AND NEW.status = 'retired'
       AND NEW.version IS NOT DISTINCT FROM OLD.version
       AND NEW.payload IS NOT DISTINCT FROM OLD.payload
       AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at THEN
        RETURN NEW;
    END IF;
    IF OLD.status = 'draft' AND TG_OP = 'UPDATE' AND NEW.status = 'published' THEN
        RAISE EXCEPTION 'draft fixtures require the controlled publish procedure';
    END IF;
    IF OLD.status IN ('published', 'retired') THEN
        RAISE EXCEPTION 'published and retired demo fixtures are immutable';
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: protect_earlybird_order_buyer_match_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_earlybird_order_buyer_match_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF OLD.buyer_match_policy IS DISTINCT FROM NEW.buyer_match_policy
       OR OLD.expected_buyer_phone_number_normalized
            IS DISTINCT FROM NEW.expected_buyer_phone_number_normalized
       OR OLD.expected_buyer_phone_verification_source
            IS DISTINCT FROM NEW.expected_buyer_phone_verification_source
       OR OLD.expected_buyer_phone_verified_at
            IS DISTINCT FROM NEW.expected_buyer_phone_verified_at THEN
        RAISE EXCEPTION 'EARLYBIRD_BUYER_MATCH_SNAPSHOT_IMMUTABLE';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: provision_e2e_test_runner_v1(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_e2e_test_runner_v1(p_user_id uuid, p_email text, p_runner_plan text, p_command_version text) RETURNS TABLE(runner_plan text, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_auth_runner_plan TEXT;
    v_auth_email TEXT;
    v_normalized_email TEXT;
    v_rollout_state TEXT;
    v_rollout_command_version TEXT;
    v_account public.users%ROWTYPE;
    v_registered_account_id UUID;
    v_registered_command_version TEXT;
    v_created BOOLEAN := FALSE;
BEGIN
    v_normalized_email := pg_catalog.lower(pg_catalog.btrim(p_email));
    IF p_user_id IS NULL
       OR p_email IS NULL
       OR v_normalized_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
       OR p_runner_plan NOT IN ('basic', 'standard')
       OR p_command_version IS NULL
       OR p_command_version !~ '^[a-z0-9._-]{1,64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_E2E_TEST_RUNNER_INPUT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- This row lock is the authorization invariant. The CLI check is only a
    -- preflight; a direct RPC call cannot provision before exact activation.
    SELECT rollout.paid_ever_state, rollout.classification_command_version
    INTO v_rollout_state, v_rollout_command_version
    FROM public.account_ledger_rollout_state AS rollout
    WHERE rollout.singleton IS TRUE
    FOR SHARE;
    IF NOT FOUND OR v_rollout_state IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_E2E_TEST_RUNNER_ROLLOUT_NOT_ACTIVE',
            ERRCODE = 'P0001';
    END IF;
    IF v_rollout_command_version IS DISTINCT FROM p_command_version THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_E2E_TEST_RUNNER_ROLLOUT_COMMAND_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.lower(pg_catalog.btrim(auth_user.email)),
        auth_user.raw_app_meta_data ->> 'analysis_test_runner_v1'
    INTO v_auth_email, v_auth_runner_plan
    FROM auth.users AS auth_user
    WHERE auth_user.id = p_user_id;
    IF NOT FOUND OR v_auth_email IS DISTINCT FROM v_normalized_email THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_E2E_TEST_RUNNER_AUTH_EMAIL_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    IF v_auth_runner_plan IS DISTINCT FROM p_runner_plan THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_E2E_TEST_RUNNER_AUTH_METADATA_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('account-e2e-test-runner:' || p_runner_plan, 0)
    );
    SELECT runner.account_id, runner.command_version
    INTO v_registered_account_id, v_registered_command_version
    FROM public.account_e2e_test_runners AS runner
    WHERE runner.runner_plan = p_runner_plan
    FOR UPDATE;
    IF FOUND AND v_registered_account_id IS DISTINCT FROM p_user_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_E2E_TEST_RUNNER_PLAN_ALREADY_BOUND',
            ERRCODE = 'P0001';
    END IF;
    IF FOUND AND v_registered_command_version IS DISTINCT FROM p_command_version THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_E2E_TEST_RUNNER_COMMAND_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT account.*
    INTO v_account
    FROM public.users AS account
    WHERE account.id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO public.users (
            id, email, provider, analysis_count, is_paid_user, is_unlimited,
            account_class, traffic_class, lifecycle, classification_version
        ) VALUES (
            p_user_id, v_normalized_email, 'e2e', 0, FALSE, FALSE,
            'e2e_test', 'e2e_test', 'active', p_command_version
        );
        SELECT account.*
        INTO v_account
        FROM public.users AS account
        WHERE account.id = p_user_id
        FOR UPDATE;
        v_created := TRUE;
    END IF;

    IF pg_catalog.lower(pg_catalog.btrim(v_account.email))
            IS DISTINCT FROM v_normalized_email
       OR v_account.account_class IS DISTINCT FROM 'e2e_test'
       OR v_account.traffic_class IS DISTINCT FROM 'e2e_test'
       OR v_account.lifecycle IS DISTINCT FROM 'active'
       OR v_account.classification_version IS DISTINCT FROM p_command_version THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_E2E_TEST_RUNNER_PRINCIPAL_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.account_e2e_test_runners (
        account_id, runner_plan, command_version
    ) VALUES (
        p_user_id, p_runner_plan, p_command_version
    ) ON CONFLICT (account_id) DO NOTHING;

    SELECT runner.account_id, runner.command_version
    INTO v_registered_account_id, v_registered_command_version
    FROM public.account_e2e_test_runners AS runner
    WHERE runner.runner_plan = p_runner_plan;
    IF v_registered_account_id IS DISTINCT FROM p_user_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_E2E_TEST_RUNNER_PLAN_ALREADY_BOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_registered_command_version IS DISTINCT FROM p_command_version THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_E2E_TEST_RUNNER_COMMAND_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.account_classification_audit AS audit
        WHERE audit.account_id = p_user_id
          AND audit.command_version = p_command_version
          AND audit.reason_code = 'E2E_RUNNER_PROVISIONED'
    ) THEN
        INSERT INTO public.account_classification_audit (
            account_id, command_version, reason_code,
            previous_account_class, previous_traffic_class, previous_lifecycle,
            next_account_class, next_traffic_class, next_lifecycle
        ) VALUES (
            p_user_id, p_command_version, 'E2E_RUNNER_PROVISIONED',
            'e2e_test', 'e2e_test', 'active',
            'e2e_test', 'e2e_test', 'active'
        );
    END IF;

    RETURN QUERY SELECT p_runner_plan, v_created;
END;
$_$;


--
-- Name: publish_analysis_v2_gender_routing_manifest(uuid, text, uuid, text, text, text, text, text, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_analysis_v2_gender_routing_manifest(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_relationship_checkpoint_id text, p_policy_version text, p_plan_id text, p_canonical_input_hmac text, p_population_count integer, p_detailed_cap integer, p_selected_count integer, p_model_attempted_count integer, p_model_valid_count integer, p_model_failed_count integer, p_model_retried_count integer, p_quota_female_shortfall integer, p_quota_uncertainty_shortfall integer, p_female_priority_count integer, p_uncertainty_count integer, p_male_deprioritized_count integer, p_selected_female_priority_count integer, p_selected_uncertainty_count integer, p_selected_male_deprioritized_count integer, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_relationship public.analysis_v2_relationship_manifests%ROWTYPE;
    v_manifest public.analysis_v2_gender_routing_manifests%ROWTYPE;
    v_row JSONB;
    v_mutual_ordinal INTEGER;
    v_ordinal INTEGER;
    v_has_image BOOLEAN;
    v_has_name BOOLEAN;
    v_selected BOOLEAN;
    v_unavailable BOOLEAN;
    v_female_score NUMERIC;
    v_male_score NUMERIC;
    v_uncertainty_score NUMERIC;
    v_row_count INTEGER := 0;
    v_selected_count INTEGER := 0;
    v_callable_count INTEGER := 0;
    v_failed_count INTEGER := 0;
    v_female_priority_count INTEGER := 0;
    v_uncertainty_count INTEGER := 0;
    v_male_deprioritized_count INTEGER := 0;
    v_selected_female_priority_count INTEGER := 0;
    v_selected_uncertainty_count INTEGER := 0;
    v_selected_male_deprioritized_count INTEGER := 0;
    v_female_slot_count INTEGER := 0;
    v_uncertainty_slot_count INTEGER := 0;
    v_rows_hash TEXT;
    v_female_quota INTEGER;
    v_uncertainty_quota INTEGER;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key <> 'track:relationships:collect'
       OR p_claim_token IS NULL
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_relationship_checkpoint_id !~ '^[a-f0-9]{64}$'
       OR p_policy_version <> 'gender-routing-v1'
       OR p_canonical_input_hmac !~ '^[a-f0-9]{64}$'
       OR pg_catalog.jsonb_typeof(p_rows) <> 'array'
       OR (p_plan_id = 'basic' AND (p_detailed_cap <> 100 OR p_population_count NOT BETWEEN 0 AND 400))
       OR (p_plan_id = 'standard' AND (p_detailed_cap <> 200 OR p_population_count NOT BETWEEN 0 AND 800))
       OR p_plan_id NOT IN ('basic', 'standard') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
    END IF;
    IF p_selected_count < 0 OR p_model_attempted_count < 0 OR p_model_valid_count < 0
       OR p_model_failed_count < 0 OR p_model_retried_count < 0
       OR p_quota_female_shortfall < 0 OR p_quota_uncertainty_shortfall < 0
       OR p_female_priority_count < 0 OR p_uncertainty_count < 0
       OR p_male_deprioritized_count < 0 OR p_selected_female_priority_count < 0
       OR p_selected_uncertainty_count < 0 OR p_selected_male_deprioritized_count < 0 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
    END IF;
    v_rows_hash := pg_catalog.md5(p_rows::TEXT);
    v_female_quota := CASE WHEN p_plan_id = 'basic' THEN 80 ELSE 160 END;
    v_uncertainty_quota := CASE WHEN p_plan_id = 'basic' THEN 20 ELSE 40 END;

    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    SELECT policy.* INTO v_policy
    FROM public.analysis_v2_provider_execution_policies AS policy
    WHERE policy.request_id = p_request_id
    FOR UPDATE;
    SELECT relationship_manifest.* INTO v_relationship
    FROM public.analysis_v2_relationship_manifests AS relationship_manifest
    WHERE relationship_manifest.request_id = p_request_id
      AND relationship_manifest.job_key = p_job_key
      AND relationship_manifest.result_hash = p_relationship_checkpoint_id
    FOR UPDATE;
    IF v_request.id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot IS DISTINCT FROM p_plan_id
       OR v_policy.request_id IS NULL
       OR v_policy.mode IS DISTINCT FROM 'test_operation_split'
       OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR v_job.request_id IS NULL
       OR v_job.status IS DISTINCT FROM 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now
       OR v_relationship.request_id IS NULL
       OR v_relationship.public_count IS DISTINCT FROM p_population_count THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT routing_manifest.* INTO v_manifest
    FROM public.analysis_v2_gender_routing_manifests AS routing_manifest
    WHERE routing_manifest.request_id = p_request_id
      AND routing_manifest.relationship_checkpoint_id = p_relationship_checkpoint_id
      AND routing_manifest.policy_version = p_policy_version
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_NOT_BUILDING', ERRCODE = 'P0001';
    END IF;
    IF v_manifest.relationship_job_key IS DISTINCT FROM p_job_key
       OR v_manifest.relationship_job_input_hash IS DISTINCT FROM p_job_input_hash
       OR v_manifest.plan_id IS DISTINCT FROM p_plan_id
       OR v_manifest.detailed_cap IS DISTINCT FROM p_detailed_cap
       OR v_manifest.population_count IS DISTINCT FROM p_population_count
       OR v_manifest.canonical_input_hmac IS DISTINCT FROM p_canonical_input_hmac THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_DRIFT', ERRCODE = 'P0001';
    END IF;
    IF v_manifest.status = 'invalidated' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALIDATED', ERRCODE = 'P0001';
    END IF;
    IF v_manifest.status = 'complete' THEN
        IF v_manifest.candidate_rows_hash IS DISTINCT FROM v_rows_hash
           OR v_manifest.selected_count IS DISTINCT FROM p_selected_count
           OR v_manifest.model_attempted_count IS DISTINCT FROM p_model_attempted_count
           OR v_manifest.model_valid_count IS DISTINCT FROM p_model_valid_count
           OR v_manifest.model_failed_count IS DISTINCT FROM p_model_failed_count
           OR v_manifest.model_retried_count IS DISTINCT FROM p_model_retried_count
           OR v_manifest.quota_female_shortfall IS DISTINCT FROM p_quota_female_shortfall
           OR v_manifest.quota_uncertainty_shortfall IS DISTINCT FROM p_quota_uncertainty_shortfall
           OR v_manifest.female_priority_count IS DISTINCT FROM p_female_priority_count
           OR v_manifest.uncertainty_count IS DISTINCT FROM p_uncertainty_count
           OR v_manifest.male_deprioritized_count IS DISTINCT FROM p_male_deprioritized_count
           OR v_manifest.selected_female_priority_count IS DISTINCT FROM p_selected_female_priority_count
           OR v_manifest.selected_uncertainty_count IS DISTINCT FROM p_selected_uncertainty_count
           OR v_manifest.selected_male_deprioritized_count IS DISTINCT FROM p_selected_male_deprioritized_count THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_gender_routing_manifest_json(v_manifest);
    END IF;

    IF pg_catalog.jsonb_array_length(p_rows) <> p_population_count THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
    END IF;
    FOR v_row IN SELECT value FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value) LOOP
        IF pg_catalog.jsonb_typeof(v_row) <> 'object'
           OR NOT (v_row ?& ARRAY[
                'mutualOrdinal', 'candidateKey', 'hasImage', 'hasName',
                'imageContentHmac', 'fullnameHmac', 'femaleScore', 'maleScore',
                'uncertaintyScore', 'evidence', 'bucket', 'routingUnavailable',
                'selected', 'selectionReason', 'selectionSlot', 'ordinal'
           ]::TEXT[])
           OR EXISTS (
                SELECT 1 FROM pg_catalog.jsonb_object_keys(v_row) AS key_name(key_name)
                WHERE key_name.key_name NOT IN (
                    'mutualOrdinal', 'candidateKey', 'hasImage', 'hasName',
                    'imageContentHmac', 'fullnameHmac', 'femaleScore', 'maleScore',
                    'uncertaintyScore', 'evidence', 'bucket', 'routingUnavailable',
                    'selected', 'selectionReason', 'selectionSlot', 'ordinal'
                )
           )
           OR pg_catalog.jsonb_typeof(v_row->'mutualOrdinal') <> 'number'
           OR (v_row->>'mutualOrdinal') !~ '^[1-9][0-9]{0,3}$'
           OR pg_catalog.jsonb_typeof(v_row->'candidateKey') <> 'string'
           OR pg_catalog.jsonb_typeof(v_row->'hasImage') <> 'boolean'
           OR pg_catalog.jsonb_typeof(v_row->'hasName') <> 'boolean'
           OR pg_catalog.jsonb_typeof(v_row->'routingUnavailable') <> 'boolean'
           OR pg_catalog.jsonb_typeof(v_row->'selected') <> 'boolean'
           OR pg_catalog.jsonb_typeof(v_row->'bucket') <> 'string'
           OR pg_catalog.jsonb_typeof(v_row->'selectionReason') <> 'string' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
        END IF;
        v_mutual_ordinal := (v_row->>'mutualOrdinal')::INTEGER;
        v_has_image := (v_row->>'hasImage')::BOOLEAN;
        v_has_name := (v_row->>'hasName')::BOOLEAN;
        v_selected := (v_row->>'selected')::BOOLEAN;
        v_unavailable := (v_row->>'routingUnavailable')::BOOLEAN;
        IF v_mutual_ordinal > 1200
           OR v_row->>'candidateKey' <> 'mutual:' || v_mutual_ordinal::TEXT
           OR v_row->>'bucket' NOT IN ('female_priority', 'uncertainty', 'male_deprioritized')
           OR (v_has_image AND v_row->'imageContentHmac' = 'null'::JSONB)
           OR (NOT v_has_image AND v_row->'imageContentHmac' <> 'null'::JSONB)
           OR (v_has_name AND v_row->'fullnameHmac' = 'null'::JSONB)
           OR (NOT v_has_name AND v_row->'fullnameHmac' <> 'null'::JSONB)
           OR (v_row->'imageContentHmac' <> 'null'::JSONB AND (
                pg_catalog.jsonb_typeof(v_row->'imageContentHmac') <> 'string'
                OR v_row->>'imageContentHmac' !~ '^[a-f0-9]{64}$'))
           OR (v_row->'fullnameHmac' <> 'null'::JSONB AND (
                pg_catalog.jsonb_typeof(v_row->'fullnameHmac') <> 'string'
                OR v_row->>'fullnameHmac' !~ '^[a-f0-9]{64}$')) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
        END IF;
        IF v_row->'femaleScore' = 'null'::JSONB
           AND v_row->'maleScore' = 'null'::JSONB
           AND v_row->'uncertaintyScore' = 'null'::JSONB THEN
            IF p_population_count > p_detailed_cap
               OR v_row->'evidence' <> 'null'::JSONB
               OR v_unavailable THEN
                RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
            END IF;
        ELSE
            IF pg_catalog.jsonb_typeof(v_row->'femaleScore') <> 'number'
               OR pg_catalog.jsonb_typeof(v_row->'maleScore') <> 'number'
               OR pg_catalog.jsonb_typeof(v_row->'uncertaintyScore') <> 'number'
               OR pg_catalog.jsonb_typeof(v_row->'evidence') <> 'string'
               OR (v_row->>'femaleScore') !~ '^(0|1)(\.[0-9]+)?$'
               OR (v_row->>'maleScore') !~ '^(0|1)(\.[0-9]+)?$'
               OR (v_row->>'uncertaintyScore') !~ '^(0|1)(\.[0-9]+)?$' THEN
                RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
            END IF;
            v_female_score := (v_row->>'femaleScore')::NUMERIC;
            v_male_score := (v_row->>'maleScore')::NUMERIC;
            v_uncertainty_score := (v_row->>'uncertaintyScore')::NUMERIC;
            IF p_population_count <= p_detailed_cap
               OR v_female_score NOT BETWEEN 0 AND 1 OR v_male_score NOT BETWEEN 0 AND 1
               OR v_uncertainty_score NOT BETWEEN 0 AND 1
               OR v_female_score + v_male_score + v_uncertainty_score NOT BETWEEN 0.999999 AND 1.000001
               OR v_row->>'evidence' <> (CASE
                    WHEN v_has_image AND v_has_name THEN 'image_and_name'
                    WHEN v_has_image THEN 'image_only'
                    WHEN v_has_name THEN 'name_only'
                    ELSE 'none'
               END)
               OR (v_row->>'bucket' = 'female_priority' AND (
                    v_female_score <= v_male_score OR v_uncertainty_score >= 0.4))
               OR (v_row->>'bucket' = 'uncertainty' AND NOT (
                    v_uncertainty_score >= 0.4 OR pg_catalog.abs(v_female_score - v_male_score) < 0.15))
               OR (v_row->>'bucket' = 'male_deprioritized' AND (
                    v_female_score > v_male_score
                    OR v_uncertainty_score >= 0.4
                    OR pg_catalog.abs(v_female_score - v_male_score) < 0.15))
               OR (v_unavailable AND (
                    v_row->>'bucket' <> 'uncertainty'
                    OR v_female_score <> 0
                    OR v_male_score <> 0
                    OR v_uncertainty_score <> 1)) THEN
                RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
            END IF;
        END IF;
        IF v_selected THEN
            IF pg_catalog.jsonb_typeof(v_row->'ordinal') <> 'number'
               OR (v_row->>'ordinal') !~ '^[1-9][0-9]{0,2}$'
               OR pg_catalog.jsonb_typeof(v_row->'selectionSlot') <> 'string' THEN
                RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
            END IF;
            v_ordinal := (v_row->>'ordinal')::INTEGER;
            IF v_ordinal > p_detailed_cap
               OR (v_row->>'selectionSlot' = 'female' AND v_row->>'selectionReason' <> 'female_quota')
               OR (v_row->>'selectionSlot' = 'uncertainty' AND v_row->>'selectionReason' <> 'uncertainty_quota')
               OR (v_row->>'selectionSlot' = 'fill' AND (
                    (p_population_count <= p_detailed_cap AND v_row->>'selectionReason' <> 'population_within_cap')
                    OR (p_population_count > p_detailed_cap AND v_row->>'selectionReason' <> 'fill')))
               OR (v_row->>'selectionSlot' = 'female' AND v_row->>'bucket' <> 'female_priority')
               OR (v_row->>'selectionSlot' = 'uncertainty' AND v_row->>'bucket' <> 'uncertainty')
               OR v_row->>'selectionSlot' NOT IN ('female', 'uncertainty', 'fill') THEN
                RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
            END IF;
        ELSIF v_row->'ordinal' <> 'null'::JSONB
           OR v_row->'selectionSlot' <> 'null'::JSONB
           OR v_row->>'selectionReason' <> 'not_selected' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
        END IF;
        PERFORM 1
        FROM public.analysis_v2_mutual_rows AS mutual_row
        WHERE mutual_row.request_id = p_request_id
          AND mutual_row.job_key = p_job_key
          AND mutual_row.mutual_ordinal = v_mutual_ordinal
          AND NOT mutual_row.is_private;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_LINEAGE_MISMATCH', ERRCODE = 'P0001';
        END IF;
        v_row_count := v_row_count + 1;
        IF v_selected THEN
            v_selected_count := v_selected_count + 1;
            IF v_row->>'selectionSlot' = 'female' THEN v_female_slot_count := v_female_slot_count + 1; END IF;
            IF v_row->>'selectionSlot' = 'uncertainty' THEN v_uncertainty_slot_count := v_uncertainty_slot_count + 1; END IF;
        END IF;
        IF v_has_image OR v_has_name THEN
            v_callable_count := v_callable_count + 1;
            IF v_unavailable THEN v_failed_count := v_failed_count + 1; END IF;
        END IF;
        IF v_row->>'bucket' = 'female_priority' THEN
            v_female_priority_count := v_female_priority_count + 1;
            IF v_selected THEN v_selected_female_priority_count := v_selected_female_priority_count + 1; END IF;
        ELSIF v_row->>'bucket' = 'uncertainty' THEN
            v_uncertainty_count := v_uncertainty_count + 1;
            IF v_selected THEN v_selected_uncertainty_count := v_selected_uncertainty_count + 1; END IF;
        ELSE
            v_male_deprioritized_count := v_male_deprioritized_count + 1;
            IF v_selected THEN v_selected_male_deprioritized_count := v_selected_male_deprioritized_count + 1; END IF;
        END IF;
    END LOOP;
    IF v_row_count <> p_population_count
       OR (SELECT pg_catalog.count(DISTINCT (value->>'mutualOrdinal')::INTEGER)
           FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)) <> p_population_count
       OR (SELECT pg_catalog.count(DISTINCT (value->>'ordinal')::INTEGER)
           FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
           WHERE (value->>'selected')::BOOLEAN) <> v_selected_count
       OR (SELECT COALESCE(pg_catalog.min((value->>'ordinal')::INTEGER), 1)
           FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
           WHERE (value->>'selected')::BOOLEAN) <> 1
       OR (SELECT COALESCE(pg_catalog.max((value->>'ordinal')::INTEGER), 0)
           FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
           WHERE (value->>'selected')::BOOLEAN) <> v_selected_count THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
    END IF;
    IF p_population_count <= p_detailed_cap THEN
        IF p_selected_count <> p_population_count OR v_selected_count <> p_population_count
           OR p_model_attempted_count <> 0 OR p_model_valid_count <> 0
           OR p_model_failed_count <> 0 OR p_model_retried_count <> 0
           OR p_quota_female_shortfall <> 0 OR p_quota_uncertainty_shortfall <> 0
           OR EXISTS (
                SELECT 1 FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value)
                WHERE value->>'selectionReason' <> 'population_within_cap'
                   OR value->>'selectionSlot' <> 'fill'
                   OR value->'femaleScore' <> 'null'::JSONB
           ) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
        END IF;
    ELSIF p_selected_count <> p_detailed_cap OR v_selected_count <> p_detailed_cap
       OR p_model_attempted_count <> v_callable_count
       OR p_model_valid_count <> v_callable_count - v_failed_count
       OR p_model_failed_count <> v_failed_count
       OR p_model_attempted_count = 0
       OR p_model_valid_count = 0
       OR p_model_failed_count::NUMERIC / p_model_attempted_count > 0.1
       OR p_model_retried_count > v_callable_count
       OR p_quota_female_shortfall <> GREATEST(0, v_female_quota - v_female_priority_count)
       OR p_quota_uncertainty_shortfall <> GREATEST(0, v_uncertainty_quota - v_uncertainty_count)
       OR v_female_slot_count <> LEAST(v_female_quota, v_female_priority_count)
       OR v_uncertainty_slot_count <> LEAST(v_uncertainty_quota, v_uncertainty_count) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
    END IF;
    IF p_female_priority_count <> v_female_priority_count
       OR p_uncertainty_count <> v_uncertainty_count
       OR p_male_deprioritized_count <> v_male_deprioritized_count
       OR p_selected_female_priority_count <> v_selected_female_priority_count
       OR p_selected_uncertainty_count <> v_selected_uncertainty_count
       OR p_selected_male_deprioritized_count <> v_selected_male_deprioritized_count
       OR p_selected_count <> v_selected_count THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_GENDER_ROUTING_MANIFEST_INVALID', ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.analysis_v2_gender_routing_candidates (
        request_id, relationship_checkpoint_id, policy_version, relationship_job_key,
        mutual_ordinal, candidate_key, has_image, has_name, image_content_hmac,
        fullname_hmac, female_score, male_score, uncertainty_score, evidence, bucket,
        routing_unavailable, selected, selection_reason, selection_slot, ordinal
    )
    SELECT p_request_id, p_relationship_checkpoint_id, p_policy_version, p_job_key,
        (value->>'mutualOrdinal')::SMALLINT, value->>'candidateKey',
        (value->>'hasImage')::BOOLEAN, (value->>'hasName')::BOOLEAN,
        NULLIF(value->>'imageContentHmac', ''), NULLIF(value->>'fullnameHmac', ''),
        CASE WHEN value->'femaleScore' = 'null'::JSONB THEN NULL ELSE (value->>'femaleScore')::NUMERIC END,
        CASE WHEN value->'maleScore' = 'null'::JSONB THEN NULL ELSE (value->>'maleScore')::NUMERIC END,
        CASE WHEN value->'uncertaintyScore' = 'null'::JSONB THEN NULL ELSE (value->>'uncertaintyScore')::NUMERIC END,
        NULLIF(value->>'evidence', ''), value->>'bucket', (value->>'routingUnavailable')::BOOLEAN,
        (value->>'selected')::BOOLEAN, value->>'selectionReason', NULLIF(value->>'selectionSlot', ''),
        CASE WHEN value->'ordinal' = 'null'::JSONB THEN NULL ELSE (value->>'ordinal')::SMALLINT END
    FROM pg_catalog.jsonb_array_elements(p_rows) AS item(value);

    UPDATE public.analysis_v2_gender_routing_manifests AS routing_manifest
    SET status = 'complete', selected_count = p_selected_count,
        model_attempted_count = p_model_attempted_count, model_valid_count = p_model_valid_count,
        model_failed_count = p_model_failed_count, model_retried_count = p_model_retried_count,
        quota_female_shortfall = p_quota_female_shortfall,
        quota_uncertainty_shortfall = p_quota_uncertainty_shortfall,
        female_priority_count = p_female_priority_count, uncertainty_count = p_uncertainty_count,
        male_deprioritized_count = p_male_deprioritized_count,
        selected_female_priority_count = p_selected_female_priority_count,
        selected_uncertainty_count = p_selected_uncertainty_count,
        selected_male_deprioritized_count = p_selected_male_deprioritized_count,
        candidate_rows_hash = v_rows_hash, completed_at = v_now, updated_at = v_now
    WHERE routing_manifest.request_id = p_request_id
      AND routing_manifest.relationship_checkpoint_id = p_relationship_checkpoint_id
      AND routing_manifest.policy_version = p_policy_version
    RETURNING * INTO v_manifest;
    RETURN public.analysis_v2_gender_routing_manifest_json(v_manifest);
END;
$_$;


--
-- Name: publish_concierge_batch_manual_override(uuid, uuid, uuid, text, text, uuid, text, text, integer, text, text, text, text, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_concierge_batch_manual_override(p_order_id uuid, p_request_id uuid, p_owner_id uuid, p_target_username text, p_target_input_hash text, p_source_request_id uuid, p_replay_lineage_hash text, p_relationship_manifest_hash text, p_expected_version integer, p_expected_result_hash text, p_result_hash text, p_result_url text, p_interaction_lineage_hash text, p_interaction_lineage jsonb, p_publication jsonb, p_classification_ledger jsonb, p_manual_import jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_result JSONB;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    -- Lock in the same order as the legacy publisher (order, then request)
    -- before taking the fulfillment row, avoiding a cross-path lock inversion.
    PERFORM 1
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;

    SELECT fulfillment.*
    INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_fulfillment.status NOT IN (
           'awaiting_operator', 'analysis_in_progress', 'completed'
       )
       OR (
           v_fulfillment.request_id IS NOT NULL
           AND v_fulfillment.request_id IS DISTINCT FROM p_request_id
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_PUBLICATION_FULFILLMENT_SCOPE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    v_result := public.publish_concierge_batch_manual_override_legacy(
        p_order_id,
        p_request_id,
        p_owner_id,
        p_target_username,
        p_target_input_hash,
        p_source_request_id,
        p_replay_lineage_hash,
        p_relationship_manifest_hash,
        p_expected_version,
        p_expected_result_hash,
        p_result_hash,
        p_result_url,
        p_interaction_lineage_hash,
        p_interaction_lineage,
        p_publication,
        p_classification_ledger,
        p_manual_import
    );

    UPDATE public.earlybird_fulfillments AS fulfillment
    SET status = 'completed',
        request_id = p_request_id,
        operator_admitted_at = COALESCE(
            fulfillment.operator_admitted_at,
            v_now
        ),
        completed_at = COALESCE(fulfillment.completed_at, v_now),
        lease_token = NULL,
        lease_expires_at = NULL,
        last_error_code = NULL,
        last_error_at = NULL,
        manual_review_at = NULL,
        updated_at = v_now
    WHERE fulfillment.order_id = p_order_id;

    RETURN v_result;
END;
$$;


--
-- Name: publish_concierge_batch_manual_override_legacy(uuid, uuid, uuid, text, text, uuid, text, text, integer, text, text, text, text, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_concierge_batch_manual_override_legacy(p_order_id uuid, p_request_id uuid, p_owner_id uuid, p_target_username text, p_target_input_hash text, p_source_request_id uuid, p_replay_lineage_hash text, p_relationship_manifest_hash text, p_expected_version integer, p_expected_result_hash text, p_result_hash text, p_result_url text, p_interaction_lineage_hash text, p_interaction_lineage jsonb, p_publication jsonb, p_classification_ledger jsonb, p_manual_import jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_order public.earlybird_orders%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_source public.analysis_requests%ROWTYPE;
    v_step_data JSONB;
    v_target TEXT;
    v_current_version INTEGER;
    v_current_result_hash TEXT;
    v_current_result_url TEXT;
    v_previous_result_hash TEXT;
    v_current_counts JSONB;
    v_male INTEGER;
    v_female INTEGER;
    v_unknown INTEGER;
    v_public INTEGER;
    v_private INTEGER;
    v_unresolved INTEGER;
    v_mutual INTEGER;
    v_authoritative_mutual INTEGER;
    v_hydrated INTEGER;
    v_analyzed INTEGER;
    v_persisted_private_rows JSONB;
    v_idempotent BOOLEAN := FALSE;
BEGIN
    v_target := pg_catalog.lower(
        pg_catalog.regexp_replace(pg_catalog.btrim(p_target_username), '^@', '')
    );
    IF p_order_id IS NULL
       OR p_request_id IS NULL
       OR p_owner_id IS NULL
       OR p_source_request_id IS NULL
       OR p_source_request_id = p_request_id
       OR v_target !~ '^[a-z0-9._]{1,30}$'
       OR p_target_input_hash !~ '^[a-f0-9]{64}$'
       OR p_replay_lineage_hash !~ '^[a-f0-9]{64}$'
       OR p_relationship_manifest_hash !~ '^[a-f0-9]{64}$'
       OR p_result_hash !~ '^[a-f0-9]{64}$'
       OR p_interaction_lineage_hash !~ '^[a-f0-9]{64}$'
       OR p_result_url IS DISTINCT FROM '/result/' || p_request_id::TEXT
       OR p_expected_version IS NULL
       OR p_expected_version < 0
       OR (p_expected_result_hash IS NOT NULL
           AND p_expected_result_hash !~ '^[a-f0-9]{64}$')
       OR pg_catalog.jsonb_typeof(p_interaction_lineage) IS DISTINCT FROM 'object'
       OR pg_catalog.jsonb_typeof(p_publication) IS DISTINCT FROM 'object'
       OR pg_catalog.jsonb_typeof(p_publication->'rows') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(p_publication->'privateRows') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(p_publication->'counts') IS DISTINCT FROM 'object'
       OR pg_catalog.jsonb_typeof(p_classification_ledger) IS DISTINCT FROM 'object'
       OR pg_catalog.jsonb_typeof(p_manual_import) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_PAYLOAD_INVALID', ERRCODE = 'P0001';
    END IF;

    IF COALESCE(p_publication->'counts'->>'male', '') !~ '^[0-9]+$'
       OR COALESCE(p_publication->'counts'->>'female', '') !~ '^[0-9]+$'
       OR COALESCE(p_publication->'counts'->>'unknown', '') !~ '^[0-9]+$'
       OR COALESCE(p_publication->'counts'->>'public', '') !~ '^[0-9]+$'
       OR COALESCE(p_publication->'counts'->>'private', '') !~ '^[0-9]+$'
       OR COALESCE(p_publication->'counts'->>'unresolved', '') !~ '^[0-9]+$'
       OR COALESCE(p_publication->'counts'->>'mutual', '') !~ '^[0-9]+$'
       OR COALESCE(p_publication->'counts'->>'authoritativeMutual', '') !~ '^[0-9]+$'
       OR COALESCE(p_publication->'counts'->>'hydrated', '') !~ '^[0-9]+$'
       OR COALESCE(p_publication->'counts'->>'analyzed', '') !~ '^[0-9]+$' THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_COUNTS_INVALID', ERRCODE = 'P0001';
    END IF;

    v_male := (p_publication->'counts'->>'male')::INTEGER;
    v_female := (p_publication->'counts'->>'female')::INTEGER;
    v_unknown := (p_publication->'counts'->>'unknown')::INTEGER;
    v_public := (p_publication->'counts'->>'public')::INTEGER;
    v_private := (p_publication->'counts'->>'private')::INTEGER;
    v_unresolved := (p_publication->'counts'->>'unresolved')::INTEGER;
    v_mutual := (p_publication->'counts'->>'mutual')::INTEGER;
    v_authoritative_mutual := (p_publication->'counts'->>'authoritativeMutual')::INTEGER;
    v_hydrated := (p_publication->'counts'->>'hydrated')::INTEGER;
    v_analyzed := (p_publication->'counts'->>'analyzed')::INTEGER;
    IF v_public <> v_male + v_female + v_unknown
       OR v_hydrated <> v_public + v_private
       OR v_mutual <> v_hydrated + v_unresolved
       OR v_authoritative_mutual <> v_mutual
       OR v_analyzed <> v_public THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_COUNTS_MISMATCH', ERRCODE = 'P0001';
    END IF;

    IF pg_catalog.jsonb_array_length(p_publication->'rows') <> v_female THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_PUBLIC_ROWS_MISMATCH', ERRCODE = 'P0001';
    END IF;

    IF (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_to_recordset(
            p_publication->'privateRows'
        ) AS row(
            sort_ordinal INTEGER,
            instagram_id TEXT,
            profile_image TEXT,
            full_name TEXT,
            name_female_score DOUBLE PRECISION,
            name_is_name BOOLEAN,
            name_confidence DOUBLE PRECISION
        )) <> v_private THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_PRIVATE_ROWS_MISMATCH', ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_to_recordset(p_publication->'privateRows') AS row(
            sort_ordinal INTEGER,
            instagram_id TEXT,
            profile_image TEXT,
            full_name TEXT,
            name_female_score DOUBLE PRECISION,
            name_is_name BOOLEAN,
            name_confidence DOUBLE PRECISION
        )
        WHERE row.sort_ordinal IS NULL
           OR row.instagram_id IS NULL
           OR row.instagram_id !~ '^[a-z0-9._]{1,30}$'
           OR row.instagram_id IS DISTINCT FROM pg_catalog.lower(
                pg_catalog.regexp_replace(pg_catalog.btrim(row.instagram_id), '^@', '')
           )
           OR row.name_female_score IS NULL
           OR row.name_female_score < 0
           OR row.name_female_score > 1
           OR row.name_is_name IS NULL
           OR row.name_confidence IS NULL
           OR row.name_confidence < 0
           OR row.name_confidence > 1
           OR (row.name_is_name = FALSE AND row.name_female_score <> 0.5)
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_PRIVATE_NAME_INVALID', ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT row.instagram_id,
                   row.sort_ordinal,
                   pg_catalog.row_number() OVER (
                       ORDER BY row.name_female_score DESC,
                                row.name_confidence DESC,
                                row.instagram_id ASC
                   )::INTEGER AS expected_sort_ordinal
            FROM pg_catalog.jsonb_to_recordset(p_publication->'privateRows') AS row(
                sort_ordinal INTEGER,
                instagram_id TEXT,
                profile_image TEXT,
                full_name TEXT,
                name_female_score DOUBLE PRECISION,
                name_is_name BOOLEAN,
                name_confidence DOUBLE PRECISION
            )
        ) AS ordered
        WHERE ordered.sort_ordinal <> ordered.expected_sort_ordinal
    ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_to_recordset(p_publication->'privateRows') AS row(
            sort_ordinal INTEGER,
            instagram_id TEXT,
            profile_image TEXT,
            full_name TEXT,
            name_female_score DOUBLE PRECISION,
            name_is_name BOOLEAN,
            name_confidence DOUBLE PRECISION
        )
        GROUP BY row.instagram_id
        HAVING pg_catalog.count(*) <> 1
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_PRIVATE_ORDER_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.*
      INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    SELECT request.*
      INTO v_request
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id
    FOR UPDATE;
    SELECT source.*
      INTO v_source
    FROM public.analysis_requests AS source
    WHERE source.id = p_source_request_id;

    IF v_order.id IS NULL
       OR v_order.user_id IS DISTINCT FROM p_owner_id
       OR pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id)) IS DISTINCT FROM v_target
       OR v_order.result_request_id IS DISTINCT FROM p_request_id
       OR v_order.status NOT IN ('paid', 'analysis_in_progress', 'completed')
       OR v_order.paid_at IS NULL
       OR v_request.id IS NULL
       OR v_request.user_id IS DISTINCT FROM p_owner_id
       OR pg_catalog.lower(pg_catalog.btrim(v_request.target_instagram_id)) IS DISTINCT FROM v_target
       OR v_source.id IS NULL
       OR v_source.user_id IS DISTINCT FROM p_owner_id THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_SCOPE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    v_step_data := COALESCE(v_request.step_data, '{}'::JSONB);
    -- The paid first order was published by a deliberately separate one-shot
    -- RPC.  Never permit this forward-only path to mutate it.
    IF v_step_data ? 'conciergeBootstrap' THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_FIRST_ORDER_IMMUTABLE', ERRCODE = 'P0001';
    END IF;
    IF COALESCE(v_step_data#>>'{conciergeBatchPublication,version}', '0') !~ '^[0-9]+$' THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_STATE_INVALID', ERRCODE = 'P0001';
    END IF;
    v_current_version := COALESCE((v_step_data#>>'{conciergeBatchPublication,version}')::INTEGER, 0);
    v_current_result_hash := v_step_data#>>'{conciergeBatchPublication,resultHash}';
    v_current_result_url := v_step_data#>>'{conciergeBatchPublication,resultUrl}';
    v_previous_result_hash := v_step_data#>>'{conciergeBatchPublication,previousResultHash}';
    v_current_counts := v_step_data#>'{conciergeBatchPublication,counts}';

    IF v_current_result_hash = p_result_hash THEN
        IF v_current_version <> p_expected_version + 1
           OR v_previous_result_hash IS DISTINCT FROM p_expected_result_hash
           OR v_current_result_url IS DISTINCT FROM p_result_url
           OR v_current_counts IS DISTINCT FROM p_publication->'counts' THEN
            RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_STALE_VERSION', ERRCODE = 'P0001';
        END IF;
        v_idempotent := TRUE;
    ELSIF v_current_version <> p_expected_version
       OR v_current_result_hash IS DISTINCT FROM p_expected_result_hash THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_STALE_VERSION', ERRCODE = 'P0001';
    END IF;

    IF NOT v_idempotent THEN
        IF v_order.status = 'completed' THEN
            RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_PUBLICATION_COMPLETED_ORDER_IMMUTABLE', ERRCODE = 'P0001';
        END IF;
        DELETE FROM public.analysis_results WHERE request_id = p_request_id;
        INSERT INTO public.analysis_results (
            request_id, rank, suspect_instagram_id, suspect_profile_image,
            suspect_full_name, bio, risk_score, photogenic_grade,
            exposure_level, is_tagged, risk_grade, gender_confidence,
            gender_status, is_unlocked, likes_count, intimate_comments_count,
            one_line_overview, risk_analysis
        )
        SELECT p_request_id, row.rank, row.suspect_instagram_id,
               row.suspect_profile_image, row.suspect_full_name, row.bio,
               row.risk_score, row.photogenic_grade, row.exposure_level,
               row.is_tagged, row.risk_grade, row.gender_confidence,
               row.gender_status, row.is_unlocked, row.likes_count,
               row.intimate_comments_count, row.one_line_overview,
               row.risk_analysis
        FROM pg_catalog.jsonb_to_recordset(p_publication->'rows') AS row(
            rank INTEGER,
            suspect_instagram_id TEXT,
            suspect_profile_image TEXT,
            suspect_full_name TEXT,
            bio TEXT,
            risk_score INTEGER,
            photogenic_grade INTEGER,
            exposure_level TEXT,
            is_tagged BOOLEAN,
            risk_grade TEXT,
            gender_confidence DOUBLE PRECISION,
            gender_status TEXT,
            is_unlocked BOOLEAN,
            likes_count INTEGER,
            intimate_comments_count INTEGER,
            one_line_overview TEXT,
            risk_analysis JSONB
        );

        DELETE FROM public.private_accounts WHERE request_id = p_request_id;
        INSERT INTO public.private_accounts (
            request_id, instagram_id, profile_image, full_name,
            name_female_score, name_is_name, name_confidence
        )
        SELECT p_request_id, row.instagram_id, row.profile_image, row.full_name,
               row.name_female_score, row.name_is_name, row.name_confidence
        FROM pg_catalog.jsonb_to_recordset(p_publication->'privateRows') AS row(
            sort_ordinal INTEGER,
            instagram_id TEXT,
            profile_image TEXT,
            full_name TEXT,
            name_female_score DOUBLE PRECISION,
            name_is_name BOOLEAN,
            name_confidence DOUBLE PRECISION
        );

        UPDATE public.analysis_requests
        SET status = 'completed',
            mutual_follows = v_mutual,
            opposite_gender_count = v_female,
            gender_stats = pg_catalog.jsonb_build_object(
                'male', v_male,
                'female', v_female,
                'unknown', v_unknown
            ),
            step_data = pg_catalog.jsonb_set(
                v_step_data,
                '{conciergeBatchPublication}',
                pg_catalog.jsonb_build_object(
                    'version', v_current_version + 1,
                    'previousResultHash', v_current_result_hash,
                    'resultHash', p_result_hash,
                    'resultUrl', p_result_url,
                    'sourceRequestId', p_source_request_id,
                    'targetInputHash', p_target_input_hash,
                    'replayLineageHash', p_replay_lineage_hash,
                    'relationshipManifestHash', p_relationship_manifest_hash,
                    'interactionLineageHash', p_interaction_lineage_hash,
                    'counts', p_publication->'counts'
                ),
                TRUE
            )
        WHERE id = p_request_id;
        UPDATE public.earlybird_orders
        SET status = 'completed'
        WHERE id = p_order_id;
        v_current_version := v_current_version + 1;
    END IF;

    SELECT COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
            'sortOrdinal', ordered.sort_ordinal,
            'instagramId', ordered.instagram_id,
            'profileImage', ordered.profile_image,
            'fullName', ordered.full_name,
            'nameFemaleScore', ordered.name_female_score,
            'nameIsName', ordered.name_is_name,
            'nameConfidence', ordered.name_confidence
        ) ORDER BY ordered.sort_ordinal
    ), '[]'::JSONB)
    INTO v_persisted_private_rows
    FROM (
        SELECT pg_catalog.row_number() OVER (
            ORDER BY private_account.name_female_score DESC,
                     private_account.name_confidence DESC,
                     private_account.instagram_id ASC
        )::INTEGER AS sort_ordinal,
        private_account.instagram_id,
        private_account.profile_image,
        private_account.full_name,
        private_account.name_female_score,
        private_account.name_is_name,
        private_account.name_confidence
        FROM public.private_accounts AS private_account
        WHERE private_account.request_id = p_request_id
    ) AS ordered;

    RETURN pg_catalog.jsonb_build_object(
        'published', TRUE,
        'idempotent', v_idempotent,
        'ownerReadContractVerified', TRUE,
        'adminReadContractVerified', TRUE,
        'resultHash', p_result_hash,
        'resultUrl', p_result_url,
        'requestId', p_request_id,
        'version', v_current_version,
        'counts', p_publication->'counts',
        'privateRows', v_persisted_private_rows
    );
END;
$_$;


--
-- Name: publish_demo_analysis_fixture(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_demo_analysis_fixture(p_version text, p_expected_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_payload JSONB;
BEGIN
    SELECT fixture.payload INTO v_payload
    FROM public.demo_analysis_fixtures AS fixture
    WHERE fixture.version = p_version AND fixture.status = 'draft'
    FOR UPDATE;
    IF v_payload IS NULL OR v_payload IS DISTINCT FROM p_expected_payload THEN
        RAISE EXCEPTION 'demo fixture draft changed or is unavailable';
    END IF;
    PERFORM set_config('app.demo_fixture_publish', '1', TRUE);
    UPDATE public.demo_analysis_fixtures AS fixture
    SET status = 'retired'
    WHERE fixture.status = 'published';
    UPDATE public.demo_analysis_fixtures AS fixture
    SET status = 'published'
    WHERE fixture.version = p_version AND fixture.status = 'draft' AND fixture.payload = p_expected_payload;
    IF NOT FOUND THEN RAISE EXCEPTION 'demo fixture draft changed during publish'; END IF;
END;
$$;


--
-- Name: publish_earlybird_v211_first_payment_concierge(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_earlybird_v211_first_payment_concierge(p_descriptor_hash text, p_evidence_hash text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_source JSONB;
    v_counts JSONB;
    v_female_rows JSONB;
    v_private_rows JSONB;
    v_payload_hash TEXT;
    v_replay RECORD;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_progress public.analysis_progress_state%ROWTYPE;
    v_existing public.earlybird_v211_concierge_publications%ROWTYPE;
    v_followers_declared INTEGER;
    v_followers_collected INTEGER;
    v_following_declared INTEGER;
    v_following_collected INTEGER;
    v_detected_mutuals INTEGER;
    v_public_mutuals INTEGER;
    v_private_mutuals INTEGER;
    v_screened_mutuals INTEGER;
    v_not_screened_mutuals INTEGER;
    v_fetch_unavailable INTEGER;
    v_media_unavailable INTEGER;
    v_analysis_unavailable INTEGER;
    v_male INTEGER;
    v_female INTEGER;
    v_unknown INTEGER;
    v_tracks JSONB;
    v_revision BIGINT;
    v_sequence BIGINT;
    v_fingerprint TEXT;
    v_event_key TEXT;
BEGIN
    IF p_descriptor_hash IS NULL
       OR p_descriptor_hash !~ '^[a-f0-9]{64}$'
       OR p_evidence_hash IS NULL
       OR p_evidence_hash !~ '^[a-f0-9]{64}$'
       OR pg_catalog.jsonb_typeof(p_payload) <> 'object'
       OR NOT p_payload ?& ARRAY[
            'schemaVersion', 'descriptorHash', 'evidenceHash',
            'semanticInputFingerprint', 'targetFullName', 'counts',
            'femaleRows', 'privateRows'
       ]
       OR p_payload - ARRAY[
            'schemaVersion', 'descriptorHash', 'evidenceHash',
            'semanticInputFingerprint', 'targetFullName', 'counts',
            'femaleRows', 'privateRows'
       ] <> '{}'::JSONB
       OR p_payload->>'schemaVersion' <> '1'
       OR p_payload->>'descriptorHash' <> p_descriptor_hash
       OR p_payload->>'evidenceHash' <> p_evidence_hash
       OR p_payload->>'semanticInputFingerprint' !~ '^[a-f0-9]{64}$'
       OR pg_catalog.jsonb_typeof(p_payload->'counts') <> 'object'
       OR pg_catalog.jsonb_typeof(p_payload->'femaleRows') <> 'array'
       OR pg_catalog.jsonb_typeof(p_payload->'privateRows') <> 'array'
       OR (
            p_payload->'targetFullName' <> 'null'::JSONB
            AND (
                pg_catalog.jsonb_typeof(p_payload->'targetFullName') <> 'string'
                OR pg_catalog.char_length(p_payload->>'targetFullName') NOT BETWEEN 1 AND 200
                OR p_payload->>'targetFullName' ~ '[[:cntrl:]]'
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_PUBLICATION_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT publication.* INTO v_existing
    FROM public.earlybird_v211_concierge_publications AS publication
    WHERE publication.status = 'completed';
    IF FOUND THEN
        IF v_existing.descriptor_hash <> p_descriptor_hash
           OR v_existing.evidence_hash <> p_evidence_hash THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_V211_CONCIERGE_PUBLICATION_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'completed', TRUE,
            'requestId', v_existing.request_id,
            'resultPath', '/result/' || v_existing.request_id::TEXT
        );
    END IF;

    v_source := public.read_earlybird_v211_concierge_recovery_source();
    IF v_source->>'descriptorHash' <> p_descriptor_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_PUBLICATION_SOURCE_DRIFT',
            ERRCODE = 'P0001';
    END IF;

    SELECT replay.* INTO v_replay
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, policy_identity_failed_request_id UUID, transient_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_apify_transient_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','policy_identity_failed_request_id','transient_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.policy_identity_failed_request_id IS NOT NULL AND decoded.transient_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS replay
    FOR UPDATE;
    IF NOT FOUND OR 1 <> (
        SELECT pg_catalog.count(*)
        
FROM LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, original_failed_request_id UUID, policy_identity_failed_request_id UUID, transient_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_apify_transient_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','policy_identity_failed_request_id','transient_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.policy_identity_failed_request_id IS NOT NULL AND decoded.transient_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS legacy_receipt_row
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_PUBLICATION_NOT_READY',
            ERRCODE = 'P0001';
    END IF;
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = v_replay.order_id
    FOR UPDATE;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = v_replay.order_id
    FOR UPDATE;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = v_fulfillment.request_id
    FOR UPDATE;
    IF v_order.id IS NULL
       OR v_fulfillment.order_id IS NULL
       OR v_request.id IS NULL
       OR v_order.plan_id <> 'basic'
       OR v_order.expected_amount_krw <> 990
       OR v_order.actual_amount_krw <> 990
       OR v_order.payment_id IS NULL
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_order.actual_groble_product_id
            IS DISTINCT FROM v_order.expected_groble_product_id
       OR v_order.exclusion_decision <> 'skip'
       OR v_order.excluded_instagram_id IS NOT NULL
       OR v_order.status <> 'analysis_in_progress'
       OR v_order.result_request_id IS DISTINCT FROM v_request.id
       OR v_fulfillment.status <> 'manual_review'
       OR v_fulfillment.request_id IS DISTINCT FROM v_request.id
       OR v_fulfillment.last_error_code <> 'ANALYSIS_FAILED'
       OR v_request.pipeline_version <> 'v2'
       OR v_request.selected_plan_id_snapshot <> 'basic'
       OR v_request.status <> 'failed'
       OR v_request.current_step <> 'failed'
       OR v_request.background_processing
       OR v_request.error_message <> 'SCRAPING_INCOMPLETE_ERROR'
       OR v_request.policy_versions_snapshot <> pg_catalog.jsonb_build_object(
            'pipeline', 'v2',
            'risk', 'risk-policy-v2.5',
            'aiStage', 'ai-stage-policy-v2.11',
            'scheduler', 'ai-scheduler-v1'
       )
       OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_result_summaries AS summary
            WHERE summary.request_id IN (
                v_replay.original_failed_request_id,
                v_replay.policy_identity_failed_request_id,
                v_replay.transient_failed_request_id,
                v_request.id
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_PUBLICATION_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    v_counts := p_payload->'counts';
    IF NOT v_counts ?& ARRAY[
        'followersDeclared', 'followersCollected',
        'followingDeclared', 'followingCollected', 'detectedMutuals',
        'publicMutuals', 'privateMutuals', 'screenedMutuals',
        'notScreenedMutuals', 'fetchUnavailableCount',
        'mediaUnavailableCount', 'analysisUnavailableCount',
        'male', 'female', 'unknown'
    ] OR v_counts - ARRAY[
        'followersDeclared', 'followersCollected',
        'followingDeclared', 'followingCollected', 'detectedMutuals',
        'publicMutuals', 'privateMutuals', 'screenedMutuals',
        'notScreenedMutuals', 'fetchUnavailableCount',
        'mediaUnavailableCount', 'analysisUnavailableCount',
        'male', 'female', 'unknown'
    ] <> '{}'::JSONB THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_PUBLICATION_COUNT_DRIFT',
            ERRCODE = 'P0001';
    END IF;
    v_followers_declared := (v_counts->>'followersDeclared')::INTEGER;
    v_followers_collected := (v_counts->>'followersCollected')::INTEGER;
    v_following_declared := (v_counts->>'followingDeclared')::INTEGER;
    v_following_collected := (v_counts->>'followingCollected')::INTEGER;
    v_detected_mutuals := (v_counts->>'detectedMutuals')::INTEGER;
    v_public_mutuals := (v_counts->>'publicMutuals')::INTEGER;
    v_private_mutuals := (v_counts->>'privateMutuals')::INTEGER;
    v_screened_mutuals := (v_counts->>'screenedMutuals')::INTEGER;
    v_not_screened_mutuals := (v_counts->>'notScreenedMutuals')::INTEGER;
    v_fetch_unavailable := (v_counts->>'fetchUnavailableCount')::INTEGER;
    v_media_unavailable := (v_counts->>'mediaUnavailableCount')::INTEGER;
    v_analysis_unavailable := (v_counts->>'analysisUnavailableCount')::INTEGER;
    v_male := (v_counts->>'male')::INTEGER;
    v_female := (v_counts->>'female')::INTEGER;
    v_unknown := (v_counts->>'unknown')::INTEGER;
    IF v_followers_collected <> 390
       OR v_followers_declared NOT BETWEEN 390 AND 393
       OR v_followers_collected * 100 < v_followers_declared * 99
       OR v_following_collected <> 256
       OR v_following_declared NOT BETWEEN 256 AND 258
       OR v_following_collected * 100 < v_following_declared * 99
       OR v_detected_mutuals <> 182
       OR v_public_mutuals <> 134
       OR v_private_mutuals <> 48
       OR v_screened_mutuals <> 134
       OR v_not_screened_mutuals <> 0
       OR v_fetch_unavailable <> 5
       OR v_media_unavailable NOT BETWEEN 0 AND 129
       OR v_analysis_unavailable NOT BETWEEN 0 AND 129
       OR v_male NOT BETWEEN 0 AND 129
       OR v_female NOT BETWEEN 0 AND 129
       OR v_unknown NOT BETWEEN 5 AND 134
       OR v_male + v_female + v_unknown <> 134
       OR v_fetch_unavailable + v_media_unavailable
            + v_analysis_unavailable > v_unknown THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_PUBLICATION_COUNT_DRIFT',
            ERRCODE = 'P0001';
    END IF;

    v_female_rows := p_payload->'femaleRows';
    v_private_rows := p_payload->'privateRows';
    IF pg_catalog.jsonb_array_length(v_female_rows) <> v_female
       OR pg_catalog.jsonb_array_length(v_private_rows) <> 48
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(v_female_rows) AS item
            WHERE pg_catalog.jsonb_typeof(item) <> 'object'
               OR NOT item ?& ARRAY[
                    'candidateId', 'sortOrdinal', 'instagramId', 'fullName',
                    'profileImageUrl', 'bio', 'displayScore', 'riskBand',
                    'featuredRank', 'recentMutualRank', 'analysisDepth',
                    'oneLineOverview', 'narrativeLineOne', 'narrativeLineTwo'
               ]
               OR item - ARRAY[
                    'candidateId', 'sortOrdinal', 'instagramId', 'fullName',
                    'profileImageUrl', 'bio', 'displayScore', 'riskBand',
                    'featuredRank', 'recentMutualRank', 'analysisDepth',
                    'oneLineOverview', 'narrativeLineOne', 'narrativeLineTwo'
               ] <> '{}'::JSONB
               OR item->'profileImageUrl' <> 'null'::JSONB
       )
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(v_private_rows) AS item
            WHERE pg_catalog.jsonb_typeof(item) <> 'object'
               OR NOT item ?& ARRAY[
                    'candidateId', 'sortOrdinal', 'instagramId', 'fullName',
                    'profileImageUrl'
               ]
               OR item - ARRAY[
                    'candidateId', 'sortOrdinal', 'instagramId', 'fullName',
                    'profileImageUrl'
               ] <> '{}'::JSONB
               OR item->'profileImageUrl' <> 'null'::JSONB
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_PUBLICATION_ROW_DRIFT',
            ERRCODE = 'P0001';
    END IF;
    IF (
        SELECT pg_catalog.count(DISTINCT item->>'candidateId')
        FROM (
            SELECT item FROM pg_catalog.jsonb_array_elements(v_female_rows) AS item
            UNION ALL
            SELECT item FROM pg_catalog.jsonb_array_elements(v_private_rows) AS item
        ) AS rows
    ) <> v_female + 48
       OR (
        SELECT pg_catalog.count(DISTINCT item->>'instagramId')
        FROM (
            SELECT item FROM pg_catalog.jsonb_array_elements(v_female_rows) AS item
            UNION ALL
            SELECT item FROM pg_catalog.jsonb_array_elements(v_private_rows) AS item
        ) AS rows
    ) <> v_female + 48
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(v_female_rows)
                WITH ORDINALITY AS row(item, ordinal)
            WHERE (item->>'sortOrdinal')::INTEGER <> ordinal
               OR item->>'candidateId' !~ '^[A-Za-z0-9._:-]{1,128}$'
               OR item->>'instagramId' !~ '^[a-z0-9._]{1,30}$'
               OR item->>'instagramId' = v_order.target_instagram_id
       )
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(v_private_rows)
                WITH ORDINALITY AS row(item, ordinal)
            WHERE (item->>'sortOrdinal')::INTEGER <> ordinal
               OR item->>'candidateId' !~ '^[A-Za-z0-9._:-]{1,128}$'
               OR item->>'instagramId' !~ '^[a-z0-9._]{1,30}$'
               OR item->>'instagramId' = v_order.target_instagram_id
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_PUBLICATION_IDENTITY_DRIFT',
            ERRCODE = 'P0001';
    END IF;

    SELECT progress.* INTO v_progress
    FROM public.analysis_progress_state AS progress
    WHERE progress.request_id = v_request.id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_PUBLICATION_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    v_payload_hash := public.analysis_v2_dag_hash_json(
        pg_catalog.jsonb_build_object(
            'domain', 'earlybird-v211-first-payment-concierge-publication-v1',
            'payload', p_payload
        )
    );
    INSERT INTO public.earlybird_v211_concierge_publications (
        request_id, descriptor_hash, evidence_hash, payload_hash,
        female_count, private_count, status
    ) VALUES (
        v_request.id, p_descriptor_hash, p_evidence_hash, v_payload_hash,
        v_female, 48, 'publishing'
    );

    INSERT INTO public.analysis_v2_result_summaries (
        request_id, target_instagram_id, target_profile_image_url, target_full_name,
        plan_id, followers_declared, followers_collected,
        following_declared, following_collected, detected_mutuals,
        public_mutuals, private_mutuals, screened_mutuals,
        not_screened_mutuals, fetch_unavailable_count,
        media_unavailable_count, analysis_unavailable_count,
        exclusion_applied, score_policy_version, finalizer_input_hash,
        male_count, female_count, unknown_count
    ) VALUES (
        v_request.id, v_order.target_instagram_id, NULL,
        p_payload->>'targetFullName', 'basic',
        v_followers_declared, v_followers_collected,
        v_following_declared, v_following_collected, v_detected_mutuals,
        v_public_mutuals, v_private_mutuals, v_screened_mutuals,
        v_not_screened_mutuals, v_fetch_unavailable,
        v_media_unavailable, v_analysis_unavailable,
        FALSE, 'risk-policy-v2.5', v_payload_hash,
        v_male, v_female, v_unknown
    );
    -- The generic target-name trigger correctly sees the scrubbed preflight;
    -- restore only the already-validated name retained in this result payload.
    UPDATE public.analysis_v2_result_summaries AS summary
    SET target_full_name = p_payload->>'targetFullName'
    WHERE summary.request_id = v_request.id;

    INSERT INTO public.analysis_v2_female_results (
        request_id, candidate_id, sort_ordinal, instagram_id, full_name,
        profile_image_url, bio, display_score, risk_band, featured_rank,
        recent_mutual_rank, analysis_depth, one_line_overview,
        narrative_line_one, narrative_line_two
    )
    SELECT v_request.id,
        item->>'candidateId', (item->>'sortOrdinal')::SMALLINT,
        item->>'instagramId', item->>'fullName', NULL, item->>'bio',
        (item->>'displayScore')::NUMERIC,
        item->>'riskBand', (item->>'featuredRank')::SMALLINT,
        (item->>'recentMutualRank')::SMALLINT, item->>'analysisDepth',
        item->>'oneLineOverview', item->>'narrativeLineOne',
        item->>'narrativeLineTwo'
    FROM pg_catalog.jsonb_array_elements(v_female_rows) AS item;

    INSERT INTO public.analysis_v2_private_results (
        request_id, candidate_id, sort_ordinal, instagram_id,
        full_name, profile_image_url
    )
    SELECT v_request.id,
        item->>'candidateId', (item->>'sortOrdinal')::SMALLINT,
        item->>'instagramId', item->>'fullName', NULL
    FROM pg_catalog.jsonb_array_elements(v_private_rows) AS item;

    IF (SELECT pg_catalog.count(*) FROM public.analysis_v2_female_results
        WHERE request_id = v_request.id) <> v_female
       OR (SELECT pg_catalog.count(*) FROM public.analysis_v2_private_results
        WHERE request_id = v_request.id) <> 48 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_PUBLICATION_ROW_DRIFT',
            ERRCODE = 'P0001';
    END IF;

    v_tracks := pg_catalog.jsonb_build_object(
        'relationshipAi', pg_catalog.jsonb_build_object(
            'state', 'completed',
            'stageCode', v_progress.tracks->'relationshipAi'->>'stageCode',
            'done', (v_progress.tracks->'relationshipAi'->>'total')::INTEGER,
            'total', (v_progress.tracks->'relationshipAi'->>'total')::INTEGER,
            'progressBp', CASE
                WHEN (v_progress.tracks->'relationshipAi'->>'total')::INTEGER = 0
                THEN 0 ELSE 10000 END
        ),
        'interactions', pg_catalog.jsonb_build_object(
            'state', 'completed',
            'stageCode', v_progress.tracks->'interactions'->>'stageCode',
            'done', (v_progress.tracks->'interactions'->>'total')::INTEGER,
            'total', (v_progress.tracks->'interactions'->>'total')::INTEGER,
            'progressBp', CASE
                WHEN (v_progress.tracks->'interactions'->>'total')::INTEGER = 0
                THEN 0 ELSE 10000 END
        ),
        'finalization', pg_catalog.jsonb_build_object(
            'state', 'completed',
            'stageCode', v_progress.tracks->'finalization'->>'stageCode',
            'done', (v_progress.tracks->'finalization'->>'total')::INTEGER,
            'total', (v_progress.tracks->'finalization'->>'total')::INTEGER,
            'progressBp', CASE
                WHEN (v_progress.tracks->'finalization'->>'total')::INTEGER = 0
                THEN 0 ELSE 10000 END
        )
    );
    v_revision := v_progress.revision + 1;
    v_sequence := v_progress.last_event_seq + 1;
    v_fingerprint := public.analysis_v2_dag_hash_json(
        pg_catalog.jsonb_build_object(
            'domain', 'analysis-v2-progress-snapshot-v1',
            'requestId', v_request.id, 'status', 'completed',
            'progressBp', 10000, 'backgroundProcessing', FALSE,
            'tracks', v_tracks, 'activeProfile', NULL, 'etaRange', NULL
        )
    );
    v_event_key := public.analysis_v2_dag_hash_json(
        pg_catalog.jsonb_build_object(
            'domain', 'analysis-v2-progress-event-v1',
            'requestId', v_request.id, 'eventCode', 'ANALYSIS_COMPLETED'
        )
    );
    UPDATE public.analysis_progress_state AS progress
    SET revision = v_revision, status = 'completed', progress_bp = 10000,
        background_processing = FALSE, tracks = v_tracks,
        active_profile = NULL, eta_range = NULL,
        last_event_seq = v_sequence, snapshot_fingerprint = v_fingerprint,
        updated_at = v_now
    WHERE progress.request_id = v_request.id;
    INSERT INTO public.analysis_progress_events (
        request_id, seq, event_key, revision, snapshot_fingerprint,
        occurred_at, event_state, event_code, copy_code, aggregate_count
    ) VALUES (
        v_request.id, v_sequence, v_event_key, v_revision, v_fingerprint,
        v_now, 'confirmed', 'ANALYSIS_COMPLETED', 'ANALYSIS_COMPLETED', NULL
    );

    UPDATE public.analysis_requests AS analysis_request
    SET status = 'completed', progress = 100,
        progress_step = 'V2 analysis completed', current_step = 'completed',
        background_processing = FALSE, error_message = NULL,
        total_followers = v_followers_declared,
        mutual_follows = v_detected_mutuals,
        opposite_gender_count = v_female,
        gender_stats = pg_catalog.jsonb_build_object(
            'male', v_male, 'female', v_female, 'unknown', v_unknown
        ),
        completed_at = v_now
    WHERE analysis_request.id = v_request.id;
    UPDATE public.earlybird_orders AS earlybird_order
    SET status = 'completed', result_request_id = v_request.id,
        updated_at = v_now
    WHERE earlybird_order.id = v_order.id;
    UPDATE public.earlybird_fulfillments AS fulfillment
    SET status = 'completed', lease_token = NULL, lease_expires_at = NULL,
        last_error_code = NULL, last_error_at = NULL,
        manual_review_at = NULL, completed_at = v_now, updated_at = v_now
    WHERE fulfillment.order_id = v_order.id;
    UPDATE public.earlybird_v211_concierge_publications AS publication
    SET status = 'completed', completed_at = v_now
    WHERE publication.request_id = v_request.id
      AND publication.status = 'publishing';

    RETURN pg_catalog.jsonb_build_object(
        'completed', TRUE,
        'requestId', v_request.id,
        'resultPath', '/result/' || v_request.id::TEXT
    );
END;
$_$;


