--
-- Name: purge_analysis_v2_ai_result_checkpoints(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_analysis_v2_ai_result_checkpoints(p_request_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_deleted INTEGER;
BEGIN
    IF p_request_id IS NULL OR NOT EXISTS (
        SELECT 1
        FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = p_request_id
          AND analysis_request.pipeline_version = 'v2'
          AND analysis_request.status IN ('completed', 'failed')
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_RESULT_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    DELETE FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
    WHERE checkpoint.request_id = p_request_id;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    RETURN v_deleted;
END;
$$;


--
-- Name: purge_analysis_v2_ai_scoring_stage(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_analysis_v2_ai_scoring_stage(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_deleted INTEGER;
BEGIN
    IF p_job_key <> 'coordinator:finalize' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_SCORING_STAGE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    JOIN public.analysis_requests AS request ON request.id = job.request_id
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
      AND job.status = 'completed'
      AND job.input_hash = p_job_input_hash
      AND job.completion_token = p_claim_token
      AND request.pipeline_version = 'v2'
      AND request.status = 'completed'
    FOR UPDATE OF job;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_SCORING_STAGE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;
    DELETE FROM public.analysis_v2_ai_scoring_stage_checkpoints AS stage
    WHERE stage.request_id = p_request_id
      AND NOT (
        stage.stage_kind = 'final_score' AND stage.batch_key = -1
        AND EXISTS (
            SELECT 1
            FROM public.analysis_v2_score_audit_intents AS intent
            LEFT JOIN public.analysis_v2_score_audit_runs AS run
              ON run.request_id = intent.request_id
             AND run.source_result_hash = intent.source_result_hash
             AND run.source_generation = intent.source_generation
            WHERE intent.request_id = p_request_id
              AND intent.source_result_hash = stage.result_hash
              AND intent.intent_status = 'queued'
              AND intent.retain_until > pg_catalog.clock_timestamp()
              AND (
                run.request_id IS NULL
                OR run.status IN ('queued','processing')
              )
        )
      );
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    RETURN v_deleted;
END;
$$;


