--
-- Name: purge_expired_analysis_v2_preflights(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_expired_analysis_v2_preflights(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '1s'
    SET statement_timeout TO '5s'
    AS $$
DECLARE
    v_scrubbed_count INTEGER;
    v_deleted_count INTEGER;
BEGIN
    PERFORM public.assert_earlybird_receipt_archive_purge_safe();
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 1000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_INVALID_MAINTENANCE_INPUT', ERRCODE = 'P0001';
    END IF;
    WITH expired AS (
        SELECT preflight.id
        FROM public.analysis_preflights AS preflight
        WHERE preflight.status <> 'consumed'
          AND preflight.expires_at <= pg_catalog.clock_timestamp()
          AND preflight.pii_scrubbed_at IS NULL
          AND NOT EXISTS (
              SELECT 1 FROM public.earlybird_orders AS earlybird_order
              WHERE earlybird_order.preflight_id = preflight.id
                AND earlybird_order.status IN (
                    'payment_pending', 'cancelled', 'paid',
                    'analysis_in_progress', 'completed'
                )
          )
        ORDER BY preflight.expires_at, preflight.id
        LIMIT p_limit FOR UPDATE SKIP LOCKED
    )
    UPDATE public.analysis_preflights AS preflight
    SET status = 'expired',
        target_instagram_id = 'retained.' || pg_catalog.substr(
            pg_catalog.replace(preflight.id::TEXT, '-', ''), 1, 20
        ),
        target_full_name = NULL, target_bio = NULL,
        target_profile_image_url = NULL, target_followers_count = NULL,
        target_following_count = NULL, target_is_private = NULL,
        capacity_required_plan_id = NULL, required_plan_id = NULL,
        plan_cards_snapshot = NULL, error_code = NULL, blocked_at = NULL,
        ready_at = NULL, exclusion_decision = 'skip',
        excluded_instagram_id = NULL, lease_token = NULL,
        lease_expires_at = NULL, pii_scrubbed_at = pg_catalog.clock_timestamp(),
        updated_at = pg_catalog.clock_timestamp()
    FROM expired WHERE preflight.id = expired.id;
    GET DIAGNOSTICS v_scrubbed_count = ROW_COUNT;

    WITH deletable AS (
        SELECT preflight.id
        FROM public.analysis_preflights AS preflight
        WHERE preflight.status = 'expired'
          AND preflight.created_at <= pg_catalog.clock_timestamp() - INTERVAL '1 hour'
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_preflight_provider_runs AS provider_run
              WHERE provider_run.preflight_id = preflight.id
                AND provider_run.status <> 'rejected'
                AND (
                    provider_run.status NOT IN (
                        'succeeded', 'failed', 'aborted', 'timed_out',
                        'resolved_no_run'
                    )
                    OR provider_run.actual_usage_usd IS NULL
                    OR provider_run.usage_reconciled_at IS NULL
                )
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.earlybird_orders AS earlybird_order
              WHERE earlybird_order.preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.earlybird_waitlist AS waitlist_entry
              WHERE waitlist_entry.preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1 
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
              WHERE recovery.recovery_preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.analysis_v2_replay_capture_authorizations
                  AS capture_authorization
              WHERE capture_authorization.preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1 
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, policy_failed_request_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
