      AND archive_source.payload->>'legacy_source_table' = 'earlybird_adoption_policy_failure_rearms'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','policy_failed_request_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.policy_failed_request_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
