              ), 'sha256'
          ), 'hex'
      )
) AS adoption_rearm
              WHERE adoption_rearm.rearmed_preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1 
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, failed_request_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
