                  archive_source.payload->'legacy_row'
              ) AS archive_row(rearmed_preflight_id UUID)
              WHERE archive_row.rearmed_preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM (
                  SELECT job.payload
                  FROM public.maintenance_jobs AS job
                  WHERE job.kind = 'recovery'
                    AND job.state = 'succeeded'
                    AND job.payload->>'legacy_source_table' = 'earlybird_profile_fetch_exhaustion_recoveries'
              ) AS archive_source
              CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
                  archive_source.payload->'legacy_row'
              ) AS archive_row(recovery_preflight_id UUID)
              WHERE archive_row.recovery_preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM (
                  SELECT job.payload
                  FROM public.maintenance_jobs AS job
                  WHERE job.kind = 'recovery'
                    AND job.state = 'succeeded'
                    AND job.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
              ) AS archive_source
              CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
                  archive_source.payload->'legacy_row'
              ) AS archive_row(recovery_preflight_id UUID)
              WHERE archive_row.recovery_preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM (
                  SELECT job.payload
                  FROM public.maintenance_jobs AS job
                  WHERE job.kind = 'rearm'
                    AND job.state = 'succeeded'
                    AND job.payload->>'legacy_source_table' = 'earlybird_terminal_unavailable_exhaustion_rearms'
              ) AS archive_source
              CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
                  archive_source.payload->'legacy_row'
              ) AS archive_row(rearmed_preflight_id UUID)
              WHERE archive_row.rearmed_preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM (
                  SELECT job.payload
                  FROM public.maintenance_jobs AS job
                  WHERE job.kind = 'replay'
                    AND job.state = 'succeeded'
                    AND job.payload->>'legacy_source_table' = 'earlybird_v211_apify_transient_replays'
              ) AS archive_source
              CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
                  archive_source.payload->'legacy_row'
              ) AS archive_row(
                  failed_preflight_id UUID, rearmed_preflight_id UUID
              )
              WHERE archive_row.failed_preflight_id = preflight.id
                 OR archive_row.rearmed_preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM (
                  SELECT job.payload
                  FROM public.maintenance_jobs AS job
                  WHERE job.kind = 'replay'
                    AND job.state = 'succeeded'
                    AND job.payload->>'legacy_source_table' = 'earlybird_v211_concierge_replays'
              ) AS archive_source
              CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
                  archive_source.payload->'legacy_row'
              ) AS archive_row(
                  failed_preflight_id UUID, rearmed_preflight_id UUID
              )
              WHERE archive_row.failed_preflight_id = preflight.id
                 OR archive_row.rearmed_preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM (
                  SELECT job.payload
                  FROM public.maintenance_jobs AS job
                  WHERE job.kind = 'rearm'
                    AND job.state = 'succeeded'
                    AND job.payload->>'legacy_source_table' = 'earlybird_v211_lease_policy_failure_rearms'
              ) AS archive_source
              CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
                  archive_source.payload->'legacy_row'
              ) AS archive_row(
                  source_preflight_id UUID, rearmed_preflight_id UUID
              )
              WHERE archive_row.source_preflight_id = preflight.id
                 OR archive_row.rearmed_preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM (
                  SELECT job.payload
                  FROM public.maintenance_jobs AS job
                  WHERE job.kind = 'replay'
                    AND job.state = 'succeeded'
                    AND job.payload->>'legacy_source_table' = 'earlybird_v211_policy_identity_replays'
              ) AS archive_source
              CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
                  archive_source.payload->'legacy_row'
              ) AS archive_row(
                  failed_preflight_id UUID, rearmed_preflight_id UUID
              )
              WHERE archive_row.failed_preflight_id = preflight.id
                 OR archive_row.rearmed_preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM (
                  SELECT job.payload
                  FROM public.maintenance_jobs AS job
                  WHERE job.kind = 'replay'
                    AND job.state = 'succeeded'
                    AND job.payload->>'legacy_source_table' = 'earlybird_v211_profile_ai_diagnostic_replays'
              ) AS archive_source
              CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
                  archive_source.payload->'legacy_row'
              ) AS archive_row(
                  failed_preflight_id UUID, rearmed_preflight_id UUID
              )
              WHERE archive_row.failed_preflight_id = preflight.id
                 OR archive_row.rearmed_preflight_id = preflight.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM (
                  SELECT job.payload
                  FROM public.maintenance_jobs AS job
                  WHERE job.kind = 'rearm'
                    AND job.state = 'succeeded'
                    AND job.payload->>'legacy_source_table' = 'earlybird_v211_relationship_lineage_failure_rearms'
              ) AS archive_source
              CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
                  archive_source.payload->'legacy_row'
              ) AS archive_row(
                  source_preflight_id UUID, rearmed_preflight_id UUID
              )
              WHERE archive_row.source_preflight_id = preflight.id
                 OR archive_row.rearmed_preflight_id = preflight.id
          )
        ORDER BY preflight.created_at, preflight.id
        LIMIT p_limit FOR UPDATE SKIP LOCKED
    )
    DELETE FROM public.analysis_preflights AS preflight
    USING deletable WHERE preflight.id = deletable.id;
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RETURN v_scrubbed_count + v_deleted_count;
END;
$$;


--
-- Name: purge_expired_analysis_v2_score_audit_evidence(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_expired_analysis_v2_score_audit_evidence(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_count INTEGER := 0;
    v_expired RECORD;
    v_summary_request_id UUID;
BEGIN
    -- Keep the lock order intent -> summary -> run -> checkpoint, matching the
    -- claim function. Locking the summary before inserting the child run keeps
    -- FK validation safe when the summary is concurrently eligible for deletion.
    FOR v_expired IN
        SELECT intent.request_id, intent.source_result_hash,
               intent.source_generation,
               request.policy_versions_snapshot->>'risk' AS risk_policy_version
        FROM public.analysis_v2_score_audit_intents AS intent
        JOIN public.analysis_requests AS request
          ON request.id = intent.request_id
        WHERE intent.intent_status = 'queued'
          AND intent.retain_until <= pg_catalog.clock_timestamp()
        ORDER BY intent.retain_until, intent.request_id
        LIMIT LEAST(GREATEST(p_limit, 1), 100)
        FOR UPDATE SKIP LOCKED
    LOOP
        v_summary_request_id := NULL;
        SELECT summary.request_id
        INTO v_summary_request_id
        FROM public.analysis_v2_result_summaries AS summary
        WHERE summary.request_id = v_expired.request_id
        FOR KEY SHARE;

        IF v_summary_request_id IS NOT NULL THEN
            INSERT INTO public.analysis_v2_score_audit_runs (
                request_id, source_result_hash, source_generation,
                risk_policy_version, status, reason
            ) VALUES (
                v_expired.request_id, v_expired.source_result_hash,
                v_expired.source_generation, v_expired.risk_policy_version,
                'partial', 'SOURCE_EVIDENCE_EXPIRED'
            )
            ON CONFLICT (request_id) DO UPDATE SET
                source_result_hash = EXCLUDED.source_result_hash,
                source_generation = EXCLUDED.source_generation,
                risk_policy_version = EXCLUDED.risk_policy_version,
                status = 'partial', reason = 'SOURCE_EVIDENCE_EXPIRED',
                lease_token = NULL, lease_expires_at = NULL,
                updated_at = pg_catalog.clock_timestamp();
        END IF;

        UPDATE public.analysis_v2_score_audit_intents AS intent
        SET intent_status = 'released',
            updated_at = pg_catalog.clock_timestamp()
        WHERE intent.request_id = v_expired.request_id
          AND intent.source_result_hash = v_expired.source_result_hash
          AND intent.source_generation = v_expired.source_generation;

        DELETE FROM public.analysis_v2_ai_scoring_stage_checkpoints AS stage
        WHERE stage.request_id = v_expired.request_id
          AND stage.stage_kind = 'final_score'
          AND stage.batch_key = -1
          AND stage.result_hash = v_expired.source_result_hash;

        v_count := v_count + 1;
    END LOOP;

    RETURN v_count;
END;
$$;


--
-- Name: purge_expired_precheckout_blite_sources_v1(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_expired_precheckout_blite_sources_v1(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_preflight_id UUID;
    v_now TIMESTAMP WITH TIME ZONE;
    v_cache public.precheckout_blite_cache%ROWTYPE;
    v_source public.precheckout_blite_sources%ROWTYPE;
    v_deleted INTEGER := 0;
BEGIN
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 1000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PRECHECKOUT_BLITE_INVALID_MAINTENANCE_INPUT', ERRCODE = 'P0001';
    END IF;

    FOR v_preflight_id IN
        SELECT preflight.id
        FROM public.precheckout_blite_sources AS expired_source
        JOIN public.analysis_preflights AS preflight
          ON preflight.id = expired_source.preflight_id
        WHERE expired_source.expires_at <= pg_catalog.clock_timestamp()
        ORDER BY preflight.id
        LIMIT p_limit
        FOR UPDATE OF preflight SKIP LOCKED
    LOOP
        -- Match claim/finalizer/terminal cleanup: parent -> cache -> source.
        SELECT cache.* INTO v_cache
        FROM public.precheckout_blite_cache AS cache
        WHERE cache.preflight_id = v_preflight_id
        FOR UPDATE;
        SELECT source.* INTO v_source
        FROM public.precheckout_blite_sources AS source
        WHERE source.preflight_id = v_preflight_id
        FOR UPDATE;
        v_now := pg_catalog.clock_timestamp();
        IF NOT FOUND OR v_source.expires_at > v_now THEN
            CONTINUE;
        END IF;
        DELETE FROM public.precheckout_blite_cache
        WHERE preflight_id = v_preflight_id;
        DELETE FROM public.precheckout_blite_sources
        WHERE preflight_id = v_preflight_id;
        v_deleted := v_deleted + 1;
    END LOOP;
    RETURN v_deleted;
END;
$$;


--
-- Name: purge_failed_analysis_v2_score_audit_sources(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_failed_analysis_v2_score_audit_sources(p_limit integer DEFAULT 5) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_count INTEGER;
BEGIN
    WITH doomed AS (
        SELECT source.request_id, source.source_result_hash
        FROM public.analysis_v2_score_audit_sources AS source
        JOIN public.analysis_requests AS request ON request.id = source.request_id
        WHERE request.status = 'failed'
        ORDER BY source.captured_at
        LIMIT LEAST(GREATEST(p_limit, 1), 20)
    )
    DELETE FROM public.analysis_v2_score_audit_sources AS source
    USING doomed
    WHERE source.request_id = doomed.request_id
      AND source.source_result_hash = doomed.source_result_hash;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


--
-- Name: purge_terminal_analysis_provider_runs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_terminal_analysis_provider_runs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.status IN ('completed', 'failed') THEN
        DELETE FROM public.analysis_provider_runs
        WHERE request_id = NEW.id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: quarantine_analysis_revenue_dispatch_v1(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quarantine_analysis_revenue_dispatch_v1(p_request_id uuid, p_job_key text, p_reason_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_guard public.analysis_revenue_dispatch_guards%ROWTYPE;
    v_changed BOOLEAN := FALSE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_reason_code IS DISTINCT FROM 'begin_failure' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REVENUE_DISPATCH_FENCE', ERRCODE = 'P0001';
    END IF;

    -- Canonical lock order: preflight → request → job → provider/source policy
    -- → revenue parent → guard.
    SELECT * INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    SELECT * INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    SELECT * INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    SELECT * INTO v_policy
    FROM public.analysis_v2_provider_execution_policies AS policy
    WHERE policy.request_id = p_request_id
    FOR UPDATE;
    SELECT * INTO v_parent
    FROM public.analysis_revenue_run_ledgers AS ledger
    WHERE ledger.request_id = p_request_id
    FOR UPDATE;
    SELECT * INTO v_guard
    FROM public.analysis_revenue_dispatch_guards AS dispatch_guard
    WHERE dispatch_guard.request_id = p_request_id
    FOR UPDATE;

    IF v_request.id IS NULL
       OR v_job.request_id IS NULL
       OR v_policy.request_id IS NULL
       OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot NOT IN ('basic', 'standard')
       OR v_policy.mode IS DISTINCT FROM 'test_operation_split'
       OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REVENUE_DISPATCH_FENCE', ERRCODE = 'P0001';
    END IF;

    IF v_guard.request_id IS NULL THEN
        INSERT INTO public.analysis_revenue_dispatch_guards (
            request_id, state, reason_code
        ) VALUES (
            p_request_id, 'quarantined', 'begin_failure'
        );
        v_changed := TRUE;
    ELSIF v_guard.state = 'quarantined'
          AND v_guard.reason_code = 'begin_failure' THEN
        v_changed := FALSE;
    ELSE
        UPDATE public.analysis_revenue_dispatch_guards AS dispatch_guard
        SET state = 'quarantined',
            reason_code = 'begin_failure',
            updated_at = pg_catalog.clock_timestamp()
        WHERE dispatch_guard.request_id = p_request_id;
        v_changed := TRUE;
    END IF;

    -- A committed begin can now be proven: keep its immutable cost lineage but
    -- put the parent under manual review. A failed/ambiguous begin with no
    -- parent is still fail-closed because the request below becomes terminal.
    IF v_parent.request_id IS NOT NULL AND v_parent.status = 'running' THEN
        UPDATE public.analysis_revenue_run_ledgers AS ledger
        SET status = 'manual_review',
            manual_review_reason = 'routing_failure'
        WHERE ledger.request_id = p_request_id;
    END IF;
    UPDATE public.analysis_requests AS analysis_request
    SET status = 'failed',
        background_processing = FALSE,
        progress_step = 'V2 analysis quarantined',
        current_step = 'failed',
        error_message = 'REVENUE_DISPATCH_QUARANTINED',
        completed_at = COALESCE(analysis_request.completed_at, pg_catalog.clock_timestamp())
    WHERE analysis_request.id = p_request_id
      AND analysis_request.status IN ('pending', 'processing');

    RETURN pg_catalog.jsonb_build_object(
        'disposition', 'quarantined',
        'created', v_changed,
        'replayed', NOT v_changed
    );
END;
$_$;


--
-- Name: read_analysis_order_audit_parity_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_analysis_order_audit_parity_snapshot(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_bundle public.analysis_order_audit_bundles%ROWTYPE;
    v_bundle_present BOOLEAN := FALSE;
    v_recovery_present BOOLEAN := FALSE;
    v_recovery_completed BOOLEAN := FALSE;
    v_order_present BOOLEAN := FALSE;
    v_source_data_present BOOLEAN := FALSE;
    v_completed BOOLEAN := FALSE;
    v_production_order BOOLEAN := FALSE;
    v_parity_attestation JSONB;

    v_relationship_job TEXT;
    v_target_evidence_job TEXT;
    v_relationship_available BOOLEAN := FALSE;
    v_target_evidence_available BOOLEAN := FALSE;
    v_candidate_available BOOLEAN := FALSE;
    v_risk_available BOOLEAN := FALSE;
    v_cost_available BOOLEAN := FALSE;

    v_relationship_source_count INTEGER;
    v_relationship_bundle_count INTEGER;
    v_relationship_source_checksum TEXT;
    v_relationship_bundle_checksum TEXT;
    v_relationship_source_complete BOOLEAN;
    v_relationship_bundle_complete BOOLEAN;

    v_target_source_count INTEGER;
    v_target_bundle_count INTEGER;
    v_target_source_checksum TEXT;
    v_target_bundle_checksum TEXT;
    v_target_source_complete BOOLEAN;
    v_target_bundle_complete BOOLEAN;

    v_candidate_source_count INTEGER;
    v_candidate_bundle_count INTEGER;
    v_candidate_source_checksum TEXT;
    v_candidate_bundle_checksum TEXT;
    v_candidate_source_complete BOOLEAN;
    v_candidate_bundle_complete BOOLEAN;

    v_risk_source_count INTEGER;
    v_risk_bundle_count INTEGER;
    v_risk_source_checksum TEXT;
    v_risk_bundle_checksum TEXT;
    v_risk_source_complete BOOLEAN;
    v_risk_bundle_complete BOOLEAN;

    v_cost_source_count INTEGER;
    v_cost_bundle_count INTEGER;
    v_cost_source_checksum TEXT;
    v_cost_bundle_checksum TEXT;
    v_cost_source_complete BOOLEAN;
    v_cost_bundle_complete BOOLEAN;
BEGIN
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_ORDER_AUDIT_CONSOLIDATION_REQUEST_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT request.*
      INTO v_request
      FROM public.analysis_requests AS request
     WHERE request.id = p_request_id
       AND request.pipeline_version = 'v2';
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    SELECT bundle.*
      INTO v_bundle
      FROM public.analysis_order_audit_bundles AS bundle
     WHERE bundle.request_id = p_request_id
     ORDER BY bundle.version DESC
     LIMIT 1;
    v_bundle_present := FOUND;

    SELECT EXISTS (
        SELECT 1
        FROM public.analysis_order_audit_assembly_queue AS queue
        WHERE queue.request_id = p_request_id
    ) INTO v_recovery_present;
    IF v_recovery_present THEN
        SELECT queue.status = 'completed', queue.parity_attestation
          INTO v_recovery_completed, v_parity_attestation
          FROM public.analysis_order_audit_assembly_queue AS queue
         WHERE queue.request_id = p_request_id;
    END IF;

    v_completed := v_request.status = 'completed';
    SELECT EXISTS (
        SELECT 1
        FROM public.earlybird_orders AS order_row
        WHERE order_row.result_request_id = p_request_id
    ) INTO v_order_present;
    v_production_order := v_completed
        AND v_request.plan_access_mode_snapshot = 'production'
        AND v_order_present;

    SELECT manifest.job_key
      INTO v_relationship_job
      FROM public.analysis_v2_relationship_manifests AS manifest
     WHERE manifest.request_id = p_request_id
     ORDER BY manifest.updated_at DESC NULLS LAST, manifest.job_key DESC
     LIMIT 1;
    v_relationship_available := v_relationship_job IS NOT NULL
        OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_mutual_rows AS mutual
            WHERE mutual.request_id = p_request_id
        );

    SELECT manifest.job_key
      INTO v_target_evidence_job
      FROM public.analysis_v2_target_evidence_manifests AS manifest
     WHERE manifest.request_id = p_request_id
     ORDER BY manifest.updated_at DESC NULLS LAST, manifest.job_key DESC
     LIMIT 1;
    v_target_evidence_available := v_target_evidence_job IS NOT NULL
        OR EXISTS (
            SELECT 1
            FROM public.analysis_target_interactors AS interaction
            WHERE interaction.request_id = p_request_id
        );

    v_candidate_available := EXISTS (
        SELECT 1
        FROM public.analysis_v2_candidate_feature_rows AS feature
        WHERE feature.request_id = p_request_id
    ) OR EXISTS (
        SELECT 1
        FROM public.analysis_v2_private_name_rows AS private_name
        WHERE private_name.request_id = p_request_id
    ) OR EXISTS (
        SELECT 1
        FROM public.analysis_v2_mutual_rows AS mutual
        WHERE mutual.request_id = p_request_id
    );

    v_risk_available := EXISTS (
        SELECT 1
        FROM public.analysis_v2_candidate_score_manifests AS manifest
        WHERE manifest.request_id = p_request_id
    ) OR EXISTS (
        SELECT 1
        FROM public.analysis_v2_candidate_score_rows AS score
        WHERE score.request_id = p_request_id
    );

    v_cost_available := EXISTS (
        SELECT 1
        FROM public.analysis_v2_cost_rollups AS rollup
        WHERE rollup.request_id = p_request_id
    );
    v_source_data_present := v_relationship_available
        OR v_target_evidence_available
        OR v_candidate_available
        OR v_risk_available
        OR v_cost_available;

    -- Relationship parity compares only the immutable common projection. Handles, names, profile
    -- media, request IDs, and timestamps are deliberately excluded from the checksum projection.
    IF v_relationship_available THEN
        SELECT count(*)::INTEGER
          INTO v_relationship_source_count
          FROM public.analysis_v2_mutual_rows AS mutual
         WHERE mutual.request_id = p_request_id
           AND (
               v_relationship_job IS NULL
               OR mutual.job_key = v_relationship_job
           );
        SELECT public.analysis_order_audit_digest(COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'mutualOrdinal', mutual.mutual_ordinal,
                    'followingOrdinal', mutual.following_ordinal,
                    'candidateKeyHash', public.analysis_order_audit_digest(mutual.username),
                    'isPrivate', mutual.is_private,
                    'isVerified', mutual.is_verified
                ) ORDER BY mutual.mutual_ordinal, mutual.username
            )::TEXT
            FROM public.analysis_v2_mutual_rows AS mutual
            WHERE mutual.request_id = p_request_id
              AND (
                  v_relationship_job IS NULL
                  OR mutual.job_key = v_relationship_job
              )
        ), '[]')) INTO v_relationship_source_checksum;
        v_relationship_source_complete := v_relationship_job IS NOT NULL
            AND EXISTS (
                SELECT 1
                FROM public.analysis_v2_relationship_sides AS side
                WHERE side.request_id = p_request_id
                  AND side.side = 'followers'
                  AND side.job_key = v_relationship_job
                  AND side.declared_count = side.collected_count
            )
            AND EXISTS (
                SELECT 1
                FROM public.analysis_v2_relationship_sides AS side
                WHERE side.request_id = p_request_id
                  AND side.side = 'following'
                  AND side.job_key = v_relationship_job
                  AND side.declared_count = side.collected_count
            )
            AND EXISTS (
                SELECT 1
                FROM public.analysis_v2_relationship_manifests AS manifest
                WHERE manifest.request_id = p_request_id
                  AND manifest.job_key = v_relationship_job
                  AND manifest.mutual_count = v_relationship_source_count
            );
    END IF;

    IF v_bundle_present THEN
        SELECT count(*)::INTEGER
          INTO v_relationship_bundle_count
          FROM public.analysis_order_audit_candidates AS candidate
         WHERE candidate.request_id = v_bundle.request_id
           AND candidate.version = v_bundle.version;
        SELECT public.analysis_order_audit_digest(COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'mutualOrdinal', candidate.mutual_ordinal,
                    'followingOrdinal', candidate.following_ordinal,
                    'candidateKeyHash', public.analysis_order_audit_digest(candidate.username),
                    'isPrivate', candidate.is_private,
                    'isVerified', candidate.is_verified
                ) ORDER BY candidate.mutual_ordinal NULLS LAST, candidate.username
            )::TEXT
            FROM public.analysis_order_audit_candidates AS candidate
            WHERE candidate.request_id = v_bundle.request_id
              AND candidate.version = v_bundle.version
        ), '[]')) INTO v_relationship_bundle_checksum;
        v_relationship_bundle_complete := v_bundle.stage_status->>'relationships' = 'true'
            AND v_bundle.mutual_total = v_relationship_bundle_count;
    END IF;

    -- Target evidence parity excludes the candidate join key; it compares the stable evidence
    -- identity and content fields in the same order used by the permanent interaction copy.
    IF v_target_evidence_available THEN
        SELECT count(*)::INTEGER
          INTO v_target_source_count
          FROM public.analysis_target_interactors AS interaction
         WHERE interaction.request_id = p_request_id
           AND (
               v_target_evidence_job IS NULL
               OR interaction.job_key = v_target_evidence_job
           );
        SELECT public.analysis_order_audit_digest(COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'ordinal', interaction.ordinal,
                    'actorKeyHash', public.analysis_order_audit_digest(interaction.actor_username),
                    'postId', interaction.post_id,
                    'signal', interaction.signal,
                    'sourceInteractionId', interaction.source_interaction_id,
                    'occurredAt', interaction.occurred_at,
                    'commentText', interaction.comment_text,
                    'details', public.analysis_order_audit_redact_json(
                        NULLIF(pg_catalog.to_jsonb(interaction)->'details', 'null'::JSONB)
                    )
                ) ORDER BY interaction.ordinal, interaction.signal,
                    interaction.source_interaction_id
            )::TEXT
            FROM public.analysis_target_interactors AS interaction
            WHERE interaction.request_id = p_request_id
              AND (
                  v_target_evidence_job IS NULL
                  OR interaction.job_key = v_target_evidence_job
              )
        ), '[]')) INTO v_target_source_checksum;
        v_target_source_complete := v_target_evidence_job IS NOT NULL
            AND EXISTS (
                SELECT 1
                FROM public.analysis_v2_target_evidence_manifests AS manifest
                WHERE manifest.request_id = p_request_id
                  AND manifest.job_key = v_target_evidence_job
                  AND manifest.interactor_count = v_target_source_count
                  AND manifest.liker_count + manifest.comment_count = manifest.interactor_count
            );
    END IF;

    IF v_bundle_present THEN
        SELECT count(*)::INTEGER
          INTO v_target_bundle_count
          FROM public.analysis_order_audit_interactions AS interaction
         WHERE interaction.request_id = v_bundle.request_id
           AND interaction.version = v_bundle.version
           AND interaction.signal IN ('target_post_like', 'target_post_comment');
        SELECT public.analysis_order_audit_digest(COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'ordinal', interaction.ordinal,
                    'actorKeyHash', CASE
                        WHEN interaction.username IS NULL THEN NULL
                        ELSE public.analysis_order_audit_digest(interaction.username)
                    END,
                    'postId', interaction.source_post_id,
                    'signal', interaction.signal,
                    'sourceInteractionId', interaction.evidence_id,
                    'occurredAt', interaction.occurred_at,
                    'commentText', interaction.comment_text,
                    'details', interaction.details
                ) ORDER BY interaction.ordinal, interaction.signal, interaction.evidence_id
            )::TEXT
            FROM public.analysis_order_audit_interactions AS interaction
            WHERE interaction.request_id = v_bundle.request_id
              AND interaction.version = v_bundle.version
              AND interaction.signal IN ('target_post_like', 'target_post_comment')
        ), '[]')) INTO v_target_bundle_checksum;
        v_target_bundle_complete := v_bundle.stage_status->>'targetEvidence' = 'true'
            AND COALESCE(v_bundle.target_likes_collected, 0)
                + COALESCE(v_bundle.target_comments_collected, 0)
                = v_target_bundle_count;
    END IF;

    -- Candidate parity uses the stable Instagram-key set only. The key itself is hashed and never
    -- leaves the database; no username or candidate identifier appears in this result.
    IF v_candidate_available THEN
        WITH expected AS (
            SELECT DISTINCT mutual.username
            FROM public.analysis_v2_mutual_rows AS mutual
            WHERE mutual.request_id = p_request_id
              AND (
                  v_relationship_job IS NULL
                  OR mutual.job_key = v_relationship_job
              )
        ), observed AS (
            SELECT DISTINCT feature.instagram_id AS username
            FROM public.analysis_v2_candidate_feature_rows AS feature
            WHERE feature.request_id = p_request_id
            UNION
            SELECT DISTINCT private_name.instagram_id AS username
            FROM public.analysis_v2_private_name_rows AS private_name
            WHERE private_name.request_id = p_request_id
        )
        SELECT count(*)::INTEGER
          INTO v_candidate_source_count
          FROM observed;
        WITH expected AS (
            SELECT DISTINCT mutual.username
            FROM public.analysis_v2_mutual_rows AS mutual
            WHERE mutual.request_id = p_request_id
              AND (
                  v_relationship_job IS NULL
                  OR mutual.job_key = v_relationship_job
              )
        ), observed AS (
            SELECT DISTINCT feature.instagram_id AS username
            FROM public.analysis_v2_candidate_feature_rows AS feature
            WHERE feature.request_id = p_request_id
            UNION
            SELECT DISTINCT private_name.instagram_id AS username
            FROM public.analysis_v2_private_name_rows AS private_name
            WHERE private_name.request_id = p_request_id
        )
        SELECT public.analysis_order_audit_digest(COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object('candidateKey', observed.username)
                ORDER BY observed.username
            )::TEXT
            FROM observed
        ), '[]')) INTO v_candidate_source_checksum;
        v_candidate_source_complete := NOT EXISTS (
            WITH expected AS (
                SELECT DISTINCT mutual.username
                FROM public.analysis_v2_mutual_rows AS mutual
                WHERE mutual.request_id = p_request_id
                  AND (
                      v_relationship_job IS NULL
                      OR mutual.job_key = v_relationship_job
                  )
            ), observed AS (
                SELECT DISTINCT feature.instagram_id AS username
                FROM public.analysis_v2_candidate_feature_rows AS feature
                WHERE feature.request_id = p_request_id
                UNION
                SELECT DISTINCT private_name.instagram_id AS username
                FROM public.analysis_v2_private_name_rows AS private_name
                WHERE private_name.request_id = p_request_id
            )
            SELECT username FROM expected
            EXCEPT
            SELECT username FROM observed
        ) AND NOT EXISTS (
            WITH expected AS (
                SELECT DISTINCT mutual.username
                FROM public.analysis_v2_mutual_rows AS mutual
                WHERE mutual.request_id = p_request_id
                  AND (
                      v_relationship_job IS NULL
                      OR mutual.job_key = v_relationship_job
                  )
            ), observed AS (
                SELECT DISTINCT feature.instagram_id AS username
                FROM public.analysis_v2_candidate_feature_rows AS feature
                WHERE feature.request_id = p_request_id
                UNION
                SELECT DISTINCT private_name.instagram_id AS username
                FROM public.analysis_v2_private_name_rows AS private_name
                WHERE private_name.request_id = p_request_id
            )
            SELECT username FROM observed
            EXCEPT
            SELECT username FROM expected
        );
    END IF;

    IF v_bundle_present THEN
        SELECT count(*)::INTEGER
          INTO v_candidate_bundle_count
          FROM public.analysis_order_audit_candidates AS candidate
         WHERE candidate.request_id = v_bundle.request_id
           AND candidate.version = v_bundle.version;
        SELECT public.analysis_order_audit_digest(COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object('candidateKey', candidate.username)
                ORDER BY candidate.username
            )::TEXT
            FROM public.analysis_order_audit_candidates AS candidate
            WHERE candidate.request_id = v_bundle.request_id
              AND candidate.version = v_bundle.version
        ), '[]')) INTO v_candidate_bundle_checksum;
        v_candidate_bundle_complete := v_bundle.stage_status->>'candidateFeatures' = 'true'
            AND v_bundle.candidate_collected = v_candidate_bundle_count;
    END IF;

    -- Risk parity compares the common score projection and intentionally omits public copy text.
    IF v_risk_available THEN
        SELECT count(*)::INTEGER
          INTO v_risk_source_count
          FROM public.analysis_v2_candidate_score_rows AS score
         WHERE score.request_id = p_request_id;
        SELECT public.analysis_order_audit_digest(COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'candidateKey', score.candidate_id,
                    'publicScore', score.public_score,
                    'riskBand', score.risk_band,
                    'preScore', score.pre_score,
                    'rawScore', score.raw_score,
                    'featuredRank', score.featured_rank,
                    'recentMutualRank', score.recent_mutual_rank,
                    'components', public.analysis_order_audit_redact_json(score.components),
                    'partnerSafetyOperationKey', score.partner_safety_operation_key,
                    'partnerSafetyResultHash', score.partner_safety_result_hash
                ) ORDER BY score.candidate_id
            )::TEXT
            FROM public.analysis_v2_candidate_score_rows AS score
            WHERE score.request_id = p_request_id
        ), '[]')) INTO v_risk_source_checksum;
        v_risk_source_complete := EXISTS (
            SELECT 1
            FROM public.analysis_v2_candidate_score_manifests AS manifest
            WHERE manifest.request_id = p_request_id
              AND manifest.item_count = v_risk_source_count
        );
    END IF;

    IF v_bundle_present THEN
        SELECT count(*)::INTEGER
          INTO v_risk_bundle_count
          FROM public.analysis_order_audit_candidates AS candidate
         WHERE candidate.request_id = v_bundle.request_id
           AND candidate.version = v_bundle.version
           AND candidate.raw_score IS NOT NULL;
        SELECT public.analysis_order_audit_digest(COALESCE((
            SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'candidateKey', candidate.candidate_id,
                    'publicScore', candidate.public_score,
                    'riskBand', candidate.risk_band,
                    'preScore', candidate.pre_score,
                    'rawScore', candidate.raw_score,
                    'featuredRank', candidate.featured_rank,
                    'recentMutualRank', candidate.recent_mutual_rank,
                    'components', candidate.risk_components,
                    'partnerSafetyOperationKey', candidate.partner_safety_operation_key,
                    'partnerSafetyResultHash', candidate.partner_safety_result_hash
                ) ORDER BY candidate.candidate_id
            )::TEXT
            FROM public.analysis_order_audit_candidates AS candidate
            WHERE candidate.request_id = v_bundle.request_id
              AND candidate.version = v_bundle.version
              AND candidate.raw_score IS NOT NULL
        ), '[]')) INTO v_risk_bundle_checksum;
        v_risk_bundle_complete := v_bundle.stage_status->>'riskScores' = 'true';
    END IF;

    -- The cost rollup's immutable source hash is already persisted in the bundle stage metadata.
    IF v_cost_available THEN
        SELECT count(*)::INTEGER
          INTO v_cost_source_count
          FROM public.analysis_v2_cost_rollups AS rollup
         WHERE rollup.request_id = p_request_id;
        v_cost_source_checksum := public.analysis_order_audit_cost_source_hash(p_request_id);
        SELECT bool_and(
            COALESCE(rollup.directly_attributable_cost_complete, FALSE)
            AND NOT COALESCE(rollup.usage_unknown, TRUE)
        )
          INTO v_cost_source_complete
          FROM public.analysis_v2_cost_rollups AS rollup
         WHERE rollup.request_id = p_request_id;
    END IF;
    IF v_bundle_present THEN
        v_cost_bundle_count := CASE
            WHEN v_bundle.stage_status ? 'costSourceHash' THEN 1 ELSE 0 END;
        v_cost_bundle_checksum := NULLIF(v_bundle.stage_status->>'costSourceHash', '');
        v_cost_bundle_complete := v_bundle.cost_status = 'complete'
            AND v_bundle.stage_status->>'cost' = 'complete'
            AND v_cost_bundle_checksum IS NOT NULL;
    END IF;

    -- The terminal assembler captures this aggregate before it invokes the purge helper. Once
    -- working rows are gone, carry forward only the source side of sections that are absent live;
    -- the latest immutable bundle and any live cost rollup always remain authoritative for their
    -- bundle/cost fields. A prior incomplete attestation remains incomplete and cannot pass parity.
    IF v_parity_attestation IS NOT NULL THEN
        IF NOT v_relationship_available
           AND pg_catalog.jsonb_typeof(v_parity_attestation->'sections'->'relationships') = 'object' THEN
            v_relationship_source_count := NULLIF(
                v_parity_attestation->'sections'->'relationships'->>'sourceCount', ''
            )::INTEGER;
            v_relationship_source_checksum := NULLIF(
                v_parity_attestation->'sections'->'relationships'->>'sourceChecksum', ''
            );
            v_relationship_source_complete := NULLIF(
                v_parity_attestation->'sections'->'relationships'->>'sourceComplete', ''
            )::BOOLEAN;
            v_relationship_available := TRUE;
        END IF;
        IF NOT v_target_evidence_available
           AND pg_catalog.jsonb_typeof(v_parity_attestation->'sections'->'targetEvidence') = 'object' THEN
            v_target_source_count := NULLIF(
                v_parity_attestation->'sections'->'targetEvidence'->>'sourceCount', ''
            )::INTEGER;
            v_target_source_checksum := NULLIF(
                v_parity_attestation->'sections'->'targetEvidence'->>'sourceChecksum', ''
            );
            v_target_source_complete := NULLIF(
                v_parity_attestation->'sections'->'targetEvidence'->>'sourceComplete', ''
            )::BOOLEAN;
            v_target_evidence_available := TRUE;
        END IF;
        IF NOT v_candidate_available
           AND pg_catalog.jsonb_typeof(v_parity_attestation->'sections'->'candidates') = 'object' THEN
            v_candidate_source_count := NULLIF(
                v_parity_attestation->'sections'->'candidates'->>'sourceCount', ''
            )::INTEGER;
            v_candidate_source_checksum := NULLIF(
                v_parity_attestation->'sections'->'candidates'->>'sourceChecksum', ''
            );
            v_candidate_source_complete := NULLIF(
                v_parity_attestation->'sections'->'candidates'->>'sourceComplete', ''
            )::BOOLEAN;
            v_candidate_available := TRUE;
        END IF;
        IF NOT v_risk_available
           AND pg_catalog.jsonb_typeof(v_parity_attestation->'sections'->'risk') = 'object' THEN
            v_risk_source_count := NULLIF(
                v_parity_attestation->'sections'->'risk'->>'sourceCount', ''
            )::INTEGER;
            v_risk_source_checksum := NULLIF(
                v_parity_attestation->'sections'->'risk'->>'sourceChecksum', ''
            );
            v_risk_source_complete := NULLIF(
                v_parity_attestation->'sections'->'risk'->>'sourceComplete', ''
            )::BOOLEAN;
            v_risk_available := TRUE;
        END IF;
        IF NOT v_cost_available
           AND pg_catalog.jsonb_typeof(v_parity_attestation->'sections'->'costLedger') = 'object' THEN
            v_cost_source_count := NULLIF(
                v_parity_attestation->'sections'->'costLedger'->>'sourceCount', ''
            )::INTEGER;
            v_cost_source_checksum := NULLIF(
                v_parity_attestation->'sections'->'costLedger'->>'sourceChecksum', ''
            );
            v_cost_source_complete := NULLIF(
                v_parity_attestation->'sections'->'costLedger'->>'sourceComplete', ''
            )::BOOLEAN;
            v_cost_available := TRUE;
        END IF;
        v_source_data_present := v_source_data_present
            OR COALESCE(
                (v_parity_attestation->'request'->>'sourceDataPresent')::BOOLEAN,
                FALSE
            );
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'request', pg_catalog.jsonb_build_object(
            'completed', v_completed,
            'productionOrder', v_production_order,
            'sourceDataPresent', v_source_data_present
        ),
        'bundle', pg_catalog.jsonb_build_object(
            'present', v_bundle_present,
            'completeness', CASE WHEN v_bundle_present THEN v_bundle.completeness_status END,
            'costStatus', CASE WHEN v_bundle_present THEN v_bundle.cost_status END,
            'version', CASE WHEN v_bundle_present THEN v_bundle.version END
        ),
        'recovery', pg_catalog.jsonb_build_object(
            'present', v_recovery_present,
            'completed', v_recovery_completed
        ),
        'sections', pg_catalog.jsonb_build_object(
            'relationships', CASE WHEN v_relationship_available OR v_bundle_present THEN
                pg_catalog.jsonb_build_object(
                    'sourceCount', v_relationship_source_count,
                    'bundleCount', v_relationship_bundle_count,
                    'sourceChecksum', v_relationship_source_checksum,
                    'bundleChecksum', v_relationship_bundle_checksum,
                    'sourceComplete', v_relationship_source_complete,
                    'bundleComplete', v_relationship_bundle_complete
                ) END,
            'targetEvidence', CASE WHEN v_target_evidence_available OR v_bundle_present THEN
                pg_catalog.jsonb_build_object(
                    'sourceCount', v_target_source_count,
                    'bundleCount', v_target_bundle_count,
                    'sourceChecksum', v_target_source_checksum,
                    'bundleChecksum', v_target_bundle_checksum,
                    'sourceComplete', v_target_source_complete,
                    'bundleComplete', v_target_bundle_complete
                ) END,
            'candidates', CASE WHEN v_candidate_available OR v_bundle_present THEN
                pg_catalog.jsonb_build_object(
                    'sourceCount', v_candidate_source_count,
                    'bundleCount', v_candidate_bundle_count,
                    'sourceChecksum', v_candidate_source_checksum,
                    'bundleChecksum', v_candidate_bundle_checksum,
                    'sourceComplete', v_candidate_source_complete,
                    'bundleComplete', v_candidate_bundle_complete
                ) END,
            'risk', CASE WHEN v_risk_available OR v_bundle_present THEN
                pg_catalog.jsonb_build_object(
                    'sourceCount', v_risk_source_count,
                    'bundleCount', v_risk_bundle_count,
                    'sourceChecksum', v_risk_source_checksum,
                    'bundleChecksum', v_risk_bundle_checksum,
                    'sourceComplete', v_risk_source_complete,
                    'bundleComplete', v_risk_bundle_complete
                ) END,
            'costLedger', CASE WHEN v_cost_available OR v_bundle_present THEN
                pg_catalog.jsonb_build_object(
                    'sourceCount', v_cost_source_count,
                    'bundleCount', v_cost_bundle_count,
                    'sourceChecksum', v_cost_source_checksum,
                    'bundleChecksum', v_cost_bundle_checksum,
                    'sourceComplete', v_cost_source_complete,
                    'bundleComplete', v_cost_bundle_complete
                ) END
        )
    );
END;
$$;


--
-- Name: read_analysis_revenue_cost_reconciliation_v1(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_analysis_revenue_cost_reconciliation_v1(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE v_ledger public.analysis_revenue_run_ledgers%ROWTYPE; v_disposition TEXT;
BEGIN
    IF p_request_id IS NULL OR p_job_key IS DISTINCT FROM 'coordinator:finalize' OR p_claim_token IS NULL OR p_job_input_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT * INTO v_ledger FROM public.analysis_revenue_run_ledgers WHERE request_id = p_request_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE'; END IF;
    v_disposition := CASE WHEN v_ledger.economic_actual_krw > v_ledger.cost_cap_krw THEN 'hard_cap_exceeded' WHEN v_ledger.economic_actual_krw > v_ledger.margin_target_krw THEN 'negative_margin_pilot' ELSE 'within_margin_target' END;
    RETURN pg_catalog.jsonb_build_object('finalizable', FALSE, 'reason', 'not_ready', 'economicDisposition', v_disposition, 'economicActualKrw', v_ledger.economic_actual_krw, 'billedActualKrw', v_ledger.billed_actual_krw);
END; $_$;


--
-- Name: read_analysis_v2_betatest_free_pool_replay_source(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_analysis_v2_betatest_free_pool_replay_source(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_provider_runs JSONB;
    v_preflight_runs JSONB;
    v_provider_run_count INTEGER;
    v_preflight_run_count INTEGER;
BEGIN
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_BETATEST_FREE_POOL_SOURCE_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    JOIN public.analysis_preflights AS preflight
      ON preflight.id = request.preflight_id
    JOIN public.analysis_v2_result_summaries AS result_summary
      ON result_summary.request_id = request.id
    JOIN public.analysis_v2_provider_execution_policies AS execution_policy
      ON execution_policy.request_id = request.id
    WHERE request.id = p_request_id
      AND request.status = 'completed'
      AND request.completed_at IS NOT NULL
      AND request.pipeline_version = 'v2'
      AND request.selected_plan_id_snapshot = 'standard'
      AND request.plan_access_mode_snapshot = 'production'
      AND request.test_entitlement_jti_hash IS NULL
      AND request.analysis_entry_channel = 'betatest'
      AND request.policy_versions_snapshot =
          '{"pipeline":"v2","risk":"risk-policy-v2.5","aiStage":"ai-stage-policy-v2.10","scheduler":"ai-scheduler-v1"}'::JSONB
      AND preflight.user_id = request.user_id
      AND preflight.status = 'consumed'
      AND preflight.access_mode = 'production'
      AND preflight.analysis_entry_channel = 'betatest'
      AND preflight.beta_entry_provenance = 'betatest_service_v1'
      AND preflight.consumed_request_id = request.id
      AND preflight.policy_versions_snapshot = request.policy_versions_snapshot
      AND preflight.pii_scrubbed_at IS NOT NULL
      AND preflight.target_instagram_id = 'retained.' || pg_catalog.substr(
          pg_catalog.replace(preflight.id::TEXT, '-', ''), 1, 20
      )
      AND preflight.target_full_name IS NULL
      AND preflight.target_bio IS NULL
      AND preflight.target_profile_image_url IS NULL
      AND preflight.exclusion_decision = 'skip'
      AND preflight.excluded_instagram_id IS NULL
      AND result_summary.plan_id = 'standard'
      AND result_summary.score_policy_version = 'risk-policy-v2.5'
      AND execution_policy.mode = 'betatest_free_pool'
      AND execution_policy.policy_version = 'betatest-free-pool-v1'
      AND execution_policy.entitlement_jti_hash IS NULL
      AND public.analysis_beta_valid_operation_slot_map(execution_policy.operation_slot_map)
      AND execution_policy.operation_slot_map ?& ARRAY[
          'target-profile', 'relationship-followers', 'relationship-following',
          'profile-fallback', 'profile-repair', 'target-likers',
          'target-comments', 'candidate-likers'
      ]
      AND NOT EXISTS (
          SELECT 1 FROM pg_catalog.jsonb_each_text(execution_policy.operation_slot_map)
          AS slot_map(operation_family, credential_slot)
          WHERE credential_slot = 'secondary'
      )
      -- Completed request targets are intentionally scrubbed to `retained.*`.
      -- Do not recover or compare the execution-policy target here; its exact
      -- persisted beta-free mode/version/map is the surviving replay evidence.
      ;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_BETATEST_FREE_POOL_SOURCE_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight WHERE preflight.id = v_request.preflight_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_BETATEST_FREE_POOL_SOURCE_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.count(*) INTO v_provider_run_count
    FROM public.analysis_v2_provider_runs AS provider_run WHERE provider_run.request_id = v_request.id;
    SELECT pg_catalog.count(*) INTO v_preflight_run_count
    FROM public.analysis_preflight_provider_runs AS provider_run WHERE provider_run.preflight_id = v_preflight.id;
    IF v_provider_run_count NOT BETWEEN 1 AND 128
       OR v_preflight_run_count NOT BETWEEN 1 AND 4
       OR EXISTS (
          SELECT 1
          FROM public.analysis_v2_provider_runs AS provider_run
          JOIN public.analysis_v2_provider_execution_policies AS execution_policy
            ON execution_policy.request_id = provider_run.request_id
          WHERE provider_run.request_id = v_request.id
            AND (provider_run.logical_provider <> 'apify'
              OR provider_run.status <> 'succeeded'
              OR provider_run.run_id IS NULL
              OR provider_run.terminalized_at IS NULL
              OR provider_run.actual_usage_usd IS NULL
              OR provider_run.usage_reconciled_at IS NULL
              OR provider_run.credential_slot = 'secondary'
              OR provider_run.credential_slot IS DISTINCT FROM execution_policy.operation_slot_map ->> pg_catalog.split_part(provider_run.operation_key, ':', 1))
       )
       OR EXISTS (
          SELECT 1
          FROM public.analysis_preflight_provider_runs AS provider_run
          JOIN public.analysis_v2_provider_execution_policies AS execution_policy
            ON execution_policy.request_id = v_request.id
          WHERE provider_run.preflight_id = v_preflight.id
            AND (provider_run.logical_provider <> 'apify'
              OR provider_run.status <> 'succeeded'
              OR provider_run.run_id IS NULL
              OR provider_run.terminalized_at IS NULL
              OR provider_run.actual_usage_usd IS NULL
              OR provider_run.usage_reconciled_at IS NULL
              OR provider_run.credential_slot = 'secondary'
              OR provider_run.credential_slot IS DISTINCT FROM execution_policy.operation_slot_map ->> 'target-profile')
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_BETATEST_FREE_POOL_PROVIDER_LEDGER_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'actorId', run.actor_id, 'credentialSlot', run.credential_slot,
        'runId', run.run_id, 'status', run.status, 'operationKey', run.operation_key
    ) ORDER BY run.job_key, run.operation_key) INTO v_provider_runs
    FROM public.analysis_v2_provider_runs AS run WHERE run.request_id = v_request.id;
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'actorId', run.actor_id, 'credentialSlot', run.credential_slot,
        'runId', run.run_id, 'status', run.status, 'operationKey', run.operation_key
    ) ORDER BY run.operation_key) INTO v_preflight_runs
    FROM public.analysis_preflight_provider_runs AS run WHERE run.preflight_id = v_preflight.id;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', v_request.id,
        'preflightId', v_preflight.id,
        'targetUsername', 'replay_' || pg_catalog.substr(pg_catalog.md5(v_request.id::TEXT || ':' || v_preflight.id::TEXT), 1, 23),
        'selectedPlanId', 'standard',
        'policyVersions', v_request.policy_versions_snapshot,
        'preflightRuns', v_preflight_runs,
        'providerRuns', v_provider_runs
    );
END;
$$;


--
-- Name: read_analysis_v2_current_production_replay_source(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_analysis_v2_current_production_replay_source(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_provider_runs JSONB;
    v_preflight_runs JSONB;
    v_provider_run_count INTEGER;
    v_preflight_run_count INTEGER;
BEGIN
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REPLAY_CURRENT_PRODUCTION_SOURCE_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    SELECT request.*
    INTO v_request
    FROM public.analysis_requests AS request
    JOIN public.analysis_preflights AS preflight
      ON preflight.id = request.preflight_id
    JOIN public.earlybird_orders AS earlybird_order
      ON earlybird_order.preflight_id = preflight.id
     AND earlybird_order.result_request_id = request.id
    JOIN public.earlybird_fulfillments AS fulfillment
      ON fulfillment.order_id = earlybird_order.id
     AND fulfillment.request_id = request.id
    JOIN public.analysis_v2_result_summaries AS result_summary
      ON result_summary.request_id = request.id
    WHERE request.id = p_request_id
      AND request.status = 'completed'
      AND request.completed_at IS NOT NULL
      AND request.pipeline_version = 'v2'
      AND request.selected_plan_id_snapshot = 'standard'
      AND request.plan_access_mode_snapshot = 'production'
      AND request.test_entitlement_jti_hash IS NULL
      AND request.policy_versions_snapshot =
          '{"pipeline":"v2","risk":"risk-policy-v2.5","aiStage":"ai-stage-policy-v2.10","scheduler":"ai-scheduler-v1"}'::JSONB
      AND preflight.user_id = request.user_id
      AND preflight.status = 'consumed'
      AND preflight.access_mode = 'production'
      AND preflight.consumed_request_id = request.id
      AND preflight.policy_versions_snapshot = request.policy_versions_snapshot
      AND preflight.pii_scrubbed_at IS NOT NULL
      AND preflight.target_instagram_id = 'retained.'
          || pg_catalog.substr(
              pg_catalog.replace(preflight.id::TEXT, '-', ''),
              1,
              20
          )
      AND preflight.target_full_name IS NULL
      AND preflight.target_bio IS NULL
      AND preflight.target_profile_image_url IS NULL
      AND preflight.exclusion_decision = 'skip'
      AND preflight.excluded_instagram_id IS NULL
      AND earlybird_order.user_id = request.user_id
      AND earlybird_order.plan_id = 'standard'
      AND earlybird_order.status = 'completed'
      AND earlybird_order.payment_id IS NOT NULL
      AND earlybird_order.paid_at IS NOT NULL
      AND earlybird_order.seller_reference_confirmed_at IS NOT NULL
      AND earlybird_order.actual_groble_product_id
          IS NOT DISTINCT FROM earlybird_order.expected_groble_product_id
      AND earlybird_order.actual_amount_krw IS NOT NULL
      AND earlybird_order.actual_amount_krw > 0
      AND earlybird_order.actual_amount_krw <= earlybird_order.expected_amount_krw
      AND fulfillment.status = 'completed'
      AND fulfillment.completed_at IS NOT NULL
      AND result_summary.plan_id = 'standard'
      AND result_summary.score_policy_version = 'risk-policy-v2.5'
      AND (
          SELECT pg_catalog.count(*)
          FROM public.earlybird_webhook_events AS payment_event
          WHERE payment_event.order_id = earlybird_order.id
            AND payment_event.event_type = 'payment.completed'
            AND payment_event.disposition = 'accepted'
            AND payment_event.payment_id = earlybird_order.payment_id
            AND payment_event.product_id = earlybird_order.actual_groble_product_id
            AND payment_event.amount_krw = earlybird_order.actual_amount_krw
      ) = 1;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REPLAY_CURRENT_PRODUCTION_SOURCE_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_request.preflight_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REPLAY_CURRENT_PRODUCTION_SOURCE_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.count(*) INTO v_provider_run_count
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = v_request.id;
    IF v_provider_run_count NOT BETWEEN 1 AND 128
       OR EXISTS (
          SELECT 1 FROM public.analysis_v2_provider_runs AS provider_run
          WHERE provider_run.request_id = v_request.id
            AND (
                provider_run.logical_provider <> 'apify'
                OR provider_run.status <> 'succeeded'
                OR provider_run.run_id IS NULL
                OR provider_run.terminalized_at IS NULL
                OR provider_run.actual_usage_usd IS NULL
                OR provider_run.usage_reconciled_at IS NULL
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REPLAY_CURRENT_PRODUCTION_PROVIDER_LEDGER_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.count(*) INTO v_preflight_run_count
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = v_preflight.id;
    IF v_preflight_run_count NOT BETWEEN 1 AND 4
       OR EXISTS (
          SELECT 1 FROM public.analysis_preflight_provider_runs AS provider_run
          WHERE provider_run.preflight_id = v_preflight.id
            AND (
                provider_run.logical_provider <> 'apify'
                OR provider_run.status <> 'succeeded'
                OR provider_run.run_id IS NULL
                OR provider_run.terminalized_at IS NULL
                OR provider_run.actual_usage_usd IS NULL
                OR provider_run.usage_reconciled_at IS NULL
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REPLAY_CURRENT_PRODUCTION_PROVIDER_LEDGER_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'actorId', run.actor_id,
        'credentialSlot', run.credential_slot,
        'runId', run.run_id,
        'status', run.status,
        'operationKey', run.operation_key
    ) ORDER BY run.job_key, run.operation_key)
    INTO v_provider_runs
    FROM public.analysis_v2_provider_runs AS run
    WHERE run.request_id = v_request.id;

    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'actorId', run.actor_id,
        'credentialSlot', run.credential_slot,
        'runId', run.run_id,
        'status', run.status,
        'operationKey', run.operation_key
    ) ORDER BY run.operation_key)
    INTO v_preflight_runs
    FROM public.analysis_preflight_provider_runs AS run
    WHERE run.preflight_id = v_preflight.id;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', v_request.id,
        'preflightId', v_preflight.id,
        'targetUsername', 'replay_' || pg_catalog.substr(pg_catalog.md5(
            v_request.id::TEXT || ':' || v_preflight.id::TEXT
        ), 1, 23),
        'selectedPlanId', 'standard',
        'policyVersions', v_request.policy_versions_snapshot,
        'preflightRuns', v_preflight_runs,
        'providerRuns', v_provider_runs
    );
END;
$$;


--
-- Name: read_analysis_v2_historical_official_e2e_replay_source(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_analysis_v2_historical_official_e2e_replay_source(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_provider_runs JSONB;
    v_preflight_runs JSONB;
BEGIN
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_HISTORICAL_SOURCE_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    JOIN public.analysis_v2_test_entitlement_consumptions AS entitlement_consumption
      ON entitlement_consumption.request_id = request.id
    JOIN public.analysis_preflights AS preflight
      ON preflight.id = entitlement_consumption.preflight_id
    WHERE request.id = p_request_id
      AND request.status = 'completed'
      AND request.pipeline_version = 'v2'
      AND request.selected_plan_id_snapshot = 'standard'
      AND request.plan_access_mode_snapshot = 'test_entitlement'
      AND request.preflight_id = preflight.id
      AND request.completed_at IS NOT NULL
      AND request.test_entitlement_jti_hash = entitlement_consumption.entitlement_jti_hash
      AND entitlement_consumption.user_id = request.user_id
      AND entitlement_consumption.selected_plan_id = 'standard'
      AND preflight.user_id = request.user_id
      AND preflight.status = 'consumed'
      AND preflight.access_mode = 'test_entitlement'
      AND preflight.consumed_request_id = request.id
      AND preflight.target_is_private IS FALSE
      AND request.policy_versions_snapshot = '{"pipeline":"v2","risk":"risk-policy-v2.3","aiStage":"ai-stage-policy-v2.7"}'::JSONB
      AND preflight.policy_versions_snapshot = request.policy_versions_snapshot;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_HISTORICAL_SOURCE_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_request.preflight_id
      AND preflight.status = 'consumed'
      AND preflight.access_mode = 'test_entitlement'
      AND preflight.consumed_request_id = v_request.id
      AND preflight.user_id = v_request.user_id
      AND preflight.target_is_private IS FALSE
      AND preflight.policy_versions_snapshot = v_request.policy_versions_snapshot;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_HISTORICAL_SOURCE_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'actorId', run.actor_id, 'credentialSlot', run.credential_slot,
        'runId', run.run_id, 'status', run.status, 'operationKey', run.operation_key
    ) ORDER BY run.job_key, run.operation_key), '[]'::JSONB) INTO v_provider_runs
    FROM (
        SELECT provider_run.* FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = v_request.id
          AND provider_run.logical_provider = 'apify'
          AND provider_run.status = 'succeeded' AND provider_run.run_id IS NOT NULL
        ORDER BY provider_run.job_key, provider_run.operation_key LIMIT 128
    ) AS run;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'actorId', run.actor_id, 'credentialSlot', run.credential_slot,
        'runId', run.run_id, 'status', run.status, 'operationKey', run.operation_key
    ) ORDER BY run.operation_key), '[]'::JSONB) INTO v_preflight_runs
    FROM (
        SELECT provider_run.* FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.preflight_id = v_preflight.id
          AND provider_run.logical_provider = 'apify'
          AND provider_run.status = 'succeeded' AND provider_run.run_id IS NOT NULL
        ORDER BY provider_run.operation_key LIMIT 4
    ) AS run;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', v_request.id,
        'preflightId', v_preflight.id,
        'targetUsername', 'replay_' || pg_catalog.substr(pg_catalog.md5(
            v_request.id::TEXT || ':' || v_preflight.id::TEXT
        ), 1, 23),
        'selectedPlanId', 'standard',
        'policyVersions', v_request.policy_versions_snapshot,
        'target', pg_catalog.jsonb_build_object(
            'fullName', v_preflight.target_full_name, 'bio', v_preflight.target_bio,
            'profileImageUrl', v_preflight.target_profile_image_url,
            'followersCount', v_preflight.target_followers_count,
            'followingCount', v_preflight.target_following_count
        ),
        'preflightRuns', v_preflight_runs,
        'providerRuns', v_provider_runs
    );
END;
$$;


--
-- Name: read_analysis_v2_replay_capture_source(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_analysis_v2_replay_capture_source(p_target_username text, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_target TEXT;
    v_request public.analysis_requests%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_provider_runs JSONB;
    v_preflight_runs JSONB;
BEGIN
    v_target := pg_catalog.lower(pg_catalog.btrim(p_target_username));
    IF v_target IS NULL OR v_target !~ '^[a-z0-9._]{1,30}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_SOURCE_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    WHERE pg_catalog.lower(request.target_instagram_id) = v_target
      AND (p_request_id IS NULL OR request.id = p_request_id)
      AND request.status = 'completed'
      AND request.pipeline_version = 'v2'
      AND request.selected_plan_id_snapshot = 'standard'
      AND request.plan_access_mode_snapshot = 'production'
      AND request.preflight_id IS NOT NULL
      AND request.completed_at IS NOT NULL
      AND request.policy_versions_snapshot =
          '{"pipeline":"v2","risk":"risk-policy-v2.4","aiStage":"ai-stage-policy-v2.9","scheduler":"ai-scheduler-v1"}'::JSONB
    ORDER BY request.completed_at DESC, request.id DESC
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN public.read_analysis_v2_replay_capture_source_v28_legacy(
            p_target_username, p_request_id
        );
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_request.preflight_id
      AND preflight.status = 'consumed'
      AND preflight.access_mode = 'production'
      AND preflight.consumed_request_id = v_request.id
      AND preflight.target_instagram_id = v_target
      AND preflight.target_is_private IS FALSE
      AND preflight.policy_versions_snapshot = v_request.policy_versions_snapshot;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_SOURCE_PREFLIGHT_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'actorId', run.actor_id, 'credentialSlot', run.credential_slot,
        'runId', run.run_id, 'status', run.status, 'operationKey', run.operation_key
    ) ORDER BY run.job_key, run.operation_key), '[]'::JSONB) INTO v_provider_runs
    FROM (
        SELECT provider_run.* FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = v_request.id
          AND provider_run.logical_provider = 'apify'
          AND provider_run.status = 'succeeded' AND provider_run.run_id IS NOT NULL
        ORDER BY provider_run.job_key, provider_run.operation_key LIMIT 128
    ) AS run;
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'actorId', run.actor_id, 'credentialSlot', run.credential_slot,
        'runId', run.run_id, 'status', run.status, 'operationKey', run.operation_key
    ) ORDER BY run.operation_key), '[]'::JSONB) INTO v_preflight_runs
    FROM (
        SELECT provider_run.* FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.preflight_id = v_preflight.id
          AND provider_run.logical_provider = 'apify'
          AND provider_run.status = 'succeeded' AND provider_run.run_id IS NOT NULL
        ORDER BY provider_run.operation_key LIMIT 4
    ) AS run;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', v_request.id, 'preflightId', v_preflight.id,
        'targetUsername', v_target, 'selectedPlanId', v_request.selected_plan_id_snapshot,
        'policyVersions', v_request.policy_versions_snapshot,
        'target', pg_catalog.jsonb_build_object(
            'fullName', v_preflight.target_full_name, 'bio', v_preflight.target_bio,
            'profileImageUrl', v_preflight.target_profile_image_url,
            'followersCount', v_preflight.target_followers_count,
            'followingCount', v_preflight.target_following_count
        ),
        'preflightRuns', v_preflight_runs, 'providerRuns', v_provider_runs
    );
END;
$_$;


--
-- Name: read_analysis_v2_replay_capture_source_v28_legacy(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_analysis_v2_replay_capture_source_v28_legacy(p_target_username text, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_target TEXT;
    v_request public.analysis_requests%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_summary public.analysis_v2_result_summaries%ROWTYPE;
    v_standard_card JSONB;
    v_standard_followers INTEGER;
    v_standard_following INTEGER;
    v_standard_detailed_limit INTEGER;
    v_provider_runs JSONB;
    v_preflight_runs JSONB;
BEGIN
    v_target := pg_catalog.lower(pg_catalog.btrim(p_target_username));
    IF v_target IS NULL OR v_target !~ '^[a-z0-9._]{1,30}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_SOURCE_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    WHERE pg_catalog.lower(request.target_instagram_id) = v_target
      AND (p_request_id IS NULL OR request.id = p_request_id)
      AND request.status = 'completed'
      AND request.pipeline_version = 'v2'
      AND request.plan_access_mode_snapshot = 'production'
      AND request.preflight_id IS NOT NULL
      AND request.completed_at IS NOT NULL
      AND (
          (
              request.selected_plan_id_snapshot = 'standard'
              AND request.policy_versions_snapshot IN (
                  '{"pipeline":"v2","risk":"risk-policy-v2.3","aiStage":"ai-stage-policy-v2.7"}'::JSONB,
                  '{"pipeline":"v2","risk":"risk-policy-v2.4","aiStage":"ai-stage-policy-v2.7"}'::JSONB,
                  '{"pipeline":"v2","risk":"risk-policy-v2.3","aiStage":"ai-stage-policy-v2.7","scheduler":"ai-scheduler-v1"}'::JSONB,
                  '{"pipeline":"v2","risk":"risk-policy-v2.4","aiStage":"ai-stage-policy-v2.7","scheduler":"ai-scheduler-v1"}'::JSONB,
                  '{"pipeline":"v2","risk":"risk-policy-v2.4","aiStage":"ai-stage-policy-v2.8","scheduler":"ai-scheduler-v1"}'::JSONB
              )
          )
          OR (
              request.selected_plan_id_snapshot = 'plus'
              AND request.policy_versions_snapshot =
                  '{"pipeline":"v2","risk":"risk-policy-v2.2","aiStage":"ai-stage-policy-v2.4"}'::JSONB
          )
      )
    ORDER BY request.completed_at DESC, request.id DESC
    LIMIT 1;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_SOURCE_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_request.preflight_id
      AND preflight.status = 'consumed'
      AND preflight.access_mode = 'production'
      AND preflight.consumed_request_id = v_request.id
      AND preflight.target_instagram_id = v_target
      AND preflight.target_is_private IS FALSE
      AND preflight.policy_versions_snapshot = v_request.policy_versions_snapshot;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_SOURCE_PREFLIGHT_MISMATCH', ERRCODE = 'P0001';
    END IF;

    IF v_request.selected_plan_id_snapshot = 'plus' THEN
        v_standard_card := v_preflight.plan_cards_snapshot->'standard';
        IF pg_catalog.jsonb_typeof(v_standard_card) <> 'object'
           OR v_standard_card->>'launchStatus' <> 'production'
           OR pg_catalog.jsonb_typeof(v_standard_card->'relationshipCapacity') <> 'object'
           OR v_standard_card->'relationshipCapacity'->>'followers' !~ '^[0-9]+$'
           OR v_standard_card->'relationshipCapacity'->>'following' !~ '^[0-9]+$'
           OR v_standard_card->>'detailedMutualLimit' !~ '^[0-9]+$' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_SOURCE_WORKLOAD_MISMATCH', ERRCODE = 'P0001';
        END IF;
        v_standard_followers := (v_standard_card->'relationshipCapacity'->>'followers')::INTEGER;
        v_standard_following := (v_standard_card->'relationshipCapacity'->>'following')::INTEGER;
        v_standard_detailed_limit := (v_standard_card->>'detailedMutualLimit')::INTEGER;
        IF v_standard_followers < 1 OR v_standard_following < 1 OR v_standard_detailed_limit < 1
           OR v_preflight.target_followers_count IS NULL OR v_preflight.target_following_count IS NULL
           OR v_preflight.target_followers_count > v_standard_followers
           OR v_preflight.target_following_count > v_standard_following THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_SOURCE_WORKLOAD_MISMATCH', ERRCODE = 'P0001';
        END IF;
        SELECT summary.* INTO v_summary
        FROM public.analysis_v2_result_summaries AS summary
        WHERE summary.request_id = v_request.id
          AND summary.target_instagram_id = v_target
          AND summary.plan_id = v_request.selected_plan_id_snapshot
          AND summary.score_policy_version = v_request.policy_versions_snapshot->>'risk'
          AND summary.followers_declared = v_preflight.target_followers_count
          AND summary.following_declared = v_preflight.target_following_count
          AND summary.public_mutuals <= v_standard_detailed_limit
          AND summary.screened_mutuals <= v_standard_detailed_limit;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_SOURCE_WORKLOAD_MISMATCH', ERRCODE = 'P0001';
        END IF;
    END IF;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'actorId', run.actor_id, 'credentialSlot', run.credential_slot,
        'runId', run.run_id, 'status', run.status, 'operationKey', run.operation_key
    ) ORDER BY run.job_key, run.operation_key), '[]'::JSONB) INTO v_provider_runs
    FROM (
        SELECT provider_run.* FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = v_request.id
          AND provider_run.logical_provider = 'apify'
          AND provider_run.status = 'succeeded' AND provider_run.run_id IS NOT NULL
        ORDER BY provider_run.job_key, provider_run.operation_key LIMIT 128
    ) AS run;
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'actorId', run.actor_id, 'credentialSlot', run.credential_slot,
        'runId', run.run_id, 'status', run.status, 'operationKey', run.operation_key
    ) ORDER BY run.operation_key), '[]'::JSONB) INTO v_preflight_runs
    FROM (
        SELECT provider_run.* FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.preflight_id = v_preflight.id
          AND provider_run.logical_provider = 'apify'
          AND provider_run.status = 'succeeded' AND provider_run.run_id IS NOT NULL
        ORDER BY provider_run.operation_key LIMIT 4
    ) AS run;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', v_request.id, 'preflightId', v_preflight.id,
        'targetUsername', v_target, 'selectedPlanId', v_request.selected_plan_id_snapshot,
        'policyVersions', v_request.policy_versions_snapshot,
        'target', pg_catalog.jsonb_build_object(
            'fullName', v_preflight.target_full_name, 'bio', v_preflight.target_bio,
            'profileImageUrl', v_preflight.target_profile_image_url,
            'followersCount', v_preflight.target_followers_count,
            'followingCount', v_preflight.target_following_count
        ),
        'preflightRuns', v_preflight_runs, 'providerRuns', v_provider_runs
    );
END;
$_$;


--
-- Name: read_analysis_v2_test_entitlement_v211_legacy_secondary_source(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_analysis_v2_test_entitlement_v211_legacy_secondary_source(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_provider_runs JSONB;
    v_preflight_runs JSONB;
BEGIN
    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    JOIN public.analysis_preflights AS preflight
      ON preflight.id = request.preflight_id
    JOIN public.analysis_v2_result_summaries AS result_summary
      ON result_summary.request_id = request.id
    WHERE request.id = p_request_id
      AND request.status = 'completed'
      AND request.completed_at IS NOT NULL
      AND request.pipeline_version = 'v2'
      AND request.selected_plan_id_snapshot = 'standard'
      AND request.plan_access_mode_snapshot = 'test_entitlement'
      AND request.analysis_entry_channel = 'standard'
      AND request.test_entitlement_jti_hash IS NOT NULL
      AND request.policy_versions_snapshot =
          '{"pipeline":"v2","risk":"risk-policy-v2.5","aiStage":"ai-stage-policy-v2.10","scheduler":"ai-scheduler-v1"}'::JSONB
      AND preflight.user_id = request.user_id
      AND preflight.status = 'consumed'
      AND preflight.access_mode = 'test_entitlement'
      AND preflight.analysis_entry_channel = 'standard'
      AND preflight.consumed_request_id = request.id
      AND preflight.policy_versions_snapshot = request.policy_versions_snapshot
      AND preflight.pii_scrubbed_at IS NOT NULL
      AND preflight.target_instagram_id = 'retained.' || pg_catalog.substr(
          pg_catalog.replace(preflight.id::TEXT, '-', ''), 1, 20
      )
      AND preflight.target_full_name IS NULL
      AND preflight.target_bio IS NULL
      AND preflight.target_profile_image_url IS NULL
      AND preflight.exclusion_decision = 'skip'
      AND preflight.excluded_instagram_id IS NULL
      AND result_summary.plan_id = 'standard'
      AND result_summary.score_policy_version = 'risk-policy-v2.5';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_V211_MAINTENANCE_SOURCE_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_request.preflight_id;

    IF (
        SELECT pg_catalog.count(*)
        FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = v_request.id
    ) NOT BETWEEN 1 AND 128 OR (
        SELECT pg_catalog.count(*)
        FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.preflight_id = v_preflight.id
    ) NOT BETWEEN 1 AND 4 OR EXISTS (
        SELECT 1 FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = v_request.id
          AND (provider_run.logical_provider <> 'apify'
            OR provider_run.status <> 'succeeded'
            OR provider_run.run_id IS NULL
            OR provider_run.terminalized_at IS NULL
            OR provider_run.actual_usage_usd IS NULL
            OR provider_run.usage_reconciled_at IS NULL
            OR provider_run.credential_slot NOT IN (
            'secondary'
            ))
    ) OR EXISTS (
        SELECT 1 FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.preflight_id = v_preflight.id
          AND (provider_run.logical_provider <> 'apify'
            OR provider_run.status <> 'succeeded'
            OR provider_run.run_id IS NULL
            OR provider_run.terminalized_at IS NULL
            OR provider_run.actual_usage_usd IS NULL
            OR provider_run.usage_reconciled_at IS NULL
            OR provider_run.credential_slot NOT IN (
            'secondary'
            ))
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_V211_MAINTENANCE_PROVIDER_LEDGER_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'actorId', run.actor_id, 'credentialSlot', run.credential_slot,
        'runId', run.run_id, 'status', run.status, 'operationKey', run.operation_key
    ) ORDER BY run.job_key, run.operation_key) INTO v_provider_runs
    FROM public.analysis_v2_provider_runs AS run WHERE run.request_id = v_request.id;
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'actorId', run.actor_id, 'credentialSlot', run.credential_slot,
        'runId', run.run_id, 'status', run.status, 'operationKey', run.operation_key
    ) ORDER BY run.operation_key) INTO v_preflight_runs
    FROM public.analysis_preflight_provider_runs AS run WHERE run.preflight_id = v_preflight.id;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', v_request.id,
        'preflightId', v_preflight.id,
        'targetUsername', 'replay_' || pg_catalog.substr(pg_catalog.md5(v_request.id::TEXT || ':' || v_preflight.id::TEXT), 1, 23),
        'selectedPlanId', 'standard',
        'policyVersions', v_request.policy_versions_snapshot,
        'preflightRuns', v_preflight_runs,
        'providerRuns', v_provider_runs,
        'originalFemaleRows', COALESCE((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'candidateId', female.candidate_id,
                'sortOrdinal', female.sort_ordinal,
                'instagramId', female.instagram_id,
                'fullName', female.full_name,
                'profileImageUrl', female.profile_image_url,
                'bio', female.bio,
                'displayScore', female.display_score,
                'riskBand', female.risk_band,
                'featuredRank', female.featured_rank,
                'recentMutualRank', female.recent_mutual_rank,
                'analysisDepth', female.analysis_depth,
                'oneLineOverview', female.one_line_overview,
                'highRiskNarrative', CASE WHEN female.narrative_line_one IS NULL THEN NULL
                    ELSE pg_catalog.jsonb_build_array(female.narrative_line_one, female.narrative_line_two)
                END
            ) ORDER BY female.sort_ordinal, female.candidate_id)
            FROM public.analysis_v2_female_results AS female
            WHERE female.request_id = v_request.id
        ), '[]'::JSONB),
        'currentRevision', COALESCE((
            SELECT revision.revision_number
            FROM public.analysis_v2_result_revisions AS revision
            WHERE revision.request_id = v_request.id AND revision.state = 'published'
        ), 0),
        'sourceFingerprint', public.analysis_v2_v211_maintenance_source_fingerprint(v_request.id)
    );
END;
$$;


--
-- Name: read_analysis_v2_test_entitlement_v211_text_only_source(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_analysis_v2_test_entitlement_v211_text_only_source(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_source JSONB; v_summary public.analysis_v2_result_summaries%ROWTYPE;
BEGIN
    v_source := public.read_analysis_v2_test_entitlement_v211_legacy_secondary_source(p_request_id);
    SELECT summary.* INTO v_summary FROM public.analysis_v2_result_summaries AS summary
    WHERE summary.request_id = p_request_id;
    IF v_summary.request_id IS NULL
       OR v_summary.male_count IS NULL OR v_summary.female_count IS NULL OR v_summary.unknown_count IS NULL
       OR v_summary.male_count + v_summary.female_count + v_summary.unknown_count <> v_summary.screened_mutuals THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_V211_TEXT_ONLY_COUNTS_INVALID', ERRCODE = 'P0001';
    END IF;
    RETURN v_source || pg_catalog.jsonb_build_object('canonicalCounts', pg_catalog.jsonb_build_object(
        'male', v_summary.male_count, 'female', v_summary.female_count, 'unknown', v_summary.unknown_count
    ));
END; $$;


--
-- Name: read_anonymous_analysis_v2_preflight(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_anonymous_analysis_v2_preflight(p_preflight_id uuid, p_claim_token_hash character varying) RETURNS SETOF public.analysis_preflights
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
    SELECT preflight.*
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id IS NULL
      AND preflight.claim_token_hash = p_claim_token_hash
      AND preflight.claim_expires_at > pg_catalog.clock_timestamp();
$$;


--
-- Name: read_anonymous_analysis_v2_preflight_public(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_anonymous_analysis_v2_preflight_public(p_preflight_id uuid, p_claim_token_hash character varying) RETURNS TABLE(id uuid, status text, expires_at timestamp with time zone, error_code text, target_instagram_id character varying, target_full_name character varying, target_bio character varying, target_followers_count integer, target_following_count integer, target_is_private boolean, access_mode text, launch_status_snapshot jsonb, capacity_required_plan_id text, required_plan_id text, plan_cards_snapshot jsonb, pricing_version character varying, pricing_snapshot jsonb, exclusion_decision text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
BEGIN
    IF p_preflight_id IS NULL OR p_claim_token_hash !~ '^[0-9a-f]{64}$' THEN
        RETURN;
    END IF;
    PERFORM pg_catalog.set_config(
        'app.anonymous_preflight_claim_hash', p_claim_token_hash, TRUE
    );
    RETURN QUERY
    SELECT
        preflight.id,
        preflight.status,
        preflight.expires_at,
        preflight.error_code,
        preflight.target_instagram_id,
        preflight.target_full_name,
        preflight.target_bio,
        preflight.target_followers_count,
        preflight.target_following_count,
        preflight.target_is_private,
        preflight.access_mode,
        preflight.launch_status_snapshot,
        preflight.capacity_required_plan_id,
        preflight.required_plan_id,
        preflight.plan_cards_snapshot,
        preflight.pricing_version,
        preflight.pricing_snapshot,
        preflight.exclusion_decision
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id IS NULL
      AND preflight.provider_selector = 'anonymous_apify'
      AND preflight.claim_token_hash = p_claim_token_hash
      AND preflight.claim_expires_at > pg_catalog.clock_timestamp();
END;
$_$;


--
-- Name: read_claimed_analysis_v2_preflight_target_hash_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_claimed_analysis_v2_preflight_target_hash_v1(p_preflight_id uuid, p_claim_token uuid) RETURNS character varying
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL OR p_claim_token IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_INVALID_CLAIM_INPUT', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status <> 'processing'
       OR v_preflight.lease_token IS DISTINCT FROM p_claim_token
       OR v_preflight.lease_expires_at IS NULL
       OR v_preflight.lease_expires_at <= v_now
       OR v_preflight.expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PREFLIGHT_CLAIM_FENCE_LOST', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.target_input_hash IS NOT NULL
       AND v_preflight.target_input_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PREFLIGHT_TARGET_HASH_INVALID', ERRCODE = 'P0001';
    END IF;

    RETURN v_preflight.target_input_hash;
END;
$_$;


--
-- Name: read_earlybird_v211_concierge_publication_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_earlybird_v211_concierge_publication_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_publication public.earlybird_v211_concierge_publications%ROWTYPE;
    v_request_status TEXT;
    v_order_status TEXT;
    v_fulfillment_status TEXT;
    v_female_rows INTEGER;
    v_private_rows INTEGER;
BEGIN
    SELECT publication.* INTO v_publication
    FROM public.earlybird_v211_concierge_publications AS publication
    WHERE publication.status = 'completed';
    IF NOT FOUND THEN
        RETURN pg_catalog.jsonb_build_object('completed', FALSE);
    END IF;
    SELECT request.status INTO v_request_status
    FROM public.analysis_requests AS request
    WHERE request.id = v_publication.request_id;
    SELECT earlybird_order.status INTO v_order_status
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.result_request_id = v_publication.request_id;
    SELECT fulfillment.status INTO v_fulfillment_status
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.request_id = v_publication.request_id;
    SELECT pg_catalog.count(*)::INTEGER INTO v_female_rows
    FROM public.analysis_v2_female_results AS female
    WHERE female.request_id = v_publication.request_id;
    SELECT pg_catalog.count(*)::INTEGER INTO v_private_rows
    FROM public.analysis_v2_private_results AS private_result
    WHERE private_result.request_id = v_publication.request_id;
    RETURN pg_catalog.jsonb_build_object(
        'completed', v_request_status = 'completed'
            AND v_order_status = 'completed'
            AND v_fulfillment_status = 'completed'
            AND v_female_rows = v_publication.female_count
            AND v_private_rows = v_publication.private_count,
        'requestId', v_publication.request_id,
        'resultPath', '/result/' || v_publication.request_id::TEXT,
        'requestStatus', v_request_status,
        'orderStatus', v_order_status,
        'fulfillmentStatus', v_fulfillment_status,
        'femaleRows', v_female_rows,
        'privateRows', v_private_rows
    );
END;
$$;


--
-- Name: read_earlybird_v211_concierge_recovery_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_earlybird_v211_concierge_recovery_source() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_source JSONB;
    v_descriptor_hash TEXT;
BEGIN
    v_source := public.read_earlybird_v211_concierge_recovery_source_v1();
    IF pg_catalog.jsonb_typeof(v_source) <> 'object'
       OR pg_catalog.jsonb_array_length(v_source->'preflightRuns') <> 4
       OR pg_catalog.jsonb_array_length(v_source->'providerRuns') <> 15
       OR pg_catalog.jsonb_array_length(v_source->'schedulerOperations') <> 22 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_SOURCE_NOT_EXACT',
            ERRCODE = 'P0001';
    END IF;
    v_descriptor_hash := public.analysis_v2_dag_hash_json(
        pg_catalog.jsonb_build_object(
            'domain', 'earlybird-v211-first-payment-concierge-source-v2',
            'source', v_source
        )
    );
    RETURN (v_source - 'schemaVersion') || pg_catalog.jsonb_build_object(
        'schemaVersion', 2,
        'descriptorHash', v_descriptor_hash
    );
END;
$$;


--
-- Name: read_earlybird_v211_concierge_recovery_source_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_earlybird_v211_concierge_recovery_source_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_replay RECORD;
    v_current_request public.analysis_requests%ROWTYPE;
    v_preflight_runs JSONB;
    v_provider_runs JSONB;
    v_scheduler_operations JSONB;
BEGIN
    IF 1 <> (
        SELECT pg_catalog.count(*)
        
FROM LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, original_failed_request_id UUID, policy_identity_failed_request_id UUID, transient_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_apify_transient_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','policy_identity_failed_request_id','transient_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.policy_identity_failed_request_id IS NOT NULL AND decoded.transient_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS legacy_receipt_row
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_SOURCE_NOT_EXACT',
            ERRCODE = 'P0001';
    END IF;

    SELECT replay.* INTO v_replay
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, policy_identity_failed_request_id UUID, transient_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_apify_transient_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','policy_identity_failed_request_id','transient_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.policy_identity_failed_request_id IS NOT NULL AND decoded.transient_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS replay
    JOIN public.earlybird_orders AS earlybird_order
      ON earlybird_order.id = replay.order_id
    JOIN public.earlybird_fulfillments AS fulfillment
      ON fulfillment.order_id = replay.order_id
    JOIN public.analysis_requests AS current_request
      ON current_request.id = fulfillment.request_id
    WHERE earlybird_order.plan_id = 'basic'
      AND earlybird_order.expected_amount_krw = 990
      AND earlybird_order.actual_amount_krw = 990
      AND earlybird_order.payment_id IS NOT NULL
      AND earlybird_order.seller_reference_confirmed_at IS NOT NULL
      AND earlybird_order.actual_groble_product_id
            IS NOT DISTINCT FROM earlybird_order.expected_groble_product_id
      AND earlybird_order.status = 'analysis_in_progress'
      AND earlybird_order.result_request_id = current_request.id
      AND fulfillment.status = 'manual_review'
      AND fulfillment.request_id = current_request.id
      AND fulfillment.last_error_code = 'ANALYSIS_FAILED'
      AND current_request.pipeline_version = 'v2'
      AND current_request.status = 'failed'
      AND current_request.current_step = 'failed'
      AND NOT current_request.background_processing
      AND current_request.error_message = 'SCRAPING_INCOMPLETE_ERROR'
      AND current_request.policy_versions_snapshot = pg_catalog.jsonb_build_object(
            'pipeline', 'v2',
            'risk', 'risk-policy-v2.5',
            'aiStage', 'ai-stage-policy-v2.11',
            'scheduler', 'ai-scheduler-v1'
      )
      AND 1 = (
          SELECT pg_catalog.count(*)
          FROM public.analysis_v2_failure_receipts AS receipt
          WHERE receipt.request_id = current_request.id
            AND receipt.failed_job_key = 'track:relationships:collect'
            AND receipt.error_code = 'SCRAPING_INCOMPLETE_ERROR'
      )
      AND 1 = (
          SELECT pg_catalog.count(*)
          FROM public.analysis_v2_failure_receipts AS receipt
          WHERE receipt.request_id = current_request.id
      )
      AND NOT EXISTS (
          SELECT 1
          FROM public.analysis_v2_result_summaries AS summary
          WHERE summary.request_id IN (
              replay.original_failed_request_id,
              replay.policy_identity_failed_request_id,
              replay.transient_failed_request_id,
              current_request.id
          )
      );
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_SOURCE_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    SELECT current_request.* INTO v_current_request
    FROM public.earlybird_fulfillments AS fulfillment
    JOIN public.analysis_requests AS current_request
      ON current_request.id = fulfillment.request_id
    WHERE fulfillment.order_id = v_replay.order_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_SOURCE_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    WITH incident_requests(request_id, source_label, source_ordinal) AS (
        VALUES
            (v_replay.original_failed_request_id, 'original'::TEXT, 1),
            (v_replay.policy_identity_failed_request_id, 'policy'::TEXT, 2),
            (v_replay.transient_failed_request_id, 'transient'::TEXT, 3),
            (v_current_request.id, 'last'::TEXT, 4)
    ), incident_preflights AS (
        SELECT incident.source_label, incident.source_ordinal,
               request.preflight_id
        FROM incident_requests AS incident
        JOIN public.analysis_requests AS request
          ON request.id = incident.request_id
    )
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'sourceLabel', incident.source_label,
        'actorId', run.actor_id,
        'credentialSlot', run.credential_slot,
        'runId', run.run_id,
        'ledgerStatus', run.status,
        'operationKey', run.operation_key
    ) ORDER BY incident.source_ordinal, run.operation_key)
    INTO v_preflight_runs
    FROM incident_preflights AS incident
    JOIN public.analysis_preflight_provider_runs AS run
      ON run.preflight_id = incident.preflight_id
    WHERE run.logical_provider = 'apify'
      AND run.run_id IS NOT NULL
      AND run.actual_usage_usd IS NOT NULL
      AND run.usage_reconciled_at IS NOT NULL;

    WITH incident_requests(request_id, source_label, source_ordinal) AS (
        VALUES
            (v_replay.original_failed_request_id, 'original'::TEXT, 1),
            (v_replay.policy_identity_failed_request_id, 'policy'::TEXT, 2),
            (v_replay.transient_failed_request_id, 'transient'::TEXT, 3),
            (v_current_request.id, 'last'::TEXT, 4)
    )
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'sourceLabel', incident.source_label,
        'jobKey', run.job_key,
        'actorId', run.actor_id,
        'credentialSlot', run.credential_slot,
        'runId', run.run_id,
        'ledgerStatus', run.status,
        'operationKey', run.operation_key
    ) ORDER BY incident.source_ordinal, run.job_key, run.operation_key)
    INTO v_provider_runs
    FROM incident_requests AS incident
    JOIN public.analysis_v2_provider_runs AS run
      ON run.request_id = incident.request_id
    WHERE run.logical_provider = 'apify'
      AND run.run_id IS NOT NULL
      AND run.actual_usage_usd IS NOT NULL
      AND run.usage_reconciled_at IS NOT NULL;

    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'jobKey', operation.job_key,
        'operationKey', operation.operation_key,
        'stage', operation.stage,
        'status', operation.status,
        'result', operation.result_json
    ) ORDER BY operation.stage, operation.job_key, operation.operation_key)
    INTO v_scheduler_operations
    FROM public.analysis_v2_scheduler_operations AS operation
    WHERE operation.request_id = v_replay.transient_failed_request_id
      AND operation.status = 'ready'
      AND operation.result_json IS NOT NULL
      AND operation.completed_at IS NOT NULL;

    IF pg_catalog.jsonb_array_length(COALESCE(v_preflight_runs, '[]'::JSONB)) < 1
       OR pg_catalog.jsonb_array_length(COALESCE(v_provider_runs, '[]'::JSONB)) < 1
       OR pg_catalog.jsonb_array_length(
            COALESCE(v_scheduler_operations, '[]'::JSONB)
          ) <> 22 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_SOURCE_INCOMPLETE',
            ERRCODE = 'P0001';
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'schemaVersion', 1,
        'preflightRuns', v_preflight_runs,
        'providerRuns', v_provider_runs,
        'schedulerOperations', v_scheduler_operations
    );
END;
$$;


--
-- Name: read_earlybird_v211_concierge_result_source(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_earlybird_v211_concierge_result_source(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_replay RECORD;
    v_source_request_id UUID;
    v_match_count INTEGER;
BEGIN
    IF p_order_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_SOURCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.count(*)::INTEGER
      INTO v_match_count
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, first_relationship_failed_request_id UUID, second_relationship_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ, reviewed_source_request_id UUID, reviewed_source_owner_id UUID, reviewed_source_target_instagram_id TEXT, reviewed_source_result_request_id UUID, reviewed_source_target_posts JSONB, reviewed_source_target_evidence JSONB, reviewed_source_fingerprint VARCHAR(64), reviewed_source_registered_at TIMESTAMPTZ, published_source_fingerprint VARCHAR(64), published_result_hash VARCHAR(64), published_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_concierge_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','first_relationship_failed_request_id','second_relationship_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at','reviewed_source_request_id','reviewed_source_owner_id','reviewed_source_target_instagram_id','reviewed_source_result_request_id','reviewed_source_target_posts','reviewed_source_target_evidence','reviewed_source_fingerprint','reviewed_source_registered_at','published_source_fingerprint','published_result_hash','published_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.first_relationship_failed_request_id IS NOT NULL AND decoded.second_relationship_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS replay
    JOIN public.earlybird_orders AS earlybird_order
      ON earlybird_order.id = replay.order_id
    JOIN public.analysis_requests AS source_request
      ON source_request.id = replay.original_failed_request_id
    JOIN public.analysis_preflights AS source_preflight
      ON source_preflight.id = source_request.preflight_id
    JOIN public.analysis_preflights AS current_preflight
      ON current_preflight.id = replay.rearmed_preflight_id
     AND current_preflight.id = earlybird_order.preflight_id
    WHERE replay.order_id = p_order_id
      AND source_request.user_id = earlybird_order.user_id
      AND source_preflight.user_id = earlybird_order.user_id
      AND source_preflight.target_instagram_id = 'retained.'
          || pg_catalog.substr(
              pg_catalog.replace(source_preflight.id::TEXT, '-', ''), 1, 20
          )
      AND current_preflight.user_id = earlybird_order.user_id
      AND source_request.pipeline_version = 'v2'
      AND source_request.status = 'failed';

    IF v_match_count <> 1 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_SOURCE_SCOPE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT replay.*
      INTO v_replay
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, first_relationship_failed_request_id UUID, second_relationship_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ, reviewed_source_request_id UUID, reviewed_source_owner_id UUID, reviewed_source_target_instagram_id TEXT, reviewed_source_result_request_id UUID, reviewed_source_target_posts JSONB, reviewed_source_target_evidence JSONB, reviewed_source_fingerprint VARCHAR(64), reviewed_source_registered_at TIMESTAMPTZ, published_source_fingerprint VARCHAR(64), published_result_hash VARCHAR(64), published_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_concierge_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','first_relationship_failed_request_id','second_relationship_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at','reviewed_source_request_id','reviewed_source_owner_id','reviewed_source_target_instagram_id','reviewed_source_result_request_id','reviewed_source_target_posts','reviewed_source_target_evidence','reviewed_source_fingerprint','reviewed_source_registered_at','published_source_fingerprint','published_result_hash','published_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.first_relationship_failed_request_id IS NOT NULL AND decoded.second_relationship_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS replay
    WHERE replay.order_id = p_order_id;
    v_source_request_id := v_replay.original_failed_request_id;
    IF v_replay.reviewed_source_fingerprint IS NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'sourceRequestId', v_source_request_id::TEXT
        );
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'sourceRequestId', v_source_request_id::TEXT,
        'reviewedSource', pg_catalog.jsonb_build_object(
            'ownerId', v_replay.reviewed_source_owner_id::TEXT,
            'targetUsername', v_replay.reviewed_source_target_instagram_id,
            'resultRequestId', v_replay.reviewed_source_result_request_id::TEXT,
            'targetPosts', v_replay.reviewed_source_target_posts,
            'targetEvidence', v_replay.reviewed_source_target_evidence,
            'sourceFingerprint', v_replay.reviewed_source_fingerprint
        )
    );
END;
$$;


--
-- Name: read_precheckout_blite_status_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_precheckout_blite_status_v1(p_preflight_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_cache public.precheckout_blite_cache%ROWTYPE;
    v_source_exists BOOLEAN;
BEGIN
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.precheckout_blite_cohort
      AND preflight.status = 'ready'
      AND preflight.pii_scrubbed_at IS NULL
      AND preflight.expires_at > v_now;
    IF NOT FOUND THEN RETURN NULL; END IF;

    SELECT cache.* INTO v_cache
    FROM public.precheckout_blite_cache AS cache
    WHERE cache.preflight_id = v_preflight.id;
    -- The finalizer writes source and cache atomically. Preserve an unusual source-only row so
    -- the existing claim path can repair its cache; only the absent source/cache pair is a
    -- non-runnable schema-cache-miss result that must immediately take the UI fallback.
    IF NOT FOUND THEN
        SELECT EXISTS (
            SELECT 1
            FROM public.precheckout_blite_sources AS source
            WHERE source.preflight_id = v_preflight.id
        ) INTO v_source_exists;
        IF v_source_exists THEN
            RETURN pg_catalog.jsonb_build_object(
                'state', 'pending', 'submittedAt', v_preflight.submitted_at,
                'deadlineAt', v_preflight.deadline_at
            );
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'state', 'failed', 'submittedAt', v_preflight.submitted_at,
            'deadlineAt', v_preflight.deadline_at, 'failedAt', v_now
        );
    END IF;
    IF v_cache.state = 'pending' THEN
        RETURN pg_catalog.jsonb_build_object(
            'state', 'pending', 'submittedAt', v_preflight.submitted_at,
            'deadlineAt', v_preflight.deadline_at
        );
    END IF;
    IF v_cache.state = 'complete' THEN
        RETURN pg_catalog.jsonb_build_object(
            'state', 'complete', 'submittedAt', v_preflight.submitted_at,
            'deadlineAt', v_preflight.deadline_at, 'completedAt', v_cache.completed_at,
            'dto', v_cache.dto
        );
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'state', 'failed', 'submittedAt', v_preflight.submitted_at,
        'deadlineAt', v_preflight.deadline_at, 'failedAt', v_cache.failed_at
    );
END;
$$;


--
-- Name: reap_analysis_v2_gemini_cutoff_leases_v2(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reap_analysis_v2_gemini_cutoff_leases_v2(p_limit integer DEFAULT 8) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_reaped INTEGER := 0;
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 8 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GEMINI_LEASE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('analysis-v2-gemini-leases', 0)
    );
    WITH expired AS (
        SELECT lease.slot
        FROM public.analysis_v2_gemini_leases AS lease
        WHERE lease.state = 'quarantined'
          AND lease.stage = 'genderResolution'
          AND lease.expires_at <= v_now
          AND NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_ai_attempts AS ai_attempt
                WHERE ai_attempt.request_id = lease.request_id
                  AND ai_attempt.job_key = lease.job_key
                  AND ai_attempt.operation_key = lease.operation_key
                  AND ai_attempt.attempt = lease.attempt
                  AND ai_attempt.stage = 'genderResolution'
                  AND ai_attempt.status = 'reserved'
          )
        ORDER BY lease.slot
        LIMIT p_limit
        FOR UPDATE
    )
    UPDATE public.analysis_v2_gemini_leases AS lease
    SET state = 'available',
        request_id = NULL,
        job_key = NULL,
        operation_key = NULL,
        stage = NULL,
        attempt = NULL,
        lease_claim_token = NULL,
        acquired_at = NULL,
        expires_at = NULL,
        quarantined_at = NULL,
        updated_at = v_now
    FROM expired
    WHERE lease.slot = expired.slot;
    GET DIAGNOSTICS v_reaped = ROW_COUNT;
    RETURN v_reaped;
END;
$$;


--
-- Name: reap_analysis_v2_scheduler_gemini_leases(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reap_analysis_v2_scheduler_gemini_leases(p_limit integer DEFAULT 8) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_reaped INTEGER := 0;
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 8 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GEMINI_LEASE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    WITH expired AS (
        SELECT lease.slot
        FROM public.analysis_v2_gemini_leases AS lease
        WHERE lease.state = 'quarantined'
          AND lease.stage IN ('genderTriage', 'featureAnalysis', 'privateAccountName')
          AND lease.expires_at <= v_now
          AND NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_ai_attempts AS attempt
                WHERE attempt.request_id = lease.request_id
                  AND attempt.job_key = lease.job_key
                  AND attempt.operation_key = lease.operation_key
                  AND attempt.attempt = lease.attempt
                  AND attempt.status = 'reserved'
          )
        ORDER BY lease.slot
        LIMIT p_limit
        FOR UPDATE
    )
    UPDATE public.analysis_v2_gemini_leases AS lease
    SET state = 'available',
        request_id = NULL,
        job_key = NULL,
        operation_key = NULL,
        stage = NULL,
        attempt = NULL,
        lease_claim_token = NULL,
        acquired_at = NULL,
        expires_at = NULL,
        quarantined_at = NULL,
        updated_at = v_now
    FROM expired
    WHERE lease.slot = expired.slot;
    GET DIAGNOSTICS v_reaped = ROW_COUNT;
    RETURN v_reaped;
END;
$$;


--
-- Name: rearm_analysis_preflight_dispatch_for_provider_capacity_v2(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rearm_analysis_preflight_dispatch_for_provider_capacity_v2(p_preflight_id uuid, p_expected_generation integer, p_expected_reservation_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_new_token UUID := extensions.gen_random_uuid();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_generation INTEGER;
BEGIN
    IF p_preflight_id IS NULL OR p_expected_generation IS NULL
       OR p_expected_generation < 1 OR p_expected_generation > 100
       OR p_expected_reservation_token IS NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE,
            'dispatch_generation', COALESCE(p_expected_generation, 1),
            'reservation_token', NULL
        );
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND
       OR v_preflight.status IS DISTINCT FROM 'pending'
       OR v_preflight.dispatch_workload_role IS DISTINCT FROM 'preflight'
       OR v_preflight.dispatch_contract_version IS DISTINCT FROM 2
       OR v_preflight.expires_at <= v_now
       OR v_preflight.dispatch_state IS DISTINCT FROM 'enqueued'
       OR v_preflight.dispatch_generation IS DISTINCT FROM p_expected_generation
       OR v_preflight.last_dispatch_token IS DISTINCT FROM p_expected_reservation_token THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE,
            'dispatch_generation', COALESCE(v_preflight.dispatch_generation,
                p_expected_generation),
            'reservation_token', NULL
        );
    END IF;
    v_generation := v_preflight.dispatch_generation + 1;
    IF v_generation > 100 THEN
        RAISE EXCEPTION USING MESSAGE = 'PREFLIGHT_DISPATCH_GENERATION_EXHAUSTED', ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_preflights AS preflight
    SET dispatch_state = 'reserved',
        dispatch_generation = v_generation,
        dispatch_token = v_new_token,
        last_dispatch_token = NULL,
        dispatch_reserved_at = v_now,
        dispatched_at = NULL,
        updated_at = v_now
    WHERE preflight.id = p_preflight_id
      AND preflight.status = 'pending'
      AND preflight.dispatch_state = 'enqueued'
      AND preflight.dispatch_generation = p_expected_generation
      AND preflight.last_dispatch_token = p_expected_reservation_token;
    IF NOT FOUND THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE,
            'dispatch_generation', p_expected_generation,
            'reservation_token', NULL
        );
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'should_enqueue', TRUE,
        'dispatch_generation', v_generation,
        'reservation_token', v_new_token
    );
END;
$$;


--
-- Name: rearm_analysis_v2_job_dispatch(uuid, text, integer, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rearm_analysis_v2_job_dispatch(p_request_id uuid, p_job_key text, p_expected_generation integer, p_expected_dispatch_token uuid, p_new_dispatch_token uuid) RETURNS TABLE(rearmed boolean, dispatch_generation integer, reservation_token uuid, job_status text, dispatch_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    PERFORM public.assert_analysis_revenue_dispatch_guard_v1(p_request_id, p_job_key);
    RETURN QUERY
    SELECT * FROM public.rearm_analysis_v2_job_dispatch_unfenced_20260811(
        p_request_id, p_job_key, p_expected_generation,
        p_expected_dispatch_token, p_new_dispatch_token
    );
END;
$$;


--
-- Name: rearm_analysis_v2_job_dispatch_unfenced_20260811(uuid, text, integer, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rearm_analysis_v2_job_dispatch_unfenced_20260811(p_request_id uuid, p_job_key text, p_expected_generation integer, p_expected_dispatch_token uuid, p_new_dispatch_token uuid) RETURNS TABLE(rearmed boolean, dispatch_generation integer, reservation_token uuid, job_status text, dispatch_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_expected_generation IS NULL
       OR p_expected_generation NOT BETWEEN 1 AND 999
       OR p_expected_dispatch_token IS NULL
       OR p_new_dispatch_token IS NULL
       OR p_new_dispatch_token = p_expected_dispatch_token
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_JOB_DISPATCH_INPUT', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    IF v_job.dispatch_state = 'reserved'
       AND v_job.dispatch_generation = p_expected_generation + 1
       AND v_job.dispatch_reservation_token = p_new_dispatch_token THEN
        RETURN QUERY SELECT
            TRUE,
            v_job.dispatch_generation,
            v_job.dispatch_reservation_token,
            v_job.status::TEXT,
            v_job.dispatch_state::TEXT;
        RETURN;
    END IF;

    IF v_request.status NOT IN ('pending', 'processing')
       OR v_job.dispatch_state NOT IN ('enqueued', 'delivered')
       OR v_job.dispatch_generation <> p_expected_generation
       OR v_job.dispatch_reservation_token <> p_expected_dispatch_token
       OR NOT (
            v_job.status = 'pending'
            OR (
                v_job.status = 'processing'
                AND v_job.lease_expires_at <= v_now
            )
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_DISPATCH_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    -- The caller must first prove Cloud Tasks NOT_FOUND. The database deliberately cannot infer
    -- absence from age, because an ambiguous task-create response must reuse the old identity.
    UPDATE public.analysis_pipeline_jobs AS job
    SET status = 'pending',
        dispatch_state = 'reserved',
        dispatch_generation = p_expected_generation + 1,
        dispatch_reservation_token = p_new_dispatch_token,
        dispatch_reserved_at = v_now,
        dispatched_at = NULL,
        dispatch_task_name = NULL,
        delivered_at = NULL,
        lease_token = NULL,
        lease_expires_at = NULL,
        updated_at = v_now
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    RETURNING job.* INTO v_job;

    RETURN QUERY SELECT
        TRUE,
        v_job.dispatch_generation,
        v_job.dispatch_reservation_token,
        v_job.status::TEXT,
        v_job.dispatch_state::TEXT;
END;
$_$;


--
-- Name: rearm_analysis_v2_job_dispatch_v2(uuid, text, integer, uuid, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rearm_analysis_v2_job_dispatch_v2(p_request_id uuid, p_job_key text, p_expected_generation integer, p_expected_dispatch_token uuid, p_new_dispatch_token uuid, p_workload_role text, p_contract_version smallint) RETURNS TABLE(rearmed boolean, dispatch_generation integer, reservation_token uuid, job_status text, dispatch_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_result RECORD;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'paid' OR p_contract_version IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT job.* INTO v_job FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    IF FOUND AND v_job.dispatch_workload_role IS NULL
       AND v_job.dispatch_contract_version IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_LEGACY_DISPATCH_ROLELESS', ERRCODE = 'P0001';
    END IF;
    IF FOUND AND (
        v_job.dispatch_workload_role IS NULL
        OR v_job.dispatch_contract_version IS NULL
        OR v_job.dispatch_workload_role IS DISTINCT FROM 'paid'
        OR v_job.dispatch_contract_version IS DISTINCT FROM 2
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT rearmed.* INTO v_result FROM public.rearm_analysis_v2_job_dispatch(
        p_request_id, p_job_key, p_expected_generation,
        p_expected_dispatch_token, p_new_dispatch_token
    ) AS rearmed;
    IF v_result.rearmed THEN
        UPDATE public.analysis_pipeline_jobs AS job
        SET dispatch_workload_role = 'paid', dispatch_contract_version = 2
        WHERE job.request_id = p_request_id AND job.job_key = p_job_key
          AND job.dispatch_state = 'reserved'
          AND job.dispatch_generation = v_result.dispatch_generation
          AND job.dispatch_reservation_token = v_result.reservation_token;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_DISPATCH_FENCE_MISMATCH', ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN QUERY SELECT v_result.rearmed, v_result.dispatch_generation,
        v_result.reservation_token, v_result.job_status, v_result.dispatch_state;
END;
$$;


--
-- Name: rearm_analysis_v2_preflight_admission_dispatch_v2(uuid, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rearm_analysis_v2_preflight_admission_dispatch_v2(p_preflight_id uuid, p_admission_generation integer, p_expected_dispatch_generation integer, p_expected_dispatch_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_new_token UUID := extensions.gen_random_uuid();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_generation INTEGER;
BEGIN
    IF p_preflight_id IS NULL OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_expected_dispatch_generation IS NULL
       OR p_expected_dispatch_generation NOT BETWEEN 1 AND 100
       OR p_expected_dispatch_token IS NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE,
            'dispatch_generation', COALESCE(p_expected_dispatch_generation, 1),
            'dispatch_token', NULL
        );
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND
       OR v_preflight.admission_status IS DISTINCT FROM 'pending'
       OR v_preflight.admission_dispatch_workload_role IS DISTINCT FROM 'paid'
       OR v_preflight.admission_dispatch_contract_version IS DISTINCT FROM 2
       OR v_preflight.admission_generation IS DISTINCT FROM p_admission_generation
       OR v_preflight.admission_dispatch_state IS DISTINCT FROM 'enqueued'
       OR v_preflight.admission_dispatch_generation IS DISTINCT FROM p_expected_dispatch_generation
       OR v_preflight.admission_dispatch_token IS DISTINCT FROM p_expected_dispatch_token
       OR v_preflight.expires_at <= v_now THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE,
            'dispatch_generation', COALESCE(v_preflight.admission_dispatch_generation,
                p_expected_dispatch_generation),
            'dispatch_token', NULL
        );
    END IF;
    v_generation := v_preflight.admission_dispatch_generation + 1;
    IF v_generation > 100 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_FRESH_ADMISSION_DISPATCH_GENERATION_EXHAUSTED',
            ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_preflights AS preflight
    SET admission_dispatch_state = 'reserved',
        admission_dispatch_generation = v_generation,
        admission_dispatch_token = v_new_token,
        admission_dispatch_reserved_at = v_now,
        admission_dispatched_at = NULL,
        updated_at = v_now
    WHERE preflight.id = p_preflight_id
      AND preflight.admission_status = 'pending'
      AND preflight.admission_generation = p_admission_generation
      AND preflight.admission_dispatch_state = 'enqueued'
      AND preflight.admission_dispatch_generation = p_expected_dispatch_generation
      AND preflight.admission_dispatch_token = p_expected_dispatch_token;
    IF NOT FOUND THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE,
            'dispatch_generation', p_expected_dispatch_generation,
            'dispatch_token', NULL
        );
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'should_enqueue', TRUE,
        'dispatch_generation', v_generation,
        'dispatch_token', v_new_token
    );
END;
$$;


--
-- Name: rearm_earlybird_concierge_snapshot_conflict_execution(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rearm_earlybird_concierge_snapshot_conflict_execution(p_order_id uuid, p_preflight_id uuid, p_request_id uuid, p_expected_manual_review_at timestamp with time zone, p_expected_admission_refreshed_at timestamp with time zone) RETURNS TABLE(applied boolean, request_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_order public.earlybird_orders%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_recovery RECORD;
    v_failed_jobs INTEGER;
    v_cancelled_jobs INTEGER;
    v_active_jobs INTEGER;
    v_provider_count INTEGER;
    v_provider_success_count INTEGER;
    v_provider_rejected_count INTEGER;
    v_result_count INTEGER;
BEGIN
    IF p_order_id IS NULL
       OR p_preflight_id IS NULL
       OR p_request_id IS NULL
       OR p_expected_manual_review_at IS NULL
       OR p_expected_admission_refreshed_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE =
            'CONCIERGE_SNAPSHOT_REARM_INVALID', ERRCODE = 'P0001';
    END IF;

    -- Lock order -> preflight -> fulfillment -> request, matching the existing
    -- concierge recovery path before touching any request-owned row.
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    SELECT recovery.* INTO v_recovery
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, preflight_id UUID, provider_operation_key TEXT, provider_input_hash VARCHAR(64), provider_run_id_hash VARCHAR(32), expected_manual_review_at TIMESTAMPTZ, expected_admission_refreshed_at TIMESTAMPTZ, old_order_followers_count INTEGER, old_order_following_count INTEGER, old_preflight_followers_count INTEGER, old_preflight_following_count INTEGER, new_witness_followers_count INTEGER, new_witness_following_count INTEGER, old_snapshot_recorded_at TIMESTAMPTZ, new_witness_recorded_at TIMESTAMPTZ, recovery_reason TEXT, followers_absolute_delta INTEGER, following_absolute_delta INTEGER, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_concierge_snapshot_conflict_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','preflight_id','provider_operation_key','provider_input_hash','provider_run_id_hash','expected_manual_review_at','expected_admission_refreshed_at','old_order_followers_count','old_order_following_count','old_preflight_followers_count','old_preflight_following_count','new_witness_followers_count','new_witness_following_count','old_snapshot_recorded_at','new_witness_recorded_at','recovery_reason','followers_absolute_delta','following_absolute_delta','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.preflight_id IS NOT NULL AND decoded.provider_operation_key IS NOT NULL AND decoded.provider_input_hash IS NOT NULL AND decoded.provider_run_id_hash IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.expected_admission_refreshed_at IS NOT NULL AND decoded.old_order_followers_count IS NOT NULL AND decoded.old_order_following_count IS NOT NULL AND decoded.old_preflight_followers_count IS NOT NULL AND decoded.old_preflight_following_count IS NOT NULL AND decoded.new_witness_followers_count IS NOT NULL AND decoded.new_witness_following_count IS NOT NULL AND decoded.old_snapshot_recorded_at IS NOT NULL AND decoded.new_witness_recorded_at IS NOT NULL AND decoded.recovery_reason IS NOT NULL AND decoded.followers_absolute_delta IS NOT NULL AND decoded.following_absolute_delta IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
    WHERE recovery.order_id = p_order_id
      AND recovery.preflight_id = p_preflight_id
    FOR UPDATE;

    IF v_order.id IS NULL
       OR v_preflight.id IS NULL
       OR v_fulfillment.order_id IS NULL
       OR v_request.id IS NULL
       OR v_recovery.order_id IS NULL
       OR v_order.preflight_id IS DISTINCT FROM p_preflight_id
       OR v_order.result_request_id IS DISTINCT FROM p_request_id
       OR v_preflight.consumed_request_id IS DISTINCT FROM p_request_id
       OR v_request.preflight_id IS DISTINCT FROM p_preflight_id
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('failed', 'processing', 'completed')
       OR v_fulfillment.request_id IS DISTINCT FROM p_request_id
       OR v_recovery.expected_manual_review_at
            IS DISTINCT FROM p_expected_manual_review_at
       OR v_recovery.expected_admission_refreshed_at
            IS DISTINCT FROM p_expected_admission_refreshed_at
       OR v_preflight.admission_refreshed_at
            IS DISTINCT FROM p_expected_admission_refreshed_at
       OR v_order.status NOT IN ('analysis_in_progress', 'completed')
       OR v_fulfillment.status NOT IN ('analysis_in_progress', 'completed')
       OR EXISTS (
            SELECT 1
            FROM public.earlybird_webhook_events AS refund_event
            WHERE refund_event.payment_id = v_order.payment_id
              AND refund_event.event_type = 'payment.refunded'
       ) THEN
        RAISE EXCEPTION USING MESSAGE =
            'CONCIERGE_SNAPSHOT_REARM_CONFLICT', ERRCODE = 'P0001';
    END IF;

    IF v_request.status = 'completed' THEN
        RETURN QUERY SELECT FALSE, 'completed'::TEXT;
        RETURN;
    END IF;

    UPDATE public.analysis_preflights
    SET target_instagram_id = v_order.target_instagram_id,
        excluded_instagram_id = v_order.excluded_instagram_id,
        exclusion_decision = v_order.exclusion_decision
    WHERE id = p_preflight_id
      AND target_instagram_id LIKE 'retained.%';

    SELECT
        pg_catalog.count(*) FILTER (WHERE job.status = 'failed')::INTEGER,
        pg_catalog.count(*) FILTER (WHERE job.status = 'cancelled')::INTEGER,
        pg_catalog.count(*) FILTER (WHERE job.status IN ('pending', 'processing'))::INTEGER
    INTO v_failed_jobs, v_cancelled_jobs, v_active_jobs
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id;
    IF v_failed_jobs <> 1 OR v_cancelled_jobs < 1 OR v_active_jobs <> 0 THEN
        RAISE EXCEPTION USING MESSAGE =
            'CONCIERGE_SNAPSHOT_REARM_JOB_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.analysis_pipeline_jobs AS job
        WHERE job.request_id = p_request_id
          AND job.job_key = 'track:target-evidence:collect'
          AND job.status = 'failed'
          AND job.last_error_code = 'SCRAPING_PROVIDER_START_REJECTED_ERROR'
    ) THEN
        RAISE EXCEPTION USING MESSAGE =
            'CONCIERGE_SNAPSHOT_REARM_JOB_CONFLICT', ERRCODE = 'P0001';
    END IF;

    SELECT count(*)::INTEGER,
           count(*) FILTER (WHERE provider_run.status = 'succeeded')::INTEGER,
           count(*) FILTER (WHERE provider_run.status = 'rejected')::INTEGER
    INTO v_provider_count, v_provider_success_count, v_provider_rejected_count
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id;
    IF v_provider_count <> 5
       OR v_provider_success_count <> 4
       OR v_provider_rejected_count <> 1
       OR NOT EXISTS (
            SELECT 1 FROM public.analysis_v2_provider_runs AS provider_run
            WHERE provider_run.request_id = p_request_id
              AND provider_run.operation_key LIKE 'target-comments:%'
              AND provider_run.status = 'rejected'
       ) THEN
        RAISE EXCEPTION USING MESSAGE =
            'CONCIERGE_SNAPSHOT_REARM_PROVIDER_CONFLICT', ERRCODE = 'P0001';
    END IF;

    SELECT count(*)::INTEGER INTO v_result_count
    FROM public.analysis_results AS result
    WHERE result.request_id = p_request_id;
    IF v_result_count <> 0
       OR EXISTS (
            SELECT 1 FROM public.analysis_v2_result_summaries AS summary
            WHERE summary.request_id = p_request_id
       )
       OR EXISTS (
            SELECT 1 FROM public.analysis_v2_target_evidence_manifests AS manifest
            WHERE manifest.request_id = p_request_id
       )
       OR EXISTS (
            SELECT 1 FROM public.analysis_v2_provider_cleanup_intents AS intent
            WHERE intent.request_id = p_request_id
              AND intent.completed_at IS NULL
       ) THEN
        RAISE EXCEPTION USING MESSAGE =
            'CONCIERGE_SNAPSHOT_REARM_RESULT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_v2_provider_runs AS provider_run
    SET status = 'starting',
        reservation_token = extensions.gen_random_uuid(),
        terminalized_at = NULL,
        actual_usage_usd = NULL,
        usage_reconciled_at = NULL,
        updated_at = v_now
    WHERE provider_run.request_id = p_request_id
      AND provider_run.operation_key LIKE 'target-comments:%'
      AND provider_run.status = 'rejected';

    UPDATE public.analysis_pipeline_jobs AS job
    SET status = 'pending',
        dispatch_state = 'reserved',
        dispatch_generation = job.dispatch_generation + 1,
        dispatch_reservation_token = extensions.gen_random_uuid(),
        dispatch_reserved_at = v_now,
        dispatched_at = NULL,
        dispatch_task_name = NULL,
        delivered_at = NULL,
        lease_token = NULL,
        lease_expires_at = NULL,
        completion_token = NULL,
        completion_fanout_hash = NULL,
        last_error_code = NULL,
        last_error_at = NULL,
        completed_at = NULL,
        updated_at = v_now
    WHERE job.request_id = p_request_id
      AND job.status IN ('failed', 'cancelled');

    UPDATE public.analysis_requests AS analysis_request
    SET status = 'processing',
        target_instagram_id = v_order.target_instagram_id,
        excluded_instagram_id = v_order.excluded_instagram_id,
        exclusion_decision_snapshot = v_order.exclusion_decision,
        background_processing = TRUE,
        current_step = 'processing',
        progress_step = '분석을 다시 시작합니다',
        error_message = NULL,
        completed_at = NULL
    WHERE analysis_request.id = p_request_id
      AND analysis_request.status = 'failed';

    RETURN QUERY SELECT TRUE, 'processing'::TEXT;
END;
$$;


--
-- Name: rearm_earlybird_first15_canary_provider_failure(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rearm_earlybird_first15_canary_provider_failure(p_order_id uuid, p_expected_failed_request_id uuid, p_fallback_credential_slot text) RETURNS TABLE(applied boolean, fulfillment_status text, request_id uuid, initial_job_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_user_id_hint UUID;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_source_request public.analysis_requests%ROWTYPE;
    v_source_preflight public.analysis_preflights%ROWTYPE;
    v_profile_source_preflight public.analysis_preflights%ROWTYPE;
    v_existing public.earlybird_first15_canary_provider_rearms%ROWTYPE;
    v_previous public.earlybird_first15_canary_provider_rearms%ROWTYPE;
    v_profile_run public.analysis_preflight_provider_runs%ROWTYPE;
    v_claim RECORD;
    v_created RECORD;
    v_new_preflight_id UUID;
    v_rearm_generation SMALLINT;
    v_entitlement_hash TEXT;
    v_base_preflight_key TEXT;
BEGIN
    IF p_order_id IS NULL
       OR p_expected_failed_request_id IS NULL
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_fallback_credential_slot)
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_CANARY_RECOVERY_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.user_id INTO v_user_id_hint
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_CANARY_RECOVERY_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    PERFORM 1 FROM public.users AS recovery_user
    WHERE recovery_user.id = v_user_id_hint
    FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_CANARY_RECOVERY_CONFLICT', ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    SELECT request.* INTO v_source_request
    FROM public.analysis_requests AS request
    WHERE request.id = p_expected_failed_request_id
    FOR UPDATE;
    SELECT rearm.* INTO v_existing
    FROM public.earlybird_first15_canary_provider_rearms AS rearm
    WHERE rearm.source_request_id = p_expected_failed_request_id
    FOR UPDATE;

    IF FOUND THEN
        IF v_existing.order_id IS DISTINCT FROM p_order_id
           OR v_existing.fallback_credential_slot IS DISTINCT FROM p_fallback_credential_slot
           OR v_order.preflight_id IS DISTINCT FROM v_existing.rearmed_preflight_id
           OR v_fulfillment.request_id IS NULL
        THEN
            RAISE EXCEPTION USING
                MESSAGE = 'FIRST15_CANARY_RECOVERY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN QUERY SELECT FALSE, v_fulfillment.status, v_fulfillment.request_id,
            'coordinator:bootstrap'::TEXT;
        RETURN;
    END IF;

    SELECT preflight.* INTO v_source_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id
    FOR UPDATE;
    SELECT rearm.* INTO v_previous
    FROM public.earlybird_first15_canary_provider_rearms AS rearm
    WHERE rearm.rearmed_preflight_id = v_source_preflight.id
    FOR UPDATE;

    IF v_order.id IS NULL
       OR v_fulfillment.order_id IS NULL
       OR v_source_request.id IS NULL
       OR v_source_preflight.id IS NULL
       OR v_order.user_id IS DISTINCT FROM v_user_id_hint
       OR v_order.status <> 'analysis_in_progress'
       OR v_order.result_request_id IS DISTINCT FROM v_source_request.id
       OR v_order.plan_id NOT IN ('basic', 'standard')
       OR v_order.payment_id IS NULL
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_order.actual_amount_krw IS NULL
       OR v_order.actual_amount_krw < 0
       OR v_order.actual_amount_krw > v_order.expected_amount_krw
       OR v_order.actual_groble_product_id
            IS DISTINCT FROM v_order.expected_groble_product_id
       OR EXISTS (
           SELECT 1 FROM public.earlybird_webhook_events AS refund_event
           WHERE refund_event.payment_id = v_order.payment_id
             AND refund_event.event_type IN (
                 'payment.refunded', 'payment.refund_pending',
                 'payment.cancelled', 'payment.failed'
             )
       )
       OR v_fulfillment.status <> 'analysis_in_progress'
       OR v_fulfillment.request_id IS DISTINCT FROM v_source_request.id
       OR v_fulfillment.lease_token IS NOT NULL
       OR v_fulfillment.lease_expires_at IS NOT NULL
       OR v_source_request.user_id IS DISTINCT FROM v_order.user_id
       OR v_source_request.preflight_id IS DISTINCT FROM v_source_preflight.id
       OR v_source_request.pipeline_version <> 'v2'
       OR v_source_request.status <> 'failed'
       OR v_source_request.current_step <> 'failed'
       OR NOT COALESCE(
           (
               v_source_request.error_message IN (
                   'SCRAPING_INCOMPLETE_ERROR',
                   'SCRAPING_PROVIDER_QUOTA_ERROR',
                   'SCRAPING_PROVIDER_START_REJECTED_ERROR'
               )
               AND EXISTS (
                   SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                   WHERE receipt.request_id = v_source_request.id
                     AND receipt.failed_job_key IN (
                         'track:relationships:collect',
                         'track:target-evidence:collect'
                     )
                     AND receipt.error_code = v_source_request.error_message
               )
           )
           OR (
               v_previous.order_id IS NOT NULL
               AND v_previous.rearm_generation = 1
               AND v_order.concierge_apify_credential_slot = 'tertiary'
               AND p_fallback_credential_slot = 'quinary'
               AND (
                   (v_previous.source_failure_code = 'SCRAPING_INCOMPLETE_ERROR'
                    AND v_source_request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
                    AND EXISTS (
                        SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                        WHERE receipt.request_id = v_source_request.id
                          AND receipt.failed_job_key = 'track:relationships:collect'
                          AND receipt.error_code = v_source_request.error_message
                    ))
                   OR (v_previous.source_failure_code = 'SCRAPING_PROVIDER_START_REJECTED_ERROR'
                    AND v_source_request.error_message = 'ANALYSIS_V2_JOB_HANDLER_FAILED'
                    AND EXISTS (
                        SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                        WHERE receipt.request_id = v_source_request.id
                          AND receipt.failed_job_key = 'track:target-evidence:collect'
                          AND receipt.error_code = v_source_request.error_message
                    ))
                   OR (v_previous.source_failure_code = 'SCRAPING_PROVIDER_QUOTA_ERROR'
                    AND v_source_request.error_message = 'ANALYSIS_V2_MEDIA_ARTIFACT_OBJECT_ERROR'
                    AND EXISTS (
                        SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                        WHERE receipt.request_id = v_source_request.id
                          AND receipt.failed_job_key = 'track:profile-ai:batch:2'
                          AND receipt.error_code = v_source_request.error_message
                    ))
               )
           )
           OR (
               v_previous.order_id IS NOT NULL
               AND v_previous.rearm_generation = 2
               AND v_order.concierge_apify_credential_slot = 'quinary'
               AND p_fallback_credential_slot = 'primary'
               AND v_previous.source_failure_code = 'ANALYSIS_V2_MEDIA_ARTIFACT_OBJECT_ERROR'
               AND v_source_request.error_message = 'JOB_ATTEMPTS_EXHAUSTED'
               AND EXISTS (
                   SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
                   WHERE receipt.request_id = v_source_request.id
                     AND receipt.failed_job_key = 'track:profile-ai:batch:2'
                     AND receipt.error_code = v_source_request.error_message
               )
           ),
           FALSE
       )
       OR EXISTS (
           SELECT 1 FROM public.analysis_pipeline_jobs AS job
           WHERE job.request_id = v_source_request.id
             AND job.status IN ('pending', 'processing', 'retryable')
       )
       OR EXISTS (
           SELECT 1 FROM public.analysis_v2_provider_runs AS provider_run
           WHERE provider_run.request_id = v_source_request.id
             AND provider_run.status IN ('starting', 'running')
       )
       OR EXISTS (
           SELECT 1 FROM public.analysis_v2_provider_runs AS provider_run
           WHERE provider_run.request_id = v_source_request.id
             AND provider_run.status IN ('succeeded', 'aborted', 'failed', 'timed_out')
             AND provider_run.run_id IS NOT NULL
             AND (
                 provider_run.actual_usage_usd IS NULL
                 OR provider_run.usage_reconciled_at IS NULL
             )
       )
       OR v_source_preflight.user_id IS DISTINCT FROM v_order.user_id
       OR v_source_preflight.access_mode <> 'production'
       OR v_source_preflight.status <> 'consumed'
       OR v_source_preflight.consumed_request_id IS DISTINCT FROM v_source_request.id
       OR v_source_preflight.admission_status <> 'ready'
       OR v_source_preflight.admission_selected_plan_id IS DISTINCT FROM v_order.plan_id
       OR v_source_preflight.admission_target_followers_count IS NULL
       OR v_source_preflight.admission_target_following_count IS NULL
       OR v_source_preflight.admission_capacity_required_plan_id IS NULL
       OR v_source_preflight.admission_required_plan_id IS NULL
       OR v_source_preflight.admission_plan_cards_snapshot IS NULL
       OR v_order.concierge_apify_credential_slot IS NULL
       OR (v_order.concierge_apify_credential_slot, p_fallback_credential_slot)
            NOT IN (
                ('senary', 'tertiary'),
                ('tertiary', 'quinary'),
                ('quinary', 'primary'),
                ('primary', 'secondary')
            )
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_CANARY_RECOVERY_INELIGIBLE', ERRCODE = 'P0001';
    END IF;

    IF v_previous.order_id IS NULL THEN
        v_profile_source_preflight := v_source_preflight;
        v_rearm_generation := 1;
    ELSE
        IF v_previous.order_id IS DISTINCT FROM v_order.id
           OR v_previous.fallback_credential_slot
                IS DISTINCT FROM v_order.concierge_apify_credential_slot
        THEN
            RAISE EXCEPTION USING
                MESSAGE = 'FIRST15_CANARY_RECOVERY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        SELECT preflight.* INTO v_profile_source_preflight
        FROM public.analysis_preflights AS preflight
        WHERE preflight.id = v_previous.profile_source_preflight_id
        FOR KEY SHARE;
        v_rearm_generation := v_previous.rearm_generation + 1;
    END IF;
    IF v_rearm_generation NOT BETWEEN 1 AND 4 OR v_profile_source_preflight.id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_CANARY_RECOVERY_CONFLICT', ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.* INTO v_profile_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = v_profile_source_preflight.id
      AND provider_run.operation_key = 'target-profile-fresh-admission:g1'
    FOR KEY SHARE;
    IF NOT FOUND
       OR v_profile_run.status <> 'succeeded'
       OR v_profile_run.logical_provider <> 'apify'
       OR v_profile_run.actor_id <> 'apify/instagram-profile-scraper'
       OR v_profile_run.run_id IS NULL
       OR v_profile_run.actual_usage_usd IS NULL
       OR v_profile_run.usage_reconciled_at IS NULL
       OR v_profile_run.reusable_profile_schema_version <> 1
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_CANARY_RECOVERY_PROFILE_SOURCE_UNAVAILABLE',
            ERRCODE = 'P0001';
    END IF;

    v_base_preflight_key := 'earlybird.fulfillment.'
        || pg_catalog.replace(v_order.id::TEXT, '-', '');
    v_entitlement_hash := pg_catalog.encode(extensions.digest(
        pg_catalog.convert_to(
            'earlybird-fulfillment-admission-v1' || pg_catalog.chr(10)
            || pg_catalog.lower(v_order.id::TEXT),
            'UTF8'
        ), 'sha256'
    ), 'hex');
    v_new_preflight_id := extensions.gen_random_uuid();

    INSERT INTO public.analysis_preflights(
        id, user_id, idempotency_key, target_instagram_id, status,
        exclusion_decision, excluded_instagram_id, access_mode,
        launch_status_snapshot, plan_catalog_snapshot, plan_cards_snapshot,
        pricing_version, pricing_snapshot, policy_versions_snapshot,
        target_followers_count, target_following_count, target_is_private,
        capacity_required_plan_id, required_plan_id, created_at, updated_at,
        expires_at, ready_at,
        admission_status, admission_generation, admission_selected_plan_id,
        admission_entitlement_jti_hash, admission_token,
        admission_requested_at, admission_refreshed_at,
        admission_dispatch_state, admission_dispatch_generation,
        admission_dispatch_token, admission_dispatch_reserved_at,
        admission_dispatched_at, admission_target_followers_count,
        admission_target_following_count,
        admission_capacity_required_plan_id, admission_required_plan_id,
        admission_plan_cards_snapshot, admission_failure_count,
        analysis_entry_channel, order_scoped_apify_credential_slot
    ) VALUES (
        v_new_preflight_id, v_order.user_id,
        v_base_preflight_key || '.first15r' || v_rearm_generation::TEXT,
        v_order.target_instagram_id, 'ready', v_order.exclusion_decision,
        v_order.excluded_instagram_id, 'production',
        v_source_preflight.launch_status_snapshot,
        v_source_preflight.plan_catalog_snapshot,
        v_source_preflight.admission_plan_cards_snapshot,
        v_source_preflight.pricing_version, v_source_preflight.pricing_snapshot,
        v_source_preflight.policy_versions_snapshot,
        v_order.target_followers_count, v_order.target_following_count, FALSE,
        v_source_preflight.admission_capacity_required_plan_id,
        v_source_preflight.admission_required_plan_id,
        v_now, v_now, v_now + INTERVAL '30 minutes', v_now,
        'ready', 1, v_order.plan_id, v_entitlement_hash,
        extensions.gen_random_uuid(), v_now, v_now,
        'enqueued', 1, extensions.gen_random_uuid(), v_now, v_now,
        v_source_preflight.admission_target_followers_count,
        v_source_preflight.admission_target_following_count,
        v_source_preflight.admission_capacity_required_plan_id,
        v_source_preflight.admission_required_plan_id,
        v_source_preflight.admission_plan_cards_snapshot, 0,
        v_source_preflight.analysis_entry_channel, p_fallback_credential_slot
    );

    INSERT INTO public.earlybird_first15_canary_provider_rearms(
        order_id, rearm_generation, source_request_id, source_preflight_id,
        profile_source_preflight_id, rearmed_preflight_id, source_failure_code,
        source_credential_slot, fallback_credential_slot
    ) VALUES (
        v_order.id, v_rearm_generation, v_source_request.id, v_source_preflight.id,
        v_profile_source_preflight.id, v_new_preflight_id,
        v_source_request.error_message, v_order.concierge_apify_credential_slot,
        p_fallback_credential_slot
    );

    UPDATE public.earlybird_orders AS earlybird_order
    SET status = 'paid', preflight_id = v_new_preflight_id,
        result_request_id = NULL,
        concierge_apify_credential_slot = p_fallback_credential_slot,
        updated_at = v_now
    WHERE earlybird_order.id = v_order.id;
    UPDATE public.earlybird_fulfillments AS fulfillment
    SET status = 'admission_pending', attempt_count = 0, request_id = NULL,
        lease_token = NULL, lease_expires_at = NULL, next_attempt_at = v_now,
        operator_admitted_at = v_now, last_error_code = NULL,
        last_error_at = NULL, manual_review_at = NULL, completed_at = NULL,
        updated_at = v_now
    WHERE fulfillment.order_id = v_order.id;

    SELECT * INTO v_claim
    FROM public.claim_earlybird_fulfillment(
        v_order.id, extensions.gen_random_uuid(), 300
    );
    IF v_claim.claimed IS DISTINCT FROM TRUE
       OR v_claim.fulfillment_status IS DISTINCT FROM 'admission_pending'
       OR v_claim.lease_token IS NULL
       OR v_claim.lease_fence IS NULL
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_CANARY_RECOVERY_CLAIM_CONFLICT', ERRCODE = 'P0001';
    END IF;
    SELECT * INTO v_created
    FROM public.create_or_replay_earlybird_fulfillment_request(
        v_order.id, v_claim.lease_token, v_claim.lease_fence
    );
    IF v_created.order_id IS DISTINCT FROM v_order.id
       OR v_created.fulfillment_status IS DISTINCT FROM 'analysis_in_progress'
       OR v_created.request_id IS NULL
       OR v_created.initial_job_key IS DISTINCT FROM 'coordinator:bootstrap'
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_CANARY_RECOVERY_REQUEST_CONFLICT', ERRCODE = 'P0001';
    END IF;

    RETURN QUERY SELECT TRUE, v_created.fulfillment_status,
        v_created.request_id, v_created.initial_job_key;
END;
$$;


--
-- Name: rearm_precheckout_blite_dispatch_v2(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rearm_precheckout_blite_dispatch_v2(p_preflight_id uuid, p_expected_generation integer, p_expected_dispatch_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_new_token UUID := extensions.gen_random_uuid();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_cache public.precheckout_blite_cache%ROWTYPE;
    v_dispatch public.precheckout_blite_dispatches%ROWTYPE;
    v_generation INTEGER;
BEGIN
    IF p_preflight_id IS NULL
       OR p_expected_dispatch_token IS NULL
       OR p_expected_generation IS NULL
       OR p_expected_generation < 1
       OR p_expected_generation > 100 THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE, 'dispatch_token', NULL,
            'dispatch_generation', COALESCE(p_expected_generation, 1)
        );
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND OR v_preflight.status IS DISTINCT FROM 'ready'
       OR v_preflight.precheckout_blite_cohort IS DISTINCT FROM TRUE
       OR v_preflight.expires_at <= v_now
       OR v_preflight.pii_scrubbed_at IS NOT NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE, 'dispatch_token', NULL,
            'dispatch_generation', p_expected_generation
        );
    END IF;
    SELECT cache.* INTO v_cache
    FROM public.precheckout_blite_cache AS cache
    WHERE cache.preflight_id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND OR v_cache.state IS DISTINCT FROM 'pending' THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE, 'dispatch_token', NULL,
            'dispatch_generation', p_expected_generation
        );
    END IF;
    SELECT dispatch.* INTO v_dispatch
    FROM public.precheckout_blite_dispatches AS dispatch
    WHERE dispatch.preflight_id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_dispatch.state IS DISTINCT FROM 'enqueued'
       OR v_dispatch.dispatch_generation IS DISTINCT FROM p_expected_generation
       OR v_dispatch.last_dispatch_token IS DISTINCT FROM p_expected_dispatch_token THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE,
            'dispatch_token', NULL,
            'dispatch_generation', COALESCE(v_dispatch.dispatch_generation, p_expected_generation)
        );
    END IF;
    v_generation := v_dispatch.dispatch_generation + 1;
    IF v_generation > 100 THEN
        RAISE EXCEPTION USING MESSAGE = 'PRECHECKOUT_BLITE_DISPATCH_GENERATION_EXHAUSTED', ERRCODE = 'P0001';
    END IF;
    UPDATE public.precheckout_blite_dispatches
    SET state = 'enqueuing',
        dispatch_generation = v_generation,
        dispatch_token = v_new_token,
        last_dispatch_token = NULL,
        attempt_count = v_dispatch.attempt_count + 1,
        lease_expires_at = v_now + INTERVAL '2 minutes',
        failure_reason = NULL,
        updated_at = v_now
    WHERE preflight_id = p_preflight_id
      AND state = 'enqueued'
      AND dispatch_generation = p_expected_generation
      AND last_dispatch_token = p_expected_dispatch_token;
    IF NOT FOUND THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE, 'dispatch_token', NULL,
            'dispatch_generation', v_dispatch.dispatch_generation
        );
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'should_enqueue', TRUE,
        'dispatch_token', v_new_token,
        'dispatch_generation', v_generation
    );
END;
$$;


--
-- Name: rearm_precheckout_blite_dispatch_v3(uuid, integer, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rearm_precheckout_blite_dispatch_v3(p_preflight_id uuid, p_expected_generation integer, p_expected_dispatch_token uuid, p_workload_role text, p_contract_version smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_new_token UUID := extensions.gen_random_uuid();
    v_dispatch public.precheckout_blite_dispatches%ROWTYPE;
    v_generation INTEGER;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'preflight'
       OR p_contract_version IS DISTINCT FROM 2
       OR p_expected_generation IS NULL
       OR p_expected_generation NOT BETWEEN 1 AND 100
       OR p_expected_dispatch_token IS NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE,
            'dispatch_generation', COALESCE(p_expected_generation, 1),
            'dispatch_token', NULL
        );
    END IF;
    SELECT dispatch.* INTO v_dispatch
    FROM public.precheckout_blite_dispatches AS dispatch
    WHERE dispatch.preflight_id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_dispatch.state IS DISTINCT FROM 'enqueued'
       OR v_dispatch.dispatch_generation IS DISTINCT FROM p_expected_generation
       OR v_dispatch.last_dispatch_token IS DISTINCT FROM p_expected_dispatch_token
       OR v_dispatch.dispatch_workload_role IS DISTINCT FROM 'preflight'
       OR v_dispatch.dispatch_contract_version IS DISTINCT FROM 2 THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE,
            'dispatch_generation', COALESCE(v_dispatch.dispatch_generation, p_expected_generation),
            'dispatch_token', NULL
        );
    END IF;
    v_generation := p_expected_generation + 1;
    IF v_generation > 100 THEN
        RAISE EXCEPTION USING MESSAGE = 'PRECHECKOUT_BLITE_DISPATCH_GENERATION_EXHAUSTED', ERRCODE = 'P0001';
    END IF;
    UPDATE public.precheckout_blite_dispatches AS dispatch
    SET state = 'enqueuing',
        dispatch_generation = v_generation,
        dispatch_token = v_new_token,
        last_dispatch_token = NULL,
        attempt_count = dispatch.attempt_count + 1,
        lease_expires_at = v_now + INTERVAL '2 minutes',
        failure_reason = NULL,
        updated_at = v_now
    WHERE dispatch.preflight_id = p_preflight_id
      AND dispatch.state = 'enqueued'
      AND dispatch.dispatch_generation = p_expected_generation
      AND dispatch.last_dispatch_token = p_expected_dispatch_token
      AND dispatch.dispatch_workload_role = 'preflight'
      AND dispatch.dispatch_contract_version = 2;
    IF NOT FOUND THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE,
            'dispatch_generation', p_expected_generation,
            'dispatch_token', NULL
        );
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'should_enqueue', TRUE,
        'dispatch_generation', v_generation,
        'dispatch_token', v_new_token
    );
END;
$$;


--
-- Name: rebind_expired_paid_earlybird_preflight(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebind_expired_paid_earlybird_preflight(p_order_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    c_max_generations CONSTANT INTEGER := 10;
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_user_id_hint UUID;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_new_preflight_id UUID;
    v_capacity_plan TEXT;
    v_required_plan TEXT;
    v_cards JSONB;
    v_capacity_rank INTEGER;
    v_required_rank INTEGER;
    v_plan_id TEXT;
    v_plan_rank INTEGER;
    v_catalog_plan JSONB;
    v_launch_status TEXT;
    v_state TEXT;
    v_reason TEXT;
    v_base_key TEXT;
    v_generation_prefix TEXT;
    v_last_generation INTEGER;
    v_generation INTEGER;
    v_idempotency_key TEXT;
    v_deactivated INTEGER;
BEGIN
    SELECT earlybird_order.user_id INTO v_user_id_hint
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    PERFORM 1
    FROM public.users AS rebind_user
    WHERE rebind_user.id = v_user_id_hint
    FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_order.user_id IS DISTINCT FROM v_user_id_hint THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = v_order.id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    IF v_order.status <> 'paid'
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_order.payment_id IS NULL
       OR v_order.actual_amount_krw IS NULL
       OR v_order.actual_amount_krw < 0
       OR v_order.actual_amount_krw > v_order.expected_amount_krw
       OR v_order.actual_groble_product_id
            IS DISTINCT FROM v_order.expected_groble_product_id
       OR v_fulfillment.status NOT IN (
            'awaiting_operator', 'admission_pending', 'retryable_failure'
       )
       OR (v_preflight.status <> 'expired' AND v_preflight.expires_at > v_now) THEN
        RETURN v_preflight.id;
    END IF;
    IF v_preflight.user_id IS DISTINCT FROM v_order.user_id
       OR v_preflight.access_mode <> 'production'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR NOT public.analysis_v2_valid_launch_snapshot(v_preflight.launch_status_snapshot)
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(v_preflight.plan_catalog_snapshot)
       OR NOT public.analysis_v2_valid_pricing_snapshot(v_preflight.pricing_snapshot)
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(v_preflight.policy_versions_snapshot)
       OR v_order.plan_id NOT IN ('basic', 'standard')
       OR v_preflight.plan_catalog_snapshot->v_order.plan_id->>'launchStatus' <> 'production' THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    v_capacity_rank := NULL;
    v_required_rank := NULL;
    v_cards := '{}'::JSONB;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_catalog_plan := v_preflight.plan_catalog_snapshot->v_plan_id;
        v_launch_status := v_preflight.launch_status_snapshot->>v_plan_id;
        IF v_catalog_plan->>'launchStatus' IS DISTINCT FROM v_launch_status THEN
            RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        IF v_capacity_rank IS NULL
           AND v_order.target_followers_count
                <= (v_catalog_plan->'relationshipCapacity'->>'followers')::INTEGER
           AND v_order.target_following_count
                <= (v_catalog_plan->'relationshipCapacity'->>'following')::INTEGER THEN
            v_capacity_rank := v_plan_rank;
            v_capacity_plan := v_plan_id;
        END IF;
    END LOOP;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        IF v_required_rank IS NULL
           AND v_plan_rank >= v_capacity_rank
           AND v_preflight.launch_status_snapshot->>v_plan_id = 'production' THEN
            v_required_rank := v_plan_rank;
            v_required_plan := v_plan_id;
        END IF;
    END LOOP;
    IF v_capacity_rank IS NULL OR v_required_rank IS NULL
       OR (CASE v_order.plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 END)
            < v_required_rank THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_catalog_plan := v_preflight.plan_catalog_snapshot->v_plan_id;
        v_launch_status := v_preflight.launch_status_snapshot->>v_plan_id;
        IF v_plan_rank < v_capacity_rank THEN
            v_state := 'unavailable'; v_reason := 'below_required_plan';
        ELSIF v_launch_status <> 'production' THEN
            v_state := 'unavailable'; v_reason := 'launch_gate';
        ELSIF v_plan_id = v_required_plan THEN
            v_state := 'required'; v_reason := NULL;
        ELSE
            v_state := 'available_upgrade'; v_reason := NULL;
        END IF;
        v_cards := v_cards || pg_catalog.jsonb_build_object(
            v_plan_id,
            pg_catalog.jsonb_build_object(
                'launchStatus', v_launch_status,
                'relationshipCapacity', v_catalog_plan->'relationshipCapacity',
                'detailedMutualLimit', v_catalog_plan->'detailedMutualLimit',
                'selectionState', v_state,
                'unavailableReason', v_reason
            )
        );
    END LOOP;
    IF NOT public.analysis_v2_valid_plan_cards_snapshot(v_cards) THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FULFILLMENT_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    v_base_key := 'earlybird.fulfillment.'
        || pg_catalog.replace(v_order.id::TEXT, '-', '');
    v_generation_prefix := v_base_key || '.r';
    SELECT pg_catalog.max(
        CASE
            WHEN preflight.idempotency_key = v_base_key THEN 0
            ELSE (pg_catalog.substr(
                preflight.idempotency_key,
                pg_catalog.char_length(v_generation_prefix) + 1
            ))::INTEGER
        END
    ) INTO v_last_generation
    FROM public.analysis_preflights AS preflight
    WHERE preflight.user_id = v_order.user_id
      AND (
          preflight.idempotency_key = v_base_key
          OR (
              pg_catalog.left(
                  preflight.idempotency_key,
                  pg_catalog.char_length(v_generation_prefix)
              ) = v_generation_prefix
              AND pg_catalog.substr(
                  preflight.idempotency_key,
                  pg_catalog.char_length(v_generation_prefix) + 1
              ) ~ '^[0-9]{1,3}$'
          )
      );
    v_generation := COALESCE(v_last_generation + 1, 0);
    IF v_generation >= c_max_generations THEN
        RETURN v_preflight.id;
    END IF;
    v_idempotency_key := CASE
        WHEN v_generation = 0 THEN v_base_key
        ELSE v_generation_prefix || v_generation::TEXT
    END;

    UPDATE public.analysis_preflights AS preflight
    SET status = 'expired',
        lease_token = NULL,
        lease_expires_at = NULL,
        updated_at = v_now
    WHERE preflight.id = v_preflight.id
      AND preflight.consumed_request_id IS NULL
      AND (preflight.status = 'expired' OR preflight.expires_at <= v_now)
      AND preflight.status IN ('pending', 'processing', 'ready', 'expired');
    GET DIAGNOSTICS v_deactivated = ROW_COUNT;
    IF v_deactivated <> 1 THEN
        RETURN v_preflight.id;
    END IF;

    v_new_preflight_id := extensions.gen_random_uuid();
    INSERT INTO public.analysis_preflights(
        id, user_id, idempotency_key, target_instagram_id, status,
        exclusion_decision, excluded_instagram_id, access_mode,
        launch_status_snapshot, plan_catalog_snapshot, plan_cards_snapshot,
        pricing_version, pricing_snapshot, policy_versions_snapshot,
        target_followers_count, target_following_count, target_is_private,
        capacity_required_plan_id, required_plan_id, created_at, updated_at,
        expires_at, ready_at
    ) VALUES (
        v_new_preflight_id, v_order.user_id, v_idempotency_key,
        v_order.target_instagram_id, 'ready', v_order.exclusion_decision,
        v_order.excluded_instagram_id, 'production',
        v_preflight.launch_status_snapshot, v_preflight.plan_catalog_snapshot, v_cards,
        v_preflight.pricing_version, v_preflight.pricing_snapshot,
        v_preflight.policy_versions_snapshot, v_order.target_followers_count,
        v_order.target_following_count, FALSE, v_capacity_plan, v_required_plan,
        v_now, v_now, v_now + INTERVAL '30 minutes', v_now
    );
    UPDATE public.earlybird_orders AS earlybird_order
    SET preflight_id = v_new_preflight_id, updated_at = v_now
    WHERE earlybird_order.id = v_order.id;
    RETURN v_new_preflight_id;
END;
$_$;


--
-- Name: reconcile_analysis_preflight_provider_run_usage(uuid, text, text, text, text, text, numeric, text, numeric, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_analysis_preflight_provider_run_usage(p_preflight_id uuid, p_input_hash text, p_run_id text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric, p_status text, p_actual_usage_usd numeric, p_provider_finished_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.statement_timestamp();
    v_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_logical_provider IS DISTINCT FROM 'apify'
       OR p_actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS DISTINCT FROM 0.002600000000
       OR p_status IS NULL
       OR p_status NOT IN ('succeeded', 'failed', 'aborted', 'timed_out')
       OR p_actual_usage_usd IS NULL
       OR p_actual_usage_usd NOT BETWEEN 0 AND 100000
       OR p_actual_usage_usd <> pg_catalog.round(p_actual_usage_usd, 12)
       OR p_actual_usage_usd > p_max_charge_usd + 0.000000001
       OR p_provider_finished_at IS NULL
       OR p_provider_finished_at > v_now - INTERVAL '30 seconds' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.input_hash = p_input_hash
      AND provider_run.run_id = p_run_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.logical_provider IS DISTINCT FROM p_logical_provider
       OR v_run.actor_id IS DISTINCT FROM p_actor_id
       OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM p_max_charge_usd
       OR v_run.status NOT IN ('running', 'succeeded', 'failed', 'aborted', 'timed_out')
       OR v_run.run_started_at IS NULL
       OR p_provider_finished_at < v_run.reserved_at
       OR p_provider_finished_at < v_run.run_started_at
       OR p_actual_usage_usd > v_run.max_charge_usd + 0.000000001 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_RECONCILIATION_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.status = 'running' THEN
        IF v_run.run_started_at > v_now - INTERVAL '30 seconds' THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_RECONCILIATION_NOT_READY',
                ERRCODE = 'P0001';
        END IF;
        UPDATE public.analysis_preflight_provider_runs AS provider_run
        SET status = p_status,
            actual_usage_usd = p_actual_usage_usd,
            terminalized_at = p_provider_finished_at,
            usage_reconciled_at = v_now,
            updated_at = v_now
        WHERE provider_run.preflight_id = v_run.preflight_id
          AND provider_run.operation_key = v_run.operation_key
        RETURNING provider_run.* INTO v_run;
        PERFORM public.record_analysis_preflight_provider_cost_event(
            v_run.run_id, v_run.logical_provider, v_run.actor_id,
            v_run.credential_slot, v_run.status, v_run.max_charge_usd,
            v_run.actual_usage_usd,
            (p_provider_finished_at AT TIME ZONE 'UTC')::DATE
        );
        RETURN public.analysis_preflight_provider_run_json(v_run);
    END IF;

    IF v_run.status IS DISTINCT FROM p_status OR v_run.terminalized_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_RECONCILIATION_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.terminalized_at > v_now - INTERVAL '30 seconds' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_RECONCILIATION_NOT_READY',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.actual_usage_usd IS NOT NULL THEN
        IF v_run.actual_usage_usd IS DISTINCT FROM p_actual_usage_usd THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_RECONCILIATION_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        PERFORM public.record_analysis_preflight_provider_cost_event(
            v_run.run_id, v_run.logical_provider, v_run.actor_id,
            v_run.credential_slot, v_run.status, v_run.max_charge_usd,
            v_run.actual_usage_usd,
            (p_provider_finished_at AT TIME ZONE 'UTC')::DATE
        );
        RETURN public.analysis_preflight_provider_run_json(v_run);
    END IF;

    UPDATE public.analysis_preflight_provider_runs AS provider_run
    SET actual_usage_usd = p_actual_usage_usd,
        terminalized_at = p_provider_finished_at,
        usage_reconciled_at = v_now,
        updated_at = v_now
    WHERE provider_run.preflight_id = v_run.preflight_id
      AND provider_run.operation_key = v_run.operation_key
    RETURNING provider_run.* INTO v_run;
    PERFORM public.record_analysis_preflight_provider_cost_event(
        v_run.run_id, v_run.logical_provider, v_run.actor_id,
        v_run.credential_slot, v_run.status, v_run.max_charge_usd,
        v_run.actual_usage_usd,
        (p_provider_finished_at AT TIME ZONE 'UTC')::DATE
    );
    RETURN public.analysis_preflight_provider_run_json(v_run);
END;
$_$;


--
-- Name: reconcile_analysis_v2_profile_provider_canary_run_usage(uuid, integer, uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_analysis_v2_profile_provider_canary_run_usage(p_source_request_id uuid, p_repetition integer, p_reservation_token uuid, p_run_id text, p_actual_usage_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_run public.analysis_v2_profile_provider_canary_runs%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL OR p_repetition NOT IN (1, 2)
       OR p_reservation_token IS NULL OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_actual_usage_usd IS NULL OR p_actual_usage_usd < 0
       OR p_actual_usage_usd > 1.000000000000
       OR p_actual_usage_usd <> pg_catalog.round(p_actual_usage_usd, 12) THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT canary_run.* INTO v_run
    FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.repetition = p_repetition
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_run.reservation_token IS DISTINCT FROM p_reservation_token
       OR v_run.run_id IS DISTINCT FROM p_run_id THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_run.state NOT IN ('succeeded', 'failed') THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_run.actual_usage_usd IS NOT NULL THEN
        IF v_run.actual_usage_usd IS DISTINCT FROM p_actual_usage_usd
           OR v_run.cost_status IS DISTINCT FROM 'actual' THEN
            RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_RECONCILIATION_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_profile_provider_canary_run_json(v_run);
    END IF;
    UPDATE public.analysis_v2_profile_provider_canary_runs AS canary_run
    SET actual_usage_usd = p_actual_usage_usd, cost_status = 'actual',
        usage_reconciled_at = v_now, updated_at = v_now
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.repetition = p_repetition
    RETURNING canary_run.* INTO v_run;
    RETURN public.analysis_v2_profile_provider_canary_run_json(v_run);
END;
$_$;


--
-- Name: reconcile_analysis_v2_profile_repair_canary_run_usage(uuid, integer, uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_analysis_v2_profile_repair_canary_run_usage(p_source_request_id uuid, p_repetition integer, p_reservation_token uuid, p_run_id text, p_actual_usage_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_run public.analysis_v2_profile_repair_canary_runs%ROWTYPE;
    v_previous_actual NUMERIC(18, 12);
BEGIN
    IF p_source_request_id IS NULL
       OR p_repetition NOT IN (1, 2)
       OR p_reservation_token IS NULL
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_actual_usage_usd IS NULL
       OR p_actual_usage_usd < 0
       OR p_actual_usage_usd > 0.050000000000
       OR p_actual_usage_usd <> pg_catalog.round(p_actual_usage_usd, 12) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;
    SELECT canary_run.* INTO v_run
    FROM public.analysis_v2_profile_repair_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-repair-canary-v1'
      AND canary_run.repetition = p_repetition
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.reservation_token IS DISTINCT FROM p_reservation_token
       OR v_run.run_id IS DISTINCT FROM p_run_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.state NOT IN ('succeeded', 'failed') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_STATE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.actual_usage_usd IS NOT NULL THEN
        IF v_run.actual_usage_usd IS DISTINCT FROM p_actual_usage_usd
           OR v_run.cost_status IS DISTINCT FROM 'actual'
           OR v_run.usage_reconciled_at IS NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_RECONCILIATION_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_profile_repair_canary_run_json(v_run);
    END IF;
    IF p_repetition = 2 THEN
        SELECT canary_run.actual_usage_usd
        INTO v_previous_actual
        FROM public.analysis_v2_profile_repair_canary_runs AS canary_run
        WHERE canary_run.source_request_id = p_source_request_id
          AND canary_run.canary_version = 'profile-repair-canary-v1'
          AND canary_run.repetition = 1;
        IF v_previous_actual IS NULL
           OR v_previous_actual + p_actual_usage_usd > 0.100000000000 THEN
            RAISE EXCEPTION USING
                MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_RECONCILIATION_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
    END IF;
    UPDATE public.analysis_v2_profile_repair_canary_runs AS canary_run
    SET actual_usage_usd = p_actual_usage_usd,
        cost_status = 'actual',
        usage_reconciled_at = v_now,
        updated_at = v_now
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-repair-canary-v1'
      AND canary_run.repetition = p_repetition
    RETURNING canary_run.* INTO v_run;
    RETURN public.analysis_v2_profile_repair_canary_run_json(v_run);
END;
$_$;


--
-- Name: reconcile_analysis_v2_provider_run_usage(uuid, text, text, text, text, numeric, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_analysis_v2_provider_run_usage(p_reservation_token uuid, p_run_id text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric, p_status text, p_actual_usage_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_run public.analysis_v2_provider_runs%ROWTYPE;
BEGIN
    IF p_reservation_token IS NULL
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_logical_provider IS NULL
       OR p_logical_provider NOT IN ('apify', 'coderx')
       OR p_actor_id IS NULL
       OR pg_catalog.char_length(p_actor_id) NOT BETWEEN 3 AND 200
       OR p_actor_id !~ '^[A-Za-z0-9][A-Za-z0-9._~/-]{2,199}$'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS NULL
       OR p_max_charge_usd NOT BETWEEN 0 AND 100000
       OR p_max_charge_usd <> pg_catalog.round(p_max_charge_usd, 12)
       OR p_status IS NULL
       OR p_status NOT IN ('succeeded', 'failed', 'aborted', 'timed_out')
       OR p_actual_usage_usd IS NULL
       OR p_actual_usage_usd NOT BETWEEN 0 AND 100000
       OR p_actual_usage_usd <> pg_catalog.round(p_actual_usage_usd, 12) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.reservation_token = p_reservation_token
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.run_id IS DISTINCT FROM p_run_id
       OR v_run.logical_provider IS DISTINCT FROM p_logical_provider
       OR v_run.actor_id IS DISTINCT FROM p_actor_id
       OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM p_max_charge_usd
       OR v_run.status IS DISTINCT FROM p_status
       OR v_run.status NOT IN ('succeeded', 'failed', 'aborted', 'timed_out')
       OR v_run.terminalized_at IS NULL
       OR p_actual_usage_usd > v_run.max_charge_usd + 0.000000001 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_RECONCILIATION_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.terminalized_at > (v_now - INTERVAL '30 seconds') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_RECONCILIATION_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.actual_usage_usd IS NOT NULL THEN
        IF v_run.actual_usage_usd IS DISTINCT FROM p_actual_usage_usd THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_RECONCILIATION_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_provider_run_json(v_run);
    END IF;

    UPDATE public.analysis_v2_provider_runs AS provider_run
    SET actual_usage_usd = p_actual_usage_usd,
        usage_reconciled_at = v_now,
        updated_at = v_now
    WHERE provider_run.request_id = v_run.request_id
      AND provider_run.job_key = v_run.job_key
      AND provider_run.operation_key = v_run.operation_key
    RETURNING provider_run.* INTO v_run;

    RETURN public.analysis_v2_provider_run_json(v_run);
END;
$_$;


--
-- Name: reconcile_earlybird_checkout_no_sale(uuid, timestamp with time zone, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_earlybird_checkout_no_sale(p_order_id uuid, p_provider_checked_at timestamp with time zone, p_reason text, p_confirm_provider_dashboard_no_sale boolean) RETURNS TABLE(disposition text, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_order public.earlybird_orders%ROWTYPE;
    v_existing public.earlybird_checkout_reconciliations%ROWTYPE;
    v_user_id UUID;
    v_now TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_order_id IS NULL
       OR p_reason IS DISTINCT FROM 'provider_dashboard_no_sale'
       OR p_confirm_provider_dashboard_no_sale IS NOT TRUE
       OR p_provider_checked_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_RECONCILIATION_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.user_id
    INTO v_user_id
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_RECONCILIATION_NOT_ELIGIBLE',
            ERRCODE = 'P0001';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(v_user_id::TEXT, 0)
    );

    SELECT earlybird_order.*
    INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;

    SELECT reconciliation.*
    INTO v_existing
    FROM public.earlybird_checkout_reconciliations AS reconciliation
    WHERE reconciliation.order_id = p_order_id
    FOR UPDATE;

    IF FOUND THEN
        IF v_order.status = v_existing.terminal_status
           AND v_existing.reason = p_reason
           AND v_existing.provider_checked_at = p_provider_checked_at THEN
            RETURN QUERY SELECT 'already_reconciled'::TEXT, v_order.status::TEXT;
            RETURN;
        END IF;
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_RECONCILIATION_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    v_now := pg_catalog.clock_timestamp();
    IF p_provider_checked_at > v_now
       OR p_provider_checked_at < v_now - INTERVAL '24 hours'
       OR p_provider_checked_at < v_order.created_at THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_RECONCILIATION_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    IF v_order.status NOT IN ('payment_pending', 'cancelled')
       OR v_order.payment_id IS NOT NULL
       OR v_order.actual_amount_krw IS NOT NULL
       OR v_order.paid_at IS NOT NULL
       OR v_order.seller_reference_confirmed_at IS NOT NULL
       OR v_order.result_request_id IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_RECONCILIATION_NOT_ELIGIBLE',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.earlybird_orders AS earlybird_order
    SET status = 'payment_failed',
        updated_at = v_now
    WHERE earlybird_order.id = v_order.id;

    INSERT INTO public.earlybird_checkout_reconciliations (
        order_id,
        prior_status,
        terminal_status,
        reason,
        provider_checked_at,
        reconciled_at
    ) VALUES (
        v_order.id,
        v_order.status,
        'payment_failed',
        p_reason,
        p_provider_checked_at,
        v_now
    );

    RETURN QUERY SELECT 'reconciled'::TEXT, 'payment_failed'::TEXT;
END;
$$;


--
-- Name: reconcile_earlybird_fulfillments(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_earlybird_fulfillments(p_limit integer DEFAULT 100) RETURNS TABLE(scanned integer, completed integer, manual_review integer, retryable integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_row RECORD;
    v_scanned INTEGER := 0;
    v_completed INTEGER := 0;
    v_manual_review INTEGER := 0;
    v_retryable INTEGER := 0;
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FULFILLMENT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    FOR v_row IN
        SELECT
            fulfillment.order_id,
            fulfillment.status,
            fulfillment.request_id,
            fulfillment.lease_token,
            fulfillment.lease_expires_at,
            earlybird_order.user_id AS order_user_id,
            earlybird_order.status AS order_status,
            earlybird_order.result_request_id,
            analysis_request.user_id AS request_user_id,
            analysis_request.status AS request_status,
            analysis_request.status = 'completed' AS request_completed,
            analysis_request.status = 'failed' AS request_failed
        FROM public.earlybird_fulfillments AS fulfillment
        JOIN public.earlybird_orders AS earlybird_order
          ON earlybird_order.id = fulfillment.order_id
        LEFT JOIN public.analysis_requests AS analysis_request
          ON analysis_request.id = fulfillment.request_id
        WHERE (
            fulfillment.status = 'analysis_in_progress'
            OR (
                fulfillment.status IN (
                    'admission_pending',
                    'retryable_failure'
                )
                AND fulfillment.lease_token IS NOT NULL
                AND fulfillment.lease_expires_at <= v_now
            )
        )
        ORDER BY fulfillment.updated_at, fulfillment.order_id
        LIMIT p_limit
        FOR UPDATE OF fulfillment, earlybird_order
    LOOP
        v_scanned := v_scanned + 1;
        IF v_row.status IN ('admission_pending', 'retryable_failure') THEN
            UPDATE public.earlybird_fulfillments AS fulfillment
            SET status = 'retryable_failure',
                lease_token = NULL,
                lease_expires_at = NULL,
                next_attempt_at = v_now,
                last_error_code = 'LEASE_EXPIRED',
                last_error_at = v_now,
                updated_at = v_now
            WHERE fulfillment.order_id = v_row.order_id;
            v_retryable := v_retryable + 1;
        ELSIF v_row.order_status <> 'analysis_in_progress' THEN
            UPDATE public.earlybird_fulfillments AS fulfillment
            SET status = 'manual_review',
                last_error_code = 'PAYMENT_STATE',
                last_error_at = v_now,
                manual_review_at = v_now,
                updated_at = v_now
            WHERE fulfillment.order_id = v_row.order_id;
            v_manual_review := v_manual_review + 1;
        ELSIF v_row.request_id IS NULL
           OR v_row.result_request_id IS DISTINCT FROM v_row.request_id
           OR v_row.request_user_id IS DISTINCT FROM v_row.order_user_id
           OR v_row.request_status IS NULL THEN
            UPDATE public.earlybird_fulfillments AS fulfillment
            SET status = 'manual_review',
                last_error_code = 'REQUEST_CONFLICT',
                last_error_at = v_now,
                manual_review_at = v_now,
                updated_at = v_now
            WHERE fulfillment.order_id = v_row.order_id;
            v_manual_review := v_manual_review + 1;
        ELSIF v_row.request_completed THEN
            UPDATE public.earlybird_fulfillments AS fulfillment
            SET status = 'completed',
                completed_at = v_now,
                updated_at = v_now
            WHERE fulfillment.order_id = v_row.order_id;
            UPDATE public.earlybird_orders AS earlybird_order
            SET status = 'completed',
                updated_at = v_now
            WHERE earlybird_order.id = v_row.order_id;
            v_completed := v_completed + 1;
        ELSIF v_row.request_failed THEN
            UPDATE public.earlybird_fulfillments AS fulfillment
            SET status = 'manual_review',
                last_error_code = 'ANALYSIS_FAILED',
                last_error_at = v_now,
                manual_review_at = v_now,
                updated_at = v_now
            WHERE fulfillment.order_id = v_row.order_id;
            v_manual_review := v_manual_review + 1;
        END IF;
    END LOOP;

    RETURN QUERY SELECT
        v_scanned,
        v_completed,
        v_manual_review,
        v_retryable;
END;
$$;


--
-- Name: reconcile_stale_earlybird_payment_discord_claims(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_stale_earlybird_payment_discord_claims(p_lease_seconds integer DEFAULT 900) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_count integer;
BEGIN
    UPDATE public.earlybird_payment_discord_outbox
    SET status = 'ambiguous_failed',
        failure_code = 'DISCORD_CLAIM_LEASE_EXPIRED_AMBIGUOUS',
        claim_token = NULL,
        claimed_at = NULL,
        updated_at = clock_timestamp()
    WHERE status = 'sending'
      AND claimed_at < clock_timestamp()
            - make_interval(secs => LEAST(
                GREATEST(COALESCE(p_lease_seconds, 900), 60),
                3600
            ));
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


