-- Name: reconcile_stale_kakao_signup_discord_claims(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_stale_kakao_signup_discord_claims(p_lease_seconds integer DEFAULT 900) RETURNS integer
