--
-- Name: reconcile_stale_maintenance_jobs_v1(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_stale_maintenance_jobs_v1(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100 THEN
        RAISE EXCEPTION USING MESSAGE = 'MAINTENANCE_RECONCILE_LIMIT_INVALID', ERRCODE = 'P0001';
    END IF;
    WITH stale AS (
        SELECT maintenance.id
        FROM public.maintenance_jobs AS maintenance
        WHERE maintenance.state = 'leased'
          AND maintenance.lease_expires_at IS NOT NULL
          AND maintenance.lease_expires_at <= pg_catalog.clock_timestamp()
        ORDER BY maintenance.lease_expires_at, maintenance.created_at
        LIMIT p_limit
        FOR UPDATE SKIP LOCKED
    )
    UPDATE public.maintenance_jobs AS maintenance
    SET state = CASE WHEN attempt_count >= 1000 THEN 'blocked' ELSE 'retryable' END,
        next_attempt_at = pg_catalog.clock_timestamp(),
        terminal_at = CASE WHEN attempt_count >= 1000 THEN pg_catalog.clock_timestamp() ELSE terminal_at END,
        last_error_code = 'LEASE_EXPIRED',
        lease_token = NULL,
        lease_holder_hash = NULL,
        lease_expires_at = NULL,
        updated_at = pg_catalog.clock_timestamp()
    FROM stale
    WHERE maintenance.id = stale.id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN pg_catalog.jsonb_build_object('status', 'reconciled', 'count', v_count);
END;
$$;


--
-- Name: reconcile_stale_sentry_discord_alert_claims(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_stale_sentry_discord_alert_claims(p_lease_seconds integer DEFAULT 300) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_count integer;
BEGIN
    UPDATE public.sentry_discord_alert_outbox
    SET status = CASE
            WHEN delivery_started_at IS NULL AND attempts < 3 THEN 'pending'
            WHEN delivery_started_at IS NULL THEN 'failed'
            ELSE 'ambiguous_failed'
        END,
        next_attempt_at = CASE
            WHEN delivery_started_at IS NULL AND attempts < 3 THEN clock_timestamp()
            ELSE next_attempt_at
        END,
        failure_code = CASE
            WHEN delivery_started_at IS NULL AND attempts < 3 THEN 'DISCORD_CLAIM_LEASE_RECOVERED_BEFORE_SEND'
            WHEN delivery_started_at IS NULL THEN 'DISCORD_CLAIM_LEASE_EXPIRED_RETRY_EXHAUSTED'
            ELSE 'DISCORD_CLAIM_LEASE_EXPIRED_AMBIGUOUS'
        END,
        claim_token = NULL,
        claimed_at = NULL,
        updated_at = clock_timestamp()
    WHERE status = 'sending'
      AND claimed_at < clock_timestamp()
            - make_interval(secs => LEAST(GREATEST(COALESCE(p_lease_seconds, 300), 60), 900));
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


--
-- Name: record_analysis_gemini_usage_expectation(uuid, uuid, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_analysis_gemini_usage_expectation(p_request_id uuid, p_user_id uuid, p_expected_step text, p_operation_key text, p_generation_kind text, p_expected_record_count integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    existing public.analysis_gemini_usage_expectations%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_user_id IS NULL
       OR p_expected_step NOT IN ('collect', 'analyze', 'deep_analysis')
       OR p_operation_key IS NULL
       OR p_operation_key !~ '^(private-names|combined:(0|[1-9][0-9]{0,6}):(0|[1-9][0-9]{0,6})|deep-risk:0)$'
       OR p_generation_kind NOT IN ('private_names', 'combined', 'deep_risk')
       OR p_expected_record_count IS NULL
       OR p_expected_record_count NOT BETWEEN 1 AND 10000
       OR (p_generation_kind = 'private_names' AND p_expected_step <> 'collect')
       OR (p_generation_kind = 'combined' AND p_expected_step <> 'analyze')
       OR (p_generation_kind = 'deep_risk' AND p_expected_step <> 'deep_analysis') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_GEMINI_EXPECTATION_INVALID',
            ERRCODE = '22023';
    END IF;

    PERFORM 1
    FROM public.analysis_requests
    WHERE id = p_request_id
      AND user_id = p_user_id
      AND status IN ('pending', 'processing')
      AND COALESCE(current_step, 'pending') = p_expected_step
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    SELECT *
    INTO existing
    FROM public.analysis_gemini_usage_expectations
    WHERE request_id = p_request_id
      AND operation_key = p_operation_key;

    IF FOUND THEN
        IF existing.generation_kind <> p_generation_kind
           OR existing.expected_record_count <> p_expected_record_count THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_GEMINI_EXPECTATION_MISMATCH',
                ERRCODE = '22023';
        END IF;
        RETURN TRUE;
    END IF;

    INSERT INTO public.analysis_gemini_usage_expectations (
        request_id,
        operation_key,
        generation_kind,
        expected_record_count
    ) VALUES (
        p_request_id,
        p_operation_key,
        p_generation_kind,
        p_expected_record_count
    );
    RETURN TRUE;
END;
$_$;


--
-- Name: record_analysis_preflight_identity_drift_cost_event(uuid, text, text, text, text, text, numeric, timestamp with time zone, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_analysis_preflight_identity_drift_cost_event(p_preflight_id uuid, p_operation_key text, p_input_hash text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric, p_reserved_at timestamp with time zone, p_evidence_reference_hash text, p_resolution_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_billing_identity_hash TEXT;
    v_event public.analysis_preflight_acquisition_cost_events%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_operation_key IS DISTINCT FROM 'target-profile-fallback'
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_logical_provider IS DISTINCT FROM 'apify'
       OR p_actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS DISTINCT FROM 0.002600000000
       OR p_reserved_at IS NULL
       OR p_evidence_reference_hash IS NULL
       OR p_evidence_reference_hash !~ '^[0-9a-f]{64}$'
       OR p_resolution_date IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_IDENTITY_DRIFT_COST_EVENT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_billing_identity_hash := pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'provider_start_identity_drift:v1:'
                    || p_preflight_id::TEXT || ':'
                    || p_operation_key || ':'
                    || p_input_hash || ':'
                    || p_logical_provider || ':'
                    || p_actor_id || ':'
                    || p_credential_slot || ':'
                    || p_max_charge_usd::TEXT || ':'
                    || pg_catalog.to_char(
                        p_reserved_at AT TIME ZONE 'UTC',
                        'YYYY-MM-DD"T"HH24:MI:SS.US'
                    ) || ':'
                    || p_evidence_reference_hash || ':'
                    || p_resolution_date::TEXT,
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );

    INSERT INTO public.analysis_preflight_acquisition_cost_events (
        billing_identity_hash,
        event_kind,
        logical_provider,
        actor_id,
        credential_slot,
        terminal_status,
        max_charge_usd,
        actual_usage_usd,
        evidence_reference_hash,
        event_date
    ) VALUES (
        v_billing_identity_hash,
        'provider_start_identity_drift',
        p_logical_provider,
        p_actor_id,
        p_credential_slot,
        'resolved_identity_drift',
        p_max_charge_usd,
        p_max_charge_usd,
        p_evidence_reference_hash,
        p_resolution_date
    )
    ON CONFLICT (billing_identity_hash) DO NOTHING
    RETURNING * INTO v_event;

    IF FOUND THEN
        RETURN;
    END IF;

    SELECT event.*
    INTO v_event
    FROM public.analysis_preflight_acquisition_cost_events AS event
    WHERE event.billing_identity_hash = v_billing_identity_hash
    FOR UPDATE;

    -- The event contract intentionally records actual_usage_usd = max_charge_usd.
    IF NOT FOUND
       OR v_event.billing_identity_hash IS DISTINCT FROM v_billing_identity_hash
       OR v_event.event_kind IS DISTINCT FROM 'provider_start_identity_drift'
       OR v_event.logical_provider IS DISTINCT FROM p_logical_provider
       OR v_event.actor_id IS DISTINCT FROM p_actor_id
       OR v_event.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_event.terminal_status IS DISTINCT FROM 'resolved_identity_drift'
       OR v_event.max_charge_usd IS DISTINCT FROM p_max_charge_usd
       OR v_event.actual_usage_usd IS DISTINCT FROM p_max_charge_usd
       OR v_event.evidence_reference_hash IS DISTINCT FROM p_evidence_reference_hash
       OR v_event.event_date IS DISTINCT FROM p_resolution_date THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_ACQUISITION_COST_EVENT_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
END;
$_$;


--
-- Name: record_analysis_preflight_manual_no_run_cost_event(uuid, text, text, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_analysis_preflight_manual_no_run_cost_event(p_preflight_id uuid, p_evidence_reference_hash text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_resolution_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_billing_identity_hash TEXT;
    v_event public.analysis_preflight_acquisition_cost_events%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_evidence_reference_hash IS NULL
       OR p_evidence_reference_hash !~ '^[0-9a-f]{64}$'
       OR p_logical_provider IS DISTINCT FROM 'apify'
       OR p_actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_resolution_date IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_ACQUISITION_COST_EVENT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_billing_identity_hash := pg_catalog.encode(
        pg_catalog.sha256(
            pg_catalog.convert_to(
                'manual_no_run:' || p_preflight_id::TEXT || ':'
                    || p_evidence_reference_hash,
                'UTF8'
            )
        ),
        'hex'
    );

    INSERT INTO public.analysis_preflight_acquisition_cost_events (
        billing_identity_hash,
        event_kind,
        logical_provider,
        actor_id,
        credential_slot,
        terminal_status,
        max_charge_usd,
        actual_usage_usd,
        evidence_reference_hash,
        event_date
    ) VALUES (
        v_billing_identity_hash,
        'manual_no_run',
        p_logical_provider,
        p_actor_id,
        p_credential_slot,
        'resolved_no_run',
        0,
        0,
        p_evidence_reference_hash,
        p_resolution_date
    )
    ON CONFLICT (billing_identity_hash) DO NOTHING
    RETURNING * INTO v_event;

    IF FOUND THEN
        RETURN;
    END IF;

    SELECT event.*
    INTO v_event
    FROM public.analysis_preflight_acquisition_cost_events AS event
    WHERE event.billing_identity_hash = v_billing_identity_hash
    FOR UPDATE;

    IF NOT FOUND
       OR v_event.event_kind IS DISTINCT FROM 'manual_no_run'
       OR v_event.logical_provider IS DISTINCT FROM p_logical_provider
       OR v_event.actor_id IS DISTINCT FROM p_actor_id
       OR v_event.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_event.terminal_status IS DISTINCT FROM 'resolved_no_run'
       OR v_event.max_charge_usd IS DISTINCT FROM 0
       OR v_event.actual_usage_usd IS DISTINCT FROM 0
       OR v_event.evidence_reference_hash IS DISTINCT FROM p_evidence_reference_hash
       OR v_event.event_date IS DISTINCT FROM p_resolution_date THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_ACQUISITION_COST_EVENT_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
END;
$_$;


