--
-- Name: record_analysis_provider_cost_started(uuid, uuid, text, text, text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_analysis_provider_cost_started(p_request_id uuid, p_user_id uuid, p_expected_step text, p_operation_key text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_run_id text, p_max_charge_usd numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    existing public.analysis_provider_cost_ledger%ROWTYPE;
    affected_rows INTEGER;
BEGIN
    IF p_request_id IS NULL
       OR p_user_id IS NULL
       OR p_operation_key IS NULL
       OR p_operation_key !~ '^(profile:target|profiles:(0|[1-9][0-9]{0,6})|relationship:(followers|following)|interaction:(target_likers|target_comments|candidate_likers):(0|[1-9][0-9]{0,6}))$'
       OR p_logical_provider IS NULL
       OR p_logical_provider NOT IN ('apify', 'coderx')
       OR p_actor_id IS NULL
       OR p_actor_id !~ '^[A-Za-z0-9][A-Za-z0-9._~/-]{2,199}$'
       OR p_credential_slot IS NULL
       OR p_credential_slot NOT IN ('primary', 'secondary')
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_max_charge_usd IS NULL
       OR p_max_charge_usd::TEXT IN ('NaN', 'Infinity', '-Infinity')
       OR p_max_charge_usd < 0
       OR p_max_charge_usd > 100000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PROVIDER_COST_INVALID',
            ERRCODE = '22023';
    END IF;

    IF p_expected_step IS NULL OR NOT (
        (p_expected_step = 'collect' AND p_operation_key ~ '^(profile:target|relationship:)')
        OR (p_expected_step = 'profiles' AND p_operation_key ~ '^profiles:')
        OR (p_expected_step = 'interactions' AND p_operation_key ~ '^interaction:')
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PROVIDER_COST_INVALID_STEP',
            ERRCODE = '22023';
    END IF;

    -- The same run is an idempotent success even after the request advances or
    -- reaches a terminal state. Every identity field still has to match.
    SELECT *
    INTO existing
    FROM public.analysis_provider_cost_ledger
    WHERE run_id = p_run_id
    FOR UPDATE;
    IF FOUND THEN
        IF (existing.request_id IS NOT NULL AND existing.request_id <> p_request_id)
           OR existing.operation_key <> p_operation_key
           OR existing.logical_provider <> p_logical_provider
           OR existing.actor_id <> p_actor_id
           OR existing.credential_slot <> p_credential_slot
           OR existing.max_charge_usd <> p_max_charge_usd THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_COST_RUN_CONFLICT',
                ERRCODE = '23505';
        END IF;
        RETURN TRUE;
    END IF;

    -- A new run may only be linked to the owner at the exact active pipeline step.
    PERFORM 1
    FROM public.analysis_requests
    WHERE id = p_request_id
      AND user_id = p_user_id
      AND status IN ('pending', 'processing')
      AND COALESCE(current_step, 'pending') = p_expected_step
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    SELECT *
    INTO existing
    FROM public.analysis_provider_cost_ledger
    WHERE request_id = p_request_id
      AND operation_key = p_operation_key
    FOR UPDATE;
    IF FOUND THEN
        IF existing.run_id <> p_run_id
           OR existing.logical_provider <> p_logical_provider
           OR existing.actor_id <> p_actor_id
           OR existing.credential_slot <> p_credential_slot
           OR existing.max_charge_usd <> p_max_charge_usd THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_COST_OPERATION_CONFLICT',
                ERRCODE = '23505';
        END IF;
        RETURN TRUE;
    END IF;

    INSERT INTO public.analysis_provider_cost_ledger (
        run_id,
        request_id,
        operation_key,
        logical_provider,
        actor_id,
        credential_slot,
        status,
        max_charge_usd
    ) VALUES (
        p_run_id,
        p_request_id,
        p_operation_key,
        p_logical_provider,
        p_actor_id,
        p_credential_slot,
        'running',
        p_max_charge_usd
    )
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    IF affected_rows = 1 THEN
        RETURN TRUE;
    END IF;

    -- A concurrent insertion can only be accepted if it is the exact same event.
    SELECT *
    INTO existing
    FROM public.analysis_provider_cost_ledger
    WHERE run_id = p_run_id
       OR (request_id = p_request_id AND operation_key = p_operation_key)
    ORDER BY (run_id = p_run_id) DESC
    LIMIT 1
    FOR UPDATE;
    IF FOUND
       AND existing.run_id = p_run_id
       AND existing.request_id IS NOT DISTINCT FROM p_request_id
       AND existing.operation_key = p_operation_key
       AND existing.logical_provider = p_logical_provider
       AND existing.actor_id = p_actor_id
       AND existing.credential_slot = p_credential_slot
       AND existing.max_charge_usd = p_max_charge_usd THEN
        RETURN TRUE;
    END IF;

    RAISE EXCEPTION USING
        MESSAGE = 'ANALYSIS_PROVIDER_COST_CONFLICT',
        ERRCODE = '23505';
END;
$_$;


--
-- Name: record_analysis_provider_cost_terminal(uuid, uuid, text, text, text, text, text, text, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_analysis_provider_cost_terminal(p_request_id uuid, p_user_id uuid, p_expected_step text, p_operation_key text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_run_id text, p_status text, p_max_charge_usd numeric, p_usage_total_usd numeric DEFAULT NULL::numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    existing public.analysis_provider_cost_ledger%ROWTYPE;
    affected_rows INTEGER;
BEGIN
    IF p_request_id IS NULL
       OR p_user_id IS NULL
       OR p_operation_key IS NULL
       OR p_operation_key !~ '^(profile:target|profiles:(0|[1-9][0-9]{0,6})|relationship:(followers|following)|interaction:(target_likers|target_comments|candidate_likers):(0|[1-9][0-9]{0,6}))$'
       OR p_logical_provider IS NULL
       OR p_logical_provider NOT IN ('apify', 'coderx')
       OR p_actor_id IS NULL
       OR p_actor_id !~ '^[A-Za-z0-9][A-Za-z0-9._~/-]{2,199}$'
       OR p_credential_slot IS NULL
       OR p_credential_slot NOT IN ('primary', 'secondary')
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_status IS NULL
       OR p_status NOT IN ('succeeded', 'failed', 'aborted', 'timed_out')
       OR p_max_charge_usd IS NULL
       OR p_max_charge_usd::TEXT IN ('NaN', 'Infinity', '-Infinity')
       OR p_max_charge_usd < 0
       OR p_max_charge_usd > 100000
       OR (
           p_usage_total_usd IS NOT NULL
           AND (
               p_usage_total_usd::TEXT IN ('NaN', 'Infinity', '-Infinity')
               OR p_usage_total_usd < 0
               OR p_usage_total_usd > 100000
           )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PROVIDER_COST_INVALID',
            ERRCODE = '22023';
    END IF;

    IF p_expected_step IS NULL OR NOT (
        (p_expected_step = 'collect' AND p_operation_key ~ '^(profile:target|relationship:)')
        OR (p_expected_step = 'profiles' AND p_operation_key ~ '^profiles:')
        OR (p_expected_step = 'interactions' AND p_operation_key ~ '^interaction:')
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PROVIDER_COST_INVALID_STEP',
            ERRCODE = '22023';
    END IF;

    SELECT *
    INTO existing
    FROM public.analysis_provider_cost_ledger
    WHERE run_id = p_run_id
    FOR UPDATE;
    IF FOUND THEN
        IF (existing.request_id IS NOT NULL AND existing.request_id <> p_request_id)
           OR existing.operation_key <> p_operation_key
           OR existing.logical_provider <> p_logical_provider
           OR existing.actor_id <> p_actor_id
           OR existing.credential_slot <> p_credential_slot
           OR existing.max_charge_usd <> p_max_charge_usd THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_COST_RUN_CONFLICT',
                ERRCODE = '23505';
        END IF;

        IF existing.status = 'running' THEN
            UPDATE public.analysis_provider_cost_ledger
            SET status = p_status,
                usage_total_usd = NULL,
                terminal_at = clock_timestamp(),
                updated_at = clock_timestamp()
            WHERE run_id = p_run_id;
            RETURN TRUE;
        END IF;

        IF existing.status <> p_status THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_COST_TERMINAL_CONFLICT',
                ERRCODE = '23505';
        END IF;

        RETURN TRUE;
    END IF;

    PERFORM 1
    FROM public.analysis_requests
    WHERE id = p_request_id
      AND user_id = p_user_id
      AND status IN ('pending', 'processing')
      AND COALESCE(current_step, 'pending') = p_expected_step
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    SELECT *
    INTO existing
    FROM public.analysis_provider_cost_ledger
    WHERE request_id = p_request_id
      AND operation_key = p_operation_key
    FOR UPDATE;
    IF FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PROVIDER_COST_OPERATION_CONFLICT',
            ERRCODE = '23505';
    END IF;

    INSERT INTO public.analysis_provider_cost_ledger (
        run_id,
        request_id,
        operation_key,
        logical_provider,
        actor_id,
        credential_slot,
        status,
        max_charge_usd,
        usage_total_usd,
        terminal_at
    ) VALUES (
        p_run_id,
        p_request_id,
        p_operation_key,
        p_logical_provider,
        p_actor_id,
        p_credential_slot,
        p_status,
        p_max_charge_usd,
        NULL,
        clock_timestamp()
    )
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    IF affected_rows = 1 THEN
        RETURN TRUE;
    END IF;

    SELECT *
    INTO existing
    FROM public.analysis_provider_cost_ledger
    WHERE run_id = p_run_id
       OR (request_id = p_request_id AND operation_key = p_operation_key)
    ORDER BY (run_id = p_run_id) DESC
    LIMIT 1
    FOR UPDATE;
    IF FOUND
       AND existing.run_id = p_run_id
       AND existing.request_id IS NOT DISTINCT FROM p_request_id
       AND existing.operation_key = p_operation_key
       AND existing.logical_provider = p_logical_provider
       AND existing.actor_id = p_actor_id
       AND existing.credential_slot = p_credential_slot
       AND existing.status = p_status
       AND existing.max_charge_usd = p_max_charge_usd THEN
        RETURN TRUE;
    END IF;

    RAISE EXCEPTION USING
        MESSAGE = 'ANALYSIS_PROVIDER_COST_CONFLICT',
        ERRCODE = '23505';
END;
$_$;


--
-- Name: record_analysis_revenue_coverage_gate_v1(uuid, text, uuid, text, integer, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_analysis_revenue_coverage_gate_v1(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_public_mutual_count integer, p_screened_count integer, p_not_screened_count integer, p_unknown_burden_count integer, p_coverage_valid boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_existing public.analysis_revenue_final_coverage_gates%ROWTYPE;
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_valid BOOLEAN;
BEGIN
    IF p_job_key IS DISTINCT FROM 'coordinator:finalize'
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_public_mutual_count IS NULL
       OR p_screened_count IS NULL
       OR p_not_screened_count IS NULL
       OR p_unknown_burden_count IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    PERFORM public.analysis_revenue_ai_cost_assert_lineage_v1(
        p_request_id, p_job_key, p_job_claim_token, p_job_input_hash, TRUE
    );
    PERFORM public.analysis_revenue_ai_cost_assert_parent_v1(p_request_id);
    SELECT * INTO v_parent
      FROM public.analysis_revenue_run_ledgers
     WHERE request_id = p_request_id
     FOR UPDATE;

    v_valid := p_coverage_valid IS TRUE
        AND p_public_mutual_count >= 0
        AND p_screened_count >= 0
        AND p_not_screened_count >= 0
        AND p_unknown_burden_count >= 0
        AND p_screened_count + p_not_screened_count = p_public_mutual_count
        AND p_unknown_burden_count <= p_screened_count
        -- A zero selected cohort is valid only when there was no public cohort.
        AND (p_public_mutual_count = 0 OR p_screened_count > 0)
        -- Exact integer semantics: exactly 30 percent passes; greater fails.
        AND p_unknown_burden_count * 10 <= p_screened_count * 3;

    SELECT * INTO v_existing
      FROM public.analysis_revenue_final_coverage_gates
     WHERE request_id = p_request_id
     FOR UPDATE;
    IF v_existing.request_id IS NOT NULL THEN
        IF v_existing.job_key IS DISTINCT FROM p_job_key
           OR v_existing.job_input_hash IS DISTINCT FROM p_job_input_hash
           OR v_existing.public_mutual_count IS DISTINCT FROM p_public_mutual_count
           OR v_existing.screened_count IS DISTINCT FROM p_screened_count
           OR v_existing.not_screened_count IS DISTINCT FROM p_not_screened_count
           OR v_existing.unknown_burden_count IS DISTINCT FROM p_unknown_burden_count
           OR v_parent.public_mutual_count IS DISTINCT FROM p_public_mutual_count
           OR v_parent.screened_count IS DISTINCT FROM p_screened_count
           OR v_parent.not_screened_count IS DISTINCT FROM p_not_screened_count
           OR v_parent.unknown_burden_count IS DISTINCT FROM p_unknown_burden_count THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_DRIFT';
        END IF;
        IF v_existing.disposition = 'accepted'
           AND v_valid
           AND v_parent.status = 'running'
           AND v_parent.manual_review_reason IS NULL THEN
            RETURN pg_catalog.jsonb_build_object(
                'disposition', 'accepted', 'created', FALSE, 'replayed', TRUE
            );
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'manual_review', 'created', FALSE, 'replayed', TRUE
        );
    END IF;

    IF v_valid
       AND v_parent.status = 'running'
       AND v_parent.manual_review_reason IS NULL THEN
        INSERT INTO public.analysis_revenue_final_coverage_gates(
            request_id, job_key, job_input_hash, public_mutual_count,
            screened_count, not_screened_count, unknown_burden_count, disposition
        ) VALUES (
            p_request_id, p_job_key, p_job_input_hash, p_public_mutual_count,
            p_screened_count, p_not_screened_count, p_unknown_burden_count, 'accepted'
        );
        UPDATE public.analysis_revenue_run_ledgers
           SET public_mutual_count = p_public_mutual_count,
               screened_count = p_screened_count,
               not_screened_count = p_not_screened_count,
               unknown_burden_count = p_unknown_burden_count
         WHERE request_id = p_request_id;
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'accepted', 'created', TRUE, 'replayed', FALSE
        );
    END IF;

    INSERT INTO public.analysis_revenue_final_coverage_gates(
        request_id, job_key, job_input_hash, public_mutual_count,
        screened_count, not_screened_count, unknown_burden_count, disposition
    ) VALUES (
        p_request_id, p_job_key, p_job_input_hash, p_public_mutual_count,
        p_screened_count, p_not_screened_count, p_unknown_burden_count, 'manual_review'
    );
    UPDATE public.analysis_revenue_run_ledgers
       SET public_mutual_count = p_public_mutual_count,
           screened_count = p_screened_count,
           not_screened_count = p_not_screened_count,
           unknown_burden_count = p_unknown_burden_count,
           status = 'manual_review',
           manual_review_reason = CASE
               WHEN manual_review_reason IN (
                   'cost_overrun', 'cost_denied', 'ambiguous_external_call'
               ) THEN manual_review_reason
               ELSE 'routing_failure'
           END
     WHERE request_id = p_request_id;
    RETURN pg_catalog.jsonb_build_object(
        'disposition', 'manual_review', 'created', TRUE, 'replayed', FALSE
    );
END;
$_$;


--
-- Name: record_analysis_revenue_fresh_provider_evidence_v1(uuid, text, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_analysis_revenue_fresh_provider_evidence_v1(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_operation_key text, p_provider_input_hash text, p_provider_run_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_provider public.analysis_v2_provider_runs%ROWTYPE;
    v_existing public.analysis_revenue_fresh_provider_evidence%ROWTYPE;
    v_operation_hash TEXT;
    v_expected_run_hash TEXT;
BEGIN
    IF p_provider_run_hash IS NULL OR p_provider_run_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_FENCE', ERRCODE = 'P0001';
    END IF;
    -- The admission function obtains the canonical lock sequence:
    -- preflight → request → job → provider/source → revenue parent.
    PERFORM public.assert_analysis_revenue_fresh_provider_admission_v1(
        p_request_id, p_job_key, p_job_claim_token, p_job_input_hash,
        p_operation_key, p_provider_input_hash
    );

    SELECT * INTO v_provider
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    FOR UPDATE;
    SELECT * INTO v_parent
    FROM public.analysis_revenue_run_ledgers AS ledger
    WHERE ledger.request_id = p_request_id
    FOR UPDATE;
    IF v_provider.request_id IS NULL
       OR v_provider.logical_provider IS DISTINCT FROM 'apify'
       OR v_provider.input_hash IS DISTINCT FROM p_provider_input_hash
       OR v_provider.job_claim_token IS DISTINCT FROM p_job_claim_token
       OR v_provider.status NOT IN ('running', 'succeeded', 'failed', 'aborted', 'timed_out')
       OR v_provider.run_id IS NULL
       OR v_provider.run_started_at IS NULL
       OR v_provider.run_started_at < v_parent.preflight_refreshed_at THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_NOT_FRESH', ERRCODE = 'P0001';
    END IF;

    v_operation_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
        'analysis-revenue-fresh-provider-operation/v1|'
        || pg_catalog.octet_length(p_operation_key)::TEXT || ':' || p_operation_key,
        'UTF8'
    ), 'sha256'), 'hex');
    v_expected_run_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
        'analysis-revenue-fresh-provider-run/v1|'
        || pg_catalog.octet_length(p_request_id::TEXT)::TEXT || ':' || p_request_id::TEXT || '|'
        || pg_catalog.octet_length(p_job_key)::TEXT || ':' || p_job_key || '|'
        || pg_catalog.octet_length(p_operation_key)::TEXT || ':' || p_operation_key || '|'
        || pg_catalog.octet_length(v_provider.run_id)::TEXT || ':' || v_provider.run_id,
        'UTF8'
    ), 'sha256'), 'hex');
    IF p_provider_run_hash IS DISTINCT FROM v_expected_run_hash THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_DRIFT', ERRCODE = 'P0001';
    END IF;

    SELECT * INTO v_existing
    FROM public.analysis_revenue_fresh_provider_evidence AS evidence
    WHERE evidence.request_id = p_request_id
      AND evidence.job_key = p_job_key
      AND evidence.operation_key_hash = v_operation_hash
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.job_input_hash IS DISTINCT FROM p_job_input_hash
           OR v_existing.provider IS DISTINCT FROM 'apify'
           OR v_existing.provider_input_hash IS DISTINCT FROM p_provider_input_hash
           OR v_existing.provider_run_hash IS DISTINCT FROM v_expected_run_hash
           OR v_existing.provider_run_started_at IS DISTINCT FROM v_provider.run_started_at
           OR NOT v_existing.no_reuse OR NOT v_existing.no_adoption OR NOT v_existing.no_cache THEN
            RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_DRIFT', ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'recorded', 'created', FALSE, 'replayed', TRUE
        );
    END IF;

    INSERT INTO public.analysis_revenue_fresh_provider_evidence (
        request_id, job_key, job_input_hash, operation_key_hash, provider,
        provider_input_hash, provider_run_hash, provider_run_started_at,
        no_reuse, no_adoption, no_cache
    ) VALUES (
        p_request_id, p_job_key, p_job_input_hash, v_operation_hash, 'apify',
        p_provider_input_hash, v_expected_run_hash, v_provider.run_started_at,
        TRUE, TRUE, TRUE
    );
    RETURN pg_catalog.jsonb_build_object(
        'disposition', 'recorded', 'created', TRUE, 'replayed', FALSE
    );
END;
$_$;


--
-- Name: record_analysis_v2_preflight_admission_failure(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_analysis_v2_preflight_admission_failure(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid) RETURNS TABLE(admission_status text, failure_count integer, admission_error_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_failure_count INTEGER;
    v_status TEXT;
    v_error_code TEXT;
BEGIN
    IF p_preflight_id IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_claim_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_FRESH_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.admission_generation = p_admission_generation
      AND preflight.admission_status = 'processing'
      AND preflight.admission_claim_token = p_claim_token
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    v_failure_count := LEAST(v_preflight.admission_failure_count + 1, 3);
    v_status := CASE WHEN v_failure_count >= 3 THEN 'blocked' ELSE 'pending' END;
    v_error_code := CASE WHEN v_status = 'blocked'
        THEN 'ANALYSIS_V2_FRESH_PROFILE_UNAVAILABLE' ELSE NULL END;

    UPDATE public.analysis_preflights AS preflight
    SET admission_status = v_status,
        admission_refreshed_at = CASE WHEN v_status = 'blocked' THEN v_now ELSE NULL END,
        admission_claim_token = NULL,
        admission_lease_expires_at = NULL,
        admission_error_code = v_error_code,
        admission_failure_count = v_failure_count,
        admission_last_error_code = 'ANALYSIS_V2_FRESH_PROFILE_UNAVAILABLE',
        updated_at = v_now
    WHERE preflight.id = v_preflight.id;

    RETURN QUERY SELECT v_status, v_failure_count, v_error_code;
END;
$$;


--
-- Name: record_external_paid_ever(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_external_paid_ever(p_order_id uuid, p_event_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_state TEXT;
    v_account_id UUID;
    v_evidence RECORD;
    v_existing public.account_paid_evidence%ROWTYPE;
    v_counts_as_external BOOLEAN;
BEGIN
    SELECT paid_order.user_id
    INTO v_account_id
    FROM public.earlybird_orders AS paid_order
    WHERE paid_order.id = p_order_id;

    IF FOUND THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(v_account_id::TEXT, 0)
        );
    END IF;

    SELECT rollout.paid_ever_state
    INTO v_state
    FROM public.account_ledger_rollout_state AS rollout
    WHERE rollout.singleton IS TRUE
    FOR SHARE;
    IF v_state IS DISTINCT FROM 'active' THEN
        RETURN FALSE;
    END IF;

    SELECT paid_order.id AS order_id,
        webhook_event.event_id,
        paid_order.user_id AS account_id,
        paid_order.payment_id,
        paid_order.paid_at,
        paid_order.actual_amount_krw AS amount_krw,
        paid_order.status AS order_status,
        account.traffic_class,
        account.classification_version
    INTO v_evidence
    FROM public.earlybird_orders AS paid_order
    JOIN public.earlybird_webhook_events AS webhook_event
      ON webhook_event.order_id = paid_order.id
    JOIN public.users AS account
      ON account.id = paid_order.user_id
    WHERE paid_order.id = p_order_id
      AND webhook_event.event_id = p_event_id
      AND webhook_event.event_type = 'payment.completed'
      AND webhook_event.disposition = 'accepted'
      AND webhook_event.payment_id = paid_order.payment_id
      AND webhook_event.product_id = paid_order.actual_groble_product_id
      AND webhook_event.amount_krw = paid_order.actual_amount_krw
      AND paid_order.payment_id IS NOT NULL
      AND paid_order.paid_at IS NOT NULL
      AND paid_order.actual_amount_krw >= 0
    FOR SHARE OF paid_order, account;

    IF NOT FOUND OR v_evidence.classification_version IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_PAID_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- Zero-amount coupon completions are valid for fulfillment, but must not
    -- create positive-amount account_paid_evidence or paid-ever flags.
    IF v_evidence.amount_krw = 0 THEN
        RETURN FALSE;
    END IF;

    IF v_evidence.order_status NOT IN (
        'paid',
        'analysis_in_progress',
        'completed',
        'overflow_refund_required',
        'refund_pending',
        'refunded'
    ) THEN
        RETURN FALSE;
    END IF;

    v_counts_as_external := v_evidence.traffic_class = 'external';

    INSERT INTO public.account_paid_evidence (
        order_id, event_id, account_id, payment_id, paid_at, amount_krw,
        counts_as_external
    ) VALUES (
        v_evidence.order_id,
        v_evidence.event_id,
        v_evidence.account_id,
        v_evidence.payment_id,
        v_evidence.paid_at,
        v_evidence.amount_krw,
        v_counts_as_external
    )
    ON CONFLICT (order_id) DO NOTHING;

    SELECT evidence.*
    INTO v_existing
    FROM public.account_paid_evidence AS evidence
    WHERE evidence.order_id = v_evidence.order_id;

    IF v_existing.event_id IS DISTINCT FROM v_evidence.event_id
       OR v_existing.account_id IS DISTINCT FROM v_evidence.account_id
       OR v_existing.payment_id IS DISTINCT FROM v_evidence.payment_id
       OR v_existing.paid_at IS DISTINCT FROM v_evidence.paid_at
       OR v_existing.amount_krw IS DISTINCT FROM v_evidence.amount_krw
       OR v_existing.counts_as_external
            IS DISTINCT FROM v_counts_as_external THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_PAID_EVIDENCE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF v_counts_as_external THEN
        UPDATE public.users AS account
        SET is_paid_user = TRUE,
            first_paid_at = CASE
                WHEN account.first_paid_at IS NULL
                    THEN v_evidence.paid_at
                ELSE LEAST(
                    account.first_paid_at, v_evidence.paid_at
                )
            END
        WHERE account.id = v_evidence.account_id;
    END IF;

    RETURN v_counts_as_external;
END;
$$;


--
-- Name: record_payment_event_v1(text, text, text, text, uuid, text, text, text, jsonb, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_payment_event_v1(p_event_id text, p_idempotency_key text, p_event_type text, p_payment_id text, p_order_id uuid, p_provider text, p_disposition text, p_payload_hash text, p_payload jsonb, p_occurred_at timestamp with time zone, p_amount_krw integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_existing public.payment_events%ROWTYPE;
BEGIN
    IF p_event_id IS NULL OR pg_catalog.length(pg_catalog.btrim(p_event_id)) = 0
       OR p_idempotency_key IS NULL OR pg_catalog.length(pg_catalog.btrim(p_idempotency_key)) = 0
       OR p_payment_id IS NULL OR pg_catalog.length(pg_catalog.btrim(p_payment_id)) = 0
       OR p_event_type NOT IN ('payment.completed', 'payment.cancel_requested', 'payment.refunded')
       OR p_provider NOT IN ('groble')
       OR p_disposition NOT IN ('accepted', 'duplicate', 'no_sale', 'rejected', 'payment_pending')
       OR p_payload_hash IS NULL OR p_payload_hash !~ '^[a-f0-9]{64}$'
       OR p_payload IS NULL OR pg_catalog.jsonb_typeof(p_payload) <> 'object'
       OR p_occurred_at IS NULL
       OR (p_amount_krw IS NOT NULL AND p_amount_krw < 0) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PAYMENT_EVENT_INPUT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT payment_event.*
    INTO v_existing
    FROM public.payment_events AS payment_event
    WHERE payment_event.event_id = p_event_id
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.idempotency_key IS DISTINCT FROM p_idempotency_key THEN
            RAISE EXCEPTION USING MESSAGE = 'PAYMENT_EVENT_IDEMPOTENCY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        IF v_existing.event_type IS DISTINCT FROM p_event_type
           OR v_existing.payment_id IS DISTINCT FROM p_payment_id
           OR v_existing.order_id IS DISTINCT FROM p_order_id
           OR v_existing.provider IS DISTINCT FROM p_provider
           OR v_existing.disposition IS DISTINCT FROM p_disposition
           OR v_existing.payload_hash IS DISTINCT FROM p_payload_hash
           OR v_existing.payload IS DISTINCT FROM p_payload
           OR v_existing.occurred_at IS DISTINCT FROM p_occurred_at
           OR v_existing.amount_krw IS DISTINCT FROM p_amount_krw THEN
            RAISE EXCEPTION USING MESSAGE = 'PAYMENT_EVENT_IDEMPOTENCY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object('status', 'recorded', 'duplicate', TRUE);
    END IF;

    SELECT payment_event.*
    INTO v_existing
    FROM public.payment_events AS payment_event
    WHERE payment_event.idempotency_key = p_idempotency_key
    FOR UPDATE;
    IF FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PAYMENT_EVENT_IDEMPOTENCY_KEY_CONFLICT', ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.payment_events(
        event_id,
        idempotency_key,
        provider,
        event_type,
        payment_id,
        order_id,
        disposition,
        amount_krw,
        payload_hash,
        payload,
        occurred_at
    ) VALUES (
        p_event_id,
        p_idempotency_key,
        p_provider,
        p_event_type,
        p_payment_id,
        p_order_id,
        p_disposition,
        p_amount_krw,
        p_payload_hash,
        p_payload,
        p_occurred_at
    )
    ON CONFLICT DO NOTHING;

    IF FOUND THEN
        RETURN pg_catalog.jsonb_build_object('status', 'recorded', 'duplicate', FALSE);
    END IF;

    SELECT payment_event.*
    INTO v_existing
    FROM public.payment_events AS payment_event
    WHERE payment_event.event_id = p_event_id
       OR payment_event.idempotency_key = p_idempotency_key
    ORDER BY payment_event.event_id = p_event_id DESC
    LIMIT 1;
    IF FOUND AND v_existing.event_id = p_event_id
       AND v_existing.idempotency_key = p_idempotency_key
       AND v_existing.event_type = p_event_type
       AND v_existing.payment_id = p_payment_id
       AND v_existing.order_id IS NOT DISTINCT FROM p_order_id
       AND v_existing.provider = p_provider
       AND v_existing.disposition = p_disposition
       AND v_existing.payload_hash = p_payload_hash
       AND v_existing.payload = p_payload
       AND v_existing.occurred_at = p_occurred_at
       AND v_existing.amount_krw IS NOT DISTINCT FROM p_amount_krw THEN
        RETURN pg_catalog.jsonb_build_object('status', 'recorded', 'duplicate', TRUE);
    END IF;
    IF FOUND AND v_existing.idempotency_key = p_idempotency_key THEN
        RAISE EXCEPTION USING MESSAGE = 'PAYMENT_EVENT_IDEMPOTENCY_KEY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    RAISE EXCEPTION USING MESSAGE = 'PAYMENT_EVENT_IDEMPOTENCY_CONFLICT', ERRCODE = 'P0001';
END;
$_$;


--
-- Name: recover_analysis_beta_apify_credit_allocations(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_analysis_beta_apify_credit_allocations(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '1s'
    SET statement_timeout TO '5s'
    AS $$
DECLARE v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
DECLARE v_candidate UUID; DECLARE v_result JSONB := '[]'::JSONB;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 1000 THEN
   RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_SETTLEMENT_INVALID', ERRCODE = 'P0001'; END IF;
 FOR v_candidate IN
   SELECT allocation.id FROM public.analysis_beta_pool_allocations AS allocation
   JOIN public.users AS users ON users.id = allocation.user_id
   LEFT JOIN public.analysis_requests AS request ON request.id = allocation.request_id
   LEFT JOIN public.analysis_preflights AS preflight ON preflight.id = allocation.preflight_id
   WHERE (allocation.lifecycle_state = 'active' AND request.status IN ('completed', 'failed'))
      OR (allocation.lifecycle_state = 'preflight_held' AND (preflight.expires_at <= v_now OR preflight.status IN ('blocked','expired')))
   ORDER BY allocation.created_at, allocation.id LIMIT p_limit
   FOR UPDATE OF users SKIP LOCKED
 LOOP v_result := v_result || public.settle_analysis_beta_apify_credit_allocation(v_candidate, 'recovery'); END LOOP;
 RETURN v_result;
END; $$;


--
-- Name: recover_analysis_v2_gender_resolution_cutoffs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_analysis_v2_gender_resolution_cutoffs(p_limit integer DEFAULT 8) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_candidate RECORD;
    v_recovered INTEGER := 0;
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 8 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GEMINI_LEASE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    FOR v_candidate IN
        SELECT
            attempt.request_id,
            attempt.job_key,
            attempt.job_claim_token,
            attempt.operation_key,
            attempt.attempt,
            attempt.reservation_token,
            attempt.model_name,
            attempt.location,
            attempt.thinking_level,
            attempt.media_count,
            attempt.media_resolution,
            attempt.prompt_version,
            attempt.schema_version,
            attempt.max_output_tokens,
            attempt.retry_count,
            attempt.created_at,
            lease.slot,
            lease.lease_claim_token,
            lease.fence
        FROM public.analysis_v2_ai_attempts AS attempt
        INNER JOIN public.analysis_v2_gemini_leases AS lease
          ON lease.request_id = attempt.request_id
         AND lease.job_key = attempt.job_key
         AND lease.operation_key = attempt.operation_key
         AND lease.attempt = attempt.attempt
        WHERE attempt.stage = 'genderResolution'
          AND attempt.status = 'reserved'
          AND lease.stage = 'genderResolution'
          AND lease.state IN ('leased', 'quarantined')
          AND lease.expires_at <= v_now
        ORDER BY attempt.created_at, attempt.request_id, attempt.operation_key
        LIMIT p_limit
    LOOP
        PERFORM public.cutoff_analysis_v2_gender_resolution_attempt(
            v_candidate.request_id,
            v_candidate.job_key,
            v_candidate.job_claim_token,
            v_candidate.operation_key,
            v_candidate.attempt,
            v_candidate.reservation_token,
            pg_catalog.jsonb_build_object(
                'model_name', v_candidate.model_name,
                'location', v_candidate.location,
                'stage', 'genderResolution',
                'thinking_level', v_candidate.thinking_level,
                'media_count', v_candidate.media_count,
                'media_resolution', v_candidate.media_resolution,
                'prompt_version', v_candidate.prompt_version,
                'schema_version', v_candidate.schema_version,
                'max_output_tokens', v_candidate.max_output_tokens,
                'retry_count', v_candidate.retry_count,
                'usage_metadata_status', 'missing',
                'usage_complete', FALSE,
                'prompt_tokens', NULL,
                'completion_tokens', NULL,
                'total_tokens', NULL,
                'thinking_tokens', NULL,
                'latency_ms', LEAST(
                    3600000::NUMERIC,
                    GREATEST(
                        0::NUMERIC,
                        EXTRACT(EPOCH FROM (v_now - v_candidate.created_at))
                            * 1000
                    )
                )::INTEGER,
                'estimated_cost_usd', NULL,
                'finish_reason', NULL
            ),
            v_candidate.slot,
            v_candidate.lease_claim_token,
            v_candidate.fence
        );
        v_recovered := v_recovered + 1;
    END LOOP;
    RETURN v_recovered;
END;
$$;


--
-- Name: recover_analysis_v2_scheduler_operations(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_analysis_v2_scheduler_operations(p_limit integer DEFAULT 8) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_candidate RECORD;
    v_recovered INTEGER := 0;
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 32 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_SCHEDULER_OPERATION_INVALID',
            ERRCODE = 'P0001';
    END IF;

    FOR v_candidate IN
        SELECT
            operation.request_id,
            operation.job_key,
            operation.operation_key,
            attempt.job_claim_token,
            attempt.attempt,
            attempt.reservation_token,
            attempt.model_name,
            attempt.location,
            attempt.stage,
            attempt.thinking_level,
            attempt.media_count,
            attempt.media_resolution,
            attempt.prompt_version,
            attempt.schema_version,
            attempt.max_output_tokens,
            attempt.retry_count,
            attempt.created_at,
            lease.slot,
            lease.lease_claim_token,
            lease.fence
        FROM public.analysis_v2_scheduler_operations AS operation
        INNER JOIN public.analysis_v2_ai_attempts AS attempt
          ON attempt.request_id = operation.request_id
         AND attempt.job_key = operation.job_key
         AND attempt.operation_key = operation.operation_key
        INNER JOIN public.analysis_v2_gemini_leases AS lease
          ON lease.request_id = attempt.request_id
         AND lease.job_key = attempt.job_key
         AND lease.operation_key = attempt.operation_key
         AND lease.attempt = attempt.attempt
        WHERE operation.status = 'claimed'
          AND operation.recovery_deadline_at <= v_now
          AND attempt.stage IN ('genderTriage', 'featureAnalysis', 'privateAccountName')
          AND attempt.status = 'reserved'
          AND lease.state IN ('leased', 'quarantined')
          AND lease.expires_at <= v_now
        ORDER BY operation.recovery_deadline_at, operation.request_id, operation.operation_key
        LIMIT p_limit
    LOOP
        PERFORM public.analysis_v2_terminalize_ai_attempt_internal(
            v_candidate.request_id,
            v_candidate.job_key,
            v_candidate.job_claim_token,
            v_candidate.operation_key,
            v_candidate.attempt,
            v_candidate.reservation_token,
            'cutoff',
            pg_catalog.jsonb_build_object(
                'model_name', v_candidate.model_name,
                'location', v_candidate.location,
                'stage', v_candidate.stage,
                'thinking_level', v_candidate.thinking_level,
                'media_count', v_candidate.media_count,
                'media_resolution', v_candidate.media_resolution,
                'prompt_version', v_candidate.prompt_version,
                'schema_version', v_candidate.schema_version,
                'max_output_tokens', v_candidate.max_output_tokens,
                'retry_count', v_candidate.retry_count,
                'usage_metadata_status', 'missing',
                'usage_complete', FALSE,
                'prompt_tokens', NULL,
                'completion_tokens', NULL,
                'total_tokens', NULL,
                'thinking_tokens', NULL,
                'latency_ms', LEAST(
                    3600000::NUMERIC,
                    GREATEST(
                        0::NUMERIC,
                        EXTRACT(EPOCH FROM (v_now - v_candidate.created_at)) * 1000
                    )
                )::INTEGER,
                'estimated_cost_usd', NULL,
                'finish_reason', NULL
            )
        );
        UPDATE public.analysis_v2_gemini_leases AS lease
        SET state = 'available',
            request_id = NULL,
            job_key = NULL,
            operation_key = NULL,
            stage = NULL,
            attempt = NULL,
            lease_claim_token = NULL,
            acquired_at = NULL,
            expires_at = NULL,
            quarantined_at = NULL,
            updated_at = v_now
        WHERE lease.slot = v_candidate.slot
          AND lease.lease_claim_token = v_candidate.lease_claim_token
          AND lease.fence = v_candidate.fence
          AND lease.expires_at <= v_now;
        v_recovered := v_recovered + 1;
    END LOOP;

    WITH terminal AS (
        SELECT operation.request_id, operation.operation_key
        FROM public.analysis_v2_scheduler_operations AS operation
        WHERE operation.status = 'claimed'
          AND operation.recovery_deadline_at <= v_now
          AND NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
                WHERE checkpoint.request_id = operation.request_id
                  AND checkpoint.job_key = operation.job_key
                  AND checkpoint.operation_key = operation.operation_key
                  AND checkpoint.stage = operation.stage
          )
          AND EXISTS (
                SELECT 1
                FROM public.analysis_v2_ai_attempts AS attempt
                WHERE attempt.request_id = operation.request_id
                  AND attempt.job_key = operation.job_key
                  AND attempt.operation_key = operation.operation_key
                  AND attempt.status <> 'rate_limited'
          )
        ORDER BY operation.recovery_deadline_at, operation.request_id, operation.operation_key
        LIMIT p_limit
        FOR UPDATE
    )
    UPDATE public.analysis_v2_scheduler_operations AS operation
    SET status = 'terminal_unavailable',
        updated_at = v_now
    FROM terminal
    WHERE operation.request_id = terminal.request_id
      AND operation.operation_key = terminal.operation_key;
    GET DIAGNOSTICS v_recovered = ROW_COUNT;
    RETURN v_recovered;
END;
$$;


--
-- Name: recover_earlybird_concierge_snapshot_conflict(uuid, uuid, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_earlybird_concierge_snapshot_conflict(p_order_id uuid, p_expected_preflight_id uuid, p_expected_manual_review_at timestamp with time zone, p_expected_admission_refreshed_at timestamp with time zone, p_server_target_input_hash text) RETURNS TABLE(applied boolean, fulfillment_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_user_id_hint UUID;
    v_payment_id_hint TEXT;
    v_incident_count INTEGER;
    v_provider_lineage_count INTEGER;
    v_provider_lineage_input_hash_count INTEGER;
    v_provider_lineage_exact_count INTEGER;
    v_updated INTEGER;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_provider_run public.analysis_preflight_provider_runs%ROWTYPE;
    v_existing RECORD;
BEGIN
    IF p_order_id IS NULL
       OR p_expected_preflight_id IS NULL
       OR p_expected_manual_review_at IS NULL
       OR p_expected_admission_refreshed_at IS NULL
       OR p_server_target_input_hash IS NULL
       OR p_server_target_input_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- Prove this is the only Basic order paid in the incident minute before
    -- resolving its opaque identity. No target or buyer identity is returned.
    SELECT pg_catalog.count(*)::INTEGER INTO v_incident_count
    FROM public.earlybird_orders AS incident_order
    WHERE incident_order.plan_id = 'basic'
      AND incident_order.paid_at >= TIMESTAMPTZ '2026-08-12 18:07:00+09'
      AND incident_order.paid_at < TIMESTAMPTZ '2026-08-12 18:08:00+09';
    IF v_incident_count <> 1 OR NOT EXISTS (
        SELECT 1
        FROM public.earlybird_orders AS incident_order
        WHERE incident_order.id = p_order_id
          AND incident_order.plan_id = 'basic'
          AND incident_order.paid_at >= TIMESTAMPTZ '2026-08-12 18:07:00+09'
          AND incident_order.paid_at < TIMESTAMPTZ '2026-08-12 18:08:00+09'
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.user_id, earlybird_order.payment_id
    INTO v_user_id_hint, v_payment_id_hint
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    IF v_payment_id_hint IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(v_payment_id_hint, 0)
    );

    -- Take the fulfillment before the order, matching request creation; the
    -- user key-share prevents deletion without introducing the inverse lock.
    PERFORM 1
    FROM public.users AS recovery_user
    WHERE recovery_user.id = v_user_id_hint
    FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_order.user_id IS DISTINCT FROM v_user_id_hint
       OR v_order.payment_id IS DISTINCT FROM v_payment_id_hint
       OR v_order.preflight_id IS DISTINCT FROM p_expected_preflight_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.id IS DISTINCT FROM p_expected_preflight_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.* INTO v_provider_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = v_preflight.id
      AND provider_run.operation_key = 'target-profile-fresh-admission:g3'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_WITNESS_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_preflight_provider_runs AS provider_lineage
    WHERE provider_lineage.preflight_id = v_preflight.id
      AND provider_lineage.operation_key IN (
          'target-profile-fresh-admission:g1',
          'target-profile-fresh-admission:g2',
          'target-profile-fresh-admission:g3'
      )
    ORDER BY provider_lineage.operation_key
    FOR UPDATE;

    SELECT
        pg_catalog.count(*)::INTEGER,
        pg_catalog.count(DISTINCT provider_lineage.input_hash)::INTEGER,
        pg_catalog.count(*) FILTER (WHERE
            provider_lineage.status = 'succeeded'
            AND provider_lineage.logical_provider = 'apify'
            AND provider_lineage.actor_id = 'apify/instagram-profile-scraper'
            AND provider_lineage.credential_slot = 'tertiary'
            AND provider_lineage.run_id IS NOT NULL
            AND provider_lineage.terminalized_at IS NOT NULL
            AND provider_lineage.actual_usage_usd IS NOT NULL
            AND provider_lineage.usage_reconciled_at IS NOT NULL
            AND provider_lineage.reusable_profile_schema_version = 1
        )::INTEGER
    INTO v_provider_lineage_count,
        v_provider_lineage_input_hash_count,
        v_provider_lineage_exact_count
    FROM public.analysis_preflight_provider_runs AS provider_lineage
    WHERE provider_lineage.preflight_id = v_preflight.id
      AND provider_lineage.operation_key IN (
          'target-profile-fresh-admission:g1',
          'target-profile-fresh-admission:g2',
          'target-profile-fresh-admission:g3'
      );

    SELECT recovery.* INTO v_existing
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, preflight_id UUID, provider_operation_key TEXT, provider_input_hash VARCHAR(64), provider_run_id_hash VARCHAR(32), expected_manual_review_at TIMESTAMPTZ, expected_admission_refreshed_at TIMESTAMPTZ, old_order_followers_count INTEGER, old_order_following_count INTEGER, old_preflight_followers_count INTEGER, old_preflight_following_count INTEGER, new_witness_followers_count INTEGER, new_witness_following_count INTEGER, old_snapshot_recorded_at TIMESTAMPTZ, new_witness_recorded_at TIMESTAMPTZ, recovery_reason TEXT, followers_absolute_delta INTEGER, following_absolute_delta INTEGER, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_concierge_snapshot_conflict_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','preflight_id','provider_operation_key','provider_input_hash','provider_run_id_hash','expected_manual_review_at','expected_admission_refreshed_at','old_order_followers_count','old_order_following_count','old_preflight_followers_count','old_preflight_following_count','new_witness_followers_count','new_witness_following_count','old_snapshot_recorded_at','new_witness_recorded_at','recovery_reason','followers_absolute_delta','following_absolute_delta','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.preflight_id IS NOT NULL AND decoded.provider_operation_key IS NOT NULL AND decoded.provider_input_hash IS NOT NULL AND decoded.provider_run_id_hash IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.expected_admission_refreshed_at IS NOT NULL AND decoded.old_order_followers_count IS NOT NULL AND decoded.old_order_following_count IS NOT NULL AND decoded.old_preflight_followers_count IS NOT NULL AND decoded.old_preflight_following_count IS NOT NULL AND decoded.new_witness_followers_count IS NOT NULL AND decoded.new_witness_following_count IS NOT NULL AND decoded.old_snapshot_recorded_at IS NOT NULL AND decoded.new_witness_recorded_at IS NOT NULL AND decoded.recovery_reason IS NOT NULL AND decoded.followers_absolute_delta IS NOT NULL AND decoded.following_absolute_delta IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
    WHERE recovery.order_id = v_order.id
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.preflight_id IS DISTINCT FROM p_expected_preflight_id
           OR v_existing.expected_manual_review_at
                IS DISTINCT FROM p_expected_manual_review_at
           OR v_existing.expected_admission_refreshed_at
                IS DISTINCT FROM p_expected_admission_refreshed_at
           OR v_order.preflight_id IS DISTINCT FROM v_existing.preflight_id
           OR v_order.target_followers_count <> 158
           OR v_order.target_following_count <> 361
           OR v_preflight.target_followers_count <> 158
           OR v_preflight.target_following_count <> 361
           OR v_preflight.admission_target_followers_count <> 158
           OR v_preflight.admission_target_following_count <> 362
           OR v_existing.old_snapshot_recorded_at
                IS DISTINCT FROM v_order.created_at
           OR v_existing.new_witness_recorded_at
                IS DISTINCT FROM p_expected_admission_refreshed_at
           OR v_existing.recovery_reason
                IS DISTINCT FROM 'bounded_time_snapshot_drift'
           OR v_provider_run.input_hash IS DISTINCT FROM v_existing.provider_input_hash
           OR v_provider_run.input_hash IS DISTINCT FROM p_server_target_input_hash
           OR v_provider_lineage_count <> 3
           OR v_provider_lineage_input_hash_count <> 1
           OR v_provider_lineage_exact_count <> 3
           OR v_provider_run.logical_provider IS DISTINCT FROM 'apify'
           OR v_provider_run.actor_id
                IS DISTINCT FROM 'apify/instagram-profile-scraper'
           OR v_provider_run.credential_slot IS DISTINCT FROM 'tertiary'
           OR v_provider_run.status IS DISTINCT FROM 'succeeded'
           OR v_provider_run.run_id IS NULL
           OR v_provider_run.terminalized_at IS NULL
           OR v_provider_run.actual_usage_usd IS NULL
           OR v_provider_run.usage_reconciled_at IS NULL
           OR v_provider_run.reusable_profile_schema_version IS DISTINCT FROM 1
           OR v_preflight.admission_generation <> 3
           OR v_preflight.admission_refreshed_at
                IS DISTINCT FROM p_expected_admission_refreshed_at
           OR pg_catalog.md5(v_provider_run.run_id)
                IS DISTINCT FROM v_existing.provider_run_id_hash
           OR v_order.status NOT IN (
                'paid', 'analysis_in_progress', 'completed'
           )
           OR EXISTS (
                SELECT 1
                FROM public.earlybird_webhook_events AS refund_event
                WHERE refund_event.payment_id = v_order.payment_id
                  AND refund_event.event_type = 'payment.refunded'
           )
           OR v_fulfillment.status NOT IN (
                'retryable_failure', 'admission_pending',
                'analysis_in_progress', 'completed'
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_REPLAY_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN QUERY SELECT FALSE, v_fulfillment.status;
        RETURN;
    END IF;

    IF v_fulfillment.manual_review_at
            IS DISTINCT FROM p_expected_manual_review_at
       OR v_preflight.admission_refreshed_at
            IS DISTINCT FROM p_expected_admission_refreshed_at THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_CAS_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    IF NOT (
        v_order.status = 'paid'
        AND v_order.plan_id = 'basic'
        AND v_order.pricing_version = 'earlybird-2026-08-v3'
        AND v_order.seller_reference_confirmed_at IS NOT NULL
        AND v_order.payment_id IS NOT NULL
        AND v_order.actual_amount_krw = 990
        AND v_order.expected_amount_krw = 990
        AND v_order.actual_groble_product_id
            IS NOT DISTINCT FROM v_order.expected_groble_product_id
        AND v_order.result_request_id IS NULL
        AND v_order.target_followers_count = 158
        AND v_order.target_following_count = 361
        AND v_order.concierge_apify_credential_slot = 'tertiary'
        AND v_fulfillment.status = 'manual_review'
        AND v_fulfillment.last_error_code = 'SNAPSHOT_CONFLICT'
        AND v_fulfillment.request_id IS NULL
        AND v_fulfillment.lease_token IS NULL
        AND v_fulfillment.lease_expires_at IS NULL
        AND v_fulfillment.operator_admitted_at IS NOT NULL
        AND v_fulfillment.attempt_count = 1
        AND v_preflight.user_id IS NOT DISTINCT FROM v_order.user_id
        AND v_preflight.id IS NOT DISTINCT FROM p_expected_preflight_id
        AND v_preflight.target_instagram_id
            IS NOT DISTINCT FROM v_order.target_instagram_id
        AND pg_catalog.lower(pg_catalog.btrim(v_preflight.target_instagram_id))
            IS NOT DISTINCT FROM
                pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id))
        AND v_preflight.exclusion_decision
            IS NOT DISTINCT FROM v_order.exclusion_decision
        AND v_preflight.excluded_instagram_id
            IS NOT DISTINCT FROM v_order.excluded_instagram_id
        AND v_preflight.status = 'ready'
        AND v_preflight.access_mode = 'production'
        AND v_preflight.consumed_request_id IS NULL
        AND v_preflight.target_followers_count = 158
        AND v_preflight.target_following_count = 361
        AND v_preflight.target_is_private IS NOT DISTINCT FROM FALSE
        AND v_preflight.admission_status = 'ready'
        AND v_preflight.admission_generation = 3
        AND v_preflight.admission_selected_plan_id = 'basic'
        AND v_preflight.admission_target_followers_count = 158
        AND v_preflight.admission_target_following_count = 362
        AND v_preflight.admission_capacity_required_plan_id = 'basic'
        AND v_preflight.admission_required_plan_id = 'basic'
        AND v_preflight.admission_plan_cards_snapshot
            IS NOT DISTINCT FROM v_preflight.plan_cards_snapshot
        AND v_preflight.order_scoped_apify_credential_slot = 'tertiary'
        AND public.earlybird_snapshot_count_drift_within_tolerance(
            v_preflight.target_followers_count,
            v_preflight.admission_target_followers_count
        )
        AND public.earlybird_snapshot_count_drift_within_tolerance(
            v_preflight.target_following_count,
            v_preflight.admission_target_following_count
        )
        AND public.analysis_v2_valid_launch_snapshot(
            v_preflight.launch_status_snapshot
        )
        AND public.analysis_v2_valid_plan_catalog_snapshot(
            v_preflight.plan_catalog_snapshot
        )
        AND public.analysis_v2_valid_plan_cards_snapshot(
            v_preflight.plan_cards_snapshot
        )
        AND public.analysis_v2_valid_pricing_snapshot(
            v_preflight.pricing_snapshot
        )
        AND public.analysis_v2_valid_policy_versions_snapshot(
            v_preflight.policy_versions_snapshot
        )
        AND v_preflight.plan_cards_snapshot
            -> 'basic' ->> 'launchStatus' = 'production'
        AND v_preflight.plan_cards_snapshot
            -> 'basic' ->> 'selectionState' IN ('required', 'available_upgrade')
        AND COALESCE(
            v_preflight.plan_cards_snapshot
                -> 'basic' -> 'relationshipCapacity' ->> 'followers', ''
        ) ~ '^[0-9]+$'
        AND COALESCE(
            v_preflight.plan_cards_snapshot
                -> 'basic' -> 'relationshipCapacity' ->> 'following', ''
        ) ~ '^[0-9]+$'
        AND 158 <= (
            v_preflight.plan_cards_snapshot
                -> 'basic' -> 'relationshipCapacity' ->> 'followers'
        )::INTEGER
        AND 362 <= (
            v_preflight.plan_cards_snapshot
                -> 'basic' -> 'relationshipCapacity' ->> 'following'
        )::INTEGER
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_INELIGIBLE',
            ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.earlybird_webhook_events AS refund_event
        WHERE refund_event.payment_id = v_order.payment_id
          AND refund_event.event_type = 'payment.refunded'
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_REFUNDED',
            ERRCODE = 'P0001';
    END IF;

    IF NOT (
        v_provider_lineage_count = 3
        AND v_provider_lineage_input_hash_count = 1
        AND v_provider_lineage_exact_count = 3
        AND v_provider_run.input_hash = p_server_target_input_hash
        AND
        v_provider_run.operation_key = 'target-profile-fresh-admission:g3'
        AND v_provider_run.input_hash ~ '^[a-f0-9]{64}$'
        AND v_provider_run.logical_provider = 'apify'
        AND v_provider_run.actor_id = 'apify/instagram-profile-scraper'
        AND v_provider_run.credential_slot = 'tertiary'
        AND v_provider_run.status = 'succeeded'
        AND v_provider_run.run_id IS NOT NULL
        AND v_provider_run.reserved_at >= v_preflight.admission_requested_at
        AND v_provider_run.run_started_at >= v_preflight.admission_requested_at
        AND v_provider_run.terminalized_at IS NOT NULL
        AND v_provider_run.terminalized_at
            <= v_preflight.admission_refreshed_at
        AND v_provider_run.actual_usage_usd IS NOT NULL
        AND v_provider_run.usage_reconciled_at IS NOT NULL
        AND v_provider_run.reusable_profile_schema_version = 1
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_WITNESS_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.analysis_requests AS prior_request
        WHERE prior_request.preflight_id = v_preflight.id
    ) OR EXISTS (
        SELECT 1
        FROM public.analysis_requests AS active_request
        WHERE active_request.user_id = v_order.user_id
          AND active_request.status IN ('pending', 'processing')
    ) OR EXISTS (
        SELECT 1
        FROM public.analysis_preflights AS active_preflight
        WHERE active_preflight.user_id = v_order.user_id
          AND active_preflight.id <> v_preflight.id
          AND active_preflight.status IN ('pending', 'processing', 'ready')
    ) OR EXISTS (
        SELECT 1
        FROM public.earlybird_orders AS other_order
        WHERE other_order.user_id = v_order.user_id
          AND other_order.id <> v_order.id
          AND other_order.status IN ('paid', 'analysis_in_progress')
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_UNRELATED_WORK',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.earlybird_fulfillments AS fulfillment
    SET status = 'retryable_failure',
        lease_token = NULL,
        lease_expires_at = NULL,
        next_attempt_at = v_now,
        last_error_code = 'CONCIERGE_SNAPSHOT_CONFLICT_RECOVERY',
        last_error_at = v_now,
        manual_review_at = NULL,
        updated_at = v_now
    WHERE fulfillment.order_id = v_order.id
      AND fulfillment.status = 'manual_review'
      AND fulfillment.last_error_code = 'SNAPSHOT_CONFLICT'
      AND fulfillment.request_id IS NULL
      AND fulfillment.manual_review_at
            IS NOT DISTINCT FROM p_expected_manual_review_at;
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    IF v_updated <> 1 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'CONCIERGE_SNAPSHOT_RECOVERY_CAS_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    PERFORM public.archive_earlybird_concierge_snapshot_conflict_recovery(
        v_order.id, v_preflight.id, v_provider_run.operation_key,
        v_provider_run.input_hash, pg_catalog.md5(v_provider_run.run_id),
        p_expected_manual_review_at, p_expected_admission_refreshed_at,
        158, 361, 158, 361, 158, 362, v_order.created_at,
        p_expected_admission_refreshed_at,
        'bounded_time_snapshot_drift', 0, 1
    );

    RETURN QUERY SELECT TRUE, 'retryable_failure'::TEXT;
END;
$_$;


--
-- Name: recover_earlybird_fresh_admission_provider_failure(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_earlybird_fresh_admission_provider_failure(p_order_id uuid) RETURNS TABLE(order_id uuid, fulfillment_status text, preflight_id uuid, user_id uuid, plan_id text, request_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_user_id_hint UUID;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_rebound_preflight public.analysis_preflights%ROWTYPE;
    v_rebound_preflight_id UUID;
    v_payment_valid BOOLEAN;
BEGIN
    IF p_order_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FRESH_ADMISSION_PROVIDER_RECOVERY_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- Match the established user -> order -> fulfillment -> preflight lock
    -- order used by paid-preflight rebinding and checkout creation.
    SELECT earlybird_order.user_id INTO v_user_id_hint
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FRESH_ADMISSION_PROVIDER_RECOVERY_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.users AS recovery_user
    WHERE recovery_user.id = v_user_id_hint
    FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FRESH_ADMISSION_PROVIDER_RECOVERY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    IF NOT FOUND OR v_order.user_id IS DISTINCT FROM v_user_id_hint THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FRESH_ADMISSION_PROVIDER_RECOVERY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FRESH_ADMISSION_PROVIDER_RECOVERY_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FRESH_ADMISSION_PROVIDER_RECOVERY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    v_payment_valid := v_order.status = 'paid'
        AND v_order.seller_reference_confirmed_at IS NOT NULL
        AND v_order.payment_id IS NOT NULL
        AND v_order.actual_amount_krw IS NOT NULL
        AND v_order.actual_amount_krw BETWEEN 0 AND v_order.expected_amount_krw
        AND v_order.actual_groble_product_id IS NOT DISTINCT FROM v_order.expected_groble_product_id;
    IF NOT v_payment_valid THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FRESH_ADMISSION_PROVIDER_RECOVERY_PAYMENT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- A response lost after commit is safe to replay. Once the replacement is
    -- already advancing, return its opaque identity without mutating it again.
    IF v_fulfillment.status IN ('analysis_in_progress', 'completed') THEN
        RETURN QUERY SELECT
            v_order.id, v_fulfillment.status, v_order.preflight_id,
            v_order.user_id, v_order.plan_id, v_fulfillment.request_id;
        RETURN;
    END IF;
    IF v_fulfillment.status = 'retryable_failure'
       AND v_fulfillment.last_error_code = 'FRESH_ADMISSION_PROVIDER_RECOVERY'
       AND v_fulfillment.request_id IS NULL
       AND v_preflight.admission_status = 'idle' THEN
        RETURN QUERY SELECT
            v_order.id, v_fulfillment.status, v_order.preflight_id,
            v_order.user_id, v_order.plan_id, NULL::UUID;
        RETURN;
    END IF;

    IF NOT (
        v_fulfillment.status = 'manual_review'
        AND v_fulfillment.last_error_code = 'TARGET_UNAVAILABLE'
        AND v_fulfillment.request_id IS NULL
        AND v_fulfillment.manual_review_at IS NOT NULL
        AND v_preflight.user_id IS NOT DISTINCT FROM v_order.user_id
        AND v_preflight.access_mode = 'production'
        AND v_preflight.consumed_request_id IS NULL
        AND v_preflight.status IN ('ready', 'expired')
        AND v_preflight.expires_at <= v_now
        AND v_preflight.admission_status = 'blocked'
        AND v_preflight.admission_error_code = 'ANALYSIS_V2_FRESH_PROFILE_UNAVAILABLE'
        AND v_preflight.admission_last_error_code = 'ANALYSIS_V2_FRESH_PROFILE_UNAVAILABLE'
        AND v_preflight.admission_failure_count = 3
        AND v_preflight.admission_selected_plan_id IS NOT DISTINCT FROM v_order.plan_id
        AND v_preflight.admission_refreshed_at IS NOT NULL
        AND v_order.plan_id IN ('basic', 'standard')
        AND public.analysis_v2_valid_launch_snapshot(v_preflight.launch_status_snapshot)
        AND public.analysis_v2_valid_plan_catalog_snapshot(v_preflight.plan_catalog_snapshot)
        AND public.analysis_v2_valid_pricing_snapshot(v_preflight.pricing_snapshot)
        AND public.analysis_v2_valid_policy_versions_snapshot(v_preflight.policy_versions_snapshot)
        AND v_preflight.plan_catalog_snapshot->v_order.plan_id->>'launchStatus' = 'production'
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FRESH_ADMISSION_PROVIDER_RECOVERY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.earlybird_fulfillments AS fulfillment
    SET status = 'retryable_failure',
        lease_token = NULL,
        lease_expires_at = NULL,
        next_attempt_at = v_now,
        last_error_code = 'FRESH_ADMISSION_PROVIDER_RECOVERY',
        last_error_at = v_now,
        manual_review_at = NULL,
        updated_at = v_now
    WHERE fulfillment.order_id = p_order_id
      AND fulfillment.status = 'manual_review'
      AND fulfillment.last_error_code = 'TARGET_UNAVAILABLE'
      AND fulfillment.request_id IS NULL
    RETURNING fulfillment.* INTO v_fulfillment;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FRESH_ADMISSION_PROVIDER_RECOVERY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    v_rebound_preflight_id := public.rebind_expired_paid_earlybird_preflight(p_order_id);
    IF v_rebound_preflight_id IS NULL
       OR v_rebound_preflight_id IS NOT DISTINCT FROM v_preflight.id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FRESH_ADMISSION_PROVIDER_RECOVERY_REBIND_FAILED',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.* INTO v_rebound_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_rebound_preflight_id;
    IF NOT FOUND
       OR v_rebound_preflight.user_id IS DISTINCT FROM v_order.user_id
       OR v_rebound_preflight.access_mode <> 'production'
       OR v_rebound_preflight.status <> 'ready'
       OR v_rebound_preflight.admission_status <> 'idle'
       OR v_rebound_preflight.consumed_request_id IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_FRESH_ADMISSION_PROVIDER_RECOVERY_REBIND_FAILED',
            ERRCODE = 'P0001';
    END IF;

    RETURN QUERY SELECT
        v_order.id,
        v_fulfillment.status,
        v_rebound_preflight_id,
        v_order.user_id,
        v_order.plan_id,
        NULL::UUID;
END;
$$;


--
-- Name: recover_earlybird_freshness_snapshot_conflict(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_earlybird_freshness_snapshot_conflict(p_order_id uuid, p_expected_manual_review_at timestamp with time zone) RETURNS TABLE(order_id uuid, fulfillment_status text, preflight_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := public.earlybird_fulfillment_clock();
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_selected_card JSONB;
BEGIN
    IF p_order_id IS NULL OR p_expected_manual_review_at IS NULL THEN RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FRESHNESS_RECOVERY_INVALID', ERRCODE = 'P0001'; END IF;
    SELECT earlybird_order.* INTO v_order FROM public.earlybird_orders AS earlybird_order WHERE earlybird_order.id = p_order_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FRESHNESS_RECOVERY_NOT_FOUND', ERRCODE = 'P0001'; END IF;
    SELECT fulfillment.* INTO v_fulfillment FROM public.earlybird_fulfillments AS fulfillment WHERE fulfillment.order_id = p_order_id FOR UPDATE;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight WHERE preflight.id = v_order.preflight_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FRESHNESS_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001'; END IF;
    IF v_fulfillment.status <> 'manual_review' OR v_fulfillment.last_error_code <> 'SNAPSHOT_CONFLICT'
       OR v_fulfillment.lease_token IS NOT NULL OR v_fulfillment.lease_expires_at IS NOT NULL
       OR v_fulfillment.request_id IS NOT NULL OR v_order.result_request_id IS NOT NULL OR v_preflight.consumed_request_id IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FRESHNESS_RECOVERY_STATE_INVALID', ERRCODE = 'P0001';
    END IF;
    IF v_fulfillment.manual_review_at IS DISTINCT FROM p_expected_manual_review_at THEN RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FRESHNESS_RECOVERY_CAS_MISMATCH', ERRCODE = 'P0001'; END IF;
    IF v_order.status <> 'paid' OR v_order.seller_reference_confirmed_at IS NULL OR v_order.payment_id IS NULL
       OR v_order.actual_amount_krw IS NULL OR v_order.actual_amount_krw < 0 OR v_order.actual_amount_krw > v_order.expected_amount_krw
       OR v_order.actual_groble_product_id IS DISTINCT FROM v_order.expected_groble_product_id
       OR v_order.target_followers_count IS NULL OR v_order.target_following_count IS NULL
       OR v_preflight.user_id IS DISTINCT FROM v_order.user_id OR v_preflight.status NOT IN ('ready','expired')
       OR v_preflight.access_mode <> 'production' OR v_preflight.target_instagram_id IS DISTINCT FROM v_order.target_instagram_id
       OR v_preflight.exclusion_decision IS DISTINCT FROM v_order.exclusion_decision
       OR v_preflight.excluded_instagram_id IS DISTINCT FROM v_order.excluded_instagram_id OR v_preflight.admission_status <> 'ready'
       OR v_preflight.target_followers_count IS NULL OR v_preflight.target_following_count IS NULL
       OR v_preflight.admission_target_followers_count IS NULL OR v_preflight.admission_target_following_count IS NULL
       OR v_preflight.admission_target_followers_count IS DISTINCT FROM v_preflight.target_followers_count
       OR v_preflight.admission_target_following_count IS DISTINCT FROM v_preflight.target_following_count
       OR v_preflight.admission_capacity_required_plan_id IS DISTINCT FROM v_preflight.capacity_required_plan_id
       OR v_preflight.admission_required_plan_id IS DISTINCT FROM v_preflight.required_plan_id
       OR v_preflight.admission_plan_cards_snapshot IS DISTINCT FROM v_preflight.plan_cards_snapshot
       OR NOT public.analysis_v2_valid_launch_snapshot(v_preflight.launch_status_snapshot)
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(v_preflight.plan_catalog_snapshot)
       OR NOT public.analysis_v2_valid_plan_cards_snapshot(v_preflight.plan_cards_snapshot)
       OR NOT public.analysis_v2_valid_pricing_snapshot(v_preflight.pricing_snapshot)
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(v_preflight.policy_versions_snapshot) THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FRESHNESS_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;
    v_selected_card := v_preflight.plan_cards_snapshot->v_order.plan_id;
    IF v_order.plan_id NOT IN ('basic','standard') OR v_preflight.admission_selected_plan_id IS DISTINCT FROM v_order.plan_id
       OR v_selected_card IS NULL OR v_selected_card->>'launchStatus' <> 'production'
       OR v_selected_card->>'selectionState' NOT IN ('required','available_upgrade')
       OR COALESCE(v_selected_card->'relationshipCapacity'->>'followers','') !~ '^[0-9]+$'
       OR COALESCE(v_selected_card->'relationshipCapacity'->>'following','') !~ '^[0-9]+$'
       OR v_preflight.target_followers_count > (v_selected_card->'relationshipCapacity'->>'followers')::INTEGER
       OR v_preflight.target_following_count > (v_selected_card->'relationshipCapacity'->>'following')::INTEGER
       OR v_order.target_followers_count > (v_selected_card->'relationshipCapacity'->>'followers')::INTEGER
       OR v_order.target_following_count > (v_selected_card->'relationshipCapacity'->>'following')::INTEGER THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FRESHNESS_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.admission_refreshed_at IS NULL OR v_preflight.admission_refreshed_at > v_now + INTERVAL '30 seconds' THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FRESHNESS_RECOVERY_FRESHNESS_INVALID', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.admission_refreshed_at >= v_now - INTERVAL '2 minutes' THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FRESHNESS_RECOVERY_NOT_EXPIRED', ERRCODE = 'P0001';
    END IF;
    IF EXISTS (SELECT 1 FROM public.analysis_requests AS active_request WHERE active_request.user_id = v_order.user_id
       AND active_request.status IN ('pending','processing')) THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_FRESHNESS_RECOVERY_ACTIVE_REQUEST_CONFLICT', ERRCODE = 'P0001';
    END IF;
    UPDATE public.earlybird_fulfillments AS fulfillment SET status = 'retryable_failure', lease_token = NULL,
        lease_expires_at = NULL, next_attempt_at = v_now, last_error_code = 'ADMISSION_FRESHNESS_EXPIRED',
        last_error_at = v_now, manual_review_at = NULL, updated_at = v_now WHERE fulfillment.order_id = p_order_id;
    RETURN QUERY SELECT p_order_id, 'retryable_failure'::TEXT, v_preflight.id;
END;
$_$;


--
-- Name: recover_earlybird_schema_failed_fulfillment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_earlybird_schema_failed_fulfillment(p_order_id uuid) RETURNS TABLE(order_id uuid, fulfillment_status text, preflight_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_failed_request public.analysis_requests%ROWTYPE;
    v_recovery RECORD;
    v_new_preflight_id UUID;
    v_capacity_plan TEXT;
    v_required_plan TEXT;
    v_capacity_rank INTEGER;
    v_required_rank INTEGER;
    v_selected_rank INTEGER;
    v_plan_id TEXT;
    v_plan_rank INTEGER;
    v_card JSONB;
    v_card_followers INTEGER;
    v_card_following INTEGER;
    v_required_card_count INTEGER := 0;
    v_order_target TEXT;
    v_failed_request_target TEXT;
BEGIN
    IF p_order_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    SELECT recovery.* INTO v_recovery
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
    WHERE recovery.order_id = v_order.id
    FOR UPDATE;
    IF FOUND THEN
        BEGIN
            SELECT fulfillment.* INTO v_fulfillment
            FROM public.earlybird_fulfillments AS fulfillment
            WHERE fulfillment.order_id = v_order.id
            FOR UPDATE NOWAIT;
        EXCEPTION
            WHEN lock_not_available THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_BUSY',
                    ERRCODE = 'P0001';
        END;
        IF NOT FOUND
           OR v_order.preflight_id IS DISTINCT FROM v_recovery.recovery_preflight_id THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_CONFLICT', ERRCODE = 'P0001';
        END IF;

        -- A duplicate operator call after the single transition is a read-only
        -- replay. It intentionally does not refresh timestamps or leases.
        IF v_fulfillment.status = 'admission_pending' THEN
            RETURN QUERY SELECT
                v_order.id,
                v_fulfillment.status,
                v_recovery.recovery_preflight_id;
            RETURN;
        END IF;

        SELECT preflight.* INTO v_preflight
        FROM public.analysis_preflights AS preflight
        WHERE preflight.id = v_recovery.recovery_preflight_id
        FOR UPDATE;
        SELECT analysis_request.* INTO v_failed_request
        FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.id = v_recovery.failed_request_id
        FOR UPDATE;

        IF NOT FOUND
           OR v_fulfillment.status <> 'manual_review'
           OR v_fulfillment.request_id IS NOT NULL
           OR v_fulfillment.lease_token IS NOT NULL
           OR v_fulfillment.lease_expires_at IS NOT NULL
           OR v_fulfillment.last_error_code IS DISTINCT FROM
                'PROVIDER_RUN_ADOPTION_REQUIRED'
           OR v_fulfillment.last_error_at IS NULL
           OR v_fulfillment.manual_review_at IS NULL
           OR v_fulfillment.completed_at IS NOT NULL
           OR v_order.status <> 'paid'
           OR v_order.result_request_id IS NOT NULL
           OR v_order.seller_reference_confirmed_at IS NULL
           OR v_order.payment_id IS NULL
           OR v_order.actual_amount_krw IS NULL
           OR v_order.actual_amount_krw < 0
           OR v_order.actual_amount_krw > v_order.expected_amount_krw
           OR v_order.actual_groble_product_id
                IS DISTINCT FROM v_order.expected_groble_product_id
           OR v_order.plan_id NOT IN ('basic', 'standard')
           OR v_preflight.id IS DISTINCT FROM v_order.preflight_id
           OR v_preflight.user_id IS DISTINCT FROM v_order.user_id
           OR v_preflight.access_mode <> 'production'
           OR v_preflight.status <> 'ready'
           OR v_preflight.consumed_request_id IS NOT NULL
           OR v_preflight.idempotency_key IS DISTINCT FROM
                ('earlybird.schema-recovery.'
                 || pg_catalog.replace(v_order.id::TEXT, '-', ''))
           OR v_failed_request.user_id IS DISTINCT FROM v_order.user_id
           OR v_failed_request.pipeline_version <> 'v2'
           OR v_failed_request.status <> 'failed'
           OR (
                pg_catalog.lower(pg_catalog.btrim(v_failed_request.target_instagram_id))
                    IS DISTINCT FROM
                    pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id))
                AND v_failed_request.target_instagram_id IS DISTINCT FROM (
                    'retained.' || pg_catalog.substr(
                        pg_catalog.replace(v_failed_request.id::TEXT, '-', ''), 1, 20
                    )
                )
           )
           OR NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_failure_receipts AS receipt
                WHERE receipt.request_id = v_failed_request.id
                  AND receipt.error_code = v_failed_request.error_message
           )
           OR EXISTS (
                SELECT 1
                FROM public.analysis_requests AS analysis_request
                WHERE analysis_request.user_id = v_order.user_id
                  AND analysis_request.status IN ('pending', 'processing')
           )
           OR EXISTS (
                SELECT 1
                FROM public.analysis_preflights AS preflight
                WHERE preflight.user_id = v_order.user_id
                  AND preflight.status IN ('pending', 'processing', 'ready')
                  AND preflight.id <> v_recovery.recovery_preflight_id
           )
           OR NOT public.earlybird_provider_run_adoption_ready(
                v_order.id,
                v_recovery.failed_request_id,
                v_recovery.recovery_preflight_id
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_ADOPTION_REARM_INELIGIBLE',
                ERRCODE = 'P0001';
        END IF;

        UPDATE public.earlybird_fulfillments AS fulfillment
        SET status = 'admission_pending',
            lease_token = NULL,
            lease_expires_at = NULL,
            next_attempt_at = v_now,
            last_error_code = NULL,
            last_error_at = NULL,
            manual_review_at = NULL,
            completed_at = NULL,
            updated_at = v_now
        WHERE fulfillment.order_id = v_order.id;

        RETURN QUERY SELECT
            v_order.id,
            'admission_pending'::TEXT,
            v_recovery.recovery_preflight_id;
        RETURN;
    END IF;

    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = v_order.id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_order.status <> 'analysis_in_progress'
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_order.payment_id IS NULL
       OR v_order.actual_amount_krw IS NULL
       OR v_order.actual_amount_krw < 0
       OR v_order.actual_amount_krw > v_order.expected_amount_krw
       OR v_order.actual_groble_product_id
            IS DISTINCT FROM v_order.expected_groble_product_id
       OR v_order.plan_id NOT IN ('basic', 'standard')
       OR v_fulfillment.status <> 'manual_review'
       OR v_fulfillment.request_id IS NULL
       OR v_order.result_request_id IS DISTINCT FROM v_fulfillment.request_id
       OR v_preflight.status <> 'consumed'
       OR v_preflight.consumed_request_id IS DISTINCT FROM v_fulfillment.request_id
       OR v_preflight.user_id IS DISTINCT FROM v_order.user_id
       OR v_preflight.access_mode <> 'production'
       OR NOT public.analysis_v2_valid_launch_snapshot(v_preflight.launch_status_snapshot)
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(v_preflight.plan_catalog_snapshot)
       OR NOT public.analysis_v2_valid_plan_cards_snapshot(v_preflight.plan_cards_snapshot)
       OR NOT public.analysis_v2_valid_pricing_snapshot(v_preflight.pricing_snapshot)
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(v_preflight.policy_versions_snapshot)
       OR v_preflight.plan_cards_snapshot->v_order.plan_id->>'launchStatus' IS DISTINCT FROM 'production'
       OR COALESCE(
            v_preflight.plan_cards_snapshot->v_order.plan_id->>'selectionState', ''
       ) NOT IN ('required', 'available_upgrade') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_INELIGIBLE', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.* INTO v_failed_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = v_fulfillment.request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_failed_request.user_id IS DISTINCT FROM v_order.user_id
       OR v_failed_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_failed_request.pipeline_version <> 'v2'
       OR v_failed_request.status <> 'failed'
       OR v_failed_request.error_message NOT IN (
            'ANALYSIS_V2_STAGE_SCHEMA_VALIDATION_ERROR',
            'JOB_ATTEMPTS_EXHAUSTED'
          )
       OR NOT EXISTS (
            SELECT 1
            FROM public.analysis_v2_failure_receipts AS receipt
            WHERE receipt.request_id = v_failed_request.id
              AND receipt.error_code = v_failed_request.error_message
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_INELIGIBLE', ERRCODE = 'P0001';
    END IF;

    v_order_target := pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id));
    v_failed_request_target := pg_catalog.lower(
        pg_catalog.btrim(v_failed_request.target_instagram_id)
    );
    IF v_order_target IS NULL
       OR v_failed_request_target IS NULL
       OR v_order.target_instagram_id IS DISTINCT FROM v_order_target
       OR v_order_target !~ '^[a-z0-9._]{1,30}$'
       OR v_failed_request_target !~ '^@?[a-z0-9._]{1,30}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_INELIGIBLE', ERRCODE = 'P0001';
    END IF;
    v_order_target := pg_catalog.regexp_replace(v_order_target, '^@', '');
    v_failed_request_target := pg_catalog.regexp_replace(
        v_failed_request_target, '^@', ''
    );
    IF v_failed_request_target IS DISTINCT FROM v_order_target
       AND v_failed_request.target_instagram_id IS DISTINCT FROM 'retained.'
            || pg_catalog.substr(
                pg_catalog.replace(v_failed_request.id::TEXT, '-', ''), 1, 20
            ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_INELIGIBLE', ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.user_id = v_order.user_id
          AND analysis_request.status IN ('pending', 'processing')
    ) OR EXISTS (
        SELECT 1
        FROM public.analysis_preflights AS preflight
        WHERE preflight.user_id = v_order.user_id
          AND preflight.status IN ('pending', 'processing', 'ready')
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_ACTIVE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    v_capacity_plan := v_preflight.capacity_required_plan_id;
    v_required_plan := v_preflight.required_plan_id;
    v_capacity_rank := CASE v_capacity_plan
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 WHEN 'plus' THEN 3 ELSE NULL END;
    v_required_rank := CASE v_required_plan
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 WHEN 'plus' THEN 3 ELSE NULL END;
    v_selected_rank := CASE v_order.plan_id
        WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE NULL END;
    IF v_capacity_rank IS NULL
       OR v_required_rank IS NULL
       OR v_selected_rank IS NULL
       OR v_required_rank < v_capacity_rank
       OR v_selected_rank < v_required_rank
       OR v_order.target_followers_count IS NULL
       OR v_order.target_followers_count < 0
       OR v_order.target_following_count IS NULL
       OR v_order.target_following_count < 0
       OR v_preflight.target_followers_count IS NULL
       OR v_preflight.target_followers_count < 0
       OR v_preflight.target_following_count IS NULL
       OR v_preflight.target_following_count < 0 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id
            WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_card := v_preflight.plan_cards_snapshot->v_plan_id;
        IF COALESCE(v_card->'relationshipCapacity'->>'followers', '') !~ '^[0-9]+$'
           OR COALESCE(v_card->'relationshipCapacity'->>'following', '') !~ '^[0-9]+$' THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        v_card_followers := (v_card->'relationshipCapacity'->>'followers')::INTEGER;
        v_card_following := (v_card->'relationshipCapacity'->>'following')::INTEGER;
        IF v_plan_rank < v_capacity_rank
           AND v_order.target_followers_count <= v_card_followers
           AND v_order.target_following_count <= v_card_following THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        IF v_plan_rank >= v_capacity_rank
           AND (
                v_order.target_followers_count > v_card_followers
                OR v_order.target_following_count > v_card_following
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        IF v_plan_id = v_order.plan_id
           AND (
                v_preflight.target_followers_count > v_card_followers
                OR v_preflight.target_following_count > v_card_following
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        IF v_card->>'selectionState' = 'required' THEN
            v_required_card_count := v_required_card_count + 1;
        END IF;
    END LOOP;
    IF v_required_card_count <> 1
       OR v_preflight.plan_cards_snapshot->v_required_plan->>'selectionState'
            IS DISTINCT FROM 'required'
       OR v_preflight.plan_cards_snapshot->v_required_plan->>'launchStatus'
            IS DISTINCT FROM 'production' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_SCHEMA_FAILURE_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    v_new_preflight_id := extensions.gen_random_uuid();
    INSERT INTO public.analysis_preflights(
        id, user_id, idempotency_key, target_instagram_id, status,
        exclusion_decision, excluded_instagram_id, access_mode,
        launch_status_snapshot, plan_catalog_snapshot, plan_cards_snapshot,
        pricing_version, pricing_snapshot, policy_versions_snapshot,
        target_followers_count, target_following_count, target_is_private,
        capacity_required_plan_id, required_plan_id, created_at, updated_at,
        expires_at, ready_at
    ) VALUES (
        v_new_preflight_id, v_order.user_id,
        'earlybird.schema-recovery.' || pg_catalog.replace(v_order.id::TEXT, '-', ''),
        v_order.target_instagram_id, 'ready', v_order.exclusion_decision,
        v_order.excluded_instagram_id, 'production',
        v_preflight.launch_status_snapshot, v_preflight.plan_catalog_snapshot,
        v_preflight.plan_cards_snapshot,
        v_preflight.pricing_version, v_preflight.pricing_snapshot, v_preflight.policy_versions_snapshot,
        v_order.target_followers_count, v_order.target_following_count, FALSE,
        v_capacity_plan, v_required_plan, v_now, v_now,
        v_now + INTERVAL '30 minutes', v_now
    );

    PERFORM public.archive_earlybird_schema_failure_recovery(
        v_order.id, v_failed_request.id, v_new_preflight_id, v_fulfillment.attempt_count
    );
    UPDATE public.earlybird_orders AS earlybird_order
    SET preflight_id = v_new_preflight_id,
        status = 'paid',
        result_request_id = NULL,
        updated_at = v_now
    WHERE earlybird_order.id = v_order.id;
    UPDATE public.earlybird_fulfillments AS fulfillment
    SET status = 'admission_pending',
        attempt_count = 0,
        lease_token = NULL,
        lease_expires_at = NULL,
        next_attempt_at = v_now,
        request_id = NULL,
        operator_admitted_at = v_now,
        last_error_code = NULL,
        last_error_at = NULL,
        completed_at = NULL,
        manual_review_at = NULL,
        updated_at = v_now
    WHERE fulfillment.order_id = v_order.id;

    RETURN QUERY SELECT v_order.id, 'admission_pending'::TEXT, v_new_preflight_id;
END;
$_$;


--
-- Name: recover_exact_earlybird_generation_two_pending_idle(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_exact_earlybird_generation_two_pending_idle(p_order_id uuid, p_expected_preflight_id uuid) RETURNS TABLE(applied boolean, fulfillment_status text, request_id uuid, initial_job_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_current public.analysis_preflights%ROWTYPE;
    v_claim RECORD;
    v_created RECORD;
    v_expected_hash TEXT;
    v_base_preflight_key TEXT;
    v_provider_run_count INTEGER;
BEGIN
    IF p_order_id IS NULL OR p_expected_preflight_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EXACT_G2_PENDING_IDLE_RECOVERY_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT earlybird_order.*
    INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EXACT_G2_PENDING_IDLE_RECOVERY_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    SELECT fulfillment.*
    INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    SELECT preflight.*
    INTO v_current
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_expected_preflight_id
    FOR UPDATE;
    IF v_fulfillment.order_id IS NULL
       OR v_current.id IS NULL
       OR v_order.preflight_id IS DISTINCT FROM p_expected_preflight_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EXACT_G2_PENDING_IDLE_RECOVERY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF v_fulfillment.status = 'analysis_in_progress'
       AND v_fulfillment.request_id IS NOT NULL
       AND v_order.status = 'analysis_in_progress'
       AND v_order.result_request_id IS NOT DISTINCT FROM v_fulfillment.request_id
       AND v_current.status = 'consumed'
       AND v_current.consumed_request_id IS NOT DISTINCT FROM v_fulfillment.request_id THEN
        RETURN QUERY SELECT FALSE, v_fulfillment.status, v_fulfillment.request_id,
            'coordinator:bootstrap'::TEXT;
        RETURN;
    END IF;

    v_expected_hash := pg_catalog.encode(
        extensions.digest(
            pg_catalog.convert_to(
                'earlybird-fulfillment-admission-v1'
                    || pg_catalog.chr(10)
                    || pg_catalog.lower(v_order.id::TEXT),
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );
    v_base_preflight_key := 'earlybird.fulfillment.'
        || pg_catalog.replace(v_order.id::TEXT, '-', '');

    SELECT pg_catalog.count(*)::INTEGER
    INTO v_provider_run_count
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = v_current.id;

    IF v_order.status IS DISTINCT FROM 'paid'
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_order.payment_id IS NULL
       OR v_order.actual_amount_krw IS NULL
       OR v_order.actual_amount_krw < 0
       OR v_order.actual_amount_krw > v_order.expected_amount_krw
       OR v_order.actual_groble_product_id
            IS DISTINCT FROM v_order.expected_groble_product_id
       OR v_order.result_request_id IS NOT NULL
       OR EXISTS (
           SELECT 1
           FROM public.earlybird_webhook_events AS refund_event
           WHERE refund_event.payment_id = v_order.payment_id
             AND refund_event.event_type IN (
                 'payment.refunded',
                 'payment.refund_pending',
                 'payment.cancelled',
                 'payment.failed'
             )
       )
       OR v_fulfillment.status IS DISTINCT FROM 'admission_pending'
       OR v_fulfillment.request_id IS NOT NULL
       OR v_fulfillment.lease_token IS NOT NULL
       OR v_fulfillment.lease_expires_at IS NOT NULL
       OR v_fulfillment.last_error_code IS NOT NULL
       OR v_current.user_id IS DISTINCT FROM v_order.user_id
       OR v_current.target_instagram_id IS DISTINCT FROM v_order.target_instagram_id
       OR v_current.exclusion_decision IS DISTINCT FROM v_order.exclusion_decision
       OR v_current.excluded_instagram_id IS DISTINCT FROM v_order.excluded_instagram_id
       OR v_current.access_mode IS DISTINCT FROM 'production'
       OR v_current.status IS DISTINCT FROM 'ready'
       OR v_current.consumed_request_id IS NOT NULL
       OR v_current.idempotency_key IS DISTINCT FROM v_base_preflight_key
       OR v_current.target_followers_count
            IS DISTINCT FROM v_order.target_followers_count
       OR v_current.target_following_count
            IS DISTINCT FROM v_order.target_following_count
       OR v_current.capacity_required_plan_id IS NULL
       OR v_current.required_plan_id IS NULL
       OR v_current.plan_cards_snapshot IS NULL
       OR v_current.admission_generation IS DISTINCT FROM 2
       OR v_current.admission_status IS DISTINCT FROM 'pending'
       OR v_current.admission_selected_plan_id IS DISTINCT FROM v_order.plan_id
       OR v_current.admission_entitlement_jti_hash IS DISTINCT FROM v_expected_hash
       OR v_current.admission_token IS NULL
       OR v_current.admission_requested_at IS NULL
       OR v_current.admission_refreshed_at IS NOT NULL
       OR v_current.admission_target_followers_count IS NOT NULL
       OR v_current.admission_target_following_count IS NOT NULL
       OR v_current.admission_capacity_required_plan_id IS NOT NULL
       OR v_current.admission_required_plan_id IS NOT NULL
       OR v_current.admission_plan_cards_snapshot IS NOT NULL
       OR v_current.admission_failure_count IS DISTINCT FROM 0
       OR v_current.admission_last_error_code IS NOT NULL
       OR v_current.admission_error_code IS NOT NULL
       OR v_current.admission_dispatch_state IS DISTINCT FROM 'idle'
       OR v_current.admission_dispatch_generation < 1
       OR v_current.admission_dispatch_token IS NOT NULL
       OR v_current.admission_dispatch_reserved_at IS NOT NULL
       OR v_current.admission_dispatched_at IS NOT NULL
       OR v_current.admission_claim_token IS NOT NULL
       OR v_current.admission_lease_expires_at IS NOT NULL
       OR v_provider_run_count IS DISTINCT FROM 1
       OR NOT EXISTS (
           SELECT 1
           FROM public.analysis_preflight_provider_runs AS generation_one_run
           WHERE generation_one_run.preflight_id = v_current.id
             AND generation_one_run.operation_key = 'target-profile-fresh-admission:g1'
             AND generation_one_run.status = 'succeeded'
             AND generation_one_run.logical_provider = 'apify'
             AND generation_one_run.actor_id = 'apify/instagram-profile-scraper'
             AND generation_one_run.credential_slot = 'senary'
             AND generation_one_run.input_hash ~ '^[a-f0-9]{64}$'
             AND generation_one_run.run_id IS NOT NULL
             AND generation_one_run.terminalized_at IS NOT NULL
             AND generation_one_run.actual_usage_usd IS NOT NULL
             AND generation_one_run.usage_reconciled_at IS NOT NULL
             AND generation_one_run.reusable_profile_schema_version = 1
       )
       OR EXISTS (
           SELECT 1
           FROM public.analysis_preflight_provider_runs AS generation_two_run
           WHERE generation_two_run.preflight_id = v_current.id
             AND generation_two_run.operation_key = 'target-profile-fresh-admission:g2'
       )
       OR EXISTS (
           SELECT 1
           FROM public.analysis_requests AS active_request
           WHERE active_request.user_id = v_order.user_id
             AND active_request.status IN ('pending', 'processing')
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EXACT_G2_PENDING_IDLE_RECOVERY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    -- The ready payload must carry an enqueued admission-dispatch witness to
    -- satisfy the durable preflight constraint.  This is checkpoint repair,
    -- not a provider admission reservation: g1 is already reconciled and g2
    -- remains absent; the following RPC only creates the request.
    UPDATE public.analysis_preflights AS preflight
    SET admission_status = 'ready',
        admission_refreshed_at = v_now,
        admission_target_followers_count = v_current.target_followers_count,
        admission_target_following_count = v_current.target_following_count,
        admission_capacity_required_plan_id = v_current.capacity_required_plan_id,
        admission_required_plan_id = v_current.required_plan_id,
        admission_plan_cards_snapshot = v_current.plan_cards_snapshot,
        admission_dispatch_state = 'enqueued',
        admission_dispatch_token = extensions.gen_random_uuid(),
        admission_dispatch_reserved_at = v_now,
        admission_dispatched_at = v_now,
        updated_at = v_now
    WHERE preflight.id = v_current.id
      AND preflight.admission_generation = 2
      AND preflight.admission_status = 'pending'
      AND preflight.admission_dispatch_state = 'idle'
      AND preflight.admission_dispatch_token IS NULL
      AND preflight.admission_claim_token IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EXACT_G2_PENDING_IDLE_RECOVERY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT * INTO v_claim
    FROM public.claim_earlybird_fulfillment(
        v_order.id,
        extensions.gen_random_uuid(),
        300
    );
    IF v_claim.claimed IS DISTINCT FROM TRUE
       OR v_claim.fulfillment_status IS DISTINCT FROM 'admission_pending'
       OR v_claim.lease_token IS NULL
       OR v_claim.lease_fence IS NULL
       OR v_claim.lease_fence < 1 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EXACT_G2_PENDING_IDLE_RECOVERY_CLAIM_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT * INTO v_created
    FROM public.create_or_replay_earlybird_fulfillment_request(
        v_order.id,
        v_claim.lease_token,
        v_claim.lease_fence
    );
    IF v_created.order_id IS DISTINCT FROM v_order.id
       OR v_created.fulfillment_status IS DISTINCT FROM 'analysis_in_progress'
       OR v_created.request_id IS NULL
       OR v_created.initial_job_key IS DISTINCT FROM 'coordinator:bootstrap' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EXACT_G2_PENDING_IDLE_RECOVERY_REQUEST_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    RETURN QUERY SELECT TRUE, v_created.fulfillment_status,
        v_created.request_id, v_created.initial_job_key;
END;
$_$;


--
-- Name: recover_expired_analysis_provider_admission(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_expired_analysis_provider_admission(p_admission_id text, p_recovery_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_current public.analysis_provider_admission_leases%ROWTYPE;
BEGIN
    IF p_admission_id IS NULL OR p_admission_id !~ '^[0-9a-f]{64}$'
       OR p_recovery_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT lease.* INTO v_current
    FROM public.analysis_provider_admission_leases AS lease
    WHERE lease.admission_id = p_admission_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_current.state = 'recovery_required' THEN
        RETURN pg_catalog.jsonb_build_object('recovered', TRUE);
    END IF;
    IF v_current.state <> 'leased' OR v_current.expires_at > v_now THEN
        RETURN pg_catalog.jsonb_build_object('recovered', FALSE);
    END IF;
    UPDATE public.analysis_provider_admission_leases AS lease
    SET state = 'recovery_required', lease_token = p_recovery_token,
        fence = lease.fence + 1, expires_at = v_now,
        recovered_at = v_now, release_reason = NULL,
        resolution_source = NULL, resolution_token_hash = NULL,
        updated_at = v_now
    WHERE lease.admission_id = p_admission_id;
    RETURN pg_catalog.jsonb_build_object('recovered', TRUE);
END;
$_$;


--
-- Name: recover_scrubbed_earlybird_freshness_snapshot_conflict(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_scrubbed_earlybird_freshness_snapshot_conflict(p_order_id uuid, p_expected_manual_review_at timestamp with time zone) RETURNS TABLE(order_id uuid, fulfillment_status text, preflight_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := public.earlybird_fulfillment_clock();
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_old public.analysis_preflights%ROWTYPE;
    v_new public.analysis_preflights%ROWTYPE;
    v_rebound_id UUID;
    v_capacity_plan TEXT;
    v_required_plan TEXT;
    v_cards JSONB := '{}'::JSONB;
    v_capacity_rank INTEGER;
    v_required_rank INTEGER;
    v_plan_id TEXT;
    v_plan_rank INTEGER;
    v_catalog_plan JSONB;
    v_launch_status TEXT;
    v_state TEXT;
    v_reason TEXT;
    v_selected_card JSONB;
    v_order_capacity_plan TEXT;
    v_order_required_plan TEXT;
    v_order_cards JSONB := '{}'::JSONB;
    v_order_capacity_rank INTEGER;
    v_order_required_rank INTEGER;
    v_user_id_hint UUID;
BEGIN
    IF p_order_id IS NULL OR p_expected_manual_review_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_INVALID', ERRCODE = 'P0001';
    END IF;

    -- create_or_replay holds users FOR UPDATE before touching preflights. Take a
    -- compatible user FK lock before any order/preflight lock so its insert can
    -- never form user -> preflight / preflight -> user. The first order read is
    -- only a hint; the locked order must prove that the immutable FK still
    -- names the same user.
    SELECT earlybird_order.user_id INTO v_user_id_hint
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    PERFORM 1
    FROM public.users AS recovery_user
    WHERE recovery_user.id = v_user_id_hint
    FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    -- After the user lock, preserve the fulfillment/rebind order:
    -- order -> fulfillment -> preflight. Active requests remain an unlocked read.
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_order.user_id IS DISTINCT FROM v_user_id_hint THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    SELECT preflight.* INTO v_old
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    IF v_fulfillment.status <> 'manual_review'
       OR v_fulfillment.last_error_code <> 'SNAPSHOT_CONFLICT'
       OR v_fulfillment.lease_token IS NOT NULL
       OR v_fulfillment.lease_expires_at IS NOT NULL
       OR v_fulfillment.request_id IS NOT NULL
       OR v_order.result_request_id IS NOT NULL
       OR v_old.consumed_request_id IS NOT NULL
       OR v_old.consumed_at IS NOT NULL
       OR v_old.lease_token IS NOT NULL
       OR v_old.lease_expires_at IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_STATE_INVALID', ERRCODE = 'P0001';
    END IF;
    IF v_fulfillment.manual_review_at IS DISTINCT FROM p_expected_manual_review_at THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_CAS_MISMATCH', ERRCODE = 'P0001';
    END IF;

    IF v_order.status <> 'paid'
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_order.payment_id IS NULL
       OR v_order.actual_amount_krw IS NULL
       OR v_order.actual_amount_krw < 0
       OR v_order.actual_amount_krw > v_order.expected_amount_krw
       OR v_order.actual_groble_product_id IS DISTINCT FROM v_order.expected_groble_product_id
       OR v_order.target_followers_count IS NULL
       OR v_order.target_following_count IS NULL
       OR v_old.user_id IS DISTINCT FROM v_order.user_id
       OR v_old.access_mode <> 'production'
       OR v_old.status <> 'expired'
       OR v_old.pii_scrubbed_at IS NULL
       OR v_old.expires_at > v_now
       OR v_old.pii_scrubbed_at < v_old.expires_at
       OR v_old.target_instagram_id IS DISTINCT FROM (
           'retained.' || pg_catalog.substr(
               pg_catalog.replace(v_old.id::TEXT, '-', ''), 1, 20
           )
       )
       OR v_old.target_full_name IS NOT NULL
       OR v_old.target_bio IS NOT NULL
       OR v_old.target_profile_image_url IS NOT NULL
       OR v_old.target_followers_count IS NOT NULL
       OR v_old.target_following_count IS NOT NULL
       OR v_old.target_is_private IS NOT NULL
       OR v_old.capacity_required_plan_id IS NOT NULL
       OR v_old.required_plan_id IS NOT NULL
       OR v_old.plan_cards_snapshot IS NOT NULL
       OR v_old.error_code IS NOT NULL
       OR v_old.blocked_at IS NOT NULL
       OR v_old.ready_at IS NOT NULL
       OR v_old.exclusion_decision <> 'skip'
       OR v_old.excluded_instagram_id IS NOT NULL
       OR NOT public.analysis_v2_valid_launch_snapshot(v_old.launch_status_snapshot)
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(v_old.plan_catalog_snapshot)
       OR NOT public.analysis_v2_valid_pricing_snapshot(v_old.pricing_snapshot)
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(v_old.policy_versions_snapshot)
       OR v_order.plan_id NOT IN ('basic', 'standard')
       OR v_old.admission_status <> 'ready'
       OR v_old.admission_selected_plan_id IS DISTINCT FROM v_order.plan_id
       OR v_old.admission_entitlement_jti_hash IS DISTINCT FROM pg_catalog.encode(
           extensions.digest(
               pg_catalog.convert_to(
                   'earlybird-fulfillment-admission-v1'
                   || pg_catalog.chr(10) || pg_catalog.lower(v_order.id::TEXT),
                   'UTF8'
               ),
               'sha256'
           ),
           'hex'
       )
       OR v_old.admission_target_followers_count IS NULL
       OR v_old.admission_target_following_count IS NULL
       OR v_old.admission_claim_token IS NOT NULL
       OR v_old.admission_lease_expires_at IS NOT NULL
       OR v_old.admission_error_code IS NOT NULL
       OR v_old.admission_refreshed_at IS NULL
       OR v_old.admission_refreshed_at > v_now
       OR v_old.admission_refreshed_at >= v_now - INTERVAL '2 minutes' THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_catalog_plan := v_old.plan_catalog_snapshot->v_plan_id;
        v_launch_status := v_old.launch_status_snapshot->>v_plan_id;
        IF v_catalog_plan->>'launchStatus' IS DISTINCT FROM v_launch_status THEN
            RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        IF v_capacity_rank IS NULL
           AND v_old.admission_target_followers_count
                <= (v_catalog_plan->'relationshipCapacity'->>'followers')::INTEGER
           AND v_old.admission_target_following_count
                <= (v_catalog_plan->'relationshipCapacity'->>'following')::INTEGER THEN
            v_capacity_rank := v_plan_rank;
            v_capacity_plan := v_plan_id;
        END IF;
    END LOOP;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        IF v_required_rank IS NULL
           AND v_plan_rank >= v_capacity_rank
           AND v_old.launch_status_snapshot->>v_plan_id = 'production' THEN
            v_required_rank := v_plan_rank;
            v_required_plan := v_plan_id;
        END IF;
    END LOOP;
    IF v_capacity_rank IS NULL OR v_required_rank IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_catalog_plan := v_old.plan_catalog_snapshot->v_plan_id;
        v_launch_status := v_old.launch_status_snapshot->>v_plan_id;
        IF v_plan_rank < v_capacity_rank THEN
            v_state := 'unavailable'; v_reason := 'below_required_plan';
        ELSIF v_launch_status <> 'production' THEN
            v_state := 'unavailable'; v_reason := 'launch_gate';
        ELSIF v_plan_id = v_required_plan THEN
            v_state := 'required'; v_reason := NULL;
        ELSE
            v_state := 'available_upgrade'; v_reason := NULL;
        END IF;
        v_cards := v_cards || pg_catalog.jsonb_build_object(
            v_plan_id,
            pg_catalog.jsonb_build_object(
                'launchStatus', v_launch_status,
                'relationshipCapacity', v_catalog_plan->'relationshipCapacity',
                'detailedMutualLimit', v_catalog_plan->'detailedMutualLimit',
                'selectionState', v_state,
                'unavailableReason', v_reason
            )
        );
    END LOOP;
    IF NOT public.analysis_v2_valid_plan_cards_snapshot(v_cards)
       OR v_old.admission_capacity_required_plan_id IS DISTINCT FROM v_capacity_plan
       OR v_old.admission_required_plan_id IS DISTINCT FROM v_required_plan
       OR v_old.admission_plan_cards_snapshot IS DISTINCT FROM v_cards THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;
    v_selected_card := v_cards->v_order.plan_id;
    IF v_selected_card IS NULL
       OR v_selected_card->>'launchStatus' <> 'production'
       OR v_selected_card->>'selectionState' NOT IN ('required', 'available_upgrade')
       OR v_order.target_followers_count
            > (v_selected_card->'relationshipCapacity'->>'followers')::INTEGER
       OR v_order.target_following_count
            > (v_selected_card->'relationshipCapacity'->>'following')::INTEGER
       OR v_old.admission_target_followers_count
            > (v_selected_card->'relationshipCapacity'->>'followers')::INTEGER
       OR v_old.admission_target_following_count
            > (v_selected_card->'relationshipCapacity'->>'following')::INTEGER THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;

    -- Rebind intentionally reconstructs the primary ready snapshot from the
    -- immutable paid-order counts. Those can be in a lower capacity tier than
    -- a later, witnessed admission refresh while both still fit the selected
    -- paid plan. Recompute that distinct canonical set for postconditions.
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_catalog_plan := v_old.plan_catalog_snapshot->v_plan_id;
        IF v_order_capacity_rank IS NULL
           AND v_order.target_followers_count
                <= (v_catalog_plan->'relationshipCapacity'->>'followers')::INTEGER
           AND v_order.target_following_count
                <= (v_catalog_plan->'relationshipCapacity'->>'following')::INTEGER THEN
            v_order_capacity_rank := v_plan_rank;
            v_order_capacity_plan := v_plan_id;
        END IF;
    END LOOP;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        IF v_order_required_rank IS NULL
           AND v_plan_rank >= v_order_capacity_rank
           AND v_old.launch_status_snapshot->>v_plan_id = 'production' THEN
            v_order_required_rank := v_plan_rank;
            v_order_required_plan := v_plan_id;
        END IF;
    END LOOP;
    IF v_order_capacity_rank IS NULL OR v_order_required_rank IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;
    FOREACH v_plan_id IN ARRAY ARRAY['basic', 'standard', 'plus'] LOOP
        v_plan_rank := CASE v_plan_id WHEN 'basic' THEN 1 WHEN 'standard' THEN 2 ELSE 3 END;
        v_catalog_plan := v_old.plan_catalog_snapshot->v_plan_id;
        v_launch_status := v_old.launch_status_snapshot->>v_plan_id;
        IF v_plan_rank < v_order_capacity_rank THEN
            v_state := 'unavailable'; v_reason := 'below_required_plan';
        ELSIF v_launch_status <> 'production' THEN
            v_state := 'unavailable'; v_reason := 'launch_gate';
        ELSIF v_plan_id = v_order_required_plan THEN
            v_state := 'required'; v_reason := NULL;
        ELSE
            v_state := 'available_upgrade'; v_reason := NULL;
        END IF;
        v_order_cards := v_order_cards || pg_catalog.jsonb_build_object(
            v_plan_id,
            pg_catalog.jsonb_build_object(
                'launchStatus', v_launch_status,
                'relationshipCapacity', v_catalog_plan->'relationshipCapacity',
                'detailedMutualLimit', v_catalog_plan->'detailedMutualLimit',
                'selectionState', v_state,
                'unavailableReason', v_reason
            )
        );
    END LOOP;
    IF NOT public.analysis_v2_valid_plan_cards_snapshot(v_order_cards) THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM public.analysis_requests AS active_request
        WHERE active_request.user_id = v_order.user_id
          AND active_request.status IN ('pending', 'processing')
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_ACTIVE_REQUEST_CONFLICT', ERRCODE = 'P0001';
    END IF;

    UPDATE public.earlybird_fulfillments AS fulfillment
    SET status = 'retryable_failure',
        lease_token = NULL,
        lease_expires_at = NULL,
        next_attempt_at = v_now,
        last_error_code = 'ADMISSION_FRESHNESS_EXPIRED',
        last_error_at = v_now,
        manual_review_at = NULL,
        updated_at = v_now
    WHERE fulfillment.order_id = p_order_id
      AND fulfillment.status = 'manual_review'
      AND fulfillment.manual_review_at IS NOT DISTINCT FROM p_expected_manual_review_at;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_CAS_MISMATCH', ERRCODE = 'P0001';
    END IF;

    v_rebound_id := public.rebind_expired_paid_earlybird_preflight(p_order_id);
    IF v_rebound_id IS NULL OR v_rebound_id = v_old.id THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_REBIND_REFUSED', ERRCODE = 'P0001';
    END IF;
    SELECT preflight.* INTO v_new
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_rebound_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_new.id IS DISTINCT FROM v_rebound_id
       OR v_new.user_id IS DISTINCT FROM v_order.user_id
       OR v_new.status <> 'ready'
       OR v_new.consumed_request_id IS NOT NULL
       OR v_new.consumed_at IS NOT NULL
       OR v_new.access_mode <> 'production'
       OR v_new.target_instagram_id IS DISTINCT FROM v_order.target_instagram_id
       OR v_new.target_followers_count IS DISTINCT FROM v_order.target_followers_count
       OR v_new.target_following_count IS DISTINCT FROM v_order.target_following_count
       OR v_new.exclusion_decision IS DISTINCT FROM v_order.exclusion_decision
       OR v_new.excluded_instagram_id IS DISTINCT FROM v_order.excluded_instagram_id
       OR v_new.launch_status_snapshot IS DISTINCT FROM v_old.launch_status_snapshot
       OR v_new.plan_catalog_snapshot IS DISTINCT FROM v_old.plan_catalog_snapshot
       OR v_new.pricing_version IS DISTINCT FROM v_old.pricing_version
       OR v_new.pricing_snapshot IS DISTINCT FROM v_old.pricing_snapshot
       OR v_new.policy_versions_snapshot IS DISTINCT FROM v_old.policy_versions_snapshot
       OR NOT public.analysis_v2_valid_launch_snapshot(v_new.launch_status_snapshot)
       OR NOT public.analysis_v2_valid_plan_catalog_snapshot(v_new.plan_catalog_snapshot)
       OR NOT public.analysis_v2_valid_plan_cards_snapshot(v_new.plan_cards_snapshot)
       OR NOT public.analysis_v2_valid_pricing_snapshot(v_new.pricing_snapshot)
       OR NOT public.analysis_v2_valid_policy_versions_snapshot(v_new.policy_versions_snapshot)
       OR v_new.capacity_required_plan_id IS DISTINCT FROM v_order_capacity_plan
       OR v_new.required_plan_id IS DISTINCT FROM v_order_required_plan
       OR v_new.plan_cards_snapshot IS DISTINCT FROM v_order_cards
       OR v_new.admission_status NOT IN ('idle', 'pending')
       OR v_new.admission_selected_plan_id IS NOT NULL
       OR v_new.admission_refreshed_at IS NOT NULL
       OR v_new.admission_target_followers_count IS NOT NULL
       OR v_new.admission_target_following_count IS NOT NULL
       OR v_new.admission_plan_cards_snapshot IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'EARLYBIRD_SCRUBBED_FRESHNESS_RECOVERY_POSTCONDITION_FAILED', ERRCODE = 'P0001';
    END IF;

    RETURN QUERY SELECT p_order_id, 'retryable_failure'::TEXT, v_new.id;
END;
$$;


--
-- Name: recover_unstaged_kakao_signup_discord_outbox(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_unstaged_kakao_signup_discord_outbox(p_grace_seconds integer DEFAULT 300) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_count integer;
BEGIN
    UPDATE public.kakao_signup_discord_outbox
    SET masked_name = NULL,
        birthyear = NULL,
        gender = NULL,
        profile_staged_at = clock_timestamp(),
        failure_code = 'PROFILE_STAGE_GRACE_EXPIRED_UNAVAILABLE',
        updated_at = clock_timestamp()
    WHERE status = 'pending'
      AND profile_staged_at IS NULL
      AND created_at < clock_timestamp()
            - make_interval(secs => LEAST(GREATEST(COALESCE(p_grace_seconds, 300), 60), 3600));
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


--
-- Name: refresh_analysis_v2_score_audit_scan_locator(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_analysis_v2_score_audit_scan_locator(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_summary public.analysis_v2_result_summaries%ROWTYPE;
    v_intent public.analysis_v2_score_audit_intents%ROWTYPE;
    v_run public.analysis_v2_score_audit_runs%ROWTYPE;
    v_request_status TEXT;
    v_class TEXT := 'terminal';
    v_active BOOLEAN := FALSE;
    v_eligible_at TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_sort_at TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_retain_until TIMESTAMPTZ;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_request_id::TEXT, 0)
    );
    SELECT summary.* INTO v_summary
    FROM public.analysis_v2_result_summaries AS summary
    WHERE summary.request_id = p_request_id;
    IF NOT FOUND THEN
        DELETE FROM public.analysis_v2_score_audit_scan_locators
        WHERE request_id = p_request_id;
        RETURN;
    END IF;
    SELECT request.status INTO v_request_status
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id;
    SELECT intent.* INTO v_intent
    FROM public.analysis_v2_score_audit_intents AS intent
    WHERE intent.request_id = p_request_id;
    SELECT run.* INTO v_run
    FROM public.analysis_v2_score_audit_runs AS run
    WHERE run.request_id = p_request_id;

    IF v_request_status = 'completed'
       AND v_summary.score_policy_version IN ('risk-policy-v2.4', 'risk-policy-v2.5') THEN
        IF v_intent.request_id IS NULL AND v_run.request_id IS NULL THEN
            v_class := 'missing_intent';
            v_active := TRUE;
            v_eligible_at := v_summary.created_at + INTERVAL '5 minutes';
            v_sort_at := v_summary.created_at;
        ELSIF v_intent.intent_status = 'queued' THEN
            v_retain_until := v_intent.retain_until;
            IF v_run.request_id IS NULL
               OR v_run.source_result_hash IS DISTINCT FROM v_intent.source_result_hash
               OR v_run.source_generation IS DISTINCT FROM v_intent.source_generation THEN
                v_class := 'unbound_intent';
                v_active := TRUE;
                v_eligible_at := LEAST(
                    pg_catalog.clock_timestamp(), v_intent.retain_until
                );
                v_sort_at := v_intent.updated_at;
            ELSIF v_run.status = 'queued' THEN
                v_class := 'queued_run';
                v_active := TRUE;
                v_eligible_at := LEAST(
                    pg_catalog.clock_timestamp(), v_intent.retain_until
                );
                v_sort_at := v_run.updated_at;
            ELSIF v_run.status = 'partial'
              AND v_run.reason IN (
                  'SOURCE_EVIDENCE_UNAVAILABLE','SOURCE_CAPTURE_FAILED'
              ) THEN
                v_class := 'retryable_partial';
                v_active := TRUE;
                v_eligible_at := LEAST(
                    pg_catalog.clock_timestamp(), v_intent.retain_until
                );
                v_sort_at := v_run.updated_at;
            ELSIF v_run.status = 'processing' THEN
                v_class := 'expired_lease';
                v_active := TRUE;
                v_eligible_at := LEAST(
                    v_run.lease_expires_at, v_intent.retain_until
                );
                v_sort_at := LEAST(
                    v_run.lease_expires_at, v_intent.retain_until
                );
            END IF;
        END IF;
    END IF;

    INSERT INTO public.analysis_v2_score_audit_scan_locators (
        request_id, locator_class, active, eligible_at, sort_at, retain_until,
        retention_deadline_epoch
    ) VALUES (
        p_request_id, v_class, v_active, v_eligible_at, v_sort_at, v_retain_until,
        CASE WHEN v_retain_until IS NULL THEN NULL ELSE
            pg_catalog.floor(EXTRACT(EPOCH FROM v_retain_until))::BIGINT
        END
    ) ON CONFLICT (request_id) DO UPDATE SET
        locator_class = EXCLUDED.locator_class,
        active = EXCLUDED.active,
        eligible_at = EXCLUDED.eligible_at,
        sort_at = EXCLUDED.sort_at,
        retain_until = EXCLUDED.retain_until,
        retention_deadline_epoch = EXCLUDED.retention_deadline_epoch,
        updated_at = pg_catalog.clock_timestamp();
END;
$$;


--
-- Name: refresh_analysis_v2_score_audit_scan_locator_request_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_analysis_v2_score_audit_scan_locator_request_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    PERFORM public.refresh_analysis_v2_score_audit_scan_locator(
        CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END
    );
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: refresh_analysis_v2_score_audit_scan_locator_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_analysis_v2_score_audit_scan_locator_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    PERFORM public.refresh_analysis_v2_score_audit_scan_locator(
        CASE WHEN TG_OP = 'DELETE' THEN OLD.request_id ELSE NEW.request_id END
    );
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: register_analysis_revenue_ai_routing_attempt_v1(uuid, text, uuid, text, text, smallint, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_analysis_revenue_ai_routing_attempt_v1(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_source_operation_key text, p_source_attempt smallint, p_routing_attempt smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_ai public.analysis_v2_ai_attempts%ROWTYPE;
    v_existing public.analysis_revenue_ai_routing_attempt_lineages%ROWTYPE;
    v_source_hash TEXT;
BEGIN
    IF p_job_key IS DISTINCT FROM 'track:relationships:collect'
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_source_operation_key !~ '^gender-triage:[a-f0-9]{64}$'
       OR p_source_attempt NOT BETWEEN 1 AND 4
       OR p_routing_attempt NOT IN (1, 2) THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    PERFORM public.analysis_revenue_ai_cost_assert_lineage_v1(
        p_request_id, p_job_key, p_job_claim_token, p_job_input_hash, TRUE
    );
    SELECT * INTO v_ai
      FROM public.analysis_v2_ai_attempts
     WHERE request_id = p_request_id
       AND job_key = p_job_key
       AND operation_key = p_source_operation_key
       AND attempt = p_source_attempt
     FOR UPDATE;
    IF v_ai.request_id IS NULL
       OR v_ai.job_claim_token IS DISTINCT FROM p_job_claim_token
       OR v_ai.stage IS DISTINCT FROM 'genderTriage'
       OR v_ai.status IS DISTINCT FROM 'reserved'
       OR v_ai.retry_count IS DISTINCT FROM p_source_attempt - 1 THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    v_source_hash := pg_catalog.encode(
        extensions.digest(pg_catalog.convert_to(p_source_operation_key, 'UTF8'), 'sha256'),
        'hex'
    );
    SELECT * INTO v_existing
      FROM public.analysis_revenue_ai_routing_attempt_lineages
     WHERE request_id = p_request_id
       AND job_key = p_job_key
       AND source_operation_key_hash = v_source_hash
     FOR UPDATE;
    IF v_existing.request_id IS NOT NULL THEN
        IF v_existing.job_input_hash IS DISTINCT FROM p_job_input_hash
           OR v_existing.routing_attempt IS DISTINCT FROM p_routing_attempt THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_DRIFT';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'accepted', 'created', FALSE, 'replayed', TRUE
        );
    END IF;
    INSERT INTO public.analysis_revenue_ai_routing_attempt_lineages(
        request_id, job_key, job_input_hash, source_operation_key_hash, routing_attempt
    ) VALUES (
        p_request_id, p_job_key, p_job_input_hash, v_source_hash, p_routing_attempt
    );
    RETURN pg_catalog.jsonb_build_object(
        'disposition', 'accepted', 'created', TRUE, 'replayed', FALSE
    );
END;
$_$;


--
-- Name: register_analysis_v2_media_artifact(uuid, text, uuid, text, text, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_analysis_v2_media_artifact(p_request_id uuid, p_job_key text, p_claim_token uuid, p_artifact_key text, p_artifact_kind text, p_content_sha256 text, p_content_type text, p_object_name text, p_object_generation text, p_byte_size integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_existing public.analysis_v2_media_artifacts%ROWTYPE;
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR p_claim_token IS NULL
       OR p_artifact_key IS NULL
       OR p_artifact_kind IS NULL
       OR p_content_sha256 IS NULL
       OR p_content_type IS NULL
       OR p_object_name IS NULL
       OR p_object_generation IS NULL
       OR p_byte_size IS NULL
       OR p_artifact_key !~ '^[a-f0-9]{64}$'
       OR p_content_sha256 !~ '^[a-f0-9]{64}$'
       OR p_object_generation !~ '^[1-9][0-9]{0,31}$'
       OR (
            (p_artifact_kind = 'jpeg'
                AND p_content_type = 'image/jpeg'
                AND p_byte_size BETWEEN 4 AND 8388608)
            OR (p_artifact_kind = 'media_bundle'
                AND p_content_type = 'application/octet-stream'
                AND p_byte_size BETWEEN 16 AND 33554432)
       ) IS NOT TRUE
       OR p_object_name <> 'analysis-v2/' || p_request_id::TEXT || '/'
            || p_artifact_key || '/' || p_content_sha256
            || (CASE p_artifact_kind WHEN 'jpeg' THEN '.jpg' ELSE '.bin' END) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_MEDIA_ARTIFACT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    -- Preserve the canonical terminal-capable lock order.
    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;

    IF v_request.id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR v_job.request_id IS NULL
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_MEDIA_ARTIFACT_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT artifact.*
    INTO v_existing
    FROM public.analysis_v2_media_artifacts AS artifact
    WHERE artifact.request_id = p_request_id
      AND artifact.artifact_key = p_artifact_key
    FOR UPDATE;

    IF FOUND THEN
        IF v_existing.registration_job_key IS DISTINCT FROM p_job_key
           OR v_existing.artifact_kind IS DISTINCT FROM p_artifact_kind
           OR v_existing.content_sha256 IS DISTINCT FROM p_content_sha256
           OR v_existing.content_type IS DISTINCT FROM p_content_type
           OR v_existing.object_name IS DISTINCT FROM p_object_name
           OR v_existing.object_generation IS DISTINCT FROM p_object_generation
           OR v_existing.byte_size IS DISTINCT FROM p_byte_size
           OR v_existing.deleted_at IS NOT NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_MEDIA_ARTIFACT_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
    ELSE
        INSERT INTO public.analysis_v2_media_artifacts (
            request_id,
            artifact_key,
            registration_job_key,
            artifact_kind,
            content_sha256,
            content_type,
            object_name,
            object_generation,
            byte_size,
            expires_at,
            created_at
        ) VALUES (
            p_request_id,
            p_artifact_key,
            p_job_key,
            p_artifact_kind,
            p_content_sha256,
            p_content_type,
            p_object_name,
            p_object_generation,
            p_byte_size,
            v_now + INTERVAL '6 hours',
            v_now
        );
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', p_request_id,
        'artifactKey', p_artifact_key,
        'artifactKind', p_artifact_kind,
        'contentSha256', p_content_sha256,
        'contentType', p_content_type,
        'objectName', p_object_name,
        'objectGeneration', p_object_generation,
        'byteSize', p_byte_size
    );
END;
$_$;


--
-- Name: register_analysis_v2_replay_capture_fragment(uuid, uuid, text, text, text, integer, integer, text, text, integer, smallint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_analysis_v2_replay_capture_fragment(p_capture_id uuid, p_write_lease_token uuid, p_opaque_locator_hash text, p_fragment_kind text, p_stage text, p_batch_ordinal integer, p_ordinal integer, p_object_key text, p_ciphertext_sha256 text, p_ciphertext_byte_size integer, p_envelope_version smallint, p_content_commitment text, p_operator_fingerprint text, p_reason_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_capture public.analysis_v2_replay_capture_authorizations%ROWTYPE;
    v_existing public.analysis_v2_replay_capture_fragments%ROWTYPE;
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    IF p_write_lease_token IS NULL
       OR p_opaque_locator_hash !~ '^[a-f0-9]{64}$'
       OR p_ciphertext_sha256 !~ '^[a-f0-9]{64}$'
       OR p_content_commitment !~ '^[a-f0-9]{64}$'
       OR p_object_key IS DISTINCT FROM (
            'replay/v1/' || p_capture_id::TEXT || '/'
            || pg_catalog.encode(
                extensions.digest(
                    'replay/v1' || pg_catalog.chr(10)
                    || p_capture_id::TEXT || pg_catalog.chr(10)
                    || p_opaque_locator_hash || pg_catalog.chr(10)
                    || p_fragment_kind || pg_catalog.chr(10)
                    || p_stage || pg_catalog.chr(10)
                    || p_batch_ordinal::TEXT || pg_catalog.chr(10)
                    || p_ordinal::TEXT,
                    'sha256'
                ),
                'hex'
            )
            || '.enc'
       )
       OR p_fragment_kind NOT IN ('provider_payload', 'normalized_snapshot', 'execution_trace')
       OR p_stage NOT IN ('preflight', 'collection', 'scoring', 'finalization')
       OR p_batch_ordinal NOT BETWEEN 0 AND 127 OR p_ordinal NOT BETWEEN 0 AND 1023
       OR p_ciphertext_byte_size NOT BETWEEN 1 AND 8388608 OR p_envelope_version <> 1
       OR p_operator_fingerprint !~ '^[a-f0-9]{64}$' OR p_reason_code !~ '^[A-Z0-9_]{1,64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_CAPTURE_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT * INTO v_capture FROM public.analysis_v2_replay_capture_authorizations WHERE capture_id = p_capture_id FOR UPDATE;
    IF NOT FOUND OR v_capture.state <> 'capturing'
       OR v_capture.write_lease_token IS DISTINCT FROM p_write_lease_token
       OR v_capture.write_lease_expires_at <= v_now
       OR v_capture.artifact_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_CAPTURE_REGISTER_REJECTED', ERRCODE = 'P0001';
    END IF;
    SELECT * INTO v_existing FROM public.analysis_v2_replay_capture_fragments
    WHERE capture_id = p_capture_id AND opaque_locator_hash = p_opaque_locator_hash
      AND fragment_kind = p_fragment_kind AND stage = p_stage AND batch_ordinal = p_batch_ordinal AND ordinal = p_ordinal;
    IF FOUND THEN
        IF v_existing.ciphertext_sha256 IS DISTINCT FROM p_ciphertext_sha256
           OR v_existing.ciphertext_byte_size IS DISTINCT FROM p_ciphertext_byte_size
           OR v_existing.content_commitment IS DISTINCT FROM p_content_commitment
           OR v_existing.object_key IS DISTINCT FROM p_object_key THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_CAPTURE_FRAGMENT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN;
    END IF;
    IF v_capture.actual_fragment_count >= v_capture.expected_fragment_count
       OR v_capture.actual_ciphertext_byte_size + p_ciphertext_byte_size > 67108864 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_REPLAY_CAPTURE_FRAGMENT_LIMIT', ERRCODE = 'P0001';
    END IF;
    INSERT INTO public.analysis_v2_replay_capture_fragments (
        capture_id, opaque_locator_hash, fragment_kind, stage, batch_ordinal, ordinal,
        object_key, ciphertext_sha256, content_commitment,
        ciphertext_byte_size, envelope_version, expires_at
    ) VALUES (
        p_capture_id, p_opaque_locator_hash, p_fragment_kind, p_stage, p_batch_ordinal, p_ordinal,
        p_object_key, p_ciphertext_sha256, p_content_commitment,
        p_ciphertext_byte_size, p_envelope_version, v_capture.artifact_expires_at
    );
    UPDATE public.analysis_v2_replay_capture_authorizations
    SET actual_fragment_count = actual_fragment_count + 1,
        actual_ciphertext_byte_size = actual_ciphertext_byte_size + p_ciphertext_byte_size,
        updated_at = v_now
    WHERE capture_id = p_capture_id;
    INSERT INTO public.analysis_v2_replay_capture_audit_events (capture_id, event_type, operator_fingerprint, reason_code)
    VALUES (p_capture_id, 'register', p_operator_fingerprint, p_reason_code);
END;
$_$;


--
-- Name: register_analysis_v2_result_image_outcome(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_analysis_v2_result_image_outcome(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_outcome jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_manifest public.analysis_v2_result_image_manifests%ROWTYPE;
    v_existing public.analysis_v2_result_image_objects%ROWTYPE;
    v_kind TEXT;
    v_locator TEXT;
    v_ordinal INTEGER;
    v_source_fingerprint TEXT;
    v_status TEXT;
    v_object_key TEXT;
    v_sha256 TEXT;
    v_byte_size INTEGER;
    v_captured_at TIMESTAMP WITH TIME ZONE;
    v_expires_at TIMESTAMP WITH TIME ZONE;
    v_failure_code TEXT;
    v_is_mandatory BOOLEAN;
    v_expected_mandatory BOOLEAN;
BEGIN
    PERFORM public.analysis_v2_assert_result_image_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    IF p_outcome IS NULL
       OR pg_catalog.jsonb_typeof(p_outcome) <> 'object'
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_object_keys(p_outcome) AS key_name(value)
            WHERE key_name.value NOT IN (
                'kind', 'candidateLocator', 'sortOrdinal',
                'sourceFingerprint', 'status', 'objectKey', 'sha256',
                'byteSize', 'capturedAt', 'expiresAt', 'failureCode',
                'isMandatory'
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT manifest.* INTO v_manifest
    FROM public.analysis_v2_result_image_manifests AS manifest
    WHERE manifest.request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_manifest.producer_job_key IS DISTINCT FROM p_job_key
       OR v_manifest.producer_input_hash IS DISTINCT FROM p_job_input_hash
       OR v_manifest.producer_claim_token IS DISTINCT FROM p_claim_token
       OR v_manifest.sealed_at IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    BEGIN
        v_kind := p_outcome->>'kind';
        v_locator := p_outcome->>'candidateLocator';
        v_ordinal := (p_outcome->>'sortOrdinal')::INTEGER;
        v_source_fingerprint := NULLIF(p_outcome->>'sourceFingerprint', '');
        v_status := p_outcome->>'status';
        v_object_key := NULLIF(p_outcome->>'objectKey', '');
        v_sha256 := NULLIF(p_outcome->>'sha256', '');
        v_byte_size := NULLIF(p_outcome->>'byteSize', '')::INTEGER;
        v_captured_at := NULLIF(p_outcome->>'capturedAt', '')
            ::TIMESTAMP WITH TIME ZONE;
        v_expires_at := (p_outcome->>'expiresAt')
            ::TIMESTAMP WITH TIME ZONE;
        v_failure_code := NULLIF(p_outcome->>'failureCode', '');
        v_is_mandatory := (p_outcome->>'isMandatory')::BOOLEAN;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_INVALID',
            ERRCODE = 'P0001';
    END;

    v_expected_mandatory := v_source_fingerprint IS NOT NULL
        AND (
            v_kind = 'target'
            OR (v_kind = 'female' AND v_ordinal BETWEEN 1 AND 3)
        );
    IF v_kind NOT IN ('target', 'female', 'private')
       OR v_locator !~ '^[A-Za-z0-9._:-]{1,128}$'
       OR v_locator ~* 'https?'
       OR (
            v_kind = 'target'
            AND (v_locator <> 'target' OR v_ordinal <> 0)
       )
       OR (
            v_kind IN ('female', 'private')
            AND (
                v_locator = 'target'
                OR v_ordinal NOT BETWEEN 1 AND 50000
            )
       )
       OR (
            v_source_fingerprint IS NOT NULL
            AND v_source_fingerprint !~ '^[a-f0-9]{64}$'
       )
       OR v_status NOT IN ('ready', 'source_missing', 'capture_failed')
       OR v_is_mandatory IS DISTINCT FROM v_expected_mandatory
       OR v_expires_at IS NULL
       OR (
            v_status = 'ready'
            AND (
                v_source_fingerprint IS NULL
                OR v_object_key !~
                    '^v1/[a-f0-9]{32}/(target|female|private)/[a-f0-9]{32}[.]webp$'
                OR pg_catalog.strpos(v_object_key, '/' || v_kind || '/') = 0
                OR v_sha256 !~ '^[a-f0-9]{64}$'
                OR v_byte_size NOT BETWEEN 1 AND 131072
                OR v_captured_at IS NULL
                OR v_captured_at > v_now + INTERVAL '5 minutes'
                OR pg_catalog.abs(EXTRACT(
                    epoch FROM (
                        v_expires_at - v_captured_at - INTERVAL '30 days'
                    )
                )) > 3600
                OR v_failure_code IS NOT NULL
            )
       )
       OR (
            v_status = 'source_missing'
            AND (
                v_source_fingerprint IS NOT NULL
                OR pg_catalog.num_nonnulls(
                    v_object_key, v_sha256, v_byte_size, v_captured_at,
                    v_failure_code
                ) <> 0
                OR pg_catalog.abs(EXTRACT(
                    epoch FROM (
                        v_expires_at - v_now - INTERVAL '30 days'
                    )
                )) > 3600
            )
       )
       OR (
            v_status = 'capture_failed'
            AND (
                v_source_fingerprint IS NULL
                OR pg_catalog.num_nonnulls(
                    v_object_key, v_sha256, v_byte_size, v_captured_at
                ) <> 0
                OR v_failure_code !~ '^[A-Z][A-Z0-9_]{0,63}$'
                OR pg_catalog.abs(EXTRACT(
                    epoch FROM (
                        v_expires_at - v_now - INTERVAL '30 days'
                    )
                )) > 3600
            )
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT image_object.* INTO v_existing
    FROM public.analysis_v2_result_image_objects AS image_object
    WHERE image_object.request_id = p_request_id
      AND image_object.kind = v_kind
      AND image_object.candidate_locator = v_locator
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.status = 'capture_failed'
           AND v_status = 'ready'
           AND v_existing.sort_ordinal IS NOT DISTINCT FROM v_ordinal
           AND v_existing.source_fingerprint IS NOT DISTINCT FROM
                v_source_fingerprint
           AND v_existing.is_mandatory IS NOT DISTINCT FROM v_is_mandatory THEN
            UPDATE public.analysis_v2_result_image_objects AS image_object
            SET status = 'ready',
                object_key = v_object_key,
                sha256 = v_sha256,
                byte_size = v_byte_size,
                captured_at = v_captured_at,
                expires_at = v_expires_at,
                failure_code = NULL,
                updated_at = v_now
            WHERE image_object.request_id = p_request_id
              AND image_object.kind = v_kind
              AND image_object.candidate_locator = v_locator;
            RETURN pg_catalog.jsonb_build_object(
                'registered', TRUE,
                'status', 'ready'
            );
        END IF;
        IF v_existing.sort_ordinal IS DISTINCT FROM v_ordinal
           OR v_existing.source_fingerprint IS DISTINCT FROM
                v_source_fingerprint
           OR v_existing.status IS DISTINCT FROM v_status
           OR v_existing.object_key IS DISTINCT FROM v_object_key
           OR v_existing.sha256 IS DISTINCT FROM v_sha256
           OR v_existing.byte_size IS DISTINCT FROM v_byte_size
           OR v_existing.captured_at IS DISTINCT FROM v_captured_at
           OR v_existing.expires_at IS DISTINCT FROM v_expires_at
           OR v_existing.failure_code IS DISTINCT FROM v_failure_code
           OR v_existing.is_mandatory IS DISTINCT FROM v_is_mandatory THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'registered', FALSE,
            'status', v_existing.status
        );
    END IF;

    INSERT INTO public.analysis_v2_result_image_objects (
        request_id, kind, candidate_locator, sort_ordinal,
        source_fingerprint, status, object_key, sha256, byte_size,
        captured_at, observed_at, expires_at, failure_code, is_mandatory
    ) VALUES (
        p_request_id, v_kind, v_locator, v_ordinal,
        v_source_fingerprint, v_status, v_object_key, v_sha256, v_byte_size,
        v_captured_at, v_now, v_expires_at, v_failure_code, v_is_mandatory
    );
    RETURN pg_catalog.jsonb_build_object(
        'registered', TRUE,
        'status', v_status
    );
END;
$_$;


--
-- Name: register_earlybird_v211_concierge_reviewed_source(uuid, uuid, uuid, uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_earlybird_v211_concierge_reviewed_source(p_order_id uuid, p_source_request_id uuid, p_result_request_id uuid, p_owner_id uuid, p_target_instagram_id text, p_source_fingerprint text, p_target_posts jsonb, p_target_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_replay RECORD;
    v_order public.earlybird_orders%ROWTYPE;
    v_source public.analysis_requests%ROWTYPE;
    v_result public.analysis_requests%ROWTYPE;
    v_target TEXT;
BEGIN
    v_target := pg_catalog.lower(
        pg_catalog.regexp_replace(pg_catalog.btrim(p_target_instagram_id), '^@', '')
    );
    IF p_order_id IS NULL
       OR p_source_request_id IS NULL
       OR p_result_request_id IS NULL
       OR p_owner_id IS NULL
       OR v_target !~ '^[a-z0-9._]{1,30}$'
       OR p_source_fingerprint IS NULL
       OR p_source_fingerprint !~ '^[a-f0-9]{64}$'
       OR pg_catalog.jsonb_typeof(p_target_posts) <> 'array'
       OR pg_catalog.jsonb_typeof(p_target_evidence) <> 'array'
       OR pg_catalog.jsonb_array_length(p_target_posts) > 8
       OR pg_catalog.jsonb_array_length(p_target_evidence) > 95
       OR pg_catalog.octet_length(p_target_posts::TEXT) > 200000
       OR pg_catalog.octet_length(p_target_evidence::TEXT) > 300000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_REVIEWED_SOURCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT replay.*
      INTO v_replay
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, first_relationship_failed_request_id UUID, second_relationship_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ, reviewed_source_request_id UUID, reviewed_source_owner_id UUID, reviewed_source_target_instagram_id TEXT, reviewed_source_result_request_id UUID, reviewed_source_target_posts JSONB, reviewed_source_target_evidence JSONB, reviewed_source_fingerprint VARCHAR(64), reviewed_source_registered_at TIMESTAMPTZ, published_source_fingerprint VARCHAR(64), published_result_hash VARCHAR(64), published_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_concierge_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','first_relationship_failed_request_id','second_relationship_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at','reviewed_source_request_id','reviewed_source_owner_id','reviewed_source_target_instagram_id','reviewed_source_result_request_id','reviewed_source_target_posts','reviewed_source_target_evidence','reviewed_source_fingerprint','reviewed_source_registered_at','published_source_fingerprint','published_result_hash','published_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.first_relationship_failed_request_id IS NOT NULL AND decoded.second_relationship_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS replay
    WHERE replay.order_id = p_order_id
    FOR UPDATE;
    SELECT earlybird_order.*
      INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    SELECT source_request.*
      INTO v_source
    FROM public.analysis_requests AS source_request
    WHERE source_request.id = p_source_request_id;
    SELECT result_request.*
      INTO v_result
    FROM public.analysis_requests AS result_request
    WHERE result_request.id = p_result_request_id;

    IF v_replay.order_id IS NULL
       OR v_replay.original_failed_request_id IS DISTINCT FROM p_source_request_id
       OR v_order.id IS NULL
       OR v_order.user_id IS DISTINCT FROM p_owner_id
       OR pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id)) IS DISTINCT FROM v_target
       OR v_order.result_request_id IS DISTINCT FROM p_result_request_id
       OR v_order.status <> 'completed'
       OR v_order.plan_id <> 'basic'
       OR v_source.id IS NULL
       OR v_source.user_id IS DISTINCT FROM p_owner_id
       OR v_source.pipeline_version <> 'v2'
       OR v_source.status <> 'failed'
       OR v_result.id IS NULL
       OR v_result.user_id IS DISTINCT FROM p_owner_id
       OR pg_catalog.lower(pg_catalog.btrim(v_result.target_instagram_id)) IS DISTINCT FROM v_target
       OR v_result.pipeline_version <> 'v1'
       OR v_result.status <> 'completed' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_REVIEWED_SOURCE_SCOPE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF v_replay.reviewed_source_fingerprint IS NOT NULL THEN
        IF v_replay.reviewed_source_fingerprint = p_source_fingerprint
           AND v_replay.reviewed_source_request_id = p_source_request_id
           AND v_replay.reviewed_source_owner_id = p_owner_id
           AND v_replay.reviewed_source_target_instagram_id = v_target
           AND v_replay.reviewed_source_result_request_id = p_result_request_id
           AND v_replay.reviewed_source_target_posts = p_target_posts
           AND v_replay.reviewed_source_target_evidence = p_target_evidence THEN
            RETURN pg_catalog.jsonb_build_object(
                'registered', TRUE,
                'sourceFingerprint', p_source_fingerprint
            );
        END IF;
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_CONCIERGE_REVIEWED_SOURCE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    PERFORM pg_catalog.set_config(
        'app.earlybird_v211_concierge_reviewed_source_register', '1', TRUE
    );
    PERFORM public.archive_earlybird_v211_concierge_reviewed_source(p_order_id, p_source_request_id, p_owner_id, v_target, p_result_request_id, p_target_posts, p_target_evidence, p_source_fingerprint, pg_catalog.clock_timestamp());
    PERFORM pg_catalog.set_config(
        'app.earlybird_v211_concierge_reviewed_source_register', '0', TRUE
    );

    RETURN pg_catalog.jsonb_build_object(
        'registered', TRUE,
        'sourceFingerprint', p_source_fingerprint
    );
END;
$_$;


