--
-- Name: reject_analysis_preflight_provider_run_start(uuid, uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_analysis_preflight_provider_run_start(p_preflight_id uuid, p_claim_token uuid, p_input_hash text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_operation_key TEXT := 'target-profile-fallback';
    v_preflight public.analysis_preflights%ROWTYPE;
    v_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_claim_token IS NULL
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS DISTINCT FROM 0.002600000000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status IS DISTINCT FROM 'processing'
       OR v_preflight.lease_token IS DISTINCT FROM p_claim_token
       OR v_preflight.lease_expires_at IS NULL
       OR v_preflight.lease_expires_at <= v_now
       OR v_preflight.expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = v_operation_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_run.input_hash IS DISTINCT FROM p_input_hash
       OR v_run.logical_provider IS DISTINCT FROM 'apify'
       OR v_run.actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper'
       OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM p_max_charge_usd THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;

    IF v_run.status = 'rejected' THEN
        PERFORM public.record_analysis_preflight_provider_start_rejected_cost_event(
            p_preflight_id, v_operation_key, v_run.logical_provider, v_run.actor_id,
            v_run.credential_slot, (v_run.terminalized_at AT TIME ZONE 'UTC')::DATE
        );
        RETURN public.analysis_preflight_provider_run_json(v_run);
    END IF;
    IF v_run.status IS DISTINCT FROM 'starting' OR v_run.run_id IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflight_provider_runs AS provider_run
    SET status = 'rejected',
        terminalized_at = v_now,
        actual_usage_usd = 0,
        usage_reconciled_at = v_now,
        updated_at = v_now
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = v_operation_key
    RETURNING provider_run.* INTO v_run;

    PERFORM public.record_analysis_preflight_provider_start_rejected_cost_event(
        p_preflight_id, v_operation_key, v_run.logical_provider, v_run.actor_id,
        v_run.credential_slot, (v_run.terminalized_at AT TIME ZONE 'UTC')::DATE
    );
    RETURN public.analysis_preflight_provider_run_json(v_run);
END;
$_$;


--
-- Name: reject_analysis_revenue_fresh_provider_evidence_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_analysis_revenue_fresh_provider_evidence_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF OLD.request_id IS DISTINCT FROM NEW.request_id
       OR OLD.job_key IS DISTINCT FROM NEW.job_key
       OR OLD.job_input_hash IS DISTINCT FROM NEW.job_input_hash
       OR OLD.operation_key_hash IS DISTINCT FROM NEW.operation_key_hash
       OR OLD.provider IS DISTINCT FROM NEW.provider
       OR OLD.provider_input_hash IS DISTINCT FROM NEW.provider_input_hash
       OR OLD.provider_run_hash IS DISTINCT FROM NEW.provider_run_hash
       OR OLD.provider_run_started_at IS DISTINCT FROM NEW.provider_run_started_at
       OR OLD.no_reuse IS DISTINCT FROM NEW.no_reuse
       OR OLD.no_adoption IS DISTINCT FROM NEW.no_adoption
       OR OLD.no_cache IS DISTINCT FROM NEW.no_cache
       OR OLD.created_at IS DISTINCT FROM NEW.created_at
       OR OLD.provider_dataset_hash IS NOT NULL
       OR OLD.dataset_bound_at IS NOT NULL
       OR NEW.provider_dataset_hash IS NULL
       OR NEW.dataset_bound_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'FRESH_PROVENANCE_DRIFT', ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_analysis_revenue_run_ledger_lineage_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_analysis_revenue_run_ledger_lineage_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF OLD.request_id IS DISTINCT FROM NEW.request_id
       OR OLD.preflight_id IS DISTINCT FROM NEW.preflight_id
       OR OLD.user_id IS DISTINCT FROM NEW.user_id
       OR OLD.plan_id IS DISTINCT FROM NEW.plan_id
       OR OLD.access_mode IS DISTINCT FROM NEW.access_mode
       OR OLD.target_username_hmac IS DISTINCT FROM NEW.target_username_hmac
       OR OLD.preflight_refreshed_at IS DISTINCT FROM NEW.preflight_refreshed_at
       OR OLD.request_started_at IS DISTINCT FROM NEW.request_started_at THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_LEDGER_DRIFT', ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_analysis_v2_fresh_admission_provider_run_start(uuid, integer, uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_analysis_v2_fresh_admission_provider_run_start(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid, p_input_hash text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_operation_key TEXT;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_claim_token IS NULL
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS DISTINCT FROM 0.002600000000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID', ERRCODE = 'P0001';
    END IF;
    v_operation_key := 'target-profile-fresh-admission:g'
        || p_admission_generation::TEXT;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status IS DISTINCT FROM 'ready'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.expires_at <= v_now
       OR v_preflight.admission_generation IS DISTINCT FROM p_admission_generation
       OR v_preflight.admission_status IS DISTINCT FROM 'processing'
       OR v_preflight.admission_claim_token IS DISTINCT FROM p_claim_token
       OR v_preflight.admission_lease_expires_at IS NULL
       OR v_preflight.admission_lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = v_operation_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_run.input_hash IS DISTINCT FROM p_input_hash
       OR v_run.logical_provider IS DISTINCT FROM 'apify'
       OR v_run.actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper'
       OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM p_max_charge_usd THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;

    IF v_run.status = 'rejected' THEN
        PERFORM public.record_analysis_preflight_provider_start_rejected_cost_event(
            p_preflight_id, v_operation_key, v_run.logical_provider, v_run.actor_id,
            v_run.credential_slot, (v_run.terminalized_at AT TIME ZONE 'UTC')::DATE
        );
        RETURN public.analysis_preflight_provider_run_json(v_run);
    END IF;
    IF v_run.status IS DISTINCT FROM 'starting' OR v_run.run_id IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflight_provider_runs AS provider_run
    SET status = 'rejected',
        terminalized_at = v_now,
        actual_usage_usd = 0,
        usage_reconciled_at = v_now,
        updated_at = v_now
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = v_operation_key
    RETURNING provider_run.* INTO v_run;

    PERFORM public.record_analysis_preflight_provider_start_rejected_cost_event(
        p_preflight_id, v_operation_key, v_run.logical_provider, v_run.actor_id,
        v_run.credential_slot, (v_run.terminalized_at AT TIME ZONE 'UTC')::DATE
    );
    RETURN public.analysis_preflight_provider_run_json(v_run);
END;
$_$;


--
-- Name: reject_analysis_v2_provider_run_start(uuid, text, uuid, text, text, uuid, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_analysis_v2_provider_run_start(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_reservation_token uuid, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight_id UUID;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_run public.analysis_v2_provider_runs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_operation_key IS NULL
       OR NOT public.analysis_v2_valid_provider_operation_key(p_operation_key)
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_reservation_token IS NULL
       OR p_logical_provider NOT IN ('apify', 'coderx')
       OR p_actor_id IS NULL
       OR pg_catalog.char_length(p_actor_id) NOT BETWEEN 3 AND 200
       OR p_actor_id !~ '^[A-Za-z0-9][A-Za-z0-9._~/-]{2,199}$'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS NULL
       OR p_max_charge_usd NOT BETWEEN 0 AND 100000
       OR p_max_charge_usd <> pg_catalog.round(p_max_charge_usd, 12) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.id
    INTO v_preflight_id
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND OR v_request.status NOT IN ('pending', 'processing') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_ACTIVE', ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    IF v_run.job_claim_token IS DISTINCT FROM p_claim_token
       OR v_run.reservation_token IS DISTINCT FROM p_reservation_token THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF v_run.input_hash IS DISTINCT FROM p_input_hash
       OR v_run.logical_provider IS DISTINCT FROM p_logical_provider
       OR v_run.actor_id IS DISTINCT FROM p_actor_id
       OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM p_max_charge_usd THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;

    IF v_run.status = 'rejected' THEN
        RETURN public.analysis_v2_provider_run_json(v_run);
    END IF;
    IF v_run.status IS DISTINCT FROM 'starting' OR v_run.run_id IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_v2_provider_runs AS provider_run
    SET status = 'rejected',
        terminalized_at = v_now,
        actual_usage_usd = 0,
        usage_reconciled_at = v_now,
        updated_at = v_now
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    RETURNING provider_run.* INTO v_run;

    RETURN public.analysis_v2_provider_run_json(v_run);
END;
$_$;


--
-- Name: reject_commerce_append_only_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_commerce_append_only_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    RAISE EXCEPTION USING
        MESSAGE = 'COMMERCE_CANONICAL_APPEND_ONLY',
        ERRCODE = 'P0001';
END;
$$;


--
-- Name: reject_concurrent_analysis_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_concurrent_analysis_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM public.analysis_requests AS analysis_request
        WHERE analysis_request.user_id = NEW.user_id
          AND analysis_request.status IN ('pending', 'processing')
    ) THEN
        RAISE EXCEPTION 'ANALYSIS_ALREADY_IN_PROGRESS';
    END IF;
    RETURN NEW;
END;
$$;


