-- Name: reject_earlybird_checkout_reconciliation_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_earlybird_checkout_reconciliation_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    RAISE EXCEPTION USING
        MESSAGE = 'EARLYBIRD_RECONCILIATION_AUDIT_IMMUTABLE',
        ERRCODE = 'P0001';
END;
$$;


--
-- Name: release_analysis_beta_preflight_prepare_claim(uuid, uuid, integer, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_beta_preflight_prepare_claim(p_preflight_id uuid, p_user_id uuid, p_prepare_generation integer, p_prepare_token uuid, p_claim_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE v_gate_enabled BOOLEAN; v_grant public.analysis_beta_access_grants%ROWTYPE;
DECLARE v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    SELECT gate_row.enabled INTO v_gate_enabled
    FROM public.analysis_beta_runtime_gate AS gate_row
    WHERE gate_row.singleton=TRUE FOR SHARE;
    PERFORM 1 FROM public.users AS owner_user
    WHERE owner_user.id=p_user_id FOR KEY SHARE;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id=p_preflight_id AND preflight.user_id=p_user_id
    FOR UPDATE;
    SELECT grant_row.* INTO v_grant
    FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id=p_user_id FOR SHARE;
    IF v_preflight.id IS NULL
       OR v_preflight.beta_entry_provenance IS DISTINCT FROM 'betatest_service_v1'
       OR v_preflight.beta_prepare_generation IS DISTINCT FROM p_prepare_generation
       OR v_preflight.beta_prepare_token IS DISTINCT FROM p_prepare_token
       OR v_preflight.beta_prepare_state IS DISTINCT FROM 'preparing'
       OR v_preflight.beta_prepare_lease_token IS DISTINCT FROM p_claim_token
       OR v_preflight.analysis_entry_channel IS DISTINCT FROM 'standard' THEN
        RETURN FALSE;
    END IF;
    UPDATE public.analysis_preflights AS preflight
    SET beta_prepare_state='reserved',
        beta_prepare_lease_token=NULL,
        beta_prepare_lease_expires_at=NULL,
        updated_at=pg_catalog.clock_timestamp()
    WHERE preflight.id=v_preflight.id;
    RETURN TRUE;
END;
$$;


--
-- Name: release_analysis_order_audit_bundle(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_order_audit_bundle(p_request_id uuid, p_lease_token uuid, p_error_code text DEFAULT NULL::text, p_retryable boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_status TEXT;
    v_next TIMESTAMPTZ;
BEGIN
    IF p_request_id IS NULL OR p_lease_token IS NULL
       OR p_error_code IS NOT NULL
          AND (p_error_code !~ '^[A-Z0-9_:-]{1,96}$') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_ORDER_AUDIT_INVALID_RELEASE', ERRCODE = 'P0001';
    END IF;

    v_status := CASE WHEN p_retryable THEN 'queued' ELSE 'failed' END;
    v_next := CASE WHEN p_retryable
        THEN pg_catalog.clock_timestamp() + INTERVAL '30 seconds'
        ELSE pg_catalog.clock_timestamp() + INTERVAL '5 minutes'
    END;
    UPDATE public.analysis_order_audit_assembly_queue
       SET status = v_status,
           next_attempt_at = v_next,
           lease_token = NULL,
           lease_expires_at = NULL,
           last_error_code = p_error_code,
           last_error_at = CASE WHEN p_error_code IS NULL THEN NULL ELSE pg_catalog.clock_timestamp() END,
           updated_at = pg_catalog.clock_timestamp()
     WHERE request_id = p_request_id
       AND lease_token = p_lease_token;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'requestId', p_request_id::TEXT,
        'status', v_status,
        'nextAttemptAt', v_next
    );
END;
$_$;


--
-- Name: release_analysis_preflight_claim(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_preflight_claim(p_preflight_id uuid, p_claim_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL OR p_claim_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_CLAIM_INPUT', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    IF v_preflight.status <> 'processing'
       OR v_preflight.lease_token IS DISTINCT FROM p_claim_token
       OR v_preflight.expires_at <= v_now THEN
        RETURN FALSE;
    END IF;

    UPDATE public.analysis_preflights
    SET status = 'pending',
        lease_token = NULL,
        lease_expires_at = NULL,
        updated_at = v_now
    WHERE id = v_preflight.id;
    RETURN TRUE;
END;
$$;


--
-- Name: release_analysis_provider_admission(text, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_provider_admission(p_admission_id text, p_lease_token uuid, p_fence bigint, p_release_reason text DEFAULT 'terminal'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_lease public.analysis_provider_admission_leases%ROWTYPE;
    v_ledger_state TEXT;
BEGIN
    IF p_admission_id IS NULL OR p_admission_id !~ '^[0-9a-f]{64}$'
       OR p_lease_token IS NULL OR p_fence IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;
    IF p_release_reason NOT IN ('terminal', 'prestart_rejected') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT lease.* INTO v_lease
    FROM public.analysis_provider_admission_leases AS lease
    WHERE lease.admission_id = p_admission_id
      AND lease.lease_token = p_lease_token
      AND lease.fence = p_fence
    FOR UPDATE;
    IF NOT FOUND OR v_lease.state = 'recovery_required' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF v_lease.state = 'released' THEN
        RETURN pg_catalog.jsonb_build_object('released', TRUE);
    END IF;
    -- A Gemini slot may have been reused after this admission expired. Its
    -- provider claim token is distinct from the job token and must still fence
    -- release; otherwise a stale worker could free a newer slot's admission.
    IF v_lease.logical_provider = 'gemini' THEN
        v_ledger_state := public.analysis_provider_admission_ledger_state(v_lease);
        IF v_ledger_state IN ('identity_conflict', 'fenced_out', 'missing') THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
    ELSIF v_lease.logical_provider = 'apify' THEN
        -- The provider-run row is reserved immediately after admission and
        -- must be terminal before a live lease can be released.  A missing
        -- row is the one safe exception: the mandatory sequencing proves no
        -- external provider start was possible.
        v_ledger_state := public.analysis_provider_admission_ledger_state(v_lease);
        IF v_ledger_state = 'identity_conflict' THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        IF v_ledger_state NOT IN ('terminal', 'missing') THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_CLAIM_CONFLICT', ERRCODE = 'P0001';
        END IF;
    END IF;
    UPDATE public.analysis_provider_admission_leases AS lease
    SET state = 'released', released_at = v_now, expires_at = v_now,
        release_reason = p_release_reason,
        updated_at = v_now
    WHERE lease.admission_id = p_admission_id;
    RETURN pg_catalog.jsonb_build_object('released', TRUE);
END;
$_$;


--
-- Name: release_analysis_request_lease(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_request_lease(p_request_id uuid, p_lease_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    affected_rows INTEGER;
BEGIN
    UPDATE public.analysis_requests AS analysis_request
    SET processing_lease_token = NULL,
        processing_lease_expires_at = NULL
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version IS DISTINCT FROM 'v2'
      AND analysis_request.processing_lease_token = p_lease_token;

    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    RETURN affected_rows = 1;
END;
$$;


--
-- Name: release_analysis_revenue_cost_operation_provider_v2(uuid, text, uuid, text, text, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_revenue_cost_operation_provider_v2(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_source_kind text, p_source_operation_key text, p_source_attempt smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE; v_request public.analysis_requests%ROWTYPE; v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_provider public.analysis_v2_provider_runs%ROWTYPE; v_parent public.analysis_revenue_run_ledgers%ROWTYPE; v_child public.analysis_revenue_cost_operations%ROWTYPE;
    v_entitlement public.analysis_v2_test_entitlement_consumptions%ROWTYPE; v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_runner_plan TEXT; v_operation_kind TEXT; v_source_hash TEXT; v_owner_hash TEXT; v_expected_krw INTEGER; v_now TIMESTAMPTZ;
    v_active_reserved INTEGER; v_settled_economic INTEGER; v_settled_billed INTEGER;
BEGIN
    IF p_request_id IS NULL OR p_job_claim_token IS NULL OR p_job_key IS NULL OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_job_input_hash !~ '^[a-f0-9]{64}$' OR p_source_kind IS NULL OR p_source_kind NOT IN ('provider_run','ai_attempt')
       OR p_source_operation_key IS NULL OR p_source_attempt IS DISTINCT FROM 0 THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    IF p_source_kind = 'ai_attempt' THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT * INTO v_preflight FROM public.analysis_preflights WHERE consumed_request_id=p_request_id FOR UPDATE;
    SELECT * INTO v_request FROM public.analysis_requests WHERE id=p_request_id FOR UPDATE;
    SELECT * INTO v_entitlement FROM public.analysis_v2_test_entitlement_consumptions WHERE request_id=p_request_id;
    SELECT * INTO v_policy FROM public.analysis_v2_provider_execution_policies WHERE request_id=p_request_id;
    SELECT runner_plan INTO v_runner_plan FROM public.load_e2e_test_runner_v1(v_request.user_id);
    IF v_preflight.id IS NULL OR v_request.id IS NULL OR v_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_request.pipeline_version IS DISTINCT FROM 'v2' OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot NOT IN ('basic','standard') OR v_request.status NOT IN ('pending','processing')
       OR v_preflight.status IS DISTINCT FROM 'consumed' OR v_preflight.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_preflight.admission_generation IS DISTINCT FROM 1 OR v_preflight.admission_status IS DISTINCT FROM 'ready'
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_preflight.admission_entitlement_jti_hash IS DISTINCT FROM v_request.test_entitlement_jti_hash
       OR v_preflight.user_id IS DISTINCT FROM v_request.user_id
       OR pg_catalog.lower(v_preflight.target_instagram_id) IS DISTINCT FROM pg_catalog.lower(v_request.target_instagram_id)
       OR v_entitlement.request_id IS NULL OR v_entitlement.preflight_id IS DISTINCT FROM v_preflight.id OR v_entitlement.user_id IS DISTINCT FROM v_request.user_id
       OR v_entitlement.selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot OR v_entitlement.entitlement_jti_hash IS DISTINCT FROM v_request.test_entitlement_jti_hash
       OR v_policy.request_id IS NULL OR v_policy.mode IS DISTINCT FROM 'test_operation_split' OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR v_policy.entitlement_jti_hash IS DISTINCT FROM v_entitlement.entitlement_jti_hash
       OR pg_catalog.lower(v_policy.target_instagram_id) IS DISTINCT FROM pg_catalog.lower(v_preflight.target_instagram_id)
       OR v_runner_plan IS DISTINCT FROM v_request.selected_plan_id_snapshot THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT * INTO v_job FROM public.analysis_pipeline_jobs WHERE request_id=p_request_id AND job_key=p_job_key FOR UPDATE;
    v_now:=pg_catalog.clock_timestamp();
    IF v_job.request_id IS NULL OR v_job.status IS DISTINCT FROM 'processing' OR v_job.lease_token IS DISTINCT FROM p_job_claim_token
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at<=v_now THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT * INTO v_provider FROM public.analysis_v2_provider_runs WHERE request_id=p_request_id AND job_key=p_job_key AND operation_key=p_source_operation_key FOR UPDATE;
    IF v_provider.request_id IS NULL OR v_provider.input_hash !~ '^[a-f0-9]{64}$' OR v_provider.job_claim_token IS DISTINCT FROM p_job_claim_token THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    v_operation_kind := CASE
        WHEN p_source_operation_key ~ '^target-profile:[a-f0-9]{64}$' THEN 'target_profile'
        WHEN p_source_operation_key ~ '^(profile-fallback|profile-repair):[a-f0-9]{64}$' THEN 'detail_profile'
        WHEN p_source_operation_key ~ '^relationship-followers:[a-f0-9]{64}$' THEN 'relationship_followers'
        WHEN p_source_operation_key ~ '^relationship-following:[a-f0-9]{64}$' THEN 'relationship_following'
        WHEN p_source_operation_key ~ '^(target-likers|target-comments|candidate-likers):[a-f0-9]{64}$' THEN 'detail_interaction'
        ELSE NULL END;
    IF v_operation_kind IS NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    v_source_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_source_operation_key,'UTF8'),'sha256'),'hex');
    v_owner_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to('revenue-cost/live-provider-owner/v2:' || p_request_id::TEXT || ':' || p_job_key || ':' || p_source_operation_key || ':' || v_provider.input_hash,'UTF8'),'sha256'),'hex');
    v_expected_krw:=public.analysis_revenue_cost_ceil_krw(v_provider.max_charge_usd);
    SELECT * INTO v_parent FROM public.analysis_revenue_run_ledgers WHERE request_id=p_request_id FOR UPDATE;
    IF v_parent.request_id IS NULL OR v_parent.preflight_id IS DISTINCT FROM v_preflight.id OR v_parent.user_id IS DISTINCT FROM v_request.user_id
       OR v_parent.plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot OR v_parent.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_parent.target_username_hmac IS DISTINCT FROM v_preflight.target_input_hash OR v_parent.preflight_refreshed_at IS DISTINCT FROM v_preflight.admission_refreshed_at
       OR v_parent.request_started_at IS DISTINCT FROM v_request.created_at OR v_parent.pricing_snapshot_version IS DISTINCT FROM 'revenue-e2e-cost-2026-08-10-v1'
       OR v_parent.buffered_fx_krw_per_usd IS DISTINCT FROM 1450
       OR v_parent.cost_cap_krw IS DISTINCT FROM (CASE WHEN v_request.selected_plan_id_snapshot='basic' THEN 1808 ELSE 3634 END)
       OR v_parent.margin_target_krw IS DISTINCT FROM (CASE WHEN v_request.selected_plan_id_snapshot='basic' THEN 904 ELSE 1817 END)
       OR v_parent.status NOT IN ('running','manual_review') THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT COALESCE(pg_catalog.sum(CASE WHEN status IN ('reserved','started') THEN reserved_krw ELSE 0 END),0)::INTEGER,
           COALESCE(pg_catalog.sum(CASE WHEN status='settled' THEN economic_actual_krw ELSE 0 END),0)::INTEGER,
           COALESCE(pg_catalog.sum(CASE WHEN status='settled' THEN billed_actual_krw ELSE 0 END),0)::INTEGER
      INTO v_active_reserved,v_settled_economic,v_settled_billed FROM public.analysis_revenue_cost_operations WHERE request_id=p_request_id;
    IF v_parent.reserved_cost_krw IS DISTINCT FROM v_active_reserved OR v_parent.economic_actual_krw IS DISTINCT FROM v_settled_economic
       OR v_parent.actual_cost_krw IS DISTINCT FROM v_settled_economic OR v_parent.billed_actual_krw IS DISTINCT FROM v_settled_billed THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT * INTO v_child FROM public.analysis_revenue_cost_operations WHERE request_id=p_request_id AND owner_kind='provider_run' AND source_job_key=p_job_key
      AND source_operation_key_hash=v_source_hash AND source_attempt=0 FOR UPDATE;
    IF NOT FOUND OR v_child.owner_key_hash IS DISTINCT FROM v_owner_hash OR v_child.attempt IS DISTINCT FROM 1 OR v_child.operation_kind IS DISTINCT FROM v_operation_kind OR v_child.units IS DISTINCT FROM 1
       OR v_child.selected_manifest_scope_hash IS NOT NULL OR v_child.estimated_economic_usd IS DISTINCT FROM v_provider.max_charge_usd OR v_child.reserved_krw IS DISTINCT FROM v_expected_krw
       OR v_child.denial_reason IS NOT NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    IF v_child.status='released' AND v_child.started_at IS NULL AND v_child.economic_actual_usd IS NULL AND v_child.billed_actual_usd IS NULL
       AND v_child.economic_actual_krw IS NULL AND v_child.billed_actual_krw IS NULL AND v_child.denial_reason IS NULL
       AND ((v_provider.status='starting' AND v_provider.run_id IS NULL AND v_provider.run_started_at IS NULL
             AND v_provider.terminalized_at IS NULL AND v_provider.actual_usage_usd IS NULL AND v_provider.usage_reconciled_at IS NULL
             AND v_child.terminal_at IS NOT DISTINCT FROM GREATEST(v_provider.reserved_at,v_child.created_at))
            OR (v_provider.status='rejected' AND v_provider.run_id IS NULL AND v_provider.run_started_at IS NULL
             AND v_provider.actual_usage_usd IS NOT DISTINCT FROM 0 AND v_provider.terminalized_at IS NOT NULL AND v_provider.usage_reconciled_at IS NOT NULL
             AND v_child.terminal_at IS NOT DISTINCT FROM v_provider.usage_reconciled_at)) THEN
        RETURN pg_catalog.jsonb_build_object('disposition','released','created',FALSE,'replayed',TRUE,'operationId',v_child.id);
    END IF;
    IF v_child.status='ambiguous' AND v_child.started_at IS NOT NULL AND v_child.terminal_at IS NOT NULL
       AND ((v_provider.status='starting' AND v_provider.run_id IS NULL AND v_provider.run_started_at IS NULL
             AND v_provider.terminalized_at IS NULL AND v_provider.actual_usage_usd IS NULL AND v_provider.usage_reconciled_at IS NULL)
            OR (v_provider.status='running' AND v_provider.run_id IS NOT NULL AND v_provider.run_started_at IS NOT NULL
             AND v_provider.terminalized_at IS NULL AND v_provider.actual_usage_usd IS NULL AND v_provider.usage_reconciled_at IS NULL)) THEN
        RETURN pg_catalog.jsonb_build_object('disposition','ambiguous','created',FALSE,'replayed',TRUE,'operationId',v_child.id,'reason','ambiguous_external_call');
    END IF;
    IF v_child.status NOT IN ('reserved','started') OR v_child.economic_actual_usd IS NOT NULL OR v_child.billed_actual_usd IS NOT NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    -- Unlike a still-starting source, a rejected source is definitive provider
    -- truth: no run crossed the external boundary.  It may release a local
    -- started marker without manufacturing an ambiguity.
    IF v_provider.status='rejected' AND v_provider.run_id IS NULL AND v_provider.run_started_at IS NULL
       AND v_provider.actual_usage_usd IS NOT DISTINCT FROM 0 AND v_provider.terminalized_at IS NOT NULL AND v_provider.usage_reconciled_at IS NOT NULL THEN
        IF v_child.terminal_at IS NOT NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
        UPDATE public.analysis_revenue_cost_operations SET status='released',started_at=NULL,terminal_at=v_provider.usage_reconciled_at WHERE id=v_child.id;
        UPDATE public.analysis_revenue_run_ledgers SET reserved_cost_krw=reserved_cost_krw-v_child.reserved_krw WHERE request_id=p_request_id;
        RETURN pg_catalog.jsonb_build_object('disposition','released','created',TRUE,'replayed',FALSE,'operationId',v_child.id);
    END IF;
    IF v_child.status='started' THEN
        -- The runtime marks this immediately before its provider call.  Even a
        -- still-starting provider row cannot prove that the call never crossed
        -- the external boundary, so it must remain recoverable ambiguity.
        UPDATE public.analysis_revenue_cost_operations SET status='ambiguous',terminal_at=v_now WHERE id=v_child.id;
        UPDATE public.analysis_revenue_run_ledgers SET reserved_cost_krw=reserved_cost_krw-v_child.reserved_krw,status='manual_review',manual_review_reason=CASE
            WHEN manual_review_reason IN ('cost_overrun','cost_denied') THEN manual_review_reason
            ELSE 'ambiguous_external_call' END WHERE request_id=p_request_id;
        RETURN pg_catalog.jsonb_build_object('disposition','ambiguous','created',TRUE,'replayed',FALSE,'operationId',v_child.id,'reason','ambiguous_external_call');
    END IF;
    IF v_provider.status = 'starting' AND v_provider.run_id IS NULL AND v_provider.run_started_at IS NULL
       AND v_provider.terminalized_at IS NULL AND v_provider.actual_usage_usd IS NULL AND v_provider.usage_reconciled_at IS NULL THEN
        IF v_child.status<>'reserved' OR v_child.started_at IS NOT NULL OR v_child.terminal_at IS NOT NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
        UPDATE public.analysis_revenue_cost_operations SET status='released',terminal_at=GREATEST(v_provider.reserved_at,v_child.created_at) WHERE id=v_child.id;
        UPDATE public.analysis_revenue_run_ledgers SET reserved_cost_krw=reserved_cost_krw-v_child.reserved_krw WHERE request_id=p_request_id;
        RETURN pg_catalog.jsonb_build_object('disposition','released','created',TRUE,'replayed',FALSE,'operationId',v_child.id);
    END IF;
    IF v_provider.run_id IS NULL OR v_provider.run_started_at IS NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    UPDATE public.analysis_revenue_cost_operations SET status='ambiguous',started_at=COALESCE(started_at,v_provider.run_started_at),terminal_at=v_now WHERE id=v_child.id;
    UPDATE public.analysis_revenue_run_ledgers SET reserved_cost_krw=reserved_cost_krw-CASE WHEN v_child.status IN ('reserved','started') THEN v_child.reserved_krw ELSE 0 END,status='manual_review',manual_review_reason=CASE
        WHEN manual_review_reason IN ('cost_overrun','cost_denied') THEN manual_review_reason
        ELSE 'ambiguous_external_call' END WHERE request_id=p_request_id;
    RETURN pg_catalog.jsonb_build_object('disposition','ambiguous','created',TRUE,'replayed',FALSE,'operationId',v_child.id,'reason','ambiguous_external_call');
END; $_$;


--
-- Name: release_analysis_revenue_cost_operation_v1(uuid, text, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_revenue_cost_operation_v1(p_request_id uuid, p_owner_kind text, p_owner_key_hash text, p_attempt smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_NOT_READY'; END; $$;


--
-- Name: release_analysis_revenue_cost_operation_v2(uuid, text, uuid, text, text, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_revenue_cost_operation_v2(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_source_kind text, p_source_operation_key text, p_source_attempt smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_ai public.analysis_v2_ai_attempts%ROWTYPE;
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_child public.analysis_revenue_cost_operations%ROWTYPE;
    v_mapping JSONB;
    v_source_hash TEXT;
    v_owner_hash TEXT;
    v_expected_usd NUMERIC;
    v_expected_krw INTEGER;
    v_now TIMESTAMPTZ;
    v_terminal_at TIMESTAMPTZ;
BEGIN
    IF p_source_kind='provider_run' THEN
        RETURN public.release_analysis_revenue_cost_operation_provider_v2(
            p_request_id,p_job_key,p_job_claim_token,p_job_input_hash,
            p_source_kind,p_source_operation_key,p_source_attempt
        );
    END IF;
    IF p_source_kind IS DISTINCT FROM 'ai_attempt' OR p_source_attempt NOT BETWEEN 1 AND 4 THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    PERFORM public.analysis_revenue_ai_cost_assert_lineage_v1(p_request_id,p_job_key,p_job_claim_token,p_job_input_hash,TRUE);
    SELECT * INTO v_ai FROM public.analysis_v2_ai_attempts
      WHERE request_id=p_request_id AND job_key=p_job_key AND operation_key=p_source_operation_key
        AND attempt=p_source_attempt FOR UPDATE;
    IF v_ai.request_id IS NULL OR v_ai.job_claim_token IS DISTINCT FROM p_job_claim_token
       OR v_ai.retry_count IS DISTINCT FROM p_source_attempt-1 THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF v_ai.status <> 'reserved' THEN
        -- A terminal source has more authority than a local pre-dispatch
        -- cleanup.  Delegate to terminal settlement; it can release only a
        -- proven no-bill outcome or record manual-review ambiguity.
        RETURN public.settle_analysis_revenue_cost_operation_v2(
            p_request_id,p_job_key,'ai_attempt',p_source_operation_key,p_source_attempt
        );
    END IF;
    v_expected_usd:=public.analysis_revenue_ai_cost_max_usd_v1(v_ai.model_name,v_ai.location,v_ai.stage,v_ai.thinking_level,v_ai.media_count,v_ai.media_resolution,v_ai.prompt_version,v_ai.schema_version,v_ai.max_output_tokens);
    v_mapping:=public.analysis_revenue_ai_cost_operation_mapping_v1(p_request_id,p_job_key,p_job_input_hash,(SELECT selected_plan_id_snapshot FROM public.analysis_requests WHERE id=p_request_id),p_source_operation_key,p_source_attempt,v_ai.stage);
    v_source_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_source_operation_key,'UTF8'),'sha256'),'hex');
    v_owner_hash:=public.analysis_revenue_ai_cost_owner_hash_v1(p_request_id,p_job_key,p_source_operation_key,p_source_attempt,v_ai.reservation_token,v_ai.model_name,v_ai.location,v_ai.stage,v_ai.thinking_level,v_ai.media_count,v_ai.media_resolution,v_ai.prompt_version,v_ai.schema_version,v_ai.max_output_tokens,v_ai.retry_count);
    v_expected_krw:=public.analysis_revenue_cost_ceil_krw(v_expected_usd);
    PERFORM public.analysis_revenue_ai_cost_assert_parent_v1(p_request_id);
    SELECT * INTO v_parent FROM public.analysis_revenue_run_ledgers WHERE request_id=p_request_id FOR UPDATE;
    PERFORM public.analysis_revenue_ai_cost_assert_aggregates_v1(p_request_id);
    SELECT * INTO v_child FROM public.analysis_revenue_cost_operations
      WHERE request_id=p_request_id AND owner_kind='ai_attempt' AND source_job_key=p_job_key
        AND source_operation_key_hash=v_source_hash AND source_attempt=p_source_attempt FOR UPDATE;
    IF v_child.id IS NULL OR v_child.owner_key_hash IS DISTINCT FROM v_owner_hash
       OR v_child.attempt IS DISTINCT FROM p_source_attempt OR v_child.operation_kind IS DISTINCT FROM (v_mapping->>'operation_kind')
       OR v_child.selected_manifest_scope_hash IS DISTINCT FROM (v_mapping->>'selected_manifest_scope_hash')
       OR v_child.units IS DISTINCT FROM 1 OR v_child.estimated_economic_usd IS DISTINCT FROM v_expected_usd
       OR v_child.reserved_krw IS DISTINCT FROM v_expected_krw OR v_child.denial_reason IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    v_terminal_at:=GREATEST(v_ai.created_at,v_child.created_at);
    IF v_child.status='released' AND v_child.started_at IS NULL
       AND v_child.terminal_at IS NOT DISTINCT FROM v_terminal_at
       AND v_child.economic_actual_usd IS NULL AND v_child.billed_actual_usd IS NULL
       AND v_child.economic_actual_krw IS NULL AND v_child.billed_actual_krw IS NULL THEN
        RETURN pg_catalog.jsonb_build_object('disposition','released','created',FALSE,'replayed',TRUE,'operationId',v_child.id);
    END IF;
    IF v_child.status='ambiguous' AND v_child.started_at IS NOT NULL AND v_child.terminal_at IS NOT NULL THEN
        RETURN pg_catalog.jsonb_build_object('disposition','ambiguous','created',FALSE,'replayed',TRUE,'operationId',v_child.id,'reason','ambiguous_external_call');
    END IF;
    IF v_parent.status IS DISTINCT FROM 'running' OR v_parent.manual_review_reason IS NOT NULL
       OR v_child.status NOT IN ('reserved','started') THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF v_child.status='reserved' THEN
        UPDATE public.analysis_revenue_cost_operations
           SET status='released',terminal_at=v_terminal_at WHERE id=v_child.id;
        UPDATE public.analysis_revenue_run_ledgers
           SET reserved_cost_krw=reserved_cost_krw-v_child.reserved_krw WHERE request_id=p_request_id;
        RETURN pg_catalog.jsonb_build_object('disposition','released','created',TRUE,'replayed',FALSE,'operationId',v_child.id);
    END IF;
    -- A started child is the durable mark immediately before Gemini.  A still
    -- reserved source cannot prove the call was never sent, so it is ambiguity,
    -- not an invented zero-cost release.
    v_now:=pg_catalog.clock_timestamp();
    UPDATE public.analysis_revenue_cost_operations
       SET status='ambiguous',terminal_at=v_now WHERE id=v_child.id;
    UPDATE public.analysis_revenue_run_ledgers
       SET reserved_cost_krw=reserved_cost_krw-v_child.reserved_krw,
           status='manual_review',manual_review_reason=CASE
               WHEN manual_review_reason IN ('cost_overrun','cost_denied') THEN manual_review_reason
               ELSE 'ambiguous_external_call' END
     WHERE request_id=p_request_id;
    RETURN pg_catalog.jsonb_build_object('disposition','ambiguous','created',TRUE,'replayed',FALSE,'operationId',v_child.id,'reason','ambiguous_external_call');
END;
$$;


--
-- Name: release_analysis_v2_gemini_lease(integer, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_v2_gemini_lease(p_slot integer, p_claim_token uuid, p_fence bigint) RETURNS TABLE(released boolean, lease_state text, fence bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_lease public.analysis_v2_gemini_leases%ROWTYPE;
BEGIN
    IF p_slot IS NULL OR p_slot NOT BETWEEN 1 AND 8
       OR p_claim_token IS NULL
       OR p_fence IS NULL OR p_fence < 1 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GEMINI_LEASE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT lease.* INTO v_lease
    FROM public.analysis_v2_gemini_leases AS lease
    WHERE lease.slot = p_slot
    FOR UPDATE;
    IF v_lease.state = 'leased'
       AND v_lease.lease_claim_token = p_claim_token
       AND v_lease.fence = p_fence THEN
        UPDATE public.analysis_v2_gemini_leases AS lease
        SET state = 'available',
            request_id = NULL,
            job_key = NULL,
            attempt = NULL,
            lease_claim_token = NULL,
            acquired_at = NULL,
            expires_at = NULL,
            quarantined_at = NULL,
            updated_at = v_now
        WHERE lease.slot = p_slot
        RETURNING lease.* INTO v_lease;
        RETURN QUERY SELECT TRUE, v_lease.state::TEXT, v_lease.fence;
        RETURN;
    END IF;
    RETURN QUERY SELECT FALSE, v_lease.state::TEXT, v_lease.fence;
END;
$$;


--
-- Name: release_analysis_v2_gemini_lease_v2(integer, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_v2_gemini_lease_v2(p_slot integer, p_claim_token uuid, p_fence bigint, p_operation_key text) RETURNS TABLE(released boolean, lease_state text, fence bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_lease public.analysis_v2_gemini_leases%ROWTYPE;
BEGIN
    SELECT lease.* INTO v_lease
    FROM public.analysis_v2_gemini_leases AS lease
    WHERE lease.slot = p_slot
    FOR UPDATE;
    IF v_lease.state IN ('leased', 'quarantined')
       AND v_lease.lease_claim_token = p_claim_token
       AND v_lease.fence = p_fence
       AND v_lease.operation_key = p_operation_key THEN
        UPDATE public.analysis_v2_gemini_leases AS lease
        SET state = 'available',
            request_id = NULL,
            job_key = NULL,
            operation_key = NULL,
            stage = NULL,
            attempt = NULL,
            lease_claim_token = NULL,
            acquired_at = NULL,
            expires_at = NULL,
            quarantined_at = NULL,
            updated_at = v_now
        WHERE lease.slot = p_slot
        RETURNING lease.* INTO v_lease;
        RETURN QUERY SELECT TRUE, v_lease.state::TEXT, v_lease.fence;
        RETURN;
    END IF;
    RETURN QUERY SELECT FALSE, v_lease.state::TEXT, v_lease.fence;
END;
$$;


--
-- Name: release_analysis_v2_job_claim(uuid, text, uuid, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_v2_job_claim(p_request_id uuid, p_job_key text, p_claim_token uuid, p_error_code text, p_retryable boolean, p_max_attempts integer DEFAULT 7) RETURNS TABLE(released boolean, job_status text, attempt_count integer, request_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL OR p_claim_token IS NULL OR p_retryable IS NULL
       OR p_max_attempts IS NULL OR p_max_attempts NOT BETWEEN 1 AND 20
       OR (p_error_code IS NOT NULL
           AND p_error_code !~ '^[A-Z][A-Z0-9_]{0,63}$')
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_INVALID_JOB_RELEASE_INPUT', ERRCODE = 'P0001';
    END IF;

    PERFORM 1 FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id FOR UPDATE;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    IF v_job.status <> 'processing' THEN
        RETURN QUERY SELECT
            FALSE, v_job.status::TEXT, v_job.attempt_count, v_request.status::TEXT;
        RETURN;
    END IF;
    IF v_job.lease_token <> p_claim_token OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_JOB_LEASE_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF NOT p_retryable OR v_job.attempt_count >= p_max_attempts THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_TERMINAL_FAILURE_CLEANUP_REQUIRED',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_pipeline_jobs AS job
    SET status = 'pending',
        lease_token = NULL,
        lease_expires_at = NULL,
        last_error_code = COALESCE(p_error_code, 'JOB_RETRYABLE_FAILURE'),
        last_error_at = v_now,
        updated_at = v_now
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    RETURNING job.* INTO v_job;

    RETURN QUERY SELECT
        TRUE, v_job.status::TEXT, v_job.attempt_count, v_request.status::TEXT;
END;
$_$;


--
-- Name: release_analysis_v2_preflight_admission(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_v2_preflight_admission(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    UPDATE public.analysis_preflights AS preflight
    SET admission_status = 'pending',
        admission_claim_token = NULL,
        admission_lease_expires_at = NULL,
        updated_at = v_now
    WHERE preflight.id = p_preflight_id
      AND preflight.admission_generation = p_admission_generation
      AND preflight.admission_status = 'processing'
      AND preflight.admission_claim_token = p_claim_token;
    RETURN FOUND;
END;
$$;


--
-- Name: release_analysis_v2_preflight_admission_dispatch(uuid, uuid, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_v2_preflight_admission_dispatch(p_preflight_id uuid, p_user_id uuid, p_admission_generation integer, p_dispatch_generation integer, p_dispatch_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_admission_generation IS NULL
       OR p_admission_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 100
       OR p_dispatch_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_FRESH_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET admission_dispatch_state = 'idle',
        admission_dispatch_token = NULL,
        admission_dispatch_reserved_at = NULL,
        admission_dispatched_at = NULL,
        updated_at = v_now
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
      AND preflight.admission_generation = p_admission_generation
      AND preflight.admission_status = 'pending'
      AND preflight.admission_dispatch_generation = p_dispatch_generation
      AND preflight.admission_dispatch_state = 'reserved'
      AND preflight.admission_dispatch_token = p_dispatch_token;
    RETURN FOUND;
END;
$$;


--
-- Name: release_analysis_v2_preflight_admission_rearmed_dispatch_v2(uuid, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_analysis_v2_preflight_admission_rearmed_dispatch_v2(p_preflight_id uuid, p_admission_generation integer, p_dispatch_generation integer, p_dispatch_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
BEGIN
    UPDATE public.analysis_preflights AS preflight
    SET admission_dispatch_state = 'idle',
        admission_dispatch_token = NULL,
        admission_dispatch_reserved_at = NULL,
        admission_dispatched_at = NULL,
        updated_at = v_now
    WHERE preflight.id = p_preflight_id
      AND preflight.admission_status = 'pending'
      AND preflight.admission_dispatch_workload_role = 'paid'
      AND preflight.admission_dispatch_contract_version = 2
      AND preflight.admission_generation = p_admission_generation
      AND preflight.admission_dispatch_state = 'reserved'
      AND preflight.admission_dispatch_generation = p_dispatch_generation
      AND preflight.admission_dispatch_token = p_dispatch_token;
    RETURN FOUND;
END;
$$;


--
-- Name: release_anonymous_profile_cache_lock(character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_anonymous_profile_cache_lock(p_target_input_hash character varying, p_lease_token uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
    DELETE FROM public.analysis_anonymous_profile_cache_locks
    WHERE target_input_hash = p_target_input_hash
      AND lease_token = p_lease_token
    RETURNING TRUE;
$$;


--
-- Name: release_precheckout_blite_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_precheckout_blite_v1(p_preflight_id uuid, p_lease_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    DELETE FROM public.precheckout_blite_cache
     WHERE preflight_id = p_preflight_id
       AND state = 'pending'
       AND lease_token = p_lease_token;
    RETURN FOUND;
END;
$$;


--
-- Name: renew_analysis_provider_admission(text, uuid, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.renew_analysis_provider_admission(p_admission_id text, p_lease_token uuid, p_fence bigint, p_lease_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_expires TIMESTAMPTZ;
    v_lease public.analysis_provider_admission_leases%ROWTYPE;
BEGIN
    IF p_admission_id IS NULL OR p_admission_id !~ '^[0-9a-f]{64}$'
       OR p_lease_token IS NULL OR p_fence IS NULL
       OR p_lease_seconds NOT BETWEEN 10 AND 900 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT lease.* INTO v_lease
    FROM public.analysis_provider_admission_leases AS lease
    WHERE lease.admission_id = p_admission_id
      AND lease.state = 'leased'
      AND lease.lease_token = p_lease_token
      AND lease.fence = p_fence
      AND lease.expires_at > v_now
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    -- Renewal is an ownership operation, not merely a lease-token heartbeat.
    -- Re-run the immutable lineage and live-owner checks so a leaked timer
    -- cannot extend an admission after the preflight/job/Gemini claim rotates
    -- or expires.  Takeover/adoption remains the only path that can install a
    -- new claim and fence after a durable running-ledger proof.
    PERFORM public.assert_analysis_provider_admission_claim(
        v_lease.workload_role,
        v_lease.logical_provider,
        v_lease.credential_slot,
        v_lease.request_id,
        v_lease.job_key,
        v_lease.operation_key,
        v_lease.job_claim_token,
        v_lease.claim_token,
        v_lease.provider_fence,
        v_now
    );
    v_expires := v_now + (p_lease_seconds || ' seconds')::INTERVAL;
    UPDATE public.analysis_provider_admission_leases AS lease
    SET expires_at = v_expires, updated_at = v_now
    WHERE lease.admission_id = p_admission_id;
    RETURN pg_catalog.jsonb_build_object(
        'renewed', TRUE, 'fence', v_lease.fence, 'expiresAt', v_expires
    );
END;
$_$;


--
-- Name: renew_analysis_v2_gemini_lease(integer, uuid, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.renew_analysis_v2_gemini_lease(p_slot integer, p_claim_token uuid, p_fence bigint, p_lease_seconds integer DEFAULT 240) RETURNS TABLE(renewed boolean, lease_state text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_lease public.analysis_v2_gemini_leases%ROWTYPE;
BEGIN
    IF p_slot IS NULL OR p_slot NOT BETWEEN 1 AND 8
       OR p_claim_token IS NULL
       OR p_fence IS NULL OR p_fence < 1
       OR p_lease_seconds IS NULL OR p_lease_seconds NOT BETWEEN 225 AND 300 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GEMINI_LEASE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT lease.* INTO v_lease
    FROM public.analysis_v2_gemini_leases AS lease
    WHERE lease.slot = p_slot
    FOR UPDATE;
    IF v_lease.state = 'leased'
       AND v_lease.lease_claim_token = p_claim_token
       AND v_lease.fence = p_fence
       AND v_lease.expires_at > v_now THEN
        UPDATE public.analysis_v2_gemini_leases AS lease
        SET expires_at = v_now + p_lease_seconds * INTERVAL '1 second',
            updated_at = v_now
        WHERE lease.slot = p_slot
        RETURNING lease.* INTO v_lease;
        RETURN QUERY SELECT TRUE, v_lease.state::TEXT, v_lease.expires_at;
        RETURN;
    END IF;
    IF v_lease.state = 'leased'
       AND v_lease.lease_claim_token = p_claim_token
       AND v_lease.fence = p_fence
       AND v_lease.expires_at <= v_now THEN
        UPDATE public.analysis_v2_gemini_leases AS lease
        SET state = 'quarantined',
            quarantined_at = v_now,
            updated_at = v_now
        WHERE lease.slot = p_slot
        RETURNING lease.* INTO v_lease;
    END IF;
    RETURN QUERY SELECT FALSE, v_lease.state::TEXT, v_lease.expires_at;
END;
$$;


--
-- Name: renew_analysis_v2_gemini_lease_v2(integer, uuid, bigint, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.renew_analysis_v2_gemini_lease_v2(p_slot integer, p_claim_token uuid, p_fence bigint, p_operation_key text, p_lease_seconds integer DEFAULT 240) RETURNS TABLE(renewed boolean, lease_state text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_lease public.analysis_v2_gemini_leases%ROWTYPE;
BEGIN
    IF p_slot IS NULL OR p_slot NOT BETWEEN 1 AND 8
       OR p_claim_token IS NULL
       OR p_fence IS NULL OR p_fence < 1
       OR NOT public.analysis_v2_valid_ai_operation_key(p_operation_key)
       OR p_lease_seconds IS NULL OR p_lease_seconds NOT BETWEEN 225 AND 300 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GEMINI_LEASE_INVALID',
            ERRCODE = 'P0001';
    END IF;
    SELECT lease.* INTO v_lease
    FROM public.analysis_v2_gemini_leases AS lease
    WHERE lease.slot = p_slot
    FOR UPDATE;
    IF v_lease.state = 'leased'
       AND v_lease.lease_claim_token = p_claim_token
       AND v_lease.fence = p_fence
       AND v_lease.operation_key = p_operation_key
       AND v_lease.expires_at > v_now THEN
        UPDATE public.analysis_v2_gemini_leases AS lease
        SET expires_at = v_now + p_lease_seconds * INTERVAL '1 second',
            updated_at = v_now
        WHERE lease.slot = p_slot
        RETURNING lease.* INTO v_lease;
        RETURN QUERY SELECT TRUE, v_lease.state::TEXT, v_lease.expires_at;
        RETURN;
    END IF;
    RETURN QUERY SELECT FALSE, v_lease.state::TEXT, v_lease.expires_at;
END;
$$;


--
-- Name: repair_analysis_v2_duplicate_overviews(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_analysis_v2_duplicate_overviews(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_updated_count INTEGER;
    v_unique_count INTEGER;
BEGIN
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_OVERVIEW_REPAIR_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2';
    IF NOT FOUND
       OR v_request.status <> 'completed'
       OR v_request.plan_access_mode_snapshot <> 'test_entitlement'
       OR v_request.completed_at IS NULL
       OR v_request.completed_at < v_now - INTERVAL '24 hours' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_OVERVIEW_REPAIR_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    WITH duplicates AS (
        SELECT female.one_line_overview
        FROM public.analysis_v2_female_results AS female
        WHERE female.request_id = p_request_id
        GROUP BY female.one_line_overview
        HAVING pg_catalog.count(*) > 1
    ),
    candidates AS (
        SELECT
            female.candidate_id,
            CASE
                WHEN female.one_line_overview LIKE
                    '% · ' || female.instagram_id
                    || ' 계정은 위험도 %점으로 판독됐어요.'
                THEN pg_catalog.split_part(
                    female.one_line_overview, ' · ', 1
                )
                ELSE female.one_line_overview
            END AS base_overview
        FROM public.analysis_v2_female_results AS female
        LEFT JOIN duplicates
          ON duplicates.one_line_overview = female.one_line_overview
        WHERE female.request_id = p_request_id
          AND (
            duplicates.one_line_overview IS NOT NULL
            OR female.one_line_overview LIKE
                '% · ' || female.instagram_id
                || ' 계정은 위험도 %점으로 판독됐어요.'
          )
    )
    UPDATE public.analysis_v2_female_results AS female
    SET one_line_overview =
        pg_catalog.left(candidates.base_overview, 105)
        || ' · ' || COALESCE(
            NULLIF(
                pg_catalog.regexp_replace(
                    female.instagram_id, '[0-9]', '', 'g'
                ),
                ''
            ),
            '해당'
        )
        || ' 계정은 '
        || CASE female.risk_band
            WHEN 'normal' THEN '일반'
            WHEN 'caution' THEN '주의'
            WHEN 'high_risk' THEN '고위험'
        END
        || ' 단계로 판독됐어요.'
    FROM candidates
    WHERE female.request_id = p_request_id
      AND female.candidate_id = candidates.candidate_id;
    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF EXISTS (
        SELECT 1
        FROM public.analysis_v2_female_results AS female
        WHERE female.request_id = p_request_id
        GROUP BY female.one_line_overview
        HAVING pg_catalog.count(*) > 1
    ) OR EXISTS (
        SELECT 1
        FROM public.analysis_v2_female_results AS female
        WHERE female.request_id = p_request_id
          AND female.one_line_overview ~ '[[:digit:]@]'
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_OVERVIEW_REPAIR_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.count(DISTINCT female.one_line_overview)::INTEGER
    INTO v_unique_count
    FROM public.analysis_v2_female_results AS female
    WHERE female.request_id = p_request_id;

    RETURN pg_catalog.jsonb_build_object(
        'updatedCount', v_updated_count,
        'uniqueCount', v_unique_count
    );
END;
$$;


--
-- Name: request_analysis_v2_provider_run_cleanup(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_analysis_v2_provider_run_cleanup(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_error_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_intent public.analysis_v2_provider_cleanup_intents%ROWTYPE;
BEGIN
    IF p_request_id IS NULL OR p_job_key IS NULL
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_error_code IS NULL OR p_error_code !~ '^[A-Z][A-Z0-9_]{2,63}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_INVALID', ERRCODE = 'P0001';
    END IF;

    -- Preserve the terminal-capable preflight -> request -> job -> intent lock order.
    PERFORM 1 FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    IF v_request.id IS NULL OR v_request.status NOT IN ('pending', 'processing')
       OR v_job.request_id IS NULL OR v_job.status <> 'processing'
       OR v_job.input_hash IS DISTINCT FROM p_job_input_hash
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT cleanup_intent.* INTO v_intent
    FROM public.analysis_v2_provider_cleanup_intents AS cleanup_intent
    WHERE cleanup_intent.request_id = p_request_id FOR UPDATE;
    IF FOUND THEN
        IF v_intent.failed_job_key IS DISTINCT FROM p_job_key
           OR v_intent.failed_job_input_hash IS DISTINCT FROM p_job_input_hash
           OR v_intent.error_code IS DISTINCT FROM p_error_code THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_INTENT_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        IF v_intent.completed_at IS NOT NULL THEN
            IF p_job_key IS DISTINCT FROM 'track:target-evidence:collect'
               OR p_error_code IS DISTINCT FROM 'SCRAPING_PROVIDER_START_REJECTED_ERROR'
               OR NOT EXISTS (
                    SELECT 1
                    FROM public.earlybird_orders AS earlybird_order
                    JOIN public.earlybird_fulfillments AS fulfillment
                      ON fulfillment.order_id = earlybird_order.id
                    
JOIN LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, preflight_id UUID, provider_operation_key TEXT, provider_input_hash VARCHAR(64), provider_run_id_hash VARCHAR(32), expected_manual_review_at TIMESTAMPTZ, expected_admission_refreshed_at TIMESTAMPTZ, old_order_followers_count INTEGER, old_order_following_count INTEGER, old_preflight_followers_count INTEGER, old_preflight_following_count INTEGER, new_witness_followers_count INTEGER, new_witness_following_count INTEGER, old_snapshot_recorded_at TIMESTAMPTZ, new_witness_recorded_at TIMESTAMPTZ, recovery_reason TEXT, followers_absolute_delta INTEGER, following_absolute_delta INTEGER, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_concierge_snapshot_conflict_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','preflight_id','provider_operation_key','provider_input_hash','provider_run_id_hash','expected_manual_review_at','expected_admission_refreshed_at','old_order_followers_count','old_order_following_count','old_preflight_followers_count','old_preflight_following_count','new_witness_followers_count','new_witness_following_count','old_snapshot_recorded_at','new_witness_recorded_at','recovery_reason','followers_absolute_delta','following_absolute_delta','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.preflight_id IS NOT NULL AND decoded.provider_operation_key IS NOT NULL AND decoded.provider_input_hash IS NOT NULL AND decoded.provider_run_id_hash IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.expected_admission_refreshed_at IS NOT NULL AND decoded.old_order_followers_count IS NOT NULL AND decoded.old_order_following_count IS NOT NULL AND decoded.old_preflight_followers_count IS NOT NULL AND decoded.old_preflight_following_count IS NOT NULL AND decoded.new_witness_followers_count IS NOT NULL AND decoded.new_witness_following_count IS NOT NULL AND decoded.old_snapshot_recorded_at IS NOT NULL AND decoded.new_witness_recorded_at IS NOT NULL AND decoded.recovery_reason IS NOT NULL AND decoded.followers_absolute_delta IS NOT NULL AND decoded.following_absolute_delta IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
                      ON recovery.order_id = earlybird_order.id
                     AND recovery.preflight_id = earlybird_order.preflight_id
                    WHERE earlybird_order.result_request_id = p_request_id
                      AND earlybird_order.preflight_id = v_request.preflight_id
                      AND earlybird_order.plan_id = 'basic'
                      AND earlybird_order.paid_at >= TIMESTAMPTZ '2026-08-12 18:07:00+09'
                      AND earlybird_order.paid_at < TIMESTAMPTZ '2026-08-12 18:08:00+09'
                      AND earlybird_order.status = 'analysis_in_progress'
                      AND fulfillment.request_id = p_request_id
                      AND fulfillment.status = 'analysis_in_progress'
                      AND recovery.expected_manual_review_at IS NOT NULL
                      AND recovery.expected_admission_refreshed_at IS NOT NULL
               )
               OR EXISTS (
                    SELECT 1
                    FROM public.earlybird_webhook_events AS refund_event
                    WHERE refund_event.payment_id = (
                        SELECT earlybird_order.payment_id
                        FROM public.earlybird_orders AS earlybird_order
                        WHERE earlybird_order.result_request_id = p_request_id
                        LIMIT 1
                    )
                      AND refund_event.event_type = 'payment.refunded'
               )
               OR EXISTS (
                    SELECT 1 FROM public.analysis_results AS result
                    WHERE result.request_id = p_request_id
               )
               OR EXISTS (
                    SELECT 1 FROM public.analysis_v2_result_summaries AS summary
                    WHERE summary.request_id = p_request_id
               )
               OR EXISTS (
                    SELECT 1 FROM public.analysis_v2_target_evidence_manifests AS manifest
                    WHERE manifest.request_id = p_request_id
               )
               OR NOT EXISTS (
                    SELECT 1
                    FROM public.analysis_v2_provider_runs AS provider_run
                    WHERE provider_run.request_id = p_request_id
                      AND provider_run.job_key = p_job_key
                      AND provider_run.operation_key LIKE 'target-comments:%'
                      AND provider_run.status = 'rejected'
               ) THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_INTENT_CONFLICT',
                    ERRCODE = 'P0001';
            END IF;
            UPDATE public.analysis_v2_provider_cleanup_intents AS cleanup_intent
            SET failed_claim_token = p_claim_token,
                completed_at = NULL
            WHERE cleanup_intent.request_id = p_request_id
              AND cleanup_intent.completed_at IS NOT NULL;
            RETURN TRUE;
        END IF;
        UPDATE public.analysis_v2_provider_cleanup_intents AS cleanup_intent
        SET failed_claim_token = p_claim_token
        WHERE cleanup_intent.request_id = p_request_id;
        RETURN TRUE;
    END IF;

    INSERT INTO public.analysis_v2_provider_cleanup_intents (
        request_id, failed_job_key, failed_job_input_hash,
        failed_claim_token, error_code
    ) VALUES (
        p_request_id, p_job_key, p_job_input_hash,
        p_claim_token, p_error_code
    );
    RETURN TRUE;
END;
$_$;


--
-- Name: reserve_analysis_apify_free_provider_slot(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_apify_free_provider_slot(p_preflight_id uuid, p_max_charge_usd numeric) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_snapshot public.analysis_apify_credit_snapshots%ROWTYPE;
    v_slot TEXT;
    v_capacity NUMERIC;
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_lock_count INTEGER := 0;
BEGIN
    IF p_preflight_id IS NULL
       OR p_max_charge_usd IS DISTINCT FROM 0.002600000000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_APIFY_FREE_POOL_CAPACITY_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.beta_entry_provenance IS NOT NULL
       OR v_preflight.analysis_entry_channel = 'betatest' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_APIFY_FREE_POOL_CAPACITY_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;

    PERFORM public.analysis_beta_pool_lock();
    FOR v_snapshot IN
        SELECT snapshot.*
        FROM public.analysis_apify_credit_snapshots AS snapshot
        WHERE public.analysis_beta_valid_apify_credential_slot(snapshot.credential_slot)
        ORDER BY CASE snapshot.credential_slot
            WHEN 'primary' THEN 1 WHEN 'tertiary' THEN 2
            WHEN 'quaternary' THEN 3 WHEN 'quinary' THEN 4
            WHEN 'senary' THEN 5 WHEN 'septenary' THEN 6
            WHEN 'octonary' THEN 7 WHEN 'nonary' THEN 8 WHEN 'tenth' THEN 9
        END
        FOR UPDATE
    LOOP
        v_lock_count := v_lock_count + 1;
    END LOOP;

    SELECT candidate.credential_slot, candidate.effective_capacity_usd
    INTO v_slot, v_capacity
    FROM (
        SELECT capacity.credential_slot,
               capacity.effective_capacity_usd
                 - COALESCE(provider_reservation.reserved_usd, 0::NUMERIC)
                   AS effective_capacity_usd,
               snapshot.observed_at
        FROM public.analysis_beta_pool_effective_capacity_snapshot() AS capacity
        JOIN public.analysis_apify_credit_snapshots AS snapshot
          ON snapshot.credential_slot = capacity.credential_slot
        LEFT JOIN LATERAL (
            SELECT pg_catalog.sum(CASE
                WHEN provider_run.status IN ('starting', 'running')
                    THEN provider_run.max_charge_usd
                WHEN provider_run.status IN ('succeeded', 'failed', 'aborted', 'timed_out')
                     AND (
                         provider_run.usage_reconciled_at IS NULL
                         OR snapshot.observed_at < provider_run.usage_reconciled_at
                     )
                    THEN COALESCE(provider_run.actual_usage_usd, provider_run.max_charge_usd)
                ELSE 0::NUMERIC
            END) AS reserved_usd
            FROM public.analysis_preflight_provider_runs AS provider_run
            JOIN public.analysis_preflights AS owner_preflight
              ON owner_preflight.id = provider_run.preflight_id
            WHERE provider_run.credential_slot = capacity.credential_slot
              AND owner_preflight.beta_entry_provenance IS NULL
              AND owner_preflight.analysis_entry_channel IS DISTINCT FROM 'betatest'
        ) AS provider_reservation ON TRUE
        WHERE snapshot.health_state = 'healthy'
          AND snapshot.monthly_limit_usd IS NOT NULL
          AND snapshot.monthly_usage_usd IS NOT NULL
          AND snapshot.billing_cycle_start_at IS NOT NULL
          AND snapshot.billing_cycle_end_at IS NOT NULL
          AND snapshot.observed_at IS NOT NULL
          AND snapshot.billing_cycle_start_at <= v_now
          AND snapshot.billing_cycle_end_at > v_now
          AND snapshot.observed_at >= v_now - INTERVAL '5 minutes'
          AND snapshot.observed_at <= v_now + INTERVAL '1 minute'
          AND snapshot.manually_excluded IS NOT TRUE
          AND capacity.effective_capacity_usd
                - COALESCE(provider_reservation.reserved_usd, 0::NUMERIC)
                >= p_max_charge_usd
    ) AS candidate
    ORDER BY candidate.effective_capacity_usd - p_max_charge_usd,
        CASE candidate.credential_slot
            WHEN 'primary' THEN 1 WHEN 'tertiary' THEN 2
            WHEN 'quaternary' THEN 3 WHEN 'quinary' THEN 4
            WHEN 'senary' THEN 5 WHEN 'septenary' THEN 6
            WHEN 'octonary' THEN 7 WHEN 'nonary' THEN 8 WHEN 'tenth' THEN 9
        END
    LIMIT 1;

    IF v_lock_count <> 9 OR v_slot IS NULL OR v_capacity < p_max_charge_usd THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_APIFY_FREE_POOL_CAPACITY_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;
    RETURN v_slot;
END;
$$;


--
-- Name: reserve_analysis_preflight_provider_run(uuid, uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_preflight_provider_run(p_preflight_id uuid, p_claim_token uuid, p_input_hash text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_slot TEXT := p_credential_slot;
    v_existing public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_credential_slot IS NULL THEN
        -- Serialize the read-before-select with the allocator. Without this
        -- preflight lock, two NULL-slot callers could both observe no row,
        -- then the second would conflict against the first chosen slot.
        PERFORM 1
        FROM public.analysis_preflights AS preflight
        WHERE preflight.id = p_preflight_id
        FOR UPDATE;
        SELECT provider_run.* INTO v_existing
        FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.preflight_id = p_preflight_id
          AND provider_run.operation_key = 'target-profile-fallback'
        FOR UPDATE;
        IF FOUND THEN
            v_slot := v_existing.credential_slot;
        ELSE
            v_slot := public.reserve_analysis_apify_free_provider_slot(
                p_preflight_id, p_max_charge_usd
            );
        END IF;
    END IF;
    IF v_slot IS NULL
       OR NOT public.analysis_beta_valid_apify_credential_slot(v_slot) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_PREFLIGHT_PROVIDER_RUN_SLOT_MISMATCH', ERRCODE = 'P0001';
    END IF;
    RETURN public.reserve_analysis_preflight_provider_run_fixed_20260904(
        p_preflight_id, p_claim_token, p_input_hash, v_slot, p_max_charge_usd
    );
END;
$$;


--
-- Name: reserve_analysis_preflight_provider_run_fixed_20260904(uuid, uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_preflight_provider_run_fixed_20260904(p_preflight_id uuid, p_claim_token uuid, p_input_hash text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $_$
DECLARE v_now TIMESTAMPTZ; v_user_hint UUID; v_gate_enabled BOOLEAN;
DECLARE v_grant public.analysis_beta_access_grants%ROWTYPE;
DECLARE v_preflight public.analysis_preflights%ROWTYPE;
DECLARE v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
DECLARE v_target_reservation public.analysis_beta_pool_reservations%ROWTYPE;
DECLARE v_existing public.analysis_preflight_provider_runs%ROWTYPE; v_spent NUMERIC;
BEGIN
    IF p_preflight_id IS NULL OR p_claim_token IS NULL OR p_input_hash!~'^[0-9a-f]{64}$'
       OR p_max_charge_usd IS DISTINCT FROM 0.002600000000 THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID', ERRCODE='P0001'; END IF;
    SELECT preflight.user_id INTO v_user_hint FROM public.analysis_preflights AS preflight WHERE preflight.id=p_preflight_id;
    SELECT gate_row.enabled INTO v_gate_enabled FROM public.analysis_beta_runtime_gate AS gate_row WHERE gate_row.singleton=TRUE FOR SHARE;
    PERFORM 1 FROM public.users AS owner_user WHERE owner_user.id=v_user_hint FOR KEY SHARE;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight WHERE preflight.id=p_preflight_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND', ERRCODE='P0001'; END IF;
    v_now:=pg_catalog.clock_timestamp();
    IF v_preflight.expires_at<=v_now OR NOT ((v_preflight.status='processing' AND v_preflight.lease_token IS NOT DISTINCT FROM p_claim_token AND v_preflight.lease_expires_at>v_now) OR (v_preflight.status='ready' AND v_preflight.consumed_request_id IS NULL AND v_preflight.admission_status='processing' AND v_preflight.admission_claim_token IS NOT DISTINCT FROM p_claim_token AND v_preflight.admission_lease_expires_at>v_now)) THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH', ERRCODE='P0001'; END IF;
    IF v_preflight.beta_entry_provenance IS NOT NULL OR v_preflight.analysis_entry_channel='betatest' THEN
        SELECT allocation.* INTO v_allocation FROM public.analysis_beta_pool_allocations AS allocation WHERE allocation.preflight_id=p_preflight_id AND allocation.lifecycle_state='preflight_held' FOR UPDATE;
        SELECT reservation.* INTO v_target_reservation FROM public.analysis_beta_pool_reservations AS reservation WHERE reservation.allocation_id=v_allocation.id AND reservation.operation_family='target-profile' FOR UPDATE;
        IF NOT FOUND OR NOT public.analysis_beta_valid_apify_credential_slot(p_credential_slot) OR v_target_reservation.credential_slot IS DISTINCT FROM p_credential_slot THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_PREFLIGHT_PROVIDER_RUN_SLOT_MISMATCH', ERRCODE='P0001'; END IF;
    ELSIF NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot) THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID', ERRCODE='P0001'; END IF;
    SELECT provider_run.* INTO v_existing FROM public.analysis_preflight_provider_runs AS provider_run WHERE provider_run.preflight_id=p_preflight_id AND provider_run.operation_key='target-profile-fallback' FOR UPDATE;
    v_now:=pg_catalog.clock_timestamp();
    IF v_preflight.expires_at<=v_now OR NOT (
        (v_preflight.status='processing'
            AND v_preflight.lease_token IS NOT DISTINCT FROM p_claim_token
            AND v_preflight.lease_expires_at>v_now)
        OR (v_preflight.status='ready'
            AND v_preflight.consumed_request_id IS NULL
            AND v_preflight.admission_status='processing'
            AND v_preflight.admission_claim_token IS NOT DISTINCT FROM p_claim_token
            AND v_preflight.admission_lease_expires_at>v_now)
    ) THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH', ERRCODE='P0001'; END IF;
    IF FOUND THEN
        IF v_existing.input_hash IS DISTINCT FROM p_input_hash OR v_existing.logical_provider IS DISTINCT FROM 'apify' OR v_existing.actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper' OR v_existing.credential_slot IS DISTINCT FROM p_credential_slot OR v_existing.max_charge_usd IS DISTINCT FROM p_max_charge_usd THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_IDENTITY_CONFLICT', ERRCODE='P0001'; END IF;
        RETURN pg_catalog.jsonb_build_object('created',FALSE,'run',public.analysis_preflight_provider_run_json(v_existing));
    END IF;
    IF v_preflight.beta_entry_provenance IS NOT NULL OR v_preflight.analysis_entry_channel='betatest' THEN
        SELECT grant_row.* INTO v_grant FROM public.analysis_beta_access_grants AS grant_row WHERE grant_row.user_id=v_user_hint FOR SHARE;
        v_now:=pg_catalog.clock_timestamp();
        IF v_preflight.expires_at<=v_now
           OR NOT ((v_preflight.status='processing'
                AND v_preflight.lease_token IS NOT DISTINCT FROM p_claim_token
                AND v_preflight.lease_expires_at>v_now)
             OR (v_preflight.status='ready'
                AND v_preflight.consumed_request_id IS NULL
                AND v_preflight.admission_status='processing'
                AND v_preflight.admission_claim_token IS NOT DISTINCT FROM p_claim_token
                AND v_preflight.admission_lease_expires_at>v_now)) THEN
            RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH', ERRCODE='P0001';
        END IF;
        IF v_gate_enabled IS DISTINCT FROM TRUE OR v_grant.user_id IS NULL
           OR v_grant.enabled IS DISTINCT FROM TRUE
           OR (v_grant.expires_at IS NOT NULL AND (
                NOT pg_catalog.isfinite(v_grant.expires_at)
                OR v_grant.expires_at<=v_now
           )) THEN
            RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_RUNTIME_DISABLED', ERRCODE='P0001';
        END IF;
        PERFORM 1 FROM public.analysis_preflight_provider_runs AS provider_run WHERE provider_run.preflight_id=p_preflight_id FOR UPDATE;
        SELECT COALESCE(pg_catalog.sum(provider_run.max_charge_usd),0::NUMERIC) INTO v_spent FROM public.analysis_preflight_provider_runs AS provider_run WHERE provider_run.preflight_id=p_preflight_id AND provider_run.operation_key IS DISTINCT FROM 'target-profile-fallback';
        IF v_spent+p_max_charge_usd>v_target_reservation.reserved_usd THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_PREFLIGHT_PROVIDER_RUN_BUDGET_EXCEEDED', ERRCODE='P0001'; END IF;
    END IF;
    v_now:=pg_catalog.clock_timestamp();
    IF v_preflight.expires_at<=v_now OR NOT (
        (v_preflight.status='processing'
            AND v_preflight.lease_token IS NOT DISTINCT FROM p_claim_token
            AND v_preflight.lease_expires_at>v_now)
        OR (v_preflight.status='ready'
            AND v_preflight.consumed_request_id IS NULL
            AND v_preflight.admission_status='processing'
            AND v_preflight.admission_claim_token IS NOT DISTINCT FROM p_claim_token
            AND v_preflight.admission_lease_expires_at>v_now)
    ) THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH', ERRCODE='P0001'; END IF;
    IF (v_preflight.beta_entry_provenance IS NOT NULL OR v_preflight.analysis_entry_channel='betatest')
       AND (v_gate_enabled IS DISTINCT FROM TRUE OR v_grant.user_id IS NULL
            OR v_grant.enabled IS DISTINCT FROM TRUE
            OR (v_grant.expires_at IS NOT NULL AND (
                NOT pg_catalog.isfinite(v_grant.expires_at)
                OR v_grant.expires_at<=v_now
            ))) THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_RUNTIME_DISABLED', ERRCODE='P0001'; END IF;
    INSERT INTO public.analysis_preflight_provider_runs(preflight_id,input_hash,credential_slot,max_charge_usd) VALUES(p_preflight_id,p_input_hash,p_credential_slot,p_max_charge_usd) RETURNING * INTO v_existing;
    RETURN pg_catalog.jsonb_build_object('created',TRUE,'run',public.analysis_preflight_provider_run_json(v_existing));
END;
$_$;


--
-- Name: reserve_analysis_provider_run(uuid, uuid, text, text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_provider_run(p_request_id uuid, p_user_id uuid, p_expected_step text, p_operation_key text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
BEGIN
    IF p_request_id IS NULL
       OR p_user_id IS NULL
       OR p_expected_step IS NULL
       OR p_operation_key IS NULL
       OR p_operation_key !~ '^(profile:target|profiles:(0|[1-9][0-9]{0,6})|relationship:(followers|following)|interaction:(target_likers|target_comments|candidate_likers):(0|[1-9][0-9]{0,6}))$'
       OR NOT (
           (p_expected_step = 'collect' AND p_operation_key ~ '^(profile:target|relationship:)')
           OR (p_expected_step = 'profiles' AND p_operation_key ~ '^profiles:')
           OR (p_expected_step = 'interactions' AND p_operation_key ~ '^interaction:')
       )
       OR p_logical_provider IS NULL
       OR p_logical_provider NOT IN ('apify', 'coderx')
       OR p_actor_id IS NULL
       OR p_actor_id !~ '^[A-Za-z0-9][A-Za-z0-9._~/-]{2,199}$'
       OR p_credential_slot IS NULL
       OR p_credential_slot NOT IN ('primary', 'secondary')
       OR p_max_charge_usd IS NULL
       OR p_max_charge_usd::TEXT IN ('NaN', 'Infinity', '-Infinity')
       OR p_max_charge_usd < 0
       OR p_max_charge_usd > 100000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PROVIDER_RUN_INVALID',
            ERRCODE = '22023';
    END IF;

    PERFORM 1
    FROM public.analysis_requests
    WHERE id = p_request_id
      AND user_id = p_user_id
      AND status IN ('pending', 'processing')
      AND COALESCE(current_step, 'pending') = p_expected_step
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.analysis_provider_runs
        WHERE request_id = p_request_id
          AND operation_key = p_operation_key
    ) THEN
        RETURN FALSE;
    END IF;

    INSERT INTO public.analysis_provider_runs (
        request_id,
        operation_key,
        logical_provider,
        actor_id,
        credential_slot,
        max_charge_usd,
        status
    ) VALUES (
        p_request_id,
        p_operation_key,
        p_logical_provider,
        p_actor_id,
        p_credential_slot,
        p_max_charge_usd,
        'starting'
    );
    RETURN TRUE;
END;
$_$;


--
-- Name: reserve_analysis_revenue_cost_operation_provider_v2(uuid, text, uuid, text, text, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_revenue_cost_operation_provider_v2(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_source_kind text, p_source_operation_key text, p_source_attempt smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_entitlement public.analysis_v2_test_entitlement_consumptions%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_provider public.analysis_v2_provider_runs%ROWTYPE;
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_child public.analysis_revenue_cost_operations%ROWTYPE;
    v_runner_plan TEXT; v_source_hash TEXT; v_owner_hash TEXT; v_expected_krw INTEGER;
    v_operation_kind TEXT; v_now TIMESTAMPTZ;
    v_active_reserved INTEGER; v_settled_economic INTEGER; v_settled_billed INTEGER;
BEGIN
    IF p_request_id IS NULL OR p_job_claim_token IS NULL OR p_job_key IS NULL
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$' OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_source_kind IS NULL OR p_source_kind NOT IN ('provider_run','ai_attempt') OR p_source_operation_key IS NULL
       OR p_source_attempt IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    -- This private provider implementation is reachable only through the
    -- provider dispatch wrapper below.
    IF p_source_kind = 'ai_attempt' THEN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE'; END IF;

    -- Canonical live order: consumed preflight -> request -> exact job -> exact
    -- provider/AI source -> parent -> exact child. Entitlement/policy are read as
    -- immutable request lineage between request and job without taking a new lock.
    SELECT * INTO v_preflight FROM public.analysis_preflights WHERE consumed_request_id = p_request_id FOR UPDATE;
    SELECT * INTO v_request FROM public.analysis_requests WHERE id = p_request_id FOR UPDATE;
    SELECT * INTO v_entitlement FROM public.analysis_v2_test_entitlement_consumptions WHERE request_id = p_request_id;
    SELECT * INTO v_policy FROM public.analysis_v2_provider_execution_policies WHERE request_id = p_request_id;
    SELECT runner_plan INTO v_runner_plan FROM public.load_e2e_test_runner_v1(v_request.user_id);
    IF v_preflight.id IS NULL OR v_request.id IS NULL OR v_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_entitlement.request_id IS NULL OR v_policy.request_id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2' OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot NOT IN ('basic','standard')
       OR v_request.status IS NULL OR v_request.status NOT IN ('pending','processing')
       OR v_preflight.status IS DISTINCT FROM 'consumed' OR v_preflight.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_preflight.admission_generation IS DISTINCT FROM 1 OR v_preflight.admission_status IS DISTINCT FROM 'ready'
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_preflight.admission_entitlement_jti_hash IS DISTINCT FROM v_request.test_entitlement_jti_hash
       OR v_preflight.user_id IS DISTINCT FROM v_request.user_id
       OR pg_catalog.lower(v_preflight.target_instagram_id) IS DISTINCT FROM pg_catalog.lower(v_request.target_instagram_id)
       OR v_entitlement.preflight_id IS DISTINCT FROM v_preflight.id OR v_entitlement.user_id IS DISTINCT FROM v_request.user_id
       OR v_entitlement.selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_entitlement.entitlement_jti_hash IS DISTINCT FROM v_request.test_entitlement_jti_hash
       OR v_policy.mode IS DISTINCT FROM 'test_operation_split' OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR v_policy.entitlement_jti_hash IS DISTINCT FROM v_entitlement.entitlement_jti_hash
       OR pg_catalog.lower(v_policy.target_instagram_id) IS DISTINCT FROM pg_catalog.lower(v_preflight.target_instagram_id)
       OR v_runner_plan IS DISTINCT FROM v_request.selected_plan_id_snapshot THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    SELECT * INTO v_job FROM public.analysis_pipeline_jobs
      WHERE request_id = p_request_id AND job_key = p_job_key FOR UPDATE;
    -- This must be after the job-row lock; transaction-start/current_timestamp
    -- can otherwise accept a lease that expired while waiting for that lock.
    v_now := pg_catalog.clock_timestamp();
    IF v_job.request_id IS NULL OR v_job.status IS DISTINCT FROM 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_job_claim_token OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now OR v_job.input_hash IS DISTINCT FROM p_job_input_hash THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;

    IF p_source_attempt IS DISTINCT FROM 0 THEN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT * INTO v_provider FROM public.analysis_v2_provider_runs
      WHERE request_id = p_request_id AND job_key = p_job_key AND operation_key = p_source_operation_key FOR UPDATE;
    IF v_provider.request_id IS NULL OR v_provider.status IS DISTINCT FROM 'starting'
       OR v_provider.input_hash !~ '^[a-f0-9]{64}$'
       OR v_provider.job_claim_token IS DISTINCT FROM p_job_claim_token THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    v_operation_kind := CASE
        WHEN p_source_operation_key ~ '^target-profile:[a-f0-9]{64}$' THEN 'target_profile'
        WHEN p_source_operation_key ~ '^(profile-fallback|profile-repair):[a-f0-9]{64}$' THEN 'detail_profile'
        WHEN p_source_operation_key ~ '^relationship-followers:[a-f0-9]{64}$' THEN 'relationship_followers'
        WHEN p_source_operation_key ~ '^relationship-following:[a-f0-9]{64}$' THEN 'relationship_following'
        WHEN p_source_operation_key ~ '^(target-likers|target-comments|candidate-likers):[a-f0-9]{64}$' THEN 'detail_interaction'
        ELSE NULL END;
    IF v_operation_kind IS NULL THEN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE'; END IF;

    v_source_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_source_operation_key, 'UTF8'), 'sha256'), 'hex');
    v_owner_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
        'revenue-cost/live-provider-owner/v2:' || p_request_id::TEXT || ':' || p_job_key || ':' || p_source_operation_key || ':' || v_provider.input_hash,
        'UTF8'), 'sha256'), 'hex');
    v_expected_krw := public.analysis_revenue_cost_ceil_krw(v_provider.max_charge_usd);
    SELECT * INTO v_parent FROM public.analysis_revenue_run_ledgers WHERE request_id = p_request_id FOR UPDATE;
    IF v_parent.request_id IS NULL OR v_parent.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_parent.user_id IS DISTINCT FROM v_request.user_id OR v_parent.plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_parent.access_mode IS DISTINCT FROM 'test_entitlement' OR v_parent.target_username_hmac IS DISTINCT FROM v_preflight.target_input_hash
       OR v_parent.preflight_refreshed_at IS DISTINCT FROM v_preflight.admission_refreshed_at
       OR v_parent.request_started_at IS DISTINCT FROM v_request.created_at
       OR v_parent.pricing_snapshot_version IS DISTINCT FROM 'revenue-e2e-cost-2026-08-10-v1'
       OR v_parent.buffered_fx_krw_per_usd IS DISTINCT FROM 1450
       OR v_parent.cost_cap_krw IS DISTINCT FROM (CASE WHEN v_request.selected_plan_id_snapshot='basic' THEN 1808 ELSE 3634 END)
       OR v_parent.margin_target_krw IS DISTINCT FROM (CASE WHEN v_request.selected_plan_id_snapshot='basic' THEN 904 ELSE 1817 END) THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    SELECT
        COALESCE(pg_catalog.sum(CASE WHEN status IN ('reserved','started') THEN reserved_krw ELSE 0 END), 0)::INTEGER,
        COALESCE(pg_catalog.sum(CASE WHEN status = 'settled' THEN economic_actual_krw ELSE 0 END), 0)::INTEGER,
        COALESCE(pg_catalog.sum(CASE WHEN status = 'settled' THEN billed_actual_krw ELSE 0 END), 0)::INTEGER
    INTO v_active_reserved, v_settled_economic, v_settled_billed
    FROM public.analysis_revenue_cost_operations WHERE request_id = p_request_id;
    IF v_parent.reserved_cost_krw IS DISTINCT FROM v_active_reserved
       OR v_parent.economic_actual_krw IS DISTINCT FROM v_settled_economic
       OR v_parent.actual_cost_krw IS DISTINCT FROM v_settled_economic
       OR v_parent.billed_actual_krw IS DISTINCT FROM v_settled_billed THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    SELECT * INTO v_child FROM public.analysis_revenue_cost_operations
      WHERE request_id = p_request_id AND owner_kind = p_source_kind
        AND source_job_key = p_job_key AND source_operation_key_hash = v_source_hash AND source_attempt = p_source_attempt FOR UPDATE;
    IF FOUND THEN
        IF v_child.owner_key_hash IS DISTINCT FROM v_owner_hash OR v_child.attempt IS DISTINCT FROM 1
           OR v_child.operation_kind IS DISTINCT FROM v_operation_kind OR v_child.units IS DISTINCT FROM 1
           OR v_child.estimated_economic_usd IS DISTINCT FROM v_provider.max_charge_usd
           OR v_child.selected_manifest_scope_hash IS NOT NULL THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_DRIFT';
        END IF;
        IF v_child.status = 'denied' AND v_child.denial_reason = 'hard_cap'
           AND v_child.reserved_krw = 0 AND v_parent.status = 'manual_review'
           AND v_parent.manual_review_reason IN ('cost_denied','cost_overrun') THEN
            RETURN pg_catalog.jsonb_build_object('disposition','denied','created',FALSE,'replayed',TRUE,'operationId',v_child.id,'reason','hard_cap');
        END IF;
        IF v_child.status = 'reserved' AND v_child.reserved_krw = v_expected_krw
           AND v_child.denial_reason IS NULL AND v_child.started_at IS NULL AND v_child.terminal_at IS NULL
           AND v_parent.status = 'running' AND v_parent.manual_review_reason IS NULL THEN
            RETURN pg_catalog.jsonb_build_object('disposition','accepted','created',FALSE,'replayed',TRUE,'operationId',v_child.id);
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_DRIFT';
    END IF;
    IF v_parent.status IS DISTINCT FROM 'running' OR v_parent.manual_review_reason IS NOT NULL THEN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE'; END IF;
    IF v_parent.economic_actual_krw + v_parent.reserved_cost_krw + v_expected_krw > v_parent.cost_cap_krw THEN
        INSERT INTO public.analysis_revenue_cost_operations (
            request_id, owner_kind, owner_key_hash, attempt, operation_kind, units, selected_manifest_scope_hash,
            source_job_key, source_operation_key_hash, source_attempt, estimated_economic_usd, reserved_krw,
            status, denial_reason, terminal_at
        ) VALUES (p_request_id, 'provider_run', v_owner_hash, 1, v_operation_kind, 1, NULL,
            p_job_key, v_source_hash, p_source_attempt, v_provider.max_charge_usd, 0, 'denied', 'hard_cap', v_now)
        RETURNING * INTO v_child;
        UPDATE public.analysis_revenue_run_ledgers SET status = 'manual_review', manual_review_reason = CASE
            WHEN manual_review_reason = 'cost_overrun' THEN 'cost_overrun'
            ELSE 'cost_denied' END
          WHERE request_id = p_request_id;
        RETURN pg_catalog.jsonb_build_object('disposition','denied','created',TRUE,'replayed',FALSE,'operationId',v_child.id,'reason','hard_cap');
    END IF;
    INSERT INTO public.analysis_revenue_cost_operations (
        request_id, owner_kind, owner_key_hash, attempt, operation_kind, units, selected_manifest_scope_hash,
        source_job_key, source_operation_key_hash, source_attempt, estimated_economic_usd, reserved_krw
    ) VALUES (p_request_id, 'provider_run', v_owner_hash, 1, v_operation_kind, 1, NULL,
        p_job_key, v_source_hash, p_source_attempt, v_provider.max_charge_usd, v_expected_krw)
    RETURNING * INTO v_child;
    UPDATE public.analysis_revenue_run_ledgers SET reserved_cost_krw = reserved_cost_krw + v_expected_krw
      WHERE request_id = p_request_id;
    RETURN pg_catalog.jsonb_build_object('disposition','accepted','created',TRUE,'replayed',FALSE,'operationId',v_child.id);
END; $_$;


--
-- Name: reserve_analysis_revenue_cost_operation_v1(uuid, text, text, smallint, text, integer, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_revenue_cost_operation_v1(p_request_id uuid, p_owner_kind text, p_owner_key_hash text, p_attempt smallint, p_operation_kind text, p_units integer, p_estimated_economic_usd numeric, p_selected_manifest_scope_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_NOT_READY'; END; $$;


--
-- Name: reserve_analysis_revenue_cost_operation_v2(uuid, text, uuid, text, text, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_revenue_cost_operation_v2(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_source_kind text, p_source_operation_key text, p_source_attempt smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_ai public.analysis_v2_ai_attempts%ROWTYPE;
    v_previous public.analysis_v2_ai_attempts%ROWTYPE;
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_child public.analysis_revenue_cost_operations%ROWTYPE;
    v_previous_child public.analysis_revenue_cost_operations%ROWTYPE;
    v_mapping JSONB;
    v_previous_mapping JSONB;
    v_source_hash TEXT;
    v_owner_hash TEXT;
    v_previous_owner_hash TEXT;
    v_operation_kind TEXT;
    v_scope_hash TEXT;
    v_expected_usd NUMERIC;
    v_expected_krw INTEGER;
    v_now TIMESTAMPTZ;
BEGIN
    IF p_source_kind = 'provider_run' THEN
        RETURN public.reserve_analysis_revenue_cost_operation_provider_v2(
            p_request_id,p_job_key,p_job_claim_token,p_job_input_hash,
            p_source_kind,p_source_operation_key,p_source_attempt
        );
    END IF;
    IF p_source_kind IS DISTINCT FROM 'ai_attempt' OR p_source_attempt NOT BETWEEN 1 AND 4 THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    PERFORM public.analysis_revenue_ai_cost_assert_lineage_v1(
        p_request_id,p_job_key,p_job_claim_token,p_job_input_hash,TRUE
    );
    SELECT * INTO v_ai FROM public.analysis_v2_ai_attempts
      WHERE request_id=p_request_id AND job_key=p_job_key
        AND operation_key=p_source_operation_key AND attempt=p_source_attempt FOR UPDATE;
    IF v_ai.request_id IS NULL OR v_ai.status IS DISTINCT FROM 'reserved'
       OR v_ai.job_claim_token IS DISTINCT FROM p_job_claim_token
       OR v_ai.retry_count IS DISTINCT FROM p_source_attempt - 1
       OR v_ai.usage_metadata_status IS NOT NULL OR v_ai.usage_complete IS NOT NULL
       OR v_ai.prompt_tokens IS NOT NULL OR v_ai.completion_tokens IS NOT NULL
       OR v_ai.total_tokens IS NOT NULL OR v_ai.thinking_tokens IS NOT NULL
       OR v_ai.estimated_cost_usd IS NOT NULL OR v_ai.finish_reason IS NOT NULL
       OR v_ai.terminal_payload_hash IS NOT NULL OR v_ai.terminalized_at IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    v_expected_usd := public.analysis_revenue_ai_cost_max_usd_v1(
        v_ai.model_name,v_ai.location,v_ai.stage,v_ai.thinking_level,v_ai.media_count,
        v_ai.media_resolution,v_ai.prompt_version,v_ai.schema_version,v_ai.max_output_tokens
    );
    v_mapping := public.analysis_revenue_ai_cost_operation_mapping_v1(
        p_request_id,p_job_key,p_job_input_hash,
        (SELECT selected_plan_id_snapshot FROM public.analysis_requests WHERE id=p_request_id),
        p_source_operation_key,p_source_attempt,v_ai.stage
    );
    v_operation_kind := v_mapping->>'operation_kind';
    v_scope_hash := v_mapping->>'selected_manifest_scope_hash';
    IF v_operation_kind NOT IN ('target_profile','relationship_followers','relationship_following','stage_one_routing','stage_one_routing_retry','detail_profile','detail_media','detail_interaction','resolver')
       OR (v_scope_hash IS NOT NULL AND v_scope_hash !~ '^[a-f0-9]{64}$') THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    v_source_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_source_operation_key,'UTF8'),'sha256'),'hex');
    v_owner_hash := public.analysis_revenue_ai_cost_owner_hash_v1(
        p_request_id,p_job_key,p_source_operation_key,p_source_attempt,v_ai.reservation_token,
        v_ai.model_name,v_ai.location,v_ai.stage,v_ai.thinking_level,v_ai.media_count,
        v_ai.media_resolution,v_ai.prompt_version,v_ai.schema_version,v_ai.max_output_tokens,v_ai.retry_count
    );
    v_expected_krw := public.analysis_revenue_cost_ceil_krw(v_expected_usd);

    -- A retry cannot sidestep a potentially billable predecessor.  The V2
    -- attempt ledger proves its rate-limit shape, and this ledger proves the
    -- exact previous reserve was released before one shared parent is charged.
    IF p_source_attempt > 1 THEN
        SELECT * INTO v_previous FROM public.analysis_v2_ai_attempts
          WHERE request_id=p_request_id AND operation_key=p_source_operation_key
            AND attempt=p_source_attempt-1 FOR UPDATE;
        IF v_previous.request_id IS NULL OR v_previous.status IS DISTINCT FROM 'rate_limited'
           OR v_previous.job_key IS DISTINCT FROM p_job_key
           OR v_previous.model_name IS DISTINCT FROM v_ai.model_name
           OR v_previous.location IS DISTINCT FROM v_ai.location
           OR v_previous.stage IS DISTINCT FROM v_ai.stage
           OR v_previous.thinking_level IS DISTINCT FROM v_ai.thinking_level
           OR v_previous.media_count IS DISTINCT FROM v_ai.media_count
           OR v_previous.media_resolution IS DISTINCT FROM v_ai.media_resolution
           OR v_previous.prompt_version IS DISTINCT FROM v_ai.prompt_version
           OR v_previous.schema_version IS DISTINCT FROM v_ai.schema_version
           OR v_previous.max_output_tokens IS DISTINCT FROM v_ai.max_output_tokens
           OR v_previous.retry_count IS DISTINCT FROM p_source_attempt-2
           OR v_previous.usage_metadata_status IS DISTINCT FROM 'missing'
           OR v_previous.usage_complete IS DISTINCT FROM FALSE
           OR v_previous.prompt_tokens IS NOT NULL OR v_previous.completion_tokens IS NOT NULL
           OR v_previous.total_tokens IS NOT NULL OR v_previous.thinking_tokens IS NOT NULL
           OR v_previous.estimated_cost_usd IS NOT NULL OR v_previous.finish_reason IS NOT NULL
           OR v_previous.terminalized_at IS NULL THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
        END IF;
        v_previous_mapping := public.analysis_revenue_ai_cost_operation_mapping_v1(
            p_request_id,p_job_key,p_job_input_hash,
            (SELECT selected_plan_id_snapshot FROM public.analysis_requests WHERE id=p_request_id),
            p_source_operation_key,((p_source_attempt - 1)::SMALLINT),v_previous.stage
        );
        v_previous_owner_hash := public.analysis_revenue_ai_cost_owner_hash_v1(
            p_request_id,p_job_key,p_source_operation_key,((p_source_attempt - 1)::SMALLINT),v_previous.reservation_token,
            v_previous.model_name,v_previous.location,v_previous.stage,v_previous.thinking_level,v_previous.media_count,
            v_previous.media_resolution,v_previous.prompt_version,v_previous.schema_version,v_previous.max_output_tokens,v_previous.retry_count
        );
        SELECT * INTO v_previous_child FROM public.analysis_revenue_cost_operations
          WHERE request_id=p_request_id AND owner_kind='ai_attempt' AND source_job_key=p_job_key
            AND source_operation_key_hash=v_source_hash AND source_attempt=p_source_attempt-1 FOR UPDATE;
        IF v_previous_child.id IS NULL OR v_previous_child.owner_key_hash IS DISTINCT FROM v_previous_owner_hash
           OR v_previous_child.attempt IS DISTINCT FROM p_source_attempt-1
           OR v_previous_child.operation_kind IS DISTINCT FROM (v_previous_mapping->>'operation_kind')
           OR v_previous_child.selected_manifest_scope_hash IS DISTINCT FROM (v_previous_mapping->>'selected_manifest_scope_hash')
           OR v_previous_child.units IS DISTINCT FROM 1
           OR v_previous_child.estimated_economic_usd IS DISTINCT FROM v_expected_usd
           OR v_previous_child.reserved_krw IS DISTINCT FROM v_expected_krw
           OR v_previous_child.status IS DISTINCT FROM 'released'
           OR v_previous_child.started_at IS NOT NULL
           OR v_previous_child.terminal_at IS DISTINCT FROM v_previous.terminalized_at
           OR v_previous_child.economic_actual_usd IS NOT NULL OR v_previous_child.billed_actual_usd IS NOT NULL
           OR v_previous_child.denial_reason IS NOT NULL THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
        END IF;
    END IF;

    PERFORM public.analysis_revenue_ai_cost_assert_parent_v1(p_request_id);
    SELECT * INTO v_parent FROM public.analysis_revenue_run_ledgers WHERE request_id=p_request_id FOR UPDATE;
    PERFORM public.analysis_revenue_ai_cost_assert_aggregates_v1(p_request_id);
    SELECT * INTO v_child FROM public.analysis_revenue_cost_operations
      WHERE request_id=p_request_id AND owner_kind='ai_attempt' AND source_job_key=p_job_key
        AND source_operation_key_hash=v_source_hash AND source_attempt=p_source_attempt FOR UPDATE;
    IF v_child.id IS NOT NULL THEN
        IF v_child.owner_key_hash IS DISTINCT FROM v_owner_hash OR v_child.attempt IS DISTINCT FROM p_source_attempt
           OR v_child.operation_kind IS DISTINCT FROM v_operation_kind OR v_child.units IS DISTINCT FROM 1
           OR v_child.selected_manifest_scope_hash IS DISTINCT FROM v_scope_hash
           OR v_child.estimated_economic_usd IS DISTINCT FROM v_expected_usd
           OR v_child.reserved_krw IS DISTINCT FROM (CASE WHEN v_child.status='denied' THEN 0 ELSE v_expected_krw END) THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_DRIFT';
        END IF;
        IF v_child.status='denied' AND v_child.denial_reason='hard_cap'
           AND v_parent.status='manual_review' AND v_parent.manual_review_reason IN ('cost_denied','cost_overrun') THEN
            RETURN pg_catalog.jsonb_build_object('disposition','denied','created',FALSE,'replayed',TRUE,'operationId',v_child.id,'reason','hard_cap');
        END IF;
        IF v_child.status='reserved' AND v_child.denial_reason IS NULL
           AND v_child.started_at IS NULL AND v_child.terminal_at IS NULL
           AND v_parent.status='running' AND v_parent.manual_review_reason IS NULL THEN
            RETURN pg_catalog.jsonb_build_object('disposition','accepted','created',FALSE,'replayed',TRUE,'operationId',v_child.id);
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_DRIFT';
    END IF;
    IF v_parent.status IS DISTINCT FROM 'running' OR v_parent.manual_review_reason IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    v_now := pg_catalog.clock_timestamp();
    IF v_parent.economic_actual_krw + v_parent.reserved_cost_krw + v_expected_krw > v_parent.cost_cap_krw THEN
        INSERT INTO public.analysis_revenue_cost_operations(
            request_id,owner_kind,owner_key_hash,attempt,operation_kind,units,selected_manifest_scope_hash,
            source_job_key,source_operation_key_hash,source_attempt,estimated_economic_usd,reserved_krw,
            status,denial_reason,terminal_at
        ) VALUES (
            p_request_id,'ai_attempt',v_owner_hash,p_source_attempt,v_operation_kind,1,v_scope_hash,
            p_job_key,v_source_hash,p_source_attempt,v_expected_usd,0,'denied','hard_cap',v_now
        ) RETURNING * INTO v_child;
        UPDATE public.analysis_revenue_run_ledgers
           SET status='manual_review',manual_review_reason=CASE WHEN manual_review_reason='cost_overrun'
               THEN 'cost_overrun' ELSE 'cost_denied' END
         WHERE request_id=p_request_id;
        RETURN pg_catalog.jsonb_build_object('disposition','denied','created',TRUE,'replayed',FALSE,'operationId',v_child.id,'reason','hard_cap');
    END IF;
    INSERT INTO public.analysis_revenue_cost_operations(
        request_id,owner_kind,owner_key_hash,attempt,operation_kind,units,selected_manifest_scope_hash,
        source_job_key,source_operation_key_hash,source_attempt,estimated_economic_usd,reserved_krw
    ) VALUES (
        p_request_id,'ai_attempt',v_owner_hash,p_source_attempt,v_operation_kind,1,v_scope_hash,
        p_job_key,v_source_hash,p_source_attempt,v_expected_usd,v_expected_krw
    ) RETURNING * INTO v_child;
    UPDATE public.analysis_revenue_run_ledgers
       SET reserved_cost_krw=reserved_cost_krw+v_expected_krw WHERE request_id=p_request_id;
    RETURN pg_catalog.jsonb_build_object('disposition','accepted','created',TRUE,'replayed',FALSE,'operationId',v_child.id);
END;
$_$;


--
-- Name: reserve_analysis_revenue_resolver_capacity_v1(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_revenue_resolver_capacity_v1(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text, p_operation_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_pass public.analysis_revenue_resolver_passes%ROWTYPE;
    v_existing public.analysis_revenue_resolver_capacity_reservations%ROWTYPE;
    v_operation_hash TEXT;
    v_limit SMALLINT;
    v_reserved_count INTEGER;
BEGIN
    IF p_job_key IS DISTINCT FROM 'coordinator:join:primary-evidence'
       OR p_job_input_hash !~ '^[a-f0-9]{64}$'
       OR p_operation_key !~ '^gender-resolution:[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    -- This is the same immutable entitlement + runner + parent ledger fence
    -- used by cost reservation, before the resolver's Gemini boundary.
    PERFORM public.analysis_revenue_ai_cost_assert_lineage_v1(
        p_request_id, p_job_key, p_job_claim_token, p_job_input_hash, TRUE
    );
    PERFORM public.analysis_revenue_ai_cost_assert_parent_v1(p_request_id);
    SELECT * INTO v_parent
      FROM public.analysis_revenue_run_ledgers
     WHERE request_id = p_request_id
     FOR UPDATE;
    v_limit := CASE v_parent.plan_id WHEN 'basic' THEN 20 ELSE 40 END;
    SELECT * INTO v_pass
      FROM public.analysis_revenue_resolver_passes
     WHERE request_id = p_request_id
     FOR UPDATE;
    IF v_pass.request_id IS NULL
       OR v_pass.job_key IS DISTINCT FROM p_job_key
       OR v_pass.job_input_hash IS DISTINCT FROM p_job_input_hash
       OR v_pass.plan_id IS DISTINCT FROM v_parent.plan_id
       OR v_pass.capacity_limit IS DISTINCT FROM v_limit THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    v_operation_hash := pg_catalog.encode(
        extensions.digest(pg_catalog.convert_to(p_operation_key, 'UTF8'), 'sha256'),
        'hex'
    );
    SELECT * INTO v_existing
      FROM public.analysis_revenue_resolver_capacity_reservations
     WHERE request_id = p_request_id
       AND operation_key_hash = v_operation_hash
     FOR UPDATE;
    IF v_existing.request_id IS NOT NULL THEN
        IF v_existing.job_key IS DISTINCT FROM p_job_key
           OR v_existing.job_input_hash IS DISTINCT FROM p_job_input_hash
           OR v_existing.plan_id IS DISTINCT FROM v_parent.plan_id
           OR v_existing.capacity_limit IS DISTINCT FROM v_limit THEN
            RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_DRIFT';
        END IF;
        IF v_existing.disposition = 'accepted'
           AND v_parent.status = 'running'
           AND v_parent.manual_review_reason IS NULL THEN
            RETURN pg_catalog.jsonb_build_object(
                'disposition', 'accepted', 'created', FALSE, 'replayed', TRUE
            );
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'capacity_skipped', 'created', FALSE, 'replayed', TRUE
        );
    END IF;

    IF v_parent.status = 'running' AND v_parent.manual_review_reason IS NULL THEN
        SELECT pg_catalog.count(*)::INTEGER INTO v_reserved_count
          FROM public.analysis_revenue_resolver_capacity_reservations
         WHERE request_id = p_request_id
           AND disposition = 'accepted';
        IF v_reserved_count < v_limit THEN
            INSERT INTO public.analysis_revenue_resolver_capacity_reservations(
                request_id, operation_key_hash, job_key, job_input_hash,
                plan_id, capacity_limit, disposition
            ) VALUES (
                p_request_id, v_operation_hash, p_job_key, p_job_input_hash,
                v_parent.plan_id, v_limit, 'accepted'
            );
            RETURN pg_catalog.jsonb_build_object(
                'disposition', 'accepted', 'created', TRUE, 'replayed', FALSE
            );
        END IF;
    END IF;

    INSERT INTO public.analysis_revenue_resolver_capacity_reservations(
        request_id, operation_key_hash, job_key, job_input_hash,
        plan_id, capacity_limit, disposition
    ) VALUES (
        p_request_id, v_operation_hash, p_job_key, p_job_input_hash,
        v_parent.plan_id, v_limit, 'capacity_skipped'
    );
    RETURN pg_catalog.jsonb_build_object(
        'disposition', 'capacity_skipped', 'created', TRUE, 'replayed', FALSE
    );
END;
$_$;


--
-- Name: reserve_analysis_v2_ai_attempt(uuid, text, uuid, text, smallint, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_ai_attempt(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_attempt smallint, p_reservation_token uuid, p_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_existing public.analysis_v2_ai_attempts%ROWTYPE;
    v_previous public.analysis_v2_ai_attempts%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_claim_token IS NULL
       OR p_reservation_token IS NULL
       OR p_operation_key IS NULL
       OR p_attempt IS NULL
       OR p_metadata IS NULL
       OR NOT public.analysis_v2_valid_ai_operation_key(p_operation_key)
       OR NOT public.analysis_v2_valid_ai_reservation_metadata(p_metadata, p_attempt)
       OR NOT public.analysis_v2_ai_operation_matches_stage(
            p_operation_key,
            p_metadata->>'stage'
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND OR v_request.pipeline_version IS DISTINCT FROM 'v2' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT ai_attempt.*
    INTO v_existing
    FROM public.analysis_v2_ai_attempts AS ai_attempt
    WHERE ai_attempt.request_id = p_request_id
      AND ai_attempt.operation_key = p_operation_key
      AND ai_attempt.attempt = p_attempt
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.job_key IS DISTINCT FROM p_job_key
           OR v_existing.job_claim_token IS DISTINCT FROM p_claim_token
           OR v_existing.model_name IS DISTINCT FROM p_metadata->>'model_name'
           OR v_existing.location IS DISTINCT FROM p_metadata->>'location'
           OR v_existing.stage IS DISTINCT FROM p_metadata->>'stage'
           OR v_existing.thinking_level IS DISTINCT FROM NULLIF(p_metadata->>'thinking_level', '')
           OR v_existing.media_count IS DISTINCT FROM (p_metadata->>'media_count')::SMALLINT
           OR v_existing.media_resolution IS DISTINCT FROM NULLIF(p_metadata->>'media_resolution', '')
           OR v_existing.prompt_version IS DISTINCT FROM p_metadata->>'prompt_version'
           OR v_existing.schema_version IS DISTINCT FROM (p_metadata->>'schema_version')::SMALLINT
           OR v_existing.max_output_tokens IS DISTINCT FROM
                (p_metadata->>'max_output_tokens')::INTEGER
           OR v_existing.retry_count IS DISTINCT FROM (p_metadata->>'retry_count')::SMALLINT THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_ai_attempt_json(v_existing)
            || pg_catalog.jsonb_build_object('created', FALSE);
    END IF;

    IF v_request.status NOT IN ('pending', 'processing') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_NOT_READY',
            ERRCODE = 'P0001';
    END IF;
    IF v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_JOB_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    IF p_attempt > 1 THEN
        SELECT ai_attempt.*
        INTO v_previous
        FROM public.analysis_v2_ai_attempts AS ai_attempt
        WHERE ai_attempt.request_id = p_request_id
          AND ai_attempt.operation_key = p_operation_key
          AND ai_attempt.attempt = p_attempt - 1
        FOR UPDATE;
        IF NOT FOUND
           OR v_previous.status <> 'rate_limited'
           OR v_previous.job_key IS DISTINCT FROM p_job_key
           OR v_previous.model_name IS DISTINCT FROM p_metadata->>'model_name'
           OR v_previous.location IS DISTINCT FROM p_metadata->>'location'
           OR v_previous.stage IS DISTINCT FROM p_metadata->>'stage'
           OR v_previous.thinking_level IS DISTINCT FROM NULLIF(p_metadata->>'thinking_level', '')
           OR v_previous.media_count IS DISTINCT FROM (p_metadata->>'media_count')::SMALLINT
           OR v_previous.media_resolution IS DISTINCT FROM NULLIF(p_metadata->>'media_resolution', '')
           OR v_previous.prompt_version IS DISTINCT FROM p_metadata->>'prompt_version'
           OR v_previous.schema_version IS DISTINCT FROM (p_metadata->>'schema_version')::SMALLINT
           OR v_previous.max_output_tokens IS DISTINCT FROM
                (p_metadata->>'max_output_tokens')::INTEGER THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_AI_ATTEMPT_NOT_RETRYABLE',
                ERRCODE = 'P0001';
        END IF;
    END IF;

    INSERT INTO public.analysis_v2_ai_attempts (
        request_id,
        job_key,
        job_claim_token,
        operation_key,
        attempt,
        reservation_token,
        model_name,
        location,
        stage,
        thinking_level,
        media_count,
        media_resolution,
        prompt_version,
        schema_version,
        max_output_tokens,
        retry_count
    ) VALUES (
        p_request_id,
        p_job_key,
        p_claim_token,
        p_operation_key,
        p_attempt,
        p_reservation_token,
        p_metadata->>'model_name',
        p_metadata->>'location',
        p_metadata->>'stage',
        NULLIF(p_metadata->>'thinking_level', ''),
        (p_metadata->>'media_count')::SMALLINT,
        NULLIF(p_metadata->>'media_resolution', ''),
        p_metadata->>'prompt_version',
        (p_metadata->>'schema_version')::SMALLINT,
        (p_metadata->>'max_output_tokens')::INTEGER,
        (p_metadata->>'retry_count')::SMALLINT
    )
    RETURNING * INTO v_existing;

    RETURN public.analysis_v2_ai_attempt_json(v_existing)
        || pg_catalog.jsonb_build_object('created', TRUE);
END;
$_$;


--
-- Name: reserve_analysis_v2_fresh_admission_provider_run(uuid, integer, uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_fresh_admission_provider_run(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid, p_input_hash text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_slot TEXT := p_credential_slot;
    v_operation_key TEXT := 'target-profile-fresh-admission:g'
        || p_admission_generation::TEXT;
    v_existing public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_credential_slot IS NULL THEN
        -- See the initial preflight wrapper: serialize the row lookup with
        -- the free-pool allocator so a concurrent retry reuses its slot.
        PERFORM 1
        FROM public.analysis_preflights AS preflight
        WHERE preflight.id = p_preflight_id
        FOR UPDATE;
        SELECT provider_run.* INTO v_existing
        FROM public.analysis_preflight_provider_runs AS provider_run
        WHERE provider_run.preflight_id = p_preflight_id
          AND provider_run.operation_key = v_operation_key
        FOR UPDATE;
        IF FOUND THEN
            v_slot := v_existing.credential_slot;
        ELSE
            v_slot := public.reserve_analysis_apify_free_provider_slot(
                p_preflight_id, p_max_charge_usd
            );
        END IF;
    END IF;
    IF v_slot IS NULL
       OR NOT public.analysis_beta_valid_apify_credential_slot(v_slot) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_BETA_PREFLIGHT_PROVIDER_RUN_SLOT_MISMATCH', ERRCODE = 'P0001';
    END IF;
    RETURN public.reserve_analysis_v2_fresh_admission_provider_run_fixed_20260904(
        p_preflight_id, p_admission_generation, p_claim_token,
        p_input_hash, v_slot, p_max_charge_usd
    );
END;
$$;


--
-- Name: reserve_analysis_v2_fresh_admission_provider_run_fixed_20260904(uuid, integer, uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_fresh_admission_provider_run_fixed_20260904(p_preflight_id uuid, p_admission_generation integer, p_claim_token uuid, p_input_hash text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $_$
DECLARE v_now TIMESTAMPTZ; v_operation_key TEXT; v_user_hint UUID; v_gate_enabled BOOLEAN;
DECLARE v_grant public.analysis_beta_access_grants%ROWTYPE;
DECLARE v_preflight public.analysis_preflights%ROWTYPE;
DECLARE v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
DECLARE v_target_reservation public.analysis_beta_pool_reservations%ROWTYPE;
DECLARE v_existing public.analysis_preflight_provider_runs%ROWTYPE; v_spent NUMERIC;
BEGIN
    IF p_preflight_id IS NULL OR p_admission_generation NOT BETWEEN 1 AND 100 OR p_claim_token IS NULL OR p_input_hash!~'^[0-9a-f]{64}$' OR p_max_charge_usd IS DISTINCT FROM 0.002600000000 THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID', ERRCODE='P0001'; END IF;
    v_operation_key:='target-profile-fresh-admission:g'||p_admission_generation::TEXT;
    SELECT preflight.user_id INTO v_user_hint FROM public.analysis_preflights AS preflight WHERE preflight.id=p_preflight_id;
    SELECT gate_row.enabled INTO v_gate_enabled FROM public.analysis_beta_runtime_gate AS gate_row WHERE gate_row.singleton=TRUE FOR SHARE;
    PERFORM 1 FROM public.users AS owner_user WHERE owner_user.id=v_user_hint FOR KEY SHARE;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight WHERE preflight.id=p_preflight_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND', ERRCODE='P0001'; END IF;
    v_now:=pg_catalog.clock_timestamp();
    IF v_preflight.status IS DISTINCT FROM 'ready' OR v_preflight.consumed_request_id IS NOT NULL OR v_preflight.expires_at<=v_now OR v_preflight.admission_generation IS DISTINCT FROM p_admission_generation OR v_preflight.admission_status IS DISTINCT FROM 'processing' OR v_preflight.admission_claim_token IS DISTINCT FROM p_claim_token OR v_preflight.admission_lease_expires_at IS NULL OR v_preflight.admission_lease_expires_at<=v_now THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH', ERRCODE='P0001'; END IF;
    IF v_preflight.beta_entry_provenance IS NOT NULL OR v_preflight.analysis_entry_channel='betatest' THEN
        IF p_admission_generation>1 THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_PREFLIGHT_PROVIDER_RUN_GENERATION_INVALID', ERRCODE='P0001'; END IF;
        SELECT allocation.* INTO v_allocation FROM public.analysis_beta_pool_allocations AS allocation WHERE allocation.preflight_id=p_preflight_id AND allocation.lifecycle_state='preflight_held' FOR UPDATE;
        SELECT reservation.* INTO v_target_reservation FROM public.analysis_beta_pool_reservations AS reservation WHERE reservation.allocation_id=v_allocation.id AND reservation.operation_family='target-profile' FOR UPDATE;
        IF NOT FOUND OR NOT public.analysis_beta_valid_apify_credential_slot(p_credential_slot) OR v_target_reservation.credential_slot IS DISTINCT FROM p_credential_slot THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_PREFLIGHT_PROVIDER_RUN_SLOT_MISMATCH', ERRCODE='P0001'; END IF;
    ELSIF NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot) THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_INVALID', ERRCODE='P0001'; END IF;
    PERFORM public.adopt_legacy_fresh_admission_provider_run(p_preflight_id,v_operation_key,v_preflight.admission_requested_at);
    SELECT provider_run.* INTO v_existing FROM public.analysis_preflight_provider_runs AS provider_run WHERE provider_run.preflight_id=p_preflight_id AND provider_run.operation_key=v_operation_key FOR UPDATE;
    v_now:=pg_catalog.clock_timestamp();
    IF v_preflight.status IS DISTINCT FROM 'ready'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.expires_at<=v_now
       OR v_preflight.admission_generation IS DISTINCT FROM p_admission_generation
       OR v_preflight.admission_status IS DISTINCT FROM 'processing'
       OR v_preflight.admission_claim_token IS DISTINCT FROM p_claim_token
       OR v_preflight.admission_lease_expires_at IS NULL
       OR v_preflight.admission_lease_expires_at<=v_now THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH', ERRCODE='P0001';
    END IF;
    IF FOUND THEN
        IF v_existing.input_hash IS DISTINCT FROM p_input_hash OR v_existing.logical_provider IS DISTINCT FROM 'apify' OR v_existing.actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper' OR v_existing.credential_slot IS DISTINCT FROM p_credential_slot OR v_existing.max_charge_usd IS DISTINCT FROM p_max_charge_usd THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_IDENTITY_CONFLICT', ERRCODE='P0001'; END IF;
        RETURN pg_catalog.jsonb_build_object('created',FALSE,'run',public.analysis_preflight_provider_run_json(v_existing));
    END IF;
    IF v_preflight.beta_entry_provenance IS NOT NULL OR v_preflight.analysis_entry_channel='betatest' THEN
        SELECT grant_row.* INTO v_grant FROM public.analysis_beta_access_grants AS grant_row WHERE grant_row.user_id=v_user_hint FOR SHARE;
        v_now:=pg_catalog.clock_timestamp();
        IF v_preflight.expires_at<=v_now
           OR v_preflight.admission_lease_expires_at IS NULL
           OR v_preflight.admission_lease_expires_at<=v_now THEN
            RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH', ERRCODE='P0001';
        END IF;
        IF v_gate_enabled IS DISTINCT FROM TRUE OR v_grant.user_id IS NULL
           OR v_grant.enabled IS DISTINCT FROM TRUE
           OR (v_grant.expires_at IS NOT NULL AND (
                NOT pg_catalog.isfinite(v_grant.expires_at)
                OR v_grant.expires_at<=v_now
           )) THEN
            RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_RUNTIME_DISABLED', ERRCODE='P0001';
        END IF;
        PERFORM 1 FROM public.analysis_preflight_provider_runs AS provider_run WHERE provider_run.preflight_id=p_preflight_id FOR UPDATE;
        SELECT COALESCE(pg_catalog.sum(provider_run.max_charge_usd),0::NUMERIC) INTO v_spent FROM public.analysis_preflight_provider_runs AS provider_run WHERE provider_run.preflight_id=p_preflight_id AND provider_run.operation_key IS DISTINCT FROM v_operation_key;
        IF v_spent+p_max_charge_usd>v_target_reservation.reserved_usd THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_PREFLIGHT_PROVIDER_RUN_BUDGET_EXCEEDED', ERRCODE='P0001'; END IF;
    END IF;
    v_now:=pg_catalog.clock_timestamp();
    IF v_preflight.status IS DISTINCT FROM 'ready'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.expires_at<=v_now
       OR v_preflight.admission_generation IS DISTINCT FROM p_admission_generation
       OR v_preflight.admission_status IS DISTINCT FROM 'processing'
       OR v_preflight.admission_claim_token IS DISTINCT FROM p_claim_token
       OR v_preflight.admission_lease_expires_at IS NULL
       OR v_preflight.admission_lease_expires_at<=v_now THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_PREFLIGHT_PROVIDER_RUN_FENCE_MISMATCH', ERRCODE='P0001';
    END IF;
    IF (v_preflight.beta_entry_provenance IS NOT NULL OR v_preflight.analysis_entry_channel='betatest')
       AND (v_gate_enabled IS DISTINCT FROM TRUE OR v_grant.user_id IS NULL
            OR v_grant.enabled IS DISTINCT FROM TRUE
            OR (v_grant.expires_at IS NOT NULL AND (
                NOT pg_catalog.isfinite(v_grant.expires_at)
                OR v_grant.expires_at<=v_now
            ))) THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_RUNTIME_DISABLED', ERRCODE='P0001'; END IF;
    INSERT INTO public.analysis_preflight_provider_runs(preflight_id,operation_key,input_hash,credential_slot,max_charge_usd) VALUES(p_preflight_id,v_operation_key,p_input_hash,p_credential_slot,p_max_charge_usd) RETURNING * INTO v_existing;
    RETURN pg_catalog.jsonb_build_object('created',TRUE,'run',public.analysis_preflight_provider_run_json(v_existing));
END;
$_$;


--
-- Name: reserve_analysis_v2_job_dispatch(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_job_dispatch(p_request_id uuid, p_job_key text, p_dispatch_token uuid) RETURNS TABLE(reserved boolean, dispatch_generation integer, reservation_token uuid, job_status text, dispatch_state text, task_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    PERFORM public.assert_analysis_revenue_dispatch_guard_v1(p_request_id, p_job_key);
    RETURN QUERY
    SELECT * FROM public.reserve_analysis_v2_job_dispatch_unfenced_20260811(
        p_request_id, p_job_key, p_dispatch_token
    );
END;
$$;


--
-- Name: reserve_analysis_v2_job_dispatch_unfenced_20260811(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_job_dispatch_unfenced_20260811(p_request_id uuid, p_job_key text, p_dispatch_token uuid) RETURNS TABLE(reserved boolean, dispatch_generation integer, reservation_token uuid, job_status text, dispatch_state text, task_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_dispatch_token IS NULL
       OR p_job_key IS NULL
       OR pg_catalog.char_length(p_job_key) NOT BETWEEN 1 AND 160
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_JOB_DISPATCH_INPUT', ERRCODE = 'P0001';
    END IF;

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    IF v_request.status NOT IN ('pending', 'processing') OR v_job.status <> 'pending' THEN
        RETURN QUERY SELECT
            FALSE,
            v_job.dispatch_generation,
            v_job.dispatch_reservation_token,
            v_job.status::TEXT,
            v_job.dispatch_state::TEXT,
            v_job.dispatch_task_name::TEXT;
        RETURN;
    END IF;

    IF v_job.dispatch_state = 'pending' THEN
        UPDATE public.analysis_pipeline_jobs AS job
        SET dispatch_state = 'reserved',
            dispatch_generation = 1,
            dispatch_reservation_token = p_dispatch_token,
            dispatch_reserved_at = v_now,
            updated_at = v_now
        WHERE job.request_id = p_request_id
          AND job.job_key = p_job_key
        RETURNING job.* INTO v_job;
    ELSIF v_job.dispatch_state = 'reserved' THEN
        -- A missing/ambiguous create response reuses this exact generation and token. Age alone
        -- never rotates a task identity.
        NULL;
    ELSE
        RETURN QUERY SELECT
            FALSE,
            v_job.dispatch_generation,
            v_job.dispatch_reservation_token,
            v_job.status::TEXT,
            v_job.dispatch_state::TEXT,
            v_job.dispatch_task_name::TEXT;
        RETURN;
    END IF;

    RETURN QUERY SELECT
        TRUE,
        v_job.dispatch_generation,
        v_job.dispatch_reservation_token,
        v_job.status::TEXT,
        v_job.dispatch_state::TEXT,
        v_job.dispatch_task_name::TEXT;
END;
$_$;


--
-- Name: reserve_analysis_v2_job_dispatch_v2(uuid, text, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_job_dispatch_v2(p_request_id uuid, p_job_key text, p_dispatch_token uuid, p_workload_role text, p_contract_version smallint) RETURNS TABLE(reserved boolean, dispatch_generation integer, reservation_token uuid, job_status text, dispatch_state text, task_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_result RECORD;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'paid' OR p_contract_version IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT job.* INTO v_job FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    IF FOUND AND v_job.dispatch_state IN ('reserved', 'enqueued', 'delivered')
       AND v_job.dispatch_workload_role IS NULL
       AND v_job.dispatch_contract_version IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_LEGACY_DISPATCH_ROLELESS', ERRCODE = 'P0001';
    END IF;
    IF FOUND AND v_job.dispatch_state IN ('reserved', 'enqueued', 'delivered')
       AND (
           v_job.dispatch_workload_role IS NULL
           OR v_job.dispatch_contract_version IS NULL
           OR v_job.dispatch_workload_role IS DISTINCT FROM 'paid'
           OR v_job.dispatch_contract_version IS DISTINCT FROM 2
       ) THEN
        IF v_job.dispatch_workload_role IS NULL
           AND v_job.dispatch_contract_version IS NULL THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_LEGACY_DISPATCH_ROLELESS', ERRCODE = 'P0001';
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT reserved.* INTO v_result FROM public.reserve_analysis_v2_job_dispatch(
        p_request_id, p_job_key, p_dispatch_token
    ) AS reserved;
    IF v_result.reserved THEN
        UPDATE public.analysis_pipeline_jobs AS job
        SET dispatch_workload_role = 'paid', dispatch_contract_version = 2
        WHERE job.request_id = p_request_id AND job.job_key = p_job_key
          AND job.dispatch_state = 'reserved'
          AND job.dispatch_generation = v_result.dispatch_generation
          AND job.dispatch_reservation_token = v_result.reservation_token;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_JOB_DISPATCH_FENCE_MISMATCH', ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN QUERY SELECT v_result.reserved, v_result.dispatch_generation,
        v_result.reservation_token, v_result.job_status, v_result.dispatch_state,
        v_result.task_name;
END;
$$;


--
-- Name: reserve_analysis_v2_preflight_admission(uuid, uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_preflight_admission(p_preflight_id uuid, p_user_id uuid, p_selected_plan_id text, p_entitlement_jti_hash text, p_admission_token uuid, p_dispatch_token uuid) RETURNS TABLE(admission_status text, should_enqueue boolean, admission_generation integer, dispatch_generation integer, dispatch_token uuid, selected_plan_id text, selected_plan_allowed boolean, admission_token uuid, admission_refreshed_at timestamp with time zone, target_followers_count integer, target_following_count integer, capacity_required_plan_id text, required_plan_id text, plan_cards_snapshot jsonb, pricing_version text, pricing_snapshot jsonb, admission_error_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_runner_plan TEXT;
    v_settlement JSONB;
    v_allowed BOOLEAN;
BEGIN
    -- Preserve the established validation and behavior until a concrete row
    -- proves this is the registered strict authorized-test lineage.
    IF p_preflight_id IS NULL
       OR p_user_id IS NULL
       OR p_selected_plan_id NOT IN ('basic', 'standard') THEN
        RETURN QUERY
        SELECT *
        FROM public.analysis_v2_reserve_preflight_admission_after_settlement_internal(
            p_preflight_id,
            p_user_id,
            p_selected_plan_id,
            p_entitlement_jti_hash,
            p_admission_token,
            p_dispatch_token
        );
        RETURN;
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_preflight.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_preflight.admission_generation < 1 THEN
        RETURN QUERY
        SELECT *
        FROM public.analysis_v2_reserve_preflight_admission_after_settlement_internal(
            p_preflight_id,
            p_user_id,
            p_selected_plan_id,
            p_entitlement_jti_hash,
            p_admission_token,
            p_dispatch_token
        );
        RETURN;
    END IF;

    SELECT runner.runner_plan
    INTO v_runner_plan
    FROM public.load_e2e_test_runner_v1(p_user_id) AS runner;
    IF v_runner_plan IS NULL
       OR v_runner_plan NOT IN ('basic', 'standard') THEN
        RETURN QUERY
        SELECT *
        FROM public.analysis_v2_reserve_preflight_admission_after_settlement_internal(
            p_preflight_id,
            p_user_id,
            p_selected_plan_id,
            p_entitlement_jti_hash,
            p_admission_token,
            p_dispatch_token
        );
        RETURN;
    END IF;

    -- Once a registered Basic/Standard runner has a g1, no different signed
    -- entitlement or plan may reach the legacy stale-admission branch. That
    -- branch creates a new provider generation before later consumption can
    -- reject the mismatched capability. Exact identity may still replay the
    -- durable result below; all mismatch cases fence before any enqueue.
    IF p_entitlement_jti_hash IS NULL
       OR p_entitlement_jti_hash !~ '^[a-f0-9]{64}$'
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM p_selected_plan_id
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM v_runner_plan
       OR v_preflight.admission_entitlement_jti_hash
            IS DISTINCT FROM p_entitlement_jti_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_REVENUE_SETTLEMENT_FENCE',
            ERRCODE = 'P0001';
    END IF;

    IF v_preflight.consumed_request_id IS NOT NULL THEN
        RETURN QUERY
        SELECT *
        FROM public.analysis_v2_reserve_preflight_admission_after_settlement_internal(
            p_preflight_id,
            p_user_id,
            p_selected_plan_id,
            p_entitlement_jti_hash,
            p_admission_token,
            p_dispatch_token
        );
        RETURN;
    END IF;

    -- A later generation has no ledger-authorized source lineage. Do not
    -- enqueue or create g3 while a migration-first route is still draining.
    IF v_preflight.admission_generation IS DISTINCT FROM 1 THEN
        RETURN QUERY SELECT
            'pending'::TEXT,
            FALSE,
            v_preflight.admission_generation,
            GREATEST(v_preflight.admission_dispatch_generation, 1),
            NULL::UUID,
            p_selected_plan_id,
            NULL::BOOLEAN,
            NULL::UUID,
            NULL::TIMESTAMP WITH TIME ZONE,
            NULL::INTEGER,
            NULL::INTEGER,
            NULL::TEXT,
            NULL::TEXT,
            NULL::JSONB,
            v_preflight.pricing_version::TEXT,
            v_preflight.pricing_snapshot,
            NULL::TEXT;
        RETURN;
    END IF;

    -- A proven blocked g1 is terminal. Replaying its stored outcome is safe;
    -- replacing it with g2 would recollect and destroy the ledger fence.
    IF v_preflight.admission_status = 'blocked' THEN
        RETURN QUERY SELECT
            'blocked'::TEXT,
            FALSE,
            v_preflight.admission_generation,
            GREATEST(v_preflight.admission_dispatch_generation, 1),
            NULL::UUID,
            p_selected_plan_id,
            NULL::BOOLEAN,
            NULL::UUID,
            v_preflight.admission_refreshed_at,
            v_preflight.admission_target_followers_count,
            v_preflight.admission_target_following_count,
            v_preflight.admission_capacity_required_plan_id,
            v_preflight.admission_required_plan_id,
            v_preflight.admission_plan_cards_snapshot,
            v_preflight.pricing_version::TEXT,
            v_preflight.pricing_snapshot,
            v_preflight.admission_error_code;
        RETURN;
    END IF;

    -- This turns the migration-first old-route path into its existing pending
    -- response before it reaches the authorized consume RPC. After settlement
    -- the same helper re-arms and returns the existing token, never a caller
    -- supplied replacement and never a new provider generation.
    IF v_preflight.admission_status = 'ready' THEN
        v_settlement := public.prepare_analysis_v2_authorized_revenue_settlement_admission(
            p_preflight_id,
            p_user_id,
            p_selected_plan_id,
            p_entitlement_jti_hash
        );
        IF v_settlement->>'disposition' = 'pending' THEN
            RETURN QUERY SELECT
                'pending'::TEXT,
                FALSE,
                v_preflight.admission_generation,
                GREATEST(v_preflight.admission_dispatch_generation, 1),
                NULL::UUID,
                p_selected_plan_id,
                NULL::BOOLEAN,
                NULL::UUID,
                NULL::TIMESTAMP WITH TIME ZONE,
                NULL::INTEGER,
                NULL::INTEGER,
                NULL::TEXT,
                NULL::TEXT,
                NULL::JSONB,
                v_preflight.pricing_version::TEXT,
                v_preflight.pricing_snapshot,
                NULL::TEXT;
            RETURN;
        END IF;
        IF v_settlement->>'disposition' IS DISTINCT FROM 'ready' THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_REVENUE_SETTLEMENT_FENCE',
                ERRCODE = 'P0001';
        END IF;

        SELECT preflight.*
        INTO v_preflight
        FROM public.analysis_preflights AS preflight
        WHERE preflight.id = p_preflight_id
          AND preflight.user_id = p_user_id
        FOR UPDATE;
        v_allowed := v_preflight.admission_plan_cards_snapshot
            ->p_selected_plan_id->>'selectionState'
            IN ('required', 'available_upgrade');
        IF v_preflight.admission_status IS DISTINCT FROM 'ready'
           OR v_preflight.admission_generation IS DISTINCT FROM 1
           OR v_preflight.admission_selected_plan_id IS DISTINCT FROM p_selected_plan_id
           OR v_preflight.admission_entitlement_jti_hash
                IS DISTINCT FROM p_entitlement_jti_hash
           OR v_preflight.admission_token
                IS DISTINCT FROM (v_settlement->>'admissionToken')::UUID
           OR v_preflight.admission_refreshed_at IS NULL
           OR v_allowed IS DISTINCT FROM TRUE THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_REVENUE_SETTLEMENT_FENCE',
                ERRCODE = 'P0001';
        END IF;
        RETURN QUERY SELECT
            'ready'::TEXT,
            FALSE,
            v_preflight.admission_generation,
            GREATEST(v_preflight.admission_dispatch_generation, 1),
            NULL::UUID,
            p_selected_plan_id,
            TRUE,
            v_preflight.admission_token,
            v_preflight.admission_refreshed_at,
            v_preflight.admission_target_followers_count,
            v_preflight.admission_target_following_count,
            v_preflight.admission_capacity_required_plan_id,
            v_preflight.admission_required_plan_id,
            v_preflight.admission_plan_cards_snapshot,
            v_preflight.pricing_version::TEXT,
            v_preflight.pricing_snapshot,
            NULL::TEXT;
        RETURN;
    END IF;

    -- Pending/processing g1 retains the original dispatch-recovery behavior:
    -- it may resume that same provider intent but cannot create g2.
    RETURN QUERY
    SELECT *
    FROM public.analysis_v2_reserve_preflight_admission_after_settlement_internal(
        p_preflight_id,
        p_user_id,
        p_selected_plan_id,
        p_entitlement_jti_hash,
        p_admission_token,
        p_dispatch_token
    );
END;
$_$;


--
-- Name: reserve_analysis_v2_preflight_admission_dispatch_v2(uuid, uuid, text, text, uuid, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_preflight_admission_dispatch_v2(p_preflight_id uuid, p_user_id uuid, p_selected_plan_id text, p_entitlement_jti_hash text, p_admission_token uuid, p_dispatch_token uuid, p_workload_role text, p_contract_version smallint) RETURNS TABLE(admission_status text, should_enqueue boolean, admission_generation integer, dispatch_generation integer, dispatch_token uuid, selected_plan_id text, selected_plan_allowed boolean, admission_token uuid, admission_refreshed_at timestamp with time zone, target_followers_count integer, target_following_count integer, capacity_required_plan_id text, required_plan_id text, plan_cards_snapshot jsonb, pricing_version text, pricing_snapshot jsonb, admission_error_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_result RECORD;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'paid' OR p_contract_version IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id AND preflight.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.admission_dispatch_state IN ('reserved', 'enqueued')
       AND v_preflight.admission_dispatch_workload_role IS NULL
       AND v_preflight.admission_dispatch_contract_version IS NULL
       AND v_preflight.admission_dispatch_generation > 0 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_LEGACY_DISPATCH_ROLELESS', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.admission_dispatch_workload_role IS NOT NULL
       AND (v_preflight.admission_dispatch_workload_role IS DISTINCT FROM 'paid'
            OR v_preflight.admission_dispatch_contract_version IS DISTINCT FROM 2) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT reserved.* INTO v_result
    FROM public.reserve_analysis_v2_preflight_admission(
        p_preflight_id, p_user_id, p_selected_plan_id, p_entitlement_jti_hash,
        p_admission_token, p_dispatch_token
    ) AS reserved;
    IF v_result.should_enqueue THEN
        UPDATE public.analysis_preflights AS preflight
        SET admission_dispatch_workload_role = 'paid',
            admission_dispatch_contract_version = 2
        WHERE preflight.id = p_preflight_id
          AND preflight.admission_dispatch_state = 'reserved'
          AND preflight.admission_dispatch_generation = v_result.dispatch_generation
          AND preflight.admission_dispatch_token = v_result.dispatch_token;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_FRESH_ADMISSION_DISPATCH_LOST', ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN QUERY SELECT v_result.admission_status, v_result.should_enqueue,
        v_result.admission_generation, v_result.dispatch_generation, v_result.dispatch_token,
        v_result.selected_plan_id, v_result.selected_plan_allowed, v_result.admission_token,
        v_result.admission_refreshed_at, v_result.target_followers_count,
        v_result.target_following_count, v_result.capacity_required_plan_id,
        v_result.required_plan_id, v_result.plan_cards_snapshot, v_result.pricing_version,
        v_result.pricing_snapshot, v_result.admission_error_code;
END;
$$;


--
-- Name: reserve_analysis_v2_preflight_dispatch(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_preflight_dispatch(p_preflight_id uuid, p_user_id uuid, p_dispatch_token uuid) RETURNS TABLE(should_enqueue boolean, dispatch_generation integer, reservation_token uuid, preflight_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight
    WHERE preflight.id=p_preflight_id AND preflight.user_id=p_user_id FOR UPDATE;
    IF FOUND AND v_preflight.status='pending'
       AND v_preflight.beta_entry_provenance IS NOT NULL
       AND v_preflight.beta_prepare_state IS DISTINCT FROM 'prepared' THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_PREPARE_REQUIRED', ERRCODE='P0001';
    END IF;
    RETURN QUERY SELECT * FROM public.reserve_analysis_v2_preflight_dispatch_unfenced_20260802(
        p_preflight_id,p_user_id,p_dispatch_token);
END;
$$;


--
-- Name: reserve_analysis_v2_preflight_dispatch_unfenced_20260802(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_preflight_dispatch_unfenced_20260802(p_preflight_id uuid, p_user_id uuid, p_dispatch_token uuid) RETURNS TABLE(should_enqueue boolean, dispatch_generation integer, reservation_token uuid, preflight_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL OR p_user_id IS NULL OR p_dispatch_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_DISPATCH_INPUT', ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    IF v_preflight.expires_at <= v_now THEN
        IF v_preflight.status IN ('pending', 'processing', 'ready') THEN
            UPDATE public.analysis_preflights
            SET status = 'expired',
                lease_token = NULL,
                lease_expires_at = NULL,
                updated_at = v_now
            WHERE id = v_preflight.id;
        END IF;
        RETURN QUERY SELECT FALSE, v_preflight.dispatch_generation, NULL::UUID, 'expired'::TEXT;
        RETURN;
    END IF;

    IF v_preflight.status <> 'pending' THEN
        RETURN QUERY
        SELECT FALSE, v_preflight.dispatch_generation, NULL::UUID, v_preflight.status;
        RETURN;
    END IF;

    IF v_preflight.dispatch_state = 'reserved'
       AND v_preflight.dispatch_reserved_at > v_now - INTERVAL '2 minutes' THEN
        RETURN QUERY
        SELECT TRUE, v_preflight.dispatch_generation, v_preflight.dispatch_token, 'pending'::TEXT;
        RETURN;
    END IF;

    IF v_preflight.dispatch_state = 'enqueued' THEN
        RETURN QUERY
        SELECT FALSE, v_preflight.dispatch_generation, NULL::UUID, 'pending'::TEXT;
        RETURN;
    END IF;

    IF v_preflight.dispatch_generation >= 100 THEN
        UPDATE public.analysis_preflights
        SET status = 'blocked',
            error_code = 'QUEUE_UNAVAILABLE',
            blocked_at = v_now,
            updated_at = v_now
        WHERE id = v_preflight.id;
        RETURN QUERY SELECT FALSE, v_preflight.dispatch_generation, NULL::UUID, 'blocked'::TEXT;
        RETURN;
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET dispatch_generation = preflight.dispatch_generation + 1,
        dispatch_state = 'reserved',
        dispatch_token = p_dispatch_token,
        dispatch_reserved_at = v_now,
        dispatched_at = NULL,
        updated_at = v_now
    WHERE id = v_preflight.id;

    RETURN QUERY
    SELECT TRUE, v_preflight.dispatch_generation + 1, p_dispatch_token, 'pending'::TEXT;
END;
$$;


--
-- Name: reserve_analysis_v2_preflight_dispatch_v2(uuid, uuid, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_preflight_dispatch_v2(p_preflight_id uuid, p_user_id uuid, p_dispatch_token uuid, p_workload_role text, p_contract_version smallint) RETURNS TABLE(should_enqueue boolean, dispatch_generation integer, reservation_token uuid, preflight_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_result RECORD;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'preflight' OR p_contract_version IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id AND preflight.user_id = p_user_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.dispatch_state IN ('reserved', 'enqueued')
       AND v_preflight.dispatch_workload_role IS NULL
       AND v_preflight.dispatch_contract_version IS NULL
       AND v_preflight.dispatch_generation > 0 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_LEGACY_DISPATCH_ROLELESS', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.dispatch_workload_role IS NOT NULL
       AND (v_preflight.dispatch_workload_role IS DISTINCT FROM 'preflight'
            OR v_preflight.dispatch_contract_version IS DISTINCT FROM 2) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    SELECT reserved.* INTO v_result
    FROM public.reserve_analysis_v2_preflight_dispatch(
        p_preflight_id, p_user_id, p_dispatch_token
    ) AS reserved;
    IF v_result.should_enqueue THEN
        UPDATE public.analysis_preflights AS preflight
        SET dispatch_workload_role = 'preflight',
            dispatch_contract_version = 2
        WHERE preflight.id = p_preflight_id
          AND preflight.dispatch_state = 'reserved'
          AND preflight.dispatch_generation = v_result.dispatch_generation
          AND preflight.dispatch_token = v_result.reservation_token;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_DISPATCH_RESERVATION_LOST', ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN QUERY SELECT v_result.should_enqueue, v_result.dispatch_generation,
        v_result.reservation_token, v_result.preflight_status;
END;
$$;


--
-- Name: reserve_analysis_v2_profile_provider_canary_run(uuid, integer, integer, integer, integer, integer, integer, integer, integer, integer, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_profile_provider_canary_run(p_source_request_id uuid, p_repetition integer, p_source_run_count integer, p_candidate_count integer, p_unique_candidate_count integer, p_public_candidate_count integer, p_incomplete_candidate_count integer, p_unavailable_candidate_count integer, p_primary_success_candidate_count integer, p_critical_candidate_count integer, p_ordered_set_hmac text, p_restricted_access_verified boolean, p_reservation_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_guard public.analysis_v2_apify_secret_ref_prune_guard%ROWTYPE;
BEGIN
    SELECT guard.*
    INTO v_guard
    FROM public.analysis_v2_apify_secret_ref_prune_guard AS guard
    WHERE guard.singleton IS TRUE
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_GUARD_CORRUPT',
            ERRCODE = 'P0001';
    END IF;
    IF v_guard.drop_slots IS NOT NULL
       AND EXISTS (
            SELECT 1
            FROM public.analysis_v2_provider_runs AS source_run
            JOIN public.analysis_v2_provider_execution_policies AS execution_policy
              ON execution_policy.request_id = source_run.request_id
            WHERE source_run.request_id = p_source_request_id
              AND source_run.status = 'succeeded'
              AND source_run.run_id ~ '^[A-Za-z0-9]{8,64}$'
              AND source_run.actor_id = 'apify/instagram-profile-scraper'
              AND source_run.job_key ~ '^track:profiles:batch:(?:0|[1-7])$'
              AND source_run.operation_key ~
                    '^profile-fallback:[0-9a-f]{64}$'
              AND execution_policy.mode = 'test_operation_split'
              AND execution_policy.policy_version = 'authorized-free-e2e-v1'
              AND execution_policy.operation_slot_map->>'profile-fallback'
                    = source_run.credential_slot
              AND source_run.credential_slot = ANY(v_guard.drop_slots)
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_FENCED',
            ERRCODE = 'P0001';
    END IF;
    RETURN public.analysis_v2_profile_provider_canary_reserve_unfenced(
        p_source_request_id,
        p_repetition,
        p_source_run_count,
        p_candidate_count,
        p_unique_candidate_count,
        p_public_candidate_count,
        p_incomplete_candidate_count,
        p_unavailable_candidate_count,
        p_primary_success_candidate_count,
        p_critical_candidate_count,
        p_ordered_set_hmac,
        p_restricted_access_verified,
        p_reservation_token
    );
END;
$_$;


--
-- Name: reserve_analysis_v2_profile_repair_canary_run(uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_profile_repair_canary_run(p_source_request_id uuid, p_repetition integer, p_credential_slot text, p_reservation_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_guard public.analysis_v2_apify_secret_ref_prune_guard%ROWTYPE;
BEGIN
    SELECT guard.*
    INTO v_guard
    FROM public.analysis_v2_apify_secret_ref_prune_guard AS guard
    WHERE guard.singleton IS TRUE
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_GUARD_CORRUPT',
            ERRCODE = 'P0001';
    END IF;
    IF v_guard.drop_slots IS NOT NULL
       AND p_credential_slot = ANY(v_guard.drop_slots) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_APIFY_SECRET_REF_PRUNE_FENCED',
            ERRCODE = 'P0001';
    END IF;
    RETURN public.analysis_v2_profile_repair_canary_reserve_unfenced(
        p_source_request_id,
        p_repetition,
        p_credential_slot,
        p_reservation_token
    );
END;
$$;


--
-- Name: reserve_analysis_v2_provider_run(uuid, text, uuid, text, text, text, text, text, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_analysis_v2_provider_run(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric, p_reservation_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_policy public.analysis_v2_provider_execution_policies%ROWTYPE;
DECLARE v_request public.analysis_requests%ROWTYPE;
DECLARE v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
DECLARE v_reservation public.analysis_beta_pool_reservations%ROWTYPE;
DECLARE v_existing public.analysis_v2_provider_runs%ROWTYPE;
DECLARE v_operation_kind TEXT;
DECLARE v_operation_family TEXT;
DECLARE v_spent NUMERIC;
BEGIN
    PERFORM 1 FROM public.analysis_preflights AS preflight WHERE preflight.consumed_request_id = p_request_id FOR UPDATE;
    SELECT analysis_request.* INTO v_request FROM public.analysis_requests AS analysis_request WHERE analysis_request.id = p_request_id FOR UPDATE;
    PERFORM 1 FROM public.analysis_pipeline_jobs AS job WHERE job.request_id = p_request_id AND job.job_key = p_job_key FOR UPDATE;
    IF EXISTS (SELECT 1 FROM public.analysis_v2_provider_cleanup_intents AS intent WHERE intent.request_id = p_request_id AND intent.completed_at IS NULL) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_REQUIRED', ERRCODE = 'P0001';
    END IF;
    SELECT policy.* INTO v_policy FROM public.analysis_v2_provider_execution_policies AS policy WHERE policy.request_id = p_request_id;
    IF v_request.analysis_entry_channel = 'betatest' THEN
        v_operation_family := pg_catalog.split_part(p_operation_key, ':', 1);
        IF NOT public.analysis_beta_valid_operation_slot_map(v_policy.operation_slot_map)
           OR v_policy.mode IS DISTINCT FROM 'betatest_free_pool'
           OR v_policy.policy_version IS DISTINCT FROM 'betatest-free-pool-v1'
           OR v_policy.entitlement_jti_hash IS NOT NULL
           OR v_operation_family NOT IN ('target-profile','relationship-followers','relationship-following','profile-fallback','profile-repair','target-likers','target-comments','candidate-likers') THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_PROVIDER_RUN_OPERATION_INVALID', ERRCODE = 'P0001';
        END IF;
        SELECT allocation.* INTO v_allocation FROM public.analysis_beta_pool_allocations AS allocation
        WHERE allocation.request_id = p_request_id AND allocation.lifecycle_state = 'active' FOR UPDATE;
        SELECT reservation.* INTO v_reservation FROM public.analysis_beta_pool_reservations AS reservation
        WHERE reservation.allocation_id = v_allocation.id AND reservation.operation_family = v_operation_family FOR UPDATE;
        IF NOT FOUND OR v_allocation.operation_slot_map IS DISTINCT FROM v_policy.operation_slot_map
           OR v_reservation.credential_slot IS DISTINCT FROM p_credential_slot
           OR v_policy.operation_slot_map->>v_operation_family IS DISTINCT FROM p_credential_slot
           OR NOT public.analysis_beta_valid_apify_credential_slot(p_credential_slot) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_PROVIDER_RUN_SLOT_MISMATCH', ERRCODE = 'P0001';
        END IF;
        SELECT provider_run.* INTO v_existing FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = p_request_id AND provider_run.job_key = p_job_key
          AND provider_run.operation_key = p_operation_key FOR UPDATE;
        IF FOUND AND (v_existing.input_hash IS DISTINCT FROM p_input_hash
           OR v_existing.logical_provider IS DISTINCT FROM p_logical_provider
           OR v_existing.actor_id IS DISTINCT FROM p_actor_id
           OR v_existing.credential_slot IS DISTINCT FROM p_credential_slot
           OR v_existing.max_charge_usd IS DISTINCT FROM p_max_charge_usd) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        SELECT COALESCE(pg_catalog.sum(provider_run.max_charge_usd), 0::NUMERIC) INTO v_spent
        FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = p_request_id
          AND pg_catalog.split_part(provider_run.operation_key, ':', 1) = v_operation_family
          AND (provider_run.job_key IS DISTINCT FROM p_job_key OR provider_run.operation_key IS DISTINCT FROM p_operation_key);
        IF v_spent + p_max_charge_usd > v_reservation.reserved_usd THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_PROVIDER_RUN_BUDGET_EXCEEDED', ERRCODE = 'P0001';
        END IF;
    ELSIF FOUND THEN
        v_operation_kind := pg_catalog.split_part(p_operation_key, ':', 1);
        IF v_policy.mode = 'test_operation_split' AND v_operation_kind = 'profile-repair' THEN v_operation_kind := 'profile-fallback'; END IF;
        IF v_policy.operation_slot_map->>v_operation_kind IS DISTINCT FROM p_credential_slot THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_AUTHORIZED_TEST_POLICY_SLOT_MISMATCH', ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN public.analysis_v2_reserve_provider_run_internal(p_request_id,p_job_key,p_claim_token,p_operation_key,p_input_hash,p_logical_provider,p_actor_id,p_credential_slot,p_max_charge_usd,p_reservation_token);
END;
$$;


--
-- Name: reserve_anonymous_analysis_v2_preflight_dispatch(uuid, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_anonymous_analysis_v2_preflight_dispatch(p_preflight_id uuid, p_claim_token_hash character varying, p_dispatch_token uuid) RETURNS TABLE(should_enqueue boolean, dispatch_generation integer, reservation_token uuid, preflight_status text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    IF p_preflight_id IS NULL
       OR p_claim_token_hash !~ '^[0-9a-f]{64}$'
       OR p_dispatch_token IS NULL THEN
        RETURN QUERY SELECT FALSE, 0, NULL::UUID, 'missing'::TEXT;
        RETURN;
    END IF;
    PERFORM pg_catalog.set_config(
        'app.anonymous_preflight_claim_hash', p_claim_token_hash, TRUE
    );
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id IS NULL
      AND preflight.claim_token_hash = p_claim_token_hash
      AND preflight.claim_expires_at > v_now
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 0, NULL::UUID, 'missing'::TEXT;
        RETURN;
    END IF;
    IF v_preflight.dispatch_state = 'enqueued' THEN
        RETURN QUERY SELECT FALSE, v_preflight.dispatch_generation, NULL::UUID, v_preflight.status;
        RETURN;
    END IF;
    UPDATE public.analysis_preflights AS target
    SET dispatch_generation = target.dispatch_generation + 1,
        dispatch_state = 'reserved',
        dispatch_token = p_dispatch_token,
        dispatch_reserved_at = v_now,
        updated_at = v_now
    WHERE target.id = p_preflight_id;
    RETURN QUERY SELECT TRUE, v_preflight.dispatch_generation + 1, p_dispatch_token, v_preflight.status;
END;
$_$;


--
-- Name: reserve_anonymous_analysis_v2_preflight_dispatch_v2(uuid, character varying, uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_anonymous_analysis_v2_preflight_dispatch_v2(p_preflight_id uuid, p_claim_token_hash character varying, p_dispatch_token uuid, p_workload_role text, p_contract_version smallint) RETURNS TABLE(should_enqueue boolean, dispatch_generation integer, reservation_token uuid, preflight_status text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE;
    v_result RECORD;
BEGIN
    IF p_preflight_id IS NULL
       OR p_claim_token_hash IS NULL
       OR p_claim_token_hash !~ '^[0-9a-f]{64}$'
       OR p_dispatch_token IS NULL
       OR p_workload_role IS DISTINCT FROM 'preflight'
       OR p_contract_version IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    PERFORM pg_catalog.set_config(
        'app.anonymous_preflight_claim_hash', p_claim_token_hash, TRUE
    );
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND preflight.user_id IS NULL
      AND preflight.claim_token_hash = p_claim_token_hash
      AND preflight.claim_expires_at > pg_catalog.clock_timestamp()
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 0, NULL::UUID, 'missing'::TEXT;
        RETURN;
    END IF;

    -- A roleless enqueued row is historical drain-only work.  Never upgrade it into a
    -- role-aware successor merely because a new producer replayed the same idempotency key.
    IF v_preflight.dispatch_state = 'enqueued'
       AND v_preflight.dispatch_workload_role IS NULL
       AND v_preflight.dispatch_contract_version IS NULL THEN
        RETURN QUERY SELECT FALSE, v_preflight.dispatch_generation, NULL::UUID,
            v_preflight.status::TEXT;
        RETURN;
    END IF;
    IF v_preflight.dispatch_workload_role IS NOT NULL
       AND (v_preflight.dispatch_workload_role IS DISTINCT FROM 'preflight'
            OR v_preflight.dispatch_contract_version IS DISTINCT FROM 2) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.dispatch_state = 'reserved'
       AND v_preflight.dispatch_workload_role IS NULL
       AND v_preflight.dispatch_contract_version IS NULL
       AND v_preflight.dispatch_generation > 0 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_LEGACY_DISPATCH_ROLELESS', ERRCODE = 'P0001';
    END IF;

    SELECT reserved.* INTO v_result
    FROM public.reserve_anonymous_analysis_v2_preflight_dispatch(
        p_preflight_id, p_claim_token_hash, p_dispatch_token
    ) AS reserved;
    IF v_result.should_enqueue THEN
        UPDATE public.analysis_preflights AS preflight
        SET dispatch_workload_role = 'preflight',
            dispatch_contract_version = 2
        WHERE preflight.id = p_preflight_id
          AND preflight.user_id IS NULL
          AND preflight.dispatch_state = 'reserved'
          AND preflight.dispatch_generation = v_result.dispatch_generation
          AND preflight.dispatch_token = v_result.reservation_token;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_DISPATCH_FENCE_LOST', ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN QUERY SELECT v_result.should_enqueue, v_result.dispatch_generation,
        v_result.reservation_token, v_result.preflight_status;
END;
$_$;


--
-- Name: reserve_anonymous_preflight_budget(character varying, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_anonymous_preflight_budget(p_ip_hash character varying, p_device_hash character varying, p_target_input_hash character varying, p_daily_limit integer DEFAULT 300) RETURNS TABLE(allowed boolean, reason text, daily_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_daily_count INTEGER;
    v_actor_count INTEGER;
BEGIN
    IF p_ip_hash !~ '^[0-9a-f]{64}$'
       OR p_device_hash !~ '^[0-9a-f]{64}$'
       OR p_target_input_hash !~ '^[0-9a-f]{64}$'
       OR p_daily_limit IS NULL OR p_daily_limit < 1 OR p_daily_limit > 10000 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_INVALID_BUDGET_INPUT', ERRCODE = 'P0001';
    END IF;
    SELECT COUNT(*)::INTEGER INTO v_daily_count
    FROM public.analysis_anonymous_preflight_attempts
    WHERE occurred_at >= date_trunc('day', v_now);
    IF v_daily_count >= p_daily_limit THEN
        RETURN QUERY SELECT FALSE, 'daily_cap'::TEXT, v_daily_count;
        RETURN;
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('anonymous-preflight-daily-budget', 0)
    );
    SELECT COUNT(*)::INTEGER INTO v_daily_count
    FROM public.analysis_anonymous_preflight_attempts
    WHERE occurred_at >= date_trunc('day', v_now);
    IF v_daily_count >= p_daily_limit THEN
        RETURN QUERY SELECT FALSE, 'daily_cap'::TEXT, v_daily_count;
        RETURN;
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_ip_hash || ':' || p_device_hash, 0)
    );
    SELECT COUNT(*)::INTEGER INTO v_actor_count
    FROM public.analysis_anonymous_preflight_attempts
    WHERE occurred_at >= v_now - INTERVAL '10 minutes'
      AND (ip_hash = p_ip_hash OR device_hash = p_device_hash);
    IF v_actor_count >= 5 THEN
        RETURN QUERY SELECT FALSE, 'rate_limited'::TEXT, v_daily_count;
        RETURN;
    END IF;
    INSERT INTO public.analysis_anonymous_preflight_attempts(
        ip_hash, device_hash, target_input_hash
    ) VALUES (p_ip_hash, p_device_hash, p_target_input_hash);
    RETURN QUERY SELECT TRUE, 'accepted'::TEXT, v_daily_count + 1;
END;
$_$;


--
-- Name: reserve_precheckout_blite_dispatch_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_precheckout_blite_dispatch_v1(p_preflight_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_token UUID := extensions.gen_random_uuid();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_dispatch public.precheckout_blite_dispatches%ROWTYPE;
    v_generation INTEGER;
BEGIN
    IF p_preflight_id IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'PRECHECKOUT_BLITE_DISPATCH_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE, 'dispatch_token', NULL, 'dispatch_generation', 1
        );
    END IF;
    IF v_preflight.precheckout_blite_cohort IS DISTINCT FROM TRUE
       OR v_preflight.status IS DISTINCT FROM 'ready'
       OR v_preflight.pii_scrubbed_at IS NOT NULL
       OR v_preflight.expires_at <= v_now
       OR NOT EXISTS (
            SELECT 1 FROM public.precheckout_blite_sources AS source
            WHERE source.preflight_id = p_preflight_id
       )
       OR NOT EXISTS (
            SELECT 1 FROM public.precheckout_blite_cache AS cache
            WHERE cache.preflight_id = p_preflight_id
              AND cache.state = 'pending'
       ) THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE, 'dispatch_token', NULL, 'dispatch_generation', 1
        );
    END IF;

    SELECT dispatch.* INTO v_dispatch
    FROM public.precheckout_blite_dispatches AS dispatch
    WHERE dispatch.preflight_id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO public.precheckout_blite_dispatches (
            preflight_id, state, attempt_count, dispatch_generation, created_at, updated_at
        ) VALUES (p_preflight_id, 'idle', 0, 1, v_now, v_now)
        RETURNING * INTO v_dispatch;
    END IF;

    v_now := pg_catalog.clock_timestamp();
    IF v_dispatch.state = 'enqueued' THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE,
            'dispatch_token', NULL,
            'dispatch_generation', v_dispatch.dispatch_generation
        );
    END IF;
    IF v_dispatch.state = 'enqueuing'
       AND v_dispatch.lease_expires_at > v_now THEN
        RETURN pg_catalog.jsonb_build_object(
            'should_enqueue', FALSE,
            'dispatch_token', NULL,
            'dispatch_generation', v_dispatch.dispatch_generation
        );
    END IF;

    v_generation := CASE
        WHEN v_dispatch.attempt_count = 0 THEN v_dispatch.dispatch_generation
        ELSE v_dispatch.dispatch_generation + 1
    END;
    IF v_generation > 100 THEN
        RAISE EXCEPTION USING MESSAGE = 'PRECHECKOUT_BLITE_DISPATCH_GENERATION_EXHAUSTED', ERRCODE = 'P0001';
    END IF;
    UPDATE public.precheckout_blite_dispatches
    SET state = 'enqueuing',
        attempt_count = v_dispatch.attempt_count + 1,
        dispatch_generation = v_generation,
        dispatch_token = v_token,
        last_dispatch_token = NULL,
        lease_expires_at = v_now + INTERVAL '2 minutes',
        failure_reason = NULL,
        updated_at = v_now
    WHERE preflight_id = p_preflight_id;
    RETURN pg_catalog.jsonb_build_object(
        'should_enqueue', TRUE,
        'dispatch_token', v_token,
        'dispatch_generation', v_generation
    );
END;
$$;


--
-- Name: reserve_precheckout_blite_dispatch_v2(uuid, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_precheckout_blite_dispatch_v2(p_preflight_id uuid, p_workload_role text, p_contract_version smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_dispatch public.precheckout_blite_dispatches%ROWTYPE;
    v_result JSONB;
BEGIN
    IF p_workload_role IS DISTINCT FROM 'preflight' OR p_contract_version IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    -- A roleless predecessor belongs to the mixed-version drain cohort.  It
    -- must never be upgraded merely because a new worker retries the same
    -- preflight id: doing so would manufacture a role-aware successor that
    -- the old task can neither claim nor safely fence.  An idle roleless row
    -- is still eligible for a genuinely new v2 reservation; every active or
    -- reserved roleless row remains drain-only.
    SELECT dispatch.* INTO v_dispatch
    FROM public.precheckout_blite_dispatches AS dispatch
    WHERE dispatch.preflight_id = p_preflight_id
    FOR UPDATE;
    IF FOUND AND v_dispatch.state IN ('reserved', 'enqueuing', 'enqueued')
       AND v_dispatch.dispatch_workload_role IS NULL
       AND v_dispatch.dispatch_contract_version IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_LEGACY_DISPATCH_ROLELESS', ERRCODE = 'P0001';
    END IF;
    IF FOUND AND (
        (v_dispatch.dispatch_workload_role IS NULL
            AND v_dispatch.dispatch_contract_version IS NOT NULL)
        OR (v_dispatch.dispatch_workload_role IS NOT NULL
            AND v_dispatch.dispatch_contract_version IS NULL)
        OR (v_dispatch.dispatch_workload_role IS NOT NULL
            AND v_dispatch.dispatch_workload_role IS DISTINCT FROM 'preflight')
        OR (v_dispatch.dispatch_contract_version IS NOT NULL
            AND v_dispatch.dispatch_contract_version IS DISTINCT FROM 2)
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_WORKLOAD_ROLE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    v_result := public.reserve_precheckout_blite_dispatch_v1(p_preflight_id);
    IF COALESCE((v_result->>'should_enqueue')::BOOLEAN, FALSE) THEN
        UPDATE public.precheckout_blite_dispatches AS dispatch
        SET dispatch_workload_role = 'preflight', dispatch_contract_version = 2
        WHERE dispatch.preflight_id = p_preflight_id
          AND dispatch.state = 'enqueuing'
          AND dispatch.dispatch_token = (v_result->>'dispatch_token')::UUID;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = 'PRECHECKOUT_BLITE_DISPATCH_FENCE_LOST', ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN v_result;
END;
$$;


--
-- Name: reserve_selfhosted_profile_request_start(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_selfhosted_profile_request_start(p_min_interval_ms integer, p_response_guard_ms integer, p_max_wait_ms integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_next_start_at TIMESTAMP WITH TIME ZONE;
    v_now TIMESTAMP WITH TIME ZONE;
    v_reserved_at TIMESTAMP WITH TIME ZONE;
    v_advanced_next_start_at TIMESTAMP WITH TIME ZONE;
    v_wait_ms BIGINT;
BEGIN
    IF p_min_interval_ms IS NULL
       OR p_min_interval_ms NOT BETWEEN 250 AND 60000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'SELFHOSTED_PROFILE_GLOBAL_GATE_INVALID_INTERVAL',
            ERRCODE = 'P0001';
    END IF;
    IF p_response_guard_ms IS NULL
       OR p_response_guard_ms NOT BETWEEN 50 AND 1000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'SELFHOSTED_PROFILE_GLOBAL_GATE_INVALID_RESPONSE_GUARD',
            ERRCODE = 'P0001';
    END IF;
    IF p_max_wait_ms IS NULL
       OR p_max_wait_ms NOT BETWEEN 0 AND 300000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'SELFHOSTED_PROFILE_GLOBAL_GATE_INVALID_MAX_WAIT',
            ERRCODE = 'P0001';
    END IF;

    SELECT gate.next_start_at
    INTO v_next_start_at
    FROM public.selfhosted_profile_request_start_gate AS gate
    WHERE gate.singleton IS TRUE
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'SELFHOSTED_PROFILE_GLOBAL_GATE_CORRUPT_STATE',
            ERRCODE = 'P0001';
    END IF;
    IF v_next_start_at IS NULL OR NOT pg_catalog.isfinite(v_next_start_at) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'SELFHOSTED_PROFILE_GLOBAL_GATE_CORRUPT_STATE',
            ERRCODE = 'P0001';
    END IF;

    v_now := pg_catalog.clock_timestamp();
    v_reserved_at := GREATEST(v_now, v_next_start_at);
    v_wait_ms := pg_catalog.ceil(
        pg_catalog.date_part('epoch', v_reserved_at - v_now) * 1000.0
    )::BIGINT;

    IF NOT pg_catalog.isfinite(v_reserved_at)
       OR v_wait_ms < 0 OR v_wait_ms > 300000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'SELFHOSTED_PROFILE_GLOBAL_GATE_WAIT_OUT_OF_RANGE',
            ERRCODE = 'P0001';
    END IF;
    IF v_wait_ms > p_max_wait_ms THEN
        RAISE EXCEPTION USING
            MESSAGE = 'SELFHOSTED_PROFILE_GLOBAL_GATE_CALLER_WAIT_EXCEEDED',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.selfhosted_profile_request_start_gate AS gate
    SET next_start_at = v_reserved_at + pg_catalog.make_interval(
        secs => (p_min_interval_ms + p_response_guard_ms)::DOUBLE PRECISION / 1000.0
    )
    WHERE gate.singleton IS TRUE
    RETURNING gate.next_start_at INTO v_advanced_next_start_at;

    IF NOT FOUND
       OR NOT pg_catalog.isfinite(v_advanced_next_start_at)
       OR v_advanced_next_start_at <= v_reserved_at THEN
        RAISE EXCEPTION USING
            MESSAGE = 'SELFHOSTED_PROFILE_GLOBAL_GATE_CORRUPT_STATE',
            ERRCODE = 'P0001';
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'schemaVersion', 1,
        'waitMs', v_wait_ms,
        'reservedAt', v_reserved_at
    );
END;
$$;


--
-- Name: reserve_vertex_ai_budget(text, text, text, text, integer, text, text, text, bigint, integer, numeric, date, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_vertex_ai_budget(p_reservation_key text, p_run_id text, p_order_id text, p_operation_key text, p_attempt integer, p_route text, p_model_name text, p_location text, p_input_tokens bigint, p_max_output_tokens integer, p_estimated_cost_usd numeric, p_day_key date DEFAULT NULL::date, p_per_run_limit_usd numeric DEFAULT 2.000000000000, p_per_order_limit_usd numeric DEFAULT 5.000000000000, p_daily_limit_usd numeric DEFAULT 100.000000000000) RETURNS TABLE(reservation_id uuid, reservation_key text, run_id text, order_id text, day_key date, route text, model_name text, attempt integer, estimated_cost_usd numeric, actual_cost_usd numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_existing public.vertex_ai_budget_reservations%ROWTYPE;
    v_run_id TEXT := NULLIF(pg_catalog.btrim(p_run_id), '');
    v_order_id TEXT := NULLIF(pg_catalog.btrim(p_order_id), '');
    v_operation_key TEXT := NULLIF(pg_catalog.btrim(p_operation_key), '');
    v_model_name TEXT := NULLIF(pg_catalog.btrim(p_model_name), '');
    v_location TEXT := COALESCE(NULLIF(pg_catalog.btrim(p_location), ''), 'global');
    v_day_key DATE := COALESCE(p_day_key, (pg_catalog.clock_timestamp() AT TIME ZONE 'UTC')::DATE);
    v_current NUMERIC;
BEGIN
    IF p_reservation_key IS NULL OR p_reservation_key !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,255}$'
       OR v_run_id IS NULL OR v_operation_key IS NULL
       OR p_attempt NOT BETWEEN 1 AND 4
       OR p_route NOT IN ('default', 'high_value', 'ambiguous')
       OR v_model_name IS NULL OR v_location IS NULL
       OR p_input_tokens IS NULL OR p_input_tokens < 0
       OR p_max_output_tokens IS NULL OR p_max_output_tokens NOT BETWEEN 1 AND 65536
       OR p_estimated_cost_usd IS NULL OR p_estimated_cost_usd <= 0
       OR p_estimated_cost_usd > 1000000
       OR p_estimated_cost_usd <> pg_catalog.round(p_estimated_cost_usd, 12)
       OR p_per_run_limit_usd IS NULL OR p_per_run_limit_usd <= 0
       OR p_per_run_limit_usd > 1000000
       OR p_per_run_limit_usd <> pg_catalog.round(p_per_run_limit_usd, 12)
       OR p_per_order_limit_usd IS NULL OR p_per_order_limit_usd <= 0
       OR p_per_order_limit_usd > 1000000
       OR p_per_order_limit_usd <> pg_catalog.round(p_per_order_limit_usd, 12)
       OR p_daily_limit_usd IS NULL OR p_daily_limit_usd <= 0
       OR p_daily_limit_usd > 1000000
       OR p_daily_limit_usd <> pg_catalog.round(p_daily_limit_usd, 12) THEN
        RAISE EXCEPTION 'VERTEX_AI_BUDGET_RESERVATION_INVALID';
    END IF;

    -- A request-scoped run ID is also the result_request_id for paid earlybird orders. Resolve
    -- that order here so all retries/stages share the order ceiling even when the worker fence
    -- carries no order field. Non-order requests intentionally fall back to run scope.
    IF v_order_id IS NULL
       AND v_run_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
        SELECT pg_catalog.lower(earlybird_order.id::TEXT)
          INTO v_order_id
          FROM public.earlybird_orders AS earlybird_order
         WHERE earlybird_order.result_request_id = v_run_id::UUID
         LIMIT 1;
    END IF;
    v_order_id := COALESCE(v_order_id, v_run_id);

    -- The shared advisory lock serializes all scope totals and the row lock makes recovery
    -- idempotent, avoiding races between different keys and duplicate retries.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('vertex-ai-budget:all-scopes', 0)
    );
    SELECT reservation.*
      INTO v_existing
      FROM public.vertex_ai_budget_reservations AS reservation
     WHERE reservation.reservation_key = p_reservation_key
     FOR UPDATE;
    IF FOUND THEN
        IF v_existing.run_id IS DISTINCT FROM v_run_id
           OR v_existing.order_id IS DISTINCT FROM v_order_id
           OR v_existing.operation_key IS DISTINCT FROM v_operation_key
           OR v_existing.attempt IS DISTINCT FROM p_attempt
           OR v_existing.route IS DISTINCT FROM p_route
           OR v_existing.model_name IS DISTINCT FROM v_model_name
           OR v_existing.model_location IS DISTINCT FROM v_location
           OR v_existing.input_tokens IS DISTINCT FROM p_input_tokens
           OR v_existing.max_output_tokens IS DISTINCT FROM p_max_output_tokens
           OR v_existing.estimated_cost_usd IS DISTINCT FROM p_estimated_cost_usd
           -- An omitted day is recovery metadata, not part of the attempt identity. This keeps
           -- reserved/settled work anchored to its original UTC day after a midnight retry;
           -- explicit day assertions still detect drift for every lifecycle state.
           OR p_day_key IS NOT NULL
              AND v_existing.day_key IS DISTINCT FROM v_day_key THEN
            RAISE EXCEPTION 'VERTEX_AI_BUDGET_RESERVATION_IDENTITY_DRIFT';
        END IF;
        -- A cancelled reservation never reached the provider. Permit the same deterministic
        -- attempt key to be admitted again after a pre-dispatch retry; active/settled rows remain
        -- fully idempotent and continue to return without another charge.
        IF v_existing.state <> 'cancelled' THEN
            RETURN QUERY SELECT
                v_existing.reservation_id, v_existing.reservation_key, v_existing.run_id,
                v_existing.order_id, v_existing.day_key, v_existing.route, v_existing.model_name,
                v_existing.attempt, v_existing.estimated_cost_usd, v_existing.actual_cost_usd;
            RETURN;
        END IF;
        DELETE FROM public.vertex_ai_budget_reservations AS reservation
         WHERE reservation.reservation_key = p_reservation_key;
    END IF;

    SELECT COALESCE(pg_catalog.sum(
        COALESCE(reservation.actual_cost_usd, reservation.estimated_cost_usd)
    ), 0)
      INTO v_current
      FROM public.vertex_ai_budget_reservations AS reservation
     WHERE reservation.run_id = v_run_id
       AND reservation.state IN ('reserved', 'settled');
    IF v_current + p_estimated_cost_usd > p_per_run_limit_usd THEN
        RAISE EXCEPTION 'VERTEX_AI_BUDGET_EXCEEDED:run:%', v_run_id;
    END IF;

    SELECT COALESCE(pg_catalog.sum(
        COALESCE(reservation.actual_cost_usd, reservation.estimated_cost_usd)
    ), 0)
      INTO v_current
      FROM public.vertex_ai_budget_reservations AS reservation
     WHERE reservation.order_id = v_order_id
       AND reservation.state IN ('reserved', 'settled');
    IF v_current + p_estimated_cost_usd > p_per_order_limit_usd THEN
        RAISE EXCEPTION 'VERTEX_AI_BUDGET_EXCEEDED:order:%', v_order_id;
    END IF;

    SELECT COALESCE(pg_catalog.sum(
        COALESCE(reservation.actual_cost_usd, reservation.estimated_cost_usd)
    ), 0)
      INTO v_current
      FROM public.vertex_ai_budget_reservations AS reservation
     WHERE reservation.day_key = v_day_key
       AND reservation.state IN ('reserved', 'settled');
    IF v_current + p_estimated_cost_usd > p_daily_limit_usd THEN
        RAISE EXCEPTION 'VERTEX_AI_BUDGET_EXCEEDED:day:%', v_day_key;
    END IF;

    RETURN QUERY INSERT INTO public.vertex_ai_budget_reservations (
        reservation_key, run_id, order_id, day_key, operation_key, attempt, route,
        model_name, model_location, input_tokens, max_output_tokens, estimated_cost_usd
    ) VALUES (
        p_reservation_key, v_run_id, v_order_id, v_day_key, v_operation_key, p_attempt, p_route,
        v_model_name, v_location, p_input_tokens, p_max_output_tokens,
        pg_catalog.round(p_estimated_cost_usd, 12)
    )
    RETURNING
        vertex_ai_budget_reservations.reservation_id,
        vertex_ai_budget_reservations.reservation_key,
        vertex_ai_budget_reservations.run_id,
        vertex_ai_budget_reservations.order_id,
        vertex_ai_budget_reservations.day_key,
        vertex_ai_budget_reservations.route,
        vertex_ai_budget_reservations.model_name,
        vertex_ai_budget_reservations.attempt,
        vertex_ai_budget_reservations.estimated_cost_usd,
        vertex_ai_budget_reservations.actual_cost_usd;
END;
$_$;


--
-- Name: resolve_analysis_preflight_provider_run_identity_drift(uuid, text, text, text, text, text, numeric, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_preflight_provider_run_identity_drift(p_preflight_id uuid, p_operation_key text, p_input_hash text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric, p_reserved_at timestamp with time zone, p_evidence_reference_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR p_operation_key IS DISTINCT FROM 'target-profile-fallback'
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_logical_provider IS DISTINCT FROM 'apify'
       OR p_actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS DISTINCT FROM 0.002600000000
       OR p_reserved_at IS NULL
       OR p_evidence_reference_hash IS NULL
       OR p_evidence_reference_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_IDENTITY_DRIFT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = p_operation_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.operation_key IS DISTINCT FROM p_operation_key
       OR v_run.input_hash IS DISTINCT FROM p_input_hash
       OR v_run.logical_provider IS DISTINCT FROM p_logical_provider
       OR v_run.actor_id IS DISTINCT FROM p_actor_id
       OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM p_max_charge_usd
       OR v_run.reserved_at IS DISTINCT FROM p_reserved_at THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_IDENTITY_DRIFT_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF v_preflight.user_id IS NOT NULL
       OR v_preflight.provider_selector IS DISTINCT FROM 'anonymous_apify'
       OR v_preflight.status IS DISTINCT FROM 'expired'
       OR v_preflight.pii_scrubbed_at IS NULL
       OR v_preflight.target_input_hash IS NULL
       OR v_run.input_hash IS NOT DISTINCT FROM v_preflight.target_input_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_IDENTITY_DRIFT_CANDIDATE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.analysis_preflight_failures AS failure
        WHERE failure.preflight_id = v_run.preflight_id
          AND failure.error_code = 'INTERNAL_ERROR'
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_IDENTITY_DRIFT_CANDIDATE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.status = 'resolved_identity_drift' THEN
        IF v_run.run_id IS NOT NULL
           OR v_run.run_started_at IS NOT NULL
           OR v_run.terminalized_at IS NULL
           OR v_run.actual_usage_usd IS DISTINCT FROM v_run.max_charge_usd
           OR v_run.usage_reconciled_at IS NULL
           OR v_run.usage_reconciliation_attempt_count IS DISTINCT FROM 0
           OR v_run.usage_reconciliation_attempted_at IS NOT NULL
           OR v_run.manual_resolution_evidence_hash IS DISTINCT FROM p_evidence_reference_hash
           OR v_run.manual_resolved_at IS NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PREFLIGHT_IDENTITY_DRIFT_RESOLUTION_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
    ELSE
        IF v_run.status IS DISTINCT FROM 'starting'
           OR v_run.run_id IS NOT NULL
           OR v_run.run_started_at IS NOT NULL
           OR v_run.terminalized_at IS NOT NULL
           OR v_run.actual_usage_usd IS NOT NULL
           OR v_run.usage_reconciled_at IS NOT NULL
           OR v_run.usage_reconciliation_attempt_count IS DISTINCT FROM 0
           OR v_run.usage_reconciliation_attempted_at IS NOT NULL
           OR v_run.manual_resolution_evidence_hash IS NOT NULL
           OR v_run.manual_resolved_at IS NOT NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PREFLIGHT_IDENTITY_DRIFT_STATE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;

        IF NOT (
            v_preflight.expires_at <= v_now - INTERVAL '7 days'
            AND v_preflight.updated_at <= v_now - INTERVAL '7 days'
            AND v_run.reserved_at <= v_now - INTERVAL '7 days'
            AND v_run.updated_at <= v_now - INTERVAL '7 days'
            AND (v_preflight.lease_expires_at IS NULL OR v_preflight.lease_expires_at <= v_now)
            AND (
                v_preflight.admission_lease_expires_at IS NULL
                OR v_preflight.admission_lease_expires_at <= v_now
            )
            AND NOT EXISTS (
                SELECT 1
                FROM public.analysis_provider_admission_leases AS admission
                WHERE admission.request_id = v_run.preflight_id
                  AND admission.logical_provider = v_run.logical_provider
                  AND admission.credential_slot = v_run.credential_slot
                  AND admission.state IN ('leased', 'recovery_required')
                  AND admission.expires_at > v_now
            )
        ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PREFLIGHT_IDENTITY_DRIFT_NOT_READY',
                ERRCODE = 'P0001';
        END IF;

        UPDATE public.analysis_preflight_provider_runs AS provider_run
        SET status = 'resolved_identity_drift',
            actual_usage_usd = v_run.max_charge_usd,
            terminalized_at = v_now,
            usage_reconciled_at = v_now,
            manual_resolution_evidence_hash = p_evidence_reference_hash,
            manual_resolved_at = v_now,
            updated_at = v_now
        WHERE provider_run.preflight_id = p_preflight_id
          AND provider_run.operation_key = p_operation_key
        RETURNING provider_run.* INTO v_run;
    END IF;

    PERFORM public.record_analysis_preflight_identity_drift_cost_event(
        v_run.preflight_id,
        v_run.operation_key,
        v_run.input_hash,
        v_run.logical_provider,
        v_run.actor_id,
        v_run.credential_slot,
        v_run.max_charge_usd,
        v_run.reserved_at,
        v_run.manual_resolution_evidence_hash,
        (v_run.manual_resolved_at AT TIME ZONE 'UTC')::DATE
    );
    RETURN public.analysis_preflight_provider_run_json(v_run);
END;
$_$;


--
-- Name: resolve_analysis_preflight_provider_run_no_run(uuid, text, text, text, text, text, numeric, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_preflight_provider_run_no_run(p_preflight_id uuid, p_operation_key text, p_input_hash text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric, p_reserved_at timestamp with time zone, p_evidence_reference_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_preflight public.analysis_preflights%ROWTYPE;
    v_run public.analysis_preflight_provider_runs%ROWTYPE;
BEGIN
    IF p_preflight_id IS NULL
       OR NOT (
            p_operation_key = 'target-profile-fallback'
            OR p_operation_key ~ '^target-profile-fresh-admission:g([1-9]|[1-9][0-9]|100)$'
       )
       OR p_input_hash IS NULL
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_logical_provider IS DISTINCT FROM 'apify'
       OR p_actor_id IS DISTINCT FROM 'apify/instagram-profile-scraper'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS DISTINCT FROM 0.002600000000
       OR p_reserved_at IS NULL
       OR p_evidence_reference_hash IS NULL
       OR p_evidence_reference_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_AMBIGUOUS_START_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.*
    INTO v_run
    FROM public.analysis_preflight_provider_runs AS provider_run
    WHERE provider_run.preflight_id = p_preflight_id
      AND provider_run.operation_key = p_operation_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_PROVIDER_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.input_hash IS DISTINCT FROM p_input_hash
       OR v_run.logical_provider IS DISTINCT FROM p_logical_provider
       OR v_run.actor_id IS DISTINCT FROM p_actor_id
       OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM p_max_charge_usd
       OR v_run.reserved_at IS DISTINCT FROM p_reserved_at THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_AMBIGUOUS_START_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    IF v_preflight.user_id IS NULL
       AND v_preflight.provider_selector = 'anonymous_apify'
       AND v_preflight.target_input_hash IS NOT NULL
       AND v_run.input_hash IS DISTINCT FROM v_preflight.target_input_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_PREFLIGHT_AMBIGUOUS_START_IDENTITY_DRIFT',
            ERRCODE = 'P0001';
    END IF;

    IF v_run.status = 'resolved_no_run' THEN
        IF v_run.run_id IS NOT NULL
           OR v_run.actual_usage_usd IS DISTINCT FROM 0
           OR v_run.manual_resolution_evidence_hash IS DISTINCT FROM p_evidence_reference_hash
           OR v_run.manual_resolved_at IS NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PREFLIGHT_AMBIGUOUS_START_RESOLUTION_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
    ELSE
        IF v_run.status IS DISTINCT FROM 'starting'
           OR v_run.run_id IS NOT NULL
           OR v_run.run_started_at IS NOT NULL
           OR v_run.terminalized_at IS NOT NULL
           OR v_run.actual_usage_usd IS NOT NULL
           OR v_run.usage_reconciled_at IS NOT NULL
           OR v_run.manual_resolution_evidence_hash IS NOT NULL
           OR v_run.manual_resolved_at IS NOT NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PREFLIGHT_AMBIGUOUS_START_STATE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        IF v_run.reserved_at > v_now - INTERVAL '30 minutes'
           OR v_run.updated_at > v_now - INTERVAL '30 minutes'
           OR v_preflight.expires_at > v_now
           OR (v_preflight.lease_expires_at IS NOT NULL AND v_preflight.lease_expires_at > v_now)
           OR (
                v_preflight.admission_lease_expires_at IS NOT NULL
                AND v_preflight.admission_lease_expires_at > v_now
           ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_PREFLIGHT_AMBIGUOUS_START_NOT_READY',
                ERRCODE = 'P0001';
        END IF;
        UPDATE public.analysis_preflight_provider_runs AS provider_run
        SET status = 'resolved_no_run',
            actual_usage_usd = 0,
            terminalized_at = v_now,
            usage_reconciled_at = v_now,
            manual_resolution_evidence_hash = p_evidence_reference_hash,
            manual_resolved_at = v_now,
            updated_at = v_now
        WHERE provider_run.preflight_id = p_preflight_id
          AND provider_run.operation_key = p_operation_key
        RETURNING provider_run.* INTO v_run;
    END IF;

    IF v_run.operation_key = 'target-profile-fallback' THEN
        PERFORM public.record_analysis_preflight_manual_no_run_cost_event(
            v_run.preflight_id, v_run.manual_resolution_evidence_hash,
            v_run.logical_provider, v_run.actor_id, v_run.credential_slot,
            (v_run.manual_resolved_at AT TIME ZONE 'UTC')::DATE
        );
    ELSE
        PERFORM public.record_analysis_preflight_manual_no_run_cost_event_for_operation(
            v_run.preflight_id, v_run.operation_key,
            v_run.manual_resolution_evidence_hash, v_run.logical_provider,
            v_run.actor_id, v_run.credential_slot,
            (v_run.manual_resolved_at AT TIME ZONE 'UTC')::DATE
        );
    END IF;
    RETURN public.analysis_preflight_provider_run_json(v_run);
END;
$_$;


--
-- Name: resolve_analysis_provider_admission(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_provider_admission(p_admission_id text, p_resolution_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_lease public.analysis_provider_admission_leases%ROWTYPE;
    v_ledger_state TEXT;
    v_source TEXT;
BEGIN
    IF p_admission_id IS NULL OR p_admission_id !~ '^[0-9a-f]{64}$'
       OR p_resolution_token IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT lease.* INTO v_lease
    FROM public.analysis_provider_admission_leases AS lease
    WHERE lease.admission_id = p_admission_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_lease.state = 'released' THEN
        RETURN pg_catalog.jsonb_build_object('resolved', FALSE);
    END IF;
    IF v_lease.state <> 'recovery_required' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_RESOLUTION_PENDING', ERRCODE = 'P0001';
    END IF;

    v_ledger_state := public.analysis_provider_admission_ledger_state(v_lease);
    IF v_ledger_state = 'identity_conflict' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_ledger_state = 'fenced_out' THEN
        IF v_lease.logical_provider <> 'gemini' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        v_source := 'gemini_lease_fenced';
    ELSIF v_ledger_state = 'missing' THEN
        -- Admission is acquired before the provider-run reserve callback.  An
        -- expired Apify row with no provider ledger therefore proves that no
        -- external start occurred and may be retired safely.  Gemini missing
        -- rows remain ambiguous because the slot fence is authoritative.
        IF v_lease.logical_provider <> 'apify' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_PROVIDER_ADMISSION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
        END IF;
        v_source := 'provider_ledger_absent';
    ELSIF v_ledger_state NOT IN ('terminal', 'available', 'quarantined') THEN
        RETURN pg_catalog.jsonb_build_object('resolved', FALSE);
    ELSE
        v_source := CASE
            WHEN v_lease.logical_provider = 'gemini' THEN 'gemini_lease_fenced'
            ELSE 'provider_ledger_terminal'
        END;
    END IF;
    UPDATE public.analysis_provider_admission_leases AS lease
    SET state = 'released', released_at = v_now,
        release_reason = 'ledger_resolved',
        resolution_source = v_source,
        resolution_token_hash = pg_catalog.encode(
            extensions.digest(
                pg_catalog.convert_to(p_resolution_token::TEXT, 'UTF8'), 'sha256'
            ), 'hex'
        ),
        updated_at = v_now
    WHERE lease.admission_id = p_admission_id
      AND lease.state = 'recovery_required';
    RETURN pg_catalog.jsonb_build_object('resolved', TRUE);
END;
$_$;


--
-- Name: resolve_analysis_v2_exact_recovery_provider_run(uuid, text, uuid, text, text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_v2_exact_recovery_provider_run(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_recovery RECORD;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_current_preflight public.analysis_preflights%ROWTYPE;
    v_recovery_preflight public.analysis_preflights%ROWTYPE;
    v_failed_request public.analysis_requests%ROWTYPE;
    v_source public.analysis_v2_provider_runs%ROWTYPE;
    v_existing public.analysis_v2_recovery_provider_run_adoptions%ROWTYPE;
BEGIN
    IF p_request_id IS NULL OR p_job_key IS NULL OR p_claim_token IS NULL
       OR NOT public.analysis_v2_valid_provider_operation_key(p_operation_key)
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_logical_provider NOT IN ('apify', 'coderx')
       OR p_actor_id IS NULL OR p_credential_slot IS NULL
       OR p_max_charge_usd IS NULL OR p_max_charge_usd NOT BETWEEN 0 AND 100000 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at <= v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request WHERE request.id = p_request_id;
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.result_request_id = p_request_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT recovery.* INTO v_recovery
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
    WHERE recovery.order_id = v_order.id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = v_recovery.order_id;
    SELECT preflight.* INTO v_current_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_request.preflight_id;
    SELECT preflight.* INTO v_recovery_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_recovery.recovery_preflight_id;
    SELECT failed_request.* INTO v_failed_request
    FROM public.analysis_requests AS failed_request
    WHERE failed_request.id = v_recovery.failed_request_id;
    IF v_request.pipeline_version <> 'v2'
       OR v_request.user_id IS DISTINCT FROM v_order.user_id
       OR v_request.target_instagram_id IS DISTINCT FROM v_order.target_instagram_id
       OR v_order.preflight_id IS DISTINCT FROM v_request.preflight_id
       OR v_order.result_request_id IS DISTINCT FROM p_request_id
       OR v_fulfillment.request_id IS DISTINCT FROM p_request_id
       OR v_order.status NOT IN ('analysis_in_progress', 'result_ready')
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_order.payment_id IS NULL
       OR v_order.actual_amount_krw IS NULL
       OR v_order.actual_amount_krw < 0
       OR v_order.actual_amount_krw > v_order.expected_amount_krw
       OR v_order.actual_groble_product_id
            IS DISTINCT FROM v_order.expected_groble_product_id
       OR v_failed_request.user_id IS DISTINCT FROM v_order.user_id
       OR (
            pg_catalog.lower(pg_catalog.btrim(v_failed_request.target_instagram_id))
                IS DISTINCT FROM
                pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id))
            AND v_failed_request.target_instagram_id IS DISTINCT FROM
                'retained.' || pg_catalog.substr(
                    pg_catalog.replace(v_failed_request.id::TEXT, '-', ''), 1, 20
                )
       )
       OR v_failed_request.status <> 'failed'
       OR v_failed_request.pipeline_version <> 'v2'
       OR NOT EXISTS (
            SELECT 1
            FROM public.analysis_v2_failure_receipts AS receipt
            WHERE receipt.request_id = v_failed_request.id
              AND receipt.error_code = v_failed_request.error_message
       )
       OR v_current_preflight.user_id IS DISTINCT FROM v_order.user_id
       OR v_current_preflight.access_mode <> 'production'
       OR v_current_preflight.consumed_request_id IS DISTINCT FROM p_request_id
       OR NOT (
            (
                v_current_preflight.id = v_recovery.recovery_preflight_id
                AND v_current_preflight.idempotency_key =
                    'earlybird.schema-recovery.'
                    || pg_catalog.replace(v_order.id::TEXT, '-', '')
            )
            OR v_current_preflight.idempotency_key ~
                ('^earlybird[.]fulfillment[.]'
                 || pg_catalog.replace(v_order.id::TEXT, '-', '')
                 || '([.]r[1-9])?$')
       )
       OR v_current_preflight.target_instagram_id
            IS DISTINCT FROM v_order.target_instagram_id       OR v_current_preflight.exclusion_decision
            IS DISTINCT FROM v_order.exclusion_decision
       OR v_current_preflight.excluded_instagram_id
            IS DISTINCT FROM v_order.excluded_instagram_id
       OR v_current_preflight.launch_status_snapshot
            IS DISTINCT FROM v_recovery_preflight.launch_status_snapshot
       OR v_current_preflight.plan_catalog_snapshot
            IS DISTINCT FROM v_recovery_preflight.plan_catalog_snapshot
       OR v_current_preflight.pricing_version
            IS DISTINCT FROM v_recovery_preflight.pricing_version
       OR v_current_preflight.pricing_snapshot
            IS DISTINCT FROM v_recovery_preflight.pricing_snapshot
       OR v_current_preflight.policy_versions_snapshot
            IS DISTINCT FROM v_recovery_preflight.policy_versions_snapshot
       OR v_recovery_preflight.user_id IS DISTINCT FROM v_order.user_id
       OR v_recovery_preflight.access_mode <> 'production'
       
       OR (
            NOT (
                v_recovery_preflight.idempotency_key =
                    'earlybird.schema-recovery.'
                    || pg_catalog.replace(v_order.id::TEXT, '-', '')
                AND (
                    (
                        v_current_preflight.id = v_recovery.recovery_preflight_id
                        AND v_current_preflight.idempotency_key =
                            'earlybird.schema-recovery.'
                            || pg_catalog.replace(v_order.id::TEXT, '-', '')
                    )
                    OR v_current_preflight.idempotency_key ~
                        ('^earlybird[.]fulfillment[.]'
                         || pg_catalog.replace(v_order.id::TEXT, '-', '')
                         || '([.]r[1-9])?$')
                )
            )
            AND NOT (
                public.earlybird_v211_relationship_lineage_rearm_ready(
                    v_order.id, v_recovery.failed_request_id,
                    v_recovery_preflight.id, v_current_preflight.id
                )
                OR public.earlybird_v211_concierge_replay_ready(
                    v_order.id, v_recovery.failed_request_id,
                    v_recovery_preflight.id, v_current_preflight.id
                )
                OR public.earlybird_v211_profile_ai_diagnostic_replay_ready(
                    v_order.id, v_recovery.failed_request_id,
                    v_recovery_preflight.id, v_current_preflight.id
                )
                OR public.earlybird_v211_policy_identity_replay_ready(
                    v_order.id, v_recovery.failed_request_id,
                    v_recovery_preflight.id, v_current_preflight.id
                )
            )
            AND (
                v_recovery_preflight.status <> 'expired'

       OR v_recovery_preflight.pii_scrubbed_at IS NULL
       OR v_recovery_preflight.pii_scrubbed_at < v_recovery_preflight.expires_at
       OR v_recovery_preflight.target_instagram_id IS DISTINCT FROM (
            'retained.' || pg_catalog.substr(
                pg_catalog.replace(v_recovery_preflight.id::TEXT, '-', ''), 1, 20
            )
       )
       OR v_recovery_preflight.target_full_name IS NOT NULL
       OR v_recovery_preflight.target_bio IS NOT NULL
       OR v_recovery_preflight.target_profile_image_url IS NOT NULL
       OR v_recovery_preflight.target_followers_count IS NOT NULL
       OR v_recovery_preflight.target_following_count IS NOT NULL
       OR v_recovery_preflight.target_is_private IS NOT NULL
       OR v_recovery_preflight.capacity_required_plan_id IS NOT NULL
       OR v_recovery_preflight.required_plan_id IS NOT NULL
       OR v_recovery_preflight.plan_cards_snapshot IS NOT NULL
       OR v_recovery_preflight.exclusion_decision <> 'skip'
       
       OR v_recovery_preflight.excluded_instagram_id IS NOT NULL
            )
       )
       OR NOT public.analysis_v2_valid_recovery_adoption_preflights
(
            v_order, v_recovery_preflight, v_current_preflight
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_LINEAGE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT source_run.* INTO v_source
    FROM public.analysis_v2_provider_runs AS source_run
    WHERE source_run.request_id = v_recovery.failed_request_id
      AND source_run.job_key = p_job_key
      AND source_run.operation_key = p_operation_key;
    IF NOT FOUND THEN
        IF public.earlybird_v211_concierge_replay_ready(
            v_order.id, v_recovery.failed_request_id,
            v_recovery_preflight.id, v_current_preflight.id
        ) OR public.earlybird_v211_profile_ai_diagnostic_replay_ready(
            v_order.id, v_recovery.failed_request_id,
            v_recovery_preflight.id, v_current_preflight.id
        ) OR public.earlybird_v211_policy_identity_replay_ready(
            v_order.id, v_recovery.failed_request_id,
            v_recovery_preflight.id, v_current_preflight.id
        ) THEN
            RETURN NULL;
        END IF;
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_SOURCE_UNAVAILABLE',
            ERRCODE = 'P0001';
    END IF;
    IF v_source.status <> 'succeeded'
       OR v_source.run_id IS NULL
       OR v_source.actual_usage_usd IS NULL
       OR v_source.usage_reconciled_at IS NULL THEN
        IF public.earlybird_v211_concierge_replay_ready(
            v_order.id, v_recovery.failed_request_id,
            v_recovery_preflight.id, v_current_preflight.id
        ) OR public.earlybird_v211_profile_ai_diagnostic_replay_ready(
            v_order.id, v_recovery.failed_request_id,
            v_recovery_preflight.id, v_current_preflight.id
        ) OR public.earlybird_v211_policy_identity_replay_ready(
            v_order.id, v_recovery.failed_request_id,
            v_recovery_preflight.id, v_current_preflight.id
        ) THEN
            RETURN NULL;
        END IF;
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_SOURCE_UNAVAILABLE',
            ERRCODE = 'P0001';
    END IF;
    IF v_source.input_hash IS DISTINCT FROM p_input_hash
       OR v_source.logical_provider IS DISTINCT FROM p_logical_provider
       OR v_source.actor_id IS DISTINCT FROM p_actor_id
       OR v_source.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_source.max_charge_usd IS DISTINCT FROM p_max_charge_usd THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_SOURCE_UNAVAILABLE',
            ERRCODE = 'P0001';
    END IF;

    SELECT adoption.* INTO v_existing
    FROM public.analysis_v2_recovery_provider_run_adoptions AS adoption
    WHERE adoption.request_id = p_request_id
      AND adoption.job_key = p_job_key
      AND adoption.operation_key = p_operation_key;
    IF FOUND AND (
        v_existing.source_request_id IS DISTINCT FROM v_source.request_id
        OR v_existing.source_job_key IS DISTINCT FROM v_source.job_key
        OR v_existing.source_run_id IS DISTINCT FROM v_source.run_id
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF NOT FOUND THEN
        INSERT INTO public.analysis_v2_recovery_provider_run_adoptions(
            request_id, job_key, operation_key,
            source_request_id, source_job_key, source_run_id
        ) VALUES (
            p_request_id, p_job_key, p_operation_key,
            v_source.request_id, v_source.job_key, v_source.run_id
        );
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'sourceRequestId', v_source.request_id,
        'sourceJobKey', v_source.job_key,
        'operationKey', v_source.operation_key,
        'inputHash', v_source.input_hash,
        'logicalProvider', v_source.logical_provider,
        'actorId', v_source.actor_id,
        'credentialSlot', v_source.credential_slot,
        'maxChargeUsd', v_source.max_charge_usd,
        'runId', v_source.run_id,
        'actualUsageUsd', v_source.actual_usage_usd,
        'usageReconciledAt', v_source.usage_reconciled_at
    );
END;
$_$;


--
-- Name: resolve_analysis_v2_gemini_lease_quarantine(integer, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_v2_gemini_lease_quarantine(p_slot integer, p_expected_fence bigint, p_evidence_hash text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    IF p_slot IS NULL OR p_slot NOT BETWEEN 1 AND 8
       OR p_expected_fence IS NULL OR p_expected_fence < 1
       OR p_evidence_hash IS NULL
       OR p_evidence_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_GEMINI_QUARANTINE_EVIDENCE_INVALID',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_v2_gemini_leases AS lease
    SET state = 'available',
        request_id = NULL,
        job_key = NULL,
        attempt = NULL,
        lease_claim_token = NULL,
        acquired_at = NULL,
        expires_at = NULL,
        quarantined_at = NULL,
        resolution_evidence_hash = p_evidence_hash,
        resolved_at = v_now,
        updated_at = v_now
    WHERE lease.slot = p_slot
      AND lease.state = 'quarantined'
      AND lease.fence = p_expected_fence;
    RETURN FOUND;
END;
$_$;


--
-- Name: resolve_analysis_v2_profile_provider_canary_adopt_run(uuid, integer, uuid, text, text, text, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_v2_profile_provider_canary_adopt_run(p_source_request_id uuid, p_repetition integer, p_reservation_token uuid, p_run_id text, p_actor_id text, p_actor_build text, p_credential_slot text, p_run_started_at timestamp with time zone, p_input_hmac text, p_evidence_reference_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_experiment public.analysis_v2_profile_provider_canary_experiments%ROWTYPE;
    v_run public.analysis_v2_profile_provider_canary_runs%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL OR p_repetition NOT IN (1, 2)
       OR p_reservation_token IS NULL OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_actor_id IS DISTINCT FROM 'apify/instagram-scraper'
       OR p_actor_build IS DISTINCT FROM '0.0.692'
       OR p_credential_slot IS DISTINCT FROM 'primary'
       OR p_run_started_at IS NULL
       OR p_input_hmac !~ '^[0-9a-f]{64}$'
       OR p_evidence_reference_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RESOLUTION_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT experiment.* INTO v_experiment
    FROM public.analysis_v2_profile_provider_canary_experiments AS experiment
    WHERE experiment.source_request_id = p_source_request_id
      AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
    FOR UPDATE;
    SELECT canary_run.* INTO v_run
    FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.repetition = p_repetition
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_run.reservation_token IS DISTINCT FROM p_reservation_token
       OR v_experiment.ordered_set_hmac IS DISTINCT FROM p_input_hmac
       OR p_run_started_at < v_run.reserved_at - INTERVAL '1 minute'
       OR p_run_started_at > v_run.ambiguous_at + INTERVAL '1 minute' THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RESOLUTION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_run.state = 'running' AND v_run.resolution_kind = 'adopted_run' THEN
        IF v_run.run_id IS DISTINCT FROM p_run_id
           OR v_run.resolution_evidence_hash IS DISTINCT FROM p_evidence_reference_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RESOLUTION_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_profile_provider_canary_run_json(v_run);
    END IF;
    IF v_run.state <> 'ambiguous' THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_v2_profile_provider_canary_runs AS canary_run
    SET state = 'running', run_id = p_run_id, run_started_at = p_run_started_at,
        cost_status = 'conservative', resolution_kind = 'adopted_run',
        resolution_evidence_hash = p_evidence_reference_hash,
        resolved_at = v_now, updated_at = v_now
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.repetition = p_repetition
    RETURNING canary_run.* INTO v_run;
    RETURN public.analysis_v2_profile_provider_canary_run_json(v_run);
END;
$_$;


--
-- Name: resolve_analysis_v2_profile_provider_canary_no_run(uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_v2_profile_provider_canary_no_run(p_source_request_id uuid, p_repetition integer, p_reservation_token uuid, p_evidence_reference_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_experiment public.analysis_v2_profile_provider_canary_experiments%ROWTYPE;
    v_run public.analysis_v2_profile_provider_canary_runs%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL OR p_repetition NOT IN (1, 2)
       OR p_reservation_token IS NULL
       OR p_evidence_reference_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RESOLUTION_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT experiment.* INTO v_experiment
    FROM public.analysis_v2_profile_provider_canary_experiments AS experiment
    WHERE experiment.source_request_id = p_source_request_id
      AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    SELECT canary_run.* INTO v_run
    FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.repetition = p_repetition
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_run.reservation_token IS DISTINCT FROM p_reservation_token THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RESOLUTION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_run.state = 'verified_no_run' THEN
        IF v_run.resolution_kind IS DISTINCT FROM 'verified_no_run'
           OR v_run.resolution_evidence_hash IS DISTINCT FROM p_evidence_reference_hash THEN
            RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RESOLUTION_CONFLICT', ERRCODE = 'P0001';
        END IF;
        IF (v_experiment.state = 'terminalizing'
                AND v_experiment.terminal_reason = 'verified_no_run')
           OR (v_experiment.state = 'experiment_terminal'
                AND v_experiment.terminal_reason = 'verified_no_run') THEN
            RETURN public.analysis_v2_profile_provider_canary_run_json(v_run);
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RESOLUTION_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_run.state <> 'ambiguous' THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_experiment.state <> 'active'
       OR v_experiment.ordered_set_hmac IS NULL
       OR v_experiment.terminal_reason IS NOT NULL
       OR v_experiment.cleanup_claim_token IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RESOLUTION_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF p_repetition = 1 AND EXISTS (
        SELECT 1 FROM public.analysis_v2_profile_provider_canary_runs AS later_run
        WHERE later_run.source_request_id = p_source_request_id
          AND later_run.canary_version = 'profile-fallback-replacement-canary-v1'
          AND later_run.repetition = 2
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RESOLUTION_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF p_repetition = 2 AND NOT EXISTS (
        SELECT 1 FROM public.analysis_v2_profile_provider_canary_runs AS first_run
        WHERE first_run.source_request_id = p_source_request_id
          AND first_run.canary_version = 'profile-fallback-replacement-canary-v1'
          AND first_run.repetition = 1
          AND first_run.state = 'succeeded'
          AND first_run.gate_passed = TRUE
          AND first_run.cost_status = 'actual'
          AND first_run.cleanup_completed_at IS NOT NULL
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RESOLUTION_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_v2_profile_provider_canary_runs AS canary_run
    SET state = 'verified_no_run', cost_status = 'actual', actual_usage_usd = 0,
        gate_passed = FALSE, kvs_cleanup_state = 'not_applicable',
        dataset_cleanup_state = 'not_applicable', request_queue_cleanup_state = 'not_applicable',
        kvs_cleaned_at = v_now, dataset_cleaned_at = v_now, request_queue_cleaned_at = v_now,
        resolution_kind = 'verified_no_run', resolution_evidence_hash = p_evidence_reference_hash,
        resolved_at = v_now, terminalized_at = v_now, usage_reconciled_at = v_now,
        cleanup_completed_at = v_now, updated_at = v_now
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.repetition = p_repetition
    RETURNING canary_run.* INTO v_run;
    UPDATE public.analysis_v2_profile_provider_canary_experiments AS experiment
    SET state = 'terminalizing', terminal_reason = 'verified_no_run',
        rep2_approval_deadline_at = NULL,
        cleanup_claim_token = p_reservation_token,
        cleanup_claimed_at = v_now, cleanup_lease_expires_at = v_now,
        updated_at = v_now
    WHERE experiment.source_request_id = p_source_request_id
      AND experiment.canary_version = 'profile-fallback-replacement-canary-v1'
      AND experiment.state = 'active'
    RETURNING experiment.* INTO v_experiment;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RESOLUTION_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    RETURN public.analysis_v2_profile_provider_canary_run_json(v_run);
END;
$_$;


--
-- Name: resolve_analysis_v2_provider_run_conservative_max_charge(uuid, text, text, text, uuid, uuid, text, text, text, text, numeric, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_v2_provider_run_conservative_max_charge(p_request_id uuid, p_job_key text, p_operation_key text, p_input_hash text, p_job_claim_token uuid, p_reservation_token uuid, p_run_id text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric, p_reserved_at timestamp with time zone, p_run_started_at timestamp with time zone, p_terminalized_at timestamp with time zone, p_status text, p_resolution_kind text, p_evidence_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_run public.analysis_v2_provider_runs%ROWTYPE;
    v_admission RECORD;
    v_child_state TEXT := 'absent';
    v_already_resolved BOOLEAN := FALSE;
    v_settlement JSONB;
    v_source_hash TEXT;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR p_operation_key IS NULL
       OR p_input_hash IS NULL
       OR p_job_claim_token IS NULL
       OR p_reservation_token IS NULL
       OR p_run_id IS NULL
       OR p_logical_provider IS NULL
       OR p_actor_id IS NULL
       OR p_credential_slot IS NULL
       OR p_max_charge_usd IS NULL
       OR p_reserved_at IS NULL
       OR p_run_started_at IS NULL
       OR p_terminalized_at IS NULL
       OR p_status IS NULL
       OR p_resolution_kind IS NULL
       OR p_evidence_hash IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_CONFLICT';
    END IF;

    IF p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR NOT public.analysis_v2_valid_provider_operation_key(p_operation_key)
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_run_id !~ '^[A-Za-z0-9:_-]+$'
       OR pg_catalog.length(p_run_id) NOT BETWEEN 8 AND 256
       OR p_actor_id !~ '^[A-Za-z0-9._:/-]+$'
       OR pg_catalog.length(p_actor_id) NOT BETWEEN 1 AND 256
       OR p_logical_provider IS DISTINCT FROM 'apify'
       OR p_credential_slot IS DISTINCT FROM 'tertiary'
       OR p_max_charge_usd <= 0
       OR p_status IS DISTINCT FROM 'succeeded'
       OR p_resolution_kind IS DISTINCT FROM 'conservative_max_charge'
       OR p_evidence_hash !~ '^[0-9a-f]{64}$'
       OR p_run_started_at < p_reserved_at
       OR p_terminalized_at < p_run_started_at
       OR p_terminalized_at > v_now - INTERVAL '7 days' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_CONFLICT';
    END IF;

    -- Stable lock order is request -> exact job -> exact provider row.
    SELECT * INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_NOT_READY';
    END IF;
    IF v_request.pipeline_version IS DISTINCT FROM 'v2' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_CONFLICT';
    END IF;

    SELECT * INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_NOT_READY';
    END IF;

    SELECT * INTO v_run
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = p_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_NOT_READY';
    END IF;

    IF v_run.input_hash IS DISTINCT FROM p_input_hash
       OR v_run.job_claim_token IS DISTINCT FROM p_job_claim_token
       OR v_run.reservation_token IS DISTINCT FROM p_reservation_token
       OR v_run.run_id IS DISTINCT FROM p_run_id
       OR v_run.logical_provider IS DISTINCT FROM p_logical_provider
       OR v_run.actor_id IS DISTINCT FROM p_actor_id
       OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM p_max_charge_usd
       OR v_run.reserved_at IS DISTINCT FROM p_reserved_at
       OR v_run.run_started_at IS DISTINCT FROM p_run_started_at
       OR v_run.terminalized_at IS DISTINCT FROM p_terminalized_at
       OR v_run.status IS DISTINCT FROM p_status THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_CONFLICT';
    END IF;

    IF (
           (v_request.processing_lease_token IS NULL AND v_request.processing_lease_expires_at IS NOT NULL)
           OR (v_request.processing_lease_token IS NOT NULL AND v_request.processing_lease_expires_at IS NULL)
           OR (v_request.processing_lease_token IS NOT NULL AND v_request.processing_lease_expires_at > v_now)
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_NOT_READY';
    END IF;
    IF (
           (v_job.lease_token IS NULL AND v_job.lease_expires_at IS NOT NULL)
           OR (v_job.lease_token IS NOT NULL AND v_job.lease_expires_at IS NULL)
           OR (v_job.lease_token IS NOT NULL AND v_job.lease_expires_at > v_now)
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_NOT_READY';
    END IF;

    FOR v_admission IN
        SELECT admission_id, state, expires_at
        FROM public.analysis_provider_admission_leases AS admission
        WHERE admission.request_id = p_request_id
          AND admission.job_key = p_job_key
          AND admission.operation_key = p_operation_key
          AND admission.logical_provider = p_logical_provider
          AND admission.credential_slot = p_credential_slot
        FOR UPDATE
    LOOP
        IF v_admission.state IN ('leased', 'recovery_required')
           AND (v_admission.expires_at IS NULL OR v_admission.expires_at > v_now) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_NOT_READY';
        END IF;
    END LOOP;

    IF v_run.manual_resolution_kind IS NOT NULL THEN
        IF v_run.manual_resolution_kind = 'conservative_max_charge'
           AND v_run.manual_resolution_evidence_hash = p_evidence_hash
           AND v_run.manual_resolved_at IS NOT NULL
           AND v_run.actual_usage_usd = v_run.max_charge_usd
           AND v_run.usage_reconciled_at IS NOT NULL THEN
            v_already_resolved := TRUE;
        ELSE
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_CONFLICT';
        END IF;
    ELSIF v_run.actual_usage_usd IS NOT NULL
          OR v_run.usage_reconciled_at IS NOT NULL
          OR v_run.manual_resolution_evidence_hash IS NOT NULL
          OR v_run.manual_resolved_at IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_CONFLICT';
    END IF;

    IF NOT v_already_resolved THEN
        UPDATE public.analysis_v2_provider_runs
        SET actual_usage_usd = max_charge_usd,
            usage_reconciled_at = v_now,
            manual_resolution_kind = 'conservative_max_charge',
            manual_resolution_evidence_hash = p_evidence_hash,
            manual_resolved_at = v_now,
            updated_at = v_now
        WHERE request_id = p_request_id
          AND job_key = p_job_key
          AND operation_key = p_operation_key
          AND actual_usage_usd IS NULL
          AND usage_reconciled_at IS NULL
          AND manual_resolution_kind IS NULL
          AND manual_resolution_evidence_hash IS NULL
          AND manual_resolved_at IS NULL
        RETURNING * INTO v_run;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_RESOLUTION_CONFLICT';
        END IF;
    END IF;

    v_source_hash := pg_catalog.encode(
        extensions.digest(pg_catalog.convert_to(p_operation_key, 'UTF8'), 'sha256'),
        'hex'
    );
    SELECT child.status
    INTO v_child_state
    FROM public.analysis_revenue_cost_operations AS child
    WHERE child.request_id = p_request_id
      AND child.owner_kind = 'provider_run'
      AND child.source_job_key = p_job_key
      AND child.source_operation_key_hash = v_source_hash
      AND child.source_attempt = 0
    FOR UPDATE;
    IF NOT FOUND THEN
        v_child_state := 'absent';
    ELSIF v_child_state NOT IN ('reserved', 'started', 'ambiguous', 'settled') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_SETTLEMENT_CONFLICT';
    END IF;

    IF v_child_state IN ('reserved', 'started', 'ambiguous', 'settled') THEN
        -- This is intentionally the newest authoritative settle RPC.  It
        -- validates the complete revenue lineage and sees the max charge only
        -- inside this transaction; any fence failure rolls back both writes.
        v_settlement := public.settle_analysis_revenue_cost_operation_v2(
            p_request_id, p_job_key, 'provider_run', p_operation_key, 0::SMALLINT
        );
        IF v_settlement->>'disposition' IS DISTINCT FROM 'settled' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CONSERVATIVE_SETTLEMENT_CONFLICT';
        END IF;
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'requestId', p_request_id,
        'jobKey', p_job_key,
        'operationKey', p_operation_key,
        'runId', p_run_id,
        'status', p_status,
        'actualUsageUsd', p_max_charge_usd,
        'manualResolutionKind', 'conservative_max_charge',
        'manualResolutionEvidenceHash', p_evidence_hash,
        'manualResolvedAt', v_run.manual_resolved_at,
        'revenueCostSettlement', CASE WHEN v_child_state = 'absent' THEN 'absent' ELSE 'settled' END,
        'replayed', v_already_resolved
    );
END;
$_$;


--
-- Name: resolve_analysis_v2_recovery_provider_run(uuid, text, uuid, text, text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_v2_recovery_provider_run(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_rearm RECORD;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
BEGIN
    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id;

    SELECT rearm.* INTO v_rearm
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, pfe_original_failed_request_id UUID, pfe2_rejected_successor_request_id UUID, media_failed_request_id UUID, rearmed_preflight_id UUID, prior_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'rearm'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_pfe3_media_artifact_rearms'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','pfe_original_failed_request_id','pfe2_rejected_successor_request_id','media_failed_request_id','rearmed_preflight_id','prior_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.pfe_original_failed_request_id IS NOT NULL AND decoded.pfe2_rejected_successor_request_id IS NOT NULL AND decoded.media_failed_request_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS rearm
    WHERE rearm.rearmed_preflight_id = v_request.preflight_id;

    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = v_rearm.order_id;

    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = v_rearm.order_id;

    -- Only the exact successor this rearm lineage produced short-circuits to
    -- NULL: the same order's preflight and result_request_id, and the same
    -- order's fulfillment request_id, must all still point at this exact
    -- p_request_id.
    IF v_request.id IS NOT NULL
       AND v_rearm.order_id IS NOT NULL
       AND v_order.id IS NOT NULL
       AND v_order.preflight_id = v_rearm.rearmed_preflight_id
       AND v_order.result_request_id = p_request_id
       AND v_fulfillment.order_id IS NOT NULL
       AND v_fulfillment.request_id = p_request_id
    THEN
        RETURN NULL;
    END IF;

    RETURN public.resolve_analysis_v2_recovery_provider_run_pre_pfe3(
        p_request_id, p_job_key, p_claim_token, p_operation_key, p_input_hash,
        p_logical_provider, p_actor_id, p_credential_slot, p_max_charge_usd
    );
END;
$$;


--
-- Name: resolve_analysis_v2_recovery_provider_run_first15(uuid, text, uuid, text, text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_v2_recovery_provider_run_first15(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_rearm public.earlybird_first15_canary_provider_rearms%ROWTYPE;
    v_source public.analysis_v2_provider_runs%ROWTYPE;
    v_existing public.analysis_v2_recovery_provider_run_adoptions%ROWTYPE;
    v_allow_replacement BOOLEAN := FALSE;
BEGIN
    IF p_request_id IS NULL OR p_job_key IS NULL OR p_claim_token IS NULL
       OR NOT public.analysis_v2_valid_provider_operation_key(p_operation_key)
       OR p_input_hash !~ '^[0-9a-f]{64}$'
       OR p_logical_provider <> 'apify'
       OR p_actor_id IS NULL
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS NULL OR p_max_charge_usd NOT BETWEEN 0 AND 100000
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_PROVIDER_ADOPTION_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id
    FOR UPDATE;
    SELECT rearm.* INTO v_rearm
    FROM public.earlybird_first15_canary_provider_rearms AS rearm
    WHERE rearm.rearmed_preflight_id = v_request.preflight_id
    FOR KEY SHARE;
    IF v_rearm.order_id IS NULL THEN RETURN NULL; END IF;
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = v_rearm.order_id
    FOR UPDATE;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = v_order.id
    FOR UPDATE;
    IF v_job.request_id IS NULL
       OR v_request.id IS NULL
       OR v_order.id IS NULL
       OR v_fulfillment.order_id IS NULL
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at <= v_now
       OR v_request.pipeline_version <> 'v2'
       OR v_request.status NOT IN ('pending', 'processing')
       OR v_order.result_request_id IS DISTINCT FROM v_request.id
       OR v_order.status <> 'analysis_in_progress'
       OR v_fulfillment.request_id IS DISTINCT FROM v_request.id
       OR v_fulfillment.status <> 'analysis_in_progress'
       OR v_order.concierge_apify_credential_slot
            IS DISTINCT FROM v_rearm.fallback_credential_slot
       OR p_credential_slot IS DISTINCT FROM v_rearm.fallback_credential_slot
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_PROVIDER_ADOPTION_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF v_rearm.source_failure_code = 'SCRAPING_PROVIDER_QUOTA_ERROR' THEN
        RETURN NULL;
    END IF;
    SELECT provider_run.* INTO v_source
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.request_id = v_rearm.source_request_id
      AND provider_run.job_key = p_job_key
      AND provider_run.operation_key = p_operation_key;
    IF NOT FOUND THEN RETURN NULL; END IF;
    IF v_source.status <> 'succeeded'
       OR v_source.run_id IS NULL
       OR v_source.actual_usage_usd IS NULL
       OR v_source.usage_reconciled_at IS NULL
       OR v_source.input_hash IS DISTINCT FROM p_input_hash
       OR v_source.logical_provider IS DISTINCT FROM p_logical_provider
       OR v_source.actor_id IS DISTINCT FROM p_actor_id
       OR v_source.credential_slot IS DISTINCT FROM v_rearm.source_credential_slot
       OR v_source.max_charge_usd IS DISTINCT FROM p_max_charge_usd
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_PROVIDER_ADOPTION_SOURCE_UNAVAILABLE',
            ERRCODE = 'P0001';
    END IF;
    SELECT adoption.* INTO v_existing
    FROM public.analysis_v2_recovery_provider_run_adoptions AS adoption
    WHERE adoption.request_id = p_request_id
      AND adoption.job_key = p_job_key
      AND adoption.operation_key = p_operation_key;
    IF FOUND AND (
        v_existing.destination_input_hash IS DISTINCT FROM p_input_hash
        OR v_existing.source_request_id IS DISTINCT FROM v_source.request_id
        OR v_existing.source_job_key IS DISTINCT FROM v_source.job_key
        OR v_existing.source_operation_key IS DISTINCT FROM v_source.operation_key
        OR v_existing.source_run_id IS DISTINCT FROM v_source.run_id
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FIRST15_PROVIDER_ADOPTION_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF NOT FOUND THEN
        INSERT INTO public.analysis_v2_recovery_provider_run_adoptions(
            request_id, job_key, operation_key, destination_input_hash,
            source_request_id, source_job_key, source_operation_key, source_run_id
        ) VALUES (
            p_request_id, p_job_key, p_operation_key, p_input_hash,
            v_source.request_id, v_source.job_key, v_source.operation_key, v_source.run_id
        );
    END IF;
    v_allow_replacement := v_rearm.source_failure_code = 'SCRAPING_INCOMPLETE_ERROR'
        AND p_job_key = 'track:relationships:collect';
    RETURN pg_catalog.jsonb_build_object(
        'sourceRequestId', v_source.request_id,
        'sourceJobKey', v_source.job_key,
        'operationKey', p_operation_key,
        'inputHash', p_input_hash,
        'logicalProvider', v_source.logical_provider,
        'actorId', v_source.actor_id,
        'credentialSlot', v_source.credential_slot,
        'maxChargeUsd', v_source.max_charge_usd,
        'runId', v_source.run_id,
        'actualUsageUsd', v_source.actual_usage_usd,
        'usageReconciledAt', v_source.usage_reconciled_at
    ) || CASE WHEN v_allow_replacement THEN
        pg_catalog.jsonb_build_object('allowRelationshipIncompleteReplacement', TRUE)
    ELSE '{}'::JSONB END;
END;
$_$;


--
-- Name: resolve_analysis_v2_recovery_provider_run_pre_first15(uuid, text, uuid, text, text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_v2_recovery_provider_run_pre_first15(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_exact JSONB;
    v_exact_source_unavailable BOOLEAN := FALSE;
    v_order public.earlybird_orders%ROWTYPE;
    v_recovery RECORD;
    v_request public.analysis_requests%ROWTYPE;
    v_failed_request public.analysis_requests%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_current public.analysis_preflights%ROWTYPE;
    v_recovery_preflight public.analysis_preflights%ROWTYPE;
    v_source_preflight public.analysis_preflights%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_source public.analysis_v2_provider_runs%ROWTYPE;
    v_existing public.analysis_v2_recovery_provider_run_adoptions%ROWTYPE;
    v_side TEXT;
    v_current_count INTEGER;
    v_source_count INTEGER;
    v_replacement BOOLEAN;
    v_current_operation TEXT;
    v_current_input TEXT;
    v_source_operation TEXT;
    v_source_input TEXT;
    v_initial_source_operation TEXT;
    v_initial_source_input TEXT;
BEGIN
    BEGIN
        v_exact := public.resolve_analysis_v2_exact_recovery_provider_run(
            p_request_id, p_job_key, p_claim_token, p_operation_key, p_input_hash,
            p_logical_provider, p_actor_id, p_credential_slot, p_max_charge_usd
        );
        RETURN v_exact;
    EXCEPTION
        WHEN SQLSTATE 'P0001' THEN
            IF SQLERRM <> 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_SOURCE_UNAVAILABLE' THEN
                RAISE;
            END IF;
            v_exact_source_unavailable := TRUE;
    END;

    IF NOT v_exact_source_unavailable
       OR p_job_key <> 'track:relationships:collect'
       OR p_logical_provider <> 'apify'
       OR p_actor_id <>
            'scraping_solutions/instagram-scraper-followers-following-no-cookies' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_SOURCE_UNAVAILABLE',
            ERRCODE = 'P0001';
    END IF;

    -- The exact resolver's failed subtransaction released its row lock. Re-lock
    -- and revalidate the live claim before any cross-identity mutation.
    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_FENCE_MISMATCH',
            ERRCODE = 'P0001';
    END IF;

    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id
    FOR UPDATE;
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.result_request_id = p_request_id
    FOR UPDATE;
    SELECT recovery.* INTO v_recovery
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_schema_failure_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
    WHERE recovery.order_id = v_order.id
    FOR UPDATE;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = v_order.id
    FOR UPDATE;
    SELECT preflight.* INTO v_current
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_order.preflight_id
    FOR UPDATE;
    SELECT preflight.* INTO v_recovery_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_recovery.recovery_preflight_id
    FOR UPDATE;
    SELECT request.* INTO v_failed_request
    FROM public.analysis_requests AS request
    WHERE request.id = v_recovery.failed_request_id
    FOR UPDATE;
    SELECT preflight.* INTO v_source_preflight FROM public.analysis_preflights AS preflight WHERE preflight.id = v_failed_request.preflight_id FOR UPDATE;

    -- Repeat every mutable lineage fence after reacquiring canonical row locks;
    -- the caught exact-resolver subtransaction intentionally released its locks.
    IF v_request.pipeline_version <> 'v2'
       OR v_request.user_id IS DISTINCT FROM v_order.user_id
       OR v_request.target_instagram_id IS DISTINCT FROM v_order.target_instagram_id
       OR v_request.preflight_id IS DISTINCT FROM v_current.id
       OR v_order.result_request_id IS DISTINCT FROM p_request_id
       OR v_fulfillment.request_id IS DISTINCT FROM p_request_id
       OR v_order.status NOT IN ('analysis_in_progress', 'result_ready')
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_order.payment_id IS NULL
       OR v_order.actual_amount_krw IS NULL
       OR v_order.actual_amount_krw < 0
       OR v_order.actual_amount_krw > v_order.expected_amount_krw
       OR v_order.actual_groble_product_id
            IS DISTINCT FROM v_order.expected_groble_product_id
       OR v_failed_request.user_id IS DISTINCT FROM v_order.user_id
       OR (
            pg_catalog.lower(pg_catalog.btrim(v_failed_request.target_instagram_id))
                IS DISTINCT FROM
                pg_catalog.lower(pg_catalog.btrim(v_order.target_instagram_id))
            AND v_failed_request.target_instagram_id IS DISTINCT FROM (
                'retained.' || pg_catalog.substr(
                    pg_catalog.replace(v_failed_request.id::TEXT, '-', ''), 1, 20
                )
            )
       )
       OR v_failed_request.status <> 'failed'
       OR v_failed_request.pipeline_version <> 'v2'
       OR NOT EXISTS (
            SELECT 1 FROM public.analysis_v2_failure_receipts AS receipt
            WHERE receipt.request_id = v_failed_request.id
              AND receipt.error_code = v_failed_request.error_message
       )
       OR v_current.user_id IS DISTINCT FROM v_order.user_id
       OR v_current.access_mode <> 'production'
       OR v_current.consumed_request_id IS DISTINCT FROM p_request_id
       OR NOT (
            (
                v_current.id = v_recovery.recovery_preflight_id
                AND v_current.idempotency_key =
                    'earlybird.schema-recovery.'
                    || pg_catalog.replace(v_order.id::TEXT, '-', '')
            )
            OR v_current.idempotency_key ~ (
                '^earlybird[.]fulfillment[.]'
                || pg_catalog.replace(v_order.id::TEXT, '-', '')
                || '([.]r[1-9])?$'
            )
       )
       OR v_current.target_instagram_id IS DISTINCT FROM v_order.target_instagram_id
       OR v_current.exclusion_decision IS DISTINCT FROM v_order.exclusion_decision
       OR v_current.excluded_instagram_id IS DISTINCT FROM v_order.excluded_instagram_id
       OR v_current.launch_status_snapshot
            IS DISTINCT FROM v_recovery_preflight.launch_status_snapshot
       OR v_current.plan_catalog_snapshot
            IS DISTINCT FROM v_recovery_preflight.plan_catalog_snapshot
       OR v_current.pricing_version IS DISTINCT FROM v_recovery_preflight.pricing_version
       OR v_current.pricing_snapshot IS DISTINCT FROM v_recovery_preflight.pricing_snapshot
       OR v_current.policy_versions_snapshot
            IS DISTINCT FROM v_recovery_preflight.policy_versions_snapshot
       OR v_recovery_preflight.user_id IS DISTINCT FROM v_order.user_id
       OR v_recovery_preflight.access_mode <> 'production'
       OR NOT public.analysis_v2_valid_recovery_adoption_preflights(
            v_order, v_recovery_preflight, v_current
       )
       OR NOT public.analysis_v2_valid_source_adoption_preflights(
            v_order, v_recovery_preflight, v_source_preflight, v_current,
            v_failed_request.id, p_request_id
       )
       OR v_source_preflight.id IS DISTINCT FROM v_failed_request.preflight_id
       OR v_source_preflight.user_id IS DISTINCT FROM v_order.user_id
       OR v_source_preflight.access_mode <> 'production'
       OR v_source_preflight.status <> 'consumed'
       OR v_source_preflight.consumed_request_id IS DISTINCT FROM v_failed_request.id
       OR v_source_preflight.admission_status <> 'ready'
       OR v_source_preflight.admission_selected_plan_id IS DISTINCT FROM v_order.plan_id
       OR v_source_preflight.admission_target_followers_count IS NULL OR v_source_preflight.admission_target_followers_count < 0
       OR v_source_preflight.admission_target_following_count IS NULL OR v_source_preflight.admission_target_following_count < 0 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_LINEAGE_CONFLICT', 
            ERRCODE = 'P0001';
    END IF;

    FOR v_side, v_replacement IN
        SELECT candidate.side, candidate.replacement
        FROM (VALUES
            ('followers'::TEXT, FALSE), ('followers'::TEXT, TRUE),
            ('following'::TEXT, FALSE), ('following'::TEXT, TRUE)
        ) AS candidate(side, replacement)
    LOOP
        v_current_count := CASE v_side
            WHEN 'followers' THEN v_current.target_followers_count
            ELSE v_current.target_following_count
        END;
        SELECT identity.operation_key, identity.input_hash
        INTO v_current_operation, v_current_input
        FROM public.analysis_v2_relationship_provider_identity(
            v_side, v_order.target_instagram_id, v_current_count,
            v_order.plan_id, v_replacement
        ) AS identity;
        EXIT WHEN v_current_operation = p_operation_key
              AND v_current_input = p_input_hash;
        v_side := NULL;
    END LOOP;
    IF v_side IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_SOURCE_UNAVAILABLE',
            ERRCODE = 'P0001';
    END IF;

    -- The paid order freezes the old/source counts. 03000 admits a later,
    -- capacity-safe fresh count on the current preflight without mutating them.
    v_source_count := CASE v_side
        WHEN 'followers' THEN v_source_preflight.admission_target_followers_count
        ELSE v_source_preflight.admission_target_following_count
    END;
    IF v_source_count = v_current_count THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_SOURCE_UNAVAILABLE',
            ERRCODE = 'P0001';
    END IF;
    SELECT identity.operation_key, identity.input_hash
    INTO v_source_operation, v_source_input
    FROM public.analysis_v2_relationship_provider_identity(
        v_side, v_order.target_instagram_id, v_source_count,
        v_order.plan_id, v_replacement
    ) AS identity;
    SELECT source_run.* INTO STRICT v_source
    FROM public.analysis_v2_provider_runs AS source_run
    WHERE source_run.request_id = v_recovery.failed_request_id
      AND source_run.job_key = p_job_key
      AND source_run.operation_key = v_source_operation
      AND source_run.input_hash = v_source_input
      AND source_run.status = 'succeeded'
      AND source_run.run_id IS NOT NULL
      AND source_run.actual_usage_usd IS NOT NULL
      AND source_run.usage_reconciled_at IS NOT NULL
      AND source_run.logical_provider = p_logical_provider
      AND source_run.actor_id = p_actor_id
      AND source_run.credential_slot = p_credential_slot
      AND source_run.actual_usage_usd <= source_run.max_charge_usd + 0.000000001
      AND source_run.actual_usage_usd <= p_max_charge_usd + 0.000000001;

    IF v_replacement THEN
        SELECT identity.operation_key, identity.input_hash
        INTO v_initial_source_operation, v_initial_source_input
        FROM public.analysis_v2_relationship_provider_identity(
            v_side, v_order.target_instagram_id, v_source_count,
            v_order.plan_id, FALSE
        ) AS identity;
        IF NOT EXISTS (
            SELECT 1
            FROM public.analysis_v2_provider_runs AS initial_run
            WHERE initial_run.request_id = v_recovery.failed_request_id
              AND initial_run.job_key = p_job_key
              AND initial_run.operation_key = v_initial_source_operation
              AND initial_run.input_hash = v_initial_source_input
              AND initial_run.status = 'succeeded'
              AND initial_run.run_id IS NOT NULL
              AND initial_run.actual_usage_usd IS NOT NULL
              AND initial_run.usage_reconciled_at IS NOT NULL
              AND initial_run.logical_provider = p_logical_provider
              AND initial_run.actor_id = p_actor_id
              AND initial_run.credential_slot = p_credential_slot
              AND initial_run.actual_usage_usd <= initial_run.max_charge_usd + 0.000000001
              AND initial_run.actual_usage_usd <= p_max_charge_usd + 0.000000001
        ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_SOURCE_UNAVAILABLE',
                ERRCODE = 'P0001';
        END IF;
    END IF;

    SELECT adoption.* INTO v_existing
    FROM public.analysis_v2_recovery_provider_run_adoptions AS adoption
    WHERE adoption.request_id = p_request_id
      AND adoption.job_key = p_job_key
      AND adoption.operation_key = p_operation_key;
    IF FOUND AND (
        v_existing.destination_input_hash IS DISTINCT FROM p_input_hash
        OR v_existing.source_request_id IS DISTINCT FROM v_source.request_id
        OR v_existing.source_job_key IS DISTINCT FROM v_source.job_key
        OR v_existing.source_operation_key IS DISTINCT FROM v_source.operation_key
        OR v_existing.source_run_id IS DISTINCT FROM v_source.run_id
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF NOT FOUND THEN
        INSERT INTO public.analysis_v2_recovery_provider_run_adoptions(
            request_id, job_key, operation_key, destination_input_hash,
            source_request_id, source_job_key, source_operation_key, source_run_id
        ) VALUES (
            p_request_id, p_job_key, p_operation_key, p_input_hash,
            v_source.request_id, v_source.job_key, v_source.operation_key, v_source.run_id
        );
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'sourceRequestId', v_source.request_id,
        'sourceJobKey', v_source.job_key,
        'operationKey', p_operation_key,
        'inputHash', p_input_hash,
        'logicalProvider', v_source.logical_provider,
        'actorId', v_source.actor_id,
        'credentialSlot', v_source.credential_slot,
        'maxChargeUsd', v_source.max_charge_usd,
        'runId', v_source.run_id,
        'actualUsageUsd', v_source.actual_usage_usd,
        'usageReconciledAt', v_source.usage_reconciled_at,
        'relationshipSourceDeclaredCount', v_source_count
    );
EXCEPTION
    WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_ADOPTION_SOURCE_UNAVAILABLE',
            ERRCODE = 'P0001';
END;
$_$;


--
-- Name: resolve_analysis_v2_recovery_provider_run_pre_pfe(uuid, text, uuid, text, text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_v2_recovery_provider_run_pre_pfe(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_existing JSONB;
BEGIN
    v_existing := public.resolve_analysis_v2_recovery_provider_run_pre_first15(
        p_request_id, p_job_key, p_claim_token, p_operation_key, p_input_hash,
        p_logical_provider, p_actor_id, p_credential_slot, p_max_charge_usd
    );
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
    RETURN public.resolve_analysis_v2_recovery_provider_run_first15(
        p_request_id, p_job_key, p_claim_token, p_operation_key, p_input_hash,
        p_logical_provider, p_actor_id, p_credential_slot, p_max_charge_usd
    );
END;
$$;


--
-- Name: resolve_analysis_v2_recovery_provider_run_pre_pfe2(uuid, text, uuid, text, text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_v2_recovery_provider_run_pre_pfe2(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_recovery RECORD;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
BEGIN
    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id;

    SELECT recovery.* INTO v_recovery
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, failed_request_id UUID, recovery_preflight_id UUID, prior_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_profile_fetch_exhaustion_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','failed_request_id','recovery_preflight_id','prior_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.failed_request_id IS NOT NULL AND decoded.recovery_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS recovery
    WHERE recovery.recovery_preflight_id = v_request.preflight_id;

    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = v_recovery.order_id;

    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = v_recovery.order_id;

    -- Only the exact successor this recovery lineage produced short-circuits
    -- to NULL: the same order's preflight and result_request_id, and the
    -- same order's fulfillment request_id, must all still point at this
    -- exact p_request_id.
    IF v_request.id IS NOT NULL
       AND v_recovery.order_id IS NOT NULL
       AND v_order.id IS NOT NULL
       AND v_order.preflight_id = v_recovery.recovery_preflight_id
       AND v_order.result_request_id = p_request_id
       AND v_fulfillment.order_id IS NOT NULL
       AND v_fulfillment.request_id = p_request_id
    THEN
        RETURN NULL;
    END IF;

    RETURN public.resolve_analysis_v2_recovery_provider_run_pre_pfe(
        p_request_id, p_job_key, p_claim_token, p_operation_key, p_input_hash,
        p_logical_provider, p_actor_id, p_credential_slot, p_max_charge_usd
    );
END;
$$;


--
-- Name: resolve_analysis_v2_recovery_provider_run_pre_pfe3(uuid, text, uuid, text, text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_analysis_v2_recovery_provider_run_pre_pfe3(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_input_hash text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_request public.analysis_requests%ROWTYPE;
    v_rearm RECORD;
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
BEGIN
    SELECT request.* INTO v_request
    FROM public.analysis_requests AS request
    WHERE request.id = p_request_id;

    SELECT rearm.* INTO v_rearm
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, pfe_original_failed_request_id UUID, rejected_successor_request_id UUID, rearmed_preflight_id UUID, prior_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'rearm'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_pfe_target_evidence_start_rejection_rearms'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','pfe_original_failed_request_id','rejected_successor_request_id','rearmed_preflight_id','prior_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.pfe_original_failed_request_id IS NOT NULL AND decoded.rejected_successor_request_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.prior_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS rearm
    WHERE rearm.rearmed_preflight_id = v_request.preflight_id;

    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = v_rearm.order_id;

    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = v_rearm.order_id;

    -- Only the exact successor this rearm lineage produced short-circuits to
    -- NULL: the same order's preflight and result_request_id, and the same
    -- order's fulfillment request_id, must all still point at this exact
    -- p_request_id.
    IF v_request.id IS NOT NULL
       AND v_rearm.order_id IS NOT NULL
       AND v_order.id IS NOT NULL
       AND v_order.preflight_id = v_rearm.rearmed_preflight_id
       AND v_order.result_request_id = p_request_id
       AND v_fulfillment.order_id IS NOT NULL
       AND v_fulfillment.request_id = p_request_id
    THEN
        RETURN NULL;
    END IF;

    RETURN public.resolve_analysis_v2_recovery_provider_run_pre_pfe2(
        p_request_id, p_job_key, p_claim_token, p_operation_key, p_input_hash,
        p_logical_provider, p_actor_id, p_credential_slot, p_max_charge_usd
    );
END;
$$;


--
-- Name: restore_earlybird_concierge_snapshot_conflict_cancelled_branche(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_earlybird_concierge_snapshot_conflict_cancelled_branche(p_order_id uuid, p_preflight_id uuid, p_request_id uuid, p_expected_manual_review_at timestamp with time zone, p_expected_admission_refreshed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_order public.earlybird_orders%ROWTYPE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_request public.analysis_requests%ROWTYPE;
    v_recovery RECORD;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
BEGIN
    SELECT * INTO v_order FROM public.earlybird_orders WHERE id = p_order_id FOR UPDATE;
    SELECT * INTO v_preflight FROM public.analysis_preflights WHERE id = p_preflight_id FOR UPDATE;
    SELECT * INTO v_fulfillment FROM public.earlybird_fulfillments WHERE order_id = p_order_id FOR UPDATE;
    SELECT * INTO v_request FROM public.analysis_requests WHERE id = p_request_id FOR UPDATE;
    SELECT * INTO v_recovery
    
FROM LATERAL (
    SELECT decoded.*
    FROM public.maintenance_jobs AS archive_source
    CROSS JOIN LATERAL pg_catalog.jsonb_to_record(
        archive_source.payload->'legacy_row'
    ) AS decoded(order_id UUID, preflight_id UUID, provider_operation_key TEXT, provider_input_hash VARCHAR(64), provider_run_id_hash VARCHAR(32), expected_manual_review_at TIMESTAMPTZ, expected_admission_refreshed_at TIMESTAMPTZ, old_order_followers_count INTEGER, old_order_following_count INTEGER, old_preflight_followers_count INTEGER, old_preflight_following_count INTEGER, new_witness_followers_count INTEGER, new_witness_following_count INTEGER, old_snapshot_recorded_at TIMESTAMPTZ, new_witness_recorded_at TIMESTAMPTZ, recovery_reason TEXT, followers_absolute_delta INTEGER, following_absolute_delta INTEGER, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'recovery'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_concierge_snapshot_conflict_recoveries'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','preflight_id','provider_operation_key','provider_input_hash','provider_run_id_hash','expected_manual_review_at','expected_admission_refreshed_at','old_order_followers_count','old_order_following_count','old_preflight_followers_count','old_preflight_following_count','new_witness_followers_count','new_witness_following_count','old_snapshot_recorded_at','new_witness_recorded_at','recovery_reason','followers_absolute_delta','following_absolute_delta','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.preflight_id IS NOT NULL AND decoded.provider_operation_key IS NOT NULL AND decoded.provider_input_hash IS NOT NULL AND decoded.provider_run_id_hash IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.expected_admission_refreshed_at IS NOT NULL AND decoded.old_order_followers_count IS NOT NULL AND decoded.old_order_following_count IS NOT NULL AND decoded.old_preflight_followers_count IS NOT NULL AND decoded.old_preflight_following_count IS NOT NULL AND decoded.new_witness_followers_count IS NOT NULL AND decoded.new_witness_following_count IS NOT NULL AND decoded.old_snapshot_recorded_at IS NOT NULL AND decoded.new_witness_recorded_at IS NOT NULL AND decoded.recovery_reason IS NOT NULL AND decoded.followers_absolute_delta IS NOT NULL AND decoded.following_absolute_delta IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS legacy_receipt_row
    WHERE order_id = p_order_id AND preflight_id = p_preflight_id
    FOR UPDATE;
    IF v_order.id IS NULL
       OR v_preflight.id IS NULL
       OR v_fulfillment.order_id IS NULL
       OR v_request.id IS NULL
       OR v_recovery.order_id IS NULL
       OR v_order.preflight_id IS DISTINCT FROM p_preflight_id
       OR v_order.result_request_id IS DISTINCT FROM p_request_id
       OR v_preflight.consumed_request_id IS DISTINCT FROM p_request_id
       OR v_request.preflight_id IS DISTINCT FROM p_preflight_id
       OR v_request.status IS DISTINCT FROM 'processing'
       OR v_order.status IS DISTINCT FROM 'analysis_in_progress'
       OR v_fulfillment.status IS DISTINCT FROM 'analysis_in_progress'
       OR v_recovery.expected_manual_review_at IS DISTINCT FROM p_expected_manual_review_at
       OR v_recovery.expected_admission_refreshed_at IS DISTINCT FROM p_expected_admission_refreshed_at
       OR v_preflight.admission_refreshed_at IS DISTINCT FROM p_expected_admission_refreshed_at
       OR EXISTS (
            SELECT 1 FROM public.earlybird_webhook_events
            WHERE payment_id = v_order.payment_id AND event_type = 'payment.refunded'
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_SNAPSHOT_RESTORE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    SELECT * INTO v_job
    FROM public.analysis_pipeline_jobs
    WHERE request_id = p_request_id AND job_key = 'track:target-evidence:collect'
    FOR UPDATE;
    IF v_job.status NOT IN ('pending', 'processing') THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_SNAPSHOT_RESTORE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_requests
    SET target_instagram_id = v_order.target_instagram_id,
        excluded_instagram_id = v_order.excluded_instagram_id,
        exclusion_decision_snapshot = v_order.exclusion_decision
    WHERE id = p_request_id;
    UPDATE public.analysis_preflights
    SET target_instagram_id = v_order.target_instagram_id,
        excluded_instagram_id = v_order.excluded_instagram_id,
        exclusion_decision = v_order.exclusion_decision
    WHERE id = p_preflight_id;
    IF EXISTS (
        SELECT 1 FROM public.analysis_pipeline_jobs
        WHERE request_id = p_request_id
          AND job_key IN ('track:profiles:batch:0', 'track:profile-ai:batch:1')
          AND status NOT IN ('pending', 'processing', 'cancelled')
    ) THEN
        RAISE EXCEPTION USING MESSAGE = 'CONCIERGE_SNAPSHOT_RESTORE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_pipeline_jobs
    SET status = 'cancelled',
        dispatch_state = 'reserved',
        dispatch_generation = dispatch_generation + 1,
        dispatch_reservation_token = extensions.gen_random_uuid(),
        dispatch_reserved_at = pg_catalog.clock_timestamp(),
        dispatched_at = NULL,
        dispatch_task_name = NULL,
        delivered_at = NULL,
        lease_token = NULL,
        lease_expires_at = NULL,
        completion_token = NULL,
        completion_fanout_hash = NULL,
        last_error_code = CASE job_key
            WHEN 'track:profiles:batch:0' THEN 'PROFILE_FETCH_PERSISTENCE_ERROR'
            ELSE 'REQUEST_TERMINATED'
        END,
        last_error_at = pg_catalog.clock_timestamp(),
        completed_at = pg_catalog.clock_timestamp(),
        updated_at = pg_catalog.clock_timestamp()
    WHERE request_id = p_request_id
      AND job_key IN ('track:profiles:batch:0', 'track:profile-ai:batch:1')
      AND status IN ('pending', 'processing');
    UPDATE public.analysis_v2_provider_runs
    SET status = 'starting',
        reservation_token = extensions.gen_random_uuid(),
        terminalized_at = NULL,
        actual_usage_usd = NULL,
        usage_reconciled_at = NULL,
        updated_at = pg_catalog.clock_timestamp()
    WHERE request_id = p_request_id
      AND operation_key LIKE 'target-comments:%'
      AND status = 'rejected';
    IF v_job.status IN ('pending', 'processing') THEN
        UPDATE public.analysis_pipeline_jobs
        SET status = 'pending',
            dispatch_state = 'reserved',
            dispatch_generation = dispatch_generation + 1,
            dispatch_reservation_token = extensions.gen_random_uuid(),
            dispatch_reserved_at = pg_catalog.clock_timestamp(),
            dispatched_at = NULL,
            dispatch_task_name = NULL,
            delivered_at = NULL,
            lease_token = NULL,
            lease_expires_at = NULL,
            completion_token = NULL,
            completion_fanout_hash = NULL,
            last_error_code = NULL,
            last_error_at = NULL,
            completed_at = NULL,
            attempt_count = 1,
            updated_at = pg_catalog.clock_timestamp()
        WHERE request_id = p_request_id
          AND job_key = 'track:target-evidence:collect';
    END IF;
    RETURN TRUE;
END;
$$;


--
-- Name: resume_earlybird_v211_policy_identity_admission(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resume_earlybird_v211_policy_identity_admission(p_order_id uuid, p_expected_manual_review_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_order public.earlybird_orders%ROWTYPE;
    v_fulfillment public.earlybird_fulfillments%ROWTYPE;
    v_replay RECORD;
    v_preflight public.analysis_preflights%ROWTYPE;
BEGIN
    IF p_order_id IS NULL OR p_expected_manual_review_at IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_POLICY_ADMISSION_RESUME_INVALID',
            ERRCODE = 'P0001';
    END IF;
    SELECT earlybird_order.* INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id FOR UPDATE;
    SELECT replay.* INTO v_replay
    
FROM public.maintenance_jobs AS archive_source
CROSS JOIN LATERAL (
    SELECT decoded.*
    FROM pg_catalog.jsonb_to_record(archive_source.payload->'legacy_row')
        AS decoded(order_id UUID, original_failed_request_id UUID, policy_identity_failed_request_id UUID, failed_preflight_id UUID, rearmed_preflight_id UUID, expected_fulfillment_attempt_count SMALLINT, expected_manual_review_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
    WHERE archive_source.state = 'succeeded'
      AND archive_source.legacy_pending_user_id IS NULL
      AND archive_source.kind = 'replay'
      AND archive_source.payload->>'legacy_source_table' = 'earlybird_v211_policy_identity_replays'
      AND archive_source.payload->'schema_version' = '1'::JSONB
      AND decoded.order_id IS NOT NULL
      AND archive_source.payload->'legacy_primary_key' =
          pg_catalog.jsonb_build_object('order_id', decoded.order_id)
      AND pg_catalog.jsonb_typeof(archive_source.payload->'legacy_row') = 'object'
      AND archive_source.payload->'legacy_row' ?& ARRAY['order_id','original_failed_request_id','policy_identity_failed_request_id','failed_preflight_id','rearmed_preflight_id','expected_fulfillment_attempt_count','expected_manual_review_at','created_at']::TEXT[]
      AND (decoded.order_id IS NOT NULL AND decoded.original_failed_request_id IS NOT NULL AND decoded.policy_identity_failed_request_id IS NOT NULL AND decoded.failed_preflight_id IS NOT NULL AND decoded.rearmed_preflight_id IS NOT NULL AND decoded.expected_fulfillment_attempt_count IS NOT NULL AND decoded.expected_manual_review_at IS NOT NULL AND decoded.created_at IS NOT NULL)
      AND archive_source.content_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(archive_source.payload::TEXT, 'UTF8'), 'sha256'
          ), 'hex'
      )
      AND archive_source.target_key_hash = pg_catalog.encode(
          extensions.digest(
              convert_to(
                  'supabase-22-legacy-earlybird-retirement-v1:'
                  || archive_source.kind || ':'
                  || (archive_source.payload->>'legacy_source_table') || ':'
                  || (archive_source.payload->'legacy_primary_key')::TEXT,
                  'UTF8'
              ), 'sha256'
          ), 'hex'
      )
) AS replay
    WHERE replay.order_id = p_order_id FOR UPDATE;
    SELECT fulfillment.* INTO v_fulfillment
    FROM public.earlybird_fulfillments AS fulfillment
    WHERE fulfillment.order_id = p_order_id FOR UPDATE;
    SELECT preflight.* INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = v_replay.rearmed_preflight_id FOR UPDATE;

    IF v_order.id IS NULL
       OR v_replay.order_id IS NULL
       OR v_order.preflight_id IS DISTINCT FROM v_replay.rearmed_preflight_id
       OR v_order.status <> 'paid'
       OR v_order.result_request_id IS NOT NULL
       OR v_order.plan_id <> 'basic'
       OR v_order.expected_amount_krw <> 990
       OR v_order.actual_amount_krw <> 990
       OR v_order.payment_id IS NULL
       OR v_order.seller_reference_confirmed_at IS NULL
       OR v_order.actual_groble_product_id
            IS DISTINCT FROM v_order.expected_groble_product_id
       OR v_fulfillment.status <> 'manual_review'
       OR v_fulfillment.attempt_count <> 1
       OR v_fulfillment.request_id IS NOT NULL
       OR v_fulfillment.last_error_code <> 'PROVIDER_RUN_ADOPTION_REQUIRED'
       OR v_fulfillment.manual_review_at
            IS DISTINCT FROM p_expected_manual_review_at
       OR v_fulfillment.lease_token IS NOT NULL
       OR v_fulfillment.lease_expires_at IS NOT NULL
       OR v_preflight.user_id IS DISTINCT FROM v_order.user_id
       OR v_preflight.status <> 'ready'
       OR v_preflight.consumed_request_id IS NOT NULL
       OR v_preflight.idempotency_key IS DISTINCT FROM (
            'earlybird.fulfillment.'
            || pg_catalog.replace(v_order.id::TEXT, '-', '') || '.r8'
       )
       OR v_preflight.target_instagram_id IS DISTINCT FROM
            v_order.target_instagram_id
       OR v_preflight.admission_status <> 'ready'
       OR v_preflight.admission_selected_plan_id <> 'basic'
       OR v_preflight.admission_dispatch_state <> 'enqueued'
       OR v_preflight.pii_scrubbed_at IS NOT NULL
       OR EXISTS (
            SELECT 1 FROM public.analysis_requests AS request
            WHERE request.preflight_id = v_preflight.id
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'EARLYBIRD_V211_POLICY_ADMISSION_RESUME_INELIGIBLE',
            ERRCODE = 'P0001';
    END IF;

    UPDATE public.earlybird_fulfillments AS fulfillment
    SET status = 'admission_pending', attempt_count = 0, request_id = NULL,
        lease_token = NULL, lease_expires_at = NULL, next_attempt_at = v_now,
        operator_admitted_at = v_now, last_error_code = NULL,
        last_error_at = NULL, manual_review_at = NULL,
        completed_at = NULL, updated_at = v_now
    WHERE fulfillment.order_id = v_order.id;
    RETURN TRUE;
END;
$$;


--
-- Name: retire_analysis_beta_pool_local_debits_after_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retire_analysis_beta_pool_local_debits_after_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    -- An equal timestamp is intentionally retained: the observation can be
    -- concurrent with the provider-side reconciliation rather than after it.
    DELETE FROM public.analysis_beta_pool_local_debits AS debit
    WHERE debit.credential_slot = NEW.credential_slot
      AND NEW.observed_at > debit.reconciliation_watermark;
    RETURN NEW;
END;
$$;


--
-- Name: scrub_terminal_analysis_v2_preflights(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scrub_terminal_analysis_v2_preflights(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_scrubbed_count INTEGER;
BEGIN
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 1000 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_MAINTENANCE_INPUT', ERRCODE = 'P0001';
    END IF;

    WITH terminal AS (
        SELECT preflight.id
        FROM public.analysis_preflights AS preflight
        JOIN public.analysis_requests AS analysis_request
          ON analysis_request.id = preflight.consumed_request_id
        WHERE preflight.status = 'consumed'
          AND analysis_request.pipeline_version = 'v2'
          AND analysis_request.status IN ('completed', 'failed')
          AND preflight.pii_scrubbed_at IS NULL
        ORDER BY analysis_request.completed_at NULLS LAST, preflight.id
        LIMIT p_limit
        FOR UPDATE OF preflight SKIP LOCKED
    )
    UPDATE public.analysis_preflights AS preflight
    SET target_instagram_id = 'retained.'
            || pg_catalog.substr(pg_catalog.replace(preflight.id::TEXT, '-', ''), 1, 20),
        target_full_name = NULL,
        target_bio = NULL,
        target_profile_image_url = NULL,
        exclusion_decision = 'skip',
        excluded_instagram_id = NULL,
        pii_scrubbed_at = clock_timestamp(),
        updated_at = clock_timestamp()
    FROM terminal
    WHERE preflight.id = terminal.id;

    GET DIAGNOSTICS v_scrubbed_count = ROW_COUNT;
    RETURN v_scrubbed_count;
END;
$$;


--
-- Name: seal_analysis_v2_result_image_manifest(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seal_analysis_v2_result_image_manifest(p_request_id uuid, p_job_key text, p_claim_token uuid, p_job_input_hash text, p_ordered_manifest_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_manifest public.analysis_v2_result_image_manifests%ROWTYPE;
    v_durable_rows INTEGER;
    v_sourced_images INTEGER;
    v_ready_images INTEGER;
    v_capture_failed_images INTEGER;
BEGIN
    PERFORM public.analysis_v2_assert_result_image_job_fence(
        p_request_id, p_job_key, p_claim_token, p_job_input_hash
    );
    SELECT manifest.* INTO v_manifest
    FROM public.analysis_v2_result_image_manifests AS manifest
    WHERE manifest.request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_manifest.producer_job_key IS DISTINCT FROM p_job_key
       OR v_manifest.producer_input_hash IS DISTINCT FROM p_job_input_hash
       OR v_manifest.producer_claim_token IS DISTINCT FROM p_claim_token
       OR v_manifest.ordered_manifest_hash IS DISTINCT FROM
            p_ordered_manifest_hash THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;

    SELECT
        pg_catalog.count(*)::INTEGER,
        pg_catalog.count(*) FILTER (
            WHERE image_object.source_fingerprint IS NOT NULL
        )::INTEGER,
        pg_catalog.count(*) FILTER (
            WHERE image_object.status = 'ready'
        )::INTEGER,
        pg_catalog.count(*) FILTER (
            WHERE image_object.status = 'capture_failed'
        )::INTEGER
    INTO
        v_durable_rows, v_sourced_images, v_ready_images,
        v_capture_failed_images
    FROM public.analysis_v2_result_image_objects AS image_object
    WHERE image_object.request_id = p_request_id;

    IF NOT public.analysis_v2_result_image_coverage_ok(
        v_manifest.expected_rows,
        v_durable_rows,
        v_sourced_images,
        v_ready_images,
        v_capture_failed_images
    )
       OR (
            v_manifest.expected_rows > 0
            AND NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_result_image_objects AS target_image
                WHERE target_image.request_id = p_request_id
                  AND target_image.kind = 'target'
                  AND target_image.candidate_locator = 'target'
            )
       )
       OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_result_image_objects AS image_object
            WHERE image_object.request_id = p_request_id
              AND image_object.is_mandatory
              AND image_object.status <> 'ready'
       )
       OR EXISTS (
            SELECT 1
            FROM public.analysis_v2_result_image_objects AS image_object
            WHERE image_object.request_id = p_request_id
              AND image_object.status = 'ready'
              AND image_object.expires_at <= v_now
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_MANIFEST_NOT_READY',
            ERRCODE = 'P0001';
    END IF;

    IF v_manifest.sealed_at IS NOT NULL THEN
        IF v_manifest.durable_rows IS DISTINCT FROM v_durable_rows
           OR v_manifest.sourced_images IS DISTINCT FROM v_sourced_images
           OR v_manifest.ready_images IS DISTINCT FROM v_ready_images
           OR v_manifest.capture_failed_images IS DISTINCT FROM
                v_capture_failed_images THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_RESULT_IMAGE_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
    ELSE
        UPDATE public.analysis_v2_result_image_manifests AS manifest
        SET durable_rows = v_durable_rows,
            sourced_images = v_sourced_images,
            ready_images = v_ready_images,
            capture_failed_images = v_capture_failed_images,
            sealed_at = v_now
        WHERE manifest.request_id = p_request_id;
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'orderedManifestHash', p_ordered_manifest_hash,
        'expectedRows', v_manifest.expected_rows,
        'durableRows', v_durable_rows,
        'sourcedImages', v_sourced_images,
        'readyImages', v_ready_images,
        'captureFailedImages', v_capture_failed_images
    );
END;
$$;


--
-- Name: set_analysis_apify_account_exclusion(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_analysis_apify_account_exclusion(p_credential_slot text, p_excluded boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
BEGIN
    IF NOT public.analysis_beta_valid_apify_credential_slot(p_credential_slot)
       OR p_excluded IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_APIFY_ACCOUNT_CONTROL_INVALID',
            ERRCODE = 'P0001';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('analysis-apify-free-pool', 0)
    );

    UPDATE public.analysis_apify_credit_snapshots AS snapshot
    SET manually_excluded = p_excluded,
        refreshed_at = v_now
    WHERE snapshot.credential_slot = p_credential_slot;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_APIFY_ACCOUNT_CONTROL_INVALID',
            ERRCODE = 'P0001';
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'credentialSlot', p_credential_slot,
        'excluded', p_excluded,
        'updatedAt', v_now
    );
END;
$$;


--
-- Name: set_analysis_beta_access_policy(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_analysis_beta_access_policy(p_mode text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE v_mode TEXT;
BEGIN
    IF p_mode IS NULL OR p_mode NOT IN ('grant_only','all_authenticated') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POLICY_INVALID', ERRCODE = 'P0001';
    END IF;
    SELECT policy_row.mode INTO v_mode FROM public.analysis_beta_access_policy AS policy_row
    WHERE policy_row.singleton=TRUE FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POLICY_INVALID', ERRCODE = 'P0001'; END IF;
    IF v_mode = p_mode THEN RETURN p_mode; END IF;
    UPDATE public.analysis_beta_access_policy AS policy_row
    SET mode=p_mode, generation=policy_row.generation+1, updated_at=pg_catalog.clock_timestamp()
    WHERE policy_row.singleton=TRUE;
    IF p_mode='grant_only' THEN
        UPDATE public.analysis_beta_access_grants AS grant_row
        SET enabled=FALSE, updated_at=pg_catalog.clock_timestamp()
        WHERE grant_row.grant_source='automatic' AND grant_row.enabled=TRUE;
    END IF;
    RETURN p_mode;
END; $$;


--
-- Name: set_analysis_beta_runtime_gate(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_analysis_beta_runtime_gate(p_enabled boolean) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
DECLARE
    v_generation BIGINT;
BEGIN
    IF p_enabled IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_GATE_INVALID', ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_beta_runtime_gate AS gate_row
    SET enabled = p_enabled,
        generation = gate_row.generation + 1,
        updated_at = pg_catalog.clock_timestamp()
    WHERE gate_row.singleton = TRUE
      AND gate_row.enabled IS DISTINCT FROM p_enabled
    RETURNING gate_row.generation INTO v_generation;
    IF v_generation IS NULL THEN
        SELECT gate_row.generation INTO v_generation
        FROM public.analysis_beta_runtime_gate AS gate_row
        WHERE gate_row.singleton = TRUE
        FOR UPDATE;
    END IF;
    RETURN v_generation;
END;
$$;


--
-- Name: set_analysis_v2_preflight_exclusion(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_analysis_v2_preflight_exclusion(p_preflight_id uuid, p_user_id uuid, p_decision text, p_excluded_instagram_id text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $_$
DECLARE v_now TIMESTAMPTZ; v_gate_enabled BOOLEAN;
DECLARE v_grant public.analysis_beta_access_grants%ROWTYPE;
DECLARE v_preflight public.analysis_preflights%ROWTYPE; v_excluded_instagram_id TEXT;
BEGIN
    IF p_preflight_id IS NULL OR p_user_id IS NULL OR p_decision NOT IN ('exclude','skip') THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_V2_INVALID_EXCLUSION', ERRCODE='P0001';
    END IF;
    IF p_decision='exclude' THEN
        v_excluded_instagram_id:=pg_catalog.lower(pg_catalog.btrim(p_excluded_instagram_id));
        IF v_excluded_instagram_id IS NULL OR v_excluded_instagram_id!~'^[a-z0-9._]{1,30}$' THEN
            RAISE EXCEPTION USING MESSAGE='ANALYSIS_V2_INVALID_EXCLUSION', ERRCODE='P0001';
        END IF;
    ELSIF p_excluded_instagram_id IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE='ANALYSIS_V2_INVALID_EXCLUSION', ERRCODE='P0001';
    END IF;
    SELECT gate_row.enabled INTO v_gate_enabled FROM public.analysis_beta_runtime_gate AS gate_row
    WHERE gate_row.singleton=TRUE FOR SHARE;
    PERFORM 1 FROM public.users AS owner_user WHERE owner_user.id=p_user_id FOR KEY SHARE;
    SELECT preflight.* INTO v_preflight FROM public.analysis_preflights AS preflight
    WHERE preflight.id=p_preflight_id AND preflight.user_id=p_user_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE='P0001'; END IF;
    SELECT grant_row.* INTO v_grant FROM public.analysis_beta_access_grants AS grant_row
    WHERE grant_row.user_id=p_user_id FOR SHARE;
    v_now:=pg_catalog.clock_timestamp();
    IF v_preflight.beta_entry_provenance IS NOT NULL AND (
        v_gate_enabled IS DISTINCT FROM TRUE OR v_grant.user_id IS NULL
        OR v_grant.enabled IS DISTINCT FROM TRUE
        OR (v_grant.expires_at IS NOT NULL AND (
            NOT pg_catalog.isfinite(v_grant.expires_at)
            OR v_grant.expires_at<=v_now
        ))
    ) THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_ACCESS_UNAVAILABLE', ERRCODE='P0001'; END IF;
    IF v_preflight.exclusion_decision=p_decision
       AND v_preflight.excluded_instagram_id IS NOT DISTINCT FROM v_excluded_instagram_id THEN RETURN FALSE; END IF;
    IF v_preflight.exclusion_decision<>'pending' THEN RAISE EXCEPTION USING MESSAGE='PREFLIGHT_IMMUTABLE', ERRCODE='P0001'; END IF;
    IF v_preflight.expires_at<=v_now OR v_preflight.status='expired' THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_V2_PREFLIGHT_EXPIRED', ERRCODE='P0001'; END IF;
    IF v_preflight.status='consumed' THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_V2_PREFLIGHT_CONSUMED', ERRCODE='P0001'; END IF;
    IF v_preflight.status NOT IN ('pending','processing','ready') THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE='P0001'; END IF;
    IF p_decision='exclude' AND v_excluded_instagram_id=v_preflight.target_instagram_id THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_V2_INVALID_EXCLUSION', ERRCODE='P0001'; END IF;
    UPDATE public.analysis_preflights SET exclusion_decision=p_decision,
        excluded_instagram_id=v_excluded_instagram_id,exclusion_decided_at=v_now,
        updated_at=v_now WHERE id=v_preflight.id AND exclusion_decision='pending';
    IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE='PREFLIGHT_IMMUTABLE', ERRCODE='P0001'; END IF;
    RETURN TRUE;
END;
$_$;


--
-- Name: set_analysis_v2_preflight_exclusion_with_landing(uuid, uuid, character varying, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_analysis_v2_preflight_exclusion_with_landing(p_preflight_id uuid, p_user_id uuid, p_claim_token_hash character varying, p_decision text, p_excluded_instagram_id text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE;
    v_preflight public.analysis_preflights%ROWTYPE;
    v_excluded_instagram_id TEXT;
BEGIN
    IF p_preflight_id IS NULL
       OR p_decision IS NULL
       OR p_decision NOT IN ('exclude', 'skip') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_EXCLUSION', ERRCODE = 'P0001';
    END IF;

    IF p_user_id IS NOT NULL THEN
        IF p_claim_token_hash IS NOT NULL
           OR (SELECT auth.uid()) IS DISTINCT FROM p_user_id THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_EXCLUSION', ERRCODE = 'P0001';
        END IF;
    ELSIF p_claim_token_hash IS NULL
          OR p_claim_token_hash !~ '^[0-9a-f]{64}$'
          OR (SELECT auth.uid()) IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_CLAIM_INVALID', ERRCODE = 'P0001';
    END IF;

    IF p_decision = 'exclude' THEN
        v_excluded_instagram_id := pg_catalog.lower(pg_catalog.btrim(p_excluded_instagram_id));
        IF v_excluded_instagram_id IS NULL
           OR v_excluded_instagram_id !~ '^[a-z0-9._]{1,30}$' THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_EXCLUSION', ERRCODE = 'P0001';
        END IF;
    ELSIF p_excluded_instagram_id IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_EXCLUSION', ERRCODE = 'P0001';
    END IF;

    -- The initial timestamp only narrows the anonymous lookup. A caller can
    -- wait on the row lock long enough for either the claim or preflight to
    -- expire, so lifecycle decisions must use a fresh wall clock after the
    -- lock has been acquired.
    v_now := pg_catalog.clock_timestamp();
    SELECT preflight.*
    INTO v_preflight
    FROM public.analysis_preflights AS preflight
    WHERE preflight.id = p_preflight_id
      AND (
          (
              p_user_id IS NOT NULL
              AND preflight.user_id = p_user_id
          )
          OR (
              p_user_id IS NULL
              AND preflight.user_id IS NULL
              AND preflight.claim_token_hash = p_claim_token_hash
              AND preflight.claim_expires_at > v_now
          )
      )
    FOR UPDATE;
    IF NOT FOUND THEN
        IF p_user_id IS NULL THEN
            RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_CLAIM_INVALID', ERRCODE = 'P0001';
        END IF;
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_FOUND', ERRCODE = 'P0001';
    END IF;

    v_now := pg_catalog.clock_timestamp();
    IF p_user_id IS NULL
       AND (
           v_preflight.claim_expires_at IS NULL
           OR v_preflight.claim_expires_at <= v_now
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANONYMOUS_PREFLIGHT_CLAIM_INVALID', ERRCODE = 'P0001';
    END IF;

    -- Lifecycle and expiry remain authoritative even for an identical retry.
    -- They must be checked before replay/self-heal so an expired or consumed
    -- row can never recreate an excluded landing lead.
    IF v_preflight.expires_at <= v_now OR v_preflight.status = 'expired' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_EXPIRED', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status = 'consumed' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_CONSUMED', ERRCODE = 'P0001';
    END IF;
    IF v_preflight.status NOT IN ('pending', 'processing', 'ready') THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_PREFLIGHT_NOT_READY', ERRCODE = 'P0001';
    END IF;

    IF p_user_id IS NOT NULL
       AND v_preflight.beta_entry_provenance IS NOT NULL
       AND NOT public.analysis_beta_has_access() THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_ACCESS_UNAVAILABLE', ERRCODE = 'P0001';
    END IF;

    -- An identical retry is successful without changing the write-once
    -- decision. For an exclusion, replay the idempotent lead insert as well so
    -- a legacy decision that predates this atomic boundary can self-heal.
    IF v_preflight.exclusion_decision = p_decision
       AND v_preflight.excluded_instagram_id IS NOT DISTINCT FROM v_excluded_instagram_id THEN
        IF p_decision = 'exclude'
           AND NOT public.create_or_replay_landing_lead_exclusion(
               p_preflight_id,
               v_excluded_instagram_id
           ) THEN
            RAISE EXCEPTION USING MESSAGE = 'LANDING_LEAD_TARGET_MISSING', ERRCODE = 'P0001';
        END IF;
        RETURN FALSE;
    END IF;
    IF v_preflight.exclusion_decision <> 'pending' THEN
        RAISE EXCEPTION USING MESSAGE = 'PREFLIGHT_IMMUTABLE', ERRCODE = 'P0001';
    END IF;
    IF p_decision = 'exclude'
       AND v_excluded_instagram_id = pg_catalog.lower(v_preflight.target_instagram_id) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_V2_INVALID_EXCLUSION', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_preflights AS preflight
    SET exclusion_decision = p_decision,
        excluded_instagram_id = v_excluded_instagram_id,
        exclusion_decided_at = v_now,
        updated_at = v_now
    WHERE preflight.id = v_preflight.id
      AND preflight.exclusion_decision = 'pending';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PREFLIGHT_IMMUTABLE', ERRCODE = 'P0001';
    END IF;

    IF p_decision = 'exclude'
       AND NOT public.create_or_replay_landing_lead_exclusion(
           p_preflight_id,
           v_excluded_instagram_id
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'LANDING_LEAD_TARGET_MISSING', ERRCODE = 'P0001';
    END IF;
    RETURN TRUE;
END;
$_$;


--
-- Name: set_anonymous_analysis_v2_preflight_exclusion(uuid, character varying, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_anonymous_analysis_v2_preflight_exclusion(p_preflight_id uuid, p_claim_token_hash character varying, p_decision text, p_excluded_instagram_id text) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'public', 'extensions'
    AS $$
    SELECT public.set_analysis_v2_preflight_exclusion_with_landing(
        p_preflight_id,
        NULL::UUID,
        p_claim_token_hash,
        p_decision,
        p_excluded_instagram_id
    );
$$;


--
-- Name: set_authenticated_analysis_v2_preflight_exclusion(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_authenticated_analysis_v2_preflight_exclusion(p_preflight_id uuid, p_user_id uuid, p_decision text, p_excluded_instagram_id text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $$
    SELECT public.set_analysis_v2_preflight_exclusion_with_landing(
        p_preflight_id,
        p_user_id,
        NULL::VARCHAR,
        p_decision,
        p_excluded_instagram_id
    );
$$;


--
-- Name: set_earlybird_order_phone_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_earlybird_order_phone_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_phone_number_normalized TEXT;
    v_phone_verification_source TEXT;
    v_phone_verified_at TIMESTAMP WITH TIME ZONE;
BEGIN
    -- The same namespaced product fence is also taken by checkout and the rolling
    -- finalizer. Direct service-role INSERTs cannot create a verified-order phantom.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'earlybird:groble:product:' || NEW.expected_groble_product_id,
            0
        )
    );

    SELECT buyer.phone_number_normalized,
        buyer.phone_number_verification_source,
        buyer.phone_number_verified_at
    INTO v_phone_number_normalized,
        v_phone_verification_source,
        v_phone_verified_at
    FROM public.users AS buyer
    WHERE buyer.id = NEW.user_id
      AND buyer.provider = 'kakao'
      AND buyer.phone_number_verification_source = 'kakao_rest_api'
      AND buyer.phone_number_verified_at IS NOT NULL
      AND buyer.phone_number_verified_at
            >= pg_catalog.clock_timestamp() - INTERVAL '24 hours'
      AND buyer.phone_number_normalized IS NOT NULL
      AND public.normalize_kr_mobile_e164(buyer.phone_number)
            IS NOT DISTINCT FROM buyer.phone_number_normalized
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'CHECKOUT_PHONE_REQUIRED';
    END IF;

    NEW.buyer_match_policy := 'verified_kakao_phone';
    NEW.expected_buyer_phone_number_normalized := v_phone_number_normalized;
    NEW.expected_buyer_phone_verification_source := v_phone_verification_source;
    NEW.expected_buyer_phone_verified_at := v_phone_verified_at;
    RETURN NEW;
END;
$$;


--
-- Name: set_earlybird_refund_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_earlybird_refund_status(p_order_id uuid, p_next_status text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_user_id UUID;
    v_order public.earlybird_orders%ROWTYPE;
BEGIN
    SELECT earlybird_order.user_id
    INTO v_user_id
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'EARLYBIRD_ORDER_NOT_FOUND';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(v_user_id::TEXT, 0)
    );

    SELECT earlybird_order.*
    INTO v_order
    FROM public.earlybird_orders AS earlybird_order
    WHERE earlybird_order.id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'EARLYBIRD_ORDER_NOT_FOUND';
    END IF;

    IF p_next_status = 'cancelled' AND v_order.status = 'payment_pending' THEN
        NULL;
    ELSIF p_next_status = 'refund_pending'
       AND v_order.status IN (
           'paid', 'analysis_in_progress', 'completed',
           'payment_failed', 'overflow_refund_required'
       ) THEN
        NULL;
    ELSIF p_next_status = 'refunded'
       AND v_order.status IN (
           'refund_pending', 'payment_failed', 'overflow_refund_required'
       ) THEN
        NULL;
    ELSE
        RAISE EXCEPTION 'EARLYBIRD_REFUND_TRANSITION_INVALID';
    END IF;

    UPDATE public.earlybird_orders AS transitioned_order
    SET status = p_next_status,
        updated_at = pg_catalog.clock_timestamp()
    WHERE transitioned_order.id = p_order_id;

    RETURN p_next_status;
END;
$$;


--
-- Name: set_kakao_signup_discord_outbox_profile(uuid, text, character, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_kakao_signup_discord_outbox_profile(p_user_id uuid, p_masked_name text, p_birthyear character, p_gender text, p_signed_up_at timestamp with time zone, p_attribution_label text DEFAULT NULL::text, p_attribution_origin text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$ BEGIN UPDATE public.kakao_signup_discord_outbox SET masked_name=p_masked_name,birthyear=p_birthyear,gender=CASE WHEN p_gender IN ('여성','남성') THEN p_gender ELSE NULL END,signed_up_at=p_signed_up_at,attribution_label=CASE WHEN p_attribution_label IN ('직접 방문','UTM: 카카오','UTM: 구글','UTM: 인스타그램','UTM: 기타','외부 참조: 카카오','외부 참조: 구글','외부 참조: 인스타그램','외부 참조: 기타') THEN p_attribution_label ELSE NULL END,attribution_origin=CASE WHEN p_attribution_origin ~ '^https?://[a-z0-9][a-z0-9.-]{0,251}/$' AND p_attribution_origin ~ '^https?://[^/]*\.[^/]+/$' AND p_attribution_origin !~ '^https?://(?:localhost|(?:[0-9]{1,3}\.){3}[0-9]{1,3})/' AND p_attribution_origin !~ '\.(localhost|local|internal|test|example|invalid|home|lan|localdomain|corp)/$' THEN p_attribution_origin ELSE NULL END,updated_at=clock_timestamp(),profile_staged_at=clock_timestamp() WHERE user_id=p_user_id AND status='pending' AND profile_staged_at IS NULL; RETURN FOUND; END; $_$;


--
-- Name: settle_analysis_beta_apify_credit_allocation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_analysis_beta_apify_credit_allocation(p_allocation_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '1s'
    SET statement_timeout TO '5s'
    AS $_$
DECLARE v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
DECLARE v_allocation public.analysis_beta_pool_allocations%ROWTYPE;
DECLARE v_preflight public.analysis_preflights%ROWTYPE;
DECLARE v_request public.analysis_requests%ROWTYPE;
DECLARE v_reservation public.analysis_beta_pool_reservations%ROWTYPE;
DECLARE v_actual NUMERIC; DECLARE v_watermark TIMESTAMP WITH TIME ZONE;
DECLARE v_safe BOOLEAN; DECLARE v_settled_count INTEGER := 0;
DECLARE v_held_count INTEGER := 0; DECLARE v_actual_total NUMERIC := 0;
DECLARE v_released_total NUMERIC := 0;
BEGIN
 IF p_allocation_id IS NULL OR p_reason NOT IN ('request_terminal','preflight_expired','recovery') THEN
  RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_SETTLEMENT_INVALID', ERRCODE = 'P0001'; END IF;
 -- Canonical order is user -> preflight -> request -> allocation -> family.
 SELECT allocation.* INTO v_allocation FROM public.analysis_beta_pool_allocations allocation WHERE allocation.id = p_allocation_id;
 IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_SETTLEMENT_NOT_FOUND', ERRCODE = 'P0001'; END IF;
 PERFORM users.id FROM public.users users WHERE users.id = v_allocation.user_id FOR KEY SHARE;
 SELECT preflight.* INTO v_preflight FROM public.analysis_preflights preflight WHERE preflight.id = v_allocation.preflight_id FOR UPDATE;
 IF v_allocation.request_id IS NOT NULL THEN SELECT request.* INTO v_request FROM public.analysis_requests request WHERE request.id = v_allocation.request_id FOR UPDATE; END IF;
 SELECT allocation.* INTO v_allocation FROM public.analysis_beta_pool_allocations allocation WHERE allocation.id = p_allocation_id FOR UPDATE;
 IF v_allocation.lifecycle_state = 'settled' THEN RETURN pg_catalog.jsonb_build_object('allocationId',v_allocation.id,'lifecycleState','settled','settledFamilies',0,'heldFamilies',0,'actualUsd',0,'releasedUsd',0); END IF;
 IF (v_allocation.lifecycle_state = 'active' AND (v_request.id IS NULL OR v_request.status NOT IN ('completed','failed')))
    OR (v_allocation.lifecycle_state = 'preflight_held' AND (v_preflight.id IS NULL OR (v_preflight.expires_at > v_now AND v_preflight.status NOT IN ('blocked','expired')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_SETTLEMENT_NOT_TERMINAL', ERRCODE = 'P0001'; END IF;
 FOR v_reservation IN SELECT reservation.* FROM public.analysis_beta_pool_reservations reservation WHERE reservation.allocation_id = v_allocation.id ORDER BY reservation.operation_family FOR UPDATE LOOP
  IF v_reservation.lifecycle_state = 'settled' THEN CONTINUE; END IF;
  v_actual := 0; v_watermark := NULL; v_safe := TRUE;
  IF v_reservation.operation_family = 'target-profile' THEN
   SELECT COALESCE(pg_catalog.bool_and(provider_run.status = 'rejected' OR (provider_run.status IN ('succeeded','failed','aborted','timed_out','resolved_no_run') AND provider_run.actual_usage_usd IS NOT NULL AND provider_run.usage_reconciled_at IS NOT NULL)), TRUE),
          COALESCE(pg_catalog.sum(CASE WHEN provider_run.status = 'rejected' THEN 0::NUMERIC ELSE provider_run.actual_usage_usd END),0::NUMERIC),
          pg_catalog.max(CASE WHEN provider_run.status = 'rejected' THEN NULL ELSE provider_run.usage_reconciled_at END)
     INTO v_safe,v_actual,v_watermark FROM public.analysis_preflight_provider_runs provider_run
    WHERE provider_run.preflight_id = v_allocation.preflight_id AND (provider_run.operation_key = 'target-profile-fallback' OR provider_run.operation_key ~ '^target-profile-fresh-admission:g([1-9]|[1-9][0-9]|100)$');
  ELSE
   SELECT COALESCE(pg_catalog.bool_and(provider_run.status = 'rejected' OR (provider_run.status IN ('succeeded','failed','aborted','timed_out') AND provider_run.actual_usage_usd IS NOT NULL AND provider_run.usage_reconciled_at IS NOT NULL)), TRUE),
          COALESCE(pg_catalog.sum(CASE WHEN provider_run.status = 'rejected' THEN 0::NUMERIC ELSE provider_run.actual_usage_usd END),0::NUMERIC),
          pg_catalog.max(CASE WHEN provider_run.status = 'rejected' THEN NULL ELSE provider_run.usage_reconciled_at END)
     INTO v_safe,v_actual,v_watermark FROM public.analysis_v2_provider_runs provider_run
    WHERE provider_run.request_id = v_allocation.request_id AND pg_catalog.split_part(provider_run.operation_key,':',1) = v_reservation.operation_family;
  END IF;
  IF NOT v_safe THEN v_held_count := v_held_count + 1; CONTINUE; END IF;
  IF v_actual > v_reservation.reserved_usd THEN RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_SETTLEMENT_ACTUAL_EXCEEDS_RESERVATION', ERRCODE = 'P0001'; END IF;
  UPDATE public.analysis_beta_pool_reservations reservation SET lifecycle_state='settled',actual_usd=v_actual,released_usd=reservation.reserved_usd-v_actual,reconciliation_watermark=v_watermark,settled_at=v_now,settlement_reason=p_reason,updated_at=v_now WHERE reservation.allocation_id=v_allocation.id AND reservation.operation_family=v_reservation.operation_family;
  v_settled_count:=v_settled_count+1; v_actual_total:=v_actual_total+v_actual; v_released_total:=v_released_total+(v_reservation.reserved_usd-v_actual);
 END LOOP;
 IF NOT EXISTS (SELECT 1 FROM public.analysis_beta_pool_reservations reservation WHERE reservation.allocation_id=v_allocation.id AND reservation.lifecycle_state <> 'settled') THEN
  UPDATE public.analysis_beta_pool_allocations allocation SET lifecycle_state='settled',settled_at=v_now,settlement_reason=p_reason,updated_at=v_now WHERE allocation.id=v_allocation.id; v_allocation.lifecycle_state:='settled'; END IF;
 RETURN pg_catalog.jsonb_build_object('allocationId',v_allocation.id,'lifecycleState',v_allocation.lifecycle_state,'settledFamilies',v_settled_count,'heldFamilies',v_held_count,'actualUsd',v_actual_total,'releasedUsd',v_released_total);
END; $_$;


--
-- Name: settle_analysis_beta_apify_preflight_credit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_analysis_beta_apify_preflight_credit(p_preflight_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '1s'
    SET statement_timeout TO '5s'
    AS $$
DECLARE v_id UUID; BEGIN
 IF p_preflight_id IS NULL THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_SETTLEMENT_INVALID', ERRCODE='P0001'; END IF;
 -- Ready/consumed and soft admission blocks do not meet this terminal predicate.
 SELECT allocation.id INTO v_id FROM public.analysis_beta_pool_allocations allocation JOIN public.analysis_preflights preflight ON preflight.id=allocation.preflight_id
  WHERE allocation.preflight_id=p_preflight_id AND allocation.lifecycle_state='preflight_held'
   AND (preflight.status IN ('blocked','expired') OR preflight.expires_at <= pg_catalog.clock_timestamp()) LIMIT 1;
 IF v_id IS NULL THEN RETURN NULL; END IF;
 RETURN public.settle_analysis_beta_apify_credit_allocation(v_id,'preflight_expired');
END; $$;


--
-- Name: settle_analysis_beta_apify_request_credit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_analysis_beta_apify_request_credit(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '1s'
    SET statement_timeout TO '5s'
    AS $$
DECLARE v_id UUID; BEGIN
 IF p_request_id IS NULL THEN RAISE EXCEPTION USING MESSAGE='ANALYSIS_BETA_SETTLEMENT_INVALID', ERRCODE='P0001'; END IF;
 -- Plain identity read; canonical primitive owns all lifecycle locks.
 SELECT allocation.id INTO v_id FROM public.analysis_beta_pool_allocations allocation JOIN public.analysis_requests request ON request.id=allocation.request_id
  WHERE allocation.request_id=p_request_id AND allocation.lifecycle_state='active' AND request.status IN ('completed','failed') LIMIT 1;
 IF v_id IS NULL THEN RETURN NULL; END IF;
 RETURN public.settle_analysis_beta_apify_credit_allocation(v_id,'request_terminal');
END; $$;


--
-- Name: settle_analysis_revenue_cost_operation_provider_v2(uuid, text, text, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_analysis_revenue_cost_operation_provider_v2(p_request_id uuid, p_job_key text, p_source_kind text, p_source_operation_key text, p_source_attempt smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_preflight public.analysis_preflights%ROWTYPE; v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE; v_provider public.analysis_v2_provider_runs%ROWTYPE;
    v_entitlement public.analysis_v2_test_entitlement_consumptions%ROWTYPE;
    v_policy public.analysis_v2_provider_execution_policies%ROWTYPE; v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_child public.analysis_revenue_cost_operations%ROWTYPE; v_runner_plan TEXT; v_source_hash TEXT; v_owner_hash TEXT;
    v_operation_kind TEXT; v_expected_krw INTEGER; v_actual_krw INTEGER; v_active_reserved INTEGER;
    v_settled_economic INTEGER; v_settled_billed INTEGER; v_unsettled INTEGER; v_denied INTEGER;
    v_ambiguous INTEGER; v_skipped_start INTEGER;
BEGIN
    IF p_request_id IS NULL OR p_job_key IS NULL OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_source_kind IS NULL OR p_source_kind NOT IN ('provider_run','ai_attempt') OR p_source_operation_key IS NULL
       OR p_source_attempt IS DISTINCT FROM 0 THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    IF p_source_kind = 'ai_attempt' THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;

    -- Canonical delayed-settlement order: preflight -> request -> exact job ->
    -- exact provider source -> parent -> child.  No clock-derived lease fence is
    -- used because terminal reconciliation must survive a missing/expired lease.
    -- analysis_v2_scrub_terminal_request_pii deliberately replaces both raw
    -- target_instagram_id values.  Terminal authority therefore relies on the
    -- immutable request/preflight IDs, entitlement and policy bindings,
    -- entitlement hash, parent target_username_hmac/preflight target_input_hash,
    -- parent timestamps, and source/child derived hashes below -- never the raw
    -- target fields that terminal PII retention intentionally destroys.
    SELECT * INTO v_preflight FROM public.analysis_preflights WHERE consumed_request_id=p_request_id FOR UPDATE;
    SELECT * INTO v_request FROM public.analysis_requests WHERE id=p_request_id FOR UPDATE;
    SELECT * INTO v_entitlement FROM public.analysis_v2_test_entitlement_consumptions WHERE request_id=p_request_id;
    SELECT * INTO v_policy FROM public.analysis_v2_provider_execution_policies WHERE request_id=p_request_id;
    SELECT runner_plan INTO v_runner_plan FROM public.load_e2e_test_runner_v1(v_request.user_id);
    IF v_preflight.id IS NULL OR v_request.id IS NULL OR v_request.preflight_id IS DISTINCT FROM v_preflight.id
       OR v_entitlement.request_id IS NULL OR v_policy.request_id IS NULL
       OR v_request.pipeline_version IS DISTINCT FROM 'v2' OR v_request.plan_access_mode_snapshot IS DISTINCT FROM 'test_entitlement'
       OR v_request.selected_plan_id_snapshot NOT IN ('basic','standard')
       OR v_preflight.status IS DISTINCT FROM 'consumed' OR v_preflight.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_preflight.admission_generation IS DISTINCT FROM 1 OR v_preflight.admission_status IS DISTINCT FROM 'ready'
       OR v_preflight.admission_selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_preflight.admission_entitlement_jti_hash IS DISTINCT FROM v_request.test_entitlement_jti_hash
       OR v_preflight.user_id IS DISTINCT FROM v_request.user_id
       OR v_entitlement.preflight_id IS DISTINCT FROM v_preflight.id OR v_entitlement.user_id IS DISTINCT FROM v_request.user_id
       OR v_entitlement.selected_plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot
       OR v_entitlement.entitlement_jti_hash IS DISTINCT FROM v_request.test_entitlement_jti_hash
       OR v_policy.mode IS DISTINCT FROM 'test_operation_split' OR v_policy.policy_version IS DISTINCT FROM 'authorized-free-e2e-v1'
       OR v_policy.entitlement_jti_hash IS DISTINCT FROM v_entitlement.entitlement_jti_hash
       OR v_runner_plan IS DISTINCT FROM v_request.selected_plan_id_snapshot THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT * INTO v_job FROM public.analysis_pipeline_jobs WHERE request_id=p_request_id AND job_key=p_job_key FOR UPDATE;
    IF v_job.request_id IS NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT * INTO v_provider FROM public.analysis_v2_provider_runs WHERE request_id=p_request_id AND job_key=p_job_key AND operation_key=p_source_operation_key FOR UPDATE;
    IF v_provider.request_id IS NULL OR v_provider.input_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    v_operation_kind := CASE
        WHEN p_source_operation_key ~ '^target-profile:[a-f0-9]{64}$' THEN 'target_profile'
        WHEN p_source_operation_key ~ '^(profile-fallback|profile-repair):[a-f0-9]{64}$' THEN 'detail_profile'
        WHEN p_source_operation_key ~ '^relationship-followers:[a-f0-9]{64}$' THEN 'relationship_followers'
        WHEN p_source_operation_key ~ '^relationship-following:[a-f0-9]{64}$' THEN 'relationship_following'
        WHEN p_source_operation_key ~ '^(target-likers|target-comments|candidate-likers):[a-f0-9]{64}$' THEN 'detail_interaction'
        ELSE NULL END;
    IF v_operation_kind IS NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    v_source_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_source_operation_key,'UTF8'),'sha256'),'hex');
    v_owner_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to('revenue-cost/live-provider-owner/v2:' || p_request_id::TEXT || ':' || p_job_key || ':' || p_source_operation_key || ':' || v_provider.input_hash,'UTF8'),'sha256'),'hex');
    v_expected_krw := public.analysis_revenue_cost_ceil_krw(v_provider.max_charge_usd);
    SELECT * INTO v_parent FROM public.analysis_revenue_run_ledgers WHERE request_id=p_request_id FOR UPDATE;
    IF v_parent.request_id IS NULL OR v_parent.preflight_id IS DISTINCT FROM v_preflight.id OR v_parent.user_id IS DISTINCT FROM v_request.user_id
       OR v_parent.plan_id IS DISTINCT FROM v_request.selected_plan_id_snapshot OR v_parent.access_mode IS DISTINCT FROM 'test_entitlement'
       OR v_parent.target_username_hmac IS DISTINCT FROM v_preflight.target_input_hash
       OR v_parent.preflight_refreshed_at IS DISTINCT FROM v_preflight.admission_refreshed_at OR v_parent.request_started_at IS DISTINCT FROM v_request.created_at
       OR v_parent.pricing_snapshot_version IS DISTINCT FROM 'revenue-e2e-cost-2026-08-10-v1' OR v_parent.buffered_fx_krw_per_usd IS DISTINCT FROM 1450
       OR v_parent.cost_cap_krw IS DISTINCT FROM (CASE WHEN v_request.selected_plan_id_snapshot='basic' THEN 1808 ELSE 3634 END)
       OR v_parent.margin_target_krw IS DISTINCT FROM (CASE WHEN v_request.selected_plan_id_snapshot='basic' THEN 904 ELSE 1817 END)
       OR v_parent.status NOT IN ('running','manual_review') THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT COALESCE(pg_catalog.sum(CASE WHEN status IN ('reserved','started') THEN reserved_krw ELSE 0 END),0)::INTEGER,
           COALESCE(pg_catalog.sum(CASE WHEN status='settled' THEN economic_actual_krw ELSE 0 END),0)::INTEGER,
           COALESCE(pg_catalog.sum(CASE WHEN status='settled' THEN billed_actual_krw ELSE 0 END),0)::INTEGER
      INTO v_active_reserved,v_settled_economic,v_settled_billed FROM public.analysis_revenue_cost_operations WHERE request_id=p_request_id;
    IF v_parent.reserved_cost_krw IS DISTINCT FROM v_active_reserved OR v_parent.economic_actual_krw IS DISTINCT FROM v_settled_economic
       OR v_parent.actual_cost_krw IS DISTINCT FROM v_settled_economic OR v_parent.billed_actual_krw IS DISTINCT FROM v_settled_billed THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    SELECT pg_catalog.count(*) FILTER (WHERE status='ambiguous')::INTEGER,
           pg_catalog.count(*) FILTER (WHERE lifecycle_anomaly='skipped_start')::INTEGER,
           pg_catalog.count(*) FILTER (WHERE status='denied')::INTEGER
      INTO v_ambiguous,v_skipped_start,v_denied
      FROM public.analysis_revenue_cost_operations WHERE request_id=p_request_id;
    -- Aggregate review state must retain every child fact before this terminal
    -- mutation.  A denial is durable cost evidence, so it requires
    -- cost_denied unless an already-recorded cost_overrun is stronger.
    IF (v_denied > 0
           AND (v_parent.status IS DISTINCT FROM 'manual_review'
             OR (v_parent.manual_review_reason IS DISTINCT FROM 'cost_overrun' AND v_parent.manual_review_reason IS DISTINCT FROM 'cost_denied')))
       OR (v_parent.manual_review_reason IS DISTINCT FROM 'cost_overrun' AND v_parent.manual_review_reason IS DISTINCT FROM 'cost_denied'
           AND ((v_ambiguous > 0 AND (v_parent.status IS DISTINCT FROM 'manual_review' OR v_parent.manual_review_reason IS DISTINCT FROM 'ambiguous_external_call'))
             OR (v_ambiguous = 0 AND v_skipped_start > 0 AND (v_parent.status IS DISTINCT FROM 'manual_review' OR v_parent.manual_review_reason IS DISTINCT FROM 'routing_failure')))) THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    SELECT * INTO v_child FROM public.analysis_revenue_cost_operations WHERE request_id=p_request_id AND owner_kind='provider_run'
      AND source_job_key=p_job_key AND source_operation_key_hash=v_source_hash AND source_attempt=0 FOR UPDATE;
    IF NOT FOUND OR v_child.owner_key_hash IS DISTINCT FROM v_owner_hash OR v_child.attempt IS DISTINCT FROM 1
       OR v_child.operation_kind IS DISTINCT FROM v_operation_kind OR v_child.units IS DISTINCT FROM 1 OR v_child.selected_manifest_scope_hash IS NOT NULL
       OR v_child.estimated_economic_usd IS DISTINCT FROM v_provider.max_charge_usd OR v_child.reserved_krw IS DISTINCT FROM v_expected_krw
       OR v_child.denial_reason IS NOT NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;

    IF v_provider.status = 'rejected' THEN
        IF v_provider.run_id IS NOT NULL OR v_provider.run_started_at IS NOT NULL
           OR v_provider.actual_usage_usd IS DISTINCT FROM 0 OR v_provider.terminalized_at IS NULL OR v_provider.usage_reconciled_at IS NULL THEN
            RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
        -- A provider `rejected` row is authoritative proof that no external run
        -- was created (run_id/run_started_at NULL and actual usage zero).  It can
        -- safely release even a locally started child and clear that local marker.
        IF v_child.status='released' AND v_child.started_at IS NULL AND v_child.terminal_at IS NOT DISTINCT FROM v_provider.usage_reconciled_at
           AND v_child.economic_actual_usd IS NULL AND v_child.billed_actual_usd IS NULL
           AND v_child.economic_actual_krw IS NULL AND v_child.billed_actual_krw IS NULL THEN
            RETURN pg_catalog.jsonb_build_object('disposition','released','created',FALSE,'replayed',TRUE,'operationId',v_child.id);
        END IF;
        IF v_child.status NOT IN ('reserved','started','ambiguous')
           OR (v_child.status IN ('reserved','started') AND v_child.terminal_at IS NOT NULL)
           OR (v_child.status = 'ambiguous' AND (v_child.started_at IS NULL OR v_child.terminal_at IS NULL))
           OR v_child.economic_actual_usd IS NOT NULL OR v_child.billed_actual_usd IS NOT NULL
           OR v_child.economic_actual_krw IS NOT NULL OR v_child.billed_actual_krw IS NOT NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
        UPDATE public.analysis_revenue_cost_operations SET status='released',started_at=NULL,terminal_at=v_provider.usage_reconciled_at WHERE id=v_child.id;
        UPDATE public.analysis_revenue_run_ledgers
           SET reserved_cost_krw=reserved_cost_krw-CASE WHEN v_child.status IN ('reserved','started') THEN v_child.reserved_krw ELSE 0 END
         WHERE request_id=p_request_id;
        SELECT pg_catalog.count(*) FILTER (WHERE status NOT IN ('settled','released'))::INTEGER, pg_catalog.count(*) FILTER (WHERE status='denied')::INTEGER,
               pg_catalog.count(*) FILTER (WHERE status='ambiguous')::INTEGER,
               pg_catalog.count(*) FILTER (WHERE lifecycle_anomaly='skipped_start')::INTEGER
          INTO v_unsettled,v_denied,v_ambiguous,v_skipped_start
          FROM public.analysis_revenue_cost_operations WHERE request_id=p_request_id;
        IF v_parent.manual_review_reason IS DISTINCT FROM 'cost_overrun' AND v_parent.manual_review_reason IS DISTINCT FROM 'cost_denied' AND v_ambiguous > 0 THEN
            UPDATE public.analysis_revenue_run_ledgers SET status='manual_review',manual_review_reason='ambiguous_external_call' WHERE request_id=p_request_id;
        ELSIF v_parent.manual_review_reason IS DISTINCT FROM 'cost_overrun' AND v_parent.manual_review_reason IS DISTINCT FROM 'cost_denied' AND v_skipped_start > 0 THEN
            UPDATE public.analysis_revenue_run_ledgers SET status='manual_review',manual_review_reason='routing_failure' WHERE request_id=p_request_id;
        ELSIF v_parent.status='manual_review' AND v_parent.manual_review_reason='ambiguous_external_call' AND v_unsettled=0 AND v_denied=0 THEN
            UPDATE public.analysis_revenue_run_ledgers SET status='running',manual_review_reason=NULL WHERE request_id=p_request_id;
        END IF;
        RETURN pg_catalog.jsonb_build_object('disposition','released','created',TRUE,'replayed',FALSE,'operationId',v_child.id);
    END IF;
    IF v_provider.status NOT IN ('succeeded','failed','aborted','timed_out') OR v_provider.run_id IS NULL OR v_provider.run_started_at IS NULL
       OR v_provider.terminalized_at IS NULL OR v_provider.actual_usage_usd IS NULL OR v_provider.usage_reconciled_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_NOT_READY'; END IF;
    v_actual_krw := public.analysis_revenue_cost_ceil_krw(v_provider.actual_usage_usd);
    IF v_child.status='settled' THEN
        IF v_child.started_at IS NULL OR v_child.terminal_at IS DISTINCT FROM v_provider.usage_reconciled_at
           OR v_child.economic_actual_usd IS DISTINCT FROM v_provider.actual_usage_usd OR v_child.billed_actual_usd IS DISTINCT FROM 0
           OR v_child.economic_actual_krw IS DISTINCT FROM v_actual_krw OR v_child.billed_actual_krw IS DISTINCT FROM 0 THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
        RETURN pg_catalog.jsonb_build_object('disposition','settled','created',FALSE,'replayed',TRUE,'operationId',v_child.id);
    END IF;
    IF v_child.status NOT IN ('reserved','started','ambiguous') OR v_child.terminal_at IS NOT NULL AND v_child.status <> 'ambiguous'
       OR v_child.economic_actual_usd IS NOT NULL OR v_child.billed_actual_usd IS NOT NULL THEN RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE'; END IF;
    UPDATE public.analysis_revenue_cost_operations
       SET status='settled',started_at=COALESCE(v_child.started_at,v_provider.run_started_at),terminal_at=v_provider.usage_reconciled_at,
           economic_actual_usd=v_provider.actual_usage_usd,billed_actual_usd=0,economic_actual_krw=v_actual_krw,billed_actual_krw=0,
           lifecycle_anomaly=CASE WHEN v_child.status='reserved' THEN 'skipped_start' ELSE lifecycle_anomaly END
     WHERE id=v_child.id;
    UPDATE public.analysis_revenue_run_ledgers
       SET reserved_cost_krw=reserved_cost_krw-CASE WHEN v_child.status IN ('reserved','started') THEN v_child.reserved_krw ELSE 0 END,
           economic_actual_krw=economic_actual_krw+v_actual_krw,actual_cost_krw=actual_cost_krw+v_actual_krw,billed_actual_krw=billed_actual_krw
     WHERE request_id=p_request_id;
    SELECT pg_catalog.count(*) FILTER (WHERE status NOT IN ('settled','released'))::INTEGER, pg_catalog.count(*) FILTER (WHERE status='denied')::INTEGER,
           pg_catalog.count(*) FILTER (WHERE status='ambiguous')::INTEGER,
           pg_catalog.count(*) FILTER (WHERE lifecycle_anomaly='skipped_start')::INTEGER
      INTO v_unsettled,v_denied,v_ambiguous,v_skipped_start
      FROM public.analysis_revenue_cost_operations WHERE request_id=p_request_id;
    IF v_provider.actual_usage_usd > v_provider.max_charge_usd OR v_parent.economic_actual_krw+v_actual_krw > v_parent.cost_cap_krw THEN
        UPDATE public.analysis_revenue_run_ledgers SET status='manual_review',manual_review_reason='cost_overrun' WHERE request_id=p_request_id;
    ELSIF v_parent.manual_review_reason IN ('cost_overrun','cost_denied') THEN
        NULL;
    ELSIF v_ambiguous > 0 THEN
        UPDATE public.analysis_revenue_run_ledgers SET status='manual_review',manual_review_reason='ambiguous_external_call' WHERE request_id=p_request_id;
    ELSIF v_skipped_start > 0 THEN
        -- A terminal provider run with no recorded start is still cost truth,
        -- and its explicit child marker survives other-child ambiguity.
        UPDATE public.analysis_revenue_run_ledgers
           SET status='manual_review',manual_review_reason='routing_failure'
         WHERE request_id=p_request_id;
    ELSIF v_parent.status='manual_review' AND v_parent.manual_review_reason='ambiguous_external_call' AND v_unsettled=0 AND v_denied=0 THEN
        UPDATE public.analysis_revenue_run_ledgers SET status='running',manual_review_reason=NULL WHERE request_id=p_request_id;
    END IF;
    RETURN pg_catalog.jsonb_build_object('disposition','settled','created',TRUE,'replayed',FALSE,'operationId',v_child.id);
END; $_$;


--
-- Name: settle_analysis_revenue_cost_operation_v1(uuid, text, text, smallint, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_analysis_revenue_cost_operation_v1(p_request_id uuid, p_owner_kind text, p_owner_key_hash text, p_attempt smallint, p_economic_actual_usd numeric, p_billed_actual_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_NOT_READY'; END; $$;


--
-- Name: settle_analysis_revenue_cost_operation_v2(uuid, text, text, text, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_analysis_revenue_cost_operation_v2(p_request_id uuid, p_job_key text, p_source_kind text, p_source_operation_key text, p_source_attempt smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_ai public.analysis_v2_ai_attempts%ROWTYPE;
    v_parent public.analysis_revenue_run_ledgers%ROWTYPE;
    v_child public.analysis_revenue_cost_operations%ROWTYPE;
    v_mapping JSONB;
    v_source_hash TEXT;
    v_owner_hash TEXT;
    v_expected_usd NUMERIC;
    v_expected_krw INTEGER;
    v_actual_usd NUMERIC;
    v_actual_krw INTEGER;
    v_was_active BOOLEAN;
    v_start_at TIMESTAMPTZ;
    v_no_bill BOOLEAN;
BEGIN
    IF p_source_kind='provider_run' THEN
        RETURN public.settle_analysis_revenue_cost_operation_provider_v2(
            p_request_id,p_job_key,p_source_kind,p_source_operation_key,p_source_attempt
        );
    END IF;
    IF p_source_kind IS DISTINCT FROM 'ai_attempt' OR p_source_attempt NOT BETWEEN 1 AND 4 THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    -- Delayed settlement deliberately has no current lease requirement: the
    -- exact terminal attempt is authoritative after the worker has exited.
    PERFORM public.analysis_revenue_ai_cost_assert_lineage_v1(p_request_id,p_job_key,NULL,NULL,FALSE);
    SELECT * INTO v_ai FROM public.analysis_v2_ai_attempts
      WHERE request_id=p_request_id AND job_key=p_job_key
        AND operation_key=p_source_operation_key AND attempt=p_source_attempt FOR UPDATE;
    IF v_ai.request_id IS NULL OR v_ai.retry_count IS DISTINCT FROM p_source_attempt-1 THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    v_expected_usd:=public.analysis_revenue_ai_cost_max_usd_v1(v_ai.model_name,v_ai.location,v_ai.stage,v_ai.thinking_level,v_ai.media_count,v_ai.media_resolution,v_ai.prompt_version,v_ai.schema_version,v_ai.max_output_tokens);
    v_mapping:=public.analysis_revenue_ai_cost_operation_mapping_v1(
        p_request_id,p_job_key,(SELECT input_hash FROM public.analysis_pipeline_jobs WHERE request_id=p_request_id AND job_key=p_job_key),
        (SELECT selected_plan_id_snapshot FROM public.analysis_requests WHERE id=p_request_id),p_source_operation_key,p_source_attempt,v_ai.stage
    );
    v_source_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_source_operation_key,'UTF8'),'sha256'),'hex');
    v_owner_hash:=public.analysis_revenue_ai_cost_owner_hash_v1(p_request_id,p_job_key,p_source_operation_key,p_source_attempt,v_ai.reservation_token,v_ai.model_name,v_ai.location,v_ai.stage,v_ai.thinking_level,v_ai.media_count,v_ai.media_resolution,v_ai.prompt_version,v_ai.schema_version,v_ai.max_output_tokens,v_ai.retry_count);
    v_expected_krw:=public.analysis_revenue_cost_ceil_krw(v_expected_usd);
    PERFORM public.analysis_revenue_ai_cost_assert_parent_v1(p_request_id);
    SELECT * INTO v_parent FROM public.analysis_revenue_run_ledgers WHERE request_id=p_request_id FOR UPDATE;
    PERFORM public.analysis_revenue_ai_cost_assert_aggregates_v1(p_request_id);
    SELECT * INTO v_child FROM public.analysis_revenue_cost_operations
      WHERE request_id=p_request_id AND owner_kind='ai_attempt' AND source_job_key=p_job_key
        AND source_operation_key_hash=v_source_hash AND source_attempt=p_source_attempt FOR UPDATE;
    IF v_child.id IS NULL OR v_child.owner_key_hash IS DISTINCT FROM v_owner_hash
       OR v_child.attempt IS DISTINCT FROM p_source_attempt OR v_child.operation_kind IS DISTINCT FROM (v_mapping->>'operation_kind')
       OR v_child.selected_manifest_scope_hash IS DISTINCT FROM (v_mapping->>'selected_manifest_scope_hash')
       OR v_child.units IS DISTINCT FROM 1 OR v_child.estimated_economic_usd IS DISTINCT FROM v_expected_usd
       OR v_child.reserved_krw IS DISTINCT FROM v_expected_krw OR v_child.denial_reason IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    IF v_ai.status='reserved' THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_NOT_READY';
    END IF;
    v_no_bill := v_ai.status IN ('rate_limited','rejected')
        AND v_ai.usage_metadata_status='missing' AND v_ai.usage_complete=FALSE
        AND v_ai.prompt_tokens IS NULL AND v_ai.completion_tokens IS NULL
        AND v_ai.total_tokens IS NULL AND v_ai.thinking_tokens IS NULL
        AND v_ai.estimated_cost_usd IS NULL AND v_ai.finish_reason IS NULL
        AND v_ai.terminalized_at IS NOT NULL;
    IF v_no_bill THEN
        IF v_child.status='released' AND v_child.started_at IS NULL THEN
            IF v_child.terminal_at IS DISTINCT FROM v_ai.terminalized_at
               OR v_child.economic_actual_usd IS NOT NULL OR v_child.billed_actual_usd IS NOT NULL
               OR v_child.economic_actual_krw IS NOT NULL OR v_child.billed_actual_krw IS NOT NULL THEN
                RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
            END IF;
            RETURN pg_catalog.jsonb_build_object('disposition','released','created',FALSE,'replayed',TRUE,'operationId',v_child.id);
        END IF;
        IF v_child.status NOT IN ('reserved','started','ambiguous')
           OR v_child.economic_actual_usd IS NOT NULL OR v_child.billed_actual_usd IS NOT NULL THEN
            RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
        END IF;
        v_was_active:=v_child.status IN ('reserved','started');
        UPDATE public.analysis_revenue_cost_operations
           SET status='released',started_at=NULL,terminal_at=v_ai.terminalized_at
         WHERE id=v_child.id;
        UPDATE public.analysis_revenue_run_ledgers
           SET reserved_cost_krw=reserved_cost_krw-CASE WHEN v_was_active THEN v_child.reserved_krw ELSE 0 END
         WHERE request_id=p_request_id;
        PERFORM public.analysis_revenue_ai_cost_refresh_review_v1(p_request_id);
        RETURN pg_catalog.jsonb_build_object('disposition','released','created',TRUE,'replayed',FALSE,'operationId',v_child.id);
    END IF;

    IF v_ai.usage_metadata_status='complete' AND v_ai.usage_complete=TRUE
       AND v_ai.prompt_tokens IS NOT NULL AND v_ai.completion_tokens IS NOT NULL
       AND v_ai.total_tokens IS NOT NULL AND v_ai.thinking_tokens IS NOT NULL
       AND v_ai.total_tokens=v_ai.prompt_tokens+v_ai.completion_tokens+v_ai.thinking_tokens
       AND v_ai.estimated_cost_usd IS NOT NULL AND v_ai.terminalized_at IS NOT NULL THEN
        v_actual_usd:=public.analysis_revenue_ai_cost_usd_v1(v_ai.model_name,v_ai.location,v_ai.prompt_tokens,v_ai.completion_tokens,v_ai.thinking_tokens);
        IF v_ai.estimated_cost_usd IS DISTINCT FROM v_actual_usd THEN
            v_actual_usd:=NULL;
        END IF;
    ELSE
        v_actual_usd:=NULL;
    END IF;

    -- Missing, malformed, or price-drifted terminal usage is never converted
    -- to zero.  It consumes no further automatic budget and becomes durable
    -- manual-review evidence with the source terminal timestamp.
    IF v_actual_usd IS NULL THEN
        IF v_child.status='ambiguous' AND v_child.started_at IS NOT NULL
           AND v_child.terminal_at IS NOT DISTINCT FROM v_ai.terminalized_at
           AND v_child.economic_actual_usd IS NULL AND v_child.billed_actual_usd IS NULL THEN
            RETURN pg_catalog.jsonb_build_object('disposition','ambiguous','created',FALSE,'replayed',TRUE,'operationId',v_child.id,'reason','ambiguous_external_call');
        END IF;
        IF v_child.status NOT IN ('reserved','started','ambiguous') THEN
            UPDATE public.analysis_revenue_run_ledgers
               SET status='manual_review',manual_review_reason=CASE
                   WHEN manual_review_reason IN ('cost_overrun','cost_denied') THEN manual_review_reason
                   ELSE 'ambiguous_external_call' END
             WHERE request_id=p_request_id;
            RETURN pg_catalog.jsonb_build_object('disposition','ambiguous','created',FALSE,'replayed',FALSE,'operationId',v_child.id,'reason','ambiguous_external_call');
        END IF;
        v_was_active:=v_child.status IN ('reserved','started');
        v_start_at:=COALESCE(v_child.started_at,v_ai.created_at);
        IF v_ai.terminalized_at IS NULL OR v_ai.terminalized_at < v_start_at THEN
            RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
        END IF;
        UPDATE public.analysis_revenue_cost_operations
           SET status='ambiguous',started_at=v_start_at,terminal_at=v_ai.terminalized_at
         WHERE id=v_child.id;
        UPDATE public.analysis_revenue_run_ledgers
           SET reserved_cost_krw=reserved_cost_krw-CASE WHEN v_was_active THEN v_child.reserved_krw ELSE 0 END,
               status='manual_review',manual_review_reason=CASE
                   WHEN manual_review_reason IN ('cost_overrun','cost_denied') THEN manual_review_reason
                   ELSE 'ambiguous_external_call' END
         WHERE request_id=p_request_id;
        RETURN pg_catalog.jsonb_build_object('disposition','ambiguous','created',TRUE,'replayed',FALSE,'operationId',v_child.id,'reason','ambiguous_external_call');
    END IF;

    v_actual_krw:=public.analysis_revenue_cost_ceil_krw(v_actual_usd);
    IF v_child.status='settled' THEN
        IF v_child.started_at IS NULL OR v_child.terminal_at IS DISTINCT FROM v_ai.terminalized_at
           OR v_child.economic_actual_usd IS DISTINCT FROM v_actual_usd OR v_child.billed_actual_usd IS DISTINCT FROM 0
           OR v_child.economic_actual_krw IS DISTINCT FROM v_actual_krw OR v_child.billed_actual_krw IS DISTINCT FROM 0 THEN
            UPDATE public.analysis_revenue_run_ledgers
               SET status='manual_review',manual_review_reason=CASE
                   WHEN manual_review_reason IN ('cost_overrun','cost_denied') THEN manual_review_reason
                   ELSE 'ambiguous_external_call' END
             WHERE request_id=p_request_id;
            RETURN pg_catalog.jsonb_build_object('disposition','ambiguous','created',FALSE,'replayed',FALSE,'operationId',v_child.id,'reason','ambiguous_external_call');
        END IF;
        RETURN pg_catalog.jsonb_build_object('disposition','settled','created',FALSE,'replayed',TRUE,'operationId',v_child.id);
    END IF;
    IF v_child.status NOT IN ('reserved','started','ambiguous') THEN
        UPDATE public.analysis_revenue_run_ledgers
           SET status='manual_review',manual_review_reason=CASE
               WHEN manual_review_reason IN ('cost_overrun','cost_denied') THEN manual_review_reason
               ELSE 'ambiguous_external_call' END
         WHERE request_id=p_request_id;
        RETURN pg_catalog.jsonb_build_object('disposition','ambiguous','created',FALSE,'replayed',FALSE,'operationId',v_child.id,'reason','ambiguous_external_call');
    END IF;
    v_was_active:=v_child.status IN ('reserved','started');
    v_start_at:=COALESCE(v_child.started_at,v_ai.created_at);
    IF v_ai.terminalized_at < v_start_at THEN
        RAISE EXCEPTION USING MESSAGE='REVENUE_COST_OPERATION_FENCE';
    END IF;
    UPDATE public.analysis_revenue_cost_operations
       SET status='settled',started_at=v_start_at,terminal_at=v_ai.terminalized_at,
           economic_actual_usd=v_actual_usd,billed_actual_usd=0,
           economic_actual_krw=v_actual_krw,billed_actual_krw=0,
           lifecycle_anomaly=CASE WHEN v_child.status='reserved' THEN 'skipped_start' ELSE lifecycle_anomaly END
     WHERE id=v_child.id;
    UPDATE public.analysis_revenue_run_ledgers
       SET reserved_cost_krw=reserved_cost_krw-CASE WHEN v_was_active THEN v_child.reserved_krw ELSE 0 END,
           economic_actual_krw=economic_actual_krw+v_actual_krw,
           actual_cost_krw=actual_cost_krw+v_actual_krw
     WHERE request_id=p_request_id;
    IF v_actual_usd > v_expected_usd OR v_parent.economic_actual_krw+v_actual_krw > v_parent.cost_cap_krw THEN
        UPDATE public.analysis_revenue_run_ledgers
           SET status='manual_review',manual_review_reason='cost_overrun'
         WHERE request_id=p_request_id;
    ELSE
        PERFORM public.analysis_revenue_ai_cost_refresh_review_v1(p_request_id);
    END IF;
    RETURN pg_catalog.jsonb_build_object('disposition','settled','created',TRUE,'replayed',FALSE,'operationId',v_child.id);
END;
$$;


--
-- Name: settle_analysis_v2_provider_run_for_cleanup(uuid, text, text, text, text, numeric, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_analysis_v2_provider_run_for_cleanup(p_reservation_token uuid, p_run_id text, p_logical_provider text, p_actor_id text, p_credential_slot text, p_max_charge_usd numeric, p_status text, p_actual_usage_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_run public.analysis_v2_provider_runs%ROWTYPE;
BEGIN
    IF p_reservation_token IS NULL OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_logical_provider NOT IN ('apify', 'coderx')
       OR p_actor_id !~ '^[A-Za-z0-9][A-Za-z0-9._~/-]{2,199}$'
       OR NOT public.analysis_v2_valid_apify_credential_slot(p_credential_slot)
       OR p_max_charge_usd IS NULL OR p_max_charge_usd NOT BETWEEN 0 AND 100000
       OR p_max_charge_usd <> pg_catalog.round(p_max_charge_usd, 12)
       OR p_status NOT IN ('succeeded', 'failed', 'aborted', 'timed_out')
       OR (p_actual_usage_usd IS NOT NULL AND (
            p_actual_usage_usd NOT BETWEEN 0 AND 100000
            OR p_actual_usage_usd <> pg_catalog.round(p_actual_usage_usd, 12)
       )) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_INVALID', ERRCODE = 'P0001';
    END IF;

    SELECT provider_run.* INTO v_run
    FROM public.analysis_v2_provider_runs AS provider_run
    WHERE provider_run.reservation_token = p_reservation_token
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_run.run_id IS DISTINCT FROM p_run_id
       OR v_run.logical_provider IS DISTINCT FROM p_logical_provider
       OR v_run.actor_id IS DISTINCT FROM p_actor_id
       OR v_run.credential_slot IS DISTINCT FROM p_credential_slot
       OR v_run.max_charge_usd IS DISTINCT FROM p_max_charge_usd
       OR p_actual_usage_usd > v_run.max_charge_usd + 0.000000001 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.analysis_v2_provider_cleanup_intents AS intent
        WHERE intent.request_id = v_run.request_id AND intent.completed_at IS NULL
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_NOT_READY', ERRCODE = 'P0001';
    END IF;

    IF v_run.status IN ('succeeded', 'failed', 'aborted', 'timed_out') THEN
        IF v_run.status IS DISTINCT FROM p_status
           OR (p_actual_usage_usd IS NOT NULL
               AND v_run.actual_usage_usd IS NOT NULL
               AND v_run.actual_usage_usd IS DISTINCT FROM p_actual_usage_usd) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_CONFLICT', ERRCODE = 'P0001';
        END IF;
        IF p_actual_usage_usd IS NOT NULL AND v_run.actual_usage_usd IS NULL THEN
            UPDATE public.analysis_v2_provider_runs AS provider_run
            SET actual_usage_usd = p_actual_usage_usd,
                usage_reconciled_at = v_now, updated_at = v_now
            WHERE provider_run.reservation_token = p_reservation_token
            RETURNING provider_run.* INTO v_run;
        END IF;
        RETURN public.analysis_v2_provider_run_json(v_run);
    END IF;
    IF v_run.status <> 'running' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_PROVIDER_RUN_CLEANUP_CONFLICT', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_v2_provider_runs AS provider_run
    SET status = p_status,
        actual_usage_usd = p_actual_usage_usd,
        terminalized_at = v_now,
        usage_reconciled_at = CASE
            WHEN p_actual_usage_usd IS NULL THEN NULL ELSE v_now
        END,
        updated_at = v_now
    WHERE provider_run.reservation_token = p_reservation_token
    RETURNING provider_run.* INTO v_run;
    RETURN public.analysis_v2_provider_run_json(v_run);
END;
$_$;


--
-- Name: settle_vertex_ai_budget(text, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_vertex_ai_budget(p_reservation_key text, p_reservation_id uuid, p_actual_cost_usd numeric DEFAULT NULL::numeric) RETURNS TABLE(reservation_id uuid, reservation_key text, run_id text, order_id text, day_key date, route text, model_name text, attempt integer, estimated_cost_usd numeric, actual_cost_usd numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_row public.vertex_ai_budget_reservations%ROWTYPE;
BEGIN
    IF p_reservation_key IS NULL OR p_reservation_id IS NULL
       OR p_actual_cost_usd IS NOT NULL
          AND (p_actual_cost_usd < 0 OR p_actual_cost_usd > 1000000
               OR p_actual_cost_usd <> pg_catalog.round(p_actual_cost_usd, 12)) THEN
        RAISE EXCEPTION 'VERTEX_AI_BUDGET_SETTLEMENT_INVALID';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('vertex-ai-budget:all-scopes', 0)
    );
    SELECT reservation.*
      INTO v_row
      FROM public.vertex_ai_budget_reservations AS reservation
     WHERE reservation.reservation_key = p_reservation_key
     FOR UPDATE;
    IF NOT FOUND OR v_row.reservation_id IS DISTINCT FROM p_reservation_id THEN
        RAISE EXCEPTION 'VERTEX_AI_BUDGET_RESERVATION_UNKNOWN';
    END IF;
    IF v_row.state = 'cancelled' THEN
        RAISE EXCEPTION 'VERTEX_AI_BUDGET_RESERVATION_CANCELLED';
    END IF;
    IF v_row.state = 'settled'
       AND v_row.actual_cost_usd IS NOT NULL
       AND p_actual_cost_usd IS NOT NULL
       AND v_row.actual_cost_usd IS DISTINCT FROM p_actual_cost_usd THEN
        RAISE EXCEPTION 'VERTEX_AI_BUDGET_SETTLEMENT_IDENTITY_DRIFT';
    END IF;
    IF v_row.state = 'reserved' THEN
        UPDATE public.vertex_ai_budget_reservations AS reservation
           SET state = 'settled',
               actual_cost_usd = p_actual_cost_usd,
               usage_unknown = p_actual_cost_usd IS NULL,
               updated_at = pg_catalog.clock_timestamp()
         WHERE reservation.reservation_key = p_reservation_key;
        v_row.state := 'settled';
        v_row.actual_cost_usd := p_actual_cost_usd;
        v_row.usage_unknown := p_actual_cost_usd IS NULL;
    ELSIF v_row.state = 'settled' AND v_row.actual_cost_usd IS NULL
          AND p_actual_cost_usd IS NOT NULL THEN
        UPDATE public.vertex_ai_budget_reservations AS reservation
           SET actual_cost_usd = p_actual_cost_usd,
               usage_unknown = FALSE,
               updated_at = pg_catalog.clock_timestamp()
         WHERE reservation.reservation_key = p_reservation_key;
        v_row.actual_cost_usd := p_actual_cost_usd;
        v_row.usage_unknown := FALSE;
    END IF;
    RETURN QUERY SELECT
        v_row.reservation_id, v_row.reservation_key, v_row.run_id, v_row.order_id,
        v_row.day_key, v_row.route, v_row.model_name, v_row.attempt,
        v_row.estimated_cost_usd, v_row.actual_cost_usd;
END;
$$;


--
-- Name: snapshot_vertex_ai_budget(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_vertex_ai_budget() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
WITH active AS (
    SELECT
        reservation.run_id,
        reservation.order_id,
        reservation.day_key::TEXT AS day_key,
        COALESCE(reservation.actual_cost_usd, reservation.estimated_cost_usd) AS amount
    FROM public.vertex_ai_budget_reservations AS reservation
    WHERE reservation.state IN ('reserved', 'settled')
),
run_totals AS (
    SELECT COALESCE(jsonb_object_agg(run_id, amount), '{}'::JSONB) AS value
    FROM (SELECT run_id, pg_catalog.sum(amount) AS amount FROM active GROUP BY run_id) grouped
),
order_totals AS (
    SELECT COALESCE(jsonb_object_agg(order_id, amount), '{}'::JSONB) AS value
    FROM (SELECT order_id, pg_catalog.sum(amount) AS amount FROM active GROUP BY order_id) grouped
),
day_totals AS (
    SELECT COALESCE(jsonb_object_agg(day_key, amount), '{}'::JSONB) AS value
    FROM (SELECT day_key, pg_catalog.sum(amount) AS amount FROM active GROUP BY day_key) grouped
)
SELECT jsonb_build_object(
    'run', (SELECT value FROM run_totals),
    'order', (SELECT value FROM order_totals),
    'day', (SELECT value FROM day_totals)
);
$$;


--
-- Name: start_demo_analysis_run(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_demo_analysis_run(p_run_id uuid, p_user_id uuid) RETURNS TABLE(id uuid, user_id uuid, target_instagram_id text, fixture_version text, idempotency_key text, duration_seconds integer, created_at timestamp with time zone, started_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.demo_analysis_runs
  set started_at = coalesce(started_at, clock_timestamp())
  where id = p_run_id and user_id = p_user_id
    and (
      started_at IS NOT NULL
      OR created_at + interval '30 minutes' > clock_timestamp()
    )
  returning id, user_id, target_instagram_id, fixture_version, idempotency_key,
    duration_seconds, created_at, started_at;
$$;


--
-- Name: takeover_analysis_v2_terminal_failure(uuid, text, integer, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.takeover_analysis_v2_terminal_failure(p_request_id uuid, p_job_key text, p_dispatch_generation integer, p_dispatch_token uuid, p_claim_token uuid, p_lease_seconds integer DEFAULT 600) RETURNS TABLE(claimed boolean, job_status text, attempt_count integer, lease_expires_at timestamp with time zone, track text, job_kind text, batch integer, input_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_intent public.analysis_v2_provider_cleanup_intents%ROWTYPE;
BEGIN
    IF p_request_id IS NULL
       OR p_job_key IS NULL
       OR p_job_key !~ '^[a-z0-9][a-z0-9:._-]{0,159}$'
       OR p_dispatch_generation IS NULL
       OR p_dispatch_generation NOT BETWEEN 1 AND 1000
       OR p_dispatch_token IS NULL
       OR p_claim_token IS NULL
       OR p_lease_seconds IS NULL
       OR p_lease_seconds NOT BETWEEN 30 AND 600 THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_TERMINAL_FAILURE_TAKEOVER_INVALID', ERRCODE = 'P0001';
    END IF;

    -- Match the scheduler's canonical lock order. Provider reservations also
    -- take preflight -> request -> job locks, so the active-set proof below
    -- cannot race a new paid start.
    PERFORM 1
    FROM public.analysis_preflights AS preflight
    WHERE preflight.consumed_request_id = p_request_id
    FOR UPDATE;

    SELECT analysis_request.* INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
      AND analysis_request.pipeline_version = 'v2'
    FOR UPDATE;
    IF NOT FOUND OR v_request.status NOT IN ('pending', 'processing') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_TERMINAL_FAILURE_TAKEOVER_NOT_READY', ERRCODE = 'P0001';
    END IF;

    SELECT job.* INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_TERMINAL_FAILURE_TAKEOVER_NOT_READY', ERRCODE = 'P0001';
    END IF;
    IF v_job.dispatch_generation IS DISTINCT FROM p_dispatch_generation
       OR v_job.dispatch_reservation_token IS DISTINCT FROM p_dispatch_token THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_TERMINAL_FAILURE_TAKEOVER_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    SELECT intent.* INTO v_intent
    FROM public.analysis_v2_provider_cleanup_intents AS intent
    WHERE intent.request_id = p_request_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_intent.completed_at IS NOT NULL
       OR v_intent.failed_job_key IS DISTINCT FROM p_job_key
       OR v_intent.failed_job_input_hash IS DISTINCT FROM v_job.input_hash
       OR v_intent.failed_job_input_hash IS DISTINCT FROM (
            SELECT job.input_hash
            FROM public.analysis_pipeline_jobs AS job
            WHERE job.request_id = p_request_id AND job.job_key = p_job_key
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_TERMINAL_FAILURE_TAKEOVER_NOT_READY', ERRCODE = 'P0001';
    END IF;

    IF v_job.status IS DISTINCT FROM 'processing'
       OR v_job.lease_token IS NULL
       OR (
            v_job.lease_token IS DISTINCT FROM v_intent.failed_claim_token
            AND v_job.lease_token IS DISTINCT FROM p_claim_token
       ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_TERMINAL_FAILURE_TAKEOVER_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;

    -- A terminal row is safe. A running row, or a starting row with no
    -- database-owner confirmation that no remote run exists, is not.
    IF EXISTS (
        SELECT 1
        FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = p_request_id
          AND provider_run.status = 'running'
    ) OR EXISTS (
        SELECT 1
        FROM public.analysis_v2_provider_runs AS provider_run
        WHERE provider_run.request_id = p_request_id
          AND provider_run.status = 'starting'
          AND NOT EXISTS (
                SELECT 1
                FROM public.analysis_v2_unconfirmed_start_resolutions AS resolution
                WHERE resolution.reservation_token = provider_run.reservation_token
          )
    ) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_TERMINAL_FAILURE_TAKEOVER_ACTIVE_PROVIDER', ERRCODE = 'P0001';
    END IF;

    -- Repeated delivery by the current owner is a no-op. A competing owner
    -- cannot pass the intent/job fence while the current takeover lease is
    -- live; if that new owner also crashes, its expired lease may be taken
    -- over by the same fenced path.
    IF v_job.lease_token IS DISTINCT FROM p_claim_token
       AND v_intent.terminalization_takeover_at IS NOT NULL
       AND v_job.lease_expires_at > v_now THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_TERMINAL_FAILURE_TAKEOVER_FENCE_MISMATCH', ERRCODE = 'P0001';
    END IF;
    IF v_job.lease_token IS DISTINCT FROM p_claim_token THEN
        UPDATE public.analysis_pipeline_jobs AS job
        SET lease_token = p_claim_token,
            lease_expires_at = v_now + p_lease_seconds * INTERVAL '1 second',
            updated_at = v_now
        WHERE job.request_id = p_request_id
          AND job.job_key = p_job_key
        RETURNING job.* INTO v_job;
        UPDATE public.analysis_v2_provider_cleanup_intents AS intent
        SET failed_claim_token = p_claim_token
            ,terminalization_takeover_at = v_now
        WHERE intent.request_id = p_request_id;
    END IF;

    RETURN QUERY SELECT
        TRUE,
        v_job.status::TEXT,
        v_job.attempt_count,
        v_job.lease_expires_at,
        v_job.track::TEXT,
        v_job.kind::TEXT,
        v_job.batch,
        v_job.input_hash::TEXT;
END;
$_$;


--
-- Name: terminalize_analysis_v2_ai_attempt(uuid, text, uuid, text, smallint, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.terminalize_analysis_v2_ai_attempt(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_attempt smallint, p_reservation_token uuid, p_status text, p_telemetry jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF p_status = 'success' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_RESULT_REQUIRED',
            ERRCODE = 'P0001';
    END IF;
    RETURN public.analysis_v2_terminalize_ai_attempt_internal(
        p_request_id,
        p_job_key,
        p_claim_token,
        p_operation_key,
        p_attempt,
        p_reservation_token,
        p_status,
        p_telemetry
    );
END;
$$;


--
-- Name: terminalize_analysis_v2_ai_attempt_with_result(uuid, text, uuid, text, smallint, uuid, jsonb, jsonb, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.terminalize_analysis_v2_ai_attempt_with_result(p_request_id uuid, p_job_key text, p_claim_token uuid, p_operation_key text, p_attempt smallint, p_reservation_token uuid, p_telemetry jsonb, p_result_identity jsonb, p_result jsonb, p_result_canonical text, p_result_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_attempt JSONB;
    v_request public.analysis_requests%ROWTYPE;
    v_job public.analysis_pipeline_jobs%ROWTYPE;
    v_cache_key TEXT;
    v_result_hash TEXT;
    v_checkpoint public.analysis_v2_ai_result_checkpoints%ROWTYPE;
    v_cached public.analysis_v2_ai_global_result_cache%ROWTYPE;
    v_now TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_result_identity IS NULL
       OR p_result IS NULL
       OR p_result_canonical IS NULL
       OR p_result_hash IS NULL
       OR p_telemetry IS NULL
       OR NOT public.analysis_v2_valid_ai_result_identity(p_result_identity)
       OR NOT public.analysis_v2_valid_ai_result_envelope(
            p_result,
            p_result_canonical,
            p_result_hash
       )
       OR p_operation_key IS DISTINCT FROM
            public.analysis_v2_ai_result_operation_key(p_result_identity)
       OR p_telemetry->>'stage' IS DISTINCT FROM p_result_identity->>'stage'
       OR p_telemetry->>'model_name' IS DISTINCT FROM p_result_identity->>'model_name'
       OR NULLIF(p_telemetry->>'thinking_level', '') IS DISTINCT FROM
            NULLIF(p_result_identity->>'thinking_level', '')
       OR NULLIF(p_telemetry->>'media_resolution', '') IS DISTINCT FROM
            NULLIF(p_result_identity->>'media_resolution', '')
       OR p_telemetry->>'prompt_version' IS DISTINCT FROM
            p_result_identity->>'prompt_version'
       OR p_telemetry->>'schema_version' IS DISTINCT FROM
            p_result_identity->>'schema_version'
       OR p_telemetry->>'max_output_tokens' IS DISTINCT FROM
            p_result_identity->>'max_output_tokens'
       OR p_telemetry->>'finish_reason' IS DISTINCT FROM 'STOP' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ANALYSIS_V2_AI_RESULT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    v_cache_key := public.analysis_v2_ai_result_cache_key(p_result_identity);
    v_result_hash := p_result_hash;

    -- The nested SECURITY DEFINER call participates in this transaction. Active-fence
    -- persistence failures roll back terminalization; a lost fence returns a committed,
    -- telemetry-only outcome without mutating a request checkpoint or global cache row.
    v_attempt := public.analysis_v2_terminalize_ai_attempt_internal(
        p_request_id,
        p_job_key,
        p_claim_token,
        p_operation_key,
        p_attempt,
        p_reservation_token,
        'success',
        p_telemetry
    );

    SELECT analysis_request.*
    INTO v_request
    FROM public.analysis_requests AS analysis_request
    WHERE analysis_request.id = p_request_id
    FOR UPDATE;

    SELECT job.*
    INTO v_job
    FROM public.analysis_pipeline_jobs AS job
    WHERE job.request_id = p_request_id
      AND job.job_key = p_job_key
    FOR UPDATE;

    v_now := pg_catalog.clock_timestamp();
    IF v_request.id IS NULL
       OR v_job.request_id IS NULL
       OR v_request.status NOT IN ('pending', 'processing')
       OR v_job.status <> 'processing'
       OR v_job.lease_token IS DISTINCT FROM p_claim_token
       OR v_job.lease_expires_at IS NULL
       OR v_job.lease_expires_at <= v_now THEN
        RETURN pg_catalog.jsonb_build_object(
            'outcome', 'fenced',
            'requestId', p_request_id,
            'operationKey', p_operation_key,
            'attempt', p_attempt,
            'reservationToken', p_reservation_token
        );
    END IF;

    SELECT checkpoint.*
    INTO v_checkpoint
    FROM public.analysis_v2_ai_result_checkpoints AS checkpoint
    WHERE checkpoint.request_id = p_request_id
      AND checkpoint.operation_key = p_operation_key
    FOR UPDATE;

    IF FOUND THEN
        IF v_checkpoint.job_key IS DISTINCT FROM p_job_key
           OR v_checkpoint.cache_key IS DISTINCT FROM v_cache_key
           OR v_checkpoint.stage IS DISTINCT FROM p_result_identity->>'stage'
           OR v_checkpoint.model_name IS DISTINCT FROM p_result_identity->>'model_name'
           OR v_checkpoint.thinking_level IS DISTINCT FROM
                NULLIF(p_result_identity->>'thinking_level', '')
           OR v_checkpoint.media_resolution IS DISTINCT FROM
                NULLIF(p_result_identity->>'media_resolution', '')
           OR v_checkpoint.prompt_version IS DISTINCT FROM
                p_result_identity->>'prompt_version'
           OR v_checkpoint.schema_version IS DISTINCT FROM
                (p_result_identity->>'schema_version')::SMALLINT
           OR v_checkpoint.max_output_tokens IS DISTINCT FROM
                (p_result_identity->>'max_output_tokens')::INTEGER
           OR v_checkpoint.input_hash IS DISTINCT FROM p_result_identity->>'input_hash'
           OR v_checkpoint.media_snapshot_hash IS DISTINCT FROM
                p_result_identity->>'media_snapshot_hash'
           OR v_checkpoint.cache_scope IS DISTINCT FROM p_result_identity->>'cache_scope'
           OR v_checkpoint.source IS DISTINCT FROM 'generated'
           OR v_checkpoint.attempt IS DISTINCT FROM p_attempt
           OR v_checkpoint.reservation_token IS DISTINCT FROM p_reservation_token
           OR v_checkpoint.result_hash IS DISTINCT FROM v_result_hash
           OR v_checkpoint.result_canonical_json IS DISTINCT FROM p_result_canonical THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ANALYSIS_V2_AI_RESULT_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN pg_catalog.jsonb_build_object(
            'outcome', 'checkpointed',
            'checkpoint', public.analysis_v2_ai_result_checkpoint_json(v_checkpoint)
        );
    END IF;

    INSERT INTO public.analysis_v2_ai_result_checkpoints (
        request_id,
        job_key,
        operation_key,
        cache_key,
        stage,
        model_name,
        thinking_level,
        media_resolution,
        prompt_version,
        schema_version,
        max_output_tokens,
        input_hash,
        media_snapshot_hash,
        cache_scope,
        source,
        attempt,
        reservation_token,
        result_json,
        result_canonical_json,
        result_hash,
        created_at
    ) VALUES (
        p_request_id,
        p_job_key,
        p_operation_key,
        v_cache_key,
        p_result_identity->>'stage',
        p_result_identity->>'model_name',
        NULLIF(p_result_identity->>'thinking_level', ''),
        NULLIF(p_result_identity->>'media_resolution', ''),
        p_result_identity->>'prompt_version',
        (p_result_identity->>'schema_version')::SMALLINT,
        (p_result_identity->>'max_output_tokens')::INTEGER,
        p_result_identity->>'input_hash',
        p_result_identity->>'media_snapshot_hash',
        p_result_identity->>'cache_scope',
        'generated',
        p_attempt,
        p_reservation_token,
        p_result,
        p_result_canonical,
        v_result_hash,
        v_now
    )
    RETURNING * INTO v_checkpoint;

    IF p_result_identity->>'cache_scope' = 'global_ttl' THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(
                'analysis-v2-ai-result-cache-key:' || v_cache_key,
                0
            )
        );
        v_now := pg_catalog.clock_timestamp();

        DELETE FROM public.analysis_v2_ai_global_result_cache AS cache
        WHERE cache.cache_key = v_cache_key
          AND cache.expires_at <= v_now;

        SELECT cache.*
        INTO v_cached
        FROM public.analysis_v2_ai_global_result_cache AS cache
        WHERE cache.cache_key = v_cache_key
        FOR UPDATE;

        IF FOUND THEN
            IF v_cached.stage IS DISTINCT FROM p_result_identity->>'stage'
               OR v_cached.model_name IS DISTINCT FROM p_result_identity->>'model_name'
               OR v_cached.thinking_level IS DISTINCT FROM
                    NULLIF(p_result_identity->>'thinking_level', '')
               OR v_cached.media_resolution IS DISTINCT FROM
                    NULLIF(p_result_identity->>'media_resolution', '')
               OR v_cached.prompt_version IS DISTINCT FROM
                    p_result_identity->>'prompt_version'
               OR v_cached.schema_version IS DISTINCT FROM
                    (p_result_identity->>'schema_version')::SMALLINT
               OR v_cached.max_output_tokens IS DISTINCT FROM
                    (p_result_identity->>'max_output_tokens')::INTEGER
               OR v_cached.input_hash IS DISTINCT FROM p_result_identity->>'input_hash'
               OR v_cached.media_snapshot_hash IS DISTINCT FROM
                    p_result_identity->>'media_snapshot_hash' THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'ANALYSIS_V2_AI_RESULT_CONFLICT',
                    ERRCODE = 'P0001';
            END IF;

            IF NOT public.analysis_v2_valid_ai_result_envelope(
                v_cached.result_json,
                v_cached.result_canonical_json,
                v_cached.result_hash
            ) THEN
                DELETE FROM public.analysis_v2_ai_global_result_cache AS cache
                WHERE cache.cache_key = v_cache_key;
                v_cached.cache_key := NULL;
            END IF;
        END IF;

        IF v_cached.cache_key IS NULL THEN
            INSERT INTO public.analysis_v2_ai_global_result_cache (
                cache_key,
                stage,
                model_name,
                thinking_level,
                media_resolution,
                prompt_version,
                schema_version,
                max_output_tokens,
                input_hash,
                media_snapshot_hash,
                result_json,
                result_canonical_json,
                result_hash,
                created_at,
                expires_at,
                last_accessed_at
            ) VALUES (
                v_cache_key,
                p_result_identity->>'stage',
                p_result_identity->>'model_name',
                NULLIF(p_result_identity->>'thinking_level', ''),
                NULLIF(p_result_identity->>'media_resolution', ''),
                p_result_identity->>'prompt_version',
                (p_result_identity->>'schema_version')::SMALLINT,
                (p_result_identity->>'max_output_tokens')::INTEGER,
                p_result_identity->>'input_hash',
                p_result_identity->>'media_snapshot_hash',
                p_result,
                p_result_canonical,
                v_result_hash,
                v_now,
                v_now + INTERVAL '6 hours',
                v_now
            );
        END IF;

        PERFORM public.analysis_v2_maintain_ai_global_result_cache(2000);
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'outcome', 'checkpointed',
        'checkpoint', public.analysis_v2_ai_result_checkpoint_json(v_checkpoint)
    );
END;
$$;


--
-- Name: terminalize_analysis_v2_profile_provider_canary_run(uuid, integer, uuid, text, integer, integer, integer, integer, integer, integer, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.terminalize_analysis_v2_profile_provider_canary_run(p_source_request_id uuid, p_repetition integer, p_reservation_token uuid, p_run_id text, p_terminal_count integer, p_success_count integer, p_unavailable_count integer, p_incomplete_count integer, p_other_failure_count integer, p_critical_success_count integer, p_latency_ms integer, p_build_verified boolean, p_restricted_access_verified boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_state TEXT;
    v_run public.analysis_v2_profile_provider_canary_runs%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL OR p_repetition NOT IN (1, 2)
       OR p_reservation_token IS NULL OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_terminal_count IS DISTINCT FROM 15
       OR p_success_count NOT BETWEEN 0 AND 15
       OR p_unavailable_count NOT BETWEEN 0 AND 15
       OR p_incomplete_count NOT BETWEEN 0 AND 15
       OR p_other_failure_count NOT BETWEEN 0 AND 15
       OR p_critical_success_count NOT BETWEEN 0 AND 3
       OR p_success_count + p_unavailable_count + p_incomplete_count + p_other_failure_count <> 15
       OR p_latency_ms NOT BETWEEN 0 AND 300000
       OR p_build_verified IS NULL
       OR p_restricted_access_verified IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_INVALID', ERRCODE = 'P0001';
    END IF;
    v_state := CASE WHEN p_success_count = 15 AND p_unavailable_count = 0
        AND p_incomplete_count = 0 AND p_other_failure_count = 0
        AND p_critical_success_count = 3 AND p_latency_ms <= 60000
        AND p_build_verified THEN 'succeeded' ELSE 'failed' END;

    SELECT canary_run.* INTO v_run
    FROM public.analysis_v2_profile_provider_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.repetition = p_repetition
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_NOT_FOUND', ERRCODE = 'P0001';
    END IF;
    IF v_run.reservation_token IS DISTINCT FROM p_reservation_token
       OR v_run.run_id IS DISTINCT FROM p_run_id THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_IDENTITY_CONFLICT', ERRCODE = 'P0001';
    END IF;
    IF v_run.state IN ('succeeded', 'failed') THEN
        IF v_run.state IS DISTINCT FROM v_state OR v_run.terminal_count IS DISTINCT FROM 15
           OR v_run.success_count IS DISTINCT FROM p_success_count
           OR v_run.unavailable_count IS DISTINCT FROM p_unavailable_count
           OR v_run.incomplete_count IS DISTINCT FROM p_incomplete_count
           OR v_run.other_failure_count IS DISTINCT FROM p_other_failure_count
           OR v_run.critical_success_count IS DISTINCT FROM p_critical_success_count
           OR v_run.latency_ms IS DISTINCT FROM p_latency_ms
           OR v_run.build_verified IS DISTINCT FROM p_build_verified
           OR v_run.restricted_access_verified IS DISTINCT FROM p_restricted_access_verified THEN
            RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_TERMINAL_CONFLICT', ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_profile_provider_canary_run_json(v_run);
    END IF;
    IF v_run.state <> 'running' THEN
        RAISE EXCEPTION USING MESSAGE = 'PROFILE_PROVIDER_CANARY_RUN_STATE_CONFLICT', ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_v2_profile_provider_canary_runs AS canary_run
    SET state = v_state, terminal_count = 15,
        success_count = p_success_count, unavailable_count = p_unavailable_count,
        incomplete_count = p_incomplete_count, other_failure_count = p_other_failure_count,
        critical_success_count = p_critical_success_count, latency_ms = p_latency_ms,
        build_verified = p_build_verified,
        restricted_access_verified = p_restricted_access_verified,
        terminalized_at = v_now, updated_at = v_now
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-fallback-replacement-canary-v1'
      AND canary_run.repetition = p_repetition
    RETURNING canary_run.* INTO v_run;
    RETURN public.analysis_v2_profile_provider_canary_run_json(v_run);
END;
$_$;


--
-- Name: terminalize_analysis_v2_profile_repair_canary_run(uuid, integer, uuid, text, text, integer, integer, integer, integer, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.terminalize_analysis_v2_profile_repair_canary_run(p_source_request_id uuid, p_repetition integer, p_reservation_token uuid, p_run_id text, p_state text, p_terminal_count integer, p_success_count integer, p_unavailable_count integer, p_incomplete_count integer, p_other_failure_count integer, p_critical_recovered_count integer, p_latency_ms integer, p_gate_passed boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_run public.analysis_v2_profile_repair_canary_runs%ROWTYPE;
BEGIN
    IF p_source_request_id IS NULL
       OR p_repetition NOT IN (1, 2)
       OR p_reservation_token IS NULL
       OR p_run_id IS NULL
       OR p_run_id !~ '^[A-Za-z0-9]{8,64}$'
       OR p_state NOT IN ('succeeded', 'failed')
       OR p_terminal_count IS DISTINCT FROM 15
       OR p_success_count NOT BETWEEN 0 AND 15
       OR p_unavailable_count NOT BETWEEN 0 AND 15
       OR p_incomplete_count NOT BETWEEN 0 AND 15
       OR p_other_failure_count NOT BETWEEN 0 AND 15
       OR p_critical_recovered_count NOT BETWEEN 0 AND p_success_count
       OR p_success_count + p_unavailable_count
            + p_incomplete_count + p_other_failure_count <> p_terminal_count
       OR p_latency_ms NOT BETWEEN 0 AND 300000
       OR p_gate_passed IS DISTINCT FROM (
            p_success_count >= 14
            AND p_unavailable_count <= 1
            AND p_other_failure_count = 0
            AND p_critical_recovered_count >= 1
       )
       OR p_gate_passed IS DISTINCT FROM (p_state = 'succeeded') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_INVALID',
            ERRCODE = 'P0001';
    END IF;
    SELECT canary_run.* INTO v_run
    FROM public.analysis_v2_profile_repair_canary_runs AS canary_run
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-repair-canary-v1'
      AND canary_run.repetition = p_repetition
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_NOT_FOUND',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.reservation_token IS DISTINCT FROM p_reservation_token
       OR v_run.run_id IS DISTINCT FROM p_run_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_IDENTITY_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    IF v_run.state IN ('succeeded', 'failed') THEN
        IF v_run.state IS DISTINCT FROM p_state
           OR v_run.terminal_count IS DISTINCT FROM p_terminal_count
           OR v_run.success_count IS DISTINCT FROM p_success_count
           OR v_run.unavailable_count IS DISTINCT FROM p_unavailable_count
           OR v_run.incomplete_count IS DISTINCT FROM p_incomplete_count
           OR v_run.other_failure_count IS DISTINCT FROM p_other_failure_count
           OR v_run.critical_recovered_count IS DISTINCT FROM p_critical_recovered_count
           OR v_run.latency_ms IS DISTINCT FROM p_latency_ms
           OR v_run.gate_passed IS DISTINCT FROM p_gate_passed THEN
            RAISE EXCEPTION USING
                MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_TERMINAL_CONFLICT',
                ERRCODE = 'P0001';
        END IF;
        RETURN public.analysis_v2_profile_repair_canary_run_json(v_run);
    END IF;
    IF v_run.state <> 'running' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'PROFILE_REPAIR_CANARY_RUN_STATE_CONFLICT',
            ERRCODE = 'P0001';
    END IF;
    UPDATE public.analysis_v2_profile_repair_canary_runs AS canary_run
    SET state = p_state,
        terminal_count = p_terminal_count,
        success_count = p_success_count,
        unavailable_count = p_unavailable_count,
        incomplete_count = p_incomplete_count,
        other_failure_count = p_other_failure_count,
        critical_recovered_count = p_critical_recovered_count,
        latency_ms = p_latency_ms,
        gate_passed = p_gate_passed,
        terminalized_at = v_now,
        updated_at = v_now
    WHERE canary_run.source_request_id = p_source_request_id
      AND canary_run.canary_version = 'profile-repair-canary-v1'
      AND canary_run.repetition = p_repetition
    RETURNING canary_run.* INTO v_run;
    RETURN public.analysis_v2_profile_repair_canary_run_json(v_run);
END;
$_$;


--
-- Name: unlink_landing_lead_journey_after_deletion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unlink_landing_lead_journey_after_deletion(p_subject_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    UPDATE public.landing_leads
    SET auth_user_id = NULL,
        mapping_status = 'unlinked_after_deletion',
        mapping_source = 'account_deletion_v1',
        linked_at = NULL
    WHERE (journey_id = p_subject_id OR auth_user_id = p_subject_id)
      AND mapping_status = 'authenticated_user';
    RETURN FOUND;
END;
$$;


--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
            BEGIN
                NEW.updated_at := pg_catalog.now();
                RETURN NEW;
            END;
            $$;


--
-- Name: upsert_analysis_apify_paid_credit_snapshot(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_analysis_apify_paid_credit_snapshot(p_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_slot TEXT;
    v_monthly_limit_usd NUMERIC;
    v_monthly_usage_usd NUMERIC;
    v_cycle_start_at TIMESTAMP WITH TIME ZONE;
    v_cycle_end_at TIMESTAMP WITH TIME ZONE;
    v_observed_at TIMESTAMP WITH TIME ZONE;
BEGIN
    IF pg_catalog.jsonb_typeof(p_snapshot) <> 'object'
       OR NOT p_snapshot ?& ARRAY[
            'credentialSlot', 'monthlyLimitUsd', 'monthlyUsageUsd',
            'billingCycleStartAt', 'billingCycleEndAt', 'observedAt', 'healthState'
       ]
       OR p_snapshot - ARRAY[
            'credentialSlot', 'monthlyLimitUsd', 'monthlyUsageUsd',
            'billingCycleStartAt', 'billingCycleEndAt', 'observedAt', 'healthState'
       ] <> '{}'::JSONB
       OR p_snapshot->>'credentialSlot' IS DISTINCT FROM 'secondary'
       OR p_snapshot->>'healthState' IS DISTINCT FROM 'healthy'
       OR pg_catalog.jsonb_typeof(p_snapshot->'monthlyLimitUsd') <> 'number'
       OR pg_catalog.jsonb_typeof(p_snapshot->'monthlyUsageUsd') <> 'number'
       OR pg_catalog.jsonb_typeof(p_snapshot->'billingCycleStartAt') <> 'string'
       OR pg_catalog.jsonb_typeof(p_snapshot->'billingCycleEndAt') <> 'string'
       OR pg_catalog.jsonb_typeof(p_snapshot->'observedAt') <> 'string' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_APIFY_ACCOUNT_INVENTORY_INVALID', ERRCODE = 'P0001';
    END IF;

    BEGIN
        v_slot := p_snapshot->>'credentialSlot';
        v_monthly_limit_usd := (p_snapshot->>'monthlyLimitUsd')::NUMERIC;
        v_monthly_usage_usd := (p_snapshot->>'monthlyUsageUsd')::NUMERIC;
        v_cycle_start_at := (p_snapshot->>'billingCycleStartAt')::TIMESTAMP WITH TIME ZONE;
        v_cycle_end_at := (p_snapshot->>'billingCycleEndAt')::TIMESTAMP WITH TIME ZONE;
        v_observed_at := (p_snapshot->>'observedAt')::TIMESTAMP WITH TIME ZONE;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
        OR invalid_datetime_format OR datetime_field_overflow THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_APIFY_ACCOUNT_INVENTORY_INVALID', ERRCODE = 'P0001';
    END;

    IF v_slot IS DISTINCT FROM 'secondary'
       OR v_monthly_limit_usd NOT BETWEEN 0 AND 100000
       OR v_monthly_usage_usd NOT BETWEEN 0 AND 100000
       OR v_monthly_limit_usd <> pg_catalog.round(v_monthly_limit_usd, 12)
       OR v_monthly_usage_usd <> pg_catalog.round(v_monthly_usage_usd, 12)
       OR NOT pg_catalog.isfinite(v_cycle_start_at)
       OR NOT pg_catalog.isfinite(v_cycle_end_at)
       OR NOT pg_catalog.isfinite(v_observed_at)
       OR v_cycle_start_at > v_observed_at
       OR v_observed_at >= v_cycle_end_at
       OR v_cycle_start_at > v_now
       OR v_cycle_end_at <= v_now
       OR v_observed_at < v_now - INTERVAL '5 minutes'
       OR v_observed_at > v_now + INTERVAL '1 minute' THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_APIFY_ACCOUNT_INVENTORY_INVALID', ERRCODE = 'P0001';
    END IF;

    UPDATE public.analysis_apify_credit_snapshots AS snapshot
    SET monthly_limit_usd = v_monthly_limit_usd,
        monthly_usage_usd = v_monthly_usage_usd,
        billing_cycle_start_at = v_cycle_start_at,
        billing_cycle_end_at = v_cycle_end_at,
        observed_at = v_observed_at,
        health_state = 'healthy',
        refreshed_at = v_now
    WHERE snapshot.credential_slot = 'secondary';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_APIFY_ACCOUNT_INVENTORY_INCOMPLETE', ERRCODE = 'P0001';
    END IF;

    RETURN public.load_analysis_apify_account_credit_inventory(300);
END;
$$;


--
-- Name: upsert_analysis_beta_access_grant(uuid, boolean, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_analysis_beta_access_grant(p_user_id uuid, p_enabled boolean, p_expires_at timestamp with time zone, p_audit_reference_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '2min'
    AS $_$
DECLARE v_now TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_user_id IS NULL OR p_enabled IS NULL OR p_audit_reference_hash IS NULL
       OR p_audit_reference_hash !~ '^[a-f0-9]{64}$'
       OR (p_expires_at IS NOT NULL AND NOT pg_catalog.isfinite(p_expires_at)) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_GRANT_INVALID', ERRCODE = 'P0001';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analysis-beta-grant:' || pg_catalog.lower(p_user_id::TEXT), 0));
    PERFORM users.id FROM public.users AS users WHERE users.id = p_user_id FOR KEY SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_GRANT_INVALID', ERRCODE = 'P0001'; END IF;
    v_now := pg_catalog.clock_timestamp();
    IF p_enabled AND p_expires_at IS NOT NULL AND p_expires_at <= v_now THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_GRANT_INVALID', ERRCODE = 'P0001';
    END IF;
    INSERT INTO public.analysis_beta_access_grants(
        user_id, enabled, expires_at, audit_reference_hash, grant_source, granted_at, updated_at
    ) VALUES (p_user_id,p_enabled,p_expires_at,p_audit_reference_hash,'operator',v_now,v_now)
    ON CONFLICT (user_id) DO UPDATE SET
        enabled=EXCLUDED.enabled, expires_at=EXCLUDED.expires_at,
        audit_reference_hash=EXCLUDED.audit_reference_hash, grant_source='operator', updated_at=v_now;
    RETURN p_enabled;
END; $_$;


--
-- Name: upsert_analysis_beta_apify_credit_snapshots(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_analysis_beta_apify_credit_snapshots(p_snapshots jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_now TIMESTAMP WITH TIME ZONE := pg_catalog.clock_timestamp();
    v_entry JSONB;
    v_slot TEXT;
    v_monthly_limit_usd NUMERIC;
    v_monthly_usage_usd NUMERIC;
    v_cycle_start_at TIMESTAMP WITH TIME ZONE;
    v_cycle_end_at TIMESTAMP WITH TIME ZONE;
    v_observed_at TIMESTAMP WITH TIME ZONE;
    v_entry_count INTEGER;
    v_distinct_slot_count INTEGER;
    v_lock_count INTEGER := 0;
    v_locked_slot TEXT;
    v_existing public.analysis_apify_credit_snapshots%ROWTYPE;
BEGIN
    IF pg_catalog.jsonb_typeof(p_snapshots) <> 'array'
       OR pg_catalog.jsonb_array_length(p_snapshots) <> 9 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INCOMPLETE', ERRCODE = 'P0001';
    END IF;

    SELECT pg_catalog.count(*), pg_catalog.count(DISTINCT entry->>'credentialSlot')
    INTO v_entry_count, v_distinct_slot_count
    FROM pg_catalog.jsonb_array_elements(p_snapshots) AS entry;
    IF v_entry_count <> 9
       OR v_distinct_slot_count <> 9
       OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements(p_snapshots) AS entry
            WHERE NOT public.analysis_beta_valid_apify_credential_slot(entry->>'credentialSlot')
       ) THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INCOMPLETE', ERRCODE = 'P0001';
    END IF;

    FOR v_entry IN SELECT entry FROM pg_catalog.jsonb_array_elements(p_snapshots) AS entry LOOP
        IF pg_catalog.jsonb_typeof(v_entry) <> 'object'
           OR NOT v_entry ?& ARRAY[
                'credentialSlot', 'monthlyLimitUsd', 'monthlyUsageUsd',
                'billingCycleStartAt', 'billingCycleEndAt', 'observedAt', 'healthState'
           ]
           OR v_entry - ARRAY[
                'credentialSlot', 'monthlyLimitUsd', 'monthlyUsageUsd',
                'billingCycleStartAt', 'billingCycleEndAt', 'observedAt', 'healthState'
           ] <> '{}'::JSONB
           OR v_entry->>'healthState' NOT IN ('healthy', 'unhealthy') THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INVALID', ERRCODE = 'P0001';
        END IF;

        v_slot := v_entry->>'credentialSlot';
        IF NOT public.analysis_beta_valid_apify_credential_slot(v_slot) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INCOMPLETE', ERRCODE = 'P0001';
        END IF;
        IF v_entry->>'healthState' = 'unhealthy' THEN
            IF v_entry->>'monthlyLimitUsd' IS NOT NULL
               OR v_entry->>'monthlyUsageUsd' IS NOT NULL
               OR v_entry->>'billingCycleStartAt' IS NOT NULL
               OR v_entry->>'billingCycleEndAt' IS NOT NULL
               OR v_entry->>'observedAt' IS NOT NULL THEN
                RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INVALID', ERRCODE = 'P0001';
            END IF;
        ELSE
            IF pg_catalog.jsonb_typeof(v_entry->'monthlyLimitUsd') <> 'number'
               OR pg_catalog.jsonb_typeof(v_entry->'monthlyUsageUsd') <> 'number'
               OR pg_catalog.jsonb_typeof(v_entry->'billingCycleStartAt') <> 'string'
               OR pg_catalog.jsonb_typeof(v_entry->'billingCycleEndAt') <> 'string'
               OR pg_catalog.jsonb_typeof(v_entry->'observedAt') <> 'string' THEN
                RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INVALID', ERRCODE = 'P0001';
            END IF;
            BEGIN
                v_monthly_limit_usd := (v_entry->>'monthlyLimitUsd')::NUMERIC;
                v_monthly_usage_usd := (v_entry->>'monthlyUsageUsd')::NUMERIC;
                v_cycle_start_at := (v_entry->>'billingCycleStartAt')::TIMESTAMP WITH TIME ZONE;
                v_cycle_end_at := (v_entry->>'billingCycleEndAt')::TIMESTAMP WITH TIME ZONE;
                v_observed_at := (v_entry->>'observedAt')::TIMESTAMP WITH TIME ZONE;
            EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
                OR invalid_datetime_format OR datetime_field_overflow THEN
                RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INVALID', ERRCODE = 'P0001';
            END;
            IF v_monthly_limit_usd NOT BETWEEN 0 AND 100000
               OR v_monthly_usage_usd NOT BETWEEN 0 AND 100000
               OR v_monthly_limit_usd <> pg_catalog.round(v_monthly_limit_usd, 12)
               OR v_monthly_usage_usd <> pg_catalog.round(v_monthly_usage_usd, 12)
               OR NOT pg_catalog.isfinite(v_cycle_start_at)
               OR NOT pg_catalog.isfinite(v_cycle_end_at)
               OR NOT pg_catalog.isfinite(v_observed_at)
               OR v_cycle_start_at > v_observed_at
               OR v_observed_at >= v_cycle_end_at
               OR v_cycle_start_at > v_now
               OR v_cycle_end_at <= v_now THEN
                RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INVALID', ERRCODE = 'P0001';
            END IF;
            IF v_observed_at < v_now - INTERVAL '5 minutes'
               OR v_observed_at > v_now + INTERVAL '1 minute' THEN
                RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_STALE', ERRCODE = 'P0001';
            END IF;
        END IF;
    END LOOP;

    PERFORM public.analysis_beta_pool_lock();
    FOR v_locked_slot IN
        SELECT snapshot.credential_slot
        FROM public.analysis_apify_credit_snapshots AS snapshot
        WHERE public.analysis_beta_valid_apify_credential_slot(snapshot.credential_slot)
        ORDER BY CASE snapshot.credential_slot
            WHEN 'primary' THEN 1 WHEN 'tertiary' THEN 2
            WHEN 'quaternary' THEN 3 WHEN 'quinary' THEN 4
            WHEN 'senary' THEN 5 WHEN 'septenary' THEN 6
            WHEN 'octonary' THEN 7 WHEN 'nonary' THEN 8 WHEN 'tenth' THEN 9
        END
        FOR UPDATE
    LOOP
        v_lock_count := v_lock_count + 1;
    END LOOP;
    IF v_lock_count <> 9 THEN
        RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INCOMPLETE', ERRCODE = 'P0001';
    END IF;

    FOR v_entry IN SELECT entry FROM pg_catalog.jsonb_array_elements(p_snapshots) AS entry LOOP
        v_slot := v_entry->>'credentialSlot';
        IF v_entry->>'healthState' = 'healthy' THEN
            v_monthly_limit_usd := (v_entry->>'monthlyLimitUsd')::NUMERIC;
            v_monthly_usage_usd := (v_entry->>'monthlyUsageUsd')::NUMERIC;
            v_cycle_start_at := (v_entry->>'billingCycleStartAt')::TIMESTAMP WITH TIME ZONE;
            v_cycle_end_at := (v_entry->>'billingCycleEndAt')::TIMESTAMP WITH TIME ZONE;
            v_observed_at := (v_entry->>'observedAt')::TIMESTAMP WITH TIME ZONE;
        ELSE
            v_monthly_limit_usd := NULL;
            v_monthly_usage_usd := NULL;
            v_cycle_start_at := NULL;
            v_cycle_end_at := NULL;
            v_observed_at := NULL;
        END IF;
        SELECT snapshot.* INTO v_existing
        FROM public.analysis_apify_credit_snapshots AS snapshot
        WHERE snapshot.credential_slot = v_slot;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_INCOMPLETE', ERRCODE = 'P0001';
        END IF;
        IF v_entry->>'healthState' = 'healthy'
           AND v_existing.health_state = 'healthy'
           AND (v_existing.observed_at > v_observed_at OR (
                v_existing.observed_at = v_observed_at
                AND (v_existing.monthly_limit_usd IS DISTINCT FROM v_monthly_limit_usd
                  OR v_existing.monthly_usage_usd IS DISTINCT FROM v_monthly_usage_usd
                  OR v_existing.billing_cycle_start_at IS DISTINCT FROM v_cycle_start_at
                  OR v_existing.billing_cycle_end_at IS DISTINCT FROM v_cycle_end_at))) THEN
            RAISE EXCEPTION USING MESSAGE = 'ANALYSIS_BETA_POOL_SNAPSHOT_CONFLICT', ERRCODE = 'P0001';
        END IF;
        UPDATE public.analysis_apify_credit_snapshots AS snapshot
        SET monthly_limit_usd = v_monthly_limit_usd,
            monthly_usage_usd = v_monthly_usage_usd,
            billing_cycle_start_at = v_cycle_start_at,
            billing_cycle_end_at = v_cycle_end_at,
            observed_at = v_observed_at,
            health_state = (v_entry->>'healthState'),
            refreshed_at = v_now
        WHERE snapshot.credential_slot = v_slot;
    END LOOP;
    RETURN public.load_analysis_beta_apify_credit_pool(300);
END;
$$;


--
-- Name: upsert_kakao_account_profile_v1(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_kakao_account_profile_v1(p_user_id uuid, p_email text, p_profile jsonb) RETURNS TABLE(id uuid, account_class text, traffic_class text, lifecycle text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_existing public.users%ROWTYPE;
BEGIN
    IF p_user_id IS NULL
       OR (p_email IS NOT NULL AND (
            pg_catalog.btrim(p_email) = ''
            OR pg_catalog.char_length(p_email) > 255
       ))
       OR NOT public.account_profile_patch_valid(p_profile, TRUE) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'ACCOUNT_KAKAO_PROFILE_INPUT_INVALID',
            ERRCODE = 'P0001';
    END IF;

    SELECT account.*
    INTO v_existing
    FROM public.users AS account
    WHERE account.id = p_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        IF p_email IS NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ACCOUNT_KAKAO_EMAIL_REQUIRED',
                ERRCODE = 'P0001';
        END IF;
        INSERT INTO public.users (
            id, email, provider, analysis_count, is_paid_user, is_unlimited,
            name, nickname, profile_image, gender, birthyear,
            phone_number, phone_number_normalized,
            phone_number_verification_source, phone_number_verified_at,
            account_class, traffic_class, lifecycle, classification_version
        ) VALUES (
            p_user_id,
            pg_catalog.btrim(p_email),
            'kakao',
            0,
            FALSE,
            FALSE,
            NULLIF(p_profile ->> 'name', ''),
            NULLIF(p_profile ->> 'nickname', ''),
            NULLIF(p_profile ->> 'profile_image', ''),
            NULLIF(p_profile ->> 'gender', ''),
            NULLIF(p_profile ->> 'birthyear', ''),
            NULLIF(p_profile ->> 'phone_number', ''),
            NULLIF(p_profile ->> 'phone_number_normalized', ''),
            NULLIF(p_profile ->> 'phone_number_verification_source', ''),
            CASE
                WHEN p_profile ->> 'phone_number_verified_at' IS NULL
                    THEN NULL
                ELSE (p_profile ->> 'phone_number_verified_at')
                    ::TIMESTAMP WITH TIME ZONE
            END,
            'production',
            'external',
            'active',
            'runtime_default_v1'
        );
    ELSE
        IF v_existing.lifecycle <> 'active' THEN
            RAISE EXCEPTION USING
                MESSAGE = 'ACCOUNT_RETIRED',
                ERRCODE = 'P0001';
        END IF;
        UPDATE public.users AS account
        SET email = COALESCE(pg_catalog.btrim(p_email), account.email),
            provider = 'kakao',
            name = CASE WHEN p_profile ? 'name'
                THEN NULLIF(p_profile ->> 'name', '') ELSE account.name END,
            nickname = CASE WHEN p_profile ? 'nickname'
                THEN NULLIF(p_profile ->> 'nickname', '')
                ELSE account.nickname END,
            profile_image = CASE WHEN p_profile ? 'profile_image'
                THEN NULLIF(p_profile ->> 'profile_image', '')
                ELSE account.profile_image END,
            gender = CASE WHEN p_profile ? 'gender'
                THEN NULLIF(p_profile ->> 'gender', '')
                ELSE account.gender END,
            birthyear = CASE WHEN p_profile ? 'birthyear'
                THEN NULLIF(p_profile ->> 'birthyear', '')
                ELSE account.birthyear END,
            phone_number = CASE WHEN p_profile ? 'phone_number'
                THEN NULLIF(p_profile ->> 'phone_number', '')
                ELSE account.phone_number END,
            phone_number_normalized = CASE
                WHEN p_profile ? 'phone_number_normalized'
                    THEN NULLIF(p_profile ->> 'phone_number_normalized', '')
                ELSE account.phone_number_normalized
            END,
            phone_number_verification_source = CASE
                WHEN p_profile ? 'phone_number_verification_source'
                    THEN NULLIF(
                        p_profile ->> 'phone_number_verification_source', ''
                    )
                ELSE account.phone_number_verification_source
            END,
            phone_number_verified_at = CASE
                WHEN NOT (p_profile ? 'phone_number_verified_at')
                    THEN account.phone_number_verified_at
                WHEN p_profile ->> 'phone_number_verified_at' IS NULL
                    THEN NULL
                ELSE (p_profile ->> 'phone_number_verified_at')
                    ::TIMESTAMP WITH TIME ZONE
            END
        WHERE account.id = p_user_id;
    END IF;

    RETURN QUERY
    SELECT account.id,
        account.account_class,
        account.traffic_class,
        account.lifecycle
    FROM public.users AS account
    WHERE account.id = p_user_id;
END;
$$;


--
-- Name: uuid_generate_v4(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uuid_generate_v4() RETURNS uuid
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'extensions'
    AS $$SELECT extensions.uuid_generate_v4()$$;


--
-- Name: verify_analysis_revenue_final_coverage_gate_v1(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_analysis_revenue_final_coverage_gate_v1(p_request_id uuid, p_job_key text, p_job_claim_token uuid, p_job_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_primary public.analysis_revenue_primary_quality_checkpoints%ROWTYPE;
BEGIN
    IF p_job_key IS DISTINCT FROM 'coordinator:finalize'
       OR p_job_input_hash !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION USING MESSAGE = 'REVENUE_COST_OPERATION_FENCE';
    END IF;
    PERFORM public.analysis_revenue_ai_cost_assert_lineage_v1(
        p_request_id, p_job_key, p_job_claim_token, p_job_input_hash, TRUE
    );
    PERFORM public.analysis_revenue_ai_cost_assert_parent_v1(p_request_id);
    SELECT * INTO v_primary
    FROM public.analysis_revenue_primary_quality_checkpoints
    WHERE request_id = p_request_id FOR UPDATE;
    IF v_primary.request_id IS NULL THEN
        UPDATE public.analysis_revenue_run_ledgers
           SET status = 'manual_review',
               manual_review_reason = CASE
                   WHEN manual_review_reason IN (
                       'cost_overrun', 'cost_denied', 'ambiguous_external_call'
                   ) THEN manual_review_reason
                   ELSE 'routing_failure'
               END
         WHERE request_id = p_request_id;
        RETURN pg_catalog.jsonb_build_object(
            'disposition', 'manual_review', 'created', TRUE, 'replayed', FALSE
        );
    END IF;
    RETURN public.record_analysis_revenue_coverage_gate_v1(
        p_request_id, p_job_key, p_job_claim_token, p_job_input_hash,
        v_primary.public_mutual_count, v_primary.screened_count,
        v_primary.not_screened_count, v_primary.final_unknown_burden_count,
        v_primary.disposition = 'accepted'
    );
END;
$_$;


--
-- Name: account_classification_audit; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_classification_audit (
    id bigint NOT NULL,
    account_id uuid NOT NULL,
    command_version text NOT NULL,
    reason_code text NOT NULL,
    previous_account_class text NOT NULL,
    previous_traffic_class text NOT NULL,
    previous_lifecycle text NOT NULL,
    next_account_class text NOT NULL,
    next_traffic_class text NOT NULL,
    next_lifecycle text NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT account_classification_audit_account_class_check CHECK (((previous_account_class = ANY (ARRAY['production'::text, 'e2e_test'::text])) AND (next_account_class = ANY (ARRAY['production'::text, 'e2e_test'::text])))),
    CONSTRAINT account_classification_audit_command_check CHECK ((command_version ~ '^[a-z0-9._-]{1,64}$'::text)),
    CONSTRAINT account_classification_audit_lifecycle_check CHECK (((previous_lifecycle = ANY (ARRAY['active'::text, 'retired'::text])) AND (next_lifecycle = ANY (ARRAY['active'::text, 'retired'::text])))),
    CONSTRAINT account_classification_audit_reason_check CHECK ((reason_code ~ '^[A-Z0-9_]{1,64}$'::text)),
    CONSTRAINT account_classification_audit_traffic_class_check CHECK (((previous_traffic_class = ANY (ARRAY['external'::text, 'operator'::text, 'e2e_test'::text, 'internal_tester'::text])) AND (next_traffic_class = ANY (ARRAY['external'::text, 'operator'::text, 'e2e_test'::text, 'internal_tester'::text]))))
);


--
-- Name: account_classification_audit_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.account_classification_audit ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.account_classification_audit_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: account_deletion_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_deletion_jobs (
    account_id uuid NOT NULL,
    state text DEFAULT 'requested'::text NOT NULL,
    requested_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    objects_purged_at timestamp with time zone,
    database_purged_at timestamp with time zone,
    completed_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT account_deletion_jobs_state_check CHECK ((state = ANY (ARRAY['requested'::text, 'objects_purged'::text, 'database_purged'::text, 'completed'::text]))),
    CONSTRAINT account_deletion_jobs_state_shape_check CHECK ((((state = 'requested'::text) AND (objects_purged_at IS NULL) AND (database_purged_at IS NULL) AND (completed_at IS NULL)) OR ((state = 'objects_purged'::text) AND (objects_purged_at IS NOT NULL) AND (database_purged_at IS NULL) AND (completed_at IS NULL)) OR ((state = 'database_purged'::text) AND (objects_purged_at IS NOT NULL) AND (database_purged_at IS NOT NULL) AND (completed_at IS NULL)) OR ((state = 'completed'::text) AND (objects_purged_at IS NOT NULL) AND (database_purged_at IS NOT NULL) AND (completed_at IS NOT NULL))))
);

ALTER TABLE ONLY public.account_deletion_jobs FORCE ROW LEVEL SECURITY;


--
-- Name: account_e2e_test_runners; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_e2e_test_runners (
    account_id uuid NOT NULL,
    runner_plan text NOT NULL,
    command_version text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT account_e2e_test_runners_command_version_check CHECK ((command_version ~ '^[a-z0-9._-]{1,64}$'::text)),
    CONSTRAINT account_e2e_test_runners_runner_plan_check CHECK ((runner_plan = ANY (ARRAY['basic'::text, 'standard'::text])))
