    CONSTRAINT analysis_provider_usage_expectations_max_charge_usd_check CHECK ((((max_charge_usd)::text <> ALL (ARRAY['NaN'::text, 'Infinity'::text, '-Infinity'::text])) AND ((max_charge_usd >= (0)::numeric) AND (max_charge_usd <= (100000)::numeric)))),
    CONSTRAINT analysis_provider_usage_expectations_operation_key_check CHECK ((operation_key ~ '^(profile:target|profiles:(0|[1-9][0-9]{0,6})|relationship:(followers|following)|interaction:(target_likers|target_comments|candidate_likers):(0|[1-9][0-9]{0,6}))$'::text))
);


--
-- Name: analysis_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_requests (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    target_instagram_id character varying(100) NOT NULL,
    target_gender character varying(10) NOT NULL,
    status character varying(20) DEFAULT 'pending'::character varying,
    progress integer DEFAULT 0,
    progress_step character varying(100),
    total_followers integer,
    mutual_follows integer,
    opposite_gender_count integer,
    confidence_score double precision,
    error_message text,
    created_at timestamp with time zone DEFAULT now(),
    completed_at timestamp with time zone,
    plan_type text DEFAULT 'basic'::text,
    gender_stats jsonb,
    current_step character varying(50) DEFAULT 'pending'::character varying,
    step_data jsonb DEFAULT '{}'::jsonb,
    share_token character varying(64),
    share_enabled boolean DEFAULT false,
    processing_lease_token uuid,
    processing_lease_expires_at timestamp with time zone,
    idempotency_key character varying(128),
    background_processing boolean DEFAULT false NOT NULL,
    retry_state_key text,
    retry_count integer DEFAULT 0 NOT NULL,
    pipeline_version text,
    preflight_id uuid,
    excluded_instagram_id character varying(30),
    exclusion_decision_snapshot text,
    plan_access_mode_snapshot text,
    capacity_required_plan_id_snapshot text,
    required_plan_id_snapshot text,
    selected_plan_id_snapshot text,
    plan_launch_status_snapshot jsonb,
    plan_cards_snapshot jsonb,
    pricing_version_snapshot character varying(64),
    pricing_snapshot jsonb,
    analysis_scope_snapshot jsonb,
    policy_versions_snapshot jsonb,
    relationship_coverage_summary jsonb,
    test_entitlement_jti_hash character varying(64),
    analysis_entry_channel text DEFAULT 'standard'::text NOT NULL,
    CONSTRAINT analysis_requests_entry_channel_access_check CHECK (((analysis_entry_channel <> 'betatest'::text) OR ((NOT (pipeline_version IS DISTINCT FROM 'v2'::text)) AND (NOT (plan_access_mode_snapshot IS DISTINCT FROM 'production'::text)) AND (test_entitlement_jti_hash IS NULL)))),
    CONSTRAINT analysis_requests_entry_channel_check CHECK ((analysis_entry_channel = ANY (ARRAY['standard'::text, 'betatest'::text]))),
    CONSTRAINT analysis_requests_pipeline_version_check CHECK (((pipeline_version IS NULL) OR (pipeline_version = ANY (ARRAY['v1'::text, 'v2'::text])))),
    CONSTRAINT analysis_requests_plan_type_check CHECK ((plan_type = ANY (ARRAY['basic'::text, 'standard'::text, 'plus'::text]))),
    CONSTRAINT analysis_requests_progress_check CHECK (((progress >= 0) AND (progress <= 100))),
    CONSTRAINT analysis_requests_retry_count_check CHECK (((retry_count >= 0) AND (retry_count <= 1000))),
    CONSTRAINT analysis_requests_retry_state_key_check CHECK (((retry_state_key IS NULL) OR (((char_length(retry_state_key) >= 4) AND (char_length(retry_state_key) <= 128)) AND (retry_state_key ~ '^v1:[a-z0-9:_=-]+$'::text)))),
    CONSTRAINT analysis_requests_retry_state_pair_check CHECK ((((retry_state_key IS NULL) AND (retry_count = 0)) OR ((retry_state_key IS NOT NULL) AND (retry_count > 0)))),
    CONSTRAINT analysis_requests_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying, 'completed'::character varying, 'failed'::character varying])::text[]))),
    CONSTRAINT analysis_requests_target_gender_check CHECK (((target_gender)::text = ANY ((ARRAY['male'::character varying, 'female'::character varying])::text[]))),
    CONSTRAINT analysis_requests_target_instagram_id_valid CHECK (((target_instagram_id)::text ~ '^[A-Za-z0-9._]{1,30}$'::text)),
    CONSTRAINT analysis_requests_v2_exclusion_check CHECK (((pipeline_version IS DISTINCT FROM 'v2'::text) OR ((exclusion_decision_snapshot IS NOT NULL) AND (exclusion_decision_snapshot = ANY (ARRAY['exclude'::text, 'skip'::text])) AND (((exclusion_decision_snapshot = 'skip'::text) AND (excluded_instagram_id IS NULL)) OR ((exclusion_decision_snapshot = 'exclude'::text) AND ((excluded_instagram_id)::text ~ '^[a-z0-9._]{1,30}$'::text) AND ((excluded_instagram_id)::text <> lower((target_instagram_id)::text))))))),
    CONSTRAINT analysis_requests_v2_plan_ids_check CHECK (((pipeline_version IS DISTINCT FROM 'v2'::text) OR ((capacity_required_plan_id_snapshot IS NOT NULL) AND (required_plan_id_snapshot IS NOT NULL) AND (selected_plan_id_snapshot IS NOT NULL) AND (capacity_required_plan_id_snapshot = ANY (ARRAY['basic'::text, 'standard'::text, 'plus'::text])) AND (required_plan_id_snapshot = ANY (ARRAY['basic'::text, 'standard'::text, 'plus'::text])) AND (selected_plan_id_snapshot = ANY (ARRAY['basic'::text, 'standard'::text, 'plus'::text])) AND (
CASE required_plan_id_snapshot
    WHEN 'basic'::text THEN 1
    WHEN 'standard'::text THEN 2
    ELSE 3
END >=
CASE capacity_required_plan_id_snapshot
    WHEN 'basic'::text THEN 1
    WHEN 'standard'::text THEN 2
    ELSE 3
END) AND (
CASE selected_plan_id_snapshot
    WHEN 'basic'::text THEN 1
    WHEN 'standard'::text THEN 2
    ELSE 3
END >=
CASE required_plan_id_snapshot
    WHEN 'basic'::text THEN 1
    WHEN 'standard'::text THEN 2
    ELSE 3
END)))),
    CONSTRAINT analysis_requests_v2_snapshot_check CHECK (((pipeline_version IS DISTINCT FROM 'v2'::text) OR ((preflight_id IS NOT NULL) AND (idempotency_key IS NOT NULL) AND (plan_access_mode_snapshot = ANY (ARRAY['production'::text, 'test_entitlement'::text])) AND public.analysis_v2_valid_launch_snapshot(plan_launch_status_snapshot) AND public.analysis_v2_valid_plan_cards_snapshot(plan_cards_snapshot) AND ((char_length((pricing_version_snapshot)::text) >= 1) AND (char_length((pricing_version_snapshot)::text) <= 64)) AND ((pricing_version_snapshot)::text ~ '^[A-Za-z0-9._:-]+$'::text) AND public.analysis_v2_valid_pricing_snapshot(pricing_snapshot) AND public.analysis_v2_valid_scope_snapshot(analysis_scope_snapshot) AND public.analysis_v2_valid_policy_versions_snapshot(policy_versions_snapshot) AND ((relationship_coverage_summary IS NULL) OR ((jsonb_typeof(relationship_coverage_summary) = 'object'::text) AND (octet_length((relationship_coverage_summary)::text) <= 8192))) AND (((plan_access_mode_snapshot = 'test_entitlement'::text) AND ((test_entitlement_jti_hash)::text ~ '^[a-f0-9]{64}$'::text)) OR ((plan_access_mode_snapshot = 'production'::text) AND (test_entitlement_jti_hash IS NULL))))))
);


--
-- Name: analysis_step_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_step_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_id uuid NOT NULL,
    step text NOT NULL,
    event_type text NOT NULL,
    delivery_attempt integer,
    progress integer,
    latency_ms integer,
    failure_category text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_step_events_check CHECK ((((event_type = ANY (ARRAY['retrying'::text, 'failed'::text, 'aborted'::text])) AND (failure_category IS NOT NULL)) OR ((event_type <> ALL (ARRAY['retrying'::text, 'failed'::text, 'aborted'::text])) AND (failure_category IS NULL)))),
    CONSTRAINT analysis_step_events_delivery_attempt_check CHECK (((delivery_attempt IS NULL) OR ((delivery_attempt >= 1) AND (delivery_attempt <= 100)))),
    CONSTRAINT analysis_step_events_event_type_check CHECK ((event_type = ANY (ARRAY['started'::text, 'completed'::text, 'retrying'::text, 'failed'::text, 'skipped'::text, 'aborted'::text]))),
    CONSTRAINT analysis_step_events_failure_category_check CHECK (((failure_category IS NULL) OR (failure_category = ANY (ARRAY['configuration'::text, 'schema'::text, 'incomplete'::text, 'budget'::text, 'timeout'::text, 'provider'::text, 'persistence'::text, 'retry_exhausted'::text, 'unknown'::text])))),
    CONSTRAINT analysis_step_events_latency_ms_check CHECK (((latency_ms IS NULL) OR ((latency_ms >= 0) AND (latency_ms <= 86400000)))),
    CONSTRAINT analysis_step_events_progress_check CHECK (((progress IS NULL) OR ((progress >= 0) AND (progress <= 100)))),
    CONSTRAINT analysis_step_events_step_check CHECK ((step = ANY (ARRAY['pending'::text, 'collect'::text, 'profiles'::text, 'analyze'::text, 'interactions'::text, 'deep_analysis'::text, 'finalize'::text, 'completed'::text, 'failed'::text, 'gender'::text, 'features'::text])))
);


