    CONSTRAINT gemini_token_usage_latency_ms_nonnegative CHECK (((latency_ms IS NULL) OR (latency_ms >= 0))),
    CONSTRAINT gemini_token_usage_thinking_tokens_nonnegative CHECK ((thinking_tokens >= 0))
);


