    CONSTRAINT scraper_provider_usage_capability_check CHECK ((capability = ANY (ARRAY['profile'::text, 'profilesBatch'::text, 'followers'::text, 'following'::text]))),
    CONSTRAINT scraper_provider_usage_estimated_cost_usd_check CHECK ((estimated_cost_usd >= (0)::numeric)),
    CONSTRAINT scraper_provider_usage_latency_ms_check CHECK ((latency_ms >= 0)),
    CONSTRAINT scraper_provider_usage_provider_check CHECK ((provider = ANY (ARRAY['apify'::text, 'coderx'::text, 'flashapi'::text, 'rapidapi'::text, 'selfhosted'::text, 'selfhosted_auth'::text]))),
    CONSTRAINT scraper_provider_usage_rate_limit_limit_check CHECK ((rate_limit_limit >= 0)),
    CONSTRAINT scraper_provider_usage_rate_limit_remaining_check CHECK ((rate_limit_remaining >= 0)),
    CONSTRAINT scraper_provider_usage_raw_result_count_check CHECK ((raw_result_count >= 0)),
    CONSTRAINT scraper_provider_usage_request_count_check CHECK ((request_count >= 0)),
    CONSTRAINT scraper_provider_usage_result_count_check CHECK ((result_count >= 0)),
    CONSTRAINT scraper_provider_usage_status_check CHECK ((status = ANY (ARRAY['success'::text, 'error'::text]))),
    CONSTRAINT scraper_provider_usage_unique_ratio_check CHECK (((unique_ratio >= (0)::double precision) AND (unique_ratio <= (1)::double precision))),
    CONSTRAINT scraper_provider_usage_unique_result_count_check CHECK ((unique_result_count >= 0)),
    CONSTRAINT scraper_usage_coverage_ratio_nonnegative CHECK (((coverage_ratio IS NULL) OR (coverage_ratio >= (0)::double precision))),
    CONSTRAINT scraper_usage_expected_result_count_nonnegative CHECK (((expected_result_count IS NULL) OR (expected_result_count >= 0))),
    CONSTRAINT scraper_usage_failure_category_valid CHECK (((failure_category IS NULL) OR (failure_category = ANY (ARRAY['configuration'::text, 'schema'::text, 'incomplete'::text, 'budget'::text, 'timeout'::text, 'provider'::text])))),
    CONSTRAINT scraper_usage_minimum_complete_count_nonnegative CHECK (((minimum_complete_count IS NULL) OR (minimum_complete_count >= 0)))
);


--
-- Name: analysis_operational_cost_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.analysis_operational_cost_summary WITH (security_invoker='true') AS
 WITH observed_request_rows AS (
         SELECT analysis_requests.id AS request_id,
            analysis_requests.created_at
           FROM public.analysis_requests
        UNION ALL
         SELECT analysis_provider_usage_expectations.request_id,
            analysis_provider_usage_expectations.created_at
           FROM public.analysis_provider_usage_expectations
        UNION ALL
         SELECT analysis_gemini_usage_expectations.request_id,
            analysis_gemini_usage_expectations.created_at
           FROM public.analysis_gemini_usage_expectations
        UNION ALL
         SELECT analysis_provider_cost_ledger.request_id,
            analysis_provider_cost_ledger.created_at
           FROM public.analysis_provider_cost_ledger
          WHERE (analysis_provider_cost_ledger.request_id IS NOT NULL)
        UNION ALL
         SELECT gemini_token_usage.request_id,
            gemini_token_usage.created_at
           FROM public.gemini_token_usage
          WHERE (gemini_token_usage.request_id IS NOT NULL)
        UNION ALL
         SELECT scraper_provider_usage.request_id,
            scraper_provider_usage.created_at
           FROM public.scraper_provider_usage
          WHERE (scraper_provider_usage.request_id IS NOT NULL)
        UNION ALL
         SELECT analysis_step_events.request_id,
            analysis_step_events.created_at
           FROM public.analysis_step_events
        ), observed_requests AS (
         SELECT observed_request_rows.request_id,
            min(observed_request_rows.created_at) AS first_observed_at
           FROM observed_request_rows
          GROUP BY observed_request_rows.request_id
        ), provider_cost AS (
         SELECT expectation.request_id,
            (count(*))::integer AS provider_expected_run_count,
            (count(ledger.run_id))::integer AS provider_run_count,
            (count(*) FILTER (WHERE (ledger.status = 'running'::text)))::integer AS provider_running_run_count,
            (count(*) FILTER (WHERE ((ledger.run_id IS NULL) OR (ledger.status = 'running'::text) OR (ledger.usage_total_usd IS NULL))))::integer AS provider_missing_actual_run_count,
            COALESCE(sum(ledger.usage_total_usd), (0)::numeric) AS provider_actual_cost_usd,
            COALESCE(sum(COALESCE(ledger.usage_total_usd, ledger.max_charge_usd, expectation.max_charge_usd)), (0)::numeric) AS provider_conservative_cost_usd
           FROM (public.analysis_provider_usage_expectations expectation
             LEFT JOIN public.analysis_provider_cost_ledger ledger ON (((ledger.request_id = expectation.request_id) AND (ledger.operation_key = expectation.operation_key))))
          GROUP BY expectation.request_id
        ), gemini_cost AS (
         SELECT gemini_token_usage.request_id,
            (count(*))::integer AS gemini_record_count,
            (count(*) FILTER (WHERE (gemini_token_usage.cached_hit IS TRUE)))::integer AS gemini_cache_hit_count,
            (count(*) FILTER (WHERE (gemini_token_usage.estimated_cost_usd IS NULL)))::integer AS gemini_missing_estimate_count,
            COALESCE(sum(gemini_token_usage.prompt_tokens), (0)::bigint) AS gemini_prompt_tokens,
            COALESCE(sum(gemini_token_usage.total_tokens), (0)::bigint) AS gemini_total_tokens,
            COALESCE(sum(gemini_token_usage.estimated_cost_usd), (0)::numeric) AS gemini_estimated_cost_usd,
            (round(avg(gemini_token_usage.latency_ms) FILTER (WHERE (gemini_token_usage.latency_ms IS NOT NULL))))::integer AS gemini_average_latency_ms
           FROM public.gemini_token_usage
          WHERE (gemini_token_usage.request_id IS NOT NULL)
          GROUP BY gemini_token_usage.request_id
        ), gemini_expectation AS (
         SELECT analysis_gemini_usage_expectations.request_id,
            (count(*))::integer AS gemini_expected_operation_count,
            (sum(analysis_gemini_usage_expectations.expected_record_count))::integer AS gemini_expected_record_count
           FROM public.analysis_gemini_usage_expectations
          GROUP BY analysis_gemini_usage_expectations.request_id
        ), scraper_usage AS (
         SELECT scraper_provider_usage.request_id,
            (count(*))::integer AS scraper_call_count,
            (count(*) FILTER (WHERE (scraper_provider_usage.status = 'error'::text)))::integer AS scraper_error_count,
            COALESCE(sum(scraper_provider_usage.result_count), (0)::bigint) AS scraper_result_count,
            COALESCE(sum(scraper_provider_usage.estimated_cost_usd), (0)::numeric) AS scraper_estimated_cost_usd,
            (round(avg(scraper_provider_usage.latency_ms)))::integer AS scraper_average_latency_ms
           FROM public.scraper_provider_usage
          WHERE (scraper_provider_usage.request_id IS NOT NULL)
          GROUP BY scraper_provider_usage.request_id
        ), step_history AS (
         SELECT analysis_step_events.request_id,
            (count(*))::integer AS step_event_count,
            min(analysis_step_events.created_at) FILTER (WHERE (analysis_step_events.event_type = 'started'::text)) AS first_step_started_at,
            max(analysis_step_events.created_at) AS last_step_event_at,
            (count(*) FILTER (WHERE (analysis_step_events.event_type = 'retrying'::text)))::integer AS retry_event_count,
            (count(*) FILTER (WHERE (analysis_step_events.event_type = ANY (ARRAY['failed'::text, 'aborted'::text]))))::integer AS failure_event_count
           FROM public.analysis_step_events
          GROUP BY analysis_step_events.request_id
        )
 SELECT observed_request.request_id,
    (COALESCE(analysis_request.status, 'deleted'::character varying))::character varying(20) AS status,
    COALESCE(analysis_request.current_step, 'deleted'::character varying) AS current_step,
    COALESCE(analysis_request.created_at, observed_request.first_observed_at) AS created_at,
    analysis_request.completed_at,
        CASE
            WHEN (analysis_request.completed_at IS NULL) THEN NULL::bigint
            ELSE GREATEST((0)::bigint, (round((EXTRACT(epoch FROM (analysis_request.completed_at - COALESCE(analysis_request.created_at, observed_request.first_observed_at))) * (1000)::numeric)))::bigint)
        END AS analysis_duration_ms,
    COALESCE(provider_cost.provider_run_count, 0) AS provider_run_count,
    COALESCE(provider_cost.provider_running_run_count, 0) AS provider_running_run_count,
    COALESCE(provider_cost.provider_missing_actual_run_count, 0) AS provider_missing_actual_run_count,
    COALESCE(provider_cost.provider_actual_cost_usd, (0)::numeric) AS provider_actual_cost_usd,
    COALESCE(provider_cost.provider_conservative_cost_usd, (0)::numeric) AS provider_conservative_cost_usd,
    ((COALESCE(provider_cost.provider_expected_run_count, 0) > 0) AND (COALESCE(provider_cost.provider_expected_run_count, 0) = COALESCE(provider_cost.provider_run_count, 0)) AND (COALESCE(provider_cost.provider_running_run_count, 0) = 0) AND (COALESCE(provider_cost.provider_missing_actual_run_count, 0) = 0)) AS provider_cost_complete,
    COALESCE(gemini_cost.gemini_record_count, 0) AS gemini_record_count,
    COALESCE(gemini_cost.gemini_cache_hit_count, 0) AS gemini_cache_hit_count,
    COALESCE(gemini_cost.gemini_missing_estimate_count, 0) AS gemini_missing_estimate_count,
    COALESCE(gemini_cost.gemini_prompt_tokens, (0)::bigint) AS gemini_prompt_tokens,
    COALESCE(gemini_cost.gemini_total_tokens, (0)::bigint) AS gemini_total_tokens,
    COALESCE(gemini_cost.gemini_estimated_cost_usd, (0)::numeric) AS gemini_estimated_cost_usd,
    gemini_cost.gemini_average_latency_ms,
    (((COALESCE(gemini_expectation.gemini_expected_record_count, 0) > 0) AND (COALESCE(gemini_expectation.gemini_expected_record_count, 0) = COALESCE(gemini_cost.gemini_record_count, 0)) AND (COALESCE(gemini_cost.gemini_missing_estimate_count, 0) = 0)) OR ((COALESCE(gemini_expectation.gemini_expected_record_count, 0) = 0) AND (COALESCE(analysis_request.mutual_follows, '-1'::integer) = 0) AND (COALESCE(gemini_cost.gemini_record_count, 0) = 0))) AS gemini_cost_complete,
    (COALESCE(provider_cost.provider_actual_cost_usd, (0)::numeric) + COALESCE(gemini_cost.gemini_estimated_cost_usd, (0)::numeric)) AS known_total_cost_usd,
    (COALESCE(provider_cost.provider_conservative_cost_usd, (0)::numeric) + COALESCE(gemini_cost.gemini_estimated_cost_usd, (0)::numeric)) AS conservative_total_cost_usd,
    (((COALESCE(analysis_request.status, 'deleted'::character varying))::text = ANY ((ARRAY['completed'::character varying, 'failed'::character varying, 'deleted'::character varying])::text[])) AND (COALESCE(provider_cost.provider_expected_run_count, 0) > 0) AND (COALESCE(provider_cost.provider_expected_run_count, 0) = COALESCE(provider_cost.provider_run_count, 0)) AND (COALESCE(provider_cost.provider_running_run_count, 0) = 0) AND (COALESCE(provider_cost.provider_missing_actual_run_count, 0) = 0) AND (((COALESCE(gemini_expectation.gemini_expected_record_count, 0) > 0) AND (COALESCE(gemini_expectation.gemini_expected_record_count, 0) = COALESCE(gemini_cost.gemini_record_count, 0)) AND (COALESCE(gemini_cost.gemini_missing_estimate_count, 0) = 0)) OR ((COALESCE(gemini_expectation.gemini_expected_record_count, 0) = 0) AND (COALESCE(analysis_request.mutual_follows, '-1'::integer) = 0) AND (COALESCE(gemini_cost.gemini_record_count, 0) = 0)))) AS total_cost_complete,
    COALESCE(scraper_usage.scraper_call_count, 0) AS scraper_call_count,
    COALESCE(scraper_usage.scraper_error_count, 0) AS scraper_error_count,
    COALESCE(scraper_usage.scraper_result_count, (0)::bigint) AS scraper_result_count,
    COALESCE(scraper_usage.scraper_estimated_cost_usd, (0)::numeric) AS scraper_estimated_cost_usd,
    scraper_usage.scraper_average_latency_ms,
    COALESCE(step_history.step_event_count, 0) AS step_event_count,
    step_history.first_step_started_at,
    step_history.last_step_event_at,
    COALESCE(step_history.retry_event_count, 0) AS retry_event_count,
    COALESCE(step_history.failure_event_count, 0) AS failure_event_count,
    COALESCE(provider_cost.provider_expected_run_count, 0) AS provider_expected_run_count,
    COALESCE(gemini_expectation.gemini_expected_operation_count, 0) AS gemini_expected_operation_count,
    COALESCE(gemini_expectation.gemini_expected_record_count, 0) AS gemini_expected_record_count
   FROM ((((((observed_requests observed_request
     LEFT JOIN public.analysis_requests analysis_request ON ((analysis_request.id = observed_request.request_id)))
     LEFT JOIN provider_cost ON ((provider_cost.request_id = observed_request.request_id)))
     LEFT JOIN gemini_cost ON ((gemini_cost.request_id = observed_request.request_id)))
     LEFT JOIN gemini_expectation ON ((gemini_expectation.request_id = observed_request.request_id)))
     LEFT JOIN scraper_usage ON ((scraper_usage.request_id = observed_request.request_id)))
     LEFT JOIN step_history ON ((step_history.request_id = observed_request.request_id)));


--
-- Name: analysis_order_audit_assembly_queue; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_order_audit_assembly_queue (
    request_id uuid NOT NULL,
    status character varying(16) DEFAULT 'queued'::character varying NOT NULL,
    attempt_count smallint DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    last_error_code character varying(96),
    last_error_at timestamp with time zone,
