    vertex_budget_mismatch_count integer NOT NULL,
    vertex_budget_conservative_fallback_usd numeric(18,12) NOT NULL,
    vertex_budget_coverage_gap_count integer NOT NULL,
    provider_no_call_count_total integer NOT NULL,
    no_call_count integer NOT NULL,
    provider_actual_total_usd numeric(18,12) NOT NULL,
    provider_conservative_total_usd numeric(18,12) NOT NULL,
    total_known_cost_usd numeric(18,12) NOT NULL,
    total_conservative_cost_usd numeric(18,12) NOT NULL,
    cost_provenance jsonb NOT NULL,
    directly_attributable_cost_complete boolean NOT NULL,
    usage_unknown boolean NOT NULL,
    captured_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT analysis_v2_cost_snapshot_access_check CHECK ((access_mode = ANY (ARRAY['production'::text, 'test_entitlement'::text]))),
    CONSTRAINT analysis_v2_cost_snapshot_nonnegative_check CHECK (((preflight_provider_run_count >= 0) AND (preflight_attributed_provider_run_count >= 0) AND (preflight_attribution_gap_count >= 0) AND (preflight_coverage_unknown = ANY (ARRAY[true, false])) AND (preflight_usage_unknown_count >= 0) AND (preflight_no_call_count >= 0) AND (preflight_no_paid_provider_count >= 0) AND (preflight_apify_actual_count >= 0) AND (preflight_provider_actual_usd >= (0)::numeric) AND (preflight_apify_actual_charge_usd >= (0)::numeric) AND (preflight_provider_conservative_usd >= (0)::numeric) AND (provider_run_count >= 0) AND (provider_active_count >= 0) AND (provider_usage_unknown_count >= 0) AND (provider_no_call_count >= 0) AND (provider_coverage_gap_count >= 0) AND (provider_actual_count >= 0) AND (provider_apify_actual_count >= 0) AND (provider_actual_usd >= (0)::numeric) AND (apify_actual_charge_usd >= (0)::numeric) AND (provider_conservative_usd >= (0)::numeric) AND (ai_attempt_count >= 0) AND (ai_reserved_count >= 0) AND (ai_usage_unknown_count >= 0) AND (ai_metered_cost_count >= 0) AND (metered_estimated_cost_usd >= (0)::numeric) AND (ai_input_tokens >= 0) AND (ai_output_tokens >= 0) AND (ai_cache_tokens >= 0) AND (cache_hit_count >= 0) AND (ai_coverage_gap_count >= 0) AND (selfhosted_no_paid_provider_count >= 0) AND (vertex_budget_reservation_count >= 0) AND (vertex_budget_matched_count >= 0) AND (vertex_budget_unmatched_count >= 0) AND (vertex_budget_usage_unknown_count >= 0) AND (vertex_budget_duplicate_count >= 0) AND (vertex_budget_mismatch_count >= 0) AND (vertex_budget_conservative_fallback_usd >= (0)::numeric) AND (vertex_budget_coverage_gap_count >= 0) AND (provider_no_call_count_total >= 0) AND (no_call_count >= 0) AND (provider_actual_total_usd >= (0)::numeric) AND (provider_conservative_total_usd >= (0)::numeric) AND (total_known_cost_usd >= (0)::numeric) AND (total_conservative_cost_usd >= (0)::numeric))),
    CONSTRAINT analysis_v2_cost_snapshot_plan_check CHECK ((plan_id = ANY (ARRAY['basic'::text, 'standard'::text, 'plus'::text]))),
    CONSTRAINT analysis_v2_cost_snapshot_scope_check CHECK (((cost_scope = 'analysis-v2-direct-provider-and-vertex-metered-v1'::text) AND (infrastructure_included = false))),
    CONSTRAINT analysis_v2_cost_snapshot_status_check CHECK ((request_status = ANY (ARRAY['pending'::text, 'processing'::text, 'completed'::text, 'failed'::text]))),
    CONSTRAINT analysis_v2_cost_snapshot_time_check CHECK ((updated_at >= captured_at)),
    CONSTRAINT analysis_v2_cost_snapshot_version_check CHECK ((rollup_version = 'analysis-v2-cost-rollup-v1'::text))
);

