CREATE TABLE public.vertex_ai_budget_reservations (
    reservation_key text NOT NULL,
    reservation_id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    run_id text NOT NULL,
    order_id text NOT NULL,
    day_key date NOT NULL,
    operation_key text NOT NULL,
    attempt integer NOT NULL,
    route text NOT NULL,
    model_name text NOT NULL,
    model_location text NOT NULL,
    input_tokens bigint NOT NULL,
    max_output_tokens integer NOT NULL,
    estimated_cost_usd numeric(18,12) NOT NULL,
    actual_cost_usd numeric(18,12),
    usage_unknown boolean DEFAULT true NOT NULL,
    state text DEFAULT 'reserved'::text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT vertex_ai_budget_clock_check CHECK ((updated_at >= created_at)),
    CONSTRAINT vertex_ai_budget_location_check CHECK ((model_location ~ '^[a-z][a-z0-9-]{0,62}$'::text)),
    CONSTRAINT vertex_ai_budget_model_check CHECK ((model_name ~ '^[a-z0-9][a-z0-9._-]{0,99}(/[a-z0-9][a-z0-9._-]{0,99})*$'::text)),
    CONSTRAINT vertex_ai_budget_operation_key_check CHECK ((operation_key ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,255}$'::text)),
    CONSTRAINT vertex_ai_budget_order_id_check CHECK ((order_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,127}$'::text)),
    CONSTRAINT vertex_ai_budget_reservation_key_check CHECK ((reservation_key ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,255}$'::text)),
    CONSTRAINT vertex_ai_budget_reservations_actual_cost_usd_check CHECK (((actual_cost_usd IS NULL) OR ((actual_cost_usd >= (0)::numeric) AND (actual_cost_usd <= (1000000)::numeric)))),
    CONSTRAINT vertex_ai_budget_reservations_attempt_check CHECK (((attempt >= 1) AND (attempt <= 4))),
    CONSTRAINT vertex_ai_budget_reservations_estimated_cost_usd_check CHECK (((estimated_cost_usd > (0)::numeric) AND (estimated_cost_usd <= (1000000)::numeric))),
    CONSTRAINT vertex_ai_budget_reservations_input_tokens_check CHECK ((input_tokens >= 0)),
    CONSTRAINT vertex_ai_budget_reservations_max_output_tokens_check CHECK (((max_output_tokens >= 1) AND (max_output_tokens <= 65536))),
    CONSTRAINT vertex_ai_budget_reservations_route_check CHECK ((route = ANY (ARRAY['default'::text, 'high_value'::text, 'ambiguous'::text]))),
    CONSTRAINT vertex_ai_budget_reservations_state_check CHECK ((state = ANY (ARRAY['reserved'::text, 'settled'::text, 'cancelled'::text]))),
    CONSTRAINT vertex_ai_budget_run_id_check CHECK ((run_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,127}$'::text)),
    CONSTRAINT vertex_ai_budget_usage_state_check CHECK ((((state = 'settled'::text) AND (usage_unknown = (actual_cost_usd IS NULL))) OR (state = ANY (ARRAY['reserved'::text, 'cancelled'::text]))))
);

