--
-- Name: analysis_v2_cost_rollups; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.analysis_v2_cost_rollups AS
 WITH preflight_sources AS (
         SELECT attribution.request_id,
            attribution.preflight_id,
            attribution.order_id,
            attribution.source_operation_key,
            provider_run.preflight_id AS joined_preflight_id,
            provider_run.logical_provider,
            provider_run.actor_id,
            provider_run.credential_slot,
            provider_run.status,
            provider_run.run_id,
            provider_run.max_charge_usd,
            provider_run.actual_usage_usd,
            provider_run.terminalized_at,
            provider_run.usage_reconciled_at
           FROM (public.analysis_v2_cost_attributions attribution
             LEFT JOIN public.analysis_preflight_provider_runs provider_run ON (((provider_run.preflight_id = attribution.preflight_id) AND (provider_run.operation_key = attribution.source_operation_key))))
          WHERE (attribution.source_kind = 'preflight_provider_run'::text)
        ), preflight_zero_sources AS (
         SELECT preflight.consumed_request_id AS request_id,
            preflight.id AS preflight_id,
                CASE
                    WHEN (preflight.provider_selector = 'selfhosted_auth'::text) THEN 1
                    ELSE 0
                END AS no_paid_provider_count,
                CASE
                    WHEN (preflight.provider_selector = 'selfhosted_auth'::text) THEN 0
                    ELSE 1
                END AS usage_unknown_count,
                CASE
                    WHEN (preflight.provider_selector = 'selfhosted_auth'::text) THEN 1
                    ELSE 0
                END AS no_call_count,
                CASE
                    WHEN (preflight.provider_selector = 'selfhosted_auth'::text) THEN jsonb_build_array(jsonb_build_object('sourceKind', 'preflight_selfhosted_auth', 'provider', 'selfhosted_auth', 'status', preflight.status, 'providerChargeUsd', (0)::numeric, 'chargeKind', 'no_paid_provider', 'noCall', true, 'usageUnknown', false))
                    ELSE '[]'::jsonb
                END AS provenance
           FROM public.analysis_preflights preflight
          WHERE ((preflight.status = 'consumed'::text) AND (preflight.consumed_request_id IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM public.analysis_v2_cost_attributions attribution
                  WHERE ((attribution.request_id = preflight.consumed_request_id) AND (attribution.preflight_id = preflight.id) AND (attribution.source_kind = 'preflight_provider_run'::text))))) AND (NOT (EXISTS ( SELECT 1
                   FROM public.analysis_preflight_provider_runs provider_run
                  WHERE (provider_run.preflight_id = preflight.id)))))
        ), preflight_rollup AS (
         SELECT source.request_id,
            (array_agg(source.preflight_id ORDER BY source.preflight_id))[1] AS preflight_id,
            (array_agg(source.order_id ORDER BY source.order_id) FILTER (WHERE (source.order_id IS NOT NULL)))[1] AS order_id,
            (count(*))::integer AS source_count,
            (count(source.joined_preflight_id))::integer AS joined_source_count,
            (count(*) FILTER (WHERE ((source.joined_preflight_id IS NULL) OR (source.status = ANY (ARRAY['starting'::text, 'running'::text])) OR (source.status = 'resolved_identity_drift'::text) OR (source.actual_usage_usd IS NULL) OR (source.usage_reconciled_at IS NULL))))::integer AS usage_unknown_count,
            (count(*) FILTER (WHERE ((source.joined_preflight_id IS NOT NULL) AND (source.status = ANY (ARRAY['rejected'::text, 'resolved_no_run'::text])) AND (source.actual_usage_usd = (0)::numeric) AND (source.usage_reconciled_at IS NOT NULL))))::integer AS no_call_count,
            (count(*) FILTER (WHERE ((source.joined_preflight_id IS NOT NULL) AND (source.logical_provider = 'apify'::text) AND (source.status = ANY (ARRAY['succeeded'::text, 'failed'::text, 'aborted'::text, 'timed_out'::text])) AND (source.run_id IS NOT NULL) AND (source.actual_usage_usd IS NOT NULL) AND (source.usage_reconciled_at IS NOT NULL))))::integer AS apify_actual_count,
            COALESCE(sum(source.actual_usage_usd) FILTER (WHERE ((source.joined_preflight_id IS NOT NULL) AND (source.status = ANY (ARRAY['succeeded'::text, 'failed'::text, 'aborted'::text, 'timed_out'::text])) AND (source.run_id IS NOT NULL) AND (source.actual_usage_usd IS NOT NULL) AND (source.usage_reconciled_at IS NOT NULL))), (0)::numeric) AS actual_usd,
            COALESCE(sum(source.actual_usage_usd) FILTER (WHERE ((source.joined_preflight_id IS NOT NULL) AND (source.logical_provider = 'apify'::text) AND (source.status = ANY (ARRAY['succeeded'::text, 'failed'::text, 'aborted'::text, 'timed_out'::text])) AND (source.run_id IS NOT NULL) AND (source.actual_usage_usd IS NOT NULL) AND (source.usage_reconciled_at IS NOT NULL))), (0)::numeric) AS apify_actual_usd,
            COALESCE(sum(
                CASE
                    WHEN (source.joined_preflight_id IS NULL) THEN (0)::numeric
                    WHEN ((source.status = ANY (ARRAY['rejected'::text, 'resolved_no_run'::text])) AND (source.actual_usage_usd = (0)::numeric)) THEN (0)::numeric
                    WHEN (source.status = 'resolved_identity_drift'::text) THEN source.max_charge_usd
                    WHEN ((source.actual_usage_usd IS NULL) OR (source.usage_reconciled_at IS NULL)) THEN source.max_charge_usd
                    ELSE source.actual_usage_usd
                END), (0)::numeric) AS conservative_usd,
            COALESCE(jsonb_agg(jsonb_build_object('sourceKind', 'preflight_provider_run', 'operationKey', source.source_operation_key, 'provider', source.logical_provider, 'actor', source.actor_id, 'credentialSlot', source.credential_slot, 'status', source.status, 'actualChargeUsd',
                CASE
                    WHEN ((source.status = ANY (ARRAY['succeeded'::text, 'failed'::text, 'aborted'::text, 'timed_out'::text])) AND (source.run_id IS NOT NULL) AND (source.actual_usage_usd IS NOT NULL) AND (source.usage_reconciled_at IS NOT NULL)) THEN source.actual_usage_usd
                    ELSE NULL::numeric
                END, 'conservativeEstimateUsd',
                CASE
                    WHEN (source.status = 'resolved_identity_drift'::text) THEN source.max_charge_usd
                    WHEN ((source.status = ANY (ARRAY['starting'::text, 'running'::text])) OR (source.actual_usage_usd IS NULL) OR (source.usage_reconciled_at IS NULL)) THEN source.max_charge_usd
                    ELSE NULL::numeric
                END, 'noCall', ((source.status = ANY (ARRAY['rejected'::text, 'resolved_no_run'::text])) AND (source.actual_usage_usd = (0)::numeric) AND (source.usage_reconciled_at IS NOT NULL)), 'usageUnknown', ((source.joined_preflight_id IS NULL) OR (source.status = ANY (ARRAY['starting'::text, 'running'::text])) OR (source.status = 'resolved_identity_drift'::text) OR (source.actual_usage_usd IS NULL) OR (source.usage_reconciled_at IS NULL))) ORDER BY source.source_operation_key) FILTER (WHERE (source.joined_preflight_id IS NOT NULL)), '[]'::jsonb) AS provenance
           FROM preflight_sources source
          GROUP BY source.request_id
        ), provider_rollup AS (
         SELECT provider_run.request_id,
            (count(*))::integer AS run_count,
            (count(*) FILTER (WHERE ((provider_run.status)::text = ANY ((ARRAY['starting'::character varying, 'running'::character varying])::text[]))))::integer AS active_count,
            (count(*) FILTER (WHERE (((provider_run.status)::text = ANY ((ARRAY['starting'::character varying, 'running'::character varying])::text[])) OR (((provider_run.status)::text = ANY ((ARRAY['succeeded'::character varying, 'failed'::character varying, 'aborted'::character varying, 'timed_out'::character varying])::text[])) AND ((provider_run.manual_resolution_kind IS NOT NULL) OR (provider_run.actual_usage_usd IS NULL) OR (provider_run.usage_reconciled_at IS NULL))))))::integer AS usage_unknown_count,
            (count(*) FILTER (WHERE (((provider_run.status)::text = 'rejected'::text) AND (provider_run.actual_usage_usd = (0)::numeric) AND (provider_run.usage_reconciled_at IS NOT NULL))))::integer AS no_call_count,
            (count(*) FILTER (WHERE (((provider_run.logical_provider)::text = 'apify'::text) AND ((provider_run.status)::text = ANY ((ARRAY['succeeded'::character varying, 'failed'::character varying, 'aborted'::character varying, 'timed_out'::character varying])::text[])) AND (provider_run.run_id IS NOT NULL) AND (provider_run.manual_resolution_kind IS NULL) AND (provider_run.actual_usage_usd IS NOT NULL) AND (provider_run.usage_reconciled_at IS NOT NULL))))::integer AS apify_actual_count,
            (count(*) FILTER (WHERE (((provider_run.status)::text = ANY ((ARRAY['succeeded'::character varying, 'failed'::character varying, 'aborted'::character varying, 'timed_out'::character varying])::text[])) AND (provider_run.run_id IS NOT NULL) AND (provider_run.manual_resolution_kind IS NULL) AND (provider_run.actual_usage_usd IS NOT NULL) AND (provider_run.usage_reconciled_at IS NOT NULL))))::integer AS actual_count,
            COALESCE(sum(provider_run.actual_usage_usd) FILTER (WHERE (((provider_run.status)::text = ANY ((ARRAY['succeeded'::character varying, 'failed'::character varying, 'aborted'::character varying, 'timed_out'::character varying])::text[])) AND (provider_run.run_id IS NOT NULL) AND (provider_run.manual_resolution_kind IS NULL) AND (provider_run.actual_usage_usd IS NOT NULL) AND (provider_run.usage_reconciled_at IS NOT NULL))), (0)::numeric) AS actual_usd,
            COALESCE(sum(provider_run.actual_usage_usd) FILTER (WHERE (((provider_run.logical_provider)::text = 'apify'::text) AND ((provider_run.status)::text = ANY ((ARRAY['succeeded'::character varying, 'failed'::character varying, 'aborted'::character varying, 'timed_out'::character varying])::text[])) AND (provider_run.run_id IS NOT NULL) AND (provider_run.manual_resolution_kind IS NULL) AND (provider_run.actual_usage_usd IS NOT NULL) AND (provider_run.usage_reconciled_at IS NOT NULL))), (0)::numeric) AS apify_actual_usd,
            COALESCE(sum(
                CASE
                    WHEN (((provider_run.status)::text = 'rejected'::text) AND (provider_run.actual_usage_usd = (0)::numeric)) THEN (0)::numeric
                    WHEN (provider_run.manual_resolution_kind = 'conservative_max_charge'::text) THEN provider_run.max_charge_usd
                    WHEN (((provider_run.status)::text = ANY ((ARRAY['starting'::character varying, 'running'::character varying])::text[])) OR (provider_run.actual_usage_usd IS NULL) OR (provider_run.usage_reconciled_at IS NULL)) THEN provider_run.max_charge_usd
                    ELSE provider_run.actual_usage_usd
                END), (0)::numeric) AS conservative_usd,
            COALESCE(jsonb_agg(jsonb_build_object('sourceKind', 'analysis_provider_run', 'operationKey', provider_run.operation_key, 'provider', provider_run.logical_provider, 'actor', provider_run.actor_id, 'credentialSlot', provider_run.credential_slot, 'status', provider_run.status, 'actualChargeUsd',
                CASE
                    WHEN (((provider_run.status)::text = ANY ((ARRAY['succeeded'::character varying, 'failed'::character varying, 'aborted'::character varying, 'timed_out'::character varying])::text[])) AND (provider_run.run_id IS NOT NULL) AND (provider_run.manual_resolution_kind IS NULL) AND (provider_run.actual_usage_usd IS NOT NULL) AND (provider_run.usage_reconciled_at IS NOT NULL)) THEN provider_run.actual_usage_usd
                    ELSE NULL::numeric
                END, 'conservativeEstimateUsd',
                CASE
                    WHEN (provider_run.manual_resolution_kind = 'conservative_max_charge'::text) THEN provider_run.max_charge_usd
                    WHEN (((provider_run.status)::text = ANY ((ARRAY['starting'::character varying, 'running'::character varying])::text[])) OR (provider_run.actual_usage_usd IS NULL) OR (provider_run.usage_reconciled_at IS NULL)) THEN provider_run.max_charge_usd
                    ELSE NULL::numeric
                END, 'noCall', (((provider_run.status)::text = 'rejected'::text) AND (provider_run.actual_usage_usd = (0)::numeric) AND (provider_run.usage_reconciled_at IS NOT NULL)), 'usageUnknown', (((provider_run.status)::text = ANY ((ARRAY['starting'::character varying, 'running'::character varying])::text[])) OR (provider_run.manual_resolution_kind IS NOT NULL) OR (provider_run.actual_usage_usd IS NULL) OR (provider_run.usage_reconciled_at IS NULL)), 'manualResolutionKind', provider_run.manual_resolution_kind) ORDER BY provider_run.operation_key), '[]'::jsonb) AS provenance
           FROM public.analysis_v2_provider_runs provider_run
          GROUP BY provider_run.request_id
        ), ai_rollup AS (
         SELECT ai_attempt.request_id,
            (count(*))::integer AS attempt_count,
            (count(*) FILTER (WHERE (ai_attempt.status = 'reserved'::text)))::integer AS reserved_count,
            (count(*) FILTER (WHERE ((ai_attempt.status <> 'reserved'::text) AND ((ai_attempt.usage_complete IS DISTINCT FROM true) OR (ai_attempt.metered_estimated_cost_usd IS NULL) OR (ai_attempt.cache_read_tokens IS NULL) OR (ai_attempt.canonical_model_name IS NULL) OR (ai_attempt.pricing_version IS NULL)))))::integer AS usage_unknown_count,
            (count(*) FILTER (WHERE ((ai_attempt.status <> 'reserved'::text) AND (ai_attempt.usage_complete = true) AND (ai_attempt.metered_estimated_cost_usd IS NOT NULL) AND (ai_attempt.cache_read_tokens IS NOT NULL) AND (ai_attempt.canonical_model_name IS NOT NULL) AND (ai_attempt.pricing_version IS NOT NULL))))::integer AS metered_cost_count,
            COALESCE(sum(ai_attempt.metered_estimated_cost_usd) FILTER (WHERE ((ai_attempt.status <> 'reserved'::text) AND (ai_attempt.usage_complete = true) AND (ai_attempt.metered_estimated_cost_usd IS NOT NULL) AND (ai_attempt.cache_read_tokens IS NOT NULL) AND (ai_attempt.canonical_model_name IS NOT NULL) AND (ai_attempt.pricing_version IS NOT NULL))), (0)::numeric) AS metered_estimated_usd,
            COALESCE(sum(ai_attempt.prompt_tokens) FILTER (WHERE ((ai_attempt.status <> 'reserved'::text) AND (ai_attempt.usage_complete = true) AND (ai_attempt.prompt_tokens IS NOT NULL) AND (ai_attempt.cache_read_tokens IS NOT NULL))), (0)::bigint) AS input_tokens,
            COALESCE(sum((ai_attempt.completion_tokens + ai_attempt.thinking_tokens)) FILTER (WHERE ((ai_attempt.status <> 'reserved'::text) AND (ai_attempt.usage_complete = true) AND (ai_attempt.completion_tokens IS NOT NULL) AND (ai_attempt.thinking_tokens IS NOT NULL) AND (ai_attempt.cache_read_tokens IS NOT NULL))), (0)::bigint) AS output_tokens,
            COALESCE(sum(ai_attempt.cache_read_tokens) FILTER (WHERE ((ai_attempt.status <> 'reserved'::text) AND (ai_attempt.usage_complete = true) AND (ai_attempt.cache_read_tokens IS NOT NULL))), (0)::bigint) AS cache_tokens,
            COALESCE(jsonb_agg(jsonb_build_object('canonicalModelName', ai_attempt.canonical_model_name, 'modelName', ai_attempt.model_name, 'modelLocation', ai_attempt.location, 'pricingVersion', ai_attempt.pricing_version, 'attempt', ai_attempt.attempt, 'status', ai_attempt.status, 'usageUnknown', ((ai_attempt.usage_complete IS DISTINCT FROM true) OR (ai_attempt.metered_estimated_cost_usd IS NULL) OR (ai_attempt.cache_read_tokens IS NULL) OR (ai_attempt.canonical_model_name IS NULL) OR (ai_attempt.pricing_version IS NULL)), 'meteredEstimatedCostUsd', ai_attempt.metered_estimated_cost_usd) ORDER BY ai_attempt.operation_key, ai_attempt.attempt) FILTER (WHERE (ai_attempt.status <> 'reserved'::text)), '[]'::jsonb) AS provenance
           FROM public.analysis_v2_ai_attempts ai_attempt
          GROUP BY ai_attempt.request_id
        ), cache_rollup AS (
         SELECT checkpoint.request_id,
            (count(*) FILTER (WHERE (checkpoint.source = 'global_cache'::text)))::integer AS cache_hit_count
           FROM public.analysis_v2_ai_result_checkpoints checkpoint
          GROUP BY checkpoint.request_id
        ), selfhosted_rollup AS (
         SELECT receipt.request_id,
            (count(*))::integer AS no_paid_provider_count,
            COALESCE(jsonb_agg(jsonb_build_object('sourceKind', 'selfhosted_auth', 'operationKey', receipt.operation_key, 'provider', 'selfhosted_auth', 'status', 'succeeded', 'providerChargeUsd', (0)::numeric, 'chargeKind', 'no_paid_provider', 'usageUnknown', false) ORDER BY receipt.operation_key), '[]'::jsonb) AS provenance
           FROM public.analysis_v2_selfhosted_auth_runs receipt
          GROUP BY receipt.request_id
        ), vertex_budget_rollup AS (
         SELECT reservation.run_id AS request_id_text,
            (count(*))::integer AS reservation_count,
            (count(*) FILTER (WHERE ((reservation.state = 'reserved'::text) OR reservation.usage_unknown OR (reservation.actual_cost_usd IS NULL))))::integer AS usage_unknown_count,
            (count(*) FILTER (WHERE (ai_attempt.request_id IS NULL)))::integer AS unmatched_count,
            (count(*) - count(DISTINCT ROW(reservation.operation_key, reservation.attempt))) AS duplicate_count,
            (count(*) FILTER (WHERE (ai_attempt.request_id IS NOT NULL)))::integer AS matched_count,
            (count(*) FILTER (WHERE ((ai_attempt.request_id IS NOT NULL) AND ((reservation.model_name IS DISTINCT FROM (ai_attempt.model_name)::text) OR (reservation.model_location IS DISTINCT FROM (ai_attempt.location)::text) OR (reservation.usage_unknown IS DISTINCT FROM (ai_attempt.metered_estimated_cost_usd IS NULL)) OR (reservation.actual_cost_usd IS DISTINCT FROM ai_attempt.metered_estimated_cost_usd)))))::integer AS mismatch_count,
            COALESCE(sum(
                CASE
                    WHEN ((reservation.state = 'reserved'::text) OR reservation.usage_unknown OR (ai_attempt.request_id IS NULL) OR (reservation.usage_unknown IS DISTINCT FROM (ai_attempt.metered_estimated_cost_usd IS NULL)) OR (reservation.actual_cost_usd IS DISTINCT FROM ai_attempt.metered_estimated_cost_usd)) THEN GREATEST((reservation.estimated_cost_usd - COALESCE(
                    CASE
                        WHEN ((ai_attempt.status <> 'reserved'::text) AND (ai_attempt.usage_complete = true) AND (ai_attempt.metered_estimated_cost_usd IS NOT NULL) AND (ai_attempt.cache_read_tokens IS NOT NULL) AND (ai_attempt.canonical_model_name IS NOT NULL) AND (ai_attempt.pricing_version IS NOT NULL)) THEN ai_attempt.metered_estimated_cost_usd
                        ELSE (0)::numeric
                    END, (0)::numeric)), (0)::numeric)
                    ELSE (0)::numeric
                END), (0)::numeric) AS conservative_fallback_usd
           FROM (public.vertex_ai_budget_reservations reservation
             LEFT JOIN public.analysis_v2_ai_attempts ai_attempt ON (((reservation.run_id = (ai_attempt.request_id)::text) AND (reservation.operation_key = (ai_attempt.operation_key)::text) AND (reservation.attempt = ai_attempt.attempt) AND (reservation.model_name = (ai_attempt.model_name)::text) AND (reservation.model_location = (ai_attempt.location)::text))))
          WHERE (reservation.state <> 'cancelled'::text)
          GROUP BY reservation.run_id
        ), order_rollup AS (
         SELECT earlybird_order.result_request_id AS request_id,
            (array_agg(earlybird_order.id ORDER BY earlybird_order.id))[1] AS order_id
           FROM public.earlybird_orders earlybird_order
          WHERE (earlybird_order.result_request_id IS NOT NULL)
          GROUP BY earlybird_order.result_request_id
        )
 SELECT 'analysis-v2-cost-rollup-v1'::text AS rollup_version,
    'analysis-v2-direct-provider-and-vertex-metered-v1'::text AS cost_scope,
    false AS infrastructure_included,
    request.id AS request_id,
    COALESCE(preflight_source.preflight_id, preflight_zero.preflight_id, request.preflight_id) AS preflight_id,
    COALESCE(preflight_source.order_id, order_source.order_id) AS order_id,
    request.selected_plan_id_snapshot AS plan_id,
    request.plan_access_mode_snapshot AS access_mode,
    request.status AS request_status,
    request.created_at,
    request.completed_at,
    COALESCE(preflight_source.source_count, 0) AS preflight_provider_run_count,
    COALESCE(preflight_source.joined_source_count, 0) AS preflight_attributed_provider_run_count,
    GREATEST((COALESCE(preflight_source.source_count, 0) - COALESCE(preflight_source.joined_source_count, 0)), 0) AS preflight_attribution_gap_count,
    ((COALESCE(preflight_source.source_count, 0) = 0) AND (COALESCE(preflight_zero.no_paid_provider_count, 0) = 0)) AS preflight_coverage_unknown,
    (COALESCE(preflight_source.usage_unknown_count, 0) + COALESCE(preflight_zero.usage_unknown_count, 0)) AS preflight_usage_unknown_count,
    (COALESCE(preflight_source.no_call_count, 0) + COALESCE(preflight_zero.no_call_count, 0)) AS preflight_no_call_count,
    COALESCE(preflight_zero.no_paid_provider_count, 0) AS preflight_no_paid_provider_count,
    COALESCE(preflight_source.apify_actual_count, 0) AS preflight_apify_actual_count,
    COALESCE(preflight_source.actual_usd, (0)::numeric) AS preflight_provider_actual_usd,
    COALESCE(preflight_source.apify_actual_usd, (0)::numeric) AS preflight_apify_actual_charge_usd,
    COALESCE(preflight_source.conservative_usd, (0)::numeric) AS preflight_provider_conservative_usd,
    COALESCE(provider.run_count, 0) AS provider_run_count,
    COALESCE(provider.active_count, 0) AS provider_active_count,
    COALESCE(provider.usage_unknown_count, 0) AS provider_usage_unknown_count,
    COALESCE(provider.no_call_count, 0) AS provider_no_call_count,
        CASE
            WHEN ((COALESCE(provider.run_count, 0) = 0) AND (COALESCE(selfhosted.no_paid_provider_count, 0) = 0)) THEN 1
            ELSE 0
        END AS provider_coverage_gap_count,
    COALESCE(provider.actual_count, 0) AS provider_actual_count,
    COALESCE(provider.apify_actual_count, 0) AS provider_apify_actual_count,
    COALESCE(provider.actual_usd, (0)::numeric) AS provider_actual_usd,
    COALESCE(provider.apify_actual_usd, (0)::numeric) AS apify_actual_charge_usd,
    COALESCE(provider.conservative_usd, (0)::numeric) AS provider_conservative_usd,
    COALESCE(ai.attempt_count, 0) AS ai_attempt_count,
    COALESCE(ai.reserved_count, 0) AS ai_reserved_count,
    COALESCE(ai.usage_unknown_count, 0) AS ai_usage_unknown_count,
    COALESCE(ai.metered_cost_count, 0) AS ai_metered_cost_count,
    COALESCE(ai.metered_estimated_usd, (0)::numeric) AS metered_estimated_cost_usd,
    COALESCE(ai.input_tokens, (0)::bigint) AS ai_input_tokens,
    COALESCE(ai.output_tokens, (0)::bigint) AS ai_output_tokens,
    COALESCE(ai.cache_tokens, (0)::bigint) AS ai_cache_tokens,
    COALESCE(cache.cache_hit_count, 0) AS cache_hit_count,
        CASE
            WHEN ((COALESCE(ai.attempt_count, 0) = 0) AND (COALESCE(cache.cache_hit_count, 0) = 0)) THEN 1
            ELSE 0
        END AS ai_coverage_gap_count,
    COALESCE(selfhosted.no_paid_provider_count, 0) AS selfhosted_no_paid_provider_count,
    COALESCE(vertex_budget.reservation_count, 0) AS vertex_budget_reservation_count,
    COALESCE(vertex_budget.matched_count, 0) AS vertex_budget_matched_count,
    COALESCE(vertex_budget.unmatched_count, 0) AS vertex_budget_unmatched_count,
    COALESCE(vertex_budget.usage_unknown_count, 0) AS vertex_budget_usage_unknown_count,
    (COALESCE(vertex_budget.duplicate_count, (0)::bigint))::integer AS vertex_budget_duplicate_count,
    COALESCE(vertex_budget.mismatch_count, 0) AS vertex_budget_mismatch_count,
    COALESCE(vertex_budget.conservative_fallback_usd, (0)::numeric) AS vertex_budget_conservative_fallback_usd,
        CASE
            WHEN (((request.policy_versions_snapshot ->> 'aiStage'::text) = 'ai-stage-policy-v2.12'::text) AND (COALESCE(vertex_budget.reservation_count, 0) = 0) AND (COALESCE(cache.cache_hit_count, 0) = 0)) THEN 1
            ELSE 0
        END AS vertex_budget_coverage_gap_count,
    ((COALESCE(preflight_source.no_call_count, 0) + COALESCE(preflight_zero.no_call_count, 0)) + COALESCE(provider.no_call_count, 0)) AS provider_no_call_count_total,
    (((COALESCE(preflight_source.no_call_count, 0) + COALESCE(preflight_zero.no_call_count, 0)) + COALESCE(provider.no_call_count, 0)) + COALESCE(cache.cache_hit_count, 0)) AS no_call_count,
    (COALESCE(preflight_source.actual_usd, (0)::numeric) + COALESCE(provider.actual_usd, (0)::numeric)) AS provider_actual_total_usd,
    (COALESCE(preflight_source.conservative_usd, (0)::numeric) + COALESCE(provider.conservative_usd, (0)::numeric)) AS provider_conservative_total_usd,
    ((COALESCE(preflight_source.actual_usd, (0)::numeric) + COALESCE(provider.actual_usd, (0)::numeric)) + COALESCE(ai.metered_estimated_usd, (0)::numeric)) AS total_known_cost_usd,
    (((COALESCE(preflight_source.conservative_usd, (0)::numeric) + COALESCE(provider.conservative_usd, (0)::numeric)) + COALESCE(ai.metered_estimated_usd, (0)::numeric)) + COALESCE(vertex_budget.conservative_fallback_usd, (0)::numeric)) AS total_conservative_cost_usd,
    ((((COALESCE(preflight_source.provenance, '[]'::jsonb) || COALESCE(preflight_zero.provenance, '[]'::jsonb)) || COALESCE(provider.provenance, '[]'::jsonb)) || COALESCE(ai.provenance, '[]'::jsonb)) || COALESCE(selfhosted.provenance, '[]'::jsonb)) AS cost_provenance,
    (((request.status)::text = ANY ((ARRAY['completed'::character varying, 'failed'::character varying])::text[])) AND (COALESCE(preflight_source.source_count, 0) = COALESCE(preflight_source.joined_source_count, 0)) AND ((COALESCE(preflight_source.source_count, 0) > 0) OR (COALESCE(preflight_zero.no_paid_provider_count, 0) > 0)) AND (GREATEST((COALESCE(preflight_source.source_count, 0) - COALESCE(preflight_source.joined_source_count, 0)), 0) = 0) AND ((COALESCE(preflight_source.usage_unknown_count, 0) + COALESCE(preflight_zero.usage_unknown_count, 0)) = 0) AND (COALESCE(provider.active_count, 0) = 0) AND (COALESCE(provider.usage_unknown_count, 0) = 0) AND ((COALESCE(provider.run_count, 0) > 0) OR (COALESCE(selfhosted.no_paid_provider_count, 0) > 0)) AND (COALESCE(ai.reserved_count, 0) = 0) AND (COALESCE(ai.usage_unknown_count, 0) = 0) AND ((COALESCE(ai.attempt_count, 0) > 0) OR (COALESCE(cache.cache_hit_count, 0) > 0)) AND (((request.policy_versions_snapshot ->> 'aiStage'::text) IS DISTINCT FROM 'ai-stage-policy-v2.12'::text) OR (((COALESCE(vertex_budget.reservation_count, 0) > 0) AND (COALESCE(vertex_budget.unmatched_count, 0) = 0) AND (COALESCE(vertex_budget.usage_unknown_count, 0) = 0) AND (COALESCE(vertex_budget.duplicate_count, (0)::bigint) = 0) AND (COALESCE(vertex_budget.mismatch_count, 0) = 0)) OR ((COALESCE(vertex_budget.reservation_count, 0) = 0) AND (COALESCE(cache.cache_hit_count, 0) > 0))))) AS directly_attributable_cost_complete,
    ((((((((((GREATEST((COALESCE(preflight_source.source_count, 0) - COALESCE(preflight_source.joined_source_count, 0)), 0) +
        CASE
            WHEN ((COALESCE(preflight_source.source_count, 0) = 0) AND (COALESCE(preflight_zero.no_paid_provider_count, 0) = 0)) THEN 1
            ELSE 0
        END) + COALESCE(preflight_source.usage_unknown_count, 0)) + COALESCE(preflight_zero.usage_unknown_count, 0)) + COALESCE(provider.usage_unknown_count, 0)) + COALESCE(ai.usage_unknown_count, 0)) + COALESCE(ai.reserved_count, 0)) +
        CASE
            WHEN ((COALESCE(provider.run_count, 0) = 0) AND (COALESCE(selfhosted.no_paid_provider_count, 0) = 0)) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN ((COALESCE(ai.attempt_count, 0) = 0) AND (COALESCE(cache.cache_hit_count, 0) = 0)) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN (NOT ((request.policy_versions_snapshot ->> 'aiStage'::text) IS DISTINCT FROM 'ai-stage-policy-v2.12'::text)) THEN ((((COALESCE(vertex_budget.unmatched_count, 0) + COALESCE(vertex_budget.usage_unknown_count, 0)) + COALESCE(vertex_budget.duplicate_count, (0)::bigint)) + COALESCE(vertex_budget.mismatch_count, 0)) +
            CASE
                WHEN ((COALESCE(vertex_budget.reservation_count, 0) = 0) AND (COALESCE(cache.cache_hit_count, 0) = 0)) THEN 1
                ELSE 0
            END)
            ELSE (0)::bigint
        END) > 0) AS usage_unknown
   FROM ((((((((public.analysis_requests request
     LEFT JOIN preflight_rollup preflight_source ON ((preflight_source.request_id = request.id)))
     LEFT JOIN preflight_zero_sources preflight_zero ON ((preflight_zero.request_id = request.id)))
     LEFT JOIN provider_rollup provider ON ((provider.request_id = request.id)))
     LEFT JOIN ai_rollup ai ON ((ai.request_id = request.id)))
     LEFT JOIN cache_rollup cache ON ((cache.request_id = request.id)))
     LEFT JOIN selfhosted_rollup selfhosted ON ((selfhosted.request_id = request.id)))
     LEFT JOIN vertex_budget_rollup vertex_budget ON ((vertex_budget.request_id_text = (request.id)::text)))
     LEFT JOIN order_rollup order_source ON ((order_source.request_id = request.id)))
  WHERE ((request.pipeline_version = 'v2'::text) AND (request.plan_access_mode_snapshot = ANY (ARRAY['production'::text, 'test_entitlement'::text])) AND (request.selected_plan_id_snapshot = ANY (ARRAY['basic'::text, 'standard'::text, 'plus'::text])));


