    CONSTRAINT analysis_v2_dag_batch_result_producer_check CHECK (((producer_job_key)::text =
CASE result_kind
    WHEN 'profile_fetch'::text THEN ('track:profiles:batch:'::text || (batch)::text)
    WHEN 'profile_ai'::text THEN ('track:profile-ai:batch:'::text || (batch)::text)
