    CONSTRAINT analysis_v2_dag_batch_results_result_hash_check CHECK (((result_hash)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT analysis_v2_dag_batch_results_result_kind_check CHECK ((result_kind = ANY (ARRAY['profile_fetch'::text, 'profile_ai'::text, 'private_name'::text]))),
    CONSTRAINT analysis_v2_dag_batch_results_revision_check CHECK (((revision >= 1) AND (revision <= 1000000)))
);

