--
-- Name: analysis_v2_dag_stage_manifests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_v2_dag_stage_manifests (
    request_id uuid NOT NULL,
    stage_kind text NOT NULL,
    producer_job_key character varying(160) NOT NULL,
    producer_input_hash character varying(64) NOT NULL,
    revision integer NOT NULL,
    result_hash character varying(64) NOT NULL,
    detected_mutual_count integer,
    public_count integer,
    private_count integer,
    detailed_selected_public_count integer,
    not_screened_public_count integer,
    interactor_count integer,
    verified_female_count integer,
    shortlist_count integer,
    shortlist_hash character varying(64),
    featured_high_risk_count integer,
    narrative_count integer,
    narrative_batch_hash character varying(64),
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    relationship_selection_policy_version text,
    relationship_selection_checkpoint_id character varying(64),
    relationship_selection_job_input_hash character varying(64),
    relationship_selection_plan_id text,
    relationship_selection_public_population_count integer,
    relationship_selection_selected_count integer,
    CONSTRAINT analysis_v2_dag_relationship_selection_policy_shape_check CHECK ((((stage_kind = 'relationships'::text) AND ((num_nonnulls(relationship_selection_policy_version, relationship_selection_checkpoint_id, relationship_selection_job_input_hash, relationship_selection_plan_id, relationship_selection_public_population_count, relationship_selection_selected_count) = 0) OR ((relationship_selection_policy_version = 'gender-routing-v1'::text) AND ((relationship_selection_checkpoint_id)::text ~ '^[a-f0-9]{64}$'::text) AND ((relationship_selection_checkpoint_id)::text = (result_hash)::text) AND ((relationship_selection_job_input_hash)::text ~ '^[a-f0-9]{64}$'::text) AND ((relationship_selection_job_input_hash)::text = (producer_input_hash)::text) AND (relationship_selection_plan_id = ANY (ARRAY['basic'::text, 'standard'::text])) AND (relationship_selection_public_population_count = public_count) AND (relationship_selection_selected_count = detailed_selected_public_count) AND (((relationship_selection_plan_id = 'basic'::text) AND ((relationship_selection_public_population_count >= 0) AND (relationship_selection_public_population_count <= 400)) AND (relationship_selection_selected_count = LEAST(relationship_selection_public_population_count, 100))) OR ((relationship_selection_plan_id = 'standard'::text) AND ((relationship_selection_public_population_count >= 0) AND (relationship_selection_public_population_count <= 800)) AND (relationship_selection_selected_count = LEAST(relationship_selection_public_population_count, 200))))))) OR ((stage_kind <> 'relationships'::text) AND (num_nonnulls(relationship_selection_policy_version, relationship_selection_checkpoint_id, relationship_selection_job_input_hash, relationship_selection_plan_id, relationship_selection_public_population_count, relationship_selection_selected_count) = 0)))),
    CONSTRAINT analysis_v2_dag_stage_hashes_check CHECK ((((shortlist_hash IS NULL) OR ((shortlist_hash)::text ~ '^[a-f0-9]{64}$'::text)) AND ((narrative_batch_hash IS NULL) OR ((narrative_batch_hash)::text ~ '^[a-f0-9]{64}$'::text)))),
    CONSTRAINT analysis_v2_dag_stage_kind_check CHECK ((stage_kind = ANY (ARRAY['relationships'::text, 'target_evidence'::text, 'primary_join'::text, 'screening'::text, 'reverse_likes'::text, 'partner_safety'::text, 'final_score'::text, 'narrative'::text]))),
    CONSTRAINT analysis_v2_dag_stage_manifests_producer_input_hash_check CHECK (((producer_input_hash)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT analysis_v2_dag_stage_manifests_result_hash_check CHECK (((result_hash)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT analysis_v2_dag_stage_manifests_revision_check CHECK (((revision >= 1) AND (revision <= 1000000))),
    CONSTRAINT analysis_v2_dag_stage_producer_check CHECK (((producer_job_key)::text =
CASE stage_kind
    WHEN 'relationships'::text THEN 'track:relationships:collect'::text
    WHEN 'target_evidence'::text THEN 'track:target-evidence:collect'::text
    WHEN 'primary_join'::text THEN 'coordinator:join:primary-evidence'::text
    WHEN 'screening'::text THEN 'coordinator:candidate-screening'::text
    WHEN 'reverse_likes'::text THEN 'track:reverse-likes:collect'::text
    WHEN 'partner_safety'::text THEN 'track:partner-safety:batch:0'::text
    WHEN 'final_score'::text THEN 'coordinator:join:final-score'::text
    WHEN 'narrative'::text THEN 'track:narratives:batch:0'::text
