    CONSTRAINT precheckout_blite_cache_payload_check CHECK ((((state = 'pending'::text) AND (dto IS NULL) AND (completed_at IS NULL) AND (failure_reason IS NULL) AND (failed_at IS NULL)) OR ((state = 'complete'::text) AND (dto IS NOT NULL) AND (jsonb_typeof(dto) = 'object'::text) AND (completed_at IS NOT NULL) AND (failure_reason IS NULL) AND (failed_at IS NULL)) OR ((state = 'failed'::text) AND (dto IS NULL) AND (completed_at IS NULL) AND (failure_reason IS NOT NULL) AND (failed_at IS NOT NULL)))),
    CONSTRAINT precheckout_blite_cache_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'complete'::text, 'failed'::text]))),
    CONSTRAINT precheckout_blite_cache_timestamp_check CHECK (((updated_at >= created_at) AND (lease_expires_at >= created_at) AND ((completed_at IS NULL) OR (completed_at >= created_at)) AND ((failed_at IS NULL) OR (failed_at >= created_at))))
);

