--
-- Name: precheckout_blite_dispatches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.precheckout_blite_dispatches (
    preflight_id uuid NOT NULL,
    state text DEFAULT 'idle'::text NOT NULL,
    attempt_count smallint DEFAULT 0 NOT NULL,
    dispatch_token uuid,
    lease_expires_at timestamp with time zone,
    failure_reason text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    dispatch_generation integer DEFAULT 1 NOT NULL,
    last_dispatch_token uuid,
    dispatch_workload_role text,
    dispatch_contract_version smallint,
    CONSTRAINT precheckout_blite_dispatch_attempt_check CHECK (((attempt_count >= 0) AND (attempt_count <= 32767))),
    CONSTRAINT precheckout_blite_dispatch_failure_check CHECK (((failure_reason IS NULL) OR (failure_reason = 'dispatch_failed'::text))),
    CONSTRAINT precheckout_blite_dispatch_generation_check CHECK (((dispatch_generation >= 1) AND (dispatch_generation <= 100))),
    CONSTRAINT precheckout_blite_dispatch_state_check CHECK ((state = ANY (ARRAY['idle'::text, 'enqueuing'::text, 'enqueued'::text]))),
    CONSTRAINT precheckout_blite_dispatch_timestamp_check CHECK ((updated_at >= created_at)),
    CONSTRAINT precheckout_blite_dispatch_token_check CHECK ((((state = 'enqueuing'::text) AND (dispatch_token IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR ((state = ANY (ARRAY['idle'::text, 'enqueued'::text])) AND (dispatch_token IS NULL) AND (lease_expires_at IS NULL))))
);

ALTER TABLE ONLY public.precheckout_blite_dispatches FORCE ROW LEVEL SECURITY;


--
-- Name: precheckout_blite_sources; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.precheckout_blite_sources (
    preflight_id uuid NOT NULL,
    schema_version smallint NOT NULL,
    target_input_hash character varying(64) NOT NULL,
    provider_run_id uuid NOT NULL,
    provider_operation_key text NOT NULL,
    provider_run_reference text NOT NULL,
    payload jsonb NOT NULL,
    payload_bytes integer NOT NULL,
    payload_hash character varying(64) NOT NULL,
    collected_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT precheckout_blite_sources_payload_check CHECK (((jsonb_typeof(payload) = 'object'::text) AND (payload_bytes >= 2) AND (payload_bytes <= 262144) AND ((payload_hash)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT precheckout_blite_sources_provider_operation_check CHECK (((provider_operation_key = 'target-profile-fallback'::text) OR (provider_operation_key ~ '^target-profile-fresh-admission:g([1-9]|[1-9][0-9]|100)$'::text))),
    CONSTRAINT precheckout_blite_sources_provider_preflight_check CHECK ((provider_run_id = preflight_id)),
    CONSTRAINT precheckout_blite_sources_provider_reference_check CHECK ((provider_run_reference ~ '^[A-Za-z0-9]{8,64}$'::text)),
    CONSTRAINT precheckout_blite_sources_schema_check CHECK ((schema_version = 1)),
    CONSTRAINT precheckout_blite_sources_target_hash_check CHECK (((target_input_hash)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT precheckout_blite_sources_time_check CHECK (((expires_at > collected_at) AND (expires_at <= (collected_at + '00:30:00'::interval)) AND (updated_at >= created_at)))
);

