    CONSTRAINT sentry_discord_alert_outbox_issue_short_id_check CHECK (((issue_short_id IS NULL) OR (issue_short_id ~ '^[A-Z][A-Z0-9_-]{0,49}-[0-9]{1,12}$'::text))),
