    CONSTRAINT sentry_discord_alert_outbox_release_check CHECK (((release IS NULL) OR ((length(release) <= 80) AND (release ~ '^[0-9A-Za-z][0-9A-Za-z._+-]*$'::text) AND (release !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text)))),
    CONSTRAINT sentry_discord_alert_outbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sending'::text, 'sent'::text, 'failed'::text, 'ambiguous_failed'::text])))
);

