    account_class text DEFAULT 'production'::text NOT NULL,
    traffic_class text DEFAULT 'external'::text NOT NULL,
    lifecycle text DEFAULT 'active'::text NOT NULL,
    first_paid_at timestamp with time zone,
    classification_version text DEFAULT 'runtime_default_v1'::text,
    CONSTRAINT users_account_class_check CHECK ((account_class = ANY (ARRAY['production'::text, 'e2e_test'::text]))),
    CONSTRAINT users_classification_pair_check CHECK ((((account_class = 'production'::text) AND (traffic_class = ANY (ARRAY['external'::text, 'operator'::text]))) OR ((account_class = 'e2e_test'::text) AND (traffic_class = ANY (ARRAY['e2e_test'::text, 'internal_tester'::text]))))),
    CONSTRAINT users_classification_version_check CHECK (((classification_version IS NULL) OR (classification_version ~ '^[a-z0-9._-]{1,64}$'::text))),
    CONSTRAINT users_lifecycle_check CHECK ((lifecycle = ANY (ARRAY['active'::text, 'retired'::text]))),
    CONSTRAINT users_paid_ever_shape_check CHECK (((is_paid_user IS NOT TRUE) OR (first_paid_at IS NOT NULL))),
    CONSTRAINT users_phone_number_normalized_check CHECK (((phone_number_normalized IS NULL) OR (phone_number_normalized ~ '^\+8210[0-9]{8}$'::text))),
    CONSTRAINT users_phone_number_provenance_check CHECK ((((phone_number_normalized IS NULL) AND (phone_number_verification_source IS NULL) AND (phone_number_verified_at IS NULL)) OR (((provider)::text = 'kakao'::text) AND (phone_number IS NOT NULL) AND (phone_number_normalized IS NOT NULL) AND (NOT (phone_number_verification_source IS DISTINCT FROM 'kakao_rest_api'::text)) AND (phone_number_verified_at IS NOT NULL) AND (NOT (public.normalize_kr_mobile_e164((phone_number)::text) IS DISTINCT FROM phone_number_normalized))))),
    CONSTRAINT users_phone_number_verification_source_check CHECK (((phone_number_verification_source IS NULL) OR (phone_number_verification_source = 'kakao_rest_api'::text))),
    CONSTRAINT users_traffic_class_check CHECK ((traffic_class = ANY (ARRAY['external'::text, 'operator'::text, 'e2e_test'::text, 'internal_tester'::text])))
);


