--
-- Name: analysis_preflights analysis_preflights_anonymous_claim_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY analysis_preflights_anonymous_claim_select ON public.analysis_preflights FOR SELECT TO authenticated, anon USING (((user_id IS NULL) AND (provider_selector = 'anonymous_apify'::text) AND ((((claim_token_hash)::text = NULLIF(current_setting('app.anonymous_preflight_claim_hash'::text, true), ''::text)) AND (claim_expires_at > clock_timestamp())) OR ((idempotency_key)::text = NULLIF(current_setting('app.anonymous_preflight_idempotency_key'::text, true), ''::text)))));


--
-- Name: analysis_preflights analysis_preflights_anonymous_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY analysis_preflights_anonymous_insert ON public.analysis_preflights FOR INSERT TO authenticated, anon WITH CHECK (((user_id IS NULL) AND (provider_selector = 'anonymous_apify'::text) AND ((target_input_hash)::text = NULLIF(current_setting('app.anonymous_preflight_target_hash'::text, true), ''::text)) AND ((idempotency_key)::text = NULLIF(current_setting('app.anonymous_preflight_idempotency_key'::text, true), ''::text)) AND ((claim_token_hash)::text = NULLIF(current_setting('app.anonymous_preflight_claim_hash'::text, true), ''::text)) AND (claim_expires_at > clock_timestamp())));


--
-- Name: analysis_preflights analysis_preflights_anonymous_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY analysis_preflights_anonymous_update ON public.analysis_preflights FOR UPDATE TO authenticated, anon USING (((user_id IS NULL) AND (provider_selector = 'anonymous_apify'::text) AND ((((claim_token_hash)::text = NULLIF(current_setting('app.anonymous_preflight_claim_hash'::text, true), ''::text)) AND (claim_expires_at > clock_timestamp())) OR ((idempotency_key)::text = NULLIF(current_setting('app.anonymous_preflight_idempotency_key'::text, true), ''::text))))) WITH CHECK (((user_id IS NULL) AND (provider_selector = 'anonymous_apify'::text) AND (((claim_token_hash)::text = NULLIF(current_setting('app.anonymous_preflight_claim_hash'::text, true), ''::text)) OR ((idempotency_key)::text = NULLIF(current_setting('app.anonymous_preflight_idempotency_key'::text, true), ''::text)))));


--
-- Name: analysis_preflights analysis_preflights_authenticated_claim_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY analysis_preflights_authenticated_claim_update ON public.analysis_preflights FOR UPDATE TO authenticated USING (((user_id IS NULL) AND (provider_selector = 'anonymous_apify'::text) AND ((claim_token_hash)::text = NULLIF(current_setting('app.anonymous_preflight_claim_hash'::text, true), ''::text)) AND (claim_expires_at > clock_timestamp()))) WITH CHECK (((user_id = ( SELECT auth.uid() AS uid)) AND (provider_selector = 'anonymous_apify'::text) AND (claim_token_hash IS NULL) AND (claim_expires_at IS NULL)));


